class HarnessError(Exception):
    terminal = "InternalFault"


class UsageRefused(HarnessError):
    terminal = "UsageRefused"


class InputRefused(HarnessError):
    terminal = "InputRefused"


class NoData(HarnessError):
    terminal = "NoData"


class EvidenceFailed(HarnessError):
    terminal = "EvidenceFailed"


class CancelledDrained(HarnessError):
    terminal = "CancelledDrained"


class InfrastructureFailed(HarnessError):
    terminal = "InfrastructureFailed"


def v2_require_allowed_terminal_error_type(
    error_type: type[HarnessError],
    *,
    label: str,
) -> None:
    if type(label) is not str or not label:
        raise EvidenceFailed("terminal error-type label is malformed")
    if (
        error_type is UsageRefused
        or error_type is InputRefused
        or error_type is InfrastructureFailed
        or error_type is EvidenceFailed
    ):
        return
    raise EvidenceFailed(f"{label} is not an allowed terminal")


def v2_raise_allowed_terminal_error(
    error_type: type[HarnessError],
    diagnostic: str,
    *,
    cause: BaseException | None = None,
) -> None:
    """Raise one fixed harness terminal without invoking a supplied factory."""
    v2_require_allowed_terminal_error_type(
        error_type,
        label="terminal error type",
    )
    if type(diagnostic) is not str or not diagnostic:
        raise EvidenceFailed("terminal diagnostic is malformed")
    if error_type is UsageRefused:
        if cause is None:
            raise UsageRefused(diagnostic)
        raise UsageRefused(diagnostic) from cause
    if error_type is InputRefused:
        if cause is None:
            raise InputRefused(diagnostic)
        raise InputRefused(diagnostic) from cause
    if error_type is InfrastructureFailed:
        if cause is None:
            raise InfrastructureFailed(diagnostic)
        raise InfrastructureFailed(diagnostic) from cause
    if error_type is EvidenceFailed:
        if cause is None:
            raise EvidenceFailed(diagnostic)
        raise EvidenceFailed(diagnostic) from cause
    raise EvidenceFailed("terminal error type is not allowed")


V2DescriptorCloseFailure = tuple[HarnessError, BaseException]


def v2_collect_owned_descriptor_close_failure(
    specifications: Sequence[tuple[int | None, HarnessError]],
) -> V2DescriptorCloseFailure | None:
    """Attempt every owned close and retain the first cleanup failure.

    This helper never raises. An active primary exception therefore remains
    authoritative, while a successful operation can surface a close-only
    failure after its ``finally`` block.
    """
    first_failure: V2DescriptorCloseFailure | None = None
    for descriptor, typed_error in specifications:
        if descriptor is None:
            continue
        attempt_started = False
        try:
            attempt_started = True; os.close(descriptor)
        except BaseException as cause:
            if not attempt_started:
                try:
                    os.close(descriptor)
                except BaseException:
                    pass
            if first_failure is None:
                first_failure = (typed_error, cause)
    return first_failure


def v2_collect_owned_descriptor_slot_close_failure(
    slot: list[int | None],
    typed_error: HarnessError,
) -> V2DescriptorCloseFailure | None:
    """Attempt one slot-owned close and relinquish its numeric identity.

    The mutable slot remains visible to every surrounding cleanup path until
    ownership is transferred to this helper. The transfer precedes the one
    close attempt, and a pre-attempt interruption closes the local owner while
    preserving the raw primary.
    """
    if (
        type(slot) is not list
        or len(slot) != 1
        or (
            list.__getitem__(slot, 0) is not None
            and type(list.__getitem__(slot, 0)) is not int
        )
    ):
        raise EvidenceFailed("descriptor ownership slot is malformed")
    descriptor: int | None = None
    try:
        descriptor = slot[0]
        if descriptor is None:
            return None
        slot[0] = None
    except BaseException as cause:
        # Reading the descriptor and clearing the slot are deliberately
        # separate operations. If a one-shot instruction-level interruption
        # lands during that transfer, the slot remains the only owner and the
        # enclosing drain retries it. If the clear committed, this frame is the
        # only owner and must make the one close attempt before preserving the
        # raw primary.
        if descriptor is None:
            raise
        if (
            type(slot) is list
            and len(slot) == 1
            and slot[0] is descriptor
        ):
            raise
        try:
            os.close(descriptor)
        except BaseException:
            pass
        raise
    # This final syscall edge is protected for the harness's declared
    # one-shot line-event interruption model. Pure Python cannot make the
    # STORE_FAST marker and the following C ``close`` call one bytecode; the
    # contract therefore makes no opcode/sys.monitoring atomicity claim here.
    attempt_started = False
    try:
        attempt_started = True; os.close(descriptor)
    except BaseException as cause:
        if not attempt_started:
            try:
                os.close(descriptor)
            except BaseException:
                pass
            raise
        return (typed_error, cause)
    return None


def v2_transfer_owned_descriptor_slot(
    source_slot: list[int | None],
    destination_slot: list[int | None],
) -> None:
    """Move one descriptor between exact ownership slots without duplication.

    The source is cleared before the destination is assigned. If an
    one-shot instruction exception lands in that ownership gap, the local
    descriptor is closed exactly once only when neither slot owns it. The raw
    primary exception remains authoritative over any cleanup failure.
    """
    descriptor: int | None = None
    try:
        if (
            type(source_slot) is not list
            or type(destination_slot) is not list
            or source_slot is destination_slot
            or list.__len__(source_slot) != 1
            or list.__len__(destination_slot) != 1
        ):
            raise EvidenceFailed(
                "descriptor ownership transfer slots are malformed"
            )
        descriptor = source_slot[0]
        destination_descriptor = destination_slot[0]
        if (
            type(descriptor) is not int
            or descriptor < 0
            or destination_descriptor is not None
        ):
            raise EvidenceFailed(
                "descriptor ownership transfer state is malformed"
            )
        source_slot[0] = None
        destination_slot[0] = descriptor
    except BaseException:
        if descriptor is not None:
            source_owns = (
                type(source_slot) is list
                and list.__len__(source_slot) == 1
                and source_slot[0] is descriptor
            )
            destination_owns = (
                type(destination_slot) is list
                and list.__len__(destination_slot) == 1
                and destination_slot[0] is descriptor
            )
            if source_owns and destination_owns:
                # This cannot arise from the validated transfer sequence, but
                # fail closed to one owner if surrounding state was corrupted.
                source_slot[0] = None
                source_owns = False
            if not source_owns and not destination_owns:
                try:
                    os.close(descriptor)
                except BaseException:
                    pass
        raise


def v2_close_owned_descriptor_slots(
    specifications: Sequence[tuple[list[int | None], HarnessError]],
    *,
    surface_failure: bool,
) -> None:
    """Attempt and relinquish every slot-owned descriptor exactly once."""
    exact_specifications: tuple[tuple[list[int | None], HarnessError], ...] = (); first_failure: V2DescriptorCloseFailure | None = None
    active_primary: BaseException | None = None
    fallback_primary: BaseException | None = None
    fallback_started = False

    def drain_remaining() -> None:
        nonlocal first_failure
        cleanup_specifications = (
            exact_specifications
            if exact_specifications
            else tuple(specifications)
        )
        for slot, typed_error in cleanup_specifications:
            if list.__getitem__(slot, 0) is not None:
                failure = v2_collect_owned_descriptor_slot_close_failure(
                    slot,
                    typed_error,
                )
                if first_failure is None and failure is not None:
                    first_failure = failure

    try:
        try:
            try:
                exact_specifications = tuple(specifications)
                drain_remaining()
            except BaseException as error:
                active_primary = error
                raise
            finally:
                fallback_started = True
                drain_remaining()
        except BaseException as error:
            fallback_primary = error
    finally:
        # A second interruption in the first fallback still cannot strand a
        # slot. Catch an interruption at this outermost drain as cleanup state,
        # retry after the injecting trace has unwound, and surface it only when
        # the explicit body-success policy permits cleanup failures to win.
        try:
            drain_remaining()
        except BaseException as error:
            if fallback_primary is None:
                fallback_primary = error
            drain_remaining()
    if surface_failure:
        if active_primary is not None:
            raise active_primary
        if fallback_primary is not None:
            raise fallback_primary
    if surface_failure:
        v2_raise_descriptor_close_failure(first_failure)


def v2_close_owned_descriptors(
    specifications: Sequence[tuple[int | None, HarnessError]],
    *,
    surface_failure: bool,
) -> None:
    """Close every descriptor, surfacing cleanup only after body success."""
    first_error: HarnessError | None = None
    first_cause: BaseException | None = None
    for descriptor, typed_error in specifications:
        if descriptor is None:
            continue
        try:
            os.close(descriptor)
        except BaseException as cause:
            if first_cause is None:
                first_error = typed_error
                first_cause = cause
    if not surface_failure or first_cause is None:
        return
    if not isinstance(first_cause, OSError):
        raise first_cause
    if first_error is None:
        raise InfrastructureFailed(
            "descriptor cleanup lost its typed failure"
        ) from first_cause
    raise first_error from first_cause


def v2_raise_descriptor_close_failure(
    failure: V2DescriptorCloseFailure | None,
) -> None:
    if failure is None:
        return
    typed_error, cause = failure
    if isinstance(cause, OSError):
        raise typed_error from cause
    raise cause


class OutputPublicationFailed(InfrastructureFailed):
    def __init__(
        self,
        message: str,
        *,
        bytes_committed: int | None,
    ) -> None:
        super().__init__(message)
        self.bytes_committed = bytes_committed


class PublishedV2Refusal(HarnessError):
    def __init__(
        self,
        *,
        terminal: str,
        document: Mapping[str, Any],
    ) -> None:
        super().__init__(terminal)
        self.terminal = terminal
        self.document = dict(document)


def v2_bounded_exact_integer_text(
    value: Any,
    *,
    label: str,
    error_type: type[HarnessError],
) -> str:
    if type(value) is not int:
        raise error_type(f"{label} is not an exact integer")
    integer_bits = int.bit_length(value)
    if integer_bits > V2_EXACT_JSON_INTEGER_BITS_CAP:
        raise error_type(
            f"{label} contains an oversized integer (bit budget exceeded)"
        )
    integer_text = str(value)
    integer_digits = len(integer_text) - (1 if value < 0 else 0)
    if integer_digits > V2_EXACT_JSON_INTEGER_DECIMAL_DIGITS_CAP:
        raise error_type(
            f"{label} contains an oversized integer "
            "(decimal-digit budget exceeded)"
        )
    return integer_text


def check_cancel() -> None:
    if _cancel_requested:
        raise CancelledDrained("cancellation requested; no mutation is in flight")


@contextmanager
def v2_offline_replay_scope() -> Iterator[None]:
    """Fail closed on run_command-routed subprocesses during replay."""
    global _v2_offline_replay_depth
    with _v2_offline_replay_scope_lock:
        if _v2_offline_replay_depth == 0 and _v2_active_subprocesses:
            raise EvidenceFailed(
                "offline v2 replay cannot overlap an active subprocess"
            )
        _v2_offline_replay_depth += 1
    try:
        yield
    finally:
        with _v2_offline_replay_scope_lock:
            if _v2_offline_replay_depth <= 0:
                raise EvidenceFailed("offline replay scope depth underflow")
            _v2_offline_replay_depth -= 1


def canonical_bytes(value: Any) -> bytes:
    return (
        json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        + "\n"
    ).encode("utf-8")


def strict_json_loads(
    payload: bytes | str,
    *,
    label: str,
    require_canonical: bool = False,
) -> Any:
    if type(payload) not in {bytes, str}:
        raise InputRefused(f"{label} must be exact bytes or exact text")
    try:
        text = bytes.decode(payload, "utf-8") if type(payload) is bytes else payload
    except UnicodeDecodeError as error:
        raise InputRefused(f"{label} is not valid UTF-8") from error
    if str.startswith(text, "\ufeff"):
        raise InputRefused(f"{label} contains a forbidden UTF-8 BOM")

    def closed_object(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
        result: dict[str, Any] = {}
        for key, value in pairs:
            if key in result:
                raise InputRefused(f"{label} contains duplicate JSON key {key!r}")
            result[key] = value
        return result

    def reject_constant(value: str) -> Any:
        raise InputRefused(f"{label} contains non-finite number {value}")

    def bounded_integer(value: str) -> int:
        digit_count = len(value) - (1 if str.startswith(value, "-") else 0)
        if digit_count > V2_EXACT_JSON_INTEGER_DECIMAL_DIGITS_CAP:
            raise InputRefused(
                f"{label} contains an oversized integer "
                "(decimal-digit budget exceeded)"
            )
        try:
            parsed = int(value, 10)
        except ValueError as error:
            raise InputRefused(f"{label} contains a malformed integer") from error
        if int.bit_length(parsed) > V2_EXACT_JSON_INTEGER_BITS_CAP:
            raise InputRefused(
                f"{label} contains an oversized integer "
                "(bit budget exceeded)"
            )
        return parsed

    def finite_float(value: str) -> float:
        try:
            parsed = float(value)
        except ValueError as error:
            raise InputRefused(f"{label} contains a malformed float") from error
        if not math.isfinite(parsed):
            raise InputRefused(f"{label} contains a non-finite number")
        return parsed

    try:
        document = json.loads(
            text,
            object_pairs_hook=closed_object,
            parse_constant=reject_constant,
            parse_int=bounded_integer,
            parse_float=finite_float,
        )
    except InputRefused:
        raise
    except json.JSONDecodeError as error:
        raise InputRefused(f"{label} is malformed JSON") from error
    except RecursionError as error:
        raise InputRefused(f"{label} exceeds the JSON parser depth") from error
    if require_canonical:
        try:
            canonical_payload = canonical_bytes(document)
            source_payload = str.encode(text, "utf-8")
        except UnicodeEncodeError as error:
            raise InputRefused(
                f"{label} contains Unicode that cannot be encoded as UTF-8"
            ) from error
        except RecursionError as error:
            raise InputRefused(
                f"{label} exceeds the canonical JSON depth"
            ) from error
        if canonical_payload != source_payload:
            raise InputRefused(
                f"{label} is not canonical JSON with one terminal newline"
            )
    return document


def semantic_root(value: Any) -> str:
    return "sha256-v1:" + hashlib.sha256(canonical_bytes(value)).hexdigest()


def text_root(value: str) -> str:
    return "sha256-v1:" + hashlib.sha256(value.encode("utf-8")).hexdigest()


def json_stdout(value: Any) -> None:
    payload = canonical_bytes(value)
    try:
        written = sys.stdout.buffer.write(payload)
        if type(written) is not int or written != len(payload):
            raise OutputPublicationFailed(
                "canonical JSONL publication was incomplete",
                bytes_committed=(
                    written
                    if (
                        type(written) is int
                        and 0 <= written <= len(payload)
                    )
                    else None
                ),
            )
        sys.stdout.flush()
    except OutputPublicationFailed:
        raise
    except BaseException as error:
        raise OutputPublicationFailed(
            "canonical JSONL publication failed with unknown commit state",
            bytes_committed=None,
        ) from error


def terminal_row(
    terminal: str,
    *,
    mode: str,
    detail: str,
    extra: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    row: dict[str, Any] = {
        "schema": EVENT_SCHEMA,
        "mode": mode,
        "stage": "terminal",
        "sequence": 0,
        "terminal": terminal,
        "exit_code": TERMINAL_EXIT[terminal],
        "detail": detail,
        "no_claim": (
            "template-hygiene evidence classifies tracker-plan debt only and "
            "mints no implementation, scientific, or release authority"
        ),
    }
    if extra:
        row.update(extra)
    return row


def v2_exact_normalized_casefold(
    value: Any,
    *,
    normalization: str,
    label: str,
    error_type: type[HarnessError],
) -> str:
    if (
        error_type is not InputRefused
        and error_type is not InfrastructureFailed
        and error_type is not EvidenceFailed
    ):
        raise EvidenceFailed(
            "normalized-casefold error type is not an allowed terminal"
        )
    if type(label) is not str or not label:
        raise EvidenceFailed("normalized-casefold label is malformed")
    if (
        type(value) is not str
        or type(normalization) is not str
        or normalization not in {"NFC", "NFKC"}
    ):
        raise error_type(f"{label} is not an exact normalizable string")
    normalized = unicodedata.normalize(normalization, value)
    if type(normalized) is not str:
        raise error_type(f"{label} normalization did not return an exact string")
    return str.casefold(normalized)


def safe_relative(value: str, *, label: str) -> PurePosixPath:
    if type(value) is not str or not value:
        raise UsageRefused(f"{label} must be a non-empty repository-relative path")
    if value != unicodedata.normalize("NFC", value):
        raise UsageRefused(f"{label} must use NFC Unicode normalization")
    try:
        value_bytes = str.encode(value, "utf-8")
    except UnicodeEncodeError as error:
        raise UsageRefused(f"{label} is not valid UTF-8") from error
    if len(value_bytes) > CAPS["relative_path_bytes"]:
        raise UsageRefused(f"{label} exceeds the relative-path byte cap")
    if any(ord(character) < 32 or ord(character) == 127 for character in value):
        raise UsageRefused(f"{label} contains a control character")
    if "\\" in value or value.startswith("~") or re.match(r"^[A-Za-z]:", value):
        raise UsageRefused(f"{label} uses a forbidden path spelling")
    raw_parts = value.split("/")
    if (
        len(raw_parts) > CAPS["path_depth"]
        or any(part in {"", ".", ".."} for part in raw_parts)
        or any(
            len(part.encode("utf-8")) > CAPS["path_component_bytes"]
            for part in raw_parts
        )
    ):
        raise UsageRefused(f"{label} has an unsafe or over-cap component")
    # The exact lexical checks above already reject absolute, empty, dot, and
    # parent components before construction, so no dynamic path method call is
    # needed to admit this normalized repository-relative value.
    return PurePosixPath(value)


def resolve_safe(value: str, *, label: str, must_exist: bool = False) -> Path:
    relative = safe_relative(value, label=label)
    candidate = REPO_ROOT.joinpath(*relative.parts)
    resolved = candidate.resolve(strict=False)
    try:
        resolved.relative_to(REPO_ROOT)
    except ValueError as error:
        raise UsageRefused(f"{label} escapes the repository") from error

    cursor = REPO_ROOT
    for part in relative.parts:
        cursor = cursor / part
        if cursor.exists() and cursor.is_symlink():
            raise InputRefused(f"{label} traverses symlink {cursor.relative_to(REPO_ROOT)}")
    if must_exist and not candidate.exists():
        raise InputRefused(f"{label} does not exist: {relative}")
    return candidate


def bounded_read(
    path: Path,
    *,
    cap: int = CAPS["input_artifact_bytes"],
    nofollow: bool = False,
    require_unique_link: bool = False,
) -> bytes:
    if type(cap) is not int or cap < 0:
        raise EvidenceFailed("bounded-read cap must be a nonnegative integer")
    if type(nofollow) is not bool or type(require_unique_link) is not bool:
        raise EvidenceFailed(
            "bounded-read descriptor policies must be exact booleans"
        )
    try:
        display_path = str(path.relative_to(REPO_ROOT))
    except ValueError:
        display_path = str(path)
    flags = os.O_RDONLY | os.O_CLOEXEC
    flags |= os.O_NONBLOCK
    if nofollow:
        flags |= os.O_NOFOLLOW
    descriptor_slot: list[int | None] = [None]
    payload: bytes | None = None
    operation_succeeded = False
    try:
        try:
            list.__setitem__(descriptor_slot, 0, os.open(path, flags))
        except OSError as error:
            raise InputRefused(
                f"expected readable regular file: {display_path}"
            ) from error
        descriptor = list.__getitem__(descriptor_slot, 0)
        if descriptor is None:
            raise InfrastructureFailed(
                f"bounded input descriptor ownership was lost: {display_path}"
            )
        before = os.fstat(descriptor)
        if not stat.S_ISREG(before.st_mode):
            raise InputRefused(f"expected regular file: {display_path}")
        if require_unique_link and before.st_nlink != 1:
            raise InputRefused(
                f"expected unique regular file: {display_path}"
            )
        with os.fdopen(descriptor, "rb", closefd=False) as handle:
            payload = handle.read(cap + 1)
        after = os.fstat(descriptor)
        if len(payload) > cap:
            raise InputRefused(
                f"input artifact exceeds {cap} byte cap: {display_path}"
            )
        before_identity = (
            before.st_dev,
            before.st_ino,
            before.st_mode,
            before.st_nlink,
            before.st_size,
            before.st_mtime_ns,
            before.st_ctime_ns,
        )
        after_identity = (
            after.st_dev,
            after.st_ino,
            after.st_mode,
            after.st_nlink,
            after.st_size,
            after.st_mtime_ns,
            after.st_ctime_ns,
        )
        if before_identity != after_identity:
            raise InputRefused(
                f"input artifact changed during bounded read: {display_path}"
            )
        operation_succeeded = True
    except HarnessError:
        raise
    except OSError as error:
        raise InputRefused(
            f"bounded input read failed: {display_path}"
        ) from error
    finally:
        v2_close_owned_descriptor_slots((
            (
                descriptor_slot,
                InfrastructureFailed(
                    f"bounded input descriptor close failed: {display_path}"
                ),
            ),
        ), surface_failure=operation_succeeded)
    if payload is None:
        raise InfrastructureFailed(
            f"bounded input read produced no payload: {display_path}"
        )
    return payload


def v2_read_repo_relative_file_strict(
    value: str,
    *,
    label: str,
    cap: int = CAPS["input_artifact_bytes"],
    _simulate_after_mtime_change: bool = False,
    _expected_identity: tuple[int, ...] | None = None,
    _expected_parent_identities: (
        tuple[tuple[str, int, int, int], ...] | None
    ) = None,
) -> bytes:
    relative = safe_relative(value, label=label)
    if type(cap) is not int or cap < 0:
        raise EvidenceFailed(f"{label} strict-read cap is invalid")
    if type(_simulate_after_mtime_change) is not bool:
        raise EvidenceFailed(
            f"{label} strict-read metadata observation mode is invalid"
        )
    if _expected_identity is not None and (
        type(_expected_identity) is not tuple
        or len(_expected_identity) != 7
        or any(type(item) is not int for item in _expected_identity)
    ):
        raise EvidenceFailed(
            f"{label} strict-read bound identity is malformed"
        )
    if _expected_parent_identities is not None and (
        type(_expected_parent_identities) is not tuple
        or not _expected_parent_identities
        or any(
            type(row) is not tuple
            or len(row) != 4
            or type(row[0]) is not str
            or any(type(item) is not int for item in row[1:])
            for row in _expected_parent_identities
        )
    ):
        raise EvidenceFailed(
            f"{label} strict-read parent binding is malformed"
        )
    if (
        _expected_parent_identities is not None
        and len(_expected_parent_identities)
        != len(relative.parts[:-1]) + 1
    ):
        raise EvidenceFailed(
            f"{label} strict-read parent binding has the wrong depth"
        )
    # The harness is already POSIX-only (`fcntl`, descriptor-relative opens,
    # and `pread`). Keep every security-relevant flag as a statically visible
    # module attribute so refusal-state analysis binds the exact constants
    # instead of treating a dynamic `getattr(os, ...)` as unbounded module use.
    directory_flags = (
        os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW
    )
    file_flags = os.O_RDONLY | os.O_CLOEXEC | os.O_NONBLOCK | os.O_NOFOLLOW
    # Seed the root slot explicitly, then append one fresh slot per lexical
    # parent.  Besides making the mandatory root owner obvious, this keeps the
    # successful index-0 dataflow distinct from the impossible empty-list
    # branch that an inlined comprehension otherwise contributes on 3.14.
    directory_descriptor_slots: list[list[int | None]] = [[None]]
    for _index in range(len(relative.parts[:-1])):
        directory_descriptor_slots.append([None])
    directory_links: list[tuple[int, str, int, int, int]] = []
    file_descriptor_slot: list[int | None] = [None]
    payload: bytes | None = None
    operation_succeeded = False
    try:
        list.__setitem__(list.__getitem__(directory_descriptor_slots, 0), 0, os.open(REPO_ROOT, directory_flags))
        root_descriptor = list.__getitem__(list.__getitem__(directory_descriptor_slots, 0), 0)
        if root_descriptor is None:
            raise InfrastructureFailed(
                f"{label} root descriptor ownership was lost"
            )
        current_descriptor = root_descriptor
        root_state = os.fstat(root_descriptor)
        root_path_identity = (
            root_state.st_dev,
            root_state.st_ino,
            stat.S_IFMT(root_state.st_mode),
        )
        if _expected_parent_identities is not None:
            if _expected_parent_identities[0] != (
                ".",
                root_state.st_dev,
                root_state.st_ino,
                stat.S_IFMT(root_state.st_mode),
            ):
                raise InputRefused(
                    f"{label} repository root changed after state capture"
                )
        for parent_index, part in enumerate(relative.parts[:-1], 1):
            list.__setitem__(list.__getitem__(directory_descriptor_slots, parent_index), 0, os.open(part, directory_flags, dir_fd=current_descriptor))
            child_descriptor = list.__getitem__(
                list.__getitem__(
                    directory_descriptor_slots,
                    parent_index,
                ),
                0,
            )
            if child_descriptor is None:
                raise InfrastructureFailed(
                    f"{label} child descriptor ownership was lost"
                )
            child_stat = os.fstat(child_descriptor)
            if not stat.S_ISDIR(child_stat.st_mode):
                raise InputRefused(
                    f"{label} contains a non-directory component"
                )
            if _expected_parent_identities is not None and (
                parent_index >= len(_expected_parent_identities)
                or _expected_parent_identities[parent_index]
                != (
                    "/".join(relative.parts[:parent_index]),
                    child_stat.st_dev,
                    child_stat.st_ino,
                    stat.S_IFMT(child_stat.st_mode),
                )
            ):
                raise InputRefused(
                    f"{label} parent changed after state capture"
                )
            directory_links.append(
                (
                    current_descriptor,
                    part,
                    child_stat.st_dev,
                    child_stat.st_ino,
                    stat.S_IFMT(child_stat.st_mode),
                )
            )
            current_descriptor = child_descriptor
        leaf = relative.parts[-1]
        list.__setitem__(file_descriptor_slot, 0, os.open(leaf, file_flags, dir_fd=current_descriptor))
        file_descriptor = list.__getitem__(file_descriptor_slot, 0)
        if file_descriptor is None:
            raise InfrastructureFailed(
                f"{label} file descriptor ownership was lost"
            )
        before = os.fstat(file_descriptor)
        bound_before_identity = (
            before.st_dev,
            before.st_ino,
            before.st_mode,
            before.st_nlink,
            before.st_size,
            before.st_mtime_ns,
            before.st_ctime_ns,
        )
        if (
            _expected_identity is not None
            and bound_before_identity != _expected_identity
        ):
            raise InputRefused(
                f"{label} changed after selected-resource state capture"
            )
        before_entry = os.stat(
            leaf,
            dir_fd=current_descriptor,
            follow_symlinks=False,
        )
        if (
            not stat.S_ISREG(before.st_mode)
            or before.st_nlink != 1
            or before.st_dev != before_entry.st_dev
            or before.st_ino != before_entry.st_ino
            or stat.S_IFMT(before.st_mode)
            != stat.S_IFMT(before_entry.st_mode)
        ):
            raise InputRefused(
                f"{label} is not one uniquely linked regular file"
            )
        if before.st_size > cap:
            raise InputRefused(f"{label} exceeds its bounded byte cap")
        chunks: list[bytes] = []
        offset = 0
        while offset < before.st_size:
            chunk = os.pread(
                file_descriptor,
                min(1024 * 1024, before.st_size - offset),
                offset,
            )
            if not chunk:
                raise InputRefused(f"{label} changed while being read")
            chunks.append(chunk)
            offset += len(chunk)
        if os.pread(file_descriptor, 1, offset):
            raise InputRefused(f"{label} grew while being read")
        after = os.fstat(file_descriptor)
        after_entry = os.stat(
            leaf,
            dir_fd=current_descriptor,
            follow_symlinks=False,
        )
        before_identity = bound_before_identity
        after_identity = (
            after.st_dev,
            after.st_ino,
            after.st_mode,
            after.st_nlink,
            after.st_size,
            after.st_mtime_ns,
            after.st_ctime_ns,
        )
        if _simulate_after_mtime_change:
            after_identity = (
                *after_identity[:5],
                after_identity[5] + 1,
                after_identity[6],
            )
        if (
            after.st_nlink != 1
            or before_identity != after_identity
            or after.st_dev != after_entry.st_dev
            or after.st_ino != after_entry.st_ino
            or stat.S_IFMT(after.st_mode)
            != stat.S_IFMT(after_entry.st_mode)
        ):
            raise InputRefused(f"{label} changed while being read")
        for parent, name, device, inode, file_type in directory_links:
            retained_entry = os.stat(
                name,
                dir_fd=parent,
                follow_symlinks=False,
            )
            if (
                retained_entry.st_dev != device
                or retained_entry.st_ino != inode
                or stat.S_IFMT(retained_entry.st_mode) != file_type
            ):
                raise InputRefused(
                    f"{label} path identity changed while being read"
                )
        try:
            final_root_state = os.stat(
                REPO_ROOT,
                follow_symlinks=False,
            )
        except OSError as error:
            raise InputRefused(
                f"{label} repository root path cannot be rechecked safely"
            ) from error
        if (
            final_root_state.st_dev,
            final_root_state.st_ino,
            stat.S_IFMT(final_root_state.st_mode),
        ) != root_path_identity:
            raise InputRefused(
                f"{label} repository root path identity changed while being read"
            )
        payload = b"".join(chunks)
        operation_succeeded = True
    except HarnessError:
        raise
    except OSError as error:
        raise InputRefused(f"{label} cannot be opened safely") from error
    finally:
        close_specs: list[tuple[list[int | None], HarnessError]] = [
            (
                file_descriptor_slot,
                InfrastructureFailed(
                    f"{label} file descriptor close failed"
                ),
            )
        ]
        for descriptor_slot in reversed(directory_descriptor_slots):
            close_specs.append((
                descriptor_slot,
                InfrastructureFailed(
                    f"{label} directory descriptor close failed"
                ),
            ))
        v2_close_owned_descriptor_slots(
            close_specs,
            surface_failure=operation_succeeded,
        )
    if payload is None:
        raise InfrastructureFailed(f"{label} strict read produced no payload")
    return payload


def write_once(path: Path, payload: bytes) -> str:
    check_cancel()
    if len(payload) > CAPS["artifact_bytes"]:
        raise EvidenceFailed(
            f"artifact exceeds {CAPS['artifact_bytes']} byte cap: "
            f"{path.relative_to(REPO_ROOT)}"
        )
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.exists():
        if not path.is_file():
            raise EvidenceFailed(
                f"artifact target is not a regular file: {path.relative_to(REPO_ROOT)}"
            )
        if bounded_read(path, cap=CAPS["artifact_bytes"]) != payload:
            raise EvidenceFailed(
                f"refusing to overwrite non-identical artifact: "
                f"{path.relative_to(REPO_ROOT)}"
            )
        return "existing-identical"
    flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
    descriptor_slot: list[int | None] = [None]
    operation_succeeded = False
    try:
        list.__setitem__(descriptor_slot, 0, os.open(path, flags, 0o644))
        descriptor = list.__getitem__(descriptor_slot, 0)
        if descriptor is None:
            raise InfrastructureFailed(
                "artifact descriptor ownership was lost"
            )
        with os.fdopen(descriptor, "wb", closefd=False) as handle:
            handle.write(payload)
            handle.flush()
            os.fsync(handle.fileno())
        operation_succeeded = True
    except EvidenceFailed:
        # No unlink is attempted: repository policy forbids file deletion.
        raise
    finally:
        v2_close_owned_descriptor_slots((
            (
                descriptor_slot,
                InfrastructureFailed(
                    "artifact descriptor close failed"
                ),
            ),
        ), surface_failure=operation_succeeded)
    return "created"


def _run_command_unscoped(
    argv: Sequence[str],
    *,
    input_text: str | None = None,
    expected: Iterable[int] = (0,),
    command_cwd: Path | None = None,
    environment_overrides: Mapping[str, str] | None = None,
    honor_cancel: bool = True,
    record_global_receipt: bool = True,
    receipt_sink: Callable[[dict[str, Any]], None] | None = None,
    stdin_bytes_cap: int | None = None,
    stdout_bytes_cap: int | None = None,
    stderr_bytes_cap: int | None = None,
) -> subprocess.CompletedProcess[str]:
    if honor_cancel:
        check_cancel()
    argv_values = [str(value) for value in argv]
    if not argv_values:
        raise InfrastructureFailed("bounded command capture received no argv")
    sanitized_argv = v2_sanitized_argv(argv_values)
    command_name = sanitized_argv[0]
    environment = os.environ.copy()
    for name in SANITIZED_ENV_NAMES:
        environment.pop(name, None)
    if environment_overrides is not None:
        environment.update(
            {
                str(name): str(value)
                for name, value in environment_overrides.items()
            }
        )
    input_bytes = (
        input_text.encode("utf-8") if input_text is not None else None
    )
    default_stream_cap = CAPS["subprocess_stdout_bytes"]
    effective_stream_caps = {
        "stdin": (
            default_stream_cap if stdin_bytes_cap is None else stdin_bytes_cap
        ),
        "stdout": (
            default_stream_cap
            if stdout_bytes_cap is None
            else stdout_bytes_cap
        ),
        "stderr": (
            default_stream_cap
            if stderr_bytes_cap is None
            else stderr_bytes_cap
        ),
    }
    if any(
        type(value) is not int
        or value < 0
        or value > default_stream_cap
        for value in effective_stream_caps.values()
    ):
        raise EvidenceFailed(
            "command stream override exceeds the global bounded byte cap"
        )
    if (
        input_bytes is not None
        and len(input_bytes) > effective_stream_caps["stdin"]
    ):
        raise EvidenceFailed("command stdin exceeds the bounded byte cap")
    expected_codes = set(expected)
    stdout_buffer = bytearray()
    stderr_buffer = bytearray()
    cleanup_errors: list[str] = []

    def append_receipt(*, category: str, exit_code: int) -> None:
        stdout_bytes = bytes(stdout_buffer)
        stderr_bytes = bytes(stderr_buffer)
        receipt = {
            "argv": sanitized_argv,
            "exit_code": int(exit_code),
            "category": category,
            "stdout": {
                "bytes": len(stdout_bytes),
                "root": (
                    "sha256-v1:"
                    + hashlib.sha256(stdout_bytes).hexdigest()
                ),
                "body_retained": False,
            },
            "stderr": {
                "bytes": len(stderr_bytes),
                "root": (
                    "sha256-v1:"
                    + hashlib.sha256(stderr_bytes).hexdigest()
                ),
                "body_retained": False,
            },
            "cleanup_error_count": len(cleanup_errors),
            "cleanup_error_kinds": list(cleanup_errors),
            "redaction_verdict": "RAW_STREAM_BODIES_NOT_RETAINED",
        }
        if record_global_receipt:
            _command_receipts.append(receipt)
        if receipt_sink is not None:
            receipt_sink(dict(receipt))

    try:
        process = subprocess.Popen(
            argv_values,
            cwd=command_cwd or REPO_ROOT,
            stdin=subprocess.PIPE if input_bytes is not None else subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            env=environment,
            start_new_session=True,
        )
    except FileNotFoundError as error:
        append_receipt(category="START_FAILED", exit_code=-1)
        raise InfrastructureFailed(
            f"required tool not found: {command_name}"
        ) from error
    except OSError as error:
        append_receipt(category="START_FAILED", exit_code=-1)
        raise InfrastructureFailed(
            f"required tool could not be started: {command_name}"
        ) from error

    def drain_process() -> None:
        # Signal the process group even if the session leader has exited:
        # descendants may still own the captured pipes.
        group_observed = True
        try:
            os.killpg(process.pid, signal.SIGTERM)
        except ProcessLookupError:
            group_observed = False
        except OSError as error:
            cleanup_errors.append(
                f"SIGTERM_PROCESS_GROUP_ERRNO_{error.errno}"
            )
        if group_observed:
            # Escalate immediately. Waiting after a reaped session leader can
            # allow its numeric process-group ID to be reused by an unrelated
            # process before the second signal.
            try:
                os.killpg(process.pid, signal.SIGKILL)
            except ProcessLookupError:
                # ESRCH proves that no process group remains at this identity.
                pass
            except PermissionError as error:
                # EPERM does not prove retirement. Retain the cleanup failure
                # so no caller can report a successfully drained group.
                cleanup_errors.append(
                    f"SIGKILL_PROCESS_GROUP_ERRNO_{error.errno}"
                )
            except OSError as error:
                cleanup_errors.append(
                    f"SIGKILL_PROCESS_GROUP_ERRNO_{error.errno}"
                )
        if process.poll() is None:
            try:
                process.wait(timeout=1)
            except subprocess.TimeoutExpired:
                cleanup_errors.append("WAIT_AFTER_SIGKILL_TIMEOUT")
            except OSError as error:
                cleanup_errors.append(
                    f"WAIT_AFTER_SIGKILL_ERRNO_{error.errno}"
                )
        for stream_name, stream in (
            ("stdin", process.stdin),
            ("stdout", process.stdout),
            ("stderr", process.stderr),
        ):
            if stream is not None and not stream.closed:
                try:
                    stream.close()
                except OSError as error:
                    cleanup_errors.append(
                        f"CLOSE_{stream_name.upper()}_ERRNO_{error.errno}"
                    )

    streams: selectors.BaseSelector | None = None
    failure_category = "CAPTURE_FAILED"

    def close_selector() -> None:
        nonlocal streams
        selected = streams
        streams = None
        if selected is None:
            return
        try:
            selected.close()
        except OSError as error:
            cleanup_errors.append(
                f"CLOSE_SELECTOR_ERRNO_{error.errno}"
            )

    try:
        streams = selectors.DefaultSelector()
        if process.stdout is None or process.stderr is None:
            raise InfrastructureFailed(
                "bounded command capture lacks required output pipes"
            )
        for stream, name in (
            (process.stdout, "stdout"),
            (process.stderr, "stderr"),
        ):
            os.set_blocking(stream.fileno(), False)
            streams.register(stream, selectors.EVENT_READ, name)
        if input_bytes is not None:
            if process.stdin is None:
                raise InfrastructureFailed(
                    "bounded command capture lacks its requested input pipe"
                )
            os.set_blocking(process.stdin.fileno(), False)
            streams.register(process.stdin, selectors.EVENT_WRITE, "stdin")
        input_offset = 0
        deadline = time.monotonic() + CAPS["subprocess_timeout_seconds"]
        while streams.get_map() or process.poll() is None:
            if honor_cancel and _cancel_requested:
                failure_category = "CANCELLED"
                raise CancelledDrained(
                    "cancellation requested; subprocess group was drained"
                )
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                failure_category = "TIMEOUT"
                raise InfrastructureFailed(
                    f"command exceeded "
                    f"{CAPS['subprocess_timeout_seconds']}s: {command_name}"
                )
            for key, _ in streams.select(timeout=min(0.05, remaining)):
                stream = key.fileobj
                if key.data == "stdin":
                    assert input_bytes is not None
                    try:
                        written = os.write(
                            stream.fileno(),
                            input_bytes[input_offset : input_offset + 65_536],
                        )
                    except (BlockingIOError, InterruptedError):
                        continue
                    except BrokenPipeError:
                        written = 0
                    input_offset += written
                    if written == 0 or input_offset == len(input_bytes):
                        streams.unregister(stream)
                        stream.close()
                    continue
                try:
                    chunk = os.read(stream.fileno(), 65_536)
                except BlockingIOError:
                    continue
                if not chunk:
                    streams.unregister(stream)
                    stream.close()
                    continue
                target = (
                    stdout_buffer
                    if key.data == "stdout"
                    else stderr_buffer
                )
                cap = effective_stream_caps[key.data]
                available = max(0, cap - len(target))
                target.extend(chunk[:available])
                if len(chunk) > available:
                    failure_category = (
                        "STDOUT_LIMIT"
                        if key.data == "stdout"
                        else "STDERR_LIMIT"
                    )
                    raise InfrastructureFailed(
                        f"{command_name} {key.data} exceeded the bounded cap"
                    )
        return_code = process.wait(timeout=1)
    except HarnessError as harness_error:
        drain_process()
        close_selector()
        append_receipt(
            category=failure_category,
            exit_code=(
                process.returncode
                if process.returncode is not None
                else -1
            ),
        )
        if cleanup_errors:
            raise InfrastructureFailed(
                "subprocess cleanup could not prove process-group retirement; "
                "inspect the retained cleanup error kinds"
            ) from harness_error
        raise
    except (OSError, ValueError, subprocess.TimeoutExpired) as error:
        drain_process()
        close_selector()
        append_receipt(
            category="CAPTURE_FAILED",
            exit_code=(
                process.returncode
                if process.returncode is not None
                else -1
            ),
        )
        raise InfrastructureFailed(
            f"{command_name} failed during bounded command capture"
        ) from error
    finally:
        close_selector()
        if process.poll() is None:
            drain_process()
    stdout_bytes = bytes(stdout_buffer)
    stderr_bytes = bytes(stderr_buffer)
    try:
        stdout = stdout_bytes.decode("utf-8")
        stderr = stderr_bytes.decode("utf-8")
    except UnicodeDecodeError as error:
        append_receipt(category="NON_UTF8", exit_code=return_code)
        raise InfrastructureFailed(
            f"{command_name} emitted non-UTF-8 command output"
        ) from error
    completed = subprocess.CompletedProcess(
        argv_values,
        return_code,
        stdout,
        stderr,
    )
    if honor_cancel and _cancel_requested:
        drain_process()
        append_receipt(category="CANCELLED_AFTER_EXIT", exit_code=return_code)
        if cleanup_errors:
            raise InfrastructureFailed(
                "post-exit cancellation could not prove process-group "
                "retirement; inspect the retained cleanup error kinds"
            )
        raise CancelledDrained(
            "cancellation requested after subprocess exit; capture was drained"
        )
    category = (
        "SUCCESS"
        if completed.returncode in expected_codes
        else "UNEXPECTED_EXIT"
    )
    append_receipt(category=category, exit_code=return_code)
    if completed.returncode not in expected_codes:
        raise InfrastructureFailed(
            f"{command_name} returned {completed.returncode}; "
            "raw diagnostic body withheld, inspect its retained stream root"
        )
    return completed


def run_command(
    argv: Sequence[str],
    *,
    input_text: str | None = None,
    expected: Iterable[int] = (0,),
    command_cwd: Path | None = None,
    environment_overrides: Mapping[str, str] | None = None,
    honor_cancel: bool = True,
    record_global_receipt: bool = True,
    receipt_sink: Callable[[dict[str, Any]], None] | None = None,
    stdin_bytes_cap: int | None = None,
    stdout_bytes_cap: int | None = None,
    stderr_bytes_cap: int | None = None,
) -> subprocess.CompletedProcess[str]:
    global _v2_active_subprocesses
    with _v2_offline_replay_scope_lock:
        if _v2_offline_replay_depth > 0:
            raise EvidenceFailed(
                "offline v2 replay forbids run_command-routed subprocesses"
            )
        _v2_active_subprocesses += 1
    try:
        return _run_command_unscoped(
            argv,
            input_text=input_text,
            expected=expected,
            command_cwd=command_cwd,
            environment_overrides=environment_overrides,
            honor_cancel=honor_cancel,
            record_global_receipt=record_global_receipt,
            receipt_sink=receipt_sink,
            stdin_bytes_cap=stdin_bytes_cap,
            stdout_bytes_cap=stdout_bytes_cap,
            stderr_bytes_cap=stderr_bytes_cap,
        )
    finally:
        with _v2_offline_replay_scope_lock:
            if _v2_active_subprocesses <= 0:
                raise EvidenceFailed("subprocess guard depth underflow")
            _v2_active_subprocesses -= 1


def v2_decode_released_br_json(payload: Any, *, label: str) -> Any:
    if type(payload) is str:
        try:
            payload_bytes = str.encode(payload, "utf-8")
        except UnicodeEncodeError as error:
            raise InfrastructureFailed(f"{label} is not valid UTF-8") from error
    elif type(payload) is bytes:
        payload_bytes = payload
    else:
        raise InfrastructureFailed(f"{label} is not exact text or bytes")
    try:
        decoded = strict_json_loads(
            payload_bytes,
            label=label,
            require_canonical=False,
        )
        return v2_validate_exact_json_wire(decoded, label=label)
    except HarnessError as error:
        raise InfrastructureFailed(f"{label} is malformed") from error


def br_json(
    *arguments: str,
    br_cwd: Path = REPO_ROOT,
) -> Any:
    completed = run_command(("br", *arguments), command_cwd=br_cwd)
    return v2_decode_released_br_json(
        completed.stdout,
        label=f"br {' '.join(arguments[:2])} output",
    )


def br_read_json(
    *arguments: str,
    br_cwd: Path = REPO_ROOT,
) -> Any:
    return br_json(*arguments, *BR_READ_FLAGS, br_cwd=br_cwd)


V2_BR_VERSION_FIELDS = frozenset(
    {
        "version",
        "build",
        "commit",
        "branch",
        "rust_version",
        "target",
        "features",
    }
)
V2_BR_CAPABILITIES_FIELDS = frozenset(
    {
        "tool",
        "version",
        "contract_version",
        "features",
        "commands",
        "global_flags",
        "output_formats",
        "exit_codes",
        "env_vars",
        "safety",
        "recommended_entrypoints",
    }
)
V2_BR_SEMVER_PATTERN = re.compile(
    r"(?:0|[1-9][0-9]*)\."
    r"(?:0|[1-9][0-9]*)\."
    r"(?:0|[1-9][0-9]*)"
    r"(?:-(?:"
    r"(?:0|[1-9][0-9]*)|"
    r"(?:[0-9A-Za-z-]*[A-Za-z-][0-9A-Za-z-]*)"
    r")(?:\."
    r"(?:0|[1-9][0-9]*|[0-9A-Za-z-]*[A-Za-z-][0-9A-Za-z-]*)"
    r")*)?"
    r"(?:\+[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*)?"
)
V2_BR_SEMVER_BYTES_CAP = 128
V2_BR_COMMAND_WORKSPACE_VALUES = frozenset(
    {"none", "optional", "required", "unknown"}
)
V2_BR_CAPABILITIES_WIRE_ORDER_IDENTITY_FIELDS = (
    "features",
    "global_flags",
    "output_formats",
    "exit_codes",
    "env_vars",
    "safety",
    "recommended_entrypoints",
    "commands.machine_output",
    "commands.examples",
)


def _v2_normalize_br_semver_exact(
    value: Any,
    *,
    label: str,
) -> str:
    if type(label) is not str or not label:
        raise EvidenceFailed("br SemVer label is malformed")
    if type(value) is not str:
        raise EvidenceFailed(f"{label} is not canonical SemVer 2.0")
    try:
        encoded_length = len(str.encode(value, "utf-8"))
    except UnicodeEncodeError as error:
        raise EvidenceFailed(
            f"{label} is not canonical SemVer 2.0"
        ) from error
    if (
        not value
        or encoded_length is None
        or encoded_length > V2_BR_SEMVER_BYTES_CAP
        or V2_BR_SEMVER_PATTERN.fullmatch(value) is None
    ):
        raise EvidenceFailed(f"{label} is not canonical SemVer 2.0")
    return value


def v2_normalize_br_semver(
    value: Any,
    *,
    label: str,
    error_type: type[HarnessError],
) -> str:
    if (
        error_type is not InputRefused
        and error_type is not InfrastructureFailed
        and error_type is not EvidenceFailed
    ):
        raise EvidenceFailed("br SemVer error type is not an allowed terminal")
    try:
        return _v2_normalize_br_semver_exact(value, label=label)
    except EvidenceFailed as error:
        if error_type is InputRefused:
            raise InputRefused("br SemVer normalization failed") from error
        if error_type is InfrastructureFailed:
            raise InfrastructureFailed(
                "br SemVer normalization failed"
            ) from error
        raise


def _v2_normalize_br_version_exact(
    document: Any,
) -> dict[str, Any]:
    required = {"version", "build"}
    if type(document) is not dict:
        raise EvidenceFailed("br version has a non-closed released schema")
    document_fields = tuple(dict.__iter__(document))
    if (
        any(field not in document_fields for field in required)
        or any(field not in V2_BR_VERSION_FIELDS for field in document_fields)
    ):
        raise EvidenceFailed("br version has a non-closed released schema")
    raw_features = dict.get(document, "features", [])
    if type(raw_features) is not list or len(raw_features) > 2:
        raise EvidenceFailed("br version features are malformed")
    normalized = {
        field: dict.get(document, field)
        for field in V2_BR_VERSION_FIELDS
    }
    features = list(list.__iter__(raw_features))
    version = _v2_normalize_br_semver_exact(
        dict.__getitem__(normalized, "version"),
        label="br version version",
    )
    if any(
        type(dict.__getitem__(normalized, field)) is not str
        or not dict.__getitem__(normalized, field)
        or dict.__getitem__(normalized, field)
        != str.strip(dict.__getitem__(normalized, field))
        for field in required
    ) or any(
        dict.__getitem__(normalized, field) is not None
        and (
            type(dict.__getitem__(normalized, field)) is not str
            or not dict.__getitem__(normalized, field)
            or dict.__getitem__(normalized, field)
            != str.strip(dict.__getitem__(normalized, field))
        )
        for field in ("commit", "branch", "rust_version", "target")
    ):
        raise EvidenceFailed("br version identity scalars are malformed")
    feature_order = {"self_update": 0, "mcp": 1}
    if (
        any(
            type(feature) is not str
            or feature not in feature_order
            for feature in features
        )
        or len(features) != len(set(features))
        or features
        != sorted(features, key=feature_order.__getitem__)
    ):
        raise EvidenceFailed("br version features are noncanonical")
    return {
        field: (
            features
            if field == "features"
            else (
                version
                if field == "version"
                else dict.__getitem__(normalized, field)
            )
        )
        for field in sorted(V2_BR_VERSION_FIELDS)
    }


def v2_normalize_br_version(
    document: Any,
    *,
    error_type: type[HarnessError],
) -> dict[str, Any]:
    if (
        error_type is not InputRefused
        and error_type is not InfrastructureFailed
        and error_type is not EvidenceFailed
    ):
        raise EvidenceFailed("br version error type is not an allowed terminal")
    document = v2_released_json_snapshot(
        document,
        error_type=error_type,
        label="br version document",
    )
    try:
        return _v2_normalize_br_version_exact(document)
    except EvidenceFailed as error:
        if error_type is InputRefused:
            raise InputRefused("br version normalization failed") from error
        if error_type is InfrastructureFailed:
            raise InfrastructureFailed(
                "br version normalization failed"
            ) from error
        raise


def br_version(*, br_cwd: Path = REPO_ROOT) -> dict[str, Any]:
    return v2_normalize_br_version(
        br_read_json("version", "--json", br_cwd=br_cwd),
        error_type=InfrastructureFailed,
    )


def v2_normalize_br_capability_commands(
    value: Any,
    *,
    error_type: type[HarnessError],
) -> list[dict[str, Any]]:
    if (
        error_type is not InputRefused
        and error_type is not InfrastructureFailed
        and error_type is not EvidenceFailed
    ):
        raise EvidenceFailed(
            "br capabilities command error type is not an allowed terminal"
        )
    fields = {
        "name",
        "summary",
        "operation",
        "workspace",
        "machine_output",
        "examples",
    }
    if type(value) is not list or len(value) > V2_COMMAND_ARGUMENTS_CAP:
        raise error_type("br capabilities commands are malformed or over cap")
    normalized: list[dict[str, Any]] = []
    for index, row in enumerate(list.__iter__(value)):
        if type(row) is not dict:
            raise error_type(
                f"br capabilities command {index} has a non-closed schema"
            )
        row_fields = tuple(dict.__iter__(row))
        if (
            len(row_fields) != len(fields)
            or any(field not in fields for field in row_fields)
        ):
            raise error_type(
                f"br capabilities command {index} has a non-closed schema"
            )
        scalar_values: dict[str, str] = {}
        for field in ("name", "summary", "operation", "workspace"):
            scalar = dict.__getitem__(row, field)
            if (
                type(scalar) is not str
                or not scalar
                or scalar != str.strip(scalar)
            ):
                raise error_type(
                    f"br capabilities command {index} has invalid scalars"
                )
            scalar_values[field] = scalar
        if (
            dict.__getitem__(scalar_values, "operation")
            not in {"read", "write", "mixed", "unknown"}
            or dict.__getitem__(scalar_values, "workspace")
            not in V2_BR_COMMAND_WORKSPACE_VALUES
        ):
            raise error_type(
                f"br capabilities command {index} has invalid scalars"
            )
        sequence_values: dict[str, list[str]] = {}
        for field in ("machine_output", "examples"):
            values = dict.__getitem__(row, field)
            if (
                type(values) is not list
                or len(values) > V2_COMMAND_ARGUMENTS_CAP
                or any(
                    type(item) is not str
                    or not item
                    or item != str.strip(item)
                    for item in list.__iter__(values)
                )
                or len(values) != len(set(values))
            ):
                raise error_type(
                    f"br capabilities command {index} has invalid {field}"
                )
            sequence_values[field] = list(list.__iter__(values))
        normalized.append(
            {
                "name": dict.__getitem__(scalar_values, "name"),
                "summary": dict.__getitem__(scalar_values, "summary"),
                "operation": dict.__getitem__(scalar_values, "operation"),
                "workspace": dict.__getitem__(scalar_values, "workspace"),
                "machine_output": dict.__getitem__(
                    sequence_values,
                    "machine_output",
                ),
                "examples": dict.__getitem__(sequence_values, "examples"),
            }
        )
    names = [dict.__getitem__(row, "name") for row in normalized]
    if names != sorted(set(names)):
        raise error_type("br capabilities command names are noncanonical")
    return normalized


def v2_normalize_br_capability_rows(
    value: Any,
    *,
    fields: frozenset[str],
    identity_field: str,
    label: str,
    error_type: type[HarnessError],
) -> list[dict[str, Any]]:
    if (
        error_type is not InputRefused
        and error_type is not InfrastructureFailed
        and error_type is not EvidenceFailed
    ):
        raise EvidenceFailed(
            "br capabilities row error type is not an allowed terminal"
        )
    if (
        type(fields) is not frozenset
        or not fields
        or any(type(field) is not str or not field for field in fields)
        or type(identity_field) is not str
        or identity_field not in fields
        or type(label) is not str
        or not label
    ):
        raise EvidenceFailed("br capabilities row contract is malformed")
    if type(value) is not list or len(value) > V2_LOG_EVENTS_CAP:
        raise error_type(f"br capabilities {label} are malformed or over cap")
    normalized: list[dict[str, Any]] = []
    identities: list[Any] = []
    for index, row in enumerate(list.__iter__(value)):
        if type(row) is not dict:
            raise error_type(
                f"br capabilities {label} row {index} has a non-closed schema"
            )
        row_fields = tuple(dict.__iter__(row))
        if (
            len(row_fields) != len(fields)
            or any(field not in fields for field in row_fields)
        ):
            raise error_type(
                f"br capabilities {label} row {index} has a non-closed schema"
            )
        normalized_row: dict[str, Any] = {}
        invalid_scalar = False
        for field in fields:
            scalar = dict.__getitem__(row, field)
            if field == "code":
                scalar_is_valid = type(scalar) is int and scalar >= 0
            else:
                scalar_is_valid = (
                    type(scalar) is str
                    and bool(scalar)
                    and scalar == str.strip(scalar)
                )
            if not scalar_is_valid:
                invalid_scalar = True
                break
            normalized_row[field] = scalar
        if invalid_scalar:
            raise error_type(
                f"br capabilities {label} row {index} has invalid scalars"
            )
        identities.append(dict.__getitem__(normalized_row, identity_field))
        normalized.append({
            field: dict.__getitem__(normalized_row, field)
            for field in sorted(fields)
        })
    if len(identities) != len(set(identities)):
        raise error_type(f"br capabilities {label} identities are duplicated")
    return normalized


def v2_normalize_br_capabilities(
    document: Any,
    *,
    error_type: type[HarnessError],
) -> dict[str, Any]:
    if (
        error_type is not InputRefused
        and error_type is not InfrastructureFailed
        and error_type is not EvidenceFailed
    ):
        raise EvidenceFailed(
            "br capabilities error type is not an allowed terminal"
        )
    document = v2_released_json_snapshot(
        document,
        error_type=error_type,
        label="br capabilities document",
    )
    if (
        type(document) is not dict
        or len(document) != len(V2_BR_CAPABILITIES_FIELDS)
        or any(
            field not in V2_BR_CAPABILITIES_FIELDS
            for field in dict.__iter__(document)
        )
        or dict.get(document, "tool") != "br"
        or dict.get(document, "contract_version") != "br.capabilities.v1"
    ):
        raise error_type("br capabilities identity or schema differs")
    version = v2_normalize_br_semver(
        dict.get(document, "version"),
        label="br capabilities version",
        error_type=error_type,
    )
    features = v2_normalize_br_capability_rows(
        dict.__getitem__(document, "features"),
        fields=frozenset({"name", "description"}),
        identity_field="name",
        label="features",
        error_type=error_type,
    )
    commands = v2_normalize_br_capability_commands(
        dict.__getitem__(document, "commands"),
        error_type=error_type,
    )
    global_flags = v2_normalize_br_capability_rows(
        dict.__getitem__(document, "global_flags"),
        fields=frozenset({"flag", "description"}),
        identity_field="flag",
        label="global flags",
        error_type=error_type,
    )
    exit_codes = v2_normalize_br_capability_rows(
        dict.__getitem__(document, "exit_codes"),
        fields=frozenset({"code", "category", "description"}),
        identity_field="code",
        label="exit codes",
        error_type=error_type,
    )
    env_vars = v2_normalize_br_capability_rows(
        dict.__getitem__(document, "env_vars"),
        fields=frozenset({"name", "description"}),
        identity_field="name",
        label="environment variables",
        error_type=error_type,
    )
    safety = v2_normalize_br_capability_rows(
        dict.__getitem__(document, "safety"),
        fields=frozenset({"name", "guarantee"}),
        identity_field="name",
        label="safety guarantees",
        error_type=error_type,
    )
    output_formats = dict.__getitem__(document, "output_formats")
    recommended_entrypoints = dict.__getitem__(
        document,
        "recommended_entrypoints",
    )
    for label, values in (
        ("output formats", output_formats),
        ("recommended entrypoints", recommended_entrypoints),
    ):
        if (
            type(values) is not list
            or len(values) > V2_COMMAND_ARGUMENTS_CAP
            or any(
                type(value) is not str
                or not value
                or value != str.strip(value)
                for value in list.__iter__(values)
            )
            or len(values) != len(set(values))
        ):
            raise error_type(f"br capabilities {label} are malformed")
    if not all(
        (
            features,
            commands,
            global_flags,
            output_formats,
            exit_codes,
            env_vars,
            safety,
            recommended_entrypoints,
        )
    ):
        raise error_type("br capabilities omits a released contract dimension")
    return {
        "tool": "br",
        "version": version,
        "contract_version": "br.capabilities.v1",
        "features": features,
        "commands": commands,
        "global_flags": global_flags,
        "output_formats": list(list.__iter__(output_formats)),
        "exit_codes": exit_codes,
        "env_vars": env_vars,
        "safety": safety,
        "recommended_entrypoints": list(
            list.__iter__(recommended_entrypoints)
        ),
    }


def v2_br_capability_identity_summary(
    version_document: Any,
    capabilities_document: Any,
    *,
    error_type: type[HarnessError],
) -> dict[str, Any]:
    version = v2_normalize_br_version(
        version_document,
        error_type=error_type,
    )
    capabilities = v2_normalize_br_capabilities(
        capabilities_document,
        error_type=error_type,
    )
    if capabilities["version"] != version["version"]:
        raise error_type(
            "br version and capabilities semantic versions disagree"
        )
    dimensions = {
        "version_features": version["features"],
        **{
            field: capabilities[field]
            for field in (
                "features",
                "commands",
                "global_flags",
                "output_formats",
                "exit_codes",
                "env_vars",
                "safety",
                "recommended_entrypoints",
            )
        },
    }
    dimension_rows = {
        name: {
            "count": len(rows),
            "root": semantic_root(rows),
        }
        for name, rows in dimensions.items()
    }
    return v2_rooted(
        {
            "version_root": semantic_root(version),
            "capabilities_root": semantic_root(capabilities),
            "combined_root": semantic_root(
                {"version": version, "capabilities": capabilities}
            ),
            "dimensions": dimension_rows,
            "wire_order_identity_fields": list(
                V2_BR_CAPABILITIES_WIRE_ORDER_IDENTITY_FIELDS
            ),
        }
    )


def br_capabilities(*, br_cwd: Path = REPO_ROOT) -> dict[str, Any]:
    return v2_normalize_br_capabilities(
        br_read_json("capabilities", "--json", br_cwd=br_cwd),
        error_type=InfrastructureFailed,
    )


def file_identity(relative: str) -> dict[str, Any]:
    path = REPO_ROOT / relative
    if not path.exists():
        return {"path": relative, "present": False}
    if not path.is_file():
        raise InfrastructureFailed(f"identity path is not a file: {relative}")
    digest = hashlib.sha256()
    total = 0
    with path.open("rb") as handle:
        while True:
            chunk = handle.read(1024 * 1024)
            if not chunk:
                break
            total += len(chunk)
            digest.update(chunk)
    return {
        "path": relative,
        "present": True,
        "bytes": total,
        "identity": "sha256-v1:" + digest.hexdigest(),
    }


def source_file_identities() -> list[dict[str, Any]]:
    return [
        file_identity(".beads/beads.db"),
        file_identity(".beads/beads.db-wal"),
        file_identity(".beads/issues.jsonl"),
        file_identity(str(SCRIPT_REL)),
        file_identity(str(CASE_MANIFEST_REL)),
    ]


def normalize_document(document: Any, *, label: str) -> list[dict[str, Any]]:
    if isinstance(document, list):
        issues = document
        has_more = False
    elif isinstance(document, dict):
        issues = document.get("issues")
        has_more = bool(document.get("has_more"))
    else:
        issues = None
        has_more = False
    if not isinstance(issues, list):
        raise InfrastructureFailed(f"{label} has no issues array")
    if has_more:
        raise InfrastructureFailed(f"{label} is truncated")
    if len(issues) > CAPS["issues"]:
        raise InfrastructureFailed(f"{label} exceeds {CAPS['issues']} issue cap")
    return issues


def v2_utf8_bytes(
    value: str,
    *,
    label: str,
    error_type: type[HarnessError],
) -> bytes:
    try:
        return value.encode("utf-8")
    except UnicodeEncodeError as error:
        raise error_type(
            f"{label} contains ill-formed Unicode"
        ) from error


def v2_validate_issue_id(
    value: Any,
    *,
    label: str,
    error_type: type[HarnessError],
) -> str:
    if type(value) is not str:
        raise error_type(f"{label} is not a released-br local issue ID")
    encoded = v2_utf8_bytes(
        value,
        label=label,
        error_type=error_type,
    )
    prefix, separator, remainder = value.rpartition("-")
    child_parts = remainder.split(".")
    issue_hash = child_parts[0]
    valid_children = True
    for child in child_parts[1:]:
        if (
            not child
            or not child.isascii()
            or not child.isdigit()
        ):
            valid_children = False
            break
        try:
            if int(child) > 0xFFFF_FFFF:
                valid_children = False
                break
        except ValueError:
            valid_children = False
            break
    if (
        not separator
        or value.startswith("-")
        or not prefix
        or len(encoded) > V2_LOCAL_ISSUE_ID_BYTES_CAP
        or len(prefix.encode("utf-8")) > V2_LOCAL_ISSUE_PREFIX_BYTES_CAP
        or V2_LOCAL_ISSUE_PREFIX_PATTERN.fullmatch(prefix) is None
        or not issue_hash
        or len(issue_hash.encode("utf-8")) > V2_LOCAL_ISSUE_HASH_BYTES_CAP
        or V2_LOCAL_ISSUE_HASH_PATTERN.fullmatch(issue_hash) is None
        or not valid_children
    ):
        raise error_type(f"{label} is not a released-br local issue ID")
    return value


def v2_validate_external_relation_id(
    value: Any,
    *,
    label: str,
    error_type: type[HarnessError],
) -> str:
    if type(value) is not str:
        raise error_type(
            f"{label} is not a bounded command-safe external relation ID"
        )
    encoded = v2_utf8_bytes(
        value,
        label=label,
        error_type=error_type,
    )
    if (
        not value.startswith("external:")
        or not value.removeprefix("external:")
        or len(encoded) > V2_EXTERNAL_RELATION_ID_BYTES_CAP
        or any(
            unicodedata.category(character).startswith("C")
            or unicodedata.category(character) in {"Zl", "Zp"}
            for character in value
        )
    ):
        raise error_type(
            f"{label} is not a bounded command-safe external relation ID"
        )
    return value


def v2_validate_status(
    value: Any,
    *,
    label: str,
    error_type: type[HarnessError],
) -> str:
    if (
        error_type is not UsageRefused
        and error_type is not InputRefused
        and error_type is not InfrastructureFailed
        and error_type is not EvidenceFailed
    ):
        raise EvidenceFailed(
            "status validator error type is not an allowed terminal"
        )
    if type(label) is not str or not label:
        raise EvidenceFailed("status validator label is malformed")
    if type(value) is not str:
        raise error_type(f"{label} is not a canonical released-br status")
    encoded = v2_utf8_bytes(
        value,
        label=label,
        error_type=error_type,
    )
    if (
        not value
        or value != value.strip()
        or value != value.lower()
        or value != unicodedata.normalize("NFC", value)
        or value.startswith("-")
        or value == "all"
        or "," in value
        or len(encoded) > V2_STATUS_BYTES_CAP
        or any(
            unicodedata.category(character).startswith("C")
            or unicodedata.category(character) in {"Zl", "Zp"}
            for character in value
        )
    ):
        raise error_type(f"{label} is not a canonical released-br status")
    return value


def v2_exact_string_sequence_snapshot(
    values: Any,
    *,
    label: str,
    cap: int,
    error_type: type[HarnessError],
) -> list[str]:
    v2_require_allowed_terminal_error_type(
        error_type,
        label="exact string-sequence error type",
    )
    if type(label) is not str or not label or type(cap) is not int or cap < 0:
        raise EvidenceFailed("exact string-sequence contract is malformed")
    if type(values) is list:
        if list.__len__(values) > cap:
            v2_raise_allowed_terminal_error(
                error_type,
                f"{label} exceed their cap",
            )
        detached = v2_released_json_snapshot(
            values,
            label=label,
            error_type=error_type,
        )
    elif type(values) is tuple:
        if tuple.__len__(values) > cap:
            v2_raise_allowed_terminal_error(
                error_type,
                f"{label} exceed their cap",
            )
        detached = list(tuple.__iter__(values))
    else:
        v2_raise_allowed_terminal_error(
            error_type,
            f"{label} are not an exact list or tuple",
        )
        raise EvidenceFailed("unreachable exact string-sequence branch")
    if type(detached) is not list or list.__len__(detached) > cap:
        v2_raise_allowed_terminal_error(
            error_type,
            f"{label} snapshot is malformed or over cap",
        )
        raise EvidenceFailed("unreachable exact string-sequence snapshot")
    for index, value in enumerate(list.__iter__(detached)):
        if type(value) is not str:
            v2_raise_allowed_terminal_error(
                error_type,
                f"{label} row {index} is not an exact string",
            )
            raise EvidenceFailed("unreachable exact string-sequence row")
    return detached


def v2_canonical_status_scopes(
    values: Sequence[Any],
    *,
    error_type: type[HarnessError] = EvidenceFailed,
) -> tuple[str, ...]:
    values = v2_exact_string_sequence_snapshot(
        values,
        label="v2 status scopes",
        cap=CAPS["issues"] + len(V2_RELEASED_KNOWN_STATUSES),
        error_type=error_type,
    )
    observed = {
        v2_validate_status(
            value,
            label=f"v2 status scope row {index}",
            error_type=error_type,
        )
        for index, value in enumerate(values)
    }
    known = [
        status for status in V2_RELEASED_KNOWN_STATUSES if status in observed
    ]
    custom = sorted(
        observed - set(V2_RELEASED_KNOWN_STATUSES),
        key=lambda value: value.encode("utf-8"),
    )
    return tuple([*known, *custom])


def v2_status_scopes(
    issues: Sequence[Mapping[str, Any]],
    *,
    error_type: type[HarnessError] = EvidenceFailed,
) -> tuple[str, ...]:
    if (
        error_type is not UsageRefused
        and error_type is not InputRefused
        and error_type is not InfrastructureFailed
        and error_type is not EvidenceFailed
    ):
        raise EvidenceFailed(
            "v2 status-scope error type is not an allowed terminal"
        )
    if type(issues) is list:
        raw_issues = issues
    elif type(issues) is tuple:
        raw_issues = [issue for issue in tuple.__iter__(issues)]
    else:
        raise error_type("v2 status-scope issues are not an exact sequence")
    exact_issues = v2_released_json_snapshot(
        raw_issues,
        label="v2 status-scope issues",
        error_type=error_type,
    )
    if type(exact_issues) is not list:
        raise error_type("v2 status-scope snapshot is not an exact array")
    for index, issue in enumerate(list.__iter__(exact_issues)):
        if type(issue) is not dict:
            raise error_type(
                f"v2 status-scope issue {index} is not an exact object"
            )
    statuses = tuple(
        dict.get(issue, "status")
        for issue in list.__iter__(exact_issues)
    )
    return v2_canonical_status_scopes(
        statuses,
        error_type=error_type,
    )


def v2_is_terminal_status(value: Any) -> bool:
    return type(value) is str and value in V2_TERMINAL_STATUSES


def v2_unreviewed_semantic_disposition(
    *,
    status: str,
    classification_disposition: str,
) -> str:
    if type(status) is not str or type(classification_disposition) is not str:
        raise EvidenceFailed(
            "unreviewed semantic disposition inputs are not exact strings"
        )
    return (
        "CONTRIBUTION_ONLY"
        if status == "closed"
        else (
            "BLOCKED_AUTHORITY"
            if classification_disposition == "OWNER_REVIEW_REQUIRED"
            else "REMEDIATION_REQUIRED"
        )
    )


def v2_released_json_snapshot(
    value: Any,
    *,
    label: str,
    error_type: type[HarnessError],
) -> Any:
    """Return one recursively exact, detached released-br JSON epoch."""
    if type(label) is not str or not label:
        raise EvidenceFailed("released JSON snapshot label is malformed")
    if (
        error_type is not UsageRefused
        and error_type is not InputRefused
        and error_type is not InfrastructureFailed
        and error_type is not EvidenceFailed
    ):
        raise EvidenceFailed(
            "released JSON snapshot error type is not an allowed terminal"
        )
    try:
        return v2_validate_exact_json_wire(value, label=label)
    except HarnessError as error:
        raise error_type(
            f"{label} is not exact released JSON data"
        ) from error


def _v2_list_issue_ids_from_exact(
    document: Any,
    *,
    label: str,
    error_type: type[HarnessError],
) -> list[str]:
    expected_fields = {"issues", "has_more", "limit", "offset", "total"}
    if type(document) is not dict:
        raise error_type(
            f"{label} does not use the exact released-br list envelope"
        )
    document_keys = tuple(dict.__iter__(document))
    if (
        any(type(key) is not str for key in document_keys)
        or set(document_keys) != expected_fields
    ):
        raise error_type(
            f"{label} does not use the exact released-br list envelope"
        )
    rows = dict.__getitem__(document, "issues")
    if (
        type(rows) is not list
        or type(dict.__getitem__(document, "has_more")) is not bool
        or dict.__getitem__(document, "has_more") is not False
        or type(dict.__getitem__(document, "limit")) is not int
        or dict.__getitem__(document, "limit") != 0
        or type(dict.__getitem__(document, "offset")) is not int
        or dict.__getitem__(document, "offset") != 0
        or type(dict.__getitem__(document, "total")) is not int
        or dict.__getitem__(document, "total") != list.__len__(rows)
        or list.__len__(rows) > CAPS["issues"]
    ):
        raise error_type(
            f"{label} has a malformed, truncated, or inconsistent list envelope"
        )
    issue_ids: list[str] = []
    for index, row in enumerate(list.__iter__(rows)):
        if type(row) is not dict:
            raise error_type(
                f"{label} row {index} is not an object"
            )
        row_keys = tuple(dict.__iter__(row))
        if any(type(key) is not str for key in row_keys):
            raise error_type(
                f"{label} row {index} contains a non-exact field name"
            )
        issue_id = v2_validate_issue_id(
            dict.get(row, "id"),
            label=f"{label} row {index} issue ID",
            error_type=error_type,
        )
        issue_ids.append(issue_id)
    list.sort(issue_ids)
    if list.__len__(issue_ids) != len(set(issue_ids)):
        raise error_type(f"{label} issue IDs contain duplicates")
    return issue_ids


def v2_list_issue_ids(
    document: Any,
    *,
    label: str,
    error_type: type[HarnessError] = InfrastructureFailed,
) -> list[str]:
    exact_document = v2_released_json_snapshot(
        document,
        label=label,
        error_type=error_type,
    )
    return _v2_list_issue_ids_from_exact(
        exact_document,
        label=label,
        error_type=error_type,
    )


def v2_normalize_released_br_list_rows(
    document: Any,
    *,
    label: str,
    error_type: type[HarnessError] = InfrastructureFailed,
) -> list[dict[str, Any]]:
    exact_document = v2_released_json_snapshot(
        document,
        label=label,
        error_type=error_type,
    )
    _v2_list_issue_ids_from_exact(
        exact_document,
        label=label,
        error_type=error_type,
    )
    rows = dict.__getitem__(exact_document, "issues")
    normalized: list[dict[str, Any]] = []
    for index, row in enumerate(list.__iter__(rows)):
        if type(row) is not dict:
            raise error_type(f"{label} row {index} is not exact")
        row_keys = tuple(dict.__iter__(row))
        if any(type(key) is not str for key in row_keys):
            raise error_type(
                f"{label} row {index} contains a non-exact field name"
            )
        missing_fields = (
            V2_RELEASED_BR_LIST_ROW_REQUIRED_FIELDS - set(row_keys)
        )
        if missing_fields:
            raise error_type(
                f"{label} row {index} lacks mandatory released fields: "
                f"{sorted(missing_fields)}"
            )
        if (
            not dict.__contains__(row, "dependency_count")
            or not dict.__contains__(row, "dependent_count")
        ):
            raise error_type(
                f"{label} row {index} lacks released relation counts"
            )
        dependency_count = dict.__getitem__(row, "dependency_count")
        dependent_count = dict.__getitem__(row, "dependent_count")
        if (
            type(dependency_count) is not int
            or type(dependent_count) is not int
            or dependency_count < 0
            or dependent_count < 0
            or dependency_count > V2_INVENTORY_ROWS_CAP
            or dependent_count > V2_INVENTORY_ROWS_CAP
        ):
            raise error_type(
                f"{label} row {index} has invalid relation counts"
            )
        issue = {
            key: value
            for key, value in dict.items(row)
            if key not in {"dependency_count", "dependent_count"}
        }
        try:
            v2_validate_raw_br_issue(issue)
        except HarnessError as error:
            raise error_type(
                f"{label} row {index} is not a released-br issue"
            ) from error
        normalized.append(row)
    list.sort(
        normalized,
        key=lambda row: dict.__getitem__(row, "id"),
    )
    return normalized


def _v2_ready_issue_ids_from_exact(
    document: Any,
    *,
    label: str,
    error_type: type[HarnessError],
) -> list[str]:
    if type(document) is not list:
        raise error_type(
            f"{label} does not use the exact released-br ready array"
        )
    if list.__len__(document) > V2_INVENTORY_ROWS_CAP:
        raise error_type(f"{label} exceeds the issue-row cap")
    issue_ids: list[str] = []
    for index, row in enumerate(list.__iter__(document)):
        if type(row) is not dict:
            raise error_type(
                f"{label} row {index} is not an object"
            )
        row_keys = tuple(dict.__iter__(row))
        if any(type(key) is not str for key in row_keys):
            raise error_type(
                f"{label} row {index} contains a non-exact field name"
            )
        missing_fields = (
            V2_RELEASED_BR_ROW_REQUIRED_COMMON_FIELDS - set(row_keys)
        )
        if missing_fields:
            raise error_type(
                f"{label} row {index} lacks mandatory released fields: "
                f"{sorted(missing_fields)}"
            )
        try:
            v2_validate_raw_br_issue(row)
        except HarnessError as error:
            raise error_type(
                f"{label} row {index} is not a released-br issue"
            ) from error
        issue_ids.append(
            v2_validate_issue_id(
                dict.get(row, "id"),
                label=f"{label} row {index} issue ID",
                error_type=error_type,
            )
        )
    list.sort(issue_ids)
    if list.__len__(issue_ids) != len(set(issue_ids)):
        raise error_type(f"{label} issue IDs contain duplicates")
    return issue_ids


def v2_ready_issue_ids(
    document: Any,
    *,
    label: str,
    error_type: type[HarnessError] = InfrastructureFailed,
) -> list[str]:
    exact_document = v2_released_json_snapshot(
        document,
        label=label,
        error_type=error_type,
    )
    return _v2_ready_issue_ids_from_exact(
        exact_document,
        label=label,
        error_type=error_type,
    )


def v2_normalize_released_br_ready_rows(
    document: Any,
    *,
    label: str,
    error_type: type[HarnessError] = InfrastructureFailed,
) -> list[dict[str, Any]]:
    """Retain every validated released-br ready-row field canonically."""
    exact_document = v2_released_json_snapshot(
        document,
        label=label,
        error_type=error_type,
    )
    _v2_ready_issue_ids_from_exact(
        exact_document,
        label=label,
        error_type=error_type,
    )
    normalized = list.copy(exact_document)
    list.sort(
        normalized,
        key=lambda row: dict.__getitem__(row, "id"),
    )
    return normalized


def v2_retain_released_br_row(row: Mapping[str, Any]) -> dict[str, Any]:
    """Replace path bodies with receipts that retain no plaintext body."""
    if type(row) is not dict:
        raise InfrastructureFailed(
            "released-br retained row source is not an exact object"
        )
    retained = dict(row)
    if "source_repo_path" in retained:
        raw_path = retained["source_repo_path"]
        if type(raw_path) is not str:
            raise InfrastructureFailed(
                "released-br source_repo_path is not an exact string"
            )
        retained["source_repo_path"] = {
            "body_retained": False,
            "text_root": text_root(raw_path),
            "value_root": semantic_root(raw_path),
        }
    return retained


def v2_validate_retained_br_path_receipt(
    value: Any,
    *,
    label: str,
    error_type: type[HarnessError],
) -> None:
    if (
        error_type is not InputRefused
        and error_type is not InfrastructureFailed
        and error_type is not EvidenceFailed
    ):
        raise EvidenceFailed(
            "retained path receipt error type is not an allowed terminal"
        )
    if type(label) is not str or not label:
        raise EvidenceFailed("retained path receipt label is malformed")
    if (
        type(value) is not dict
        or set(value) != V2_RETAINED_BR_PATH_RECEIPT_FIELDS
        or value["body_retained"] is not False
        or any(
            type(value[field]) is not str
            or re.fullmatch(r"sha256-v1:[0-9a-f]{64}", value[field]) is None
            for field in ("text_root", "value_root")
        )
    ):
        v2_raise_allowed_terminal_error(
            error_type,
            f"{label} path receipt is malformed",
        )


def v2_require_retained_br_rows_path_safe(
    rows: Sequence[Mapping[str, Any]],
    *,
    label: str,
    error_type: type[HarnessError],
) -> None:
    v2_require_allowed_terminal_error_type(
        error_type,
        label="retained row path-safety error type",
    )
    if type(label) is not str or not label:
        raise EvidenceFailed("retained row path-safety label is malformed")
    if type(rows) is list:
        if list.__len__(rows) > V2_INVENTORY_ROWS_CAP:
            v2_raise_allowed_terminal_error(
                error_type,
                f"{label} rows exceed their cap",
            )
        raw_rows = rows
    elif type(rows) is tuple:
        if tuple.__len__(rows) > V2_INVENTORY_ROWS_CAP:
            v2_raise_allowed_terminal_error(
                error_type,
                f"{label} rows exceed their cap",
            )
        raw_rows = list(tuple.__iter__(rows))
    else:
        v2_raise_allowed_terminal_error(
            error_type,
            f"{label} rows are not an exact list or tuple",
        )
        raise EvidenceFailed("unreachable retained row sequence branch")
    exact_rows = v2_released_json_snapshot(
        raw_rows,
        label=f"{label} retained rows",
        error_type=error_type,
    )
    if type(exact_rows) is not list:
        v2_raise_allowed_terminal_error(
            error_type,
            f"{label} retained row snapshot is malformed",
        )
        raise EvidenceFailed("unreachable retained row snapshot branch")
    for index, row in enumerate(list.__iter__(exact_rows)):
        if type(row) is not dict:
            v2_raise_allowed_terminal_error(
                error_type,
                f"{label} row {index} is not an exact object",
            )
            raise EvidenceFailed("unreachable retained row type branch")
        if "source_repo_path" in row:
            v2_validate_retained_br_path_receipt(
                row["source_repo_path"],
                label=f"{label} row {index}",
                error_type=error_type,
            )


def v2_retained_br_row_id(row: Any) -> str:
    if type(row) is not dict:
        raise EvidenceFailed("retained br row is not an exact object")
    issue_id = dict.get(row, "id")
    if type(issue_id) is not str or not issue_id:
        raise EvidenceFailed("retained br row ID is malformed")
    return issue_id


def v2_normalize_retained_br_rows(
    rows: Any,
    *,
    label: str,
    relation_counts: bool,
    error_type: type[HarnessError],
) -> list[dict[str, Any]]:
    if type(rows) is not list or len(rows) > V2_INVENTORY_ROWS_CAP:
        raise error_type(f"{label} rows are malformed or over cap")
    required = (
        V2_RELEASED_BR_LIST_ROW_REQUIRED_FIELDS
        if relation_counts
        else V2_RELEASED_BR_ROW_REQUIRED_COMMON_FIELDS
    )
    normalized: list[dict[str, Any]] = []
    for index, row in enumerate(rows):
        if type(row) is not dict:
            raise error_type(f"{label} row {index} is not an exact object")
        missing = required - set(row)
        if missing:
            raise error_type(
                f"{label} row {index} lacks mandatory retained fields: "
                f"{sorted(missing)}"
            )
        if "source_repo_path" in row:
            v2_validate_retained_br_path_receipt(
                dict.__getitem__(row, "source_repo_path"),
                label=f"{label} row {index}",
                error_type=error_type,
            )
        if relation_counts:
            for field in ("dependency_count", "dependent_count"):
                v2_br_nonnegative_int(
                    dict.get(row, field),
                    label=f"{label} row {index} {field}",
                    cap=V2_INVENTORY_ROWS_CAP,
                    error_type=error_type,
                )
        raw_like = {
            field: ("" if field == "source_repo_path" else value)
            for field, value in dict.items(row)
            if not relation_counts
            or field not in {"dependency_count", "dependent_count"}
        }
        try:
            v2_validate_raw_br_issue(raw_like)
        except HarnessError as error:
            raise error_type(
                f"{label} row {index} is not a retained released-br issue"
            ) from error
        normalized.append(dict.copy(row))
    ids = [v2_retained_br_row_id(row) for row in normalized]
    if len(ids) != len(set(ids)):
        raise error_type(f"{label} row membership is noncanonical")
    rows_by_id = {
        v2_retained_br_row_id(row): row
        for row in normalized
    }
    return [
        dict.__getitem__(rows_by_id, issue_id)
        for issue_id in sorted(ids)
    ]


def v2_validate_issue_universe_membership(
    *,
    listed_issue_ids: Sequence[str],
    tombstone_issue_ids: Sequence[str],
    tracker_status: Mapping[str, Any],
    br_version: str,
) -> list[str]:
    listed = list(listed_issue_ids)
    tombstones = list(tombstone_issue_ids)
    overlap = sorted(set(listed) & set(tombstones))
    if overlap:
        raise InfrastructureFailed(
            "released br list overlaps ordinary and tombstone membership; "
            f"first={overlap[0]}"
        )
    summary = tracker_status.get("summary")
    if not isinstance(summary, Mapping):
        raise InfrastructureFailed(
            "released br status summary is unavailable for issue-universe "
            "membership validation"
        )
    if (
        len(listed) != summary.get("total_issues")
        or len(tombstones) != summary.get("tombstone_issues")
    ):
        raise NoData(
            "UnsupportedCapability: released br "
            f"{br_version} cannot enumerate template rows; list/status "
            "membership proves a hidden or otherwise unsupported issue "
            "universe"
        )
    return sorted([*listed, *tombstones])


def load_case_manifest() -> dict[str, Any]:
    path = resolve_safe(str(CASE_MANIFEST_REL), label="case manifest", must_exist=True)
    try:
        document = tomllib.loads(bounded_read(path).decode("utf-8"))
    except (UnicodeDecodeError, tomllib.TOMLDecodeError) as error:
        raise InputRefused(f"case manifest is malformed: {error}") from error
    if document.get("schema") != CASE_MANIFEST_SCHEMA:
        raise InputRefused("case manifest has an unknown schema")
    cases = document.get("case")
    if not isinstance(cases, list):
        raise InputRefused("case manifest must contain [[case]] rows")
    ids = [str(row.get("id", "")) for row in cases if isinstance(row, dict)]
    if len(ids) != len(set(ids)):
        raise InputRefused("case manifest contains duplicate case IDs")
    if tuple(ids) != EXPECTED_CASE_IDS:
        raise InputRefused(
            "case manifest membership/order differs from the frozen 21-case registry"
        )
    if tuple(str(value) for value in document.get("case_order", ())) != EXPECTED_CASE_IDS:
        raise InputRefused("case_order differs from the frozen 21-case registry")
    if int(document.get("case_count", -1)) != len(EXPECTED_CASE_IDS):
        raise InputRefused("case_count differs from the frozen registry")
    schema_contract = document.get("schema_contract")
    if not isinstance(schema_contract, dict):
        raise InputRefused("case manifest lacks schema_contract")
    required_case_fields = schema_contract.get("required_case_fields")
    if not isinstance(required_case_fields, list):
        raise InputRefused("schema_contract lacks required_case_fields")
    allowed_roles = set(str(value) for value in schema_contract.get("allowed_roles", ()))
    allowed_modes = set(str(value) for value in schema_contract.get("allowed_modes", ()))
    allowed_terminals = set(
        str(value) for value in schema_contract.get("allowed_terminals", ())
    )
    allowed_subject_terminals = set(
        str(value)
        for value in schema_contract.get("allowed_subject_terminals", ())
    )
    allowed_mutations = set(
        str(value)
        for value in schema_contract.get("allowed_mutation_bindings", ())
    )
    allowed_replays = set(
        str(value)
        for value in schema_contract.get("allowed_replay_bindings", ())
    )
    allowed_inner_categories = set(
        str(value)
        for value in schema_contract.get("allowed_inner_br_categories", ())
    )
    case_pattern = re.compile(str(schema_contract.get("case_id_pattern", r"$^")))
    for index, row in enumerate(cases):
        if not isinstance(row, dict):
            raise InputRefused(f"case row {index} is not a table")
        required = set(str(value) for value in required_case_fields)
        missing = sorted(required - set(row))
        if missing:
            raise InputRefused(f"{row.get('id', index)} lacks fields {missing}")
        extra = sorted(set(row) - required)
        if extra:
            raise InputRefused(f"{row['id']} has unknown fields {extra}")
        if int(row.get("ordinal", -1)) != index + 1:
            raise InputRefused(f"{row['id']} has a non-dense ordinal")
        if not case_pattern.fullmatch(str(row["id"])):
            raise InputRefused(f"{row['id']} has an invalid case ID")
        if str(row["role"]) not in allowed_roles:
            raise InputRefused(f"{row['id']} has an unknown role")
        if str(row["mode"]) not in allowed_modes:
            raise InputRefused(f"{row['id']} has an unknown mode")
        terminal = str(row["expected_terminal"])
        if terminal not in allowed_terminals:
            raise InputRefused(f"{row['id']} has unknown terminal {terminal}")
        if int(row["expected_exit"]) != 0:
            raise InputRefused(f"{row['id']} expectation harness must exit zero")
        if str(row["expected_subject_terminal"]) not in allowed_subject_terminals:
            raise InputRefused(f"{row['id']} has an unknown subject terminal")
        if str(row["mutation"]) not in allowed_mutations:
            raise InputRefused(f"{row['id']} has an unknown mutation binding")
        if str(row["replay"]) not in allowed_replays:
            raise InputRefused(f"{row['id']} has an unknown replay binding")
        if str(row["expected_inner_br_category"]) not in allowed_inner_categories:
            raise InputRefused(f"{row['id']} has an unknown inner br category")
        if row["expected_live_target_mutation"] is not False:
            raise InputRefused(f"{row['id']} may not mutate the live target")
        if bool(row["inverse_required"]) != (str(row["replay"]) == "inverse"):
            raise InputRefused(f"{row['id']} inverse/replay binding disagrees")
        if str(row["mode"]) == "--replay REL" and str(row["replay"]) != "artifact-only":
            raise InputRefused(f"{row['id']} --replay must be artifact-only")
    manifest_caps = document.get("caps")
    if not isinstance(manifest_caps, dict):
        raise InputRefused("case manifest lacks caps")
    if int(manifest_caps.get("max_targets_per_plan_shard", -1)) != CAPS[
        "plan_shard_rows"
    ]:
        raise InputRefused("manifest planning cap differs from harness")
    if int(manifest_caps.get("max_targets_per_apply_manifest", -1)) != CAPS[
        "apply_rows"
    ]:
        raise InputRefused("manifest apply cap differs from harness")
    document["case_count"] = len(cases)
    document["semantic_root"] = semantic_root(
        {key: value for key, value in document.items() if key != "semantic_root"}
    )
    return document


