            "responsibility_assignment_required_fields"
        ]
        != [
            "target_id",
            "implementation_owner",
            "evidence_owner",
            "terminal_consumer",
        ]
        or document["row_contract"][
            "responsibility_assignments_are_target_indexed"
        ]
        is not True
    ):
        raise InputRefused("v2 responsibility-assignment contract differs")
    if (
        not v2_manifest_ordered_string_list(
            document["packing_contract"]["hard_keys"],
            V2_PACKING_HARD_KEYS,
        )
        or document["packing_contract"]["retained_payload_measure"]
        != "SUM_SOURCE_FULL_ISSUE_CANONICAL_BYTES"
        or document["packing_contract"]["generated_child_payload_measure"]
        != "PLANNED_CHILD_CANONICAL_BYTES_WITH_DISTINCT_CAP"
        or document["packing_contract"]["generated_child_payload_exceeded"]
        != "EVIDENCE_FAILED_NO_PARTIAL_PLAN"
    ):
        raise InputRefused("v2 packing hard-key contract differs")
    if (
        not v2_manifest_closed_field_list(
            document["packing_contract"]["review_plan_required_fields"],
            V2_REVIEW_PLAN_FIELDS,
        )
        or not v2_manifest_closed_field_list(
            document["packing_contract"]["review_plan_count_fields"],
            V2_REVIEW_PLAN_COUNT_FIELDS,
        )
        or not v2_manifest_closed_field_list(
            document["packing_contract"]["review_plan_work_fields"],
            V2_REVIEW_PLAN_WORK_FIELDS,
        )
        or not v2_manifest_closed_field_list(
            document["packing_contract"]["oversize_required_fields"],
            V2_OVERSIZE_ARTIFACT_FIELDS,
        )
        or not v2_manifest_closed_field_list(
            document["packing_contract"][
                "oversize_exceeded_cap_required_fields"
            ],
            V2_OVERSIZE_EXCEEDED_CAP_FIELDS,
        )
        or not v2_manifest_closed_field_list(
            document["packing_contract"][
                "oversize_witness_required_fields"
            ],
            V2_OVERSIZE_WITNESS_FIELDS,
        )
        or document["packing_contract"]["oversize_clause_diagnostic"]
        != "BOUNDED_MAX_COUNT_AND_MEMBERSHIP_ROOT"
    ):
        raise InputRefused("v2 oversize diagnostic contract differs")
    history_contract = document["history_contract"]
    if (
        not v2_manifest_closed_field_list(
            history_contract["required_fields"],
            V2_HISTORY_ROW_FIELDS,
        )
        or not v2_manifest_ordered_string_list(
            history_contract["closer_states"],
            V2_CLOSER_STATES,
        )
        or history_contract["movement_current_universe"]
        != "FULL_ALL_STATUS_CAPTURE"
        or history_contract["movement_requires_current_universe_root"]
        is not True
        or history_contract["movement_requires_current_universe_count"]
        is not True
        or history_contract["movement_destination_root_kinds"]
        != [
            "INVENTORY_TARGET",
            "FULL_UNIVERSE_FILTERED_FINDING",
            "FULL_UNIVERSE_CLEAN_SUCCESSOR",
        ]
        or history_contract["movement_requires_destination_root_kind"]
        is not True
        or history_contract["prior_target_absent_from_current_universe"]
        != "REFUSE"
        or history_contract["prior_target_outside_selected_inventory"]
        != "REQUIRE_TYPED_CURRENT_FINDING_OR_CLOSED_CLEAN_SUCCESSOR"
        or history_contract["scope_successor_finding_states"]
        != ["CURRENT_FINDING", "NO_CURRENT_FINDING"]
        or history_contract["scope_successor_reasons"]
        != [
            "FILTERED_CURRENT_FINDING",
            "CLOSED_WITHOUT_CURRENT_FINDING",
        ]
        or not v2_manifest_closed_field_list(
            history_contract["scope_successor_required_fields"],
            V2_SCOPE_SUCCESSOR_FIELDS,
        )
        or history_contract["current_finding_membership"]
        != "FULL_SOURCE_DERIVED_EXPLICIT_ROOT_REQUIRED"
        or history_contract["nonclosed_filtered_current_finding"]
        != "ALLOW_TYPED_FILTERED_SUCCESSOR"
        or history_contract["nonclosed_without_current_finding"]
        != "REFUSE"
        or not v2_manifest_closed_field_list(
            history_contract["movement_required_fields"],
            V2_MOVEMENT_RECEIPT_FIELDS,
        )
        or history_contract["movement_successor_lineage_fields"]
        != [
            *V2_MOVEMENT_SUCCESSOR_LINEAGE_FIELDS,
        ]
    ):
        raise InputRefused("v2 clean-closure movement contract differs")
    cli_contract = document["cli_contract"]
    if (
        cli_contract["planner_modes"]
        != ["--review-plan", "--history-plan"]
        or cli_contract["review_receipts_paths"]
        != "SAFE_RELATIVE_EXACT_LOWERCASE_NONHIDDEN_JSON_ONLY"
        or cli_contract["review_receipts_read_policy"]
        != (
            "DESCRIPTOR_RELATIVE_O_NOFOLLOW_UNIQUE_REGULAR_STABLE_PATH_"
            "AND_CONTENT"
        )
        or cli_contract["review_receipts_aliases"] != "REFUSE"
        or cli_contract["v2_replay_mode"] != "--replay-v2 REL"
        or cli_contract["legacy_replay_mode"] != "--replay REL"
        or cli_contract["legacy_replay_dispatch"]
        != "TERMINAL_SCHEMA_AUTODETECT_COMPATIBILITY"
        or cli_contract["explicit_v2_replay_terminal_schema"]
        != V2_TERMINAL_SCHEMA
        or cli_contract["explicit_replay_preclassified"] is not True
        or cli_contract["legacy_replay_preclassified"] is not False
        or cli_contract["replay_auxiliary_options"] != "REFUSE"
    ):
        raise InputRefused("v2 CLI and replay-mode contract differs")
    artifact_contract = document["artifact_contract"]
    if (
        artifact_contract["bundle_states"]
        != ["COMPLETE_GREEN", "COMPLETE_NON_GREEN"]
        or not v2_manifest_ordered_string_list(
            artifact_contract["semantic_refusal_terminals"],
            V2_SEMANTIC_REFUSAL_TERMINALS,
        )
        or artifact_contract["semantic_refusal_projection_schema"]
        != V2_REFUSAL_PROJECTION_SCHEMA
        or artifact_contract["semantic_refusal_optional_content"]
        != "FORBIDDEN"
        or artifact_contract["semantic_refusal_requires_reserved_run"] is not True
        or artifact_contract["retry_requires_fresh_run_dir"] is not True
        or artifact_contract["publication_topology_preflight"]
        != "EXACT_FILE_DIRECTORY_SET_BEFORE_FIRST_PAYLOAD_WRITE"
        or artifact_contract["publication_addressing"]
        != "DESCRIPTOR_RELATIVE_O_NOFOLLOW"
        or artifact_contract["reserved_prefix_membership"]
        != "EMPTY_TERMINAL_ONLY"
        or artifact_contract["terminal_assignment_state_machine"]
        != [
            "RESERVED_EMPTY",
            "ASSIGNMENT_STARTED",
            "DURABLY_COMMITTED",
            "VERIFIED_SEALED",
        ]
        or artifact_contract["terminal_readback"]
        != "SAME_DESCRIPTOR_AND_PATH_IDENTITY"
        or artifact_contract["persistent_incomplete_prefix_retry"]
        != "BOUNDED_FRESH_ATTEMPT_AFTER_INCOMPLETE_PREFIX"
    ):
        raise InputRefused("v2 semantic-refusal artifact contract differs")
    logging_contract = document["logging_contract"]
    if (
        logging_contract["subprocess_capture"]
        != "NONBLOCKING_SELECTOR_BOUNDED"
        or logging_contract["subprocess_process_group"]
        != "NEW_SESSION_TERM_THEN_IMMEDIATE_KILL_AND_DRAIN"
        or tuple(logging_contract["subprocess_failure_receipts"])
        != V2_SUBPROCESS_FAILURE_RECEIPTS
        or logging_contract["subprocess_stream_cap_accounting"]
        != "RETAIN_AT_MOST_EXACT_CAP_AND_ROOT_RETAINED_PREFIX"
        or logging_contract["subprocess_argv_redaction"]
        != (
            "COUNT_AND_BYTES_BOUNDED_CONTEXTUAL_SENSITIVE_VALUE_AND_"
            "ABSOLUTE_PATH_REDACTED"
        )
    ):
        raise InputRefused("v2 bounded subprocess logging contract differs")
    replay_contract = document["replay_contract"]
    if (
        replay_contract["artifact_only"] is not True
        or replay_contract["live_tracker_reads"] != "FORBIDDEN"
        or replay_contract["live_tracker_writes"] != "FORBIDDEN"
        or replay_contract["network_access"] != "FORBIDDEN"
        or replay_contract["output_is_disjoint"] is not True
        or replay_contract["overwrite"] != "FORBIDDEN"
        or replay_contract[
            "missing_unlisted_duplicate_changed_unsafe_extra"
        ]
        != "REFUSE"
        or replay_contract["selected_projection_required"] is not True
        or replay_contract["not_requested_projection_required"] is not True
        or replay_contract["all_status_partition_required"] is not True
        or replay_contract[
            "oversize_inventory_required_when_nonempty"
        ]
        is not True
        or replay_contract["first_divergence_required"] is not True
        or replay_contract["v2_manifest_root_required"] is not True
        or replay_contract["v1_manifest_root_required"] is not False
        or replay_contract["replay_mints_authority"] is not False
        or replay_contract[
            "replay_proves_current_tracker_state"
        ]
        is not False
        or replay_contract["semantic_refusal_behavior"]
        != "VALIDATE_AND_REFUSE_WITHOUT_OUTPUT"
        or replay_contract["semantic_refusal_replay_mints_pass"]
        is not False
        or replay_contract["result_schema"] != V2_REPLAY_RESULT_SCHEMA
        or not v2_manifest_closed_field_list(
            replay_contract["result_required_fields"],
            V2_REPLAY_RESULT_FIELDS,
        )
        or replay_contract["result_rooted"] is not True
        or replay_contract["execution_process_guard"]
        != "RUN_COMMAND_ROUTED_REENTRANT_FAIL_CLOSED_SUBPROCESS_EXCLUSION"
        or replay_contract["explicit_cli_mode"] != "--replay-v2"
        or replay_contract["legacy_cli_mode"] != "--replay"
        or replay_contract["legacy_dispatch"]
        != "SCHEMA_AUTODETECT_AFTER_UNCLASSIFIED_PREFLIGHT"
        or replay_contract["v2_terminal_schema_required"]
        != V2_TERMINAL_SCHEMA
        or replay_contract["reproduction_mode"] != "--replay-v2"
        or replay_contract["explicit_cli_subprocess_proof"]
        != "ARTIFACT_BACKED_SUCCESS_AND_TYPED_FAILURE_MATRIX"
    ):
        raise InputRefused("v2 offline replay contract differs")

    v1_path = resolve_safe(
        str(CASE_MANIFEST_REL),
        label="v1 compatibility manifest",
        must_exist=True,
    )
    v1_payload = bounded_read(v1_path)
    compatibility = document["compatibility_contract"]
    v1_content_root = "sha256-v1:" + hashlib.sha256(v1_payload).hexdigest()
    if v1_content_root != compatibility["v1_manifest_content_root"]:
        raise InputRefused("frozen v1 manifest content identity drifted")
    v1_manifest = load_case_manifest()
    if (
        v1_manifest["semantic_root"]
        != compatibility["v1_case_manifest_semantic_root"]
    ):
        raise InputRefused("frozen v1 case-manifest semantic root drifted")
    if (
        compatibility["v1_manifest_path"] != str(CASE_MANIFEST_REL)
        or compatibility["v1_harness_path"] != str(SCRIPT_REL)
        or compatibility["v1_schema"] != CASE_MANIFEST_SCHEMA
        or compatibility["v1_case_count"] != 21
        or compatibility["v1_assertion_count"] != 148
        or re.fullmatch(
            r"[0-9a-f]{40}",
            compatibility["v1_manifest_adopted_git_blob"],
        )
        is None
        or re.fullmatch(
            r"[0-9a-f]{40}",
            compatibility["v1_harness_adopted_git_blob"],
        )
        is None
        or re.fullmatch(
            r"[0-9a-f]{40}",
            compatibility["v1_manifest_adopted_git_commit"],
        )
        is None
        or compatibility["v1_manifest_blob_retention"]
        != "REACHABLE_COMMIT_PATH_IDENTITY"
        or compatibility["v1_harness_blob_retention"]
        != "UNREACHABLE_LOCAL_OBJECT_NODATA"
        or compatibility["adoption_head_binding"]
        != "CAMPAIGN_METADATA_ONLY_NOT_V1_PATH_IDENTITY"
        or compatibility["adoption_artifact_retention"]
        != "IGNORED_LOCAL_ONLY_NODATA"
        or compatibility["portable_adoption_evidence"] is not False
        or compatibility["compatibility_proof_authority"]
        != "CURRENT_V1_MANIFEST_AND_RUNTIME_REGRESSION_ONLY"
    ):
        raise InputRefused(
            "v1 compatibility retention or proof-authority boundary differs"
        )

    document["content_identity"] = content_identity
    document["harness_contract_identity"] = harness_contract_identity
    document["semantic_root"] = semantic_root(
        {key: value for key, value in document.items() if key != "semantic_root"}
    )
    # The runtime-only callable registry is proved by the dedicated
    # compiled-executor-bijection assertion. Manifest admission binds the
    # closed assertion membership without pulling every executor function into
    # refusal-state projections merely because a registry stores it as data.
    return document


def canonical_issue_projection(issue: Mapping[str, Any]) -> dict[str, Any]:
    dependencies = sorted(
        (
            {
                "id": str(edge.get("id", "")),
                "type": str(
                    edge.get("dependency_type", edge.get("type", ""))
                ),
                "status": str(edge.get("status") or ""),
                "priority": edge.get("priority"),
            }
            for edge in (issue.get("dependencies") or [])
            if isinstance(edge, dict)
        ),
        key=lambda edge: (edge["type"], edge["id"]),
    )
    dependents = sorted(
        (
            {
                "id": str(edge.get("id", "")),
                "type": str(
                    edge.get("dependency_type", edge.get("type", ""))
                ),
                "status": str(edge.get("status") or ""),
                "priority": edge.get("priority"),
            }
            for edge in (issue.get("dependents") or [])
            if isinstance(edge, dict)
        ),
        key=lambda edge: (edge["type"], edge["id"]),
    )
    return {
        "id": str(issue.get("id", "")),
        "title": str(issue.get("title", "")),
        "type": str(issue.get("issue_type") or issue.get("type") or ""),
        "status": str(issue.get("status", "")),
        "priority": issue.get("priority"),
        "assignee": str(issue.get("assignee") or ""),
        "owner": str(issue.get("owner") or ""),
        "parent": str(issue.get("parent") or ""),
        "estimated_minutes": issue.get("estimated_minutes"),
        "due_at": str(issue.get("due_at") or ""),
        "defer_until": str(issue.get("defer_until") or ""),
        "close_reason": str(issue.get("close_reason") or ""),
        "ephemeral": issue.get("ephemeral") is True,
        "pinned": issue.get("pinned") is True,
        "is_template": issue.get("is_template") is True,
        "external_ref": str(issue.get("external_ref") or ""),
        "source_system": str(issue.get("source_system") or ""),
        "source_repo": str(issue.get("source_repo") or ""),
        "agent_context": str(issue.get("agent_context") or ""),
        "labels": sorted(str(label) for label in (issue.get("labels") or [])),
        "description": str(issue.get("description") or ""),
        "acceptance_criteria": str(issue.get("acceptance_criteria") or ""),
        "design": str(issue.get("design") or ""),
        "notes": str(issue.get("notes") or ""),
        "updated_at": str(issue.get("updated_at") or ""),
        "dependencies": dependencies,
        "dependents": dependents,
    }


def show_issues(issue_ids: Sequence[str]) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    batch_size = min(CAPS["show_batch"], 56)
    for offset in range(0, len(issue_ids), batch_size):
        check_cancel()
        batch = issue_ids[offset : offset + batch_size]
        document = br_read_json("show", *batch, "--json")
        if not isinstance(document, list):
            raise InfrastructureFailed("br show batch did not return an array")
        rows.extend(
            canonical_issue_projection(issue)
            for issue in document
            if isinstance(issue, dict)
        )
    rows.sort(key=lambda issue: issue["id"])
    if [row["id"] for row in rows] != sorted(issue_ids):
        raise InfrastructureFailed("br show membership differs from lint issue set")
    return rows


def v2_validate_raw_br_issue(issue: Mapping[str, Any]) -> None:
    if type(issue) is not dict:
        raise InfrastructureFailed("v2 br issue is not an exact object")
    unknown_issue_fields = set(issue) - V2_RAW_BR_SHOW_FIELDS
    if unknown_issue_fields:
        raise InfrastructureFailed(
            "v2 br issue has unknown released-show fields: "
            f"{sorted(unknown_issue_fields)}"
        )
    if not {"id", "title", "status", "priority"}.issubset(issue):
        raise InfrastructureFailed(
            "v2 br issue lacks required released-show fields"
        )
    issue_id = issue["id"]
    fallback_issue_type = issue["type"] if "type" in issue else None
    issue_type = (
        issue["issue_type"]
        if "issue_type" in issue
        else fallback_issue_type
    )
    raw_issue_status = issue["status"]
    issue_status = v2_validate_status(
        raw_issue_status,
        label="v2 br issue status",
        error_type=InfrastructureFailed,
    )
    if (
        "issue_type" in issue
        and "type" in issue
        and issue["issue_type"] != fallback_issue_type
    ):
        raise InfrastructureFailed(
            "v2 br issue contains contradictory type aliases"
        )
    if (
        type(issue_id) is not str
        or not issue_id
        or type(issue["title"]) is not str
        or not str.strip(issue["title"])
        or type(issue_type) is not str
        or not issue_type
        or raw_issue_status != issue_status
        or type(issue["priority"]) is not int
        or issue["priority"] not in range(5)
    ):
        raise InfrastructureFailed("v2 br issue contains invalid core scalars")
    issue_id = v2_validate_issue_id(
        issue_id,
        label="v2 br issue ID",
        error_type=InfrastructureFailed,
    )
    for field in (
        "assignee",
        "owner",
        "parent",
        "description",
        "acceptance_criteria",
        "design",
        "notes",
        "created_at",
        "created_by",
        "closed_at",
        "close_reason",
        "closed_by_session",
        "due_at",
        "defer_until",
        "external_ref",
        "source_system",
        "agent_context",
        "deleted_at",
        "deleted_by",
        "delete_reason",
        "original_type",
        "compacted_at",
        "compacted_at_commit",
        "sender",
        "source_repo",
        "source_repo_path",
        "updated_at",
    ):
        value = issue[field] if field in issue else None
        if value is not None and type(value) is not str:
            raise InfrastructureFailed(
                f"v2 br issue {issue_id} has a non-string {field}"
            )
    labels = issue["labels"] if "labels" in issue else None
    if labels is None:
        labels = []
    if type(labels) is not list:
        raise InfrastructureFailed(f"v2 br issue {issue_id} has invalid labels")
    if len(labels) > V2_LABELS_PER_ISSUE_CAP:
        raise InfrastructureFailed(
            f"v2 br issue {issue_id} exceeds the label-count cap"
        )
    if any(
        type(value) is not str or not value for value in labels
    ) or len(labels) != len(set(labels)):
        raise InfrastructureFailed(f"v2 br issue {issue_id} has invalid labels")
    comments = issue["comments"] if "comments" in issue else None
    if comments is None:
        comments = []
    if (
        type(comments) is not list
        or len(comments) > V2_AUDIT_EVENTS_PER_ISSUE_CAP
    ):
        raise InfrastructureFailed(
            f"v2 br issue {issue_id} has invalid comments"
        )
    previous_comment_order: tuple[datetime, int] | None = None
    comment_ids: dict[int, None] = {}
    for comment_index, comment in enumerate(comments):
        if type(comment) is not dict:
            raise InfrastructureFailed(
                f"v2 br issue {issue_id} has invalid comment {comment_index}"
            )
        if (
            set(comment) != V2_SOURCE_COMMENT_FIELDS
            or type(comment["id"]) is not int
            or comment["id"] <= 0
            or comment["id"] in comment_ids
            or comment["issue_id"] != issue_id
            or type(comment["author"]) is not str
            or not comment["author"]
            or type(comment["text"]) is not str
            or type(comment["created_at"]) is not str
        ):
            raise InfrastructureFailed(
                f"v2 br issue {issue_id} has invalid comment {comment_index}"
            )
        comment_timestamp = v2_parse_timestamp(
            comment["created_at"],
            label=f"v2 br issue {issue_id} comment {comment_index}",
        )
        comment_order = (comment_timestamp, comment["id"])
        if (
            previous_comment_order is not None
            and comment_order <= previous_comment_order
        ):
            raise InfrastructureFailed(
                f"v2 br issue {issue_id} comments are not ordered by "
                "created_at then ID ascending"
            )
        previous_comment_order = comment_order
        comment_ids[comment["id"]] = None
    events = issue["events"] if "events" in issue else None
    if events is not None and events != []:
        raise InfrastructureFailed(
            f"v2 br show unexpectedly returned events for {issue_id}"
        )
    rollup = issue["rollup"] if "rollup" in issue else None
    if rollup is not None:
        if (
            type(rollup) is not dict
            or set(rollup) != V2_SOURCE_ROLLUP_FIELDS
            or type(rollup["status"]) is not str
            or not rollup["status"]
            or type(rollup["descendants"]) is not dict
            or len(rollup["descendants"]) > V2_INVENTORY_ROWS_CAP
            or any(
                type(status) is not str
                or not status
                or type(count) is not int
                or count < 0
                for status, count in dict.items(rollup["descendants"])
            )
        ):
            raise InfrastructureFailed(
                f"v2 br issue {issue_id} has invalid rollup"
            )
        try:
            v2_validate_status(
                rollup["status"],
                label=f"v2 br issue {issue_id} rollup status",
                error_type=InfrastructureFailed,
            )
            for descendant_status in rollup["descendants"]:
                v2_validate_status(
                    descendant_status,
                    label=(
                        f"v2 br issue {issue_id} rollup descendant status"
                    ),
                    error_type=InfrastructureFailed,
                )
        except HarnessError as error:
            raise InfrastructureFailed(
                f"v2 br issue {issue_id} has invalid rollup"
            ) from error
    estimate = (
        issue["estimated_minutes"]
        if "estimated_minutes" in issue
        else None
    )
    if estimate is not None and (
        type(estimate) is not int or estimate < 0
    ):
        raise InfrastructureFailed(
            f"v2 br issue {issue_id} has invalid estimated minutes"
        )
    for boolean_field in ("ephemeral", "pinned", "is_template"):
        if boolean_field in issue and type(issue[boolean_field]) is not bool:
            raise InfrastructureFailed(
                f"v2 br issue {issue_id} has invalid {boolean_field} state"
            )
    for integer_field in ("compaction_level", "original_size"):
        value = issue[integer_field] if integer_field in issue else None
        if value is not None and (
            type(value) is not int or value < 0
        ):
            raise InfrastructureFailed(
                f"v2 br issue {issue_id} has invalid {integer_field}"
            )
    for relation_field in ("dependencies", "dependents"):
        relations = issue[relation_field] if relation_field in issue else None
        if relations is None:
            relations = []
        if type(relations) is not list:
            raise InfrastructureFailed(
                f"v2 br issue {issue_id} has invalid {relation_field}"
            )
        if len(relations) > V2_RELATIONS_PER_DIRECTION_CAP:
            raise InfrastructureFailed(
                f"v2 br issue {issue_id} exceeds the {relation_field} cap"
            )
        relation_neighbors: list[str] = []
        for relation in relations:
            if type(relation) is not dict:
                raise InfrastructureFailed(
                    f"v2 br issue {issue_id} has an invalid relation row"
                )
            if (
                not {"id", "title", "status", "priority"}.issubset(
                    relation
                )
                or set(relation)
                - {
                    "id",
                    "title",
                    "status",
                    "priority",
                    "dependency_type",
                    "type",
                }
            ):
                raise InfrastructureFailed(
                    f"v2 br issue {issue_id} has an invalid relation row "
                    "with a non-closed schema"
                )
            if (
                "dependency_type" in relation
                and "type" in relation
                and dict.__getitem__(relation, "dependency_type")
                != dict.__getitem__(relation, "type")
            ):
                raise InfrastructureFailed(
                    f"v2 br issue {issue_id} has contradictory relation aliases"
                )
            fallback_relation_type = (
                dict.__getitem__(relation, "type")
                if "type" in relation
                else None
            )
            relation_type = (
                dict.__getitem__(relation, "dependency_type")
                if "dependency_type" in relation
                else fallback_relation_type
            )
            relation_status = dict.__getitem__(relation, "status")
            relation_priority = dict.__getitem__(relation, "priority")
            relation_id = dict.__getitem__(relation, "id")
            relation_title = dict.__getitem__(relation, "title")
            if (
                type(relation_id) is not str
                or not relation_id
                or relation_id == issue_id
                or (
                    str.startswith(relation_id, "external:")
                    and (
                        relation_id == "external:"
                        or (
                            relation_field == "dependencies"
                            and relation_type == "parent-child"
                        )
                        or (
                            relation_field == "dependents"
                            and relation_type != "parent-child"
                        )
                    )
                )
                or type(relation_type) is not str
                or not relation_type
                or type(relation_title) is not str
                or not str.strip(relation_title)
                or type(relation_status) is not str
                or (
                    type(relation_priority) is not int
                    or relation_priority not in range(5)
                )
            ):
                raise InfrastructureFailed(
                    f"v2 br issue {issue_id} has an invalid relation row"
                )
            v2_validate_status(
                relation_status,
                label=(
                    f"v2 br issue {issue_id} {relation_field} "
                    "relation status"
                ),
                error_type=InfrastructureFailed,
            )
            relation_label = (
                f"v2 br issue {issue_id} {relation_field} relation ID"
            )
            relation_neighbors.append(
                v2_validate_external_relation_id(
                    relation_id,
                    label=relation_label,
                    error_type=InfrastructureFailed,
                )
                if str.startswith(relation_id, "external:")
                else v2_validate_issue_id(
                    relation_id,
                    label=relation_label,
                    error_type=InfrastructureFailed,
                )
            )
        if len(relation_neighbors) != len(set(relation_neighbors)):
            raise InfrastructureFailed(
                f"v2 br issue {issue_id} duplicates a "
                f"{relation_field} neighbor"
            )


def v2_full_issue_projection(issue: Mapping[str, Any]) -> dict[str, Any]:
    v2_validate_raw_br_issue(issue)
    stable = {
        **canonical_issue_projection(issue),
        **{
            relation_field: sorted(
                (
                    {
                        "id": str(edge.get("id") or ""),
                        "title": str(edge.get("title") or ""),
                        "type": str(
                            edge.get(
                                "dependency_type",
                                edge.get("type", ""),
                            )
                        ),
                        "status": str(edge.get("status") or ""),
                        "priority": edge.get("priority"),
                    }
                    for edge in (issue.get(relation_field) or [])
                    if isinstance(edge, dict)
                ),
                key=lambda edge: (edge["type"], edge["id"]),
            )
            for relation_field in ("dependencies", "dependents")
        },
    }
    fields = {
        field: str(issue.get(field) or "")
        for field in ("description", "acceptance_criteria", "design", "notes")
    }
    comments = [
        {
            "id": comment["id"],
            "issue_id": comment["issue_id"],
            "author": comment["author"],
            "text": comment["text"],
            "created_at": comment["created_at"],
        }
        for comment in (issue.get("comments") or [])
    ]
    rollup = issue.get("rollup")
    normalized_rollup = (
        None
        if rollup is None
        else {
            "status": rollup["status"],
            "descendants": dict(sorted(rollup["descendants"].items())),
        }
    )
    projection = {
        **stable,
        "ephemeral": issue.get("ephemeral") is True,
        "pinned": issue.get("pinned") is True,
        "is_template": issue.get("is_template") is True,
        "due_at": str(issue.get("due_at") or ""),
        "defer_until": str(issue.get("defer_until") or ""),
        "created_at": str(issue.get("created_at") or ""),
        "created_by": str(issue.get("created_by") or ""),
        "closed_at": str(issue.get("closed_at") or ""),
        "close_reason": str(issue.get("close_reason") or ""),
        "closed_by_session": str(issue.get("closed_by_session") or ""),
        "external_ref": str(issue.get("external_ref") or ""),
        "source_system": str(issue.get("source_system") or ""),
        "agent_context": str(issue.get("agent_context") or ""),
        "deleted_at": str(issue.get("deleted_at") or ""),
        "deleted_by": str(issue.get("deleted_by") or ""),
        "delete_reason": str(issue.get("delete_reason") or ""),
        "original_type": str(issue.get("original_type") or ""),
        "compaction_level": int(issue.get("compaction_level") or 0),
        "compacted_at": str(issue.get("compacted_at") or ""),
        "compacted_at_commit": str(issue.get("compacted_at_commit") or ""),
        "original_size": issue.get("original_size"),
        "sender": str(issue.get("sender") or ""),
        "comments": comments,
        "events": [],
        "rollup": normalized_rollup,
        "released_fields_present": sorted(issue),
        "released_field_value_roots": {
            field: semantic_root(issue[field]) for field in sorted(issue)
        },
        "field_roots": {
            field: text_root(value) for field, value in sorted(fields.items())
        },
        "source_repo": str(issue.get("source_repo") or ""),
        "source_repo_path": {
            "body_retained": False,
            "root": text_root(str(issue.get("source_repo_path") or "")),
        },
        "no_claim": V2_SOURCE_ISSUE_NO_CLAIM,
    }
    return {
        **projection,
        "source_issue_projection_root": semantic_root(
            {
                key: value
                for key, value in projection.items()
                if key != "no_claim"
            }
        ),
    }


def v2_show_all_issues(
    issue_ids: Sequence[str],
    *,
    br_cwd: Path = REPO_ROOT,
) -> list[dict[str, Any]]:
    if len(issue_ids) > V2_INVENTORY_ROWS_CAP:
        raise InputRefused(
            f"v2 source has more than {V2_INVENTORY_ROWS_CAP} issue rows"
        )
    validated_issue_ids = [
        v2_validate_issue_id(
            issue_id,
            label=f"v2 show issue ID {index}",
            error_type=InputRefused,
        )
        for index, issue_id in enumerate(issue_ids)
    ]
    if len(validated_issue_ids) != len(set(validated_issue_ids)):
        raise InputRefused("v2 show issue IDs are not unique")
    rows: list[dict[str, Any]] = []
    retained_projection_bytes = len(canonical_bytes([]))
    batch_size = min(CAPS["show_batch"], 56)
    for offset in range(0, len(validated_issue_ids), batch_size):
        check_cancel()
        batch = validated_issue_ids[offset : offset + batch_size]
        document = br_read_json(
            "show",
            *batch,
            "--json",
            br_cwd=br_cwd,
        )
        if not isinstance(document, list):
            raise InfrastructureFailed("v2 br show batch did not return an array")
        if len(document) != len(batch):
            raise InfrastructureFailed(
                "v2 br show batch cardinality differs from its request"
            )
        for index, issue in enumerate(document):
            if not isinstance(issue, dict):
                raise InfrastructureFailed(
                    f"v2 br show batch row {index} is not an object"
                )
            projected = v2_full_issue_projection(issue)
            projected_bytes = len(canonical_bytes(projected))
            retained_projection_bytes = (
                projected_bytes + 2
                if not rows
                else retained_projection_bytes + projected_bytes
            )
            v2_validate_aggregate_byte_count(
                retained_projection_bytes,
                cap=V2_SOURCE_PROJECTION_BYTES_CAP,
                label="v2 source projections",
                error_type=InfrastructureFailed,
            )
            rows.append(projected)
    rows.sort(key=lambda issue: issue["id"])
    if [row["id"] for row in rows] != sorted(validated_issue_ids):
        raise InfrastructureFailed("v2 br show membership differs from br list")
    return rows


def v2_normalize_br_lint_document(
    document: Any,
    *,
    scope: str,
    error_type: type[HarnessError] = InfrastructureFailed,
) -> dict[str, Any]:
    if (
        error_type is not InputRefused
        and error_type is not InfrastructureFailed
        and error_type is not EvidenceFailed
    ):
        raise EvidenceFailed(
            "br lint normalizer error type is not an allowed terminal"
        )
    if type(scope) is not str or not scope:
        raise error_type("br lint scope is not an exact non-empty string")
    document = v2_released_json_snapshot(
        document,
        label="br lint document",
        error_type=error_type,
    )
    if type(document) is not dict or set(document) != {
        "total",
        "issues",
        "results",
    }:
        raise error_type(f"br lint {scope} has a non-closed output schema")
    total = document["total"]
    issues = document["issues"]
    raw_results = document["results"]
    if (
        type(total) is not int
        or type(issues) is not int
        or total < 0
        or issues < 0
        or type(raw_results) is not list
        or total > CAPS["warnings"]
        or issues > CAPS["issues"]
        or list.__len__(raw_results) != issues
    ):
        raise error_type(f"br lint {scope} counts or rows are malformed")
    for index, raw_row in enumerate(raw_results):
        if type(raw_row) is not dict or set(raw_row) != {
            "id",
            "title",
            "type",
            "missing",
            "warnings",
            "suggestions",
        }:
            raise error_type(
                f"br lint {scope} row {index} has a non-closed schema"
            )
        issue_id = v2_validate_issue_id(
            dict.__getitem__(raw_row, "id"),
            label=f"br lint {scope} row {index} ID",
            error_type=error_type,
        )
        title = dict.__getitem__(raw_row, "title")
        issue_type = dict.__getitem__(raw_row, "type")
        missing = dict.__getitem__(raw_row, "missing")
        warnings = dict.__getitem__(raw_row, "warnings")
        suggestions = dict.__getitem__(raw_row, "suggestions")
        if (
            type(title) is not str
            or not str.strip(title)
            or type(issue_type) is not str
            or not issue_type
            or type(missing) is not list
            or not missing
            or type(suggestions) is not list
            or list.__len__(missing) > FIXTURE_MAX_WARNINGS_PER_ISSUE
            or list.__len__(suggestions) > FIXTURE_MAX_WARNINGS_PER_ISSUE
        ):
            raise error_type(
                f"br lint {scope} row {index} has invalid released scalars"
            )
        required = dict.get(REQUIRED_SECTIONS_BY_TYPE, issue_type)
        if (
            any(
                type(section) is not str or not section
                for section in missing
            )
            or type(required) is not tuple
            or any(type(section) is not str for section in required)
            or missing
            != [section for section in required if section in set(missing)]
            or len(missing) != len(set(missing))
            or type(warnings) is not int
            or warnings != len(missing)
            or len(suggestions) != len(missing)
        ):
            raise error_type(
                f"br lint {scope} row {index} has invalid released scalars"
            )
        expected_suggestions = [
            {
                "section": section,
                "hint": LINT_SECTION_HINTS_BY_TYPE[issue_type][section],
            }
            for section in missing
        ]
        suggestions_are_exact = all(
            type(suggestion) is dict
            and set(suggestion) == {"section", "hint"}
            and all(
                type(suggestion[field]) is str
                and bool(suggestion[field])
                for field in ("section", "hint")
            )
            for suggestion in suggestions
        )
        if (
            not suggestions_are_exact
            or suggestions != expected_suggestions
        ):
            raise error_type(
                f"br lint {scope} row {index} suggestions differ from "
                "released-br"
            )
    normalized_rows = sorted(
        raw_results,
        key=lambda row: dict.__getitem__(row, "id"),
    )
    ids = [row["id"] for row in normalized_rows]
    if len(ids) != len(set(ids)):
        raise error_type(f"br lint {scope} contains duplicate issue")
    if (
        ids != sorted(ids)
        or len(normalized_rows) != issues
        or sum(row["warnings"] for row in normalized_rows) != total
    ):
        raise error_type(f"br lint {scope} count or membership differs")
    return {
        "total": total,
        "issues": issues,
        "results": normalized_rows,
    }


def v2_validate_lint_scope_coherence(
    lint: Mapping[str, Any],
    *,
    full_issues: Sequence[Mapping[str, Any]] | None,
    error_type: type[HarnessError],
) -> None:
    if (
        error_type is not InputRefused
        and error_type is not InfrastructureFailed
        and error_type is not EvidenceFailed
    ):
        raise EvidenceFailed(
            "br lint coherence error type is not an allowed terminal"
        )
    if full_issues is None:
        raw_full_issues: list[Any] | None = None
    elif type(full_issues) is list:
        if list.__len__(full_issues) > CAPS["issues"]:
            raise error_type("br lint full issues exceed their cap")
        raw_full_issues = full_issues
    elif type(full_issues) is tuple:
        if tuple.__len__(full_issues) > CAPS["issues"]:
            raise error_type("br lint full issues exceed their cap")
        raw_full_issues = list(tuple.__iter__(full_issues))
    else:
        raise error_type("br lint full issues are not an exact sequence")
    detached_inputs = v2_released_json_snapshot(
        {
            "lint": lint,
            "full_issues": raw_full_issues,
        },
        label="br lint coherence inputs",
        error_type=error_type,
    )
    if type(detached_inputs) is not dict:
        raise error_type("br lint coherence snapshot is not an exact object")
    lint = dict.__getitem__(detached_inputs, "lint")
    full_issues = dict.__getitem__(detached_inputs, "full_issues")
    if type(lint) is not dict or "all" not in lint:
        raise error_type("br lint scope membership differs")
    status_scopes = v2_canonical_status_scopes(
        [scope for scope in lint if scope != "all"],
        error_type=error_type,
    )
    if set(lint) != {*status_scopes, "all"}:
        raise error_type("br lint scope membership differs")
    ordered_scopes = (*status_scopes, "all")
    normalized = {
        scope: v2_normalize_br_lint_document(
            lint[scope],
            scope=scope,
            error_type=error_type,
        )
        for scope in ordered_scopes
    }
    retained_scopes = {
        scope: dict.__getitem__(lint, scope)
        for scope in ordered_scopes
    }
    if normalized != retained_scopes:
        raise error_type("br lint scopes are not canonically normalized")
    all_by_id = {
        row["id"]: row for row in normalized["all"]["results"]
    }
    scoped_issue_ids: dict[str, str] = {}
    for scope in status_scopes:
        for row in normalized[scope]["results"]:
            if all_by_id.get(row["id"]) != row:
                raise error_type(
                    f"br lint {scope} row differs from the all-scope row"
                )
            if row["id"] in scoped_issue_ids:
                raise error_type(
                    "br lint status cuts are not the exact union of all; "
                    f"duplicate issue {row['id']}"
                )
            scoped_issue_ids[row["id"]] = scope
    if set(scoped_issue_ids) != set(all_by_id):
        missing = sorted(set(all_by_id) - set(scoped_issue_ids))
        extra = sorted(set(scoped_issue_ids) - set(all_by_id))
        first = (missing or extra or ["unknown"])[0]
        raise error_type(
            "br lint status cuts are not the exact union of all; "
            f"first divergent issue {first}"
        )
    if full_issues is None:
        return
    if type(full_issues) is not list:
        raise error_type("br lint full-issue snapshot is not an exact array")
    issue_by_id: dict[str, dict[str, Any]] = {}
    for issue_index, issue in enumerate(full_issues):
        if type(issue) is not dict:
            raise error_type(
                f"br lint full issue {issue_index} is not an exact object"
            )
        issue_fields = frozenset(dict.__iter__(issue))
        if not {
            "id",
            "title",
            "type",
            "status",
        }.issubset(issue_fields):
            raise error_type(
                f"br lint full issue {issue_index} lacks identity fields"
            )
        issue_id = dict.__getitem__(issue, "id")
        issue_title = dict.__getitem__(issue, "title")
        issue_type = dict.__getitem__(issue, "type")
        issue_status = dict.__getitem__(issue, "status")
        if (
            type(issue_id) is not str
            or not issue_id
            or type(issue_title) is not str
            or not str.strip(issue_title)
            or type(issue_type) is not str
            or not issue_type
            or type(issue_status) is not str
            or issue_id in issue_by_id
        ):
            raise error_type(
                f"br lint full issue {issue_index} has invalid identity"
            )
        v2_validate_issue_id(
            issue_id,
            label=f"br lint full issue {issue_index} ID",
            error_type=error_type,
        )
        v2_validate_status(
            issue_status,
            label=f"br lint full issue {issue_index} status",
            error_type=error_type,
        )
        issue_by_id[issue_id] = issue
    missing_status_scopes = set(v2_status_scopes(full_issues)) - set(
        status_scopes
    )
    if missing_status_scopes:
        raise error_type(
            "br lint lacks full-issue status scopes: "
            f"{sorted(missing_status_scopes)}"
        )
    for issue_id, row in all_by_id.items():
        issue = issue_by_id.get(issue_id)
        if (
            issue is None
            or row["title"] != issue["title"]
            or row["type"] != issue["type"]
        ):
            raise error_type(
                "br lint row identity differs from the full issue projection"
            )
        expected_scope = issue["status"]
        if dict.get(scoped_issue_ids, issue_id) != expected_scope:
            raise error_type(
                "br lint status scopes disagree with the full issue "
                "projection"
            )


def lint_scopes(
    *,
    br_cwd: Path = REPO_ROOT,
    status_scopes: Sequence[str] = STATUS_SCOPES,
) -> dict[str, Any]:
    canonical_status_scopes = v2_canonical_status_scopes(
        status_scopes,
        error_type=InfrastructureFailed,
    )
    result = {
        scope: v2_normalize_br_lint_document(
            br_read_json(
                "lint",
                "--status",
                scope,
                "--json",
                br_cwd=br_cwd,
            ),
            scope=scope,
            error_type=InfrastructureFailed,
        )
        for scope in (*canonical_status_scopes, "all")
    }
    v2_validate_lint_scope_coherence(
        result,
        full_issues=None,
        error_type=InfrastructureFailed,
    )
    return result


def section_present(text: str, section: str) -> bool:
    lines = visible_markdown_lines(text)
    return lines is not None and any(line.strip() == section for line in lines)


def visible_markdown_lines(text: str) -> list[str] | None:
    if type(text) is not str:
        raise EvidenceFailed("markdown source is not an exact string")
    if len(text) > CAPS["semantic_field_bytes"]:
        return None
    encoded = str.encode(text, "utf-8")
    lines = str.splitlines(text)
    if (
        len(encoded) > CAPS["semantic_field_bytes"]
        or len(lines) > CAPS["semantic_field_lines"]
    ):
        return None
    visible: list[str] = []
    fenced = False
    fence_marker = ""
    in_comment = False
    for line in lines:
        stripped = str.lstrip(line)
        if in_comment:
            if "-->" in stripped:
                in_comment = False
            continue
        if str.startswith(stripped, "<!--"):
            if "-->" not in stripped:
                in_comment = True
            continue
        if str.startswith(stripped, ("```", "~~~")):
            marker = stripped[:3]
            if not fenced:
                fenced = True
                fence_marker = marker
            elif marker == fence_marker:
                fenced = False
                fence_marker = ""
            continue
        if fenced or str.startswith(stripped, ">"):
            continue
        visible.append(line)
    return visible


def section_body(text: str, section: str) -> str | None:
    if type(section) is not str:
        raise EvidenceFailed("markdown section is not an exact string")
    lines = visible_markdown_lines(text)
    if lines is None:
        return None
    start: int | None = None
    for index, line in enumerate(lines):
        if str.strip(line) == section:
            start = index + 1
            break
    if start is None:
        return None
    body: list[str] = []
    for line in lines[start:]:
        if re.match(r"^\s*#{1,6}\s+\S", line):
            break
        body.append(line)
    return str.strip("\n".join(body))


def placeholder_body(text: str) -> bool:
    if type(text) is not str:
        raise EvidenceFailed("placeholder source is not an exact string")
    normalized = str.strip(
        str.casefold(" ".join(str.split(text))),
        " .:-",
    )
    if not normalized:
        return True
    placeholder_terms = {
        "tbd",
        "todo",
        "to do",
        "placeholder",
        "fixme",
        "none",
        "n/a",
        "na",
        "later",
        "coming soon",
        "fill this in",
        "to be defined",
        "as above",
        "done",
        "works",
        "passes tests",
    }
    return normalized in placeholder_terms


def independent_template_findings(
    issue: Mapping[str, Any],
) -> dict[str, str]:
    if type(issue) is not dict:
        raise EvidenceFailed("template finding source is not an exact object")
    raw_issue_type = dict.get(issue, "type") or dict.get(issue, "issue_type")
    raw_description = dict.get(issue, "description")
    if raw_issue_type is None:
        issue_type = ""
    elif type(raw_issue_type) is str:
        issue_type = raw_issue_type
    else:
        raise EvidenceFailed("template finding type is not an exact string")
    if raw_description is None:
        description = ""
    elif type(raw_description) is str:
        description = raw_description
    else:
        raise EvidenceFailed(
            "template finding description is not an exact string"
        )
    required = dict.get(REQUIRED_SECTIONS_BY_TYPE, issue_type, ())
    if visible_markdown_lines(description) is None:
        return {
            section: "semantic-field-cap-exceeded"
            for section in required
        }
    findings: dict[str, str] = {}
    for section in required:
        body = section_body(description, section)
        if body is None:
            findings[section] = "missing-literal-heading"
        elif placeholder_body(body):
            findings[section] = "empty-or-placeholder-body"
    return findings


def malformed_section_present(text: str, section: str) -> bool:
    if type(text) is not str or type(section) is not str:
        raise EvidenceFailed("section classifier inputs are not exact strings")
    visible = visible_markdown_lines(text)
    if visible is None:
        return False
    lowered_lines = [
        str.casefold(str.strip(line)) for line in visible
    ]
    canonical = str.casefold(section)
    if section == "## Acceptance Criteria":
        terms = ("acceptance criteria", "acceptance")
    elif section == "## Steps to Reproduce":
        terms = ("steps to reproduce", "repro")
    elif section == "## Success Criteria":
        terms = ("success criteria", "exit criteria")
    else:
        terms = ()
    for line in lowered_lines:
        if line == canonical:
            continue
        stripped = str.strip(str.lstrip(line, "#*-: "))
        for term in terms:
            if stripped == term or str.startswith(stripped, term + ":"):
                return True
    return False


def relevant_clauses(issue: Mapping[str, Any]) -> list[dict[str, str]]:
    if type(issue) is not dict:
        raise EvidenceFailed("clause source issue is not an exact object")
    rows: list[dict[str, str]] = []
    for field in ("description", "acceptance_criteria", "design", "notes"):
        raw_text = issue[field] if field in issue else None
        if raw_text is None:
            text = ""
        elif type(raw_text) is str:
            text = raw_text
        else:
            raise EvidenceFailed(
                f"clause source field {field} is not an exact string"
            )
        for line in str.splitlines(text):
            stripped = " ".join(str.split(line))
            if not stripped:
                continue
            lowered = str.casefold(stripped)
            if str.startswith(stripped, "#") or any(
                term in lowered for term in CLAUSE_TERMS
            ):
                encoded = str.encode(stripped, "utf-8")
                if len(encoded) > CAPS["clause_bytes"]:
                    encoded = encoded[: CAPS["clause_bytes"]]
                    stripped = bytes.decode(
                        encoded,
                        "utf-8",
                        errors="ignore",
                    ) + "…"
                rows.append({"field": field, "text": stripped})
                if len(rows) >= CAPS["clauses_per_issue"]:
                    return rows
    return rows


def obligation_mapping(issue: Mapping[str, Any]) -> dict[str, Any]:
    if type(issue) is not dict:
        raise EvidenceFailed("obligation source issue is not an exact object")
    issue = v2_released_json_snapshot(
        issue,
        label="obligation source issue",
        error_type=EvidenceFailed,
    )
    if type(issue) is not dict:
        raise EvidenceFailed("obligation source snapshot is not exact")
    text_fields: list[str] = []
    for field in ("description", "acceptance_criteria", "design", "notes"):
        raw_text = issue[field] if field in issue else None
        if raw_text is None:
            text_fields.append("")
        elif type(raw_text) is str:
            text_fields.append(raw_text)
        else:
            raise EvidenceFailed(
                f"obligation source field {field} is not an exact string"
            )
    text = "\n".join(text_fields)
    lowered = str.casefold(text)
    paths = sorted(set(re.findall(PATH_PATTERN, text)))[:64]
    return {
        "paths": paths,
        "unit_tests": "unit test" in lowered,
        "e2e": "e2e" in lowered or "end-to-end" in lowered,
        "logging": "log" in lowered or "jsonl" in lowered or "ndjson" in lowered,
        "replay": "replay" in lowered,
        "source_closure": "source closure" in lowered or "source-closure" in lowered,
        "authority": "authority" in lowered or "authoritative" in lowered,
        "no_claim": "no-claim" in lowered or "no claim" in lowered,
        "terminal": "terminal" in lowered or "close gate" in lowered,
    }


def strong_structured_acceptance(issue: Mapping[str, Any]) -> bool:
    if type(issue) is not dict:
        raise EvidenceFailed("acceptance source issue is not an exact object")
    raw_text = (
        issue["acceptance_criteria"]
        if "acceptance_criteria" in issue
        else None
    )
    if raw_text is None:
        text = ""
    elif type(raw_text) is str:
        if len(raw_text) > CAPS["semantic_field_bytes"]:
            return False
        text = str.strip(raw_text)
    else:
        raise EvidenceFailed("acceptance source field is not an exact string")
    if len(str.encode(text, "utf-8")) < 240:
        return False
    lowered = str.casefold(text)
    term_count = sum(term in lowered for term in CONTRACT_TERMS)
    structure_count = sum(
        1
        for line in str.splitlines(text)
        if re.match(r"^\s*(?:[-*]|\d+[.)])\s+", line)
        or str.startswith(str.strip(line), "##")
    )
    literal_specificity = bool(V2_PATH_PATTERN_SEARCH(text)) or bool(
        re.search(r"\b(?:P[0-4]|G[0-5]|NoData|Pass|Refused|[a-z]+-[a-z0-9.]+)\b", text)
    )
    return term_count >= 4 and structure_count >= 2 and literal_specificity


def existing_reproduction(issue: Mapping[str, Any]) -> bool:
    if type(issue) is not dict:
        raise EvidenceFailed("reproduction source issue is not an exact object")
    text_fields: list[str] = []
    for field in ("description", "acceptance_criteria", "notes"):
        raw_text = issue[field] if field in issue else None
        if raw_text is None:
            text_fields.append("")
        elif type(raw_text) is str:
            text_fields.append(raw_text)
        else:
            raise EvidenceFailed(
                f"reproduction source field {field} is not an exact string"
            )
    text = "\n".join(text_fields)
    lowered = str.casefold(text)
    has_repro = "repro" in lowered or "reproduce" in lowered
    has_observation = any(
        marker in lowered
        for marker in ("expected", "observed", "actual", "fails", "failure")
    )
    has_literal = (
        V2_PATH_PATTERN_SEARCH(text) is not None
        or "`" in text
        or "--" in text
    )
    return has_repro and has_observation and has_literal


def classify_issue(
    issue: Mapping[str, Any],
    missing_sections: Sequence[str],
    independent_findings: Mapping[str, str] | None = None,
    *,
    duplicate_acceptance: bool = False,
    section_only_reviewed: bool = False,
) -> tuple[str, str, str]:
    if type(issue) is not dict:
        raise EvidenceFailed("classification issue is not an exact object")
    if type(missing_sections) is not tuple:
        raise EvidenceFailed("classification sections are not an exact tuple")
    if (
        independent_findings is not None
        and type(independent_findings) is not dict
    ):
        raise EvidenceFailed(
            "classification independent findings are not exact"
        )
    if (
        type(duplicate_acceptance) is not bool
        or type(section_only_reviewed) is not bool
    ):
        raise EvidenceFailed("classification selectors are not exact")

    def optional_text(field: str) -> str:
        raw_value = dict.get(issue, field)
        if raw_value is None:
            return ""
        if type(raw_value) is not str:
            raise EvidenceFailed(
                f"classification field {field} is not an exact string"
            )
        return raw_value

    status = optional_text("status")
    issue_type = optional_text("type") or optional_text("issue_type")
    description = optional_text("description")
    acceptance = optional_text("acceptance_criteria")
    if any(type(section) is not str for section in missing_sections):
        raise EvidenceFailed("classification sections are not exact strings")
    missing = tuple(sorted(missing_sections))
    findings = (
        {}
        if independent_findings is None
        else dict(independent_findings)
    )

    if status == "closed":
        return (
            "HISTORICAL_IMMUTABLE_REVIEW",
            "closed history is reviewed separately and is never rewritten as live proof",
            "falsified if a closed row is placed in an active apply shard",
        )

    if status == "deferred":
        return (
            "OWNER_REVIEW_REQUIRED",
            "deferred debt remains scheduled but cannot enter an active apply shard",
            "falsified by an explicit owner transition plus a review bound to the new root",
        )

    if "empty-or-placeholder-body" in dict.values(findings):
        return (
            "SUBSTANTIVE_SEMANTIC_OMISSION",
            "a required literal heading has an empty or explicit placeholder body",
            "falsified by issue-specific non-placeholder obligations under the heading",
        )

    if "semantic-field-cap-exceeded" in dict.values(findings):
        return (
            "OWNER_REVIEW_REQUIRED",
            "semantic field exceeds the bounded parser cap and cannot be auto-classified",
            "falsified by a bounded owner-reviewed projection bound to the frozen field root",
        )

    if "## Steps to Reproduce" in missing and issue_type != "bug":
        return (
            "MALFORMED_OR_WRONG_TYPE",
            "a non-bug issue is being asked for a bug reproduction section",
            "falsified if the issue type is bug at the frozen source identity",
        )

    raw_dependents = (
        issue["dependents"] if "dependents" in issue else None
    )
    if raw_dependents is None:
        raw_dependents = []
    if type(raw_dependents) is not list:
        raise EvidenceFailed("classification dependents are not exact")
    child_ids: list[str] = []
    for edge in raw_dependents:
        if type(edge) is not dict:
            raise EvidenceFailed("classification dependent is not exact")
        edge_type = dict.get(edge, "type")
        edge_id = dict.get(edge, "id")
        if edge_type == "parent-child":
            if type(edge_id) is not str or not edge_id:
                raise EvidenceFailed(
                    "classification child ID is not an exact string"
                )
            child_ids.append(edge_id)
    children = sorted(child_ids)
    rollup_text = f"{description}\n{acceptance}"
    lowered_rollup = str.casefold(rollup_text)
    mentions_child_contract = any(
        term in lowered_rollup
        for term in ("child", "children", "descendant", "rollup", "roll-up")
    )
    has_terminal_contract = any(
        term in lowered_rollup
        for term in ("close gate", "terminal", "done when", "completion gate")
    )
    if (
        issue_type == "epic"
        and any(
            section in missing
            for section in ("## Acceptance Criteria", "## Success Criteria")
        )
        and (
            (mentions_child_contract and not children)
            or (
                bool(children)
                and (
                    not all(child in rollup_text for child in children)
                    or not has_terminal_contract
                )
            )
        )
    ):
        return (
            "ROLLUP_CHILD_SET_GAP",
            "rollup direct-child edges, exact membership text, or terminal gate are incomplete",
            "falsified by exact direct-child edges and text plus one compatible close gate",
        )

    if (
        missing == ("## Acceptance Criteria",)
        and strong_structured_acceptance(issue)
        and not duplicate_acceptance
        and section_only_reviewed
    ):
        return (
            "SECTION_NAME_ONLY",
            "complete issue-specific criteria already exist in the structured field",
            "falsified if semantic review finds a missing obligation beyond navigation",
        )

    if (
        missing == ("## Steps to Reproduce",)
        and existing_reproduction(issue)
        and section_only_reviewed
    ):
        return (
            "SECTION_NAME_ONLY",
            "issue-specific reproduction, expected result, and observed failure already exist",
            "falsified if the existing reproduction cannot reach the named failure",
        )

    if (
        "## Acceptance Criteria" in missing
        and len(str.encode(str.strip(acceptance), "utf-8")) < 120
    ):
        return (
            "SUBSTANTIVE_SEMANTIC_OMISSION",
            "no sufficiently specific structured completion contract exists",
            "falsified by locating a complete issue-specific contract in a frozen field",
        )

    if "## Steps to Reproduce" in missing and not existing_reproduction(issue):
        return (
            "SUBSTANTIVE_SEMANTIC_OMISSION",
            "the bug lacks a reachable expected-versus-observed reproduction",
            "falsified by a frozen no-mock reproduction with a named failure",
        )

    if any(malformed_section_present(description, section) for section in missing):
        return (
            "MALFORMED_OR_WRONG_TYPE",
            "complete section-like prose may exist under a malformed heading and needs typed review",
            "falsified if semantic review finds any missing obligation beyond the heading",
        )

    if (
        dict.get(issue, "assignee")
        or dict.get(issue, "owner")
        or status == "in_progress"
    ):
        return (
            "OWNER_REVIEW_REQUIRED",
            "substantive prose exists but the active owner must adjudicate completeness",
            "falsified by owner-reviewed exact criteria or a typed omission finding",
        )

    return (
        "OWNER_REVIEW_REQUIRED",
        "the frozen fields are ambiguous and no safe automatic repair is authorized",
        "falsified by independent semantic review assigning another exact disposition",
    )


def v2_validate_inventory_issue_row(
    issue: Any,
    *,
    index: int,
) -> None:
    """Validate every field consumed by the v1 inventory assembler."""
    if type(index) is not int or index < 0:
        raise EvidenceFailed("inventory issue row index is invalid")
    if type(issue) is not dict:
        raise EvidenceFailed(
            f"inventory issue row {index} is not an exact object"
        )
    field_count = dict.__len__(issue)
    if field_count > V2_ASSERTION_EVIDENCE_ITEM_CAP:
        raise EvidenceFailed(
            f"inventory issue row {index} exceeds its schema-key cap"
        )
    fields = tuple(dict.__iter__(issue))
    if (
        len(fields) != field_count
        or any(type(field) is not str for field in fields)
    ):
        raise EvidenceFailed(
            f"inventory issue row {index} has a non-string schema key"
        )
    schema = frozenset(fields)
    if (
        schema != V1_INVENTORY_ISSUE_REQUIRED_FIELDS
        and schema != V1_INVENTORY_ISSUE_PROJECTED_FIELDS
        and schema != V2_SOURCE_ALL_ISSUE_FIELDS
    ):
        raise EvidenceFailed(
            f"inventory issue row {index} has an unsupported closed schema"
        )

    issue_id = dict.__getitem__(issue, "id")
    title = dict.__getitem__(issue, "title")
    issue_type = dict.__getitem__(issue, "type")
    status = dict.__getitem__(issue, "status")
    priority = dict.__getitem__(issue, "priority")
    if (
        type(issue_id) is not str
        or not issue_id
        or type(title) is not str
        or not str.strip(title)
        or type(issue_type) is not str
        or not issue_type
        or type(status) is not str
        or type(priority) is not int
        or priority not in range(5)
    ):
        raise EvidenceFailed(
            f"inventory issue row {index} has invalid core scalars"
        )
    v2_validate_issue_id(
        issue_id,
        label=f"inventory issue row {index} ID",
        error_type=EvidenceFailed,
    )
    validated_status = v2_validate_status(
        status,
        label=f"inventory issue row {index} status",
        error_type=EvidenceFailed,
    )
    if validated_status != status:
        raise EvidenceFailed(
            f"inventory issue row {index} status is noncanonical"
        )

    for field in (
        "assignee",
        "owner",
        "parent",
        "description",
        "acceptance_criteria",
        "design",
        "notes",
        "updated_at",
    ):
        value = dict.__getitem__(issue, field)
        if (
            type(value) is not str
            or len(value) > CAPS["field_bytes"]
            or len(str.encode(value, "utf-8")) > CAPS["field_bytes"]
        ):
            raise EvidenceFailed(
                f"inventory issue row {index} has invalid {field}"
            )
    parent = dict.__getitem__(issue, "parent")
    if parent:
        v2_validate_issue_id(
            parent,
            label=f"inventory issue row {index} parent ID",
            error_type=EvidenceFailed,
        )
    estimate = dict.__getitem__(issue, "estimated_minutes")
    if estimate is not None and (
        type(estimate) is not int or estimate < 0
    ):
        raise EvidenceFailed(
            f"inventory issue row {index} has invalid estimated minutes"
        )

    labels = dict.__getitem__(issue, "labels")
    if (
        type(labels) is not list
        or list.__len__(labels) > V2_LABELS_PER_ISSUE_CAP
    ):
        raise EvidenceFailed(
            f"inventory issue row {index} has invalid labels"
        )
    label_snapshot = tuple(list.__iter__(labels))
    if (
        len(label_snapshot) != list.__len__(labels)
        or any(type(label) is not str or not label for label in label_snapshot)
        or len(label_snapshot) != len(set(label_snapshot))
    ):
        raise EvidenceFailed(
            f"inventory issue row {index} has invalid labels"
        )

    for relation_field in ("dependencies", "dependents"):
        relations = dict.__getitem__(issue, relation_field)
        if (
            type(relations) is not list
            or list.__len__(relations) > V2_RELATIONS_PER_DIRECTION_CAP
        ):
            raise EvidenceFailed(
                f"inventory issue row {index} has invalid {relation_field}"
            )
        relation_identities: dict[tuple[str, str], None] = {}
        for relation_index, relation in enumerate(
            tuple(list.__iter__(relations))
        ):
            if type(relation) is not dict:
                raise EvidenceFailed(
                    f"inventory issue row {index} has a non-object "
                    f"{relation_field} row {relation_index}"
                )
            relation_fields = frozenset(dict.__iter__(relation))
            if (
                relation_fields != V1_INVENTORY_RELATION_FIELDS
                and relation_fields != V2_SOURCE_RELATION_FIELDS
            ):
                raise EvidenceFailed(
                    f"inventory issue row {index} has an unsupported "
                    f"{relation_field} schema at row {relation_index}"
                )
            relation_id = dict.__getitem__(relation, "id")
            relation_type = dict.__getitem__(relation, "type")
            relation_status = dict.__getitem__(relation, "status")
            relation_priority = dict.__getitem__(relation, "priority")
            if (
                type(relation_id) is not str
                or not relation_id
                or relation_id == issue_id
                or (
                    str.startswith(relation_id, "external:")
                    and (
                        relation_id == "external:"
                        or (
                            relation_field == "dependencies"
                            and relation_type == "parent-child"
                        )
                        or (
                            relation_field == "dependents"
                            and relation_type != "parent-child"
                        )
                    )
                )
                or type(relation_type) is not str
                or not relation_type
                or type(relation_status) is not str
                or type(relation_priority) is not int
                or relation_priority not in range(5)
                or (
                    "title" in relation_fields
                    and (
                        type(dict.__getitem__(relation, "title")) is not str
                        or not str.strip(
                            dict.__getitem__(relation, "title")
                        )
                    )
                )
            ):
                raise EvidenceFailed(
                    f"inventory issue row {index} has invalid "
                    f"{relation_field} row {relation_index}"
                )
            v2_validate_status(
                relation_status,
                label=(
                    f"inventory issue row {index} {relation_field} "
                    f"row {relation_index} status"
                ),
                error_type=EvidenceFailed,
            )
            relation_label = (
                f"inventory issue row {index} {relation_field} "
                f"row {relation_index} ID"
            )
            if str.startswith(relation_id, "external:"):
                v2_validate_external_relation_id(
                    relation_id,
                    label=relation_label,
                    error_type=EvidenceFailed,
                )
            else:
                v2_validate_issue_id(
                    relation_id,
                    label=relation_label,
                    error_type=EvidenceFailed,
                )
            relation_identity = (relation_type, relation_id)
            if relation_identity in relation_identities:
                raise EvidenceFailed(
                    f"inventory issue row {index} duplicates a "
                    f"{relation_field} relation"
                )
            relation_identities[relation_identity] = None


def v2_validate_inventory_source(source: Any) -> None:
    """Validate source identity fields embedded into a v1 inventory."""
    source = v2_validate_exact_json_wire(
        source,
        label="inventory source input",
    )
    if type(source) is not dict:
        raise EvidenceFailed("inventory source is not an exact object")
    required_fields = {
        "schema",
        "br_version",
        "case_manifest_root",
        "semantic_root",
    }
    source_fields = tuple(dict.__iter__(source))
    if (
        dict.__len__(source) > V2_ASSERTION_EVIDENCE_ITEM_CAP
        or any(type(field) is not str for field in source_fields)
        or not required_fields.issubset(source_fields)
    ):
        raise EvidenceFailed("inventory source lacks required exact fields")
    schema = dict.__getitem__(source, "schema")
    case_manifest_root = dict.__getitem__(source, "case_manifest_root")
    source_root = dict.__getitem__(source, "semantic_root")
    br_version_value = dict.__getitem__(source, "br_version")
    if (
        type(schema) is not str
        or schema not in {SOURCE_SCHEMA, V2_SOURCE_SCHEMA}
        or type(case_manifest_root) is not str
        or not case_manifest_root
        or type(source_root) is not str
        or re.fullmatch(r"sha256-v1:[0-9a-f]{64}", source_root) is None
        or (
            type(br_version_value) is not str
            and type(br_version_value) is not dict
        )
        or (
            type(br_version_value) is str
            and (
                not br_version_value
                or len(br_version_value) > V2_BR_SEMVER_BYTES_CAP
                or len(str.encode(br_version_value, "utf-8"))
                > V2_BR_SEMVER_BYTES_CAP
            )
        )
        or (
            type(br_version_value) is dict
            and dict.__len__(br_version_value) == 0
        )
    ):
        raise EvidenceFailed("inventory source identity fields are invalid")
    if type(br_version_value) is str and schema != SOURCE_SCHEMA:
        raise EvidenceFailed(
            "only the legacy v1 inventory source may use a string br version"
        )
    if type(br_version_value) is dict:
        normalized_br_version = v2_normalize_br_version(
            br_version_value,
            error_type=EvidenceFailed,
        )
        if normalized_br_version != br_version_value:
            raise EvidenceFailed(
                "inventory source br version is not canonically normalized"
            )
    verify_semantic_root(source, label="inventory source")


def lint_result_map(lint: Mapping[str, Any]) -> dict[str, tuple[str, ...]]:
    lint = v2_validate_exact_json_wire(
        lint,
        label="lint result-map input",
    )
    if type(lint) is not dict:
        raise EvidenceFailed("lint result-map input is not an exact object")
    v2_validate_lint_scope_coherence(
        lint,
        full_issues=None,
        error_type=EvidenceFailed,
    )
    all_scope = dict.__getitem__(lint, "all")
    if type(all_scope) is not dict:
        raise EvidenceFailed("lint all scope is not an exact object")
    result_rows = dict.__getitem__(all_scope, "results")
    if type(result_rows) is not list:
        raise EvidenceFailed("lint all results are not an exact array")
    result: dict[str, tuple[str, ...]] = {}
    for row in result_rows:
        if type(row) is not dict:
            raise EvidenceFailed("lint all row is not an exact object")
        issue_id = dict.__getitem__(row, "id")
        issue_type = dict.__getitem__(row, "type")
        missing = dict.__getitem__(row, "missing")
        if (
            type(issue_id) is not str
            or not issue_id
            or type(issue_type) is not str
            or not issue_type
            or type(missing) is not list
        ):
            raise EvidenceFailed("lint all row has invalid exact fields")
        raw_sections = tuple(list.__iter__(missing))
        if any(type(section) is not str for section in raw_sections):
            raise EvidenceFailed("lint all missing section is not exact")
        if len(raw_sections) != len(set(raw_sections)):
            raise EvidenceFailed(
                f"lint all duplicates a section for {issue_id}"
            )
        sections = v2_canonical_missing_sections(
            issue_type,
            raw_sections,
        )
        if not sections:
            raise InfrastructureFailed("lint result contains an empty ID or missing set")
        if any(section not in SECTION_CODES for section in sections):
            raise EvidenceFailed(f"lint all contains an unknown section for {issue_id}")
        if issue_id in result:
            raise EvidenceFailed(f"lint all contains duplicate issue {issue_id}")
        result[issue_id] = sections
    return result


def validate_scope_partitions(lint: Mapping[str, Any]) -> None:
    v2_validate_lint_scope_coherence(
        lint,
        full_issues=None,
        error_type=EvidenceFailed,
    )


def assemble_inventory(
    lint: Mapping[str, Any],
    issue_rows: Sequence[Mapping[str, Any]],
    source: Mapping[str, Any],
    independent_findings_by_id: Mapping[str, Mapping[str, str]] | None = None,
    *,
    include_issue_rows_without_findings: bool = False,
) -> dict[str, Any]:
    if type(lint) is not dict:
        raise EvidenceFailed("lint inventory input is not an exact object")
    if type(issue_rows) is not list:
        raise EvidenceFailed("show issue rows are not an exact sequence")
    if type(source) is not dict:
        raise EvidenceFailed("inventory source is not an exact object")
    if (
        independent_findings_by_id is not None
        and type(independent_findings_by_id) is not dict
    ):
        raise EvidenceFailed("independent findings are not an exact object")
    if type(include_issue_rows_without_findings) is not bool:
        raise EvidenceFailed("inventory inclusion selector is not exact")
    if list.__len__(issue_rows) > CAPS["issues"]:
        raise EvidenceFailed("show issue rows exceed their application cap")
    if dict.__len__(lint) > CAPS["issues"] + 1:
        raise EvidenceFailed("lint scopes exceed their application cap")
    if (
        independent_findings_by_id is not None
        and dict.__len__(independent_findings_by_id) > CAPS["issues"]
    ):
        raise EvidenceFailed(
            "independent findings exceed their application cap"
        )
    detached_inputs = v2_validate_exact_json_wire(
        {
            "lint": lint,
            "issue_rows": issue_rows,
            "source": source,
            "independent_findings_by_id": independent_findings_by_id,
        },
        label="inventory assembler inputs",
    )
    if type(detached_inputs) is not dict:
        raise EvidenceFailed("inventory input snapshot is not an exact object")
    lint = dict.__getitem__(detached_inputs, "lint")
    issue_rows = dict.__getitem__(detached_inputs, "issue_rows")
    source = dict.__getitem__(detached_inputs, "source")
    independent_findings_by_id = dict.__getitem__(
        detached_inputs,
        "independent_findings_by_id",
    )
    if (
        type(lint) is not dict
        or type(issue_rows) is not list
        or type(source) is not dict
        or (
            independent_findings_by_id is not None
            and type(independent_findings_by_id) is not dict
        )
    ):
        raise EvidenceFailed("inventory input snapshot has invalid exact types")
    if (
        list.__len__(issue_rows) > CAPS["issues"]
        or dict.__len__(lint) > CAPS["issues"] + 1
        or (
            independent_findings_by_id is not None
            and dict.__len__(independent_findings_by_id) > CAPS["issues"]
        )
    ):
        raise EvidenceFailed("inventory input snapshot exceeds application caps")
    for issue_index, issue in enumerate(issue_rows):
        v2_validate_inventory_issue_row(issue, index=issue_index)
    v2_validate_inventory_source(source)
    v2_validate_lint_scope_coherence(
        lint,
        full_issues=issue_rows,
        error_type=EvidenceFailed,
    )
    non_all_status_scopes: list[str] = []
    for scope in lint:
        if scope != "all":
            non_all_status_scopes.append(scope)
    status_scopes = v2_canonical_status_scopes(non_all_status_scopes)
    br_missing_by_id = lint_result_map(lint)
    if type(br_missing_by_id) is not dict:
        raise EvidenceFailed("lint result map is not an exact object")
    independent: dict[str, dict[str, str]] = {}
    raw_independent_findings = (
        {} if independent_findings_by_id is None else independent_findings_by_id
    )
    if (
        type(raw_independent_findings) is not dict
        or dict.__len__(raw_independent_findings) > CAPS["issues"]
    ):
        raise EvidenceFailed("independent findings are not an exact object")
    for raw_issue_id, findings in dict.items(raw_independent_findings):
        if type(findings) is not dict:
            raise EvidenceFailed(
                "independent findings row is not an exact object"
            )
        if type(raw_issue_id) is not str:
            raise EvidenceFailed(
                "independent findings issue ID is not an exact string"
            )
        v2_validate_issue_id(
            raw_issue_id,
            label="independent findings issue ID",
            error_type=EvidenceFailed,
        )
        if dict.__len__(findings) > FIXTURE_MAX_WARNINGS_PER_ISSUE:
            raise EvidenceFailed(
                f"independent findings for {raw_issue_id} exceed their cap"
            )
        if dict.__len__(findings) == 0:
            continue
        normalized_findings: dict[str, str] = {}
        for section, reason in dict.items(findings):
            if (
                type(section) is not str
                or section not in SECTION_CODES
                or type(reason) is not str
                or not reason
                or len(reason) > CAPS["semantic_field_bytes"]
                or len(str.encode(reason, "utf-8"))
                > CAPS["semantic_field_bytes"]
            ):
                raise EvidenceFailed(
                    "independent finding is not exact string data"
                )
            normalized_findings[section] = reason
        independent[raw_issue_id] = normalized_findings
    finding_ids = set(br_missing_by_id) | set(independent)
    selected_ids = set(finding_ids)
    if include_issue_rows_without_findings:
        selected_ids = selected_ids | {
            issue["id"] for issue in issue_rows
        }
    missing_by_id: dict[str, tuple[str, ...]] = {}
    for issue_id in sorted(selected_ids):
        br_missing_sections = set(
            dict.get(br_missing_by_id, issue_id, ())
        )
        independent_missing_sections = set(
            dict.get(independent, issue_id, ())
        )
        combined_missing_sections = (
            br_missing_sections | independent_missing_sections
        )
        missing_by_id[issue_id] = tuple(
            sorted(combined_missing_sections)
        )
    issue_map: dict[str, dict[str, Any]] = {}
    for issue in issue_rows:
        issue_map[issue["id"]] = issue
    if len(issue_map) != len(issue_rows):
        raise EvidenceFailed("show issue set contains duplicate IDs")
    if set(issue_map) != set(missing_by_id):
        raise EvidenceFailed(
            "show issue set differs from the combined br and independent issue set"
        )
    acceptance_counts: dict[str, int] = {}
    for issue in issue_rows:
        raw_acceptance_text = dict.get(issue, "acceptance_criteria")
        if raw_acceptance_text is None:
            acceptance_text = ""
        elif type(raw_acceptance_text) is str:
            acceptance_text = str.strip(raw_acceptance_text)
        else:
            raise EvidenceFailed(
                "show issue acceptance criteria is not an exact string"
            )
        if acceptance_text:
            acceptance_root = text_root(acceptance_text)
            acceptance_counts[acceptance_root] = (
                dict.get(acceptance_counts, acceptance_root, 0) + 1
            )
    lint_status_by_id: dict[str, str] = {}
    for status in status_scopes:
        for lint_row in lint[status]["results"]:
            if type(lint_row) is not dict:
                raise EvidenceFailed("lint result row is not an exact object")
            issue_id = str(dict.get(lint_row, "id", ""))
            lint_status_by_id[issue_id] = status
    for issue_id, expected_status in lint_status_by_id.items():
        if issue_map[issue_id]["status"] != expected_status:
            raise EvidenceFailed(
                f"{issue_id} show status disagrees with lint cut {expected_status}"
            )

    rows: list[dict[str, Any]] = []
    warning_rows: list[dict[str, Any]] = []
    for issue_id in sorted(missing_by_id):
        issue = issue_map[issue_id]
        missing = missing_by_id[issue_id]
        finding_reasons = dict.get(independent, issue_id, {})
        raw_acceptance_text = dict.get(issue, "acceptance_criteria")
        if raw_acceptance_text is None:
            acceptance_text = ""
        elif type(raw_acceptance_text) is str:
            acceptance_text = str.strip(raw_acceptance_text)
        else:
            raise EvidenceFailed(
                "show issue acceptance criteria is not an exact string"
            )
        duplicate_acceptance = bool(acceptance_text) and (
            acceptance_counts[text_root(acceptance_text)] > 1
        )
        if missing:
            disposition, rationale, falsifier = classify_issue(
                issue,
                missing,
                finding_reasons,
                duplicate_acceptance=duplicate_acceptance,
            )
        elif include_issue_rows_without_findings:
            disposition = "OWNER_REVIEW_REQUIRED"
            rationale = (
                "absence of a template-lint warning is not a semantic review "
                "receipt; user value, graph position, priority, estimate, "
                "ownership, authority, tests, E2E, logging, replay, and source "
                "closure remain to be reviewed against the exact target root"
            )
            falsifier = (
                "a root-bound independent semantic-review receipt assigns "
                "REVIEWED_NO_CHANGE, ROLLUP_ONLY, CONTRIBUTION_ONLY, "
                "TYPED_INAPPLICABLE, BLOCKED_AUTHORITY, or a concrete "
                "REMEDIATION_REQUIRED finding"
            )
        else:
            raise EvidenceFailed(
                f"{issue_id} has no warning or independent finding"
            )
        if disposition not in DISPOSITIONS:
            raise EvidenceFailed(f"unknown disposition for {issue_id}")
        fields: dict[str, str] = {}
        for field in (
            "description",
            "acceptance_criteria",
            "design",
            "notes",
        ):
            raw_field_text = dict.get(issue, field)
            if raw_field_text is None:
                field_text = ""
            elif type(raw_field_text) is str:
                field_text = raw_field_text
            else:
                raise EvidenceFailed(
                    f"show issue field {field} is not an exact string"
                )
            fields[field] = text_root(field_text)
        domain_labels: list[str] = []
        for label in dict.get(issue, "labels", []):
            if type(label) is not str:
                raise EvidenceFailed("show issue label is not an exact string")
            if str.startswith(label,
                ("crate:", "area:", "layer:", "authority:")
            ):
                domain_labels.append(label)
        mapping = obligation_mapping(issue)
        if type(mapping) is not dict:
            raise EvidenceFailed("obligation mapping is not an exact object")
        row = {
            "id": issue_id,
            "title": issue["title"],
            "type": issue["type"],
            "status": issue["status"],
            "priority": issue["priority"],
            "assignee": issue["assignee"],
            "owner": issue["owner"],
            "parent": issue["parent"],
            "authority_domain": (
                sorted(domain_labels)[0]
                if domain_labels
                else (issue["parent"] or issue["type"] or "unclassified")
            ),
            "implementation_owner": (
                issue["assignee"] or issue["owner"] or "UNASSIGNED"
            ),
            "evidence_owner": "UNRESOLVED",
            "terminal_owner": "UNRESOLVED",
            "missing_sections": list(missing),
            "br_lint_missing_sections": list(
                dict.get(br_missing_by_id, issue_id, ())
            ),
            "independent_findings": dict(
                sorted(dict.items(finding_reasons))
            ),
            "semantic_flags": {
                "duplicate_structured_acceptance": duplicate_acceptance,
                "section_only_review_bound": False,
            },
            "lint_disagreement": (
                set(dict.get(br_missing_by_id, issue_id, ()))
                != set(finding_reasons)
            ),
            "overlap": len(missing) > 1,
            "disposition": disposition,
            "rationale": rationale,
            "falsifier": falsifier,
            "field_roots": fields,
            "relevant_clauses": relevant_clauses(issue),
            "dependencies": issue["dependencies"],
            "dependents": issue["dependents"],
            "mapping": mapping,
            "testing_obligation": {
                "unit_tests_named": mapping["unit_tests"],
                "e2e_named": mapping["e2e"],
            },
            "logging_obligation": mapping["logging"],
            "replay_obligation": mapping["replay"],
            "source_closure_obligation": mapping["source_closure"],
            "authority": "CLASSIFICATION_ONLY",
            "no_claim": (
                "this row schedules semantic review and does not authorize "
                "content mutation or completion"
            ),
            "estimated_minutes": issue["estimated_minutes"],
            "updated_at": issue["updated_at"],
        }
        if include_issue_rows_without_findings:
            review_disposition = v2_unreviewed_semantic_disposition(
                status=issue["status"],
                classification_disposition=disposition,
            )
            row["template_warning_state"] = (
                "PRESENT" if missing else "NONE"
            )
            row["semantic_review_disposition"] = review_disposition
            row["semantic_review_receipt_state"] = "UNREVIEWED"
            row["semantic_review_dimensions"] = (
                v2_unreviewed_semantic_dimensions()
            )
            row["semantic_review_receipt_root"] = None
            row["reviewed_no_change_receipt_root"] = None
        rows.append(row)
        for section in missing:
            warning_rows.append(
                {
                    "id": issue_id,
                    "section": section,
                    "status": issue["status"],
                    "priority": issue["priority"],
                    "type": issue["type"],
                    "disposition": disposition,
                }
            )

    if len(rows) > CAPS["issues"] or len(warning_rows) > CAPS["warnings"]:
        raise EvidenceFailed("assembled inventory exceeds declared caps")

    section_counts = Counter(
        dict.__getitem__(warning_row, "section")
        for warning_row in warning_rows
    )
    status_counts = Counter(
        dict.__getitem__(row, "status") for row in rows
    )
    priority_counts = Counter(
        f"P{dict.__getitem__(row, 'priority')}" for row in rows
    )
    type_counts = Counter(
        dict.__getitem__(row, "type") for row in rows
    )
    disposition_counts = Counter(
        dict.__getitem__(row, "disposition") for row in rows
    )
    overlap_counts = Counter(
        (
            "NO_TEMPLATE_WARNING"
            if not dict.__getitem__(row, "missing_sections")
            else (
                "+".join(dict.__getitem__(row, "missing_sections"))
                if dict.__getitem__(row, "overlap")
                else dict.__getitem__(row, "missing_sections")[0]
            )
        )
        for row in rows
    )
    partition_keys = (
        (*PARTITION_KEYS, "NO_TEMPLATE_WARNING")
        if include_issue_rows_without_findings
        else PARTITION_KEYS
    )
    partition_by_issue_id: dict[str, str] = {}
    partition_name_by_codes = {
        ("A",): "A_only",
        ("S",): "S_only",
        ("C",): "C_only",
        ("A", "S"): "A_and_S_only",
        ("A", "C"): "A_and_C_only",
        ("S", "C"): "S_and_C_only",
        ("A", "S", "C"): "A_and_S_and_C",
    }
    for row in rows:
        missing_sections = row["missing_sections"]
        if (
            type(missing_sections) is not list
            or any(
                type(section) is not str
                or section not in SECTION_CODES
                for section in missing_sections
            )
        ):
            raise EvidenceFailed(
                "warning overlap contains an unknown missing section"
            )
        codes = tuple(
            code
            for section, code in (
                ("## Acceptance Criteria", "A"),
                ("## Steps to Reproduce", "S"),
                ("## Success Criteria", "C"),
            )
            if section in missing_sections
        )
        if type(codes) is not tuple:
            raise EvidenceFailed("warning overlap codes are not exact")
        partition_name = (
            "NO_TEMPLATE_WARNING"
            if len(codes) == 0 and include_issue_rows_without_findings
            else partition_name_by_codes.get(codes)
        )
        if partition_name is None:
            raise EvidenceFailed(f"unpartitioned warning overlap for {row['id']}")
        row_id = dict.__getitem__(row, "id")
        if type(row_id) is not str or row_id in partition_by_issue_id:
            raise EvidenceFailed(
                "warning overlap contains a duplicate or invalid issue ID"
            )
        partition_by_issue_id[row_id] = partition_name
    partitions = {
        key: [
            row_id
            for row_id in partition_by_issue_id
            if dict.__getitem__(partition_by_issue_id, row_id) == key
        ]
        for key in partition_keys
    }
    partition_lengths: list[int] = []
    for issue_ids in partitions.values():
        if type(issue_ids) is not list:
            raise EvidenceFailed(
                "exclusive partition contains a non-exact issue list"
            )
        partition_lengths.append(len(issue_ids))
    partition_union = sum(partition_lengths)
    if partition_union != len(rows):
        raise EvidenceFailed("exclusive partition arithmetic differs from issue union")
    rows_by_status = sorted(
        rows,
        key=lambda row: (
            dict.__getitem__(row, "status"),
            dict.__getitem__(row, "id"),
        ),
    )
    grouped_rows_by_status = {
        status: tuple(group)
        for status, group in groupby(
            rows_by_status,
            key=lambda row: dict.__getitem__(row, "status"),
        )
    }
    if any(
        status not in status_scopes
        for status in grouped_rows_by_status
    ):
        raise EvidenceFailed("assembled status membership differs")
    combined_status_cuts = {
        status: {
            "issues": len(status_rows),
            "warnings": sum(
                len(dict.__getitem__(row, "missing_sections"))
                for row in status_rows
            ),
            "issue_ids": [
                dict.__getitem__(row, "id") for row in status_rows
            ],
        }
        for status in status_scopes
        for status_rows in (
            dict.get(grouped_rows_by_status, status, ()),
        )
    }
    warning_count_by_id: dict[str, int] = {}
    for row in rows:
        warning_count_by_id[row["id"]] = len(row["missing_sections"])

    br_lint_warning_counts: list[int] = []
    for missing_sections in dict.values(br_missing_by_id):
        if type(missing_sections) is not tuple:
            raise EvidenceFailed(
                "lint result map contains a non-exact section tuple"
            )
        br_lint_warning_counts.append(len(missing_sections))
    br_lint_warning_count = sum(br_lint_warning_counts)
    independent_warning_counts: list[int] = []
    for findings in dict.values(independent):
        if type(findings) is not dict:
            raise EvidenceFailed(
                "independent findings map contains a non-exact row"
            )
        independent_warning_counts.append(len(findings))
    independent_warning_count = sum(independent_warning_counts)
    lint_disagreement_count = sum(
        1 for row in rows if row["lint_disagreement"] is True
    )

    status_cuts: dict[str, dict[str, Any]] = {}
    for scope in (*status_scopes, "all"):
        scope_issue_ids: list[str] = []
        for lint_row in lint[scope]["results"]:
            if type(lint_row) is not dict:
                raise EvidenceFailed("lint result row is not an exact object")
            scope_issue_ids.append(str(dict.get(lint_row, "id", "")))
        status_cuts[scope] = {
            "warnings": lint[scope]["total"],
            "issues": lint[scope]["issues"],
            "issue_ids": scope_issue_ids,
        }

    partition_documents: dict[str, dict[str, Any]] = {}
    for key in partition_keys:
        partition_warning_counts: list[int] = []
        for issue_id in partitions[key]:
            partition_warning_counts.append(warning_count_by_id[issue_id])
        partition_warning_count = sum(partition_warning_counts)
        partition_documents[key] = {
            "issue_ids": list(partitions[key]),
            "issues": len(partitions[key]),
            "warnings": partition_warning_count,
        }

    caps_snapshot = {
        key: dict.__getitem__(CAPS, key)
        for key in sorted(CAPS)
    }
    if any(type(value) is not int for value in dict.values(caps_snapshot)):
        raise EvidenceFailed("inventory caps snapshot contains a non-integer")
    inventory: dict[str, Any] = {
        "schema": INVENTORY_SCHEMA,
        "tool": {
            "br": source["br_version"],
            "rule": "br-lint-template-sections-v1",
            "classifier": "frankensim-semantic-disposition-v1",
            "case_manifest_root": source["case_manifest_root"],
        },
        "source": source,
        "caps": caps_snapshot,
        "counts": {
            "issues": len(rows),
            "warnings": len(warning_rows),
            "br_lint_issues": len(br_missing_by_id),
            "br_lint_warnings": br_lint_warning_count,
            "independent_issues": len(independent),
            "independent_warnings": independent_warning_count,
            "lint_disagreements": lint_disagreement_count,
            "by_section": dict(sorted(dict.items(section_counts))),
            "by_status": dict(sorted(dict.items(status_counts))),
            "by_priority": dict(sorted(dict.items(priority_counts))),
            "by_type": dict(sorted(dict.items(type_counts))),
            "by_disposition": dict(
                sorted(dict.items(disposition_counts))
            ),
            "overlap_partitions": dict(
                sorted(dict.items(overlap_counts))
            ),
        },
        "status_cuts": status_cuts,
        "combined_status_cuts": combined_status_cuts,
        "partitions": partition_documents,
        "rows": rows,
        "warning_rows": warning_rows,
        "no_claim": (
            "classification schedules semantic review; it does not authorize "
            "substantive text, close target Beads, or confer product authority"
        ),
    }
    if include_issue_rows_without_findings:
        template_warning_issue_ids: list[str] = []
        no_template_warning_issue_ids: list[str] = []
        unreviewed_semantic_receipt_issue_ids: list[str] = []
        review_scope_issue_ids: list[str] = []
        for row in rows:
            review_scope_issue_ids.append(row["id"])
            if row["missing_sections"]:
                template_warning_issue_ids.append(row["id"])
            else:
                no_template_warning_issue_ids.append(row["id"])
            if row["semantic_review_receipt_state"] == "UNREVIEWED":
                unreviewed_semantic_receipt_issue_ids.append(row["id"])
        template_warning_issue_count = len(template_warning_issue_ids)
        no_template_warning_issue_count = len(
            no_template_warning_issue_ids
        )
        unreviewed_semantic_receipt_count = len(
            unreviewed_semantic_receipt_issue_ids
        )
        inventory["counts"] = {
            **inventory["counts"],
                "complete_review_scope_issues": len(rows),
                "template_warning_issues": template_warning_issue_count,
                "no_template_warning_issues": (
                    no_template_warning_issue_count
                ),
                "unreviewed_semantic_receipts": (
                    unreviewed_semantic_receipt_count
                ),
        }
        inventory["review_scope"] = {
            "nonclosed_complete": True,
            "closed_rows": "WARNING_OR_INDEPENDENT_FINDING_ONLY",
            "issue_ids": review_scope_issue_ids,
            "issue_ids_root": semantic_root(review_scope_issue_ids),
            "allowed_semantic_review_dispositions": list(
                V2_SEMANTIC_REVIEW_DISPOSITIONS
            ),
            "reviewed_no_change_requires_root_bound_receipt": True,
            "no_claim": (
                "complete inventory membership is not completed semantic "
                "review and does not make unreviewed rows actionable"
            ),
        }
        inventory["no_claim"] = (
            "the inventory exact-covers every selected nonclosed row plus "
            "closed finding rows, but UNREVIEWED is not REVIEWED_NO_CHANGE "
            "and no row is authorized for mutation or closure"
        )
    inventory["semantic_root"] = semantic_root(inventory)
    return inventory


def priority_group(priority: Any) -> str:
    if priority == 0:
        return "p0"
    if priority == 1:
        return "p1"
    if priority in (2, 3, 4):
        return "p2-p4"
    raise EvidenceFailed(f"priority {priority!r} is outside P0-P4")


def proposal_for_row(
    inventory_row: Mapping[str, Any],
    issue: Mapping[str, Any],
) -> dict[str, Any] | None:
    if inventory_row["disposition"] != "SECTION_NAME_ONLY":
        return None
    missing = tuple(inventory_row["missing_sections"])
    old = str(issue.get("description") or "")
    if missing == ("## Acceptance Criteria",):
        criteria = str(issue.get("acceptance_criteria") or "").strip()
        if not criteria:
            return None
        new = old.rstrip() + "\n\n## Acceptance Criteria\n\n" + criteria + "\n"
    elif missing == ("## Steps to Reproduce",):
        match = re.search(r"(?im)^(?P<prefix>\s*(?:REPRO|Reproduction)\s*:)", old)
        if not match:
            return None
        new = old[: match.start()] + "## Steps to Reproduce\n\n" + old[match.start() :]
    else:
        return None
    return {
        "id": inventory_row["id"],
        "disposition": "SECTION_NAME_ONLY",
        "field": "description",
        "missing_section": missing[0],
        "old_root": text_root(old),
        "new_root": text_root(new),
        "old_value": old,
        "new_value": new,
        "inverse_value": old,
        "reviewed": False,
        "rationale": inventory_row["rationale"],
    }


def build_plan(
    inventory: Mapping[str, Any],
    issue_rows: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    issues = {str(row["id"]): row for row in issue_rows}
    status_order = {
        status: index
        for index, status in enumerate(
            v2_canonical_status_scopes(
                [row["status"] for row in inventory["rows"]]
            )
        )
    }
    groups: dict[
        tuple[int, str, int, str, str, str, str],
        list[Mapping[str, Any]],
    ] = {}
    for row in inventory["rows"]:
        if row["status"] == "closed":
            continue
        owner = row["assignee"] or row["owner"] or "unassigned"
        key = (
            int(row["priority"]),
            priority_group(row["priority"]),
            status_order[row["status"]],
            row["status"],
            owner,
            row["authority_domain"],
            row["disposition"],
        )
        if key not in groups:
            groups[key] = []
        list.append(groups[key], row)

    shards: list[dict[str, Any]] = []
    sequence = 0
    for key in sorted(groups):
        rows = sorted(groups[key], key=lambda row: row["id"])
        for offset in range(0, len(rows), CAPS["plan_shard_rows"]):
            sequence += 1
            batch = rows[offset : offset + CAPS["plan_shard_rows"]]
            shards.append(
                {
                    "sequence": sequence,
                    "priority": key[0],
                    "priority_group": key[1],
                    "status": key[3],
                    "owner": key[4],
                    "authority_domain": key[5],
                    "disposition": key[6],
                    "issue_ids": [row["id"] for row in batch],
                    "warning_count": sum(len(row["missing_sections"]) for row in batch),
                    "max_issues": CAPS["plan_shard_rows"],
                    "requires_owner_review": key[6] != "SECTION_NAME_ONLY",
                }
            )

    scheduled_ids = sorted(
        row["id"] for row in inventory["rows"] if row["status"] != "closed"
    )
    shard_ids = [issue_id for shard in shards for issue_id in shard["issue_ids"]]
    if len(shard_ids) != len(set(shard_ids)):
        raise EvidenceFailed("plan contains duplicate shard membership")
    if sorted(shard_ids) != scheduled_ids:
        raise EvidenceFailed("plan does not exact-cover every non-closed inventory row")
    inventory_by_id = {row["id"]: row for row in inventory["rows"]}
    for shard in shards:
        if len(shard["issue_ids"]) > CAPS["plan_shard_rows"]:
            raise EvidenceFailed("plan shard exceeds its target cap")
        for issue_id in shard["issue_ids"]:
            row = inventory_by_id[issue_id]
            if (
                row["priority"] != shard["priority"]
                or row["status"] != shard["status"]
                or (row["assignee"] or row["owner"] or "unassigned")
                != shard["owner"]
                or row["authority_domain"] != shard["authority_domain"]
                or row["disposition"] != shard["disposition"]
            ):
                raise EvidenceFailed(
                    f"plan shard crosses a partition boundary at {issue_id}"
                )

    proposals = [
        proposal
        for row in inventory["rows"]
        if (proposal := proposal_for_row(row, issues[row["id"]])) is not None
    ]
    plan: dict[str, Any] = {
        "schema": PLAN_SCHEMA,
        "inventory_root": inventory["semantic_root"],
        "shards": shards,
        "section_name_only_proposals": proposals,
        "apply_contract": {
            "schema": APPLY_SCHEMA,
            "max_rows": CAPS["apply_rows"],
            "requires_reviewed": True,
            "requires_reviewed_by": True,
            "requires_reservation_receipt": True,
            "mutator": "br update only",
            "rollback": "reverse br update after exact post-write root check",
        },
        "no_claim": (
            "this plan is a bounded review schedule; every substantive row remains "
            "unapplied until its owning remediation Bead is independently reviewed"
        ),
    }
    plan["semantic_root"] = semantic_root(plan)
    return plan


class LiveSnapshot:
    """Read-only public carrier without a generated dataclass constructor."""

    __slots__ = (
        "_lint",
        "_issues",
        "_source",
        "_inventory",
        "_plan",
        "_all_issues",
    )

    def __init__(
        self,
        lint: dict[str, Any],
        issues: list[dict[str, Any]],
        source: dict[str, Any],
        inventory: dict[str, Any],
        plan: dict[str, Any],
        all_issues: tuple[dict[str, Any], ...] = (),
    ) -> None:
        self._lint = lint
        self._issues = issues
        self._source = source
        self._inventory = inventory
        self._plan = plan
        self._all_issues = all_issues

    @property
    def lint(self) -> dict[str, Any]:
        return self._lint

    @property
    def issues(self) -> list[dict[str, Any]]:
        return self._issues

    @property
    def source(self) -> dict[str, Any]:
        return self._source

    @property
    def inventory(self) -> dict[str, Any]:
        return self._inventory

    @property
    def plan(self) -> dict[str, Any]:
        return self._plan

    @property
    def all_issues(self) -> tuple[dict[str, Any], ...]:
        return self._all_issues


class V2RetainedSnapshot:
    """Minimal reconstruction carrier with no generated or ambient hooks."""

    __slots__ = (
        "lint",
        "issues",
        "source",
        "inventory",
        "plan",
        "all_issues",
    )

    def __init__(
        self,
        *,
        lint: dict[str, Any],
        issues: list[dict[str, Any]],
        source: dict[str, Any],
        inventory: dict[str, Any],
        plan: dict[str, Any],
        all_issues: tuple[dict[str, Any], ...],
    ) -> None:
        self.lint = lint
        self.issues = issues
        self.source = source
        self.inventory = inventory
        self.plan = plan
        self.all_issues = all_issues


