def v2_validate_live_capture_round_class_contract() -> None:
    pinned_type = V2_LIVE_CAPTURE_ROUND_TYPE_CONTRACT
    if V2LiveCaptureRound is not pinned_type or type(pinned_type) is not type:
        raise EvidenceFailed("v2 live capture round type identity drifted")
    class_dictionary = v2_raw_type_dictionary(pinned_type)
    if (
        dict(class_dictionary).get(V2_INSTANCE_DICTIONARY_ATTRIBUTE)
        is not V2_LIVE_CAPTURE_ROUND_INSTANCE_DICT_DESCRIPTOR
        or V2_GETATTRIBUTE_ATTRIBUTE in class_dictionary
        or V2_GETATTR_ATTRIBUTE in class_dictionary
        or any(
            field_name in class_dictionary
            for field_name in V2_LIVE_CAPTURE_ROUND_FIELDS
        )
    ):
        raise EvidenceFailed("v2 live capture round descriptor layout drifted")


def v2_exact_live_capture_round(
    value: Any,
    *,
    label: str,
) -> dict[str, Any]:
    if type(label) is not str or not label:
        raise EvidenceFailed("v2 live capture round label is malformed")
    v2_validate_live_capture_round_class_contract()
    pinned_type = V2_LIVE_CAPTURE_ROUND_TYPE_CONTRACT
    if type(value) is not pinned_type:
        raise EvidenceFailed(f"{label} is not an exact live capture round")
    attributes = v2_exact_descriptor_read(
        V2_LIVE_CAPTURE_ROUND_INSTANCE_DICT_DESCRIPTOR,
        value,
        pinned_type,
        label=f"{label} instance dictionary",
    )
    if type(attributes) is not dict:
        raise EvidenceFailed(f"{label} has a non-closed field layout")
    try:
        attribute_snapshot = dict.copy(attributes)
    except RuntimeError as error:
        raise EvidenceFailed(
            f"{label} changed while being captured"
        ) from error
    attribute_keys = tuple(dict.__iter__(attribute_snapshot))
    if (
        tuple.__len__(attribute_keys) != len(V2_LIVE_CAPTURE_ROUND_FIELDS)
        or any(type(key) is not str for key in attribute_keys)
        or tuple(sorted(attribute_keys))
        != V2_LIVE_CAPTURE_ROUND_FIELD_ORDER
    ):
        raise EvidenceFailed(f"{label} has a non-closed field layout")
    ordinal = dict.__getitem__(attribute_snapshot, "ordinal")
    if type(ordinal) is not int:
        raise EvidenceFailed(f"{label} ordinal is not an exact integer")
    for field_name in V2_LIVE_CAPTURE_ROUND_TUPLE_FIELDS:
        field_value = dict.__getitem__(attribute_snapshot, field_name)
        if type(field_value) is not tuple:
            raise EvidenceFailed(
                f"{label} {field_name} is not an exact tuple"
            )
        field_cap = (
            V2_BUNDLE_FILES_CAP
            if field_name == "source_files"
            else (
                V2_LOG_EVENTS_CAP
                if field_name == "command_receipts"
                else V2_INVENTORY_ROWS_CAP
            )
        )
        if tuple.__len__(field_value) > field_cap:
            raise EvidenceFailed(
                f"{label} {field_name} exceeds its cap"
            )
    for field_name in V2_LIVE_CAPTURE_ROUND_DICT_FIELDS:
        if type(dict.__getitem__(attribute_snapshot, field_name)) is not dict:
            raise EvidenceFailed(
                f"{label} {field_name} is not an exact object"
            )
    original_references = tuple(
        dict.__getitem__(attribute_snapshot, field_name)
        for field_name in V2_LIVE_CAPTURE_ROUND_FIELD_ORDER
    )
    detached = v2_released_json_snapshot(
        {
            "ordinal": ordinal,
            "issue_ids": list(
                tuple.__iter__(
                    dict.__getitem__(attribute_snapshot, "issue_ids")
                )
            ),
            "listed_rows": list(
                tuple.__iter__(
                    dict.__getitem__(attribute_snapshot, "listed_rows")
                )
            ),
            "tombstone_rows": list(
                tuple.__iter__(
                    dict.__getitem__(attribute_snapshot, "tombstone_rows")
                )
            ),
            "full_issues": list(
                tuple.__iter__(
                    dict.__getitem__(attribute_snapshot, "full_issues")
                )
            ),
            "lint": dict.__getitem__(attribute_snapshot, "lint"),
            "tracker_status": dict.__getitem__(
                attribute_snapshot,
                "tracker_status",
            ),
            "tracker_ready_rows": list(
                tuple.__iter__(
                    dict.__getitem__(attribute_snapshot, "tracker_ready_rows")
                )
            ),
            "tracker_ready_issue_ids": list(
                tuple.__iter__(
                    dict.__getitem__(
                        attribute_snapshot,
                        "tracker_ready_issue_ids",
                    )
                )
            ),
            "sync_status": dict.__getitem__(attribute_snapshot, "sync_status"),
            "export_witness": dict.__getitem__(
                attribute_snapshot,
                "export_witness",
            ),
            "version": dict.__getitem__(attribute_snapshot, "version"),
            "capabilities": dict.__getitem__(
                attribute_snapshot,
                "capabilities",
            ),
            "source_files": list(
                tuple.__iter__(
                    dict.__getitem__(attribute_snapshot, "source_files")
                )
            ),
            "rule_contract": dict.__getitem__(
                attribute_snapshot,
                "rule_contract",
            ),
            "case_manifest_root": dict.__getitem__(
                attribute_snapshot,
                "case_manifest_root",
            ),
            "case_manifest_content_identity": dict.__getitem__(
                attribute_snapshot,
                "case_manifest_content_identity",
            ),
            "command_receipts": list(
                tuple.__iter__(
                    dict.__getitem__(attribute_snapshot, "command_receipts")
                )
            ),
            "capture_state": dict.__getitem__(
                attribute_snapshot,
                "capture_state",
            ),
        },
        label=f"{label} fields",
        error_type=EvidenceFailed,
    )
    final_attributes = v2_exact_descriptor_read(
        V2_LIVE_CAPTURE_ROUND_INSTANCE_DICT_DESCRIPTOR,
        value,
        pinned_type,
        label=f"{label} final instance dictionary",
    )
    try:
        final_fields = tuple(dict.__iter__(final_attributes))
        final_layout_stable = (
            tuple.__len__(final_fields)
            == len(V2_LIVE_CAPTURE_ROUND_FIELDS)
            and all(type(key) is str for key in final_fields)
            and tuple(sorted(final_fields))
            == V2_LIVE_CAPTURE_ROUND_FIELD_ORDER
        )
        references_stable = not any(
            dict.__getitem__(final_attributes, field_name) is not original
            for field_name, original in zip(
                V2_LIVE_CAPTURE_ROUND_FIELD_ORDER,
                original_references,
                strict=True,
            )
        )
    except (KeyError, RuntimeError) as error:
        raise EvidenceFailed(
            f"{label} changed while being captured"
        ) from error
    if (
        final_attributes is not attributes
        or type(final_attributes) is not dict
        or not final_layout_stable
        or not references_stable
    ):
        raise EvidenceFailed(f"{label} changed while being captured")
    if type(detached) is not dict:
        raise EvidenceFailed(f"{label} field snapshot is malformed")
    full_issues = dict.__getitem__(detached, "full_issues")
    lint = dict.__getitem__(detached, "lint")
    try:
        for issue_index, issue in enumerate(list.__iter__(full_issues)):
            v2_validate_source_full_issue(issue, index=issue_index)
        v2_validate_lint_scope_coherence(
            lint,
            full_issues=full_issues,
            error_type=EvidenceFailed,
        )
    except HarnessError as error:
        raise EvidenceFailed(
            f"{label} full-issue or lint evidence is malformed"
        ) from error
    expected_capture_state = v2_capture_state(
        issue_ids=dict.__getitem__(detached, "issue_ids"),
        full_issues=full_issues,
        lint=lint,
        tracker_status=dict.__getitem__(detached, "tracker_status"),
        tracker_ready_issue_ids=dict.__getitem__(
            detached,
            "tracker_ready_issue_ids",
        ),
        sync_status=dict.__getitem__(detached, "sync_status"),
        export_witness=dict.__getitem__(detached, "export_witness"),
        version=dict.__getitem__(detached, "version"),
        capabilities=dict.__getitem__(detached, "capabilities"),
        source_files=dict.__getitem__(detached, "source_files"),
        rule_contract=dict.__getitem__(detached, "rule_contract"),
        case_manifest_root=dict.__getitem__(
            detached,
            "case_manifest_root",
        ),
        case_manifest_content_identity=dict.__getitem__(
            detached,
            "case_manifest_content_identity",
        ),
        listed_rows=dict.__getitem__(detached, "listed_rows"),
        tombstone_rows=dict.__getitem__(detached, "tombstone_rows"),
        tracker_ready_rows=dict.__getitem__(detached, "tracker_ready_rows"),
    )
    if dict.__getitem__(detached, "capture_state") != expected_capture_state:
        raise EvidenceFailed(f"{label} capture state is not field-bound")
    return detached
