def v2_br_exact_mapping(
    value: Any,
    fields: frozenset[str],
    *,
    label: str,
    error_type: type[HarnessError],
) -> dict[str, Any]:
    if (
        error_type is not InputRefused
        and error_type is not InfrastructureFailed
        and error_type is not EvidenceFailed
    ):
        raise EvidenceFailed(
            "br exact-mapping error type is not an allowed terminal"
        )
    if (
        type(fields) is not frozenset
        or not fields
        or any(type(field) is not str or not field for field in fields)
        or type(label) is not str
        or not label
    ):
        raise EvidenceFailed("br exact-mapping contract is malformed")
    value = v2_released_json_snapshot(
        value,
        error_type=error_type,
        label=label,
    )
    actual_fields = (
        tuple(dict.__iter__(value))
        if type(value) is dict
        else ()
    )
    keys_are_exact = all(
        type(field) is str and bool(field) for field in actual_fields
    )
    actual = (
        frozenset(actual_fields)
        if keys_are_exact
        else frozenset()
    )
    if type(value) is not dict or not keys_are_exact or actual != fields:
        raise error_type(
            f"{label} has a non-closed schema; "
            f"missing={sorted(fields - actual)}, "
            f"extra={sorted(actual - fields)}, "
            f"exact_string_keys={keys_are_exact}"
        )
    return dict.copy(value)


def v2_br_nonnegative_int(
    value: Any,
    *,
    label: str,
    cap: int,
    error_type: type[HarnessError],
) -> int:
    if (
        error_type is not InputRefused
        and error_type is not InfrastructureFailed
        and error_type is not EvidenceFailed
    ):
        raise EvidenceFailed(
            "br bounded-integer error type is not an allowed terminal"
        )
    if (
        type(label) is not str
        or not label
        or type(cap) is not int
        or cap < 0
    ):
        raise EvidenceFailed("br bounded-integer contract is malformed")
    if type(value) is not int or value < 0 or value > cap:
        raise error_type(f"{label} is not an exact bounded nonnegative integer")
    return value


def v2_br_hash(
    value: Any,
    *,
    label: str,
    error_type: type[HarnessError],
) -> str:
    if (
        error_type is not InputRefused
        and error_type is not InfrastructureFailed
        and error_type is not EvidenceFailed
    ):
        raise EvidenceFailed("br hash error type is not an allowed terminal")
    if type(label) is not str or not label:
        raise EvidenceFailed("br hash label is malformed")
    if type(value) is not str or V2_BR_HASH_FULLMATCH(
        r"[0-9a-f]{64}", value
    ) is None:
        raise error_type(f"{label} is not a canonical lowercase hash")
    return value


def v2_br_exact_json_list(
    value: Any,
    *,
    label: str,
    cap: int,
    error_type: type[HarnessError],
) -> list[Any]:
    """Detach one released JSON array and enforce its exact length bound."""
    if (
        error_type is not InputRefused
        and error_type is not InfrastructureFailed
        and error_type is not EvidenceFailed
    ):
        raise EvidenceFailed(
            "br exact-list error type is not an allowed terminal"
        )
    if (
        type(label) is not str
        or not label
        or type(cap) is not int
        or cap < 0
    ):
        raise EvidenceFailed("br exact-list contract is malformed")
    detached = v2_released_json_snapshot(
        value,
        error_type=error_type,
        label=label,
    )
    if type(detached) is not list or len(detached) > cap:
        raise error_type(f"{label} is malformed or over cap")
    return list(list.__iter__(detached))


def v2_br_status_identity_projection(
    status: Mapping[str, Any],
    *,
    error_type: type[HarnessError],
) -> dict[str, Any]:
    """Retain the complete normalized released-br status identity."""
    if type(status) is not dict:
        raise error_type("br status identity input is not an exact object")
    return dict(status)


def v2_normalize_br_status(
    document: Any,
    *,
    error_type: type[HarnessError],
) -> dict[str, Any]:
    outer = v2_br_exact_mapping(
        document,
        frozenset({"summary"}),
        label="br status",
        error_type=error_type,
    )
    raw_summary = outer["summary"]
    required_fields = V2_BR_STATUS_SUMMARY_FIELDS - frozenset({
        "average_lead_time_hours",
    })
    if type(raw_summary) is not dict:
        raise error_type("br status summary has a non-closed released schema")
    summary_fields = frozenset(dict.__iter__(raw_summary))
    if (
        not required_fields <= summary_fields
        or not summary_fields <= V2_BR_STATUS_SUMMARY_FIELDS
    ):
        raise error_type("br status summary has a non-closed released schema")
    for field in required_fields:
        v2_br_nonnegative_int(
            raw_summary[field],
            label=f"br status summary {field}",
            cap=V2_INVENTORY_ROWS_CAP,
            error_type=error_type,
        )
    lead_time = (
        raw_summary["average_lead_time_hours"]
        if "average_lead_time_hours" in raw_summary
        else None
    )
    if lead_time is not None and (
        type(lead_time) is not float
        or not math.isfinite(lead_time)
        or lead_time < 0
    ):
        raise error_type("br status average lead time is not a finite nonnegative float")
    total = raw_summary["total_issues"]
    for field in (
        "blocked_issues",
        "epics_eligible_for_closure",
        "pinned_issues",
        "ready_issues",
    ):
        if raw_summary[field] > total:
            raise error_type(f"br status summary {field} exceeds total issues")
    summary = {
        **raw_summary,
        "average_lead_time_hours": lead_time,
    }
    return {"summary": summary}


def v2_normalize_br_sync_status(
    document: Any,
    *,
    input_kind: str,
    error_type: type[HarnessError],
) -> dict[str, Any]:
    if input_kind not in {"released_live", "retained"}:
        raise error_type("br sync status input kind is unknown")
    optional_fields = {
        "jsonl_content_hash",
        "last_export_time",
        "last_import_time",
    }
    if type(document) is not dict:
        raise error_type("br sync status has a non-closed schema")
    document_fields = set(document)
    if input_kind == "released_live":
        valid_outer_schema = (
            (V2_BR_SYNC_FIELDS - optional_fields) <= document_fields
            and document_fields <= V2_BR_SYNC_FIELDS
        )
    else:
        valid_outer_schema = document_fields == V2_BR_SYNC_FIELDS
    if not valid_outer_schema:
        raise error_type("br sync status has a non-closed schema")
    normalized = {
        **document,
        "jsonl_content_hash": (
            document["jsonl_content_hash"]
            if "jsonl_content_hash" in document
            else None
        ),
        "last_export_time": (
            document["last_export_time"]
            if "last_export_time" in document
            else None
        ),
        "last_import_time": (
            document["last_import_time"]
            if "last_import_time" in document
            else None
        ),
    }
    for field in ("db_newer", "jsonl_exists", "jsonl_newer"):
        if type(normalized[field]) is not bool:
            raise error_type(f"br sync status {field} is not an exact boolean")
    v2_br_nonnegative_int(
        normalized["dirty_count"],
        label="br sync status dirty_count",
        cap=V2_INVENTORY_ROWS_CAP,
        error_type=error_type,
    )
    if normalized["jsonl_content_hash"] is not None:
        v2_br_hash(
            normalized["jsonl_content_hash"],
            label="br sync status JSONL content hash",
            error_type=error_type,
        )
    if not normalized["jsonl_exists"] and normalized["jsonl_newer"]:
        raise error_type("br sync status marks an absent JSONL export as newer")
    for field in ("last_export_time", "last_import_time"):
        value = normalized[field]
        if value is not None and not isinstance(value, str):
            raise error_type(f"br sync status {field} is not a string or null")
        if value is not None:
            try:
                v2_parse_timestamp(value, label=f"br sync status {field}")
            except HarnessError as error:
                raise error_type(f"br sync status {field} is malformed") from error
    if not isinstance(normalized["workspace_health"], str) or not normalized[
        "workspace_health"
    ]:
        raise error_type("br sync status workspace health is empty or malformed")
    reliability = v2_br_exact_mapping(
        normalized["reliability_audit"],
        V2_BR_RELIABILITY_FIELDS,
        label="br sync reliability audit",
        error_type=error_type,
    )
    anomalies = reliability["anomalies"]
    anomaly_count = v2_br_nonnegative_int(
        reliability["anomaly_count"],
        label="br sync reliability anomaly_count",
        cap=V2_INVENTORY_ROWS_CAP,
        error_type=error_type,
    )
    if not isinstance(anomalies, list) or anomaly_count != len(anomalies):
        raise error_type("br sync reliability anomaly count differs from its rows")
    prior_anomaly_ordinal = -1
    expected_health = "healthy"
    seen_database_missing = False
    seen_database_not_sqlite = False
    seen_sidecar_mismatch = False
    seen_truncated_wal = False
    seen_jsonl_conflict_markers = False
    seen_journal_sidecar_present = False
    seen_orphaned_lock_file = False
    seen_jsonl_newer = False
    seen_db_newer = False
    for index, raw_anomaly in enumerate(anomalies):
        anomaly = v2_br_exact_mapping(
            raw_anomaly,
            V2_BR_RELIABILITY_ANOMALY_FIELDS,
            label=f"br sync reliability anomaly {index}",
            error_type=error_type,
        )
        anomaly_code = anomaly["code"]
        anomaly_message = anomaly["message"]
        anomaly_severity = anomaly["severity"]
        if (
            type(anomaly_code) is not str
            or not anomaly_code
            or type(anomaly_message) is not str
            or not anomaly_message
            or type(anomaly_severity) is not str
            or not anomaly_severity
        ):
            raise error_type(
                f"br sync reliability anomaly {index} is malformed"
            )
        duplicate = False
        if anomaly_code == "database_missing":
            anomaly_ordinal = 0
            expected_contract = V2_BR_SYNC_ANOMALY_CONTRACT[
                "database_missing"
            ]
            duplicate = seen_database_missing
            seen_database_missing = True
        elif anomaly_code == "database_not_sqlite":
            anomaly_ordinal = 1
            expected_contract = V2_BR_SYNC_ANOMALY_CONTRACT[
                "database_not_sqlite"
            ]
            duplicate = seen_database_not_sqlite
            seen_database_not_sqlite = True
        elif anomaly_code == "sidecar_mismatch":
            anomaly_ordinal = 2
            expected_contract = V2_BR_SYNC_ANOMALY_CONTRACT[
                "sidecar_mismatch"
            ]
            duplicate = seen_sidecar_mismatch
            seen_sidecar_mismatch = True
        elif anomaly_code == "truncated_wal":
            anomaly_ordinal = 3
            expected_contract = V2_BR_SYNC_ANOMALY_CONTRACT["truncated_wal"]
            duplicate = seen_truncated_wal
            seen_truncated_wal = True
        elif anomaly_code == "jsonl_conflict_markers":
            anomaly_ordinal = 4
            expected_contract = V2_BR_SYNC_ANOMALY_CONTRACT[
                "jsonl_conflict_markers"
            ]
            duplicate = seen_jsonl_conflict_markers
            seen_jsonl_conflict_markers = True
        elif anomaly_code == "journal_sidecar_present":
            anomaly_ordinal = 5
            expected_contract = V2_BR_SYNC_ANOMALY_CONTRACT[
                "journal_sidecar_present"
            ]
            duplicate = seen_journal_sidecar_present
            seen_journal_sidecar_present = True
        elif anomaly_code == "orphaned_lock_file":
            anomaly_ordinal = 6
            expected_contract = V2_BR_SYNC_ANOMALY_CONTRACT[
                "orphaned_lock_file"
            ]
            duplicate = seen_orphaned_lock_file
            seen_orphaned_lock_file = True
        elif anomaly_code == "jsonl_newer":
            anomaly_ordinal = 7
            expected_contract = V2_BR_SYNC_ANOMALY_CONTRACT["jsonl_newer"]
            duplicate = seen_jsonl_newer
            seen_jsonl_newer = True
        elif anomaly_code == "db_newer":
            anomaly_ordinal = 8
            expected_contract = V2_BR_SYNC_ANOMALY_CONTRACT["db_newer"]
            duplicate = seen_db_newer
            seen_db_newer = True
        else:
            raise error_type(
                f"br sync reliability anomaly {index} is not released-br exact"
            )
        if duplicate:
            raise error_type(
                "br sync reliability anomaly codes are duplicated"
            )
        if anomaly_ordinal <= prior_anomaly_ordinal:
            raise error_type(
                "br sync reliability anomalies are not in released-br order"
            )
        prior_anomaly_ordinal = anomaly_ordinal
        if expected_contract != (anomaly_severity, anomaly_message):
            raise error_type(
                f"br sync reliability anomaly {index} is not released-br exact"
            )
        if anomaly_severity == "unsafe":
            expected_health = "unsafe"
        elif (
            anomaly_severity == "recoverable"
            and expected_health != "unsafe"
        ):
            expected_health = "recoverable"
        elif anomaly_severity == "degraded" and expected_health == "healthy":
            expected_health = "degraded"
    if (
        seen_database_missing and seen_database_not_sqlite
    ) or (seen_sidecar_mismatch and seen_truncated_wal):
        raise error_type(
            "br sync reliability anomalies describe an impossible file state"
        )
    if (
        reliability["source"] != "sync.status"
        or reliability["health"] != expected_health
        or normalized["workspace_health"] != reliability["health"]
        or (reliability["health"] == "healthy") != (anomaly_count == 0)
        or normalized["jsonl_newer"] != seen_jsonl_newer
        or normalized["db_newer"] != seen_db_newer
    ):
        raise error_type("br sync reliability audit identity is malformed")
    normalized_reliability = {
        "anomalies": anomalies,
        "anomaly_count": anomaly_count,
        "health": reliability["health"],
        "source": reliability["source"],
    }
    raw_git_export = normalized["git_export"]
    if not isinstance(raw_git_export, dict):
        raise error_type("br sync git export is not an object")
    git_export_fields = set(raw_git_export)
    if (
        input_kind == "released_live"
        and V2_BR_GIT_EXPORT_PROBED_REQUIRED_RAW_FIELDS
        <= git_export_fields
        and git_export_fields <= V2_BR_GIT_EXPORT_PROBED_RAW_FIELDS
    ):
        normalized_git_export = {
            "state": "PROBED",
            "available": raw_git_export["available"],
            "reason": None,
            "diagnostic_command": None,
            "tracked": raw_git_export["tracked"],
            "worktree_clean": raw_git_export["worktree_clean"],
            "index_clean": raw_git_export["index_clean"],
            "head_hash": (
                raw_git_export["head_hash"]
                if "head_hash" in raw_git_export
                else None
            ),
            "worktree_hash": (
                raw_git_export["worktree_hash"]
                if "worktree_hash" in raw_git_export
                else None
            ),
        }
    elif (
        input_kind == "released_live"
        and git_export_fields == V2_BR_GIT_EXPORT_NOT_PROBED_RAW_FIELDS
    ):
        normalized_git_export = {
            "state": "NOT_PROBED",
            **raw_git_export,
            "tracked": None,
            "worktree_clean": None,
            "index_clean": None,
            "head_hash": None,
            "worktree_hash": None,
        }
    elif input_kind == "released_live" and git_export_fields == {"available"}:
        normalized_git_export = {
            "state": "LEGACY_UNAVAILABLE",
            **raw_git_export,
            "reason": None,
            "diagnostic_command": None,
            "tracked": None,
            "worktree_clean": None,
            "index_clean": None,
            "head_hash": None,
            "worktree_hash": None,
        }
    elif input_kind == "retained" and git_export_fields == V2_BR_GIT_EXPORT_FIELDS:
        normalized_git_export = dict(raw_git_export)
    else:
        raise error_type(
            "br sync git export does not match its declared live or retained "
            "closed union schema"
        )
    git_state = normalized_git_export["state"]
    if git_state == "PROBED":
        if normalized_git_export["available"] is not True or any(
            type(normalized_git_export[field]) is not bool
            for field in (
                "tracked",
                "worktree_clean",
                "index_clean",
            )
        ) or any(
            normalized_git_export[field] is not None
            for field in ("reason", "diagnostic_command")
        ):
            raise error_type("br sync probed git export is malformed")
        hash_width: int | None = None
        for hash_field in ("head_hash", "worktree_hash"):
            hash_value = normalized_git_export[hash_field]
            if hash_value is None:
                continue
            if (
                type(hash_value) is not str
                or re.fullmatch(r"(?:[0-9a-f]{40}|[0-9a-f]{64})", hash_value)
                is None
            ):
                raise error_type(
                    f"br sync git export {hash_field} is not a canonical "
                    "SHA-1 or SHA-256 object ID"
                )
            current_hash_width = len(hash_value)
            if hash_width is not None and current_hash_width != hash_width:
                raise error_type("br sync git export mixes Git object formats")
            hash_width = current_hash_width
        if normalized["jsonl_exists"] != (
            normalized_git_export["worktree_hash"] is not None
        ):
            raise error_type(
                "br sync git export worktree hash disagrees with file presence"
            )
        tracked = normalized_git_export["tracked"]
        head_present = normalized_git_export["head_hash"] is not None
        worktree_present = (
            normalized_git_export["worktree_hash"] is not None
        )
        index_clean = normalized_git_export["index_clean"]
        worktree_clean = normalized_git_export["worktree_clean"]
        if index_clean and tracked != head_present:
            raise error_type(
                "clean br sync index disagrees with HEAD path presence"
            )
        if not tracked and not head_present and not index_clean:
            raise error_type(
                "absent br sync index and HEAD cannot be dirty"
            )
        if worktree_clean and tracked and not worktree_present:
            raise error_type(
                "tracked clean br sync worktree path is missing"
            )
        if not tracked and not worktree_present and not worktree_clean:
            raise error_type(
                "absent br sync index and worktree cannot be dirty"
            )
        if (
            tracked
            and worktree_clean
            and index_clean
            and normalized_git_export["head_hash"]
            != normalized_git_export["worktree_hash"]
        ):
            raise error_type("clean br sync git export hashes disagree")
    elif git_state == "NOT_PROBED":
        if normalized_git_export != {
            "state": "NOT_PROBED",
            "available": False,
            "reason": "not_probed",
            "diagnostic_command": "br vcs-status --json",
            "tracked": None,
            "worktree_clean": None,
            "index_clean": None,
            "head_hash": None,
            "worktree_hash": None,
        }:
            raise error_type("br sync not-probed git export is malformed")
    elif git_state == "LEGACY_UNAVAILABLE":
        if normalized_git_export != {
            "state": "LEGACY_UNAVAILABLE",
            "available": False,
            "reason": None,
            "diagnostic_command": None,
            "tracked": None,
            "worktree_clean": None,
            "index_clean": None,
            "head_hash": None,
            "worktree_hash": None,
        }:
            raise error_type("br sync legacy-unavailable git export is malformed")
    else:
        raise error_type("br sync git export has an unknown normalized state")
    return {
        **normalized,
        "reliability_audit": normalized_reliability,
        "git_export": normalized_git_export,
    }


def _v2_normalize_br_witness_actions_exact(
    value: Any,
    *,
    chunks: Sequence[Mapping[str, Any]],
    comparison: Mapping[str, Any],
    require_complete_candidate_coverage: bool = True,
    error_type: type[HarnessError],
) -> list[dict[str, Any]]:
    if (
        error_type is not InputRefused
        and error_type is not InfrastructureFailed
        and error_type is not EvidenceFailed
    ):
        raise EvidenceFailed(
            "br witness-action error type is not an allowed terminal"
        )
    if type(require_complete_candidate_coverage) is not bool:
        raise EvidenceFailed(
            "br witness-action coverage policy is not exact"
        )
    if (
        type(value) is not list
        or len(value) > 2 * V2_INVENTORY_ROWS_CAP
        or type(chunks) is not list
        or len(chunks) > V2_INVENTORY_ROWS_CAP
        or type(comparison) is not dict
    ):
        raise error_type(
            "br witness-action exact inputs are malformed or over cap"
        )
    comparison = v2_br_exact_mapping(
        comparison,
        V2_BR_WITNESS_COMPARISON_FIELDS,
        label="br witness-action comparison",
        error_type=error_type,
    )
    comparable = v2_br_nonnegative_int(
        comparison["comparable_chunk_count"],
        label="br witness-action comparable chunk count",
        cap=V2_INVENTORY_ROWS_CAP,
        error_type=error_type,
    )
    base_chunk_count = v2_br_nonnegative_int(
        comparison["base_chunk_count"],
        label="br witness-action base chunk count",
        cap=V2_INVENTORY_ROWS_CAP,
        error_type=error_type,
    )
    base_line_count = v2_br_nonnegative_int(
        comparison["base_line_count"],
        label="br witness-action base line count",
        cap=V2_INVENTORY_ROWS_CAP,
        error_type=error_type,
    )
    for field in ("schema_versions_match", "chunk_size_lines_match"):
        if type(comparison[field]) is not bool:
            raise error_type(
                f"br witness-action comparison {field} is not boolean"
            )
    if comparable > min(base_chunk_count, len(chunks)):
        raise error_type(
            "br witness-action comparable membership exceeds its inputs"
        )
    normalized: list[dict[str, Any]] = []
    candidate_indices: list[int] = []
    dropped_indices: list[int] = []
    dropped_action_spans: list[tuple[int, int]] = []
    drops_started = False
    witnesses_comparable = (
        comparison["schema_versions_match"]
        and comparison["chunk_size_lines_match"]
    )
    for index, raw in enumerate(value):
        action = v2_br_exact_mapping(
            raw,
            V2_BR_WITNESS_ACTION_FIELDS,
            label=f"br witness action {index}",
            error_type=error_type,
        )
        kind = action["action"]
        if type(kind) is not str or kind not in {
            "reuse_unchanged",
            "rebuild_candidate",
            "read_added",
            "drop_removed",
        }:
            raise error_type(f"br witness action {index} has an unknown kind")
        action_start_line = v2_br_nonnegative_int(
            action["start_line"],
            label=f"br witness action {index} start_line",
            cap=V2_INVENTORY_ROWS_CAP,
            error_type=error_type,
        )
        action_line_count = v2_br_nonnegative_int(
            action["line_count"],
            label=f"br witness action {index} line_count",
            cap=V2_INVENTORY_ROWS_CAP,
            error_type=error_type,
        )
        action_byte_count = v2_br_nonnegative_int(
            action["byte_count"],
            label=f"br witness action {index} byte_count",
            cap=RUN_ARTIFACT_CAP,
            error_type=error_type,
        )
        base_index = action["base_index"]
        candidate_index = action["candidate_index"]
        if kind == "drop_removed":
            if type(base_index) is not int or candidate_index is not None:
                raise error_type(f"br witness action {index} index contract differs")
            if base_index < comparable or base_index >= base_chunk_count:
                raise error_type(f"br witness action {index} base index is invalid")
            if (
                action_line_count == 0
                or action_byte_count < action_line_count
            ):
                raise error_type(
                    f"br witness action {index} removed chunk has impossible "
                    "line or byte counts"
                )
            drops_started = True
            dropped_indices.append(base_index)
            dropped_action_spans.append((
                action_start_line,
                action_line_count,
            ))
        elif type(candidate_index) is not int:
            raise error_type(f"br witness action {index} index contract differs")
        if candidate_index is not None:
            if drops_started:
                raise error_type("br witness candidate action follows a drop action")
            if candidate_index < 0 or candidate_index >= len(chunks):
                raise error_type(f"br witness action {index} candidate index is invalid")
            if candidate_index < comparable:
                if (
                    base_index != candidate_index
                    or kind not in {"reuse_unchanged", "rebuild_candidate"}
                ):
                    raise error_type(
                        f"br witness action {index} comparable index contract differs"
                    )
            elif (
                base_index is not None
                or kind
                != (
                    "read_added"
                    if witnesses_comparable
                    else "rebuild_candidate"
                )
            ):
                raise error_type(
                    f"br witness action {index} tail index contract differs"
                )
            chunk = v2_br_exact_mapping(
                chunks[candidate_index],
                V2_BR_WITNESS_CHUNK_FIELDS,
                label=f"br witness action {index} candidate chunk",
                error_type=error_type,
            )
            chunk_start_line = v2_br_nonnegative_int(
                chunk["start_line"],
                label=f"br witness action {index} chunk start_line",
                cap=V2_INVENTORY_ROWS_CAP,
                error_type=error_type,
            )
            chunk_line_count = v2_br_nonnegative_int(
                chunk["line_count"],
                label=f"br witness action {index} chunk line_count",
                cap=V2_INVENTORY_ROWS_CAP,
                error_type=error_type,
            )
            chunk_byte_count = v2_br_nonnegative_int(
                chunk["byte_count"],
                label=f"br witness action {index} chunk byte_count",
                cap=RUN_ARTIFACT_CAP,
                error_type=error_type,
            )
            if any(
                action_value != chunk_value
                for action_value, chunk_value in (
                    (action_start_line, chunk_start_line),
                    (action_line_count, chunk_line_count),
                    (action_byte_count, chunk_byte_count),
                )
            ):
                raise error_type(f"br witness action {index} differs from its chunk")
            candidate_indices.append(candidate_index)
        normalized.append(action)
    if require_complete_candidate_coverage:
        if candidate_indices != list(range(len(chunks))):
            raise error_type("br witness candidate actions do not exact-cover chunks")
        if dropped_indices != list(range(comparable, base_chunk_count)):
            raise error_type("br witness dropped actions do not exact-cover base tail")
        if dropped_action_spans:
            next_removed_line = base_line_count - sum(
                line_count
                for _start_line, line_count in dropped_action_spans
            )
            if next_removed_line < 0:
                raise error_type(
                    "br witness removed action lines exceed the base witness"
                )
            for start_line, line_count in dropped_action_spans:
                if start_line != next_removed_line:
                    raise error_type(
                        "br witness removed action line spans are noncontiguous"
                    )
                next_removed_line = v2_exact_int_add(
                    next_removed_line,
                    line_count,
                )
            if next_removed_line != base_line_count:
                raise error_type(
                    "br witness removed action lines do not end at the base tail"
                )
    else:
        if candidate_indices != sorted(set(candidate_indices)):
            raise error_type("br witness candidate actions are noncanonical")
        if dropped_indices != sorted(set(dropped_indices)):
            raise error_type("br witness dropped actions are noncanonical")
    return normalized


def v2_normalize_br_witness_actions(
    value: Any,
    *,
    chunks: Sequence[Mapping[str, Any]],
    comparison: Mapping[str, Any],
    require_complete_candidate_coverage: bool = True,
    error_type: type[HarnessError],
) -> list[dict[str, Any]]:
    """Normalize independently supplied witness actions through exact JSON."""
    exact_value = v2_br_exact_json_list(
        value,
        label="br witness actions",
        cap=2 * V2_INVENTORY_ROWS_CAP,
        error_type=error_type,
    )
    exact_chunks = v2_br_exact_json_list(
        chunks,
        label="br witness action chunks",
        cap=V2_INVENTORY_ROWS_CAP,
        error_type=error_type,
    )
    exact_comparison = v2_br_exact_mapping(
        comparison,
        V2_BR_WITNESS_COMPARISON_FIELDS,
        label="br witness action comparison",
        error_type=error_type,
    )
    return _v2_normalize_br_witness_actions_exact(
        exact_value,
        chunks=exact_chunks,
        comparison=exact_comparison,
        require_complete_candidate_coverage=(
            require_complete_candidate_coverage
        ),
        error_type=error_type,
    )


def v2_br_witness_u64(value: int) -> bytes:
    if type(value) is not int or not 0 <= value <= 0xFFFF_FFFF_FFFF_FFFF:
        raise EvidenceFailed("br witness root input exceeds u64")
    return value.to_bytes(8, "little")


def v2_br_witness_framed(value: str) -> bytes:
    if type(value) is not str:
        raise EvidenceFailed("br witness framed input is not an exact string")
    encoded_length = 0
    for character in value:
        codepoint = ord(character)
        if 0xD800 <= codepoint <= 0xDFFF:
            raise EvidenceFailed(
                "br witness framed input contains ill-formed Unicode"
            )
        encoded_length += (
            1
            if codepoint <= 0x7F
            else 2
            if codepoint <= 0x7FF
            else 3
            if codepoint <= 0xFFFF
            else 4
        )
        if encoded_length > RUN_ARTIFACT_CAP:
            raise EvidenceFailed("br witness framed input exceeds the byte cap")
    try:
        encoded = str.encode(value, "utf-8")
    except UnicodeEncodeError as error:
        raise EvidenceFailed(
            "br witness framed input contains ill-formed Unicode"
        ) from error
    if len(encoded) != encoded_length:
        raise EvidenceFailed("br witness framed byte accounting differs")
    return v2_br_witness_u64(len(encoded)) + b"\0" + encoded + b"\0"


def v2_br_witness_root(
    *,
    schema_version: str,
    chunk_size_lines: int,
    line_count: int,
    byte_count: int,
    chunks: Sequence[Mapping[str, Any]],
) -> str:
    if type(schema_version) is not str:
        raise EvidenceFailed("br witness root schema version is not an exact string")
    if schema_version != "br.jsonl-witness.v1":
        raise EvidenceFailed("br witness root schema version is not canonical")
    if type(chunks) is list:
        if list.__len__(chunks) > V2_INVENTORY_ROWS_CAP:
            raise EvidenceFailed(
                "br witness root chunk membership exceeds the cap"
            )
        chunk_rows = tuple(list.__iter__(chunks))
    elif type(chunks) is tuple:
        if tuple.__len__(chunks) > V2_INVENTORY_ROWS_CAP:
            raise EvidenceFailed(
                "br witness root chunk membership exceeds the cap"
            )
        chunk_rows = tuple(tuple.__iter__(chunks))
    else:
        raise EvidenceFailed(
            "br witness root chunks are not an exact list or tuple"
        )
    exact_chunks: list[dict[str, Any]] = []
    for chunk_index, chunk in enumerate(chunk_rows):
        if type(chunk) is not dict:
            raise EvidenceFailed(
                f"br witness root chunk {chunk_index} is not an exact object"
            )
        if dict.__len__(chunk) != len(V2_BR_WITNESS_CHUNK_FIELDS):
            raise EvidenceFailed(
                f"br witness root chunk {chunk_index} has a non-closed schema"
            )
        chunk_snapshot = dict.copy(chunk)
        chunk_fields = tuple(dict.__iter__(chunk_snapshot))
        if (
            any(type(field) is not str or not field for field in chunk_fields)
            or frozenset(chunk_fields) != V2_BR_WITNESS_CHUNK_FIELDS
        ):
            raise EvidenceFailed(
                f"br witness root chunk {chunk_index} has a non-closed schema"
            )
        for field in ("index", "start_line", "line_count", "byte_count"):
            v2_br_witness_u64(chunk_snapshot[field])
        v2_br_hash(
            chunk_snapshot["hash"],
            label=f"br witness root chunk {chunk_index} hash",
            error_type=EvidenceFailed,
        )
        for field in ("first_line_hash", "last_line_hash"):
            optional_hash = chunk_snapshot[field]
            if optional_hash is not None:
                v2_br_hash(
                    optional_hash,
                    label=f"br witness root chunk {chunk_index} {field}",
                    error_type=EvidenceFailed,
                )
        exact_chunks.append(chunk_snapshot)
    digest = V2_SHA256_CONSTRUCTOR()
    V2_SHA256_UPDATE(digest, b"br:jsonl-witness:root:v1\0")
    V2_SHA256_UPDATE(digest, v2_br_witness_framed(schema_version))
    V2_SHA256_UPDATE(digest, v2_br_witness_u64(chunk_size_lines))
    V2_SHA256_UPDATE(digest, v2_br_witness_u64(line_count))
    V2_SHA256_UPDATE(digest, v2_br_witness_u64(byte_count))
    V2_SHA256_UPDATE(digest, v2_br_witness_u64(len(exact_chunks)))
    for chunk in exact_chunks:
        V2_SHA256_UPDATE(digest, v2_br_witness_u64(chunk["index"]))
        V2_SHA256_UPDATE(digest, v2_br_witness_u64(chunk["start_line"]))
        V2_SHA256_UPDATE(digest, v2_br_witness_u64(chunk["line_count"]))
        V2_SHA256_UPDATE(digest, v2_br_witness_u64(chunk["byte_count"]))
        V2_SHA256_UPDATE(digest, v2_br_witness_framed(chunk["hash"]))
        for field in ("first_line_hash", "last_line_hash"):
            optional_hash = chunk[field]
            if optional_hash is None:
                V2_SHA256_UPDATE(digest, b"\0")
            else:
                V2_SHA256_UPDATE(digest, b"\x01")
                V2_SHA256_UPDATE(
                    digest,
                    v2_br_witness_framed(optional_hash),
                )
    return V2_SHA256_HEXDIGEST(digest)


def v2_normalize_br_export_witness(
    document: Any,
    *,
    input_kind: str,
    workspace_root: Path | None = None,
    expected_chunk_size_lines: int | None = None,
    expected_max_parallelism: int | None = None,
    error_type: type[HarnessError],
) -> dict[str, Any]:
    if (
        error_type is not InputRefused
        and error_type is not InfrastructureFailed
        and error_type is not EvidenceFailed
    ):
        raise EvidenceFailed(
            "br export-witness error type is not an allowed terminal"
        )
    if (
        type(input_kind) is not str
        or input_kind not in {"released_live", "retained"}
    ):
        raise error_type("br export witness input kind is unknown")
    if (
        expected_chunk_size_lines is not None
        and (
            type(expected_chunk_size_lines) is not int
            or expected_chunk_size_lines < 0
            or expected_chunk_size_lines > V2_INVENTORY_ROWS_CAP
        )
    ):
        raise error_type(
            "br export witness expected chunk size is malformed"
        )
    if (
        expected_max_parallelism is not None
        and (
            type(expected_max_parallelism) is not int
            or expected_max_parallelism < 0
            or expected_max_parallelism > V2_INVENTORY_ROWS_CAP
        )
    ):
        raise error_type(
            "br export witness expected parallelism is malformed"
        )
    if input_kind == "released_live" and workspace_root is None:
        raise error_type("live br export witness lacks its workspace root")
    if input_kind == "retained" and workspace_root is not None:
        raise error_type("retained br export witness carries a live workspace root")
    if (
        workspace_root is not None
        and type(workspace_root) is not type(REPO_ROOT)
    ):
        raise error_type("br export witness workspace root type differs")
    document = v2_released_json_snapshot(
        document,
        error_type=error_type,
        label="br export witness",
    )
    if type(document) is not dict:
        raise error_type("br export witness is not an object")
    document_fields = set(dict.__iter__(document))
    raw_present_fields = (
        V2_BR_WITNESS_REQUIRED_RAW_FIELDS | V2_BR_WITNESS_BASE_FIELDS
    )
    if (
        input_kind == "released_live"
        and document_fields == V2_BR_WITNESS_REQUIRED_RAW_FIELDS
    ):
        normalized = {
            **document,
            "base_evidence_state": "ABSENT_NODATA",
            **{field: None for field in V2_BR_WITNESS_BASE_FIELDS},
        }
    elif input_kind == "released_live" and document_fields == raw_present_fields:
        normalized = {
            **document,
            "base_evidence_state": "PRESENT",
        }
    elif input_kind == "retained" and document_fields == V2_BR_WITNESS_FIELDS:
        normalized = dict(document)
    else:
        raise error_type(
            "br export witness has a partial or non-closed base-evidence schema"
        )
    base_evidence_state = normalized["base_evidence_state"]
    if base_evidence_state == "ABSENT_NODATA":
        if any(
            normalized[field] is not None
            for field in V2_BR_WITNESS_BASE_FIELDS
        ):
            raise error_type(
                "br export witness absent base evidence carries a base field"
            )
    elif base_evidence_state != "PRESENT" or any(
        normalized[field] is None for field in V2_BR_WITNESS_BASE_FIELDS
    ):
        raise error_type("br export witness base evidence state is inconsistent")
    jsonl_relative = ".beads/issues.jsonl"
    base_jsonl_relative = ".beads/beads.base.jsonl"
    if input_kind == "released_live":
        if workspace_root is None:
            raise EvidenceFailed(
                "released-live br export witness lost its workspace root"
            )
        live_root = workspace_root.resolve()
        live_root_parts = live_root.parts
        live_jsonl_path = live_root / jsonl_relative
        resolved_jsonl_path = live_jsonl_path.resolve(strict=False)
        resolved_jsonl_parts = resolved_jsonl_path.parts
        if (
            len(resolved_jsonl_parts) < len(live_root_parts)
            or resolved_jsonl_parts[:len(live_root_parts)]
            != live_root_parts
        ):
            raise error_type(
                "br export witness jsonl_path resolves outside its workspace"
            )
        expected_jsonl_path = str(live_jsonl_path)
        expected_base_jsonl_path: str | None = None
        if base_evidence_state == "PRESENT":
            live_base_jsonl_path = live_root / base_jsonl_relative
            resolved_base_jsonl_path = live_base_jsonl_path.resolve(
                strict=False
            )
            resolved_base_jsonl_parts = resolved_base_jsonl_path.parts
            if (
                len(resolved_base_jsonl_parts) < len(live_root_parts)
                or resolved_base_jsonl_parts[:len(live_root_parts)]
                != live_root_parts
            ):
                raise error_type(
                    "br export witness base_jsonl_path resolves outside its "
                    "workspace"
                )
            expected_base_jsonl_path = str(live_base_jsonl_path)
    else:
        expected_jsonl_path = jsonl_relative
        expected_base_jsonl_path = (
            base_jsonl_relative
            if base_evidence_state == "PRESENT"
            else None
        )
    if normalized["jsonl_path"] != expected_jsonl_path:
        raise error_type(
            "br export witness jsonl_path is outside its fixed path"
        )
    if normalized["base_jsonl_path"] != expected_base_jsonl_path:
        raise error_type(
            "br export witness base_jsonl_path is outside its fixed path"
        )
    normalized = {
        "base_comparison": normalized["base_comparison"],
        "base_evidence_state": base_evidence_state,
        "base_jsonl_path": (
            base_jsonl_relative
            if base_evidence_state == "PRESENT"
            else None
        ),
        "base_parallel_work_plan": normalized["base_parallel_work_plan"],
        "base_reuse_materialization": normalized[
            "base_reuse_materialization"
        ],
        "base_reuse_plan": normalized["base_reuse_plan"],
        "jsonl_path": jsonl_relative,
        "witness": normalized["witness"],
    }
    witness = v2_br_exact_mapping(
        normalized["witness"],
        V2_BR_WITNESS_BODY_FIELDS,
        label="br export witness body",
        error_type=error_type,
    )
    if witness["schema_version"] != "br.jsonl-witness.v1":
        raise error_type("br export witness has an unknown schema version")
    line_count = v2_br_nonnegative_int(
        witness["line_count"],
        label="br export witness line_count",
        cap=V2_INVENTORY_ROWS_CAP,
        error_type=error_type,
    )
    byte_count = v2_br_nonnegative_int(
        witness["byte_count"],
        label="br export witness byte_count",
        cap=RUN_ARTIFACT_CAP,
        error_type=error_type,
    )
    chunk_size = v2_br_nonnegative_int(
        witness["chunk_size_lines"],
        label="br export witness chunk_size_lines",
        cap=V2_INVENTORY_ROWS_CAP,
        error_type=error_type,
    )
    if chunk_size == 0:
        raise error_type("br export witness chunk size is zero")
    if (
        expected_chunk_size_lines is not None
        and chunk_size != expected_chunk_size_lines
    ):
        raise error_type(
            "br export witness chunk size differs from its fixed invocation"
        )
    v2_br_hash(
        witness["root_hash"],
        label="br export witness root_hash",
        error_type=error_type,
    )
    raw_chunks = witness["chunks"]
    if type(raw_chunks) is not list or len(raw_chunks) > V2_INVENTORY_ROWS_CAP:
        raise error_type("br export witness chunks are malformed or over cap")
    chunks: list[dict[str, Any]] = []
    next_line = 0
    total_bytes = 0
    for index, raw_chunk in enumerate(raw_chunks):
        chunk = v2_br_exact_mapping(
            raw_chunk,
            V2_BR_WITNESS_CHUNK_FIELDS,
            label=f"br export witness chunk {index}",
            error_type=error_type,
        )
        if chunk["index"] != index or chunk["start_line"] != next_line:
            raise error_type("br export witness chunk order or line offset differs")
        chunk_lines = v2_br_nonnegative_int(
            chunk["line_count"],
            label=f"br export witness chunk {index} line_count",
            cap=chunk_size,
            error_type=error_type,
        )
        chunk_bytes = v2_br_nonnegative_int(
            chunk["byte_count"],
            label=f"br export witness chunk {index} byte_count",
            cap=RUN_ARTIFACT_CAP,
            error_type=error_type,
        )
        if chunk_lines == 0 or chunk_bytes < chunk_lines or (
            index + 1 < len(raw_chunks) and chunk_lines != chunk_size
        ):
            raise error_type(
                "br export witness chunk membership or byte count is noncanonical"
            )
        for field in ("hash", "first_line_hash", "last_line_hash"):
            v2_br_hash(
                chunk[field],
                label=f"br export witness chunk {index} {field}",
                error_type=error_type,
            )
        if (
            chunk_lines == 1
            and chunk["first_line_hash"] != chunk["last_line_hash"]
        ):
            raise error_type(
                "br export witness one-line chunk boundary hashes differ"
            )
        next_line += chunk_lines
        total_bytes += chunk_bytes
        if total_bytes > RUN_ARTIFACT_CAP:
            raise error_type("br export witness chunk bytes exceed the cap")
        chunks.append(chunk)
    if (line_count == 0) != (not chunks):
        raise error_type("br export witness empty membership is inconsistent")
    if next_line != line_count or total_bytes != byte_count:
        raise error_type("br export witness chunk arithmetic differs")
    expected_witness_root = v2_br_witness_root(
        schema_version=witness["schema_version"],
        chunk_size_lines=chunk_size,
        line_count=line_count,
        byte_count=byte_count,
        chunks=chunks,
    )
    if witness["root_hash"] != expected_witness_root:
        raise error_type(
            "br export witness root differs from its retained metadata"
        )
    witness = {**witness, "chunks": chunks}

    if base_evidence_state == "ABSENT_NODATA":
        return {
            "base_comparison": normalized["base_comparison"],
            "base_evidence_state": base_evidence_state,
            "base_jsonl_path": normalized["base_jsonl_path"],
            "base_parallel_work_plan": normalized["base_parallel_work_plan"],
            "base_reuse_materialization": normalized[
                "base_reuse_materialization"
            ],
            "base_reuse_plan": normalized["base_reuse_plan"],
            "jsonl_path": normalized["jsonl_path"],
            "witness": witness,
        }

    comparison = v2_br_exact_mapping(
        normalized["base_comparison"],
        V2_BR_WITNESS_COMPARISON_FIELDS,
        label="br export witness base comparison",
        error_type=error_type,
    )
    integer_fields = V2_BR_WITNESS_COMPARISON_FIELDS - {
        "chunk_size_lines_match",
        "drift_detected",
        "first_changed_chunk_index",
        "root_hashes_match",
        "schema_versions_match",
    }
    for field in integer_fields:
        v2_br_nonnegative_int(
            comparison[field],
            label=f"br export witness comparison {field}",
            cap=RUN_ARTIFACT_CAP,
            error_type=error_type,
        )
    for field in (
        "chunk_size_lines_match",
        "drift_detected",
        "root_hashes_match",
        "schema_versions_match",
    ):
        if type(comparison[field]) is not bool:
            raise error_type(f"br export witness comparison {field} is not boolean")
    if (
        expected_chunk_size_lines is not None
        or expected_max_parallelism is not None
    ) and not (
        comparison["schema_versions_match"]
        and comparison["chunk_size_lines_match"]
    ):
        raise error_type(
            "br export witness comparison differs from its fixed invocation"
        )
    first_changed = comparison["first_changed_chunk_index"]
    maximum_chunks = max(
        comparison["base_chunk_count"],
        comparison["candidate_chunk_count"],
    )
    if first_changed is not None and (
        type(first_changed) is not int
        or first_changed < 0
        or first_changed > maximum_chunks
    ):
        raise error_type("br export witness first changed chunk index is invalid")
    witnesses_comparable = (
        comparison["schema_versions_match"]
        and comparison["chunk_size_lines_match"]
    )
    comparable = (
        min(
            comparison["base_chunk_count"],
            comparison["candidate_chunk_count"],
        )
        if witnesses_comparable
        else 0
    )
    if (
        comparison["comparable_chunk_count"] != comparable
        or comparison["unchanged_chunks"] + comparison["changed_chunks"]
        != comparable
        or comparison["added_chunks"]
        != comparison["candidate_chunk_count"] - comparable
        or comparison["removed_chunks"]
        != comparison["base_chunk_count"] - comparable
        or comparison["base_byte_count"]
        != comparison["unchanged_byte_count"]
        + comparison["changed_base_byte_count"]
        + comparison["removed_byte_count"]
        or comparison["candidate_byte_count"]
        != comparison["unchanged_byte_count"]
        + comparison["changed_candidate_byte_count"]
        + comparison["added_byte_count"]
        or comparison["safe_reuse_prefix_chunks"]
        > comparison["unchanged_chunks"]
        or comparison["candidate_chunk_count"] != len(chunks)
        or comparison["candidate_line_count"] != line_count
        or comparison["candidate_byte_count"] != byte_count
        or comparison["drift_detected"]
        != (not (witnesses_comparable and comparison["root_hashes_match"]))
    ):
        raise error_type("br export witness comparison arithmetic differs")
    if (
        (comparison["base_line_count"] == 0)
        != (comparison["base_chunk_count"] == 0)
        or (comparison["base_chunk_count"] == 0)
        != (comparison["base_byte_count"] == 0)
        or comparison["base_byte_count"]
        < comparison["base_line_count"]
        or (comparison["candidate_line_count"] == 0)
        != (comparison["candidate_chunk_count"] == 0)
        or (comparison["candidate_chunk_count"] == 0)
        != (comparison["candidate_byte_count"] == 0)
        or (comparison["unchanged_chunks"] == 0)
        != (comparison["unchanged_byte_count"] == 0)
        or (comparison["changed_chunks"] == 0)
        != (comparison["changed_base_byte_count"] == 0)
        or (comparison["changed_chunks"] == 0)
        != (comparison["changed_candidate_byte_count"] == 0)
        or (comparison["added_chunks"] == 0)
        != (comparison["added_byte_count"] == 0)
        or (comparison["removed_chunks"] == 0)
        != (comparison["removed_byte_count"] == 0)
    ):
        raise error_type(
            "br export witness byte and chunk emptiness differs"
        )
    if comparison["chunk_size_lines_match"] and comparison[
        "base_chunk_count"
    ]:
        minimum_base_lines = (
            comparison["base_chunk_count"] - 1
        ) * chunk_size
        maximum_base_lines = comparison["base_chunk_count"] * chunk_size
        if not (
            minimum_base_lines
            < comparison["base_line_count"]
            <= maximum_base_lines
        ):
            raise error_type(
                "br export witness base chunk and line counts disagree"
            )
    if not comparison["drift_detected"] and (
        first_changed is not None
        or any(
            comparison[field] != 0
            for field in (
                "added_byte_count",
                "added_chunks",
                "changed_base_byte_count",
                "changed_candidate_byte_count",
                "changed_chunks",
                "removed_byte_count",
                "removed_chunks",
            )
        )
    ):
        raise error_type("br export witness no-drift comparison is inconsistent")

    reuse_plan = v2_br_exact_mapping(
        normalized["base_reuse_plan"],
        frozenset({"actions", "comparison", "schedule"}),
        label="br export witness reuse plan",
        error_type=error_type,
    )
    if reuse_plan["comparison"] != comparison:
        raise error_type("br export witness repeated comparison differs")
    actions = _v2_normalize_br_witness_actions_exact(
        reuse_plan["actions"],
        chunks=chunks,
        comparison=comparison,
        error_type=error_type,
    )
    if comparison["chunk_size_lines_match"]:
        minimum_changed_base_bytes = 0
        for action in actions:
            if action["base_index"] is None:
                continue
            base_index = v2_br_nonnegative_int(
                action["base_index"],
                label="br export witness action base index",
                cap=V2_INVENTORY_ROWS_CAP,
                error_type=error_type,
            )
            base_start = v2_br_nonnegative_int(
                base_index * chunk_size,
                label="br export witness action base start",
                cap=V2_INVENTORY_ROWS_CAP,
                error_type=error_type,
            )
            if base_start >= comparison["base_line_count"]:
                raise error_type(
                    "br export witness action starts beyond its base lines"
                )
            base_lines = v2_br_nonnegative_int(
                min(
                    chunk_size,
                    comparison["base_line_count"] - base_start,
                ),
                label="br export witness action base line count",
                cap=chunk_size,
                error_type=error_type,
            )
            if action["action"] == "drop_removed":
                if (
                    action["start_line"] != base_start
                    or action["line_count"] != base_lines
                ):
                    raise error_type(
                        "br export witness removed action differs from its "
                        "released base chunk geometry"
                    )
            elif action["action"] == "reuse_unchanged":
                if action["line_count"] != base_lines:
                    raise error_type(
                        "br export witness reused action differs from its "
                        "released base chunk geometry"
                    )
            elif action["action"] == "rebuild_candidate":
                minimum_changed_base_bytes = v2_exact_int_add(
                    minimum_changed_base_bytes,
                    base_lines,
                )
        if (
            comparison["changed_base_byte_count"]
            < minimum_changed_base_bytes
        ):
            raise error_type(
                "br export witness changed base bytes cannot contain its "
                "released base chunk lines"
            )
    safe_prefix = 0
    candidate_action_count = 0
    first_changed: int | None = None
    for action in actions:
        if action["candidate_index"] is None:
            continue
        if first_changed is None and action["action"] == "reuse_unchanged":
            safe_prefix = v2_exact_int_add(safe_prefix, 1)
        elif first_changed is None:
            first_changed = candidate_action_count
        candidate_action_count = v2_exact_int_add(
            candidate_action_count,
            1,
        )
    if first_changed is None and len(actions) > candidate_action_count:
        first_changed = v2_br_nonnegative_int(
            actions[candidate_action_count]["base_index"],
            label="br export witness first removed base index",
            cap=V2_INVENTORY_ROWS_CAP,
            error_type=error_type,
        )
    elif first_changed is None and not witnesses_comparable:
        first_changed = 0
    if (
        comparison["safe_reuse_prefix_chunks"] != safe_prefix
        or comparison["first_changed_chunk_index"] != first_changed
    ):
        raise error_type(
            "br export witness changed-index or reusable-prefix evidence differs"
        )
    schedule = v2_br_exact_mapping(
        reuse_plan["schedule"],
        V2_BR_WITNESS_SCHEDULE_FIELDS,
        label="br export witness schedule",
        error_type=error_type,
    )
    for field in V2_BR_WITNESS_SCHEDULE_FIELDS - {"deterministic_candidate_order"}:
        v2_br_nonnegative_int(
            schedule[field],
            label=f"br export witness schedule {field}",
            cap=RUN_ARTIFACT_CAP,
            error_type=error_type,
        )
    if schedule["deterministic_candidate_order"] is not True:
        raise error_type("br export witness candidate action order is nondeterministic")
    reuse_action_count = 0
    rebuild_action_count = 0
    read_added_action_count = 0
    drop_action_count = 0
    reuse_byte_count = 0
    rebuild_byte_count = 0
    read_added_byte_count = 0
    drop_byte_count = 0
    for action in actions:
        action_byte_count = v2_br_nonnegative_int(
            action["byte_count"],
            label="br export witness action byte count",
            cap=RUN_ARTIFACT_CAP,
            error_type=error_type,
        )
        if action["action"] == "reuse_unchanged":
            reuse_action_count = v2_exact_int_add(reuse_action_count, 1)
            reuse_byte_count = v2_exact_int_add(
                reuse_byte_count,
                action_byte_count,
            )
        elif action["action"] == "rebuild_candidate":
            rebuild_action_count = v2_exact_int_add(rebuild_action_count, 1)
            rebuild_byte_count = v2_exact_int_add(
                rebuild_byte_count,
                action_byte_count,
            )
        elif action["action"] == "read_added":
            read_added_action_count = v2_exact_int_add(
                read_added_action_count,
                1,
            )
            read_added_byte_count = v2_exact_int_add(
                read_added_byte_count,
                action_byte_count,
            )
        elif action["action"] == "drop_removed":
            drop_action_count = v2_exact_int_add(drop_action_count, 1)
            drop_byte_count = v2_exact_int_add(
                drop_byte_count,
                action_byte_count,
            )
        else:
            raise EvidenceFailed(
                "normalized br witness action kind escaped its closed schema"
            )
    expected_rebuild_bytes = (
        comparison["changed_candidate_byte_count"]
        if witnesses_comparable
        else comparison["added_byte_count"]
    )
    if (
        reuse_byte_count != comparison["unchanged_byte_count"]
        or rebuild_byte_count != expected_rebuild_bytes
        or read_added_byte_count
        != (comparison["added_byte_count"] if witnesses_comparable else 0)
        or drop_byte_count != comparison["removed_byte_count"]
    ):
        raise error_type(
            "br export witness action bytes differ from its comparison"
        )
    if (
        schedule["total_actions"] != len(actions)
        or schedule["candidate_output_actions"] != candidate_action_count
        or schedule["max_parallel_candidate_actions"] != candidate_action_count
        or schedule["metadata_only_drop_actions"] != drop_action_count
        or schedule["reusable_actions"] != reuse_action_count
        or schedule["rebuild_actions"] != rebuild_action_count
        or schedule["read_added_actions"] != read_added_action_count
        or schedule["candidate_output_line_count"] != line_count
        or schedule["candidate_output_byte_count"] != byte_count
        or schedule["reusable_byte_count"] != reuse_byte_count
        or schedule["rebuild_byte_count"] != rebuild_byte_count
        or schedule["read_added_byte_count"] != read_added_byte_count
        or schedule["dropped_byte_count"] != drop_byte_count
        or reuse_action_count != comparison["unchanged_chunks"]
        or rebuild_action_count
        != (
            comparison["changed_chunks"]
            if witnesses_comparable
            else comparison["added_chunks"]
        )
        or read_added_action_count
        != (comparison["added_chunks"] if witnesses_comparable else 0)
        or drop_action_count != comparison["removed_chunks"]
    ):
        raise error_type("br export witness schedule arithmetic differs")
    expected_root_hashes_match = (
        witnesses_comparable
        and comparison["base_line_count"]
        == comparison["candidate_line_count"]
        and comparison["base_byte_count"]
        == comparison["candidate_byte_count"]
        and comparison["base_chunk_count"]
        == comparison["candidate_chunk_count"]
        and all(
            comparison[field] == 0
            for field in (
                "added_byte_count",
                "added_chunks",
                "changed_base_byte_count",
                "changed_candidate_byte_count",
                "changed_chunks",
                "removed_byte_count",
                "removed_chunks",
            )
        )
    )
    if comparison["root_hashes_match"] is not expected_root_hashes_match:
        raise error_type(
            "br export witness root-match evidence differs from its comparison"
        )
    reuse_plan = {
        **reuse_plan,
        "actions": actions,
        "schedule": schedule,
    }

    materialization = v2_br_exact_mapping(
        normalized["base_reuse_materialization"],
        V2_BR_WITNESS_MATERIALIZATION_FIELDS,
        label="br export witness reuse materialization",
        error_type=error_type,
    )
    for field in V2_BR_WITNESS_MATERIALIZATION_FIELDS:
        v2_br_nonnegative_int(
            materialization[field],
            label=f"br export witness materialization {field}",
            cap=RUN_ARTIFACT_CAP,
            error_type=error_type,
        )
    if (
        materialization["reused_chunks"] != reuse_action_count
        or materialization["rebuilt_chunks"] != rebuild_action_count
        or materialization["read_added_chunks"] != read_added_action_count
        or materialization["dropped_chunks"] != drop_action_count
        or materialization["reused_byte_count"] != reuse_byte_count
        or materialization["rebuilt_byte_count"] != rebuild_byte_count
        or materialization["read_added_byte_count"] != read_added_byte_count
        or materialization["dropped_byte_count"] != drop_byte_count
        or materialization["output_byte_count"] != byte_count
        or materialization["output_byte_count"]
        != materialization["reused_byte_count"]
        + materialization["rebuilt_byte_count"]
        + materialization["read_added_byte_count"]
    ):
        raise error_type("br export witness materialization arithmetic differs")

    parallel = v2_br_exact_mapping(
        normalized["base_parallel_work_plan"],
        V2_BR_WITNESS_PARALLEL_FIELDS,
        label="br export witness parallel plan",
        error_type=error_type,
    )
    for field in V2_BR_WITNESS_PARALLEL_FIELDS - {
        "batches",
        "deterministic_batch_order",
    }:
        v2_br_nonnegative_int(
            parallel[field],
            label=f"br export witness parallel plan {field}",
            cap=V2_INVENTORY_ROWS_CAP,
            error_type=error_type,
        )
    max_parallelism = v2_br_nonnegative_int(
        parallel["max_parallelism"],
        label="br export witness maximum parallelism",
        cap=V2_INVENTORY_ROWS_CAP,
        error_type=error_type,
    )
    if parallel["deterministic_batch_order"] is not True or max_parallelism == 0:
        raise error_type("br export witness parallel plan is nondeterministic")
    if (
        expected_max_parallelism is not None
        and max_parallelism != expected_max_parallelism
    ):
        raise error_type(
            "br export witness parallelism differs from its fixed invocation"
        )
    raw_batches = parallel["batches"]
    if type(raw_batches) is not list or len(raw_batches) > V2_INVENTORY_ROWS_CAP:
        raise error_type("br export witness batches are malformed or over cap")
    batches: list[dict[str, Any]] = []
    covered_action_count = 0
    candidate_output_batch_count = 0
    metadata_only_drop_batch_count = 0
    prior_batch_kind: str | None = None
    prior_batch_action_count = 0
    for index, raw_batch in enumerate(raw_batches):
        batch = v2_br_exact_mapping(
            raw_batch,
            V2_BR_WITNESS_BATCH_FIELDS,
            label=f"br export witness batch {index}",
            error_type=error_type,
        )
        batch_kind = batch["kind"]
        if (
            batch["index"] != index
            or type(batch_kind) is not str
            or batch_kind not in {
            "candidate_output",
            "metadata_only_drop",
            }
        ):
            raise error_type("br export witness batch identity is noncanonical")
        if batch_kind == "candidate_output":
            candidate_output_batch_count = v2_exact_int_add(
                candidate_output_batch_count,
                1,
            )
        else:
            metadata_only_drop_batch_count = v2_exact_int_add(
                metadata_only_drop_batch_count,
                1,
            )
        batch_actions = _v2_normalize_br_witness_actions_exact(
            batch["actions"],
            chunks=chunks,
            comparison=comparison,
            require_complete_candidate_coverage=False,
            error_type=error_type,
        )
        if not batch_actions or len(batch_actions) > max_parallelism:
            raise error_type(
                "br export witness batch is empty or exceeds max parallelism"
            )
        batch_candidate_count = 0
        expected_start: int | None = None
        expected_end: int | None = None
        expected_batch_line_count = 0
        expected_batch_byte_count = 0
        batch_contains_only_drops = True
        for action in batch_actions:
            candidate_index = action["candidate_index"]
            if candidate_index is not None:
                candidate_index = v2_br_nonnegative_int(
                    candidate_index,
                    label="br export witness batch candidate index",
                    cap=V2_INVENTORY_ROWS_CAP,
                    error_type=error_type,
                )
                if expected_start is None:
                    expected_start = candidate_index
                expected_end = v2_exact_int_add(candidate_index, 1)
                batch_candidate_count = v2_exact_int_add(
                    batch_candidate_count,
                    1,
                )
            if action["action"] != "drop_removed":
                batch_contains_only_drops = False
            expected_batch_line_count = v2_exact_int_add(
                expected_batch_line_count,
                v2_br_nonnegative_int(
                    action["line_count"],
                    label="br export witness batch action line count",
                    cap=V2_INVENTORY_ROWS_CAP,
                    error_type=error_type,
                ),
            )
            expected_batch_byte_count = v2_exact_int_add(
                expected_batch_byte_count,
                v2_br_nonnegative_int(
                    action["byte_count"],
                    label="br export witness batch action byte count",
                    cap=RUN_ARTIFACT_CAP,
                    error_type=error_type,
                ),
            )
        if batch_kind == "candidate_output":
            if (
                batch_candidate_count == 0
                or batch_candidate_count != len(batch_actions)
            ):
                raise error_type(
                    "br export witness candidate batch is empty or contains a drop"
                )
        else:
            if not batch_contains_only_drops:
                raise error_type(
                    "br export witness metadata-only batch contains an output action"
                )
            expected_start = None
            expected_end = None
        batch_action_count = v2_br_nonnegative_int(
            batch["action_count"],
            label="br export witness batch action count",
            cap=V2_INVENTORY_ROWS_CAP,
            error_type=error_type,
        )
        if (
            prior_batch_kind == batch_kind
            and prior_batch_action_count < max_parallelism
        ):
            raise error_type(
                "br export witness batches split a non-full same-kind group"
            )
        prior_batch_kind = batch_kind
        prior_batch_action_count = batch_action_count
        batch_start = (
            None
            if batch["candidate_start_index"] is None
            else v2_br_nonnegative_int(
                batch["candidate_start_index"],
                label="br export witness batch candidate start index",
                cap=V2_INVENTORY_ROWS_CAP,
                error_type=error_type,
            )
        )
        batch_end = (
            None
            if batch["candidate_end_index"] is None
            else v2_br_nonnegative_int(
                batch["candidate_end_index"],
                label="br export witness batch candidate end index",
                cap=V2_INVENTORY_ROWS_CAP,
                error_type=error_type,
            )
        )
        batch_line_count = v2_br_nonnegative_int(
            batch["line_count"],
            label="br export witness batch line count",
            cap=V2_INVENTORY_ROWS_CAP,
            error_type=error_type,
        )
        batch_byte_count = v2_br_nonnegative_int(
            batch["byte_count"],
            label="br export witness batch byte count",
            cap=RUN_ARTIFACT_CAP,
            error_type=error_type,
        )
        if (
            batch_action_count != len(batch_actions)
            or batch_start != expected_start
            or batch_end != expected_end
            or batch_line_count != expected_batch_line_count
            or batch_byte_count != expected_batch_byte_count
        ):
            raise error_type("br export witness batch arithmetic differs")
        batch = {**batch, "actions": batch_actions}
        batches.append(batch)
        for batch_action in batch_actions:
            if (
                covered_action_count >= len(actions)
                or batch_action != actions[covered_action_count]
            ):
                raise error_type(
                    "br export witness batch action order or membership differs"
                )
            covered_action_count = v2_exact_int_add(
                covered_action_count,
                1,
            )
    if (
        parallel["total_batches"] != len(batches)
        or parallel["candidate_output_batches"]
        != candidate_output_batch_count
        or parallel["metadata_only_drop_batches"]
        != metadata_only_drop_batch_count
        or covered_action_count != len(actions)
    ):
        raise error_type("br export witness parallel batch coverage differs")
    parallel = {**parallel, "batches": batches}

    return {
        "base_evidence_state": base_evidence_state,
        "base_jsonl_path": normalized["base_jsonl_path"],
        "base_comparison": comparison,
        "base_parallel_work_plan": parallel,
        "base_reuse_materialization": materialization,
        "base_reuse_plan": reuse_plan,
        "jsonl_path": normalized["jsonl_path"],
        "witness": witness,
    }


def v2_issue_is_exportable(issue: Mapping[str, Any]) -> bool:
    issue_id = str(issue.get("id") or "")
    return (
        issue.get("ephemeral") is not True
        and "-wisp-" not in issue_id
    )


def v2_validate_live_envelope_consistency(
    *,
    tracker_status: Mapping[str, Any],
    sync_status: Mapping[str, Any],
    export_witness: Mapping[str, Any],
    full_issues: Sequence[Mapping[str, Any]],
    error_type: type[HarnessError],
) -> None:
    summary = tracker_status["summary"]
    status_counts = Counter(str(issue.get("status") or "") for issue in full_issues)
    non_tombstone_total = sum(
        issue.get("status") != "tombstone" for issue in full_issues
    )
    pinned_total = sum(
        issue.get("pinned") is True or issue.get("status") == "pinned"
        for issue in full_issues
        if issue.get("status") != "tombstone"
    )
    if (
        summary["total_issues"] != non_tombstone_total
        or summary["open_issues"] != status_counts["open"]
        or summary["in_progress_issues"] != status_counts["in_progress"]
        or summary["deferred_issues"] != status_counts["deferred"]
        or summary["draft_issues"] != status_counts["draft"]
        or summary["closed_issues"] != status_counts["closed"]
        or summary["tombstone_issues"] != status_counts["tombstone"]
        or summary["pinned_issues"] != pinned_total
        or summary["blocked_issues"] < status_counts["blocked"]
        or summary["blocked_issues"]
        > summary["total_issues"] - summary["closed_issues"]
        or summary["ready_issues"] > summary["open_issues"]
    ):
        raise error_type("br status summary disagrees with the all-status source")
    witness = export_witness["witness"]
    comparison = export_witness["base_comparison"]
    exported_issue_count = sum(
        v2_issue_is_exportable(issue) for issue in full_issues
    )
    if (
        sync_status["jsonl_exists"] is not True
        or witness["line_count"] != exported_issue_count
        or (
            export_witness["base_evidence_state"] == "PRESENT"
            and comparison["candidate_line_count"] != exported_issue_count
        )
    ):
        raise error_type("br sync witness disagrees with the all-status source")


def v2_source_file_identities() -> list[dict[str, Any]]:
    identities: list[dict[str, Any]] = []
    for relative in (
        str(SCRIPT_REL),
        str(CASE_MANIFEST_REL),
        str(CASE_MANIFEST_V2_REL),
    ):
        payload = v2_read_file_strict(
            REPO_ROOT / relative,
            label=f"v2 source identity {relative}",
        )
        identities.append(
            {
                "path": relative,
                "bytes": len(payload),
                "content_identity": (
                    "sha256-v1:" + hashlib.sha256(payload).hexdigest()
                ),
            }
        )
    return identities


def v2_validate_capture_row_coherence(
    rows: Sequence[Mapping[str, Any]],
    full_issues: Sequence[Mapping[str, Any]],
    *,
    label: str,
    relation_counts: bool,
    error_type: type[HarnessError] = EvidenceFailed,
) -> None:
    v2_require_allowed_terminal_error_type(
        error_type,
        label="capture row coherence error type",
    )
    if type(label) is not str or not label or type(relation_counts) is not bool:
        raise EvidenceFailed("capture row coherence controls are malformed")
    detached = v2_released_json_snapshot(
        {"rows": rows, "full_issues": full_issues},
        label=f"{label} inputs",
        error_type=error_type,
    )
    if type(detached) is not dict:
        v2_raise_allowed_terminal_error(
            error_type,
            f"{label} snapshot is malformed",
        )
    rows = dict.__getitem__(detached, "rows")
    full_issues = dict.__getitem__(detached, "full_issues")
    if type(rows) is not list or type(full_issues) is not list:
        v2_raise_allowed_terminal_error(
            error_type,
            f"{label} inputs are not exact arrays",
        )
    issues_by_id: dict[str, dict[str, Any]] = {}
    for issue_index, issue in enumerate(full_issues):
        if type(issue) is not dict:
            v2_raise_allowed_terminal_error(
                error_type,
                f"{label} full issue {issue_index} is not an exact object",
            )
        issue_id = dict.get(issue, "id")
        if (
            type(issue_id) is not str
            or not issue_id
            or issue_id in issues_by_id
        ):
            v2_raise_allowed_terminal_error(
                error_type,
                f"{label} full issue {issue_index} has an invalid ID",
            )
        issues_by_id[issue_id] = issue
    for index, row in enumerate(rows):
        if type(row) is not dict:
            v2_raise_allowed_terminal_error(
                error_type,
                f"{label} row {index} is not an exact object",
            )
        issue_id = dict.get(row, "id")
        if type(issue_id) is not str or not issue_id:
            v2_raise_allowed_terminal_error(
                error_type,
                f"{label} row {index} has an invalid ID",
            )
        issue = dict.get(issues_by_id, issue_id)
        value_roots = (
            dict.get(issue, "released_field_value_roots")
            if issue is not None
            else None
        )
        if issue is None or type(value_roots) is not dict:
            v2_raise_allowed_terminal_error(
                error_type,
                f"{label} row {index} is absent from full issue projections"
            )
        if relation_counts:
            dependencies = dict.get(issue, "dependencies")
            dependents = dict.get(issue, "dependents")
            if type(dependencies) is not list or type(dependents) is not list:
                v2_raise_allowed_terminal_error(
                    error_type,
                    f"{label} row {issue_id} relations are malformed",
                )
            if (
                dict.get(row, "dependency_count") != len(dependencies)
                or dict.get(row, "dependent_count") != len(dependents)
            ):
                v2_raise_allowed_terminal_error(
                    error_type,
                    f"{label} row {issue_id} relation counts differ",
                )
        for field in dict.__iter__(row):
            value = dict.__getitem__(row, field)
            if field in {"dependency_count", "dependent_count"}:
                continue
            if field == "source_repo_path" and type(value) is dict:
                issue_path = dict.get(issue, "source_repo_path")
                if (
                    set(value) != V2_RETAINED_BR_PATH_RECEIPT_FIELDS
                    or dict.get(value, "body_retained") is not False
                    or type(issue_path) is not dict
                    or set(issue_path) != {"body_retained", "root"}
                    or dict.get(issue_path, "body_retained") is not False
                    or dict.get(value, "text_root")
                    != dict.get(issue_path, "root")
                ):
                    v2_raise_allowed_terminal_error(
                        error_type,
                        f"{label} row {issue_id}/{field} receipt differs "
                        "from show"
                    )
                observed_value_root = dict.get(value, "value_root")
            else:
                observed_value_root = semantic_root(value)
            if dict.get(value_roots, field) != observed_value_root:
                v2_raise_allowed_terminal_error(
                    error_type,
                    f"{label} row {issue_id}/{field} differs from show"
                )


def v2_capture_state(
    *,
    issue_ids: Sequence[str],
    full_issues: Sequence[Mapping[str, Any]],
    lint: Mapping[str, Any],
    tracker_status: Mapping[str, Any],
    tracker_ready_issue_ids: Sequence[str],
    sync_status: Mapping[str, Any],
    export_witness: Mapping[str, Any],
    version: Mapping[str, Any],
    capabilities: Mapping[str, Any],
    source_files: Sequence[Mapping[str, Any]],
    rule_contract: Mapping[str, Any],
    case_manifest_root: str,
    case_manifest_content_identity: str,
    listed_rows: Sequence[Mapping[str, Any]],
    tombstone_rows: Sequence[Mapping[str, Any]],
    tracker_ready_rows: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    for field_label, field_value, field_cap in (
        ("issue IDs", issue_ids, V2_INVENTORY_ROWS_CAP),
        ("full issues", full_issues, V2_INVENTORY_ROWS_CAP),
        (
            "tracker ready issue IDs",
            tracker_ready_issue_ids,
            V2_INVENTORY_ROWS_CAP,
        ),
        ("source files", source_files, V2_BUNDLE_FILES_CAP),
        ("listed rows", listed_rows, V2_INVENTORY_ROWS_CAP),
        ("tombstone rows", tombstone_rows, V2_INVENTORY_ROWS_CAP),
        (
            "tracker ready rows",
            tracker_ready_rows,
            V2_INVENTORY_ROWS_CAP,
        ),
    ):
        if type(field_value) is not list:
            raise EvidenceFailed(
                f"v2 capture-state {field_label} are not an exact list"
            )
        if list.__len__(field_value) > field_cap:
            raise EvidenceFailed(
                f"v2 capture-state {field_label} exceed their cap"
            )
    for field_label, field_value in (
        ("lint", lint),
        ("tracker status", tracker_status),
        ("sync status", sync_status),
        ("export witness", export_witness),
        ("version", version),
        ("capabilities", capabilities),
        ("rule contract", rule_contract),
    ):
        if type(field_value) is not dict:
            raise EvidenceFailed(
                f"v2 capture-state {field_label} is not an exact object"
            )
    for field_label, field_value in (
        ("manifest root", case_manifest_root),
        ("manifest content identity", case_manifest_content_identity),
    ):
        if type(field_value) is not str or not v2_is_semantic_root(
            field_value
        ):
            raise EvidenceFailed(
                f"v2 capture-state {field_label} is not canonical"
            )
    detached_inputs = v2_released_json_snapshot(
        {
            "issue_ids": issue_ids,
            "full_issues": full_issues,
            "lint": lint,
            "tracker_status": tracker_status,
            "tracker_ready_issue_ids": tracker_ready_issue_ids,
            "sync_status": sync_status,
            "export_witness": export_witness,
            "version": version,
            "capabilities": capabilities,
            "source_files": source_files,
            "rule_contract": rule_contract,
            "case_manifest_root": case_manifest_root,
            "case_manifest_content_identity": (
                case_manifest_content_identity
            ),
            "listed_rows": listed_rows,
            "tombstone_rows": tombstone_rows,
            "tracker_ready_rows": tracker_ready_rows,
        },
        label="v2 capture-state inputs",
        error_type=EvidenceFailed,
    )
    if type(detached_inputs) is not dict:
        raise EvidenceFailed("v2 capture-state snapshot is malformed")
    issue_ids = dict.__getitem__(detached_inputs, "issue_ids")
    full_issues = dict.__getitem__(detached_inputs, "full_issues")
    lint = dict.__getitem__(detached_inputs, "lint")
    tracker_status = dict.__getitem__(detached_inputs, "tracker_status")
    tracker_ready_issue_ids = dict.__getitem__(
        detached_inputs,
        "tracker_ready_issue_ids",
    )
    sync_status = dict.__getitem__(detached_inputs, "sync_status")
    export_witness = dict.__getitem__(detached_inputs, "export_witness")
    version = dict.__getitem__(detached_inputs, "version")
    capabilities = dict.__getitem__(detached_inputs, "capabilities")
    source_files = dict.__getitem__(detached_inputs, "source_files")
    rule_contract = dict.__getitem__(detached_inputs, "rule_contract")
    case_manifest_root = dict.__getitem__(
        detached_inputs,
        "case_manifest_root",
    )
    case_manifest_content_identity = dict.__getitem__(
        detached_inputs,
        "case_manifest_content_identity",
    )
    listed_rows = dict.__getitem__(detached_inputs, "listed_rows")
    tombstone_rows = dict.__getitem__(detached_inputs, "tombstone_rows")
    tracker_ready_rows = dict.__getitem__(
        detached_inputs,
        "tracker_ready_rows",
    )
    if (
        type(issue_ids) is not list
        or type(full_issues) is not list
        or type(lint) is not dict
        or type(tracker_status) is not dict
        or type(tracker_ready_issue_ids) is not list
        or type(sync_status) is not dict
        or type(export_witness) is not dict
        or type(version) is not dict
        or type(capabilities) is not dict
        or type(source_files) is not list
        or type(rule_contract) is not dict
        or type(case_manifest_root) is not str
        or type(case_manifest_content_identity) is not str
        or type(listed_rows) is not list
        or type(tombstone_rows) is not list
        or type(tracker_ready_rows) is not list
    ):
        raise EvidenceFailed(
            "v2 capture-state inputs have malformed outer containers"
        )
    if any(type(value) is not str for value in issue_ids):
        raise EvidenceFailed("v2 capture issue IDs are not exact strings")
    normalized_ids = list(issue_ids)
    if normalized_ids != sorted(normalized_ids):
        raise EvidenceFailed("v2 capture issue IDs must be sorted")
    v2_assert_unique(normalized_ids, label="v2 capture issue IDs")
    if any(type(value) is not dict for value in full_issues):
        raise EvidenceFailed("v2 capture full issues are not exact objects")
    normalized_issues = list(full_issues)
    normalized_listed_rows = v2_normalize_retained_br_rows(
        listed_rows,
        label="v2 capture listed",
        relation_counts=True,
        error_type=EvidenceFailed,
    )
    normalized_tombstone_rows = v2_normalize_retained_br_rows(
        tombstone_rows,
        label="v2 capture tombstone",
        relation_counts=True,
        error_type=EvidenceFailed,
    )
    normalized_ready_rows = v2_normalize_retained_br_rows(
        tracker_ready_rows,
        label="v2 capture ready",
        relation_counts=False,
        error_type=EvidenceFailed,
    )
    if any(
        type(value) is not str
        for value in tracker_ready_issue_ids
    ):
        raise EvidenceFailed(
            "v2 capture ready issue IDs are not exact strings"
        )
    normalized_ready_ids = list(tracker_ready_issue_ids)
    full_ids = [dict.get(value, "id") for value in normalized_issues]
    if (
        any(type(value) is not str or not value for value in full_ids)
        or len(full_ids) != len(set(full_ids))
        or sorted(full_ids) != normalized_ids
    ):
        raise EvidenceFailed(
            "v2 capture full-issue membership differs from list membership"
        )
    if (
        normalized_ready_ids != sorted(normalized_ready_ids)
        or len(normalized_ready_ids) != len(set(normalized_ready_ids))
        or bool(set(normalized_ready_ids) - set(normalized_ids))
    ):
        raise EvidenceFailed(
            "v2 capture ready membership is noncanonical or outside source"
        )
    v2_validate_tracker_ready_membership(
        normalized_issues,
        normalized_ready_ids,
        error_type=EvidenceFailed,
    )
    listed_ids = [dict.get(row, "id") for row in normalized_listed_rows]
    tombstone_ids = [
        dict.get(row, "id") for row in normalized_tombstone_rows
    ]
    if (
        any(type(value) is not str or not value for value in listed_ids)
        or any(type(value) is not str or not value for value in tombstone_ids)
        or listed_ids != sorted(listed_ids)
        or tombstone_ids != sorted(tombstone_ids)
        or len(listed_ids) != len(set(listed_ids))
        or len(tombstone_ids) != len(set(tombstone_ids))
        or set(listed_ids) & set(tombstone_ids)
        or sorted([*listed_ids, *tombstone_ids]) != normalized_ids
    ):
        raise EvidenceFailed(
            "v2 capture list-row membership differs from issue IDs"
        )
    ready_row_ids = [dict.get(row, "id") for row in normalized_ready_rows]
    if ready_row_ids != normalized_ready_ids:
        raise EvidenceFailed(
            "v2 capture ready-row membership differs from ready IDs"
        )
    v2_validate_capture_row_coherence(
        [*normalized_listed_rows, *normalized_tombstone_rows],
        normalized_issues,
        label="v2 capture list rows",
        relation_counts=True,
    )
    v2_validate_capture_row_coherence(
        normalized_ready_rows,
        normalized_issues,
        label="v2 capture ready rows",
        relation_counts=False,
    )
    document = {
        "issue_ids": normalized_ids,
        "issue_count": len(normalized_ids),
        "issue_ids_root": semantic_root(normalized_ids),
        "listed_rows_root": semantic_root(normalized_listed_rows),
        "tombstone_rows_root": semantic_root(normalized_tombstone_rows),
        "full_issue_projection_root": semantic_root(
            sorted(normalized_issues, key=lambda row: str(row["id"]))
        ),
        "lint_projection_root": semantic_root(lint),
        "tracker_status_root": semantic_root(
            v2_br_status_identity_projection(
                tracker_status,
                error_type=EvidenceFailed,
            )
        ),
        "tracker_ready_issue_ids_root": semantic_root(
            normalized_ready_ids
        ),
        "tracker_ready_rows_root": semantic_root(normalized_ready_rows),
        "sync_status_root": semantic_root(sync_status),
        "export_witness_root": semantic_root(export_witness),
        "br_version_root": semantic_root(version),
        "br_capabilities_root": semantic_root(capabilities),
        "source_files_root": semantic_root(source_files),
        "rule_contract_root": semantic_root(rule_contract),
        "case_manifest_root": case_manifest_root,
        "case_manifest_content_identity": case_manifest_content_identity,
    }
    return v2_rooted(document)


def v2_validate_capture_pair(
    before: Mapping[str, Any],
    after: Mapping[str, Any],
) -> str:
    detached = v2_released_json_snapshot(
        {"before": before, "after": after},
        label="v2 coherent capture pair",
        error_type=InputRefused,
    )
    if type(detached) is not dict:
        raise InputRefused("v2 coherent capture pair snapshot is malformed")
    before = dict.__getitem__(detached, "before")
    after = dict.__getitem__(detached, "after")
    if type(before) is not dict or type(after) is not dict:
        raise InputRefused("v2 coherent capture states are not exact objects")
    v2_exact_keys(before, V2_CAPTURE_STATE_KEYS, label="v2 capture before")
    v2_exact_keys(after, V2_CAPTURE_STATE_KEYS, label="v2 capture after")
    verify_semantic_root(before, label="v2 capture before")
    verify_semantic_root(after, label="v2 capture after")
    if before != after:
        changed = sorted(
            key
            for key in V2_CAPTURE_STATE_KEYS - {"semantic_root"}
            if before[key] != after[key]
        )
        raise InputRefused(
            "ConcurrentDrift: v2 coherent capture changed dimensions "
            f"{changed}"
        )
    return str(after["semantic_root"])


def v2_validate_source_capture_contract(
    capture_contract: Any,
    *,
    audit_capture: Mapping[str, Any],
    coherent_capture_root: str,
) -> None:
    if not v2_is_semantic_root(coherent_capture_root):
        raise InputRefused(
            "v2 source coherent capture root is not canonical"
        )
    detached = v2_released_json_snapshot(
        {
            "capture_contract": capture_contract,
            "audit_capture": audit_capture,
        },
        label="v2 source capture contract inputs",
        error_type=InputRefused,
    )
    if type(detached) is not dict:
        raise InputRefused("v2 source capture contract snapshot is malformed")
    capture_contract = dict.__getitem__(detached, "capture_contract")
    audit_capture = dict.__getitem__(detached, "audit_capture")
    if type(capture_contract) is not dict:
        raise InputRefused("v2 source capture contract is not an object")
    if type(audit_capture) is not dict:
        raise InputRefused("v2 source audit capture is not an object")
    v2_exact_keys(
        capture_contract,
        V2_SOURCE_CAPTURE_CONTRACT_FIELDS,
        label="v2 source capture contract",
    )
    if (
        capture_contract["count"] != 2
        or capture_contract["coherent"] is not True
        or capture_contract["tracker_cli"] != "br"
        or capture_contract["direct_tracker_file_access"] is not False
        or capture_contract["network_access"] is not False
    ):
        raise InputRefused("v2 source capture contract scalars differ")
    bracket = dict.__getitem__(capture_contract, "audit_bracket")
    if type(bracket) is not dict:
        raise InputRefused("v2 source audit bracket is not an object")
    v2_exact_keys(
        bracket,
        V2_AUDIT_BRACKET_FIELDS,
        label="v2 source audit bracket",
    )
    verify_semantic_root(bracket, label="v2 source audit bracket")
    verify_semantic_root(
        audit_capture,
        label="v2 source audit capture contract input",
    )
    not_requested = dict.__contains__(audit_capture, "state")
    v2_exact_keys(
        audit_capture,
        (
            V2_AUDIT_CAPTURE_NOT_REQUESTED_FIELDS
            if not_requested
            else V2_AUDIT_CAPTURE_FIELDS
        ),
        label="v2 source audit capture contract input",
    )
    if (
        not_requested
        and (
            dict.__getitem__(audit_capture, "state") != "NOT_REQUESTED"
            or dict.__getitem__(audit_capture, "capture_count") != 0
        )
    ) or (
        not not_requested
        and dict.__getitem__(audit_capture, "capture_count") != 2
    ):
        raise InputRefused("v2 source audit capture state differs")
    expected = v2_rooted(
        {
            "state": "NOT_REQUESTED" if not_requested else "CAPTURED",
            "position": V2_AUDIT_CAPTURE_POSITION,
            "source_before_ordinal": 1,
            "source_after_ordinal": 2,
            "audit_capture_ordinals": [] if not_requested else [1, 2],
            "source_before_root": coherent_capture_root,
            "source_after_root": coherent_capture_root,
            "audit_capture_root": dict.__getitem__(
                audit_capture,
                "semantic_root",
            ),
            "no_claim": V2_AUDIT_BRACKET_NO_CLAIM,
        }
    )
    if bracket != expected:
        divergence = first_projection_divergence(expected, bracket)
        raise InputRefused(
            "v2 source audit bracket differs at "
            f"{divergence or '$'}"
        )


def collect_live(case_manifest: Mapping[str, Any]) -> LiveSnapshot:
    status = br_read_json("status", "--json", "--no-activity")
    sync_status_before = br_read_json("sync", "--status", "--json")
    export_witness_before = br_read_json("sync", "--witness", "--json")
    version = br_version()
    capabilities = br_capabilities()
    files_before = source_file_identities()
    list_before_document = br_read_json(
        "list",
        "--all",
        "--deferred",
        "--json",
        "--limit",
        "0",
    )
    list_before = normalize_document(list_before_document, label="br list before")
    list_projection_before = [
        canonical_issue_projection(issue) for issue in list_before
    ]
    list_root_before = semantic_root(list_projection_before)
    independent_before = {
        issue["id"]: findings
        for issue in list_projection_before
        if (findings := independent_template_findings(issue))
    }

    lint_before = lint_scopes()
    issue_ids_before = sorted(
        set(lint_result_map(lint_before)) | set(independent_before)
    )
    issues_before = show_issues(issue_ids_before)
    independent_show_before = {
        issue["id"]: findings
        for issue in issues_before
        if (findings := independent_template_findings(issue))
    }
    issue_root_before = semantic_root(issues_before)

    list_after_document = br_read_json(
        "list",
        "--all",
        "--deferred",
        "--json",
        "--limit",
        "0",
    )
    list_after = normalize_document(list_after_document, label="br list after")
    list_projection_after = [
        canonical_issue_projection(issue) for issue in list_after
    ]
    list_root_after = semantic_root(list_projection_after)
    independent_after = {
        issue["id"]: findings
        for issue in list_projection_after
        if (findings := independent_template_findings(issue))
    }
    lint_after = lint_scopes()
    issue_ids_after = sorted(
        set(lint_result_map(lint_after)) | set(independent_after)
    )
    issues_after = show_issues(issue_ids_after)
    independent_show_after = {
        issue["id"]: findings
        for issue in issues_after
        if (findings := independent_template_findings(issue))
    }
    issue_root_after = semantic_root(issues_after)
    sync_status_after = br_read_json("sync", "--status", "--json")
    export_witness_after = br_read_json("sync", "--witness", "--json")
    files_after = source_file_identities()

    if (
        list_root_before != list_root_after
        or issue_root_before != issue_root_after
        or issue_ids_before != issue_ids_after
        or independent_before != independent_after
        or independent_before != independent_show_before
        or independent_after != independent_show_after
        or lint_before != lint_after
        or sync_status_before != sync_status_after
        or export_witness_before != export_witness_after
        or files_before != files_after
    ):
        raise InputRefused(
            "ConcurrentDrift: Beads membership or fields changed during inventory"
        )
    if len(list_before) != len(list_after):
        raise InputRefused("ConcurrentDrift: Beads issue count changed during inventory")
    for issue in issues_after:
        if issue["status"] not in STATUS_SCOPES:
            raise EvidenceFailed(
                f"{issue['id']} has unpartitioned status {issue['status']}"
            )
        if issue["priority"] not in range(5):
            raise EvidenceFailed(
                f"{issue['id']} has unpartitioned priority {issue['priority']}"
            )

    source = {
        "schema": SOURCE_SCHEMA,
        "br_version": version,
        "br_capabilities": capabilities,
        "br_lint_rule": {
            "identity": (
                "beads-rust-lint-description-substring-v"
                f"{version['version']}"
            ),
            "field": "description",
            "matching": "case-insensitive substring; independently checked as Markdown",
            "required_sections_by_type": REQUIRED_SECTIONS_BY_TYPE,
        },
        "case_manifest_root": case_manifest["semantic_root"],
        "live_issue_count": len(list_after),
        "live_issue_projection_root": list_root_after,
        "lint_issue_projection_root": issue_root_after,
        "tracker_status": status if isinstance(status, dict) else {},
        "sync_status": sync_status_after,
        "export_witness": export_witness_after,
        "files": files_after,
        "status_cut": list(LINT_SCOPES),
    }
    source["semantic_root"] = semantic_root(source)
    inventory = assemble_inventory(
        lint_after, issues_after, source, independent_show_after
    )
    plan = build_plan(inventory, issues_after)
    return LiveSnapshot(
        lint_after,
        issues_after,
        source,
        inventory,
        plan,
        tuple(list_projection_after),
    )


def v2_source_rule_contract() -> dict[str, Any]:
    return {
        "required_sections_by_type": {
            issue_type: list(sections)
            for issue_type, sections in dict.items(
                REQUIRED_SECTIONS_BY_TYPE
            )
        },
        "clause_terms": list(CLAUSE_TERMS),
        "classifier": "independent-template-findings-v2",
    }


def v2_validate_manifest_source_identity(
    source_files: Any,
    *,
    manifest_content_identity: str,
    label: str,
    error_type: type[HarnessError],
) -> None:
    v2_require_allowed_terminal_error_type(
        error_type,
        label="manifest source identity error type",
    )
    if type(label) is not str or not label:
        raise EvidenceFailed("manifest source identity label is malformed")
    if type(source_files) is not list:
        v2_raise_allowed_terminal_error(
            error_type,
            f"{label} source files are not an exact list",
        )
    if list.__len__(source_files) > V2_BUNDLE_FILES_CAP:
        v2_raise_allowed_terminal_error(
            error_type,
            f"{label} source files exceed their cap",
        )
    if (
        type(manifest_content_identity) is not str
        or not v2_is_semantic_root(manifest_content_identity)
    ):
        v2_raise_allowed_terminal_error(
            error_type,
            f"{label} manifest content identity is malformed",
        )
    manifest_rows = [
        row
        for row in list.__iter__(source_files)
        if type(row) is dict
        and dict.get(row, "path") == CASE_MANIFEST_V2_REL_TEXT
    ]
    if (
        len(manifest_rows) != 1
        or dict.get(manifest_rows[0], "content_identity")
        != manifest_content_identity
    ):
        v2_raise_allowed_terminal_error(
            error_type,
            f"{label} manifest identity changed",
        )


def v2_not_requested_audit_capture() -> dict[str, Any]:
    return v2_rooted(
        {
            "state": "NOT_REQUESTED",
            "capture_count": 0,
            "issue_ids": [],
            "documents": [],
            "command_receipts": [],
            "raw_stream_bodies_retained": False,
            "no_claim": V2_AUDIT_NOT_REQUESTED_NO_CLAIM,
        }
    )


def v2_capture_live_round(
    case_manifest: Mapping[str, Any],
    rule_contract: Mapping[str, Any],
    *,
    ordinal: int,
    br_cwd: Path = REPO_ROOT,
) -> V2LiveCaptureRound:
    if type(ordinal) is not int or ordinal not in {1, 2}:
        raise EvidenceFailed("v2 source capture ordinal must be one or two")
    case_manifest = v2_released_json_snapshot(
        case_manifest,
        label="v2 live capture case manifest",
        error_type=InputRefused,
    )
    if type(case_manifest) is not dict:
        raise InputRefused(
            "v2 live capture case manifest is not an exact object"
        )
    try:
        case_manifest = v2_clone_runner_manifest(case_manifest)
    except EvidenceFailed as error:
        raise InputRefused(
            "v2 live capture case manifest contract is malformed"
        ) from error
    manifest_content_identity = dict.get(
        case_manifest,
        "content_identity",
    )
    if (
        not v2_is_semantic_root(manifest_content_identity)
        or dict.get(case_manifest, "schema") != V2_MANIFEST_SCHEMA
        or dict.get(case_manifest, "manifest_path")
        != CASE_MANIFEST_V2_REL_TEXT
        or dict.get(case_manifest, "harness_path") != SCRIPT_REL_TEXT
    ):
        raise EvidenceFailed(
            "v2 live capture case manifest identity is malformed"
        )
    rule_contract = v2_released_json_snapshot(
        rule_contract,
        label="v2 live capture rule contract",
        error_type=InputRefused,
    )
    if type(rule_contract) is not dict:
        raise InputRefused("v2 live capture rule contract is not an exact object")
    if rule_contract != v2_source_rule_contract():
        raise InputRefused(
            "v2 live capture rule contract differs from the canonical rules"
        )
    workspace_root = Path(br_cwd).resolve()
    source_files_before = (
        v2_source_file_identities() if ordinal == 1 else None
    )
    if source_files_before is not None:
        v2_validate_manifest_source_identity(
            source_files_before,
            manifest_content_identity=manifest_content_identity,
            label="ConcurrentDrift: v2 live capture preflight",
            error_type=InputRefused,
        )
    receipt_start = len(_command_receipts)
    status = v2_normalize_br_status(
        br_read_json(
            "status",
            "--json",
            "--no-activity",
            br_cwd=br_cwd,
        ),
        error_type=InfrastructureFailed,
    )
    sync_status = v2_normalize_br_sync_status(
        br_read_json(
            "sync",
            "--status",
            "--json",
            br_cwd=br_cwd,
        ),
        input_kind="released_live",
        error_type=InfrastructureFailed,
    )
    export_witness = v2_normalize_br_export_witness(
        br_read_json(
            "sync",
            "--witness",
            "--json",
            br_cwd=br_cwd,
        ),
        input_kind="released_live",
        workspace_root=workspace_root,
        expected_chunk_size_lines=(
            V2_BR_WITNESS_CAPTURE_CHUNK_SIZE_LINES
        ),
        expected_max_parallelism=(
            V2_BR_WITNESS_CAPTURE_MAX_PARALLELISM
        ),
        error_type=InfrastructureFailed,
    )
    version = br_version(br_cwd=br_cwd)
    capabilities = br_capabilities(br_cwd=br_cwd)
    listed = br_read_json(
        "list",
        "--all",
        "--json",
        "--limit",
        "0",
        br_cwd=br_cwd,
    )
    raw_listed_rows = v2_normalize_released_br_list_rows(
        listed,
        label=f"v2 br list capture {ordinal}",
    )
    listed_issue_ids = [row["id"] for row in raw_listed_rows]
    tombstones = br_read_json(
        "list",
        "--status",
        "tombstone",
        "--json",
        "--limit",
        "0",
        br_cwd=br_cwd,
    )
    raw_tombstone_rows = v2_normalize_released_br_list_rows(
        tombstones,
        label=f"v2 br tombstone list capture {ordinal}",
    )
    tombstone_issue_ids = [row["id"] for row in raw_tombstone_rows]
    issue_ids = v2_validate_issue_universe_membership(
        listed_issue_ids=listed_issue_ids,
        tombstone_issue_ids=tombstone_issue_ids,
        tracker_status=status,
        br_version=version["version"],
    )
    ready_document = br_read_json(
        "ready",
        "--json",
        "--limit",
        "0",
        br_cwd=br_cwd,
    )
    raw_tracker_ready_rows = v2_normalize_released_br_ready_rows(
        ready_document,
        label=f"v2 br ready capture {ordinal}",
    )
    tracker_ready_issue_ids = [row["id"] for row in raw_tracker_ready_rows]
    if (
        not set(tracker_ready_issue_ids).issubset(listed_issue_ids)
        or len(tracker_ready_issue_ids)
        != status["summary"]["ready_issues"]
    ):
        raise InfrastructureFailed(
            "released br ready membership disagrees with list/status source"
        )
    full_issues = v2_show_all_issues(issue_ids, br_cwd=br_cwd)
    v2_validate_source_graph(full_issues)
    v2_validate_capture_row_coherence(
        [
            row
            for source_rows in (raw_listed_rows, raw_tombstone_rows)
            for row in source_rows
        ],
        full_issues,
        label=f"ConcurrentDrift: v2 list capture {ordinal}",
        relation_counts=True,
        error_type=InputRefused,
    )
    v2_validate_capture_row_coherence(
        raw_tracker_ready_rows,
        full_issues,
        label=f"ConcurrentDrift: v2 ready capture {ordinal}",
        relation_counts=False,
        error_type=InputRefused,
    )
    listed_rows = [
        v2_retain_released_br_row(row) for row in raw_listed_rows
    ]
    tombstone_rows = [
        v2_retain_released_br_row(row) for row in raw_tombstone_rows
    ]
    tracker_ready_rows = [
        v2_retain_released_br_row(row)
        for row in raw_tracker_ready_rows
    ]
    lint_status_scopes = v2_canonical_status_scopes(
        [
            status_value
            for status_values in (
                V2_RELEASED_KNOWN_STATUSES,
                tuple(issue["status"] for issue in full_issues),
            )
            for status_value in status_values
        ],
        error_type=InfrastructureFailed,
    )
    lint = lint_scopes(
        br_cwd=br_cwd,
        status_scopes=lint_status_scopes,
    )
    v2_validate_lint_scope_coherence(
        lint,
        full_issues=full_issues,
        error_type=InfrastructureFailed,
    )
    source_files = (
        source_files_before
        if source_files_before is not None
        else v2_source_file_identities()
    )
    v2_validate_manifest_source_identity(
        source_files,
        manifest_content_identity=manifest_content_identity,
        label="ConcurrentDrift: v2 live capture",
        error_type=InputRefused,
    )
    v2_validate_live_envelope_consistency(
        tracker_status=status,
        sync_status=sync_status,
        export_witness=export_witness,
        full_issues=full_issues,
        error_type=InfrastructureFailed,
    )
    capture_state = v2_capture_state(
        issue_ids=issue_ids,
        full_issues=full_issues,
        lint=lint,
        tracker_status=status,
        tracker_ready_issue_ids=tracker_ready_issue_ids,
        sync_status=sync_status,
        export_witness=export_witness,
        version=version,
        capabilities=capabilities,
        source_files=source_files,
        rule_contract=rule_contract,
        case_manifest_root=dict.__getitem__(case_manifest, "semantic_root"),
        case_manifest_content_identity=manifest_content_identity,
        listed_rows=listed_rows,
        tombstone_rows=tombstone_rows,
        tracker_ready_rows=tracker_ready_rows,
    )
    projection_entries = v2_observation_command_projection_entries(
        tracker_status=status,
        tracker_ready_issue_ids=tracker_ready_issue_ids,
        sync_status=sync_status,
        export_witness=export_witness,
        version=version,
        capabilities=capabilities,
        issue_ids=issue_ids,
        listed_rows=listed_rows,
        tombstone_rows=tombstone_rows,
        tracker_ready_rows=tracker_ready_rows,
        full_issues=full_issues,
        lint=lint,
    )
    round_receipts = _command_receipts[receipt_start:]
    if len(round_receipts) != len(projection_entries):
        raise InfrastructureFailed(
            "v2 live capture receipt count differs from normalized "
            "command projections"
        )
    for receipt, projection in zip(
        round_receipts,
        projection_entries,
        strict=True,
    ):
        receipt.update(
            {
                "capture_ordinal": ordinal,
                "projection_kind": projection["projection_kind"],
                "normalized_projection_root": projection[
                    "normalized_projection_root"
                ],
            }
        )
    detached_round_receipts = v2_released_json_snapshot(
        round_receipts,
        label=f"v2 live capture round {ordinal} command receipts",
        error_type=EvidenceFailed,
    )
    if (
        type(detached_round_receipts) is not list
        or len(detached_round_receipts) > V2_LOG_EVENTS_CAP
        or any(
            type(receipt) is not dict
            for receipt in detached_round_receipts
        )
    ):
        raise EvidenceFailed(
            f"v2 live capture round {ordinal} command receipts are malformed"
        )
    return V2LiveCaptureRound(
        ordinal=ordinal,
        issue_ids=tuple(issue_ids),
        listed_rows=tuple(listed_rows),
        tombstone_rows=tuple(tombstone_rows),
        full_issues=tuple(full_issues),
        lint=lint,
        tracker_status=status,
        tracker_ready_rows=tuple(tracker_ready_rows),
        tracker_ready_issue_ids=tuple(tracker_ready_issue_ids),
        sync_status=sync_status,
        export_witness=export_witness,
        version=version,
        capabilities=capabilities,
        source_files=tuple(source_files),
        rule_contract=rule_contract,
        case_manifest_root=dict.__getitem__(case_manifest, "semantic_root"),
        case_manifest_content_identity=manifest_content_identity,
        command_receipts=tuple(detached_round_receipts),
        capture_state=capture_state,
    )


def _v2_build_audit_bracket_from_fields(
    before_fields: dict[str, Any],
    after_fields: dict[str, Any],
    audit_capture: Mapping[str, Any],
) -> dict[str, Any]:
    if type(before_fields) is not dict or type(after_fields) is not dict:
        raise EvidenceFailed("v2 audit bracket fields are not exact objects")
    before_ordinal = dict.__getitem__(before_fields, "ordinal")
    after_ordinal = dict.__getitem__(after_fields, "ordinal")
    before_issue_ids = dict.__getitem__(before_fields, "issue_ids")
    after_issue_ids = dict.__getitem__(after_fields, "issue_ids")
    if (
        type(before_ordinal) is not int
        or type(after_ordinal) is not int
        or before_ordinal != 1
        or after_ordinal != 2
    ):
        raise EvidenceFailed("v2 audit bracket source ordinals differ")
    if (
        type(before_issue_ids) is not list
        or type(after_issue_ids) is not list
        or before_issue_ids != after_issue_ids
        or len(before_issue_ids) > V2_INVENTORY_ROWS_CAP
        or any(type(issue_id) is not str for issue_id in before_issue_ids)
    ):
        raise EvidenceFailed("v2 audit bracket issue membership differs")
    try:
        audit_capture, _audit_receipts = v2_validate_audit_capture(
            audit_capture,
            allowed_issue_ids=set(before_issue_ids),
        )
    except InputRefused as error:
        raise EvidenceFailed(
            "v2 bracketed audit capture is malformed"
        ) from error
    coherent_capture_root = v2_validate_capture_pair(
        dict.__getitem__(before_fields, "capture_state"),
        dict.__getitem__(after_fields, "capture_state"),
    )
    not_requested = dict.__contains__(audit_capture, "state")
    if (
        (
            not_requested
            and dict.__getitem__(audit_capture, "capture_count") != 0
        )
        or (
            not not_requested
            and dict.__getitem__(audit_capture, "capture_count") != 2
        )
    ):
        raise EvidenceFailed("v2 bracketed audit capture count differs")
    return v2_rooted(
        {
            "state": "NOT_REQUESTED" if not_requested else "CAPTURED",
            "position": V2_AUDIT_CAPTURE_POSITION,
            "source_before_ordinal": 1,
            "source_after_ordinal": 2,
            "audit_capture_ordinals": [] if not_requested else [1, 2],
            "source_before_root": coherent_capture_root,
            "source_after_root": coherent_capture_root,
            "audit_capture_root": dict.__getitem__(
                audit_capture,
                "semantic_root",
            ),
            "no_claim": V2_AUDIT_BRACKET_NO_CLAIM,
        }
    )


def v2_build_audit_bracket(
    before: V2LiveCaptureRound,
    after: V2LiveCaptureRound,
    audit_capture: Mapping[str, Any],
) -> dict[str, Any]:
    before_fields = v2_exact_live_capture_round(
        before,
        label="v2 audit bracket before round",
    )
    after_fields = v2_exact_live_capture_round(
        after,
        label="v2 audit bracket after round",
    )
    return _v2_build_audit_bracket_from_fields(
        before_fields,
        after_fields,
        audit_capture,
    )


def v2_finalize_live_capture_pair(
    case_manifest: Mapping[str, Any],
    *,
    before: V2LiveCaptureRound,
    after: V2LiveCaptureRound,
    audit_capture: Mapping[str, Any],
) -> LiveSnapshot:
    before_fields = v2_exact_live_capture_round(
        before,
        label="v2 finalizer before round",
    )
    after_fields = v2_exact_live_capture_round(
        after,
        label="v2 finalizer after round",
    )
    case_manifest = v2_released_json_snapshot(
        case_manifest,
        label="v2 finalizer case manifest",
        error_type=InputRefused,
    )
    if type(case_manifest) is not dict:
        raise InputRefused("v2 finalizer case manifest is not an exact object")
    try:
        case_manifest = v2_clone_runner_manifest(case_manifest)
    except EvidenceFailed as error:
        raise InputRefused(
            "v2 finalizer case manifest contract is malformed"
        ) from error
    manifest_content_identity = dict.get(
        case_manifest,
        "content_identity",
    )
    if (
        not v2_is_semantic_root(manifest_content_identity)
        or dict.get(case_manifest, "schema") != V2_MANIFEST_SCHEMA
        or dict.get(case_manifest, "manifest_path")
        != CASE_MANIFEST_V2_REL_TEXT
        or dict.get(case_manifest, "harness_path") != SCRIPT_REL_TEXT
    ):
        raise InputRefused(
            "v2 finalizer case manifest identity is malformed"
        )
    captured_manifest_root = dict.__getitem__(
        after_fields,
        "case_manifest_root",
    )
    captured_manifest_content_identity = dict.__getitem__(
        after_fields,
        "case_manifest_content_identity",
    )
    if (
        dict.__getitem__(before_fields, "case_manifest_root")
        != captured_manifest_root
        or dict.__getitem__(
            before_fields,
            "case_manifest_content_identity",
        )
        != captured_manifest_content_identity
        or dict.__getitem__(case_manifest, "semantic_root")
        != captured_manifest_root
        or manifest_content_identity != captured_manifest_content_identity
    ):
        raise InputRefused(
            "ConcurrentDrift: v2 finalizer manifest differs from capture"
        )
    v2_validate_manifest_source_identity(
        dict.__getitem__(after_fields, "source_files"),
        manifest_content_identity=manifest_content_identity,
        label="ConcurrentDrift: v2 finalizer",
        error_type=InputRefused,
    )
    coherent_capture_root = v2_validate_capture_pair(
        dict.__getitem__(before_fields, "capture_state"),
        dict.__getitem__(after_fields, "capture_state"),
    )
    audit_bracket = _v2_build_audit_bracket_from_fields(
        before_fields,
        after_fields,
        audit_capture,
    )
    full_after = dict.__getitem__(after_fields, "full_issues")
    if len(full_after) > V2_INVENTORY_ROWS_CAP:
        raise InputRefused(
            f"v2 source exceeds {V2_INVENTORY_ROWS_CAP} issue rows"
        )
    for issue in full_after:
        v2_validate_status(
            issue["status"],
            label=f"{issue['id']} source status",
            error_type=EvidenceFailed,
        )
        if issue["priority"] not in range(5):
            raise EvidenceFailed(
                f"{issue['id']} has unpartitioned priority {issue['priority']}"
            )
    independent = {
        issue["id"]: findings
        for issue in full_after
        if (findings := independent_template_findings(issue))
    }
    after_lint = dict.__getitem__(after_fields, "lint")
    lint_ids = set(lint_result_map(after_lint))
    nonclosed_ids = {
        str(issue["id"])
        for issue in full_after
        if not v2_is_terminal_status(issue["status"])
    }
    finding_ids = lint_ids | set(independent)
    full_by_id = {issue["id"]: issue for issue in full_after}
    tombstone_finding_ids = sorted(
        issue_id
        for issue_id in finding_ids
        if full_by_id[issue_id]["status"] == "tombstone"
    )
    if tombstone_finding_ids:
        raise NoData(
            "UnsupportedCapability: tombstone template findings require a "
            "deleted-record adjudication contract; first issue "
            f"{tombstone_finding_ids[0]}"
        )
    reviewable_finding_ids = {
        issue_id
        for issue_id in finding_ids
        if full_by_id[issue_id]["status"] != "tombstone"
    }
    target_ids = sorted(nonclosed_ids | reviewable_finding_ids)
    target_issues = [full_by_id[issue_id] for issue_id in target_ids]
    if (
        _command_receipts is not V2_INITIAL_COMMAND_RECEIPTS
        or type(_command_receipts) is not list
    ):
        raise EvidenceFailed(
            "v2 finalizer command-receipt storage identity drifted"
        )
    detached_ambient_command_receipts = v2_released_json_snapshot(
        _command_receipts,
        label="v2 finalizer ambient command receipts",
        error_type=EvidenceFailed,
    )
    if (
        type(detached_ambient_command_receipts) is not list
        or any(
            type(receipt) is not dict
            for receipt in detached_ambient_command_receipts
        )
    ):
        raise EvidenceFailed(
            "v2 finalizer ambient command receipts are malformed"
        )
    captured_command_receipts = [
        *dict.__getitem__(before_fields, "command_receipts"),
        *dict.__getitem__(after_fields, "command_receipts"),
    ]
    if (
        len(captured_command_receipts) > V2_LOG_EVENTS_CAP
        or detached_ambient_command_receipts != captured_command_receipts
    ):
        raise EvidenceFailed(
            "v2 finalizer ambient command receipts differ from captured rounds"
        )
    command_receipts = [
        {**receipt, "capture_sequence": index}
        for index, receipt in enumerate(captured_command_receipts)
    ]
    source: dict[str, Any] = {
        "schema": V2_SOURCE_SCHEMA,
        "capture_contract": {
            "count": 2,
            "coherent": True,
            "tracker_cli": "br",
            "direct_tracker_file_access": False,
            "network_access": False,
            "audit_bracket": audit_bracket,
        },
        "br_version": dict.__getitem__(after_fields, "version"),
        "br_capabilities": dict.__getitem__(after_fields, "capabilities"),
        "tracker_status": dict.__getitem__(after_fields, "tracker_status"),
        "tracker_list_rows": dict.__getitem__(after_fields, "listed_rows"),
        "tracker_list_rows_root": semantic_root(
            dict.__getitem__(after_fields, "listed_rows")
        ),
        "tracker_tombstone_rows": dict.__getitem__(
            after_fields,
            "tombstone_rows",
        ),
        "tracker_tombstone_rows_root": semantic_root(
            dict.__getitem__(after_fields, "tombstone_rows")
        ),
        "tracker_ready_rows": dict.__getitem__(
            after_fields,
            "tracker_ready_rows",
        ),
        "tracker_ready_issue_ids": dict.__getitem__(
            after_fields,
            "tracker_ready_issue_ids",
        ),
        "tracker_ready_issue_ids_root": semantic_root(
            dict.__getitem__(after_fields, "tracker_ready_issue_ids")
        ),
        "tracker_ready_rows_root": semantic_root(
            dict.__getitem__(after_fields, "tracker_ready_rows")
        ),
        "sync_status": dict.__getitem__(after_fields, "sync_status"),
        "export_witness": dict.__getitem__(after_fields, "export_witness"),
        "case_manifest_root": dict.__getitem__(
            case_manifest,
            "semantic_root",
        ),
        "case_manifest_content_identity": dict.__getitem__(
            case_manifest,
            "content_identity",
        ),
        "coherent_capture_root": coherent_capture_root,
        "source_files": dict.__getitem__(after_fields, "source_files"),
        "rule_contract_root": semantic_root(
            dict.__getitem__(after_fields, "rule_contract")
        ),
        "live_issue_count": len(full_after),
        "live_issue_projection_root": semantic_root(full_after),
        "lint_issue_ids_root": semantic_root(sorted(lint_ids)),
        "independent_finding_issue_ids_root": semantic_root(sorted(independent)),
        "nonclosed_issue_ids_root": semantic_root(sorted(nonclosed_ids)),
        "selected_review_issue_ids_root": semantic_root(target_ids),
        "selected_review_issue_count": len(target_ids),
        "nonclosed_issue_count": len(nonclosed_ids),
        "closed_finding_issue_count": len(
            reviewable_finding_ids - nonclosed_ids
        ),
        "status_cut": list(
            v2_canonical_status_scopes(
                [scope for scope in after_lint if scope != "all"]
            )
        ),
        "command_receipts": [
            receipt for receipt in command_receipts
        ],
        "no_claim": V2_SOURCE_OBSERVATION_NO_CLAIM,
    }
    try:
        v2_validate_source_command_receipts(
            source,
            issue_ids=[issue["id"] for issue in full_after],
            full_issues=full_after,
            lint=after_lint,
        )
    except InputRefused as error:
        raise EvidenceFailed(
            "v2 finalizer command receipts differ from captured source"
        ) from error
    source["semantic_root"] = semantic_root(source)
    inventory = assemble_inventory(
        after_lint,
        target_issues,
        source,
        independent,
        include_issue_rows_without_findings=True,
    )
    plan = build_plan(inventory, target_issues)
    return LiveSnapshot(
        after_lint,
        target_issues,
        source,
        inventory,
        plan,
        tuple(full_after),
    )


def v2_issue_matches_source_filters(
    issue: Mapping[str, Any],
    *,
    priority_filter: set[str] | None,
    status_filter: set[str] | None,
    target_filter: set[str] | None,
) -> bool:
    issue_id = str(issue["id"])
    return (
        (priority_filter is None or f"P{issue['priority']}" in priority_filter)
        and (status_filter is None or issue["status"] in status_filter)
        and (target_filter is None or issue_id in target_filter)
    )


def v2_exact_string_set_snapshot(
    values: Any,
    *,
    label: str,
    cap: int,
    error_type: type[HarnessError],
) -> set[str]:
    """Detach one bounded exact-string set without consuming mixed epochs."""
    v2_require_allowed_terminal_error_type(
        error_type,
        label="exact string-set error type",
    )
    if type(label) is not str or not label or type(cap) is not int or cap < 0:
        raise EvidenceFailed("exact string-set contract is malformed")
    if type(values) is not set:
        v2_raise_allowed_terminal_error(
            error_type,
            f"{label} is not an exact set",
        )
        raise EvidenceFailed("unreachable exact string-set type branch")
    declared_count = set.__len__(values)
    if declared_count > cap:
        v2_raise_allowed_terminal_error(
            error_type,
            f"{label} exceeds its cap",
        )
    try:
        first_epoch = list(set.__iter__(values))
    except RuntimeError as error:
        try:
            v2_raise_allowed_terminal_error(
                error_type,
                f"{label} changed while being captured",
            )
        except HarnessError as terminal_error:
            raise terminal_error from error
        raise EvidenceFailed("unreachable exact string-set first epoch")
    if any(type(value) is not str for value in first_epoch):
        v2_raise_allowed_terminal_error(
            error_type,
            f"{label} contains a non-exact string",
        )
    ordered = sorted(first_epoch, key=lambda value: str.encode(value, "utf-8"))
    try:
        final_epoch = list(set.__iter__(values))
    except RuntimeError as error:
        try:
            v2_raise_allowed_terminal_error(
                error_type,
                f"{label} changed while being captured",
            )
        except HarnessError as terminal_error:
            raise terminal_error from error
        raise EvidenceFailed("unreachable exact string-set final epoch")
    if (
        len(ordered) != declared_count
        or len(final_epoch) != declared_count
        or any(type(value) is not str for value in final_epoch)
        or sorted(
            final_epoch,
            key=lambda value: str.encode(value, "utf-8"),
        )
        != ordered
    ):
        v2_raise_allowed_terminal_error(
            error_type,
            f"{label} changed while being captured",
        )
    return set(ordered)


def v2_history_audit_ids_from_round(
    capture: V2LiveCaptureRound,
    *,
    manifest: Mapping[str, Any],
    priority_filter: set[str] | None,
    status_filter: set[str] | None,
    target_filter: set[str] | None,
) -> list[str]:
    capture_fields = v2_exact_live_capture_round(
        capture,
        label="v2 history audit source round",
    )
    if dict.__getitem__(capture_fields, "ordinal") != 1:
        raise EvidenceFailed("v2 history audit requires source round one")
    manifest = v2_released_json_snapshot(
        manifest,
        label="v2 history audit case manifest",
        error_type=InputRefused,
    )
    if type(manifest) is not dict:
        raise InputRefused(
            "v2 history audit case manifest is not an exact object"
        )
    verify_semantic_root(manifest, label="v2 history audit case manifest")
    history_contract = dict.get(manifest, "history_contract")
    if type(history_contract) is not dict:
        raise InputRefused("v2 history audit contract is not an exact object")
    anchor = dict.get(history_contract, "legacy_coverage_anchor_issue")
    if type(anchor) is not str or not anchor:
        raise InputRefused("v2 history audit anchor is malformed")
    v2_validate_issue_id(
        anchor,
        label="v2 history audit anchor",
        error_type=InputRefused,
    )
    priority_filter = (
        None
        if priority_filter is None
        else v2_exact_string_set_snapshot(
            priority_filter,
            label="v2 history audit priority filter",
            cap=V2_INVENTORY_ROWS_CAP,
            error_type=InputRefused,
        )
    )
    status_filter = (
        None
        if status_filter is None
        else v2_exact_string_set_snapshot(
            status_filter,
            label="v2 history audit status filter",
            cap=V2_INVENTORY_ROWS_CAP,
            error_type=InputRefused,
        )
    )
    target_filter = (
        None
        if target_filter is None
        else v2_exact_string_set_snapshot(
            target_filter,
            label="v2 history audit target filter",
            cap=V2_INVENTORY_ROWS_CAP,
            error_type=InputRefused,
        )
    )
    if priority_filter is not None and any(
        value not in {"P0", "P1", "P2", "P3", "P4"}
        for value in priority_filter
    ):
        raise InputRefused("v2 history audit priority filter is unknown")
    if status_filter is not None:
        for index, value in enumerate(sorted(status_filter)):
            v2_validate_status(
                value,
                label=f"v2 history audit status filter {index}",
                error_type=InputRefused,
            )
    if target_filter is not None:
        for index, value in enumerate(sorted(target_filter)):
            v2_validate_issue_id(
                value,
                label=f"v2 history audit target filter {index}",
                error_type=InputRefused,
            )
    full_issues = dict.__getitem__(capture_fields, "full_issues")
    lint = dict.__getitem__(capture_fields, "lint")
    issue_ids = dict.__getitem__(capture_fields, "issue_ids")
    independent_ids = {
        issue["id"]
        for issue in full_issues
        if independent_template_findings(issue)
    }
    source_inventory_ids = (
        {
            issue["id"]
            for issue in full_issues
            if not v2_is_terminal_status(issue["status"])
        }
        | set(lint_result_map(lint))
        | independent_ids
    )
    if target_filter is not None:
        unknown_targets = sorted(target_filter - source_inventory_ids)
        if unknown_targets:
            raise UsageRefused(
                "--targets contains IDs outside the exact planner inventory: "
                + ", ".join(unknown_targets)
            )
    audit_ids = {
        issue["id"]
        for issue in full_issues
        if issue["id"] in source_inventory_ids
        and issue["status"] == "closed"
        and v2_issue_matches_source_filters(
            issue,
            priority_filter=priority_filter,
            status_filter=status_filter,
            target_filter=target_filter,
        )
    }
    if anchor not in set(issue_ids):
        raise EvidenceFailed("v2 history anchor is absent from the source capture")
    return sorted(audit_ids | {anchor})


def collect_live_v2(
    case_manifest: Mapping[str, Any],
    *,
    br_cwd: Path = REPO_ROOT,
) -> LiveSnapshot:
    _command_receipts.clear()
    rule_contract = v2_source_rule_contract()
    before = v2_capture_live_round(
        case_manifest,
        rule_contract,
        ordinal=1,
        br_cwd=br_cwd,
    )
    audit_capture = v2_not_requested_audit_capture()
    check_cancel()
    after = v2_capture_live_round(
        case_manifest,
        rule_contract,
        ordinal=2,
        br_cwd=br_cwd,
    )
    check_cancel()
    return v2_finalize_live_capture_pair(
        case_manifest,
        before=before,
        after=after,
        audit_capture=audit_capture,
    )


def partition_projection(inventory: Mapping[str, Any]) -> dict[str, Any]:
    section_codes = {
        "## Acceptance Criteria": ("A", "MissingAcceptanceCriteria"),
        "## Steps to Reproduce": ("S", "MissingStepsToReproduce"),
        "## Success Criteria": ("C", "MissingSuccessCriteria"),
    }
    partition_names = {
        frozenset(("A",)): "A_only",
        frozenset(("S",)): "S_only",
        frozenset(("C",)): "C_only",
        frozenset(("A", "S")): "A_and_S_only",
        frozenset(("A", "C")): "A_and_C_only",
        frozenset(("S", "C")): "S_and_C_only",
        frozenset(("A", "S", "C")): "A_and_S_and_C",
    }
    memberships: dict[str, list[str]] = {"A": [], "S": [], "C": []}
    partitions: dict[str, list[str]] = {
        name: [] for name in partition_names.values()
    }
    warning_rows: list[dict[str, str]] = []
    seen_warning_rows: set[tuple[str, str, str]] = set()
    union_ids: set[str] = set()

    for row in sorted(inventory.get("rows", []), key=lambda value: value["id"]):
        issue_id = str(row["id"])
        codes: set[str] = set()
        for section in sorted(str(value) for value in row["missing_sections"]):
            if section not in section_codes:
                raise EvidenceFailed(
                    f"partition projection has unknown missing section for {issue_id}"
                )
            code, warning_class = section_codes[section]
            identity = (issue_id, warning_class, section)
            if identity in seen_warning_rows:
                raise EvidenceFailed(
                    f"partition projection has duplicate warning row for {issue_id}"
                )
            seen_warning_rows.add(identity)
            codes.add(code)
            memberships[code].append(issue_id)
            warning_rows.append(
                {
                    "issue_id": issue_id,
                    "warning_class": warning_class,
                    "missing_section": section,
                }
            )
        frozen_codes = frozenset(codes)
        if not frozen_codes or frozen_codes not in partition_names:
            raise EvidenceFailed(
                f"partition projection has an empty or unknown warning set for {issue_id}"
            )
        partitions[partition_names[frozen_codes]].append(issue_id)
        union_ids.add(issue_id)

    for values in memberships.values():
        values.sort()
    for values in partitions.values():
        values.sort()
    warning_rows.sort(
        key=lambda row: (
            row["issue_id"],
            row["warning_class"],
            row["missing_section"],
        )
    )
    partition_union = {
        issue_id for values in partitions.values() for issue_id in values
    }
    if partition_union != union_ids:
        first = sorted(partition_union ^ union_ids)[0]
        raise EvidenceFailed(
            f"partition union differs from warning membership at {first}"
        )
    if sum(len(values) for values in partitions.values()) != len(union_ids):
        raise EvidenceFailed("exclusive overlap partitions are not disjoint")
    if len(warning_rows) != int(inventory["counts"]["warnings"]):
        raise EvidenceFailed("partition warning-row arithmetic differs")

    document: dict[str, Any] = {
        "schema": PARTITIONS_SCHEMA,
        "inventory_root": inventory["semantic_root"],
        "sets": memberships,
        "partitions": partitions,
        "warning_rows": warning_rows,
        "counts": {
            "union": len(union_ids),
            "warnings": len(warning_rows),
            "sets": {
                code: len(values) for code, values in sorted(memberships.items())
            },
            "partitions": {
                name: len(values) for name, values in sorted(partitions.items())
            },
        },
        "no_claim": (
            "exact overlap arithmetic classifies membership only and authorizes "
            "no wording, mutation, closure, or product claim"
        ),
    }
    document["semantic_root"] = semantic_root(document)
    return document


def source_artifact(
    *,
    lint: Mapping[str, Any],
    issues: Sequence[Mapping[str, Any]],
    source: Mapping[str, Any],
    independent_findings_by_id: Mapping[str, Mapping[str, str]] | None = None,
) -> dict[str, Any]:
    captured = {
        "lint": lint,
        "issues": list(issues),
        "source": source,
        "independent_findings_by_id": {
            str(issue_id): dict(sorted(findings.items()))
            for issue_id, findings in sorted(
                (independent_findings_by_id or {}).items()
            )
            if findings
        },
    }
    document: dict[str, Any] = {
        "schema": SOURCE_SCHEMA,
        "case_manifest_root": source.get("case_manifest_root"),
        "captured": captured,
        "no_claim": (
            "retained source bytes support deterministic reconstruction only; "
            "they are not producer authentication or current tracker authority"
        ),
    }
    document["semantic_root"] = semantic_root(document)
    return document


def reproduction_argv(
    mode: str,
    artifact_root: str,
    artifact_dir: str,
) -> list[str]:
    if mode not in {"inventory", "plan"}:
        raise EvidenceFailed(f"unsupported evidence-bundle mode {mode!r}")
    return [
        str(SCRIPT_REL),
        f"--{mode}",
        "--artifact-root",
        str(safe_relative(artifact_root, label="artifact root")),
        "--artifact-dir",
        str(safe_relative(artifact_dir, label="artifact dir")),
    ]


def event_rows(
    mode: str,
    inventory: Mapping[str, Any],
    plan: Mapping[str, Any],
    artifact_root: str,
    artifact_dir: str,
) -> list[dict[str, Any]]:
    reproduction = reproduction_argv(mode, artifact_root, artifact_dir)
    proposal_map = {
        row["id"]: row for row in plan.get("section_name_only_proposals", [])
    }
    partitions = partition_projection(inventory)
    source_root = str(inventory["source"]["semantic_root"])
    safe_artifacts = list(RUN_ARTIFACTS)
    rows: list[dict[str, Any]] = []

    def append(
        stage: str,
        *,
        issue: str | None = None,
        warning: Any = None,
        disposition: str | None = None,
        shard: str | None = None,
        old_root: str | None = None,
        new_root: str | None = None,
        command: Sequence[str] = (),
        result: str,
        terminal: str | None = None,
        extra: Mapping[str, Any] | None = None,
    ) -> None:
        row: dict[str, Any] = {
            "schema": EVENT_SCHEMA,
            "tool": "beads-template-hygiene",
            "rule": "br-lint-template-sections-v1",
            "source": source_root,
            "run": artifact_dir,
            "mode": mode,
            "case": "template-lint.inventory-live",
            "attempt": 1,
            "stage": stage,
            "sequence": len(rows),
            "issue": issue,
            "warning": warning,
            "disposition": disposition,
            "shard": shard,
            "old_semantic_root": old_root,
            "new_semantic_root": new_root,
            "command": list(command),
            "result": result,
            "first_divergence": None,
            "caps": {
                "issues": CAPS["issues"],
                "warnings": CAPS["warnings"],
                "plan_shard_rows": CAPS["plan_shard_rows"],
                "apply_rows": CAPS["apply_rows"],
                "events": EVENT_COUNT_CAP,
                "event_line_bytes": EVENT_LINE_CAP,
                "artifact_bytes": RUN_ARTIFACT_CAP,
            },
            "terminal": terminal,
            "inverse_br_command": None,
            "safe_relative_artifacts": safe_artifacts,
            "reproduction": reproduction,
        }
        if extra:
            row.update(extra)
        missing = [field for field in EVENT_REQUIRED_FIELDS if field not in row]
        if missing:
            raise EvidenceFailed(
                f"event {stage} lacks required fields {sorted(missing)}"
            )
        rows.append(row)

    append("start", result="started")
    append(
        "source",
        result="captured",
        extra={
            "case_manifest_root": inventory["tool"]["case_manifest_root"],
            "status_cut": inventory["source"]["status_cut"],
        },
    )
    append(
        "inventory",
        result="assembled",
        extra={
            "inventory_root": inventory["semantic_root"],
            "issues": inventory["counts"]["issues"],
            "warnings": inventory["counts"]["warnings"],
        },
    )
    if mode == "plan" and inventory["rows"]:
        append(
            "join",
            result="joined",
            extra={"issues": inventory["counts"]["issues"]},
        )
    detail_stage = "classify" if mode == "plan" else "join"
    for inventory_row in sorted(inventory["rows"], key=lambda value: value["id"]):
        proposal = proposal_map.get(inventory_row["id"])
        append(
            detail_stage,
            issue=inventory_row["id"],
            warning=list(inventory_row["missing_sections"]),
            disposition=inventory_row["disposition"],
            shard=priority_group(inventory_row["priority"]),
            old_root=inventory_row["field_roots"]["description"],
            new_root=proposal["new_root"] if proposal else None,
            result="classified" if mode == "plan" else "joined",
        )
    if mode == "inventory":
        append(
            "partition",
            result="derived",
            extra={
                "partitions_root": partitions["semantic_root"],
                "partition_counts": partitions["counts"]["partitions"],
            },
        )
    else:
        append(
            "plan",
            result="bounded",
            extra={
                "plan_root": plan["semantic_root"],
                "shards": len(plan["shards"]),
                "max_targets_per_shard": CAPS["plan_shard_rows"],
            },
        )
    append(
        "publish",
        result="sealed",
        extra={
            "inventory_root": inventory["semantic_root"],
            "partitions_root": partitions["semantic_root"],
            "plan_root": plan["semantic_root"],
        },
    )
    append(
        "terminal",
        result="pass",
        terminal="Pass",
        extra={
            "exit_code": TERMINAL_EXIT["Pass"],
            "inventory_root": inventory["semantic_root"],
            "partitions_root": partitions["semantic_root"],
            "plan_root": plan["semantic_root"],
            "case_manifest_root": inventory["tool"]["case_manifest_root"],
            "event_count": len(rows) + 1,
            "no_claim": inventory["no_claim"],
        },
    )
    if len(rows) > EVENT_COUNT_CAP:
        raise EvidenceFailed(f"event stream exceeds {EVENT_COUNT_CAP} events")
    for row in rows:
        if len(canonical_bytes(row)) > EVENT_LINE_CAP:
            raise EvidenceFailed(
                f"event sequence {row['sequence']} exceeds {EVENT_LINE_CAP} bytes"
            )
    return rows


def artifact_identity(name: str, payload: bytes, schema: str) -> str:
    return semantic_root(
        {
            "schema": ARTIFACT_IDENTITY_SCHEMA,
            "content_schema": schema,
            "length": len(payload),
            "relative_path": str(safe_relative(name, label="artifact name")),
            "canonical_bytes_identity": (
                "sha256-v1:" + hashlib.sha256(payload).hexdigest()
            ),
        }
    )


def terminal_artifact(
    *,
    mode: str,
    artifact_root: str,
    artifact_dir: str,
    source: Mapping[str, Any],
    inventory: Mapping[str, Any],
    partitions: Mapping[str, Any],
    plan: Mapping[str, Any],
    event_count: int,
    payloads: Mapping[str, bytes],
) -> dict[str, Any]:
    schema_by_name = {
        "source.json": SOURCE_SCHEMA,
        "inventory.json": INVENTORY_SCHEMA,
        "partitions.json": PARTITIONS_SCHEMA,
        "plan.json": PLAN_SCHEMA,
        "events.jsonl": EVENT_SCHEMA,
        "reproduce.txt": "frankensim.argv-json.v1",
    }
    identities = {
        name: artifact_identity(name, payloads[name], schema_by_name[name])
        for name in sorted(payloads)
    }
    document: dict[str, Any] = {
        "schema": RUN_TERMINAL_SCHEMA,
        "mode": mode,
        "terminal": "Pass",
        "exit_code": TERMINAL_EXIT["Pass"],
        "artifact_root": str(safe_relative(artifact_root, label="artifact root")),
        "artifact_dir": str(safe_relative(artifact_dir, label="artifact dir")),
        "safe_relative_artifacts": list(RUN_ARTIFACTS),
        "artifact_identities": identities,
        "source_root": source["semantic_root"],
        "source_identity_root": inventory["source"]["semantic_root"],
        "case_manifest_root": inventory["tool"]["case_manifest_root"],
        "inventory_root": inventory["semantic_root"],
        "partitions_root": partitions["semantic_root"],
        "plan_root": plan["semantic_root"],
        "event_count": event_count,
        "event_sequence": list(range(event_count)),
        "reproduction": reproduction_argv(mode, artifact_root, artifact_dir),
        "issues": inventory["counts"]["issues"],
        "warnings": inventory["counts"]["warnings"],
        "no_claim": inventory["no_claim"],
    }
    document["semantic_root"] = semantic_root(document)
    return document


def build_run_payloads(
    *,
    mode: str,
    artifact_root: str,
    artifact_dir: str,
    source: Mapping[str, Any],
    inventory: Mapping[str, Any],
    partitions: Mapping[str, Any],
    plan: Mapping[str, Any],
) -> dict[str, bytes]:
    events = event_rows(
        mode,
        inventory,
        plan,
        artifact_root,
        artifact_dir,
    )
    reproduction = canonical_bytes(
        reproduction_argv(mode, artifact_root, artifact_dir)
    )
    payloads: dict[str, bytes] = {
        "source.json": canonical_bytes(source),
        "inventory.json": canonical_bytes(inventory),
        "partitions.json": canonical_bytes(partitions),
        "plan.json": canonical_bytes(plan),
        "events.jsonl": b"".join(canonical_bytes(row) for row in events),
        "reproduce.txt": reproduction,
    }
    terminal = terminal_artifact(
        mode=mode,
        artifact_root=artifact_root,
        artifact_dir=artifact_dir,
        source=source,
        inventory=inventory,
        partitions=partitions,
        plan=plan,
        event_count=len(events),
        payloads=payloads,
    )
    payloads["terminal.json"] = canonical_bytes(terminal)
    if tuple(sorted(payloads)) != tuple(sorted(RUN_ARTIFACTS)):
        raise EvidenceFailed("run payload membership differs from artifact contract")
    for name, payload in payloads.items():
        if len(payload) > RUN_ARTIFACT_CAP:
            raise EvidenceFailed(
                f"artifact {name} exceeds {RUN_ARTIFACT_CAP} byte cap"
            )
    return payloads


def resolve_run_dir(
    artifact_root: str,
    artifact_dir: str,
    *,
    label: str,
    must_exist: bool = False,
) -> Path:
    root_rel = safe_relative(artifact_root, label="artifact root")
    dir_rel = safe_relative(artifact_dir, label=label)
    combined = root_rel / dir_rel
    if len(str(combined).encode("utf-8")) > 512:
        raise UsageRefused(f"{label} exceeds the 512-byte relative path cap")
    return resolve_safe(str(combined), label=label, must_exist=must_exist)


def require_fresh_run_dir(path: Path, *, label: str) -> None:
    if path.exists():
        raise EvidenceFailed(
            f"{label} already exists; overwrite and run-directory reuse are forbidden"
        )


def write_bundle(
    *,
    mode: str,
    artifact_root: str,
    artifact_dir: str,
    snapshot: LiveSnapshot,
) -> dict[str, Any]:
    output = resolve_run_dir(
        artifact_root,
        artifact_dir,
        label="artifact dir",
    )
    independent_findings = {
        str(row["id"]): dict(row.get("independent_findings", {}))
        for row in snapshot.inventory["rows"]
        if row.get("independent_findings")
    }
    retained_source = source_artifact(
        lint=snapshot.lint,
        issues=snapshot.issues,
        source=snapshot.source,
        independent_findings_by_id=independent_findings,
    )
    partitions = partition_projection(snapshot.inventory)
    payloads = build_run_payloads(
        mode=mode,
        artifact_root=artifact_root,
        artifact_dir=artifact_dir,
        source=retained_source,
        inventory=snapshot.inventory,
        partitions=partitions,
        plan=snapshot.plan,
    )
    require_fresh_run_dir(output, label="artifact run directory")
    results = {
        name: write_once(output / name, payloads[name]) for name in sorted(payloads)
    }
    return {
        "terminal": "Pass",
        "mode": mode,
        "artifact_dir": str(
            safe_relative(artifact_root, label="artifact root")
            / safe_relative(artifact_dir, label="artifact dir")
        ),
        "source_root": retained_source["semantic_root"],
        "inventory_root": snapshot.inventory["semantic_root"],
        "partitions_root": partitions["semantic_root"],
        "plan_root": snapshot.plan["semantic_root"],
        "issues": snapshot.inventory["counts"]["issues"],
        "warnings": snapshot.inventory["counts"]["warnings"],
        "writes": results,
        "no_claim": snapshot.inventory["no_claim"],
    }


def read_json_artifact(path: Path) -> Any:
    if path.is_symlink():
        raise InputRefused(
            f"artifact replay first divergence: symlink {path.name}"
        )
    try:
        payload = bounded_read(path, cap=RUN_ARTIFACT_CAP)
        document = json.loads(payload.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise InputRefused(
            f"artifact replay first divergence: malformed {path.name}: {error}"
        ) from error
    if canonical_bytes(document) != payload:
        raise EvidenceFailed(
            f"artifact replay first divergence: non-canonical {path.name}"
        )
    return document


def verify_semantic_root(document: Mapping[str, Any], *, label: str) -> None:
    if type(label) is not str or not label:
        raise EvidenceFailed("semantic-root validation label is malformed")
    document = v2_released_json_snapshot(
        document,
        label="semantic-root document",
        error_type=EvidenceFailed,
    )
    if type(document) is not dict:
        raise EvidenceFailed(f"{label} is not an exact rooted object")
    if "semantic_root" not in document:
        raise EvidenceFailed(f"{label} lacks semantic_root")
    retained = dict.__getitem__(document, "semantic_root")
    if not v2_is_semantic_root(retained):
        raise EvidenceFailed(f"{label}.semantic_root is not canonical")
    unrooted: dict[str, Any] = {}
    for key in dict.__iter__(document):
        if type(key) is not str:
            raise EvidenceFailed(f"{label} has a non-string field")
        if key != "semantic_root":
            unrooted[key] = dict.__getitem__(document, key)
    expected = semantic_root(unrooted)
    if retained != expected:
        raise EvidenceFailed(
            f"artifact replay first divergence: {label}.semantic_root"
        )


def v2_is_semantic_root(value: Any) -> bool:
    return (
        type(value) is str
        and len(value) == len("sha256-v1:") + 64
        and re.fullmatch(r"sha256-v1:[0-9a-f]{64}", value) is not None
    )


def v2_require_semantic_root(value: Any, *, label: str) -> str:
    if not v2_is_semantic_root(value):
        raise EvidenceFailed(f"{label} is not a canonical semantic root")
    return value


def first_projection_divergence(
    expected: Any,
    observed: Any,
    *,
    path: str = "$",
) -> str | None:
    if type(expected) is not type(observed):
        return f"{path}.type"
    if isinstance(expected, dict):
        expected_keys = set(expected)
        observed_keys = set(observed)
        if expected_keys != observed_keys:
            missing = sorted(expected_keys - observed_keys)
            extra = sorted(observed_keys - expected_keys)
            key = (missing or extra)[0]
            return f"{path}.{key}"
        for key in sorted(expected):
            divergence = first_projection_divergence(
                expected[key],
                observed[key],
                path=f"{path}.{key}",
            )
            if divergence is not None:
                return divergence
        return None
    if isinstance(expected, list):
        for index, (left, right) in enumerate(zip(expected, observed)):
            divergence = first_projection_divergence(
                left,
                right,
                path=f"{path}[{index}]",
            )
            if divergence is not None:
                return divergence
        if len(expected) != len(observed):
            return f"{path}[{min(len(expected), len(observed))}]"
        return None
    return None if expected == observed else path


def require_projection_equal(label: str, expected: Any, observed: Any) -> None:
    divergence = first_projection_divergence(expected, observed)
    if divergence is not None:
        raise EvidenceFailed(
            f"artifact replay first divergence: {label}{divergence}"
        )


def require_payload_equal(label: str, expected: bytes, observed: bytes) -> None:
    for index, (left, right) in enumerate(zip(expected, observed)):
        if left != right:
            raise EvidenceFailed(
                f"artifact replay first divergence: {label} byte {index}"
            )
    if len(expected) != len(observed):
        raise EvidenceFailed(
            f"artifact replay first divergence: {label} byte "
            f"{min(len(expected), len(observed))}"
        )


def read_event_artifact(path: Path) -> tuple[list[dict[str, Any]], bytes]:
    if path.is_symlink():
        raise InputRefused("artifact replay first divergence: symlink events.jsonl")
    payload = bounded_read(path, cap=RUN_ARTIFACT_CAP)
    if not payload or not payload.endswith(b"\n"):
        raise EvidenceFailed(
            "artifact replay first divergence: events.jsonl terminal newline"
        )
    lines = payload.splitlines(keepends=True)
    if len(lines) > EVENT_COUNT_CAP:
        raise EvidenceFailed(
            "artifact replay first divergence: events.jsonl event cap"
        )
    rows: list[dict[str, Any]] = []
    for index, line in enumerate(lines):
        if len(line) > EVENT_LINE_CAP:
            raise EvidenceFailed(
                f"artifact replay first divergence: events.jsonl line {index} cap"
            )
        try:
            row = json.loads(line.decode("utf-8"))
        except (UnicodeDecodeError, json.JSONDecodeError) as error:
            raise InputRefused(
                f"artifact replay first divergence: events.jsonl line {index}: {error}"
            ) from error
        if not isinstance(row, dict):
            raise InputRefused(
                f"artifact replay first divergence: events.jsonl line {index} type"
            )
        if canonical_bytes(row) != line:
            raise EvidenceFailed(
                f"artifact replay first divergence: events.jsonl line {index} canonical"
            )
        if row.get("sequence") != index:
            raise EvidenceFailed(
                f"artifact replay first divergence: events.jsonl line {index} sequence"
            )
        missing = [field for field in EVENT_REQUIRED_FIELDS if field not in row]
        if missing:
            raise EvidenceFailed(
                f"artifact replay first divergence: events.jsonl line {index} "
                f"missing {sorted(missing)[0]}"
            )
        if not isinstance(row["command"], list):
            raise EvidenceFailed(
                f"artifact replay first divergence: events.jsonl line {index} command"
            )
        if row["inverse_br_command"] is not None and not isinstance(
            row["inverse_br_command"], list
        ):
            raise EvidenceFailed(
                f"artifact replay first divergence: events.jsonl line {index} inverse"
            )
        if not isinstance(row["reproduction"], list):
            raise EvidenceFailed(
                f"artifact replay first divergence: events.jsonl line {index} reproduction"
            )
        rows.append(row)
    if rows[-1].get("stage") != "terminal" or rows[-1].get("terminal") != "Pass":
        raise EvidenceFailed(
            "artifact replay first divergence: events.jsonl terminal event"
        )
    return rows, payload


def independent_replay_projection(sources: Mapping[str, Any]) -> dict[str, Any]:
    captured: Any = sources.get("captured", sources)
    if sources.get("captured") is not None:
        if sources.get("schema") != SOURCE_SCHEMA:
            raise InputRefused("source artifact has an unknown schema")
        verify_semantic_root(sources, label="source.json")
    if not isinstance(captured, dict):
        raise InputRefused("source artifact lacks a captured object")
    lint = captured.get("lint")
    issues = captured.get("issues")
    source = captured.get("source")
    independent = captured.get("independent_findings_by_id", {})
    if (
        not isinstance(lint, dict)
        or not isinstance(issues, list)
        or not isinstance(source, dict)
        or not isinstance(independent, dict)
    ):
        raise InputRefused(
            "source artifact lacks lint/issues/source/independent findings"
        )
    verify_semantic_root(source, label="source.json.captured.source")
    rebuilt = assemble_inventory(lint, issues, source, independent)

    warning_total = sum(len(row["missing_sections"]) for row in rebuilt["rows"])
    if warning_total != rebuilt["counts"]["warnings"]:
        raise EvidenceFailed(
            "artifact replay first divergence: inventory warning arithmetic"
        )
    if len({row["id"] for row in rebuilt["rows"]}) != rebuilt["counts"]["issues"]:
        raise EvidenceFailed(
            "artifact replay first divergence: inventory issue membership"
        )
    return rebuilt


def replay_reproduction_argv(
    artifact_root: str,
    input_dir: str,
    output_dir: str,
) -> list[str]:
    return [
        str(SCRIPT_REL),
        "--replay",
        str(safe_relative(input_dir, label="replay input")),
        "--artifact-root",
        str(safe_relative(artifact_root, label="artifact root")),
        "--artifact-dir",
        str(safe_relative(output_dir, label="artifact dir")),
    ]


def replay_event_rows(
    *,
    artifact_root: str,
    input_dir: str,
    output_dir: str,
    source: Mapping[str, Any],
    inventory: Mapping[str, Any],
    partitions: Mapping[str, Any],
    plan: Mapping[str, Any],
    retained_events_root: str,
    retained_terminal_root: str,
) -> list[dict[str, Any]]:
    reproduction = replay_reproduction_argv(
        artifact_root,
        input_dir,
        output_dir,
    )
    safe_artifacts = list(RUN_ARTIFACTS)
    rows: list[dict[str, Any]] = []

    def append(
        stage: str,
        *,
        result: str,
        command: Sequence[str] = (),
        terminal: str | None = None,
        extra: Mapping[str, Any] | None = None,
    ) -> None:
        row: dict[str, Any] = {
            "schema": EVENT_SCHEMA,
            "tool": "beads-template-hygiene",
            "rule": "artifact-only-replay-v1",
            "source": source["semantic_root"],
            "run": output_dir,
            "mode": "replay",
            "case": "template-lint.artifact-replay",
            "attempt": 1,
            "stage": stage,
            "sequence": len(rows),
            "issue": None,
            "warning": None,
            "disposition": None,
            "shard": None,
            "old_semantic_root": None,
            "new_semantic_root": None,
            "command": list(command),
            "result": result,
            "first_divergence": None,
            "caps": {
                "events": EVENT_COUNT_CAP,
                "event_line_bytes": EVENT_LINE_CAP,
                "artifact_bytes": RUN_ARTIFACT_CAP,
            },
            "terminal": terminal,
            "inverse_br_command": None,
            "safe_relative_artifacts": safe_artifacts,
            "reproduction": reproduction,
        }
        if extra:
            row.update(extra)
        missing = [field for field in EVENT_REQUIRED_FIELDS if field not in row]
        if missing:
            raise EvidenceFailed(
                f"replay event {stage} lacks required fields {sorted(missing)}"
            )
        rows.append(row)

    append("start", result="started", command=reproduction)
    append(
        "artifact-admission",
        result="admitted",
        extra={
            "input_dir": input_dir,
            "required_artifacts": safe_artifacts,
            "live_br_access": "forbidden-and-not-used",
        },
    )
    append(
        "reconstruct",
        result="reconstructed",
        extra={
            "source_root": source["semantic_root"],
            "inventory_root": inventory["semantic_root"],
            "partitions_root": partitions["semantic_root"],
            "plan_root": plan["semantic_root"],
        },
    )
    append(
        "compare",
        result="equivalent",
        extra={
            "retained_events_root": retained_events_root,
            "reconstructed_events_root": retained_events_root,
            "retained_terminal_root": retained_terminal_root,
            "reconstructed_terminal_root": retained_terminal_root,
        },
    )
    append(
        "publish-disjoint",
        result="ready",
        extra={"input_dir": input_dir, "output_dir": output_dir},
    )
    append(
        "terminal",
        result="pass",
        terminal="Pass",
        extra={
            "exit_code": TERMINAL_EXIT["Pass"],
            "subject_terminal": "REPLAY_EQUIVALENT",
            "event_count": len(rows) + 1,
            "inventory_root": inventory["semantic_root"],
            "partitions_root": partitions["semantic_root"],
            "plan_root": plan["semantic_root"],
            "first_divergence": None,
            "no_claim": (
                "artifact-only replay proves deterministic reconstruction of "
                "the retained projection and mints no authority"
            ),
        },
    )
    for row in rows:
        if len(canonical_bytes(row)) > EVENT_LINE_CAP:
            raise EvidenceFailed(
                f"replay event sequence {row['sequence']} exceeds "
                f"{EVENT_LINE_CAP} bytes"
            )
    return rows


def build_replay_output_payloads(
    *,
    artifact_root: str,
    input_dir: str,
    output_dir: str,
    source: Mapping[str, Any],
    inventory: Mapping[str, Any],
    partitions: Mapping[str, Any],
    plan: Mapping[str, Any],
    retained_events_root: str,
    retained_terminal_root: str,
    retained_artifact_identities: Mapping[str, Any],
) -> dict[str, bytes]:
    events = replay_event_rows(
        artifact_root=artifact_root,
        input_dir=input_dir,
        output_dir=output_dir,
        source=source,
        inventory=inventory,
        partitions=partitions,
        plan=plan,
        retained_events_root=retained_events_root,
        retained_terminal_root=retained_terminal_root,
    )
    reproduction = replay_reproduction_argv(
        artifact_root,
        input_dir,
        output_dir,
    )
    payloads: dict[str, bytes] = {
        "source.json": canonical_bytes(source),
        "inventory.json": canonical_bytes(inventory),
        "partitions.json": canonical_bytes(partitions),
        "plan.json": canonical_bytes(plan),
        "events.jsonl": b"".join(canonical_bytes(row) for row in events),
        "reproduce.txt": canonical_bytes(reproduction),
    }
    schema_by_name = {
        "source.json": SOURCE_SCHEMA,
        "inventory.json": INVENTORY_SCHEMA,
        "partitions.json": PARTITIONS_SCHEMA,
        "plan.json": PLAN_SCHEMA,
        "events.jsonl": EVENT_SCHEMA,
        "reproduce.txt": "frankensim.argv-json.v1",
    }
    output_identities = {
        name: artifact_identity(name, payloads[name], schema_by_name[name])
        for name in sorted(payloads)
    }
    terminal: dict[str, Any] = {
        "schema": RUN_TERMINAL_SCHEMA,
        "mode": "replay",
        "terminal": "Pass",
        "subject_terminal": "REPLAY_EQUIVALENT",
        "exit_code": TERMINAL_EXIT["Pass"],
        "artifact_root": str(safe_relative(artifact_root, label="artifact root")),
        "input_dir": str(safe_relative(input_dir, label="replay input")),
        "artifact_dir": str(safe_relative(output_dir, label="artifact dir")),
        "safe_relative_artifacts": list(RUN_ARTIFACTS),
        "artifact_identities": output_identities,
        "retained_artifact_identities": dict(
            sorted(retained_artifact_identities.items())
        ),
        "source_root": source["semantic_root"],
        "inventory_root": inventory["semantic_root"],
        "partitions_root": partitions["semantic_root"],
        "plan_root": plan["semantic_root"],
        "retained_events_root": retained_events_root,
        "reconstructed_events_root": retained_events_root,
        "retained_terminal_root": retained_terminal_root,
        "reconstructed_terminal_root": retained_terminal_root,
        "event_count": len(events),
        "event_sequence": list(range(len(events))),
        "first_divergence": None,
        "live_br_access": "forbidden-and-not-used",
        "reproduction": reproduction,
        "no_claim": (
            "replay equivalence is deterministic reconstruction evidence, not "
            "authentication, current-state proof, semantic approval, or "
            "capability authority"
        ),
    }
    terminal["semantic_root"] = semantic_root(terminal)
    payloads["terminal.json"] = canonical_bytes(terminal)
    for name, payload in payloads.items():
        if len(payload) > RUN_ARTIFACT_CAP:
            raise EvidenceFailed(
                f"replay artifact {name} exceeds {RUN_ARTIFACT_CAP} byte cap"
            )
    return payloads


def replay_bundle(
    *,
    artifact_root: str,
    input_dir: str,
    output_dir: str,
    case_manifest_root: str | None = None,
) -> dict[str, Any]:
    source_dir = resolve_run_dir(
        artifact_root,
        input_dir,
        label="replay input",
        must_exist=True,
    )
    target_dir = resolve_run_dir(
        artifact_root,
        output_dir,
        label="artifact dir",
    )
    if not source_dir.is_dir():
        raise InputRefused("replay input is not a directory")
    source_resolved = source_dir.resolve(strict=True)
    target_resolved = target_dir.resolve(strict=False)
    if source_resolved == target_resolved:
        raise InputRefused("replay input and output must be disjoint")
    if (
        source_resolved in target_resolved.parents
        or target_resolved in source_resolved.parents
    ):
        raise InputRefused("replay input/output may not contain one another")

    for name in RUN_ARTIFACTS:
        candidate = source_dir / name
        if not candidate.exists():
            raise InputRefused(
                f"artifact replay first divergence: missing {name}"
            )
        if candidate.is_symlink() or not candidate.is_file():
            raise InputRefused(
                f"artifact replay first divergence: unsafe {name}"
            )

    retained_source = read_json_artifact(source_dir / "source.json")
    retained_inventory = read_json_artifact(source_dir / "inventory.json")
    retained_partitions = read_json_artifact(source_dir / "partitions.json")
    retained_plan = read_json_artifact(source_dir / "plan.json")
    retained_terminal = read_json_artifact(source_dir / "terminal.json")
    retained_events, retained_event_bytes = read_event_artifact(
        source_dir / "events.jsonl"
    )
    reproduce_path = source_dir / "reproduce.txt"
    if reproduce_path.is_symlink():
        raise InputRefused(
            "artifact replay first divergence: symlink reproduce.txt"
        )
    retained_reproduce = bounded_read(reproduce_path, cap=RUN_ARTIFACT_CAP)
    try:
        reproduction_document = json.loads(retained_reproduce.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise InputRefused(
            f"artifact replay first divergence: malformed reproduce.txt: {error}"
        ) from error
    if (
        not isinstance(reproduction_document, list)
        or not all(isinstance(value, str) for value in reproduction_document)
        or canonical_bytes(reproduction_document) != retained_reproduce
    ):
        raise EvidenceFailed(
            "artifact replay first divergence: reproduce.txt canonical argv"
        )

    for label, document, schema in (
        ("inventory.json", retained_inventory, INVENTORY_SCHEMA),
        ("partitions.json", retained_partitions, PARTITIONS_SCHEMA),
        ("plan.json", retained_plan, PLAN_SCHEMA),
        ("terminal.json", retained_terminal, RUN_TERMINAL_SCHEMA),
    ):
        if not isinstance(document, dict) or document.get("schema") != schema:
            raise InputRefused(
                f"artifact replay first divergence: {label} schema"
            )
        verify_semantic_root(document, label=label)
    if not isinstance(retained_source, dict):
        raise InputRefused("artifact replay first divergence: source.json type")
    if case_manifest_root is not None and (
        retained_source.get("case_manifest_root") != case_manifest_root
        or retained_terminal.get("case_manifest_root") != case_manifest_root
    ):
        raise EvidenceFailed(
            "artifact replay first divergence: case manifest identity"
        )
    if retained_terminal.get("artifact_root") != str(
        safe_relative(artifact_root, label="artifact root")
    ):
        raise EvidenceFailed(
            "artifact replay first divergence: terminal.json$.artifact_root"
        )
    if retained_terminal.get("artifact_dir") != str(
        safe_relative(input_dir, label="replay input")
    ):
        raise EvidenceFailed(
            "artifact replay first divergence: terminal.json$.artifact_dir"
        )

    rebuilt_inventory = independent_replay_projection(retained_source)
    captured = retained_source["captured"]
    rebuilt_partitions = partition_projection(rebuilt_inventory)
    rebuilt_plan = build_plan(rebuilt_inventory, captured["issues"])
    mode = str(retained_terminal.get("mode") or "")
    expected_retained_payloads = build_run_payloads(
        mode=mode,
        artifact_root=artifact_root,
        artifact_dir=input_dir,
        source=retained_source,
        inventory=rebuilt_inventory,
        partitions=rebuilt_partitions,
        plan=rebuilt_plan,
    )

    require_projection_equal(
        "inventory.json",
        rebuilt_inventory,
        retained_inventory,
    )
    require_projection_equal(
        "partitions.json",
        rebuilt_partitions,
        retained_partitions,
    )
    require_projection_equal("plan.json", rebuilt_plan, retained_plan)
    expected_event_rows = [
        json.loads(line)
        for line in expected_retained_payloads["events.jsonl"]
        .decode("utf-8")
        .splitlines()
    ]
    require_projection_equal(
        "events.jsonl",
        expected_event_rows,
        retained_events,
    )
    require_payload_equal(
        "events.jsonl",
        expected_retained_payloads["events.jsonl"],
        retained_event_bytes,
    )
    require_payload_equal(
        "reproduce.txt",
        expected_retained_payloads["reproduce.txt"],
        retained_reproduce,
    )
    expected_terminal = json.loads(expected_retained_payloads["terminal.json"])
    require_projection_equal(
        "terminal.json",
        expected_terminal,
        retained_terminal,
    )
    retained_payloads = {
        "source.json": canonical_bytes(retained_source),
        "inventory.json": canonical_bytes(retained_inventory),
        "partitions.json": canonical_bytes(retained_partitions),
        "plan.json": canonical_bytes(retained_plan),
        "events.jsonl": retained_event_bytes,
        "terminal.json": canonical_bytes(retained_terminal),
        "reproduce.txt": retained_reproduce,
    }
    for name in RUN_ARTIFACTS:
        require_payload_equal(
            name,
            expected_retained_payloads[name],
            retained_payloads[name],
        )

    retained_events_root = (
        "sha256-v1:" + hashlib.sha256(retained_event_bytes).hexdigest()
    )
    replay_payloads = build_replay_output_payloads(
        artifact_root=artifact_root,
        input_dir=input_dir,
        output_dir=output_dir,
        source=retained_source,
        inventory=rebuilt_inventory,
        partitions=rebuilt_partitions,
        plan=rebuilt_plan,
        retained_events_root=retained_events_root,
        retained_terminal_root=retained_terminal["semantic_root"],
        retained_artifact_identities=retained_terminal["artifact_identities"],
    )
    require_fresh_run_dir(target_dir, label="replay output directory")
    results = {
        name: write_once(target_dir / name, replay_payloads[name])
        for name in sorted(replay_payloads)
    }
    replay_terminal = json.loads(replay_payloads["terminal.json"])
    return {
        "terminal": "Pass",
        "mode": "replay",
        "subject_terminal": "REPLAY_EQUIVALENT",
        "input_dir": str(
            safe_relative(artifact_root, label="artifact root")
            / safe_relative(input_dir, label="replay input")
        ),
        "artifact_dir": str(
            safe_relative(artifact_root, label="artifact root")
            / safe_relative(output_dir, label="artifact dir")
        ),
        "source_root": retained_source["semantic_root"],
        "inventory_root": rebuilt_inventory["semantic_root"],
        "partitions_root": rebuilt_partitions["semantic_root"],
        "plan_root": rebuilt_plan["semantic_root"],
        "retained_events_root": retained_events_root,
        "retained_terminal_root": retained_terminal["semantic_root"],
        "replay_terminal_root": replay_terminal["semantic_root"],
        "first_divergence": None,
        "live_br_access": "forbidden-and-not-used",
        "writes": results,
        "no_claim": (
            "artifact-only replay proves deterministic reconstruction of the "
            "retained projection; it does not authenticate the producer, prove "
            "current tracker state, approve semantics, or mint capability authority"
        ),
    }


def _apply_issue_projection(issue: Mapping[str, Any]) -> dict[str, Any]:
    """Return the exact mutable-state projection, excluding br's update timestamp."""

    def edges(name: str) -> list[dict[str, Any]]:
        return sorted(
            (
                {
                    "id": str(edge.get("id", "")),
                    "type": str(
                        edge.get("dependency_type") or edge.get("type") or ""
                    ),
                    "status": str(edge.get("status", "")),
                    "priority": edge.get("priority"),
                }
                for edge in (issue.get(name) or [])
                if isinstance(edge, dict)
            ),
            key=lambda edge: (edge["type"], edge["id"]),
        )

    return {
        "id": str(issue.get("id", "")),
        "title": str(issue.get("title", "")),
        "type": str(issue.get("issue_type") or issue.get("type") or ""),
        "status": str(issue.get("status", "")),
        "priority": issue.get("priority"),
        "assignee": str(issue.get("assignee") or ""),
        "owner": str(issue.get("owner") or ""),
        "parent": str(issue.get("parent") or ""),
        "labels": sorted(str(label) for label in (issue.get("labels") or [])),
        "description": str(issue.get("description") or ""),
        "acceptance_criteria": str(issue.get("acceptance_criteria") or ""),
        "design": str(issue.get("design") or ""),
        "notes": str(issue.get("notes") or ""),
        "estimated_minutes": issue.get("estimated_minutes"),
        "dependencies": edges("dependencies"),
        "dependents": edges("dependents"),
    }


def _recovery_br_command(
    argv: Sequence[str],
    *,
    input_text: str | None = None,
) -> subprocess.CompletedProcess[str]:
    """Run a bounded br recovery command even after cancellation was requested."""

    return run_command(
        argv,
        input_text=input_text,
        expected=range(-255, 256),
        honor_cancel=False,
        record_global_receipt=False,
    )


def _read_apply_issue(issue_id: str, *, recovery: bool = False) -> dict[str, Any]:
    if recovery:
        completed = _recovery_br_command(
            ("br", "show", issue_id, "--json", *BR_READ_FLAGS)
        )
        if completed.returncode != 0:
            raise InfrastructureFailed(
                f"br recovery show returned {completed.returncode}; "
                "raw diagnostic body withheld"
            )
        try:
            document = json.loads(completed.stdout)
        except json.JSONDecodeError as error:
            raise InfrastructureFailed(
                f"br recovery show emitted malformed JSON for {issue_id}"
            ) from error
    else:
        document = br_read_json("show", issue_id, "--json")
    if not isinstance(document, list) or len(document) != 1:
        raise InfrastructureFailed(
            f"br show did not return exactly the explicit target {issue_id}"
        )
    if not isinstance(document[0], dict):
        raise InfrastructureFailed(f"br show returned a malformed row for {issue_id}")
    projection = _apply_issue_projection(document[0])
    if projection["id"] != issue_id:
        raise InfrastructureFailed(
            f"br show returned {projection['id']!r} for explicit target {issue_id}"
        )
    return projection


def _apply_update_argv(issue_id: str, agent_name: str) -> tuple[str, ...]:
    return (
        "br",
        "update",
        issue_id,
        "--description-file",
        "-",
        "--agent-name",
        agent_name,
        "--json",
    )


def _validate_update_stdout(
    completed: subprocess.CompletedProcess[str],
    issue_id: str,
) -> HarnessError | None:
    if completed.returncode != 0:
        detail = completed.stderr.strip().splitlines()
        named = detail[0][:240] if detail else "no diagnostic"
        return InfrastructureFailed(
            f"br update returned {completed.returncode} for {issue_id}: {named}"
        )
    try:
        parsed = json.loads(completed.stdout)
    except json.JSONDecodeError:
        return InfrastructureFailed(
            f"br update committed-state output was malformed for {issue_id}"
        )
    if not isinstance(parsed, (dict, list)) or not parsed:
        return InfrastructureFailed(f"br update returned no row for {issue_id}")
    return None


def _restore_apply_target(
    *,
    issue_id: str,
    agent_name: str,
    inverse_value: str,
    before_projection: Mapping[str, Any],
    after_projection: Mapping[str, Any],
) -> dict[str, Any]:
    before_root = semantic_root(before_projection)
    after_root = semantic_root(after_projection)
    current = _read_apply_issue(issue_id, recovery=True)
    current_root = semantic_root(current)
    if current_root == before_root:
        return {
            "state": "already-restored",
            "issue": issue_id,
            "before_root": before_root,
            "observed_root": current_root,
            "inverse_invoked": False,
            "verified": True,
        }
    if current_root != after_root:
        raise EvidenceFailed(
            f"{issue_id} has concurrent drift; exact-root restoration is unsafe"
        )

    completed = _recovery_br_command(
        _apply_update_argv(issue_id, agent_name),
        input_text=inverse_value,
    )
    output_failure = _validate_update_stdout(completed, issue_id)
    restored = _read_apply_issue(issue_id, recovery=True)
    restored_root = semantic_root(restored)
    if restored_root != before_root:
        detail = f"; transport={output_failure}" if output_failure else ""
        raise EvidenceFailed(
            f"{issue_id} inverse did not restore its exact pre-run root{detail}"
        )
    return {
        "state": "restored",
        "issue": issue_id,
        "before_root": before_root,
        "after_root": after_root,
        "observed_root": restored_root,
        "inverse_invoked": True,
        "inverse_stdout_valid": output_failure is None,
        "verified": True,
    }


def _apply_output_directory(
    artifact_root: str,
    artifact_dir: str,
    artifact_names: Sequence[str],
) -> tuple[Path, PurePosixPath]:
    root_rel = safe_relative(artifact_root, label="artifact root")
    output_rel = safe_relative(artifact_dir, label="artifact dir")
    combined = root_rel / output_rel
    output = resolve_safe(str(combined), label="apply artifact directory")
    if output.exists():
        raise InputRefused(
            f"apply artifact run directory already exists: {combined}"
        )
    for name in artifact_names:
        path = output / name
        if path.exists():
            raise InputRefused(
                f"refusing pre-existing apply artifact: {combined / name}"
            )
    return output, combined


def validate_apply_manifest(
    document: Mapping[str, Any],
    snapshot: LiveSnapshot,
) -> list[dict[str, Any]]:
    if document.get("schema") != APPLY_SCHEMA:
        raise InputRefused("apply manifest has an unknown schema")
    if document.get("inventory_root") != snapshot.inventory["semantic_root"]:
        raise InputRefused("apply manifest targets a stale inventory root")
    if document.get("plan_root") != snapshot.plan["semantic_root"]:
        raise InputRefused("apply manifest targets a stale plan root")
    if document.get("reviewed") is not True:
        raise InputRefused("apply manifest is not explicitly reviewed")
    reviewed_by = str(document.get("reviewed_by") or "").strip()
    agent_name = str(document.get("agent_name") or "").strip()
    if not reviewed_by:
        raise InputRefused("apply manifest lacks reviewed_by")
    if not agent_name:
        raise InputRefused("apply manifest lacks an explicit agent_name")
    if not str(document.get("reservation_receipt") or "").strip():
        raise InputRefused("apply manifest lacks a reservation receipt")

    rows = document.get("rows")
    if not isinstance(rows, list) or len(rows) != 1:
        raise InputRefused("V1 apply manifest must contain exactly one target row")
    if CAPS["apply_rows"] != 1:
        raise EvidenceFailed("V1 apply atomicity cap is not exactly one")
    if not isinstance(rows[0], dict):
        raise InputRefused("apply manifest target row is malformed")
    row = dict(rows[0])
    issue_id = str(row.get("id") or "")
    if not issue_id or document.get("target_id") != issue_id:
        raise InputRefused("apply manifest lacks one matching explicit target_id")
    if row.get("reviewed") is not True:
        raise InputRefused(f"{issue_id} row is not explicitly reviewed")
    if str(row.get("reviewed_by") or "").strip() != reviewed_by:
        raise InputRefused(f"{issue_id} row reviewed_by binding differs")
    if str(row.get("agent_name") or "").strip() != agent_name:
        raise InputRefused(f"{issue_id} row agent_name binding differs")

    inventory_rows = {candidate["id"]: candidate for candidate in snapshot.inventory["rows"]}
    live_issues = {candidate["id"]: candidate for candidate in snapshot.issues}
    proposal_rows = {
        candidate["id"]: candidate
        for candidate in snapshot.plan.get("section_name_only_proposals", [])
        if isinstance(candidate, dict) and candidate.get("id")
    }
    if issue_id not in inventory_rows or issue_id not in live_issues:
        raise InputRefused(f"apply target is outside the frozen inventory: {issue_id}")
    if issue_id not in proposal_rows:
        raise InputRefused(f"apply target lacks a current plan proposal: {issue_id}")

    inventory_row = inventory_rows[issue_id]
    live_issue = live_issues[issue_id]
    current_reviewers = {
        str(value).strip()
        for value in (live_issue.get("assignee"), live_issue.get("owner"))
        if str(value or "").strip()
    }
    if not current_reviewers or reviewed_by not in current_reviewers:
        raise InputRefused(
            f"{issue_id} reviewed_by is not the current assignee or owner"
        )
    if (
        str(document.get("current_owner") or "").strip() != reviewed_by
        or str(row.get("current_owner") or "").strip() != reviewed_by
    ):
        raise InputRefused(f"{issue_id} current-owner review binding differs")
    if inventory_row["status"] in {"deferred", "closed"}:
        raise InputRefused(
            f"{issue_id} status {inventory_row['status']} forbids V1 apply"
        )
    if inventory_row["disposition"] != "SECTION_NAME_ONLY":
        raise InputRefused(f"{issue_id} live disposition is not SECTION_NAME_ONLY")
    authority_domain = str(inventory_row.get("authority_domain") or "")
    if (
        document.get("authority_domain") != authority_domain
        or row.get("authority_domain") != authority_domain
    ):
        raise InputRefused(f"{issue_id} authority-domain binding differs")

    proposal = proposal_rows[issue_id]
    proposal_root = semantic_root(proposal)
    if (
        document.get("proposal_root") != proposal_root
        or row.get("proposal_root") != proposal_root
    ):
        raise InputRefused(f"{issue_id} proposal-root binding differs")
    proposal_fields = (
        "id",
        "disposition",
        "field",
        "missing_section",
        "old_root",
        "new_root",
        "old_value",
        "new_value",
        "inverse_value",
        "rationale",
    )
    for field in proposal_fields:
        if row.get(field) != proposal.get(field):
            raise InputRefused(f"{issue_id} differs from current proposal field {field}")

    old = str(live_issues[issue_id]["description"])
    new = str(row["new_value"])
    inverse = str(row["inverse_value"])
    if row["field"] != "description":
        raise InputRefused(f"{issue_id} may update only description")
    if row["old_root"] != text_root(old) or row["old_value"] != old:
        raise InputRefused(f"{issue_id} old field binding drifted")
    if row["new_root"] != text_root(new):
        raise InputRefused(f"{issue_id} new field root is inconsistent")
    if inverse != old:
        raise InputRefused(f"{issue_id} inverse does not exactly restore old text")
    if len(new.encode("utf-8")) > CAPS["field_bytes"]:
        raise InputRefused(f"{issue_id} proposed field exceeds cap")
    if old and not all(fragment in new for fragment in old.splitlines() if fragment):
        raise InputRefused(f"{issue_id} proposed field loses existing scope")
    section = str(row["missing_section"])
    if not section_present(new, section):
        raise InputRefused(f"{issue_id} proposed field lacks {section}")
    return [row]


def apply_reviewed_manifest(
    *,
    manifest_rel: str,
    artifact_root: str,
    artifact_dir: str,
    snapshot: LiveSnapshot,
) -> dict[str, Any]:
    manifest_path = resolve_safe(manifest_rel, label="apply manifest", must_exist=True)
    try:
        document = json.loads(bounded_read(manifest_path).decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as error:
        raise InputRefused(f"apply manifest is malformed: {error}") from error
    if not isinstance(document, dict):
        raise InputRefused("apply manifest root must be an object")
    rows = validate_apply_manifest(document, snapshot)
    row = rows[0]
    issue_id = str(row["id"])
    agent_name = str(document["agent_name"]).strip()
    reviewed_by = str(document["reviewed_by"]).strip()
    proposal_root = str(document["proposal_root"])
    manifest_root = semantic_root(document)
    artifact_names = (
        *RUN_ARTIFACTS,
        "apply-manifest.json",
        "inverse-br.json",
        "restoration.json",
    )
    output, output_rel = _apply_output_directory(
        artifact_root, artifact_dir, artifact_names
    )
    frozen_issue = _apply_issue_projection(
        {candidate["id"]: candidate for candidate in snapshot.issues}[issue_id]
    )

    # This read is the apply authority. The retained snapshot alone is never
    # allowed to authorize a mutation.
    before = _read_apply_issue(issue_id)
    before_root = semantic_root(before)
    if before_root != semantic_root(frozen_issue):
        raise InputRefused(f"{issue_id} drifted before apply pre-observation")
    after = dict(before)
    after["description"] = str(row["new_value"])
    after_root = semantic_root(after)
    forward_argv = _apply_update_argv(issue_id, agent_name)
    inverse_argv = _apply_update_argv(issue_id, agent_name)
    inverse_artifact = {
        "schema": "frankensim.beads-template-hygiene.inverse-br.v1",
        "manifest_root": manifest_root,
        "inventory_root": snapshot.inventory["semantic_root"],
        "plan_root": snapshot.plan["semantic_root"],
        "proposal_root": proposal_root,
        "target_id": issue_id,
        "reviewed_by": reviewed_by,
        "agent_name": agent_name,
        "before_issue_root": before_root,
        "planned_after_issue_root": after_root,
        "commands": [
            {
                "argv": list(inverse_argv),
                "stdin": str(row["inverse_value"]),
                "stdin_root": text_root(str(row["inverse_value"])),
                "expected_before_root": after_root,
                "expected_after_root": before_root,
            }
        ],
        "execution_order": "reverse",
        "retained_before_forward_mutation": True,
    }
    independent_findings = {
        str(candidate["id"]): dict(candidate.get("independent_findings", {}))
        for candidate in snapshot.inventory["rows"]
        if candidate.get("independent_findings")
    }
    retained_source = source_artifact(
        lint=snapshot.lint,
        issues=snapshot.issues,
        source=snapshot.source,
        independent_findings_by_id=independent_findings,
    )
    partitions = partition_projection(snapshot.inventory)
    reproduce_argv = [
        str(SCRIPT_REL),
        "--apply-manifest",
        manifest_rel,
        "--artifact-root",
        artifact_root,
        "--artifact-dir",
        artifact_dir,
    ]

    events: list[dict[str, Any]] = []

    def append_event(
        stage: str,
        *,
        result: str,
        command: Sequence[str] = (),
        inverse_command: Sequence[str] | None = None,
        terminal: str | None = None,
        old_root: str | None = None,
        new_root: str | None = None,
        extra: Mapping[str, Any] | None = None,
    ) -> None:
        event: dict[str, Any] = {
            "schema": EVENT_SCHEMA,
            "tool": "beads-template-hygiene",
            "rule": "reviewed-single-target-br-apply-v1",
            "source": retained_source["semantic_root"],
            "run": str(output_rel),
            "mode": "apply",
            "case": "template-lint.br-only-apply",
            "attempt": 1,
            "stage": stage,
            "sequence": len(events),
            "issue": issue_id,
            "warning": row["missing_section"],
            "disposition": row["disposition"],
            "shard": priority_group(
                {
                    candidate["id"]: candidate
                    for candidate in snapshot.inventory["rows"]
                }[issue_id]["priority"]
            ),
            "old_semantic_root": old_root,
            "new_semantic_root": new_root,
            "command": list(command),
            "result": result,
            "first_divergence": None,
            "caps": {
                "apply_rows": CAPS["apply_rows"],
                "events": EVENT_COUNT_CAP,
                "event_line_bytes": EVENT_LINE_CAP,
                "artifact_bytes": RUN_ARTIFACT_CAP,
            },
            "terminal": terminal,
            "inverse_br_command": (
                list(inverse_command) if inverse_command is not None else None
            ),
            "safe_relative_artifacts": list(artifact_names),
            "reproduction": reproduce_argv,
        }
        if extra:
            event.update(extra)
        missing = [field for field in EVENT_REQUIRED_FIELDS if field not in event]
        if missing:
            raise EvidenceFailed(
                f"apply event {stage} lacks required fields {sorted(missing)}"
            )
        if len(events) >= EVENT_COUNT_CAP:
            raise EvidenceFailed(f"apply event stream exceeds {EVENT_COUNT_CAP} events")
        if len(canonical_bytes(event)) > EVENT_LINE_CAP:
            raise EvidenceFailed(
                f"apply event sequence {event['sequence']} exceeds "
                f"{EVENT_LINE_CAP} bytes"
            )
        events.append(event)

    pre_payloads = {
        "source.json": canonical_bytes(retained_source),
        "inventory.json": canonical_bytes(snapshot.inventory),
        "partitions.json": canonical_bytes(partitions),
        "plan.json": canonical_bytes(snapshot.plan),
        "apply-manifest.json": canonical_bytes(document),
        "inverse-br.json": canonical_bytes(inverse_artifact),
        "reproduce.txt": canonical_bytes(reproduce_argv),
    }
    for name, payload in pre_payloads.items():
        if len(payload) > RUN_ARTIFACT_CAP:
            raise EvidenceFailed(
                f"apply pre-mutation artifact {name} exceeds its cap"
            )
    writes = {
        name: write_once(output / name, payload)
        for name, payload in sorted(pre_payloads.items())
    }

    # Retaining evidence is work between reads, so repeat the exact read guard
    # immediately before the only forward mutation.
    guarded_before = _read_apply_issue(issue_id)
    if semantic_root(guarded_before) != before_root:
        raise InputRefused(f"{issue_id} drifted after inverse retention")

    append_event(
        "start",
        result="admitted",
        extra={
            "inventory_root": snapshot.inventory["semantic_root"],
            "plan_root": snapshot.plan["semantic_root"],
            "proposal_root": proposal_root,
            "manifest_root": manifest_root,
        },
    )
    append_event(
        "source",
        result="captured",
        extra={"source_root": retained_source["semantic_root"]},
    )
    append_event(
        "inventory",
        result="bound",
        extra={"inventory_root": snapshot.inventory["semantic_root"]},
    )
    append_event("join", result="one-explicit-target")
    append_event("classify", result="section-name-only")
    append_event(
        "plan",
        result="exact-current-root-bound",
        extra={
            "plan_root": snapshot.plan["semantic_root"],
            "proposal_root": proposal_root,
        },
    )
    append_event(
        "reserve",
        result="receipt-bound-and-inverse-retained",
        inverse_command=inverse_argv,
        extra={
            "reservation_receipt": str(document["reservation_receipt"]),
            "inverse_artifact": str(output_rel / "inverse-br.json"),
        },
    )
    append_event(
        "pre-observe",
        result="exact-root-match",
        command=["br", "show", issue_id, "--json", *BR_READ_FLAGS],
        inverse_command=inverse_argv,
        old_root=before_root,
        new_root=after_root,
    )

    forward_attempted = False
    committed = False
    failure: HarnessError | None = None
    restoration: dict[str, Any] | None = None
    try:
        completed: subprocess.CompletedProcess[str] | None = None
        transport_failure: HarnessError | None = None
        try:
            forward_attempted = True
            completed = run_command(forward_argv, input_text=str(row["new_value"]))
        except HarnessError as error:
            transport_failure = error
        if completed is not None:
            output_failure = _validate_update_stdout(completed, issue_id)
            if output_failure is not None:
                transport_failure = output_failure

        # The command may have committed even when its return code or JSON
        # transport failed. Always decide from the exact immediate read.
        observed_after = _read_apply_issue(
            issue_id, recovery=_cancel_requested or transport_failure is not None
        )
        observed_after_root = semantic_root(observed_after)
        if observed_after_root == after_root:
            committed = True
        elif observed_after_root != before_root:
            raise EvidenceFailed(
                f"{issue_id} post-read found an unplanned concurrent state"
            )
        append_event(
            "apply",
            result="committed" if committed else "not-committed",
            command=forward_argv,
            inverse_command=inverse_argv,
            old_root=before_root,
            new_root=after_root,
            extra={"observed_semantic_root": observed_after_root},
        )
        if transport_failure is not None:
            raise transport_failure
        if not committed:
            raise EvidenceFailed(
                f"{issue_id} br update returned without the planned exact state"
            )

        append_event(
            "post-observe",
            result="exact-root-match",
            command=["br", "show", issue_id, "--json", *BR_READ_FLAGS],
            inverse_command=inverse_argv,
            old_root=before_root,
            new_root=after_root,
        )
        lint_result = br_read_json("lint", issue_id, "--json")
        if not isinstance(lint_result, dict) or not isinstance(
            lint_result.get("results"), list
        ):
            raise InfrastructureFailed(f"br lint returned malformed data for {issue_id}")
        remaining = {
            str(candidate.get("id", "")): candidate.get("missing") or []
            for candidate in lint_result["results"]
            if isinstance(candidate, dict)
        }
        if row["missing_section"] in remaining.get(issue_id, []):
            raise EvidenceFailed(f"{issue_id} still lacks {row['missing_section']}")
        if not section_present(observed_after["description"], row["missing_section"]):
            raise EvidenceFailed(
                f"{issue_id} independent heading check failed after update"
            )
        append_event(
            "export",
            result="planned-warning-cleared",
            command=["br", "lint", issue_id, "--json", *BR_READ_FLAGS],
            inverse_command=inverse_argv,
            old_root=before_root,
            new_root=after_root,
        )

        restoration = {
            "schema": "frankensim.beads-template-hygiene.restoration.v1",
            "state": "forward-accepted",
            "target_id": issue_id,
            "before_issue_root": before_root,
            "current_issue_root": observed_after_root,
            "planned_after_issue_root": after_root,
            "inverse_retained": True,
            "restoration_required": False,
            "verified": observed_after_root == after_root,
        }
        append_event(
            "publish",
            result="terminal-last",
            old_root=before_root,
            new_root=after_root,
            extra={"artifacts": list(artifact_names)},
        )
        append_event(
            "terminal",
            result="pass",
            terminal="Pass",
            old_root=before_root,
            new_root=after_root,
            extra={
                "exit_code": TERMINAL_EXIT["Pass"],
                "inventory_root": snapshot.inventory["semantic_root"],
                "partitions_root": partitions["semantic_root"],
                "plan_root": snapshot.plan["semantic_root"],
                "proposal_root": proposal_root,
                "manifest_root": manifest_root,
                "subject_terminal": "APPLIED_AND_INVERTIBLE",
                "event_count": len(events) + 1,
                "no_claim": snapshot.inventory["no_claim"],
            },
        )
        post_payloads = {
            "restoration.json": canonical_bytes(restoration),
            "events.jsonl": b"".join(canonical_bytes(event) for event in events),
        }
        for name, payload in post_payloads.items():
            if len(payload) > RUN_ARTIFACT_CAP:
                raise EvidenceFailed(
                    f"apply post-mutation artifact {name} exceeds its cap"
                )
        for name, payload in sorted(post_payloads.items()):
            writes[name] = write_once(output / name, payload)
        identity_schemas = {
            "source.json": SOURCE_SCHEMA,
            "inventory.json": INVENTORY_SCHEMA,
            "partitions.json": PARTITIONS_SCHEMA,
            "plan.json": PLAN_SCHEMA,
            "apply-manifest.json": APPLY_SCHEMA,
            "inverse-br.json": inverse_artifact["schema"],
            "restoration.json": restoration["schema"],
            "events.jsonl": EVENT_SCHEMA,
            "reproduce.txt": "frankensim.argv-json.v1",
        }
        identity_payloads = {**pre_payloads, **post_payloads}
        terminal: dict[str, Any] = {
            "schema": RUN_TERMINAL_SCHEMA,
            "mode": "apply",
            "terminal": "Pass",
            "subject_terminal": "APPLIED_AND_INVERTIBLE",
            "exit_code": TERMINAL_EXIT["Pass"],
            "artifact_root": str(
                safe_relative(artifact_root, label="artifact root")
            ),
            "artifact_dir": str(
                safe_relative(artifact_dir, label="artifact dir")
            ),
            "safe_relative_artifacts": list(artifact_names),
            "artifact_identities": {
                name: artifact_identity(
                    name, payload, identity_schemas[name]
                )
                for name, payload in sorted(identity_payloads.items())
            },
            "source_root": retained_source["semantic_root"],
            "inventory_root": snapshot.inventory["semantic_root"],
            "partitions_root": partitions["semantic_root"],
            "plan_root": snapshot.plan["semantic_root"],
            "proposal_root": proposal_root,
            "manifest_root": manifest_root,
            "before_issue_root": before_root,
            "after_issue_root": after_root,
            "event_count": len(events),
            "event_sequence": list(range(len(events))),
            "reproduction": reproduce_argv,
            "no_claim": snapshot.inventory["no_claim"],
        }
        terminal["semantic_root"] = semantic_root(terminal)
        # A Pass seal is deliberately the final filesystem operation. There is
        # no fallible publication step after it.
        writes["terminal.json"] = write_once(
            output / "terminal.json", canonical_bytes(terminal)
        )
    except HarnessError as error:
        failure = error
    except BaseException as error:
        failure = InfrastructureFailed(f"unexpected apply failure: {error}")

    if failure is not None:
        if forward_attempted:
            try:
                restoration = _restore_apply_target(
                    issue_id=issue_id,
                    agent_name=agent_name,
                    inverse_value=str(row["inverse_value"]),
                    before_projection=before,
                    after_projection=after,
                )
                idempotent = _restore_apply_target(
                    issue_id=issue_id,
                    agent_name=agent_name,
                    inverse_value=str(row["inverse_value"]),
                    before_projection=before,
                    after_projection=after,
                )
                if idempotent["state"] != "already-restored":
                    raise EvidenceFailed(
                        f"{issue_id} restoration was not idempotent"
                    )
                restoration["idempotent_recheck"] = idempotent
                append_event(
                    "inverse",
                    result=str(restoration["state"]),
                    command=(
                        inverse_argv
                        if restoration.get("inverse_invoked")
                        else ()
                    ),
                    inverse_command=inverse_argv,
                    old_root=after_root,
                    new_root=before_root,
                )
                append_event(
                    "restore",
                    result="idempotent-exact-root-verified",
                    inverse_command=inverse_argv,
                    old_root=after_root,
                    new_root=before_root,
                )
            except HarnessError as rollback_error:
                raise EvidenceFailed(
                    f"{issue_id} apply failed and restoration is incomplete: "
                    f"{rollback_error}"
                ) from failure

        if restoration is None:
            restoration = {
                "schema": "frankensim.beads-template-hygiene.restoration.v1",
                "state": "forward-not-committed",
                "target_id": issue_id,
                "before_issue_root": before_root,
                "current_issue_root": semantic_root(
                    _read_apply_issue(issue_id, recovery=True)
                ),
                "planned_after_issue_root": after_root,
                "inverse_retained": True,
                "restoration_required": False,
                "verified": True,
            }
        append_event(
            "refuse",
            result=failure.terminal,
            inverse_command=inverse_argv,
            old_root=before_root,
            new_root=after_root,
            extra={"detail": str(failure)},
        )
        append_event(
            "terminal",
            result="refused",
            terminal=failure.terminal,
            old_root=before_root,
            new_root=after_root,
            extra={
                "exit_code": TERMINAL_EXIT[failure.terminal],
                "inventory_root": snapshot.inventory["semantic_root"],
                "partitions_root": partitions["semantic_root"],
                "plan_root": snapshot.plan["semantic_root"],
                "proposal_root": proposal_root,
                "manifest_root": manifest_root,
                "restored": bool(restoration and restoration.get("verified")),
                "event_count": len(events) + 1,
                "no_claim": snapshot.inventory["no_claim"],
            },
        )
        failure_payloads: dict[str, bytes] = {
            "events.jsonl": b"".join(canonical_bytes(event) for event in events),
            "restoration.json": canonical_bytes(restoration),
        }
        publication_errors: list[str] = []
        for name, payload in sorted(failure_payloads.items()):
            try:
                writes[name] = write_once(output / name, payload)
            except HarnessError as publication_error:
                publication_errors.append(f"{name}: {publication_error}")
        failure_terminal: dict[str, Any] = {
            "schema": RUN_TERMINAL_SCHEMA,
            "mode": "apply",
            "terminal": failure.terminal,
            "exit_code": TERMINAL_EXIT[failure.terminal],
            "artifact_root": str(
                safe_relative(artifact_root, label="artifact root")
            ),
            "artifact_dir": str(
                safe_relative(artifact_dir, label="artifact dir")
            ),
            "safe_relative_artifacts": list(artifact_names),
            "source_root": retained_source["semantic_root"],
            "inventory_root": snapshot.inventory["semantic_root"],
            "partitions_root": partitions["semantic_root"],
            "plan_root": snapshot.plan["semantic_root"],
            "proposal_root": proposal_root,
            "manifest_root": manifest_root,
            "before_issue_root": before_root,
            "planned_after_issue_root": after_root,
            "restored": bool(restoration.get("verified")),
            "event_count": len(events),
            "event_sequence": list(range(len(events))),
            "reproduction": reproduce_argv,
            "detail": str(failure),
            "no_claim": snapshot.inventory["no_claim"],
        }
        failure_terminal["semantic_root"] = semantic_root(failure_terminal)
        try:
            writes["terminal.json"] = write_once(
                output / "terminal.json", canonical_bytes(failure_terminal)
            )
        except HarnessError as publication_error:
            publication_errors.append(f"terminal.json: {publication_error}")
        if publication_errors:
            raise EvidenceFailed(
                "apply failed after exact restoration, but failure evidence "
                f"publication was incomplete: {'; '.join(publication_errors)}"
            ) from failure
        raise failure

    return {
        "terminal": "Pass",
        "mode": "apply",
        "rows": 1,
        "issue_ids": [issue_id],
        "artifact_dir": str(output_rel),
        "inventory_root": snapshot.inventory["semantic_root"],
        "plan_root": snapshot.plan["semantic_root"],
        "proposal_root": proposal_root,
        "manifest_root": manifest_root,
        "writes": writes,
        "no_claim": snapshot.inventory["no_claim"],
    }


def fixture_issue(
    *,
    issue_id: str = "fixture-1",
    title: str = "Specific fixture behavior",
    issue_type: str = "task",
    status: str = "open",
    priority: int = 1,
    description: str = "Specific work with deterministic boundaries.",
    acceptance: str = "",
    design: str = "",
    notes: str = "",
    assignee: str = "",
    owner: str = "",
    parent: str = "",
    labels: Sequence[str] = ("reality-check",),
    dependencies: Sequence[Mapping[str, Any]] = (),
    children: Sequence[str] = (),
) -> dict[str, Any]:
    return {
        "id": issue_id,
        "title": title,
        "type": issue_type,
        "status": status,
        "priority": priority,
        "assignee": assignee,
        "owner": owner,
        "parent": parent,
        "labels": list(labels),
        "description": description,
        "acceptance_criteria": acceptance,
        "design": design,
        "notes": notes,
        "estimated_minutes": 60,
        "updated_at": "frozen",
        "dependencies": [
            {
                "title": str(
                    edge.get("title") or "Specific fixture behavior"
                ),
                **dict(edge),
            }
            for edge in dependencies
        ],
        "dependents": [
            {
                "id": child,
                "title": "Specific fixture behavior",
                "type": "parent-child",
                "status": "open",
                "priority": 1,
            }
            for child in children
        ],
    }


FIXTURE_REQUIRED_SECTIONS_BY_TYPE = {
    "bug": ("## Steps to Reproduce", "## Acceptance Criteria"),
    "task": ("## Acceptance Criteria",),
    "feature": ("## Acceptance Criteria",),
    "epic": ("## Success Criteria",),
    "chore": (),
    "docs": (),
    "question": (),
    "custom": (),
}


def v2_canonical_missing_sections(
    issue_type: str,
    sections: Iterable[Any],
) -> tuple[str, ...]:
    if type(issue_type) is not str:
        raise EvidenceFailed("missing-section issue type is not an exact string")
    if type(sections) is not tuple:
        raise EvidenceFailed("missing sections are not an exact tuple")
    if len(sections) > FIXTURE_MAX_WARNINGS_PER_ISSUE:
        raise EvidenceFailed("missing sections exceed their declared cap")
    raw_sections: tuple[str, ...] = ()
    for section in sections:
        if type(section) is not str or not section:
            raise EvidenceFailed(
                "missing section is not a nonempty exact string"
            )
        raw_sections = (*raw_sections, section)
    required_order = dict.get(
        FIXTURE_REQUIRED_SECTIONS_BY_TYPE,
        issue_type,
        (),
    )
    if (
        type(required_order) is not tuple
        or any(type(section) is not str for section in required_order)
    ):
        raise EvidenceFailed(
            "required missing-section order is not an exact string tuple"
        )
    raw_section_set = set(raw_sections)
    return (
        *(
            section
            for section in required_order
            if section in raw_section_set
        ),
        *sorted(raw_section_set - set(required_order)),
    )


FIXTURE_MAX_WARNINGS_PER_ISSUE = 16
FIXTURE_BR_ROOT_REL = PurePosixPath(
    "target/beads-template-hygiene/self-test-br-fixture"
)
FIXTURE_BR_DB_REL = FIXTURE_BR_ROOT_REL / ".beads" / "beads.db"
FIXTURE_BR_DB_ARG = ".beads/beads.db"
# This inode is intentionally persistent: releasing a lease unlocks and closes
# it but never unlinks it, so every process coordinates on one stable target.
FIXTURE_BR_LOCK_REL = PurePosixPath(
    "target/beads-template-hygiene/self-test-br-fixture.lock"
)
FIXTURE_BR_LOCK_TIMEOUT_SECONDS = 30.0
FIXTURE_BR_LOCK_POLL_SECONDS = 0.05
FIXTURE_BR_STABLE_TITLE = (
    "Template hygiene no-mock actionable fixture v2"
)
FIXTURE_BR_REGRESSION_TITLE = "Template hygiene no-mock regression fixture"
FIXTURE_BR_STABLE_ID_PREFIX = "thfx-template-hygiene-actionable-v2-"
FIXTURE_BR_REGRESSION_ID_PREFIX = "thfx-template-hygiene-regression-"
FIXTURE_BR_LEGACY_ID_PREFIX = "thfx-template-hygiene-stable-"
FIXTURE_BR_LABEL = "template-hygiene-fixture"
FIXTURE_BR_STABLE_DESCRIPTION = (
    "Stable no-mock fixture baseline.\n\n"
    "Completion is checked only inside this isolated br database."
)
FIXTURE_BR_REGRESSION_DESCRIPTION = (
    "Intentionally missing an acceptance section."
)
FIXTURE_BR_LEGACY_TITLE = "Template hygiene no-mock stable fixture"
FIXTURE_BR_LEGACY_DESCRIPTION = FIXTURE_BR_STABLE_DESCRIPTION
FIXTURE_BR_REGRESSION_CLOSE_REASON = "template hygiene fixture baseline"


@dataclass
class FixtureBrDescriptorOwner:
    _descriptor: int | None = field(repr=False)

    @property
    def descriptor(self) -> int:
        descriptor = self._descriptor
        if type(descriptor) is not int or descriptor < 0:
            raise InfrastructureFailed(
                "no-mock fixture lock descriptor ownership was lost"
            )
        return descriptor

    def close(self) -> OSError | None:
        descriptor_slot: list[int | None] = [None]
        if not v2_transfer_fixture_descriptor_owner_to_slot(
            self,
            descriptor_slot,
        ):
            return None
        close_failure = v2_collect_owned_descriptor_slot_close_failure(
            descriptor_slot,
            InfrastructureFailed(
                "no-mock fixture lock descriptor close failed"
            ),
        )
        if close_failure is None:
            return None
        error = close_failure[1]
        if isinstance(error, OSError):
            return error
        raise error

    def __del__(self) -> None:
        try:
            self.close()
        except BaseException:
            # A failed transfer retains the field; a committed transfer either
            # closed its local owner or left the close result indeterminate.
            # Retry only the still-visible field owner.
            if type(getattr(self, "_descriptor", None)) is int:
                try:
                    self.close()
                except BaseException:
                    pass


def v2_transfer_fixture_descriptor_owner_to_slot(
    owner: FixtureBrDescriptorOwner,
    destination_slot: list[int | None],
) -> bool:
    """Move the fixture descriptor field into one exact cleanup slot."""
    if (
        type(owner) is not FixtureBrDescriptorOwner
        or type(destination_slot) is not list
        or list.__len__(destination_slot) != 1
    ):
        raise InfrastructureFailed(
            "no-mock fixture descriptor transfer state is malformed"
        )
    descriptor: int | None = None
    try:
        descriptor = owner._descriptor
        destination_descriptor = list.__getitem__(destination_slot, 0)
        if descriptor is None:
            if destination_descriptor is not None:
                raise InfrastructureFailed(
                    "no-mock fixture descriptor destination is not empty"
                )
            return False
        if (
            type(descriptor) is not int
            or descriptor < 0
            or destination_descriptor is not None
        ):
            raise InfrastructureFailed(
                "no-mock fixture descriptor transfer state is malformed"
            )
        owner._descriptor = None
        list.__setitem__(destination_slot, 0, descriptor)
    except BaseException:
        if descriptor is not None:
            field_owns = (
                type(owner) is FixtureBrDescriptorOwner
                and owner._descriptor is descriptor
            )
            slot_owns = (
                type(destination_slot) is list
                and list.__len__(destination_slot) == 1
                and list.__getitem__(destination_slot, 0) is descriptor
            )
            if field_owns and slot_owns:
                owner._descriptor = None
                field_owns = False
            if not field_owns and not slot_owns:
                try:
                    os.close(descriptor)
                except BaseException:
                    pass
        raise
    return True


@dataclass
class FixtureBrThreadGuardOwner:
    _guard: Any = field(repr=False)
    _owns_guard: bool = field(default=False, repr=False)

    def release(self) -> None:
        if not self._owns_guard:
            return
        attempt_started = False
        try:
            self._owns_guard = False; attempt_started = True; self._guard.release()
        except BaseException:
            if not attempt_started:
                self._owns_guard = False
                try:
                    self._guard.release()
                except BaseException:
                    pass
            raise

    def __del__(self) -> None:
        try:
            self.release()
        except BaseException:
            if getattr(self, "_owns_guard", False):
                self._owns_guard = False
                try:
                    self._guard.release()
                except BaseException:
                    pass


@dataclass(frozen=True)
class FixtureBrLease:
    _descriptor_owner: FixtureBrDescriptorOwner = field(repr=False)
    lock_path: Path = field(repr=False)
    device: int
    inode: int
    contended: bool
    wait_polls: int

    @property
    def descriptor(self) -> int:
        return self._descriptor_owner.descriptor


_fixture_br_thread_guard = threading.RLock()
_fixture_br_lock_depth = 0
_fixture_br_active_lease: FixtureBrLease | None = None


def _fixture_br_try_acquire_thread_guard(
    *,
    owner_slot: list[FixtureBrThreadGuardOwner | None],
) -> None:
    if (
        type(owner_slot) is not list
        or len(owner_slot) != 1
        or list.__getitem__(owner_slot, 0) is not None
    ):
        raise InfrastructureFailed(
            "no-mock fixture thread-guard owner slot is not empty"
        )
    # Publish the finalizer-backed owner into caller-controlled storage before
    # acquisition. The acquire and ownership-bit store share one source line,
    # so a return-event interruption still leaves the production caller able
    # to release the guard without depending on prompt object finalization.
    owner = FixtureBrThreadGuardOwner(_fixture_br_thread_guard)
    list.__setitem__(owner_slot, 0, owner)
    owner._owns_guard = _fixture_br_thread_guard.acquire(blocking=False)
    if not owner._owns_guard:
        list.__setitem__(owner_slot, 0, None)


def _fixture_br_cleanup_open_descriptors(
    descriptor_owner: FixtureBrDescriptorOwner,
    parent_descriptor_owner: FixtureBrDescriptorOwner,
    *,
    transfer_target: bool,
    surface_failure: bool,
) -> None:
    """Idempotently close an open attempt or complete its target handoff."""
    target_close_error: BaseException | None = None
    parent_close_error: BaseException | None = None
    if not transfer_target:
        target_close_error = descriptor_owner.close()
    parent_close_error = parent_descriptor_owner.close()
    if transfer_target and parent_close_error is not None:
        target_close_error = descriptor_owner.close()
    if not surface_failure:
        return
    if parent_close_error is not None:
        if not isinstance(parent_close_error, OSError):
            raise parent_close_error
        raise InfrastructureFailed(
            "no-mock fixture lock parent descriptor close failed"
        ) from parent_close_error
    if target_close_error is not None:
        if not isinstance(target_close_error, OSError):
            raise target_close_error
        raise InfrastructureFailed(
            "no-mock fixture lock descriptor close failed"
        ) from target_close_error


def _fixture_br_open_lock_descriptor(
    *,
    descriptor_owner_slot: list[FixtureBrDescriptorOwner | None],
    parent_owner_slot: list[FixtureBrDescriptorOwner | None],
) -> tuple[
    Path,
    os.stat_result,
]:
    for label, owner_slot in (
        ("target", descriptor_owner_slot),
        ("parent", parent_owner_slot),
    ):
        if (
            type(owner_slot) is not list
            or len(owner_slot) != 1
            or list.__getitem__(owner_slot, 0) is not None
        ):
            raise InfrastructureFailed(
                f"no-mock fixture lock {label} owner slot is not empty"
            )
    lock_path = resolve_safe(
        str(FIXTURE_BR_LOCK_REL),
        label="no-mock fixture lock",
    )
    lock_parent = resolve_safe(
        str(FIXTURE_BR_LOCK_REL.parent),
        label="no-mock fixture lock parent",
    )
    try:
        lock_parent.mkdir(parents=True, exist_ok=True)
    except OSError as error:
        raise InfrastructureFailed(
            "no-mock fixture lock parent could not be created safely"
        ) from error
    directory_flags = os.O_RDONLY | os.O_DIRECTORY
    directory_flags |= os.O_NOFOLLOW
    descriptor_flags = os.O_RDWR | os.O_CREAT
    descriptor_flags |= os.O_CLOEXEC
    descriptor_flags |= os.O_NONBLOCK
    descriptor_flags |= os.O_NOFOLLOW
    parent_descriptor_owner = FixtureBrDescriptorOwner(None)
    descriptor_owner = FixtureBrDescriptorOwner(None)
    list.__setitem__(parent_owner_slot, 0, parent_descriptor_owner)
    list.__setitem__(descriptor_owner_slot, 0, descriptor_owner)
    owner_returned = False
    try:
        parent_descriptor_owner._descriptor = os.open(lock_parent, directory_flags)
        parent_descriptor = parent_descriptor_owner.descriptor
        parent_before = os.fstat(parent_descriptor)
        if not stat.S_ISDIR(parent_before.st_mode):
            raise InfrastructureFailed(
                "no-mock fixture lock parent is not a directory"
            )
        # The owner already exists, so no allocation follows the raw open. One
        # physical source line removes the modeled post-open/pre-store trace
        # interruption point.
        descriptor_owner._descriptor = os.open(FIXTURE_BR_LOCK_REL.name, descriptor_flags, 0o600, dir_fd=parent_descriptor)
        descriptor = descriptor_owner.descriptor
        descriptor_state = os.fstat(descriptor)
        path_state = os.lstat(lock_path)
        parent_after = os.fstat(parent_descriptor)
        if (
            not stat.S_ISREG(descriptor_state.st_mode)
            or descriptor_state.st_nlink != 1
            or not stat.S_ISREG(path_state.st_mode)
            or path_state.st_nlink != 1
            or descriptor_state.st_dev != path_state.st_dev
            or descriptor_state.st_ino != path_state.st_ino
            or parent_before.st_dev != parent_after.st_dev
            or parent_before.st_ino != parent_after.st_ino
        ):
            raise InfrastructureFailed(
                "no-mock fixture lock path identity is unsafe"
            )
        # Do not create a line-event gap between declaring the caller-owned
        # handoff and starting the return. A return-event interruption leaves
        # both owners in the caller slots for its enclosing cleanup.
        owner_returned = True; return lock_path, descriptor_state
    except HarnessError:
        raise
    except OSError as error:
        raise InfrastructureFailed(
            "no-mock fixture lock could not be opened safely"
        ) from error
    finally:
        # A single protected call owns the entire exit transition. If it is
        # interrupted, the fallback converts a pending return into cleanup of
        # both descriptors; an already-active body primary remains primary.
        try: _fixture_br_cleanup_open_descriptors(descriptor_owner, parent_descriptor_owner, transfer_target=owner_returned, surface_failure=owner_returned)
        except BaseException:
            try:
                _fixture_br_cleanup_open_descriptors(
                    descriptor_owner,
                    parent_descriptor_owner,
                    transfer_target=False,
                    surface_failure=False,
                )
            except BaseException:
                pass
            if owner_returned:
                raise


def _fixture_br_cleanup_failed_acquisition(
    descriptor_owner_slot: list[FixtureBrDescriptorOwner | None],
    parent_owner_slot: list[FixtureBrDescriptorOwner | None],
    descriptor: int | None,
    acquired: bool,
) -> None:
    descriptor_owner = list.__getitem__(descriptor_owner_slot, 0)
    if (
        type(descriptor_owner) is FixtureBrDescriptorOwner
        and descriptor_owner._descriptor is not None
    ):
        # The protected simple suite has no unlock-to-close line boundary. A
        # pre-entry or unlock failure reaches the idempotent owner fallback.
        try: fcntl.flock(descriptor, fcntl.LOCK_UN) if acquired and type(descriptor) is int else None; descriptor_owner.close()
        except BaseException:
            try:
                descriptor_owner.close()
            except BaseException:
                pass
    parent_owner = list.__getitem__(parent_owner_slot, 0)
    if (
        type(parent_owner) is FixtureBrDescriptorOwner
        and parent_owner._descriptor is not None
    ):
        try: parent_owner.close()
        except BaseException:
            if parent_owner._descriptor is not None:
                try:
                    parent_owner.close()
                except BaseException:
                    pass


def _fixture_br_acquire_file_lock(
    *,
    lease_slot: list[FixtureBrLease | None],
    honor_cancel: bool = True,
) -> None:
    if (
        type(lease_slot) is not list
        or len(lease_slot) != 1
        or list.__getitem__(lease_slot, 0) is not None
    ):
        raise InfrastructureFailed(
            "no-mock fixture file-lock lease slot is not empty"
        )
    if type(honor_cancel) is not bool:
        raise InfrastructureFailed(
            "no-mock fixture file-lock cancellation policy is malformed"
        )
    descriptor_owner_slot: list[FixtureBrDescriptorOwner | None] = [None]
    parent_owner_slot: list[FixtureBrDescriptorOwner | None] = [None]
    descriptor: int | None = None
    deadline = time.monotonic() + FIXTURE_BR_LOCK_TIMEOUT_SECONDS
    contended = False
    wait_polls = 0
    acquired = False
    try:
        lock_path, descriptor_state = _fixture_br_open_lock_descriptor(
            descriptor_owner_slot=descriptor_owner_slot,
            parent_owner_slot=parent_owner_slot,
        )
        descriptor_owner = list.__getitem__(descriptor_owner_slot, 0)
        if type(descriptor_owner) is not FixtureBrDescriptorOwner:
            raise InfrastructureFailed(
                "no-mock fixture lock descriptor ownership was lost"
            )
        descriptor = descriptor_owner.descriptor
        while True:
            if honor_cancel:
                check_cancel()
            try:
                fcntl.flock(
                    descriptor,
                    fcntl.LOCK_EX | fcntl.LOCK_NB,
                )
                acquired = True
                break
            except BlockingIOError:
                contended = True
            except OSError as error:
                if error.errno not in {errno.EACCES, errno.EAGAIN, errno.EINTR}:
                    raise InfrastructureFailed(
                        "no-mock fixture lock acquisition failed"
                    ) from error
                contended = True
            if time.monotonic() >= deadline:
                raise InfrastructureFailed(
                    "no-mock fixture lock acquisition exceeded its bounded timeout"
                )
            wait_polls += 1
            time.sleep(FIXTURE_BR_LOCK_POLL_SECONDS)
        path_state = os.lstat(lock_path)
        locked_state = os.fstat(descriptor)
        if (
            not stat.S_ISREG(path_state.st_mode)
            or path_state.st_nlink != 1
            or locked_state.st_nlink != 1
            or locked_state.st_dev != descriptor_state.st_dev
            or locked_state.st_ino != descriptor_state.st_ino
            or path_state.st_dev != locked_state.st_dev
            or path_state.st_ino != locked_state.st_ino
        ):
            raise InfrastructureFailed(
                "no-mock fixture lock identity changed during acquisition"
            )
        lease = FixtureBrLease(
            _descriptor_owner=descriptor_owner,
            lock_path=lock_path,
            device=int(locked_state.st_dev),
            inode=int(locked_state.st_ino),
            contended=contended,
            wait_polls=wait_polls,
        )
        # The caller owns the live lease before the return can be interrupted.
        # Clearing the local owner slot on the same line prevents dual owners.
        list.__setitem__(lease_slot, 0, lease); list.__setitem__(descriptor_owner_slot, 0, None); return None
    except BaseException as primary:
        try: _fixture_br_cleanup_failed_acquisition(descriptor_owner_slot, parent_owner_slot, descriptor, acquired)
        except BaseException:
            try:
                _fixture_br_cleanup_failed_acquisition(
                    descriptor_owner_slot,
                    parent_owner_slot,
                    descriptor,
                    acquired,
                )
            except BaseException:
                pass
        raise primary


def _fixture_br_release_file_lock(lease: FixtureBrLease) -> None:
    failure: BaseException | None = None
    descriptor = lease.descriptor
    try:
        descriptor_state = os.fstat(descriptor)
        path_state = os.lstat(lease.lock_path)
        if (
            not stat.S_ISREG(descriptor_state.st_mode)
            or descriptor_state.st_nlink != 1
            or not stat.S_ISREG(path_state.st_mode)
            or path_state.st_nlink != 1
            or descriptor_state.st_dev != lease.device
            or descriptor_state.st_ino != lease.inode
            or path_state.st_dev != lease.device
            or path_state.st_ino != lease.inode
        ):
            raise InfrastructureFailed(
                "no-mock fixture lock identity changed while held"
            )
    except OSError as error:
        failure = error
    finally:
        active_primary = sys.exception()
        close_error: BaseException | None = None
        cleanup_interruption: BaseException | None = None
        # The try suite, unlock, and ownership-relinquishing close deliberately
        # share one physical line. CPython can therefore neither inject at an
        # unprotected try header nor stop after unlock succeeds but before the
        # close begins. Any unlock failure reaches the fallback owner close.
        try: fcntl.flock(descriptor, fcntl.LOCK_UN); close_error = lease._descriptor_owner.close()
        except BaseException as error:
            cleanup_interruption = error
            try:
                fallback_close_error = lease._descriptor_owner.close()
                if close_error is None:
                    close_error = fallback_close_error
            except BaseException as fallback_error:
                if close_error is None:
                    close_error = fallback_error
        if active_primary is None and failure is None:
            failure = (
                cleanup_interruption
                if cleanup_interruption is not None
                else close_error
                if close_error is not None
                else None
            )
    if failure is not None:
        if not isinstance(failure, OSError):
            raise failure
        raise InfrastructureFailed(
            "no-mock fixture lock could not be released safely"
        ) from failure


def _fixture_br_cleanup_lease_scope(
    guard_owner_slot: list[FixtureBrThreadGuardOwner | None],
    lease_delivery_slot: list[FixtureBrLease | None],
    entry_depth: int | None,
    outermost: bool,
    *,
    surface_failure: bool,
) -> None:
    """Idempotently drain scope ownership from caller-visible rescue slots."""
    global _fixture_br_active_lease, _fixture_br_lock_depth
    release_error: BaseException | None = None
    # Every mutation is recoverable from either a global or caller-owned slot.
    # If a line-trace interruption escapes this helper, fixture_br_lease calls
    # it again after the injecting trace has been disabled.
    if entry_depth is not None and _fixture_br_lock_depth > entry_depth:
        _fixture_br_lock_depth -= 1
    if outermost:
        lease = (
            _fixture_br_active_lease
            if _fixture_br_active_lease is not None
            else list.__getitem__(lease_delivery_slot, 0)
        )
        if (
            type(lease) is FixtureBrLease
            and lease._descriptor_owner._descriptor is not None
        ):
            try:
                _fixture_br_release_file_lock(lease)
            except BaseException as error:
                release_error = error
                # A trace can interrupt at the callee entry before release
                # transfers any ownership. Retry only while the owner field is
                # still live; once an attempt starts, its field is nil and the
                # numeric descriptor is never reused.
                if lease._descriptor_owner._descriptor is not None:
                    try:
                        _fixture_br_release_file_lock(lease)
                    except BaseException as fallback_error:
                        if release_error is None:
                            release_error = fallback_error
        _fixture_br_active_lease, lease_delivery_slot[0] = None, None
    guard_owner = list.__getitem__(guard_owner_slot, 0)
    if (
        type(guard_owner) is FixtureBrThreadGuardOwner
        and guard_owner._owns_guard
    ):
        try:
            guard_owner.release()
        except BaseException as error:
            if release_error is None:
                release_error = error
            if guard_owner._owns_guard:
                try:
                    guard_owner.release()
                except BaseException as fallback_error:
                    if release_error is None:
                        release_error = fallback_error
    if release_error is not None and surface_failure:
        raise release_error


@contextmanager
def fixture_br_lease(
    *,
    honor_cancel: bool = True,
) -> Iterator[FixtureBrLease]:
    global _fixture_br_active_lease, _fixture_br_lock_depth
    deadline = time.monotonic() + FIXTURE_BR_LOCK_TIMEOUT_SECONDS
    guard_owner_slot: list[FixtureBrThreadGuardOwner | None] = [None]
    lease_delivery_slot: list[FixtureBrLease | None] = [None]
    guard_owner: FixtureBrThreadGuardOwner | None = None
    entry_depth: int | None = None
    outermost = False
    body_succeeded = False
    if type(honor_cancel) is not bool:
        raise InfrastructureFailed(
            "no-mock fixture lease cancellation policy is malformed"
        )
    try:
        while guard_owner is None:
            if honor_cancel:
                check_cancel()
            _fixture_br_try_acquire_thread_guard(
                owner_slot=guard_owner_slot
            )
            guard_owner = list.__getitem__(guard_owner_slot, 0)
            if guard_owner is not None:
                break
            if time.monotonic() >= deadline:
                raise InfrastructureFailed(
                    "no-mock fixture in-process lease exceeded its bounded "
                    "timeout"
                )
            time.sleep(FIXTURE_BR_LOCK_POLL_SECONDS)
        entry_depth = _fixture_br_lock_depth
        outermost = entry_depth == 0
        if outermost:
            _fixture_br_acquire_file_lock(
                lease_slot=lease_delivery_slot,
                honor_cancel=honor_cancel,
            )
            delivered_lease = list.__getitem__(lease_delivery_slot, 0)
            if type(delivered_lease) is not FixtureBrLease:
                raise InfrastructureFailed(
                    "no-mock fixture file-lock lease delivery was lost"
                )
            _fixture_br_active_lease, lease_delivery_slot[0] = delivered_lease, None
        lease = _fixture_br_active_lease
        if lease is None:
            raise InfrastructureFailed(
                "no-mock fixture lease state is internally inconsistent"
            )
        _fixture_br_lock_depth += 1
        yield lease
        body_succeeded = True
    finally:
        # Put the try header and first cleanup call on the same physical line:
        # an injected exception at that line is caught, then the idempotent
        # fallback drains every rescue slot while preserving a body primary.
        try: _fixture_br_cleanup_lease_scope(guard_owner_slot, lease_delivery_slot, entry_depth, outermost, surface_failure=body_succeeded)
        except BaseException:
            try:
                _fixture_br_cleanup_lease_scope(
                    guard_owner_slot,
                    lease_delivery_slot,
                    entry_depth,
                    outermost,
                    surface_failure=False,
                )
            except BaseException:
                pass
            if body_succeeded:
                raise


def v2_fixture_br_lease_lifecycle_probe() -> dict[str, Any]:
    """Exercise interrupted ownership handoffs and cleanup precedence."""
    global _fixture_br_thread_guard
    if _fixture_br_lock_depth != 0 or _fixture_br_active_lease is not None:
        raise EvidenceFailed(
            "no-mock fixture lease lifecycle probe requires pristine state"
        )
    original_thread_guard = _fixture_br_thread_guard
    guard_acquire_returned = False
    guard_delivery_interrupted = False
    guard_pre_owner_window_observed = False

    class ObservedThreadGuard:
        def __init__(self) -> None:
            self._guard = threading.RLock()

        def acquire(self, *, blocking: bool = True) -> bool:
            nonlocal guard_acquire_returned
            acquired = self._guard.acquire(blocking=blocking)
            if acquired:
                guard_acquire_returned = True
            return acquired

        def release(self) -> None:
            self._guard.release()

    synthetic_thread_guard = ObservedThreadGuard()

    def interrupt_guard_owner_delivery(
        frame: Any,
        event: str,
        _argument: Any,
    ) -> Any:
        nonlocal guard_delivery_interrupted
        nonlocal guard_pre_owner_window_observed
        if (
            event == "line"
            and frame.f_code
            is _fixture_br_try_acquire_thread_guard.__code__
        ):
