    def probe_guard_from_other_thread(
        guard: Any,
        *,
        name: str,
    ) -> tuple[bool, bool, list[str]]:
        acquired_other_thread = False
        worker_errors: list[str] = []

        def acquire_from_worker() -> None:
            nonlocal acquired_other_thread
            try:
                acquired = guard.acquire(blocking=False)
                acquired_other_thread = acquired
                if acquired:
                    guard.release()
            except BaseException as error:
                list.append(worker_errors, v2_raw_type_name(type(error)))

        worker = threading.Thread(target=acquire_from_worker, name=name)
        worker.start()
        worker.join(timeout=5.0)
        return acquired_other_thread, worker.is_alive(), worker_errors

