    open_return_production_parent_relinquished = (
        type(open_return_parent_owner) is FixtureBrDescriptorOwner
        and open_return_parent_owner._descriptor is None
    )
    open_return_test_cleanup_performed = False
    for retained_owner in (
        open_return_target_owner,
        open_return_parent_owner,
    ):
        if (
            type(retained_owner) is FixtureBrDescriptorOwner
            and retained_owner._descriptor is not None
        ):
            open_return_test_cleanup_performed = True
            retained_owner.close()

    class SyntheticAcquireReturnPrimary(RuntimeError):
        pass

    acquire_return_primary = SyntheticAcquireReturnPrimary(
        "synthetic file-lock acquisition return interruption"
    )
    acquire_return_guard = CountingThreadGuard()
    acquire_return_retained_leases: list[FixtureBrLease] = []
    acquire_return_retained_arguments: list[Any] = []
    acquire_return_descriptor: int | None = None
    acquire_return_flock_calls: list[tuple[int, int]] = []
    acquire_return_close_calls: list[int] = []
    acquire_return_body_entered = False
    acquire_return_observed: BaseException | None = None
    original_acquire_return_flock = fcntl.flock
    original_acquire_return_close = os.close

    def observe_acquire_return_flock(
        descriptor: int,
        operation: int,
    ) -> Any:
        result = original_acquire_return_flock(descriptor, operation)
        list.append(acquire_return_flock_calls, (descriptor, operation))
        return result

    def observe_acquire_return_close(descriptor: int) -> None:
        original_acquire_return_close(descriptor)
        list.append(acquire_return_close_calls, descriptor)

    def interrupt_acquire_return(
        frame: Any,
        event: str,
        argument: Any,
    ) -> Any:
        nonlocal acquire_return_descriptor
        if (
            event == "return"
            and frame.f_code is _fixture_br_acquire_file_lock.__code__
        ):
            lease = frame.f_locals.get("lease")
            if type(lease) is FixtureBrLease:
                acquire_return_descriptor = lease.descriptor
                list.append(acquire_return_retained_leases, lease)
            list.append(acquire_return_retained_arguments, argument)
            sys.settrace(None)
            raise acquire_return_primary
        return interrupt_acquire_return

    prior_acquire_return_trace = sys.gettrace()
    _fixture_br_thread_guard = acquire_return_guard
    fcntl.flock = observe_acquire_return_flock
    os.close = observe_acquire_return_close
    sys.settrace(interrupt_acquire_return)
    try:
        try:
            with fixture_br_lease():
                acquire_return_body_entered = True
        except BaseException as error:
            acquire_return_observed = error
    finally:
        sys.settrace(prior_acquire_return_trace)
        _fixture_br_thread_guard = original_thread_guard
        fcntl.flock = original_acquire_return_flock
        os.close = original_acquire_return_close
    acquire_return_lease = (
        acquire_return_retained_leases[-1]
        if acquire_return_retained_leases
        else None
    )
    acquire_return_owner_relinquished = (
        type(acquire_return_lease) is FixtureBrLease
        and acquire_return_lease._descriptor_owner._descriptor is None
    )
    acquire_return_state_pristine = (
        _fixture_br_lock_depth == 0
        and _fixture_br_active_lease is None
    )
    acquire_return_production_guard_release_calls = (
        acquire_return_guard.release_calls
    )
    (
        acquire_return_guard_reacquired,
        acquire_return_guard_worker_alive,
        acquire_return_guard_worker_errors,
    ) = probe_guard_from_other_thread(
        acquire_return_guard,
        name="v2-fixture-acquire-return-guard-probe",
    )
    acquire_return_test_cleanup_performed = False
    if (
        type(acquire_return_lease) is FixtureBrLease
        and acquire_return_lease._descriptor_owner._descriptor is not None
    ):
        acquire_return_test_cleanup_performed = True
        _fixture_br_release_file_lock(acquire_return_lease)

    class OwnerSlotSubclass(list[Any]):
        pass

    def observe_owner_slot_refusal(callback: Callable[[], Any]) -> str:
        try:
            callback()
        except HarnessError as error:
            return error.terminal
        except BaseException as error:
            return v2_raw_type_name(type(error))
        return "Pass"

    owner_slot_validation = {
        "guard-tuple": observe_owner_slot_refusal(
            lambda: _fixture_br_try_acquire_thread_guard(
                owner_slot=(None,)
            )
        ),
        "guard-list-subclass": observe_owner_slot_refusal(
            lambda: _fixture_br_try_acquire_thread_guard(
                owner_slot=OwnerSlotSubclass([None])
            )
        ),
        "guard-wrong-length": observe_owner_slot_refusal(
            lambda: _fixture_br_try_acquire_thread_guard(owner_slot=[])
        ),
        "guard-occupied": observe_owner_slot_refusal(
            lambda: _fixture_br_try_acquire_thread_guard(
                owner_slot=[object()]
            )
        ),
        "open-target-tuple": observe_owner_slot_refusal(
            lambda: _fixture_br_open_lock_descriptor(
                descriptor_owner_slot=(None,),
                parent_owner_slot=[None],
            )
        ),
        "open-target-list-subclass": observe_owner_slot_refusal(
            lambda: _fixture_br_open_lock_descriptor(
                descriptor_owner_slot=OwnerSlotSubclass([None]),
                parent_owner_slot=[None],
            )
        ),
        "open-parent-wrong-length": observe_owner_slot_refusal(
            lambda: _fixture_br_open_lock_descriptor(
                descriptor_owner_slot=[None],
                parent_owner_slot=[],
            )
        ),
        "open-parent-occupied": observe_owner_slot_refusal(
            lambda: _fixture_br_open_lock_descriptor(
                descriptor_owner_slot=[None],
                parent_owner_slot=[object()],
            )
        ),
        "acquire-tuple": observe_owner_slot_refusal(
            lambda: _fixture_br_acquire_file_lock(
                lease_slot=(None,)
            )
        ),
        "acquire-list-subclass": observe_owner_slot_refusal(
            lambda: _fixture_br_acquire_file_lock(
                lease_slot=OwnerSlotSubclass([None])
            )
        ),
        "acquire-wrong-length": observe_owner_slot_refusal(
            lambda: _fixture_br_acquire_file_lock(lease_slot=[])
        ),
        "acquire-occupied": observe_owner_slot_refusal(
            lambda: _fixture_br_acquire_file_lock(
                lease_slot=[object()]
            )
        ),
    }

    def exercise_scope_cleanup_phase(phase: str) -> dict[str, Any]:
        global _fixture_br_thread_guard
        if phase not in {
            "fixture-entry",
            "helper-pre-depth",
            "helper-post-depth",
            "helper-release-entry",
            "helper-post-lease",
            "helper-guard-entry",
        }:
            raise EvidenceFailed("unknown fixture cleanup phase probe")
        if _fixture_br_lock_depth != 0 or _fixture_br_active_lease is not None:
            raise EvidenceFailed(
                "fixture cleanup phase probe inherited non-pristine state"
            )

        class SyntheticScopeBodyPrimary(RuntimeError):
            pass

        class SyntheticScopeCleanupPrimary(RuntimeError):
            pass

        phase_ordinal = {
            "fixture-entry": 1,
            "helper-pre-depth": 2,
            "helper-post-depth": 3,
            "helper-release-entry": 4,
            "helper-post-lease": 5,
            "helper-guard-entry": 6,
        }[phase]
        fake_descriptor = 910_000 + phase_ordinal
        fake_owner = FixtureBrDescriptorOwner(fake_descriptor)
        fake_lease = FixtureBrLease(
            _descriptor_owner=fake_owner,
            lock_path=Path(".beads") / ".fixture-br-v2.lock",
            device=1,
            inode=1,
            contended=False,
            wait_polls=0,
        )
        fake_guard = CountingThreadGuard()
        body_primary = SyntheticScopeBodyPrimary(
            f"synthetic body primary for {phase}"
        )
        cleanup_primary = SyntheticScopeCleanupPrimary(
            f"synthetic cleanup interruption for {phase}"
        )
        release_calls: list[FixtureBrLease] = []
        retained_leases: list[FixtureBrLease] = []
        retained_guard_owners: list[FixtureBrThreadGuardOwner] = []
        known_guard_owner: FixtureBrThreadGuardOwner | None = None
        injected = False
        observed: BaseException | None = None

        def fake_acquire(
            *,
            lease_slot: list[FixtureBrLease | None],
        ) -> None:
            list.__setitem__(lease_slot, 0, fake_lease)

        def fake_release(lease: FixtureBrLease) -> None:
            list.append(release_calls, lease)
            lease._descriptor_owner._descriptor = None

        def interrupt_cleanup_phase(
            frame: Any,
            event: str,
            _argument: Any,
        ) -> Any:
            nonlocal injected
            nonlocal known_guard_owner
            if (
                injected
                or event != "line"
                or sys.exception() is not body_primary
            ):
                return interrupt_cleanup_phase
            is_fixture_entry = (
                phase == "fixture-entry"
                and frame.f_code is fixture_br_lease.__wrapped__.__code__
                and _fixture_br_lock_depth == 1
                and _fixture_br_active_lease is fake_lease
                and not release_calls
                and fake_owner._descriptor == fake_descriptor
            )
            is_helper_pre_depth = (
                phase == "helper-pre-depth"
                and frame.f_code is _fixture_br_cleanup_lease_scope.__code__
                and _fixture_br_lock_depth == 1
                and _fixture_br_active_lease is fake_lease
                and not release_calls
                and fake_owner._descriptor == fake_descriptor
            )
            is_helper_post_depth = (
                phase == "helper-post-depth"
                and frame.f_code is _fixture_br_cleanup_lease_scope.__code__
                and _fixture_br_lock_depth == 0
                and _fixture_br_active_lease is fake_lease
                and not release_calls
                and fake_owner._descriptor == fake_descriptor
            )
            guard_owner_slot = frame.f_locals.get("guard_owner_slot")
            retained_guard_owner = (
                list.__getitem__(guard_owner_slot, 0)
                if type(guard_owner_slot) is list
                and len(guard_owner_slot) == 1
                else None
            )
            if type(retained_guard_owner) is FixtureBrThreadGuardOwner:
                known_guard_owner = retained_guard_owner
            elif (
                frame.f_code is FixtureBrThreadGuardOwner.release.__code__
                and type(frame.f_locals.get("self"))
                is FixtureBrThreadGuardOwner
            ):
                known_guard_owner = frame.f_locals["self"]
            is_helper_release_entry = (
                phase == "helper-release-entry"
                and frame.f_code is fake_release.__code__
                and _fixture_br_lock_depth == 0
                and _fixture_br_active_lease is fake_lease
                and not release_calls
                and fake_owner._descriptor == fake_descriptor
            )
            is_helper_post_lease = (
                phase == "helper-post-lease"
                and frame.f_code is _fixture_br_cleanup_lease_scope.__code__
                and _fixture_br_lock_depth == 0
                and release_calls == [fake_lease]
                and fake_owner._descriptor is None
                and type(retained_guard_owner)
                is FixtureBrThreadGuardOwner
                and retained_guard_owner._owns_guard
            )
            is_helper_guard_entry = (
                phase == "helper-guard-entry"
                and frame.f_code
                is FixtureBrThreadGuardOwner.release.__code__
                and _fixture_br_lock_depth == 0
                and release_calls == [fake_lease]
                and fake_owner._descriptor is None
                and type(known_guard_owner)
                is FixtureBrThreadGuardOwner
                and known_guard_owner._owns_guard
            )
            if not (
                is_fixture_entry
                or is_helper_pre_depth
                or is_helper_post_depth
                or is_helper_release_entry
                or is_helper_post_lease
                or is_helper_guard_entry
            ):
                return interrupt_cleanup_phase
            injected = True
            list.append(retained_leases, fake_lease)
            if type(known_guard_owner) is FixtureBrThreadGuardOwner:
                list.append(retained_guard_owners, known_guard_owner)
            sys.settrace(None)
            raise cleanup_primary

        original_phase_guard = _fixture_br_thread_guard
        original_phase_acquire = globals()["_fixture_br_acquire_file_lock"]
        original_phase_release = globals()["_fixture_br_release_file_lock"]
        prior_phase_trace = sys.gettrace()
        _fixture_br_thread_guard = fake_guard
        globals()["_fixture_br_acquire_file_lock"] = fake_acquire
        globals()["_fixture_br_release_file_lock"] = fake_release
        sys.settrace(interrupt_cleanup_phase)
        try:
            try:
                with fixture_br_lease():
                    raise body_primary
            except BaseException as error:
                observed = error
        finally:
            phase_execution_error = sys.exception()
            sys.settrace(prior_phase_trace)
            _fixture_br_thread_guard = original_phase_guard
            globals()["_fixture_br_acquire_file_lock"] = (
                original_phase_acquire
            )
            globals()["_fixture_br_release_file_lock"] = (
                original_phase_release
            )
            if phase_execution_error is not None:
                fake_owner._descriptor = None
                try:
                    fake_guard.release()
                except RuntimeError:
                    pass
                globals()["_fixture_br_lock_depth"] = 0
                globals()["_fixture_br_active_lease"] = None
        retained_guard_owner = (
            retained_guard_owners[-1]
            if retained_guard_owners
            else None
        )
        production_guard_release_calls = fake_guard.release_calls
        production_state_pristine = (
            _fixture_br_lock_depth == 0
            and _fixture_br_active_lease is None
        )
        (
            other_thread_acquired,
            worker_alive,
            worker_errors,
        ) = probe_guard_from_other_thread(
            fake_guard,
            name=f"v2-fixture-cleanup-{phase}",
        )
        row = {
            "injected": injected,
            "primary_preserved": observed is body_primary,
            "release_count": len(release_calls),
            "released_exact_lease": release_calls == [fake_lease],
            "descriptor_owner_relinquished": (
                fake_owner._descriptor is None
            ),
            "guard_owner_relinquished": (
                type(retained_guard_owner) is FixtureBrThreadGuardOwner
                and not retained_guard_owner._owns_guard
            ),
            "guard_release_calls": production_guard_release_calls,
            "state_pristine": production_state_pristine,
            "retained_lease_count": len(retained_leases),
            "retained_guard_owner_count": len(retained_guard_owners),
            "other_thread_acquired": other_thread_acquired,
            "worker_alive": worker_alive,
            "worker_errors": worker_errors,
            "test_cleanup_performed": False,
        }
        if fake_owner._descriptor is not None:
            row["test_cleanup_performed"] = True
            fake_owner._descriptor = None
        if (
            type(retained_guard_owner) is FixtureBrThreadGuardOwner
            and retained_guard_owner._owns_guard
        ):
            row["test_cleanup_performed"] = True
            retained_guard_owner.release()
        if (
            _fixture_br_lock_depth != 0
            or _fixture_br_active_lease is not None
        ):
            row["test_cleanup_performed"] = True
            globals()["_fixture_br_lock_depth"] = 0
            globals()["_fixture_br_active_lease"] = None
        return row

    scope_cleanup_phases = {
        phase: exercise_scope_cleanup_phase(phase)
        for phase in (
            "fixture-entry",
            "helper-pre-depth",
            "helper-post-depth",
            "helper-release-entry",
            "helper-post-lease",
            "helper-guard-entry",
        )
    }

    class SyntheticUnlockPrimary(RuntimeError):
        pass

    raw_unlock_lease_slot: list[FixtureBrLease | None] = [None]
    _fixture_br_acquire_file_lock(lease_slot=raw_unlock_lease_slot)
    raw_unlock_lease = list.__getitem__(raw_unlock_lease_slot, 0)
    if type(raw_unlock_lease) is not FixtureBrLease:
        raise EvidenceFailed("raw-unlock probe did not receive its lease")
    raw_unlock_descriptor = raw_unlock_lease.descriptor
    raw_unlock_close_calls: list[int] = []
    original_unlock_flock = fcntl.flock
    original_unlock_close = os.close

    def fail_raw_unlock(descriptor: int, operation: int) -> Any:
        if (
            descriptor == raw_unlock_descriptor
            and operation == fcntl.LOCK_UN
        ):
            raise SyntheticUnlockPrimary("synthetic raw unlock failure")
        return original_unlock_flock(descriptor, operation)

    def observe_raw_unlock_close(descriptor: int) -> None:
        original_unlock_close(descriptor)
        if descriptor == raw_unlock_descriptor:
            list.append(raw_unlock_close_calls, descriptor)

    fcntl.flock = fail_raw_unlock
    os.close = observe_raw_unlock_close
    raw_unlock_production_close_count = -1
    raw_unlock_production_owner_relinquished = False
    raw_unlock_test_cleanup_performed = False
    try:
        try:
            _fixture_br_release_file_lock(raw_unlock_lease)
        except SyntheticUnlockPrimary as error:
            raw_unlock_primary = v2_raw_type_name(type(error))
            raw_unlock_primary_message = str(error)
        else:
            raw_unlock_primary = "Pass"
            raw_unlock_primary_message = None
        raw_unlock_production_close_count = len(raw_unlock_close_calls)
        raw_unlock_production_owner_relinquished = (
            raw_unlock_lease._descriptor_owner._descriptor is None
        )
    finally:
        fcntl.flock = original_unlock_flock
        os.close = original_unlock_close
        if raw_unlock_lease._descriptor_owner._descriptor is not None:
            raw_unlock_test_cleanup_performed = True
            raw_unlock_lease._descriptor_owner.close()
    raw_unlock_post_teardown_owner_relinquished = (
        raw_unlock_lease._descriptor_owner._descriptor is None
    )

    class SyntheticReleaseBetweenAttemptsPrimary(RuntimeError):
        pass

    release_between_lease_slot: list[FixtureBrLease | None] = [None]
    _fixture_br_acquire_file_lock(lease_slot=release_between_lease_slot)
    release_between_lease = list.__getitem__(release_between_lease_slot, 0)
    if type(release_between_lease) is not FixtureBrLease:
        raise EvidenceFailed(
            "release-boundary probe did not receive its lease"
        )
    release_between_descriptor = release_between_lease.descriptor
    release_between_unlock_returned = False
    release_between_close_calls: list[int] = []

    def observe_release_between_flock(
        descriptor: int,
        operation: int,
    ) -> Any:
        nonlocal release_between_unlock_returned
        result = original_unlock_flock(descriptor, operation)
        if (
            descriptor == release_between_descriptor
            and operation == fcntl.LOCK_UN
        ):
            release_between_unlock_returned = True
        return result

    def observe_release_between_close(descriptor: int) -> None:
        original_unlock_close(descriptor)
        if descriptor == release_between_descriptor:
            list.append(release_between_close_calls, descriptor)

    def interrupt_release_between_attempts(
        frame: Any,
        event: str,
        _argument: Any,
    ) -> Any:
        if (
            event == "line"
            and frame.f_code is _fixture_br_release_file_lock.__code__
            and release_between_unlock_returned
            and release_between_lease._descriptor_owner._descriptor
            == release_between_descriptor
        ):
            sys.settrace(None)
            raise SyntheticReleaseBetweenAttemptsPrimary(
                "synthetic release interruption between cleanup attempts"
            )
        return interrupt_release_between_attempts

    prior_release_between_trace = sys.gettrace()
    fcntl.flock = observe_release_between_flock
    os.close = observe_release_between_close
    sys.settrace(interrupt_release_between_attempts)
    release_between_production_close_count = -1
    release_between_production_owner_relinquished = False
    release_between_test_cleanup_performed = False
    try:
        try:
            _fixture_br_release_file_lock(release_between_lease)
        except SyntheticReleaseBetweenAttemptsPrimary as error:
            release_between_primary = v2_raw_type_name(type(error))
        else:
            release_between_primary = "Pass"
        release_between_production_close_count = len(
            release_between_close_calls
        )
        release_between_production_owner_relinquished = (
            release_between_lease._descriptor_owner._descriptor is None
        )
    finally:
        sys.settrace(prior_release_between_trace)
        fcntl.flock = original_unlock_flock
        os.close = original_unlock_close
        if release_between_lease._descriptor_owner._descriptor is not None:
            release_between_test_cleanup_performed = True
            release_between_lease._descriptor_owner.close()
    release_between_post_teardown_owner_relinquished = (
        release_between_lease._descriptor_owner._descriptor is None
    )
    return {
        "guard_pre_owner_window_observed": (
            guard_pre_owner_window_observed
        ),
        "guard_delivery_interrupted": guard_delivery_interrupted,
        "guard_reacquired_other_thread": guard_reacquired_other_thread,
        "guard_worker_alive": guard_worker_alive,
        "guard_worker_errors": guard_worker_errors,
        "guard_release_pre_call": {
            "interrupted": guard_release_interrupted,
            "primary": guard_release_primary,
            "owner_retained": guard_owner_retained_before_retry,
            "release_calls_after_interruption": (
                guard_release_calls_after_interruption
            ),
            "other_thread_acquired_before_retry": (
                guard_reacquired_before_retry
            ),
            "other_thread_alive_before_retry": guard_retry_probe_alive,
            "other_thread_errors_before_retry": guard_retry_probe_errors,
            "other_thread_acquired_after_retry": (
                guard_reacquired_after_retry
            ),
            "other_thread_alive_after_retry": (
                guard_post_retry_probe_alive
            ),
            "other_thread_errors_after_retry": (
                guard_post_retry_probe_errors
            ),
        },
        "guard_finalizer_pre_call": {
            "interrupted": guard_finalizer_interrupted,
            "owner_relinquished": guard_finalizer_owner_relinquished,
            "release_calls": guard_finalizer_release_calls,
            "other_thread_acquired": guard_reacquired_after_finalizer,
            "other_thread_alive": guard_finalizer_probe_alive,
