            ),
            "other_thread_acquired": guard_reacquired_after_post_call,
            "other_thread_alive": guard_post_call_probe_alive,
            "other_thread_errors": guard_post_call_probe_errors,
        },
        "depth_delivery_interrupted": depth_delivery_interrupted,
        "depth_body_entered": depth_body_entered,
