            ),
            "closed_expected_descriptor": (
                descriptor_post_call_close_calls
                == [post_call_descriptor]
            ),
            "owner_relinquished": (
                descriptor_post_call_owner_relinquished
            ),
        },
        "guard_return_handoff": {
            "primary_preserved": (
                guard_return_observed is guard_return_primary
            ),
            "retained_owner_count": len(guard_return_retained_owners),
            "body_entered": guard_return_body_entered,
            "owner_relinquished": guard_return_owner_relinquished,
            "release_calls": guard_return_production_release_calls,
            "state_pristine": guard_return_state_pristine,
            "other_thread_acquired": (
                guard_return_reacquired_other_thread
            ),
            "other_thread_alive": guard_return_worker_alive,
            "other_thread_errors": guard_return_worker_errors,
            "test_cleanup_performed": (
                guard_return_test_cleanup_performed
            ),
        },
        "open_return_handoff": {
            "primary_preserved": (
                open_return_observed is open_return_primary
            ),
            "retained_argument_count": len(
                open_return_retained_arguments
            ),
            "opened_descriptor_count": len(open_return_descriptors),
            "target_closed_once": (
                type(open_return_target_descriptor) is int
                and open_return_close_calls.count(
                    open_return_target_descriptor
                )
                == 1
            ),
            "parent_closed_once": (
                type(open_return_parent_descriptor) is int
                and open_return_close_calls.count(
                    open_return_parent_descriptor
                )
                == 1
            ),
            "target_owner_relinquished": (
                open_return_production_target_relinquished
            ),
            "parent_owner_relinquished": (
                open_return_production_parent_relinquished
            ),
            "lease_slot_empty": (
                list.__getitem__(open_return_lease_slot, 0) is None
            ),
            "test_cleanup_performed": (
                open_return_test_cleanup_performed
            ),
        },
        "acquire_return_handoff": {
            "primary_preserved": (
                acquire_return_observed is acquire_return_primary
            ),
            "retained_lease_count": len(acquire_return_retained_leases),
            "retained_argument_count": len(
                acquire_return_retained_arguments
            ),
            "body_entered": acquire_return_body_entered,
            "lock_count": sum(
                1
                for descriptor, operation in acquire_return_flock_calls
                if descriptor == acquire_return_descriptor
                and operation == fcntl.LOCK_EX | fcntl.LOCK_NB
            ),
            "unlock_count": sum(
                1
                for descriptor, operation in acquire_return_flock_calls
                if descriptor == acquire_return_descriptor
                and operation == fcntl.LOCK_UN
            ),
            "close_count": acquire_return_close_calls.count(
                acquire_return_descriptor
            ),
            "owner_relinquished": acquire_return_owner_relinquished,
            "guard_release_calls": (
                acquire_return_production_guard_release_calls
            ),
            "state_pristine": acquire_return_state_pristine,
            "guard_reacquired_other_thread": (
                acquire_return_guard_reacquired
            ),
            "guard_worker_alive": acquire_return_guard_worker_alive,
            "guard_worker_errors": acquire_return_guard_worker_errors,
            "test_cleanup_performed": (
                acquire_return_test_cleanup_performed
            ),
        },
        "owner_slot_validation": owner_slot_validation,
        "scope_cleanup_phases": scope_cleanup_phases,
        "raw_unlock_primary": raw_unlock_primary,
        "raw_unlock_primary_message": raw_unlock_primary_message,
        "raw_unlock_close_count": raw_unlock_production_close_count,
        "raw_unlock_closed_expected_descriptor": (
            raw_unlock_production_close_count == 1
            and raw_unlock_close_calls[0] == raw_unlock_descriptor
        ),
        "raw_unlock_owner_relinquished": (
            raw_unlock_production_owner_relinquished
        ),
        "raw_unlock_test_cleanup_performed": (
            raw_unlock_test_cleanup_performed
        ),
        "raw_unlock_post_teardown_owner_relinquished": (
            raw_unlock_post_teardown_owner_relinquished
        ),
        "release_between_attempts": {
            "unlock_returned": release_between_unlock_returned,
            "primary": release_between_primary,
            "close_count": release_between_production_close_count,
            "closed_expected_descriptor": (
                release_between_production_close_count == 1
                and release_between_close_calls[0]
                == release_between_descriptor
            ),
            "owner_relinquished": (
                release_between_production_owner_relinquished
            ),
            "test_cleanup_performed": (
                release_between_test_cleanup_performed
            ),
            "post_teardown_owner_relinquished": (
                release_between_post_teardown_owner_relinquished
            ),
        },
    }


def fixture_br_external_lock_probe(
    lease: FixtureBrLease,
    *,
    expected: str,
) -> None:
    if expected not in {"ACQUIRED", "CONTENDED"}:
        raise EvidenceFailed("fixture lock probe expectation is unknown")
    try:
        path_state = os.lstat(lease.lock_path)
    except OSError as error:
        raise InfrastructureFailed(
            "fixture lock probe path cannot be inspected safely"
        ) from error
    if (
        not stat.S_ISREG(path_state.st_mode)
        or path_state.st_nlink != 1
        or path_state.st_dev != lease.device
        or path_state.st_ino != lease.inode
    ):
        raise InfrastructureFailed(
            "fixture lock probe path identity differs from its lease"
        )
    probe = (
        "import fcntl, os, stat, sys\n"
        "flags = os.O_RDWR | getattr(os, 'O_NOFOLLOW', 0)\n"
        "descriptor = os.open(sys.argv[1], flags)\n"
        "try:\n"
        "    value = os.fstat(descriptor)\n"
        "    if not stat.S_ISREG(value.st_mode) or value.st_nlink != 1:\n"
        "        raise SystemExit(3)\n"
        "    try:\n"
        "        fcntl.flock(descriptor, fcntl.LOCK_EX | fcntl.LOCK_NB)\n"
        "    except BlockingIOError:\n"
        "        state = 'CONTENDED'\n"
        "    else:\n"
        "        state = 'ACQUIRED'\n"
        "        fcntl.flock(descriptor, fcntl.LOCK_UN)\n"
        "    sys.stdout.write(state)\n"
        "finally:\n"
        "    os.close(descriptor)\n"
    )
    completed = run_command(
        (sys.executable, "-c", probe, str(lease.lock_path)),
        record_global_receipt=False,
        stdout_bytes_cap=32,
        stderr_bytes_cap=1024,
    )
    observed = completed.stdout.strip()
    if observed != expected:
        raise EvidenceFailed(
            "fixture lock cross-process probe differed: "
            f"expected {expected}, observed {observed or 'EMPTY'}"
        )


def fixture_equal(actual: Any, expected: Any, label: str) -> None:
    if actual != expected:
        raise EvidenceFailed(
            f"{label}: expected {expected!r}, observed {actual!r}"
        )


def fixture_true(condition: bool, label: str) -> None:
    if not condition:
        raise EvidenceFailed(label)


def fixture_expected_missing(issue_type: str) -> tuple[str, ...]:
    return tuple(FIXTURE_REQUIRED_SECTIONS_BY_TYPE.get(issue_type, ()))


def fixture_lint(
    issues: Sequence[Mapping[str, Any]],
    missing: Mapping[str, Sequence[str]],
    *,
    status_scopes: Sequence[str] = STATUS_SCOPES,
) -> dict[str, Any]:
    if len(issues) > CAPS["issues"]:
        raise EvidenceFailed(
            f"fixture issue count exceeds {CAPS['issues']} cap"
        )
    issue_ids = [str(issue.get("id") or "") for issue in issues]
    if any(not issue_id for issue_id in issue_ids):
        raise EvidenceFailed("fixture contains an empty issue ID")
    if len(issue_ids) != len(set(issue_ids)):
        raise EvidenceFailed("fixture contains duplicate issue IDs")
    extra_missing_ids = sorted(set(missing) - set(issue_ids))
    if extra_missing_ids:
        raise EvidenceFailed(
            f"fixture missing map has unknown issue {extra_missing_ids[0]}"
        )

    canonical_status_scopes = v2_canonical_status_scopes(status_scopes)
    allowed_statuses = set(canonical_status_scopes)
    normalized_missing: dict[str, tuple[str, ...]] = {}
    warning_total = 0
    for issue in issues:
        issue_id = str(issue["id"])
        status = str(issue.get("status") or "")
        priority = issue.get("priority")
        issue_type = str(issue.get("type") or "")
        if status not in allowed_statuses:
            raise EvidenceFailed(
                f"fixture {issue_id} has unknown status {status!r}"
            )
        if not isinstance(priority, int) or priority not in range(5):
            raise EvidenceFailed(
                f"fixture {issue_id} has priority outside P0-P4"
            )
        if not issue_type:
            raise EvidenceFailed(f"fixture {issue_id} has empty type")
        raw_sections = tuple(str(section) for section in missing.get(issue_id, ()))
        if any(not section for section in raw_sections):
            raise EvidenceFailed(
                f"fixture {issue_id} contains an empty missing section"
            )
        if len(raw_sections) != len(set(raw_sections)):
            raise EvidenceFailed(
                f"fixture {issue_id} contains duplicate missing sections"
            )
        sections = v2_canonical_missing_sections(issue_type, raw_sections)
        if len(sections) > FIXTURE_MAX_WARNINGS_PER_ISSUE:
            raise EvidenceFailed(
                f"fixture {issue_id} exceeds per-issue warning cap"
            )
        normalized_missing[issue_id] = sections
        warning_total += len(sections)
    if warning_total > CAPS["warnings"]:
        raise EvidenceFailed(
            f"fixture warning count exceeds {CAPS['warnings']} cap"
        )

    result: dict[str, Any] = {}
    for scope in (*canonical_status_scopes, "all"):
        selected: list[dict[str, Any]] = []
        for issue in sorted(issues, key=lambda row: str(row["id"])):
            sections = normalized_missing[str(issue["id"])]
            if not sections:
                continue
            if scope != "all" and issue["status"] != scope:
                continue
            selected.append(
                {
                "id": issue["id"],
                "title": issue["title"],
                "type": issue["type"],
                    "missing": list(sections),
                    "warnings": len(sections),
                    "suggestions": [
                        {
                            "section": section,
                            "hint": LINT_SECTION_HINTS_BY_TYPE.get(
                                str(issue["type"]), {}
                            ).get(
                                section,
                                "Synthetic fixture-only missing-section hint",
                            ),
                        }
                        for section in sections
                    ],
                }
            )
        result[scope] = {
            "total": sum(row["warnings"] for row in selected),
            "issues": len(selected),
            "results": selected,
        }
    return result


def fixture_source(
    issues: Sequence[Mapping[str, Any]] = (),
    *,
    status_scopes: Sequence[str] = STATUS_SCOPES,
) -> dict[str, Any]:
    canonical_status_scopes = v2_canonical_status_scopes(status_scopes)
    ordered_issues = sorted(
        (dict(issue) for issue in issues),
        key=lambda issue: str(issue.get("id") or ""),
    )
    source: dict[str, Any] = {
        "schema": SOURCE_SCHEMA,
        "br_version": "fixture",
        "case_manifest_root": "fixture",
        "live_issue_count": len(ordered_issues),
        "live_issue_projection_root": semantic_root(ordered_issues),
        "lint_issue_projection_root": "fixture",
        "status_summary": {
            status: sum(issue.get("status") == status for issue in ordered_issues)
            for status in canonical_status_scopes
        },
        "files": [],
        "status_cut": [*canonical_status_scopes, "all"],
    }
    source["semantic_root"] = semantic_root(source)
    return source


def fixture_inventory(
    issues: Sequence[Mapping[str, Any]],
    missing: Mapping[str, Sequence[str]],
    *,
    findings: Mapping[str, Mapping[str, str]] | None = None,
) -> dict[str, Any]:
    lint = fixture_lint(issues, missing)
    issue_ids = {
        str(row["id"])
        for row in lint["all"]["results"]
    } | set((findings or {}).keys())
    selected = [issue for issue in issues if str(issue["id"]) in issue_ids]
    return assemble_inventory(
        lint,
        selected,
        fixture_source(issues),
        findings,
    )


def fixture_reviewed_apply_admission() -> tuple[LiveSnapshot, dict[str, Any]]:
    acceptance = (
        "1. Run `tests/e2e/template_apply.rs` against the explicit fixture.\n"
        "2. Retain deterministic logs, inverse replay, and source closure.\n"
        "3. Refuse stale roots, wrong owners, and any substantive text change.\n"
        "4. Preserve the no-claim boundary after the bounded test passes."
    )
    issue = fixture_issue(
        issue_id="fixture-reviewed-apply",
        description="Exact fixture scope remains byte-preserved.",
        acceptance=acceptance,
        assignee="FixtureOwner",
        labels=("authority:template-hygiene",),
    )
    lint = fixture_lint(
        [issue],
        {issue["id"]: ("## Acceptance Criteria",)},
    )
    source = fixture_source([issue])
    inventory = assemble_inventory(lint, [issue], source)
    inventory["rows"][0]["disposition"] = "SECTION_NAME_ONLY"
    inventory["rows"][0]["rationale"] = (
        "fixture owner review is explicitly bound to the exact roots"
    )
    inventory["rows"][0]["semantic_flags"]["section_only_review_bound"] = True
    inventory["warning_rows"][0]["disposition"] = "SECTION_NAME_ONLY"
    inventory["counts"]["by_disposition"] = {"SECTION_NAME_ONLY": 1}
    inventory.pop("semantic_root", None)
    inventory["semantic_root"] = semantic_root(inventory)
    plan = build_plan(inventory, [issue])
    proposal = dict(plan["section_name_only_proposals"][0])
    proposal_root = semantic_root(proposal)
    row = dict(proposal)
    row.update(
        {
            "reviewed": True,
            "reviewed_by": "FixtureOwner",
            "current_owner": "FixtureOwner",
            "agent_name": "FixtureAgent",
            "authority_domain": "authority:template-hygiene",
            "proposal_root": proposal_root,
        }
    )
    document = {
        "schema": APPLY_SCHEMA,
        "target_id": issue["id"],
        "inventory_root": inventory["semantic_root"],
        "plan_root": plan["semantic_root"],
        "proposal_root": proposal_root,
        "reviewed": True,
        "reviewed_by": "FixtureOwner",
        "current_owner": "FixtureOwner",
        "agent_name": "FixtureAgent",
        "reservation_receipt": "fixture-root-bound-receipt",
        "authority_domain": "authority:template-hygiene",
        "rows": [row],
    }
    return LiveSnapshot(lint, [issue], source, inventory, plan), document


def expect_error(
    error_type: type[HarnessError],
    callback: Callable[[], Any],
    *,
    contains: str | None = None,
) -> HarnessError:
    try:
        callback()
    except error_type as error:
        if contains is not None and contains not in str(error):
            raise EvidenceFailed(
                f"{error_type.__name__} diagnostic lacks {contains!r}: {error}"
            ) from error
        return error
    raise EvidenceFailed(f"expected {error_type.__name__} was not raised")


def fixture_br_argv(*arguments: str) -> tuple[str, ...]:
    return (
        "br",
        *arguments,
        "--db",
        FIXTURE_BR_DB_ARG,
        "--no-auto-flush",
        "--no-auto-import",
        "--no-color",
    )


def fixture_br_run(
    *arguments: str,
    input_text: str | None = None,
    honor_cancel: bool = True,
) -> subprocess.CompletedProcess[str]:
    if type(honor_cancel) is not bool:
        raise EvidenceFailed(
            "fixture br command cancellation policy is malformed"
        )
    with fixture_br_lease(honor_cancel=honor_cancel):
        fixture_root = resolve_safe(
            str(FIXTURE_BR_ROOT_REL),
            label="no-mock fixture root",
            must_exist=True,
        )
        return run_command(
            fixture_br_argv(*arguments),
            input_text=input_text,
            command_cwd=fixture_root,
            honor_cancel=honor_cancel,
            record_global_receipt=False,
        )


def fixture_br_json(
    *arguments: str,
    input_text: str | None = None,
    honor_cancel: bool = True,
) -> Any:
    completed = fixture_br_run(
        *arguments,
        "--json",
        input_text=input_text,
        honor_cancel=honor_cancel,
    )
    return v2_decode_released_br_json(
        completed.stdout,
        label=f"fixture br {arguments[0]} output",
    )


def fixture_br_list(
    *,
    honor_cancel: bool = True,
) -> list[dict[str, Any]]:
    document = fixture_br_json(
        "list",
        "--all",
        "--deferred",
        "--limit",
        "0",
        honor_cancel=honor_cancel,
    )
    return v2_normalize_released_br_list_rows(
        document,
        label="fixture br database list",
    )


def fixture_br_export_list(
    *,
    honor_cancel: bool = True,
) -> list[dict[str, Any]]:
    """Read the fixture's exported JSONL through released br, never directly."""
    with fixture_br_lease(honor_cancel=honor_cancel):
        fixture_root = resolve_safe(
            str(FIXTURE_BR_ROOT_REL),
            label="no-mock fixture root",
            must_exist=True,
        )
        completed = run_command(
            (
                "br",
                "list",
                "--all",
                "--deferred",
                "--limit",
                "0",
                "--json",
                "--no-db",
                "--no-auto-flush",
                "--no-auto-import",
                "--no-color",
            ),
            command_cwd=fixture_root,
            honor_cancel=honor_cancel,
            record_global_receipt=False,
        )
    document = v2_decode_released_br_json(
        completed.stdout,
        label="fixture br JSONL-only list output",
    )
    return v2_normalize_released_br_list_rows(
        document,
        label="fixture br JSONL-only list",
    )


def fixture_br_show(
    issue_id: str,
    *,
    honor_cancel: bool = True,
) -> dict[str, Any]:
    document = fixture_br_json(
        "show",
        issue_id,
        honor_cancel=honor_cancel,
    )
    if type(document) is not list or list.__len__(document) != 1:
        raise InfrastructureFailed(
            f"fixture br show did not return exactly {issue_id}"
        )
    issue = list.__getitem__(document, 0)
    if type(issue) is not dict:
        raise InfrastructureFailed("fixture br show row is not an exact object")
    v2_validate_raw_br_issue(issue)
    if dict.get(issue, "id") != issue_id:
        raise InfrastructureFailed("fixture br show returned the wrong issue")
    return dict(issue)


def fixture_br_restorable_projection(
    issue: Mapping[str, Any],
) -> dict[str, Any]:
    if type(issue) is not dict:
        raise InfrastructureFailed("fixture issue is not an exact object")
    v2_validate_raw_br_issue(issue)
    detached = v2_validate_exact_json_wire(
        issue,
        label="fixture restorable issue projection",
    )
    if type(detached) is not dict:
        raise InfrastructureFailed("fixture issue projection is not an object")
    projection = dict(detached)
    if dict.__contains__(projection, "updated_at"):
        dict.__delitem__(projection, "updated_at")
    for field in ("labels", "dependencies", "dependents", "comments"):
        if not dict.__contains__(projection, field):
            continue
        values = dict.__getitem__(projection, field)
        if type(values) is not list:
            raise InfrastructureFailed(
                f"fixture issue {field} is not an exact array"
            )
        dict.__setitem__(
            projection,
            field,
            sorted(values, key=lambda value: canonical_bytes(value)),
        )
    return projection


def fixture_br_semantic_projection(issue: Mapping[str, Any]) -> dict[str, Any]:
    return fixture_br_restorable_projection(issue)


def fixture_br_find_canonical(prefix: str) -> dict[str, Any] | None:
    if type(prefix) is not str or not prefix:
        raise EvidenceFailed("fixture canonical ID prefix is malformed")
    matches = [
        issue
        for issue in fixture_br_list()
        if type(dict.get(issue, "id")) is str
        and dict.__getitem__(issue, "id").startswith(prefix)
        and FIXTURE_BR_LABEL in (dict.get(issue, "labels") or [])
    ]
    if len(matches) > 1:
        raise EvidenceFailed(f"fixture contains duplicate canonical prefix {prefix!r}")
    return matches[0] if matches else None


def fixture_br_create_seed(
    *,
    title: str,
    slug: str,
    status: str,
    description: str,
    ephemeral: bool,
) -> dict[str, Any]:
    arguments = [
        "create",
        "--title",
        title,
        "--slug",
        slug,
        "--type",
        "task",
        "--priority",
        "4",
        "--status",
        status,
        "--description-file",
        "-",
        "--labels",
        FIXTURE_BR_LABEL,
    ]
    if ephemeral:
        arguments.append("--ephemeral")
    fixture_br_json(*arguments, input_text=description)
    created = fixture_br_find_canonical(f"thfx-{slug}-")
    if created is None:
        raise InfrastructureFailed(f"fixture br create did not retain {title!r}")
    return created


def fixture_br_set_status(
    issue_id: str,
    desired: str,
    *,
    honor_cancel: bool = True,
) -> None:
    current = fixture_br_show(issue_id, honor_cancel=honor_cancel)
    status = dict.get(current, "status")
    if type(status) is not str:
        raise InfrastructureFailed("fixture status is not an exact string")
    if status == desired:
        return
    if desired == "open" and status == "closed":
        fixture_br_json(
            "reopen",
            issue_id,
            "--reason",
            "template hygiene fixture restoration",
            honor_cancel=honor_cancel,
        )
        return
    if desired == "closed":
        fixture_br_json(
            "close",
            issue_id,
            "--reason",
            FIXTURE_BR_REGRESSION_CLOSE_REASON,
            honor_cancel=honor_cancel,
        )
        return
    fixture_br_json(
        "update",
        issue_id,
        "--status",
        desired,
        honor_cancel=honor_cancel,
    )


def fixture_br_set_description(
    issue_id: str,
    description: str,
    *,
    honor_cancel: bool = True,
) -> None:
    if type(description) is not str:
        raise EvidenceFailed("fixture description is not an exact string")
    current = fixture_br_show(issue_id, honor_cancel=honor_cancel)
    if dict.get(current, "description") == description:
        return
    fixture_br_json(
        "update",
        issue_id,
        "--description-file",
        "-",
        input_text=description,
        honor_cancel=honor_cancel,
    )


def fixture_br_set_title(
    issue_id: str,
    title: str,
    *,
    honor_cancel: bool = True,
) -> None:
    if type(title) is not str or not title:
        raise EvidenceFailed("fixture title is not an exact nonempty string")
    current = fixture_br_show(issue_id, honor_cancel=honor_cancel)
    if dict.get(current, "title") == title:
        return
    fixture_br_json(
        "update",
        issue_id,
        "--title",
        title,
        honor_cancel=honor_cancel,
    )


def fixture_br_validate_canonical_seed(
    issue: Mapping[str, Any],
    *,
    title: str,
    description: str,
    status: str,
    ephemeral: bool,
) -> None:
    if type(issue) is not dict:
        raise InfrastructureFailed("fixture canonical seed is not an exact object")
    v2_validate_raw_br_issue(issue)
    empty_optional_fields = (
        "acceptance_criteria",
        "design",
        "notes",
        "assignee",
        "owner",
        "parent",
        "due_at",
        "defer_until",
        "external_ref",
        "source_system",
        "agent_context",
    )
    if (
        issue.get("title") != title
        or issue.get("description") != description
        or issue.get("status") != status
        or issue.get("priority") != 4
        or issue.get("issue_type", issue.get("type")) != "task"
        or issue.get("labels") != [FIXTURE_BR_LABEL]
        or (issue.get("ephemeral") is True) is not ephemeral
        or issue.get("pinned") is True
        or issue.get("is_template") is True
        or issue.get("estimated_minutes") is not None
        or any(issue.get(field) not in {None, ""} for field in empty_optional_fields)
        or (issue.get("dependencies") or []) != []
        or (issue.get("dependents") or []) != []
    ):
        raise InfrastructureFailed("fixture canonical seed mutable state differs")


def fixture_br_context() -> dict[str, str]:
    with fixture_br_lease():
        return _fixture_br_context_locked()


def _fixture_br_ensure_canonical_seeds() -> tuple[str, str, bool]:
    fixture_initialized = False
    stable = fixture_br_find_canonical(FIXTURE_BR_STABLE_ID_PREFIX)
    if stable is None:
        stable = fixture_br_create_seed(
            title=FIXTURE_BR_STABLE_TITLE,
            slug="template-hygiene-actionable-v2",
            status="open",
            description=FIXTURE_BR_STABLE_DESCRIPTION,
            ephemeral=False,
        )
        fixture_initialized = True
    stable_id = stable["id"]
    stable = fixture_br_show(stable_id)
    fixture_br_validate_canonical_seed(
        stable,
        title=FIXTURE_BR_STABLE_TITLE,
        description=FIXTURE_BR_STABLE_DESCRIPTION,
        status="open",
        ephemeral=False,
    )

    regression = fixture_br_find_canonical(FIXTURE_BR_REGRESSION_ID_PREFIX)
    if regression is None:
        regression = fixture_br_create_seed(
            title=FIXTURE_BR_REGRESSION_TITLE,
            slug="template-hygiene-regression",
            status="open",
            description=FIXTURE_BR_REGRESSION_DESCRIPTION,
            ephemeral=True,
        )
        fixture_br_set_status(regression["id"], "closed")
        fixture_initialized = True
    regression_id = regression["id"]
    regression = fixture_br_show(regression_id)
    if (
        regression.get("status") != "closed"
        or regression.get("close_reason")
        != FIXTURE_BR_REGRESSION_CLOSE_REASON
        or regression.get("ephemeral") is not True
    ):
        raise InfrastructureFailed(
            "no-mock regression fixture lacks its exact closed ephemeral baseline"
        )
    fixture_br_validate_canonical_seed(
        regression,
        title=FIXTURE_BR_REGRESSION_TITLE,
        description=FIXTURE_BR_REGRESSION_DESCRIPTION,
        status="closed",
        ephemeral=True,
    )
    return stable_id, regression_id, fixture_initialized


def _fixture_br_context_locked() -> dict[str, str]:
    try:
        fixture_initialized = False
        fixture_root = resolve_safe(
            str(FIXTURE_BR_ROOT_REL),
            label="no-mock fixture root",
        )
        fixture_root.mkdir(parents=True, exist_ok=True)
        fixture_db = REPO_ROOT.joinpath(*FIXTURE_BR_DB_REL.parts)
        if not fixture_db.exists():
            fixture_br_run("init", "--prefix", "thfx")
            fixture_initialized = True
            if not fixture_db.exists():
                raise InfrastructureFailed(
                    "fixture br init did not create its isolated database"
                )

        stable_id, regression_id, seeds_initialized = (
            _fixture_br_ensure_canonical_seeds()
        )
        fixture_initialized = fixture_initialized or seeds_initialized

        # Initialization may create the database or canonical rows and must
        # publish them once. Existing fixtures are never silently repaired or
        # flushed here: every case must enter with the state left by the prior
        # transaction so restoration residue remains observable.
        if fixture_initialized:
            fixture_br_json("sync", "--flush-only")
        fixture_rows = fixture_br_list()
        canonical_ids = {stable_id, regression_id}
        legacy_ids: list[str] = []
        for row in fixture_rows:
            row_id = dict.get(row, "id")
            labels = dict.get(row, "labels") or []
            if row_id in canonical_ids:
                continue
            if (
                type(row_id) is not str
                or row.get("ephemeral") is not True
                or FIXTURE_BR_LABEL not in labels
                or not row_id.startswith(FIXTURE_BR_LEGACY_ID_PREFIX)
            ):
                raise InfrastructureFailed(
                    "no-mock fixture contains an unsupported unselected row"
                )
            legacy_ids.append(row_id)
            fixture_br_validate_canonical_seed(
                fixture_br_show(row_id),
                title=FIXTURE_BR_LEGACY_TITLE,
                description=FIXTURE_BR_LEGACY_DESCRIPTION,
                status="open",
                ephemeral=True,
            )
        if len(legacy_ids) > 1:
            raise InfrastructureFailed(
                "no-mock fixture contains duplicate legacy canonical rows"
            )
        fixture_rows_by_id = {row["id"]: row for row in fixture_rows}
        for row_id, row in fixture_rows_by_id.items():
            show = fixture_br_show(row_id)
            if row["dependency_count"] != len(show.get("dependencies") or []):
                raise InfrastructureFailed(
                    f"fixture list dependency count differs for {row_id}"
                )
            if row["dependent_count"] != len(show.get("dependents") or []):
                raise InfrastructureFailed(
                    f"fixture list dependent count differs for {row_id}"
                )
            for field, value in dict.items(row):
                if field in {"dependency_count", "dependent_count"}:
                    continue
                if not dict.__contains__(show, field) or show[field] != value:
                    raise InfrastructureFailed(
                        f"fixture list/show field differs for {row_id}/{field}"
                    )
        expected_exported_ids = sorted(
            row["id"]
            for row in fixture_rows
            if row.get("ephemeral") is not True
            and "-wisp-" not in row["id"]
        )
        exported_rows = fixture_br_export_list()
        exported_ids = sorted(row["id"] for row in exported_rows)
        exported_rows_by_id = {row["id"]: row for row in exported_rows}
        expected_exported_rows = {
            row_id: fixture_rows_by_id[row_id]
            for row_id in expected_exported_ids
        }
        post_flush_status = v2_normalize_br_sync_status(
            fixture_br_json("sync", "--status"),
            input_kind="released_live",
            error_type=InfrastructureFailed,
        )
        post_flush_witness = fixture_br_json("sync", "--witness")
        normalized_witness = v2_normalize_br_export_witness(
            post_flush_witness,
            input_kind="released_live",
            workspace_root=fixture_root,
            expected_chunk_size_lines=(
                V2_BR_WITNESS_CAPTURE_CHUNK_SIZE_LINES
            ),
            expected_max_parallelism=(
                V2_BR_WITNESS_CAPTURE_MAX_PARALLELISM
            ),
            error_type=InfrastructureFailed,
        )
        witness_body = normalized_witness["witness"]
        if (
            post_flush_status.get("jsonl_exists") is not True
            or exported_ids != expected_exported_ids
            or exported_rows_by_id != expected_exported_rows
            or witness_body["line_count"] != len(expected_exported_ids)
        ):
            raise InfrastructureFailed(
                "no-mock fixture database, export, and witness disagree"
            )

        return {
            "db": str(FIXTURE_BR_DB_REL),
            "stable_id": stable_id,
            "regression_id": regression_id,
        }
    except InfrastructureFailed as error:
        if isinstance(error.__cause__, FileNotFoundError):
            raise NoData(
                "no-mock br fixture unavailable because released br is absent; "
                f"persistent safe target is {FIXTURE_BR_ROOT_REL}: {error}"
            ) from error
        raise


def fixture_br_description_round_trip(
    case_id: str,
    *,
    assert_stale_guard: bool = False,
    inject_failure: bool = False,
) -> dict[str, Any]:
    with fixture_br_lease():
        return _fixture_br_description_round_trip_locked(
            case_id,
            assert_stale_guard=assert_stale_guard,
            inject_failure=inject_failure,
        )


def _fixture_br_description_round_trip_locked(
    case_id: str,
    *,
    assert_stale_guard: bool = False,
    inject_failure: bool = False,
) -> dict[str, Any]:
    context = fixture_br_context()
    issue_id = context["stable_id"]
    fixture_br_set_status(issue_id, "open")
    before_issue = fixture_br_show(issue_id)
    before = fixture_br_semantic_projection(before_issue)
    old_description = before["description"]
    planned_root = text_root(old_description)
    new_description = (
        old_description.rstrip()
        + f"\n\n## Acceptance Criteria\n\nNo-mock fixture case `{case_id}`.\n"
    )
    observed_failure = False
    try:
        fixture_br_set_description(issue_id, new_description)
        changed = fixture_br_show(issue_id)
        fixture_true(
            text_root(str(changed.get("description") or "")) != planned_root,
            f"{case_id}: br update did not change the field root",
        )
        if assert_stale_guard:
            expect_error(
                InputRefused,
                lambda: (
                    None
                    if text_root(str(changed.get("description") or ""))
                    == planned_root
                    else (_ for _ in ()).throw(
                        InputRefused("stale exact-root apply refused")
                    )
                ),
                contains="stale exact-root",
            )
            observed_failure = True
        if inject_failure:
            try:
                raise InfrastructureFailed("seeded post-update fixture fault")
            except InfrastructureFailed:
                observed_failure = True
    finally:
        current = fixture_br_show(issue_id)
        if str(current.get("description") or "") != old_description:
            fixture_br_set_description(issue_id, old_description)
    restored = fixture_br_semantic_projection(fixture_br_show(issue_id))
    fixture_equal(restored, before, f"{case_id}: semantic restoration")
    if assert_stale_guard or inject_failure:
        fixture_true(observed_failure, f"{case_id}: fault/refusal was not observed")
    return {
        "checks": 5 if assert_stale_guard or inject_failure else 4,
        "fixture_db": context["db"],
        "semantic_restoration": "exact-excluding-append-only-audit-history",
    }


def fixture_br_regression_round_trip() -> dict[str, Any]:
    with fixture_br_lease():
        return _fixture_br_regression_round_trip_locked()


def _fixture_br_regression_round_trip_locked() -> dict[str, Any]:
    context = fixture_br_context()
    issue_id = context["regression_id"]
    fixture_br_set_status(issue_id, "closed")
    before = fixture_br_restorable_projection(fixture_br_show(issue_id))
    before_audit = v2_normalize_audit_document(
        fixture_br_json("audit", "log", issue_id),
        issue_id=issue_id,
    )
    fixture_equal(before["status"], "closed", "regression fixture baseline status")
    targeted_lint = v2_normalize_br_lint_document(
        fixture_br_json("lint", issue_id),
        scope=issue_id,
        error_type=InfrastructureFailed,
    )
    targeted_ids = {row["id"] for row in targeted_lint["results"]}
    fixture_true(
        issue_id in targeted_ids,
        "closed regression did not retain its targeted lint finding",
    )
    open_lint = v2_normalize_br_lint_document(
        fixture_br_json("lint"),
        scope="open",
        error_type=InfrastructureFailed,
    )
    open_ids = {row["id"] for row in open_lint["results"]}
    fixture_true(
        context["stable_id"] in open_ids,
        "actionable fixture did not remain in open lint membership",
    )
    restored = fixture_br_restorable_projection(fixture_br_show(issue_id))
    restored_audit = v2_normalize_audit_document(
        fixture_br_json("audit", "log", issue_id),
        issue_id=issue_id,
    )
    fixture_equal(
        restored,
        before,
        "read-only regression lint changed the issue projection",
    )
    fixture_equal(
        restored_audit,
        before_audit,
        "read-only regression lint changed audit history",
    )
    return {
        "checks": 4,
        "fixture_db": context["db"],
        "semantic_restoration": "read-only exact issue and audit preservation",
    }


def self_test_case(
    case_id: str,
    *,
    live_snapshot: LiveSnapshot | None,
) -> dict[str, Any]:
    strong_acceptance = (
        "## Detailed completion contract\n\n"
        "1. Run `scripts/ci/beads_template_hygiene.sh --self-test` and require "
        "deterministic unit, boundary, mutation, cancellation, and replay checks.\n"
        "2. Refuse malformed input, stale source identity, copied criteria, and "
        "unreviewed semantic changes with an exact typed terminal.\n"
        "3. Retain bounded redacted JSONL logs, a disjoint artifact replay, and "
        "the first divergent issue or field root.\n"
        "4. Close only after source closure and independent verification; this "
        "fixture mints no product, scientific, release, or owner authority."
    )

    if case_id == "template-lint.inventory-empty":
        inventory = fixture_inventory([], {})
        fixture_equal(inventory["counts"]["issues"], 0, "empty issue count")
        fixture_equal(inventory["counts"]["warnings"], 0, "empty warning count")
        fixture_equal(
            set(inventory["status_cuts"]),
            set(LINT_SCOPES),
            "empty status-cut coverage",
        )

        one = fixture_issue(issue_id="fixture-one", priority=4)
        one_inventory = fixture_inventory(
            [one],
            {"fixture-one": ("## Acceptance Criteria",)},
        )
        fixture_equal(one_inventory["counts"]["issues"], 1, "one-row boundary")
        fixture_equal(one_inventory["counts"]["warnings"], 1, "one-warning boundary")

        maximum = [
            fixture_issue(issue_id=f"fixture-max-{index:04d}")
            for index in range(CAPS["issues"])
        ]
        maximum_missing = {
            issue["id"]: ("## Acceptance Criteria",) for issue in maximum
        }
        maximum_lint = fixture_lint(maximum, maximum_missing)
        fixture_equal(
            maximum_lint["all"]["issues"],
            CAPS["issues"],
            "maximum issue cap",
        )
        expect_error(
            EvidenceFailed,
            lambda: fixture_lint(
                maximum
                + [fixture_issue(issue_id="fixture-over-issue-cap")],
                {
                    **maximum_missing,
                    "fixture-over-issue-cap": ("## Acceptance Criteria",),
                },
            ),
            contains="issue count",
        )

        sixteen_sections = tuple(
            f"## Synthetic fixture section {index:02d}"
            for index in range(FIXTURE_MAX_WARNINGS_PER_ISSUE)
        )
        warning_max_issues = [
            fixture_issue(issue_id=f"fixture-warning-{index:04d}")
            for index in range(CAPS["warnings"] // len(sixteen_sections))
        ]
        warning_max_missing = {
            issue["id"]: sixteen_sections for issue in warning_max_issues
        }
        warning_max_lint = fixture_lint(
            warning_max_issues,
            warning_max_missing,
        )
        fixture_equal(
            {
                "total": warning_max_lint["all"]["total"],
                "hints": sorted(
                    {
                        suggestion["hint"]
                        for row in warning_max_lint["all"]["results"]
                        for suggestion in row["suggestions"]
                    }
                ),
            },
            {
                "total": CAPS["warnings"],
                "hints": ["Synthetic fixture-only missing-section hint"],
            },
            "maximum warning cap and synthetic-only fallback hint",
        )
        over_warning_issue = fixture_issue(issue_id="fixture-warning-over")
        expect_error(
            EvidenceFailed,
            lambda: fixture_lint(
                warning_max_issues + [over_warning_issue],
                {
                    **warning_max_missing,
                    over_warning_issue["id"]: ("## Acceptance Criteria",),
                },
            ),
            contains="warning count",
        )
        expect_error(
            EvidenceFailed,
            lambda: fixture_lint(
                [fixture_issue(issue_id="fixture-bad-status", status="unknown")],
                {"fixture-bad-status": ("## Acceptance Criteria",)},
            ),
            contains="unknown status",
        )
        expect_error(
            EvidenceFailed,
            lambda: fixture_lint(
                [fixture_issue(issue_id="fixture-bad-priority", priority=5)],
                {"fixture-bad-priority": ("## Acceptance Criteria",)},
            ),
            contains="outside P0-P4",
        )
        expect_error(
            EvidenceFailed,
            lambda: fixture_lint(
                [
                    fixture_issue(issue_id="fixture-duplicate"),
                    fixture_issue(issue_id="fixture-duplicate"),
                ],
                {"fixture-duplicate": ("## Acceptance Criteria",)},
            ),
            contains="duplicate issue IDs",
        )
        return {
            "category": "schema-boundary-and-caps",
            "checks": 12,
            "max_issues": CAPS["issues"],
            "max_warnings": CAPS["warnings"],
        }

    if case_id == "template-lint.inventory-live":
        fixture_true(live_snapshot is not None, "live inventory did not execute")
        assert live_snapshot is not None
        fixture_equal(
            live_snapshot.inventory["schema"],
            INVENTORY_SCHEMA,
            "live inventory schema",
        )
        fixture_equal(
            set(live_snapshot.inventory["status_cuts"]),
            set(LINT_SCOPES),
            "live status-cut coverage",
        )
        fixture_equal(
            live_snapshot.inventory["counts"]["warnings"],
            len(live_snapshot.inventory["warning_rows"]),
            "live warning arithmetic",
        )

        required_types = ("bug", "task", "feature", "epic")
        universe: list[dict[str, Any]] = []
        missing: dict[str, tuple[str, ...]] = {}
        for status_index, status in enumerate(STATUS_SCOPES):
            for type_index, issue_type in enumerate(required_types):
                issue_id = f"fixture-{status}-{issue_type}"
                issue = fixture_issue(
                    issue_id=issue_id,
                    title=(
                        "Δeterministic Unicode fixture 🧪"
                        if not universe
                        else f"{status} {issue_type} fixture"
                    ),
                    issue_type=issue_type,
                    status=status,
                    priority=(status_index * len(required_types) + type_index) % 5,
                    description="Unicode units: μm, °C, and λ remain canonical.",
                )
                universe.append(issue)
                missing[issue_id] = fixture_expected_missing(issue_type)
        for issue_type in ("chore", "docs", "question", "custom"):
            issue_id = f"fixture-open-{issue_type}"
            universe.append(
                fixture_issue(
                    issue_id=issue_id,
                    issue_type=issue_type,
                    status="open",
                    priority=4,
                )
            )
            missing[issue_id] = fixture_expected_missing(issue_type)

        for issue_type, expected in FIXTURE_REQUIRED_SECTIONS_BY_TYPE.items():
            fixture_equal(
                tuple(sorted(REQUIRED_SECTIONS_BY_TYPE.get(issue_type, ()))),
                tuple(sorted(expected)),
                f"rule matrix for {issue_type}",
            )

        lint = fixture_lint(universe, missing)
        inventory = fixture_inventory(universe, missing)
        warned_ids = {row["id"] for row in inventory["rows"]}
        for issue_type in ("chore", "docs", "question", "custom"):
            fixture_true(
                f"fixture-open-{issue_type}" not in warned_ids,
                f"{issue_type} incorrectly acquired a default lint requirement",
            )
        fixture_equal(
            set(inventory["counts"]["by_status"]),
            set(STATUS_SCOPES),
            "all statuses represented",
        )
        fixture_equal(
            set(inventory["counts"]["by_priority"]),
            {f"P{priority}" for priority in range(5)},
            "all priorities represented",
        )
        fixture_equal(
            set(inventory["counts"]["by_type"]),
            set(required_types),
            "all required-section types represented",
        )
        fixture_true(
            "Δeterministic Unicode fixture 🧪"
            in {row["title"] for row in inventory["rows"]},
            "Unicode title did not survive inventory projection",
        )
        reversed_inventory = fixture_inventory(
            list(reversed(universe)),
            dict(reversed(list(missing.items()))),
        )
        fixture_equal(
            reversed_inventory["semantic_root"],
            inventory["semantic_root"],
            "input-order invariant inventory",
        )
        fixture_equal(
            lint["all"]["total"],
            sum(lint[scope]["total"] for scope in STATUS_SCOPES),
            "all-status warning union",
        )
        return {
            "category": "live-and-universe-projection",
            "checks": 18,
            "statuses": list(STATUS_SCOPES),
            "priorities": [0, 1, 2, 3, 4],
            "types": list(FIXTURE_REQUIRED_SECTIONS_BY_TYPE),
            "live_warnings": live_snapshot.inventory["counts"]["warnings"],
        }

    if case_id == "template-lint.overlap-partitions":
        sections = (
            "## Acceptance Criteria",
            "## Steps to Reproduce",
            "## Success Criteria",
        )
        combinations = (
            (sections[0],),
            (sections[1],),
            (sections[2],),
            (sections[0], sections[1]),
            (sections[0], sections[2]),
            (sections[1], sections[2]),
            sections,
        )
        issues = [
            fixture_issue(
                issue_id=f"fixture-overlap-{index}",
                issue_type="bug",
                status=STATUS_SCOPES[index % len(STATUS_SCOPES)],
            )
            for index in range(len(combinations))
        ]
        missing = {
            issue["id"]: combination
            for issue, combination in zip(issues, combinations, strict=True)
        }
        inventory = fixture_inventory(issues, missing)
        fixture_equal(inventory["counts"]["issues"], 7, "seven overlap issues")
        fixture_equal(inventory["counts"]["warnings"], 12, "overlap warning sum")
        expected_partitions = {
            "+".join(sorted(combination)): 1 for combination in combinations
        }
        fixture_equal(
            inventory["counts"]["overlap_partitions"],
            dict(sorted(expected_partitions.items())),
            "seven exclusive overlap partitions",
        )
        reversed_inventory = fixture_inventory(
            list(reversed(issues)),
            dict(reversed(list(missing.items()))),
        )
        fixture_equal(
            reversed_inventory["semantic_root"],
            inventory["semantic_root"],
            "overlap input-order invariance",
        )

        duplicate_lint = json.loads(json.dumps(fixture_lint(issues, missing)))
        duplicate = dict(duplicate_lint["all"]["results"][0])
        duplicate_lint["all"]["results"].append(duplicate)
        duplicate_lint["all"]["issues"] += 1
        duplicate_lint["all"]["total"] += duplicate["warnings"]
        expect_error(
            EvidenceFailed,
            lambda: assemble_inventory(
                duplicate_lint,
                issues,
                fixture_source(issues),
            ),
            contains="duplicate issue",
        )

        union_gap_lint = json.loads(json.dumps(fixture_lint(issues, missing)))
        gap_issue = issues[0]
        gap_scope = str(gap_issue["status"])
        gap_rows = union_gap_lint[gap_scope]["results"]
        removed = gap_rows.pop(0)
        union_gap_lint[gap_scope]["issues"] -= 1
        union_gap_lint[gap_scope]["total"] -= removed["warnings"]
        expect_error(
            EvidenceFailed,
            lambda: assemble_inventory(
                union_gap_lint,
                issues,
                fixture_source(issues),
            ),
            contains="exact union",
        )
        return {
            "category": "exact-partition-metamorphic",
            "checks": 7,
            "exclusive_partitions": 7,
            "warnings": 12,
        }

    if case_id == "template-lint.section-only":
        issue = fixture_issue(acceptance=strong_acceptance)
        reviewed = classify_issue(
            issue,
            ("## Acceptance Criteria",),
            section_only_reviewed=True,
        )[0]
        fixture_equal(reviewed, "SECTION_NAME_ONLY", "reviewed section-only")
        unreviewed = classify_issue(
            issue,
            ("## Acceptance Criteria",),
        )[0]
        fixture_equal(
            unreviewed,
            "OWNER_REVIEW_REQUIRED",
            "unreviewed polished criteria",
        )
        duplicate = classify_issue(
            issue,
            ("## Acceptance Criteria",),
            duplicate_acceptance=True,
            section_only_reviewed=True,
        )[0]
        fixture_equal(
            duplicate,
            "OWNER_REVIEW_REQUIRED",
            "duplicate generic criteria",
        )
        reproduction_issue = fixture_issue(
            issue_id="fixture-reviewed-repro",
            issue_type="bug",
            description=(
                "REPRO: run `scripts/ci/beads_template_hygiene.sh --self-test`. "
                "Expected Pass; observed failure before the heading repair."
            ),
        )
        reproduction = classify_issue(
            reproduction_issue,
            ("## Steps to Reproduce",),
            section_only_reviewed=True,
        )[0]
        fixture_equal(
            reproduction,
            "SECTION_NAME_ONLY",
            "reviewed reproduction heading-only repair",
        )

        old_description = str(issue["description"])
        proposal = proposal_for_row(
            {
                "id": issue["id"],
                "disposition": "SECTION_NAME_ONLY",
                "missing_sections": ["## Acceptance Criteria"],
                "rationale": "reviewed fixture",
            },
            issue,
        )
        fixture_true(proposal is not None, "section-only proposal was not built")
        assert proposal is not None
        fixture_true(
            old_description in proposal["new_value"],
            "section-only proposal lost existing description",
        )
        fixture_true(
            "## Acceptance Criteria" in proposal["new_value"],
            "section-only proposal lacks literal heading",
        )
        fixture_equal(
            proposal["inverse_value"],
            old_description,
            "section-only exact inverse",
        )
        return {
            "category": "review-bound-section-only",
            "checks": 8,
            "review_required": True,
        }

    if case_id == "template-lint.substantive-omission":
        empty = classify_issue(
            fixture_issue(acceptance=""),
