    or len(V2_REVIEW_RECEIPT_PROVENANCE_FIELDS)
    != len(set(V2_REVIEW_RECEIPT_PROVENANCE_FIELDS))
    or bool(
        set(V2_REVIEW_RECEIPT_SCOPE_FIELDS)
        & set(V2_REVIEW_RECEIPT_PROVENANCE_FIELDS)
    )
    or (
        set(V2_REVIEW_RECEIPT_SCOPE_FIELDS)
        | set(V2_REVIEW_RECEIPT_PROVENANCE_FIELDS)
    )
    != V2_REVIEW_RECEIPT_FIELDS
):
    raise RuntimeError(
        "review receipt scope/provenance fields do not exactly partition "
        "the closed receipt schema"
    )


def v2_review_receipt_scope_root(receipt: Mapping[str, Any]) -> str:
    receipt = v2_released_json_snapshot(
        receipt,
        label="review receipt scope row",
        error_type=InputRefused,
    )
    if type(receipt) is not dict:
        raise InputRefused("review receipt scope row is not an exact object")
    receipt_fields = frozenset(dict.__iter__(receipt))
    if receipt_fields != {*V2_REVIEW_RECEIPT_FIELDS, "semantic_root"}:
        raise InputRefused(
            "review receipt scope root requires the exact closed row schema"
        )
    verify_semantic_root(receipt, label="review receipt scope row")
    return semantic_root(
        {
            "schema": V2_REVIEW_RECEIPT_SCOPE_SCHEMA,
            "receipt": {
                field: dict.__getitem__(receipt, field)
                for field in V2_REVIEW_RECEIPT_SCOPE_FIELDS
            },
        }
    )


def v2_reviewed_no_change_receipt_root(
    disposition: str,
    *,
    semantic_complete: bool,
    receipt: dict[str, Any] | None,
) -> str | None:
    """Select the no-change proof root from an already bound review epoch."""
    if (
        type(disposition) is not str
        or disposition not in V2_SEMANTIC_REVIEW_DISPOSITIONS
        or type(semantic_complete) is not bool
    ):
        raise EvidenceFailed(
            "reviewed-no-change selector inputs are malformed"
        )
    if semantic_complete:
        if type(receipt) is not dict:
            raise EvidenceFailed(
                "completed semantic review lacks an exact receipt"
            )
        semantic_receipt_root = v2_review_receipt_scope_root(receipt)
    elif receipt is not None and type(receipt) is not dict:
        raise EvidenceFailed(
            "incomplete semantic review receipt is malformed"
        )
    if disposition == "REVIEWED_NO_CHANGE" and semantic_complete:
        return semantic_receipt_root
    return None


def _v2_validate_review_receipt_document_provenance_exact(
    receipt_document: dict[str, Any],
    *,
    inventory: dict[str, Any] | None,
    label: str,
) -> None:
    if (
        type(receipt_document) is not dict
        or (inventory is not None and type(inventory) is not dict)
        or type(label) is not str
        or not label
    ):
        raise InputRefused("review receipt provenance inputs are not exact")
    receipts = dict.get(receipt_document, "receipts")
    if type(receipts) is not list:
        raise InputRefused(f"{label} receipts are not an exact array")
    for field in V2_REVIEW_RECEIPT_PROVENANCE_FIELDS:
        value = dict.get(receipt_document, field)
        if (
            type(value) is not str
            or re.fullmatch(r"sha256-v1:[0-9a-f]{64}", value) is None
        ):
            raise InputRefused(f"{label} {field} is malformed")
    if inventory is not None and not receipts and (
        receipt_document["inventory_root"]
        != dict.get(inventory, "semantic_root")
        or receipt_document["campaign_epoch_root"]
        != dict.get(inventory, "campaign_epoch_root")
    ):
        raise InputRefused(
            f"{label} envelope does not bind the current campaign"
        )


def v2_validate_review_receipt_document_provenance(
    receipt_document: Mapping[str, Any],
    receipts: Sequence[Any],
    *,
    inventory: Mapping[str, Any] | None,
    label: str,
) -> None:
    if type(label) is not str or not label:
        raise InputRefused("review receipt provenance label is malformed")
    detached = v2_released_json_snapshot(
        {
            "receipt_document": receipt_document,
            "receipts": receipts,
            "inventory": inventory,
        },
        label="review receipt provenance inputs",
        error_type=InputRefused,
    )
    if type(detached) is not dict:
        raise InputRefused("review receipt provenance snapshot is malformed")
    receipt_document = dict.__getitem__(detached, "receipt_document")
    receipts = dict.__getitem__(detached, "receipts")
    inventory = dict.__getitem__(detached, "inventory")
    if (
        type(receipt_document) is not dict
        or type(receipts) is not list
        or (inventory is not None and type(inventory) is not dict)
    ):
        raise InputRefused("review receipt provenance inputs are not exact")
    document_receipts = dict.get(receipt_document, "receipts")
    if type(document_receipts) is not list or receipts != document_receipts:
        raise InputRefused(
            f"{label} receipt rows differ from their provenance envelope"
        )
    _v2_validate_review_receipt_document_provenance_exact(
        receipt_document,
        inventory=inventory,
        label=label,
    )


def _v2_validate_review_receipt_row_provenance_exact(
    receipt: dict[str, Any],
    receipt_document: dict[str, Any],
    *,
    label: str,
) -> None:
    if (
        type(receipt) is not dict
        or type(receipt_document) is not dict
        or type(label) is not str
        or not label
    ):
        raise InputRefused("review receipt row provenance inputs are not exact")
    for field in V2_REVIEW_RECEIPT_PROVENANCE_FIELDS:
        value = dict.get(receipt, field)
        envelope_value = dict.get(receipt_document, field)
        if (
            type(value) is not str
            or re.fullmatch(r"sha256-v1:[0-9a-f]{64}", value) is None
            or type(envelope_value) is not str
            or re.fullmatch(
                r"sha256-v1:[0-9a-f]{64}",
                envelope_value,
            )
            is None
            or value != envelope_value
        ):
            raise InputRefused(
                f"{label} {field} differs from its provenance envelope"
            )


def v2_validate_review_receipt_row_provenance(
    receipt: Mapping[str, Any],
    receipt_document: Mapping[str, Any],
    *,
    label: str,
) -> None:
    if type(label) is not str or not label:
        raise InputRefused("review receipt provenance label is malformed")
    detached = v2_released_json_snapshot(
        {
            "receipt": receipt,
            "receipt_document": receipt_document,
        },
        label="review receipt row provenance inputs",
        error_type=InputRefused,
    )
    if type(detached) is not dict:
        raise InputRefused(
            "review receipt row provenance snapshot is malformed"
        )
    exact_receipt = dict.__getitem__(detached, "receipt")
    exact_document = dict.__getitem__(detached, "receipt_document")
    if type(exact_receipt) is not dict or type(exact_document) is not dict:
        raise InputRefused("review receipt row provenance inputs are not exact")
    _v2_validate_review_receipt_row_provenance_exact(
        exact_receipt,
        exact_document,
        label=label,
    )

V2_AUTHORITY_IDENTITY_FIELDS = (
    "reviewer",
    "reviewer_kind",
    "coordination_assignee",
    "declared_domain_owner",
    "declared_acceptance_owner",
    "implementation_owner",
    "evidence_owner",
    "terminal_consumer",
    "manual_authorization_source",
    "external_authority_adapter",
    "conditional_capability_identity",
)
V2_RESERVED_AUTHORITY_IDENTITY_PRESENCE_KEYS = frozenset(
    {
        "nodata",
        "unresolved",
        "unknown",
        "none",
        "notprovided",
        "unassigned",
        "unset",
        "missing",
        "na",
        "notapplicable",
        "notset",
        "null",
        "nil",
        "tbd",
        "tba",
        "noowner",
        "noreviewer",
    }
)


def v2_validate_authority_identity_text(
    value: Any,
    *,
    target_id: str,
    field_name: str,
    allow_empty: bool,
    allow_unresolved: bool,
    error_type: type[HarnessError],
) -> str:
    v2_require_allowed_terminal_error_type(
        error_type,
        label="authority identity error type",
    )
    if (
        type(target_id) is not str
        or not target_id
        or type(field_name) is not str
        or not field_name
        or type(allow_empty) is not bool
        or type(allow_unresolved) is not bool
    ):
        raise EvidenceFailed("authority identity validator inputs are malformed")
    if (
        type(value) is not str
        or value != str.strip(value)
        or value != unicodedata.normalize("NFC", value)
        or any(
            unicodedata.category(character).startswith("C")
            or unicodedata.category(character) in {"Zl", "Zp"}
            for character in value
        )
    ):
        raise error_type(
            "review receipt authority identity is noncanonical for "
            f"{target_id}: {field_name}"
        )
    try:
        value_bytes = str.encode(value, "utf-8")
    except UnicodeEncodeError as error:
        raise error_type(
            "review receipt authority identity is noncanonical for "
            f"{target_id}: {field_name}"
        ) from error
    if len(value_bytes) > V2_AUTHORITY_IDENTITY_BYTES_CAP:
        raise error_type(
            "review receipt authority identity is noncanonical for "
            f"{target_id}: {field_name}"
        )
    if not value:
        if allow_empty:
            return value
        raise error_type(
            "review receipt authority identity is empty for "
            f"{target_id}: {field_name}"
        )
    compatibility_normalized = v2_exact_normalized_casefold(
        value,
        normalization="NFKC",
        label=(
            "review receipt authority identity "
            f"{target_id}: {field_name}"
        ),
        error_type=error_type,
    )
    normalized_presence = "".join(
        character
        for character in compatibility_normalized
        if character.isalnum()
    )
    if not normalized_presence:
        raise error_type(
            "review receipt authority identity contains no alphanumeric "
            f"identity for {target_id}: {field_name}"
        )
    if (
        normalized_presence
        in V2_RESERVED_AUTHORITY_IDENTITY_PRESENCE_KEYS
        and not (allow_unresolved and value == "UNRESOLVED")
    ):
        raise error_type(
            "review receipt authority identity uses a reserved no-data "
            f"sentinel for {target_id}: {field_name}"
        )
    return value


def v2_validate_receipt_authority_identities(
    receipt: Mapping[str, Any],
    *,
    target_id: str,
) -> None:
    target_id = v2_validate_issue_id(
        target_id,
        label="review receipt authority target ID",
        error_type=InputRefused,
    )
    receipt = v2_released_json_snapshot(
        receipt,
        label="review receipt authority row",
        error_type=InputRefused,
    )
    if (
        type(receipt) is not dict
    ):
        raise InputRefused("review receipt authority row is not an exact object")
    for field_name in V2_AUTHORITY_IDENTITY_FIELDS:
        v2_validate_authority_identity_text(
            dict.get(receipt, field_name),
            target_id=target_id,
            field_name=field_name,
            allow_empty=True,
            allow_unresolved=False,
            error_type=InputRefused,
        )
    reviewer_present = bool(receipt["reviewer"])
    reviewer_kind_present = bool(receipt["reviewer_kind"])
    if reviewer_present != reviewer_kind_present:
        raise InputRefused(
            f"review receipt reviewer identity is incomplete for {target_id}"
        )
    manual_authorization = dict.get(receipt, "manual_authorization")
    manual_source = receipt["manual_authorization_source"]
    if type(manual_authorization) is not bool:
        raise InputRefused(
            f"review receipt manual authorization is not boolean for {target_id}"
        )
    if manual_authorization:
        if (
            not manual_source
            or not reviewer_present
            or not receipt["declared_acceptance_owner"]
        ):
            raise InputRefused(
                "review receipt manual authorization lacks its canonical "
                f"reviewer, acceptance owner, or source for {target_id}"
            )
    elif manual_source:
        raise InputRefused(
            "review receipt has a manual-authorization source while manual "
            f"authorization is false for {target_id}"
        )
    for verdict_field, required_fields in (
        (
            "external_authority_verdict",
            (
                "external_authority_adapter",
                "external_authority_receipt_root",
            ),
        ),
        (
            "conditional_capability_verdict",
            (
                "conditional_capability_identity",
                "conditional_capability_receipt_root",
            ),
        ),
        (
            "gate_admission_verdict",
            ("gate_admission_receipt_root",),
        ),
    ):
        verdict = dict.get(receipt, verdict_field)
        required_values = tuple(
            dict.get(receipt, field_name) for field_name in required_fields
        )
        if type(verdict) is not str or any(
            type(value) is not str for value in required_values
        ):
            raise InputRefused(
                "review receipt gate evidence is not exact for "
                f"{target_id}: {verdict_field}"
            )
        if verdict == "VALID" and any(not value for value in required_values):
            raise InputRefused(
                "review receipt VALID gate lacks complete structural evidence "
                f"for {target_id}: {verdict_field}"
            )
        if verdict == "NODATA" and any(required_values):
            raise InputRefused(
                "review receipt NODATA gate retains contradictory evidence "
                f"for {target_id}: {verdict_field}"
            )


def v2_validate_source_closure_transition(
    *,
    target: Mapping[str, Any],
    receipt: Mapping[str, Any],
    semantic_complete: bool,
) -> None:
    if type(semantic_complete) is not bool:
        raise InputRefused("source-closure completion selector is not exact")
    detached = v2_validate_exact_json_wire(
        {"target": target, "receipt": receipt},
        label="source-closure transition inputs",
    )
    if type(detached) is not dict:
        raise InputRefused("source-closure transition snapshot is malformed")
    target = dict.__getitem__(detached, "target")
    receipt = dict.__getitem__(detached, "receipt")
    if type(target) is not dict or type(receipt) is not dict:
        raise InputRefused("source-closure transition inputs are not objects")
    target_id = dict.get(target, "id")
    if type(target_id) is not str or not target_id:
        raise InputRefused("source-closure target identity is malformed")
    v2_validate_issue_id(
        target_id,
        label="source-closure target ID",
        error_type=InputRefused,
    )
    target_closure = dict.get(target, "source_closure")
    receipt_closure = dict.get(receipt, "source_closure")
    for label, closure in (
        ("target", target_closure),
        ("receipt", receipt_closure),
    ):
        if type(closure) is not dict:
            raise InputRefused(
                f"review receipt {label} source closure is not an object "
                f"for {target_id}"
            )
        v2_exact_keys(
            closure,
            {"required", "state"},
            label=f"review receipt {label} source closure for {target_id}",
        )
        if (
            type(closure["required"]) is not bool
            or type(closure["state"]) is not str
            or closure["state"] not in V2_SOURCE_CLOSURE_STATES
        ):
            raise InputRefused(
                f"review receipt {label} source closure is outside its "
                f"closed state set for {target_id}"
            )
    if receipt_closure["required"] != target_closure["required"]:
        raise InputRefused(
            f"review receipt changes the source-closure obligation for {target_id}"
        )
    if not target_closure["required"]:
        if target_closure["state"] != "NOT_REQUIRED_BY_V1_CLASSIFICATION":
            raise InputRefused(
                "target has a noncanonical not-required source "
                f"closure for {target_id}"
            )
        if receipt_closure != target_closure:
            raise InputRefused(
                "review receipt changes a not-required source closure for "
                f"{target_id}"
            )
        return
    if target_closure["state"] != "REVIEW_REQUIRED":
        raise InputRefused(
            f"required target source closure has an invalid base state for {target_id}"
        )
    expected_state = "REVIEW_REQUIRED"
    if semantic_complete:
        dimension_rows = dict.get(receipt, "semantic_review_dimensions")
        if type(dimension_rows) is not list:
            raise InputRefused(
                f"review receipt semantic dimensions are malformed for {target_id}"
            )
        dimensions: dict[str, str] = {}
        for index, row in enumerate(dimension_rows):
            if type(row) is not dict:
                raise InputRefused(
                    "review receipt semantic dimension row is malformed for "
                    f"{target_id}/{index}"
                )
            dimension = dict.get(row, "dimension")
            verdict = dict.get(row, "verdict")
            if (
                type(dimension) is not str
                or not dimension
                or type(verdict) is not str
                or not verdict
                or dimension in dimensions
            ):
                raise InputRefused(
                    "review receipt semantic dimension identity is malformed "
                    f"for {target_id}/{index}"
                )
            dimensions[dimension] = verdict
        if "source_and_terminal_closure" not in dimensions:
            raise InputRefused(
                f"review receipt lacks source-closure dimension for {target_id}"
            )
        closure_verdict = dimensions["source_and_terminal_closure"]
        if closure_verdict == "SATISFIED":
            expected_state = "ROOT_BOUND_REVIEWED_COMPLETE"
        elif closure_verdict == "NOT_APPLICABLE":
            expected_state = "ROOT_BOUND_NOT_APPLICABLE"
        else:
            expected_state = "ROOT_BOUND_REVIEW_BLOCKED"
    if receipt_closure["state"] != expected_state:
        raise InputRefused(
            "review receipt source-closure transition disagrees with its "
            f"root-bound semantic disposition for {target_id}"
        )


def v2_empty_review_receipts(
    *, inventory_root: str, campaign_epoch_root: str
) -> dict[str, Any]:
    if (
        not v2_is_semantic_root(inventory_root)
        or not v2_is_semantic_root(campaign_epoch_root)
    ):
        raise EvidenceFailed(
            "empty review receipt roots are not canonical"
        )
    return v2_rooted(
        {
            "schema": V2_REVIEW_RECEIPTS_SCHEMA,
            "inventory_root": inventory_root,
            "campaign_epoch_root": campaign_epoch_root,
            "receipts": [],
            "source": "NOT_PROVIDED",
            "no_claim": V2_REVIEW_RECEIPTS_NO_CLAIM,
        }
    )


def v2_load_review_receipts(
    relative: str | None,
    *,
    inventory: Mapping[str, Any],
) -> dict[str, Any]:
    if relative is None:
        return v2_empty_review_receipts(
            inventory_root=str(inventory["semantic_root"]),
            campaign_epoch_root=str(inventory["campaign_epoch_root"]),
        )
    relative_path = safe_relative(relative, label="review receipts")
    if relative_path.suffix != ".json":
        raise InputRefused("review receipts must be a closed JSON document")
    payload = v2_read_repo_relative_file_strict(
        relative,
        label="review receipts",
    )
    document = strict_json_loads(
        payload,
        label="review receipts",
        require_canonical=True,
    )
    if not isinstance(document, dict):
        raise InputRefused("review receipts must be an object")
    v2_exact_keys(
        document,
        {
            "schema",
            "inventory_root",
            "campaign_epoch_root",
            "receipts",
            "source",
            "no_claim",
        },
        label="review receipts",
    )
    if document["schema"] != V2_REVIEW_RECEIPTS_SCHEMA:
        raise InputRefused("unknown review-receipts schema")
    if (
        not isinstance(document["inventory_root"], str)
        or not isinstance(document["campaign_epoch_root"], str)
        or not isinstance(document["source"], str)
        or not document["source"].strip()
        or document["no_claim"] != V2_REVIEW_RECEIPTS_NO_CLAIM
    ):
        raise InputRefused("review receipts contain invalid document scalars")
    receipts = document["receipts"]
    if not isinstance(receipts, list):
        raise InputRefused("review receipts must contain an array")
    if len(receipts) > V2_INVENTORY_ROWS_CAP:
        raise InputRefused("review receipts exceed the inventory-row cap")
    v2_validate_review_receipt_document_provenance(
        document,
        receipts,
        inventory=inventory,
        label="review receipts",
    )
    inventory_by_id = {row["id"]: row for row in inventory["rows"]}
    normalized: list[dict[str, Any]] = []
    for index, receipt in enumerate(receipts):
        if not isinstance(receipt, dict):
            raise InputRefused(f"review receipt {index} is not an object")
        v2_exact_keys(
            receipt,
            V2_REVIEW_RECEIPT_FIELDS,
            label=f"review receipt {index}",
        )
        if not isinstance(receipt["target_id"], str) or not receipt["target_id"]:
            raise InputRefused(f"review receipt {index} has an invalid target ID")
        target_id = receipt["target_id"]
        if target_id not in inventory_by_id:
            raise InputRefused(f"review receipt targets unknown {target_id}")
        if receipt["target_root"] != inventory_by_id[target_id]["target_root"]:
            raise InputRefused(f"review receipt target root drifted for {target_id}")
        v2_validate_review_receipt_row_provenance(
            receipt,
            document,
            label=f"review receipt {target_id}",
        )
        review_minutes = receipt["review_minutes"]
        if type(review_minutes) is not int or review_minutes < 0:
            raise InputRefused(f"review receipt minutes are invalid for {target_id}")
        if receipt["external_authority_verdict"] not in {
            "NODATA",
            "VALID",
            "INVALID",
            "REVOKED",
            "EXPIRED",
            "CONFLICTED",
        }:
            raise InputRefused(
                f"review receipt external-authority verdict is unknown for {target_id}"
            )
        if receipt["conditional_capability_verdict"] not in {
            "NODATA",
            "VALID",
            "FAILED",
            "LYING",
            "NON_ATOMIC",
            "VERSION_MISMATCHED",
            "CONFLICTED",
        }:
            raise InputRefused(
                f"review receipt conditional-capability verdict is unknown for {target_id}"
            )
        if receipt["gate_admission_verdict"] not in {
            "NODATA",
            "VALID",
            "FAILED",
            "CONFLICTED",
        }:
            raise InputRefused(
                f"review receipt gate-admission verdict is unknown for {target_id}"
            )
        targets = v2_validate_compatibility_target_ids(
            receipt["compatibility_target_ids"],
            label=f"compatibility target IDs for {target_id}",
        )
        if targets and target_id not in targets:
            raise InputRefused(
                f"compatibility set does not include its target {target_id}"
            )
        if any(value not in inventory_by_id for value in targets):
            raise InputRefused(
                f"compatibility set includes an unknown target for {target_id}"
            )
        string_fields = V2_REVIEW_RECEIPT_FIELDS - {
            "compatibility_target_ids",
            "review_minutes",
            "manual_authorization",
            "source_closure",
            "semantic_review_dimensions",
        }
        if any(not isinstance(receipt[field], str) for field in string_fields):
            raise InputRefused(
                f"review receipt contains a non-string scalar for {target_id}"
            )
        if receipt["no_claim"] != V2_REVIEW_RECEIPT_ROW_NO_CLAIM:
            raise InputRefused(
                f"review receipt no-claim boundary differs for {target_id}"
            )
        if type(receipt["manual_authorization"]) is not bool:
            raise InputRefused(
                f"review receipt manual authorization is not boolean for {target_id}"
            )
        v2_validate_receipt_authority_identities(
            receipt,
            target_id=target_id,
        )
        if not isinstance(receipt["source_closure"], dict):
            raise InputRefused(
                f"review receipt source closure is not an object for {target_id}"
            )
        v2_exact_keys(
            receipt["source_closure"],
            {"required", "state"},
            label=f"review receipt source closure for {target_id}",
        )
        if (
            type(receipt["source_closure"]["required"]) is not bool
            or not isinstance(receipt["source_closure"]["state"], str)
            or not receipt["source_closure"]["state"]
        ):
            raise InputRefused(
                f"review receipt source closure scalars are invalid for {target_id}"
            )
        for root_field in (
            "compatibility_receipt_root",
            "external_authority_receipt_root",
            "conditional_capability_receipt_root",
            "gate_admission_receipt_root",
        ):
            root_value = str(receipt[root_field])
            if root_value and not re.fullmatch(
                r"sha256-v1:[0-9a-f]{64}",
                root_value,
            ):
                raise InputRefused(
                    f"review receipt {root_field} is malformed for {target_id}"
                )
        semantic_disposition = receipt["semantic_review_disposition"]
        if semantic_disposition not in V2_SEMANTIC_REVIEW_DISPOSITIONS:
            raise InputRefused(
                f"review receipt semantic disposition is unknown for {target_id}"
            )
        semantic_complete = v2_validate_semantic_dimension_receipts(
            receipt["semantic_review_dimensions"],
            target_root=str(receipt["target_root"]),
            disposition=semantic_disposition,
            allow_empty=True,
            label=f"review receipt semantic dimensions for {target_id}",
        )
        v2_validate_source_closure_transition(
            target=inventory_by_id[target_id],
            receipt=receipt,
            semantic_complete=semantic_complete,
        )
        if semantic_complete:
            if (
                not receipt["reviewer"].strip()
                or not receipt["reviewer_kind"].strip()
                or not receipt["semantic_review_rationale"].strip()
                or not receipt["semantic_review_falsifier"].strip()
            ):
                raise InputRefused(
                    f"review receipt semantic adjudication is incomplete for {target_id}"
                )
        elif (
            receipt["semantic_review_rationale"]
            or receipt["semantic_review_falsifier"]
            or semantic_disposition
            != inventory_by_id[target_id]["semantic_review_disposition"]
        ):
            raise InputRefused(
                f"review receipt claims semantic adjudication without dimensions for {target_id}"
            )
        normalized.append(v2_rooted(receipt))
    original_target_ids = [row["target_id"] for row in normalized]
    v2_assert_unique(
        original_target_ids,
        label="review receipt target IDs",
    )
    if original_target_ids != sorted(original_target_ids):
        raise InputRefused("review receipt rows are not in canonical target order")
    normalized.sort(key=lambda row: row["target_id"])
    result = dict(document)
    result["receipts"] = normalized
    result["source_identity"] = {
        "path": relative,
        "bytes": len(payload),
        "root": "sha256-v1:" + hashlib.sha256(payload).hexdigest(),
    }
    rooted = v2_rooted(result)
    v2_validate_receipt_bindings(rooted, inventory)
    return rooted


def _v2_validate_compatibility_receipts_exact(
    receipts: dict[str, Any],
    inventory: dict[str, Any],
) -> None:
    if type(receipts) is not dict or type(inventory) is not dict:
        raise InputRefused("compatibility receipt inputs are not objects")
    inventory_rows = dict.get(inventory, "rows")
    if (
        type(inventory_rows) is not list
        or list.__len__(inventory_rows) > V2_INVENTORY_ROWS_CAP
        or dict.__len__(receipts) > V2_INVENTORY_ROWS_CAP
    ):
        raise InputRefused("compatibility receipt inputs exceed their cap")
    inventory_by_id: dict[str, dict[str, Any]] = {}
    for index, row in enumerate(list.__iter__(inventory_rows)):
        if type(row) is not dict:
            raise InputRefused(
                f"compatibility inventory row {index} is not an object"
            )
        target_id = dict.get(row, "id")
        target_root = dict.get(row, "target_root")
        dependency_root = dict.get(row, "dependency_neighborhood_root")
        if (
            type(target_id) is not str
            or not target_id
            or target_id in inventory_by_id
            or not v2_is_semantic_root(target_root)
            or not v2_is_semantic_root(dependency_root)
        ):
            raise InputRefused(
                f"compatibility inventory row {index} is malformed"
            )
        v2_validate_issue_id(
            target_id,
            label=f"compatibility inventory row {index} ID",
            error_type=InputRefused,
        )
        inventory_by_id[target_id] = row
    for receipt_id in dict.__iter__(receipts):
        if type(receipt_id) is not str:
            raise InputRefused(
                "compatibility receipt map contains a non-string key"
            )
        receipt = dict.__getitem__(receipts, receipt_id)
        if type(receipt) is not dict:
            raise InputRefused(
                f"compatibility receipt {receipt_id} is not an object"
            )
        target_id = dict.get(receipt, "target_id")
        key = dict.get(receipt, "compatibility_key")
        root = dict.get(receipt, "compatibility_receipt_root")
        rationale = dict.get(receipt, "compatibility_rationale")
        falsifier = dict.get(receipt, "compatibility_falsifier")
        target_ids = dict.get(receipt, "compatibility_target_ids")
        coordination_assignee = dict.get(
            receipt,
            "coordination_assignee",
        )
        declared_domain_owner = dict.get(
            receipt,
            "declared_domain_owner",
        )
        user_effect_value = dict.get(receipt, "user_effect")
        reviewer = dict.get(receipt, "reviewer")
        reviewer_kind = dict.get(receipt, "reviewer_kind")
        if (
            type(target_id) is not str
            or target_id != receipt_id
            or target_id not in inventory_by_id
            or type(key) is not str
            or type(root) is not str
            or type(rationale) is not str
            or type(falsifier) is not str
            or type(coordination_assignee) is not str
            or type(declared_domain_owner) is not str
            or type(user_effect_value) is not str
            or type(reviewer) is not str
            or type(reviewer_kind) is not str
        ):
            raise InputRefused(
                f"compatibility receipt {receipt_id} has malformed scalars"
            )
        for field_name, value, byte_cap in (
            ("compatibility_key", key, V2_AUTHORITY_IDENTITY_BYTES_CAP),
            (
                "compatibility_rationale",
                rationale,
                CAPS["semantic_field_bytes"],
            ),
            (
                "compatibility_falsifier",
                falsifier,
                CAPS["semantic_field_bytes"],
            ),
        ):
            try:
                encoded_value = str.encode(value, "utf-8")
            except UnicodeEncodeError as error:
                raise InputRefused(
                    f"compatibility receipt {receipt_id} {field_name} "
                    "is not canonical UTF-8"
                ) from error
            if (
                value != str.strip(value)
                or value != unicodedata.normalize("NFC", value)
                or len(encoded_value) > byte_cap
                or any(
                    unicodedata.category(character).startswith("C")
                    or unicodedata.category(character) in {"Zl", "Zp"}
                    for character in value
                )
            ):
                raise InputRefused(
                    f"compatibility receipt {receipt_id} {field_name} "
                    "is noncanonical"
                )
        v2_validate_canonical_semantic_text(
            user_effect_value,
            label=f"compatibility receipt {receipt_id} user effect",
            allow_empty=False,
            error_type=InputRefused,
        )
        if root and not v2_is_semantic_root(root):
            raise InputRefused(
                f"compatibility receipt {receipt_id} root is malformed"
            )
        target_ids = v2_validate_compatibility_target_ids(
            target_ids,
            label=f"compatibility target IDs for {receipt_id}",
        )
        if key:
            if not reviewer or not reviewer_kind:
                raise InputRefused(
                    f"compatibility receipt {receipt_id} lacks reviewer provenance"
                )
            continue
        if target_ids or root or rationale or falsifier:
            raise InputRefused(
                f"target {target_id} has compatibility data without a key"
            )
    keyed_receipts = sorted(
        (
            dict.__getitem__(receipts, receipt_id)
            for receipt_id in dict.__iter__(receipts)
            if dict.get(
                dict.__getitem__(receipts, receipt_id),
                "compatibility_key",
            )
        ),
        key=lambda row: (
            dict.__getitem__(row, "compatibility_key"),
            dict.__getitem__(row, "target_id"),
        ),
    )
    group_start = 0
    while group_start < len(keyed_receipts):
        key = dict.__getitem__(
            list.__getitem__(keyed_receipts, group_start),
            "compatibility_key",
        )
        group_end = group_start + 1
        while (
            group_end < len(keyed_receipts)
            and dict.__getitem__(
                list.__getitem__(keyed_receipts, group_end),
                "compatibility_key",
            )
            == key
        ):
            group_end += 1
        group = keyed_receipts[group_start:group_end]
        expected_ids = sorted(
            dict.__getitem__(row, "target_id") for row in group
        )
        roots = {
            dict.__getitem__(row, "compatibility_receipt_root")
            for row in group
        }
        rationales = {
            dict.__getitem__(row, "compatibility_rationale")
            for row in group
        }
        falsifiers = {
            dict.__getitem__(row, "compatibility_falsifier")
            for row in group
        }
        declared_sets = {
            tuple(dict.__getitem__(row, "compatibility_target_ids"))
            for row in group
        }
        if (
            "" in roots
            or "" in rationales
            or "" in falsifiers
            or len(roots) != 1
            or len(rationales) != 1
            or len(falsifiers) != 1
            or declared_sets != {tuple(expected_ids)}
        ):
            raise InputRefused(
                f"compatibility receipt {key!r} is not target-complete"
            )
        coordination = sorted(
            {
                dict.__getitem__(row, "target_id"): dict.__getitem__(
                    row,
                    "coordination_assignee",
                )
                for row in group
            }.items()
        )
        declared_domain = sorted(
            {
                dict.__getitem__(row, "target_id"): dict.__getitem__(
                    row,
                    "declared_domain_owner",
                )
                for row in group
            }.items()
        )
        user_effect = sorted(
            {
                dict.__getitem__(row, "target_id"): dict.__getitem__(
                    row,
                    "user_effect",
                )
                for row in group
            }.items()
        )
        reviewers = sorted(
            (
                dict.__getitem__(row, "target_id"),
                dict.__getitem__(row, "reviewer"),
                dict.__getitem__(row, "reviewer_kind"),
            )
            for row in group
        )
        dependency_neighborhood = sorted(
            (
                target_id,
                dict.__getitem__(
                    dict.__getitem__(inventory_by_id, target_id),
                    "dependency_neighborhood_root",
                ),
            )
            for target_id in expected_ids
        )
        target_roots = sorted(
            (
                target_id,
                dict.__getitem__(
                    dict.__getitem__(inventory_by_id, target_id),
                    "target_root",
                ),
            )
            for target_id in expected_ids
        )
        rationale = sorted(rationales)[0]
        falsifier = sorted(falsifiers)[0]
        computed = semantic_root(
            {
                "compatibility_key": key,
                "coordination": coordination,
                "declared_domain": declared_domain,
                "user_effect": user_effect,
                "reviewers": reviewers,
                "dependency_neighborhood": dependency_neighborhood,
                "target_ids": expected_ids,
                "target_roots": target_roots,
                "rationale": rationale,
                "falsifier": falsifier,
            }
        )
        if roots != {computed}:
            raise InputRefused(
                f"compatibility receipt {key!r} root does not match its scope"
            )
        group_start = group_end


def v2_validate_compatibility_receipts(
    receipts: Mapping[str, Mapping[str, Any]],
    inventory: Mapping[str, Any],
) -> None:
    detached = v2_released_json_snapshot(
        {"receipts": receipts, "inventory": inventory},
        label="compatibility receipt inputs",
        error_type=InputRefused,
    )
    if type(detached) is not dict:
        raise InputRefused("compatibility receipt snapshot is malformed")
    exact_receipts = dict.__getitem__(detached, "receipts")
    exact_inventory = dict.__getitem__(detached, "inventory")
    if type(exact_receipts) is not dict or type(exact_inventory) is not dict:
        raise InputRefused("compatibility receipt inputs are not objects")
    _v2_validate_compatibility_receipts_exact(
        exact_receipts,
        exact_inventory,
    )


def v2_reconstructed_review_receipt_source_payload(
    receipt_document: Mapping[str, Any],
) -> bytes:
    receipt_document = v2_validate_exact_json_wire(
        receipt_document,
        label="review receipt source reconstruction",
    )
    if type(receipt_document) is not dict:
        raise InputRefused(
            "review receipt source payload is not an exact object"
        )
    source_document = {
        key: value
        for key, value in dict.items(receipt_document)
        if key not in {"semantic_root", "source_identity"}
    }
    rows = dict.get(source_document, "receipts")
    if type(rows) is not list or any(
        type(row) is not dict for row in rows
    ):
        raise InputRefused(
            "review receipt source payload cannot be reconstructed"
        )
    if len(rows) > V2_INVENTORY_ROWS_CAP:
        raise InputRefused(
            "review receipt source payload exceeds the inventory-row cap"
        )
    source_document["receipts"] = [
        {
            key: value
            for key, value in dict.items(row)
            if key != "semantic_root"
        }
        for row in rows
    ]
    return canonical_bytes(source_document)


def v2_validate_review_receipt_source_identity(
    receipt_document: Mapping[str, Any],
    *,
    label: str,
) -> None:
    if type(label) is not str or not label:
        raise InputRefused("review receipt source identity label is malformed")
    receipt_document = v2_validate_exact_json_wire(
        receipt_document,
        label="review receipt source identity input",
    )
    if type(receipt_document) is not dict:
        raise InputRefused(f"{label} is not an exact object")
    source = dict.get(receipt_document, "source")
    source_identity = dict.get(receipt_document, "source_identity")
    receipts = dict.get(receipt_document, "receipts")
    if type(source) is not str or not source:
        raise InputRefused(f"{label} source is malformed")
    if source == "NOT_PROVIDED":
        if (
            source_identity is not None
            or type(receipts) is not list
            or list.__len__(receipts) != 0
        ):
            raise InputRefused(
                f"{label} absent source must have an empty receipt set"
            )
        return
    if source == "SYNTHETIC_FIXTURE":
        if source_identity is not None:
            raise InputRefused(
                f"{label} generated source must not carry a file identity"
            )
        return
    if source_identity is None:
        raise InputRefused(f"{label} lacks its required file identity")
    if type(source_identity) is not dict:
        raise InputRefused(f"{label} source identity is not an object")
    v2_exact_keys(
        source_identity,
        {"path", "bytes", "root"},
        label=f"{label} source identity",
    )
    try:
        relative_path = safe_relative(
            source_identity["path"],
            label=f"{label} source identity path",
        )
        normalized_path = str(relative_path)
        final_component = tuple.__getitem__(relative_path.parts, -1)
    except (KeyError, TypeError, UsageRefused) as error:
        raise InputRefused(f"{label} source identity path is malformed") from error
    if not str.endswith(str.lstrip(final_component, "."), ".json"):
        raise InputRefused(
            f"{label} source must name a closed JSON document"
        )
    reconstructed = v2_reconstructed_review_receipt_source_payload(
        receipt_document
    )
    expected_root = (
        "sha256-v1:" + hashlib.sha256(reconstructed).hexdigest()
    )
    if (
        normalized_path != source_identity["path"]
        or source != source_identity["path"]
        or type(source_identity["bytes"]) is not int
        or source_identity["bytes"] != len(reconstructed)
        or type(source_identity["root"]) is not str
        or source_identity["root"] != expected_root
    ):
        raise InputRefused(
            f"{label} source identity does not bind reconstructed canonical bytes"
        )


def v2_validate_compatibility_target_ids(
    value: Any,
    *,
    label: str,
    error_type: type[HarnessError] = InputRefused,
) -> list[str]:
    if (
        error_type is not InputRefused
        and error_type is not InfrastructureFailed
        and error_type is not EvidenceFailed
    ):
        raise EvidenceFailed(
            "compatibility target error type is not an allowed terminal"
        )
    if type(label) is not str or not label:
        raise EvidenceFailed("compatibility target label is malformed")
    if type(value) is not list:
        v2_raise_allowed_terminal_error(
            error_type,
            f"{label} must be an array",
        )
    if len(value) > V2_COMPATIBILITY_TARGETS_PER_RECEIPT_CAP:
        v2_raise_allowed_terminal_error(
            error_type,
            f"{label} exceed their cap",
        )
    if any(
        type(target_id) is not str
        or not target_id
        or target_id != str.strip(target_id)
        for target_id in value
    ):
        v2_raise_allowed_terminal_error(
            error_type,
            f"{label} are malformed",
        )
    if value != sorted(set(value)):
        v2_raise_allowed_terminal_error(
            error_type,
            f"{label} are noncanonical",
        )
    return value


def v2_fixture_gate_receipt_root(
    gate: str,
    *,
    target_root: str,
) -> str:
    if type(gate) is not str:
        raise EvidenceFailed("synthetic fixture gate is not an exact string")
    if not v2_is_semantic_root(target_root):
        raise EvidenceFailed(
            "synthetic fixture target root is not canonical"
        )
    if gate not in {"external", "conditional", "admission"}:
        raise EvidenceFailed(f"unsupported synthetic fixture gate {gate!r}")
    return semantic_root(
        {
            "gate": gate,
            "target_root": target_root,
        }
    )


