def v2_verify_review_input_semantic_root(
    document: Any,
    *,
    label: str,
) -> None:
    try:
        verify_semantic_root(document, label=label)
    except HarnessError as error:
        raise InputRefused(f"{label} semantic root is invalid") from error


def v2_validate_review_inventory_filter_values(
    values: Any,
    *,
    label: str,
) -> list[str]:
    if type(values) is not list or len(values) > V2_INVENTORY_ROWS_CAP:
        raise InputRefused(f"review inventory {label} filter is malformed")
    if any(type(value) is not str or not value for value in values):
        raise InputRefused(
            f"review inventory {label} filter contains an invalid value"
        )
    if values != sorted(set(values)):
        raise InputRefused(
            f"review inventory {label} filter is noncanonical"
        )
    if label == "priorities" and any(
        value not in {"P0", "P1", "P2", "P3", "P4"} for value in values
    ):
        raise InputRefused("review inventory priority filter is unknown")
    if label == "statuses":
        for index, value in enumerate(values):
            v2_validate_status(
                value,
                label=f"review inventory status filter {index}",
                error_type=InputRefused,
            )
    if label == "targets":
        for index, value in enumerate(values):
            v2_validate_issue_id(
                value,
                label=f"review inventory target filter {index}",
                error_type=InputRefused,
            )
    if label == "readiness" and any(
        value not in V2_READINESS_STATES for value in values
    ):
        raise InputRefused("review inventory readiness filter is unknown")
    if label == "routes" and any(
        value not in V2_REMEDIATION_ROUTES for value in values
    ):
        raise InputRefused("review inventory route filter is unknown")
    return values


def v2_validate_review_inventory_relation_rows(
    rows: Any,
    *,
    target_id: str,
    relation_field: str,
    label: str,
) -> None:
    if (
        type(relation_field) is not str
        or relation_field not in {"dependencies", "dependents"}
        or type(target_id) is not str
        or not target_id
        or type(label) is not str
        or not label
    ):
        raise EvidenceFailed("review inventory relation contract is malformed")
    rows = v2_released_json_snapshot(
        rows,
        label=label,
        error_type=InputRefused,
    )
    if type(rows) is not list or len(rows) > V2_RELATIONS_PER_DIRECTION_CAP:
        raise InputRefused(f"{label} are malformed or over cap")
    for index, relation in enumerate(rows):
        if type(relation) is not dict:
            raise InputRefused(f"{label} row {index} is not an exact object")
        fields = frozenset(dict.__iter__(relation))
        if fields != V2_SOURCE_RELATION_FIELDS:
            raise InputRefused(f"{label} row {index} has an unknown schema")
        relation_id = dict.__getitem__(relation, "id")
        relation_type = dict.__getitem__(relation, "type")
        relation_status = dict.__getitem__(relation, "status")
        relation_priority = dict.__getitem__(relation, "priority")
        if (
            type(relation_id) is not str
            or not relation_id
            or relation_id == target_id
            or type(relation_type) is not str
            or not relation_type
            or type(relation_status) is not str
            or type(relation_priority) is not int
            or relation_priority not in range(5)
            or type(dict.__getitem__(relation, "title")) is not str
            or not str.strip(dict.__getitem__(relation, "title"))
            or (
                str.startswith(relation_id, "external:")
                and (
                    (
                        relation_field == "dependencies"
                        and relation_type == "parent-child"
                    )
                    or (
                        relation_field == "dependents"
                        and relation_type != "parent-child"
                    )
                )
            )
        ):
            raise InputRefused(f"{label} row {index} has invalid scalars")
        if str.startswith(relation_id, "external:"):
            v2_validate_external_relation_id(
                relation_id,
                label=f"{label} row {index} ID",
                error_type=InputRefused,
            )
        else:
            v2_validate_issue_id(
                relation_id,
                label=f"{label} row {index} ID",
                error_type=InputRefused,
            )
        v2_validate_status(
            relation_status,
            label=f"{label} row {index} status",
            error_type=InputRefused,
        )
    neighbor_ids = [dict.__getitem__(relation, "id") for relation in rows]
    if len(neighbor_ids) != len(set(neighbor_ids)):
        raise InputRefused(f"{label} duplicate a neighbor")
    if rows != sorted(rows, key=lambda row: (row["type"], row["id"])):
        raise InputRefused(f"{label} are noncanonical")


def v2_validate_review_inventory_active_context(
    context: Any,
    *,
    target_id: str,
    target_status: str,
    tracker_assignee: str,
    dependencies: list[dict[str, Any]],
) -> None:
    if type(dependencies) is not list:
        raise EvidenceFailed(
            "review inventory active-context dependency contract is malformed"
        )
    if type(context) is not dict:
        raise InputRefused(
            f"review inventory target {target_id} active context is not an object"
        )
    v2_exact_keys(
        context,
        V2_REVIEW_INVENTORY_ACTIVE_CONTEXT_FIELDS,
        label=f"review inventory target {target_id} active context",
    )
    v2_verify_review_input_semantic_root(
        context,
        label=f"review inventory target {target_id} active context",
    )
    reasons = dict.__getitem__(context, "non_actionable_reasons")
    tracker_ready = dict.__getitem__(context, "tracker_ready")
    conflict = target_status == "in_progress" or bool(tracker_assignee)
    expected_child_status = (
        "deferred" if conflict or tracker_ready is not True else "open"
    )
    if (
        dict.__getitem__(context, "status") != target_status
        or dict.__getitem__(context, "tracker_assignee") != tracker_assignee
        or type(tracker_ready) is not bool
        or type(reasons) is not list
        or len(reasons) > V2_INVENTORY_ROWS_CAP
        or any(type(reason) is not str or not reason for reason in reasons)
        or len(reasons) != len(set(reasons))
        or dict.__getitem__(context, "conflict") is not conflict
        or dict.__getitem__(context, "generated_child_desired_status")
        != expected_child_status
        or dict.__getitem__(
            context,
            "coordination_acknowledgement_required",
        )
        is not conflict
        or dict.__getitem__(context, "actionability_review_required")
        is not (not tracker_ready)
        or dict.__getitem__(context, "agent_mail_hint") is not None
        or dict.__getitem__(context, "agent_mail_hint_authoritative")
        is not False
        or dict.__getitem__(context, "no_claim")
        != V2_ACTIVE_WORK_CONTEXT_NO_CLAIM
    ):
        raise InputRefused(
            f"review inventory target {target_id} active context is incoherent"
        )
    reason_order = {
        "pinned": 1,
        "template": 2,
        "ephemeral": 3,
        "wisp": 4,
        "defer-metadata-present": 5,
        "nonterminal-blocking-dependency-present": 6,
        "tracker-ready-policy-exclusion": 7,
    }
    ranked_reasons: list[tuple[int, bytes]] = []
    status_reason_count = 0
    for reason_index, reason in enumerate(reasons):
        if str.startswith(reason, "terminal-status:"):
            reason_status = str.removeprefix(reason, "terminal-status:")
            if not v2_is_terminal_status(reason_status):
                raise InputRefused(
                    f"review inventory target {target_id} active reason "
                    f"{reason_index} has a nonterminal terminal status"
                )
            reason_rank = 0
            status_reason_count += 1
        elif str.startswith(reason, "tracker-status-not-ready:"):
            reason_status = str.removeprefix(
                reason,
                "tracker-status-not-ready:",
            )
            v2_validate_status(
                reason_status,
                label=(
                    f"review inventory target {target_id} active reason "
                    f"{reason_index} status"
                ),
                error_type=InputRefused,
            )
            if reason_status == "open" or v2_is_terminal_status(reason_status):
                raise InputRefused(
                    f"review inventory target {target_id} active reason "
                    f"{reason_index} has an impossible tracker status"
                )
            reason_rank = 0
            status_reason_count += 1
        elif reason in reason_order:
            reason_rank = dict.__getitem__(reason_order, reason)
        else:
            raise InputRefused(
                f"review inventory target {target_id} active reason "
                f"{reason_index} is unknown"
            )
        ranked_reasons.append((reason_rank, str.encode(reason, "utf-8")))
    if (
        status_reason_count > 1
        or bool(reasons) is tracker_ready
        or ranked_reasons != sorted(ranked_reasons)
    ):
        raise InputRefused(
            f"review inventory target {target_id} active reasons are incoherent"
        )
    expected_status_reason = (
        f"terminal-status:{target_status}"
        if v2_is_terminal_status(target_status)
        else (
            f"tracker-status-not-ready:{target_status}"
            if target_status != "open"
            else None
        )
    )
    if (
        (expected_status_reason is not None and expected_status_reason not in reasons)
        or (
            expected_status_reason is None
            and status_reason_count != 0
        )
        or (
            "tracker-ready-policy-exclusion" in reasons
            and reasons != ["tracker-ready-policy-exclusion"]
        )
        or (target_status == "pinned" and "pinned" not in reasons)
    ):
        raise InputRefused(
            f"review inventory target {target_id} active status reasons differ"
        )
    blocking_dependency_present = any(
        dict.__getitem__(relation, "type") in V2_BLOCKING_DEPENDENCY_TYPES
        and not v2_is_terminal_status(
            dict.__getitem__(relation, "status")
        )
        for relation in dependencies
    )
    if (
        ("wisp" in reasons) is not ("-wisp-" in target_id)
        or (
            "nonterminal-blocking-dependency-present" in reasons
        )
        is not blocking_dependency_present
    ):
        raise InputRefused(
            f"review inventory target {target_id} active evidence reasons differ"
        )


def v2_validate_review_inventory_target(
    target: Any,
    *,
    index: int,
    campaign_epoch_root: str,
) -> tuple[str, str, int]:
    if type(index) is not int or index < 0 or type(target) is not dict:
        raise InputRefused(f"review inventory row {index} is not an exact object")
    v2_exact_keys(
        target,
        V2_REVIEW_INVENTORY_TARGET_FIELDS,
        label=f"review inventory row {index}",
    )
    v2_verify_review_input_semantic_root(
        target,
        label=f"review inventory row {index}",
    )
    target_id = dict.__getitem__(target, "id")
    issue_id = dict.__getitem__(target, "issue_id")
    title = dict.__getitem__(target, "title")
    issue_type = dict.__getitem__(target, "type")
    status = dict.__getitem__(target, "status")
    priority = dict.__getitem__(target, "priority")
    if (
        type(target_id) is not str
        or not target_id
        or issue_id != target_id
        or type(title) is not str
        or not str.strip(title)
        or type(issue_type) is not str
        or not issue_type
        or dict.__getitem__(target, "issue_type") != issue_type
        or type(status) is not str
        or type(priority) is not int
        or priority not in range(5)
    ):
        raise InputRefused(f"review inventory row {index} core scalars differ")
    v2_validate_issue_id(
        target_id,
        label=f"review inventory row {index} ID",
        error_type=InputRefused,
    )
    v2_validate_status(
        status,
        label=f"review inventory row {index} status",
        error_type=InputRefused,
    )
    if status == "tombstone":
        raise InputRefused(
            f"review inventory row {index} cannot schedule an unsupported "
            "tombstone finding"
        )
    priority_lane = f"P{priority}"
    destination = (
        "history-v2.json" if status == "closed" else "review-plan-v2.json"
    )
    if (
        dict.__getitem__(target, "priority_lane") != priority_lane
        or dict.__getitem__(target, "status_lane") != status
        or dict.__getitem__(target, "lane") != f"{priority_lane}/{status}"
        or dict.__getitem__(target, "campaign_epoch_root")
        != campaign_epoch_root
        or dict.__getitem__(target, "destination") != destination
        or dict.__getitem__(target, "movement_destination") != destination
    ):
        raise InputRefused(f"review inventory row {index} routing aliases differ")
    for field in (
        "tracker_assignee",
        "coordination_assignee",
        "tracker_owner",
        "parent",
        "disposition_rationale",
        "disposition_falsifier",
        "declared_domain_owner",
        "declared_acceptance_owner",
        "implementation_owner",
        "evidence_owner",
        "terminal_consumer",
        "user_effect",
        "no_claim",
    ):
        if type(dict.__getitem__(target, field)) is not str:
            raise InputRefused(
                f"review inventory row {index} {field} is not a string"
            )
    if dict.__getitem__(target, "coordination_assignee") != dict.__getitem__(
        target,
        "tracker_assignee",
    ):
        raise InputRefused(
            f"review inventory row {index} coordination alias differs"
        )
    parent = dict.__getitem__(target, "parent")
    if parent:
        v2_validate_issue_id(
            parent,
            label=f"review inventory row {index} parent ID",
            error_type=InputRefused,
        )
    if parent == target_id:
        raise InputRefused(
            f"review inventory row {index} cannot name itself as parent"
        )
    labels = dict.__getitem__(target, "labels")
    if (
        type(labels) is not list
        or len(labels) > V2_LABELS_PER_ISSUE_CAP
        or any(type(label) is not str or not label for label in labels)
        or labels != sorted(set(labels))
    ):
        raise InputRefused(f"review inventory row {index} labels are noncanonical")
    missing_sections = dict.__getitem__(target, "missing_sections")
    try:
        canonical_missing_sections = list(
            v2_canonical_missing_sections(
                issue_type,
                tuple(list.__iter__(missing_sections)),
            )
        ) if type(missing_sections) is list else None
    except HarnessError as error:
        raise InputRefused(
            f"review inventory row {index} missing sections are noncanonical"
        ) from error
    if (
        type(missing_sections) is not list
        or len(missing_sections) > V2_WARNINGS_PER_ISSUE_CAP
        or missing_sections != canonical_missing_sections
    ):
        raise InputRefused(
            f"review inventory row {index} missing sections are noncanonical"
        )
    if (
        dict.__getitem__(target, "disposition") not in DISPOSITIONS
        or dict.__getitem__(target, "template_warning_state")
        != ("PRESENT" if missing_sections else "NONE")
    ):
        raise InputRefused(
            f"review inventory row {index} warning disposition differs"
        )
    classification_disposition = dict.__getitem__(target, "disposition")
    if (
        (status == "closed")
        is not (
            classification_disposition
            == "HISTORICAL_IMMUTABLE_REVIEW"
        )
        or (
            status == "deferred"
            and classification_disposition != "OWNER_REVIEW_REQUIRED"
        )
        or (status == "closed" and not missing_sections)
        or (
            status != "closed"
            and not missing_sections
            and classification_disposition != "OWNER_REVIEW_REQUIRED"
        )
    ):
        raise InputRefused(
            f"review inventory row {index} classification differs from "
            "its selected source state"
        )
    v2_validate_unreviewed_semantic_contract(
        target,
        label=f"review inventory row {index}",
    )
    if dict.__getitem__(target, "semantic_review_disposition") != (
        v2_unreviewed_semantic_disposition(
            status=status,
            classification_disposition=classification_disposition,
        )
    ):
        raise InputRefused(
            f"review inventory row {index} unreviewed semantic disposition "
            "differs from its classification"
        )
    for field in ("disposition_rationale", "disposition_falsifier", "user_effect"):
        v2_validate_canonical_semantic_text(
            dict.__getitem__(target, field),
            label=f"review inventory row {index} {field}",
            allow_empty=False,
            error_type=InputRefused,
        )
    expected_user_effect = (
        "make exact review debt visible to users"
        if dict.__getitem__(target, "no_claim")
        == "synthetic planning row grants no authority"
        else (
            "make the target planning contract specific, testable, "
            "replayable, and honest without changing target behavior"
        )
    )
    if dict.__getitem__(target, "user_effect") != expected_user_effect:
        raise InputRefused(
            f"review inventory row {index} user effect differs from its "
            "projection kind"
        )
    field_roots = dict.__getitem__(target, "field_roots")
    field_lengths = dict.__getitem__(target, "field_byte_lengths")
    if (
        type(field_roots) is not dict
        or frozenset(dict.__iter__(field_roots))
        != V2_REVIEW_INVENTORY_FIELD_NAMES
        or any(
            not v2_is_semantic_root(dict.__getitem__(field_roots, field))
            for field in V2_REVIEW_INVENTORY_FIELD_NAMES
        )
        or type(field_lengths) is not dict
        or frozenset(dict.__iter__(field_lengths))
        != V2_REVIEW_INVENTORY_FIELD_NAMES
        or any(
            type(dict.__getitem__(field_lengths, field)) is not int
            or dict.__getitem__(field_lengths, field) < 0
            or dict.__getitem__(field_lengths, field) > CAPS["field_bytes"]
            for field in V2_REVIEW_INVENTORY_FIELD_NAMES
        )
    ):
        raise InputRefused(
            f"review inventory row {index} field evidence is malformed"
        )
    clause_index = dict.__getitem__(target, "clause_roots")
    v2_validate_clause_index(clause_index)
    if (
        any(
            dict.__getitem__(clause_row, "byte_length")
            > dict.__getitem__(
                field_lengths,
                dict.__getitem__(clause_row, "field"),
            )
            for clause_row in dict.__getitem__(clause_index, "rows")
        )
        or dict.__getitem__(clause_index, "maximum_clause_bytes")
        > max(
            (
                dict.__getitem__(field_lengths, field)
                for field in V2_REVIEW_INVENTORY_FIELD_NAMES
            ),
            default=0,
        )
    ):
        raise InputRefused(
            f"review inventory row {index} clause lengths exceed their fields"
        )
    for field in (
        "target_root",
        "source_issue_projection_root",
        "v1_row_root",
        "dependency_neighborhood_root",
    ):
        if not v2_is_semantic_root(dict.__getitem__(target, field)):
            raise InputRefused(
                f"review inventory row {index} {field} is malformed"
            )
    if dict.__getitem__(target, "target_root") != v2_normalized_target_root(
        target
    ):
        raise InputRefused(
            f"review inventory row {index} normalized target root differs"
        )
    v2_validate_review_inventory_relation_rows(
        dict.__getitem__(target, "dependencies"),
        target_id=target_id,
        relation_field="dependencies",
        label=f"review inventory row {index} dependencies",
    )
    v2_validate_review_inventory_relation_rows(
        dict.__getitem__(target, "dependents"),
        target_id=target_id,
        relation_field="dependents",
        label=f"review inventory row {index} dependents",
    )
    parent_edges = [
        dict.__getitem__(relation, "id")
        for relation in dict.__getitem__(target, "dependencies")
        if dict.__getitem__(relation, "type") == "parent-child"
    ]
    if parent_edges != ([parent] if parent else []):
        raise InputRefused(
            f"review inventory row {index} parent relation differs"
        )
    expected_dependency_root = v2_dependency_neighborhood_root(target)
    if (
        dict.__getitem__(target, "dependency_neighborhood_root")
        != expected_dependency_root
    ):
        raise InputRefused(
            f"review inventory row {index} dependency root differs"
        )
    domain_candidates = dict.__getitem__(target, "domain_candidates")
    if (
        type(domain_candidates) is not list
        or len(domain_candidates) > V2_INVENTORY_ROWS_CAP
        or dict.__getitem__(target, "domain_candidate") != domain_candidates
    ):
        raise InputRefused(
            f"review inventory row {index} domain candidates differ"
        )
    candidate_identities: list[tuple[str, str]] = []
    candidate_falsifiers = {
        "v1-classification-hint": (
            "a root-bound reviewer may reject this inferred domain; "
            "the hint grants no authority"
        ),
        "tracker-parent": (
            "the parent may be only a rollup and not a domain owner"
        ),
        "tracker-label": (
            "a label is a routing hint and may be stale, generic, "
            "or unauthorized"
        ),
        "source-path-clause": (
            "a mentioned path may not own the target semantics"
        ),
    }
    for candidate_index, candidate in enumerate(domain_candidates):
        if type(candidate) is not dict:
            raise InputRefused(
                f"review inventory row {index} domain candidate "
                f"{candidate_index} is not an object"
            )
        v2_exact_keys(
            candidate,
            {"candidate", "source", "provenance_root", "falsifier"},
            label=(
                f"review inventory row {index} domain candidate "
                f"{candidate_index}"
            ),
        )
        candidate_value = dict.__getitem__(candidate, "candidate")
        candidate_source = dict.__getitem__(candidate, "source")
        candidate_falsifier = dict.__getitem__(candidate, "falsifier")
        if (
            type(candidate_value) is not str
            or not candidate_value
            or type(candidate_source) is not str
            or type(candidate_falsifier) is not str
        ):
            raise InputRefused(
                f"review inventory row {index} domain candidate "
                f"{candidate_index} is malformed"
            )
        if candidate_source == "tracker-parent":
            candidate_parent = (
                str.removeprefix(candidate_value, "parent:")
                if str.startswith(candidate_value, "parent:")
                else ""
            )
            expected_candidate_root = (
                text_root(candidate_parent)
                if candidate_parent == parent and bool(parent)
                else None
            )
        elif candidate_source == "source-path-clause":
            expected_candidate_root = text_root(
                str.removeprefix(candidate_value, "path:")
            ) if str.startswith(candidate_value, "path:") else None
        elif candidate_source == "tracker-label":
            expected_candidate_root = (
                text_root(candidate_value)
                if candidate_value in labels
                and str.startswith(
                    candidate_value,
                    ("crate:", "domain:", "authority:"),
                )
                else None
            )
        elif candidate_source == "v1-classification-hint":
            expected_candidate_root = text_root(candidate_value)
        else:
            expected_candidate_root = None
        if (
            candidate_source not in candidate_falsifiers
            or candidate_falsifier
            != dict.__getitem__(candidate_falsifiers, candidate_source)
            or expected_candidate_root is None
            or dict.__getitem__(candidate, "provenance_root")
            != expected_candidate_root
        ):
            raise InputRefused(
                f"review inventory row {index} domain candidate "
                f"{candidate_index} is malformed"
            )
        candidate_identities.append((candidate_value, candidate_source))
    if candidate_identities != sorted(set(candidate_identities)):
        raise InputRefused(
            f"review inventory row {index} domain candidates are noncanonical"
        )
    reviewer = dict.__getitem__(target, "reviewer_provenance")
    if type(reviewer) is not dict:
        raise InputRefused(
            f"review inventory row {index} reviewer provenance is malformed"
        )
    v2_exact_keys(
        reviewer,
        {"state", "receipt_root"},
        label=f"review inventory row {index} reviewer provenance",
    )
    if (
        dict.__getitem__(reviewer, "state") != "NODATA"
        or dict.__getitem__(reviewer, "receipt_root") is not None
    ):
        raise InputRefused(
            f"review inventory row {index} reviewer provenance grants authority"
        )
    closure = dict.__getitem__(target, "source_closure")
    if type(closure) is not dict:
        raise InputRefused(
            f"review inventory row {index} source closure is malformed"
        )
    v2_exact_keys(
        closure,
        {"required", "state"},
        label=f"review inventory row {index} source closure",
    )
    closure_required = dict.__getitem__(closure, "required")
    if (
        type(closure_required) is not bool
        or dict.__getitem__(closure, "state")
        != (
            "REVIEW_REQUIRED"
            if closure_required
            else "NOT_REQUIRED_BY_V1_CLASSIFICATION"
        )
    ):
        raise InputRefused(
            f"review inventory row {index} source closure differs"
        )
    estimate = dict.__getitem__(
        target,
        "target_implementation_estimated_minutes",
    )
    estimate_alias = dict.__getitem__(
        target,
        "target_implementation_estimate_minutes",
    )
    estimate_state = dict.__getitem__(
        target,
        "target_implementation_estimate_state",
    )
    if (
        type(estimate_state) is not str
        or estimate_state not in {"DECLARED", "NODATA"}
        or (
            estimate_state == "DECLARED"
            and (
                type(estimate) is not int
                or type(estimate_alias) is not int
                or estimate < 0
                or estimate_alias != estimate
            )
        )
        or (
            estimate_state == "NODATA"
            and (estimate is not None or estimate_alias is not None)
        )
    ):
        raise InputRefused(
            f"review inventory row {index} implementation estimate differs"
        )
    review_minutes = dict.__getitem__(target, "review_minutes")
    generated_minutes = dict.__getitem__(
        target,
        "generated_child_estimated_minutes",
    )
    retained_bytes = dict.__getitem__(target, "retained_payload_bytes")
    if (
        type(review_minutes) is not int
        or review_minutes < 0
        or int.bit_length(review_minutes) > V2_EXACT_JSON_INTEGER_BITS_CAP
        or type(generated_minutes) is not int
        or generated_minutes != review_minutes
        or type(retained_bytes) is not int
        or retained_bytes < 0
        or int.bit_length(retained_bytes) > V2_EXACT_JSON_INTEGER_BITS_CAP
        or retained_bytes < sum(
            dict.__getitem__(field_lengths, field)
            for field in V2_REVIEW_INVENTORY_FIELD_NAMES
        )
        or retained_bytes > V2_SOURCE_PROJECTION_BYTES_CAP
    ):
        raise InputRefused(
            f"review inventory row {index} work or payload estimate differs"
        )
    if dict.__getitem__(target, "no_claim") == (
        "this normalized target schedules review only; it does not "
        "approve semantics, mutate the target, or prove implementation"
    ) and review_minutes != v2_review_minutes(
        v2_synthetic_source_issue(target)
    ):
        raise InputRefused(
            f"review inventory row {index} review estimate differs from source"
        )
    if (
        dict.__getitem__(target, "declared_domain_owner") != ""
        or dict.__getitem__(target, "declared_acceptance_owner") != ""
        or dict.__getitem__(target, "evidence_owner") != "UNRESOLVED"
        or dict.__getitem__(target, "terminal_consumer") != "UNRESOLVED"
        or dict.__getitem__(target, "implementation_owner")
        != (
            dict.__getitem__(target, "tracker_assignee")
            or dict.__getitem__(target, "tracker_owner")
            or "UNRESOLVED"
        )
        or dict.__getitem__(target, "external_authority_adapter_identity") != ""
        or dict.__getitem__(target, "external_authority_receipt_root") != ""
        or dict.__getitem__(target, "external_authority_verdict") != "NODATA"
        or dict.__getitem__(target, "conditional_write_capability_identity")
        != ""
        or dict.__getitem__(target, "conditional_write_receipt_root") != ""
        or dict.__getitem__(target, "conditional_write_verdict") != "NODATA"
        or dict.__getitem__(target, "readiness") != "REVIEW_ONLY"
        or dict.__getitem__(target, "remediation_route") != "ANALYSIS_ONLY"
        or dict.__getitem__(target, "no_claim")
        not in V2_REVIEW_TARGET_NO_CLAIMS
    ):
        raise InputRefused(
            f"review inventory row {index} pre-review authority differs"
        )
    v2_validate_review_inventory_active_context(
        dict.__getitem__(target, "active_work_context"),
        target_id=target_id,
        target_status=status,
        tracker_assignee=dict.__getitem__(target, "tracker_assignee"),
        dependencies=dict.__getitem__(target, "dependencies"),
    )
    if dict.__getitem__(target, "no_claim") == (
        "synthetic planning row grants no authority"
    ):
        try:
            v2_validate_synthetic_target_identity(target)
        except HarnessError as error:
            raise InputRefused(
                f"review inventory row {index} synthetic identity differs"
            ) from error
    return target_id, status, len(missing_sections)


def v2_validate_review_inventory(inventory: Any) -> dict[str, Any]:
    inventory = v2_released_json_snapshot(
        inventory,
        label="review receipt inventory",
        error_type=InputRefused,
    )
    if type(inventory) is not dict:
        raise InputRefused("review receipt inventory is not an exact object")
    v2_exact_keys(
        inventory,
        V2_REVIEW_INVENTORY_FIELDS,
        label="review receipt inventory",
    )
    inventory_no_claim = dict.__getitem__(inventory, "no_claim")
    if (
        dict.__getitem__(inventory, "schema") != V2_INVENTORY_SCHEMA
        or type(inventory_no_claim) is not str
        or inventory_no_claim not in V2_REVIEW_INVENTORY_NO_CLAIMS
    ):
        raise InputRefused("review receipt inventory identity differs")
    for root_field in (
        "v1_inventory_root",
        "campaign_epoch_root",
        "nonclosed_ids_root",
        "history_ids_root",
    ):
        if not v2_is_semantic_root(dict.__getitem__(inventory, root_field)):
            raise InputRefused(
                f"review receipt inventory {root_field} is malformed"
            )
    v2_verify_review_input_semantic_root(
        inventory,
        label="review receipt inventory",
    )
    filters = dict.__getitem__(inventory, "filters")
    if type(filters) is not dict:
        raise InputRefused("review receipt inventory filters are not an object")
    v2_exact_keys(
        filters,
        V2_REVIEW_INVENTORY_FILTER_FIELDS,
        label="review receipt inventory filters",
    )
    for filter_name in (
        "priorities",
        "statuses",
        "targets",
        "readiness",
        "routes",
    ):
        v2_validate_review_inventory_filter_values(
            dict.__getitem__(filters, filter_name),
            label=filter_name,
        )
    if (
        dict.__getitem__(filters, "empty_means_all") is not True
        or dict.__getitem__(
            filters,
            "authority_filters_apply_to_selected_projection",
        )
        is not True
    ):
        raise InputRefused("review receipt inventory filter semantics differ")
    rows = dict.__getitem__(inventory, "rows")
    if type(rows) is not list or len(rows) > V2_INVENTORY_ROWS_CAP:
        raise InputRefused("review receipt inventory rows are malformed")
    campaign_epoch_root = dict.__getitem__(inventory, "campaign_epoch_root")
    observations = [
        v2_validate_review_inventory_target(
            target,
            index=index,
            campaign_epoch_root=campaign_epoch_root,
        )
        for index, target in enumerate(rows)
    ]
    target_ids = [observation[0] for observation in observations]
    if target_ids != sorted(set(target_ids)):
        raise InputRefused(
            "review receipt inventory target membership is noncanonical"
        )
    row_identity_roots = [
        dict.__getitem__(target, identity_field)
        for target in rows
        for identity_field in (
            "target_root",
            "source_issue_projection_root",
            "v1_row_root",
        )
    ]
    identity_roots = [
        *row_identity_roots,
        dict.__getitem__(inventory, "v1_inventory_root"),
        campaign_epoch_root,
    ]
    if len(identity_roots) != len(set(identity_roots)):
        raise InputRefused(
            "review receipt inventory identity roots alias across "
            "inventory, campaign, row, or projection kinds"
        )
    identity_root_set = frozenset(identity_roots)
    dependency_roots = [
        dict.__getitem__(target, "dependency_neighborhood_root")
        for target in rows
    ]
    if any(
        dependency_root in identity_root_set
        for dependency_root in dependency_roots
    ):
        raise InputRefused(
            "review receipt inventory dependency roots alias inventory, "
            "campaign, target, source, or v1 identities"
        )
    nonclosed_ids = [
        target_id
        for target_id, status, _warning_count in observations
        if status != "closed"
    ]
    history_ids = [
        target_id
        for target_id, status, _warning_count in observations
        if status == "closed"
    ]
    expected_target_no_claim = (
        "synthetic planning row grants no authority"
        if inventory_no_claim == "synthetic inventory is test evidence only"
        else (
            "this normalized target schedules review only; it does not "
            "approve semantics, mutate the target, or prove implementation"
        )
    )
    if any(
        dict.__getitem__(target, "no_claim") != expected_target_no_claim
        for target in rows
    ):
        raise InputRefused(
            "review receipt inventory and target no-claim kinds differ"
        )
    synthetic_inventory_kind = (
        inventory_no_claim == "synthetic inventory is test evidence only"
    )
    synthetic_v1_inventory_root = semantic_root({"synthetic": True})
    if (
        dict.__getitem__(inventory, "v1_inventory_root")
        == synthetic_v1_inventory_root
    ) is not synthetic_inventory_kind:
        raise InputRefused(
            "review receipt inventory synthetic identity kind differs"
        )
    if synthetic_inventory_kind:
        expected_campaign_epoch_root = semantic_root(
            [
                {
                    "id": dict.__getitem__(target, "id"),
                    "target_root": dict.__getitem__(target, "target_root"),
                }
                for target in rows
            ]
        )
        if campaign_epoch_root != expected_campaign_epoch_root:
            raise InputRefused(
                "review receipt inventory synthetic campaign root differs "
                "from its target membership"
            )
    priority_filter = dict.__getitem__(filters, "priorities")
    status_filter = dict.__getitem__(filters, "statuses")
    target_filter = dict.__getitem__(filters, "targets")
    if (
        priority_filter
        and any(
            dict.__getitem__(target, "priority_lane")
            not in priority_filter
            for target in rows
        )
    ) or (
        status_filter
        and any(
            dict.__getitem__(target, "status") not in status_filter
            for target in rows
        )
    ) or (
        target_filter
        and any(target_id not in target_filter for target_id in target_ids)
    ):
        raise InputRefused(
            "review receipt inventory rows differ from selected filters"
        )
    warning_count = sum(
        warning_count for _target_id, _status, warning_count in observations
    )
    v2_validate_source_limits(
        row_count=len(rows),
        warning_count=warning_count,
        maximum_warnings_per_issue=max(
            (
                warning_count
                for _target_id, _status, warning_count in observations
            ),
            default=0,
        ),
    )
    counts = dict.__getitem__(inventory, "counts")
    if type(counts) is not dict:
        raise InputRefused("review receipt inventory counts are not an object")
    v2_exact_keys(
        counts,
        V2_REVIEW_INVENTORY_COUNT_FIELDS,
        label="review receipt inventory counts",
    )
    expected_counts = {
        "targets": len(rows),
        "nonclosed": len(nonclosed_ids),
        "history": len(history_ids),
        "warnings": warning_count,
    }
    if any(
        type(dict.__getitem__(counts, field)) is not int
        or dict.__getitem__(counts, field) != expected
        for field, expected in dict.items(expected_counts)
    ):
        raise InputRefused("review receipt inventory counts differ from rows")
    if (
        dict.__getitem__(inventory, "nonclosed_ids_root")
        != semantic_root(nonclosed_ids)
        or dict.__getitem__(inventory, "history_ids_root")
        != semantic_root(history_ids)
    ):
        raise InputRefused(
            "review receipt inventory membership roots differ from rows"
        )
    row_by_id = {
        dict.__getitem__(target, "id"): target
        for target in rows
    }
    def selected_has_relation(
        relations: list[dict[str, Any]],
        *,
        relation_type: str,
        neighbor_id: str,
    ) -> bool:
        lower = 0
        upper = len(relations)
        while lower < upper:
            midpoint = (lower + upper) // 2
            candidate = list.__getitem__(relations, midpoint)
            candidate_type = dict.__getitem__(candidate, "type")
            candidate_id = dict.__getitem__(candidate, "id")
            precedes = (
                str.__lt__(candidate_type, relation_type) is True
                or (
                    str.__eq__(candidate_type, relation_type) is True
                    and str.__lt__(candidate_id, neighbor_id) is True
                )
            )
            if precedes:
                lower = midpoint + 1
            else:
                upper = midpoint
        if lower >= len(relations):
            return False
        candidate = list.__getitem__(relations, lower)
        return (
            str.__eq__(
                dict.__getitem__(candidate, "type"),
                relation_type,
            )
            is True
            and str.__eq__(
                dict.__getitem__(candidate, "id"),
                neighbor_id,
            )
            is True
        )

    for target_id in target_ids:
        target = dict.__getitem__(row_by_id, target_id)
        for relation_field, reciprocal_field in (
            ("dependencies", "dependents"),
            ("dependents", "dependencies"),
        ):
            for relation in dict.__getitem__(target, relation_field):
                neighbor_id = dict.__getitem__(relation, "id")
                if (
                    str.startswith(neighbor_id, "external:")
                    or not dict.__contains__(row_by_id, neighbor_id)
                ):
                    continue
                neighbor = dict.__getitem__(row_by_id, neighbor_id)
                if (
                    dict.__getitem__(relation, "title")
                    != dict.__getitem__(neighbor, "title")
                    or dict.__getitem__(relation, "status")
                    != dict.__getitem__(neighbor, "status")
                    or dict.__getitem__(relation, "priority")
                    != dict.__getitem__(neighbor, "priority")
                    or not selected_has_relation(
                        dict.__getitem__(neighbor, reciprocal_field),
                        relation_type=dict.__getitem__(relation, "type"),
                        neighbor_id=target_id,
                    )
                ):
                    raise InputRefused(
                        "review receipt inventory selected relation differs "
                        f"for {target_id}.{relation_field}->{neighbor_id}"
                    )
    selected_blocking_adjacency = {
        target_id: sorted(
            dict.__getitem__(relation, "id")
            for relation in dict.__getitem__(
                dict.__getitem__(row_by_id, target_id),
                "dependencies",
            )
            if (
                dict.__getitem__(relation, "type")
                in V2_BLOCKING_DEPENDENCY_TYPES
                and dict.__getitem__(relation, "id") in row_by_id
            )
        )
        for target_id in target_ids
    }
    selected_parent_adjacency = {
        target_id: (
            [dict.__getitem__(dict.__getitem__(row_by_id, target_id), "parent")]
            if dict.__getitem__(dict.__getitem__(row_by_id, target_id), "parent")
            in row_by_id
            else []
        )
        for target_id in target_ids
    }
    try:
        v2_validate_source_graph_acyclic(
            selected_blocking_adjacency,
            node_ids=target_ids,
            relation_label="selected blocking dependency cycle",
        )
        v2_validate_source_graph_acyclic(
            selected_parent_adjacency,
            node_ids=target_ids,
            relation_label="selected parent hierarchy cycle",
        )
    except EvidenceFailed as error:
        raise InputRefused(
            "review receipt inventory selected relation graph is cyclic"
        ) from error
    return inventory


def v2_validate_receipt_bindings(
    receipt_document: Mapping[str, Any],
    inventory: Mapping[str, Any],
) -> tuple[dict[str, Any], dict[str, Any]]:
    detached_inputs = v2_validate_exact_json_wire(
        {
            "receipt_document": receipt_document,
            "inventory": inventory,
        },
        label="review receipt binding inputs",
    )
    if type(detached_inputs) is not dict:
        raise InputRefused("review receipt binding snapshot is malformed")
    receipt_document = dict.__getitem__(
        detached_inputs,
        "receipt_document",
    )
    inventory = dict.__getitem__(detached_inputs, "inventory")
    if type(receipt_document) is not dict or type(inventory) is not dict:
        raise InputRefused("review receipt binding inputs are not objects")
    allowed_document_keys = {
        "schema",
        "inventory_root",
        "campaign_epoch_root",
        "receipts",
        "source",
        "source_identity",
        "no_claim",
        "semantic_root",
    }
    required_document_keys = frozenset(
        allowed_document_keys - {"source_identity"}
    )
    allowed_document_keys = frozenset(allowed_document_keys)
    receipt_document_keys = frozenset(dict.__iter__(receipt_document))
    if (
        (
            receipt_document_keys != required_document_keys
            and receipt_document_keys != allowed_document_keys
        )
        or dict.get(receipt_document, "schema")
        != V2_REVIEW_RECEIPTS_SCHEMA
        or dict.get(receipt_document, "no_claim")
        != V2_REVIEW_RECEIPTS_NO_CLAIM
    ):
        raise InputRefused("review receipts bind a different source or schema")
    source = dict.__getitem__(receipt_document, "source")
    if type(source) is not str or not str.strip(source):
        raise InputRefused("review receipts source is malformed")
    rows = dict.get(receipt_document, "receipts")
    if (
        type(rows) is not list
        or len(rows) > V2_INVENTORY_ROWS_CAP
    ):
        raise InputRefused("review receipts must contain an array")
    _v2_validate_review_receipt_document_provenance_exact(
        receipt_document,
        inventory=inventory,
        label="review receipts",
    )
    verify_semantic_root(receipt_document, label="v2 review receipts")
    v2_validate_review_receipt_source_identity(
        receipt_document,
        label="review receipts",
    )
    inventory = v2_validate_review_inventory(inventory)
    inventory_rows = dict.__getitem__(inventory, "rows")
    inventory_by_id: dict[str, dict[str, Any]] = {}
    for inventory_index, target in enumerate(inventory_rows):
        target_id = dict.__getitem__(target, "id")
        inventory_by_id[target_id] = target
    observed_ids: list[str] = []
    for index, receipt in enumerate(rows):
        if type(receipt) is not dict:
            raise InputRefused(f"review receipt {index} is not an object")
        v2_exact_keys(
            receipt,
            {*V2_REVIEW_RECEIPT_FIELDS, "semantic_root"},
            label=f"review receipt {index}",
        )
        verify_semantic_root(receipt, label=f"review receipt {index}")
        target_id = receipt["target_id"]
        if type(target_id) is not str or not target_id:
            raise InputRefused(f"review receipt {index} has an invalid target ID")
        if target_id not in inventory_by_id:
            raise InputRefused(f"review receipt targets unknown {target_id}")
        target = inventory_by_id[target_id]
        if receipt["target_root"] != target["target_root"]:
            raise InputRefused(
                f"review receipt target root drifted for {target_id}"
            )
        _v2_validate_review_receipt_row_provenance_exact(
            receipt,
            receipt_document,
            label=f"review receipt {target_id}",
        )
        review_minutes = receipt["review_minutes"]
        if type(review_minutes) is not int or review_minutes < 0:
            raise InputRefused(f"review receipt minutes are invalid for {target_id}")
        string_fields = V2_REVIEW_RECEIPT_FIELDS - {
            "compatibility_target_ids",
            "review_minutes",
            "manual_authorization",
            "source_closure",
            "semantic_review_dimensions",
        }
        if any(type(receipt[field]) is not str for field in string_fields):
            raise InputRefused(
                f"review receipt contains a non-string scalar for {target_id}"
            )
        if receipt["no_claim"] != V2_REVIEW_RECEIPT_ROW_NO_CLAIM:
            raise InputRefused(
                f"review receipt no-claim boundary differs for {target_id}"
            )
        if type(receipt["manual_authorization"]) is not bool:
            raise InputRefused(
                f"review receipt manual authorization is not boolean for {target_id}"
            )
        semantic_rationale = v2_validate_canonical_semantic_text(
            receipt["semantic_review_rationale"],
            label=f"review receipt semantic rationale for {target_id}",
            allow_empty=True,
            error_type=InputRefused,
        )
        semantic_falsifier = v2_validate_canonical_semantic_text(
            receipt["semantic_review_falsifier"],
            label=f"review receipt semantic falsifier for {target_id}",
            allow_empty=True,
            error_type=InputRefused,
        )
        v2_validate_canonical_semantic_text(
            receipt["user_effect"],
            label=f"review receipt user effect for {target_id}",
            allow_empty=False,
            error_type=InputRefused,
        )
        v2_validate_receipt_authority_identities(
            receipt,
            target_id=target_id,
        )
        if receipt["external_authority_verdict"] not in {
            "NODATA",
            "VALID",
            "INVALID",
            "REVOKED",
            "EXPIRED",
            "CONFLICTED",
        }:
            raise InputRefused(
                f"review receipt external-authority verdict is unknown for {target_id}"
            )
        if receipt["conditional_capability_verdict"] not in {
            "NODATA",
            "VALID",
            "FAILED",
            "LYING",
            "NON_ATOMIC",
            "VERSION_MISMATCHED",
            "CONFLICTED",
        }:
            raise InputRefused(
                f"review receipt conditional-capability verdict is unknown for {target_id}"
            )
        if receipt["gate_admission_verdict"] not in {
            "NODATA",
            "VALID",
            "FAILED",
            "CONFLICTED",
        }:
            raise InputRefused(
                f"review receipt gate-admission verdict is unknown for {target_id}"
            )
        targets = v2_validate_compatibility_target_ids(
            receipt["compatibility_target_ids"],
            label=f"compatibility target IDs for {target_id}",
        )
        if targets and target_id not in targets:
            raise InputRefused(
                f"compatibility set does not include its target {target_id}"
            )
        if any(value not in inventory_by_id for value in targets):
            raise InputRefused(
                f"compatibility set includes an unknown target for {target_id}"
            )
        source_closure = receipt["source_closure"]
        if type(source_closure) is not dict:
            raise InputRefused(
                f"review receipt source closure is not an object for {target_id}"
            )
        v2_exact_keys(
            source_closure,
            {"required", "state"},
            label=f"review receipt source closure for {target_id}",
        )
        if (
            type(source_closure["required"]) is not bool
            or type(source_closure["state"]) is not str
            or not source_closure["state"]
        ):
            raise InputRefused(
                f"review receipt source closure scalars are invalid for {target_id}"
            )
        for root_field in (
            "compatibility_receipt_root",
            "external_authority_receipt_root",
            "conditional_capability_receipt_root",
            "gate_admission_receipt_root",
        ):
            root_value = receipt[root_field]
            if root_value and re.fullmatch(
                r"sha256-v1:[0-9a-f]{64}",
                root_value,
            ) is None:
                raise InputRefused(
                    f"review receipt {root_field} is malformed for {target_id}"
                )
        if receipt_document["source"] == "SYNTHETIC_FIXTURE":
            for gate, verdict_field, root_field in (
                (
                    "external",
                    "external_authority_verdict",
                    "external_authority_receipt_root",
                ),
                (
                    "conditional",
                    "conditional_capability_verdict",
                    "conditional_capability_receipt_root",
                ),
                (
                    "admission",
                    "gate_admission_verdict",
                    "gate_admission_receipt_root",
                ),
            ):
                if (
                    receipt[verdict_field] == "VALID"
                    and receipt[root_field]
                    != v2_fixture_gate_receipt_root(
                        gate,
                        target_root=target["target_root"],
                    )
                ):
                    raise InputRefused(
                        "synthetic fixture "
                        f"{gate} receipt root is not target-scoped for {target_id}"
                    )
        semantic_disposition = receipt["semantic_review_disposition"]
        if semantic_disposition not in V2_SEMANTIC_REVIEW_DISPOSITIONS:
            raise InputRefused(
                f"review receipt semantic disposition is unknown for {target_id}"
            )
        semantic_complete = v2_validate_semantic_dimension_receipts(
            receipt["semantic_review_dimensions"],
            target_root=receipt["target_root"],
            disposition=semantic_disposition,
            allow_empty=True,
            label=f"review receipt semantic dimensions for {target_id}",
        )
        v2_validate_source_closure_transition(
            target=target,
            receipt=receipt,
            semantic_complete=semantic_complete,
        )
        if semantic_complete:
            if (
                not str.strip(receipt["reviewer"])
                or not str.strip(receipt["reviewer_kind"])
                or not semantic_rationale
                or not semantic_falsifier
            ):
                raise InputRefused(
                    f"review receipt semantic adjudication is incomplete for {target_id}"
                )
        elif (
            semantic_rationale
            or semantic_falsifier
            or semantic_disposition
            != inventory_by_id[target_id]["semantic_review_disposition"]
        ):
            raise InputRefused(
                f"review receipt claims semantic adjudication without dimensions for {target_id}"
            )
        observed_ids.append(target_id)
    v2_assert_unique(observed_ids, label="review receipt target IDs")
    if observed_ids != sorted(observed_ids):
        raise InputRefused("review receipt rows are not in canonical target order")
    receipts_by_id = {
        dict.__getitem__(receipt, "target_id"): receipt
        for receipt in rows
    }
    _v2_validate_compatibility_receipts_exact(
        receipts_by_id,
        inventory,
    )
    return receipt_document, inventory


def v2_receipt_authority_flags(
    receipt: dict[str, Any] | None,
    *,
    target_root: str,
) -> tuple[bool, bool, bool, bool, bool, bool, bool, bool]:
    """Project declaration, gate, and fixture-binding facts from one row."""
    if not v2_is_semantic_root(target_root):
        raise EvidenceFailed("receipt authority target root is malformed")
    if receipt is None:
        return (False, False, False, False, False, False, False, False)
    if type(receipt) is not dict:
        raise EvidenceFailed("receipt authority row is not an exact object")
    fields = (
        "reviewer",
        "reviewer_kind",
        "declared_acceptance_owner",
        "external_authority_verdict",
        "external_authority_adapter",
        "external_authority_receipt_root",
        "conditional_capability_verdict",
        "conditional_capability_identity",
        "conditional_capability_receipt_root",
        "gate_admission_verdict",
        "gate_admission_receipt_root",
    )
    if any(field not in receipt for field in fields) or any(
        type(dict.__getitem__(receipt, field)) is not str
        for field in fields
    ):
        raise EvidenceFailed("receipt authority row lacks exact scalar fields")
    review_declared = bool(
        str.strip(dict.__getitem__(receipt, "reviewer"))
        and str.strip(dict.__getitem__(receipt, "reviewer_kind"))
    )
    authority_declared = bool(
        review_declared
        and str.strip(
            dict.__getitem__(receipt, "declared_acceptance_owner")
        )
    )
    external_receipt_valid = bool(
        dict.__getitem__(receipt, "external_authority_verdict") == "VALID"
        and str.strip(
            dict.__getitem__(receipt, "external_authority_adapter")
        )
        and dict.__getitem__(receipt, "external_authority_receipt_root")
    )
    conditional_receipt_valid = bool(
        dict.__getitem__(receipt, "conditional_capability_verdict")
        == "VALID"
        and str.strip(
            dict.__getitem__(receipt, "conditional_capability_identity")
        )
        and dict.__getitem__(receipt, "conditional_capability_receipt_root")
    )
    gate_receipt_valid = bool(
        dict.__getitem__(receipt, "gate_admission_verdict") == "VALID"
        and dict.__getitem__(receipt, "gate_admission_receipt_root")
    )
    external_fixture_bound = (
        dict.__getitem__(receipt, "external_authority_receipt_root")
        == v2_fixture_gate_receipt_root(
            "external",
            target_root=target_root,
        )
    )
    conditional_fixture_bound = (
        dict.__getitem__(receipt, "conditional_capability_receipt_root")
        == v2_fixture_gate_receipt_root(
            "conditional",
            target_root=target_root,
        )
    )
    gate_fixture_bound = (
        dict.__getitem__(receipt, "gate_admission_receipt_root")
        == v2_fixture_gate_receipt_root(
            "admission",
            target_root=target_root,
        )
    )
    return (
        review_declared,
        authority_declared,
        external_receipt_valid,
        conditional_receipt_valid,
        gate_receipt_valid,
        external_fixture_bound,
        conditional_fixture_bound,
        gate_fixture_bound,
    )


def v2_normalized_authority_row(
    target: Mapping[str, Any],
    decision: Mapping[str, Any],
) -> dict[str, Any]:
    """Build the closed V2_NORMALIZED_ROW_FIELDS projection for one target."""
    pair = v2_released_json_snapshot(
        {"target": target, "decision": decision},
        label="v2 normalized authority row inputs",
        error_type=EvidenceFailed,
    )
    if type(pair) is not dict:
        raise EvidenceFailed(
            "v2 normalized authority row inputs are not an exact object"
        )
    target = dict.__getitem__(pair, "target")
    decision = dict.__getitem__(pair, "decision")
    if type(target) is not dict or type(decision) is not dict:
        raise EvidenceFailed(
            "v2 normalized authority target or decision is not exact"
        )
    return v2_rooted(
        {
            "issue_id": target["id"],
            "title": target["title"],
            "issue_type": target["type"],
            "priority": target["priority"],
            "status": target["status"],
            "missing_sections": target["missing_sections"],
            "disposition": target["disposition"],
            "template_warning_state": decision[
                "template_warning_state"
            ],
            "semantic_review_disposition": decision[
                "semantic_review_disposition"
            ],
            "semantic_review_receipt_state": decision[
                "semantic_review_receipt_state"
            ],
            "semantic_review_dimensions": decision[
                "semantic_review_dimensions"
            ],
            "semantic_review_receipt_root": decision[
                "semantic_review_receipt_root"
            ],
            "reviewed_no_change_receipt_root": decision[
                "reviewed_no_change_receipt_root"
            ],
            "semantic_review_action": decision[
                "semantic_review_action"
            ],
            "semantic_review_rationale": decision[
                "semantic_review_rationale"
            ],
            "semantic_review_falsifier": decision[
                "semantic_review_falsifier"
            ],
            "coordination_assignee": decision[
                "coordination_assignee"
            ],
            "tracker_owner": target["tracker_owner"],
            "domain_candidate": decision["domain_candidates"],
            "declared_domain_owner": decision[
                "declared_domain_owner"
            ],
            "declared_acceptance_owner": decision[
                "declared_acceptance_owner"
            ],
            "implementation_owner": decision[
                "implementation_owner"
            ],
            "evidence_owner": decision["evidence_owner"],
            "terminal_consumer": decision["terminal_consumer"],
            "reviewer_provenance": decision["reviewer_provenance"],
            "source_closure": decision["source_closure"],
            "user_effect": decision["user_effect"],
            "field_roots": decision["field_roots"],
            "target_implementation_estimated_minutes": decision[
                "target_implementation_estimated_minutes"
            ],
            "target_implementation_estimate_state": decision[
                "target_implementation_estimate_state"
            ],
            "review_minutes": decision["review_minutes"],
            "generated_child_estimated_minutes": decision[
                "review_minutes"
            ],
            "external_authority_adapter_identity": decision[
                "external_authority"
            ]["adapter"],
            "external_authority_receipt_root": decision[
                "external_authority"
            ]["receipt_root"],
            "external_authority_verdict": decision[
                "external_authority"
            ]["verdict"],
            "conditional_write_capability_identity": decision[
                "conditional_write_capability"
            ]["identity"],
            "conditional_write_receipt_root": decision[
                "conditional_write_capability"
            ]["receipt_root"],
            "conditional_write_verdict": decision[
                "conditional_write_capability"
            ]["verdict"],
            "readiness": decision["readiness"],
            "remediation_route": decision["remediation_route"],
            "active_work_context": decision["active_work_context"],
            "campaign_epoch_root": target["campaign_epoch_root"],
            "lane": target["lane"],
            "movement_destination": target[
                "movement_destination"
            ],
            "no_claim": decision["no_claim"],
        }
    )


def v2_derive_authority(
    inventory: Mapping[str, Any],
    receipt_document: Mapping[str, Any],
    *,
    current_br_version: str,
    allow_mechanical_fixture: bool = False,
) -> dict[str, Any]:
    if type(current_br_version) is not str:
        raise InputRefused("current br version is not an exact string")
    current_br_version = v2_normalize_br_semver(
        current_br_version,
        label="current br version",
        error_type=InputRefused,
    )
    if type(allow_mechanical_fixture) is not bool:
        raise InputRefused(
            "mechanical fixture selector is not an exact boolean"
        )
    receipt_document, inventory = v2_validate_receipt_bindings(
        receipt_document,
        inventory,
    )
    receipts = {
        row["target_id"]: row for row in receipt_document.get("receipts", [])
    }
    decisions: list[dict[str, Any]] = []
    for target in inventory["rows"]:
        v2_validate_unreviewed_semantic_contract(
            target,
            label=f"authority inventory target {target['id']}",
        )
        receipt = receipts.get(target["id"])
        receipt_scope_root = (
            v2_review_receipt_scope_root(receipt)
            if receipt is not None
            else None
        )
        semantic_review_complete = bool(
            receipt and receipt["semantic_review_dimensions"]
        )
        semantic_review_disposition = (
            receipt["semantic_review_disposition"]
            if semantic_review_complete and receipt
            else target["semantic_review_disposition"]
        )
        semantic_review_receipt_state = (
            "ROOT_BOUND_REVIEWED"
            if semantic_review_complete
            else "UNREVIEWED"
        )
        semantic_review_receipt_root = (
            receipt_scope_root
            if semantic_review_complete and receipt
            else None
        )
        reviewed_no_change_receipt_root = (
            v2_reviewed_no_change_receipt_root(
                semantic_review_disposition,
                semantic_complete=semantic_review_complete,
                receipt=receipt,
            )
        )
        if not semantic_review_complete:
            semantic_review_action = "SEMANTIC_REVIEW_REQUIRED"
        elif semantic_review_disposition == "REMEDIATION_REQUIRED":
            semantic_review_action = "REMEDIATION_CANDIDATE"
        elif semantic_review_disposition == "BLOCKED_AUTHORITY":
            semantic_review_action = "AUTHORITY_RESOLUTION_REQUIRED"
        else:
            semantic_review_action = "RETAINED_ADJUDICATION"
        (
            review_declared,
            authority_declared,
            external_receipt_valid,
            conditional_receipt_valid,
            gate_receipt_valid,
            external_fixture_bound,
            conditional_fixture_bound,
            gate_fixture_bound,
        ) = v2_receipt_authority_flags(
            receipt,
            target_root=target["target_root"],
        )
        fixture_source = (
            allow_mechanical_fixture
            and receipt_document["source"] == "SYNTHETIC_FIXTURE"
        )
        current_tool_nodata = current_br_version == "0.2.19"
        external_verified = bool(
            fixture_source
            and external_receipt_valid
            and external_fixture_bound
        )
        conditional_verified = bool(
            fixture_source
            and not current_tool_nodata
            and conditional_receipt_valid
            and conditional_fixture_bound
        )
        gate_admitted = bool(
            fixture_source
            and not current_tool_nodata
            and gate_receipt_valid
            and gate_fixture_bound
        )
        mechanically_eligible = bool(
            fixture_source
            and not current_tool_nodata
            and external_verified
            and conditional_verified
            and gate_admitted
        )
        if mechanically_eligible:
            readiness = "MECHANICALLY_APPLY_ELIGIBLE"
        elif authority_declared or external_verified or conditional_verified:
            readiness = "DECLARED_READY"
        else:
            readiness = "REVIEW_ONLY"
        active_context = target["active_work_context"]
        if (
            not active_context["tracker_ready"]
            or target["status"] == "deferred"
        ):
            readiness = "REVIEW_ONLY"
        if (
            not active_context["tracker_ready"]
            or target["status"] == "deferred"
            or active_context["conflict"]
        ):
            route = "ANALYSIS_ONLY"
            deferred_prohibition = (
                not active_context["tracker_ready"]
                or target["status"] == "deferred"
            )
        elif mechanically_eligible:
            route = "AUTOMATED_CONDITIONAL"
            deferred_prohibition = False
        elif (
            authority_declared
            and receipt
            and receipt["manual_authorization"]
        ):
            route = "MANUAL_BR_REVIEW"
            deferred_prohibition = False
        else:
            route = "ANALYSIS_ONLY"
            deferred_prohibition = False
        decision = {
            "target_id": target["id"],
            "target_root": target["target_root"],
            "tracker_assignee": target["tracker_assignee"],
            "tracker_owner": target["tracker_owner"],
            "coordination_assignee": (
                receipt["coordination_assignee"]
                if receipt and receipt["coordination_assignee"]
                else target["tracker_assignee"]
            ),
            "domain_candidates": target["domain_candidates"],
            "declared_domain_owner": (
                receipt["declared_domain_owner"] if receipt else ""
            ),
            "declared_acceptance_owner": (
                receipt["declared_acceptance_owner"]
                if authority_declared and receipt
                else ""
            ),
            "implementation_owner": (
                receipt["implementation_owner"]
                if (
                    authority_declared
                    and receipt
                    and receipt["implementation_owner"]
                )
                else "UNRESOLVED"
            ),
            "evidence_owner": (
                receipt["evidence_owner"]
                if (
                    authority_declared
                    and receipt
                    and receipt["evidence_owner"]
                )
                else "UNRESOLVED"
            ),
            "terminal_consumer": (
                receipt["terminal_consumer"]
                if (
                    authority_declared
                    and receipt
                    and receipt["terminal_consumer"]
                )
                else "UNRESOLVED"
            ),
            "reviewer_provenance": {
                "reviewer": (
                    receipt["reviewer"]
                    if review_declared and receipt
                    else ""
                ),
                "reviewer_kind": (
                    receipt["reviewer_kind"]
                    if review_declared and receipt
                    else "NODATA"
                ),
                "receipt_root": (
                    receipt_scope_root
                    if review_declared and receipt
                    else None
                ),
                "self_report_ceiling": "DECLARED_READY",
            },
            "source_closure": (
                receipt["source_closure"]
                if receipt
                else target["source_closure"]
            ),
            "user_effect": (
                receipt["user_effect"]
                if receipt
                else target["user_effect"]
            ),
            "template_warning_state": target["template_warning_state"],
            "semantic_review_disposition": semantic_review_disposition,
            "semantic_review_receipt_state": (
                semantic_review_receipt_state
            ),
            "semantic_review_dimensions": (
                receipt["semantic_review_dimensions"]
                if semantic_review_complete and receipt
                else target["semantic_review_dimensions"]
            ),
            "semantic_review_receipt_root": (
                semantic_review_receipt_root
            ),
            "reviewed_no_change_receipt_root": (
                reviewed_no_change_receipt_root
            ),
            "semantic_review_action": semantic_review_action,
            "semantic_review_rationale": (
                receipt["semantic_review_rationale"]
                if semantic_review_complete and receipt
                else ""
            ),
            "semantic_review_falsifier": (
                receipt["semantic_review_falsifier"]
                if semantic_review_complete and receipt
                else target["disposition_falsifier"]
            ),
            "field_roots": target["field_roots"],
            "target_implementation_estimated_minutes": target[
                "target_implementation_estimated_minutes"
            ],
            "target_implementation_estimate_state": target[
                "target_implementation_estimate_state"
            ],
            "review_minutes": (
                receipt["review_minutes"]
                if receipt
                else target["review_minutes"]
            ),
            "external_authority": {
                "adapter": (
                    receipt["external_authority_adapter"] if receipt else ""
                ),
                "receipt_root": (
                    receipt["external_authority_receipt_root"] if receipt else ""
                ),
                "verdict": (
                    receipt["external_authority_verdict"] if receipt else "NODATA"
                ),
                "verified": external_verified,
                "structurally_valid": external_receipt_valid,
                "trust_registry": (
                    "FIXTURE_INDEPENDENT"
                    if external_verified
                    else "NODATA"
                ),
            },
            "conditional_write_capability": {
                "identity": (
                    receipt["conditional_capability_identity"] if receipt else ""
                ),
                "receipt_root": (
                    receipt["conditional_capability_receipt_root"]
                    if receipt
                    else ""
                ),
                "verdict": (
                    receipt["conditional_capability_verdict"]
                    if receipt
                    else "NODATA"
                ),
                "verified": conditional_verified,
                "structurally_valid": conditional_receipt_valid,
                "current_tool_verdict": (
                    "AUTOMATION_NODATA"
                    if current_tool_nodata
                    else "REQUIRES_1_3_ADMISSION"
                ),
            },
            "gate_admission": {
                "receipt_root": (
                    receipt["gate_admission_receipt_root"] if receipt else ""
                ),
                "verdict": (
                    receipt["gate_admission_verdict"] if receipt else "NODATA"
                ),
                "verified": gate_admitted,
                "structurally_valid": gate_receipt_valid,
            },
            "readiness": readiness,
            "remediation_route": route,
            "manual_authorization": {
                "declared": bool(
                    authority_declared
                    and receipt
                    and receipt["manual_authorization"]
                ),
                "source": (
                    receipt["manual_authorization_source"]
                    if (
                        authority_declared
                        and receipt
                        and receipt["manual_authorization"]
                    )
                    else ""
                ),
                "mechanical_authority": False,
                "no_cas_no_clobber_no_exactly_once": True,
            },
            "compatibility": {
                "key": (
                    receipt["compatibility_key"]
                    if receipt
                    else ""
                ),
                "target_ids": (
                    receipt["compatibility_target_ids"]
                    if receipt
                    else []
                ),
                "receipt_root": (
                    receipt["compatibility_receipt_root"]
                    if receipt
                    else ""
                ),
                "rationale": (
                    receipt["compatibility_rationale"]
                    if receipt
                    else ""
                ),
                "falsifier": (
                    receipt["compatibility_falsifier"]
                    if receipt
                    else ""
                ),
                "target_complete": bool(
                    receipt and receipt["compatibility_key"]
                ),
            },
            "active_work_context": active_context,
            "deferred_apply_prohibition": deferred_prohibition,
            "no_claim": (
                "authority and readiness are planning projections only; "
                "automated application requires root-bound external, "
                "conditional-write, and admission evidence"
            ),
        }
        if decision["readiness"] not in V2_READINESS_STATES:
            raise EvidenceFailed("v2 readiness escaped its closed state set")
        if decision["remediation_route"] not in V2_REMEDIATION_ROUTES:
            raise EvidenceFailed("v2 remediation route escaped its closed state set")
        if (
            decision["semantic_review_disposition"]
            not in V2_SEMANTIC_REVIEW_DISPOSITIONS
            or decision["semantic_review_receipt_state"]
            not in V2_SEMANTIC_REVIEW_RECEIPT_STATES
            or decision["semantic_review_action"]
            not in V2_SEMANTIC_REVIEW_ACTIONS
        ):
            raise EvidenceFailed("v2 semantic review escaped its closed state sets")
        decisions.append(v2_rooted(decision))
    decisions = sorted(decisions, key=lambda row: row["target_id"])
    target_by_id = {row["id"]: row for row in inventory["rows"]}
    normalized_rows = []
    for decision in decisions:
        target = target_by_id[decision["target_id"]]
        normalized_rows.append(
            v2_normalized_authority_row(target, decision)
        )
    for index, normalized_row in enumerate(normalized_rows):
        v2_exact_keys(
            normalized_row,
            V2_NORMALIZED_ROW_FIELDS,
            label=f"normalized authority row {index}",
        )
    readiness_counts = Counter(row["readiness"] for row in decisions)
    route_counts = Counter(row["remediation_route"] for row in decisions)
    semantic_review_state_counts = Counter(
        row["semantic_review_receipt_state"] for row in decisions
    )
    semantic_review_disposition_counts = Counter(
        row["semantic_review_disposition"] for row in decisions
    )
    semantic_review_action_counts = Counter(
        row["semantic_review_action"] for row in decisions
    )
    document = {
        "schema": V2_AUTHORITY_SCHEMA,
        "inventory_root": inventory["semantic_root"],
        "review_receipts_root": receipt_document["semantic_root"],
        "current_br_version": current_br_version,
        "current_br_conditional_write_capability": (
            "AUTOMATION_NODATA"
            if current_br_version == "0.2.19"
            else "REQUIRES_1_3_ADMISSION"
        ),
        "decisions": decisions,
        "normalized_rows": normalized_rows,
        "counts": {
            "readiness": {
                key: readiness_counts[key] for key in sorted(readiness_counts)
            },
            "routes": {
                key: route_counts[key] for key in sorted(route_counts)
            },
            "active_conflicts": sum(
                bool(row["active_work_context"]["conflict"]) for row in decisions
            ),
            "semantic_review_states": {
                key: semantic_review_state_counts[key]
                for key in sorted(semantic_review_state_counts)
            },
            "semantic_review_dispositions": {
                key: semantic_review_disposition_counts[key]
                for key in sorted(semantic_review_disposition_counts)
            },
            "semantic_review_actions": {
                key: semantic_review_action_counts[key]
                for key in sorted(semantic_review_action_counts)
            },
        },
        "no_claim": (
            "self-report, assignment, labels, and repository data cannot mint "
            "external review authority or atomic conditional-write capability"
        ),
    }
    return v2_rooted(document)


V2_AUTHORITY_REPORT_FIELDS = frozenset(
    {
        "schema",
        "inventory_root",
        "review_receipts_root",
        "current_br_version",
        "current_br_conditional_write_capability",
        "decisions",
        "normalized_rows",
        "counts",
        "no_claim",
        "semantic_root",
    }
)
V2_AUTHORITY_DECISION_FIELDS = frozenset(
    {
        "target_id",
        "target_root",
        "tracker_assignee",
        "tracker_owner",
        "coordination_assignee",
        "domain_candidates",
        "declared_domain_owner",
        "declared_acceptance_owner",
        "implementation_owner",
        "evidence_owner",
        "terminal_consumer",
        "reviewer_provenance",
        "source_closure",
        "user_effect",
        "template_warning_state",
        "semantic_review_disposition",
        "semantic_review_receipt_state",
        "semantic_review_dimensions",
        "semantic_review_receipt_root",
        "reviewed_no_change_receipt_root",
        "semantic_review_action",
        "semantic_review_rationale",
        "semantic_review_falsifier",
        "field_roots",
        "target_implementation_estimated_minutes",
        "target_implementation_estimate_state",
        "review_minutes",
        "external_authority",
        "conditional_write_capability",
        "gate_admission",
        "readiness",
        "remediation_route",
        "manual_authorization",
        "compatibility",
        "active_work_context",
        "deferred_apply_prohibition",
        "no_claim",
        "semantic_root",
    }
)
V2_AUTHORITY_EXTERNAL_FIELDS = frozenset(
    {
        "adapter",
        "receipt_root",
        "verdict",
        "verified",
        "structurally_valid",
        "trust_registry",
    }
)
V2_AUTHORITY_CONDITIONAL_FIELDS = frozenset(
    {
        "identity",
        "receipt_root",
        "verdict",
        "verified",
        "structurally_valid",
        "current_tool_verdict",
    }
)
V2_AUTHORITY_GATE_FIELDS = frozenset(
    {"receipt_root", "verdict", "verified", "structurally_valid"}
)
V2_AUTHORITY_MANUAL_FIELDS = frozenset(
    {
        "declared",
        "source",
        "mechanical_authority",
        "no_cas_no_clobber_no_exactly_once",
    }
)
V2_AUTHORITY_COMPATIBILITY_FIELDS = frozenset(
    {
        "key",
        "target_ids",
        "receipt_root",
        "rationale",
        "falsifier",
        "target_complete",
    }
)
V2_AUTHORITY_COUNT_FIELDS = frozenset(
    {
        "readiness",
        "routes",
        "active_conflicts",
        "semantic_review_states",
        "semantic_review_dispositions",
        "semantic_review_actions",
    }
)
V2_AUTHORITY_NO_CLAIM = (
    "self-report, assignment, labels, and repository data cannot mint "
    "external review authority or atomic conditional-write capability"
)
V2_AUTHORITY_DECISION_NO_CLAIM = (
    "authority and readiness are planning projections only; automated "
    "application requires root-bound external, conditional-write, and "
    "admission evidence"
)


def _v2_validate_review_plan_authority_exact(
    authority: Any,
    inventory: Mapping[str, Any],
) -> dict[str, Any]:
    authority = v2_released_json_snapshot(
        authority,
        label="v2 review-plan authority",
        error_type=EvidenceFailed,
    )
    if type(authority) is not dict or type(inventory) is not dict:
        raise EvidenceFailed(
            "v2 review-plan authority validation inputs are malformed"
        )
    if frozenset(dict.__iter__(authority)) != V2_AUTHORITY_REPORT_FIELDS:
        raise EvidenceFailed("v2 review-plan authority schema is not closed")
    verify_semantic_root(authority, label="v2 review-plan authority")
    if (
        authority["schema"] != V2_AUTHORITY_SCHEMA
        or authority["inventory_root"] != inventory["semantic_root"]
        or not v2_is_semantic_root(authority["review_receipts_root"])
        or authority["no_claim"] != V2_AUTHORITY_NO_CLAIM
    ):
        raise EvidenceFailed(
            "v2 review-plan authority identity or provenance differs"
        )
    current_version = authority["current_br_version"]
    if type(current_version) is not str:
        raise EvidenceFailed(
            "v2 review-plan authority version is not an exact string"
        )
    normalized_version = v2_normalize_br_semver(
        current_version,
        label="v2 review-plan authority version",
        error_type=EvidenceFailed,
    )
    expected_capability = (
        "AUTOMATION_NODATA"
        if normalized_version == "0.2.19"
        else "REQUIRES_1_3_ADMISSION"
    )
    if (
        normalized_version != current_version
        or authority["current_br_conditional_write_capability"]
        != expected_capability
    ):
        raise EvidenceFailed(
            "v2 review-plan authority tool capability differs"
        )
    decisions = authority["decisions"]
    normalized_rows = authority["normalized_rows"]
    if (
        type(decisions) is not list
        or type(normalized_rows) is not list
        or len(decisions) > V2_INVENTORY_ROWS_CAP
        or len(normalized_rows) != len(decisions)
        or any(type(row) is not dict for row in decisions)
        or any(type(row) is not dict for row in normalized_rows)
    ):
        raise EvidenceFailed(
            "v2 review-plan authority row collections are malformed"
        )
    inventory_rows = inventory.get("rows")
    if type(inventory_rows) is not list:
        raise EvidenceFailed(
            "v2 review-plan authority inventory rows are malformed"
        )
    target_by_id = {row["id"]: row for row in inventory_rows}
    decision_ids: list[str] = []
    for index, decision in enumerate(decisions):
        if frozenset(dict.__iter__(decision)) != V2_AUTHORITY_DECISION_FIELDS:
            raise EvidenceFailed(
                f"v2 review-plan authority decision {index} schema is not closed"
            )
        verify_semantic_root(
            decision,
            label=f"v2 review-plan authority decision {index}",
        )
        target_id = decision["target_id"]
        v2_validate_issue_id(
            target_id,
            label=f"v2 review-plan authority decision {index} target ID",
            error_type=EvidenceFailed,
        )
        decision_ids.append(target_id)
        target = dict.get(target_by_id, target_id)
        if type(target) is not dict:
            raise EvidenceFailed(
                "v2 review-plan authority decision is outside inventory"
            )
        if (
            decision["target_root"] != target["target_root"]
            or decision["tracker_assignee"]
            != target["tracker_assignee"]
            or decision["tracker_owner"] != target["tracker_owner"]
            or decision["domain_candidates"]
            != target["domain_candidates"]
            or decision["field_roots"] != target["field_roots"]
            or decision["template_warning_state"]
            != target["template_warning_state"]
            or decision["target_implementation_estimated_minutes"]
            != target["target_implementation_estimated_minutes"]
            or decision["target_implementation_estimate_state"]
            != target["target_implementation_estimate_state"]
            or decision["active_work_context"]
            != target["active_work_context"]
            or type(decision["readiness"]) is not str
            or decision["readiness"] not in V2_READINESS_STATES
            or type(decision["remediation_route"]) is not str
            or decision["remediation_route"] not in V2_REMEDIATION_ROUTES
            or type(decision["semantic_review_disposition"]) is not str
            or decision["semantic_review_disposition"]
            not in V2_SEMANTIC_REVIEW_DISPOSITIONS
            or type(decision["semantic_review_receipt_state"]) is not str
            or decision["semantic_review_receipt_state"]
            not in V2_SEMANTIC_REVIEW_RECEIPT_STATES
            or type(decision["semantic_review_action"]) is not str
            or decision["semantic_review_action"]
            not in V2_SEMANTIC_REVIEW_ACTIONS
            or type(decision["deferred_apply_prohibition"]) is not bool
            or decision["no_claim"] != V2_AUTHORITY_DECISION_NO_CLAIM
        ):
            raise EvidenceFailed(
                "v2 review-plan authority decision differs from its target"
            )
        for field, allow_empty, allow_unresolved in (
            ("coordination_assignee", True, False),
            ("declared_domain_owner", True, False),
            ("declared_acceptance_owner", True, False),
            ("implementation_owner", False, True),
            ("evidence_owner", False, True),
            ("terminal_consumer", False, True),
        ):
            v2_validate_authority_identity_text(
                decision[field],
                target_id=target_id,
                field_name=field,
                allow_empty=allow_empty,
                allow_unresolved=allow_unresolved,
                error_type=EvidenceFailed,
            )
        for field, allow_empty in (
            ("semantic_review_rationale", True),
            ("semantic_review_falsifier", False),
            ("user_effect", False),
        ):
            v2_validate_canonical_semantic_text(
                decision[field],
                label=(
                    f"v2 review-plan authority decision {index} {field}"
                ),
                allow_empty=allow_empty,
                error_type=EvidenceFailed,
            )
        for nested_field, expected_fields in (
            ("external_authority", V2_AUTHORITY_EXTERNAL_FIELDS),
            (
                "conditional_write_capability",
                V2_AUTHORITY_CONDITIONAL_FIELDS,
            ),
            ("gate_admission", V2_AUTHORITY_GATE_FIELDS),
            ("manual_authorization", V2_AUTHORITY_MANUAL_FIELDS),
            ("compatibility", V2_AUTHORITY_COMPATIBILITY_FIELDS),
        ):
            nested = decision[nested_field]
            if (
                type(nested) is not dict
                or frozenset(dict.__iter__(nested)) != expected_fields
            ):
                raise EvidenceFailed(
                    "v2 review-plan authority decision nested schema differs"
                )
        external = decision["external_authority"]
        conditional = decision["conditional_write_capability"]
        gate = decision["gate_admission"]
        manual = decision["manual_authorization"]
        compatibility = decision["compatibility"]
        if (
            any(
                type(external[field]) is not str
                for field in (
                    "adapter",
                    "receipt_root",
                    "verdict",
                    "trust_registry",
                )
            )
            or any(
                type(external[field]) is not bool
                for field in ("verified", "structurally_valid")
            )
            or external["verdict"]
            not in {
                "NODATA",
                "VALID",
                "INVALID",
                "REVOKED",
                "EXPIRED",
                "CONFLICTED",
            }
            or any(
                type(conditional[field]) is not str
                for field in (
                    "identity",
                    "receipt_root",
                    "verdict",
                    "current_tool_verdict",
                )
            )
            or any(
                type(conditional[field]) is not bool
                for field in ("verified", "structurally_valid")
            )
            or conditional["verdict"]
            not in {
                "NODATA",
                "VALID",
                "FAILED",
                "LYING",
                "NON_ATOMIC",
                "VERSION_MISMATCHED",
                "CONFLICTED",
            }
            or any(
                type(gate[field]) is not str
                for field in ("receipt_root", "verdict")
            )
            or any(
                type(gate[field]) is not bool
                for field in ("verified", "structurally_valid")
            )
            or gate["verdict"]
            not in {"NODATA", "VALID", "FAILED", "CONFLICTED"}
        ):
            raise EvidenceFailed(
                "v2 review-plan authority gate scalars are malformed"
            )
        for field_name, value in (
            ("external_authority.adapter", external["adapter"]),
            (
                "conditional_write_capability.identity",
                conditional["identity"],
            ),
            ("manual_authorization.source", manual["source"]),
        ):
            v2_validate_authority_identity_text(
                value,
                target_id=target_id,
                field_name=field_name,
                allow_empty=True,
                allow_unresolved=False,
                error_type=EvidenceFailed,
            )
        if (
            external["verdict"] == "NODATA"
            and (external["adapter"] or external["receipt_root"])
        ) or (
            conditional["verdict"] == "NODATA"
            and (conditional["identity"] or conditional["receipt_root"])
        ) or (
            gate["verdict"] == "NODATA" and gate["receipt_root"]
        ):
            raise EvidenceFailed(
                "v2 review-plan authority NODATA gate retains contradictory "
                "evidence"
            )
        expected_external_structural = bool(
            external["verdict"] == "VALID"
            and str.strip(external["adapter"])
            and external["receipt_root"]
        )
        expected_conditional_structural = bool(
            conditional["verdict"] == "VALID"
            and str.strip(conditional["identity"])
            and conditional["receipt_root"]
        )
        expected_gate_structural = bool(
            gate["verdict"] == "VALID" and gate["receipt_root"]
        )
        for root_value in (
            external["receipt_root"],
            conditional["receipt_root"],
            gate["receipt_root"],
        ):
            if root_value and not v2_is_semantic_root(root_value):
                raise EvidenceFailed(
                    "v2 review-plan authority gate receipt root is malformed"
                )
        if (
            external["structurally_valid"]
            is not expected_external_structural
            or conditional["structurally_valid"]
            is not expected_conditional_structural
            or gate["structurally_valid"] is not expected_gate_structural
            or (
                external["verdict"] == "VALID"
                and not expected_external_structural
            )
            or (
                conditional["verdict"] == "VALID"
                and not expected_conditional_structural
            )
            or (
                gate["verdict"] == "VALID"
                and not expected_gate_structural
            )
            or conditional["current_tool_verdict"] != expected_capability
            or (
                external["verified"]
                and (
                    not expected_external_structural
                    or external["receipt_root"]
                    != v2_fixture_gate_receipt_root(
                        "external",
                        target_root=target["target_root"],
                    )
                )
            )
            or (
                conditional["verified"]
                and (
                    normalized_version == "0.2.19"
                    or not expected_conditional_structural
                    or conditional["receipt_root"]
                    != v2_fixture_gate_receipt_root(
                        "conditional",
                        target_root=target["target_root"],
                    )
                )
            )
            or (
                gate["verified"]
                and (
                    normalized_version == "0.2.19"
                    or not expected_gate_structural
                    or gate["receipt_root"]
                    != v2_fixture_gate_receipt_root(
                        "admission",
                        target_root=target["target_root"],
                    )
                )
            )
            or external["trust_registry"]
            != (
                "FIXTURE_INDEPENDENT"
                if external["verified"]
                else "NODATA"
            )
        ):
            raise EvidenceFailed(
                "v2 review-plan authority gate evidence is incoherent"
            )
        if (
            type(manual["declared"]) is not bool
            or type(manual["source"]) is not str
            or manual["mechanical_authority"] is not False
            or manual["no_cas_no_clobber_no_exactly_once"] is not True
            or bool(manual["source"]) is not manual["declared"]
            or type(compatibility["key"]) is not str
            or type(compatibility["target_ids"]) is not list
            or type(compatibility["receipt_root"]) is not str
            or type(compatibility["rationale"]) is not str
            or type(compatibility["falsifier"]) is not str
            or type(compatibility["target_complete"]) is not bool
            or compatibility["target_complete"]
            is not bool(compatibility["key"])
        ):
            raise EvidenceFailed(
                "v2 review-plan authority manual or compatibility state differs"
            )
        compatibility_ids = v2_validate_compatibility_target_ids(
            compatibility["target_ids"],
            label=(
                "v2 review-plan authority decision "
                f"{index} compatibility target IDs"
            ),
        )
        if compatibility["key"]:
            if (
                target_id not in compatibility_ids
                or any(value not in target_by_id for value in compatibility_ids)
                or not v2_is_semantic_root(compatibility["receipt_root"])
                or not compatibility["rationale"]
                or not compatibility["falsifier"]
            ):
                raise EvidenceFailed(
                    "v2 review-plan authority compatibility evidence differs"
                )
        elif (
            compatibility_ids
            or compatibility["receipt_root"]
            or compatibility["rationale"]
            or compatibility["falsifier"]
        ):
            raise EvidenceFailed(
                "v2 review-plan authority empty compatibility is not exact"
            )
        semantic_complete = (
            decision["semantic_review_receipt_state"]
            == "ROOT_BOUND_REVIEWED"
        )
        if semantic_complete:
            v2_validate_semantic_dimension_receipts(
                decision["semantic_review_dimensions"],
                target_root=target["target_root"],
                disposition=decision["semantic_review_disposition"],
                allow_empty=False,
                label=f"v2 review-plan authority decision {index}",
            )
        elif (
            decision["semantic_review_receipt_state"] != "UNREVIEWED"
            or decision["semantic_review_dimensions"]
            != v2_unreviewed_semantic_dimensions()
            or decision["semantic_review_disposition"]
            != target["semantic_review_disposition"]
            or decision["semantic_review_receipt_root"] is not None
            or decision["reviewed_no_change_receipt_root"] is not None
            or decision["semantic_review_rationale"]
            or decision["semantic_review_falsifier"]
            != target["disposition_falsifier"]
        ):
            raise EvidenceFailed(
                "v2 review-plan authority unreviewed semantic state differs"
            )
        expected_semantic_action = (
            "SEMANTIC_REVIEW_REQUIRED"
            if not semantic_complete
            else (
                "REMEDIATION_CANDIDATE"
                if decision["semantic_review_disposition"]
                == "REMEDIATION_REQUIRED"
                else (
                    "AUTHORITY_RESOLUTION_REQUIRED"
                    if decision["semantic_review_disposition"]
                    == "BLOCKED_AUTHORITY"
                    else "RETAINED_ADJUDICATION"
                )
            )
        )
        expected_reviewed_no_change_root = (
            decision["semantic_review_receipt_root"]
            if (
                semantic_complete
                and decision["semantic_review_disposition"]
                == "REVIEWED_NO_CHANGE"
            )
            else None
        )
        if (
            decision["semantic_review_action"]
            != expected_semantic_action
            or decision["reviewed_no_change_receipt_root"]
            != expected_reviewed_no_change_root
            or (
                semantic_complete
                and (
                    not v2_is_semantic_root(
                        decision["semantic_review_receipt_root"]
                    )
                    or not str.strip(
                        decision["semantic_review_rationale"]
                    )
                    or not str.strip(
                        decision["semantic_review_falsifier"]
                    )
                )
            )
        ):
            raise EvidenceFailed(
                "v2 review-plan authority semantic review state differs"
            )
        v2_validate_source_closure_transition(
            target=target,
            receipt=decision,
            semantic_complete=semantic_complete,
        )
        reviewer = decision["reviewer_provenance"]
        if (
            type(reviewer) is not dict
            or frozenset(dict.__iter__(reviewer))
            != {
                "reviewer",
                "reviewer_kind",
                "receipt_root",
                "self_report_ceiling",
            }
            or type(reviewer["reviewer"]) is not str
            or type(reviewer["reviewer_kind"]) is not str
            or reviewer["self_report_ceiling"] != "DECLARED_READY"
        ):
            raise EvidenceFailed(
                "v2 review-plan authority reviewer provenance differs"
            )
        if not (
            reviewer["reviewer"] == ""
            and reviewer["reviewer_kind"] == "NODATA"
        ):
            for field_name in ("reviewer", "reviewer_kind"):
                v2_validate_authority_identity_text(
                    reviewer[field_name],
                    target_id=target_id,
                    field_name=f"reviewer_provenance.{field_name}",
                    allow_empty=False,
                    allow_unresolved=False,
                    error_type=EvidenceFailed,
                )
        review_declared = bool(
            str.strip(reviewer["reviewer"])
            and str.strip(reviewer["reviewer_kind"])
        )
        if (
            review_declared
            is not v2_is_semantic_root(reviewer["receipt_root"])
            or (
                not review_declared
                and (
                    reviewer["reviewer"]
                    or reviewer["reviewer_kind"] != "NODATA"
                    or reviewer["receipt_root"] is not None
                )
            )
        ):
            raise EvidenceFailed(
                "v2 review-plan authority reviewer receipt differs"
            )
        if (
            type(decision["review_minutes"]) is not int
            or decision["review_minutes"] < 0
            or int.bit_length(decision["review_minutes"])
            > V2_EXACT_JSON_INTEGER_BITS_CAP
            or type(decision["user_effect"]) is not str
            or not str.strip(decision["user_effect"])
        ):
            raise EvidenceFailed(
                "v2 review-plan authority work or user effect differs"
            )
        mechanically_eligible = bool(
            external["verified"]
            and conditional["verified"]
            and gate["verified"]
        )
        authority_declared = bool(
            review_declared and decision["declared_acceptance_owner"]
        )
        if (
            bool(decision["declared_acceptance_owner"])
            is not authority_declared
            or (
                not authority_declared
                and (
                    decision["implementation_owner"] != "UNRESOLVED"
                    or decision["evidence_owner"] != "UNRESOLVED"
                    or decision["terminal_consumer"] != "UNRESOLVED"
                )
            )
            or (
                semantic_complete
                and reviewer["receipt_root"]
                != decision["semantic_review_receipt_root"]
            )
        ):
            raise EvidenceFailed(
                "v2 review-plan authority responsibility or review provenance "
                "differs"
            )
        expected_readiness = (
            "MECHANICALLY_APPLY_ELIGIBLE"
            if mechanically_eligible
            else (
                "DECLARED_READY"
                if (
                    authority_declared
                    or external["verified"]
                    or conditional["verified"]
                )
                else "REVIEW_ONLY"
            )
        )
        active_context = decision["active_work_context"]
        if (
            not active_context["tracker_ready"]
            or target["status"] == "deferred"
        ):
            expected_readiness = "REVIEW_ONLY"
        if (
            not active_context["tracker_ready"]
            or target["status"] == "deferred"
            or active_context["conflict"]
        ):
            expected_route = "ANALYSIS_ONLY"
            expected_deferred_prohibition = bool(
                not active_context["tracker_ready"]
                or target["status"] == "deferred"
            )
        elif mechanically_eligible:
            expected_route = "AUTOMATED_CONDITIONAL"
            expected_deferred_prohibition = False
        elif authority_declared and manual["declared"]:
            expected_route = "MANUAL_BR_REVIEW"
            expected_deferred_prohibition = False
        else:
            expected_route = "ANALYSIS_ONLY"
            expected_deferred_prohibition = False
        if (
            (manual["declared"] and not authority_declared)
            or decision["readiness"] != expected_readiness
            or decision["remediation_route"] != expected_route
            or decision["deferred_apply_prohibition"]
            is not expected_deferred_prohibition
        ):
            raise EvidenceFailed(
                "v2 review-plan authority readiness or route differs"
            )
        normalized_row = normalized_rows[index]
        if (
            frozenset(dict.__iter__(normalized_row))
            != V2_NORMALIZED_ROW_FIELDS
        ):
            raise EvidenceFailed(
                f"v2 normalized authority row {index} schema is not closed"
            )
        verify_semantic_root(
            normalized_row,
            label=f"v2 normalized authority row {index}",
        )
        if normalized_row != v2_normalized_authority_row(target, decision):
            raise EvidenceFailed(
                "v2 normalized authority row differs from its canonical "
                "closed projection"
            )
    if (
        decision_ids != sorted(decision_ids)
        or len(decision_ids) != len(set(decision_ids))
        or set(decision_ids) != set(target_by_id)
    ):
        raise EvidenceFailed(
            "v2 review-plan authority decision membership is noncanonical"
        )
    compatibility_receipts = {
        decision["target_id"]: {
            "target_id": decision["target_id"],
            "compatibility_key": decision["compatibility"]["key"],
            "compatibility_receipt_root": decision["compatibility"][
                "receipt_root"
            ],
            "compatibility_rationale": decision["compatibility"][
                "rationale"
            ],
            "compatibility_falsifier": decision["compatibility"][
                "falsifier"
            ],
            "compatibility_target_ids": decision["compatibility"][
                "target_ids"
            ],
            "coordination_assignee": decision[
                "coordination_assignee"
            ],
            "declared_domain_owner": decision[
                "declared_domain_owner"
            ],
            "user_effect": decision["user_effect"],
            "reviewer": decision["reviewer_provenance"]["reviewer"],
            "reviewer_kind": decision["reviewer_provenance"][
                "reviewer_kind"
            ],
        }
        for decision in decisions
    }
    _v2_validate_compatibility_receipts_exact(
        compatibility_receipts,
        inventory,
    )
    receipt_provenance_root = authority["review_receipts_root"]
    foreign_identity_roots = {
        inventory["semantic_root"],
        inventory["v1_inventory_root"],
        inventory["campaign_epoch_root"],
        inventory["nonclosed_ids_root"],
        inventory["history_ids_root"],
        authority["semantic_root"],
        *(row["semantic_root"] for row in inventory_rows),
        *(row["target_root"] for row in inventory_rows),
        *(row["source_issue_projection_root"] for row in inventory_rows),
        *(row["v1_row_root"] for row in inventory_rows),
        *(row["dependency_neighborhood_root"] for row in inventory_rows),
        *(
            root
            for row in inventory_rows
            for _field, root in dict.items(row["field_roots"])
        ),
        *(
            row["clause_roots"][field]
            for row in inventory_rows
            for field in (
                "membership_root",
                "over_row_cap_membership_root",
                "over_byte_cap_membership_root",
            )
        ),
        *(
            clause["text_root"]
            for row in inventory_rows
            for clause in row["clause_roots"]["rows"]
        ),
        *(
            candidate["provenance_root"]
            for row in inventory_rows
            for candidate in row["domain_candidates"]
        ),
        *(row["semantic_root"] for row in decisions),
        *(row["semantic_root"] for row in normalized_rows),
        *(
            root_value
            for decision in decisions
            for root_value in (
                decision["semantic_review_receipt_root"],
                decision["reviewed_no_change_receipt_root"],
                decision["reviewer_provenance"]["receipt_root"],
                decision["external_authority"]["receipt_root"],
                decision["conditional_write_capability"]["receipt_root"],
                decision["gate_admission"]["receipt_root"],
                decision["compatibility"]["receipt_root"],
                *(
                    root
                    for _field, root in dict.items(
                        decision["field_roots"]
                    )
                ),
                *(
                    dimension["evidence_root"]
                    for dimension in decision[
                        "semantic_review_dimensions"
                    ]
                ),
            )
            if v2_is_semantic_root(root_value)
        ),
    }
    if receipt_provenance_root in foreign_identity_roots:
        raise EvidenceFailed(
            "v2 review-plan authority receipt provenance aliases another "
            "identity kind"
        )
    counts = authority["counts"]
    if (
        type(counts) is not dict
        or frozenset(dict.__iter__(counts)) != V2_AUTHORITY_COUNT_FIELDS
    ):
        raise EvidenceFailed("v2 review-plan authority counts are malformed")
    readiness_counts = Counter(row["readiness"] for row in decisions)
    route_counts = Counter(row["remediation_route"] for row in decisions)
    semantic_state_counts = Counter(
        row["semantic_review_receipt_state"] for row in decisions
    )
    semantic_disposition_counts = Counter(
        row["semantic_review_disposition"] for row in decisions
    )
    semantic_action_counts = Counter(
        row["semantic_review_action"] for row in decisions
    )
    expected_counts = {
        "readiness": {
            key: readiness_counts[key] for key in sorted(readiness_counts)
        },
        "routes": {
            key: route_counts[key] for key in sorted(route_counts)
        },
        "active_conflicts": sum(
            row["active_work_context"]["conflict"] is True
            for row in decisions
        ),
        "semantic_review_states": {
            key: semantic_state_counts[key]
            for key in sorted(semantic_state_counts)
        },
        "semantic_review_dispositions": {
            key: semantic_disposition_counts[key]
            for key in sorted(semantic_disposition_counts)
        },
        "semantic_review_actions": {
            key: semantic_action_counts[key]
            for key in sorted(semantic_action_counts)
        },
    }
    if counts != expected_counts:
        raise EvidenceFailed("v2 review-plan authority counts differ")
    return authority


def v2_validate_review_plan_authority(
    authority: Any,
    inventory: Any,
) -> dict[str, Any]:
    try:
        exact_inventory = v2_validate_review_inventory(inventory)
    except HarnessError as error:
        raise EvidenceFailed(
            "v2 review-plan authority inventory is invalid"
        ) from error
    try:
        return _v2_validate_review_plan_authority_exact(
            authority,
            exact_inventory,
        )
    except EvidenceFailed:
        raise
    except HarnessError as error:
        raise EvidenceFailed(
            "v2 review-plan authority nested contract is invalid"
        ) from error


def v2_validate_review_plan_receipt_provenance(
    authority: Mapping[str, Any],
    inventory: Mapping[str, Any],
    *,
    review_receipts: Any | None,
    allow_mechanical_fixture: bool,
) -> None:
    if type(authority) is not dict or type(inventory) is not dict:
        raise EvidenceFailed(
            "v2 review-plan receipt provenance inputs are not exact objects"
        )
    if type(allow_mechanical_fixture) is not bool:
        raise EvidenceFailed(
            "v2 review-plan mechanical-fixture selector is not exact"
        )
    decisions = authority["decisions"]
    if type(decisions) is not list:
        raise EvidenceFailed(
            "v2 review-plan receipt provenance lacks decisions"
        )
    mechanical_claim_present = any(
        decision["external_authority"]["verified"]
        or decision["conditional_write_capability"]["verified"]
        or decision["gate_admission"]["verified"]
        or decision["readiness"] == "MECHANICALLY_APPLY_ELIGIBLE"
        or decision["remediation_route"] == "AUTOMATED_CONDITIONAL"
        for decision in decisions
    )
    receipt_claim_present = any(
        decision["semantic_review_receipt_state"]
        == "ROOT_BOUND_REVIEWED"
        or bool(decision["reviewer_provenance"]["reviewer"])
        or decision["manual_authorization"]["declared"]
        or bool(decision["compatibility"]["key"])
        or decision["external_authority"]["verdict"] != "NODATA"
        or decision["conditional_write_capability"]["verdict"]
        != "NODATA"
        or decision["gate_admission"]["verdict"] != "NODATA"
        for decision in decisions
    )
    if review_receipts is None:
        if receipt_claim_present or mechanical_claim_present:
            raise EvidenceFailed(
                "v2 review-plan receipt-derived authority lacks its admitted "
                "receipt document"
            )
        derived_empty_receipts = v2_empty_review_receipts(
            inventory_root=inventory["semantic_root"],
            campaign_epoch_root=inventory["campaign_epoch_root"],
        )
        empty_receipts = v2_released_json_snapshot(
            derived_empty_receipts,
            label="v2 canonical empty review receipts",
            error_type=EvidenceFailed,
        )
        if type(empty_receipts) is not dict:
            raise EvidenceFailed(
                "v2 canonical empty review receipts are not an exact object"
            )
        if authority["review_receipts_root"] != empty_receipts["semantic_root"]:
            raise EvidenceFailed(
                "v2 review-plan claim-free authority is not bound to the "
                "canonical empty receipt document"
            )
        review_receipts = empty_receipts
    if mechanical_claim_present and not allow_mechanical_fixture:
        raise EvidenceFailed(
            "v2 review-plan mechanical authority lacks its explicit fixture "
            "boundary"
        )
    derived_authority = v2_derive_authority(
        inventory,
        review_receipts,
        current_br_version=authority["current_br_version"],
        allow_mechanical_fixture=allow_mechanical_fixture,
    )
    expected_authority = v2_released_json_snapshot(
        derived_authority,
        label="v2 receipt-derived expected authority",
        error_type=EvidenceFailed,
    )
    if type(expected_authority) is not dict:
        raise EvidenceFailed(
            "v2 receipt-derived expected authority is not an exact object"
        )
    if authority != expected_authority:
        raise EvidenceFailed(
            "v2 review-plan receipt-derived authority differs from its admitted "
            "receipt derivation"
        )


def v2_lane_parent(priority: int) -> str:
    return {
        0: "frankensim-semantic-bead-template-hygiene-961yr.2",
        1: "frankensim-semantic-bead-template-hygiene-961yr.3",
        2: "frankensim-semantic-bead-template-hygiene-961yr.4.1",
        3: "frankensim-semantic-bead-template-hygiene-961yr.4.2",
        4: "frankensim-semantic-bead-template-hygiene-961yr.4.3",
    }[priority]


def v2_hard_vector(
    target: Mapping[str, Any], authority: Mapping[str, Any]
) -> tuple[Any, ...]:
    target_type = str(target["type"])
    raw_missing_sections = target["missing_sections"]
    if type(raw_missing_sections) is not list:
        raise EvidenceFailed(
            "hard-vector missing sections are not an exact list"
        )
    missing_sections = v2_canonical_missing_sections(
        target_type,
        tuple(raw_missing_sections),
    )
    return (
        int(target["priority"]),
        str(target["status"]),
        str(target["disposition"]),
        target_type,
        missing_sections,
        str(authority["semantic_review_disposition"]),
        str(authority["semantic_review_receipt_state"]),
        str(authority["semantic_review_action"]),
        str(authority["readiness"]),
        str(authority["remediation_route"]),
        str(
            authority["active_work_context"][
                "generated_child_desired_status"
            ]
        ),
    )


def v2_packing_group_key(
    target: Mapping[str, Any],
    authority: Mapping[str, Any],
) -> tuple[Any, ...]:
    compatibility_key = str(authority["compatibility"]["key"] or "")
    grouping_identity = compatibility_key or f"singleton:{target['id']}"
    return (
        *v2_hard_vector(target, authority),
        grouping_identity,
    )


def v2_packing_input_bindings(
    rows: Sequence[tuple[Mapping[str, Any], Mapping[str, Any]]],
) -> tuple[str, str]:
    # Bind only a complete, unique, target-authority-coherent group.  Set and
    # dict projections below are intentionally downstream of this lossless
    # admission boundary so duplicate or mismatched rows cannot be collapsed
    # into apparently valid packing roots.
    v2_packing_group_row_identity(rows)
    group_keys = {
        v2_packing_group_key(target, authority)
        for target, authority in rows
    }
    if len(group_keys) != 1:
        raise EvidenceFailed(
            "packing input crosses a hard or compatibility group"
        )
    load_rows = [
        {
            "target_id": target["id"],
            "target_root": target["target_root"],
            "authority_decision_root": authority["semantic_root"],
            "review_minutes": authority["review_minutes"],
            "retained_payload_bytes": target["retained_payload_bytes"],
        }
        for target, authority in sorted(
            rows,
            key=lambda pair: pair[0]["id"],
        )
    ]
    return (
        semantic_root({"group_key": next(iter(group_keys))}),
        semantic_root(load_rows),
    )


def v2_load_tuple(target: Mapping[str, Any], authority: Mapping[str, Any]) -> tuple[int, int, int]:
    return (
        int(authority["review_minutes"]),
        int(target["retained_payload_bytes"]),
        1,
    )


def v2_bin_load(
    rows: Sequence[tuple[Mapping[str, Any], Mapping[str, Any]]]
) -> tuple[int, int, int]:
    return (
        sum(int(authority["review_minutes"]) for _, authority in rows),
        sum(int(target["retained_payload_bytes"]) for target, _ in rows),
        len(rows),
    )


def v2_bin_feasible(
    rows: Sequence[tuple[Mapping[str, Any], Mapping[str, Any]]],
    *,
    max_targets: int,
) -> bool:
    minutes, retained_bytes, targets = v2_bin_load(rows)
    return (
        targets <= max_targets
        and minutes <= V2_REVIEW_MINUTES_CAP
        and retained_bytes <= V2_CHILD_PAYLOAD_CAP
        and not v2_child_transport_violations(rows)
    )


def v2_partition_objective(
    bins: Sequence[Sequence[tuple[Mapping[str, Any], Mapping[str, Any]]]],
) -> tuple[Any, ...]:
    loads = [v2_bin_load(rows) for rows in bins]
    memberships = tuple(
        sorted(tuple(sorted(target["id"] for target, _ in rows)) for rows in bins)
    )
    descending_loads = tuple(sorted(loads, reverse=True))
    return (
        len(bins),
        max((load[0] for load in loads), default=0),
        max((load[1] for load in loads), default=0),
        max((load[2] for load in loads), default=0),
        descending_loads,
        memberships,
    )


def v2_objective_document(
    bins: Sequence[Sequence[tuple[Mapping[str, Any], Mapping[str, Any]]]],
) -> dict[str, Any]:
    objective = v2_partition_objective(bins)
    return {
        "child_count": objective[0],
        "maximum_review_minutes": objective[1],
        "maximum_retained_payload_bytes": objective[2],
        "maximum_target_count": objective[3],
        "descending_load_vectors": [
            list(load) for load in objective[4]
        ],
        "lexicographic_memberships": [
            list(membership) for membership in objective[5]
        ],
    }


def v2_exact_partition(
    rows: Sequence[tuple[Mapping[str, Any], Mapping[str, Any]]],
    *,
    max_targets: int,
) -> list[list[tuple[Mapping[str, Any], Mapping[str, Any]]]]:
    ordered = sorted(rows, key=lambda pair: pair[0]["id"])
    count = len(ordered)
    if count > V2_EXACT_OPTIMALITY_MAX_TARGETS:
        raise EvidenceFailed("exact partition called above its frozen target cutoff")
    feasible_masks: dict[int, tuple[int, ...]] = {}
    for mask in range(1, 1 << count):
        selected = [ordered[index] for index in range(count) if mask & (1 << index)]
        if v2_bin_feasible(selected, max_targets=max_targets):
            pivot = (mask & -mask).bit_length() - 1
            prior_masks = dict.get(feasible_masks, pivot, ())
            feasible_masks[pivot] = (*prior_masks, mask)
    memo: dict[int, list[list[tuple[Mapping[str, Any], Mapping[str, Any]]]]] = {
        0: []
    }
    for mask in range(1, 1 << count):
        pivot = (mask & -mask).bit_length() - 1
        best: list[list[tuple[Mapping[str, Any], Mapping[str, Any]]]] | None = None
        for subset in dict.get(feasible_masks, pivot, ()):
            if subset & mask != subset:
                continue
            selected = [
                ordered[index] for index in range(count) if subset & (1 << index)
            ]
            # Every candidate removes a non-empty subset from ``mask``, so its
            # remainder has already been solved by this ascending-mask dynamic
            # program.  This is the same recurrence and first-winner tie rule
            # as the former recursive closure, without hidden closure state.
            candidate = [selected, *memo[mask ^ subset]]
            if best is None or v2_partition_objective(candidate) < v2_partition_objective(best):
                best = candidate
        if best is None:
            raise EvidenceFailed("no feasible exact review partition exists")
        memo[mask] = best
    return memo[(1 << count) - 1]


def v2_large_partition(
    rows: Sequence[tuple[Mapping[str, Any], Mapping[str, Any]]],
    *,
    max_targets: int,
) -> tuple[
    list[list[tuple[Mapping[str, Any], Mapping[str, Any]]]],
    dict[str, Any],
]:
    ordered = sorted(
        rows,
        key=lambda pair: (
            -int(pair[1]["review_minutes"]),
            -int(pair[0]["retained_payload_bytes"]),
            pair[0]["id"],
        ),
    )
    group_key_root, ordered_load_rows_root = v2_packing_input_bindings(
        ordered
    )
    total_minutes = sum(int(pair[1]["review_minutes"]) for pair in ordered)
    total_bytes = sum(int(pair[0]["retained_payload_bytes"]) for pair in ordered)
    lower_bound = max(
        math.ceil(len(ordered) / max_targets),
        math.ceil(total_minutes / V2_REVIEW_MINUTES_CAP),
        math.ceil(total_bytes / V2_CHILD_PAYLOAD_CAP),
        1,
    )
    bin_count = lower_bound
    while bin_count <= len(ordered):
        bins: list[list[tuple[Mapping[str, Any], Mapping[str, Any]]]] = [
            [] for _ in range(bin_count)
        ]
        admitted = True
        for row in ordered:
            candidates = sorted(
                range(bin_count),
                key=lambda index: (
                    v2_bin_load(bins[index]),
                    tuple(target["id"] for target, _ in bins[index]),
                    index,
                ),
            )
            destination = next(
                (
                    index
                    for index in candidates
                    if v2_bin_feasible(
                        [*bins[index], row],
                        max_targets=max_targets,
                    )
                ),
                None,
            )
            if destination is None:
                admitted = False
                break
            bins[destination].append(row)
        if admitted and all(bins):
            achieved = v2_objective_document(bins)
            witness = {
                "algorithm": "DETERMINISTIC_LPT_VECTOR_PACKING",
                "group_key_root": group_key_root,
                "ordered_load_rows_root": ordered_load_rows_root,
                "lower_bound_children": lower_bound,
                "observed_children": bin_count,
                "child_count_gap": bin_count - lower_bound,
                "lower_bound_vector": {
                    "targets": math.ceil(len(ordered) / max_targets),
                    "review_minutes": math.ceil(
                        total_minutes / V2_REVIEW_MINUTES_CAP
                    ),
                    "retained_payload_bytes": math.ceil(
                        total_bytes / V2_CHILD_PAYLOAD_CAP
                    ),
                },
                "transport_constraint_root": (
                    v2_partition_transport_constraint_root(bins)
                ),
                "achieved_objective": achieved,
                "gap_witness": {
                    "child_count": bin_count - lower_bound,
                    "maximum_review_minutes_above_average": (
                        achieved["maximum_review_minutes"]
                        - math.ceil(total_minutes / bin_count)
                    ),
                    "maximum_retained_bytes_above_average": (
                        achieved["maximum_retained_payload_bytes"]
                        - math.ceil(total_bytes / bin_count)
                    ),
                },
                "exact_optimality_claim": False,
                "max_targets_per_child": max_targets,
                "rationale": (
                    "deterministic largest-first vector placement starts at "
                    "the independently computed multidimensional lower bound"
                ),
                "falsifier": (
                    "a feasible plan with a lexicographically smaller frozen "
                    "objective or an incorrect lower bound invalidates this witness"
                ),
            }
            return bins, v2_rooted(witness)
        bin_count += 1
    raise EvidenceFailed("large-instance review packing has no feasible partition")


def v2_pack_group(
    rows: Sequence[tuple[Mapping[str, Any], Mapping[str, Any]]],
    *,
    max_targets: int,
) -> tuple[
    list[list[tuple[Mapping[str, Any], Mapping[str, Any]]]],
    dict[str, Any],
]:
    if not 1 <= max_targets <= V2_REVIEW_TARGET_HARD_MAX:
        raise UsageRefused(
            f"--max-targets-per-child must be in 1..{V2_REVIEW_TARGET_HARD_MAX}"
        )
    if any(
        int(authority["review_minutes"]) > V2_REVIEW_MINUTES_CAP
        or int(target["retained_payload_bytes"]) > V2_CHILD_PAYLOAD_CAP
        or bool(v2_child_transport_violations([(target, authority)]))
        for target, authority in rows
    ):
        raise EvidenceFailed("oversize rows must be removed before standard packing")
    group_key_root, ordered_load_rows_root = v2_packing_input_bindings(rows)
    if len(rows) <= V2_EXACT_OPTIMALITY_MAX_TARGETS:
        bins = v2_exact_partition(rows, max_targets=max_targets)
        witness = v2_rooted(
            {
                "algorithm": "EXACT_SUBSET_PARTITION",
                "group_key_root": group_key_root,
                "ordered_load_rows_root": ordered_load_rows_root,
                "exact_optimality_max_targets": V2_EXACT_OPTIMALITY_MAX_TARGETS,
                "exact_optimality_claim": True,
                "objective": v2_objective_document(bins),
                "transport_constraint_root": (
                    v2_partition_transport_constraint_root(bins)
                ),
                "max_targets_per_child": max_targets,
                "rationale": (
                    "the exact subset search minimizes the frozen objective "
                    "over every feasible partition"
                ),
                "falsifier": (
                    "a feasible partition with a lexicographically smaller "
                    "objective invalidates this witness"
                ),
            }
        )
        return bins, witness
    return v2_large_partition(rows, max_targets=max_targets)


def v2_markdown_inline_code(value: str) -> str:
    longest = max(
        (len(match.group(0)) for match in re.finditer(r"`+", value)),
        default=0,
    )
    fence = "`" * (longest + 1)
    padding = " " if value.startswith("`") or value.endswith("`") else ""
    return f"{fence}{padding}{value}{padding}{fence}"


def v2_child_text(
    targets: Sequence[Mapping[str, Any]],
    authorities: Sequence[Mapping[str, Any]],
    *,
    oversize: bool,
) -> tuple[str, str, str, str]:
    target_ids = [target["id"] for target in targets]
    disposition = str(targets[0]["disposition"])
    workflow_obligations = {
        "MALFORMED_OR_WRONG_TYPE": (
            "Validate the declared issue type and repair malformed template "
            "structure without changing the underlying scope; add focused type "
            "and schema unit tests."
        ),
        "ROLLUP_CHILD_SET_GAP": (
            "Reconstruct the exact child/dependency set, prove the rollup union "
            "and zero cells, and retain graph-aware E2E evidence."
        ),
        "OWNER_REVIEW_REQUIRED": (
            "Obtain root-bound answers from the current semantic owner for "
            "acceptance, implementation, evidence, and terminal-consumer questions."
        ),
        "SUBSTANTIVE_SEMANTIC_OMISSION": (
            "Add issue-specific acceptance and success proof obligations, "
            "including unit/property coverage, authentic E2E, detailed logging, "
            "offline replay, cancellation, and no-claim boundaries."
        ),
        "SECTION_NAME_ONLY": (
            "Preserve every existing byte of substantive prose and make only "
            "the independently reviewed heading/placement correction."
        ),
        "HISTORICAL_IMMUTABLE_REVIEW": (
            "Do not mutate the closed source; account for closer provenance, "
            "citations, candidate consumers, and proof NoData in history."
        ),
    }.get(
        disposition,
        "Resolve the exact rooted disposition without generic replacement text.",
    )
    target_lines = "\n".join(
        f"- `{target['id']}` target_root `{target['target_root']}` "
        + (
            f"template findings {', '.join(target['missing_sections'])}"
            if target["missing_sections"]
            else (
                "template findings NONE; comprehensive semantic review "
                "remains UNREVIEWED"
            )
        )
        + (
            f"; semantic action `{authority['semantic_review_action']}` "
            f"with disposition `{authority['semantic_review_disposition']}`"
        )
        + (
            "; responsibilities "
            "implementation="
            f"{v2_markdown_inline_code(authority['implementation_owner'])}, "
            "evidence="
            f"{v2_markdown_inline_code(authority['evidence_owner'])}, "
            "terminal-consumer="
            f"{v2_markdown_inline_code(authority['terminal_consumer'])}"
        )
        for target, authority in zip(targets, authorities, strict=True)
    )
    description = (
        "Review the exact semantic Bead plan quality for the targets below. "
        "Use each retained target and field root; do not replace issue-specific "
        "meaning with generic boilerplate.\n\n"
        f"{target_lines}\n\n"
        "This generated plan is tracker-read-only. The future publisher must "
        "re-observe every target and preserve all target semantics.\n\n"
        f"Disposition-specific workflow: {workflow_obligations}"
    )
    if oversize:
        description += (
            "\n\nThis is an OVERSIZE_REVIEW_REQUIRED escalation. The bounded "
            "index is explicitly incomplete; the retained full-plan artifact "
            "and canonical `br show ID --json` reproduction are authoritative "
            "for source retrieval."
        )
    acceptance = (
        "1. Review every exact target and field root without dropping or "
        "duplicating membership.\n"
        "2. Resolve the named disposition using issue-specific acceptance, "
        "unit/property tests, authentic E2E, deterministic logging, and replay.\n"
        "3. Preserve target implementation estimates separately from review "
        "effort and keep authority/readiness/route boundaries explicit.\n"
        "4. Retain the exact semantic-review disposition, dimension receipts, "
        "and root-bound adjudication; only REMEDIATION_REQUIRED may become a "
        "future corrective-materialization candidate.\n"
        "5. Refuse stale roots, active conflicts, deferred apply, semantic "
        "truncation, generic merges, and unverified evidence.\n"
        "6. Close only through the canonical generated-leaf terminal protocol."
        f"\n7. Disposition-specific acceptance: {workflow_obligations}"
    )
    design = (
        "Hard partition vector: priority/status/disposition/type/missing-set/"
        "semantic-disposition/semantic-receipt-state/semantic-action/readiness/"
        "remediation-route. Compatibility is valid only through the retained "
        "target-complete receipt. "
        f"Workflow `{disposition}`: {workflow_obligations}"
    )
    notes = (
        f"Targets: {', '.join(target_ids)}. Readiness: "
        f"{', '.join(sorted({row['readiness'] for row in authorities}))}. "
        "No external-human, target-implementation, science, performance, "
        "product, promotion, or release authority is minted."
    )
    return description, acceptance, design, notes


def v2_validate_child_payload(child: Mapping[str, Any]) -> None:
    if type(child) is not dict:
        raise EvidenceFailed("planned child is not an object")
    v2_exact_keys(
        child,
        V2_PLANNED_CHILD_FIELDS,
        label="planned child",
    )
    target_ids = child["target_ids"]
    if (
        type(target_ids) is not list
        or not 1 <= len(target_ids) <= V2_REVIEW_TARGET_HARD_MAX
        or not all(type(value) is str and value for value in target_ids)
        or target_ids != sorted(target_ids)
        or len(target_ids) != len(set(target_ids))
    ):
        raise EvidenceFailed(
            "planned child target membership exceeds its hard cap or is "
            "malformed"
        )
    target_count = len(target_ids)
    target_indexed_fields = (
        "target_roots",
        "source_dependency_snapshot",
        "target_implementation_estimates",
        "target_implementation_estimated_minutes",
        "target_implementation_estimate_states",
        "responsibility_assignments",
        "semantic_review_receipt_roots",
        "reviewed_no_change_receipt_roots",
        "external_authority",
        "external_authority_receipt_root",
        "external_authority_verdict",
        "conditional_write_capability",
        "conditional_write_receipt_root",
        "conditional_write_verdict",
    )
    target_indexed_cardinality_differs = False
    for field in target_indexed_fields:
        indexed_value = child[field]
        if (
            type(indexed_value) is not list
            or len(indexed_value) != target_count
        ):
            target_indexed_cardinality_differs = True
            break
    if target_indexed_cardinality_differs:
        raise EvidenceFailed(
            "planned child target-indexed collection cardinality differs"
        )
    if (
        type(child["labels"]) is not list
        or len(child["labels"]) > V2_LABELS_PER_ISSUE_CAP
        or type(child["intended_generated_edges"]) is not list
        or len(child["intended_generated_edges"]) != 2
    ):
        raise EvidenceFailed(
            "planned child label or generated-edge cardinality differs"
        )
    key_inputs_preflight = child["external_ref_key_inputs"]
    key_input_target_fields = (
        "target_ids",
        "target_roots",
        "semantic_review_receipt_roots",
        "responsibility_assignments",
        "authority_decision_roots",
    )
    key_input_cardinality_differs = type(key_inputs_preflight) is not dict
    if not key_input_cardinality_differs:
        for field in key_input_target_fields:
            if not dict.__contains__(key_inputs_preflight, field):
                key_input_cardinality_differs = True
                break
            indexed_value = dict.__getitem__(key_inputs_preflight, field)
            if (
                type(indexed_value) is not list
                or len(indexed_value) != target_count
            ):
                key_input_cardinality_differs = True
                break
    if key_input_cardinality_differs:
        raise EvidenceFailed(
            "planned child external identity collection cardinality differs"
        )
    compatibility_preflight = child["compatibility"]
    compatibility_target_ids = (
        dict.__getitem__(compatibility_preflight, "target_ids")
        if type(compatibility_preflight) is dict
        and dict.__contains__(compatibility_preflight, "target_ids")
        else None
    )
    if (
        type(compatibility_target_ids) is not list
        or len(compatibility_target_ids)
        > V2_COMPATIBILITY_TARGETS_PER_RECEIPT_CAP
    ):
        raise EvidenceFailed(
            "planned child compatibility collection exceeds its cap or is "
            "malformed"
        )
    v2_validate_canonical_byte_size(
        child,
        cap=V2_GENERATED_CHILD_PAYLOAD_CAP,
        label="planned child generated payload",
    )
    verify_semantic_root(child, label="planned child")
    if (
        child["schema"]
        != "frankensim.beads-template-hygiene.planned-child.v2"
        or not all(
            type(child[field]) is str and child[field]
            for field in (
                "child_key",
                "title",
                "issue_type",
                "desired_status",
                "lane_parent",
                "external_ref",
                "acceptance_criteria",
                "acceptance",
                "design",
                "notes",
                "disposition_workflow",
                "semantic_review_disposition",
                "semantic_review_receipt_state",
                "semantic_review_action",
                "readiness",
                "remediation_route",
                "packing_witness_root",
                "falsifier",
                "description_root",
                "no_claim",
                "semantic_root",
            )
        )
        or type(child["coordination_assignee"]) is not str
        or type(child["priority"]) is not int
        or child["priority"] not in range(5)
        or child["lane_parent"] != v2_lane_parent(child["priority"])
        or child["issue_type"] != "task"
        or type(child["labels"]) is not list
        or not all(type(value) is str and value for value in child["labels"])
        or child["labels"] != sorted(set(child["labels"]))
        or child["desired_status"] not in {"open", "deferred"}
        or child["readiness"] not in V2_READINESS_STATES
        or child["remediation_route"] not in V2_REMEDIATION_ROUTES
        or child["semantic_review_disposition"]
        not in V2_SEMANTIC_REVIEW_DISPOSITIONS
        or child["semantic_review_receipt_state"]
        not in V2_SEMANTIC_REVIEW_RECEIPT_STATES
        or child["semantic_review_action"] not in V2_SEMANTIC_REVIEW_ACTIONS
        or child["disposition_workflow"]
        not in {*DISPOSITIONS, "OVERSIZE_REVIEW_REQUIRED"}
        or child["no_claim"] != V2_PLANNED_CHILD_NO_CLAIM
        or not v2_is_semantic_root(child["packing_witness_root"])
    ):
        raise EvidenceFailed("planned child scalar or enum contract differs")
    description = child["description_file_artifact"]
    if type(description) is not dict:
        raise EvidenceFailed("planned child description artifact is malformed")
    v2_exact_keys(
        description,
        {"media_type", "bytes", "root", "content", "transport"},
        label="planned child description artifact",
    )
    if (
        description["media_type"] != "text/markdown; charset=utf-8"
        or type(description["bytes"]) is not int
        or description["bytes"] < 0
        or type(description["root"]) is not str
        or type(description["content"]) is not str
        or description["transport"] != "br create --description-file -"
    ):
        raise EvidenceFailed(
            "planned child description transport scalar contract differs"
        )
    payloads = {
        "description": str.encode(description["content"], "utf-8"),
        "acceptance": str.encode(child["acceptance_criteria"], "utf-8"),
        "design": str.encode(child["design"], "utf-8"),
        "notes": str.encode(child["notes"], "utf-8"),
    }
    limits = {
        "description": V2_CHILD_DESCRIPTION_CAP,
        "acceptance": V2_CHILD_ACCEPTANCE_CAP,
        "design": V2_CHILD_DESIGN_CAP,
        "notes": V2_CHILD_NOTES_CAP,
    }
    for field, payload in payloads.items():
        if len(payload) > limits[field]:
            raise EvidenceFailed(f"planned child {field} exceeds its transport cap")
    if (
        description["bytes"] != len(payloads["description"])
        or description["root"] != text_root(description["content"])
        or child["description_root"] != description["root"]
        or child["acceptance"] != child["acceptance_criteria"]
    ):
        raise EvidenceFailed("planned child transport roots or aliases disagree")
    argv_bytes = sum(
        len(payloads[field]) for field in ("acceptance", "design", "notes")
    )
    if argv_bytes > V2_CHILD_ARGV_AGGREGATE_CAP:
        raise EvidenceFailed("planned child aggregate non-description argv exceeds cap")
    if (
        type(child["review_minutes"]) is not int
        or child["review_minutes"] < 0
        or child["review_minutes"] > V2_REVIEW_MINUTES_CAP
        or type(child["estimated_minutes"]) is not int
        or type(child["generated_child_estimated_minutes"]) is not int
        or child["estimated_minutes"] != child["review_minutes"]
        or child["generated_child_estimated_minutes"]
        != child["review_minutes"]
    ):
        raise EvidenceFailed("planned child review-minute aliases disagree")
    target_roots = child["target_roots"]
    target_roots_malformed = (
        type(target_roots) is not list
        or len(target_roots) != len(target_ids)
    )
    if not target_roots_malformed:
        for value in target_roots:
            if not v2_is_semantic_root(value):
                target_roots_malformed = True
                break
    if (
        target_roots_malformed
        or len(target_roots) != len(set(target_roots))
    ):
        raise EvidenceFailed("planned child target membership or roots are malformed")
    dependency_snapshot = child["source_dependency_snapshot"]
    dependency_snapshot_malformed = (
        type(dependency_snapshot) is not list
        or len(dependency_snapshot) != len(target_ids)
    )
    if not dependency_snapshot_malformed:
        for row in dependency_snapshot:
            if (
                type(row) is not dict
                or set(row)
                != {"target_id", "dependency_neighborhood_root"}
                or type(row["target_id"]) is not str
                or not v2_is_semantic_root(
                    row["dependency_neighborhood_root"]
                )
            ):
                dependency_snapshot_malformed = True
                break
    if (
        dependency_snapshot_malformed
        or [row["target_id"] for row in dependency_snapshot] != target_ids
    ):
        raise EvidenceFailed(
            "planned child dependency snapshot is malformed or misordered"
        )
    estimate_rows = child["target_implementation_estimates"]
    estimate_aliases = child["target_implementation_estimated_minutes"]
    estimate_states = child["target_implementation_estimate_states"]
    if not all(
        type(rows) is list and len(rows) == len(target_ids)
        for rows in (estimate_rows, estimate_aliases, estimate_states)
    ):
        raise EvidenceFailed("planned child implementation estimates are malformed")
    for target_id, estimate, alias, state_row in zip(
        target_ids,
        estimate_rows,
        estimate_aliases,
        estimate_states,
    ):
        if (
            type(estimate) is not dict
            or set(estimate) != {"target_id", "state", "estimated_minutes"}
            or type(alias) is not dict
            or set(alias) != {"target_id", "estimated_minutes"}
            or type(state_row) is not dict
            or set(state_row) != {"target_id", "state"}
            or estimate["target_id"] != target_id
            or alias["target_id"] != target_id
            or state_row["target_id"] != target_id
            or estimate["state"] != state_row["state"]
            or estimate["state"] not in {"DECLARED", "NODATA"}
            or estimate["estimated_minutes"] != alias["estimated_minutes"]
            or (
                estimate["state"] == "DECLARED"
                and (
                    type(estimate["estimated_minutes"]) is not int
                    or estimate["estimated_minutes"] < 0
                )
            )
            or (
                estimate["state"] == "NODATA"
                and estimate["estimated_minutes"] is not None
            )
        ):
            raise EvidenceFailed(
                "planned child implementation estimate state/value disagrees"
            )

    def target_indexed_rows(
        field: str,
        expected_fields: set[str],
    ) -> list[Mapping[str, Any]]:
        rows = child[field]
        rows_malformed = (
            type(rows) is not list
            or len(rows) != len(target_ids)
        )
        if not rows_malformed:
            for row in rows:
                if (
                    type(row) is not dict
                    or set(row) != expected_fields
                ):
                    rows_malformed = True
                    break
        if (
            rows_malformed
            or [row["target_id"] for row in rows] != target_ids
        ):
            raise EvidenceFailed(
                f"planned child {field} target-indexed rows are malformed"
            )
        return rows

    semantic_root_rows = target_indexed_rows(
        "semantic_review_receipt_roots",
        {"target_id", "receipt_root"},
    )
    reviewed_no_change_rows = target_indexed_rows(
        "reviewed_no_change_receipt_roots",
        {"target_id", "receipt_root"},
    )
    responsibility_rows = target_indexed_rows(
        "responsibility_assignments",
        {
            "target_id",
            "implementation_owner",
            "evidence_owner",
            "terminal_consumer",
        },
    )
    for row in responsibility_rows:
        assignment_is_noncanonical = False
        for field in (
            "implementation_owner",
            "evidence_owner",
            "terminal_consumer",
        ):
            value = row[field]
            if (
                type(value) is not str
                or not value
                or value != value.strip()
            ):
                assignment_is_noncanonical = True
                break
        if assignment_is_noncanonical:
            raise EvidenceFailed(
                "planned child responsibility assignment is noncanonical"
            )
    for semantic_row, no_change_row in zip(
        semantic_root_rows,
        reviewed_no_change_rows,
        strict=True,
    ):
        semantic_receipt_root = semantic_row["receipt_root"]
        no_change_root = no_change_row["receipt_root"]
        if (
            semantic_receipt_root is not None
            and (
                not v2_is_semantic_root(semantic_receipt_root)
            )
        ):
            raise EvidenceFailed(
                "planned child semantic-review receipt root is malformed"
            )
        if (
            no_change_root is not None
            and (
                not v2_is_semantic_root(no_change_root)
            )
        ):
            raise EvidenceFailed(
                "planned child reviewed-no-change root is malformed"
            )
        if (
            child["semantic_review_receipt_state"] == "UNREVIEWED"
            and semantic_receipt_root is not None
        ):
            raise EvidenceFailed(
                "unreviewed planned child carries a semantic receipt root"
            )
        if (
            child["semantic_review_disposition"] == "REVIEWED_NO_CHANGE"
            and no_change_root != semantic_receipt_root
        ) or (
            child["semantic_review_disposition"] != "REVIEWED_NO_CHANGE"
            and no_change_root is not None
        ):
            raise EvidenceFailed(
                "planned child reviewed-no-change root disagrees with disposition"
            )

    external_rows = target_indexed_rows(
        "external_authority",
        {
            "target_id",
            "adapter",
            "receipt_root",
            "verdict",
            "verified",
            "structurally_valid",
            "trust_registry",
        },
    )
    external_root_rows = target_indexed_rows(
        "external_authority_receipt_root",
        {"target_id", "receipt_root"},
    )
    external_verdict_rows = target_indexed_rows(
        "external_authority_verdict",
        {"target_id", "verdict"},
    )
    conditional_rows = target_indexed_rows(
        "conditional_write_capability",
        {
            "target_id",
            "identity",
            "receipt_root",
            "verdict",
            "verified",
            "structurally_valid",
            "current_tool_verdict",
        },
    )
    conditional_root_rows = target_indexed_rows(
        "conditional_write_receipt_root",
        {"target_id", "receipt_root"},
    )
    conditional_verdict_rows = target_indexed_rows(
        "conditional_write_verdict",
        {"target_id", "verdict"},
    )
    for index, target_id in enumerate(target_ids):
        external = external_rows[index]
        conditional = conditional_rows[index]
        if (
            external["receipt_root"]
            != external_root_rows[index]["receipt_root"]
            or external["verdict"]
            != external_verdict_rows[index]["verdict"]
            or external["verdict"]
            not in {
                "NODATA",
                "VALID",
                "INVALID",
                "REVOKED",
                "EXPIRED",
                "CONFLICTED",
            }
            or type(external["verified"]) is not bool
            or type(external["structurally_valid"]) is not bool
            or type(external["receipt_root"]) is not str
            or (
                external["receipt_root"] != ""
                and not v2_is_semantic_root(external["receipt_root"])
            )
            or conditional["receipt_root"]
            != conditional_root_rows[index]["receipt_root"]
            or conditional["verdict"]
            != conditional_verdict_rows[index]["verdict"]
            or conditional["verdict"]
            not in {
                "NODATA",
                "VALID",
                "FAILED",
                "LYING",
                "NON_ATOMIC",
                "VERSION_MISMATCHED",
                "CONFLICTED",
            }
            or type(conditional["verified"]) is not bool
            or type(conditional["structurally_valid"]) is not bool
            or type(conditional["receipt_root"]) is not str
            or (
                conditional["receipt_root"] != ""
                and not v2_is_semantic_root(conditional["receipt_root"])
            )
            or not all(
                type(external[field]) is str
                for field in (
                    "adapter",
                    "receipt_root",
                    "verdict",
                    "trust_registry",
                )
            )
            or not all(
                type(conditional[field]) is str
                for field in (
                    "identity",
                    "receipt_root",
                    "verdict",
                    "current_tool_verdict",
                )
            )
        ):
            raise EvidenceFailed(
                "planned child authority/capability aliases disagree for "
                f"{target_id}"
            )
    compatibility = child["compatibility"]
    if type(compatibility) is not dict:
        raise EvidenceFailed("planned child compatibility receipt is malformed")
    v2_exact_keys(
        compatibility,
        {
            "key",
            "target_ids",
            "receipt_root",
            "rationale",
            "falsifier",
            "target_complete",
        },
        label="planned child compatibility receipt",
    )
    if (
        not all(
            type(compatibility[field]) is str
            for field in (
                "key",
                "receipt_root",
                "rationale",
                "falsifier",
            )
        )
        or type(compatibility["target_complete"]) is not bool
        or (
            compatibility["receipt_root"] != ""
            and not v2_is_semantic_root(compatibility["receipt_root"])
        )
    ):
        raise EvidenceFailed("planned child compatibility scalars are malformed")
    compatibility_target_ids = v2_validate_compatibility_target_ids(
        compatibility["target_ids"],
        label="planned child compatibility target IDs",
        error_type=EvidenceFailed,
    )
    if compatibility["target_complete"]:
        compatibility_text_is_incomplete = False
        for field in (
            "key",
            "receipt_root",
            "rationale",
            "falsifier",
        ):
            value = compatibility[field]
            if not value or value != str.strip(value):
                compatibility_text_is_incomplete = True
                break
        if (
            compatibility_text_is_incomplete
            or not v2_is_semantic_root(compatibility["receipt_root"])
            or any(
                target_id not in compatibility_target_ids
                for target_id in target_ids
            )
        ):
            raise EvidenceFailed(
                "planned child target-complete compatibility receipt "
                "does not cover its child"
            )
    elif (
        len(target_ids) != 1
        or compatibility != {
            "key": "",
            "target_ids": [],
            "receipt_root": "",
            "rationale": V2_SINGLETON_NO_COMPATIBILITY_RATIONALE,
            "falsifier": V2_SINGLETON_NO_COMPATIBILITY_FALSIFIER,
            "target_complete": False,
        }
    ):
        raise EvidenceFailed(
            "planned child no-compatibility singleton receipt differs"
        )
    child_key = child["child_key"]
    generated = f"generated:{child_key}"
    expected_edges = [
        {
            "from": generated,
            "to": child["lane_parent"],
            "type": "parent-child",
        },
        {
            "from": V2_GENERATION_GATE_ID,
            "to": generated,
            "type": "blocks",
        },
    ]
    if child["intended_generated_edges"] != expected_edges:
        raise EvidenceFailed(
            "planned child generated-edge membership, direction, or type differs"
        )
    key_inputs = child["external_ref_key_inputs"]
    if type(key_inputs) is not dict:
        raise EvidenceFailed("planned child external identity inputs are malformed")
    v2_exact_keys(
        key_inputs,
        {
            "schema",
            "priority",
            "lane_parent",
            "generation_gate_id",
            "status",
            "disposition",
            "type",
            "missing_sections",
            "semantic_review_disposition",
            "semantic_review_receipt_state",
            "semantic_review_action",
            "semantic_review_receipt_roots",
            "responsibility_assignments",
            "readiness",
            "remediation_route",
            "desired_status",
            "target_ids",
            "target_roots",
            "authority_decision_roots",
            "compatibility",
            "packing_witness_root",
            "oversize",
            "render_policy",
        },
        label="planned child external identity inputs",
    )
    expected_render_policy = v2_child_render_policy()
    oversize_inputs = key_inputs["oversize"]
    expected_oversize = (
        child["disposition_workflow"] == "OVERSIZE_REVIEW_REQUIRED"
    )
    oversize_inputs_malformed = type(oversize_inputs) is not dict
    artifact_reference: Any = None
    if not oversize_inputs_malformed:
        if set(oversize_inputs) != {"required", "artifact_reference"}:
            oversize_inputs_malformed = True
        else:
            oversize_required = oversize_inputs["required"]
            artifact_reference = oversize_inputs["artifact_reference"]
            if (
                type(oversize_required) is not bool
                or oversize_required != expected_oversize
            ):
                oversize_inputs_malformed = True
    if expected_oversize:
        if type(artifact_reference) is not dict:
            oversize_inputs_malformed = True
        elif set(artifact_reference) != {"relative_path", "semantic_root"}:
            oversize_inputs_malformed = True
        else:
            artifact_relative_path = artifact_reference["relative_path"]
            artifact_semantic_root = artifact_reference["semantic_root"]
            if (
                type(artifact_relative_path) is not str
                or type(artifact_semantic_root) is not str
                or not v2_is_semantic_root(artifact_semantic_root)
                or (
                    "Full retained oversize artifact: "
                    f"{artifact_relative_path} root {artifact_semantic_root}."
                )
                not in child["notes"]
            ):
                oversize_inputs_malformed = True
    elif artifact_reference is not None:
        oversize_inputs_malformed = True
    if oversize_inputs_malformed:
        raise EvidenceFailed(
            "planned child oversize external identity inputs disagree"
        )
    decision_roots = key_inputs["authority_decision_roots"]
    decision_roots_malformed = (
        type(decision_roots) is not list
        or len(decision_roots) != len(target_ids)
    )
    if not decision_roots_malformed:
        for row in decision_roots:
            if (
                type(row) is not dict
                or set(row) != {"target_id", "decision_root"}
                or type(row["target_id"]) is not str
                or not v2_is_semantic_root(row["decision_root"])
            ):
                decision_roots_malformed = True
                break
    if (
        decision_roots_malformed
        or [row["target_id"] for row in decision_roots] != target_ids
    ):
        raise EvidenceFailed(
            "planned child authority-decision identity roots are malformed"
        )
    key_inputs_root = semantic_root(key_inputs)
    v2_require_semantic_root(
        key_inputs_root,
        label="planned child external identity inputs root",
    )
    if (
        child["external_ref"] != f"fs-template-hygiene:v2:{child_key}"
        or key_inputs["lane_parent"] != child["lane_parent"]
        or key_inputs["generation_gate_id"] != V2_GENERATION_GATE_ID
        or key_inputs["target_ids"] != target_ids
        or key_inputs["target_roots"] != target_roots
        or key_inputs["semantic_review_disposition"]
        != child["semantic_review_disposition"]
        or key_inputs["semantic_review_receipt_state"]
        != child["semantic_review_receipt_state"]
        or key_inputs["semantic_review_action"]
        != child["semantic_review_action"]
        or key_inputs["semantic_review_receipt_roots"]
        != child["semantic_review_receipt_roots"]
        or key_inputs["responsibility_assignments"]
        != child["responsibility_assignments"]
        or key_inputs["desired_status"] != child["desired_status"]
        or key_inputs["compatibility"] != compatibility
        or key_inputs["packing_witness_root"]
        != child["packing_witness_root"]
        or key_inputs["render_policy"] != expected_render_policy
        or key_inputs_root[10:] != child_key
    ):
        raise EvidenceFailed("planned child external identity inputs disagree")


def v2_child_render_policy() -> dict[str, Any]:
    return {
        "schema": "frankensim.beads-template-hygiene.child-render-policy.v1",
        "planned_child_no_claim": V2_PLANNED_CHILD_NO_CLAIM,
        "review_plan_schema": V2_REVIEW_PLAN_SCHEMA,
        "generation_gate_id": V2_GENERATION_GATE_ID,
        "review_minutes_cap": V2_REVIEW_MINUTES_CAP,
        "child_description_cap": V2_CHILD_DESCRIPTION_CAP,
        "child_acceptance_cap": V2_CHILD_ACCEPTANCE_CAP,
        "child_design_cap": V2_CHILD_DESIGN_CAP,
        "child_notes_cap": V2_CHILD_NOTES_CAP,
        "child_argv_aggregate_cap": V2_CHILD_ARGV_AGGREGATE_CAP,
        "generated_child_payload_cap": V2_GENERATED_CHILD_PAYLOAD_CAP,
        "normalized_target_identity_schema": (
            V2_NORMALIZED_TARGET_IDENTITY_SCHEMA
        ),
        "normalized_target_identity_algorithm": (
            V2_NORMALIZED_TARGET_IDENTITY_ALGORITHM
        ),
        "normalized_target_identity_excluded_fields": list(
            V2_NORMALIZED_TARGET_ROOT_EXCLUDED_FIELD_ORDER
        ),
        "singleton_rationale": V2_SINGLETON_NO_COMPATIBILITY_RATIONALE,
        "singleton_falsifier": V2_SINGLETON_NO_COMPATIBILITY_FALSIFIER,
    }


def v2_target_authority_row_identity(
    rows: Sequence[tuple[Mapping[str, Any], Mapping[str, Any]]],
    *,
    max_rows: int,
    label: str,
) -> tuple[tuple[str, str, str], ...]:
    if (
        type(max_rows) is not int
        or max_rows < 1
        or type(label) is not str
        or not label
    ):
        raise EvidenceFailed("target-authority row contract is malformed")
    if type(rows) is not list and type(rows) is not tuple:
        raise EvidenceFailed(
            f"{label} rows must use an exact list or tuple"
        )
    if not 1 <= len(rows) <= max_rows:
        raise EvidenceFailed(
            f"{label} row cardinality exceeds its exact bounds"
        )
    identities: list[tuple[str, str, str]] = []
    for index in range(len(rows)):
        pair = rows[index]
        if type(pair) is not tuple or len(pair) != 2:
            raise EvidenceFailed(
                f"{label} row {index} is not an exact target-authority pair"
            )
        target, authority = pair
        if type(target) is not dict or type(authority) is not dict:
            raise EvidenceFailed(
                f"{label} row {index} does not contain exact objects"
            )
        if not (
            dict.__contains__(target, "id")
            and dict.__contains__(target, "target_root")
            and dict.__contains__(authority, "target_id")
            and dict.__contains__(authority, "target_root")
            and dict.__contains__(authority, "semantic_root")
        ):
            raise EvidenceFailed(
                f"{label} row {index} lacks identity fields"
            )
        target_id = target["id"]
        target_root = target["target_root"]
        authority_id = authority["target_id"]
        authority_target_root = authority["target_root"]
        authority_root = authority["semantic_root"]
        if type(target_id) is not str or type(authority_id) is not str:
            raise EvidenceFailed(
                f"{label} row {index} identity is malformed or mismatched"
            )
        v2_validate_issue_id(
            target_id,
            label=f"{label} row {index} target ID",
            error_type=EvidenceFailed,
        )
        v2_validate_issue_id(
            authority_id,
            label=f"{label} row {index} authority target ID",
            error_type=EvidenceFailed,
        )
        if (
            type(target_root) is not str
            or not v2_is_semantic_root(target_root)
            or authority_id != target_id
            or type(authority_target_root) is not str
            or authority_target_root != target_root
            or type(authority_root) is not str
            or not v2_is_semantic_root(authority_root)
        ):
            raise EvidenceFailed(
                f"{label} row {index} identity is malformed or mismatched"
            )
        verify_semantic_root(
            target,
            label=f"{label} row {index} target",
        )
        verify_semantic_root(
            authority,
            label=f"{label} row {index} authority",
        )
        if target_root != v2_normalized_target_root(target):
            raise EvidenceFailed(
                f"{label} row {index} normalized target root differs"
            )
        identities.append((target_id, target_root, authority_root))
    ordered = tuple(sorted(identities))
    if len({row[0] for row in ordered}) != len(ordered):
        raise EvidenceFailed(f"{label} target identities are duplicated")
    return ordered


def v2_child_row_identity(
    rows: Sequence[tuple[Mapping[str, Any], Mapping[str, Any]]],
) -> tuple[tuple[str, str, str], ...]:
    return v2_target_authority_row_identity(
        rows,
        max_rows=V2_REVIEW_TARGET_HARD_MAX,
        label="planned child",
    )


def v2_packing_group_row_identity(
    rows: Sequence[tuple[Mapping[str, Any], Mapping[str, Any]]],
) -> tuple[tuple[str, str, str], ...]:
    return v2_target_authority_row_identity(
        rows,
        max_rows=V2_INVENTORY_ROWS_CAP,
        label="packing group",
    )


def v2_child_oversize_reference(
    *,
    oversize: bool,
    oversize_artifact: Mapping[str, Any] | None,
) -> tuple[bool, str, str]:
    if type(oversize) is not bool:
        raise EvidenceFailed("planned child oversize flag is not an exact bool")
    if oversize != (oversize_artifact is not None):
        raise EvidenceFailed(
            "planned child oversize flag and retained artifact must be present iff"
        )
    if oversize_artifact is None:
        return False, "", ""
    if type(oversize_artifact) is not dict:
        raise EvidenceFailed(
            "planned child oversize registry reference is not an exact object"
        )
    detached = oversize_artifact
    v2_exact_keys(
        detached,
        V2_OVERSIZE_REGISTRY_FIELDS,
        label="planned child oversize registry reference",
    )
    relative_path = detached["relative_path"]
    semantic_root_value = detached["semantic_root"]
    target_roots = detached["target_roots"]
    if (
        type(relative_path) is not str
        or str(
            safe_relative(
                relative_path,
                label="planned child oversize registry reference",
            )
        )
        != relative_path
        or type(target_roots) is not list
        or len(target_roots) != 1
        or type(target_roots[0]) is not str
        or not v2_is_semantic_root(target_roots[0])
        or relative_path
        != (
            "oversize/"
            f"{target_roots[0][len('sha256-v1:'):]}.json"
        )
        or detached["media_kind"] != "application/json"
        or detached["schema_kind"]
        != "frankensim.beads-template-hygiene.oversize-review.v2"
        or type(detached["byte_length"]) is not int
        or detached["byte_length"] < 0
        or type(detached["aggregate_cap_accounting"]) is not int
        or detached["aggregate_cap_accounting"]
        != detached["byte_length"]
        or type(semantic_root_value) is not str
        or not v2_is_semantic_root(semantic_root_value)
        or type(detached["field_roots"]) is not dict
        or type(detached["clause_roots"]) is not dict
        or type(detached["exceeded_caps"]) is not list
        or not detached["exceeded_caps"]
        or any(
            type(row) is not dict
            or set(row) != V2_OVERSIZE_EXCEEDED_CAP_FIELDS
            or type(row["cap"]) is not str
            or not row["cap"]
            or type(row["source_path"]) is not str
            or not row["source_path"]
            or type(row["observed"]) is not int
            or type(row["limit"]) is not int
            or row["observed"] <= row["limit"]
            or type(row["violation_count"]) is not int
            or row["violation_count"] < 1
            or type(row["violating_membership_root"]) is not str
            or not v2_is_semantic_root(row["violating_membership_root"])
            for row in detached["exceeded_caps"]
        )
    ):
        raise EvidenceFailed(
            "planned child oversize registry reference is malformed"
        )
    return True, relative_path, semantic_root_value


def v2_make_child(
    rows: Sequence[tuple[Mapping[str, Any], Mapping[str, Any]]],
    *,
    packing_witness: Mapping[str, Any],
    oversize: bool = False,
    oversize_artifact: Mapping[str, Any] | None = None,
    _validate_payload: bool = True,
) -> dict[str, Any]:
    v2_child_row_identity(rows)
    (
        oversize_required,
        oversize_relative_path,
        oversize_artifact_root,
    ) = v2_child_oversize_reference(
        oversize=oversize,
        oversize_artifact=oversize_artifact,
    )
    targets = [pair[0] for pair in rows]
    authorities = [pair[1] for pair in rows]
    target_ids = sorted(target["id"] for target in targets)
    target_by_id = {target["id"]: target for target in targets}
    authority_by_id = {
        authority["target_id"]: authority for authority in authorities
    }
    ordered_targets = [target_by_id[target_id] for target_id in target_ids]
    ordered_authorities = [authority_by_id[target_id] for target_id in target_ids]
    readiness_values = [
        authority["readiness"] for authority in ordered_authorities
    ]
    if any(type(value) is not str for value in readiness_values):
        raise EvidenceFailed(
            "planned child readiness values are not exact strings"
        )
    readiness = readiness_values[0]
    priority = int(ordered_targets[0]["priority"])
    hard_vectors = {
        v2_hard_vector(target, authority)
        for target, authority in zip(ordered_targets, ordered_authorities)
    }
    if len(hard_vectors) != 1:
        raise EvidenceFailed("planned child crosses a hard partition vector")
    if len(ordered_targets) > 1:
        compatibility_roots = {
            authority["compatibility"]["receipt_root"]
            for authority in ordered_authorities
        }
        if "" in compatibility_roots or len(compatibility_roots) != 1:
            raise EvidenceFailed("multi-target child lacks one compatibility receipt")
    compatibility = dict(ordered_authorities[0]["compatibility"])
    if len(ordered_targets) == 1 and not compatibility["key"]:
        compatibility["rationale"] = (
            V2_SINGLETON_NO_COMPATIBILITY_RATIONALE
        )
        compatibility["falsifier"] = (
            V2_SINGLETON_NO_COMPATIBILITY_FALSIFIER
        )
    lane_parent = v2_lane_parent(priority)
    description, acceptance, design, notes = v2_child_text(
        ordered_targets,
        ordered_authorities,
        oversize=oversize,
    )
    responsibility_assignments = [
        {
            "target_id": authority["target_id"],
            "implementation_owner": authority["implementation_owner"],
            "evidence_owner": authority["evidence_owner"],
            "terminal_consumer": authority["terminal_consumer"],
        }
        for authority in ordered_authorities
    ]
    desired_statuses = {
        authority["active_work_context"][
            "generated_child_desired_status"
        ]
        for authority in ordered_authorities
    }
    if len(desired_statuses) != 1:
        raise EvidenceFailed(
            "planned child crosses an actionability-status partition"
        )
    desired_status = next(iter(desired_statuses))
    packing_witness_root = packing_witness["semantic_root"]
    if (
        type(packing_witness_root) is not str
        or not v2_is_semantic_root(packing_witness_root)
    ):
        raise EvidenceFailed("planned child packing witness root is malformed")
    stable_key_inputs = {
        "schema": V2_REVIEW_PLAN_SCHEMA,
        "priority": priority,
        "lane_parent": lane_parent,
        "generation_gate_id": V2_GENERATION_GATE_ID,
        "status": ordered_targets[0]["status"],
        "disposition": ordered_targets[0]["disposition"],
        "type": ordered_targets[0]["type"],
        "missing_sections": ordered_targets[0]["missing_sections"],
        "semantic_review_disposition": ordered_authorities[0][
            "semantic_review_disposition"
        ],
        "semantic_review_receipt_state": ordered_authorities[0][
            "semantic_review_receipt_state"
        ],
        "semantic_review_action": ordered_authorities[0][
            "semantic_review_action"
        ],
        "semantic_review_receipt_roots": [
            {
                "target_id": authority["target_id"],
                "receipt_root": authority[
                    "semantic_review_receipt_root"
                ],
            }
            for authority in ordered_authorities
        ],
        "responsibility_assignments": responsibility_assignments,
        "readiness": readiness,
        "remediation_route": ordered_authorities[0]["remediation_route"],
        "desired_status": desired_status,
        "target_ids": target_ids,
        "target_roots": [target["target_root"] for target in ordered_targets],
        "authority_decision_roots": [
            {
                "target_id": authority["target_id"],
                "decision_root": authority["semantic_root"],
            }
            for authority in ordered_authorities
        ],
        "compatibility": compatibility,
        "packing_witness_root": packing_witness_root,
        "oversize": {
            "required": oversize,
            "artifact_reference": (
                {
                    "relative_path": oversize_relative_path,
                    "semantic_root": oversize_artifact_root,
                }
                if oversize_required
                else None
            ),
        },
        "render_policy": v2_child_render_policy(),
    }
    stable_key_inputs_root = semantic_root(stable_key_inputs)
    v2_require_semantic_root(
        stable_key_inputs_root,
        label="planned child stable external identity inputs root",
    )
    child_key = stable_key_inputs_root[10:]
    actual_review_minutes = sum(
        int(authority["review_minutes"]) for authority in ordered_authorities
    )
    review_minutes = (
        min(actual_review_minutes, V2_REVIEW_MINUTES_CAP)
        if oversize
        else actual_review_minutes
    )
    retained_notes = notes
    if oversize_required:
        retained_notes = (
            f"{notes} Actual unbounded review estimate: "
            f"{actual_review_minutes} minutes. Full retained oversize "
            f"artifact: {oversize_relative_path} root "
            f"{oversize_artifact_root}."
        )
    coordination_assignees = sorted(
        {
            str(authority["coordination_assignee"])
            for authority in ordered_authorities
            if authority["coordination_assignee"]
        }
    )
    coordination_assignee = (
        coordination_assignees[0] if len(coordination_assignees) == 1 else ""
    )
    disposition = (
        "OVERSIZE_REVIEW_REQUIRED"
        if oversize
        else ordered_targets[0]["disposition"]
    )
    title = (
        f"Review {disposition} template debt for "
        f"{target_ids[0]}"
        if len(target_ids) == 1
        else f"Review {disposition} template debt for {len(target_ids)} targets"
    )
    description_artifact = {
        "media_type": "text/markdown; charset=utf-8",
        "bytes": len(description.encode("utf-8")),
        "root": text_root(description),
        "content": description,
        "transport": "br create --description-file -",
    }
    child = {
        "schema": "frankensim.beads-template-hygiene.planned-child.v2",
        "child_key": child_key,
        "title": title,
        "issue_type": "task",
        "priority": priority,
        "desired_status": desired_status,
        "coordination_assignee": coordination_assignee,
        "labels": sorted(
            {
                "generated-template-review",
                "plan-hygiene",
                "testing",
                "e2e",
                "logging",
                "replay",
                f"priority-p{priority}",
                f"readiness-{str.lower(readiness)}",
                (
                    "oversize-review-required"
                    if oversize
                    else "bounded-review-shard"
                ),
            }
        ),
        "lane_parent": lane_parent,
        "external_ref": f"fs-template-hygiene:v2:{child_key}",
        "external_ref_key_inputs": stable_key_inputs,
        "source_dependency_snapshot": [
            {
                "target_id": target["id"],
                "dependency_neighborhood_root": target[
                    "dependency_neighborhood_root"
                ],
            }
            for target in ordered_targets
        ],
        "intended_generated_edges": [
            {
                "from": f"generated:{child_key}",
                "to": lane_parent,
                "type": "parent-child",
            },
            {
                "from": V2_GENERATION_GATE_ID,
                "to": f"generated:{child_key}",
                "type": "blocks",
            },
        ],
        "description_file_artifact": description_artifact,
        "description_root": description_artifact["root"],
        "acceptance_criteria": acceptance,
        "acceptance": acceptance,
        "design": design,
        "notes": retained_notes,
        "review_minutes": review_minutes,
        "estimated_minutes": review_minutes,
        "generated_child_estimated_minutes": review_minutes,
        "target_implementation_estimates": [
            {
                "target_id": target["id"],
                "state": target["target_implementation_estimate_state"],
                "estimated_minutes": target[
                    "target_implementation_estimated_minutes"
                ],
            }
            for target in ordered_targets
        ],
        "target_implementation_estimated_minutes": [
            {
                "target_id": target["id"],
                "estimated_minutes": target[
                    "target_implementation_estimated_minutes"
                ],
            }
            for target in ordered_targets
        ],
        "target_implementation_estimate_states": [
            {
                "target_id": target["id"],
                "state": target["target_implementation_estimate_state"],
            }
            for target in ordered_targets
        ],
        "responsibility_assignments": responsibility_assignments,
        "target_ids": target_ids,
        "target_roots": [
            target_by_id[target_id]["target_root"] for target_id in target_ids
        ],
        "disposition_workflow": disposition,
        "semantic_review_disposition": ordered_authorities[0][
            "semantic_review_disposition"
        ],
        "semantic_review_receipt_state": ordered_authorities[0][
            "semantic_review_receipt_state"
        ],
        "semantic_review_action": ordered_authorities[0][
            "semantic_review_action"
        ],
        "semantic_review_receipt_roots": [
            {
                "target_id": authority["target_id"],
                "receipt_root": authority[
                    "semantic_review_receipt_root"
                ],
            }
            for authority in ordered_authorities
        ],
        "reviewed_no_change_receipt_roots": [
            {
                "target_id": authority["target_id"],
                "receipt_root": authority[
                    "reviewed_no_change_receipt_root"
                ],
            }
            for authority in ordered_authorities
        ],
        "external_authority": [
            {
                "target_id": authority["target_id"],
                **authority["external_authority"],
            }
            for authority in ordered_authorities
        ],
        "external_authority_receipt_root": [
            {
                "target_id": authority["target_id"],
                "receipt_root": authority["external_authority"]["receipt_root"],
            }
            for authority in ordered_authorities
        ],
        "external_authority_verdict": [
            {
                "target_id": authority["target_id"],
                "verdict": authority["external_authority"]["verdict"],
            }
            for authority in ordered_authorities
        ],
        "conditional_write_capability": [
            {
                "target_id": authority["target_id"],
                **authority["conditional_write_capability"],
            }
            for authority in ordered_authorities
        ],
        "conditional_write_receipt_root": [
            {
                "target_id": authority["target_id"],
                "receipt_root": authority["conditional_write_capability"][
                    "receipt_root"
                ],
            }
            for authority in ordered_authorities
        ],
        "conditional_write_verdict": [
            {
                "target_id": authority["target_id"],
                "verdict": authority["conditional_write_capability"]["verdict"],
            }
            for authority in ordered_authorities
        ],
        "readiness": readiness,
        "remediation_route": ordered_authorities[0]["remediation_route"],
        "packing_witness_root": packing_witness_root,
        "compatibility": compatibility,
        "falsifier": (
            "any stale target root, missing payload field, incompatible hard "
            "vector, incomplete compatibility scope, or lost target refuses"
        ),
        "no_claim": V2_PLANNED_CHILD_NO_CLAIM,
    }
    rooted = v2_rooted(child)
    if _validate_payload:
        v2_validate_child_payload(rooted)
    return rooted


def v2_child_render_cache_contract() -> tuple[
    tuple[types.CodeType, ...],
    str,
]:
    code_objects = (
        v2_make_child.__code__,
        v2_child_text.__code__,
        v2_markdown_inline_code.__code__,
        v2_child_render_policy.__code__,
        v2_child_row_identity.__code__,
        v2_target_authority_row_identity.__code__,
        v2_normalized_target_root.__code__,
        v2_child_oversize_reference.__code__,
        v2_hard_vector.__code__,
        v2_lane_parent.__code__,
        v2_validate_child_payload.__code__,
        v2_rooted.__code__,
        semantic_root.__code__,
        text_root.__code__,
        canonical_bytes.__code__,
    )
    return code_objects, semantic_root(v2_child_render_policy())


_v2_child_transport_cache: OrderedDict[
    tuple[Any, ...],
    tuple[tuple[types.CodeType, ...], str, dict[str, int]],
] = OrderedDict()
_v2_child_transport_cache_lock = threading.RLock()


def _v2_child_transport_observations_locked(
    rows: Sequence[tuple[Mapping[str, Any], Mapping[str, Any]]],
    *,
    oversize: bool = False,
    oversize_artifact: Mapping[str, Any] | None = None,
) -> dict[str, int]:
    row_identity = v2_child_row_identity(rows)
    oversize_reference = v2_child_oversize_reference(
        oversize=oversize,
        oversize_artifact=oversize_artifact,
    )
    render_code_objects, render_policy_root = (
        v2_child_render_cache_contract()
    )
    cache_key = (
        row_identity,
        oversize,
        oversize_reference,
        render_policy_root,
        render_code_objects,
    )
    cached = _v2_child_transport_cache.get(cache_key)
    if (
        cached is not None
        and cached[1] == render_policy_root
        and len(cached[0]) == len(render_code_objects)
        and all(
            cached_code is current_code
            for cached_code, current_code in zip(
                cached[0],
                render_code_objects,
                strict=True,
            )
        )
    ):
        _v2_child_transport_cache.move_to_end(cache_key)
        return dict(cached[2])
    candidate = v2_make_child(
        rows,
        packing_witness={
            "semantic_root": V2_PACKING_PREFLIGHT_WITNESS_ROOT,
        },
        oversize=oversize,
        oversize_artifact=oversize_artifact,
        _validate_payload=False,
    )
    description = candidate["description_file_artifact"]["content"].encode(
        "utf-8"
    )
    acceptance = candidate["acceptance_criteria"].encode("utf-8")
    design = candidate["design"].encode("utf-8")
    notes = candidate["notes"].encode("utf-8")
    observations = {
        "description_bytes": len(description),
        "acceptance_bytes": len(acceptance),
        "design_bytes": len(design),
        "notes_bytes": len(notes),
        "aggregate_non_description_argv_bytes": (
            len(acceptance) + len(design) + len(notes)
        ),
        "generated_child_payload_bytes": len(canonical_bytes(candidate)),
    }
    final_code_objects, final_policy_root = (
        v2_child_render_cache_contract()
    )
    if (
        final_policy_root != render_policy_root
        or len(final_code_objects) != len(render_code_objects)
        or any(
            final_code is not initial_code
            for final_code, initial_code in zip(
                final_code_objects,
                render_code_objects,
                strict=True,
            )
        )
    ):
        raise EvidenceFailed(
            "planned child render contract changed during observation"
        )
    _v2_child_transport_cache[cache_key] = (
        render_code_objects,
        render_policy_root,
        dict(observations),
    )
    _v2_child_transport_cache.move_to_end(cache_key)
    while (
        len(_v2_child_transport_cache)
        > V2_CHILD_TRANSPORT_CACHE_ENTRIES_CAP
    ):
        _v2_child_transport_cache.popitem(last=False)
    return observations


def v2_child_transport_observations(
    rows: Sequence[tuple[Mapping[str, Any], Mapping[str, Any]]],
    *,
    oversize: bool = False,
    oversize_artifact: Mapping[str, Any] | None = None,
) -> dict[str, int]:
    with _v2_child_transport_cache_lock:
        return _v2_child_transport_observations_locked(
            rows,
            oversize=oversize,
            oversize_artifact=oversize_artifact,
        )


def v2_child_transport_violations(
    rows: Sequence[tuple[Mapping[str, Any], Mapping[str, Any]]],
    *,
    oversize: bool = False,
    oversize_artifact: Mapping[str, Any] | None = None,
) -> list[dict[str, Any]]:
    observations = v2_child_transport_observations(
        rows,
        oversize=oversize,
        oversize_artifact=oversize_artifact,
    )
    contracts = (
        (
            "max_description_bytes",
            "rendered_child.description_bytes",
            "description_bytes",
            V2_CHILD_DESCRIPTION_CAP,
        ),
        (
            "max_acceptance_bytes",
            "rendered_child.acceptance_bytes",
            "acceptance_bytes",
            V2_CHILD_ACCEPTANCE_CAP,
        ),
        (
            "max_design_bytes",
            "rendered_child.design_bytes",
            "design_bytes",
            V2_CHILD_DESIGN_CAP,
        ),
        (
            "max_notes_bytes",
            "rendered_child.notes_bytes",
            "notes_bytes",
            V2_CHILD_NOTES_CAP,
        ),
        (
            "max_aggregate_non_description_argv_bytes",
            "rendered_child.aggregate_non_description_argv_bytes",
            "aggregate_non_description_argv_bytes",
            V2_CHILD_ARGV_AGGREGATE_CAP,
        ),
        (
            "max_generated_child_payload_bytes",
            "rendered_child.generated_child_payload_bytes",
            "generated_child_payload_bytes",
            V2_GENERATED_CHILD_PAYLOAD_CAP,
        ),
    )
    target_ids = sorted(str(target["id"]) for target, _ in rows)
    return [
        {
            "cap": cap_name,
            "source_path": source_path,
            "observed": observations[observation_name],
            "limit": limit,
            "violation_count": 1,
            "violating_membership_root": semantic_root(target_ids),
        }
        for cap_name, source_path, observation_name, limit in contracts
        if observations[observation_name] > limit
    ]


def v2_partition_transport_row_key(row: Mapping[str, Any]) -> tuple[str, ...]:
    if type(row) is not dict or set(row) != {"target_ids", "observations"}:
        raise EvidenceFailed("v2 partition transport row is malformed")
    target_ids = row["target_ids"]
    if (
        type(target_ids) is not list
        or not target_ids
        or not all(type(target_id) is str and target_id for target_id in target_ids)
        or target_ids != sorted(target_ids)
        or len(target_ids) != len(set(target_ids))
    ):
        raise EvidenceFailed(
            "v2 partition transport membership is malformed"
        )
    return tuple(target_ids)


def v2_partition_transport_constraint_root(
    bins: Sequence[
        Sequence[tuple[Mapping[str, Any], Mapping[str, Any]]]
    ],
) -> str:
    rows = [
        {
            "target_ids": sorted(
                str(target["id"]) for target, _ in batch
            ),
            "observations": v2_child_transport_observations(batch),
        }
        for batch in bins
    ]
    ordered_rows = sorted(
        rows,
        key=lambda row: v2_partition_transport_row_key(row),
    )
    return semantic_root(
        {
            "caps": {
                "description_bytes": V2_CHILD_DESCRIPTION_CAP,
                "acceptance_bytes": V2_CHILD_ACCEPTANCE_CAP,
                "design_bytes": V2_CHILD_DESIGN_CAP,
                "notes_bytes": V2_CHILD_NOTES_CAP,
                "aggregate_non_description_argv_bytes": (
                    V2_CHILD_ARGV_AGGREGATE_CAP
                ),
                "generated_child_payload_bytes": (
                    V2_GENERATED_CHILD_PAYLOAD_CAP
                ),
            },
            "bins": ordered_rows,
        }
    )


def v2_independent_membership_load(
    membership: Sequence[str],
    load_by_id: Mapping[str, tuple[int, int, int]],
) -> tuple[int, int, int]:
    return (
        sum(load_by_id[target_id][0] for target_id in membership),
        sum(load_by_id[target_id][1] for target_id in membership),
        len(membership),
    )


def v2_independent_partition_objective(
    partition: Sequence[Sequence[str]],
    load_by_id: Mapping[str, tuple[int, int, int]],
) -> tuple[Any, ...]:
    loads = [
        v2_independent_membership_load(membership, load_by_id)
        for membership in partition
    ]
    memberships = tuple(
        sorted(tuple(sorted(membership)) for membership in partition)
    )
    return (
        len(partition),
        max((load[0] for load in loads), default=0),
        max((load[1] for load in loads), default=0),
        max((load[2] for load in loads), default=0),
        tuple(sorted(loads, reverse=True)),
        memberships,
    )


def v2_independent_objective_document(
    partition: Sequence[Sequence[str]],
    load_by_id: Mapping[str, tuple[int, int, int]],
) -> dict[str, Any]:
    key = v2_independent_partition_objective(partition, load_by_id)
    return {
        "child_count": key[0],
        "maximum_review_minutes": key[1],
        "maximum_retained_payload_bytes": key[2],
        "maximum_target_count": key[3],
        "descending_load_vectors": [list(value) for value in key[4]],
        "lexicographic_memberships": [list(value) for value in key[5]],
    }


def v2_independent_exact_optimum(
    *,
    expected_ids: Sequence[str],
    load_by_id: Mapping[str, tuple[int, int, int]],
    row_by_id: Mapping[
        str,
        tuple[Mapping[str, Any], Mapping[str, Any]],
    ],
    max_targets: int,
) -> list[list[str]]:
    count = len(expected_ids)
    feasible_masks: dict[int, tuple[int, ...]] = {}
    for mask in range(1, 1 << count):
        membership = [
            expected_ids[index]
            for index in range(count)
            if mask & (1 << index)
        ]
        selected_rows = [row_by_id[target_id] for target_id in membership]
        minutes, retained_bytes, target_count = (
            v2_independent_membership_load(membership, load_by_id)
        )
        if (
            target_count <= max_targets
            and minutes <= V2_REVIEW_MINUTES_CAP
            and retained_bytes <= V2_CHILD_PAYLOAD_CAP
            and v2_bin_feasible(
                selected_rows,
                max_targets=max_targets,
            )
        ):
            pivot = (mask & -mask).bit_length() - 1
            prior_masks = dict.get(feasible_masks, pivot, ())
            feasible_masks[pivot] = (*prior_masks, mask)

    memo: dict[int, list[list[str]]] = {0: []}
    for mask in range(1, 1 << count):
        pivot = (mask & -mask).bit_length() - 1
        best: list[list[str]] | None = None
        best_key: tuple[Any, ...] | None = None
        for subset in dict.get(feasible_masks, pivot, ()):
            if subset & mask != subset:
                continue
            membership = [
                expected_ids[index]
                for index in range(count)
                if subset & (1 << index)
            ]
            # Objective evaluation canonicalizes memberships independently;
            # retaining DP construction order here avoids a second comparison
            # surface over values recovered from the local memo table.
            candidate = [membership, *memo[mask ^ subset]]
            candidate_key = v2_independent_partition_objective(
                candidate,
                load_by_id,
            )
            if best_key is None or candidate_key < best_key:
                best = candidate
                best_key = candidate_key
        if best is None:
            raise EvidenceFailed(
                "independent exact verifier found no feasible partition"
            )
        memo[mask] = best
    return memo[(1 << count) - 1]


def v2_verify_packing_witness_independent(
    *,
    rows: Sequence[tuple[Mapping[str, Any], Mapping[str, Any]]],
    grouped_children: Sequence[Mapping[str, Any]],
    witness: Mapping[str, Any],
    max_targets: int,
) -> None:
    v2_packing_group_row_identity(rows)
    if (
        (
            type(grouped_children) is not list
            and type(grouped_children) is not tuple
        )
        or not grouped_children
        or any(type(child) is not dict for child in grouped_children)
        or type(witness) is not dict
        or type(max_targets) is not int
        or not 1 <= max_targets <= V2_REVIEW_TARGET_HARD_MAX
    ):
        raise EvidenceFailed("packing witness inputs are malformed")
    if not rows:
        raise EvidenceFailed("packing witness has no input rows")
    group_key_root, ordered_load_rows_root = v2_packing_input_bindings(rows)
    if not (
        dict.__contains__(witness, "group_key_root")
        and dict.__contains__(witness, "ordered_load_rows_root")
        and dict.__contains__(witness, "algorithm")
    ):
        raise EvidenceFailed("packing witness lacks required identity fields")
    if (
        witness["group_key_root"] != group_key_root
        or witness["ordered_load_rows_root"] != ordered_load_rows_root
    ):
        raise EvidenceFailed("packing witness input bindings differ")
    load_by_id: dict[str, tuple[int, int, int]] = {}
    row_by_id: dict[
        str,
        tuple[Mapping[str, Any], Mapping[str, Any]],
    ] = {}
    for target, authority in rows:
        target_id = target["id"]
        if not (
            dict.__contains__(authority, "review_minutes")
            and dict.__contains__(target, "retained_payload_bytes")
        ):
            raise EvidenceFailed("packing witness row lacks load fields")
        review_minutes = authority["review_minutes"]
        retained_payload_bytes = target["retained_payload_bytes"]
        if (
            type(review_minutes) is not int
            or review_minutes < 0
            or type(retained_payload_bytes) is not int
            or retained_payload_bytes < 0
        ):
            raise EvidenceFailed("packing witness row load is malformed")
        load_by_id[target_id] = (
            review_minutes,
            retained_payload_bytes,
            1,
        )
        row_by_id[target_id] = (target, authority)
    expected_ids = sorted(load_by_id)
    memberships: list[list[str]] = []
    for child in grouped_children:
        if not dict.__contains__(child, "target_ids"):
            raise EvidenceFailed("packing child lacks target membership")
        raw_membership = child["target_ids"]
        if (
            type(raw_membership) is not list
            or not raw_membership
            or not all(
                type(target_id) is str and target_id
                for target_id in raw_membership
            )
        ):
            raise EvidenceFailed("packing child target membership is malformed")
        memberships = [*memberships, sorted(raw_membership)]
    memberships = sorted(memberships)
    flattened = [
        target_id
        for membership in memberships
        for target_id in membership
    ]
    if (
        sorted(flattened) != expected_ids
        or len(flattened) != len(set(flattened))
    ):
        raise EvidenceFailed(
            "packing witness membership is not an exact partition: "
            f"expected={expected_ids!r} observed={memberships!r}"
        )

    partition_rows: list[
        list[tuple[Mapping[str, Any], Mapping[str, Any]]]
    ] = []
    for membership in memberships:
        minutes, retained_bytes, target_count = (
            v2_independent_membership_load(membership, load_by_id)
        )
        selected_rows: list[
            tuple[Mapping[str, Any], Mapping[str, Any]]
        ] = []
        for target_id in membership:
            selected_rows = [*selected_rows, row_by_id[target_id]]
        partition_rows = [*partition_rows, selected_rows]
        if (
            not membership
            or target_count > max_targets
            or minutes > V2_REVIEW_MINUTES_CAP
            or retained_bytes > V2_CHILD_PAYLOAD_CAP
            or not v2_bin_feasible(
                selected_rows,
                max_targets=max_targets,
            )
        ):
            raise EvidenceFailed("packing witness contains an infeasible child")
    observed_objective = v2_independent_objective_document(
        memberships,
        load_by_id,
    )
    algorithm = witness["algorithm"]
    if algorithm == "EXACT_SUBSET_PARTITION":
        v2_exact_keys(
            witness,
            {
                "algorithm",
                "group_key_root",
                "ordered_load_rows_root",
                "exact_optimality_max_targets",
                "exact_optimality_claim",
                "objective",
                "transport_constraint_root",
                "max_targets_per_child",
                "rationale",
                "falsifier",
                "semantic_root",
            },
            label="exact packing witness",
        )
        if (
            len(expected_ids) > V2_EXACT_OPTIMALITY_MAX_TARGETS
            or witness["exact_optimality_max_targets"]
            != V2_EXACT_OPTIMALITY_MAX_TARGETS
            or witness["exact_optimality_claim"] is not True
            or witness["transport_constraint_root"]
            != v2_partition_transport_constraint_root(
                partition_rows
            )
            or witness["max_targets_per_child"] != max_targets
            or type(witness["rationale"]) is not str
            or not witness["rationale"]
            or type(witness["falsifier"]) is not str
            or not witness["falsifier"]
        ):
            raise EvidenceFailed("exact packing witness scalar contract differs")
        optimum = v2_independent_exact_optimum(
            expected_ids=expected_ids,
            load_by_id=load_by_id,
            row_by_id=row_by_id,
            max_targets=max_targets,
        )
        if (
            v2_independent_partition_objective(memberships, load_by_id)
            != v2_independent_partition_objective(optimum, load_by_id)
            or witness["objective"] != observed_objective
        ):
            raise EvidenceFailed(
                "exact packing witness is not independently optimal"
            )
        return
    if algorithm == "DETERMINISTIC_LPT_VECTOR_PACKING":
        v2_exact_keys(
            witness,
            {
                "algorithm",
                "group_key_root",
                "ordered_load_rows_root",
                "lower_bound_children",
                "observed_children",
                "child_count_gap",
                "lower_bound_vector",
                "transport_constraint_root",
                "achieved_objective",
                "gap_witness",
                "exact_optimality_claim",
                "max_targets_per_child",
                "rationale",
                "falsifier",
                "semantic_root",
            },
            label="large packing witness",
        )
        total_minutes, total_bytes, _ = v2_independent_membership_load(
            expected_ids,
            load_by_id,
        )
        lower_bound_vector = {
            "targets": math.ceil(len(expected_ids) / max_targets),
            "review_minutes": math.ceil(
                total_minutes / V2_REVIEW_MINUTES_CAP
            ),
            "retained_payload_bytes": math.ceil(
                total_bytes / V2_CHILD_PAYLOAD_CAP
            ),
        }
        lower_bound = max(
            lower_bound_vector["targets"],
            lower_bound_vector["review_minutes"],
            lower_bound_vector["retained_payload_bytes"],
            1,
        )
        observed_children = len(memberships)
        gap = observed_children - lower_bound
        expected_gap = {
            "child_count": gap,
            "maximum_review_minutes_above_average": (
                observed_objective["maximum_review_minutes"]
                - math.ceil(total_minutes / observed_children)
            ),
            "maximum_retained_bytes_above_average": (
                observed_objective["maximum_retained_payload_bytes"]
                - math.ceil(total_bytes / observed_children)
            ),
        }
        if (
            len(expected_ids) <= V2_EXACT_OPTIMALITY_MAX_TARGETS
            or witness["lower_bound_vector"] != lower_bound_vector
            or witness["transport_constraint_root"]
            != v2_partition_transport_constraint_root(
                partition_rows
            )
            or witness["lower_bound_children"] != lower_bound
            or witness["observed_children"] != observed_children
            or witness["child_count_gap"] != gap
            or witness["achieved_objective"] != observed_objective
            or witness["gap_witness"] != expected_gap
            or witness["exact_optimality_claim"] is not False
            or witness["max_targets_per_child"] != max_targets
            or gap < 0
            or min(expected_gap.values()) < 0
            or type(witness["rationale"]) is not str
            or not witness["rationale"]
            or type(witness["falsifier"]) is not str
            or not witness["falsifier"]
        ):
            raise EvidenceFailed("large packing witness arithmetic differs")
        return
    raise EvidenceFailed("independent packing verifier received an unknown algorithm")


def v2_review_plan_universe(
    inventory: Mapping[str, Any],
    authority: Mapping[str, Any],
    *,
    review_receipts: Any | None = None,
    allow_mechanical_fixture: bool = False,
) -> tuple[dict[str, Mapping[str, Any]], dict[str, Mapping[str, Any]]]:
    if type(inventory) is not dict or type(authority) is not dict:
        raise EvidenceFailed(
            "v2 review-plan inventory and authority roots must be exact objects"
        )
    if not (
        dict.__contains__(inventory, "rows")
        and dict.__contains__(inventory, "filters")
        and dict.__contains__(authority, "decisions")
    ):
        raise EvidenceFailed(
            "v2 review-plan inventory or authority lacks required collections"
        )
    inventory_rows = inventory["rows"]
    authority_decisions = authority["decisions"]
    if type(inventory_rows) is not list or type(authority_decisions) is not list:
        raise EvidenceFailed(
            "v2 review-plan inventory rows and authority decisions must be arrays"
        )
    if (
        len(inventory_rows) > V2_INVENTORY_ROWS_CAP
        or len(authority_decisions) > V2_INVENTORY_ROWS_CAP
    ):
        raise EvidenceFailed(
            "v2 review-plan source collections exceed the exact row cap"
        )
    if any(type(row) is not dict for row in inventory_rows) or any(
        type(row) is not dict for row in authority_decisions
    ):
        raise EvidenceFailed(
            "v2 review-plan inventory rows and authority decisions must contain "
            "exact objects"
        )

    # Detach the admitted source pair before any identity projection.  This
    # makes the planner consume one immutable exact-wire observation and also
    # rejects hook-bearing nested containers before they can influence cache
    # keys, sorting, or membership checks.
    source_pair = v2_released_json_snapshot(
        {
            "inventory": inventory,
            "authority": authority,
        },
        label="v2 review-plan source pair",
        error_type=EvidenceFailed,
    )
    if type(source_pair) is not dict:
        raise EvidenceFailed("v2 review-plan source pair is not an object")
    inventory = source_pair["inventory"]
    authority = source_pair["authority"]
    inventory = v2_validate_review_inventory(inventory)
    try:
        authority = _v2_validate_review_plan_authority_exact(
            authority,
            inventory,
        )
    except EvidenceFailed:
        raise
    except HarnessError as error:
        raise EvidenceFailed(
            "v2 review-plan authority nested contract is invalid"
        ) from error
    v2_validate_review_plan_receipt_provenance(
        authority,
        inventory,
        review_receipts=review_receipts,
        allow_mechanical_fixture=allow_mechanical_fixture,
    )
    inventory_rows = inventory["rows"]
    authority_decisions = authority["decisions"]

    inventory_ids: list[str] = []
    for index, row in enumerate(inventory_rows):
        if (
            not dict.__contains__(row, "id")
            or not dict.__contains__(row, "status")
            or type(row["id"]) is not str
            or not row["id"]
            or type(row["status"]) is not str
        ):
            raise EvidenceFailed(
                f"v2 review-plan inventory row {index} identity is malformed"
            )
        v2_validate_issue_id(
            row["id"],
            label=f"v2 review-plan inventory row {index} ID",
            error_type=EvidenceFailed,
        )
        verify_semantic_root(
            row,
            label=f"v2 review-plan inventory row {index}",
        )
        if (
            not dict.__contains__(row, "target_root")
            or type(row["target_root"]) is not str
            or not v2_is_semantic_root(row["target_root"])
        ):
            raise EvidenceFailed(
                f"v2 review-plan inventory row {index} target root is malformed"
            )
        inventory_ids.append(row["id"])
    if (
        inventory_ids != sorted(inventory_ids)
        or len(inventory_ids) != len(set(inventory_ids))
    ):
        raise EvidenceFailed(
            "v2 review-plan inventory IDs are noncanonical or duplicated"
        )

    authority_ids: list[str] = []
    for index, row in enumerate(authority_decisions):
        if (
            not dict.__contains__(row, "target_id")
            or not dict.__contains__(row, "target_root")
            or not dict.__contains__(row, "readiness")
            or not dict.__contains__(row, "remediation_route")
            or type(row["target_id"]) is not str
            or not row["target_id"]
            or type(row["target_root"]) is not str
            or not v2_is_semantic_root(row["target_root"])
            or type(row["readiness"]) is not str
            or type(row["remediation_route"]) is not str
        ):
            raise EvidenceFailed(
                f"v2 review-plan authority row {index} identity is malformed"
            )
        v2_validate_issue_id(
            row["target_id"],
            label=f"v2 review-plan authority row {index} target ID",
            error_type=EvidenceFailed,
        )
        verify_semantic_root(
            row,
            label=f"v2 review-plan authority row {index}",
        )
        authority_ids.append(row["target_id"])
    if (
        authority_ids != sorted(authority_ids)
        or len(authority_ids) != len(set(authority_ids))
    ):
        raise EvidenceFailed(
            "v2 review-plan authority IDs are noncanonical or duplicated"
        )
    if set(authority_ids) != set(inventory_ids):
        raise EvidenceFailed(
            "v2 review-plan full inventory and authority memberships differ"
        )
    if (
        not dict.__contains__(authority, "inventory_root")
        or authority["inventory_root"] != inventory["semantic_root"]
    ):
        raise EvidenceFailed(
            "v2 review-plan authority is not bound to its inventory root"
        )

    complete_targets = {row["id"]: row for row in inventory_rows}
    complete_authority = {
        row["target_id"]: row for row in authority_decisions
    }
    for target_id in inventory_ids:
        if (
            complete_authority[target_id]["target_root"]
            != complete_targets[target_id]["target_root"]
        ):
            raise EvidenceFailed(
                "v2 review-plan target and authority roots differ for "
                f"{target_id}"
            )

    # Closed targets remain part of the validated source universe and its
    # authority membership.  They are excluded only after that lossless
    # validation because a history row must never hide malformed authority.
    upstream_targets = {
        target_id: complete_targets[target_id]
        for target_id in inventory_ids
        if complete_targets[target_id]["status"] != "closed"
    }
    upstream_authority = {
        target_id: complete_authority[target_id]
        for target_id in inventory_ids
        if target_id in upstream_targets
    }
    if set(upstream_authority) != set(upstream_targets):
        raise EvidenceFailed(
            "v2 review-plan lacks an authority decision for its upstream universe"
        )
    filters = inventory["filters"]
    if type(filters) is not dict:
        raise EvidenceFailed("v2 review-plan inventory filters are malformed")
    if not (
        dict.__contains__(filters, "readiness")
        and dict.__contains__(filters, "routes")
    ):
        raise EvidenceFailed(
            "v2 review-plan inventory filters lack required fields"
        )
    readiness_values = filters["readiness"]
    route_values = filters["routes"]
    if (
        type(readiness_values) is not list
        or type(route_values) is not list
        or not all(type(value) is str for value in readiness_values)
        or not all(type(value) is str for value in route_values)
    ):
        raise EvidenceFailed(
            "v2 review-plan inventory filter values are malformed"
        )
    if (
        readiness_values != sorted(readiness_values)
        or len(readiness_values) != len(set(readiness_values))
        or route_values != sorted(route_values)
        or len(route_values) != len(set(route_values))
    ):
        raise EvidenceFailed(
            "v2 review-plan inventory filter values are noncanonical"
        )
    readiness = set(readiness_values)
    routes = set(route_values)
    selected_ids = sorted(
        target_id
        for target_id in upstream_authority
        if (
            not readiness
            or upstream_authority[target_id]["readiness"] in readiness
        )
        and (
            not routes
            or upstream_authority[target_id]["remediation_route"] in routes
        )
    )
    return (
        {
            target_id: upstream_targets[target_id]
            for target_id in selected_ids
        },
        {
            target_id: upstream_authority[target_id]
            for target_id in selected_ids
        },
    )


def v2_preflight_review_plan_collections(
    review_plan: Mapping[str, Any],
) -> tuple[
    list[dict[str, Any]],
    list[dict[str, Any]],
    list[dict[str, Any]],
    list[dict[str, Any]],
    list[dict[str, Any]],
    list[dict[str, Any]],
]:
    if type(review_plan) is not dict:
        raise EvidenceFailed("v2 review plan is not an exact object")
    bounded_fields = (
        ("children", "children"),
        ("packing_witnesses", "packing witnesses"),
        ("semantic_adjudications", "semantic adjudications"),
        (
            "retained_without_direct_child",
            "retained-without-direct-child rows",
        ),
        ("remediation_candidates", "remediation candidates"),
        ("oversize_content", "oversize registry"),
    )
    collections: list[list[dict[str, Any]]] = []
    for field, label in bounded_fields:
        if not dict.__contains__(review_plan, field):
            raise EvidenceFailed(f"v2 review-plan {label} are missing")
        rows = review_plan[field]
        if type(rows) is not list:
            raise EvidenceFailed(f"v2 review-plan {label} are malformed")
        if len(rows) > V2_INVENTORY_ROWS_CAP:
            raise EvidenceFailed(
                f"v2 review-plan {label} exceed the "
                f"{V2_INVENTORY_ROWS_CAP}-row cap"
            )
        if any(type(row) is not dict for row in rows):
            raise EvidenceFailed(f"v2 review-plan {label} are malformed")
        collections.append(rows)
    sized_review_plan = (
        review_plan
        if "semantic_root" in review_plan
        else {
            **review_plan,
            "semantic_root": V2_PACKING_PREFLIGHT_WITNESS_ROOT,
        }
    )
    v2_validate_canonical_byte_size(
        sized_review_plan,
        cap=RUN_ARTIFACT_CAP,
        label="v2 review plan",
    )
    return (
        collections[0],
        collections[1],
        collections[2],
        collections[3],
        collections[4],
        collections[5],
    )


def v2_validate_review_plan(
    review_plan: Mapping[str, Any],
    inventory: Mapping[str, Any],
    authority: Mapping[str, Any],
    *,
    review_receipts: Any | None = None,
    allow_mechanical_fixture: bool = False,
) -> None:
    if type(review_plan) is not dict:
        raise EvidenceFailed("v2 review plan is not an object")
    v2_exact_keys(
        review_plan,
        V2_REVIEW_PLAN_FIELDS,
        label="v2 review plan",
    )
    (
        children,
        witnesses,
        adjudications,
        retained_without_direct_child,
        remediation_candidates,
        oversize_content,
    ) = v2_preflight_review_plan_collections(review_plan)
    verify_semantic_root(review_plan, label="v2 review plan")
    counts = review_plan["counts"]
    work = review_plan["work"]
    if type(counts) is not dict or type(work) is not dict:
        raise EvidenceFailed("v2 review-plan counts or work projection is malformed")
    v2_exact_keys(
        counts,
        V2_REVIEW_PLAN_COUNT_FIELDS,
        label="v2 review-plan counts",
    )
    v2_exact_keys(
        work,
        V2_REVIEW_PLAN_WORK_FIELDS,
        label="v2 review-plan work",
    )
    if (
        type(inventory) is not dict
        or type(authority) is not dict
        or not dict.__contains__(inventory, "semantic_root")
        or not dict.__contains__(inventory, "campaign_epoch_root")
        or not dict.__contains__(authority, "semantic_root")
    ):
        raise EvidenceFailed(
            "v2 review-plan source roots are missing or malformed"
        )
    if (
        review_plan["schema"] != V2_REVIEW_PLAN_SCHEMA
        or review_plan["state"] != "POPULATED"
        or review_plan["inventory_root"] != inventory["semantic_root"]
        or review_plan["authority_root"] != authority["semantic_root"]
        or review_plan["campaign_epoch_root"]
        != inventory["campaign_epoch_root"]
        or review_plan["hard_max_targets_per_child"]
        != V2_REVIEW_TARGET_HARD_MAX
        or review_plan["review_minutes_cap"] != V2_REVIEW_MINUTES_CAP
        or review_plan["retained_child_bytes_cap"] != V2_CHILD_PAYLOAD_CAP
        or review_plan["no_claim"] != V2_REVIEW_PLAN_NO_CLAIM
    ):
        raise EvidenceFailed(
            "v2 review-plan identity, cap, or source bindings disagree"
        )
    witness_by_root: dict[str, Mapping[str, Any]] = {}
    for witness in witnesses:
        verify_semantic_root(witness, label="v2 packing witness")
        witness_root = str(witness["semantic_root"])
        if witness_root in witness_by_root:
            raise EvidenceFailed("v2 review-plan duplicates a packing witness")
        witness_by_root[witness_root] = witness
    target_by_id, authority_by_id = v2_review_plan_universe(
        inventory,
        authority,
        review_receipts=review_receipts,
        allow_mechanical_fixture=allow_mechanical_fixture,
    )
    expected_scheduled_ids = sorted(
        target_id
        for target_id, decision in authority_by_id.items()
        if decision["semantic_review_action"]
        != "RETAINED_ADJUDICATION"
    )
    expected_adjudications: list[dict[str, Any]] = []
    for target_id, decision in sorted(authority_by_id.items()):
        if (
            decision["semantic_review_receipt_state"]
            != "ROOT_BOUND_REVIEWED"
        ):
            continue
        expected_adjudications = [
            *expected_adjudications,
            v2_rooted(
                {
                    "target_id": target_id,
                    "target_root": target_by_id[target_id]["target_root"],
                    "authority_decision_root": decision["semantic_root"],
                    "semantic_review_disposition": decision[
                        "semantic_review_disposition"
                    ],
                    "semantic_review_receipt_state": decision[
                        "semantic_review_receipt_state"
                    ],
                    "semantic_review_action": decision[
                        "semantic_review_action"
                    ],
                    "semantic_review_receipt_root": decision[
                        "semantic_review_receipt_root"
                    ],
                    "reviewed_no_change_receipt_root": decision[
                        "reviewed_no_change_receipt_root"
                    ],
                    "future_corrective_materialization_eligible": (
                        decision["semantic_review_disposition"]
                        == "REMEDIATION_REQUIRED"
                    ),
                    "no_claim": (
                        "root-bound semantic adjudication is retained planning "
                        "evidence and does not itself mutate or complete a target"
                    ),
                }
            ),
        ]
    expected_retained = [
        row
        for row in expected_adjudications
        if row["semantic_review_action"] == "RETAINED_ADJUDICATION"
    ]
    expected_remediation = [
        row
        for row in expected_adjudications
        if row["future_corrective_materialization_eligible"]
    ]
    if (
        adjudications != expected_adjudications
        or retained_without_direct_child != expected_retained
        or remediation_candidates != expected_remediation
    ):
        raise EvidenceFailed(
            "v2 review-plan semantic adjudication projection differs"
        )
    observed_ids: list[str] = []
    for child in children:
        v2_validate_child_payload(child)
        ids = child["target_ids"]
        roots = child["target_roots"]
        if any(target_id not in target_by_id for target_id in ids):
            raise EvidenceFailed("v2 review-plan child substitutes an unknown target")
        expected_roots = [target_by_id[target_id]["target_root"] for target_id in ids]
        if roots != expected_roots:
            raise EvidenceFailed("v2 review-plan child target roots disagree")
        for target_id in ids:
            target = target_by_id[target_id]
            decision = authority_by_id[target_id]
            expected_vector = v2_hard_vector(target, decision)
            observed_vector = (
                child["priority"],
                target["status"],
                child["disposition_workflow"],
                target["type"],
                tuple(target["missing_sections"]),
                child["semantic_review_disposition"],
                child["semantic_review_receipt_state"],
                child["semantic_review_action"],
                child["readiness"],
                child["remediation_route"],
                child["desired_status"],
            )
            if child["disposition_workflow"] == "OVERSIZE_REVIEW_REQUIRED":
                observed_vector = (
                    child["priority"],
                    target["status"],
                    target["disposition"],
                    target["type"],
                    tuple(target["missing_sections"]),
                    child["semantic_review_disposition"],
                    child["semantic_review_receipt_state"],
                    child["semantic_review_action"],
                    child["readiness"],
                    child["remediation_route"],
                    child["desired_status"],
                )
            if observed_vector != expected_vector:
                raise EvidenceFailed(
                    "v2 review-plan child crosses a hard partition vector"
                )
        observed_ids = [*observed_ids, *ids]
    expected_ids = expected_scheduled_ids
    if (
        sorted(observed_ids) != expected_ids
        or len(observed_ids) != len(set(observed_ids))
    ):
        raise EvidenceFailed(
            "v2 review-plan target mapping is dropped, duplicated, or substituted"
        )
    retained_ids = sorted(
        row["target_id"] for row in expected_retained
    )
    if sorted([*observed_ids, *retained_ids]) != sorted(target_by_id):
        raise EvidenceFailed(
            "v2 review-plan scheduled and retained target universe differs"
        )
    if (
        counts["targets"] != len(target_by_id)
        or counts["scheduled_targets"] != len(expected_ids)
        or counts["retained_without_direct_child"]
        != len(expected_retained)
        or counts["semantic_adjudications"]
        != len(expected_adjudications)
        or counts["remediation_candidates"]
        != len(expected_remediation)
    ):
        raise EvidenceFailed("v2 review-plan target counts disagree with membership")
    children_by_witness: dict[
        str,
        tuple[Mapping[str, Any], ...],
    ] = {}
    for child in children:
        witness_root = str(child["packing_witness_root"])
        if witness_root not in witness_by_root:
            raise EvidenceFailed(
                "v2 review-plan child references an unknown packing witness"
            )
        prior_children = (
            children_by_witness[witness_root]
            if dict.__contains__(children_by_witness, witness_root)
            else ()
        )
        children_by_witness[witness_root] = (*prior_children, child)
    if set(children_by_witness) != set(witness_by_root):
        raise EvidenceFailed("v2 review-plan retains an unused packing witness")
    max_targets = review_plan["max_targets_per_child"]
    if (
        type(max_targets) is not int
        or not 1 <= max_targets <= V2_REVIEW_TARGET_HARD_MAX
    ):
        raise EvidenceFailed("v2 review-plan target cap is malformed")
    oversize_by_target: dict[str, Mapping[str, Any]] = {}
    oversize_paths: dict[str, None] = {}
    for index, entry in enumerate(oversize_content):
        if not isinstance(entry, dict):
            raise EvidenceFailed(
                f"v2 review-plan oversize row {index} is malformed"
            )
        v2_exact_keys(
            entry,
            V2_OVERSIZE_REGISTRY_FIELDS,
            label=f"v2 review-plan oversize row {index}",
        )
        target_roots = entry["target_roots"]
        if (
            not isinstance(target_roots, list)
            or len(target_roots) != 1
            or not isinstance(target_roots[0], str)
        ):
            raise EvidenceFailed(
                f"v2 review-plan oversize row {index} has malformed target roots"
            )
        target_root = target_roots[0]
        matching_targets = [
            target
            for target in target_by_id.values()
            if target["target_root"] == target_root
        ]
        if len(matching_targets) != 1:
            raise EvidenceFailed(
                f"v2 review-plan oversize row {index} names an unknown target"
            )
        target = matching_targets[0]
        decision = authority_by_id[target["id"]]
        expected_exceeded = v2_oversize_exceeded_caps(target, decision)
        relative = str(
            safe_relative(
                entry["relative_path"],
                label=f"v2 review-plan oversize row {index}",
            )
        )
        target_root_text = target_root
        if V2_SEMANTIC_ROOT_PATTERN.fullmatch(target_root_text) is None:
            raise EvidenceFailed(
                f"v2 review-plan oversize row {index} target root is malformed"
            )
        expected_relative = (
            "oversize/"
            f"{target_root_text[len('sha256-v1:'):]}.json"
        )
        if (
            target_root in oversize_by_target
            or relative in oversize_paths
            or relative != expected_relative
            or entry["media_kind"] != "application/json"
            or entry["schema_kind"]
            != "frankensim.beads-template-hygiene.oversize-review.v2"
            or type(entry["byte_length"]) is not int
            or entry["byte_length"] < 0
            or type(entry["aggregate_cap_accounting"]) is not int
            or entry["aggregate_cap_accounting"] != entry["byte_length"]
            or type(entry["semantic_root"]) is not str
            or re.fullmatch(
                r"sha256-v1:[0-9a-f]{64}",
                entry["semantic_root"],
            )
            is None
            or entry["field_roots"] != target["field_roots"]
            or entry["clause_roots"] != target["clause_roots"]
            or entry["exceeded_caps"] != expected_exceeded
            or not expected_exceeded
        ):
            raise EvidenceFailed(
                f"v2 review-plan oversize row {index} differs from its target"
            )
        oversize_by_target[target_root] = entry
        oversize_paths[relative] = None
    expected_oversize_roots = {
        target_by_id[target_id]["target_root"]
        for target_id in expected_scheduled_ids
        if v2_oversize_exceeded_caps(
            target_by_id[target_id],
            authority_by_id[target_id],
        )
    }
    if set(oversize_by_target) != expected_oversize_roots:
        raise EvidenceFailed(
            "v2 review-plan oversize registry membership differs from source"
        )
    if (
        children
        != sorted(
            children,
            key=lambda child: (child["priority"], child["child_key"]),
        )
        or witnesses
        != sorted(witnesses, key=lambda witness: witness["semantic_root"])
        or oversize_content
        != sorted(
            oversize_content,
            key=lambda entry: entry["relative_path"],
        )
    ):
        raise EvidenceFailed(
            "v2 review-plan child, witness, or oversize ordering is noncanonical"
        )
    for witness_root, grouped_children in children_by_witness.items():
        witness = witness_by_root[witness_root]
        if (
            type(witness) is not dict
            or not dict.__contains__(witness, "algorithm")
            or type(witness["algorithm"]) is not str
        ):
            raise EvidenceFailed("v2 packing witness algorithm is malformed")
        algorithm = witness["algorithm"]
        grouped_ids = sorted(
            target_id
            for child in grouped_children
            for target_id in child["target_ids"]
        )
        if algorithm == "OVERSIZE_ESCALATION":
            v2_exact_keys(
                witness,
                V2_OVERSIZE_WITNESS_FIELDS,
                label="oversize packing witness",
            )
            if (
                len(grouped_children) != 1
                or len(grouped_ids) != 1
                or witness["target_id"] != grouped_ids[0]
                or grouped_children[0]["disposition_workflow"]
                != "OVERSIZE_REVIEW_REQUIRED"
                or witness["exact_optimality_claim"] is not False
                or type(witness["reason"]) is not str
                or not witness["reason"]
            ):
                raise EvidenceFailed(
                    "v2 oversize witness membership or disposition disagrees"
                )
            target_root = target_by_id[grouped_ids[0]]["target_root"]
            if not dict.__contains__(oversize_by_target, target_root):
                raise EvidenceFailed(
                    "v2 oversize witness lacks its registered artifact"
                )
            entry = oversize_by_target[target_root]
            oversize_rows = [
                (
                    target_by_id[grouped_ids[0]],
                    authority_by_id[grouped_ids[0]],
                )
            ]
            group_key_root, ordered_load_rows_root = (
                v2_packing_input_bindings(oversize_rows)
            )
            expected_exceeded_caps = v2_oversize_exceeded_caps(
                oversize_rows[0][0],
                oversize_rows[0][1],
            )
            if (
                type(entry) is not dict
                or witness["full_artifact_root"]
                != entry["semantic_root"]
                or witness["group_key_root"] != group_key_root
                or witness["ordered_load_rows_root"]
                != ordered_load_rows_root
                or witness["exceeded_caps"]
                != expected_exceeded_caps
                or entry["exceeded_caps"]
                != expected_exceeded_caps
                or witness["reason"]
                != (
                    "single target exceeds "
                    + ", ".join(
                        row["cap"] for row in expected_exceeded_caps
                    )
                )
            ):
                raise EvidenceFailed(
                    "v2 oversize witness is not bound to its registered artifact"
                )
            continue
        if algorithm not in {
            "EXACT_SUBSET_PARTITION",
            "DETERMINISTIC_LPT_VECTOR_PACKING",
        }:
            raise EvidenceFailed("v2 packing witness uses an unknown algorithm")
        grouped_rows = [
            (target_by_id[target_id], authority_by_id[target_id])
            for target_id in grouped_ids
        ]
        v2_verify_packing_witness_independent(
            rows=grouped_rows,
            grouped_children=grouped_children,
            witness=witness,
            max_targets=max_targets,
        )
    for child in children:
        child_ids = list(child["target_ids"])
        witness = witness_by_root[str(child["packing_witness_root"])]
        child_rows = [
            (target_by_id[target_id], authority_by_id[target_id])
            for target_id in child_ids
        ]
        if witness["algorithm"] == "OVERSIZE_ESCALATION":
            target_root = target_by_id[child_ids[0]]["target_root"]
            if not dict.__contains__(oversize_by_target, target_root):
                raise EvidenceFailed(
                    "v2 oversize child lacks its registered artifact"
                )
            expected_child = v2_make_child(
                child_rows,
                packing_witness=witness,
                oversize=True,
                oversize_artifact=oversize_by_target[target_root],
            )
        else:
            expected_child = v2_make_child(
                child_rows,
                packing_witness=witness,
            )
        if child != expected_child:
            divergence = first_projection_divergence(
                expected_child,
                child,
            )
            raise EvidenceFailed(
                "v2 review-plan child differs from its exact source-derived "
                f"projection at {divergence or '$'}"
            )
    expected_readiness_counts: dict[str, int] = {}
    expected_route_counts: dict[str, int] = {}
    for target_id in authority_by_id:
        decision = authority_by_id[target_id]
        readiness_value = decision["readiness"]
        route_value = decision["remediation_route"]
        expected_readiness_counts[readiness_value] = (
            expected_readiness_counts[readiness_value]
            if dict.__contains__(
                expected_readiness_counts,
                readiness_value,
            )
            else 0
        ) + 1
        expected_route_counts[route_value] = (
            expected_route_counts[route_value]
            if dict.__contains__(expected_route_counts, route_value)
            else 0
        ) + 1
    expected_counts = {
        "targets": len(target_by_id),
        "scheduled_targets": len(expected_ids),
        "retained_without_direct_child": len(expected_retained),
        "semantic_adjudications": len(expected_adjudications),
        "remediation_candidates": len(expected_remediation),
        "children": len(children),
        "oversize_targets": len(expected_oversize_roots),
        "readiness": {
            key: expected_readiness_counts[key]
            for key in sorted(expected_readiness_counts)
        },
        "routes": {
            key: expected_route_counts[key]
            for key in sorted(expected_route_counts)
        },
    }
    expected_work = {
        "total_review_minutes": sum(
            int(authority_by_id[target_id]["review_minutes"])
            for target_id in expected_ids
        ),
        "total_bounded_child_review_minutes": sum(
            int(child["review_minutes"]) for child in children
        ),
        "total_underlying_target_review_minutes": sum(
            int(decision["review_minutes"])
            for decision in authority_by_id.values()
        ),
        "total_completed_adjudication_minutes": sum(
            int(authority_by_id[row["target_id"]]["review_minutes"])
            for row in expected_retained
        ),
        "minimum_child_review_minutes": min(
            (int(child["review_minutes"]) for child in children),
            default=0,
        ),
        "maximum_child_review_minutes": max(
            (int(child["review_minutes"]) for child in children),
            default=0,
        ),
    }
    if counts != expected_counts or work != expected_work:
        divergence = first_projection_divergence(
            {"counts": expected_counts, "work": expected_work},
            {"counts": counts, "work": work},
        )
        raise EvidenceFailed(
            "v2 review-plan count or work projection differs at "
            f"{divergence or '$'}"
        )


def v2_oversize_exceeded_caps(
    target: Mapping[str, Any],
    authority: Mapping[str, Any],
) -> list[dict[str, Any]]:
    candidates = [
        (
            "max_review_minutes_per_child",
            "authority.review_minutes",
            int(authority["review_minutes"]),
            V2_REVIEW_MINUTES_CAP,
        ),
        (
            "max_retained_child_payload_bytes",
            "target.retained_payload_bytes",
            int(target["retained_payload_bytes"]),
            V2_CHILD_PAYLOAD_CAP,
        ),
        (
            "max_description_bytes",
            "target.field_byte_lengths.description",
            int(target["field_byte_lengths"]["description"]),
            V2_CHILD_DESCRIPTION_CAP,
        ),
        (
            "max_acceptance_bytes",
            "target.field_byte_lengths.acceptance_criteria",
            int(target["field_byte_lengths"]["acceptance_criteria"]),
            V2_CHILD_ACCEPTANCE_CAP,
        ),
        (
            "max_design_bytes",
            "target.field_byte_lengths.design",
            int(target["field_byte_lengths"]["design"]),
            V2_CHILD_DESIGN_CAP,
        ),
        (
            "max_notes_bytes",
            "target.field_byte_lengths.notes",
            int(target["field_byte_lengths"]["notes"]),
            V2_CHILD_NOTES_CAP,
        ),
    ]
    exceeded = [
        {
            "cap": cap_name,
            "source_path": source_path,
            "observed": observed,
            "limit": limit,
            "violation_count": 1,
            "violating_membership_root": semantic_root(
                [
                    {
                        "source_path": source_path,
                        "observed": observed,
                    }
                ]
            ),
        }
        for cap_name, source_path, observed, limit in candidates
        if observed > limit
    ]
    exceeded = [
        *exceeded,
        *v2_child_transport_violations([(target, authority)]),
    ]
    clause_index = target["clause_roots"]
    v2_validate_clause_index(clause_index)
    if clause_index["row_count"] > V2_CLAUSE_ROWS_CAP:
        exceeded = [
            *exceeded,
            {
                "cap": "max_clause_rows_per_issue",
                "source_path": "target.clause_roots.row_count",
                "observed": int(clause_index["row_count"]),
                "limit": V2_CLAUSE_ROWS_CAP,
                "violation_count": (
                    int(clause_index["row_count"]) - V2_CLAUSE_ROWS_CAP
                ),
                "violating_membership_root": str(
                    clause_index["over_row_cap_membership_root"]
                ),
            },
        ]
    if clause_index["over_byte_cap_count"]:
        exceeded = [
            *exceeded,
            {
                "cap": "max_clause_bytes",
                "source_path": "target.clause_roots.maximum_clause_bytes",
                "observed": int(clause_index["maximum_clause_bytes"]),
                "limit": V2_CLAUSE_BYTES_CAP,
                "violation_count": int(
                    clause_index["over_byte_cap_count"]
                ),
                "violating_membership_root": str(
                    clause_index["over_byte_cap_membership_root"]
                ),
            },
        ]
    for index, row in enumerate(exceeded):
        if (
            type(row) is not dict
            or set(row) != V2_OVERSIZE_EXCEEDED_CAP_FIELDS
            or type(row["cap"]) is not str
            or type(row["source_path"]) is not str
        ):
            raise EvidenceFailed(
                f"v2 oversize cap diagnostic {index} is malformed"
            )
    canonical_order = (
        (
            "max_acceptance_bytes",
            "rendered_child.acceptance_bytes",
        ),
        (
            "max_acceptance_bytes",
            "target.field_byte_lengths.acceptance_criteria",
        ),
        (
            "max_aggregate_non_description_argv_bytes",
            "rendered_child.aggregate_non_description_argv_bytes",
        ),
        (
            "max_clause_bytes",
            "target.clause_roots.maximum_clause_bytes",
        ),
        (
            "max_clause_rows_per_issue",
            "target.clause_roots.row_count",
        ),
        (
            "max_description_bytes",
            "rendered_child.description_bytes",
        ),
        (
            "max_description_bytes",
            "target.field_byte_lengths.description",
        ),
        (
            "max_design_bytes",
            "rendered_child.design_bytes",
        ),
        (
            "max_design_bytes",
            "target.field_byte_lengths.design",
        ),
        (
            "max_generated_child_payload_bytes",
            "rendered_child.generated_child_payload_bytes",
        ),
        (
            "max_notes_bytes",
            "rendered_child.notes_bytes",
        ),
        (
            "max_notes_bytes",
            "target.field_byte_lengths.notes",
        ),
        (
            "max_retained_child_payload_bytes",
            "target.retained_payload_bytes",
        ),
        (
            "max_review_minutes_per_child",
            "authority.review_minutes",
        ),
    )
    ordered_exceeded: list[dict[str, Any]] = []
    for cap_name, source_path in canonical_order:
        matching_count = 0
        for row in exceeded:
            if row["cap"] == cap_name and row["source_path"] == source_path:
                ordered_exceeded.append(row)
                matching_count += 1
        if matching_count > 1:
            raise EvidenceFailed(
                "v2 oversize cap diagnostics duplicate a canonical slot"
            )
    if len(ordered_exceeded) != len(exceeded):
        raise EvidenceFailed(
            "v2 oversize cap diagnostic escaped the canonical order"
        )
    return ordered_exceeded


def v2_build_review_plan_uncommitted(
    inventory: Mapping[str, Any],
    authority: Mapping[str, Any],
    *,
    max_targets: int,
    review_receipts: Any | None = None,
    allow_mechanical_fixture: bool = False,
) -> tuple[dict[str, Any], dict[str, bytes]]:
    all_target_by_id, all_authority_by_id = v2_review_plan_universe(
        inventory,
        authority,
        review_receipts=review_receipts,
        allow_mechanical_fixture=allow_mechanical_fixture,
    )
    scheduled_ids = sorted(
        target_id
        for target_id, decision in all_authority_by_id.items()
        if decision["semantic_review_action"]
        != "RETAINED_ADJUDICATION"
    )
    target_by_id = {
        target_id: all_target_by_id[target_id] for target_id in scheduled_ids
    }
    authority_by_id = {
        target_id: all_authority_by_id[target_id]
        for target_id in scheduled_ids
    }
    semantic_adjudications = [
        v2_rooted(
            {
                "target_id": target_id,
                "target_root": all_target_by_id[target_id]["target_root"],
                "authority_decision_root": decision["semantic_root"],
                "semantic_review_disposition": decision[
                    "semantic_review_disposition"
                ],
                "semantic_review_receipt_state": decision[
                    "semantic_review_receipt_state"
                ],
                "semantic_review_action": decision[
                    "semantic_review_action"
                ],
                "semantic_review_receipt_root": decision[
                    "semantic_review_receipt_root"
                ],
                "reviewed_no_change_receipt_root": decision[
                    "reviewed_no_change_receipt_root"
                ],
                "future_corrective_materialization_eligible": (
                    decision["semantic_review_receipt_state"]
                    == "ROOT_BOUND_REVIEWED"
                    and decision["semantic_review_disposition"]
                    == "REMEDIATION_REQUIRED"
                ),
                "no_claim": (
                    "root-bound semantic adjudication is retained planning "
                    "evidence and does not itself mutate or complete a target"
                ),
            }
        )
        for target_id, decision in sorted(all_authority_by_id.items())
        if decision["semantic_review_receipt_state"]
        == "ROOT_BOUND_REVIEWED"
    ]
    retained_without_direct_child = [
        row
        for row in semantic_adjudications
        if row["semantic_review_action"] == "RETAINED_ADJUDICATION"
    ]
    remediation_candidates = [
        row
        for row in semantic_adjudications
        if row["future_corrective_materialization_eligible"]
    ]
    group_rows: list[
        tuple[
            tuple[Any, ...],
            Mapping[str, Any],
            Mapping[str, Any],
        ]
    ] = []
    oversize_rows: list[tuple[Mapping[str, Any], Mapping[str, Any]]] = []
    for target_id in scheduled_ids:
        target = target_by_id[target_id]
        decision = authority_by_id[target_id]
        if v2_oversize_exceeded_caps(target, decision):
            oversize_rows.append((target, decision))
            continue
        key = v2_packing_group_key(target, decision)
        group_rows.append((key, target, decision))

    # Materialize every bucket before filling any bucket.  Besides preserving
    # linear-time grouping, this gives the refusal dataflow an exact invariant:
    # every value in the local map is a fresh base list, with no loop-carried
    # empty-map branch that could masquerade as an arbitrary append receiver.
    groups: dict[
        tuple[Any, ...],
        tuple[tuple[Mapping[str, Any], Mapping[str, Any]], ...],
    ] = {key: () for key, _target, _decision in group_rows}
    for key, target, decision in group_rows:
        groups[key] = (
            *dict.__getitem__(groups, key),
            (target, decision),
        )

    children: list[dict[str, Any]] = []
    packing_witnesses: list[dict[str, Any]] = []
    for key in sorted(groups, key=lambda value: repr(value)):
        rows = groups[key]
        bins, witness = v2_pack_group(rows, max_targets=max_targets)
        packing_witnesses.append(witness)
        for batch in bins:
            children.append(
                v2_make_child(batch, packing_witness=witness)
            )

    oversize_payloads: dict[str, bytes] = {}
    oversize_inventory: list[dict[str, Any]] = []
    for target, decision in oversize_rows:
        exceeded_caps = v2_oversize_exceeded_caps(target, decision)
        if not exceeded_caps:
            raise EvidenceFailed(
                "v2 oversize routing lacks an independently exceeded cap"
            )
        target_root_text = target["target_root"]
        if (
            type(target_root_text) is not str
            or V2_SEMANTIC_ROOT_PATTERN.fullmatch(target_root_text) is None
        ):
            raise EvidenceFailed("v2 oversize target root is malformed")
        relative = (
            "oversize/"
            f"{target_root_text[len('sha256-v1:'):]}.json"
        )
        complete_plan = {
            "target": target,
            "authority": decision,
            "actual_review_minutes": int(decision["review_minutes"]),
        }
        complete_plan_root = semantic_root(complete_plan)
        full = v2_rooted(
            {
                "schema": (
                    "frankensim.beads-template-hygiene.oversize-review.v2"
                ),
                "source_roots": [
                    target["target_root"],
                    target["v1_row_root"],
                    target["campaign_epoch_root"],
                ],
                "field_roots": target["field_roots"],
                "clause_roots": target["clause_roots"],
                "exceeded_caps": exceeded_caps,
                "bounded_incomplete_index": {
                    "complete": False,
                    "target_id": target["id"],
                    "missing_sections": target["missing_sections"],
                },
                "canonical_br_show_argv": [
                    "br",
                    "show",
                    target["id"],
                    "--json",
                    *BR_READ_FLAGS,
                ],
                "retained_full_plan_path": relative,
                "retained_full_plan_root": complete_plan_root,
                "complete_plan": complete_plan,
                "owner_questions": list(V2_OVERSIZE_OWNER_QUESTIONS),
                "no_claim": V2_OVERSIZE_NO_CLAIM,
            }
        )
        payload = canonical_bytes(full)
        oversize_payloads[relative] = payload
        entry = {
            "relative_path": relative,
            "media_kind": "application/json",
            "schema_kind": full["schema"],
            "byte_length": len(payload),
            "semantic_root": full["semantic_root"],
            "target_roots": [target["target_root"]],
            "field_roots": target["field_roots"],
            "clause_roots": target["clause_roots"],
            "exceeded_caps": exceeded_caps,
            "aggregate_cap_accounting": len(payload),
        }
        oversize_transport_violations = v2_child_transport_violations(
            [(target, decision)],
            oversize=True,
            oversize_artifact=entry,
        )
        if oversize_transport_violations:
            raise InputRefused(
                "UNREPRESENTABLE_CHILD_TRANSPORT: even the bounded oversize "
                "handoff exceeds "
                + ", ".join(
                    row["cap"] for row in oversize_transport_violations
                )
            )
        oversize_inventory.append(entry)
        group_key_root, ordered_load_rows_root = v2_packing_input_bindings(
            [(target, decision)]
        )
        witness = v2_rooted(
            {
                "algorithm": "OVERSIZE_ESCALATION",
                "group_key_root": group_key_root,
                "ordered_load_rows_root": ordered_load_rows_root,
                "target_id": target["id"],
                "exceeded_caps": exceeded_caps,
                "reason": (
                    "single target exceeds "
                    + ", ".join(row["cap"] for row in exceeded_caps)
                ),
                "full_artifact_root": full["semantic_root"],
                "exact_optimality_claim": False,
            }
        )
        packing_witnesses.append(witness)
        children.append(
            v2_make_child(
                [(target, decision)],
                packing_witness=witness,
                oversize=True,
                oversize_artifact=entry,
            )
        )

    children = sorted(
        children,
        key=lambda child: (child["priority"], child["child_key"]),
    )
    mapped_ids = [target_id for child in children for target_id in child["target_ids"]]
    expected_scheduled_ids = scheduled_ids
    if (
        sorted(mapped_ids) != expected_scheduled_ids
        or len(mapped_ids) != len(set(mapped_ids))
    ):
        raise EvidenceFailed(
            "v2 plan does not exact-map every scheduled target once"
        )
    retained_ids = sorted(
        row["target_id"] for row in retained_without_direct_child
    )
    if (
        sorted([*mapped_ids, *retained_ids])
        != sorted(all_target_by_id)
        or set(mapped_ids) & set(retained_ids)
    ):
        raise EvidenceFailed(
            "v2 plan does not exactly partition scheduled and retained targets"
        )
    document = {
        "schema": V2_REVIEW_PLAN_SCHEMA,
        "state": "POPULATED",
        "inventory_root": inventory["semantic_root"],
        "authority_root": authority["semantic_root"],
        "campaign_epoch_root": inventory["campaign_epoch_root"],
        "max_targets_per_child": max_targets,
        "hard_max_targets_per_child": V2_REVIEW_TARGET_HARD_MAX,
        "review_minutes_cap": V2_REVIEW_MINUTES_CAP,
        "retained_child_bytes_cap": V2_CHILD_PAYLOAD_CAP,
        "children": children,
        "semantic_adjudications": semantic_adjudications,
        "retained_without_direct_child": retained_without_direct_child,
        "remediation_candidates": remediation_candidates,
        "packing_witnesses": sorted(
            packing_witnesses, key=lambda row: row["semantic_root"]
        ),
        "oversize_content": sorted(
            oversize_inventory, key=lambda row: row["relative_path"]
        ),
        "counts": {
            "targets": len(all_target_by_id),
            "scheduled_targets": len(expected_scheduled_ids),
            "retained_without_direct_child": len(
                retained_without_direct_child
            ),
            "semantic_adjudications": len(semantic_adjudications),
            "remediation_candidates": len(remediation_candidates),
            "children": len(children),
            "oversize_targets": len(oversize_rows),
            "readiness": dict(sorted(Counter(
                decision["readiness"]
                for decision in all_authority_by_id.values()
            ).items())),
            "routes": dict(sorted(Counter(
                decision["remediation_route"]
                for decision in all_authority_by_id.values()
            ).items())),
        },
        "work": {
            "total_review_minutes": sum(
                int(decision["review_minutes"])
                for decision in authority_by_id.values()
            ),
            "total_bounded_child_review_minutes": sum(
                int(child["review_minutes"]) for child in children
            ),
            "total_underlying_target_review_minutes": sum(
                int(decision["review_minutes"])
                for decision in all_authority_by_id.values()
            ),
            "total_completed_adjudication_minutes": sum(
                int(all_authority_by_id[row["target_id"]]["review_minutes"])
                for row in retained_without_direct_child
            ),
            "minimum_child_review_minutes": min(
                (int(child["review_minutes"]) for child in children),
                default=0,
            ),
            "maximum_child_review_minutes": max(
                (int(child["review_minutes"]) for child in children),
                default=0,
            ),
        },
        "no_claim": V2_REVIEW_PLAN_NO_CLAIM,
    }
    v2_preflight_review_plan_collections(document)
    rooted = v2_rooted(document)
    v2_validate_review_plan(
        rooted,
        inventory,
        authority,
        review_receipts=review_receipts,
        allow_mechanical_fixture=allow_mechanical_fixture,
    )
    return rooted, oversize_payloads


def v2_build_review_plan(
    inventory: Mapping[str, Any],
    authority: Mapping[str, Any],
    *,
    max_targets: int,
    review_receipts: Any | None = None,
    allow_mechanical_fixture: bool = False,
) -> tuple[dict[str, Any], dict[str, bytes]]:
    # Transport observations are a successful-call performance cache, not a
    # side effect that a refused plan is allowed to retain.  Preserve both
    # entry values and LRU order across every exceptional exit.
    with _v2_child_transport_cache_lock:
        prior_transport_cache: list[
            tuple[
                tuple[Any, ...],
                tuple[
                    tuple[types.CodeType, ...],
                    str,
                    dict[str, int],
                ],
            ]
        ] = []
        for key, value in _v2_child_transport_cache.items():
            prior_transport_cache.append((key, value))
        try:
            return v2_build_review_plan_uncommitted(
                inventory,
                authority,
                max_targets=max_targets,
                review_receipts=review_receipts,
                allow_mechanical_fixture=allow_mechanical_fixture,
            )
        except BaseException:
            _v2_child_transport_cache.clear()
            _v2_child_transport_cache.update(prior_transport_cache)
            raise


def v2_reproduction_argv(
    *,
    mode: str,
    artifact_root: str,
    artifact_dir: str,
    review_receipts: str | None = None,
    prior_campaign: str | None = None,
    priorities: str | None = None,
    statuses: str | None = None,
    targets: str | None = None,
    readiness: str | None = None,
    routes: str | None = None,
    max_targets: int = V2_REVIEW_TARGET_DEFAULT,
    explain_target: str | None = None,
    replay_input: str | None = None,
) -> list[str]:
    if mode == "replay":
        if replay_input is None:
            raise EvidenceFailed("v2 replay reproduction lacks its input")
        return [
            str(SCRIPT_REL),
            "--replay-v2",
            str(safe_relative(replay_input, label="replay input")),
            "--artifact-root",
            str(safe_relative(artifact_root, label="artifact root")),
            "--artifact-dir",
            str(safe_relative(artifact_dir, label="artifact dir")),
        ]
    flag = {
        "review-plan": "--review-plan",
        "history-plan": "--history-plan",
    }.get(mode)
    if flag is None:
        raise EvidenceFailed(f"unsupported v2 reproduction mode {mode}")
    argv = [
        str(SCRIPT_REL),
        flag,
        "--artifact-root",
        str(safe_relative(artifact_root, label="artifact root")),
        "--artifact-dir",
        str(safe_relative(artifact_dir, label="artifact dir")),
    ]
    for option, value in (
        ("--review-receipts", review_receipts),
        ("--prior-campaign", prior_campaign),
        ("--priorities", priorities),
        ("--statuses", statuses),
        ("--targets", targets),
        ("--readiness", readiness),
        ("--routes", routes),
        ("--explain-target", explain_target),
    ):
        if value is not None:
            argv.extend((option, value))
    if max_targets != V2_REVIEW_TARGET_DEFAULT:
        argv.extend(("--max-targets-per-child", str(max_targets)))
    return argv


V2_SENSITIVE_KEY_TERMINALS = frozenset(
    {"password", "passwd", "secret", "credential", "token"}
)
V2_SENSITIVE_KEYS = frozenset(
    {
        "api_key",
        "access_key_id",
        "private_key",
        "secret_access_key",
        "authorization",
        "proxy_authorization",
    }
)
V2_SENSITIVE_COMPACT_KEYS = frozenset(
    {
        "apikey",
        "accesskeyid",
        "privatekey",
        "secretaccesskey",
        "clientsecret",
        "accesstoken",
        "refreshtoken",
    }
)
V2_SENSITIVE_COMPOUND_KEYS = frozenset(
    {
        "secret_key",
        "token_value",
        "password_value",
        "credential_value",
    }
)
V2_ABSOLUTE_PATH_ROOT_PATTERN = (
    r"(?i)(?<![A-Za-z0-9_.:/-])"
    r"(?<!<repo>)"
    r"(?:[A-Z]:[\\/]|\\\\|/(?=[A-Za-z0-9_.~-]))"
)


def v2_is_sensitive_key(value: Any) -> bool:
    if type(value) is not str:
        raise EvidenceFailed("sensitive-key classification requires exact text")
    stripped_value = value.strip()
    first_boundary_normalized = re.sub(
        r"(?<=[A-Z])(?=[A-Z][a-z])",
        "_",
        stripped_value,
    )
    second_boundary_normalized = re.sub(
        r"(?<=[a-z0-9])(?=[A-Z])",
        "_",
        first_boundary_normalized,
    )
    lowered = str.lower(second_boundary_normalized)
    hyphen_normalized = str.replace(lowered, "-", "_")
    whitespace_normalized = re.sub(r"\s+", "_", hyphen_normalized)
    normalized = str.lstrip(whitespace_normalized, "_")
    segments = [
        segment
        for segment in re.split(r"[./:\[\]]+", normalized)
        if segment
    ]
    if not segments:
        return False

    for segment in segments:
        candidate = segment
        while True:
            compact_candidate = str.replace(candidate, "_", "")
            candidate_parts = str.split(candidate, "_")
            sensitive_suffix = False
            for sensitive_key in V2_SENSITIVE_KEYS:
                if str.endswith(candidate, "_" + sensitive_key):
                    sensitive_suffix = True
                    break
            if (
                candidate in V2_SENSITIVE_KEYS
                or candidate in V2_SENSITIVE_COMPOUND_KEYS
                or compact_candidate in V2_SENSITIVE_COMPACT_KEYS
                or sensitive_suffix
                or candidate_parts[-1] in V2_SENSITIVE_KEY_TERMINALS
            ):
                return True
            if not str.endswith(candidate, "_value"):
                break
            candidate = str.removesuffix(candidate, "_value")
    return False


def v2_contains_sensitive_context_start(value: str) -> bool:
    start_patterns: tuple[
        tuple[re.Pattern[str], str], ...
    ] = (
        (
            re.compile(
                r"(?P<key>[A-Za-z_][-A-Za-z0-9_.:\[\]]{0,127})"
                r"\s*[:=]\s*"
            ),
            "DIRECT",
        ),
        (
            re.compile(
                r"(?P<key_quote>[\"'])"
                r"(?P<key>[A-Za-z_][-A-Za-z0-9_.: \[\]]{0,127})"
                r"(?P=key_quote)\s*:\s*"
            ),
            "DIRECT",
        ),
        (
            re.compile(
                r"(?<![A-Za-z0-9_-])"
                r"(?P<key>--?[A-Za-z][-A-Za-z0-9_.\[\]]{0,127})\s+"
            ),
            "DASH_STRIPPED",
        ),
        (
            re.compile(r"(?i)\b(?P<key>Bearer)\s+"),
            "ALWAYS",
        ),
    )
    for pattern, key_mode in start_patterns:
        for match in re.Pattern.finditer(pattern, value):
            candidate_key = match.group("key")
            if key_mode == "DIRECT":
                key_is_sensitive = v2_is_sensitive_key(candidate_key)
            elif key_mode == "DASH_STRIPPED":
                key_is_sensitive = v2_is_sensitive_key(
                    str.lstrip(candidate_key, "-")
                )
            elif key_mode == "ALWAYS":
                key_is_sensitive = True
            else:
                raise EvidenceFailed("sensitive-context key mode is unknown")
            if key_is_sensitive:
                return True
    return False


def v2_is_sensitive_mapping_key(value: str) -> bool:
    assignment_name = str.split(value, "=", 1)[0]
    if assignment_name != value and v2_is_sensitive_key(assignment_name):
        return True
    header_name = str.split(value, ":", 1)[0]
    if header_name != value and v2_is_sensitive_key(header_name):
        return True
    split_option_keys = re.findall(
        r"^--?([A-Za-z][-A-Za-z0-9_.\[\]]{0,127})\s+",
        value,
    )
    return v2_contains_sensitive_context_start(value) or bool(
        split_option_keys
        and v2_is_sensitive_key(split_option_keys[0])
    ) or re.match(r"(?i)^Bearer\s+\S+", value) is not None


def v2_redacted_value(value: str) -> str:
    if re.fullmatch(r"<redacted(?::[0-9a-f]{64})?>", value):
        return value
    return (
        "<redacted:"
        + hashlib.sha256(value.encode("utf-8")).hexdigest()
        + ">"
    )


def v2_contains_absolute_path(value: str) -> bool:
    if type(value) is not str:
        raise EvidenceFailed("absolute-path detection requires exact text")
    return bool(
        value.startswith("/")
        or REPO_ROOT_TEXT in value
        or re.search(V2_ABSOLUTE_PATH_ROOT_PATTERN, value)
    )


def v2_exact_redaction_interval(start: Any, end: Any) -> tuple[int, int]:
    if (
        type(start) is not int
        or type(end) is not int
        or start < 0
        or end < start
    ):
        raise EvidenceFailed("redaction interval is malformed")
    return start, end


def v2_redaction_intervals_overlap(
    left_end: Any,
    right_start: Any,
) -> bool:
    if type(left_end) is not int or type(right_start) is not int:
        raise EvidenceFailed("redaction overlap coordinates are malformed")
    return left_end >= right_start


def v2_exact_int_min(left: Any, right: Any) -> int:
    if type(left) is not int or type(right) is not int:
        raise EvidenceFailed("exact integer minimum inputs are malformed")
    return min(left, right)


def v2_exact_int_max(left: Any, right: Any) -> int:
    if type(left) is not int or type(right) is not int:
        raise EvidenceFailed("exact integer maximum inputs are malformed")
    return max(left, right)


def v2_exact_int_less(left: Any, right: Any) -> bool:
    if type(left) is not int or type(right) is not int:
        raise EvidenceFailed("exact integer comparison inputs are malformed")
    return left < right


def v2_exact_int_add(left: Any, right: Any) -> int:
    if type(left) is not int or type(right) is not int:
        raise EvidenceFailed("exact integer addition inputs are malformed")
    return left + right


def v2_exact_int_remaining(cap: Any, used: Any) -> int:
    if (
        type(cap) is not int
        or type(used) is not int
        or cap < 0
        or used < 0
        or used > cap
    ):
        raise EvidenceFailed("exact integer cap accounting inputs are malformed")
    return cap - used


def v2_exact_list_appended(values: Any, value: Any) -> list[Any]:
    if type(values) is not list:
        raise EvidenceFailed("exact immutable list append input is malformed")
    return [*values, value]


def v2_exact_str_equal(left: Any, right: Any) -> bool:
    if type(left) is not str or type(right) is not str:
        raise EvidenceFailed("exact string comparison inputs are malformed")
    return left == right


def v2_apply_redaction_interval(
    value: Any,
    start: Any,
    end: Any,
) -> str:
    if (
        type(value) is not str
        or type(start) is not int
        or type(end) is not int
        or start < 0
        or end < start
        or end > len(value)
    ):
        raise EvidenceFailed("redaction replacement inputs are malformed")
    return value[:start] + "<redacted>" + value[end:]


def v2_apply_absolute_path_interval(
    value: Any,
    start: Any,
    end: Any,
) -> str:
    if (
        type(value) is not str
        or type(start) is not int
        or type(end) is not int
        or start < 0
        or end < start
        or end > len(value)
    ):
        raise EvidenceFailed("absolute-path replacement inputs are malformed")
    return value[:start] + "<absolute-path>" + value[end:]


def v2_apply_exact_text_replacement(
    value: Any,
    start: Any,
    end: Any,
    replacement: Any,
) -> str:
    if (
        type(value) is not str
        or type(start) is not int
        or type(end) is not int
        or type(replacement) is not str
        or start < 0
        or end < start
        or end > len(value)
    ):
        raise EvidenceFailed("exact text replacement inputs are malformed")
    return value[:start] + replacement + value[end:]


def v2_redact_absolute_paths(value: Any) -> str:
    if type(value) is not str:
        raise EvidenceFailed("absolute-path redaction requires exact text")
    replacements: list[tuple[int, int]] = []
    consumed_until = -1
    root_pattern = re.compile(V2_ABSOLUTE_PATH_ROOT_PATTERN)
    for match in re.Pattern.finditer(root_pattern, value):
        path_start = match.start()
        if v2_exact_int_less(path_start, consumed_until):
            continue
        line_end = len(value)
        for separator in ("\r", "\n"):
            position = str.find(value, separator, match.end())
            if v2_redaction_intervals_overlap(position, 0):
                line_end = v2_exact_int_min(line_end, position)
        path_end = line_end
        quote_index = v2_exact_int_add(path_start, -1)
        if (
            v2_exact_int_less(0, path_start)
            and value[quote_index] in {'"', "'"}
        ):
            quote = value[quote_index]
            cursor = match.end()
            while v2_exact_int_less(cursor, line_end):
                if value[cursor] == "\\":
                    cursor = v2_exact_int_min(
                        v2_exact_int_add(cursor, 2),
                        line_end,
                    )
                    continue
                if value[cursor] == quote:
                    path_end = cursor
                    break
                cursor = v2_exact_int_add(cursor, 1)
        else:
            for quote in ('"', "'"):
                position = str.find(value, quote, match.end())
                if (
                    v2_redaction_intervals_overlap(position, 0)
                    and v2_exact_int_less(position, path_end)
                ):
                    path_end = v2_exact_int_min(path_end, position)
        if not v2_exact_int_less(path_start, path_end):
            raise EvidenceFailed("absolute-path redaction interval is empty")
        replacements.append((path_start, path_end))
        consumed_until = path_end
    for raw_start, raw_end in reversed(replacements):
        start, end = v2_exact_redaction_interval(raw_start, raw_end)
        value = v2_apply_absolute_path_interval(value, start, end)
    return value


def v2_sanitized_argv(argv: Sequence[Any]) -> list[str]:
    if type(argv) is list:
        if list.__len__(argv) > V2_COMMAND_ARGUMENTS_CAP:
            raise EvidenceFailed(
                "v2 command receipt exceeds its argument-count cap"
            )
        for raw in list.__iter__(argv):
            if type(raw) is not str:
                raise EvidenceFailed(
                    "v2 command receipt argument is not an exact string"
                )
            try:
                str.encode(raw, "utf-8")
            except UnicodeEncodeError as error:
                raise EvidenceFailed(
                    "v2 command receipt argument is not valid UTF-8"
                ) from error
        argv = v2_released_json_snapshot(
            argv,
            label="v2 command receipt argv",
            error_type=EvidenceFailed,
        )
    elif type(argv) is tuple:
        if tuple.__len__(argv) > V2_COMMAND_ARGUMENTS_CAP:
            raise EvidenceFailed(
                "v2 command receipt exceeds its argument-count cap"
            )
        argv = list(tuple.__iter__(argv))
    else:
        raise EvidenceFailed(
            "v2 command receipt argv is not an exact list or tuple"
        )
    if type(argv) is not list:
        raise EvidenceFailed("v2 command receipt argv snapshot is malformed")
    if list.__len__(argv) > V2_COMMAND_ARGUMENTS_CAP:
        raise EvidenceFailed("v2 command receipt exceeds its argument-count cap")
    result: list[str] = []
    sensitive_value_pending = False
    for raw in list.__iter__(argv):
        if type(raw) is not str:
            raise EvidenceFailed(
                "v2 command receipt argument is not an exact string"
            )
        value = raw
        try:
            value_bytes = str.encode(value, "utf-8")
        except UnicodeEncodeError as error:
            raise EvidenceFailed(
                "v2 command receipt argument is not valid UTF-8"
            ) from error
        if len(value_bytes) > V2_COMMAND_ARGUMENT_BYTES_CAP:
            raise EvidenceFailed("v2 command receipt exceeds its argument-byte cap")
        already_redacted = re.fullmatch(
            r"<redacted(?::[0-9a-f]{64})?>", value
        ) is not None
        if sensitive_value_pending:
            result.append(value if already_redacted else v2_redacted_value(value))
            sensitive_value_pending = False
            continue
        option_name = str.split(value, "=", 1)[0]
        sensitive_flag = (
            str.startswith(option_name, "-")
            and "=" not in value
            and v2_is_sensitive_key(str.lstrip(option_name, "-"))
        )
        assignment_key = (
            option_name
            if "=" in value
            and re.fullmatch(
                r"(?:--?[A-Za-z][-A-Za-z0-9_.:\[\]]{0,127}"
                r"|[A-Za-z_][-A-Za-z0-9_.:\[\]]{0,127})",
                option_name,
            )
            is not None
            else ""
        )
        sensitive_assignment = bool(
            assignment_key
            and v2_is_sensitive_key(str.lstrip(assignment_key, "-"))
        )
        authorization_header = bool(
            re.match(r"(?i)^(?:proxy-)?authorization\s*:", value)
            or re.search(r"(?i)\bbearer\s+\S+", value)
        )
        if sensitive_flag:
            result.append(value)
            sensitive_value_pending = True
            continue
        if (
            sensitive_assignment
            or authorization_header
            or v2_contains_absolute_path(value)
        ):
            result.append(v2_redacted_value(value))
        else:
            contextual = v2_redact_contextual_text(value)
            result.append(
                contextual
                if contextual != value
                else value
            )
    return result


def v2_validate_retained_reproduction_argv(
    value: Any,
    *,
    label: str,
) -> list[str]:
    """Validate one retained argv against the released count/byte contract."""
    if type(value) is not list:
        raise EvidenceFailed(f"{label} is not an exact argv array")
    sanitized = v2_sanitized_argv(value)
    if sanitized != value:
        raise EvidenceFailed(f"{label} contains an unsanitized argument")
    return value


def v2_redact_contextual_text(value: str) -> str:
    stripped = str.strip(value)
    if str.startswith(stripped, ("{", "[")):
        try:
            structured = json.loads(stripped)
        except (json.JSONDecodeError, UnicodeDecodeError):
            structured = None
        if isinstance(structured, (dict, list)):
            structured_payload = canonical_bytes(
                v2_assertion_evidence_projection(structured)
            )
            structured_text = bytes.decode(structured_payload, "utf-8")
            return str.rstrip(structured_text, "\n")
    text = str.replace(value, REPO_ROOT_TEXT, "<repo>")

    authorization_header = re.compile(
        r"(?im)(?P<prefix>\b(?:Proxy-)?Authorization\s*:\s*)"
        r"(?P<body>[^\r\n]*)"
    )

    def redact_authorization(match: re.Match[str]) -> str:
        return match.group("prefix") + "<redacted>"

    text = re.Pattern.sub(
        authorization_header,
        redact_authorization,
        text,
    )

    def redact_quoted_values(
        source: str,
        start_pattern: re.Pattern[str],
        *,
        key_mode: str,
    ) -> str:
        replacements: list[tuple[int, int, str]] = []
        consumed_until = -1
        for match in re.Pattern.finditer(start_pattern, source):
            if v2_exact_int_less(match.start(), consumed_until):
                continue
            candidate_key = match.group("key")
            if key_mode == "DIRECT":
                key_is_sensitive = v2_is_sensitive_key(candidate_key)
            elif key_mode == "DASH_STRIPPED":
                key_is_sensitive = v2_is_sensitive_key(
                    str.lstrip(candidate_key, "-")
                )
            elif key_mode == "ALWAYS":
                key_is_sensitive = True
            else:
                raise EvidenceFailed("quoted redaction key mode is unknown")
            if not key_is_sensitive:
                continue
            value_start = match.end()
            if (
                v2_redaction_intervals_overlap(value_start, len(source))
                or source[value_start] not in {'"', "'"}
            ):
                continue
            quote = source[value_start]
            cursor = v2_exact_int_add(value_start, 1)
            closing_quote: int | None = None
            while v2_exact_int_less(cursor, len(source)):
                if source[cursor] == "\\":
                    cursor = v2_exact_int_min(
                        v2_exact_int_add(cursor, 2),
                        len(source),
                    )
                    continue
                if v2_exact_str_equal(source[cursor], quote):
                    closing_quote = cursor
                    break
                cursor = v2_exact_int_add(cursor, 1)
            value_end = (
                v2_exact_int_add(closing_quote, 1)
                if closing_quote is not None
                else len(source)
            )
            replacement = (
                quote
                + "<redacted>"
                + (quote if closing_quote is not None else "")
            )
            replacements.append((value_start, value_end, replacement))
            consumed_until = value_end
        for start, end, replacement in reversed(replacements):
            source = v2_apply_exact_text_replacement(
                source,
                start,
                end,
                replacement,
            )
        return source

    assignment_start = re.compile(
        r"(?P<key>[A-Za-z_][-A-Za-z0-9_.:\[\]]{0,127})"
        r"(?P<sep>\s*[:=]\s*)"
    )
    text = redact_quoted_values(
        text,
        assignment_start,
        key_mode="DIRECT",
    )
    quoted_property_start = re.compile(
        r"(?P<key_quote>[\"'])(?P<key>[A-Za-z_][-A-Za-z0-9_.: \[\]]{0,127})"
        r"(?P=key_quote)(?P<sep>\s*:\s*)"
    )
    text = redact_quoted_values(
        text,
        quoted_property_start,
        key_mode="DIRECT",
    )
    split_option_start = re.compile(
        r"(?<![A-Za-z0-9_-])"
        r"(?P<key>--?[A-Za-z][-A-Za-z0-9_.\[\]]{0,127})"
        r"(?P<sep>\s+)"
    )
    text = redact_quoted_values(
        text,
        split_option_start,
        key_mode="DASH_STRIPPED",
    )
    bearer_start = re.compile(
        r"(?i)\b(?P<key>Bearer)(?P<sep>\s+)"
    )
    text = redact_quoted_values(
        text,
        bearer_start,
        key_mode="ALWAYS",
    )

    def sensitive_line_tail_replacements(
        source: str,
        start_pattern: re.Pattern[str],
        *,
        key_mode: str,
    ) -> list[tuple[int, int]]:
        replacements: list[tuple[int, int]] = []
        for match in re.Pattern.finditer(start_pattern, source):
            candidate_key = match.group("key")
            if key_mode == "DIRECT":
                key_is_sensitive = v2_is_sensitive_key(candidate_key)
            elif key_mode == "DASH_STRIPPED":
                key_is_sensitive = v2_is_sensitive_key(
                    str.lstrip(candidate_key, "-")
                )
            elif key_mode == "ALWAYS":
                key_is_sensitive = True
            else:
                raise EvidenceFailed("tail redaction key mode is unknown")
            if not key_is_sensitive:
                continue
            value_start = match.end()
            if (
                v2_redaction_intervals_overlap(value_start, len(source))
                or source[value_start] in {'"', "'", "\r", "\n"}
            ):
                continue
            line_end = len(source)
            for separator in ("\r", "\n"):
                position = str.find(source, separator, value_start)
                if v2_redaction_intervals_overlap(position, 0):
                    line_end = v2_exact_int_min(line_end, position)
            replacements.append((value_start, line_end))
        return replacements

    tail_replacements = [
        *sensitive_line_tail_replacements(
            text,
            assignment_start,
            key_mode="DIRECT",
        ),
        *sensitive_line_tail_replacements(
            text,
            quoted_property_start,
            key_mode="DIRECT",
        ),
        *sensitive_line_tail_replacements(
            text,
            split_option_start,
            key_mode="DASH_STRIPPED",
        ),
        *sensitive_line_tail_replacements(
            text,
            bearer_start,
            key_mode="ALWAYS",
        ),
    ]
    pending_start = 0
    pending_end = 0
    has_pending_replacement = False
    for start, end in sorted(tail_replacements, reverse=True):
        start, end = v2_exact_redaction_interval(start, end)
        if not has_pending_replacement:
            pending_start = start
            pending_end = end
            has_pending_replacement = True
            continue
        if v2_redaction_intervals_overlap(end, pending_start):
            pending_start = v2_exact_int_min(start, pending_start)
            pending_end = v2_exact_int_max(end, pending_end)
            continue
        text = v2_apply_redaction_interval(
            text,
            pending_start,
            pending_end,
        )
        pending_start = start
        pending_end = end
    if has_pending_replacement:
        text = v2_apply_redaction_interval(
            text,
            pending_start,
            pending_end,
        )
    return v2_redact_absolute_paths(text)


def v2_bounded_diagnostic_summary(value: Any) -> str:
    if type(value) is str:
        source = value
    else:
        value_type = type(value)
        try:
            is_exception = BaseException in v2_raw_type_mro(value_type)
        except EvidenceFailed:
            is_exception = False
        if is_exception:
            try:
                diagnostic, diagnostic_exact = v2_exception_diagnostic(value)
            except EvidenceFailed:
                diagnostic, diagnostic_exact = "", False
            if diagnostic_exact and diagnostic:
                source = diagnostic
            else:
                try:
                    type_name = v2_exception_type_projection(value_type)
                except EvidenceFailed:
                    type_name = "opaque-exception"
                source = f"{type_name}: no exact diagnostic message"
        else:
            source = v2_diagnostic_type_projection(value_type)
    if len(source) > V2_DIAGNOSTIC_SOURCE_CHARACTERS_CAP:
        source = (
            source[:V2_DIAGNOSTIC_SOURCE_CHARACTERS_CAP]
            + "...<source-characters:"
            + str(len(source))
            + ">"
        )
    source = source.encode("utf-8", errors="replace").decode("utf-8")
    text = v2_redact_contextual_text(source)
    text = " ".join(str.split(text))
    encoded = str.encode(text, "utf-8")
    if len(encoded) <= V2_DIAGNOSTIC_SUMMARY_BYTES_CAP:
        return text
    suffix = "...<truncated:" + text_root(text) + ">"
    prefix_budget = (
        V2_DIAGNOSTIC_SUMMARY_BYTES_CAP - len(suffix.encode("utf-8"))
    )
    prefix = bytes.decode(
        encoded[:prefix_budget],
        "utf-8",
        errors="ignore",
    )
    return prefix + suffix


def v2_assertion_evidence_utf8_length(
    value: Any,
    *,
    cap: int,
    label: str,
) -> int:
    if type(value) is not str or type(cap) is not int or cap < 0:
        raise EvidenceFailed(f"{label} UTF-8 accounting inputs are malformed")
    byte_length = 0
    for character in value:
        codepoint = ord(character)
        if 0xD800 <= codepoint <= 0xDFFF:
            raise EvidenceFailed(f"{label} contains invalid Unicode")
        byte_length += (
            1
            if codepoint <= 0x7F
            else 2
            if codepoint <= 0x7FF
            else 3
            if codepoint <= 0xFFFF
            else 4
        )
        if byte_length > cap:
            raise EvidenceFailed(f"{label} exceeds its UTF-8 byte cap")
    return byte_length


def v2_assertion_evidence_charge_items(
    budget: dict[str, Any],
    *,
    length: int,
    item_multiplier: int,
    snapshot_base: int,
    snapshot_per_item: int,
) -> None:
    if (
        type(length) is not int
        or type(item_multiplier) is not int
        or type(snapshot_base) is not int
        or type(snapshot_per_item) is not int
        or length < 0
        or item_multiplier < 0
        or snapshot_base < 0
        or snapshot_per_item < 0
    ):
        raise EvidenceFailed("assertion evidence resource charge is malformed")
    item_charge = length * item_multiplier
    snapshot_charge = snapshot_base + length * snapshot_per_item
    next_items = v2_exact_int_add(budget["items"], item_charge)
    next_snapshot_bytes = v2_exact_int_add(
        budget["snapshot_bytes"],
        snapshot_charge,
    )
    if v2_exact_int_less(V2_ASSERTION_EVIDENCE_ITEM_CAP, next_items):
        raise EvidenceFailed("assertion evidence exceeds its item cap")
    if v2_exact_int_less(
        V2_ASSERTION_EVIDENCE_SNAPSHOT_BYTES_CAP,
        next_snapshot_bytes,
    ):
        raise EvidenceFailed("assertion evidence exceeds its snapshot byte cap")
    budget["items"] = next_items
    budget["snapshot_bytes"] = next_snapshot_bytes


def v2_assertion_evidence_type_identity(
    value: type[Any],
    *,
    budget: dict[str, Any],
    label: str,
) -> str:
    module = v2_raw_type_attribute(value, "__module__")
    qualname = v2_raw_type_attribute(value, "__qualname__")
    if type(module) is not str or type(qualname) is not str:
        raise EvidenceFailed(f"{label} fields are not exact strings")
    remaining = v2_exact_int_remaining(
        V2_ASSERTION_EVIDENCE_SCALAR_BYTES_CAP,
        budget["scalar_bytes"],
    )
    module_bytes = v2_assertion_evidence_utf8_length(
        module,
        cap=remaining,
        label=f"{label} module",
    )
    if module_bytes >= remaining:
        raise EvidenceFailed(f"{label} exceeds its scalar byte cap")
    qualname_bytes = v2_assertion_evidence_utf8_length(
        qualname,
        cap=remaining - module_bytes - 1,
        label=f"{label} qualified name",
    )
    identity_bytes = module_bytes + 1 + qualname_bytes
    budget["scalar_bytes"] = v2_exact_int_add(
        budget["scalar_bytes"],
        identity_bytes,
    )
    return module + "." + qualname


def _v2_assertion_evidence_projection(
    value: Any,
    *,
    sensitive: bool,
    redact_visible_text: bool,
    depth: int,
    budget: dict[str, Any],
    active_container_ids: tuple[int, ...],
) -> Any:
    if depth > V2_ASSERTION_EVIDENCE_DEPTH_CAP:
        raise EvidenceFailed("assertion evidence exceeds its projection depth cap")
    next_nodes = v2_exact_int_add(budget["nodes"], 1)
    if v2_exact_int_less(V2_ASSERTION_EVIDENCE_NODE_CAP, next_nodes):
        raise EvidenceFailed("assertion evidence exceeds its node cap")
    budget["nodes"] = next_nodes
    if (
        sensitive
        and type(value) is dict
        and dict.__len__(value) == 2
        and all(type(key) is str for key in dict.__iter__(value))
        and dict.__contains__(value, "kind")
        and dict.__contains__(value, "content_root")
        and type(dict.__getitem__(value, "kind")) is str
        and dict.__getitem__(value, "kind") == "redacted"
        and v2_is_semantic_root(dict.__getitem__(value, "content_root"))
    ):
        return _v2_assertion_evidence_projection(
            value,
            sensitive=False,
            redact_visible_text=redact_visible_text,
            depth=depth + 1,
            budget=budget,
            active_container_ids=active_container_ids,
        )
    if sensitive:
        type_identity = v2_assertion_evidence_type_identity(
            type(value),
            budget=budget,
            label="assertion evidence sensitive type identity",
        )
        projection = {
            "type": type_identity,
            "value": _v2_assertion_evidence_projection(
                value,
                sensitive=False,
                redact_visible_text=False,
                depth=depth + 1,
                budget=budget,
                active_container_ids=active_container_ids,
            ),
        }
        projection_payload = canonical_bytes(projection)
        if len(projection_payload) > V2_ASSERTION_EVIDENCE_PROJECTION_BYTES_CAP:
            raise EvidenceFailed(
                "assertion evidence sensitive projection exceeds its byte cap"
            )
        return {
            "kind": "redacted",
            "content_root": "sha256-v1:"
            + hashlib.sha256(projection_payload).hexdigest(),
        }
    if value is None or type(value) is bool:
        return value
    if type(value) is int:
        integer_text = v2_bounded_exact_integer_text(
            value,
            label="assertion evidence integer",
            error_type=EvidenceFailed,
        )
        integer_bytes = len(str.encode(integer_text, "ascii"))
        next_scalar_bytes = v2_exact_int_add(
            budget["scalar_bytes"],
            integer_bytes,
        )
        if v2_exact_int_less(
            V2_ASSERTION_EVIDENCE_SCALAR_BYTES_CAP,
            next_scalar_bytes,
        ):
            raise EvidenceFailed("assertion evidence exceeds its scalar byte cap")
        budget["scalar_bytes"] = next_scalar_bytes
        return value
    if type(value) is float:
        if not math.isfinite(value):
            raise EvidenceFailed(
                "assertion evidence contains a non-finite float"
            )
        float_bytes = len(str.encode(repr(value), "ascii"))
        next_scalar_bytes = v2_exact_int_add(
            budget["scalar_bytes"],
            float_bytes,
        )
        if v2_exact_int_less(
            V2_ASSERTION_EVIDENCE_SCALAR_BYTES_CAP,
            next_scalar_bytes,
        ):
            raise EvidenceFailed("assertion evidence exceeds its scalar byte cap")
        budget["scalar_bytes"] = next_scalar_bytes
        return value
    if type(value) is str:
        value_bytes = v2_assertion_evidence_utf8_length(
            value,
            cap=v2_exact_int_remaining(
                V2_ASSERTION_EVIDENCE_SCALAR_BYTES_CAP,
                budget["scalar_bytes"],
            ),
            label="assertion evidence string",
        )
        budget["scalar_bytes"] = v2_exact_int_add(
            budget["scalar_bytes"],
            value_bytes,
        )
        projected_text = (
            value
            if not redact_visible_text
            else v2_redacted_value(value)
            if v2_contains_absolute_path(value)
            else v2_redact_contextual_text(value)
        )
        v2_assertion_evidence_utf8_length(
            projected_text,
            cap=V2_ASSERTION_EVIDENCE_PROJECTION_BYTES_CAP,
            label="assertion evidence projected string",
        )
        return projected_text
    value_type = type(value)
    if value_type is bytes or value_type is bytearray or value_type is memoryview:
        if value_type is memoryview:
            try:
                payload_length = memoryview.nbytes.__get__(
                    value,
                    memoryview,
                )
            except (BufferError, ValueError) as error:
                raise EvidenceFailed(
                    "assertion evidence memoryview is unavailable"
                ) from error
        else:
            payload_length = len(value)
        next_scalar_bytes = v2_exact_int_add(
            budget["scalar_bytes"],
            payload_length,
        )
        next_snapshot_bytes = v2_exact_int_add(
            budget["snapshot_bytes"],
            payload_length,
        )
        if (
            v2_exact_int_less(
                V2_ASSERTION_EVIDENCE_SCALAR_BYTES_CAP,
                next_scalar_bytes,
            )
            or v2_exact_int_less(
                V2_ASSERTION_EVIDENCE_SNAPSHOT_BYTES_CAP,
                next_snapshot_bytes,
            )
        ):
            raise EvidenceFailed("assertion evidence bytes exceed a resource cap")
        budget["scalar_bytes"] = next_scalar_bytes
        budget["snapshot_bytes"] = next_snapshot_bytes
        if value_type is memoryview:
            try:
                payload = memoryview.tobytes(value)
            except (BufferError, ValueError) as error:
                raise EvidenceFailed(
                    "assertion evidence memoryview became unavailable"
                ) from error
            if len(payload) != payload_length:
                raise EvidenceFailed(
                    "assertion evidence memoryview changed during projection"
                )
        else:
            payload = bytes(value)
        if value_type is bytearray and len(payload) != payload_length:
            raise EvidenceFailed(
                "assertion evidence bytearray changed during projection"
            )
        return {
            "kind": "bytes",
            "byte_length": payload_length,
            "content_root": "sha256-v1:" + hashlib.sha256(payload).hexdigest(),
        }
    if value_type is dict or value_type is OrderedDict or value_type is Counter:
        length = (
            OrderedDict.__len__(value)
            if value_type is OrderedDict
            else dict.__len__(value)
        )
        v2_assertion_evidence_charge_items(
            budget,
            length=length,
            item_multiplier=2,
            snapshot_base=V2_EXACT_WIRE_DICT_SNAPSHOT_BASE_BYTES,
            snapshot_per_item=V2_EXACT_WIRE_DICT_SNAPSHOT_ITEM_BYTES,
        )
        identity = id(value)
        if identity in active_container_ids:
            raise EvidenceFailed("assertion evidence contains a container cycle")
        next_active_container_ids = (*active_container_ids, identity)
        try:
            raw_items = (
                list(OrderedDict.items(value))
                if value_type is OrderedDict
                else list(dict.items(value))
            )
        except RuntimeError as error:
            raise EvidenceFailed(
                "assertion evidence mapping changed during projection"
            ) from error
        if len(raw_items) != length:
            raise EvidenceFailed(
                "assertion evidence mapping changed during projection"
            )
        projected: dict[str, Any] = {}
        if any(type(key) is not str for key, _item in raw_items):
            raise EvidenceFailed(
                "assertion evidence mapping keys must be exact strings"
            )
        for key, item in raw_items:
            key_bytes = v2_assertion_evidence_utf8_length(
                key,
                cap=v2_exact_int_remaining(
                    V2_ASSERTION_EVIDENCE_SCALAR_BYTES_CAP,
                    budget["scalar_bytes"],
                ),
                label="assertion evidence mapping key",
            )
            budget["scalar_bytes"] = v2_exact_int_add(
                budget["scalar_bytes"],
                key_bytes,
            )
            redacted_key = v2_redact_contextual_text(key)
            mapping_key_sensitive = v2_is_sensitive_mapping_key(key)
            mapping_value_sensitive = (
                v2_is_sensitive_key(key) or mapping_key_sensitive
            )
            projected_key = (
                key
                if redacted_key == key
                and not mapping_key_sensitive
                and not v2_contains_absolute_path(key)
                else "<redacted-key:"
                + hashlib.sha256(str.encode(key, "utf-8")).hexdigest()
                + ">"
            )
            if dict.__contains__(projected, projected_key):
                raise EvidenceFailed(
                    "assertion evidence mapping keys collide after projection"
                )
            dict.__setitem__(
                projected,
                projected_key,
                _v2_assertion_evidence_projection(
                    item,
                    sensitive=mapping_value_sensitive,
                    redact_visible_text=redact_visible_text,
                    depth=depth + 1,
                    budget=budget,
                    active_container_ids=next_active_container_ids,
                ),
            )
        return projected
    if value_type is list or value_type is tuple:
        length = list.__len__(value) if value_type is list else tuple.__len__(value)
        v2_assertion_evidence_charge_items(
            budget,
            length=length,
            item_multiplier=1,
            snapshot_base=V2_EXACT_WIRE_LIST_SNAPSHOT_BASE_BYTES,
            snapshot_per_item=V2_EXACT_WIRE_LIST_SNAPSHOT_ITEM_BYTES,
        )
        identity = id(value)
        if identity in active_container_ids:
            raise EvidenceFailed("assertion evidence contains a container cycle")
        next_active_container_ids = (*active_container_ids, identity)
        items = list(
            list.__iter__(value)
            if value_type is list
            else tuple.__iter__(value)
        )
        if len(items) != length:
            raise EvidenceFailed(
                "assertion evidence sequence changed during projection"
            )
        return [
            _v2_assertion_evidence_projection(
                item,
                sensitive=sensitive,
                redact_visible_text=redact_visible_text,
                depth=depth + 1,
                budget=budget,
                active_container_ids=next_active_container_ids,
            )
            for item in items
        ]
    if value_type is set or value_type is frozenset:
        length = set.__len__(value) if value_type is set else frozenset.__len__(value)
        v2_assertion_evidence_charge_items(
            budget,
            length=length,
            item_multiplier=1,
            snapshot_base=V2_EXACT_WIRE_LIST_SNAPSHOT_BASE_BYTES,
            snapshot_per_item=V2_EXACT_WIRE_LIST_SNAPSHOT_ITEM_BYTES,
        )
        identity = id(value)
        if identity in active_container_ids:
            raise EvidenceFailed("assertion evidence contains a container cycle")
        next_active_container_ids = (*active_container_ids, identity)
        try:
            items = list(
                set.__iter__(value)
                if value_type is set
                else frozenset.__iter__(value)
            )
        except RuntimeError as error:
            raise EvidenceFailed(
                "assertion evidence set changed during projection"
            ) from error
        if len(items) != length:
            raise EvidenceFailed(
                "assertion evidence set changed during projection"
            )
        projected = [
            _v2_assertion_evidence_projection(
                item,
                sensitive=sensitive,
                redact_visible_text=redact_visible_text,
                depth=depth + 1,
                budget=budget,
                active_container_ids=next_active_container_ids,
            )
            for item in items
        ]
        return sorted(projected, key=lambda item: canonical_bytes(item))
    type_identity = v2_assertion_evidence_type_identity(
        value_type,
        budget=budget,
        label="assertion evidence opaque type identity",
    )
    projected_type_identity = (
        type_identity
        if not redact_visible_text
        else v2_redacted_value(type_identity)
        if v2_contains_absolute_path(type_identity)
        else v2_redact_contextual_text(type_identity)
    )
    v2_assertion_evidence_utf8_length(
        projected_type_identity,
        cap=V2_ASSERTION_EVIDENCE_PROJECTION_BYTES_CAP,
        label="assertion evidence projected opaque type identity",
    )
    return {
        "kind": "opaque",
        "type": projected_type_identity,
    }


def v2_assertion_evidence_projection(
    value: Any,
    *,
    sensitive: bool = False,
) -> Any:
    if type(sensitive) is not bool:
        raise EvidenceFailed(
            "assertion evidence sensitive flag must be an exact boolean"
        )
    budget: dict[str, Any] = {
        "nodes": 0,
        "items": 0,
        "scalar_bytes": 0,
        "snapshot_bytes": 0,
    }
    projected = _v2_assertion_evidence_projection(
        value,
        sensitive=sensitive,
        redact_visible_text=True,
        depth=0,
        budget=budget,
        active_container_ids=(),
    )
    try:
        payload = canonical_bytes(projected)
    except (TypeError, ValueError, OverflowError, RecursionError) as error:
        raise EvidenceFailed(
            "assertion evidence projection is not canonical"
        ) from error
    if len(payload) > V2_ASSERTION_EVIDENCE_PROJECTION_BYTES_CAP:
        raise EvidenceFailed("assertion evidence projection exceeds its byte cap")
    return projected


def v2_source_command_receipts(
    source: Mapping[str, Any],
) -> list[dict[str, Any]]:
    if (
        type(source) is not dict
        or not dict.__contains__(source, "captured")
        or type(source["captured"]) is not dict
    ):
        raise EvidenceFailed("v2 event source is not an exact captured object")
    captured = source["captured"]
    if (
        not dict.__contains__(captured, "observation")
        or not dict.__contains__(captured, "audit_capture")
        or type(captured["observation"]) is not dict
        or type(captured["audit_capture"]) is not dict
    ):
        raise EvidenceFailed("v2 event source capture envelopes are malformed")
    observation = captured["observation"]
    audit_capture = captured["audit_capture"]
    if (
        not dict.__contains__(observation, "command_receipts")
        or not dict.__contains__(audit_capture, "command_receipts")
    ):
        raise EvidenceFailed("v2 event source lacks command receipts")
    observation_rows = observation["command_receipts"]
    audit_rows = audit_capture["command_receipts"]
    if type(observation_rows) is not list or type(audit_rows) is not list:
        raise EvidenceFailed("v2 event source command receipts are not arrays")
    if (
        list.__len__(observation_rows) > V2_LOG_EVENTS_CAP
        or list.__len__(audit_rows) > V2_LOG_EVENTS_CAP
        or list.__len__(observation_rows) + list.__len__(audit_rows)
        > V2_LOG_EVENTS_CAP
    ):
        raise EvidenceFailed("v2 event source command receipts exceed their cap")
    receipts: list[dict[str, Any]] = []
    for row in observation_rows:
        if type(row) is not dict:
            raise EvidenceFailed("v2 observation command receipt is malformed")
        v2_exact_keys(
            row,
            V2_SOURCE_COMMAND_RECEIPT_FIELDS,
            label="v2 observation command receipt",
        )
        stdout = row["stdout"]
        stderr = row["stderr"]
        if type(stdout) is dict:
            v2_exact_keys(
                stdout,
                V2_SOURCE_STREAM_RECEIPT_FIELDS,
                label="v2 observation stdout receipt",
            )
        if type(stderr) is dict:
            v2_exact_keys(
                stderr,
                V2_SOURCE_STREAM_RECEIPT_FIELDS,
                label="v2 observation stderr receipt",
            )
        if (
            type(row["capture_sequence"]) is not int
            or type(row["capture_ordinal"]) is not int
            or type(row["projection_kind"]) is not str
            or type(row["normalized_projection_root"]) is not str
            or type(row["argv"]) is not list
            or any(type(value) is not str for value in row["argv"])
            or type(row["exit_code"]) is not int
            or type(row["category"]) is not str
            or type(stdout) is not dict
            or type(stderr) is not dict
            or type(stdout["bytes"]) is not int
            or type(stdout["root"]) is not str
            or type(stderr["bytes"]) is not int
            or type(stderr["root"]) is not str
        ):
            raise EvidenceFailed("v2 observation command receipt scalars differ")
        receipts.append(
            {
                "ordering": (
                    0,
                    row["capture_sequence"],
                    "",
                ),
                "capture_ordinal": row["capture_ordinal"],
                "projection_kind": row["projection_kind"],
                "normalized_projection_root": row[
                    "normalized_projection_root"
                ],
                "argv": row["argv"],
                "exit_code": row["exit_code"],
                "result_category": row["category"],
                "stdout_byte_length": row["stdout"]["bytes"],
                "stdout_root": row["stdout"]["root"],
                "stderr_byte_length": row["stderr"]["bytes"],
                "stderr_root": row["stderr"]["root"],
            }
        )
    for row in audit_rows:
        if type(row) is not dict:
            raise EvidenceFailed("v2 audit command receipt is malformed")
        v2_exact_keys(
            row,
            V2_AUDIT_COMMAND_RECEIPT_FIELDS,
            label="v2 audit command receipt",
        )
        if (
            type(row["capture_ordinal"]) is not int
            or type(row["issue_id"]) is not str
            or not row["issue_id"]
            or type(row["argv"]) is not list
            or any(type(value) is not str for value in row["argv"])
            or type(row["exit_code"]) is not int
            or type(row["result_category"]) is not str
            or type(row["stdout_byte_length"]) is not int
            or type(row["stdout_root"]) is not str
            or type(row["normalized_document_root"]) is not str
            or type(row["stderr_byte_length"]) is not int
            or type(row["stderr_root"]) is not str
        ):
            raise EvidenceFailed("v2 audit command receipt scalars differ")
        receipts.append(
            {
                "ordering": (
                    row["capture_ordinal"],
                    1_000_000,
                    row["issue_id"],
                ),
                "capture_ordinal": row["capture_ordinal"],
                "projection_kind": "audit_document",
                "normalized_projection_root": row[
                    "normalized_document_root"
                ],
                "argv": row["argv"],
                "exit_code": row["exit_code"],
                "result_category": row["result_category"],
                "stdout_byte_length": row["stdout_byte_length"],
                "stdout_root": row["stdout_root"],
                "stderr_byte_length": row["stderr_byte_length"],
                "stderr_root": row["stderr_root"],
            }
        )
    return sorted(
        receipts,
        key=lambda row: row["ordering"],
    )


def v2_validate_log_event_count(
    count: int,
    *,
    error_type: type[HarnessError],
) -> None:
    if type(count) is not int or count < 0:
        raise error_type("v2 event count uses an invalid counter")
    if count > V2_LOG_EVENTS_CAP:
        raise error_type("v2 event count exceeds its cap")


def v2_build_event_row(
    *,
    mode: str,
    subject_mode: str,
    case_id: str,
    assertion_id: str,
    safe_artifact_projection: Mapping[str, Any],
    sequence: int,
    stage: str,
    argv: Sequence[Any] = (),
    exit_code: int = 0,
    result_category: str = "PASS",
    semantic_projection: Mapping[str, Any] | None = None,
    stdout_byte_length: int = 0,
    stdout_root: str | None = None,
    stderr_byte_length: int = 0,
    stderr_root: str | None = None,
    terminal: str | None = None,
) -> dict[str, Any]:
    empty_root = "sha256-v1:" + hashlib.sha256(b"").hexdigest()
    parameter = {
        "mode": mode,
        "subject_mode": subject_mode,
        "stage": stage,
        "sequence": sequence,
    }
    row = {
        "schema": V2_EVENT_SCHEMA,
        "case_id": case_id,
        "assertion_id": assertion_id,
        "executor_id": assertion_id,
        "parameter_root": semantic_root(parameter),
        "stage": stage,
        "sequence": sequence,
        "argv": v2_sanitized_argv(argv),
        "exit_code": int(exit_code),
        "result_category": result_category,
        "semantic_projection": dict(semantic_projection or {}),
        "stdout_byte_length": int(stdout_byte_length),
        "stdout_root": empty_root if stdout_root is None else stdout_root,
        "stderr_byte_length": int(stderr_byte_length),
        "stderr_root": empty_root if stderr_root is None else stderr_root,
        "first_divergence": None,
        "recovery": "NOT_REQUIRED",
        "terminal": terminal,
        "safe_relative_artifacts": dict(safe_artifact_projection),
        "no_claim": (
            "the event is redacted deterministic planning evidence and "
            "mints no semantic, human, write, implementation, or release authority"
        ),
    }
    v2_validate_log_event_count(
        sequence + 1,
        error_type=EvidenceFailed,
    )
    if len(canonical_bytes(row)) > V2_LOG_LINE_BYTES_CAP:
        raise EvidenceFailed("v2 event line exceeds its byte cap")
    return row


def v2_source_command_event_row(
    *,
    mode: str,
    subject_mode: str,
    case_id: str,
    assertion_id: str,
    safe_artifact_projection: Mapping[str, Any],
    sequence: int,
    source_index: int,
    receipt: Mapping[str, Any],
) -> dict[str, Any]:
    if type(receipt) is not dict:
        raise EvidenceFailed("v2 source command receipt is not an exact object")
    v2_exact_keys(
        receipt,
        frozenset({
            "ordering",
            "capture_ordinal",
            "projection_kind",
            "normalized_projection_root",
            "argv",
            "exit_code",
            "result_category",
            "stdout_byte_length",
            "stdout_root",
            "stderr_byte_length",
            "stderr_root",
        }),
        label="v2 source command event receipt",
    )
    ordering = dict.__getitem__(receipt, "ordering")
    capture_ordinal = dict.__getitem__(receipt, "capture_ordinal")
    projection_kind = dict.__getitem__(receipt, "projection_kind")
    normalized_projection_root = dict.__getitem__(
        receipt,
        "normalized_projection_root",
    )
    argv = dict.__getitem__(receipt, "argv")
    exit_code = dict.__getitem__(receipt, "exit_code")
    result_category = dict.__getitem__(receipt, "result_category")
    stdout_byte_length = dict.__getitem__(receipt, "stdout_byte_length")
    stdout_root = dict.__getitem__(receipt, "stdout_root")
    stderr_byte_length = dict.__getitem__(receipt, "stderr_byte_length")
    stderr_root = dict.__getitem__(receipt, "stderr_root")
    if (
        type(ordering) is not tuple
        or tuple.__len__(ordering) != 3
        or type(capture_ordinal) is not int
        or type(projection_kind) is not str
        or type(normalized_projection_root) is not str
        or type(argv) is not list
        or type(exit_code) is not int
        or type(result_category) is not str
        or type(stdout_byte_length) is not int
        or type(stdout_root) is not str
        or type(stderr_byte_length) is not int
        or type(stderr_root) is not str
        or type(sequence) is not int
        or type(source_index) is not int
    ):
        raise EvidenceFailed("v2 source command event receipt scalars differ")
    validated_argv = v2_sanitized_argv(argv)
    stage = f"source-command-{source_index:06d}"
    command_receipt_root = semantic_root({
        "capture_ordinal": capture_ordinal,
        "projection_kind": projection_kind,
        "normalized_projection_root": normalized_projection_root,
        "argv": argv,
        "exit_code": exit_code,
        "result_category": result_category,
        "stdout_byte_length": stdout_byte_length,
        "stdout_root": stdout_root,
        "stderr_byte_length": stderr_byte_length,
        "stderr_root": stderr_root,
    })
    return v2_build_event_row(
        mode=mode,
        subject_mode=subject_mode,
        case_id=case_id,
        assertion_id=assertion_id,
        safe_artifact_projection=safe_artifact_projection,
        sequence=sequence,
        stage=stage,
        argv=validated_argv,
        exit_code=exit_code,
        result_category=result_category,
        semantic_projection={"command_receipt_root": command_receipt_root},
        stdout_byte_length=stdout_byte_length,
        stdout_root=stdout_root,
        stderr_byte_length=stderr_byte_length,
        stderr_root=stderr_root,
    )


def v2_event_rows(
    *,
    mode: str,
    subject_mode: str,
    source: Mapping[str, Any],
    inventory: Mapping[str, Any],
    authority: Mapping[str, Any],
    review_plan: Mapping[str, Any],
    history: Mapping[str, Any],
    zero_sets: Mapping[str, Any],
    safe_artifacts: Sequence[str],
    reproduction: Sequence[str],
) -> list[dict[str, Any]]:
    case_id, assertion_id = {
        "review-plan": (
            "template-lint-v2.nomock-review-plan",
            "v2.case.nomock-review-plan",
        ),
        "history-plan": (
            "template-lint-v2.nomock-history-plan",
            "v2.case.nomock-history-plan",
        ),
        "replay": (
            "template-lint-v2.nomock-offline-replay",
            "v2.case.nomock-offline-replay",
        ),
    }[mode]
    safe_artifact_projection = {
        "base": list(V2_RUN_ARTIFACTS),
        "optional_count": len(safe_artifacts) - len(V2_RUN_ARTIFACTS),
        "optional_paths_root": semantic_root(
            sorted(
                set(safe_artifacts) - set(V2_RUN_ARTIFACTS),
                key=lambda value: value.encode("utf-8"),
            )
        ),
    }
    sequence = 0
    events: list[dict[str, Any]] = [v2_build_event_row(
        mode=mode,
        subject_mode=subject_mode,
        case_id=case_id,
        assertion_id=assertion_id,
        safe_artifact_projection=safe_artifact_projection,
        sequence=sequence,
        stage="assertion-start",
        argv=reproduction,
        semantic_projection={
            "source_root": source["semantic_root"],
            "manifest_root": source["manifest"]["semantic_root"],
        },
    )]
    sequence = v2_exact_int_add(sequence, 1)
    source_command_receipts = v2_source_command_receipts(source)
    if type(source_command_receipts) is not list:
        raise EvidenceFailed("v2 source command receipts are not an exact list")
    source_index = 0
    for receipt in source_command_receipts:
        events = v2_exact_list_appended(events, v2_source_command_event_row(
            mode=mode,
            subject_mode=subject_mode,
            case_id=case_id,
            assertion_id=assertion_id,
            safe_artifact_projection=safe_artifact_projection,
            sequence=sequence,
            source_index=source_index,
            receipt=receipt,
        ))
        sequence = v2_exact_int_add(sequence, 1)
        source_index = v2_exact_int_add(source_index, 1)
    for stage, document in (
        ("inventory-derived", inventory),
        ("authority-derived", authority),
        ("review-projection-derived", review_plan),
        ("history-projection-derived", history),
        ("zero-sets-derived", zero_sets),
    ):
        events = v2_exact_list_appended(events, v2_build_event_row(
            mode=mode,
            subject_mode=subject_mode,
            case_id=case_id,
            assertion_id=assertion_id,
            safe_artifact_projection=safe_artifact_projection,
            sequence=sequence,
            stage=stage,
            semantic_projection={"semantic_root": document["semantic_root"]},
        ))
        sequence = v2_exact_int_add(sequence, 1)
    events = v2_exact_list_appended(events, v2_build_event_row(
        mode=mode,
        subject_mode=subject_mode,
        case_id=case_id,
        assertion_id=assertion_id,
        safe_artifact_projection=safe_artifact_projection,
        sequence=sequence,
        stage="assertion-terminal",
        semantic_projection={
            "source_root": source["semantic_root"],
            "inventory_root": inventory["semantic_root"],
            "authority_root": authority["semantic_root"],
            "review_plan_root": review_plan["semantic_root"],
            "history_root": history["semantic_root"],
            "zero_sets_root": zero_sets["semantic_root"],
        },
    ))
    sequence = v2_exact_int_add(sequence, 1)
    events = v2_exact_list_appended(events, v2_build_event_row(
        mode=mode,
        subject_mode=subject_mode,
        case_id=case_id,
        assertion_id=assertion_id,
        safe_artifact_projection=safe_artifact_projection,
        sequence=sequence,
        stage="suite-terminal",
        semantic_projection={
            "subject_mode": subject_mode,
            "prior_event_roots": [
                semantic_root(row) for row in events
            ],
        },
        terminal="Pass",
    ))
    if (
        [row["sequence"] for row in events] != list(range(len(events)))
        or sum(row["terminal"] is not None for row in events) != 1
        or events[-1]["terminal"] != "Pass"
    ):
        raise EvidenceFailed("v2 terminal event is not unique and last")
    return events


def v2_artifact_identity(
    *,
    relative_path: str,
    schema_kind: str,
    payload: bytes,
) -> str:
    return semantic_root(
        {
            "relative_path": str(
                safe_relative(relative_path, label="v2 artifact")
            ),
            "schema_kind": schema_kind,
            "byte_length": len(payload),
            "content_root": (
                "sha256-v1:" + hashlib.sha256(payload).hexdigest()
            ),
        }
    )


def v2_bundle_payloads(
    *,
    mode: str,
    subject_mode: str,
    artifact_root: str,
    artifact_dir: str,
    source: Mapping[str, Any],
    inventory: Mapping[str, Any],
    authority: Mapping[str, Any],
    review_plan: Mapping[str, Any],
    history: Mapping[str, Any],
    zero_sets: Mapping[str, Any],
    optional_payloads: Mapping[str, bytes],
    reproduction: Sequence[str],
    current_source_files: list[dict[str, Any]],
    replay_equivalence: Mapping[str, Any] | None = None,
) -> dict[str, bytes]:
    source, current_source_files = (
        v2_validate_source_document_against_source_files(
            source,
            current_source_files,
        )
    )
    if subject_mode == "review-plan":
        if "state" not in source["captured"]["audit_capture"]:
            raise EvidenceFailed(
                "v2 review-plan source unexpectedly retains a history audit"
            )
        v2_validate_review_plan(
            review_plan,
            inventory,
            authority,
            review_receipts=source["captured"]["review_receipts"],
        )
        v2_validate_not_requested(
            history,
            schema=V2_HISTORY_SCHEMA,
            mode=subject_mode,
            source_root=source["semantic_root"],
            inventory_root=inventory["semantic_root"],
            projection="history",
        )
    elif subject_mode == "history-plan":
        if "state" in source["captured"]["audit_capture"]:
            raise EvidenceFailed(
                "v2 history-plan source lacks its requested history audit"
            )
        v2_validate_not_requested(
            review_plan,
            schema=V2_REVIEW_PLAN_SCHEMA,
            mode=subject_mode,
            source_root=source["semantic_root"],
            inventory_root=inventory["semantic_root"],
            projection="review-plan",
        )
        expected_history = v2_build_history(
            source_root=source["semantic_root"],
            inventory=inventory,
            authority=authority,
            all_issues=source["captured"]["all_issues"],
            audit_capture=source["captured"]["audit_capture"],
            history_contract=source["contracts"]["history"],
        )
        if history != expected_history:
            divergence = first_projection_divergence(
                expected_history,
                history,
            )
            raise EvidenceFailed(
                "v2 history projection differs from its exact source-derived "
                f"projection at {divergence or '$'}"
            )
    else:
        raise EvidenceFailed("v2 bundle subject mode is unknown")
    registry = review_plan.get("oversize_content") or []
    if not isinstance(registry, list):
        raise EvidenceFailed("v2 oversize registry is not an array")
    registry_by_path: dict[str, Mapping[str, Any]] = {}
    for index, entry in enumerate(registry):
        if not isinstance(entry, dict):
            raise EvidenceFailed(f"v2 oversize registry row {index} is malformed")
        v2_exact_keys(
            entry,
            V2_OVERSIZE_REGISTRY_FIELDS,
            label=f"v2 oversize registry row {index}",
        )
        relative = str(
            safe_relative(entry["relative_path"], label="v2 oversize artifact")
        )
        if relative in V2_RUN_ARTIFACTS or relative in registry_by_path:
            raise EvidenceFailed("v2 oversize registry duplicates an artifact")
        registry_by_path[relative] = entry
    if set(optional_payloads) != set(registry_by_path):
        raise EvidenceFailed("v2 optional payload membership differs from its registry")
    inventory_by_id = {
        row["id"]: row for row in inventory.get("rows", [])
    }
    authority_by_id = {
        row["target_id"]: row
        for row in authority.get("decisions", [])
    }
    for relative, payload in optional_payloads.items():
        if len(payload) > RUN_ARTIFACT_CAP:
            raise EvidenceFailed(f"v2 optional artifact {relative} exceeds cap")
        document = strict_json_loads(
            payload,
            label=f"v2 optional artifact {relative}",
            require_canonical=True,
        )
        if type(document) is not dict:
            raise EvidenceFailed(f"v2 optional artifact {relative} is not an object")
        v2_exact_keys(
            document,
            V2_OVERSIZE_ARTIFACT_FIELDS,
            label=f"v2 optional artifact {relative}",
        )
        verify_semantic_root(document, label=f"v2 optional artifact {relative}")
        entry = registry_by_path[relative]
        complete_plan = document["complete_plan"]
        bounded_index = document["bounded_incomplete_index"]
        if (
            type(complete_plan) is not dict
            or set(complete_plan)
            != {"target", "authority", "actual_review_minutes"}
            or type(complete_plan["target"]) is not dict
            or type(complete_plan["authority"]) is not dict
            or type(bounded_index) is not dict
            or set(bounded_index)
            != {"complete", "target_id", "missing_sections"}
            or bounded_index["complete"] is not False
            or not isinstance(bounded_index["target_id"], str)
            or not isinstance(bounded_index["missing_sections"], list)
        ):
            raise EvidenceFailed(
                f"v2 optional artifact {relative} has a malformed full plan"
            )
        target_id = bounded_index["target_id"]
        if (
            target_id not in inventory_by_id
            or target_id not in authority_by_id
        ):
            raise EvidenceFailed(
                f"v2 optional artifact {relative} names an unknown target"
            )
        expected_target = inventory_by_id[target_id]
        expected_authority = authority_by_id[target_id]
        expected_complete_plan = {
            "target": expected_target,
            "authority": expected_authority,
            "actual_review_minutes": int(
                expected_authority["review_minutes"]
            ),
        }
        expected_exceeded_caps = v2_oversize_exceeded_caps(
            expected_target,
            expected_authority,
        )
        expected_target_root_text = expected_target["target_root"]
        if (
            type(expected_target_root_text) is not str
            or V2_SEMANTIC_ROOT_PATTERN.fullmatch(
                expected_target_root_text
            )
            is None
        ):
            raise EvidenceFailed(
                f"v2 optional artifact {relative} target root is malformed"
            )
        expected_relative = (
            "oversize/"
            f"{expected_target_root_text[len('sha256-v1:'):]}.json"
        )
        if (
            relative != expected_relative
            or complete_plan != expected_complete_plan
            or bounded_index["missing_sections"]
            != expected_target["missing_sections"]
            or document["source_roots"]
            != [
                expected_target["target_root"],
                expected_target["v1_row_root"],
                expected_target["campaign_epoch_root"],
            ]
            or document["field_roots"] != expected_target["field_roots"]
            or document["clause_roots"] != expected_target["clause_roots"]
            or document["exceeded_caps"] != expected_exceeded_caps
            or not expected_exceeded_caps
            or document["canonical_br_show_argv"]
            != ["br", "show", target_id, "--json", *BR_READ_FLAGS]
            or document["retained_full_plan_path"] != relative
            or document["retained_full_plan_root"]
            != semantic_root(expected_complete_plan)
            or document["owner_questions"]
            != list(V2_OVERSIZE_OWNER_QUESTIONS)
            or document["no_claim"] != V2_OVERSIZE_NO_CLAIM
        ):
            raise EvidenceFailed(
                f"v2 optional artifact {relative} differs from source projections"
            )
        exceeded_caps = document["exceeded_caps"]
        if (
            not isinstance(exceeded_caps, list)
            or not exceeded_caps
            or any(
                not isinstance(row, dict)
                or set(row) != V2_OVERSIZE_EXCEEDED_CAP_FIELDS
                or not isinstance(row["cap"], str)
                or not row["cap"]
                or not isinstance(row["source_path"], str)
                or not row["source_path"]
                or type(row["observed"]) is not int
                or type(row["limit"]) is not int
                or row["observed"] <= row["limit"]
                or type(row["violation_count"]) is not int
                or row["violation_count"] < 1
                or not isinstance(row["violating_membership_root"], str)
                or re.fullmatch(
                    r"sha256-v1:[0-9a-f]{64}",
                    row["violating_membership_root"],
                )
                is None
                for row in exceeded_caps
            )
        ):
            raise EvidenceFailed(
                f"v2 optional artifact {relative} has malformed cap diagnostics"
            )
        if (
            entry["byte_length"] != len(payload)
            or entry["semantic_root"] != document["semantic_root"]
            or entry["aggregate_cap_accounting"] != len(payload)
            or entry["schema_kind"] != document["schema"]
            or entry["media_kind"] != "application/json"
            or entry["target_roots"] != [expected_target["target_root"]]
            or entry["field_roots"] != document["field_roots"]
            or entry["clause_roots"] != document["clause_roots"]
            or entry["exceeded_caps"] != document["exceeded_caps"]
            or document["retained_full_plan_path"] != relative
            or document["retained_full_plan_root"]
            != semantic_root(document["complete_plan"])
        ):
            raise EvidenceFailed(f"v2 optional registry identity differs for {relative}")

    safe_artifacts = sorted(
        [*V2_RUN_ARTIFACTS, *optional_payloads],
        key=lambda value: value.encode("utf-8"),
    )
    events = v2_event_rows(
        mode=mode,
        subject_mode=subject_mode,
        source=source,
        inventory=inventory,
        authority=authority,
        review_plan=review_plan,
        history=history,
        zero_sets=zero_sets,
        safe_artifacts=safe_artifacts,
        reproduction=reproduction,
    )
    payloads: dict[str, bytes] = {
        "source-v2.json": canonical_bytes(source),
        "inventory-v2.json": canonical_bytes(inventory),
        "authority-v2.json": canonical_bytes(authority),
        "review-plan-v2.json": canonical_bytes(review_plan),
        "history-v2.json": canonical_bytes(history),
        "zero-sets-v2.json": canonical_bytes(zero_sets),
        "events.jsonl": b"".join(canonical_bytes(row) for row in events),
        "reproduce.txt": canonical_bytes(list(reproduction)),
        **dict(optional_payloads),
    }
    schema_by_name = {
        "source-v2.json": V2_SOURCE_SCHEMA,
        "inventory-v2.json": V2_INVENTORY_SCHEMA,
        "authority-v2.json": V2_AUTHORITY_SCHEMA,
        "review-plan-v2.json": V2_REVIEW_PLAN_SCHEMA,
        "history-v2.json": V2_HISTORY_SCHEMA,
        "zero-sets-v2.json": V2_ZERO_SETS_SCHEMA,
        "events.jsonl": V2_EVENT_SCHEMA,
        "reproduce.txt": "frankensim.argv-json.v2",
        **{
            relative: str(registry_by_path[relative]["schema_kind"])
            for relative in optional_payloads
        },
    }
    identities = {
        name: v2_artifact_identity(
            relative_path=name,
            schema_kind=schema_by_name[name],
            payload=payloads[name],
        )
        for name in sorted(payloads, key=lambda value: value.encode("utf-8"))
    }
    terminal = v2_rooted(
        {
            "schema": V2_TERMINAL_SCHEMA,
            "mode": mode,
            "subject_mode": subject_mode,
            "bundle_state": "COMPLETE_GREEN",
            "terminal": "Pass",
            "exit_code": 0,
            "artifact_root": str(
                safe_relative(artifact_root, label="artifact root")
            ),
            "artifact_dir": str(
                safe_relative(artifact_dir, label="artifact dir")
            ),
            "base_artifacts": list(V2_RUN_ARTIFACTS),
            "safe_relative_artifacts": safe_artifacts,
            "artifact_identities": identities,
            "optional_content_registry": registry,
            "manifest_root": source["manifest"]["semantic_root"],
            "source_root": source["semantic_root"],
            "inventory_root": inventory["semantic_root"],
            "authority_root": authority["semantic_root"],
            "review_plan_root": review_plan["semantic_root"],
            "history_root": history["semantic_root"],
            "zero_sets_root": zero_sets["semantic_root"],
            "events_content_root": (
                "sha256-v1:"
                + hashlib.sha256(payloads["events.jsonl"]).hexdigest()
            ),
            "event_count": len(events),
            "event_sequence": list(range(len(events))),
            "event_roots": [semantic_root(row) for row in events],
            "terminal_event_root": semantic_root(events[-1]),
            "reproduction": list(reproduction),
            "replay_equivalence": dict(replay_equivalence or {}),
            "first_divergence": None,
            "recovery": "NOT_REQUIRED",
            "complete_evidence_bundle": True,
            "complete_green_prefix": True,
            "retry_requires_fresh_run_dir": False,
            "no_claim": (
                "the final seal proves deterministic bundle construction only; "
                "it does not prove current state on replay or mint any authority"
            ),
        }
    )
    payloads = {
        **payloads,
        "terminal.json": canonical_bytes(terminal),
    }
    if set(payloads) != set(V2_RUN_ARTIFACTS) | set(optional_payloads):
        raise EvidenceFailed("v2 payload membership differs from its exact contract")
    for name, payload in dict.items(payloads):
        if len(payload) > RUN_ARTIFACT_CAP:
            raise EvidenceFailed(f"v2 artifact {name} exceeds its 64 MiB cap")
    return payloads


def v2_refusal_event_rows(
    *,
    mode: str,
    terminal_name: str,
    failure: Mapping[str, Any],
    reproduction: Sequence[str],
) -> list[dict[str, Any]]:
    if mode not in {"review-plan", "history-plan"}:
        raise EvidenceFailed("v2 refusal event mode is unknown")
    if terminal_name not in V2_SEMANTIC_REFUSAL_TERMINALS:
        raise EvidenceFailed("v2 refusal event terminal is not semantic")
    if (
        len(reproduction) > V2_COMMAND_ARGUMENTS_CAP
        or any(
            not isinstance(value, str)
            or len(value.encode("utf-8")) > V2_COMMAND_ARGUMENT_BYTES_CAP
            for value in reproduction
        )
        or v2_sanitized_argv(reproduction) != list(reproduction)
    ):
        raise EvidenceFailed("v2 refusal reproduction is not bounded and sanitized")
    case_id = (
        "template-lint-v2.nomock-review-plan"
        if mode == "review-plan"
        else "template-lint-v2.nomock-history-plan"
    )
    assertion_id = (
        "v2.case.nomock-review-plan"
        if mode == "review-plan"
        else "v2.case.nomock-history-plan"
    )
    safe_artifact_projection = {
        "base": list(V2_RUN_ARTIFACTS),
        "optional_count": 0,
        "optional_paths_root": semantic_root([]),
    }
    empty_root = "sha256-v1:" + hashlib.sha256(b"").hexdigest()
    stages = (
        "assertion-start",
        "assertion-terminal",
        "suite-terminal",
    )
    events: list[dict[str, Any]] = []
    for sequence, event_stage in enumerate(stages):
        is_failure_event = event_stage != "assertion-start"
        is_terminal_event = event_stage == "suite-terminal"
        parameter = {
            "mode": mode,
            "subject_mode": mode,
            "stage": event_stage,
            "sequence": sequence,
        }
        event = {
            "schema": V2_EVENT_SCHEMA,
            "case_id": case_id,
            "assertion_id": assertion_id,
            "executor_id": assertion_id,
            "parameter_root": semantic_root(parameter),
            "stage": event_stage,
            "sequence": sequence,
            "argv": list(reproduction) if sequence == 0 else [],
            "exit_code": (
                TERMINAL_EXIT[terminal_name] if is_failure_event else 0
            ),
            "result_category": (
                "SEMANTIC_REFUSAL" if is_failure_event else "STARTED"
            ),
            "semantic_projection": {
                "failure_root": failure["semantic_root"],
                "available_roots": failure["available_roots"],
                "prior_event_roots": (
                    [semantic_root(row) for row in events]
                    if is_terminal_event
                    else []
                ),
            },
            "stdout_byte_length": 0,
            "stdout_root": empty_root,
            "stderr_byte_length": 0,
            "stderr_root": empty_root,
            "first_divergence": (
                failure["first_divergence"]
                if is_failure_event
                else None
            ),
            "recovery": (
                failure["recovery"]
                if is_failure_event
                else "NOT_REQUIRED"
            ),
            "terminal": terminal_name if is_terminal_event else None,
            "safe_relative_artifacts": safe_artifact_projection,
            "no_claim": (
                "the event retains only rooted refusal evidence and no raw "
                "streams, tracker bodies, credentials, or authority"
            ),
        }
        if len(canonical_bytes(event)) > V2_LOG_LINE_BYTES_CAP:
            raise EvidenceFailed("v2 refusal event exceeds its line cap")
        events.append(event)
    return events


def v2_refusal_bundle_payloads(
    *,
    mode: str,
    artifact_root: str,
    artifact_dir: str,
    manifest: Mapping[str, Any],
    error: HarnessError,
    stage: str,
    available_roots: Mapping[str, str | None],
    argv: Sequence[Any],
) -> tuple[dict[str, bytes], dict[str, Any]]:
    terminal_name = v2_sealed_error_terminal(error)
    if terminal_name not in V2_SEMANTIC_REFUSAL_TERMINALS:
        raise EvidenceFailed("non-semantic failure cannot mint a refusal bundle")
    raw_argv = [str(raw) for raw in argv]
    if len(raw_argv) > V2_COMMAND_ARGUMENTS_CAP:
        omitted = raw_argv[V2_COMMAND_ARGUMENTS_CAP - 1 :]
        raw_argv = [
            *raw_argv[: V2_COMMAND_ARGUMENTS_CAP - 1],
            (
                f"<omitted:{len(omitted)}:"
                f"{semantic_root(omitted)}>"
            ),
        ]
    prebounded_argv: list[str] = []
    for value in raw_argv:
        if len(value.encode("utf-8")) > V2_COMMAND_ARGUMENT_BYTES_CAP:
            prebounded_argv.append(
                "<redacted:"
                + hashlib.sha256(value.encode("utf-8")).hexdigest()
                + ">"
            )
        else:
            prebounded_argv.append(value)
    bounded_argv = v2_sanitized_argv(prebounded_argv)
    failure = v2_failure_evidence(
        stage=stage,
        detail=v2_bounded_diagnostic_summary(error),
        terminal=terminal_name,
        manifest_root=str(manifest["semantic_root"]),
        available_roots=available_roots,
    )
    projection_names = {
        "source-v2.json": ("source", V2_SOURCE_SCHEMA),
        "inventory-v2.json": ("inventory", V2_INVENTORY_SCHEMA),
        "authority-v2.json": ("authority", V2_AUTHORITY_SCHEMA),
        "review-plan-v2.json": ("review-plan", V2_REVIEW_PLAN_SCHEMA),
        "history-v2.json": ("history", V2_HISTORY_SCHEMA),
        "zero-sets-v2.json": ("zero-sets", V2_ZERO_SETS_SCHEMA),
    }
    documents: dict[str, dict[str, Any]] = {}
    available_key_by_projection = {
        "source": "source",
        "inventory": "inventory",
        "authority": "authority",
        "review-plan": "review_plan",
        "history": "history",
        "zero-sets": "zero_sets",
    }
    for artifact_name, (projection, expected_schema) in projection_names.items():
        available_key = available_key_by_projection[projection]
        documents[artifact_name] = v2_rooted(
            {
                "schema": V2_REFUSAL_PROJECTION_SCHEMA,
                "artifact_name": artifact_name,
                "projection": projection,
                "expected_success_schema": expected_schema,
                "mode": mode,
                "state": "REFUSED",
                "manifest_root": manifest["semantic_root"],
                "failure_root": failure["semantic_root"],
                "available_projection_root": available_roots.get(available_key),
                "complete_green_prefix": False,
                "no_claim": (
                    "this closed refusal envelope is complete failure evidence "
                    "and is not a successful planner projection"
                ),
            }
        )
    events = v2_refusal_event_rows(
        mode=mode,
        terminal_name=terminal_name,
        failure=failure,
        reproduction=bounded_argv,
    )
    payloads: dict[str, bytes] = {
        **{
            name: canonical_bytes(document)
            for name, document in documents.items()
        },
        "events.jsonl": b"".join(canonical_bytes(row) for row in events),
        "reproduce.txt": canonical_bytes(bounded_argv),
    }
    schema_by_name = {
        **{
            name: V2_REFUSAL_PROJECTION_SCHEMA for name in projection_names
        },
        "events.jsonl": V2_EVENT_SCHEMA,
        "reproduce.txt": "frankensim.argv-json.v2",
    }
    identities = {
        name: v2_artifact_identity(
            relative_path=name,
            schema_kind=schema_by_name[name],
            payload=payloads[name],
        )
        for name in sorted(payloads, key=lambda value: value.encode("utf-8"))
    }
    terminal = v2_rooted(
        {
            "schema": V2_TERMINAL_SCHEMA,
            "mode": mode,
            "subject_mode": mode,
            "bundle_state": "COMPLETE_NON_GREEN",
            "terminal": terminal_name,
            "exit_code": TERMINAL_EXIT[terminal_name],
            "artifact_root": str(
                safe_relative(artifact_root, label="artifact root")
            ),
            "artifact_dir": str(
                safe_relative(artifact_dir, label="artifact dir")
            ),
            "base_artifacts": list(V2_RUN_ARTIFACTS),
            "safe_relative_artifacts": list(V2_RUN_ARTIFACTS),
            "artifact_identities": identities,
            "optional_content_registry": [],
            "manifest_root": manifest["semantic_root"],
            "manifest_content_identity": manifest["content_identity"],
            "source_root": documents["source-v2.json"]["semantic_root"],
            "inventory_root": documents["inventory-v2.json"]["semantic_root"],
            "authority_root": documents["authority-v2.json"]["semantic_root"],
            "review_plan_root": documents["review-plan-v2.json"][
                "semantic_root"
            ],
            "history_root": documents["history-v2.json"]["semantic_root"],
            "zero_sets_root": documents["zero-sets-v2.json"]["semantic_root"],
            "events_content_root": (
                "sha256-v1:"
                + hashlib.sha256(payloads["events.jsonl"]).hexdigest()
            ),
            "event_count": len(events),
            "event_sequence": list(range(len(events))),
            "event_roots": [semantic_root(row) for row in events],
            "terminal_event_root": semantic_root(events[-1]),
            "reproduction": bounded_argv,
            "replay_equivalence": {},
            "failure_evidence": failure,
            "failure_root": failure["semantic_root"],
            "first_divergence": failure["first_divergence"],
            "recovery": failure["recovery"],
            "complete_evidence_bundle": True,
            "complete_green_prefix": False,
            "retry_requires_fresh_run_dir": True,
            "no_claim": (
                "the complete non-green seal proves only a typed semantic "
                "refusal and can never be promoted or replayed as Pass"
            ),
        }
    )
    payloads["terminal.json"] = canonical_bytes(terminal)
    if set(payloads) != set(V2_RUN_ARTIFACTS):
        raise EvidenceFailed("v2 refusal payload membership is not exactly nine")
    if any(len(payload) > RUN_ARTIFACT_CAP for payload in payloads.values()):
        raise EvidenceFailed("v2 refusal payload exceeds an artifact cap")
    return payloads, failure


def v2_write_exclusive(path: Path, payload: bytes) -> None:
    if len(payload) > RUN_ARTIFACT_CAP:
        raise EvidenceFailed("v2 writer received an over-cap payload")
    flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
    flags |= os.O_NOFOLLOW
    descriptor_slot: list[int | None] = [None]
    written = 0
    operation_succeeded = False
    try:
        try:
            list.__setitem__(descriptor_slot, 0, os.open(path, flags, 0o644))
        except FileExistsError as error:
            raise EvidenceFailed(
                "v2 overwrite is forbidden for reserved artifact"
            ) from error
        except OSError as error:
            raise InfrastructureFailed(
                "v2 exclusive writer could not create reserved artifact"
            ) from error
        descriptor = list.__getitem__(descriptor_slot, 0)
        if descriptor is None:
            raise InfrastructureFailed(
                "v2 exclusive writer descriptor ownership was lost"
            )
        while written < len(payload):
            count = os.write(descriptor, payload[written:])
            if (
                type(count) is not int
                or count <= 0
                or count > len(payload) - written
            ):
                raise InfrastructureFailed(
                    "v2 exclusive writer observed an invalid write count"
                )
            written += count
        os.fsync(descriptor)
        operation_succeeded = True
    except OSError as error:
        raise InfrastructureFailed(
            "v2 exclusive writer failed for reserved artifact"
        ) from error
    except BaseException:
        # Repository policy forbids deletion; an incomplete prefix deliberately
        # remains without a valid terminal seal for manual recovery.
        raise
    finally:
        v2_close_owned_descriptor_slots((
            (
                descriptor_slot,
                InfrastructureFailed(
                    "v2 exclusive writer could not close reserved artifact"
                ),
            ),
        ), surface_failure=operation_succeeded)


def v2_fsync_directory(path: Path) -> None:
    flags = os.O_RDONLY | os.O_DIRECTORY
    flags |= os.O_NOFOLLOW
    descriptor_slot: list[int | None] = [None]
    operation_succeeded = False
    try:
        try:
            list.__setitem__(descriptor_slot, 0, os.open(path, flags))
        except OSError as error:
            raise InfrastructureFailed(
                "v2 directory could not be opened for fsync"
            ) from error
        descriptor = list.__getitem__(descriptor_slot, 0)
        if descriptor is None:
            raise InfrastructureFailed(
                "v2 directory descriptor ownership was lost"
            )
        os.fsync(descriptor)
        operation_succeeded = True
    except OSError as error:
        raise InfrastructureFailed("v2 directory fsync failed") from error
    finally:
        v2_close_owned_descriptor_slots((
            (
                descriptor_slot,
                InfrastructureFailed(
                    "v2 directory descriptor close failed"
                ),
            ),
        ), surface_failure=operation_succeeded)


def v2_finalize_reservation_descriptor(
    reservation: Any,
    role: str,
) -> None:
    descriptor_slot: list[int | None] = [None]
    try:
        v2_transfer_reservation_descriptor_to_slot(
            reservation,
            role,
            descriptor_slot,
        )
        v2_collect_owned_descriptor_slot_close_failure(
            descriptor_slot,
            InfrastructureFailed(
                "v2 reservation finalizer descriptor close failed"
            ),
        )
    except BaseException:
        # Finalization cannot surface evidence. A one-shot interruption before
        # either ownership clear leaves the descriptor in its visible owner;
        # after a committed clear, the transfer/collector closes the local gap
        # before preserving that interruption.
        try:
            if list.__getitem__(descriptor_slot, 0) is None:
                v2_transfer_reservation_descriptor_to_slot(
                    reservation,
                    role,
                    descriptor_slot,
                )
            v2_collect_owned_descriptor_slot_close_failure(
                descriptor_slot,
                InfrastructureFailed(
                    "v2 reservation finalizer descriptor close failed"
                ),
            )
        except BaseException:
            pass
    finally:
        if type(reservation) is V2BundleReservation:
            reservation.handoff_owner_active = not (
                reservation.terminal_descriptor is None
                and reservation.output_descriptor is None
                and reservation.parent_descriptor is None
            )


V2_RESERVATION_DESCRIPTOR_ROLES = ("terminal", "output", "parent")


@dataclass
class V2BundleReservation:
    output: Path
    artifact_root: str
    artifact_dir: str
    terminal_descriptor: int | None
    output_descriptor: int | None
    parent_descriptor: int | None
    path_anchors: tuple[tuple[Path, int, int, int], ...]
    written_identities: dict[str, dict[str, int]] = field(default_factory=dict)
    terminal_assignment_started: bool = False
    terminal_assignment_committed: bool = False
    sealed: bool = False
    cleanup_failures: list[dict[str, Any]] = field(default_factory=list)
    handoff_owner_active: bool = field(default=False, repr=False)

    def __del__(self) -> None:
        """Best-effort one-attempt drain for an interrupted return handoff."""
        try:
            if self.handoff_owner_active is not True:
                return
            for role in V2_RESERVATION_DESCRIPTOR_ROLES:
                v2_finalize_reservation_descriptor(self, role)
        finally:
            # A raw interruption between role attempts drains every field that
            # still carries ownership. Fields cleared after an attempted close
            # are skipped, so an indeterminate numeric identity is never used
            # twice.
            if self.handoff_owner_active is True:
                for role in V2_RESERVATION_DESCRIPTOR_ROLES:
                    v2_finalize_reservation_descriptor(self, role)
                if (
                    self.terminal_descriptor is None
                    and self.output_descriptor is None
                    and self.parent_descriptor is None
                ):
                    self.handoff_owner_active = False


def v2_reservation_descriptor_field(role: str) -> str:
    if role == "terminal":
        return "terminal_descriptor"
    if role == "output":
        return "output_descriptor"
    if role == "parent":
        return "parent_descriptor"
    raise EvidenceFailed("v2 reservation descriptor role is malformed")


def v2_transfer_reservation_descriptor_to_slot(
    reservation: V2BundleReservation,
    role: str,
    destination_slot: list[int | None],
) -> bool:
    """Move one reservation descriptor into an exact cleanup slot."""
    if (
        type(reservation) is not V2BundleReservation
        or type(destination_slot) is not list
        or list.__len__(destination_slot) != 1
    ):
        raise EvidenceFailed(
            "v2 reservation descriptor transfer state is malformed"
        )
    field_name = v2_reservation_descriptor_field(role)
    descriptor: int | None = None
    try:
        descriptor = object.__getattribute__(reservation, field_name)
        destination_descriptor = list.__getitem__(destination_slot, 0)
        if descriptor is None:
            if destination_descriptor is not None:
                raise EvidenceFailed(
                    "v2 reservation descriptor destination is not empty"
                )
            return False
        if (
            type(descriptor) is not int
            or descriptor < 0
            or destination_descriptor is not None
        ):
            raise EvidenceFailed(
                "v2 reservation descriptor transfer state is malformed"
            )
        object.__setattr__(reservation, field_name, None)
        list.__setitem__(destination_slot, 0, descriptor)
    except BaseException:
        if descriptor is not None:
            field_owns = (
                type(reservation) is V2BundleReservation
                and object.__getattribute__(reservation, field_name)
                is descriptor
            )
            slot_owns = (
                type(destination_slot) is list
                and list.__len__(destination_slot) == 1
                and list.__getitem__(destination_slot, 0) is descriptor
            )
            if field_owns and slot_owns:
                object.__setattr__(reservation, field_name, None)
                field_owns = False
            if not field_owns and not slot_owns:
                try:
                    os.close(descriptor)
                except BaseException:
                    pass
        raise
    return True


def v2_transfer_descriptor_slot_to_reservation(
    source_slot: list[int | None],
    reservation: V2BundleReservation,
    role: str,
) -> None:
    """Move one slot descriptor into a published active reservation."""
    if (
        type(source_slot) is not list
        or list.__len__(source_slot) != 1
        or type(reservation) is not V2BundleReservation
        or reservation.handoff_owner_active is not True
    ):
        raise EvidenceFailed(
            "v2 reservation descriptor adoption state is malformed"
        )
    field_name = v2_reservation_descriptor_field(role)
    descriptor: int | None = None
    try:
        descriptor = list.__getitem__(source_slot, 0)
        destination_descriptor = object.__getattribute__(
            reservation,
            field_name,
        )
        if (
            type(descriptor) is not int
            or descriptor < 0
            or destination_descriptor is not None
        ):
            raise EvidenceFailed(
                "v2 reservation descriptor adoption state is malformed"
            )
        list.__setitem__(source_slot, 0, None)
        object.__setattr__(reservation, field_name, descriptor)
    except BaseException:
        if descriptor is not None:
            slot_owns = (
                type(source_slot) is list
                and list.__len__(source_slot) == 1
                and list.__getitem__(source_slot, 0) is descriptor
            )
            field_owns = (
                type(reservation) is V2BundleReservation
                and object.__getattribute__(reservation, field_name)
                is descriptor
            )
            if slot_owns and field_owns:
                list.__setitem__(source_slot, 0, None)
                slot_owns = False
            if not slot_owns and not field_owns:
                try:
                    os.close(descriptor)
                except BaseException:
                    pass
        raise


def v2_capture_path_anchor(
    path: Path,
    *,
    expect_directory: bool,
) -> tuple[Path, int, int, int]:
    value = os.lstat(path)
    expected = stat.S_ISDIR(value.st_mode) if expect_directory else stat.S_ISREG(
        value.st_mode
    )
    if not expected:
        raise EvidenceFailed("v2 reservation path has the wrong filesystem kind")
    return (
        path,
        int(value.st_dev),
        int(value.st_ino),
        int(stat.S_IFMT(value.st_mode)),
    )


def v2_assert_reservation_anchors(
    reservation: V2BundleReservation,
) -> None:
    for path, device, inode, file_type in reservation.path_anchors:
        try:
            value = os.lstat(path)
        except OSError as error:
            raise InfrastructureFailed(
                "v2 reserved publication path disappeared"
            ) from error
        if (
            value.st_dev != device
            or value.st_ino != inode
            or stat.S_IFMT(value.st_mode) != file_type
        ):
            raise InfrastructureFailed(
                "v2 reserved publication path changed identity"
            )
    descriptor = reservation.terminal_descriptor
    output_descriptor = reservation.output_descriptor
    parent_descriptor = reservation.parent_descriptor
    if (
        descriptor is None
        or output_descriptor is None
        or parent_descriptor is None
    ):
        raise EvidenceFailed("v2 bundle reservation descriptors are not open")
    terminal_path, device, inode, file_type = reservation.path_anchors[-1]
    descriptor_stat = os.fstat(descriptor)
    if (
        terminal_path != reservation.output / "terminal.json"
        or descriptor_stat.st_dev != device
        or descriptor_stat.st_ino != inode
        or stat.S_IFMT(descriptor_stat.st_mode) != file_type
        or not stat.S_ISREG(descriptor_stat.st_mode)
        or descriptor_stat.st_nlink != 1
    ):
        raise InfrastructureFailed(
            "v2 reserved terminal descriptor lost its path identity"
        )
    output_path_anchor = next(
        anchor
        for anchor in reservation.path_anchors
        if anchor[0] == reservation.output
    )
    output_stat = os.fstat(output_descriptor)
    if (
        output_stat.st_dev != output_path_anchor[1]
        or output_stat.st_ino != output_path_anchor[2]
        or stat.S_IFMT(output_stat.st_mode) != output_path_anchor[3]
        or not stat.S_ISDIR(output_stat.st_mode)
    ):
        raise InfrastructureFailed(
            "v2 reserved output directory descriptor lost its path identity"
        )
    parent_stat = os.fstat(parent_descriptor)
    parent_anchor = next(
        anchor
        for anchor in reservation.path_anchors
        if anchor[0] == reservation.output.parent
    )
    if (
        parent_stat.st_dev != parent_anchor[1]
        or parent_stat.st_ino != parent_anchor[2]
        or stat.S_IFMT(parent_stat.st_mode) != parent_anchor[3]
        or not stat.S_ISDIR(parent_stat.st_mode)
    ):
        raise InfrastructureFailed(
            "v2 reserved parent directory descriptor lost its path identity"
        )


def v2_close_reservation(
    reservation: V2BundleReservation,
    *,
    surface_failure: bool = True,
) -> None:
    if type(surface_failure) is not bool:
        raise EvidenceFailed(
            "v2 reservation cleanup failure policy is not exact"
        )
    terminal_slot: list[int | None] = [None]
    output_slot: list[int | None] = [None]
    parent_slot: list[int | None] = [None]
    descriptor_slots: tuple[
        tuple[str, list[int | None]],
        ...,
    ] = (
        ("terminal", terminal_slot),
        ("output", output_slot),
        ("parent", parent_slot),
    )
    failures: list[tuple[BaseException, dict[str, Any]]] = []
    active_primary: BaseException | None = None
    fallback_primary: BaseException | None = None
    fallback_started = False

    def adopt_remaining_fields() -> None:
        if (
            list.__getitem__(terminal_slot, 0) is None
            and type(reservation.terminal_descriptor) is int
        ):
            v2_transfer_reservation_descriptor_to_slot(
                reservation,
                "terminal",
                terminal_slot,
            )
        if (
            list.__getitem__(output_slot, 0) is None
            and type(reservation.output_descriptor) is int
        ):
            v2_transfer_reservation_descriptor_to_slot(
                reservation,
                "output",
                output_slot,
            )
        if (
            list.__getitem__(parent_slot, 0) is None
            and type(reservation.parent_descriptor) is int
        ):
            v2_transfer_reservation_descriptor_to_slot(
                reservation,
                "parent",
                parent_slot,
            )
        if (
            reservation.terminal_descriptor is None
            and reservation.output_descriptor is None
            and reservation.parent_descriptor is None
        ):
            reservation.handoff_owner_active = False

    def attempt_close(
        role: str,
        descriptor_slot: list[int | None],
    ) -> None:
        descriptor = list.__getitem__(descriptor_slot, 0)
        if descriptor is None:
            return
        close_failure = v2_collect_owned_descriptor_slot_close_failure(
            descriptor_slot,
            InfrastructureFailed(
                "v2 bundle reservation descriptor cleanup failed"
            ),
        )
        if close_failure is not None:
            error = close_failure[1]
            list.append(failures, (
                error,
                {
                    "descriptor_role": role,
                    "descriptor": descriptor,
                    "error_type": v2_exception_type_projection(type(error)),
                    "errno": (
                        error.errno
                        if isinstance(error, OSError)
                        and type(error.errno) is int
                        else None
                    ),
                },
            ))

    def drain_remaining() -> None:
        adopt_remaining_fields()
        for role, descriptor_slot in descriptor_slots:
            if list.__getitem__(descriptor_slot, 0) is not None:
                attempt_close(role, descriptor_slot)

    try:
        try:
            try:
                drain_remaining()
            except BaseException as error:
                active_primary = error
                raise
            finally:
                fallback_started = True
                drain_remaining()
        except BaseException as error:
            fallback_primary = error
    finally:
        # A second interruption after field adoption still leaves the local
        # slots visible to this outer retry. Treat an outermost interruption as
        # cleanup state, retry the drain, and let the caller's explicit policy
        # decide whether that cleanup primary may surface.
        try:
            drain_remaining()
        except BaseException as error:
            if fallback_primary is None:
                fallback_primary = error
            drain_remaining()
        for _error, evidence in failures:
            list.append(reservation.cleanup_failures, evidence)
    if surface_failure:
        if active_primary is not None:
            raise active_primary
        if fallback_primary is not None:
            raise fallback_primary
    if not failures:
        return
    verified_durable = (
        reservation.terminal_assignment_committed and reservation.sealed
    )
    if verified_durable:
        # The durable, verified seal remains true. Cleanup degradation is
        # retained on the reservation for the caller's structured evidence.
        return
    if not surface_failure:
        return
    first_error = failures[0][0]
    if not isinstance(first_error, OSError):
        raise first_error
    raise InfrastructureFailed(
        "v2 bundle reservation descriptor cleanup failed before verified "
        "durability"
    ) from first_error


def v2_close_owned_reservation_slot(
    reservation_slot: list[V2BundleReservation | None],
    *,
    surface_failure: bool = True,
) -> V2BundleReservation | None:
    """Idempotently close the exact reservation retained by one caller slot."""
    if type(reservation_slot) is not list or len(reservation_slot) != 1:
        raise EvidenceFailed("v2 reservation ownership slot is malformed")
    reservation = list.__getitem__(reservation_slot, 0)
    if reservation is None:
        return None
    if type(reservation) is not V2BundleReservation:
        raise EvidenceFailed("v2 reservation ownership slot is malformed")
    try:
        v2_close_reservation(
            reservation,
            surface_failure=surface_failure,
        )
    finally:
        if (
            reservation.terminal_descriptor is None
            and reservation.output_descriptor is None
            and reservation.parent_descriptor is None
        ):
            list.__setitem__(reservation_slot, 0, None)
    return reservation


def _v2_open_or_create_directory_chain_owned(
    relative: PurePosixPath,
    *,
    label: str,
    descriptor_slot: list[int | None],
    child_slot: list[int | None],
) -> int:
    directory_flags = os.O_RDONLY | os.O_DIRECTORY
    directory_flags |= os.O_NOFOLLOW
    try:
        list.__setitem__(descriptor_slot, 0, os.open(REPO_ROOT, directory_flags))
    except OSError as error:
        raise InfrastructureFailed(
            "v2 repository root could not be opened for reservation"
        ) from error
    try:
        for part in relative.parts:
            descriptor = list.__getitem__(descriptor_slot, 0)
            if descriptor is None:
                raise InfrastructureFailed(
                    "v2 reservation directory descriptor ownership was lost"
                )
            try:
                os.mkdir(part, 0o755, dir_fd=descriptor)
            except FileExistsError:
                pass
            except OSError as error:
                if error.errno in {errno.ELOOP, errno.ENOTDIR}:
                    raise EvidenceFailed(
                        f"{label} contains an unsafe path component"
                    ) from error
                raise
            try:
                list.__setitem__(child_slot, 0, os.open(part, directory_flags, dir_fd=descriptor))
            except OSError as error:
                if error.errno in {errno.ELOOP, errno.ENOTDIR}:
                    raise EvidenceFailed(
                        f"{label} contains a symlink or non-directory component"
                    ) from error
                raise
            try:
                next_descriptor = list.__getitem__(child_slot, 0)
                if next_descriptor is None:
                    raise InfrastructureFailed(
                        "v2 reservation child descriptor ownership was lost"
                    )
                value = os.fstat(next_descriptor)
                if not stat.S_ISDIR(value.st_mode):
                    raise EvidenceFailed(
                        f"{label} contains a non-directory component"
                    )
                # The adopted entry is now descriptor-bound. Durably commit
                # its parent entry before advancing into that child.
                os.fsync(descriptor)
            except BaseException:
                v2_collect_owned_descriptor_slot_close_failure(
                    child_slot,
                    InfrastructureFailed(
                        "v2 reservation child descriptor close failed"
                    ),
                )
                raise
            parent_close_failure = (
                v2_collect_owned_descriptor_slot_close_failure(
                    descriptor_slot,
                    InfrastructureFailed(
                        "v2 reservation parent descriptor close failed"
                    ),
                )
            )
            if parent_close_failure is not None:
                v2_collect_owned_descriptor_slot_close_failure(
                    child_slot,
                    InfrastructureFailed(
                        "v2 reservation child descriptor close failed"
                    ),
                )
                v2_raise_descriptor_close_failure(parent_close_failure)
            v2_transfer_owned_descriptor_slot(
                child_slot,
                descriptor_slot,
            )
        descriptor = list.__getitem__(descriptor_slot, 0)
        if descriptor is None:
            raise InfrastructureFailed(
                "v2 reservation directory descriptor ownership was lost"
            )
        return descriptor
    except BaseException:
        v2_collect_owned_descriptor_slot_close_failure(
            child_slot,
            InfrastructureFailed(
                "v2 reservation child descriptor close failed"
            ),
        )
        v2_collect_owned_descriptor_slot_close_failure(
            descriptor_slot,
            InfrastructureFailed(
                "v2 reservation directory descriptor close failed"
            ),
        )
        raise


def v2_open_or_create_directory_chain(
    relative: PurePosixPath,
    *,
    label: str,
    _descriptor_slot: list[int | None],
) -> int:
    if (
        type(_descriptor_slot) is not list
        or len(_descriptor_slot) != 1
        or list.__getitem__(_descriptor_slot, 0) is not None
    ):
        raise EvidenceFailed(
            "v2 reservation destination descriptor slot is not empty"
        )
    descriptor_slot = _descriptor_slot
    child_slot: list[int | None] = [None]
    try:
        return _v2_open_or_create_directory_chain_owned(
            relative,
            label=label,
            descriptor_slot=descriptor_slot,
            child_slot=child_slot,
        )
    except BaseException:
        v2_close_owned_descriptor_slots((
            (
                child_slot,
                InfrastructureFailed(
                    "v2 reservation child descriptor close failed"
                ),
            ),
            (
                descriptor_slot,
                InfrastructureFailed(
                    "v2 reservation directory descriptor close failed"
                ),
            ),
        ), surface_failure=False)
        raise


def _v2_reserve_bundle(
    *,
    artifact_root: str,
    artifact_dir: str,
    _reservation_slot: list[V2BundleReservation | None],
) -> V2BundleReservation:
    if (
        type(_reservation_slot) is not list
        or len(_reservation_slot) != 1
        or list.__getitem__(_reservation_slot, 0) is not None
    ):
        raise EvidenceFailed(
            "v2 bundle destination reservation slot is not empty"
        )
    root_relative = safe_relative(
        artifact_root,
        label="v2 artifact root",
    )
    dir_relative = safe_relative(
        artifact_dir,
        label="v2 artifact dir",
    )
    combined_relative = root_relative / dir_relative
    if len(str(combined_relative).encode("utf-8")) > 512:
        raise UsageRefused(
            "v2 artifact dir exceeds the 512-byte relative path cap"
        )
    root = REPO_ROOT.joinpath(*root_relative.parts)
    output = REPO_ROOT.joinpath(*combined_relative.parts)
    parent_relative = root_relative.joinpath(*dir_relative.parts[:-1])
    terminal_path = output / "terminal.json"
    directory_flags = os.O_RDONLY | os.O_DIRECTORY
    directory_flags |= os.O_NOFOLLOW
    parent_descriptor_slot: list[int | None] = [None]
    output_descriptor_slot: list[int | None] = [None]
    terminal_descriptor_slot: list[int | None] = [None]
    try:
        v2_open_or_create_directory_chain(
            parent_relative,
            label="v2 artifact-dir parent",
            _descriptor_slot=parent_descriptor_slot,
        )
        parent_descriptor = list.__getitem__(parent_descriptor_slot, 0)
        if parent_descriptor is None:
            raise InfrastructureFailed(
                "v2 parent reservation descriptor ownership was lost"
            )
        try:
            os.mkdir(
                dir_relative.name,
                0o755,
                dir_fd=parent_descriptor,
            )
        except FileExistsError as error:
            raise EvidenceFailed(
                "v2 artifact run directory already exists"
            ) from error
        os.fsync(parent_descriptor)
        try:
            list.__setitem__(output_descriptor_slot, 0, os.open(dir_relative.name, directory_flags, dir_fd=parent_descriptor))
        except OSError as error:
            if error.errno in {errno.ELOOP, errno.ENOTDIR}:
                raise EvidenceFailed(
                    "v2 artifact run directory is unsafe"
                ) from error
            raise
        output_descriptor = list.__getitem__(output_descriptor_slot, 0)
        if output_descriptor is None:
            raise InfrastructureFailed(
                "v2 output reservation descriptor ownership was lost"
            )
        terminal_flags = os.O_RDWR | os.O_CREAT | os.O_EXCL
        terminal_flags |= os.O_NOFOLLOW
        try:
            list.__setitem__(terminal_descriptor_slot, 0, os.open("terminal.json", terminal_flags, 0o644, dir_fd=output_descriptor))
        except FileExistsError as error:
            raise EvidenceFailed(
                "v2 terminal reservation already exists"
            ) from error
        terminal_descriptor = list.__getitem__(terminal_descriptor_slot, 0)
        if terminal_descriptor is None:
            raise InfrastructureFailed(
                "v2 terminal reservation descriptor ownership was lost"
            )
        os.fsync(terminal_descriptor)
        os.fsync(output_descriptor)
        os.fsync(parent_descriptor)
        anchor_paths: list[Path] = [root]
        cursor = root
        for part in output.relative_to(root).parts:
            cursor = cursor / part
            anchor_paths.append(cursor)
        path_anchors = tuple(
            [
                *(
                    v2_capture_path_anchor(path, expect_directory=True)
                    for path in anchor_paths
                ),
                v2_capture_path_anchor(
                    terminal_path,
                    expect_directory=False,
                ),
            ]
        )
        reservation = V2BundleReservation(
            output=output,
            artifact_root=artifact_root,
            artifact_dir=artifact_dir,
            terminal_descriptor=None,
            output_descriptor=None,
            parent_descriptor=None,
            path_anchors=path_anchors,
        )
        # Publish an active finalizer owner before moving the first descriptor.
        # Every subsequent instruction boundary therefore leaves each numeric
        # descriptor in either its source slot or this caller-visible owner.
        reservation.handoff_owner_active = True
        list.__setitem__(_reservation_slot, 0, reservation)
        v2_transfer_descriptor_slot_to_reservation(
            terminal_descriptor_slot,
            reservation,
            "terminal",
        )
        v2_transfer_descriptor_slot_to_reservation(
            output_descriptor_slot,
            reservation,
            "output",
        )
        v2_transfer_descriptor_slot_to_reservation(
            parent_descriptor_slot,
            reservation,
            "parent",
        )
        reservation.written_identities["terminal.json"] = v2_stat_identity(
            os.fstat(terminal_descriptor)
        )
        v2_assert_reservation_anchors(reservation)
        return reservation
    except BaseException:
        v2_close_owned_descriptor_slots((
            (
                terminal_descriptor_slot,
                InfrastructureFailed(
                    "v2 failed terminal reservation descriptor close failed"
                ),
            ),
            (
                output_descriptor_slot,
                InfrastructureFailed(
                    "v2 failed output reservation descriptor close failed"
                ),
            ),
            (
                parent_descriptor_slot,
                InfrastructureFailed(
                    "v2 failed parent reservation descriptor close failed"
                ),
            ),
        ), surface_failure=False)
        failed_reservation = list.__getitem__(_reservation_slot, 0)
        if type(failed_reservation) is V2BundleReservation:
            try:
                v2_close_owned_reservation_slot(
                    _reservation_slot,
                    surface_failure=False,
                )
            except BaseException:
                pass
        raise


def v2_reserve_bundle(
    *,
    artifact_root: str,
    artifact_dir: str,
    _reservation_slot: list[V2BundleReservation | None],
) -> V2BundleReservation:
    if (
        type(_reservation_slot) is not list
        or len(_reservation_slot) != 1
        or list.__getitem__(_reservation_slot, 0) is not None
    ):
        raise EvidenceFailed(
            "v2 bundle destination reservation slot is not empty"
        )
    try:
        return _v2_reserve_bundle(
            artifact_root=artifact_root,
            artifact_dir=artifact_dir,
            _reservation_slot=_reservation_slot,
        )
    except BaseException as error:
        failed_reservation = list.__getitem__(_reservation_slot, 0)
        if type(failed_reservation) is V2BundleReservation:
            try:
                v2_close_owned_reservation_slot(
                    _reservation_slot,
                    surface_failure=False,
                )
            except BaseException:
                pass
        if v2_raw_instance_of(error, HarnessError):
            raise
        if v2_raw_instance_of(error, OSError):
            raise InfrastructureFailed(
                "v2 bundle reservation failed at the filesystem boundary"
            ) from error
        raise


def v2_expected_bundle_directories(
    names: Iterable[str],
) -> list[str]:
    expected: dict[str, None] = {}
    for name in names:
        parent = PurePosixPath(name).parent
        while str(parent) != ".":
            expected[str(parent)] = None
            parent = parent.parent
    return sorted(expected, key=lambda value: str.encode(value, "utf-8"))


def v2_validate_bundle_enumeration_budget(
    *,
    file_count: int,
    directory_count: int,
    path_bytes: int,
    error_type: type[HarnessError] = EvidenceFailed,
) -> None:
    values = (file_count, directory_count, path_bytes)
    if any(type(value) is not int or value < 0 for value in values):
        raise error_type("v2 bundle enumeration budget uses invalid counters")
    if file_count > V2_BUNDLE_FILES_CAP:
        raise error_type("v2 bundle exceeds its file-count cap")
    if directory_count > V2_BUNDLE_DIRECTORIES_CAP:
        raise error_type("v2 bundle exceeds its directory-count cap")
    if file_count + directory_count > (
        V2_BUNDLE_FILES_CAP + V2_BUNDLE_DIRECTORIES_CAP
    ):
        raise error_type("v2 bundle exceeds its aggregate entry cap")
    if path_bytes > V2_BUNDLE_ENUMERATED_PATH_BYTES_CAP:
        raise error_type("v2 bundle exceeds its enumerated-path byte cap")


def v2_validate_artifact_size(
    byte_length: int,
    *,
    label: str,
    error_type: type[HarnessError] = EvidenceFailed,
) -> None:
    if type(byte_length) is not int or byte_length < 0:
        raise error_type(f"{label} uses an invalid artifact byte count")
    if byte_length > RUN_ARTIFACT_CAP:
        raise error_type(f"{label} exceeds its artifact cap")


def v2_validate_aggregate_byte_count(
    byte_length: int,
    *,
    cap: int,
    label: str,
    error_type: type[HarnessError] = EvidenceFailed,
) -> None:
    if (
        type(byte_length) is not int
        or byte_length < 0
        or type(cap) is not int
        or cap < 0
    ):
        raise error_type(f"{label} uses an invalid aggregate byte count")
    if byte_length > cap:
        raise error_type(f"{label} exceeds its aggregate byte cap")


def v2_validate_canonical_byte_size(
    value: Any,
    *,
    cap: int,
    label: str,
    error_type: type[HarnessError] = EvidenceFailed,
) -> int:
    if type(cap) is not int or cap < 0:
        raise error_type(f"{label} uses an invalid canonical byte cap")
    byte_length = 1  # canonical_bytes appends one terminal newline.
    encoder = json.JSONEncoder(
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
    )
    try:
        for chunk in json.JSONEncoder.iterencode(encoder, value):
            byte_length += len(str.encode(chunk, "utf-8"))
            if byte_length > cap:
                raise error_type(
                    f"{label} exceeds its aggregate byte cap"
                )
    except error_type:
        raise
    except (TypeError, ValueError) as error:
        raise error_type(
            f"{label} is not canonically JSON serializable"
        ) from error
    return byte_length


def v2_preflight_publication_topology(
    payloads: Mapping[str, bytes],
) -> tuple[list[str], list[str]]:
    if type(payloads) is not dict:
        raise EvidenceFailed(
            "v2 publication payload collection must be an exact dictionary"
        )
    v2_validate_bundle_enumeration_budget(
        file_count=dict.__len__(payloads),
        directory_count=0,
        path_bytes=0,
    )
    names: list[str] = []
    for raw_name, payload in dict.items(payloads):
        if type(raw_name) is not str or type(payload) is not bytes:
            raise EvidenceFailed(
                "v2 publication payload keys and values must use exact "
                "strings and bytes"
            )
        try:
            relative = safe_relative(raw_name, label="v2 artifact member")
        except UsageRefused as error:
            raise EvidenceFailed("v2 publication member path is unsafe") from error
        if str(relative) != raw_name:
            raise EvidenceFailed("v2 publication member path is noncanonical")
        v2_validate_artifact_size(
            len(payload),
            label=f"v2 publication member {raw_name}",
        )
        names.append(raw_name)
    names = sorted(names, key=lambda value: value.encode("utf-8"))
    if len(names) != len(set(names)) or "terminal.json" not in names:
        raise EvidenceFailed(
            "v2 publication topology lacks unique terminal membership"
        )
    directories = v2_expected_bundle_directories(names)
    path_bytes = 0
    for value in [*names, *directories]:
        path_bytes += len(bytes(value, "utf-8"))
    v2_validate_bundle_enumeration_budget(
        file_count=len(names),
        directory_count=len(directories),
        path_bytes=path_bytes,
    )
    if set(names) & set(directories):
        raise EvidenceFailed(
            "v2 publication topology contains a file/directory prefix collision"
        )
    aliases: dict[str, str] = {}
    for relative in [*directories, *names]:
        alias = v2_exact_normalized_casefold(
            relative,
            normalization="NFC",
            label="v2 publication topology member",
            error_type=EvidenceFailed,
        )
        if alias in aliases:
            raise EvidenceFailed(
                "v2 publication topology contains a Unicode/case alias"
            )
        aliases[alias] = relative
    return names, directories


def _v2_open_reserved_directory_owned(
    reservation: V2BundleReservation,
    relative: PurePosixPath,
    *,
    create: bool,
    descriptor_slot: list[int | None],
    child_slot: list[int | None],
) -> int:
    output_descriptor = reservation.output_descriptor
    if output_descriptor is None:
        raise EvidenceFailed("v2 output directory descriptor is closed")
    try:
        list.__setitem__(descriptor_slot, 0, os.dup(output_descriptor))
    except OSError as error:
        raise InfrastructureFailed(
            "v2 publication output descriptor could not be duplicated"
        ) from error
    directory_flags = os.O_RDONLY | os.O_DIRECTORY
    directory_flags |= os.O_NOFOLLOW
    try:
        for part in relative.parts:
            if part in {"", "."}:
                continue
            descriptor = list.__getitem__(descriptor_slot, 0)
            if descriptor is None:
                raise InfrastructureFailed(
                    "v2 publication directory descriptor ownership was lost"
                )
            if create:
                try:
                    os.mkdir(part, 0o755, dir_fd=descriptor)
                except FileExistsError:
                    pass
                except OSError as error:
                    raise InfrastructureFailed(
                        "v2 publication directory could not be created"
                    ) from error
            try:
                list.__setitem__(child_slot, 0, os.open(part, directory_flags, dir_fd=descriptor))
            except OSError as error:
                if error.errno in {errno.ELOOP, errno.ENOTDIR}:
                    raise EvidenceFailed(
                        "v2 publication path component is unsafe"
                    ) from error
                raise InfrastructureFailed(
                    "v2 publication path component could not be opened"
                ) from error
            try:
                next_descriptor = list.__getitem__(child_slot, 0)
                if next_descriptor is None:
                    raise InfrastructureFailed(
                        "v2 publication child descriptor ownership was lost"
                    )
                value = os.fstat(next_descriptor)
                if not stat.S_ISDIR(value.st_mode):
                    raise EvidenceFailed(
                        "v2 publication path component is not a directory"
                    )
                if create:
                    os.fsync(descriptor)
            except OSError as error:
                v2_collect_owned_descriptor_slot_close_failure(
                    child_slot,
                    InfrastructureFailed(
                        "v2 publication child descriptor close failed"
                    ),
                )
                raise InfrastructureFailed(
                    "v2 publication path component metadata or durability "
                    "check failed"
                ) from error
            except BaseException:
                v2_collect_owned_descriptor_slot_close_failure(
                    child_slot,
                    InfrastructureFailed(
                        "v2 publication child descriptor close failed"
                    ),
                )
                raise
            parent_close_failure = (
                v2_collect_owned_descriptor_slot_close_failure(
                    descriptor_slot,
                    InfrastructureFailed(
                        "v2 publication parent descriptor close failed"
                    ),
                )
            )
            if parent_close_failure is not None:
                v2_collect_owned_descriptor_slot_close_failure(
                    child_slot,
                    InfrastructureFailed(
                        "v2 publication child descriptor close failed"
                    ),
                )
                v2_raise_descriptor_close_failure(parent_close_failure)
            v2_transfer_owned_descriptor_slot(
                child_slot,
                descriptor_slot,
            )
        descriptor = list.__getitem__(descriptor_slot, 0)
        if descriptor is None:
            raise InfrastructureFailed(
                "v2 publication directory descriptor ownership was lost"
            )
        return descriptor
    except BaseException:
        v2_collect_owned_descriptor_slot_close_failure(
            child_slot,
            InfrastructureFailed(
                "v2 publication child descriptor close failed"
            ),
        )
        v2_collect_owned_descriptor_slot_close_failure(
            descriptor_slot,
            InfrastructureFailed(
                "v2 publication directory descriptor close failed"
            ),
        )
        raise


def v2_open_reserved_directory(
    reservation: V2BundleReservation,
    relative: PurePosixPath,
    *,
    create: bool,
    _descriptor_slot: list[int | None],
) -> int:
    if (
        type(_descriptor_slot) is not list
        or len(_descriptor_slot) != 1
        or list.__getitem__(_descriptor_slot, 0) is not None
    ):
        raise EvidenceFailed(
            "v2 publication destination descriptor slot is not empty"
        )
    descriptor_slot = _descriptor_slot
    child_slot: list[int | None] = [None]
    try:
        return _v2_open_reserved_directory_owned(
            reservation,
            relative,
            create=create,
            descriptor_slot=descriptor_slot,
            child_slot=child_slot,
        )
    except BaseException:
        v2_close_owned_descriptor_slots((
            (
                child_slot,
                InfrastructureFailed(
                    "v2 publication child descriptor close failed"
                ),
            ),
            (
                descriptor_slot,
                InfrastructureFailed(
                    "v2 publication directory descriptor close failed"
                ),
            ),
        ), surface_failure=False)
        raise


def v2_write_reserved_member(
    reservation: V2BundleReservation,
    *,
    relative: PurePosixPath,
    payload: bytes,
) -> dict[str, int]:
    v2_validate_artifact_size(
        len(payload),
        label="v2 writer payload",
    )
    parent_descriptor_slot: list[int | None] = [None]
    descriptor_slot: list[int | None] = [None]
    identity: dict[str, int] | None = None
    operation_succeeded = False
    try:
        v2_open_reserved_directory(
            reservation,
            relative.parent,
            create=True,
            _descriptor_slot=parent_descriptor_slot,
        )
        parent_descriptor = list.__getitem__(parent_descriptor_slot, 0)
        if parent_descriptor is None:
            raise InfrastructureFailed(
                "v2 reserved member parent descriptor ownership was lost"
            )
        flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
        flags |= os.O_NOFOLLOW
        try:
            list.__setitem__(descriptor_slot, 0, os.open(relative.name, flags, 0o644, dir_fd=parent_descriptor))
        except FileExistsError as error:
            raise EvidenceFailed(
                f"v2 overwrite is forbidden for {relative}"
            ) from error
        descriptor = list.__getitem__(descriptor_slot, 0)
        if descriptor is None:
            raise InfrastructureFailed(
                "v2 reserved member descriptor ownership was lost"
            )
        written = 0
        while written < len(payload):
            count = os.write(descriptor, payload[written:])
            if (
                type(count) is not int
                or count <= 0
                or count > len(payload) - written
            ):
                raise InfrastructureFailed(
                    "v2 reserved member observed an invalid write count"
                )
            written += count
        os.fsync(descriptor)
        identity = v2_stat_identity(os.fstat(descriptor))
        os.fsync(parent_descriptor)
        operation_succeeded = True
    except HarnessError:
        raise
    except OSError as error:
        raise InfrastructureFailed(
            f"v2 descriptor-relative write failed for {relative}"
        ) from error
    finally:
        v2_close_owned_descriptor_slots((
            (
                descriptor_slot,
                InfrastructureFailed(
                    "v2 reserved member descriptor close failed: "
                    f"{relative}"
                ),
            ),
            (
                parent_descriptor_slot,
                InfrastructureFailed(
                    "v2 reserved member parent descriptor close failed: "
                    f"{relative}"
                ),
            ),
        ), surface_failure=operation_succeeded)
    if identity is None:
        raise InfrastructureFailed(
            f"v2 descriptor-relative write produced no identity for {relative}"
        )
    return identity


def v2_read_descriptor_strict(
    descriptor: int,
    *,
    label: str,
    expected_identity: Mapping[str, int] | None = None,
) -> bytes:
    try:
        before = os.fstat(descriptor)
        if not stat.S_ISREG(before.st_mode) or before.st_nlink != 1:
            raise InputRefused(f"{label} is not a uniquely linked regular file")
        identity = v2_stat_identity(before)
        if expected_identity is not None and identity != dict(expected_identity):
            raise InputRefused(f"{label} changed descriptor identity")
        if before.st_size > RUN_ARTIFACT_CAP:
            raise InputRefused(f"{label} exceeds the v2 artifact cap")
        chunks: list[bytes] = []
        offset = 0
        while offset < before.st_size:
            chunk = os.pread(
                descriptor,
                min(1024 * 1024, before.st_size - offset),
                offset,
            )
            if not chunk:
                raise InputRefused(f"{label} changed while being read")
            chunks.append(chunk)
            offset += len(chunk)
        if os.pread(descriptor, 1, offset):
            raise InputRefused(f"{label} grew while being read")
        after = os.fstat(descriptor)
        if after.st_nlink != 1 or v2_stat_identity(after) != identity:
            raise InputRefused(f"{label} changed while being read")
        return b"".join(chunks)
    except InputRefused:
        raise
    except OSError as error:
        raise InputRefused(f"{label} failed during strict descriptor read") from error


def v2_read_reserved_member(
    reservation: V2BundleReservation,
    *,
    name: str,
    expected_identity: Mapping[str, int],
) -> bytes:
    if name == "terminal.json":
        descriptor = reservation.terminal_descriptor
        if descriptor is None:
            raise EvidenceFailed("v2 terminal descriptor is closed")
        return v2_read_descriptor_strict(
            descriptor,
            label="v2 reserved terminal",
            expected_identity=expected_identity,
        )
    relative = PurePosixPath(name)
    parent_descriptor_slot: list[int | None] = [None]
    descriptor_slot: list[int | None] = [None]
    payload: bytes | None = None
    operation_succeeded = False
    try:
        v2_open_reserved_directory(
            reservation,
            relative.parent,
            create=False,
            _descriptor_slot=parent_descriptor_slot,
        )
        parent_descriptor = list.__getitem__(parent_descriptor_slot, 0)
        if parent_descriptor is None:
            raise InfrastructureFailed(
                "v2 reserved artifact parent descriptor ownership was lost"
            )
        flags = os.O_RDONLY | os.O_NOFOLLOW
        list.__setitem__(descriptor_slot, 0, os.open(relative.name, flags, dir_fd=parent_descriptor))
        descriptor = list.__getitem__(descriptor_slot, 0)
        if descriptor is None:
            raise InfrastructureFailed(
                "v2 reserved artifact descriptor ownership was lost"
            )
        payload = v2_read_descriptor_strict(
            descriptor,
            label=f"v2 reserved artifact {name}",
            expected_identity=expected_identity,
        )
        operation_succeeded = True
    except InputRefused:
        raise
    except OSError as error:
        raise InputRefused(
            f"v2 reserved artifact {name} cannot be opened safely"
        ) from error
    finally:
        v2_close_owned_descriptor_slots((
            (
                descriptor_slot,
                InfrastructureFailed(
                    "v2 reserved artifact descriptor close failed: "
                    f"{name}"
                ),
            ),
            (
                parent_descriptor_slot,
                InfrastructureFailed(
                    "v2 reserved artifact parent descriptor close failed: "
                    f"{name}"
                ),
            ),
        ), surface_failure=operation_succeeded)
    if payload is None:
        raise InfrastructureFailed(
            f"v2 reserved artifact {name} produced no payload"
        )
    return payload


def v2_verify_reserved_publication(
    reservation: V2BundleReservation,
    *,
    payloads: Mapping[str, bytes],
    terminal_sealed: bool,
) -> None:
    v2_assert_reservation_anchors(reservation)
    expected_files, expected_directories = v2_preflight_publication_topology(
        payloads
    )
    try:
        observed_files, observed_directories, identities = v2_enumerate_bundle(
            reservation.output
        )
        if (
            observed_files != expected_files
            or observed_directories != expected_directories
        ):
            raise InfrastructureFailed(
                "v2 publication tree differs from its exact file/directory contract"
            )
        for name in expected_files:
            path_observed = v2_read_file_strict(
                reservation.output.joinpath(*PurePosixPath(name).parts),
                label=f"v2 published artifact {name}",
                expected_identity=identities[name],
            )
            writer_identity = reservation.written_identities.get(name)
            if writer_identity != identities[name]:
                raise InfrastructureFailed(
                    f"v2 writer/enumerator identity differs for {name}"
                )
            descriptor_observed = v2_read_reserved_member(
                reservation,
                name=name,
                expected_identity=writer_identity,
            )
            expected = (
                payloads[name]
                if name != "terminal.json" or terminal_sealed
                else b""
            )
            if path_observed != expected or descriptor_observed != expected:
                raise InfrastructureFailed(
                    f"v2 published bytes differ for {name}"
                )
    except InputRefused as error:
        raise InfrastructureFailed(
            "v2 publication could not be verified safely"
        ) from error
    v2_assert_reservation_anchors(reservation)


def _v2_publish_reserved_bundle(
    reservation: V2BundleReservation,
    *,
    payloads: Mapping[str, bytes],
) -> dict[str, Any]:
    if reservation.sealed or reservation.terminal_descriptor is None:
        raise EvidenceFailed("v2 artifact reservation is already consumed")
    expected_files, _ = v2_preflight_publication_topology(payloads)
    payload_map = {name: payloads[name] for name in expected_files}
    output_descriptor = reservation.output_descriptor
    descriptor = reservation.terminal_descriptor
    if output_descriptor is None or descriptor is None:
        raise EvidenceFailed("v2 artifact reservation descriptors are closed")

    # The reservation owns a fresh directory containing only its empty
    # terminal placeholder. Validate that exact prefix before writing any
    # caller-provided byte.
    v2_verify_reserved_publication(
        reservation,
        payloads={"terminal.json": payload_map["terminal.json"]},
        terminal_sealed=False,
    )
    nonterminal = [
        name for name in expected_files if name != "terminal.json"
    ]
    writes: list[str] = []
    for name in nonterminal:
        v2_assert_reservation_anchors(reservation)
        check_cancel()
        relative = PurePosixPath(name)
        reservation.written_identities[name] = v2_write_reserved_member(
            reservation,
            relative=relative,
            payload=payload_map[name],
        )
        writes.append(name)
        v2_assert_reservation_anchors(reservation)
    os.fsync(output_descriptor)
    v2_verify_reserved_publication(
        reservation,
        payloads=payload_map,
        terminal_sealed=False,
    )

    terminal_payload = payload_map["terminal.json"]
    # This is the final cancellation boundary. Everything after
    # terminal_assignment_started is a bounded, non-cancellable seal
    # transaction whose exact state is reported to the caller.
    v2_assert_reservation_anchors(reservation)
    check_cancel()
    reservation.terminal_assignment_started = True
    try:
        os.lseek(descriptor, 0, os.SEEK_SET)
        written = 0
        while written < len(terminal_payload):
            count = os.write(descriptor, terminal_payload[written:])
            if (
                type(count) is not int
                or count <= 0
                or count > len(terminal_payload) - written
            ):
                raise OSError("invalid write count for reserved v2 terminal")
            written += count
        os.ftruncate(descriptor, len(terminal_payload))
        os.fsync(descriptor)
        terminal_identity = v2_stat_identity(os.fstat(descriptor))
        reservation.written_identities["terminal.json"] = terminal_identity
        observed_terminal = v2_read_descriptor_strict(
            descriptor,
            label="v2 committed terminal descriptor",
            expected_identity=terminal_identity,
        )
        if observed_terminal != terminal_payload:
            raise InfrastructureFailed(
                "v2 committed terminal descriptor differs from its payload"
            )
        reservation.terminal_assignment_committed = True
    except OSError as error:
        raise InfrastructureFailed(
            "v2 reserved terminal seal could not be finalized"
        ) from error
    except InputRefused as error:
        raise InfrastructureFailed(
            "v2 reserved terminal seal could not be read back safely"
        ) from error
    v2_verify_reserved_publication(
        reservation,
        payloads=payload_map,
        terminal_sealed=True,
    )
    reservation.sealed = True
    writes.append("terminal.json")
    return {
        "artifact_dir": str(
            safe_relative(reservation.artifact_root, label="artifact root")
            / safe_relative(reservation.artifact_dir, label="artifact dir")
        ),
        "publication_order": writes,
        "terminal_content_sealed_last": True,
    }


def v2_publish_reserved_bundle(
    reservation: V2BundleReservation,
    *,
    payloads: Mapping[str, bytes],
) -> dict[str, Any]:
    try:
        return _v2_publish_reserved_bundle(
            reservation,
            payloads=payloads,
        )
    except HarnessError:
        raise
    except OSError as error:
        raise InfrastructureFailed(
            "v2 publication failed at the filesystem boundary"
        ) from error


def v2_publish_bundle(
    *,
    artifact_root: str,
    artifact_dir: str,
    payloads: Mapping[str, bytes],
) -> dict[str, Any]:
    body_succeeded = False
    result: dict[str, Any] | None = None
    reservation_slot: list[V2BundleReservation | None] = [None]
    reservation: V2BundleReservation | None = None
    active_primary: BaseException | None = None
    cleanup_started = False
    try:
        try:
            v2_reserve_bundle(
                artifact_root=artifact_root,
                artifact_dir=artifact_dir,
                _reservation_slot=reservation_slot,
            )
            reservation = list.__getitem__(reservation_slot, 0)
            if type(reservation) is not V2BundleReservation:
                raise InfrastructureFailed(
                    "v2 publication reservation ownership was lost"
                )
            try:
                result = v2_publish_reserved_bundle(
                    reservation,
                    payloads=payloads,
                )
            except CancelledDrained as cancellation:
                raise v2_contextual_cancellation_error(
                    reservation,
                    publication_started=True,
                ) from cancellation
            if _cancel_requested:
                raise v2_contextual_cancellation_error(
                    reservation,
                    publication_started=True,
                )
            body_succeeded = True
            return result
        except BaseException as error:
            active_primary = error
            raise
        finally:
            cleanup_started = True
            try:
                v2_close_owned_reservation_slot(
                    reservation_slot,
                    surface_failure=body_succeeded,
                )
            except BaseException:
                # Cleanup remains attempt-all. A close-only failure surfaces
                # after success but never replaces an active body primary.
                if body_succeeded:
                    raise
    finally:
        try:
            if list.__getitem__(reservation_slot, 0) is not None:
                v2_close_owned_reservation_slot(
                    reservation_slot,
                    surface_failure=body_succeeded,
                )
        except BaseException:
            if active_primary is None and body_succeeded:
                raise
        if type(reservation) is V2BundleReservation:
            if reservation.cleanup_failures and result is not None:
                result["reservation_cleanup_failures"] = [
                    dict(row) for row in reservation.cleanup_failures
                ]
        if active_primary is not None:
            raise active_primary


def v2_synopsis(
    *,
    subject_mode: str,
    review_plan: Mapping[str, Any],
    history: Mapping[str, Any],
    authority: Mapping[str, Any],
    zero_sets: Mapping[str, Any],
    artifact_dir: str,
    reproduction: Sequence[str],
    explain_target: str | None,
) -> dict[str, Any]:
    children = review_plan.get("children") or []
    retained_without_direct_child = (
        review_plan.get("retained_without_direct_child") or []
    )
    selected_ids = sorted(
        {
            target_id
            for child in children
            for target_id in child.get("target_ids", [])
        }
        | {
            row["target_id"] for row in retained_without_direct_child
        }
        | {
            row["issue_id"] for row in history.get("rows", [])
        }
    )
    if explain_target is not None and explain_target not in selected_ids:
        raise InputRefused(f"--explain-target is not selected: {explain_target}")
    shown_ids = selected_ids[:V2_SYNOPSIS_ID_PREVIEW_CAP]
    work = review_plan.get("work") or {
        "total_review_minutes": 0,
        "minimum_child_review_minutes": 0,
        "maximum_child_review_minutes": 0,
    }
    decisions = authority.get("decisions") or []
    decision_by_target = {
        row.get("target_id"): row
        for row in decisions
        if isinstance(row, dict)
        and isinstance(row.get("target_id"), str)
        and row["target_id"]
    }
    selected_decisions = [
        decision_by_target[target_id]
        for target_id in selected_ids
        if target_id in decision_by_target
    ]
    if (
        explain_target is not None
        and explain_target not in decision_by_target
    ):
        raise EvidenceFailed(
            "--explain-target lacks an authority decision: "
            f"{explain_target}"
        )
    synopsis = {
        "schema": "frankensim.beads-template-hygiene.synopsis.v2",
        "mode": subject_mode,
        "counts": {
            "targets": len(selected_ids),
            "children": len(children),
            "readiness": dict(
                sorted(
                    Counter(
                        row["readiness"] for row in selected_decisions
                    ).items()
                )
            ),
            "routes": dict(
                sorted(
                    Counter(
                        row["remediation_route"]
                        for row in selected_decisions
                    ).items()
                )
            ),
            "owners": len(
                {
                    row["coordination_assignee"]
                    for row in selected_decisions
                    if row["coordination_assignee"]
                }
            ),
            "oversize": len(review_plan.get("oversize_content") or []),
            "zero_receipts": zero_sets.get("counts", {}).get(
                "zero_receipts", 0
            ),
        },
        "work": {
            "total_review_minutes": int(
                work.get("total_review_minutes", 0)
            ),
            "minimum_review_minutes": int(
                work.get("minimum_child_review_minutes", 0)
            ),
            "maximum_review_minutes": int(
                work.get("maximum_child_review_minutes", 0)
            ),
        },
        "capacity_wave_forecast": {
            f"P{priority}": sum(
                child.get("priority") == priority for child in children
            )
            for priority in range(5)
        },
        "active_conflicts": [
            row["target_id"]
            for row in selected_decisions
            if row["active_work_context"]["conflict"]
        ][:V2_SYNOPSIS_ID_PREVIEW_CAP],
        "top_blockers": [
            row["target_id"]
            for row in selected_decisions
            if row["readiness"] != "MECHANICALLY_APPLY_ELIGIBLE"
        ][:V2_SYNOPSIS_ID_PREVIEW_CAP],
        "selected_ids": {
            "total": len(selected_ids),
            "shown": len(shown_ids),
            "ids": shown_ids,
            "truncated": len(shown_ids) < len(selected_ids),
            "notice": (
                "synopsis-only ID preview truncated; machine artifacts are complete"
                if len(shown_ids) < len(selected_ids)
                else None
            ),
        },
        "why_grouped": (
            "hard priority/status/disposition/type/missing-set/semantic-"
            "disposition/semantic-receipt-state/semantic-action/readiness/"
            "remediation-route partitions plus target-complete compatibility "
            "receipts"
        ),
        "explanation": (
            {
                "target_id": explain_target,
                "authority_root": decision_by_target[explain_target][
                    "semantic_root"
                ],
            }
            if explain_target is not None
            else None
        ),
        "safe_next_action": (
            "review the retained child/history payload and its authority route; "
            "do not mutate a target from this planner"
        ),
        "artifacts": artifact_dir,
        "reproduction": list(reproduction),
        "no_claim": (
            "the synopsis is bounded operator guidance; complete machine "
            "artifacts remain untruncated and no authority is minted"
        ),
    }
    if len(canonical_bytes(synopsis)) > V2_SYNOPSIS_BYTES_CAP:
        raise EvidenceFailed("v2 synopsis exceeds its frozen UTF-8 byte cap")
    return synopsis


def v2_contextual_cancellation_error(
    reservation: V2BundleReservation,
    *,
    publication_started: bool,
) -> HarnessError:
    try:
        v2_assert_reservation_anchors(reservation)
    except (HarnessError, OSError):
        return InfrastructureFailed(
            "v2 cancellation coincided with reservation path-identity loss; "
            "manual verification of the reserved bundle is required"
        )
    if reservation.sealed or reservation.terminal_assignment_committed:
        return InfrastructureFailed(
            "v2 cancellation surfaced after a durable terminal commit; "
            "manual verification of the reserved bundle is required"
        )
    if reservation.terminal_assignment_started:
        return InfrastructureFailed(
            "v2 cancellation surfaced after terminal assignment began but "
            "before a verified durable commit; manual verification of the "
            "reserved bundle is required"
        )
    nonterminal_members = sorted(
        set(reservation.written_identities) - {"terminal.json"},
        key=lambda value: value.encode("utf-8"),
    )
    if publication_started or nonterminal_members:
        if nonterminal_members:
            return CancelledDrained(
                "cancellation requested; a retained incomplete nonterminal "
                f"publication prefix with {len(nonterminal_members)} member(s) "
                "remains unsealed; retry with a fresh run directory; no Bead "
                "mutation occurred"
            )
        return CancelledDrained(
            "cancellation requested at publication start; an empty "
            "terminal-only reservation remains unsealed; retry with a fresh "
            "run directory; no Bead mutation occurred"
        )
    return CancelledDrained(
        "cancellation requested before publication; an empty terminal-only "
        "reservation remains unsealed; retry with a fresh run directory; no "
        "Bead mutation occurred"
    )


def _v2_execute_live_plan_owned(
    *,
    mode: str,
    parsed: argparse.Namespace,
    manifest: Mapping[str, Any],
    br_cwd: Path = REPO_ROOT,
    _reservation_slot: list[V2BundleReservation | None],
) -> dict[str, Any]:
    artifact_dir = require_v2_artifact_grammar(parsed)
    output = resolve_run_dir(
        parsed.artifact_root,
        artifact_dir,
        label="v2 artifact dir",
    )
    require_fresh_run_dir(output, label="v2 artifact run directory")
    priority_filter = v2_parse_csv_set(
        parsed.priorities,
        allowed={f"P{priority}" for priority in range(5)},
        label="--priorities",
    )
    status_filter = v2_parse_status_set(
        parsed.statuses,
        label="--statuses",
    )
    target_filter = v2_parse_target_set(
        parsed.targets,
        label="--targets",
    )
    readiness_filter = v2_parse_csv_set(
        parsed.readiness,
        allowed=V2_READINESS_STATES,
        label="--readiness",
    )
    route_filter = v2_parse_csv_set(
        parsed.routes,
        allowed=V2_REMEDIATION_ROUTES,
        label="--routes",
    )
    if mode == "history-plan" and (
        readiness_filter is not None or route_filter is not None
    ):
        raise UsageRefused(
            "--readiness and --routes select review-plan authority decisions; "
            "history-plan accepts status, priority, and exact target filters"
        )
    reproduction = v2_reproduction_argv(
        mode=mode,
        artifact_root=parsed.artifact_root,
        artifact_dir=artifact_dir,
        review_receipts=parsed.review_receipts,
        prior_campaign=parsed.prior_campaign,
        priorities=(
            ",".join(sorted(priority_filter))
            if priority_filter is not None
            else None
        ),
        statuses=(
            ",".join(sorted(status_filter))
            if status_filter is not None
            else None
        ),
        targets=(
            ",".join(sorted(target_filter))
            if target_filter is not None
            else None
        ),
        readiness=(
            ",".join(sorted(readiness_filter))
            if readiness_filter is not None
            else None
        ),
        routes=(
            ",".join(sorted(route_filter))
            if route_filter is not None
            else None
        ),
        max_targets=parsed.max_targets_per_child,
        explain_target=parsed.explain_target,
    )
    body_succeeded = False
    published_refusal: PublishedV2Refusal | None = None
    synopsis: dict[str, Any] | None = None
    stage = "source_capture_round_1"
    publication_started = False
    available_roots: dict[str, str | None] = {
        "source": None,
        "inventory": None,
        "authority": None,
        "review_plan": None,
        "history": None,
        "zero_sets": None,
    }
    reservation_slot = _reservation_slot
    reservation: V2BundleReservation | None = None
    try:
        v2_reserve_bundle(
            artifact_root=parsed.artifact_root,
            artifact_dir=artifact_dir,
            _reservation_slot=reservation_slot,
        )
        reservation = list.__getitem__(reservation_slot, 0)
        if type(reservation) is not V2BundleReservation:
            raise InfrastructureFailed(
                "v2 live-plan reservation ownership was lost"
            )
        _command_receipts.clear()
        rule_contract = v2_source_rule_contract()
        before = v2_capture_live_round(
            manifest,
            rule_contract,
            ordinal=1,
            br_cwd=br_cwd,
        )
        before_fields = v2_exact_live_capture_round(
            before,
            label="v2 live-plan source round 1",
        )
        v2_validate_status_filter_membership(
            status_filter,
            dict.__getitem__(before_fields, "full_issues"),
            label="--statuses",
            error_type=UsageRefused,
        )
        stage = "history_audit_between_source_rounds"
        if mode == "history-plan":
            audit_ids = v2_history_audit_ids_from_round(
                before,
                manifest=manifest,
                priority_filter=priority_filter,
                status_filter=status_filter,
                target_filter=target_filter,
            )
            audit_capture = v2_capture_histories(
                audit_ids,
                br_cwd=br_cwd,
            )
        else:
            audit_capture = v2_not_requested_audit_capture()
        stage = "source_capture_round_2"
        after = v2_capture_live_round(
            manifest,
            rule_contract,
            ordinal=2,
            br_cwd=br_cwd,
        )
        check_cancel()
        stage = "source_capture_coherence"
        snapshot = v2_finalize_live_capture_pair(
            manifest,
            before=before,
            after=after,
            audit_capture=audit_capture,
        )
        stage = "campaign_epoch"
        campaign_root, _ = v2_campaign_epoch(snapshot)
        stage = "inventory"
        inventory = v2_build_inventory(
            snapshot,
            campaign_epoch_root=campaign_root,
            priority_filter=priority_filter,
            status_filter=status_filter,
            target_filter=target_filter,
            readiness_filter=readiness_filter,
            route_filter=route_filter,
        )
        available_roots["inventory"] = inventory["semantic_root"]
        if mode == "history-plan":
            expected_audit_ids = sorted(
                {
                    row["id"]
                    for row in inventory["rows"]
                    if row["status"] == "closed"
                }
                | {
                    str(
                        manifest["history_contract"][
                            "legacy_coverage_anchor_issue"
                        ]
                    )
                }
            )
            if audit_capture["issue_ids"] != expected_audit_ids:
                raise EvidenceFailed(
                    "v2 bracketed history audit membership differs from the "
                    "post-capture selected inventory"
                )
        stage = "review_receipt_admission"
        review_receipts = v2_load_review_receipts(
            parsed.review_receipts,
            inventory=inventory,
        )
        stage = "authority"
        version = str(snapshot.source["br_version"]["version"])
        authority = v2_derive_authority(
            inventory,
            review_receipts,
            current_br_version=version,
        )
        available_roots["authority"] = authority["semantic_root"]
        stage = "prior_campaign"
        prior_campaign = v2_load_prior_campaign(
            parsed.prior_campaign,
            accepted_manifest=manifest,
            current_source_files=snapshot.source["source_files"],
        )
        stage = "source_assembly"
        source = v2_build_source_document(
            snapshot=snapshot,
            manifest=manifest,
            inventory=inventory,
            review_receipts=review_receipts,
            prior_campaign=prior_campaign,
            audit_capture=audit_capture,
            priority_filter=priority_filter,
            status_filter=status_filter,
            target_filter=target_filter,
            readiness_filter=readiness_filter,
            route_filter=route_filter,
        )
        available_roots["source"] = source["semantic_root"]
        stage = "selected_projection"
        if mode == "review-plan":
            review_plan, optional_payloads = v2_build_review_plan(
                inventory,
                authority,
                max_targets=parsed.max_targets_per_child,
                review_receipts=review_receipts,
            )
            history = v2_not_requested(
                schema=V2_HISTORY_SCHEMA,
                mode=mode,
                source_root=source["semantic_root"],
                inventory_root=inventory["semantic_root"],
                projection="history",
            )
        else:
            review_plan = v2_not_requested(
                schema=V2_REVIEW_PLAN_SCHEMA,
                mode=mode,
                source_root=source["semantic_root"],
                inventory_root=inventory["semantic_root"],
                projection="review-plan",
            )
            optional_payloads = {}
            history = v2_build_history(
                source_root=source["semantic_root"],
                inventory=inventory,
                authority=authority,
                all_issues=snapshot.all_issues,
                audit_capture=audit_capture,
                history_contract=manifest["history_contract"],
            )
        available_roots["review_plan"] = review_plan["semantic_root"]
        available_roots["history"] = history["semantic_root"]
        stage = "zero_sets"
        zero_sets = v2_build_zero_sets(
            source_root=source["semantic_root"],
            inventory=inventory,
            prior_campaign=prior_campaign,
            current_universe=snapshot.all_issues,
            current_finding_ids=v2_snapshot_current_finding_ids(snapshot),
        )
        available_roots["zero_sets"] = zero_sets["semantic_root"]
        stage = "bundle_assembly"
        payloads = v2_bundle_payloads(
            mode=mode,
            subject_mode=mode,
            artifact_root=parsed.artifact_root,
            artifact_dir=artifact_dir,
            source=source,
            inventory=inventory,
            authority=authority,
            review_plan=review_plan,
            history=history,
            zero_sets=zero_sets,
            optional_payloads=optional_payloads,
            reproduction=reproduction,
            current_source_files=snapshot.source["source_files"],
        )
        stage = "synopsis"
        synopsis = v2_synopsis(
            subject_mode=mode,
            review_plan=review_plan,
            history=history,
            authority=authority,
            zero_sets=zero_sets,
            artifact_dir=str(
                safe_relative(parsed.artifact_root, label="artifact root")
                / safe_relative(artifact_dir, label="artifact dir")
            ),
            reproduction=reproduction,
            explain_target=parsed.explain_target,
        )
        check_cancel()
        stage = "publication"
        publication_started = True
        v2_publish_reserved_bundle(
            reservation,
            payloads=payloads,
        )
        if _cancel_requested:
            raise v2_contextual_cancellation_error(
                reservation,
                publication_started=True,
            )
        body_succeeded = True
        return synopsis
    except HarnessError as error:
        if type(reservation) is not V2BundleReservation:
            raise
        error_terminal = v2_sealed_error_terminal(error)
        if v2_raw_instance_of(error, CancelledDrained):
            raise v2_contextual_cancellation_error(
                reservation,
                publication_started=publication_started,
            ) from error
        if (
            error_terminal in V2_SEMANTIC_REFUSAL_TERMINALS
            and not publication_started
            and not reservation.sealed
        ):
            refusal_payloads, failure = v2_refusal_bundle_payloads(
                mode=mode,
                artifact_root=parsed.artifact_root,
                artifact_dir=artifact_dir,
                manifest=manifest,
                error=error,
                stage=stage,
                available_roots=available_roots,
                argv=[str(SCRIPT_REL), *sys.argv[1:]],
            )
            try:
                v2_publish_reserved_bundle(
                    reservation,
                    payloads=refusal_payloads,
                )
                if _cancel_requested:
                    raise v2_contextual_cancellation_error(
                        reservation,
                        publication_started=True,
                    )
            except CancelledDrained as cancellation:
                raise v2_contextual_cancellation_error(
                    reservation,
                    publication_started=True,
                ) from cancellation
            terminal = strict_json_loads(
                refusal_payloads["terminal.json"],
                label="v2 refusal terminal",
                require_canonical=True,
            )
            result = v2_rooted(
                {
                    "schema": V2_REFUSAL_RESULT_SCHEMA,
                    "terminal": error_terminal,
                    "exit_code": TERMINAL_EXIT[error_terminal],
                    "subject_mode": mode,
                    "artifact_dir": str(
                        safe_relative(
                            parsed.artifact_root,
                            label="artifact root",
                        )
                        / safe_relative(artifact_dir, label="artifact dir")
                    ),
                    "terminal_root": terminal["semantic_root"],
                    "failure_root": failure["semantic_root"],
                    "first_divergence": failure["first_divergence"],
                    "recovery": failure["recovery"],
                    "complete_evidence_bundle": True,
                    "complete_green_prefix": False,
                    "no_claim": (
                        "the planner produced a complete typed refusal bundle "
                        "and did not mutate any Bead"
                    ),
                }
            )
            published_refusal = PublishedV2Refusal(
                terminal=error_terminal,
                document=result,
            )
            raise published_refusal from error
        if publication_started:
            if reservation.terminal_assignment_committed:
                detail = (
                    "terminal content was durably committed, but post-seal "
                    "verification failed"
                )
            elif reservation.terminal_assignment_started:
                detail = (
                    "terminal assignment began but did not reach a verified "
                    "durable commit"
                )
            else:
                detail = "terminal assignment never began"
            raise InfrastructureFailed(
                f"v2 publication failed; {detail}; manual recovery is required"
            ) from error
        raise


def v2_execute_live_plan(
    *,
    mode: str,
    parsed: argparse.Namespace,
    manifest: Mapping[str, Any],
    br_cwd: Path = REPO_ROOT,
) -> dict[str, Any]:
    reservation_slot: list[V2BundleReservation | None] = [None]
    cleanup_reservation: V2BundleReservation | None = None
    result: dict[str, Any] | None = None
    active_primary: BaseException | None = None
    body_succeeded = False
    cleanup_started = False
    try:
        try:
            result = _v2_execute_live_plan_owned(
                mode=mode,
                parsed=parsed,
                manifest=manifest,
                br_cwd=br_cwd,
                _reservation_slot=reservation_slot,
            )
            body_succeeded = True
            return result
        except BaseException as error:
            active_primary = error
            raise
        finally:
            cleanup_started = True
            cleanup_candidate = list.__getitem__(reservation_slot, 0)
            if type(cleanup_candidate) is V2BundleReservation:
                cleanup_reservation = cleanup_candidate
            try:
                v2_close_owned_reservation_slot(
                    reservation_slot,
                    surface_failure=body_succeeded,
                )
            except BaseException:
                # The wrapper owns cleanup independently of source/planning
                # work. Close-only failure surfaces only after body success.
                if body_succeeded:
                    raise
    finally:
        fallback_candidate = list.__getitem__(reservation_slot, 0)
        if (
            cleanup_reservation is None
            and type(fallback_candidate) is V2BundleReservation
        ):
            cleanup_reservation = fallback_candidate
        try:
            if fallback_candidate is not None:
                v2_close_owned_reservation_slot(
                    reservation_slot,
                    surface_failure=body_succeeded,
                )
        except BaseException:
            if active_primary is None and body_succeeded:
                raise
        if (
            type(cleanup_reservation) is V2BundleReservation
            and cleanup_reservation.cleanup_failures
        ):
            cleanup_evidence = [
                dict(row) for row in cleanup_reservation.cleanup_failures
            ]
            if body_succeeded and result is not None:
                result["reservation_cleanup_failures"] = cleanup_evidence
            if type(active_primary) is PublishedV2Refusal:
                refusal_document = dict(active_primary.document)
                dict.pop(refusal_document, "semantic_root", None)
                refusal_document["reservation_cleanup_failures"] = (
                    cleanup_evidence
                )
                active_primary.document = v2_rooted(refusal_document)
        if active_primary is not None:
            raise active_primary


def v2_stat_identity(value: os.stat_result) -> dict[str, int]:
    return {
        "device": value.st_dev,
        "inode": value.st_ino,
        "mode": value.st_mode,
        "link_count": value.st_nlink,
        "size": value.st_size,
        "mtime_ns": value.st_mtime_ns,
        "ctime_ns": value.st_ctime_ns,
    }


def v2_read_file_strict(
    path: Path,
    *,
    label: str,
    expected_identity: Mapping[str, int] | None = None,
) -> bytes:
    flags = os.O_RDONLY | os.O_NOFOLLOW
    descriptor_slot: list[int | None] = [None]
    payload: bytes | None = None
    operation_succeeded = False
    try:
        try:
            list.__setitem__(descriptor_slot, 0, os.open(path, flags))
        except OSError as error:
            raise InputRefused(f"{label} cannot be opened safely") from error
        descriptor = list.__getitem__(descriptor_slot, 0)
        if descriptor is None:
            raise InfrastructureFailed(
                f"{label} descriptor ownership was lost"
            )
        before = os.fstat(descriptor)
        if not stat.S_ISREG(before.st_mode):
            raise InputRefused(f"{label} is not a regular file")
        before_identity = v2_stat_identity(before)
        if before.st_nlink != 1:
            raise InputRefused(f"{label} has a hard-link alias")
        if (
            expected_identity is not None
            and before_identity != dict(expected_identity)
        ):
            raise InputRefused(f"{label} changed identity after enumeration")
        if before.st_size > RUN_ARTIFACT_CAP:
            raise InputRefused(f"{label} exceeds the v2 artifact cap")
        chunks: list[bytes] = []
        remaining = before.st_size
        while remaining:
            chunk = os.read(descriptor, min(1024 * 1024, remaining))
            if not chunk:
                raise InputRefused(f"{label} changed while being read")
            chunks.append(chunk)
            remaining -= len(chunk)
        if os.read(descriptor, 1):
            raise InputRefused(f"{label} grew while being read")
        after = os.fstat(descriptor)
        if after.st_nlink != 1 or v2_stat_identity(after) != before_identity:
            raise InputRefused(f"{label} changed while being read")
        payload = b"".join(chunks)
        operation_succeeded = True
    except InputRefused:
        raise
    except OSError as error:
        raise InputRefused(f"{label} failed during strict read") from error
    finally:
        v2_close_owned_descriptor_slots((
            (
                descriptor_slot,
                InfrastructureFailed(
                    f"{label} descriptor close failed"
                ),
            ),
        ), surface_failure=operation_succeeded)
    if payload is None:
        raise InfrastructureFailed(f"{label} strict read produced no payload")
    return payload


def v2_safe_member(value: str, *, label: str) -> str:
    try:
        return str(safe_relative(value, label=label))
    except UsageRefused as error:
        raise InputRefused(f"{label} is unsafe") from error


def v2_register_member_identity(
    seen: dict[tuple[int, int], str],
    *,
    device: int,
    inode: int,
    link_count: int,
    relative: str,
    kind: str,
) -> None:
    if kind not in {"directory", "file"}:
        raise EvidenceFailed("v2 bundle identity kind is unknown")
    identity = (device, inode)
    if identity in seen:
        raise InputRefused(
            "v2 bundle contains an inode alias between "
            f"{seen[identity]!r} and {relative!r}"
        )
    if kind == "file" and link_count != 1:
        raise InputRefused(
            f"v2 bundle file {relative!r} has an external hard-link alias"
        )
    seen[identity] = relative


def v2_enumerate_bundle(
    directory: Path,
) -> tuple[list[str], list[str], dict[str, dict[str, int]]]:
    files: list[str] = []
    directories: list[str] = []
    file_identities: dict[str, dict[str, int]] = {}
    identities: dict[tuple[int, int], str] = {}
    try:
        root_stat = os.lstat(directory)
    except OSError as error:
        raise InputRefused("v2 bundle root cannot be inspected safely") from error
    if not stat.S_ISDIR(root_stat.st_mode):
        raise InputRefused("v2 bundle root is not a directory")
    v2_register_member_identity(
        identities,
        device=root_stat.st_dev,
        inode=root_stat.st_ino,
        link_count=root_stat.st_nlink,
        relative=".",
        kind="directory",
    )
    stack = [directory]
    entry_count = 0
    enumerated_path_bytes = 0
    while stack:
        root = stack.pop()
        names: list[str] = []
        try:
            with os.scandir(root) as iterator:
                for entry in iterator:
                    entry_count += 1
                    if entry_count > (
                        V2_BUNDLE_FILES_CAP
                        + V2_BUNDLE_DIRECTORIES_CAP
                    ):
                        raise InputRefused(
                            "v2 bundle exceeds its aggregate entry cap"
                        )
                    names.append(entry.name)
        except InputRefused:
            raise
        except OSError as error:
            raise InputRefused(
                "v2 bundle directory changed during enumeration"
            ) from error
        child_directories: list[Path] = []
        for name in sorted(names, key=lambda value: value.encode("utf-8")):
            candidate = root / name
            try:
                member_stat = os.lstat(candidate)
            except OSError as error:
                raise InputRefused(
                    "v2 bundle member changed during enumeration"
                ) from error
            relative = candidate.relative_to(directory).as_posix()
            relative = v2_safe_member(relative, label="bundle member")
            enumerated_path_bytes += len(relative.encode("utf-8"))
            if (
                enumerated_path_bytes
                > V2_BUNDLE_ENUMERATED_PATH_BYTES_CAP
            ):
                raise InputRefused(
                    "v2 bundle exceeds its enumerated-path byte cap"
                )
            if stat.S_ISDIR(member_stat.st_mode):
                if len(directories) >= V2_BUNDLE_DIRECTORIES_CAP:
                    raise InputRefused(
                        "v2 bundle exceeds its directory-count cap"
                    )
                v2_register_member_identity(
                    identities,
                    device=member_stat.st_dev,
                    inode=member_stat.st_ino,
                    link_count=member_stat.st_nlink,
                    relative=relative,
                    kind="directory",
                )
                directories.append(relative)
                child_directories.append(candidate)
            elif stat.S_ISREG(member_stat.st_mode):
                if len(files) >= V2_BUNDLE_FILES_CAP:
                    raise InputRefused(
                        "v2 bundle exceeds its file-count cap"
                    )
                v2_register_member_identity(
                    identities,
                    device=member_stat.st_dev,
                    inode=member_stat.st_ino,
                    link_count=member_stat.st_nlink,
                    relative=relative,
                    kind="file",
                )
                files.append(relative)
                file_identities[relative] = v2_stat_identity(member_stat)
            else:
                raise InputRefused("v2 bundle contains an unsafe member")
        stack.extend(reversed(child_directories))
    files.sort(key=lambda value: value.encode("utf-8"))
    directories.sort(key=lambda value: value.encode("utf-8"))
    v2_assert_unique(files, label="v2 bundle files")
    aliases: dict[str, str] = {}
    for relative in [*directories, *files]:
        alias = v2_exact_normalized_casefold(
            relative,
            normalization="NFC",
            label="v2 bundle member",
            error_type=InputRefused,
        )
        if alias in aliases and aliases[alias] != relative:
            raise InputRefused("v2 bundle contains a Unicode/case path alias")
        aliases[alias] = relative
    return files, directories, file_identities


def v2_read_event_stream(
    payload: bytes,
    *,
    expected_terminal: str = "Pass",
) -> list[dict[str, Any]]:
    if not payload or not payload.endswith(b"\n"):
        raise InputRefused("v2 events.jsonl lacks a terminal newline")
    lines = payload.splitlines(keepends=True)
    v2_validate_log_event_count(
        len(lines),
        error_type=InputRefused,
    )
    events: list[dict[str, Any]] = []
    for index, line in enumerate(lines):
        if len(line) > V2_LOG_LINE_BYTES_CAP:
            raise InputRefused(f"v2 event line {index} exceeds its cap")
        document = strict_json_loads(
            line,
            label=f"v2 event line {index}",
            require_canonical=True,
        )
        if not isinstance(document, dict):
            raise InputRefused(f"v2 event line {index} is not an object")
        v2_exact_keys(
            document,
            V2_EVENT_FIELDS,
            label=f"v2 event line {index}",
        )
        if document["schema"] != V2_EVENT_SCHEMA or document["sequence"] != index:
            raise EvidenceFailed(f"v2 event sequence/schema differs at {index}")
        events.append(document)
    if (
        sum(event["terminal"] is not None for event in events) != 1
        or not events
        or events[-1]["terminal"] != expected_terminal
        or events[-1]["exit_code"] != TERMINAL_EXIT[expected_terminal]
        or (
            expected_terminal == "Pass"
            and (
                events[-1]["first_divergence"] is not None
                or events[-1]["recovery"] != "NOT_REQUIRED"
            )
        )
        or (
            expected_terminal != "Pass"
            and (
                not isinstance(events[-1]["first_divergence"], str)
                or not events[-1]["first_divergence"]
                or not isinstance(events[-1]["recovery"], str)
                or events[-1]["recovery"] == "NOT_REQUIRED"
            )
        )
    ):
        raise EvidenceFailed("v2 retained terminal event is not unique and last")
    return events


def v2_validate_source_full_issue(
    issue: Any,
    *,
    index: int,
) -> None:
    if type(issue) is not dict:
        raise InputRefused(f"v2 source all-issue row {index} is not an object")
    v2_exact_keys(
        issue,
        V2_SOURCE_ALL_ISSUE_FIELDS,
        label=f"v2 source all-issue row {index}",
    )
    issue_status = v2_validate_status(
        dict.__getitem__(issue, "status"),
        label=f"v2 source all-issue row {index} status",
        error_type=InputRefused,
    )
    string_fields = (
        "id",
        "title",
        "type",
        "status",
        "assignee",
        "owner",
        "parent",
        "description",
        "acceptance_criteria",
        "design",
        "notes",
        "updated_at",
        "created_at",
        "created_by",
        "closed_at",
        "close_reason",
        "closed_by_session",
        "due_at",
        "defer_until",
        "external_ref",
        "source_system",
        "agent_context",
        "deleted_at",
        "deleted_by",
        "delete_reason",
        "original_type",
        "compacted_at",
        "compacted_at_commit",
        "sender",
        "source_repo",
        "no_claim",
    )
    if (
        any(
            type(dict.__getitem__(issue, field)) is not str
            for field in string_fields
        )
        or not dict.__getitem__(issue, "id")
        or not str.strip(dict.__getitem__(issue, "title"))
        or not dict.__getitem__(issue, "type")
        or dict.__getitem__(issue, "status") != issue_status
        or type(dict.__getitem__(issue, "priority")) is not int
        or dict.__getitem__(issue, "priority") not in range(5)
        or type(dict.__getitem__(issue, "ephemeral")) is not bool
        or type(dict.__getitem__(issue, "pinned")) is not bool
        or type(dict.__getitem__(issue, "is_template")) is not bool
        or type(dict.__getitem__(issue, "compaction_level")) is not int
        or dict.__getitem__(issue, "compaction_level") < 0
        or (
            dict.__getitem__(issue, "original_size") is not None
            and (
                type(dict.__getitem__(issue, "original_size")) is not int
                or dict.__getitem__(issue, "original_size") < 0
            )
        )
        or dict.__getitem__(issue, "events") != []
        or dict.__getitem__(issue, "no_claim") != V2_SOURCE_ISSUE_NO_CLAIM
        or (
            dict.__getitem__(issue, "estimated_minutes") is not None
            and (
                type(dict.__getitem__(issue, "estimated_minutes")) is not int
                or dict.__getitem__(issue, "estimated_minutes") < 0
            )
        )
    ):
        raise InputRefused(
            f"v2 source all-issue row {index} has invalid core scalars"
        )
    released_fields_present = dict.__getitem__(
        issue,
        "released_fields_present",
    )
    if (
        not isinstance(released_fields_present, list)
        or released_fields_present != sorted(set(released_fields_present))
        or any(
            not isinstance(field, str)
            or field not in V2_RAW_BR_SHOW_FIELDS
            for field in released_fields_present
        )
        or not {"id", "title", "status", "priority"}.issubset(
            released_fields_present
        )
    ):
        raise InputRefused(
            f"v2 source all-issue row {index} released field-presence "
            "projection is malformed"
        )
    released_field_value_roots = dict.__getitem__(
        issue,
        "released_field_value_roots",
    )
    if (
        not isinstance(released_field_value_roots, dict)
        or list(released_field_value_roots) != released_fields_present
        or any(
            type(dict.__getitem__(released_field_value_roots, root_field))
            is not str
            or re.fullmatch(
                r"sha256-v1:[0-9a-f]{64}",
                dict.__getitem__(released_field_value_roots, root_field),
            )
            is None
            for root_field in dict.__iter__(released_field_value_roots)
        )
    ):
        raise InputRefused(
            f"v2 source all-issue row {index} released raw-value roots "
            "are malformed"
        )
    expected_source_issue_projection_root = semantic_root(
        {
            key: dict.__getitem__(issue, key)
            for key in V2_SOURCE_ALL_ISSUE_FIELDS
            if key not in {"no_claim", "source_issue_projection_root"}
        }
    )
    if (
        dict.__getitem__(issue, "source_issue_projection_root")
        != expected_source_issue_projection_root
    ):
        raise EvidenceFailed(
            f"v2 source all-issue row {index} projection root differs"
        )
    v2_validate_issue_id(
        dict.__getitem__(issue, "id"),
        label=f"v2 source all-issue row {index} ID",
        error_type=InputRefused,
    )
    if dict.__getitem__(issue, "parent"):
        v2_validate_issue_id(
            dict.__getitem__(issue, "parent"),
            label=f"v2 source all-issue row {index} parent ID",
            error_type=InputRefused,
        )
    labels = dict.__getitem__(issue, "labels")
    if (
        not isinstance(labels, list)
        or len(labels) > V2_LABELS_PER_ISSUE_CAP
        or any(not isinstance(value, str) or not value for value in labels)
        or labels != sorted(set(labels))
    ):
        raise InputRefused(
            f"v2 source all-issue row {index} has noncanonical labels"
        )
    comments = dict.__getitem__(issue, "comments")
    if (
        not isinstance(comments, list)
        or len(comments) > V2_AUDIT_EVENTS_PER_ISSUE_CAP
    ):
        raise InputRefused(
            f"v2 source all-issue row {index} has malformed comments"
        )
    previous_comment_order: tuple[datetime, int] | None = None
    comment_ids: dict[int, None] = {}
    for comment_index, comment in enumerate(comments):
        if type(comment) is not dict:
            raise InputRefused(
                f"v2 source comment {comment_index} is not an object"
            )
        v2_exact_keys(
            comment,
            V2_SOURCE_COMMENT_FIELDS,
            label=(
                f"v2 source all-issue row {index} comment {comment_index}"
            ),
        )
        if (
            type(dict.__getitem__(comment, "id")) is not int
            or dict.__getitem__(comment, "id") <= 0
            or dict.__getitem__(comment, "id") in comment_ids
            or dict.__getitem__(comment, "issue_id")
            != dict.__getitem__(issue, "id")
            or type(dict.__getitem__(comment, "author")) is not str
            or not dict.__getitem__(comment, "author")
            or type(dict.__getitem__(comment, "text")) is not str
            or type(dict.__getitem__(comment, "created_at")) is not str
        ):
            raise InputRefused(
                f"v2 source all-issue row {index} has invalid comment "
                f"{comment_index}"
            )
        comment_timestamp = v2_parse_timestamp(
            dict.__getitem__(comment, "created_at"),
            label=(
                f"v2 source all-issue row {index} comment {comment_index}"
            ),
        )
        comment_order = (
            comment_timestamp,
            dict.__getitem__(comment, "id"),
        )
        if (
            previous_comment_order is not None
            and comment_order <= previous_comment_order
        ):
            raise InputRefused(
                f"v2 source all-issue row {index} comments are noncanonical"
            )
        previous_comment_order = comment_order
        comment_ids[dict.__getitem__(comment, "id")] = None
    rollup = dict.__getitem__(issue, "rollup")
    if rollup is not None:
        if type(rollup) is not dict:
            raise InputRefused(
                f"v2 source all-issue row {index} rollup is not an object"
            )
        v2_exact_keys(
            rollup,
            V2_SOURCE_ROLLUP_FIELDS,
            label=f"v2 source all-issue row {index} rollup",
        )
        descendants = dict.__getitem__(rollup, "descendants")
        if (
            type(dict.__getitem__(rollup, "status")) is not str
            or not dict.__getitem__(rollup, "status")
            or type(descendants) is not dict
            or len(descendants) > V2_INVENTORY_ROWS_CAP
            or list(descendants) != sorted(descendants)
            or any(
                type(status) is not str
                or not status
                or type(dict.__getitem__(descendants, status)) is not int
                or dict.__getitem__(descendants, status) < 0
                for status in dict.__iter__(descendants)
            )
        ):
            raise InputRefused(
                f"v2 source all-issue row {index} rollup is malformed"
            )
        v2_validate_status(
            dict.__getitem__(rollup, "status"),
            label=f"v2 source all-issue row {index} rollup status",
            error_type=InputRefused,
        )
        for descendant_status in descendants:
            v2_validate_status(
                descendant_status,
                label=(
                    f"v2 source all-issue row {index} rollup descendant "
                    "status"
                ),
                error_type=InputRefused,
            )
    for relation_field in ("dependencies", "dependents"):
        relations = dict.__getitem__(issue, relation_field)
        if (
            not isinstance(relations, list)
            or len(relations) > V2_RELATIONS_PER_DIRECTION_CAP
        ):
            raise InputRefused(
                f"v2 source all-issue row {index} has malformed "
                f"{relation_field}"
            )
        for relation_index, relation in enumerate(relations):
            if type(relation) is not dict:
                raise InputRefused(
                    f"v2 source {relation_field} row {relation_index} "
                    "is not an object"
                )
            v2_exact_keys(
                relation,
                V2_SOURCE_RELATION_FIELDS,
                label=(
                    f"v2 source all-issue row {index} "
                    f"{relation_field} row {relation_index}"
                ),
            )
            relation_id = dict.__getitem__(relation, "id")
            relation_type = dict.__getitem__(relation, "type")
            relation_title = dict.__getitem__(relation, "title")
            relation_status = dict.__getitem__(relation, "status")
            relation_priority = dict.__getitem__(relation, "priority")
            if type(relation_status) is str:
                v2_validate_status(
                    relation_status,
                    label=(
                        f"v2 source all-issue row {index} "
                        f"{relation_field} row {relation_index} status"
                    ),
                    error_type=InputRefused,
                )
            if (
                type(relation_id) is not str
                or not relation_id
                or relation_id == dict.__getitem__(issue, "id")
                or (
                    type(relation_id) is str
                    and str.startswith(relation_id, "external:")
                    and (
                        relation_id == "external:"
                        or (
                            relation_field == "dependencies"
                            and relation_type == "parent-child"
                        )
                        or (
                            relation_field == "dependents"
                            and relation_type != "parent-child"
                        )
                    )
                )
                or type(relation_type) is not str
                or not relation_type
                or type(relation_title) is not str
                or not str.strip(relation_title)
                or type(relation_status) is not str
                or (
                    type(relation_priority) is not int
                    or relation_priority not in range(5)
                )
            ):
                raise InputRefused(
                    f"v2 source all-issue row {index} has an invalid "
                    f"{relation_field} row"
                )
            relation_label = (
                f"v2 source all-issue row {index} {relation_field} "
                f"row {relation_index} ID"
            )
            if str.startswith(relation_id, "external:"):
                v2_validate_external_relation_id(
                    relation_id,
                    label=relation_label,
                    error_type=InputRefused,
                )
            else:
                v2_validate_issue_id(
                    relation_id,
                    label=relation_label,
                    error_type=InputRefused,
                )
        relation_neighbors = [
            dict.__getitem__(relation, "id") for relation in relations
        ]
        if len(relation_neighbors) != len(set(relation_neighbors)):
            raise InputRefused(
                f"v2 source all-issue row {index} duplicates a "
                f"{relation_field} neighbor"
            )
        relation_order = [
            (
                dict.__getitem__(relation, "type"),
                dict.__getitem__(relation, "id"),
            )
            for relation in relations
        ]
        if relation_order != sorted(relation_order):
            raise InputRefused(
                f"v2 source all-issue row {index} has noncanonical "
                f"{relation_field}"
            )
    field_roots = dict.__getitem__(issue, "field_roots")
    if (
        not isinstance(field_roots, dict)
        or set(field_roots)
        != {"description", "acceptance_criteria", "design", "notes"}
        or field_roots
        != {
            field: text_root(dict.__getitem__(issue, field))
            for field in (
                "description",
                "acceptance_criteria",
                "design",
                "notes",
            )
        }
    ):
        raise EvidenceFailed(
            f"v2 source all-issue row {index} field roots disagree"
        )
    source_repo_path = dict.__getitem__(issue, "source_repo_path")
    if (
        not isinstance(source_repo_path, dict)
        or set(source_repo_path) != {"body_retained", "root"}
        or dict.__getitem__(source_repo_path, "body_retained") is not False
        or type(dict.__getitem__(source_repo_path, "root")) is not str
        or re.fullmatch(
            r"sha256-v1:[0-9a-f]{64}",
            dict.__getitem__(source_repo_path, "root"),
        )
        is None
    ):
        raise InputRefused(
            f"v2 source all-issue row {index} source path receipt is malformed"
        )


def v2_graph_node_index(
    node_index: Any,
    neighbor_id: Any,
) -> int:
    if (
        type(node_index) is not dict
        or dict.__len__(node_index) > V2_INVENTORY_ROWS_CAP
        or type(neighbor_id) is not str
    ):
        raise EvidenceFailed("v2 source graph node lookup is malformed")
    node_number = dict.get(node_index, neighbor_id)
    if (
        type(node_number) is not int
        or node_number < 0
        or node_number >= len(node_index)
    ):
        raise EvidenceFailed(
            "v2 source graph cycle adjacency names an absent node"
        )
    return node_number


def v2_graph_adjacency_mask(
    node_index: Any,
    neighbors: Any,
) -> int:
    exact_neighbors = v2_exact_string_sequence_snapshot(
        neighbors,
        label="v2 source graph cycle adjacency",
        cap=V2_RELATIONS_PER_DIRECTION_CAP,
        error_type=EvidenceFailed,
    )
    adjacency_mask = sum(
        1 << v2_graph_node_index(node_index, neighbor_id)
        for neighbor_id in exact_neighbors
    )
    if int.bit_count(adjacency_mask) != list.__len__(exact_neighbors):
        raise EvidenceFailed(
            "v2 source graph cycle adjacency repeats a neighbor"
        )
    return adjacency_mask


def v2_graph_adjacency_masks(
    adjacency: Any,
    node_ids: Any,
) -> tuple[int, ...]:
    if (
        type(adjacency) is not dict
        or dict.__len__(adjacency) > V2_INVENTORY_ROWS_CAP
        or type(node_ids) is not list
        or list.__len__(node_ids) > V2_INVENTORY_ROWS_CAP
        or list.__len__(node_ids) != dict.__len__(adjacency)
        or node_ids != sorted(set(node_ids))
        or any(
            type(node_id) is not str
            or not dict.__contains__(adjacency, node_id)
            for node_id in node_ids
        )
    ):
        raise EvidenceFailed("v2 source graph mask inputs are malformed")
    node_index = {
        node_id: index for index, node_id in enumerate(node_ids)
    }
    return tuple(
        v2_graph_adjacency_mask(
            node_index,
            dict.__getitem__(adjacency, node_id),
        )
        for node_id in node_ids
    )


def v2_graph_full_mask(node_count: Any) -> int:
    if type(node_count) is not int:
        raise EvidenceFailed("v2 source graph node count is malformed")
    if node_count < 0 or node_count > V2_INVENTORY_ROWS_CAP:
        raise EvidenceFailed("v2 source graph node count exceeds its bound")
    return (1 << node_count) - 1


def v2_graph_lowest_bit(mask: Any) -> int:
    if (
        type(mask) is not int
        or mask <= 0
        or int.bit_length(mask) > V2_INVENTORY_ROWS_CAP
    ):
        raise EvidenceFailed("v2 source graph pending mask is malformed")
    return mask & -mask


def v2_graph_node_number_from_bit(node_bit: Any) -> int:
    if (
        type(node_bit) is not int
        or node_bit <= 0
        or int.bit_length(node_bit) > V2_INVENTORY_ROWS_CAP
    ):
        raise EvidenceFailed("v2 source graph node bit is malformed")
    node_number = int.bit_length(node_bit) - 1
    if node_bit != 1 << node_number:
        raise EvidenceFailed("v2 source graph node bit is not singular")
    return node_number


def v2_graph_mask_without_bit(mask: Any, node_bit: Any) -> int:
    if (
        type(mask) is not int
        or mask < 0
        or int.bit_length(mask) > V2_INVENTORY_ROWS_CAP
    ):
        raise EvidenceFailed("v2 source graph mask is malformed")
    v2_graph_node_number_from_bit(node_bit)
    return mask & ~node_bit


def v2_graph_mask_with_bit(mask: Any, node_bit: Any) -> int:
    if (
        type(mask) is not int
        or mask < 0
        or int.bit_length(mask) > V2_INVENTORY_ROWS_CAP
    ):
        raise EvidenceFailed("v2 source graph mask is malformed")
    v2_graph_node_number_from_bit(node_bit)
    return mask | node_bit


def v2_graph_mask_contains_bit(mask: Any, node_bit: Any) -> bool:
    if (
        type(mask) is not int
        or mask < 0
        or int.bit_length(mask) > V2_INVENTORY_ROWS_CAP
    ):
        raise EvidenceFailed("v2 source graph mask is malformed")
    v2_graph_node_number_from_bit(node_bit)
    return bool(mask & node_bit)


def v2_graph_degree_width(node_count: Any) -> int:
    if (
        type(node_count) is not int
        or node_count < 0
        or node_count > V2_INVENTORY_ROWS_CAP
    ):
        raise EvidenceFailed("v2 source graph node count exceeds its bound")
    return max(1, int.bit_length(node_count))


def v2_graph_packed_degree(
    indegree_slots: Any,
    node_number: Any,
    degree_width: Any,
) -> int:
    if (
        type(indegree_slots) is not int
        or indegree_slots < 0
        or type(node_number) is not int
        or node_number < 0
        or node_number >= V2_INVENTORY_ROWS_CAP
        or type(degree_width) is not int
        or degree_width <= 0
        or degree_width > int.bit_length(V2_INVENTORY_ROWS_CAP)
        or int.bit_length(indegree_slots)
        > V2_INVENTORY_ROWS_CAP * degree_width
    ):
        raise EvidenceFailed("v2 source graph indegree state is malformed")
    degree_shift = node_number * degree_width
    degree_mask = (1 << degree_width) - 1
    return (indegree_slots >> degree_shift) & degree_mask


def v2_graph_increment_packed_degree(
    indegree_slots: Any,
    node_number: Any,
    degree_width: Any,
    node_count: Any,
) -> int:
    prior_indegree = v2_graph_packed_degree(
        indegree_slots,
        node_number,
        degree_width,
    )
    if (
        type(node_count) is not int
        or node_count < 0
        or node_count > V2_INVENTORY_ROWS_CAP
        or prior_indegree >= node_count
    ):
        raise EvidenceFailed("v2 source graph indegree exceeds its bound")
    return indegree_slots + (1 << (node_number * degree_width))


def v2_graph_decrement_packed_degree(
    indegree_slots: Any,
    node_number: Any,
    degree_width: Any,
) -> int:
    prior_indegree = v2_graph_packed_degree(
        indegree_slots,
        node_number,
        degree_width,
    )
    if prior_indegree <= 0:
        raise EvidenceFailed("v2 source graph indegree state is inconsistent")
    return indegree_slots - (1 << (node_number * degree_width))


def v2_graph_mask_with_node(mask: Any, node_number: Any) -> int:
    if type(mask) is not int or type(node_number) is not int:
        raise EvidenceFailed("v2 source graph mask update is malformed")
    if (
        mask < 0
        or int.bit_length(mask) > V2_INVENTORY_ROWS_CAP
        or node_number < 0
        or node_number >= V2_INVENTORY_ROWS_CAP
    ):
        raise EvidenceFailed("v2 source graph mask update exceeds its bound")
    return mask | (1 << node_number)


def v2_validate_source_graph_acyclic(
    adjacency: Any,
    *,
    node_ids: Any,
    relation_label: str,
) -> None:
    if type(adjacency) is not dict:
        raise EvidenceFailed("v2 source graph cycle contract is malformed")
    if type(relation_label) is not str:
        raise EvidenceFailed("v2 source graph cycle contract is malformed")
    if str.__eq__(str.strip(relation_label), "") is True:
        raise EvidenceFailed("v2 source graph cycle contract is malformed")
    if dict.__len__(adjacency) > V2_INVENTORY_ROWS_CAP:
        raise EvidenceFailed("v2 source graph cycle contract is malformed")
    try:
        adjacency = v2_validate_exact_json_wire(
            adjacency,
            label="v2 source graph cycle adjacency",
        )
    except HarnessError as error:
        raise EvidenceFailed(
            "v2 source graph cycle adjacency is malformed"
        ) from error
    if type(adjacency) is not dict:
        raise EvidenceFailed("v2 source graph cycle adjacency is malformed")
    node_ids = v2_exact_string_sequence_snapshot(
        node_ids,
        label="v2 source graph cycle node IDs",
        cap=V2_INVENTORY_ROWS_CAP,
        error_type=EvidenceFailed,
    )
    node_count = list.__len__(node_ids)
    if type(node_count) is not int:
        raise EvidenceFailed("v2 source graph node count is malformed")
    if (
        int.__ne__(node_count, dict.__len__(adjacency)) is True
        or int.__ne__(node_count, len(frozenset(node_ids))) is True
        or node_ids != sorted(node_ids)
    ):
        raise EvidenceFailed("v2 source graph node membership is malformed")
    for node_index, node_id in enumerate(list.__iter__(node_ids)):
        v2_validate_issue_id(
            node_id,
            label=f"v2 source graph node {node_index}",
            error_type=EvidenceFailed,
        )
        if dict.__contains__(adjacency, node_id) is not True:
            raise EvidenceFailed(
                "v2 source graph adjacency differs from its node membership"
            )
    adjacency_masks = v2_graph_adjacency_masks(adjacency, node_ids)
    if (
        type(adjacency_masks) is not tuple
        or tuple.__len__(adjacency_masks) != node_count
    ):
        raise EvidenceFailed("v2 source graph adjacency masks are malformed")
    degree_width = v2_graph_degree_width(node_count)
    indegree_slots = 0
    for adjacency_mask in tuple.__iter__(adjacency_masks):
        if type(adjacency_mask) is not int or adjacency_mask < 0:
            raise EvidenceFailed(
                "v2 source graph adjacency mask is malformed"
            )
        pending_neighbors = adjacency_mask
        while int.__ne__(pending_neighbors, 0) is True:
            neighbor_bit = v2_graph_lowest_bit(pending_neighbors)
            neighbor_number = v2_graph_node_number_from_bit(neighbor_bit)
            indegree_slots = v2_graph_increment_packed_degree(
                indegree_slots,
                neighbor_number,
                degree_width,
                node_count,
            )
            pending_neighbors = v2_graph_mask_without_bit(
                pending_neighbors,
                neighbor_bit,
            )
    ready_mask = 0
    for node_number in range(node_count):
        if v2_graph_packed_degree(
            indegree_slots,
            node_number,
            degree_width,
        ) == 0:
            ready_mask = v2_graph_mask_with_node(ready_mask, node_number)
    remaining = v2_graph_full_mask(node_count)
    while int.__ne__(ready_mask, 0) is True:
        node_bit = v2_graph_lowest_bit(ready_mask)
        ready_mask = v2_graph_mask_without_bit(ready_mask, node_bit)
        remaining = v2_graph_mask_without_bit(remaining, node_bit)
        node_number = v2_graph_node_number_from_bit(node_bit)
        adjacency_mask = tuple.__getitem__(adjacency_masks, node_number)
        pending_neighbors = adjacency_mask
        while int.__ne__(pending_neighbors, 0) is True:
            neighbor_bit = v2_graph_lowest_bit(pending_neighbors)
            neighbor_number = v2_graph_node_number_from_bit(neighbor_bit)
            prior_indegree = v2_graph_packed_degree(
                indegree_slots,
                neighbor_number,
                degree_width,
            )
            indegree_slots = v2_graph_decrement_packed_degree(
                indegree_slots,
                neighbor_number,
                degree_width,
            )
            if (
                prior_indegree == 1
                and v2_graph_mask_contains_bit(remaining, neighbor_bit)
            ):
                ready_mask = v2_graph_mask_with_bit(
                    ready_mask,
                    neighbor_bit,
                )
            pending_neighbors = v2_graph_mask_without_bit(
                pending_neighbors,
                neighbor_bit,
            )
    if int.__ne__(remaining, 0) is True:
        retained_cycle_nodes = [
            node_id
            for node_number, node_id in enumerate(node_ids)
            if v2_graph_mask_contains_bit(
                remaining,
                1 << node_number,
            )
        ]
        raise EvidenceFailed(
            "v2 source graph contains a "
            f"{relation_label}: remaining_nodes="
            f"{len(retained_cycle_nodes)}, "
            f"root={semantic_root(retained_cycle_nodes)}"
        )


def v2_validate_source_graph(
    all_issues: Sequence[Mapping[str, Any]],
) -> None:
    if type(all_issues) is not list:
        raise InputRefused("v2 source graph issues are not an exact array")
    issue_by_id: dict[str, dict[str, Any]] = {}
    for issue_index, issue in enumerate(list.__iter__(all_issues)):
        if type(issue) is not dict:
            raise InputRefused(
                f"v2 source graph issue {issue_index} is not an exact object"
            )
        v2_exact_keys(
            issue,
            V2_SOURCE_ALL_ISSUE_FIELDS,
            label=f"v2 source graph issue {issue_index}",
        )
        issue_id = dict.__getitem__(issue, "id")
        if (
            type(issue_id) is not str
            or not issue_id
            or dict.__contains__(issue_by_id, issue_id)
        ):
            raise InputRefused("v2 source graph issue membership is malformed")
        dict.__setitem__(issue_by_id, issue_id, issue)
    reverse_fields = (
        ("dependencies", "dependents"),
        ("dependents", "dependencies"),
    )

    def has_relation(
        relations: Sequence[Mapping[str, Any]],
        identity: tuple[str, str],
    ) -> bool:
        if type(relations) is not list:
            raise EvidenceFailed(
                "v2 source graph reciprocal relations are not an exact array"
            )
        lower = 0
        upper = len(relations)
        while lower < upper:
            midpoint = (lower + upper) // 2
            relation = list.__getitem__(relations, midpoint)
            relation_identity = (
                dict.__getitem__(relation, "type"),
                dict.__getitem__(relation, "id"),
            )
            if relation_identity < identity:
                lower = midpoint + 1
            else:
                upper = midpoint
        index = lower
        if index >= len(relations):
            return False
        relation = list.__getitem__(relations, index)
        return (
            dict.__getitem__(relation, "type"),
            dict.__getitem__(relation, "id"),
        ) == identity

    for issue_id in sorted(dict.__iter__(issue_by_id)):
        issue = dict.__getitem__(issue_by_id, issue_id)
        for relation_field, _reciprocal_field in reverse_fields:
            neighbors = [
                dict.__getitem__(relation, "id")
                for relation in dict.__getitem__(issue, relation_field)
            ]
            if (
                issue_id in neighbors
                or len(neighbors) != len(set(neighbors))
            ):
                raise EvidenceFailed(
                    "v2 source graph contains a self edge or duplicate "
                    f"neighbor for {issue_id}.{relation_field}"
                )
        parent_edges = sorted(
            dict.__getitem__(relation, "id")
            for relation in dict.__getitem__(issue, "dependencies")
            if dict.__getitem__(relation, "type") == "parent-child"
        )
        parent_id = dict.__getitem__(issue, "parent")
        expected_parent_edges = [parent_id] if parent_id else []
        if parent_edges != expected_parent_edges:
            raise EvidenceFailed(
                "v2 source graph parent scalar and parent-child dependency "
                f"differ for {issue_id}"
            )
        for relation_field, reciprocal_field in reverse_fields:
            for relation in dict.__getitem__(issue, relation_field):
                neighbor_id = dict.__getitem__(relation, "id")
                relation_type = dict.__getitem__(relation, "type")
                if str.startswith(neighbor_id, "external:"):
                    if (
                        neighbor_id == "external:"
                        or (
                            relation_field == "dependencies"
                            and relation_type == "parent-child"
                        )
                        or (
                            relation_field == "dependents"
                            and relation_type != "parent-child"
                        )
                    ):
                        raise EvidenceFailed(
                            "v2 source graph external relation has an invalid "
                            "direction, type, or empty identity"
                        )
                    continue
                if not dict.__contains__(issue_by_id, neighbor_id):
                    raise EvidenceFailed(
                        "v2 source graph relation names an absent neighbor: "
                        f"{issue_id}.{relation_field}->{neighbor_id}"
                    )
                neighbor = dict.__getitem__(issue_by_id, neighbor_id)
                if (
                    dict.__getitem__(relation, "status")
                    != dict.__getitem__(neighbor, "status")
                    or dict.__getitem__(relation, "priority")
                    != dict.__getitem__(neighbor, "priority")
                    or dict.__getitem__(relation, "title")
                    != dict.__getitem__(neighbor, "title")
                ):
                    raise EvidenceFailed(
                        "v2 source graph relation title, status, or priority "
                        "disagrees "
                        f"with neighbor {neighbor_id}"
                    )
                reciprocal_identity = (
                    relation_type,
                    issue_id,
                )
                if not has_relation(
                    dict.__getitem__(neighbor, reciprocal_field),
                    reciprocal_identity,
                ):
                    raise EvidenceFailed(
                        "v2 source graph relation lacks exact reciprocal edge: "
                        f"{issue_id}.{relation_field}->{neighbor_id}"
                    )
    blocking_adjacency: dict[str, list[str]] = {}
    parent_adjacency: dict[str, list[str]] = {}
    for issue_id in sorted(dict.__iter__(issue_by_id)):
        issue = dict.__getitem__(issue_by_id, issue_id)
        dict.__setitem__(blocking_adjacency, issue_id, sorted(
            dict.__getitem__(relation, "id")
            for relation in dict.__getitem__(issue, "dependencies")
            if (
                dict.__getitem__(relation, "type")
                in V2_BLOCKING_DEPENDENCY_TYPES
                and not str.startswith(
                    dict.__getitem__(relation, "id"),
                    "external:",
                )
            )
        ))
        parent_id = dict.__getitem__(issue, "parent")
        dict.__setitem__(
            parent_adjacency,
            issue_id,
            [parent_id] if parent_id else [],
        )
    v2_validate_source_graph_acyclic(
        blocking_adjacency,
        node_ids=sorted(dict.__iter__(issue_by_id)),
        relation_label="blocking dependency cycle",
    )
    v2_validate_source_graph_acyclic(
        parent_adjacency,
        node_ids=sorted(dict.__iter__(issue_by_id)),
        relation_label="parent hierarchy cycle",
    )

    for issue_id in sorted(dict.__iter__(issue_by_id)):
        issue = dict.__getitem__(issue_by_id, issue_id)
        rollup = dict.__getitem__(issue, "rollup")
        if rollup is None:
            continue
        visited = {issue_id: None}
        frontier = [issue_id]
        descendant_counts: dict[str, int] = {}
        while frontier:
            next_frontier: list[str] = []
            for current in frontier:
                current_issue = dict.__getitem__(issue_by_id, current)
                for relation in dict.__getitem__(current_issue, "dependents"):
                    child_id = dict.__getitem__(relation, "id")
                    if (
                        dict.__getitem__(relation, "type") != "parent-child"
                        or str.startswith(child_id, "external:")
                        or child_id in visited
                    ):
                        continue
                    dict.__setitem__(visited, child_id, None)
                    child_status = dict.__getitem__(
                        dict.__getitem__(issue_by_id, child_id),
                        "status",
                    )
                    dict.__setitem__(
                        descendant_counts,
                        child_status,
                        dict.get(descendant_counts, child_status, 0) + 1,
                    )
                    next_frontier.append(child_id)
            frontier = sorted(next_frontier)
        expected_descendants = {
            status: dict.__getitem__(descendant_counts, status)
            for status in sorted(descendant_counts)
        }
        if dict.__getitem__(rollup, "descendants") != expected_descendants:
            raise EvidenceFailed(
                "v2 source graph rollup descendant counts disagree for "
                f"{issue_id}"
            )


def v2_validate_retained_argv(value: Any, *, label: str) -> list[str]:
    if type(label) is not str or not label:
        raise InputRefused("retained argv label is malformed")
    if type(value) is not list:
        raise InputRefused(f"{label} argv is malformed")
    declared_count = list.__len__(value)
    if declared_count == 0:
        raise InputRefused(f"{label} argv is malformed")
    if declared_count > V2_COMMAND_ARGUMENTS_CAP:
        raise InputRefused(f"{label} argv exceeds its bounded contract")
    try:
        snapshot: list[Any] = list(list.__iter__(value))
    except RuntimeError as error:
        raise InputRefused(
            f"{label} argv changed while being validated"
        ) from error
    if (
        list.__len__(snapshot) != declared_count
        or list.__len__(value) != declared_count
    ):
        raise InputRefused(f"{label} argv changed while being validated")
    try:
        for index in range(declared_count):
            if list.__len__(value) != declared_count:
                raise InputRefused(
                    f"{label} argv changed while being validated"
                )
            argument = list.__getitem__(snapshot, index)
            if type(argument) is not str:
                raise InputRefused(f"{label} argv is malformed")
            if len(argument) > V2_COMMAND_ARGUMENT_BYTES_CAP:
                raise InputRefused(
                    f"{label} argv exceeds its bounded contract"
                )
            try:
                argument_bytes = str.encode(argument, "utf-8")
            except UnicodeEncodeError as error:
                raise InputRefused(
                    f"{label} argv is not valid UTF-8"
                ) from error
            if len(argument_bytes) > V2_COMMAND_ARGUMENT_BYTES_CAP:
                raise InputRefused(
                    f"{label} argv exceeds its bounded contract"
                )
    except InputRefused:
        raise
    except (IndexError, RuntimeError) as error:
        raise InputRefused(
            f"{label} argv changed while being validated"
        ) from error
    try:
        sanitized = v2_sanitized_argv(snapshot)
    except UnicodeEncodeError as error:
        raise InputRefused(f"{label} argv is not valid UTF-8") from error
    except HarnessError as error:
        raise InputRefused(
            f"{label} argv exceeds its bounded contract"
        ) from error
    try:
        source_unchanged = list.__len__(value) == declared_count
        for index in range(declared_count):
            if (
                list.__len__(value) != declared_count
                or list.__getitem__(value, index)
                is not list.__getitem__(snapshot, index)
            ):
                source_unchanged = False
                break
        if list.__len__(value) != declared_count:
            source_unchanged = False
    except (IndexError, RuntimeError) as error:
        raise InputRefused(
            f"{label} argv changed while being validated"
        ) from error
    if not source_unchanged:
        raise InputRefused(f"{label} argv changed while being validated")
    if sanitized != snapshot:
        raise InputRefused(f"{label} argv retains an unsanitized value")
    return snapshot


def v2_validate_source_stream_receipt(
    stream: Any,
    *,
    label: str,
) -> None:
    if type(label) is not str or not label:
        raise EvidenceFailed("source stream receipt label is malformed")
    if type(stream) is not dict:
        raise InputRefused(f"{label} is not an object")
    v2_exact_keys(stream, V2_SOURCE_STREAM_RECEIPT_FIELDS, label=label)
    byte_count = dict.__getitem__(stream, "bytes")
    root = dict.__getitem__(stream, "root")
    body_retained = dict.__getitem__(stream, "body_retained")
    if (
        type(byte_count) is not int
        or byte_count < 0
        or byte_count > CAPS["subprocess_stdout_bytes"]
        or type(root) is not str
        or re.fullmatch(r"sha256-v1:[0-9a-f]{64}", root) is None
        or body_retained is not False
        or (
            byte_count == 0
            and root
            != "sha256-v1:" + hashlib.sha256(b"").hexdigest()
        )
    ):
        raise InputRefused(f"{label} scalar or retention contract differs")


def v2_expected_observation_round_argv(
    issue_ids: Sequence[str],
    *,
    status_scopes: Sequence[str] = STATUS_SCOPES,
) -> list[list[str]]:
    issue_ids = v2_exact_string_sequence_snapshot(
        issue_ids,
        label="v2 expected observation issue IDs",
        cap=V2_INVENTORY_ROWS_CAP,
        error_type=EvidenceFailed,
    )
    status_scopes = v2_exact_string_sequence_snapshot(
        status_scopes,
        label="v2 expected observation status scopes",
        cap=CAPS["issues"] + len(V2_RELEASED_KNOWN_STATUSES),
        error_type=EvidenceFailed,
    )
    for index, issue_id in enumerate(issue_ids):
        v2_validate_issue_id(
            issue_id,
            label=f"v2 expected observation issue ID {index}",
            error_type=EvidenceFailed,
        )
    ordered_ids = sorted(issue_ids)
    canonical_status_scopes = v2_canonical_status_scopes(status_scopes)
    base_commands: list[list[str]] = [
        ["br", "status", "--json", "--no-activity", *BR_READ_FLAGS],
        ["br", "sync", "--status", "--json", *BR_READ_FLAGS],
        ["br", "sync", "--witness", "--json", *BR_READ_FLAGS],
        ["br", "version", "--json", *BR_READ_FLAGS],
        ["br", "capabilities", "--json", *BR_READ_FLAGS],
        ["br", "list", "--all", "--json", "--limit", "0", *BR_READ_FLAGS],
        [
            "br",
            "list",
            "--status",
            "tombstone",
            "--json",
            "--limit",
            "0",
            *BR_READ_FLAGS,
        ],
        ["br", "ready", "--json", "--limit", "0", *BR_READ_FLAGS],
    ]
    batch_size = min(CAPS["show_batch"], 56)
    show_commands = [
        [
            "br",
            "show",
            *ordered_ids[offset : offset + batch_size],
            "--json",
            *BR_READ_FLAGS,
        ]
        for offset in range(0, len(ordered_ids), batch_size)
    ]
    lint_commands = [
        [
            "br",
            "lint",
            "--status",
            scope,
            "--json",
            *BR_READ_FLAGS,
        ]
        for scope in (*canonical_status_scopes, "all")
    ]
    return [*base_commands, *show_commands, *lint_commands]


def v2_expected_observation_argv(
    issue_ids: Sequence[str],
    *,
    status_scopes: Sequence[str] = STATUS_SCOPES,
) -> list[list[str]]:
    commands = v2_expected_observation_round_argv(
        issue_ids,
        status_scopes=status_scopes,
    )
    return [*commands, *commands]


def v2_observation_command_projection_entries(
    *,
    tracker_status: Mapping[str, Any],
    tracker_ready_issue_ids: Sequence[str],
    sync_status: Mapping[str, Any],
    export_witness: Mapping[str, Any],
    version: Mapping[str, Any],
    capabilities: Mapping[str, Any],
    issue_ids: Sequence[str],
    listed_rows: Sequence[Mapping[str, Any]],
    tombstone_rows: Sequence[Mapping[str, Any]],
    tracker_ready_rows: Sequence[Mapping[str, Any]],
    full_issues: Sequence[Mapping[str, Any]],
    lint: Mapping[str, Any],
) -> list[dict[str, str]]:
    ordered_ids = sorted(str(issue_id) for issue_id in issue_ids)
    if ordered_ids != list(issue_ids):
        raise EvidenceFailed(
            "v2 command projection issue IDs are noncanonical"
        )
    issue_by_id = {
        str(issue["id"]): dict(issue)
        for issue in full_issues
    }
    if sorted(issue_by_id) != ordered_ids:
        raise EvidenceFailed(
            "v2 command projection show membership differs from list"
        )
    ready_ids = [str(issue_id) for issue_id in tracker_ready_issue_ids]
    normalized_listed_rows = v2_normalize_retained_br_rows(
        [dict(row) for row in listed_rows],
        label="v2 command projection listed",
        relation_counts=True,
        error_type=EvidenceFailed,
    )
    normalized_tombstone_rows = v2_normalize_retained_br_rows(
        [dict(row) for row in tombstone_rows],
        label="v2 command projection tombstone",
        relation_counts=True,
        error_type=EvidenceFailed,
    )
    normalized_ready_rows = v2_normalize_retained_br_rows(
        [dict(row) for row in tracker_ready_rows],
        label="v2 command projection ready",
        relation_counts=False,
        error_type=EvidenceFailed,
    )
    ordinary_ids = {
        issue_id
        for issue_id in ordered_ids
        if issue_by_id[issue_id]["status"] != "tombstone"
    }
    if (
        ready_ids != sorted(ready_ids)
        or len(ready_ids) != len(set(ready_ids))
        or not set(ready_ids).issubset(ordinary_ids)
    ):
        raise EvidenceFailed(
            "v2 command projection ready membership is noncanonical or "
            "outside the ordinary issue universe"
        )
    if (
        [str(row.get("id") or "") for row in normalized_listed_rows]
        != sorted(ordinary_ids)
        or [
            str(row.get("id") or "")
            for row in normalized_tombstone_rows
        ]
        != sorted(set(ordered_ids) - ordinary_ids)
        or [str(row.get("id") or "") for row in normalized_ready_rows]
        != ready_ids
    ):
        raise EvidenceFailed(
            "v2 command projection list or ready rows differ from membership"
        )
    v2_validate_capture_row_coherence(
        [*normalized_listed_rows, *normalized_tombstone_rows],
        full_issues,
        label="v2 command projection list rows",
        relation_counts=True,
    )
    v2_validate_capture_row_coherence(
        normalized_ready_rows,
        full_issues,
        label="v2 command projection ready rows",
        relation_counts=False,
    )

    def projection(
        kind: str,
        *,
        selector: Mapping[str, Any],
        document: Any,
    ) -> dict[str, str]:
        return {
            "projection_kind": kind,
            "normalized_projection_root": semantic_root(
                {
                    "schema": "frankensim.br-command-projection.v1",
                    "projection_kind": kind,
                    "selector": dict(selector),
                    "document": document,
                }
            ),
        }

    entries = [
        projection(
            "tracker_status",
            selector={},
            document=dict(tracker_status),
        ),
        projection(
            "sync_status",
            selector={},
            document=dict(sync_status),
        ),
        projection(
            "export_witness",
            selector={},
            document=dict(export_witness),
        ),
        projection(
            "br_version",
            selector={},
            document=dict(version),
        ),
        projection(
            "br_capabilities",
            selector={},
            document=dict(capabilities),
        ),
        projection(
            "tracker_list_rows",
            selector={"all": True, "tombstones": False},
            document=normalized_listed_rows,
        ),
        projection(
            "tracker_tombstone_rows",
            selector={"status": "tombstone"},
            document=normalized_tombstone_rows,
        ),
        projection(
            "tracker_ready_rows",
            selector={},
            document=normalized_ready_rows,
        ),
    ]
    batch_size = min(CAPS["show_batch"], 56)
    for offset in range(0, len(ordered_ids), batch_size):
        batch_ids = ordered_ids[offset : offset + batch_size]
        entries.append(
            projection(
                "show_batch",
                selector={"issue_ids": batch_ids},
                document=[issue_by_id[issue_id] for issue_id in batch_ids],
            )
        )
    lint_status_scopes = v2_canonical_status_scopes(
        [scope for scope in lint if scope != "all"]
    )
    for scope in (*lint_status_scopes, "all"):
        if scope not in lint:
            raise EvidenceFailed(
                f"v2 command projection lacks lint scope {scope}"
            )
        entries.append(
            projection(
                "lint_scope",
                selector={"status": scope},
                document=dict(lint[scope]),
            )
        )
    return entries


def v2_validate_source_command_receipts(
    observation: Mapping[str, Any],
    *,
    issue_ids: Sequence[str],
    full_issues: Sequence[Mapping[str, Any]],
    lint: Mapping[str, Any],
) -> list[Mapping[str, Any]]:
    if type(issue_ids) is list:
        if list.__len__(issue_ids) > V2_INVENTORY_ROWS_CAP:
            raise InputRefused(
                "v2 source observation issue IDs exceed their cap"
            )
        raw_issue_ids = issue_ids
    elif type(issue_ids) is tuple:
        if tuple.__len__(issue_ids) > V2_INVENTORY_ROWS_CAP:
            raise InputRefused(
                "v2 source observation issue IDs exceed their cap"
            )
        raw_issue_ids = [value for value in tuple.__iter__(issue_ids)]
    else:
        raise InputRefused(
            "v2 source observation issue IDs are not an exact sequence"
        )
    if type(full_issues) is list:
        if list.__len__(full_issues) > V2_INVENTORY_ROWS_CAP:
            raise InputRefused(
                "v2 source observation issues exceed their cap"
            )
        raw_full_issues = full_issues
    elif type(full_issues) is tuple:
        if tuple.__len__(full_issues) > V2_INVENTORY_ROWS_CAP:
            raise InputRefused(
                "v2 source observation issues exceed their cap"
            )
        raw_full_issues = [value for value in tuple.__iter__(full_issues)]
    else:
        raise InputRefused(
            "v2 source observation issues are not an exact sequence"
        )
    detached = v2_released_json_snapshot(
        {
            "observation": observation,
            "issue_ids": raw_issue_ids,
            "full_issues": raw_full_issues,
            "lint": lint,
        },
        label="v2 source observation command-receipt inputs",
        error_type=InputRefused,
    )
    if type(detached) is not dict:
        raise InputRefused(
            "v2 source observation command-receipt snapshot is malformed"
        )
    observation = dict.__getitem__(detached, "observation")
    issue_ids = dict.__getitem__(detached, "issue_ids")
    full_issues = dict.__getitem__(detached, "full_issues")
    lint = dict.__getitem__(detached, "lint")
    if (
        type(observation) is not dict
        or type(issue_ids) is not list
        or type(full_issues) is not list
        or type(lint) is not dict
    ):
        raise InputRefused(
            "v2 source observation command-receipt inputs are not exact"
        )
    receipts = dict.get(observation, "command_receipts")
    if type(receipts) is not list:
        raise InputRefused(
            "v2 source observation command receipts are not an array"
        )
    if len(receipts) > V2_LOG_EVENTS_CAP - 8:
        raise InputRefused(
            "v2 source observation command receipts exceed the event budget"
        )
    round_projections = v2_observation_command_projection_entries(
        tracker_status=observation["tracker_status"],
        tracker_ready_issue_ids=observation[
            "tracker_ready_issue_ids"
        ],
        sync_status=observation["sync_status"],
        export_witness=observation["export_witness"],
        version=observation["br_version"],
        capabilities=observation["br_capabilities"],
        issue_ids=issue_ids,
        listed_rows=observation["tracker_list_rows"],
        tombstone_rows=observation["tracker_tombstone_rows"],
        tracker_ready_rows=observation["tracker_ready_rows"],
        full_issues=full_issues,
        lint=lint,
    )
    expected_projections = [*round_projections, *round_projections]
    if len(receipts) != len(expected_projections):
        raise InputRefused(
            "v2 source observation command receipt count differs from "
            "normalized projections"
        )
    for index, (receipt, expected_projection) in enumerate(
        zip(receipts, expected_projections, strict=True)
    ):
        label = f"v2 source observation command receipt {index}"
        if not isinstance(receipt, dict):
            raise InputRefused(f"{label} is not an object")
        v2_exact_keys(
            receipt,
            V2_SOURCE_COMMAND_RECEIPT_FIELDS,
            label=label,
        )
        v2_validate_retained_argv(receipt["argv"], label=label)
        cleanup_kinds = receipt["cleanup_error_kinds"]
        if (
            type(receipt["capture_sequence"]) is not int
            or receipt["capture_sequence"] != index
            or receipt["capture_ordinal"]
            != (1 if index < len(round_projections) else 2)
            or type(receipt["capture_ordinal"]) is not int
            or receipt["projection_kind"]
            != expected_projection["projection_kind"]
            or receipt["normalized_projection_root"]
            != expected_projection["normalized_projection_root"]
            or not isinstance(
                receipt["normalized_projection_root"], str
            )
            or re.fullmatch(
                r"sha256-v1:[0-9a-f]{64}",
                receipt["normalized_projection_root"],
            )
            is None
            or type(receipt["exit_code"]) is not int
            or receipt["exit_code"] != 0
            or receipt["category"] != "SUCCESS"
            or type(receipt["cleanup_error_count"]) is not int
            or receipt["cleanup_error_count"] != 0
            or not isinstance(cleanup_kinds, list)
            or cleanup_kinds
            or receipt["redaction_verdict"]
            != "RAW_STREAM_BODIES_NOT_RETAINED"
        ):
            raise InputRefused(
                f"{label} sequence, projection, terminal, or cleanup "
                "contract differs"
            )
        v2_validate_source_stream_receipt(
            receipt["stdout"],
            label=f"{label} stdout",
        )
        v2_validate_source_stream_receipt(
            receipt["stderr"],
            label=f"{label} stderr",
        )
    expected_argv = v2_expected_observation_argv(
        issue_ids,
        status_scopes=v2_canonical_status_scopes(
            [scope for scope in lint if scope != "all"]
        ),
    )
    if [receipt["argv"] for receipt in receipts] != expected_argv:
        raise InputRefused(
            "v2 source observation command membership, order, or read-only "
            "grammar differs"
        )
    return receipts


def v2_validate_audit_capture(
    audit_capture: Mapping[str, Any],
    *,
    allowed_issue_ids: set[str],
) -> tuple[dict[str, Any], list[Mapping[str, Any]]]:
    if type(allowed_issue_ids) is not set:
        raise InputRefused("v2 source audit allowed IDs are not an exact set")
    declared_allowed_count = set.__len__(allowed_issue_ids)
    if declared_allowed_count > V2_INVENTORY_ROWS_CAP:
        raise InputRefused("v2 source audit allowed IDs exceed their cap")
    try:
        raw_allowed_ids = list(set.__iter__(allowed_issue_ids))
    except RuntimeError as error:
        raise InputRefused(
            "v2 source audit allowed IDs changed while being captured"
        ) from error
    if any(type(value) is not str for value in raw_allowed_ids):
        raise InputRefused(
            "v2 source audit allowed IDs contain a non-exact string"
        )
    ordered_allowed_ids = sorted(
        raw_allowed_ids,
        key=lambda value: str.encode(value, "utf-8"),
    )
    exact_allowed_ids = [
        v2_validate_issue_id(
            allowed_issue_id,
            label=f"v2 source audit allowed issue ID {index}",
            error_type=InputRefused,
        )
        for index, allowed_issue_id in enumerate(ordered_allowed_ids)
    ]
    try:
        final_raw_allowed_ids = list(set.__iter__(allowed_issue_ids))
    except RuntimeError as error:
        raise InputRefused(
            "v2 source audit allowed IDs changed while being captured"
        ) from error
    if (
        len(exact_allowed_ids) != declared_allowed_count
        or any(type(value) is not str for value in final_raw_allowed_ids)
        or sorted(
            final_raw_allowed_ids,
            key=lambda value: str.encode(value, "utf-8"),
        )
        != ordered_allowed_ids
    ):
        raise InputRefused(
            "v2 source audit allowed IDs changed while being captured"
        )
    allowed_issue_ids = set(exact_allowed_ids)
    audit_capture = v2_released_json_snapshot(
        audit_capture,
        label="v2 source audit capture input",
        error_type=InputRefused,
    )
    if type(audit_capture) is not dict:
        raise InputRefused("v2 source audit capture is not an exact object")
    if "state" in audit_capture:
        v2_exact_keys(
            audit_capture,
            V2_AUDIT_CAPTURE_NOT_REQUESTED_FIELDS,
            label="v2 source audit capture not-requested envelope",
        )
        v2_validate_canonical_byte_size(
            audit_capture,
            cap=V2_AUDIT_CAPTURE_BYTES_CAP,
            label="v2 source audit capture",
            error_type=InputRefused,
        )
        expected = v2_rooted(
            {
                "state": "NOT_REQUESTED",
                "capture_count": 0,
                "issue_ids": [],
                "documents": [],
                "command_receipts": [],
                "raw_stream_bodies_retained": False,
                "no_claim": V2_AUDIT_NOT_REQUESTED_NO_CLAIM,
            }
        )
        if audit_capture != expected:
            divergence = first_projection_divergence(expected, audit_capture)
            raise InputRefused(
                "v2 source audit not-requested envelope differs at "
                f"{divergence or '$'}"
            )
        return audit_capture, []

    v2_exact_keys(
        audit_capture,
        V2_AUDIT_CAPTURE_FIELDS,
        label="v2 source audit capture envelope",
    )
    issue_ids = audit_capture["issue_ids"]
    documents = audit_capture["documents"]
    receipts = audit_capture["command_receipts"]
    if (
        audit_capture["capture_count"] != 2
        or audit_capture["worker_bound"] != V2_AUDIT_WORKERS
        or not isinstance(issue_ids, list)
        or not isinstance(documents, list)
        or not isinstance(receipts, list)
        or len(issue_ids) > V2_INVENTORY_ROWS_CAP
        or len(documents) != len(issue_ids)
        or len(receipts) != 2 * len(issue_ids)
        or audit_capture["raw_stream_bodies_retained"] is not False
        or audit_capture["no_claim"] != V2_AUDIT_CAPTURE_NO_CLAIM
    ):
        raise InputRefused(
            "v2 source audit capture cardinality or scalar contract differs"
        )
    v2_validate_canonical_byte_size(
        audit_capture,
        cap=V2_AUDIT_CAPTURE_BYTES_CAP,
        label="v2 source audit capture",
        error_type=InputRefused,
    )
    if (
        any(
            not isinstance(issue_id, str) or not issue_id
            for issue_id in issue_ids
        )
        or issue_ids != sorted(set(issue_ids))
        or bool(set(issue_ids) - allowed_issue_ids)
    ):
        raise InputRefused(
            "v2 source audit capture membership contract differs"
        )
    for index, issue_id in enumerate(issue_ids):
        v2_validate_issue_id(
            issue_id,
            label=f"v2 source audit issue ID {index}",
            error_type=InputRefused,
        )
    document_ids = [
        dict.get(document, "issue_id")
        for document in documents
        if isinstance(document, dict)
    ]
    if len(document_ids) != len(documents) or document_ids != issue_ids:
        raise InputRefused(
            "v2 source audit document membership differs from issue IDs"
        )
    documents_by_id: dict[str, Mapping[str, Any]] = {}
    for index, document in enumerate(documents):
        try:
            expected_document = v2_normalize_audit_document(
                {
                    "issue_id": document["issue_id"],
                    "events": dict.get(document, "events"),
                },
                issue_id=document["issue_id"],
            )
        except (InfrastructureFailed, EvidenceFailed, KeyError) as error:
            raise InputRefused(
                f"v2 source audit document {index} is malformed or over cap"
            ) from error
        if document != expected_document:
            divergence = first_projection_divergence(
                expected_document,
                document,
            )
            raise InputRefused(
                "v2 source audit document differs from its normalized "
                f"projection at {divergence or '$'}"
            )
        documents_by_id[document["issue_id"]] = document
    expected_order = [
        (capture_ordinal, issue_id)
        for capture_ordinal in (1, 2)
        for issue_id in issue_ids
    ]
    observed_order: list[tuple[int, str]] = []
    for index, receipt in enumerate(receipts):
        label = f"v2 source audit command receipt {index}"
        if not isinstance(receipt, dict):
            raise InputRefused(f"{label} is not an object")
        v2_exact_keys(
            receipt,
            V2_AUDIT_COMMAND_RECEIPT_FIELDS,
            label=label,
        )
        issue_id = receipt["issue_id"]
        ordinal = receipt["capture_ordinal"]
        if (
            type(ordinal) is not int
            or ordinal not in {1, 2}
            or not isinstance(issue_id, str)
            or (ordinal, issue_id) != expected_order[index]
            or receipt["argv"]
            != [
                "br",
                "audit",
                "log",
                issue_id,
                "--json",
                *BR_READ_FLAGS,
            ]
            or receipt["exit_code"] != 0
            or type(receipt["exit_code"]) is not int
            or receipt["result_category"] != "SUCCESS"
            or type(receipt["stdout_byte_length"]) is not int
            or not 0
            < receipt["stdout_byte_length"]
            <= V2_AUDIT_STREAM_BYTES_CAP
            or type(receipt["stderr_byte_length"]) is not int
            or not 0
            <= receipt["stderr_byte_length"]
            <= V2_AUDIT_STREAM_BYTES_CAP
            or (
                receipt["stderr_byte_length"] == 0
                and receipt["stderr_root"]
                != "sha256-v1:" + hashlib.sha256(b"").hexdigest()
            )
            or any(
                not isinstance(receipt[field], str)
                or re.fullmatch(
                    r"sha256-v1:[0-9a-f]{64}",
                    receipt[field],
                )
                is None
                for field in (
                    "stdout_root",
                    "normalized_document_root",
                    "stderr_root",
                )
            )
            or receipt["normalized_document_root"]
            != documents_by_id[issue_id]["semantic_root"]
            or receipt["raw_stream_bodies_retained"] is not False
        ):
            raise InputRefused(f"{label} identity or terminal contract differs")
        v2_validate_retained_argv(receipt["argv"], label=label)
        observed_order.append((ordinal, issue_id))
    if observed_order != expected_order:
        raise InputRefused(
            "v2 source audit command receipt order is noncanonical"
        )
    receipts_by_coordinate = {
        (receipt["capture_ordinal"], receipt["issue_id"]): receipt
        for receipt in receipts
    }
    for issue_id in issue_ids:
        if v2_audit_receipt_coherence_projection(
            receipts_by_coordinate[(1, issue_id)]
        ) != v2_audit_receipt_coherence_projection(
            receipts_by_coordinate[(2, issue_id)]
        ):
            raise InputRefused(
                "v2 source audit command receipts differ across captures for "
                f"{issue_id}"
            )
    verify_semantic_root(
        audit_capture,
        label="v2 source audit capture envelope",
    )
    return audit_capture, receipts


def v2_validate_source_review_receipt_envelope(
    receipt_document: Mapping[str, Any],
) -> None:
    receipt_document = v2_released_json_snapshot(
        receipt_document,
        label="v2 source review receipt envelope",
        error_type=InputRefused,
    )
    if type(receipt_document) is not dict:
        raise InputRefused("v2 source review receipts are not an object")
    allowed_fields = {
        "schema",
        "inventory_root",
        "campaign_epoch_root",
        "receipts",
        "source",
        "source_identity",
        "no_claim",
        "semantic_root",
    }
    required_fields = allowed_fields - {"source_identity"}
    observed_fields = frozenset(dict.__iter__(receipt_document))
    if observed_fields != required_fields and observed_fields != allowed_fields:
        raise InputRefused(
            "v2 source review receipt envelope has a non-closed schema"
        )
    receipts = dict.__getitem__(receipt_document, "receipts")
    schema = dict.__getitem__(receipt_document, "schema")
    inventory_root = dict.__getitem__(receipt_document, "inventory_root")
    campaign_epoch_root = dict.__getitem__(
        receipt_document,
        "campaign_epoch_root",
    )
    source = dict.__getitem__(receipt_document, "source")
    no_claim = dict.__getitem__(receipt_document, "no_claim")
    if (
        type(schema) is not str
        or schema != V2_REVIEW_RECEIPTS_SCHEMA
        or not v2_is_semantic_root(inventory_root)
        or not v2_is_semantic_root(campaign_epoch_root)
        or type(source) is not str
        or not str.strip(source)
        or type(receipts) is not list
        or list.__len__(receipts) > V2_INVENTORY_ROWS_CAP
        or type(no_claim) is not str
        or no_claim != V2_REVIEW_RECEIPTS_NO_CLAIM
    ):
        raise InputRefused(
            "v2 source review receipt envelope identity or no-claim differs"
        )
    _v2_validate_review_receipt_document_provenance_exact(
        receipt_document,
        inventory=None,
        label="v2 source review receipts",
    )
    verify_semantic_root(
        receipt_document,
        label="v2 source review receipt envelope",
    )
    v2_validate_review_receipt_source_identity(
        receipt_document,
        label="v2 source review receipts",
    )
    target_ids: list[str] = []
    for index, receipt in enumerate(list.__iter__(receipts)):
        if type(receipt) is not dict:
            raise InputRefused(
                f"v2 source review receipt row {index} is not an object"
            )
        v2_exact_keys(
            receipt,
            {*V2_REVIEW_RECEIPT_FIELDS, "semantic_root"},
            label=f"v2 source review receipt row {index}",
        )
        _v2_validate_review_receipt_row_provenance_exact(
            receipt,
            receipt_document,
            label=f"v2 source review receipt row {index}",
        )
        verify_semantic_root(
            receipt,
            label=f"v2 source review receipt row {index}",
        )
        target_id = dict.__getitem__(receipt, "target_id")
        if (
            type(target_id) is not str
            or not target_id
            or type(dict.__getitem__(receipt, "no_claim")) is not str
            or dict.__getitem__(receipt, "no_claim")
            != V2_REVIEW_RECEIPT_ROW_NO_CLAIM
        ):
            raise InputRefused(
                f"v2 source review receipt row {index} identity or no-claim differs"
            )
        v2_validate_issue_id(
            target_id,
            label=f"v2 source review receipt row {index} target ID",
            error_type=InputRefused,
        )
        target_ids.append(target_id)
    if target_ids != sorted(target_ids) or len(target_ids) != len(
        set(target_ids)
    ):
        raise InputRefused(
            "v2 source review receipt membership is noncanonical"
        )


def v2_validate_source_prior_campaign_envelope(
    prior_campaign: Mapping[str, Any],
) -> None:
    if not isinstance(prior_campaign, dict):
        raise InputRefused("v2 source prior campaign is not an object")
    state = prior_campaign.get("state")
    if state == "NOT_PROVIDED":
        v2_exact_keys(
            prior_campaign,
            {
                "state",
                "bundle_path",
                "terminal_root",
                "inventory_root",
                "rows",
                "no_claim",
                "semantic_root",
            },
            label="v2 source prior campaign",
        )
        if (
            prior_campaign["bundle_path"] is not None
            or prior_campaign["terminal_root"] is not None
            or prior_campaign["inventory_root"] is not None
            or prior_campaign["rows"] != []
            or prior_campaign["no_claim"]
            != V2_PRIOR_CAMPAIGN_NOT_PROVIDED_NO_CLAIM
        ):
            raise InputRefused(
                "v2 source absent prior campaign carries evidence or authority"
            )
        verify_semantic_root(
            prior_campaign,
            label="v2 source prior campaign",
        )
        return
    if state != "PROVIDED":
        raise InputRefused("v2 source prior campaign has an unknown state")
    v2_exact_keys(
        prior_campaign,
        {
            "state",
            "bundle_path",
            "terminal_root",
            "inventory_root",
            "campaign_epoch_root",
            "rows",
            "no_claim",
            "semantic_root",
        },
        label="v2 source prior campaign",
    )
    try:
        normalized_path = str(
            safe_relative(
                prior_campaign["bundle_path"],
                label="v2 source prior campaign bundle path",
            )
        )
    except (KeyError, TypeError, UsageRefused) as error:
        raise InputRefused(
            "v2 source prior campaign bundle path is malformed"
        ) from error
    if (
        normalized_path != prior_campaign["bundle_path"]
        or any(
            not isinstance(prior_campaign[field], str)
            or re.fullmatch(
                r"sha256-v1:[0-9a-f]{64}",
                prior_campaign[field],
            )
            is None
            for field in (
                "terminal_root",
                "inventory_root",
                "campaign_epoch_root",
            )
        )
        or not isinstance(prior_campaign["rows"], list)
        or len(prior_campaign["rows"]) > V2_INVENTORY_ROWS_CAP
        or prior_campaign["no_claim"]
        != V2_PRIOR_CAMPAIGN_PROVIDED_NO_CLAIM
    ):
        raise InputRefused(
            "v2 source prior campaign identity or no-claim differs"
        )
    verify_semantic_root(
        prior_campaign,
        label="v2 source prior campaign",
    )


def v2_preflight_source_v1_inventory_nested_lists(
    inventory: Mapping[str, Any],
) -> None:
    if type(inventory) is not dict:
        raise InputRefused(
            "v2 source v1 inventory projection is not an exact object"
        )
    rows = inventory["rows"] if "rows" in inventory else None
    warning_rows = (
        inventory["warning_rows"]
        if "warning_rows" in inventory
        else None
    )
    if type(rows) is not list:
        raise InputRefused("v2 source v1 inventory rows are not an array")
    if type(warning_rows) is not list:
        raise InputRefused(
            "v2 source v1 inventory warning rows are not an array"
        )
    if len(rows) > V2_INVENTORY_ROWS_CAP:
        raise InputRefused(
            "v2 source v1 inventory rows exceed the inventory row cap"
        )
    if len(warning_rows) > V2_WARNING_ROWS_CAP:
        raise InputRefused(
            "v2 source v1 inventory warning rows exceed the warning row cap"
        )
    warning_count = 0
    maximum_warnings_per_issue = 0
    for index, row in enumerate(rows):
        if type(row) is not dict:
            raise InputRefused(
                f"v2 source v1 inventory row {index} is not an object"
            )
        missing_sections = (
            row["missing_sections"]
            if "missing_sections" in row
            else None
        )
        if type(missing_sections) is not list:
            raise InputRefused(
                "v2 source v1 inventory row "
                f"{index} missing sections are not an array"
            )
        row_warning_count = len(missing_sections)
        maximum_warnings_per_issue = max(
            maximum_warnings_per_issue,
            row_warning_count,
        )
        warning_count += row_warning_count
        if warning_count > V2_WARNING_ROWS_CAP:
            raise InputRefused(
                "v2 source v1 inventory row warnings exceed the warning row cap"
            )
    v2_validate_source_limits(
        row_count=len(rows),
        warning_count=max(warning_count, len(warning_rows)),
        maximum_warnings_per_issue=maximum_warnings_per_issue,
    )


def v2_preflight_source_v1_lint_nested_lists(
    lint: Mapping[str, Any],
) -> None:
    if type(lint) is not dict:
        raise InputRefused("v2 source v1 lint projection is not an exact object")
    for scope in LINT_SCOPES:
        projection = lint[scope] if scope in lint else None
        if type(projection) is not dict:
            raise InputRefused(
                f"v2 source v1 lint scope {scope} is not an object"
            )
        results = projection["results"] if "results" in projection else None
        declared_issues = (
            projection["issues"] if "issues" in projection else None
        )
        declared_warnings = (
            projection["total"] if "total" in projection else None
        )
        if type(results) is not list:
            raise InputRefused(
                f"v2 source v1 lint scope {scope} results are not an array"
            )
        if (
            type(declared_issues) is not int
            or declared_issues < 0
            or type(declared_warnings) is not int
            or declared_warnings < 0
        ):
            raise InputRefused(
                f"v2 source v1 lint scope {scope} counts are malformed"
            )
        warning_count = 0
        maximum_warnings_per_issue = 0
        for index, row in enumerate(results):
            if type(row) is not dict:
                raise InputRefused(
                    "v2 source v1 lint scope "
                    f"{scope} row {index} is not an object"
                )
            missing_sections = row["missing"] if "missing" in row else None
            suggestions = (
                row["suggestions"] if "suggestions" in row else None
            )
            if type(missing_sections) is not list:
                raise InputRefused(
                    "v2 source v1 lint scope "
                    f"{scope} row {index} missing sections are not an array"
                )
            if suggestions is not None and type(suggestions) is not list:
                raise InputRefused(
                    "v2 source v1 lint scope "
                    f"{scope} row {index} suggestions are not an array"
                )
            if (
                type(suggestions) is list
                and len(suggestions) > V2_WARNINGS_PER_ISSUE_CAP
            ):
                raise InputRefused(
                    "v2 source v1 lint scope "
                    f"{scope} row {index} suggestions exceed the per-issue cap"
                )
            row_warning_count = len(missing_sections)
            maximum_warnings_per_issue = max(
                maximum_warnings_per_issue,
                row_warning_count,
            )
            warning_count += row_warning_count
            if warning_count > V2_WARNING_ROWS_CAP:
                raise InputRefused(
                    f"v2 source v1 lint scope {scope} warnings exceed the cap"
                )
        v2_validate_source_limits(
            row_count=max(len(results), declared_issues),
            warning_count=max(warning_count, declared_warnings),
            maximum_warnings_per_issue=maximum_warnings_per_issue,
        )
    v2_validate_lint_scope_coherence(
        lint,
        full_issues=None,
        error_type=InputRefused,
    )


def v2_preflight_source_observation_nested_lists(
    observation: Mapping[str, Any],
) -> None:
    if type(observation) is not dict:
        raise InputRefused("v2 source observation is not an exact object")
    source_files = (
        observation["source_files"]
        if "source_files" in observation
        else None
    )
    status_cut = (
        observation["status_cut"]
        if "status_cut" in observation
        else None
    )
    tracker_ready_issue_ids = (
        observation["tracker_ready_issue_ids"]
        if "tracker_ready_issue_ids" in observation
        else None
    )
    tracker_row_arrays = {
        field: observation[field] if field in observation else None
        for field in (
            "tracker_list_rows",
            "tracker_tombstone_rows",
            "tracker_ready_rows",
        )
    }
    command_receipts = (
        observation["command_receipts"]
        if "command_receipts" in observation
        else None
    )
    br_version = (
        observation["br_version"]
        if "br_version" in observation
        else None
    )
    features = (
        br_version["features"]
        if type(br_version) is dict and "features" in br_version
        else None
    )
    if type(source_files) is not list:
        raise InputRefused(
            "v2 source observation source files are not an array"
        )
    if len(source_files) > V2_BUNDLE_FILES_CAP:
        raise InputRefused(
            "v2 source observation source files exceed the bundle file cap"
        )
    if type(status_cut) is not list:
        raise InputRefused(
            "v2 source observation status cut is not an array"
        )
    if len(status_cut) > V2_INVENTORY_ROWS_CAP:
        raise InputRefused(
            "v2 source observation status cut exceeds the inventory row cap"
        )
    if type(tracker_ready_issue_ids) is not list:
        raise InputRefused(
            "v2 source observation ready membership is not an array"
        )
    if len(tracker_ready_issue_ids) > V2_INVENTORY_ROWS_CAP:
        raise InputRefused(
            "v2 source observation ready membership exceeds the issue-row cap"
        )
    for field, rows in tracker_row_arrays.items():
        if type(rows) is not list:
            raise InputRefused(
                f"v2 source observation {field} is not an array"
            )
        if len(rows) > V2_INVENTORY_ROWS_CAP:
            raise InputRefused(
                f"v2 source observation {field} exceeds the issue-row cap"
            )
    if type(command_receipts) is not list:
        raise InputRefused(
            "v2 source observation command receipts are not an array"
        )
    if len(command_receipts) > V2_LOG_EVENTS_CAP - 8:
        raise InputRefused(
            "v2 source observation command receipts exceed the event budget"
        )
    if type(features) is not list:
        raise InputRefused(
            "v2 source observation br features are not an array"
        )
    if len(features) > V2_LOG_EVENTS_CAP:
        raise InputRefused(
            "v2 source observation br features exceed the event budget"
        )
    for index, receipt in enumerate(command_receipts):
        if type(receipt) is not dict:
            raise InputRefused(
                f"v2 source observation command receipt {index} is not an object"
            )
        for field in ("argv", "cleanup_error_kinds"):
            values = receipt[field] if field in receipt else None
            if type(values) is not list:
                raise InputRefused(
                    "v2 source observation command receipt "
                    f"{index} {field} is not an array"
                )
            if len(values) > V2_LOG_EVENTS_CAP:
                raise InputRefused(
                    "v2 source observation command receipt "
                    f"{index} {field} exceeds the event budget"
                )


def v2_exact_wire_list_item(
    value: list[Any],
    *,
    index: int,
    expected_length: int,
    label: str,
    path: str,
) -> tuple[bool, Any]:
    if list.__len__(value) != expected_length:
        raise InputRefused(f"{label} changed while validating {path}")
    if index >= expected_length:
        return False, None
    try:
        return True, list.__getitem__(value, index)
    except IndexError as error:
        raise InputRefused(
            f"{label} changed while validating {path}"
        ) from error


def v2_exact_wire_dict_item(
    value: dict[str, Any],
    *,
    iterator: Iterator[Any],
    expected_length: int,
    label: str,
    path: str,
) -> tuple[bool, Any, Any]:
    if dict.__len__(value) != expected_length:
        raise InputRefused(f"{label} changed while validating {path}")
    try:
        key = next(iterator)
    except StopIteration:
        if dict.__len__(value) != expected_length:
            raise InputRefused(f"{label} changed while validating {path}")
        return False, None, None
    except RuntimeError as error:
        raise InputRefused(
            f"{label} changed while validating {path}"
        ) from error
    # An exact dict can still contain a hostile non-string key. Gate it before
    # lookup: even dict.__getitem__ hashes its argument and would otherwise
    # execute user code while this boundary is trying to refuse the input.
    if type(key) is not str:
        raise InputRefused(
            f"{label} contains a non-exact object key at {path}"
        )
    try:
        item = dict.__getitem__(value, key)
    except KeyError as error:
        raise InputRefused(
            f"{label} changed while validating {path}"
        ) from error
    return True, key, item


def v2_exact_wire_container_unchanged(
    value: Any,
    snapshot: Any,
    *,
    label: str,
    path: str,
) -> None:
    def same_member(left: Any, right: Any) -> bool:
        if type(left) is not type(right):
            return False
        if left is None or type(left) is bool:
            return left is right
        if type(left) in {int, str}:
            return left == right
        if type(left) is float:
            return float.hex(left) == float.hex(right)
        if type(left) in {list, dict}:
            return left is right
        return False

    unchanged = True
    if type(value) is list and type(snapshot) is list:
        live_length = list.__len__(value)
        snapshot_length = list.__len__(snapshot)
        unchanged = live_length == snapshot_length
        if unchanged:
            for index in range(snapshot_length):
                present, live_item = v2_exact_wire_list_item(
                    value,
                    index=index,
                    expected_length=snapshot_length,
                    label=label,
                    path=path,
                )
                if not present:
                    unchanged = False
                    break
                if not same_member(
                    live_item,
                    list.__getitem__(snapshot, index),
                ):
                    unchanged = False
                    break
    elif type(value) is dict and type(snapshot) is dict:
        unchanged = dict.__len__(value) == dict.__len__(snapshot)
        if unchanged:
            for key, snapshot_item in dict.items(snapshot):
                if not dict.__contains__(value, key):
                    unchanged = False
                    break
                try:
                    live_item = dict.__getitem__(value, key)
                except (KeyError, RuntimeError) as error:
                    raise InputRefused(
                        f"{label} changed while validating {path}"
                    ) from error
                if not same_member(live_item, snapshot_item):
                    unchanged = False
                    break
    else:
        raise EvidenceFailed(
            f"{label} exact-wire snapshot type differs at {path}"
        )
    if not unchanged:
        raise InputRefused(f"{label} changed while validating {path}")


def v2_exact_json_string_wire_lengths(
    value: str,
    *,
    wire_cap: int,
    label: str,
    path: str,
) -> tuple[int, int]:
    """Return exact UTF-8 scalar and canonical JSON string byte lengths."""
    if type(value) is not str or type(wire_cap) is not int or wire_cap < 0:
        raise EvidenceFailed(f"{label} exact-wire string accounting is invalid")
    utf8_bytes = 0
    wire_bytes = 2  # Opening and closing quotes.
    for character in value:
        codepoint = ord(character)
        if 0xD800 <= codepoint <= 0xDFFF:
            raise InputRefused(f"{label} contains invalid Unicode at {path}")
        if codepoint <= 0x7F:
            utf8_bytes += 1
        elif codepoint <= 0x7FF:
            utf8_bytes += 2
        elif codepoint <= 0xFFFF:
            utf8_bytes += 3
        else:
            utf8_bytes += 4
        if character in {'"', "\\"}:
            wire_bytes += 2
        elif codepoint <= 0x1F:
            wire_bytes += 2 if character in "\b\t\n\f\r" else 6
        else:
            wire_bytes += (
                1
                if codepoint <= 0x7F
                else 2
                if codepoint <= 0x7FF
                else 3
                if codepoint <= 0xFFFF
                else 4
            )
        if wire_bytes > wire_cap:
            raise InputRefused(
                f"{label} exceeds its exact-wire canonical byte cap"
            )
    if wire_bytes > wire_cap:
        raise InputRefused(
            f"{label} exceeds its exact-wire canonical byte cap"
        )
    return utf8_bytes, wire_bytes


def v2_validate_exact_json_wire(
    value: Any,
    *,
    label: str,
    item_cap: int = V2_SOURCE_EXACT_WIRE_ITEM_CAP,
    node_cap: int = V2_SOURCE_EXACT_WIRE_NODE_CAP,
    depth_cap: int = V2_SOURCE_EXACT_WIRE_DEPTH_CAP,
    byte_cap: int = V2_SOURCE_PROJECTION_BYTES_CAP,
    snapshot_byte_cap: int = V2_SOURCE_EXACT_WIRE_SNAPSHOT_BYTES_CAP,
) -> Any:
    """Validate exact JSON data and return a detached stable tree."""
    if (
        type(item_cap) is not int
        or type(node_cap) is not int
        or type(depth_cap) is not int
        or type(byte_cap) is not int
        or type(snapshot_byte_cap) is not int
        or item_cap < 0
        or node_cap < 1
        or depth_cap < 0
        or byte_cap < 1
        or snapshot_byte_cap < 0
    ):
        raise EvidenceFailed(f"{label} exact-wire caps are invalid")
    stack: list[tuple[str, Any, int, str, Any]] = [
        ("value", value, 0, "$", None)
    ]
    active_containers: dict[int, None] = {}
    container_snapshots: list[tuple[Any, Any, str]] = []
    node_count = 0
    item_count = 0
    scalar_bytes = 0
    canonical_wire_bytes = 1  # canonical_bytes terminal newline.
    snapshot_bytes = 0
    while stack:
        operation, current, depth, path, state = stack.pop()
        if operation == "leave":
            dict.pop(active_containers, id(current), None)
            continue
        if operation == "list-item":
            index, expected_length = state
            present, item = v2_exact_wire_list_item(
                current,
                index=int(index),
                expected_length=int(expected_length),
                label=label,
                path=path,
            )
            if not present:
                continue
            stack.append((
                "list-item",
                current,
                depth,
                path,
                (int(index) + 1, int(expected_length)),
            ))
            stack.append((
                "value",
                item,
                depth + 1,
                f"{path}[{index}]",
                None,
            ))
            continue
        if operation == "dict-item":
            iterator, ordinal, expected_length = state
            present, key, item = v2_exact_wire_dict_item(
                current,
                iterator=iterator,
                expected_length=int(expected_length),
                label=label,
                path=path,
            )
            if not present:
                continue
            if type(key) is not str:
                raise InputRefused(
                    f"{label} contains a non-exact object key at {path}"
                )
            key_utf8_bytes, key_wire_bytes = (
                v2_exact_json_string_wire_lengths(
                    key,
                    wire_cap=byte_cap - canonical_wire_bytes,
                    label=label,
                    path=f"{path}.<key:{ordinal}>",
                )
            )
            scalar_bytes += key_utf8_bytes
            canonical_wire_bytes += key_wire_bytes
            stack.append((
                "dict-item",
                current,
                depth,
                path,
                (iterator, int(ordinal) + 1, int(expected_length)),
            ))
            stack.append((
                "value",
                item,
                depth + 1,
                f"{path}.<member:{ordinal}>",
                None,
            ))
            if (
                scalar_bytes > byte_cap
                or canonical_wire_bytes > byte_cap
            ):
                raise InputRefused(
                    f"{label} exceeds its exact-wire byte cap"
                )
            continue
        if operation != "value":
            raise EvidenceFailed(f"{label} exact-wire traversal state differs")
        if depth > depth_cap:
            raise InputRefused(f"{label} exceeds its exact-wire depth cap")
        node_count += 1
        if node_count > node_cap:
            raise InputRefused(f"{label} exceeds its exact-wire node cap")
        if current is None:
            canonical_wire_bytes += 4
            if canonical_wire_bytes > byte_cap:
                raise InputRefused(
                    f"{label} exceeds its exact-wire canonical byte cap"
                )
            continue
        if type(current) is bool:
            canonical_wire_bytes += 4 if current else 5
            if canonical_wire_bytes > byte_cap:
                raise InputRefused(
                    f"{label} exceeds its exact-wire canonical byte cap"
                )
            continue
        if type(current) is int:
            integer_text = v2_bounded_exact_integer_text(
                current,
                label=f"{label} integer at {path}",
                error_type=InputRefused,
            )
            integer_bytes = len(str.encode(integer_text, "ascii"))
            scalar_bytes += integer_bytes
            canonical_wire_bytes += integer_bytes
        elif type(current) is float:
            if not V2_EXACT_JSON_ISFINITE(current):
                raise InputRefused(
                    f"{label} contains a non-finite float at {path}"
                )
            float_text = repr(current)
            float_bytes = len(str.encode(float_text, "ascii"))
            scalar_bytes += float_bytes
            canonical_wire_bytes += float_bytes
        elif type(current) is str:
            string_utf8_bytes, string_wire_bytes = (
                v2_exact_json_string_wire_lengths(
                    current,
                    wire_cap=byte_cap - canonical_wire_bytes,
                    label=label,
                    path=path,
                )
            )
            scalar_bytes += string_utf8_bytes
            canonical_wire_bytes += string_wire_bytes
        elif type(current) is list:
            length = list.__len__(current)
            if length > item_cap - item_count:
                raise InputRefused(f"{label} exceeds its exact-wire item cap")
            item_count += length
            structural_bytes = 2 + (length - 1 if length else 0)
            snapshot_charge = (
                V2_EXACT_WIRE_LIST_SNAPSHOT_BASE_BYTES
                + length * V2_EXACT_WIRE_LIST_SNAPSHOT_ITEM_BYTES
            )
            if structural_bytes > byte_cap - canonical_wire_bytes:
                raise InputRefused(
                    f"{label} exceeds its exact-wire canonical byte cap"
                )
            if snapshot_charge > snapshot_byte_cap - snapshot_bytes:
                raise InputRefused(
                    f"{label} exceeds its exact-wire snapshot cap"
                )
            canonical_wire_bytes += structural_bytes
            snapshot_bytes += snapshot_charge
            identity = id(current)
            if identity in active_containers:
                raise InputRefused(
                    f"{label} contains a cyclic container at {path}"
                )
            active_containers[identity] = None
            snapshot = list.copy(current)
            if list.__len__(current) != length:
                raise InputRefused(
                    f"{label} changed while validating {path}"
                )
            container_snapshots.append((current, snapshot, path))
            stack.append(("leave", current, depth, path, None))
            stack.append((
                "list-item",
                snapshot,
                depth,
                path,
                (0, length),
            ))
        elif type(current) is dict:
            length = dict.__len__(current)
            dict_items = length * 2
            if dict_items > item_cap - item_count:
                raise InputRefused(f"{label} exceeds its exact-wire item cap")
            item_count += dict_items
            structural_bytes = (
                2
                + (length - 1 if length else 0)
                + length
            )
            snapshot_charge = (
                V2_EXACT_WIRE_DICT_SNAPSHOT_BASE_BYTES
                + length * V2_EXACT_WIRE_DICT_SNAPSHOT_ITEM_BYTES
            )
            if structural_bytes > byte_cap - canonical_wire_bytes:
                raise InputRefused(
                    f"{label} exceeds its exact-wire canonical byte cap"
                )
            if snapshot_charge > snapshot_byte_cap - snapshot_bytes:
                raise InputRefused(
                    f"{label} exceeds its exact-wire snapshot cap"
                )
            canonical_wire_bytes += structural_bytes
            snapshot_bytes += snapshot_charge
            identity = id(current)
            if identity in active_containers:
                raise InputRefused(
                    f"{label} contains a cyclic container at {path}"
                )
            active_containers[identity] = None
            snapshot = dict.copy(current)
            if dict.__len__(current) != length:
                raise InputRefused(
                    f"{label} changed while validating {path}"
                )
            container_snapshots.append((current, snapshot, path))
            stack.append(("leave", current, depth, path, None))
            stack.append((
                "dict-item",
                snapshot,
                depth,
                path,
                (dict.__iter__(snapshot), 0, length),
            ))
        else:
            raise InputRefused(
                f"{label} contains a non-exact JSON value at {path}"
            )
        if (
            scalar_bytes > byte_cap
            or canonical_wire_bytes > byte_cap
            or snapshot_bytes > snapshot_byte_cap
        ):
            raise InputRefused(
                f"{label} exceeds an exact-wire byte or snapshot cap"
            )
    for live_container, snapshot, path in container_snapshots:
        v2_exact_wire_container_unchanged(
            live_container,
            snapshot,
            label=label,
            path=path,
        )
    detached_by_path: dict[str, Any] = {}
    for _live_container, snapshot, snapshot_path in reversed(
        container_snapshots
    ):
        if type(snapshot) is list:
            for index in range(list.__len__(snapshot)):
                item = list.__getitem__(snapshot, index)
                if type(item) in {list, dict}:
                    child_path = f"{snapshot_path}[{index}]"
                    child = dict.get(detached_by_path, child_path)
                    if child is None:
                        raise EvidenceFailed(
                            f"{label} exact-wire detached list child is missing"
                        )
                    list.__setitem__(snapshot, index, child)
        else:
            for ordinal, (key, item) in enumerate(dict.items(snapshot)):
                if type(item) in {list, dict}:
                    child_path = f"{snapshot_path}.<member:{ordinal}>"
                    child = dict.get(detached_by_path, child_path)
                    if child is None:
                        raise EvidenceFailed(
                            f"{label} exact-wire detached object child is missing"
                        )
                    dict.__setitem__(snapshot, key, child)
        detached_by_path[snapshot_path] = snapshot
    if type(value) in {list, dict}:
        detached_root = dict.get(detached_by_path, "$")
        if detached_root is None:
            raise EvidenceFailed(f"{label} exact-wire detached root is missing")
    else:
        detached_root = value
    return detached_root


def v2_validate_source_document_against_source_files(
    source: Mapping[str, Any],
    current_source_files: list[dict[str, Any]],
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    validated_source = v2_validate_exact_json_wire(
        source,
        label="v2 source artifact",
    )
    validated_source_files = v2_validate_exact_json_wire(
        current_source_files,
        label="v2 source validation identities",
    )
    if type(validated_source) is not dict:
        raise EvidenceFailed("v2 source artifact is not an exact object")
    if type(validated_source_files) is not list:
        raise EvidenceFailed("v2 source identities are not an exact array")
    source = validated_source
    current_source_files = validated_source_files
    if (
        type(current_source_files) is not list
        or len(current_source_files) != 3
        or any(type(identity) is not dict for identity in current_source_files)
    ):
        raise EvidenceFailed(
            "v2 source validation identities are not three exact dictionaries"
        )
    expected_identity_paths = [
        SCRIPT_REL_TEXT,
        CASE_MANIFEST_REL_TEXT,
        CASE_MANIFEST_V2_REL_TEXT,
    ]
    for index, identity in enumerate(current_source_files):
        v2_exact_keys(
            identity,
            {"path", "bytes", "content_identity"},
            label=f"v2 source validation identity {index}",
        )
        if (
            type(identity["path"]) is not str
            or identity["path"] != expected_identity_paths[index]
            or type(identity["bytes"]) is not int
            or identity["bytes"] < 0
            or type(identity["content_identity"]) is not str
            or re.fullmatch(
                r"sha256-v1:[0-9a-f]{64}",
                identity["content_identity"],
            )
            is None
        ):
            raise EvidenceFailed(
                f"v2 source validation identity {index} is malformed"
            )
    if dict.get(source, "schema") != V2_SOURCE_SCHEMA:
        raise InputRefused("v2 source artifact has an unknown schema")
    v2_exact_keys(
        source,
        V2_SOURCE_FIELDS,
        label="source-v2.json",
    )
    if (
        source["schema"] != V2_SOURCE_SCHEMA
        or not isinstance(source["campaign_epoch_root"], str)
        or re.fullmatch(
            r"sha256-v1:[0-9a-f]{64}",
            source["campaign_epoch_root"],
        )
        is None
        or source["tracker_authority"] != "READ_ONLY"
        or source["direct_tracker_file_access"] is not False
        or source["network_access"] is not False
        or source["no_claim"] != V2_SOURCE_NO_CLAIM
    ):
        raise InputRefused("v2 source artifact has invalid identity or authority")
    manifest = source["manifest"]
    if not isinstance(manifest, dict):
        raise InputRefused("v2 source retained manifest is not an object")
    v2_exact_keys(
        manifest,
        V2_SOURCE_MANIFEST_FIELDS,
        label="v2 source retained manifest",
    )
    if (
        manifest["path"] != CASE_MANIFEST_V2_REL_TEXT
        or not all(
            isinstance(manifest[field], str)
            and re.fullmatch(
                r"sha256-v1:[0-9a-f]{64}",
                manifest[field],
            )
            is not None
            for field in (
                "semantic_root",
                "content_identity",
                "harness_contract_identity",
            )
        )
        or any(
            type(manifest[field]) is not int or manifest[field] < 0
            for field in ("case_count", "assertion_count", "criterion_count")
        )
    ):
        raise InputRefused("v2 source retained manifest scalars are invalid")
    contracts = source["contracts"]
    if (
        not isinstance(source["v1_baseline"], dict)
        or not isinstance(contracts, dict)
        or set(contracts) != V2_SOURCE_CONTRACT_FIELDS
        or any(
            type(value) is not dict for value in dict.values(contracts)
        )
    ):
        raise InputRefused("v2 source retained contracts are malformed")
    captured = source["captured"]
    roots = source["capture_roots"]
    if not isinstance(captured, dict) or not isinstance(roots, dict):
        raise InputRefused("v2 source lacks captured inputs or roots")
    v2_exact_keys(
        captured,
        V2_SOURCE_CAPTURE_FIELDS,
        label="v2 source captured inputs",
    )
    v2_exact_keys(
        roots,
        V2_SOURCE_CAPTURE_ROOT_FIELDS,
        label="v2 source capture roots",
    )
    if (
        not isinstance(captured["all_issues"], list)
        or not isinstance(captured["v1_lint_projection"], dict)
        or any(
            not isinstance(captured[field], dict)
            for field in (
                "v1_inventory_projection",
                "observation",
                "campaign",
                "filters",
                "review_receipts",
                "prior_campaign",
                "audit_capture",
            )
        )
    ):
        raise InputRefused("v2 source captured input types are malformed")
    v2_preflight_source_v1_lint_nested_lists(
        captured["v1_lint_projection"]
    )
    v2_preflight_source_v1_inventory_nested_lists(
        captured["v1_inventory_projection"]
    )
    v2_preflight_source_observation_nested_lists(
        captured["observation"]
    )
    all_issues = captured["all_issues"]
    if len(all_issues) > V2_INVENTORY_ROWS_CAP:
        raise InputRefused(
            "v2 source all-issue projection exceeds its row cap"
        )
    retained_projection_bytes = len(canonical_bytes([]))
    for index, row in enumerate(all_issues):
        v2_validate_source_full_issue(row, index=index)
        row_bytes = len(canonical_bytes(row))
        retained_projection_bytes = (
            row_bytes + 2
            if index == 0
            else retained_projection_bytes + row_bytes
        )
        v2_validate_aggregate_byte_count(
            retained_projection_bytes,
            cap=V2_SOURCE_PROJECTION_BYTES_CAP,
            label="v2 source all-issue projections",
            error_type=InputRefused,
        )
    v2_assert_unique(
        [row["id"] for row in all_issues],
        label="v2 source all-issue IDs",
    )
    if [row["id"] for row in all_issues] != sorted(
        row["id"] for row in all_issues
    ):
        raise InputRefused(
            "v2 source all-issue membership is noncanonical"
        )
    v2_validate_source_graph(all_issues)
    v2_validate_lint_scope_coherence(
        captured["v1_lint_projection"],
        full_issues=all_issues,
        error_type=InputRefused,
    )
    campaign = captured["campaign"]
    v2_exact_keys(
        campaign,
        {"issue_count", "issue_ids_root", "projection_root"},
        label="v2 source campaign receipt",
    )
    if (
        type(campaign["issue_count"]) is not int
        or campaign["issue_count"] < 0
        or campaign["projection_root"] != source["campaign_epoch_root"]
        or any(
            not isinstance(campaign[field], str)
            or re.fullmatch(
                r"sha256-v1:[0-9a-f]{64}",
                campaign[field],
            )
            is None
            for field in ("issue_ids_root", "projection_root")
        )
    ):
        raise EvidenceFailed("v2 source campaign receipt disagrees")
    for label, document in (
        ("v1 inventory", captured["v1_inventory_projection"]),
        ("observation", captured["observation"]),
    ):
        if "semantic_root" not in document:
            raise InputRefused(f"v2 source {label} lacks a semantic root")
        verify_semantic_root(document, label=f"source-v2 {label}")
    v2_validate_source_review_receipt_envelope(
        captured["review_receipts"]
    )
    v2_validate_source_prior_campaign_envelope(
        captured["prior_campaign"]
    )
    expected = {
        "all_issues": semantic_root(captured["all_issues"]),
        "v1_lint_projection": semantic_root(captured["v1_lint_projection"]),
        "v1_inventory_projection": captured["v1_inventory_projection"][
            "semantic_root"
        ],
        "observation": captured["observation"]["semantic_root"],
        "review_receipts": captured["review_receipts"]["semantic_root"],
        "prior_campaign": captured["prior_campaign"]["semantic_root"],
        "audit_capture": captured["audit_capture"]["semantic_root"],
    }
    if roots != expected:
        raise EvidenceFailed("v2 source captured-input roots disagree")
    campaign_ready_values = captured["observation"].get(
        "tracker_ready_issue_ids"
    )
    if not isinstance(campaign_ready_values, list):
        raise InputRefused(
            "v2 source campaign lacks exact tracker-ready membership"
        )
    campaign_ready_ids = set(campaign_ready_values)
    campaign_issues = sorted(
        (
            v2_bind_tracker_actionability(
                row,
                tracker_ready=row["id"] in campaign_ready_ids,
            )
            for row in all_issues
            if not v2_is_terminal_status(row["status"])
        ),
        key=lambda row: row["id"],
    )
    if (
        campaign["issue_count"] != len(campaign_issues)
        or campaign["issue_ids_root"]
        != semantic_root([row["id"] for row in campaign_issues])
        or campaign["projection_root"]
        != semantic_root(
            [v2_stable_issue_projection(row) for row in campaign_issues]
        )
    ):
        raise EvidenceFailed("v2 source campaign membership receipt disagrees")
    observation_preflight = captured["observation"]
    v2_exact_keys(
        observation_preflight,
        V2_SOURCE_OBSERVATION_FIELDS,
        label="v2 source observation",
    )
    if (
        observation_preflight["schema"] != V2_SOURCE_SCHEMA
        or observation_preflight["no_claim"]
        != V2_SOURCE_OBSERVATION_NO_CLAIM
        or not isinstance(observation_preflight["source_files"], list)
        or len(observation_preflight["source_files"]) != 3
        or any(
            not isinstance(identity, dict)
            or set(identity) != {"path", "bytes", "content_identity"}
            for identity in observation_preflight["source_files"]
        )
    ):
        raise InputRefused(
            "v2 source observation identity or capture contract is malformed"
        )
    current_source_files_preflight = [
        dict(identity) for identity in current_source_files
    ]
    expected_source_files_preflight = current_source_files_preflight
    if (
        observation_preflight["source_files"]
        != expected_source_files_preflight
        or observation_preflight["source_files"][1]["content_identity"]
        != source["v1_baseline"].get("v1_manifest_content_root")
        or observation_preflight["source_files"][2]["content_identity"]
        != observation_preflight["case_manifest_content_identity"]
    ):
        raise EvidenceFailed(
            "v2 source observation source-file identities are not bound to "
            "the executing harness and retained manifest baselines"
        )
    try:
        independent_findings = {
            row["id"]: findings
            for row in all_issues
            if (findings := independent_template_findings(row))
        }
        lint_ids = set(
            lint_result_map(captured["v1_lint_projection"])
        )
        all_issue_by_id = {row["id"]: row for row in all_issues}
        finding_ids = lint_ids | set(independent_findings)
        tombstone_finding_ids = {
            issue_id
            for issue_id in finding_ids
            if all_issue_by_id[issue_id]["status"] == "tombstone"
        }
        if tombstone_finding_ids:
            raise InputRefused(
                "v2 source contains unsupported tombstone template findings"
            )
        target_ids = sorted(
            {
                row["id"]
                for row in all_issues
                if not v2_is_terminal_status(row["status"])
            }
            | finding_ids
        )
    except HarnessError:
        raise
    except (
        AttributeError,
        IndexError,
        KeyError,
        TypeError,
        ValueError,
    ) as error:
        raise InputRefused(
            "v2 source v1 lint or inventory projection is malformed"
        ) from error
    filters = captured["filters"]
    if (
        not isinstance(filters, dict)
        or set(filters)
        != {
            "priorities",
            "statuses",
            "targets",
            "readiness",
            "routes",
            "empty_means_all",
            "authority_filters_apply_to_selected_projection",
        }
        or not isinstance(filters["priorities"], list)
        or not isinstance(filters["statuses"], list)
        or not isinstance(filters["targets"], list)
        or not isinstance(filters["readiness"], list)
        or not isinstance(filters["routes"], list)
        or any(
            not isinstance(value, str)
            or value not in {f"P{priority}" for priority in range(5)}
            for value in filters["priorities"]
        )
        or any(
            not isinstance(value, str)
            for value in filters["statuses"]
        )
        or any(
            not isinstance(value, str)
            or re.fullmatch(
                r"[A-Za-z0-9][A-Za-z0-9._:-]{0,255}",
                value,
            )
            is None
            for value in filters["targets"]
        )
        or any(
            not isinstance(value, str)
            or value not in V2_READINESS_STATES
            for value in filters["readiness"]
        )
        or any(
            not isinstance(value, str)
            or value not in V2_REMEDIATION_ROUTES
            for value in filters["routes"]
        )
        or filters["priorities"] != sorted(set(filters["priorities"]))
        or filters["statuses"] != sorted(set(filters["statuses"]))
        or filters["targets"] != sorted(set(filters["targets"]))
        or filters["readiness"] != sorted(set(filters["readiness"]))
        or filters["routes"] != sorted(set(filters["routes"]))
        or filters["empty_means_all"] is not True
        or filters["authority_filters_apply_to_selected_projection"] is not True
    ):
        raise EvidenceFailed("v2 source filter projection is malformed")
    for index, value in enumerate(filters["statuses"]):
        v2_validate_status(
            value,
            label=f"v2 source status filter row {index}",
            error_type=EvidenceFailed,
        )
    v2_validate_status_filter_membership(
        set(filters["statuses"]) or None,
        all_issues,
        label="v2 source status filter",
        error_type=EvidenceFailed,
    )
    observation = captured["observation"]
    v2_exact_keys(
        observation,
        V2_SOURCE_OBSERVATION_FIELDS,
        label="v2 source observation",
    )
    br_version = observation.get("br_version")
    capture_contract = observation.get("capture_contract")
    source_files = observation.get("source_files")
    normalized_br_version = v2_normalize_br_version(
        br_version,
        error_type=InputRefused,
    )
    normalized_br_capabilities = v2_normalize_br_capabilities(
        observation.get("br_capabilities"),
        error_type=InputRefused,
    )
    if (
        observation["schema"] != V2_SOURCE_SCHEMA
        or br_version != normalized_br_version
        or observation["br_capabilities"]
        != normalized_br_capabilities
        or normalized_br_capabilities["version"]
        != normalized_br_version["version"]
        or any(
            not isinstance(observation[field], dict)
            for field in ("tracker_status", "sync_status", "export_witness")
        )
        or not isinstance(source_files, list)
        or len(source_files) != 3
        or observation["no_claim"] != V2_SOURCE_OBSERVATION_NO_CLAIM
    ):
        raise InputRefused(
            "v2 source observation identity or capture contract is malformed"
        )
    root_fields = (
        "coherent_capture_root",
        "rule_contract_root",
        "live_issue_projection_root",
        "tracker_list_rows_root",
        "tracker_tombstone_rows_root",
        "tracker_ready_issue_ids_root",
        "tracker_ready_rows_root",
        "lint_issue_ids_root",
        "independent_finding_issue_ids_root",
        "nonclosed_issue_ids_root",
        "selected_review_issue_ids_root",
    )
    if any(
        not isinstance(observation[field], str)
        or re.fullmatch(
            r"sha256-v1:[0-9a-f]{64}",
            observation[field],
        )
        is None
        for field in root_fields
    ):
        raise InputRefused("v2 source observation contains a malformed root")
    audit_capture, audit_receipts = v2_validate_audit_capture(
        captured["audit_capture"],
        allowed_issue_ids={row["id"] for row in all_issues},
    )
    v2_validate_source_capture_contract(
        capture_contract,
        audit_capture=audit_capture,
        coherent_capture_root=observation["coherent_capture_root"],
    )
    observed_source_paths: list[str] = []
    for index, identity in enumerate(source_files):
        if not isinstance(identity, dict):
            raise InputRefused(
                f"v2 source observation source file {index} is malformed"
            )
        v2_exact_keys(
            identity,
            {"path", "bytes", "content_identity"},
            label=f"v2 source observation source file {index}",
        )
        if (
            not isinstance(identity["path"], str)
            or type(identity["bytes"]) is not int
            or identity["bytes"] < 0
            or not isinstance(identity["content_identity"], str)
            or re.fullmatch(
                r"sha256-v1:[0-9a-f]{64}",
                identity["content_identity"],
            )
            is None
        ):
            raise InputRefused(
                f"v2 source observation source file {index} is malformed"
            )
        try:
            canonical_path = str(
                safe_relative(
                    identity["path"],
                    label=f"v2 source observation source file {index}",
                )
            )
        except UsageRefused as error:
            raise InputRefused(
                f"v2 source observation source file {index} path is unsafe"
            ) from error
        if canonical_path != identity["path"]:
            raise InputRefused(
                f"v2 source observation source file {index} path is noncanonical"
            )
        observed_source_paths.append(canonical_path)
    if len(observed_source_paths) != len(set(observed_source_paths)):
        raise InputRefused("v2 source observation duplicates a source file")
    if observed_source_paths != [
        SCRIPT_REL_TEXT,
        CASE_MANIFEST_REL_TEXT,
        CASE_MANIFEST_V2_REL_TEXT,
    ]:
        raise InputRefused(
            "v2 source observation source-file membership or order differs"
        )
    expected_source_files = current_source_files
    if (
        source_files != expected_source_files
        or source_files[1]["content_identity"]
        != source["v1_baseline"].get("v1_manifest_content_root")
        or source_files[2]["content_identity"]
        != observation["case_manifest_content_identity"]
    ):
        raise EvidenceFailed(
            "v2 source observation source-file identities are not bound to "
            "the executing harness and retained manifest baselines"
        )
    normalized_tracker_status = v2_normalize_br_status(
        observation["tracker_status"],
        error_type=InputRefused,
    )
    tracker_list_rows = v2_normalize_retained_br_rows(
        observation["tracker_list_rows"],
        label="retained v2 ordinary list rows",
        relation_counts=True,
        error_type=InputRefused,
    )
    tracker_tombstone_rows = v2_normalize_retained_br_rows(
        observation["tracker_tombstone_rows"],
        label="retained v2 tombstone list rows",
        relation_counts=True,
        error_type=InputRefused,
    )
    tracker_ready_rows = v2_normalize_retained_br_rows(
        observation["tracker_ready_rows"],
        label="retained v2 ready rows",
        relation_counts=False,
        error_type=InputRefused,
    )
    ordinary_issue_ids = sorted(
        issue_id
        for issue_id, issue in all_issue_by_id.items()
        if issue["status"] != "tombstone"
    )
    tombstone_issue_ids = sorted(
        issue_id
        for issue_id, issue in all_issue_by_id.items()
        if issue["status"] == "tombstone"
    )
    if (
        [row["id"] for row in tracker_list_rows] != ordinary_issue_ids
        or [row["id"] for row in tracker_tombstone_rows]
        != tombstone_issue_ids
        or observation["tracker_list_rows"] != tracker_list_rows
        or observation["tracker_tombstone_rows"]
        != tracker_tombstone_rows
        or observation["tracker_ready_rows"] != tracker_ready_rows
        or observation["tracker_list_rows_root"]
        != semantic_root(tracker_list_rows)
        or observation["tracker_tombstone_rows_root"]
        != semantic_root(tracker_tombstone_rows)
        or observation["tracker_ready_rows_root"]
        != semantic_root(tracker_ready_rows)
    ):
        raise InputRefused(
            "v2 source observation list-row roots or memberships differ"
        )
    v2_validate_capture_row_coherence(
        [*tracker_list_rows, *tracker_tombstone_rows],
        all_issues,
        label="retained v2 list rows",
        relation_counts=True,
        error_type=InputRefused,
    )
    v2_validate_capture_row_coherence(
        tracker_ready_rows,
        all_issues,
        label="retained v2 ready rows",
        relation_counts=False,
        error_type=InputRefused,
    )
    tracker_ready_issue_ids = observation["tracker_ready_issue_ids"]
    if (
        any(
            not isinstance(issue_id, str) or not issue_id
            for issue_id in tracker_ready_issue_ids
        )
        or tracker_ready_issue_ids != sorted(tracker_ready_issue_ids)
        or len(tracker_ready_issue_ids)
        != len(set(tracker_ready_issue_ids))
        or any(
            issue_id not in all_issue_by_id
            for issue_id in tracker_ready_issue_ids
        )
        or any(
            all_issue_by_id[issue_id]["status"] == "tombstone"
            for issue_id in tracker_ready_issue_ids
        )
        or len(tracker_ready_issue_ids)
        != normalized_tracker_status["summary"]["ready_issues"]
        or observation["tracker_ready_issue_ids_root"]
        != semantic_root(tracker_ready_issue_ids)
        or [row["id"] for row in tracker_ready_rows]
        != tracker_ready_issue_ids
    ):
        raise InputRefused(
            "v2 source observation ready membership is noncanonical, "
            "unrooted, or inconsistent with tracker status"
        )
    v2_validate_tracker_ready_membership(
        all_issues,
        tracker_ready_issue_ids,
        error_type=InputRefused,
    )
    normalized_sync_status = v2_normalize_br_sync_status(
        observation["sync_status"],
        input_kind="retained",
        error_type=InputRefused,
    )
    normalized_export_witness = v2_normalize_br_export_witness(
        observation["export_witness"],
        input_kind="retained",
        expected_chunk_size_lines=(
            V2_BR_WITNESS_CAPTURE_CHUNK_SIZE_LINES
        ),
        expected_max_parallelism=(
            V2_BR_WITNESS_CAPTURE_MAX_PARALLELISM
        ),
        error_type=InputRefused,
    )
    if (
        observation["tracker_status"] != normalized_tracker_status
        or observation["sync_status"] != normalized_sync_status
        or observation["export_witness"] != normalized_export_witness
    ):
        raise InputRefused(
            "v2 source observation br envelopes are not canonically normalized"
        )
    v2_validate_live_envelope_consistency(
        tracker_status=normalized_tracker_status,
        sync_status=normalized_sync_status,
        export_witness=normalized_export_witness,
        full_issues=all_issues,
        error_type=InputRefused,
    )
    observation_receipts = v2_validate_source_command_receipts(
        observation,
        issue_ids=[row["id"] for row in all_issues],
        full_issues=all_issues,
        lint=captured["v1_lint_projection"],
    )
    v1_inventory_rows = captured["v1_inventory_projection"].get("rows")
    if (
        not isinstance(v1_inventory_rows, list)
        or len(v1_inventory_rows) > V2_INVENTORY_ROWS_CAP
        or any(
            not isinstance(row, dict)
            or not isinstance(row.get("id"), str)
            or not row["id"]
            for row in v1_inventory_rows
        )
    ):
        raise InputRefused(
            "v2 source v1 inventory rows are malformed"
        )
    v1_inventory_ids = [row["id"] for row in v1_inventory_rows]
    if (
        v1_inventory_ids != sorted(v1_inventory_ids)
        or len(v1_inventory_ids) != len(set(v1_inventory_ids))
    ):
        raise InputRefused(
            "v2 source v1 inventory membership is noncanonical"
        )
    expected_lint_ids = sorted(lint_ids)
    expected_independent_ids = sorted(independent_findings)
    expected_nonclosed_ids = sorted(
        row["id"]
        for row in all_issues
        if not v2_is_terminal_status(row["status"])
    )
    expected_finding_ids = set(expected_lint_ids) | set(
        expected_independent_ids
    )
    tombstone_finding_ids = sorted(
        issue_id
        for issue_id in expected_finding_ids
        if all_issue_by_id[issue_id]["status"] == "tombstone"
    )
    if tombstone_finding_ids:
        raise InputRefused(
            "v2 source contains unsupported tombstone template findings"
        )
    expected_reviewable_finding_ids = {
        issue_id
        for issue_id in expected_finding_ids
        if all_issue_by_id[issue_id]["status"] != "tombstone"
    }
    expected_selected_ids = sorted(
        set(expected_nonclosed_ids) | expected_reviewable_finding_ids
    )
    expected_closed_finding_ids = (
        expected_reviewable_finding_ids - set(expected_nonclosed_ids)
    )
    observation_counts = {
        "live_issue_count": len(all_issues),
        "selected_review_issue_count": len(expected_selected_ids),
        "nonclosed_issue_count": len(expected_nonclosed_ids),
        "closed_finding_issue_count": len(expected_closed_finding_ids),
    }
    if (
        observation["case_manifest_root"] != manifest["semantic_root"]
        or observation["case_manifest_content_identity"]
        != manifest["content_identity"]
        or observation["live_issue_projection_root"]
        != semantic_root(all_issues)
        or observation["lint_issue_ids_root"]
        != semantic_root(expected_lint_ids)
        or observation["independent_finding_issue_ids_root"]
        != semantic_root(expected_independent_ids)
        or observation["nonclosed_issue_ids_root"]
        != semantic_root(expected_nonclosed_ids)
        or observation["selected_review_issue_ids_root"]
        != semantic_root(expected_selected_ids)
        or observation["status_cut"]
        != list(
            v2_canonical_status_scopes(
                [
                    scope
                    for scope in captured["v1_lint_projection"]
                    if scope != "all"
                ]
            )
        )
        or v1_inventory_ids != expected_selected_ids
        or any(
            type(observation[field]) is not int
            or observation[field] != expected
            for field, expected in dict.items(observation_counts)
        )
    ):
        raise EvidenceFailed(
            "v2 source observation membership, manifest, or count bindings "
            "disagree"
        )
    rule_contract = v2_source_rule_contract()
    expected_capture = v2_capture_state(
        issue_ids=sorted(row["id"] for row in all_issues),
        full_issues=all_issues,
        lint=captured["v1_lint_projection"],
        tracker_status=observation["tracker_status"],
        tracker_ready_issue_ids=tracker_ready_issue_ids,
        sync_status=observation["sync_status"],
        export_witness=observation["export_witness"],
        version=observation["br_version"],
        capabilities=observation["br_capabilities"],
        source_files=source_files,
        rule_contract=rule_contract,
        case_manifest_root=manifest["semantic_root"],
        case_manifest_content_identity=manifest["content_identity"],
        listed_rows=tracker_list_rows,
        tombstone_rows=tracker_tombstone_rows,
        tracker_ready_rows=tracker_ready_rows,
    )
    if (
        observation["rule_contract_root"] != semantic_root(rule_contract)
        or observation["coherent_capture_root"]
        != expected_capture["semantic_root"]
    ):
        raise EvidenceFailed(
            "v2 source observation coherent-capture or rule-contract root "
            "cannot be reconstructed"
        )
    try:
        expected_v1_inventory = assemble_inventory(
            captured["v1_lint_projection"],
            [all_issue_by_id[issue_id] for issue_id in target_ids],
            observation,
            independent_findings,
            include_issue_rows_without_findings=True,
        )
    except HarnessError:
        raise
    except (
        AttributeError,
        IndexError,
        KeyError,
        TypeError,
        ValueError,
    ) as error:
        raise InputRefused(
            "v2 source v1 inventory projection cannot be reconstructed"
        ) from error
    if expected_v1_inventory != captured["v1_inventory_projection"]:
        divergence = first_projection_divergence(
            expected_v1_inventory,
            captured["v1_inventory_projection"],
        )
        raise EvidenceFailed(
            "v2 source v1 inventory cannot be reconstructed from captured "
            f"inputs at {divergence or '$'}"
        )
    if len(observation_receipts) + len(audit_receipts) > (
        V2_LOG_EVENTS_CAP - 8
    ):
        raise InputRefused(
            "v2 source command receipts exceed the retained event budget"
        )
    if "state" not in audit_capture:
        all_issue_by_id = {row["id"]: row for row in all_issues}
        priority_filter = set(filters["priorities"])
        status_filter = set(filters["statuses"])
        target_filter = set(filters["targets"])
        expected_audit_ids = {
            issue_id
            for issue_id in v1_inventory_ids
            if issue_id in all_issue_by_id
            and all_issue_by_id[issue_id]["status"] == "closed"
            and (
                not priority_filter
                or f"P{all_issue_by_id[issue_id]['priority']}"
                in priority_filter
            )
            and (
                not status_filter
                or all_issue_by_id[issue_id]["status"] in status_filter
            )
            and (
                not target_filter
                or issue_id in target_filter
            )
        }
        legacy_coverage_anchor_issue = contracts["history"][
            "legacy_coverage_anchor_issue"
        ]
        if type(legacy_coverage_anchor_issue) is not str:
            raise InputRefused(
                "v2 source history coverage anchor is not an exact string"
            )
        expected_audit_ids = (
            expected_audit_ids | {legacy_coverage_anchor_issue}
        )
        if audit_capture["issue_ids"] != sorted(expected_audit_ids):
            raise InputRefused(
                "v2 source audit capture membership differs from the selected "
                "closed/history universe"
            )
    documents = audit_capture["documents"]
    if not isinstance(documents, list):
        raise EvidenceFailed("v2 source audit capture is malformed")
    audit_ids: list[str] = []
    for index, document in enumerate(documents):
        if not isinstance(document, dict):
            raise EvidenceFailed(f"v2 source audit row {index} is malformed")
        issue_id = str(document["issue_id"] or "")
        try:
            normalized = v2_normalize_audit_document(
                {"issue_id": issue_id, "events": document["events"]},
                issue_id=issue_id,
            )
        except InfrastructureFailed as error:
            raise InputRefused(
                f"v2 retained source audit row {index} is malformed"
            ) from error
        if normalized != document:
            raise EvidenceFailed(
                f"v2 source audit row {index} differs from strict normalization"
            )
        audit_ids.append(issue_id)
    v2_assert_unique(audit_ids, label="v2 source audit IDs")
    verify_semantic_root(source, label="source-v2.json")
    return source, current_source_files


def v2_validate_source_document(source: Mapping[str, Any]) -> None:
    v2_validate_source_document_against_source_files(
        source,
        v2_source_file_identities(),
    )


def v2_validate_source_manifest_anchor(
    source: Mapping[str, Any],
    accepted_manifest: Mapping[str, Any],
) -> None:
    if type(source) is not dict or type(accepted_manifest) is not dict:
        raise EvidenceFailed(
            "v2 source and accepted manifest anchor must be exact objects"
        )
    retained = dict.get(source, "manifest")
    if type(retained) is not dict:
        raise EvidenceFailed("v2 source lacks a retained manifest identity")
    if (
        dict.get(retained, "semantic_root")
        != dict.get(accepted_manifest, "semantic_root")
        or dict.get(retained, "content_identity")
        != dict.get(accepted_manifest, "content_identity")
        or dict.get(retained, "harness_contract_identity")
        != dict.get(accepted_manifest, "harness_contract_identity")
        or dict.get(retained, "case_count")
        != dict.get(accepted_manifest, "case_count")
        or dict.get(retained, "assertion_count")
        != dict.get(accepted_manifest, "assertion_count")
        or dict.get(retained, "criterion_count")
        != dict.get(accepted_manifest, "criterion_count")
    ):
        raise EvidenceFailed(
            "v2 retained manifest identity differs from the accepted trust anchor"
        )
    expected_contracts = {
        "source": dict(accepted_manifest["source_contract"]),
        "row": dict(accepted_manifest["row_contract"]),
        "authority": dict(accepted_manifest["authority_contract"]),
        "packing": dict(accepted_manifest["packing_contract"]),
        "history": dict(accepted_manifest["history_contract"]),
        "artifact": dict(accepted_manifest["artifact_contract"]),
        "logging": dict(accepted_manifest["logging_contract"]),
        "replay": dict(accepted_manifest["replay_contract"]),
        "caps": dict(accepted_manifest["caps"]),
    }
    if dict.get(source, "contracts") != expected_contracts:
        raise EvidenceFailed(
            "v2 retained contracts differ from the accepted manifest"
        )
    if dict.get(source, "v1_baseline") != dict.get(
        accepted_manifest,
        "compatibility_contract",
    ):
        raise EvidenceFailed(
            "v2 retained v1 baseline differs from the accepted manifest"
        )


def v2_read_retained_bundle(
    *,
    artifact_root: str,
    input_dir: str,
) -> tuple[Path, dict[str, bytes], dict[str, Any], list[dict[str, Any]]]:
    directory = resolve_run_dir(
        artifact_root,
        input_dir,
        label="v2 replay input",
        must_exist=True,
    )
    if directory.is_symlink() or not directory.is_dir():
        raise InputRefused("v2 replay input is not a safe directory")
    observed_files, observed_directories, file_identities = v2_enumerate_bundle(
        directory
    )
    if "terminal.json" not in file_identities:
        raise InputRefused("v2 replay input lacks terminal.json")
    terminal_payload = v2_read_file_strict(
        directory / "terminal.json",
        label="v2 terminal.json",
        expected_identity=file_identities["terminal.json"],
    )
    terminal = strict_json_loads(
        terminal_payload,
        label="v2 terminal.json",
        require_canonical=True,
    )
    if not isinstance(terminal, dict) or terminal.get("schema") != V2_TERMINAL_SCHEMA:
        raise InputRefused("v2 terminal.json has an unknown schema")
    verify_semantic_root(terminal, label="terminal.json")
    registry = terminal["optional_content_registry"]
    if not isinstance(registry, list):
        raise EvidenceFailed("v2 terminal optional registry is malformed")
    optional_paths: list[str] = []
    for index, entry in enumerate(registry):
        if not isinstance(entry, dict):
            raise EvidenceFailed(f"v2 terminal optional row {index} is malformed")
        optional_paths.append(
            v2_safe_member(
                str(entry.get("relative_path") or ""),
                label=f"v2 terminal optional row {index}",
            )
        )
    v2_assert_unique(optional_paths, label="v2 terminal optional paths")
    expected_files = sorted(
        [*V2_RUN_ARTIFACTS, *optional_paths],
        key=lambda value: value.encode("utf-8"),
    )
    if observed_files != expected_files:
        missing = sorted(set(expected_files) - set(observed_files))
        extra = sorted(set(observed_files) - set(expected_files))
        first = (missing or extra or ["membership"])[0]
        raise InputRefused(
            f"v2 replay first divergence at {first}: missing={missing[:1]} extra={extra[:1]}"
        )
    expected_directory_set: set[str] = set()
    for path in optional_paths:
        parent = PurePosixPath(path).parent
        while str(parent) != ".":
            expected_directory_set.add(str(parent))
            parent = parent.parent
    expected_directories = sorted(
        expected_directory_set,
        key=lambda value: value.encode("utf-8"),
    )
    if observed_directories != expected_directories:
        raise InputRefused("v2 replay contains an unlisted directory")
    payloads = {
        name: v2_read_file_strict(
            directory.joinpath(*PurePosixPath(name).parts),
            label=f"v2 artifact {name}",
            expected_identity=file_identities[name],
        )
        for name in observed_files
    }
    if payloads["terminal.json"] != terminal_payload:
        raise InputRefused("v2 terminal changed between strict reads")
    expected_terminal = terminal.get("terminal")
    if not isinstance(expected_terminal, str) or expected_terminal not in TERMINAL_EXIT:
        raise EvidenceFailed("v2 terminal names an unknown terminal state")
    events = v2_read_event_stream(
        payloads["events.jsonl"],
        expected_terminal=expected_terminal,
    )
    return directory, payloads, terminal, events


def v2_validate_refusal_bundle(
    *,
    artifact_root: str,
    input_dir: str,
    payloads: Mapping[str, bytes],
    terminal: Mapping[str, Any],
    events: Sequence[Mapping[str, Any]],
    accepted_manifest: Mapping[str, Any],
) -> dict[str, Any]:
    terminal_fields = {
        "schema",
        "mode",
        "subject_mode",
        "bundle_state",
        "terminal",
        "exit_code",
        "artifact_root",
        "artifact_dir",
        "base_artifacts",
        "safe_relative_artifacts",
        "artifact_identities",
        "optional_content_registry",
        "manifest_root",
        "manifest_content_identity",
        "source_root",
        "inventory_root",
        "authority_root",
        "review_plan_root",
        "history_root",
        "zero_sets_root",
        "events_content_root",
        "event_count",
        "event_sequence",
        "event_roots",
        "terminal_event_root",
        "reproduction",
        "replay_equivalence",
        "failure_evidence",
        "failure_root",
        "first_divergence",
        "recovery",
        "complete_evidence_bundle",
        "complete_green_prefix",
        "retry_requires_fresh_run_dir",
        "no_claim",
        "semantic_root",
    }
    v2_exact_keys(
        terminal,
        terminal_fields,
        label="v2 refusal terminal",
    )
    verify_semantic_root(terminal, label="v2 refusal terminal")
    terminal_name = terminal["terminal"]
    expected_recovery = {
        "InputRefused": "CORRECT_INPUT_AND_RETRY_IN_FRESH_RUN_DIR",
        "NoData": "PROVIDE_REQUIRED_DATA_AND_RETRY_IN_FRESH_RUN_DIR",
        "EvidenceFailed": "MANUAL_RECOVERY_REQUIRED",
    }.get(terminal_name)
    expected_terminal_no_claim = (
        "the complete non-green seal proves only a typed semantic "
        "refusal and can never be promoted or replayed as Pass"
    )
    if (
        terminal["schema"] != V2_TERMINAL_SCHEMA
        or terminal["bundle_state"] != "COMPLETE_NON_GREEN"
        or terminal_name not in V2_SEMANTIC_REFUSAL_TERMINALS
        or terminal["exit_code"] != TERMINAL_EXIT[terminal_name]
        or terminal["mode"] not in {"review-plan", "history-plan"}
        or terminal["subject_mode"] != terminal["mode"]
        or terminal["artifact_root"]
        != str(safe_relative(artifact_root, label="artifact root"))
        or terminal["artifact_dir"]
        != str(safe_relative(input_dir, label="artifact dir"))
        or terminal["base_artifacts"] != list(V2_RUN_ARTIFACTS)
        or terminal["safe_relative_artifacts"] != list(V2_RUN_ARTIFACTS)
        or terminal["optional_content_registry"] != []
        or terminal["manifest_root"] != accepted_manifest["semantic_root"]
        or terminal["manifest_content_identity"]
        != accepted_manifest["content_identity"]
        or terminal["complete_evidence_bundle"] is not True
        or terminal["complete_green_prefix"] is not False
        or terminal["retry_requires_fresh_run_dir"] is not True
        or terminal["replay_equivalence"] != {}
        or not isinstance(terminal["first_divergence"], str)
        or not terminal["first_divergence"]
        or terminal["recovery"] != expected_recovery
        or terminal["no_claim"] != expected_terminal_no_claim
    ):
        raise EvidenceFailed("v2 refusal terminal contract differs")
    if set(payloads) != set(V2_RUN_ARTIFACTS):
        raise EvidenceFailed("v2 refusal artifact membership is not exactly nine")
    if payloads["terminal.json"] != canonical_bytes(terminal):
        raise EvidenceFailed("v2 refusal terminal payload differs from its document")
    failure = terminal["failure_evidence"]
    if not isinstance(failure, dict):
        raise EvidenceFailed("v2 refusal terminal lacks failure evidence")
    failure_fields = {
        "schema",
        "result_category",
        "stage",
        "terminal",
        "exit_code",
        "diagnostic_code",
        "detail_root",
        "first_divergence",
        "recovery",
        "manifest_root",
        "available_roots",
        "output_reserved",
        "complete_evidence_bundle",
        "complete_green_prefix",
        "retry_requires_fresh_run_dir",
        "no_claim",
        "semantic_root",
    }
    v2_exact_keys(failure, failure_fields, label="v2 failure evidence")
    verify_semantic_root(failure, label="v2 failure evidence")
    expected_failure_no_claim = (
        "failure evidence identifies recovery work and never seals a "
        "partial or ambiguous publication as green"
    )
    available_roots = failure["available_roots"]
    expected_available_root_keys = {
        "source",
        "inventory",
        "authority",
        "review_plan",
        "history",
        "zero_sets",
    }
    if (
        failure["schema"] != V2_FAILURE_EVIDENCE_SCHEMA
        or failure["result_category"] != "SEMANTIC_REFUSAL"
        or failure["terminal"] != terminal_name
        or failure["exit_code"] != terminal["exit_code"]
        or failure["diagnostic_code"]
        != f"{terminal_name}:{failure['stage']}"
        or failure["manifest_root"] != accepted_manifest["semantic_root"]
        or failure["semantic_root"] != terminal["failure_root"]
        or failure["first_divergence"] != terminal["first_divergence"]
        or failure["recovery"] != expected_recovery
        or not isinstance(available_roots, dict)
        or set(available_roots) != expected_available_root_keys
        or any(
            value is not None
            and (
                not isinstance(value, str)
                or not value.startswith("sha256-v1:")
            )
            for value in available_roots.values()
        )
        or failure["output_reserved"] is not True
        or failure["complete_evidence_bundle"] is not True
        or failure["complete_green_prefix"] is not False
        or failure["retry_requires_fresh_run_dir"] is not True
        or failure["no_claim"] != expected_failure_no_claim
    ):
        raise EvidenceFailed("v2 refusal failure bindings disagree")
    projection_names = {
        "source-v2.json": ("source", V2_SOURCE_SCHEMA, "source_root"),
        "inventory-v2.json": (
            "inventory",
            V2_INVENTORY_SCHEMA,
            "inventory_root",
        ),
        "authority-v2.json": (
            "authority",
            V2_AUTHORITY_SCHEMA,
            "authority_root",
        ),
        "review-plan-v2.json": (
            "review-plan",
            V2_REVIEW_PLAN_SCHEMA,
            "review_plan_root",
        ),
        "history-v2.json": (
            "history",
            V2_HISTORY_SCHEMA,
            "history_root",
        ),
        "zero-sets-v2.json": (
            "zero-sets",
            V2_ZERO_SETS_SCHEMA,
            "zero_sets_root",
        ),
    }
    envelope_fields = {
        "schema",
        "artifact_name",
        "projection",
        "expected_success_schema",
        "mode",
        "state",
        "manifest_root",
        "failure_root",
        "available_projection_root",
        "complete_green_prefix",
        "no_claim",
        "semantic_root",
    }
    schema_by_name: dict[str, str] = {
        "events.jsonl": V2_EVENT_SCHEMA,
        "reproduce.txt": "frankensim.argv-json.v2",
    }
    for name, (projection, success_schema, terminal_root_field) in (
        projection_names.items()
    ):
        document = strict_json_loads(
            payloads[name],
            label=f"v2 refusal artifact {name}",
            require_canonical=True,
        )
        if not isinstance(document, dict):
            raise EvidenceFailed(f"v2 refusal artifact {name} is not an object")
        v2_exact_keys(
            document,
            envelope_fields,
            label=f"v2 refusal artifact {name}",
        )
        verify_semantic_root(document, label=f"v2 refusal artifact {name}")
        expected_envelope_no_claim = (
            "this closed refusal envelope is complete failure evidence "
            "and is not a successful planner projection"
        )
        available_key = {
            "source": "source",
            "inventory": "inventory",
            "authority": "authority",
            "review-plan": "review_plan",
            "history": "history",
            "zero-sets": "zero_sets",
        }[projection]
        if (
            document["schema"] != V2_REFUSAL_PROJECTION_SCHEMA
            or document["artifact_name"] != name
            or document["projection"] != projection
            or document["expected_success_schema"] != success_schema
            or document["mode"] != terminal["subject_mode"]
            or document["state"] != "REFUSED"
            or document["manifest_root"] != accepted_manifest["semantic_root"]
            or document["failure_root"] != failure["semantic_root"]
            or document["available_projection_root"]
            != available_roots[available_key]
            or document["complete_green_prefix"] is not False
            or document["no_claim"] != expected_envelope_no_claim
            or terminal[terminal_root_field] != document["semantic_root"]
        ):
            raise EvidenceFailed(
                f"v2 refusal envelope bindings disagree for {name}"
            )
        schema_by_name[name] = V2_REFUSAL_PROJECTION_SCHEMA
    reproduction = strict_json_loads(
        payloads["reproduce.txt"],
        label="v2 refusal reproduce.txt",
        require_canonical=True,
    )
    reproduction = v2_validate_retained_reproduction_argv(
        reproduction,
        label="v2 refusal reproduce.txt",
    )
    if (
        reproduction != terminal["reproduction"]
    ):
        raise EvidenceFailed("v2 refusal reproduction binding differs")
    expected_identity_names = set(payloads) - {"terminal.json"}
    if set(terminal["artifact_identities"]) != expected_identity_names:
        raise EvidenceFailed("v2 refusal artifact identity membership differs")
    for name in sorted(expected_identity_names):
        expected_identity = v2_artifact_identity(
            relative_path=name,
            schema_kind=schema_by_name[name],
            payload=payloads[name],
        )
        if terminal["artifact_identities"][name] != expected_identity:
            raise EvidenceFailed(
                f"v2 refusal artifact identity differs for {name}"
            )
    expected_events = v2_refusal_event_rows(
        mode=terminal["mode"],
        terminal_name=terminal_name,
        failure=failure,
        reproduction=reproduction,
    )
    if list(events) != expected_events:
        raise EvidenceFailed("v2 refusal events differ from exact reconstruction")
    expected_event_payload = b"".join(
        canonical_bytes(row) for row in expected_events
    )
    if (
        payloads["events.jsonl"] != expected_event_payload
        or terminal["event_count"] != len(expected_events)
        or terminal["event_sequence"] != list(range(len(expected_events)))
        or terminal["event_roots"]
        != [semantic_root(row) for row in expected_events]
        or terminal["terminal_event_root"] != semantic_root(expected_events[-1])
        or terminal["events_content_root"]
        != "sha256-v1:" + hashlib.sha256(expected_event_payload).hexdigest()
    ):
        raise EvidenceFailed("v2 refusal event seal differs")
    return v2_rooted(
        {
            "schema": V2_REFUSAL_RESULT_SCHEMA,
            "terminal": terminal_name,
            "exit_code": terminal["exit_code"],
            "subject_mode": terminal["subject_mode"],
            "terminal_root": terminal["semantic_root"],
            "failure_root": failure["semantic_root"],
            "first_divergence": terminal["first_divergence"],
            "recovery": terminal["recovery"],
            "complete_evidence_bundle": True,
            "complete_green_prefix": False,
            "replay_validated_without_output": True,
            "no_claim": (
                "offline validation preserves the retained non-green result "
                "and cannot mint Pass or current tracker authority"
            ),
        }
    )


def _v2_reconstruct_retained_uncommitted(
    *,
    artifact_root: str,
    input_dir: str,
    payloads: Mapping[str, bytes],
    terminal: Mapping[str, Any],
    events: Sequence[Mapping[str, Any]],
    accepted_manifest: Mapping[str, Any],
    current_source_files: list[dict[str, Any]],
) -> tuple[
    dict[str, Any],
    dict[str, Any],
    dict[str, Any],
    dict[str, Any],
    dict[str, Any],
    dict[str, Any],
    dict[str, bytes],
]:
    terminal_fields = {
        "schema",
        "mode",
        "subject_mode",
        "bundle_state",
        "terminal",
        "exit_code",
        "artifact_root",
        "artifact_dir",
        "base_artifacts",
        "safe_relative_artifacts",
        "artifact_identities",
        "optional_content_registry",
        "manifest_root",
        "source_root",
        "inventory_root",
        "authority_root",
        "review_plan_root",
        "history_root",
        "zero_sets_root",
        "events_content_root",
        "event_count",
        "event_sequence",
        "event_roots",
        "terminal_event_root",
        "reproduction",
        "replay_equivalence",
        "first_divergence",
        "recovery",
        "complete_evidence_bundle",
        "complete_green_prefix",
        "retry_requires_fresh_run_dir",
        "no_claim",
        "semantic_root",
    }
    v2_exact_keys(
        terminal,
        terminal_fields,
        label="v2 retained green terminal",
    )
    verify_semantic_root(terminal, label="v2 retained green terminal")
    registry = terminal["optional_content_registry"]
    if type(registry) is not list:
        raise EvidenceFailed("v2 retained optional registry is malformed")
    optional_paths: list[str] = []
    registry_by_path: dict[str, dict[str, Any]] = {}
    for index, entry in enumerate(registry):
        if type(entry) is not dict:
            raise EvidenceFailed(
                f"v2 retained optional registry row {index} is malformed"
            )
        try:
            relative_value = entry["relative_path"]
        except KeyError as error:
            raise EvidenceFailed(
                f"v2 retained optional registry row {index} is malformed"
            ) from error
        if type(relative_value) is not str:
            raise EvidenceFailed(
                f"v2 retained optional registry row {index} is malformed"
            )
        relative_path = v2_safe_member(
            relative_value,
            label=f"v2 retained optional registry row {index}",
        )
        optional_paths.append(relative_path)
        registry_by_path[relative_path] = entry
    v2_assert_unique(
        optional_paths,
        label="v2 retained optional registry paths",
    )
    for optional_path in optional_paths:
        if optional_path in V2_RUN_ARTIFACTS:
            raise EvidenceFailed(
                "v2 retained optional registry shadows a base artifact"
            )
    expected_payload_names = set(V2_RUN_ARTIFACTS) | set(optional_paths)
    if set(payloads) != expected_payload_names:
        raise EvidenceFailed("v2 reconstructed artifact membership differs")
    expected_safe_artifacts = sorted(
        expected_payload_names,
        key=lambda value: value.encode("utf-8"),
    )
    expected_terminal_no_claim = (
        "the final seal proves deterministic bundle construction only; "
        "it does not prove current state on replay or mint any authority"
    )
    if (
        terminal["schema"] != V2_TERMINAL_SCHEMA
        or terminal["bundle_state"] != "COMPLETE_GREEN"
        or terminal["terminal"] != "Pass"
        or terminal["exit_code"] != 0
        or terminal["mode"]
        not in {terminal["subject_mode"], "replay"}
        or terminal["subject_mode"]
        not in {"review-plan", "history-plan"}
        or terminal["artifact_root"]
        != str(safe_relative(artifact_root, label="artifact root"))
        or terminal["artifact_dir"]
        != str(safe_relative(input_dir, label="artifact dir"))
        or terminal["base_artifacts"] != list(V2_RUN_ARTIFACTS)
        or terminal["safe_relative_artifacts"]
        != expected_safe_artifacts
        or terminal["complete_evidence_bundle"] is not True
        or terminal["complete_green_prefix"] is not True
        or terminal["first_divergence"] is not None
        or terminal["recovery"] != "NOT_REQUIRED"
        or terminal["retry_requires_fresh_run_dir"] is not False
        or terminal["no_claim"] != expected_terminal_no_claim
    ):
        raise EvidenceFailed(
            "v2 retained reconstruction requires an explicit complete-green seal"
        )
    documents: dict[str, dict[str, Any]] = {}
    schemas = {
        "source-v2.json": V2_SOURCE_SCHEMA,
        "inventory-v2.json": V2_INVENTORY_SCHEMA,
        "authority-v2.json": V2_AUTHORITY_SCHEMA,
        "review-plan-v2.json": V2_REVIEW_PLAN_SCHEMA,
        "history-v2.json": V2_HISTORY_SCHEMA,
        "zero-sets-v2.json": V2_ZERO_SETS_SCHEMA,
    }
    for name, schema in schemas.items():
        document = strict_json_loads(
            payloads[name],
            label=f"v2 artifact {name}",
            require_canonical=True,
        )
        if type(document) is not dict:
            raise InputRefused(f"v2 artifact {name} has an unknown schema")
        try:
            document_schema = document["schema"]
        except KeyError as error:
            raise InputRefused(
                f"v2 artifact {name} has an unknown schema"
            ) from error
        if document_schema != schema:
            raise InputRefused(f"v2 artifact {name} has an unknown schema")
        verify_semantic_root(document, label=name)
        documents[name] = document
    source = documents["source-v2.json"]
    retained_inventory = documents["inventory-v2.json"]
    retained_authority = documents["authority-v2.json"]
    retained_review = documents["review-plan-v2.json"]
    retained_history = documents["history-v2.json"]
    retained_zero = documents["zero-sets-v2.json"]
    source, current_source_files = (
        v2_validate_source_document_against_source_files(
            source,
            current_source_files,
        )
    )
    v2_validate_source_manifest_anchor(source, accepted_manifest)
    reproduction = strict_json_loads(
        payloads["reproduce.txt"],
        label="v2 reproduce.txt",
        require_canonical=True,
    )
    reproduction = v2_validate_retained_reproduction_argv(
        reproduction,
        label="v2 reproduce.txt",
    )

    roots = {
        "manifest_root": source["manifest"]["semantic_root"],
        "source_root": source["semantic_root"],
        "inventory_root": retained_inventory["semantic_root"],
        "authority_root": retained_authority["semantic_root"],
        "review_plan_root": retained_review["semantic_root"],
        "history_root": retained_history["semantic_root"],
        "zero_sets_root": retained_zero["semantic_root"],
    }
    for field, expected in roots.items():
        if terminal[field] != expected:
            raise EvidenceFailed(f"v2 terminal root differs at {field}")
    expected_event_sequence: list[int] = []
    expected_event_count = 0
    for event_index, _ in enumerate(events):
        expected_event_sequence.append(event_index)
        expected_event_count += 1
    if (
        terminal["event_count"] != expected_event_count
        or terminal["event_sequence"] != expected_event_sequence
        or terminal["event_roots"]
        != [semantic_root(row) for row in events]
        or terminal["terminal_event_root"] != semantic_root(events[-1])
        or terminal["events_content_root"]
        != "sha256-v1:" + hashlib.sha256(payloads["events.jsonl"]).hexdigest()
        or terminal["reproduction"] != reproduction
    ):
        raise EvidenceFailed("v2 terminal event/reproduction seal differs")

    schema_by_name = {
        **schemas,
        "events.jsonl": V2_EVENT_SCHEMA,
        "reproduce.txt": "frankensim.argv-json.v2",
    }
    for relative_path in optional_paths:
        schema_kind = registry_by_path[relative_path]["schema_kind"]
        if type(schema_kind) is not str:
            raise EvidenceFailed(
                "v2 retained optional registry schema kind is malformed"
            )
        schema_by_name[relative_path] = schema_kind
    expected_identity_names = set(payloads) - {"terminal.json"}
    if set(terminal["artifact_identities"]) != expected_identity_names:
        raise EvidenceFailed("v2 terminal artifact identity membership differs")
    for name in sorted(expected_identity_names):
        expected_identity = v2_artifact_identity(
            relative_path=name,
            schema_kind=schema_by_name[name],
            payload=payloads[name],
        )
        if terminal["artifact_identities"][name] != expected_identity:
            raise EvidenceFailed(f"v2 artifact identity differs for {name}")

    snapshot = v2_snapshot_from_source(source)
    campaign_root, _ = v2_campaign_epoch(snapshot)
    if campaign_root != source["campaign_epoch_root"]:
        raise EvidenceFailed("v2 retained campaign root cannot be reconstructed")
    filters = source["captured"]["filters"]
    priority_filter = set(filters["priorities"]) or None
    status_filter = set(filters["statuses"]) or None
    target_filter = set(filters["targets"]) or None
    readiness_filter = set(filters["readiness"]) or None
    route_filter = set(filters["routes"]) or None
    inventory = v2_build_inventory(
        snapshot,
        campaign_epoch_root=campaign_root,
        priority_filter=priority_filter,
        status_filter=status_filter,
        target_filter=target_filter,
        readiness_filter=readiness_filter,
        route_filter=route_filter,
    )
    authority = v2_derive_authority(
        inventory,
        source["captured"]["review_receipts"],
        current_br_version=str(
            source["captured"]["observation"]["br_version"]["version"]
        ),
    )
    v2_validate_zero_sets(
        retained_zero,
        source_root=source["semantic_root"],
        inventory=inventory,
        prior_campaign=source["captured"]["prior_campaign"],
        current_universe=snapshot.all_issues,
        current_finding_ids=v2_snapshot_current_finding_ids(snapshot),
    )
    subject_mode = str(terminal["subject_mode"] or terminal["mode"] or "")
    if subject_mode == "review-plan":
        review, optional_payloads = v2_build_review_plan(
            inventory,
            authority,
            max_targets=int(retained_review["max_targets_per_child"]),
            review_receipts=source["captured"]["review_receipts"],
        )
        history = v2_not_requested(
            schema=V2_HISTORY_SCHEMA,
            mode=subject_mode,
            source_root=source["semantic_root"],
            inventory_root=inventory["semantic_root"],
            projection="history",
        )
    elif subject_mode == "history-plan":
        review = v2_not_requested(
            schema=V2_REVIEW_PLAN_SCHEMA,
            mode=subject_mode,
            source_root=source["semantic_root"],
            inventory_root=inventory["semantic_root"],
            projection="review-plan",
        )
        optional_payloads = {}
        history = v2_build_history(
            source_root=source["semantic_root"],
            inventory=inventory,
            authority=authority,
            all_issues=snapshot.all_issues,
            audit_capture=source["captured"]["audit_capture"],
            history_contract=source["contracts"]["history"],
        )
    else:
        raise EvidenceFailed("v2 terminal subject mode is unknown")
    zero_sets = v2_build_zero_sets(
        source_root=source["semantic_root"],
        inventory=inventory,
        prior_campaign=source["captured"]["prior_campaign"],
        current_universe=snapshot.all_issues,
        current_finding_ids=v2_snapshot_current_finding_ids(snapshot),
    )
    reconstructed = v2_bundle_payloads(
        mode=str(terminal["mode"]),
        subject_mode=subject_mode,
        artifact_root=artifact_root,
        artifact_dir=input_dir,
        source=source,
        inventory=inventory,
        authority=authority,
        review_plan=review,
        history=history,
        zero_sets=zero_sets,
        optional_payloads=optional_payloads,
        reproduction=reproduction,
        current_source_files=current_source_files,
        replay_equivalence=terminal["replay_equivalence"] or {},
    )
    if set(reconstructed) != set(payloads):
        raise EvidenceFailed("v2 reconstructed artifact membership differs")
    for name in sorted(reconstructed):
        if reconstructed[name] != payloads[name]:
            raise EvidenceFailed(f"v2 replay first byte divergence in {name}")
    return (
        source,
        inventory,
        authority,
        review,
        history,
        zero_sets,
        optional_payloads,
    )


def v2_reconstruct_retained(
    *,
    artifact_root: str,
    input_dir: str,
    payloads: Mapping[str, bytes],
    terminal: Mapping[str, Any],
    events: Sequence[Mapping[str, Any]],
    accepted_manifest: Mapping[str, Any],
    current_source_files: list[dict[str, Any]],
) -> tuple[
    dict[str, Any],
    dict[str, Any],
    dict[str, Any],
    dict[str, Any],
    dict[str, Any],
    dict[str, Any],
    dict[str, bytes],
]:
    # Offline reconstruction is observational: even a successful plan build
    # must not retain transport-cache insertions or LRU reordering, and a
    # later byte-comparison refusal must restore the exact entry order.
    with _v2_child_transport_cache_lock:
        prior_transport_cache: list[
            tuple[
                tuple[Any, ...],
                tuple[
                    tuple[types.CodeType, ...],
                    str,
                    dict[str, int],
                ],
            ]
        ] = []
        for key in _v2_child_transport_cache:
            prior_transport_cache.append(
                (key, _v2_child_transport_cache[key]),
            )
        try:
            _v2_child_transport_cache.clear()
            return _v2_reconstruct_retained_uncommitted(
                artifact_root=artifact_root,
                input_dir=input_dir,
                payloads=payloads,
                terminal=terminal,
                events=events,
                accepted_manifest=accepted_manifest,
                current_source_files=current_source_files,
            )
        finally:
            _v2_child_transport_cache.clear()
            _v2_child_transport_cache.update(prior_transport_cache)


def v2_validate_replay_result_document(
    document: Mapping[str, Any],
    *,
    published_terminal: Mapping[str, Any],
) -> None:
    if (
        not isinstance(document, dict)
        or set(document) != V2_REPLAY_RESULT_FIELDS
    ):
        raise EvidenceFailed("v2 replay result has a non-closed schema")
    try:
        artifact_dir = safe_relative(
            document["artifact_dir"],
            label="v2 replay result artifact directory",
        )
    except (TypeError, UsageRefused) as error:
        raise EvidenceFailed(
            "v2 replay result artifact directory is unsafe"
        ) from error
    roots = (
        document["retained_terminal_root"],
        document["replay_terminal_root"],
    )
    if (
        document["schema"] != V2_REPLAY_RESULT_SCHEMA
        or document["terminal"] != "Pass"
        or not isinstance(document["subject_mode"], str)
        or document["subject_mode"] not in {"review-plan", "history-plan"}
        or str(artifact_dir) != document["artifact_dir"]
        or any(
            not isinstance(root, str)
            or re.fullmatch(r"sha256-v1:[0-9a-f]{64}", root) is None
            for root in roots
        )
        or document["live_tracker_reads"] is not False
        or document["live_tracker_writes"] is not False
        or document["network_access"] is not False
        or document["no_claim"] != V2_REPLAY_RESULT_NO_CLAIM
    ):
        raise EvidenceFailed("v2 replay result contract differs")
    verify_semantic_root(document, label="v2 replay result")
    if type(published_terminal) is not dict:
        raise EvidenceFailed("v2 replay result lacks its published terminal")
    verify_semantic_root(
        published_terminal,
        label="v2 replay result published terminal",
    )
    replay_equivalence = dict.get(
        published_terminal,
        "replay_equivalence",
    )
    try:
        published_artifact_path = (
            safe_relative(
                published_terminal["artifact_root"],
                label="v2 published replay artifact root",
            )
            / safe_relative(
                published_terminal["artifact_dir"],
                label="v2 published replay artifact directory",
            )
        )
    except (KeyError, TypeError, UsageRefused) as error:
        raise EvidenceFailed(
            "v2 replay result published terminal path is malformed"
        ) from error
    activity_mismatch = type(replay_equivalence) is not dict
    if not activity_mismatch:
        for field in (
            "live_tracker_reads",
            "live_tracker_writes",
            "network_access",
        ):
            if (
                document[field] != dict.get(replay_equivalence, field)
                or document[field] is not False
            ):
                activity_mismatch = True
                break
    if (
        dict.get(published_terminal, "schema") != V2_TERMINAL_SCHEMA
        or dict.get(published_terminal, "mode") != "replay"
        or dict.get(published_terminal, "bundle_state")
        != "COMPLETE_GREEN"
        or dict.get(published_terminal, "terminal") != "Pass"
        or dict.get(published_terminal, "exit_code") != 0
        or type(replay_equivalence) is not dict
        or document["replay_terminal_root"]
        != published_terminal["semantic_root"]
        or document["retained_terminal_root"]
        != dict.get(replay_equivalence, "retained_terminal_root")
        or document["subject_mode"]
        != dict.get(published_terminal, "subject_mode")
        or document["artifact_dir"] != str(published_artifact_path)
        or activity_mismatch
    ):
        raise EvidenceFailed(
            "v2 replay result differs from its published terminal"
        )


def _v2_replay_bundle_offline(
    *,
    artifact_root: str,
    input_dir: str,
    output_dir: str,
    accepted_manifest: Mapping[str, Any],
    current_source_files: list[dict[str, Any]],
) -> dict[str, Any]:
    source_directory, retained_payloads, terminal, events = (
        v2_read_retained_bundle(
            artifact_root=artifact_root,
            input_dir=input_dir,
        )
    )
    if terminal.get("bundle_state") == "COMPLETE_NON_GREEN":
        result = v2_validate_refusal_bundle(
            artifact_root=artifact_root,
            input_dir=input_dir,
            payloads=retained_payloads,
            terminal=terminal,
            events=events,
            accepted_manifest=accepted_manifest,
        )
        raise PublishedV2Refusal(
            terminal=str(result["terminal"]),
            document=result,
        )
    if terminal.get("bundle_state") != "COMPLETE_GREEN":
        raise EvidenceFailed("v2 replay bundle state is unknown")
    output_directory = resolve_run_dir(
        artifact_root,
        output_dir,
        label="v2 replay output",
    )
    source_resolved = source_directory.resolve(strict=True)
    output_resolved = output_directory.resolve(strict=False)
    if (
        source_resolved == output_resolved
        or source_resolved in output_resolved.parents
        or output_resolved in source_resolved.parents
    ):
        raise InputRefused("v2 replay input and output must be disjoint")
    (
        source,
        inventory,
        authority,
        review,
        history,
        zero_sets,
        optional_payloads,
    ) = v2_reconstruct_retained(
        artifact_root=artifact_root,
        input_dir=input_dir,
        payloads=retained_payloads,
        terminal=terminal,
        events=events,
        accepted_manifest=accepted_manifest,
        current_source_files=current_source_files,
    )
    reproduction = v2_reproduction_argv(
        mode="replay",
        artifact_root=artifact_root,
        artifact_dir=output_dir,
        replay_input=input_dir,
    )
    replay_equivalence = {
        "retained_terminal_root": terminal["semantic_root"],
        "retained_source_root": source["semantic_root"],
        "retained_inventory_root": inventory["semantic_root"],
        "retained_authority_root": authority["semantic_root"],
        "retained_review_plan_root": review["semantic_root"],
        "retained_history_root": history["semantic_root"],
        "retained_zero_sets_root": zero_sets["semantic_root"],
        "retained_events_content_root": terminal["events_content_root"],
        "live_tracker_reads": False,
        "live_tracker_writes": False,
        "network_access": False,
    }
    replay_payloads = v2_bundle_payloads(
        mode="replay",
        subject_mode=terminal["subject_mode"],
        artifact_root=artifact_root,
        artifact_dir=output_dir,
        source=source,
        inventory=inventory,
        authority=authority,
        review_plan=review,
        history=history,
        zero_sets=zero_sets,
        optional_payloads=optional_payloads,
        reproduction=reproduction,
        current_source_files=current_source_files,
        replay_equivalence=replay_equivalence,
    )
    publication = v2_publish_bundle(
        artifact_root=artifact_root,
        artifact_dir=output_dir,
        payloads=replay_payloads,
    )
    _, published_payloads, published_terminal, _ = v2_read_retained_bundle(
        artifact_root=artifact_root,
        input_dir=output_dir,
    )
    if published_payloads != replay_payloads:
        raise EvidenceFailed(
            "v2 replay published payloads differ from their reconstruction"
        )
    result = v2_rooted(
        {
            "schema": V2_REPLAY_RESULT_SCHEMA,
            "terminal": "Pass",
            "subject_mode": terminal["subject_mode"],
            "artifact_dir": publication["artifact_dir"],
            "retained_terminal_root": terminal["semantic_root"],
            "replay_terminal_root": published_terminal["semantic_root"],
            "live_tracker_reads": False,
            "live_tracker_writes": False,
            "network_access": False,
            "no_claim": V2_REPLAY_RESULT_NO_CLAIM,
        }
    )
    v2_validate_replay_result_document(
        result,
        published_terminal=published_terminal,
    )
    return result


def v2_replay_bundle(
    *,
    artifact_root: str,
    input_dir: str,
    output_dir: str,
    accepted_manifest: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    accepted = (
        load_case_manifest_v2()
        if accepted_manifest is None
        else v2_clone_runner_manifest(accepted_manifest)
    )
    current_source_files = v2_source_file_identities()
    if accepted_manifest is not None:
        current_source_files[2] = {
            **current_source_files[2],
            "content_identity": accepted["content_identity"],
        }
    with v2_offline_replay_scope():
        result = _v2_replay_bundle_offline(
            artifact_root=artifact_root,
            input_dir=input_dir,
            output_dir=output_dir,
            accepted_manifest=accepted,
            current_source_files=current_source_files,
        )
    return result


def peek_replay_schema(artifact_root: str, input_dir: str) -> str:
    directory = resolve_run_dir(
        artifact_root,
        input_dir,
        label="replay input",
        must_exist=True,
    )
    payload = v2_read_file_strict(
        directory / "terminal.json",
        label="replay terminal",
    )
    document = strict_json_loads(payload, label="replay terminal")
    if not isinstance(document, dict) or not isinstance(document.get("schema"), str):
        raise InputRefused("replay terminal does not identify its schema")
    return document["schema"]


