def v2_exact_descriptor_read(
    descriptor: Any,
    value: Any,
    owner: type[Any],
    *,
    label: str,
    allow_absent: bool = False,
) -> Any:
    if not v2_exact_type_is_one_of(
        descriptor,
        (types.GetSetDescriptorType, types.MemberDescriptorType),
    ):
        raise EvidenceFailed(
            f"refusal-state {label} does not use an exact built-in descriptor"
        )
    try:
        return type(descriptor).__get__(descriptor, value, owner)
    except AttributeError:
        if allow_absent:
            return V2_RAW_DESCRIPTOR_ATTRIBUTE_ABSENT
        raise EvidenceFailed(
            f"refusal-state {label} inspection failed without running user code"
        ) from None
    except Exception as error:
        raise EvidenceFailed(
            f"refusal-state {label} inspection failed without running user code"
        ) from error


def v2_raw_builtin_descriptor_attribute(value: Any, name: str) -> Any:
    descriptor: Any = None
    for owner in v2_raw_type_mro(type(value)):
        owner_dictionary = v2_raw_type_dictionary(owner)
        if name in owner_dictionary:
            descriptor = owner_dictionary[name]
            break
    if descriptor is None:
        raise EvidenceFailed(
            f"refusal-state built-in descriptor lacks exact {name} metadata"
        )
    return v2_exact_descriptor_read(
        descriptor,
        value,
        type(value),
        label=f"built-in descriptor {name}",
    )


def v2_optional_raw_builtin_descriptor_attribute(
    value: Any,
    name: str,
) -> Any:
    for owner in v2_raw_type_mro(type(value)):
        owner_dictionary = v2_raw_type_dictionary(owner)
        if name not in owner_dictionary:
            continue
        return v2_exact_descriptor_read(
            owner_dictionary[name],
            value,
            type(value),
            label=f"built-in descriptor {name}",
        )
    return None


def v2_raw_type_dictionary(value: type[Any]) -> types.MappingProxyType:
    raw = v2_exact_descriptor_read(
        V2_TYPE_DICTIONARY_DESCRIPTOR,
        value,
        type(value),
        label="type dictionary",
    )
    if type(raw) is not types.MappingProxyType:
        raise EvidenceFailed("refusal-state type dictionary is not exact")
    return raw


def v2_raw_type_attribute(value: type[Any], name: str) -> Any:
    descriptor = V2_TYPE_ATTRIBUTE_DESCRIPTORS.get(name)
    if descriptor is None:
        raise EvidenceFailed(
            "refusal-state requested an unsupported raw type attribute"
        )
    return v2_exact_descriptor_read(
        descriptor,
        value,
        type(value),
        label=f"type {name}",
    )


def v2_raw_type_mro(value: type[Any]) -> tuple[type[Any], ...]:
    raw = v2_raw_type_attribute(value, "__mro__")
    if type(raw) is not tuple:
        raise EvidenceFailed("refusal-state type MRO is not exact")
    for item in tuple.__iter__(raw):
        item_metaclass = type(item)
        if item_metaclass is type:
            continue
        metaclass_mro = v2_exact_descriptor_read(
            V2_TYPE_ATTRIBUTE_DESCRIPTORS["__mro__"],
            item_metaclass,
            type(item_metaclass),
            label="MRO member metaclass MRO",
        )
        if type(metaclass_mro) is not tuple or not any(
            member is type for member in tuple.__iter__(metaclass_mro)
        ):
            raise EvidenceFailed("refusal-state type MRO member is not a type")
    return raw


def v2_raw_instance_of(
    value: Any,
    candidate_types: type[Any] | tuple[type[Any], ...],
) -> bool:
    """Check instance ancestry without consulting value.__class__."""
    candidates = (
        candidate_types
        if type(candidate_types) is tuple
        else (candidate_types,)
    )
    value_mro = v2_raw_type_mro(type(value))
    return any(
        member is candidate
        for member in tuple.__iter__(value_mro)
        for candidate in tuple.__iter__(candidates)
    )


def v2_raw_is_type_object(value: Any) -> bool:
    return type(value) is type or any(
        member is type
        for member in tuple.__iter__(v2_raw_type_mro(type(value)))
    )


def v2_exact_type_is_one_of(
    value: Any,
    candidate_types: Iterable[type[Any]],
) -> bool:
    value_type = type(value)
    return any(value_type is candidate for candidate in candidate_types)


def v2_type_layout_is_audited(
    value: type[Any],
    *,
    audited_native_bases: Iterable[type[Any]] = (),
) -> bool:
    audited = (object, *tuple(audited_native_bases))
    native_attribute_types = (
        types.BuiltinFunctionType,
        types.BuiltinMethodType,
        types.ClassMethodDescriptorType,
        types.GetSetDescriptorType,
        types.MethodDescriptorType,
        types.WrapperDescriptorType,
    )
    for base in v2_raw_type_mro(value):
        if any(base is candidate for candidate in audited):
            continue
        for name, attribute in v2_raw_type_dictionary(base).items():
            attribute_type = type(attribute)
            if attribute_type is types.MemberDescriptorType:
                # Python __slots__ are read exactly by
                # v2_state_object_metadata.
                continue
            if (
                attribute_type is types.GetSetDescriptorType
                and name in {"__dict__", "__weakref__"}
            ):
                continue
            if any(
                attribute_type is candidate
                for candidate in native_attribute_types
            ):
                return False
    return True


def v2_require_audited_type_layout(
    value: Any,
    *,
    audited_native_bases: Iterable[type[Any]] = (),
) -> None:
    if not v2_type_layout_is_audited(
        type(value),
        audited_native_bases=audited_native_bases,
    ):
        raise EvidenceFailed(
            "refusal-state object reaches unaudited extension-backed "
            "instance state"
        )


def v2_unwrap_function_wrapper(value: Any) -> Any:
    if type(value) is staticmethod:
        descriptor = V2_STATICMETHOD_FUNCTION_DESCRIPTOR
        label = "staticmethod function"
    elif type(value) is classmethod:
        descriptor = V2_CLASSMETHOD_FUNCTION_DESCRIPTOR
        label = "classmethod function"
    else:
        raise EvidenceFailed("refusal-state callable wrapper type is unsupported")
    wrapped = v2_exact_descriptor_read(
        descriptor,
        value,
        type(value),
        label=label,
    )
    return wrapped


def v2_rlock_observation(value: Any) -> dict[str, Any]:
    type_dictionary = v2_raw_type_dictionary(V2_REFUSAL_RLOCK_TYPE)
    required = ("_is_owned", "_recursion_count", "acquire", "release")
    missing = [name for name in required if name not in type_dictionary]
    if missing:
        raise EvidenceFailed(
            "refusal-state CPython RLock observation capability is missing: "
            + ", ".join(missing)
        )
    owned = bool(type_dictionary["_is_owned"](value))
    recursion_count = int(type_dictionary["_recursion_count"](value))
    if "locked" in type_dictionary:
        locked_by_any_thread = bool(type_dictionary["locked"](value))
        any_thread_observer = "cpython-rlock-locked"
    elif owned:
        locked_by_any_thread = True
        any_thread_observer = "current-owner-implies-locked"
    else:
        acquired_for_probe = bool(type_dictionary["acquire"](value, False))
        try:
            locked_by_any_thread = not acquired_for_probe
        finally:
            if acquired_for_probe:
                type_dictionary["release"](value)
        any_thread_observer = "nonblocking-acquire-restored"
    return {
        "locked_by_any_thread": locked_by_any_thread,
        "owned_by_current_thread": owned,
        "current_thread_recursion_count": recursion_count,
        "observer": {
            "any_thread": any_thread_observer,
            "current_thread": "cpython-current-thread-private-methods",
        },
    }


def v2_new_refusal_projection_context(
    limits: Mapping[str, int] | None = None,
    *,
    authorized_external_capabilities: Iterable[str] = (),
) -> dict[str, Any]:
    accepted_limits = {
        "nodes": V2_REFUSAL_NODE_CAP,
        "items": V2_REFUSAL_ITEM_CAP,
        "scalar_bytes": V2_REFUSAL_SCALAR_BYTES_CAP,
        "instructions": V2_REFUSAL_INSTRUCTION_CAP,
        "projection_bytes": V2_REFUSAL_PROJECTION_BYTES_CAP,
    }
    if limits is not None:
        if type(limits) is not dict or not set(dict.keys(limits)).issubset(
            accepted_limits
        ):
            raise EvidenceFailed(
                "refusal-state projection limits have unknown dimensions"
            )
        for name, value in dict.items(limits):
            if type(value) is not int or value < 0:
                raise EvidenceFailed(
                    "refusal-state projection limits must be nonnegative integers"
                )
            accepted_limits[name] = value
    accepted_external_capabilities = frozenset(
        authorized_external_capabilities
    )
    return {
        "limits": accepted_limits,
        "counters": {
            "nodes": 0,
            "items": 0,
            "scalar_bytes": 0,
            "instructions": 0,
        },
        "object_ids": {},
        # Keep every graph object alive for the complete projection. CPython
        # may otherwise recycle the address of a temporary container and make
        # an unrelated later object look like a reference to the first one.
        "object_references": {},
        "active_ids": set(),
        "executable_overlay_active_ids": set(),
        "executable_overlay_references": {},
        # Executable overlays may reach the same helper through multiple
        # globals, descriptors, or constructed-result paths. Expand each exact
        # function once, then emit a stable graph reference so repeated aliases
        # cannot consume the aggregate access budget more than once.
        "executable_overlay_completed_ids": set(),
        # Privileged opcode contracts are callable-identity-bound, not merely
        # code-object-bound.  The overlay sets this only while analyzing the
        # exact function object whose executable graph is being projected.
        "active_executable_function": None,
        "next_node_id": 0,
        "global_accesses": 0,
        "explicit_external_capabilities": accepted_external_capabilities,
        "authorized_external_capabilities": accepted_external_capabilities,
    }


def v2_refusal_charge(
    context: dict[str, Any],
    dimension: str,
    amount: int = 1,
) -> None:
    counters = context["counters"]
    counters[dimension] += amount
    if counters[dimension] > context["limits"][dimension]:
        label = dimension.replace("_", " ")
        raise EvidenceFailed(
            f"refusal-state projection exceeds its aggregate {label} cap"
        )


def v2_is_dangerous_builtin(value: Any) -> bool:
    return any(value is candidate for candidate in V2_DANGEROUS_BUILTIN_IDENTITIES)


def v2_is_trusted_module(value: types.ModuleType) -> bool:
    return any(value is module for module in V2_REFUSAL_TRUSTED_MODULES)


def v2_is_external_module(value: types.ModuleType) -> bool:
    return any(value is module for module in V2_REFUSAL_EXTERNAL_MODULES)


def v2_raw_module_dict(value: types.ModuleType) -> dict[str, Any]:
    raw = v2_exact_descriptor_read(
        V2_MODULE_DICTIONARY_DESCRIPTOR,
        value,
        type(value),
        label="module dictionary",
    )
    if type(raw) is not dict:
        raise EvidenceFailed("refusal-state module dictionary is not exact")
    return raw


def v2_raw_module_name(value: types.ModuleType) -> str:
    raw_name = v2_raw_module_dict(value).get("__name__")
    if raw_name is not None and type(raw_name) is not str:
        raise EvidenceFailed("refusal-state module name is not exact")
    return raw_name if raw_name is not None else ""


def v2_external_capability_name(
    module: types.ModuleType,
    attribute_name: str,
) -> str:
    if module is os and attribute_name in {
        "chdir",
        "fchdir",
        "getcwd",
        "getcwdb",
    }:
        return "process-cwd"
    if module is os and attribute_name in {"getenv", "getenvb"}:
        return "process-python-environment"
    if module is sys and attribute_name in {
        "getrecursionlimit",
        "setrecursionlimit",
    }:
        return "process-recursion-limit"
    return f"{v2_raw_module_name(module)}.{attribute_name}"


V2_FIXTURE_SELECTED_RESOURCE_CAPABILITY = "fixture-selected-resources"
V2_FIXTURE_SELECTED_RESOURCE_IMPLEMENTATION_CAPABILITY = (
    "fixture-selected-resource-implementation"
)
V2_FIXTURE_SELECTED_RESOURCE_SCOPE_CONTROL_CAPABILITY = (
    "fixture-selected-resource-scope-control"
)


def v2_fixture_selected_resource_path_key(path: Path) -> str:
    """Return one exact lexical repository-relative selected-resource key."""
    if type(path) is not type(REPO_ROOT):
        raise EvidenceFailed(
            "selected fixture resource path must use the exact repository "
            "path type"
        )
    root_parts = REPO_ROOT.parts
    candidate_parts = path.parts
    if (
        len(candidate_parts) < len(root_parts)
        or candidate_parts[:len(root_parts)] != root_parts
    ):
        raise EvidenceFailed(
            "selected fixture resource path escapes the repository"
        )
    relative_parts = candidate_parts[len(root_parts):]
    if any(part in {"", ".", ".."} for part in relative_parts):
        raise EvidenceFailed(
            "selected fixture resource path is not lexically canonical"
        )
    path_key = "/".join(relative_parts) if relative_parts else "."
    if len(path_key) > V2_FIXTURE_RESOURCE_PATH_BYTES_CAP:
        raise EvidenceFailed(
            "selected fixture resource path exceeds its byte cap"
        )
    if path_key != unicodedata.normalize("NFC", path_key):
        raise EvidenceFailed(
            "selected fixture resource path must use NFC Unicode normalization"
        )
    try:
        path_key_bytes = str.encode(path_key, "utf-8")
    except UnicodeEncodeError as error:
        raise EvidenceFailed(
            "selected fixture resource path is not valid UTF-8"
        ) from error
    v2_require_fixture_resource_cap(
        len(path_key_bytes),
        V2_FIXTURE_RESOURCE_PATH_BYTES_CAP,
        diagnostic=(
            "selected fixture resource path exceeds its byte cap"
        ),
    )
    return path_key


V2_FIXTURE_SELECTED_RESOURCE_OPERATIONS = frozenset({
    "exclusive-overwrite-refusal",
    "fresh-run-dir-check",
    "open-read-descriptor",
    "process-cwd",
    "process-environment-binding-replace",
    "process-environment-codec-mutate",
    "process-environment-delete",
    "process-environment-set",
    "process-recursion-limit",
    "race-pristine-observation",
    "strict-read",
    "synthetic-mtime-race-read",
})
V2_FIXTURE_SELECTED_RESOURCE_PATH_OPERATIONS = frozenset({
    "exclusive-overwrite-refusal",
    "fresh-run-dir-check",
    "open-read-descriptor",
    "process-cwd",
    "strict-read",
    "synthetic-mtime-race-read",
})
V2_FIXTURE_SELECTED_RESOURCE_PATHLESS_OPERATIONS = frozenset({
    "process-environment-binding-replace",
    "process-environment-codec-mutate",
    "process-environment-delete",
    "process-environment-set",
    "process-recursion-limit",
    "race-pristine-observation",
})
if (
    V2_FIXTURE_SELECTED_RESOURCE_PATH_OPERATIONS
    & V2_FIXTURE_SELECTED_RESOURCE_PATHLESS_OPERATIONS
    or (
        V2_FIXTURE_SELECTED_RESOURCE_PATH_OPERATIONS
        | V2_FIXTURE_SELECTED_RESOURCE_PATHLESS_OPERATIONS
    )
    != V2_FIXTURE_SELECTED_RESOURCE_OPERATIONS
):
    raise InfrastructureFailed(
        "selected fixture resource operation partition is inconsistent"
    )


def v2_exact_fixture_resource_operation_grants_snapshot(
    operation_grants: Sequence[tuple[str, Sequence[Path] | None]],
) -> tuple[tuple[str, tuple[Path, ...] | None], ...]:
    if type(operation_grants) not in {list, tuple}:
        raise EvidenceFailed(
            "selected fixture resource operation grants must use an exact "
            "bounded sequence"
        )
    declared_count = len(operation_grants)
    if declared_count > len(V2_FIXTURE_SELECTED_RESOURCE_OPERATIONS):
        raise EvidenceFailed(
            "selected fixture resource operation-grant count exceeds its cap"
        )
    exact_getitem = (
        list.__getitem__
        if type(operation_grants) is list
        else tuple.__getitem__
    )
    snapshot: list[tuple[str, tuple[Path, ...] | None]] = []
    source_rows: list[tuple[str, Sequence[Path] | None]] = []
    try:
        for index in range(declared_count):
            if len(operation_grants) != declared_count:
                raise EvidenceFailed(
                    "selected fixture resource operation grants changed "
                    "while being captured"
                )
            row = exact_getitem(operation_grants, index)
            if type(row) is not tuple or len(row) != 2:
                raise EvidenceFailed(
                    "selected fixture resource operation grant is malformed"
                )
            operation = tuple.__getitem__(row, 0)
            granted_paths = tuple.__getitem__(row, 1)
            if (
                type(operation) is not str
                or operation not in V2_FIXTURE_SELECTED_RESOURCE_OPERATIONS
            ):
                raise EvidenceFailed(
                    "selected fixture resource operation grant is malformed"
                )
            if operation in V2_FIXTURE_SELECTED_RESOURCE_PATH_OPERATIONS:
                if type(granted_paths) not in {list, tuple}:
                    raise EvidenceFailed(
                        "path-bound selected fixture resource operation lacks "
                        "an exact path grant"
                    )
                path_snapshot = v2_exact_fixture_resource_paths_snapshot(
                    granted_paths
                )
                if not path_snapshot:
                    raise EvidenceFailed(
                        "path-bound selected fixture resource operation has "
                        "an empty path grant"
                    )
            else:
                if granted_paths is not None:
                    raise EvidenceFailed(
                        "pathless selected fixture resource operation has a "
                        "path grant"
                    )
                path_snapshot = None
            list.append(source_rows, row)
            list.append(snapshot, (operation, path_snapshot))
    except EvidenceFailed:
        raise
    except (IndexError, RuntimeError) as error:
        raise EvidenceFailed(
            "selected fixture resource operation grants changed while being "
            "captured"
        ) from error
    try:
        if len(operation_grants) != declared_count:
            raise EvidenceFailed(
                "selected fixture resource operation grants changed while "
                "being captured"
            )
        for index in range(declared_count):
            row = exact_getitem(operation_grants, index)
            if row is not source_rows[index]:
                raise EvidenceFailed(
                    "selected fixture resource operation grants changed "
                    "while being captured"
                )
            operation, path_snapshot = snapshot[index]
            if (
                tuple.__getitem__(row, 0) is not operation
                or (
                    path_snapshot is None
                    and tuple.__getitem__(row, 1) is not None
                )
            ):
                raise EvidenceFailed(
                    "selected fixture resource operation grants changed "
                    "while being captured"
                )
            if path_snapshot is not None:
                current_paths = v2_exact_fixture_resource_paths_snapshot(
                    tuple.__getitem__(row, 1)
                )
                if len(current_paths) != len(path_snapshot) or any(
                    current_paths[path_index] is not path_snapshot[path_index]
                    for path_index in range(len(path_snapshot))
                ):
                    raise EvidenceFailed(
                        "selected fixture resource operation grants changed "
                        "while being captured"
                    )
        if len(operation_grants) != declared_count:
            raise EvidenceFailed(
                "selected fixture resource operation grants changed while "
                "being captured"
            )
    except EvidenceFailed:
        raise
    except (IndexError, RuntimeError) as error:
        raise EvidenceFailed(
            "selected fixture resource operation grants changed while being "
            "captured"
        ) from error
    operations = tuple(row[0] for row in snapshot)
    if len(operations) != len(set(operations)):
        raise EvidenceFailed(
            "selected fixture resource operation grants contain a duplicate"
        )
    return tuple(snapshot)


def _v2_fixture_capture_anchored_resource_binding_owned(
    path: Path,
    current_slot: list[int | None],
    child_slot: list[int | None],
) -> tuple[str, tuple[tuple[int, ...], tuple[tuple[str, int, int, int], ...]]]:
    """Capture one leaf and its lexical parents without following a symlink."""
    relative = v2_fixture_selected_resource_path_key(path)
    relative_path = PurePosixPath(relative)
    directory_flags = (
        os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW
    )
    try:
        list.__setitem__(current_slot, 0, os.open(REPO_ROOT, directory_flags))
    except OSError as error:
        raise EvidenceFailed(
            "selected fixture repository root cannot be opened safely"
        ) from error
    operation_succeeded = False
    try:
        current_descriptor = list.__getitem__(current_slot, 0)
        if current_descriptor is None:
            raise EvidenceFailed(
                "selected fixture repository root descriptor ownership was lost"
            )
        root_state = os.fstat(current_descriptor)
        parent_rows: list[tuple[str, int, int, int]] = [(
            ".",
            root_state.st_dev,
            root_state.st_ino,
            stat.S_IFMT(root_state.st_mode),
        )]
        if relative == ".":
            leaf_state = root_state
        else:
            for expected_index, component in enumerate(
                relative_path.parts[:-1],
                1,
            ):
                current_descriptor = list.__getitem__(current_slot, 0)
                if current_descriptor is None:
                    raise EvidenceFailed(
                        "selected fixture resource parent descriptor ownership "
                        "was lost"
                    )
                try:
                    list.__setitem__(child_slot, 0, os.open(component, directory_flags, dir_fd=current_descriptor))
                except OSError as error:
                    raise EvidenceFailed(
                        "selected fixture resource parent cannot be opened "
                        "safely"
                    ) from error
                try:
                    child_descriptor = list.__getitem__(child_slot, 0)
                    if child_descriptor is None:
                        raise EvidenceFailed(
                            "selected fixture resource child descriptor "
                            "ownership was lost"
                        )
                    child_state = os.fstat(child_descriptor)
                    if not stat.S_ISDIR(child_state.st_mode):
                        raise EvidenceFailed(
                            "selected fixture resource parent is not a "
                            "directory"
                        )
                    parent_rows.append((
                        "/".join(relative_path.parts[:expected_index]),
                        child_state.st_dev,
                        child_state.st_ino,
                        stat.S_IFMT(child_state.st_mode),
                    ))
                except BaseException:
                    v2_collect_owned_descriptor_slot_close_failure(
                        child_slot,
                        EvidenceFailed(
                            "selected fixture resource child descriptor close "
                            "failed"
                        ),
                    )
                    raise
                close_failure = (
                    v2_collect_owned_descriptor_slot_close_failure(
                        current_slot,
                        EvidenceFailed(
                            "selected fixture resource parent descriptor close "
                            "failed"
                        ),
                    )
                )
                if close_failure is not None:
                    v2_collect_owned_descriptor_slot_close_failure(
                        child_slot,
                        EvidenceFailed(
                            "selected fixture resource child descriptor close "
                            "failed"
                        ),
                    )
                    v2_raise_descriptor_close_failure(close_failure)
                v2_transfer_owned_descriptor_slot(
                    child_slot,
                    current_slot,
                )
            current_descriptor = list.__getitem__(current_slot, 0)
            if current_descriptor is None:
                raise EvidenceFailed(
                    "selected fixture resource parent descriptor ownership "
                    "was lost"
                )
            try:
                leaf_state = os.stat(
                    relative_path.parts[-1],
                    dir_fd=current_descriptor,
                    follow_symlinks=False,
                )
            except OSError as error:
                raise EvidenceFailed(
                    "selected fixture resource metadata cannot be read safely"
                ) from error
        operation_succeeded = True
        return relative, (
            v2_fixture_stat_identity_tuple(leaf_state),
            tuple(parent_rows),
        )
    except OSError as error:
        raise EvidenceFailed(
            "selected fixture resource metadata cannot be captured safely"
        ) from error
    finally:
        v2_close_owned_descriptor_slots((
            (
                child_slot,
                EvidenceFailed(
                    "selected fixture resource child descriptor close failed"
                ),
            ),
            (
                current_slot,
                EvidenceFailed(
                    "selected fixture resource parent descriptor close failed"
                ),
            ),
        ), surface_failure=operation_succeeded)


def v2_fixture_capture_anchored_resource_binding(
    path: Path,
) -> tuple[str, tuple[tuple[int, ...], tuple[tuple[str, int, int, int], ...]]]:
    current_slot: list[int | None] = [None]
    child_slot: list[int | None] = [None]
    try:
        return _v2_fixture_capture_anchored_resource_binding_owned(
            path,
            current_slot,
            child_slot,
        )
    except BaseException:
        v2_close_owned_descriptor_slots((
            (
                child_slot,
                EvidenceFailed(
                    "selected fixture resource child descriptor close failed"
                ),
            ),
            (
                current_slot,
                EvidenceFailed(
                    "selected fixture resource parent descriptor close failed"
                ),
            ),
        ), surface_failure=False)
        raise


def _v2_build_fixture_selected_resource_scope() -> tuple[
    Callable[
        [
            Sequence[Path],
            Sequence[Path],
            Sequence[tuple[str, Sequence[Path] | None]],
        ],
        list[Any],
    ],
    Callable[[list[Any]], None],
    Callable[[Path, str], tuple[str, tuple[Any, ...]]],
    Callable[
        [Path, str],
        tuple[
            str,
            tuple[Any, ...] | None,
            tuple[tuple[str, int, int, int], ...],
        ],
    ],
    Callable[[str], None],
    Callable[[], list[Any]],
    Callable[[list[Any]], int],
    Callable[[list[Any]], None],
    Callable[[], bool],
]:
    active_scope_slot: list[dict[str, Any] | None] = [None]
    scope_lock = threading.RLock()

    def capture_lexical_parent_binding_owned(
        path: Path,
        current_slot: list[int | None],
        child_slot: list[int | None],
    ) -> tuple[tuple[str, int, int, int], ...]:
        relative_parts = path.parts[len(REPO_ROOT.parts):]
        parent_rows: list[tuple[str, int, int, int]] = []
        directory_flags = (
            os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW
        )
        try:
            list.__setitem__(current_slot, 0, os.open(REPO_ROOT, directory_flags))
        except OSError as error:
            raise EvidenceFailed(
                "selected fixture repository root cannot be opened safely"
            ) from error
        operation_succeeded = False
        try:
            current_descriptor = list.__getitem__(current_slot, 0)
            if current_descriptor is None:
                raise EvidenceFailed(
                    "selected fixture repository root descriptor ownership was "
                    "lost"
                )
            root_state = os.fstat(current_descriptor)
            list.append(parent_rows, (
                ".",
                root_state.st_dev,
                root_state.st_ino,
                stat.S_IFMT(root_state.st_mode),
            ))
            for index, component in enumerate(relative_parts[:-1], 1):
                current_descriptor = list.__getitem__(current_slot, 0)
                if current_descriptor is None:
                    raise EvidenceFailed(
                        "selected fixture access-parent descriptor ownership was "
                        "lost"
                    )
                try:
                    entry_state = os.stat(
                        component,
                        dir_fd=current_descriptor,
                        follow_symlinks=False,
                    )
                except OSError:
                    break
                entry_row = (
                    "/".join(relative_parts[:index]),
                    entry_state.st_dev,
                    entry_state.st_ino,
                    stat.S_IFMT(entry_state.st_mode),
                )
                list.append(parent_rows, entry_row)
                if not stat.S_ISDIR(entry_state.st_mode):
                    break
                try:
                    list.__setitem__(child_slot, 0, os.open(component, directory_flags, dir_fd=current_descriptor))
                except OSError:
                    break
                try:
                    child_descriptor = list.__getitem__(child_slot, 0)
                    if child_descriptor is None:
                        raise EvidenceFailed(
                            "selected fixture access-parent child descriptor "
                            "ownership was lost"
                        )
                    child_state = os.fstat(child_descriptor)
                    if not stat.S_ISDIR(child_state.st_mode):
                        raise EvidenceFailed(
                            "selected fixture access parent is not a directory"
                        )
                    opened_row = (
                        entry_row[0],
                        child_state.st_dev,
                        child_state.st_ino,
                        stat.S_IFMT(child_state.st_mode),
                    )
                    if opened_row != entry_row:
                        raise EvidenceFailed(
                            "selected fixture access parent changed while "
                            "being bound"
                        )
                except BaseException:
                    v2_collect_owned_descriptor_slot_close_failure(
                        child_slot,
                        EvidenceFailed(
                            "selected fixture access-parent descriptor close "
                            "failed"
                        ),
                    )
                    raise
                close_failure = (
                    v2_collect_owned_descriptor_slot_close_failure(
                        current_slot,
                        EvidenceFailed(
                            "selected fixture access-parent descriptor close "
                            "failed"
                        ),
                    )
                )
                if close_failure is not None:
                    v2_collect_owned_descriptor_slot_close_failure(
                        child_slot,
                        EvidenceFailed(
                            "selected fixture access-parent descriptor close "
                            "failed"
                        ),
                    )
                    v2_raise_descriptor_close_failure(close_failure)
                v2_transfer_owned_descriptor_slot(
                    child_slot,
                    current_slot,
                )
            operation_succeeded = True
            return tuple(parent_rows)
        except OSError as error:
            raise EvidenceFailed(
                "selected fixture access-parent binding failed"
            ) from error
        finally:
            v2_close_owned_descriptor_slots((
                (
                    child_slot,
                    EvidenceFailed(
                        "selected fixture access-parent descriptor close failed"
                    ),
                ),
                (
                    current_slot,
                    EvidenceFailed(
                        "selected fixture access-parent descriptor close failed"
                    ),
                ),
            ), surface_failure=operation_succeeded)

    def capture_lexical_parent_binding(
        path: Path,
    ) -> tuple[tuple[str, int, int, int], ...]:
        current_slot: list[int | None] = [None]
        child_slot: list[int | None] = [None]
        try:
            return capture_lexical_parent_binding_owned(
                path,
                current_slot,
                child_slot,
            )
        except BaseException:
            v2_close_owned_descriptor_slots((
                (
                    child_slot,
                    EvidenceFailed(
                        "selected fixture access-parent descriptor close failed"
                    ),
                ),
                (
                    current_slot,
                    EvidenceFailed(
                        "selected fixture access-parent descriptor close failed"
                    ),
                ),
            ), surface_failure=False)
            raise

    def enter(
        observed_paths: Sequence[Path],
        access_paths: Sequence[Path],
        operation_grants: Sequence[
            tuple[str, Sequence[Path] | None]
        ],
        *,
        _token_slot: list[Any],
    ) -> list[Any]:
        if (
            type(_token_slot) is not list
            or len(_token_slot) != 1
            or list.__getitem__(_token_slot, 0) is not None
        ):
            raise EvidenceFailed(
                "selected fixture resource scope token slot is not empty"
            )
        thread_id = threading.get_ident()
        with scope_lock:
            if list.__getitem__(active_scope_slot, 0) is not None:
                raise EvidenceFailed(
                    "selected fixture resource scope is already active"
                )
        observed_snapshot = v2_exact_fixture_resource_paths_snapshot(
            observed_paths
        )
        access_snapshot = v2_exact_fixture_resource_paths_snapshot(
            access_paths
        )
        observed_keys = tuple(
            v2_fixture_selected_resource_path_key(path)
            for path in observed_snapshot
        )
        access_keys = tuple(
            v2_fixture_selected_resource_path_key(path)
            for path in access_snapshot
        )
        operation_grant_snapshot = (
            v2_exact_fixture_resource_operation_grants_snapshot(
                operation_grants
            )
        )
        if (
            len(observed_keys) != len(set(observed_keys))
            or len(access_keys) != len(set(access_keys))
            or not set(observed_keys).issubset(access_keys)
        ):
            raise EvidenceFailed(
                "selected fixture resource scope paths are duplicate or "
                "not fully state-bound"
            )
        access_key_set = set(access_keys)
        observed_key_set = set(observed_keys)
        grants: dict[str, frozenset[str] | None] = {}
        normalized_grants: list[tuple[str, tuple[str, ...] | None]] = []
        for operation, granted_paths in operation_grant_snapshot:
            if granted_paths is None:
                dict.__setitem__(grants, operation, None)
                list.append(normalized_grants, (operation, None))
                continue
            granted_keys = tuple(
                v2_fixture_selected_resource_path_key(path)
                for path in granted_paths
            )
            if (
                len(granted_keys) != len(set(granted_keys))
                or not set(granted_keys).issubset(access_key_set)
                or (
                    operation != "strict-read"
                    and not set(granted_keys).issubset(observed_key_set)
                )
            ):
                raise EvidenceFailed(
                    "selected fixture resource operation grant paths are "
                    "duplicate, unselected, or not state-bound"
                )
            dict.__setitem__(grants, operation, frozenset(granted_keys))
            list.append(normalized_grants, (operation, granted_keys))
        observed_bindings: dict[str, tuple[Any, ...]] = {}
        for path, path_key in zip(
            observed_snapshot,
            observed_keys,
            strict=True,
        ):
            captured_key, captured_binding = (
                v2_fixture_capture_anchored_resource_binding(path)
            )
            if captured_key != path_key:
                raise EvidenceFailed(
                    "selected fixture resource key changed while binding state"
                )
            dict.__setitem__(
                observed_bindings,
                path_key,
                captured_binding,
            )
        access_parent_bindings = {
            path_key: (
                dict.__getitem__(observed_bindings, path_key)[1]
                if path_key in observed_bindings
                else capture_lexical_parent_binding(path)
            )
            for path, path_key in zip(
                access_snapshot,
                access_keys,
                strict=True,
            )
        }
        lifecycle_slot = ["ACTIVE"]
        token: list[Any] = [
            thread_id,
            observed_keys,
            access_keys,
            tuple(normalized_grants),
            lifecycle_slot,
        ]
        scope_state = {
            "token": token,
            "owner_thread_id": thread_id,
            "lifecycle": "ACTIVE",
            "observed": observed_keys,
            "observed_bindings": observed_bindings,
            "access": access_keys,
            "access_parent_bindings": access_parent_bindings,
            "grants": grants,
            "operation_uses": 0,
            "owned_descriptors": [],
            "descriptor_reservations": [],
        }
        try:
            with scope_lock:
                if list.__getitem__(active_scope_slot, 0) is not None:
                    raise EvidenceFailed(
                        "selected fixture resource scope is already active"
                    )
                list.__setitem__(
                    active_scope_slot,
                    0,
                    scope_state,
                )
                list.__setitem__(_token_slot, 0, token)
            return token
        except BaseException:
            with scope_lock:
                if list.__getitem__(active_scope_slot, 0) is scope_state:
                    list.__setitem__(active_scope_slot, 0, None)
                if list.__getitem__(_token_slot, 0) is token:
                    list.__setitem__(_token_slot, 0, None)
            raise

    def leave(token: list[Any]) -> None:
        unique_descriptor_slots: list[list[int | None]] = []
        descriptor_reservations: tuple[list[int | None], ...] = ()
        first_close_error: BaseException | None = None

        def attempt_descriptor_slot_close(
            descriptor_slot: list[int | None],
        ) -> None:
            nonlocal first_close_error
            try:
                close_failure = v2_collect_owned_descriptor_slot_close_failure(
                    descriptor_slot,
                    EvidenceFailed(
                        "selected fixture resource owned-descriptor cleanup failed"
                    ),
                )
            except BaseException as error:
                if first_close_error is None:
                    first_close_error = error
            else:
                if close_failure is not None and first_close_error is None:
                    first_close_error = close_failure[1]

        with scope_lock:
            state = list.__getitem__(active_scope_slot, 0)
            if state is None:
                if (
                    type(token) is list
                    and list.__len__(token) == 5
                    and type(list.__getitem__(token, 4)) is list
                    and list.__len__(list.__getitem__(token, 4)) == 1
                    and list.__getitem__(list.__getitem__(token, 4), 0)
                    == "CLOSED"
                ):
                    return
                raise EvidenceFailed(
                    "selected fixture resource scope token is invalid"
                )
            if (
                type(token) is not list
                or dict.__getitem__(state, "token") is not token
                or dict.__getitem__(state, "lifecycle")
                not in {"ACTIVE", "CLOSING"}
            ):
                raise EvidenceFailed(
                    "selected fixture resource scope token is invalid"
                )
            lifecycle_slot = list.__getitem__(token, 4)
            if type(lifecycle_slot) is not list or list.__len__(lifecycle_slot) != 1:
                raise EvidenceFailed(
                    "selected fixture resource lifecycle token is invalid"
                )
            owned_descriptor_slots = tuple(
                dict.__getitem__(state, "owned_descriptors")
            )
            descriptor_reservations = tuple(
                dict.__getitem__(state, "descriptor_reservations")
            )
            for descriptor_slot in reversed(
                (*owned_descriptor_slots, *descriptor_reservations)
            ):
                if any(
                    descriptor_slot is seen_slot
                    for seen_slot in unique_descriptor_slots
                ):
                    continue
                list.append(unique_descriptor_slots, descriptor_slot)
            try:
                dict.__setitem__(state, "lifecycle", "CLOSING")
                list.__setitem__(lifecycle_slot, 0, "CLOSING")
                for descriptor_slot in unique_descriptor_slots:
                    attempt_descriptor_slot_close(descriptor_slot)
            finally:
                for descriptor_slot in unique_descriptor_slots:
                    if list.__getitem__(descriptor_slot, 0) is not None:
                        attempt_descriptor_slot_close(descriptor_slot)
                if all(
                    list.__getitem__(descriptor_slot, 0) is None
                    for descriptor_slot in unique_descriptor_slots
                ):
                    dict.__setitem__(state, "lifecycle", "CLOSED")
                    list.__setitem__(lifecycle_slot, 0, "CLOSED")
                    list.__setitem__(active_scope_slot, 0, None)
        if first_close_error is not None:
            raise EvidenceFailed(
                "selected fixture resource owned-descriptor cleanup failed"
            ) from first_close_error
        if descriptor_reservations:
            raise EvidenceFailed(
                "selected fixture resource descriptor reservation was not settled"
            )

    def require_active_state() -> dict[str, Any]:
        state = list.__getitem__(active_scope_slot, 0)
        if (
            state is None
            or dict.__getitem__(state, "lifecycle") != "ACTIVE"
            or dict.__getitem__(state, "owner_thread_id")
            != threading.get_ident()
        ):
            raise EvidenceFailed(
                "selected fixture resource access has no active scope"
            )
        return state

    def charge_operation_use(state: dict[str, Any]) -> None:
        operation_uses = dict.__getitem__(state, "operation_uses")
        if operation_uses >= V2_FIXTURE_RESOURCE_OPERATION_USES_CAP:
            raise EvidenceFailed(
                "selected fixture resource operation-use budget is exhausted"
            )
        dict.__setitem__(state, "operation_uses", operation_uses + 1)

    def require_path_operation(
        state: dict[str, Any],
        path_key: str,
        operation: str,
    ) -> None:
        charge_operation_use(state)
        grants = dict.__getitem__(state, "grants")
        if (
            operation not in grants
            or dict.__getitem__(grants, operation) is None
            or path_key not in dict.__getitem__(grants, operation)
        ):
            raise EvidenceFailed(
                "fixture callback used an unauthorized selected-resource "
                f"path-operation grant: {operation}:{path_key}"
            )

    def require_operation(operation: str) -> None:
        if (
            type(operation) is not str
            or operation not in V2_FIXTURE_SELECTED_RESOURCE_PATHLESS_OPERATIONS
        ):
            raise EvidenceFailed(
                "selected fixture resource pathless operation is malformed"
            )
        with scope_lock:
            state = require_active_state()
            charge_operation_use(state)
            grants = dict.__getitem__(state, "grants")
            if operation not in grants or dict.__getitem__(grants, operation) is not None:
                raise EvidenceFailed(
                    "fixture callback used an unauthorized selected-resource "
                    f"pathless operation: {operation}"
                )

    def require_observed(
        path: Path,
        operation: str,
    ) -> tuple[str, tuple[Any, ...]]:
        if (
            type(operation) is not str
            or operation not in V2_FIXTURE_SELECTED_RESOURCE_PATH_OPERATIONS
        ):
            raise EvidenceFailed(
                "selected fixture resource path operation is malformed"
            )
        path_key = v2_fixture_selected_resource_path_key(path)
        with scope_lock:
            state = require_active_state()
            require_path_operation(state, path_key, operation)
            if path_key not in dict.__getitem__(state, "observed"):
                raise EvidenceFailed(
                    "fixture callback accessed an unobserved resource path: "
                    f"{path_key}"
                )
            expected_binding = dict.__getitem__(
                dict.__getitem__(state, "observed_bindings"),
                path_key,
            )
        return path_key, expected_binding

    def require_access(
        path: Path,
        operation: str,
    ) -> tuple[
        str,
        tuple[Any, ...] | None,
        tuple[tuple[str, int, int, int], ...],
    ]:
        if (
            type(operation) is not str
            or operation not in V2_FIXTURE_SELECTED_RESOURCE_PATH_OPERATIONS
        ):
            raise EvidenceFailed(
                "selected fixture resource path operation is malformed"
            )
        path_key = v2_fixture_selected_resource_path_key(path)
        with scope_lock:
            state = require_active_state()
            require_path_operation(state, path_key, operation)
            if path_key not in dict.__getitem__(state, "access"):
                raise EvidenceFailed(
                    "fixture callback accessed an unselected resource path: "
                    f"{path_key}"
                )
            expected_binding = dict.get(
                dict.__getitem__(state, "observed_bindings"),
                path_key,
            )
            expected_parents = dict.__getitem__(
                dict.__getitem__(state, "access_parent_bindings"),
                path_key,
            )
        return path_key, expected_binding, expected_parents

    def reserve_owned_descriptor(
        *,
        _reservation_slot: list[Any],
    ) -> list[Any]:
        if (
            type(_reservation_slot) is not list
            or len(_reservation_slot) != 1
            or list.__getitem__(_reservation_slot, 0) is not None
        ):
            raise EvidenceFailed(
                "selected fixture descriptor reservation slot is not empty"
            )
        reservation: list[Any] = [None]
        with scope_lock:
            state = require_active_state()
            owned_descriptors = dict.__getitem__(
                state,
                "owned_descriptors",
            )
            reservations = dict.__getitem__(
                state,
                "descriptor_reservations",
            )
            if (
                len(owned_descriptors) + len(reservations)
                >= V2_FIXTURE_RESOURCE_OWNED_DESCRIPTORS_CAP
            ):
                raise EvidenceFailed(
                    "selected fixture resource owned-descriptor budget is "
                    "exhausted"
                )
            list.append(reservations, reservation); list.__setitem__(_reservation_slot, 0, reservation)
        try:
            return reservation
        except BaseException:
            with scope_lock:
                state = list.__getitem__(active_scope_slot, 0)
                if (
                    state is not None
                    and dict.__getitem__(state, "owner_thread_id")
                    == threading.get_ident()
                ):
                    reservations = dict.__getitem__(
                        state,
                        "descriptor_reservations",
                    )
                    reservation_index = find_reservation_index(
                        reservations,
                        reservation,
                    )
                    if reservation_index is not None:
                        list.pop(reservations, reservation_index)
                if list.__getitem__(_reservation_slot, 0) is reservation:
                    list.__setitem__(_reservation_slot, 0, None)
            raise

    def find_reservation_index(
        reservations: list[list[Any]],
        reservation: list[Any],
    ) -> int | None:
        return next(
            (
                index
                for index in range(len(reservations))
                if list.__getitem__(reservations, index) is reservation
            ),
            None,
        )

    def register_owned_descriptor(
        reservation: list[Any],
    ) -> int:
        descriptor = (
            list.__getitem__(reservation, 0)
            if type(reservation) is list and len(reservation) == 1
            else None
        )
        if type(descriptor) is not int or descriptor < 0:
            raise EvidenceFailed(
                "selected fixture resource descriptor is not exact"
            )
        with scope_lock:
            state = require_active_state()
            reservations = dict.__getitem__(
                state,
                "descriptor_reservations",
            )
            reservation_index = (
                find_reservation_index(reservations, reservation)
                if type(reservation) is list
                else None
            )
            if reservation_index is None:
                raise EvidenceFailed(
                    "selected fixture resource descriptor reservation is "
                    "invalid"
                )
            owned_descriptors = dict.__getitem__(
                state,
                "owned_descriptors",
            )
            if any(
                type(owned_slot) is list
                and len(owned_slot) == 1
                and list.__getitem__(owned_slot, 0) == descriptor
                for owned_slot in owned_descriptors
            ):
                raise EvidenceFailed(
                    "selected fixture resource descriptor is already owned"
                )
            # Append the same owning slot before removing its reservation.  A
            # line-trace interruption can therefore make the slot temporarily
            # visible in both collections, but never in neither collection.
            list.append(owned_descriptors, reservation)
            list.pop(reservations, reservation_index)
        return descriptor

    def cancel_owned_descriptor_reservation(
        reservation: list[Any],
    ) -> None:
        with scope_lock:
            state = require_active_state()
            reservations = dict.__getitem__(
                state,
                "descriptor_reservations",
            )
            reservation_index = (
                find_reservation_index(reservations, reservation)
                if type(reservation) is list
                else None
            )
            if reservation_index is None:
                raise EvidenceFailed(
                    "selected fixture resource descriptor reservation is "
                    "invalid"
                )
            close_failure = v2_collect_owned_descriptor_slot_close_failure(
                reservation,
                EvidenceFailed(
                    "selected fixture resource reserved-descriptor cleanup "
                    "failed"
                ),
            )
            list.pop(reservations, reservation_index)
        v2_raise_descriptor_close_failure(close_failure)

    def pristine() -> bool:
        with scope_lock:
            return list.__getitem__(active_scope_slot, 0) is None

    return (
        enter,
        leave,
        require_observed,
        require_access,
        require_operation,
        reserve_owned_descriptor,
        register_owned_descriptor,
        cancel_owned_descriptor_reservation,
        pristine,
    )


(
    v2_fixture_selected_resource_scope_enter,
    v2_fixture_selected_resource_scope_leave,
    v2_fixture_require_observed_resource_path,
    v2_fixture_require_selected_resource_path,
    v2_fixture_require_selected_resource_operation,
    v2_fixture_reserve_selected_owned_descriptor,
    v2_fixture_register_selected_owned_descriptor,
    v2_fixture_cancel_selected_owned_descriptor_reservation,
    v2_fixture_selected_resource_scope_is_pristine,
) = _v2_build_fixture_selected_resource_scope()
V2_FIXTURE_SELECTED_RESOURCE_SCOPE_BOUNDARIES = (
    ("enter", v2_fixture_selected_resource_scope_enter),
    ("leave", v2_fixture_selected_resource_scope_leave),
    ("require-observed", v2_fixture_require_observed_resource_path),
    ("require-access", v2_fixture_require_selected_resource_path),
    ("require-operation", v2_fixture_require_selected_resource_operation),
    ("reserve-owned-descriptor", v2_fixture_reserve_selected_owned_descriptor),
    ("register-owned-descriptor", v2_fixture_register_selected_owned_descriptor),
    (
        "cancel-owned-descriptor-reservation",
        v2_fixture_cancel_selected_owned_descriptor_reservation,
    ),
    ("pristine", v2_fixture_selected_resource_scope_is_pristine),
)


def v2_fixture_selected_resource_scope_boundary_role(
    value: Any,
) -> str | None:
    return next(
        (
            role
            for role, candidate
            in V2_FIXTURE_SELECTED_RESOURCE_SCOPE_BOUNDARIES
            if value is candidate
        ),
        None,
    )


def v2_fixture_stat_identity_tuple(value: Any) -> tuple[int, ...]:
    if type(value) is not os.stat_result:
        raise EvidenceFailed(
            "selected fixture resource metadata result is not exact"
        )
    return (
        value.st_dev,
        value.st_ino,
        value.st_mode,
        value.st_nlink,
        value.st_size,
        value.st_mtime_ns,
        value.st_ctime_ns,
    )


def v2_fixture_require_bound_stat_identity(
    value: Any,
    expected_identity: tuple[int, ...],
) -> None:
    if (
        type(expected_identity) is not tuple
        or len(expected_identity) != 7
        or any(type(item) is not int for item in expected_identity)
    ):
        raise EvidenceFailed(
            "selected fixture resource bound identity is malformed"
        )
    if v2_fixture_stat_identity_tuple(value) != expected_identity:
        raise EvidenceFailed(
            "selected fixture resource changed after state capture"
        )


def v2_fixture_require_bound_resource_binding(
    binding: tuple[Any, ...],
) -> tuple[tuple[int, ...], tuple[tuple[str, int, int, int], ...]]:
    if (
        type(binding) is not tuple
        or len(binding) != 2
        or type(binding[0]) is not tuple
        or type(binding[1]) is not tuple
    ):
        raise EvidenceFailed(
            "selected fixture resource binding is malformed"
        )
    leaf_identity = binding[0]
    parent_identities = binding[1]
    if (
        len(leaf_identity) != 7
        or any(type(item) is not int for item in leaf_identity)
        or not parent_identities
        or any(
            type(row) is not tuple
            or len(row) != 4
            or type(row[0]) is not str
            or any(type(item) is not int for item in row[1:])
            for row in parent_identities
        )
    ):
        raise EvidenceFailed(
            "selected fixture resource binding is malformed"
        )
    return leaf_identity, parent_identities


def _v2_fixture_open_anchored_parent_owned(
    relative: str,
    expected_parents: tuple[tuple[str, int, int, int], ...],
    descriptor_slot: list[int | None],
    child_slot: list[int | None],
) -> str | None:
    if type(relative) is not str or not relative:
        raise EvidenceFailed(
            "selected fixture resource relative path is not exact"
        )
    relative_path = PurePosixPath(relative)
    if len(expected_parents) != len(relative_path.parts[:-1]) + 1:
        raise EvidenceFailed(
            "selected fixture resource parent binding has the wrong depth"
        )
    if (
        type(descriptor_slot) is not list
        or len(descriptor_slot) != 1
        or list.__getitem__(descriptor_slot, 0) is not None
    ):
        raise EvidenceFailed(
            "selected fixture resource parent descriptor slot is not empty"
        )
    directory_flags = (
        os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW
    )
    try:
        list.__setitem__(descriptor_slot, 0, os.open(REPO_ROOT, directory_flags))
    except OSError as error:
        raise EvidenceFailed(
            "selected fixture repository root cannot be opened safely"
        ) from error
    try:
        current_descriptor = list.__getitem__(descriptor_slot, 0)
        if current_descriptor is None:
            raise EvidenceFailed(
                "selected fixture repository root descriptor ownership was lost"
            )
        root_state = os.fstat(current_descriptor)
        if (
            not expected_parents
            or expected_parents[0]
            != (
                ".",
                root_state.st_dev,
                root_state.st_ino,
                stat.S_IFMT(root_state.st_mode),
            )
        ):
            raise EvidenceFailed(
                "selected fixture repository root changed after state capture"
            )
        if relative == ".":
            return None
        for expected_index, part in enumerate(
            relative_path.parts[:-1],
            1,
        ):
            current_descriptor = list.__getitem__(descriptor_slot, 0)
            if current_descriptor is None:
                raise EvidenceFailed(
                    "selected fixture resource parent descriptor ownership was "
                    "lost"
                )
            try:
                list.__setitem__(child_slot, 0, os.open(part, directory_flags, dir_fd=current_descriptor))
            except OSError as error:
                raise EvidenceFailed(
                    "selected fixture resource parent cannot be opened safely"
                ) from error
            try:
                child_descriptor = list.__getitem__(child_slot, 0)
                if child_descriptor is None:
                    raise EvidenceFailed(
                        "selected fixture resource child descriptor ownership "
                        "was lost"
                    )
                child_state = os.fstat(child_descriptor)
                if not stat.S_ISDIR(child_state.st_mode):
                    raise EvidenceFailed(
                        "selected fixture resource parent is not a directory"
                    )
                expected_row = (
                    "/".join(relative_path.parts[:expected_index]),
                    child_state.st_dev,
                    child_state.st_ino,
                    stat.S_IFMT(child_state.st_mode),
                )
                if (
                    expected_index >= len(expected_parents)
                    or expected_parents[expected_index] != expected_row
                ):
                    raise EvidenceFailed(
                        "selected fixture resource parent changed after state "
                        "capture"
                    )
            except OSError as error:
                v2_collect_owned_descriptor_slot_close_failure(
                    child_slot,
                    EvidenceFailed(
                        "selected fixture resource child descriptor close "
                        "failed"
                    ),
                )
                raise EvidenceFailed(
                    "selected fixture resource parent metadata cannot be "
                    "read safely"
                ) from error
            except BaseException:
                v2_collect_owned_descriptor_slot_close_failure(
                    child_slot,
                    EvidenceFailed(
                        "selected fixture resource child descriptor close "
                        "failed"
                    ),
                )
                raise
            close_failure = (
                v2_collect_owned_descriptor_slot_close_failure(
                    descriptor_slot,
                    EvidenceFailed(
                        "selected fixture resource parent descriptor close "
                        "failed"
                    ),
                )
            )
            if close_failure is not None:
                v2_collect_owned_descriptor_slot_close_failure(
                    child_slot,
                    EvidenceFailed(
                        "selected fixture resource child descriptor close "
                        "failed"
                    ),
                )
                v2_raise_descriptor_close_failure(close_failure)
            v2_transfer_owned_descriptor_slot(
                child_slot,
                descriptor_slot,
            )
        if list.__getitem__(descriptor_slot, 0) is None:
            raise EvidenceFailed(
                "selected fixture resource parent descriptor ownership was lost"
            )
        return relative_path.parts[-1]
    except OSError as error:
        v2_close_owned_descriptor_slots((
            (
                child_slot,
                EvidenceFailed(
                    "selected fixture resource child descriptor close failed"
                ),
            ),
            (
                descriptor_slot,
                EvidenceFailed(
                    "selected fixture repository root descriptor close failed"
                ),
            ),
        ), surface_failure=False)
        raise EvidenceFailed(
            "selected fixture repository root metadata cannot be read safely"
        ) from error
    except BaseException:
        v2_close_owned_descriptor_slots((
            (
                child_slot,
                EvidenceFailed(
                    "selected fixture resource child descriptor close failed"
                ),
            ),
            (
                descriptor_slot,
                EvidenceFailed(
                    "selected fixture resource parent descriptor close failed"
                ),
            ),
        ), surface_failure=False)
        raise


def v2_fixture_open_anchored_parent(
    relative: str,
    expected_parents: tuple[tuple[str, int, int, int], ...],
    descriptor_slot: list[int | None],
) -> str | None:
    if (
        type(descriptor_slot) is not list
        or len(descriptor_slot) != 1
        or list.__getitem__(descriptor_slot, 0) is not None
    ):
        raise EvidenceFailed(
            "selected fixture resource parent descriptor slot is not empty"
        )
    child_slot: list[int | None] = [None]
    try:
        return _v2_fixture_open_anchored_parent_owned(
            relative,
            expected_parents,
            descriptor_slot,
            child_slot,
        )
    except BaseException:
        v2_close_owned_descriptor_slots((
            (
                child_slot,
                EvidenceFailed(
                    "selected fixture resource child descriptor close failed"
                ),
            ),
            (
                descriptor_slot,
                EvidenceFailed(
                    "selected fixture resource parent descriptor close failed"
                ),
            ),
        ), surface_failure=False)
        raise


def _v2_fixture_refuse_access_only_strict_read_owned(
    relative: str,
    expected_parents: tuple[tuple[str, int, int, int], ...],
    current_slot: list[int | None],
    child_slot: list[int | None],
) -> None:
    """Probe only lexical parents; never open or read the unbound leaf."""
    if type(relative) is not str or not relative:
        raise EvidenceFailed(
            "selected fixture access-only relative path is not exact"
        )
    relative_path = PurePosixPath(relative)
    maximum_parent_rows = len(relative_path.parts[:-1]) + 1
    if (
        type(expected_parents) is not tuple
        or not expected_parents
        or len(expected_parents) > maximum_parent_rows
        or any(
            type(row) is not tuple
            or len(row) != 4
            or type(row[0]) is not str
            or any(type(item) is not int for item in row[1:])
            for row in expected_parents
        )
    ):
        raise EvidenceFailed(
            "selected fixture access-only parent binding is malformed"
        )
    directory_flags = (
        os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW
    )
    try:
        list.__setitem__(current_slot, 0, os.open(REPO_ROOT, directory_flags))
    except OSError as error:
        raise InputRefused(
            "bounded input path component cannot be opened safely"
        ) from error
    primary_failure = True
    try:
        current_descriptor = list.__getitem__(current_slot, 0)
        if current_descriptor is None:
            raise InputRefused(
                "bounded input path component descriptor ownership was lost"
            )
        root_state = os.fstat(current_descriptor)
        if expected_parents[0] != (
            ".",
            root_state.st_dev,
            root_state.st_ino,
            stat.S_IFMT(root_state.st_mode),
        ):
            raise InputRefused(
                "bounded input path component changed before refusal"
            )
        for expected_index, component in enumerate(
            relative_path.parts[:-1],
            1,
        ):
            current_descriptor = list.__getitem__(current_slot, 0)
            if current_descriptor is None:
                raise InputRefused(
                    "bounded input path component descriptor ownership was lost"
                )
            if expected_index >= len(expected_parents):
                raise InputRefused(
                    "bounded input path component is not state-bound"
                )
            if expected_parents[expected_index][3] != stat.S_IFDIR:
                raise InputRefused(
                    "bounded input path component cannot be opened safely"
                )
            try:
                list.__setitem__(child_slot, 0, os.open(component, directory_flags, dir_fd=current_descriptor))
            except OSError as error:
                raise InputRefused(
                    "bounded input path component cannot be opened safely"
                ) from error
            try:
                child_descriptor = list.__getitem__(child_slot, 0)
                if child_descriptor is None:
                    raise InputRefused(
                        "bounded input path component child descriptor "
                        "ownership was lost"
                    )
                child_state = os.fstat(child_descriptor)
                expected_row = (
                    "/".join(relative_path.parts[:expected_index]),
                    child_state.st_dev,
                    child_state.st_ino,
                    stat.S_IFMT(child_state.st_mode),
                )
                if expected_parents[expected_index] != expected_row:
                    raise InputRefused(
                        "bounded input path component changed before refusal"
                    )
            except BaseException:
                v2_collect_owned_descriptor_slot_close_failure(
                    child_slot,
                    EvidenceFailed(
                        "selected fixture access-only child descriptor close "
                        "failed"
                    ),
                )
                raise
            close_failure = (
                v2_collect_owned_descriptor_slot_close_failure(
                    current_slot,
                    EvidenceFailed(
                        "selected fixture access-only parent descriptor close "
                        "failed"
                    ),
                )
            )
            if close_failure is not None:
                v2_collect_owned_descriptor_slot_close_failure(
                    child_slot,
                    EvidenceFailed(
                        "selected fixture access-only child descriptor close "
                        "failed"
                    ),
                )
                v2_raise_descriptor_close_failure(close_failure)
            v2_transfer_owned_descriptor_slot(
                child_slot,
                current_slot,
            )
        raise InputRefused(
            "access-only selected fixture strict read was refused before leaf "
            "open"
        )
    except OSError as error:
        raise InputRefused(
            "bounded input path component cannot be opened safely"
        ) from error
    finally:
        v2_close_owned_descriptor_slots((
            (
                child_slot,
                EvidenceFailed(
                    "selected fixture access-only child descriptor close failed"
                ),
            ),
            (
                current_slot,
                EvidenceFailed(
                    "selected fixture access-only parent descriptor close failed"
                ),
            ),
        ), surface_failure=not primary_failure)


def v2_fixture_refuse_access_only_strict_read(
    relative: str,
    expected_parents: tuple[tuple[str, int, int, int], ...],
) -> None:
    current_slot: list[int | None] = [None]
    child_slot: list[int | None] = [None]
    try:
        _v2_fixture_refuse_access_only_strict_read_owned(
            relative,
            expected_parents,
            current_slot,
            child_slot,
        )
    except BaseException:
        v2_close_owned_descriptor_slots((
            (
                child_slot,
                EvidenceFailed(
                    "selected fixture access-only child descriptor close failed"
                ),
            ),
            (
                current_slot,
                EvidenceFailed(
                    "selected fixture access-only parent descriptor close failed"
                ),
            ),
        ), surface_failure=False)
        raise


def v2_fixture_selected_lstat_anchored(
    relative: str,
    expected_binding: tuple[Any, ...],
) -> Any:
    expected_identity, expected_parents = (
        v2_fixture_require_bound_resource_binding(expected_binding)
    )
    parent_slot: list[int | None] = [None]
    operation_succeeded = False
    try:
        leaf = v2_fixture_open_anchored_parent(
            relative,
            expected_parents,
            parent_slot,
        )
        parent_descriptor = list.__getitem__(parent_slot, 0)
        if parent_descriptor is None:
            raise EvidenceFailed(
                "selected fixture resource parent descriptor ownership was lost"
            )
        state = (
            os.fstat(parent_descriptor)
            if leaf is None
            else os.stat(
                leaf,
                dir_fd=parent_descriptor,
                follow_symlinks=False,
            )
        )
        v2_fixture_require_bound_stat_identity(state, expected_identity)
        operation_succeeded = True
        return state
    except OSError as error:
        raise EvidenceFailed(
            "selected fixture resource metadata cannot be read safely"
        ) from error
    finally:
        v2_close_owned_descriptor_slots((
            (
                parent_slot,
                EvidenceFailed(
                    "selected fixture resource parent descriptor close failed"
                ),
            ),
        ), surface_failure=operation_succeeded)


def v2_fixture_open_anchored_read_descriptor(
    relative: str,
    expected_binding: tuple[Any, ...],
    descriptor_slot: list[int | None],
) -> None:
    if (
        type(descriptor_slot) is not list
        or len(descriptor_slot) != 1
        or list.__getitem__(descriptor_slot, 0) is not None
    ):
        raise EvidenceFailed(
            "selected fixture read descriptor slot is not empty"
        )
    expected_identity, expected_parents = (
        v2_fixture_require_bound_resource_binding(expected_binding)
    )
    parent_slot: list[int | None] = [None]
    try:
        leaf = v2_fixture_open_anchored_parent(
            relative,
            expected_parents,
            parent_slot,
        )
        parent_descriptor = list.__getitem__(parent_slot, 0)
        if parent_descriptor is None:
            raise EvidenceFailed(
                "selected fixture resource parent descriptor ownership was lost"
            )
        if leaf is None:
            raise EvidenceFailed(
                "selected fixture read descriptor requires a regular file"
            )
        read_flags = os.O_RDONLY | os.O_CLOEXEC | os.O_NONBLOCK | os.O_NOFOLLOW
        list.__setitem__(descriptor_slot, 0, os.open(leaf, read_flags, dir_fd=parent_descriptor))
        descriptor = list.__getitem__(descriptor_slot, 0)
        if descriptor is None:
            raise EvidenceFailed(
                "selected fixture read descriptor ownership was lost"
            )
        descriptor_state = os.fstat(descriptor)
        entry_state = os.stat(
            leaf,
            dir_fd=parent_descriptor,
            follow_symlinks=False,
        )
        if (
            not stat.S_ISREG(descriptor_state.st_mode)
            or descriptor_state.st_nlink != 1
            or descriptor_state.st_dev != entry_state.st_dev
            or descriptor_state.st_ino != entry_state.st_ino
            or stat.S_IFMT(descriptor_state.st_mode)
            != stat.S_IFMT(entry_state.st_mode)
        ):
            raise EvidenceFailed(
                "selected fixture read descriptor is not one exact regular file"
            )
        v2_fixture_require_bound_stat_identity(
            descriptor_state,
            expected_identity,
        )
    except HarnessError:
        v2_close_owned_descriptor_slots((
            (
                descriptor_slot,
                EvidenceFailed(
                    "selected fixture read descriptor close failed"
                ),
            ),
            (
                parent_slot,
                EvidenceFailed(
                    "selected fixture resource parent descriptor close failed"
                ),
            ),
        ), surface_failure=False)
        raise
    except OSError as error:
        v2_close_owned_descriptor_slots((
            (
                descriptor_slot,
                EvidenceFailed(
                    "selected fixture read descriptor close failed"
                ),
            ),
            (
                parent_slot,
                EvidenceFailed(
                    "selected fixture resource parent descriptor close failed"
                ),
            ),
        ), surface_failure=False)
        raise EvidenceFailed(
            "selected fixture read descriptor cannot be opened safely"
        ) from error
    except BaseException:
        v2_close_owned_descriptor_slots((
            (
                descriptor_slot,
                EvidenceFailed(
                    "selected fixture read descriptor close failed"
                ),
            ),
            (
                parent_slot,
                EvidenceFailed(
                    "selected fixture resource parent descriptor close failed"
                ),
            ),
        ), surface_failure=False)
        raise
    if list.__getitem__(descriptor_slot, 0) is None:
        v2_collect_owned_descriptor_slot_close_failure(
            parent_slot,
            EvidenceFailed(
                "selected fixture resource parent descriptor close failed"
            ),
        )
        raise EvidenceFailed(
            "selected fixture read descriptor was not opened"
        )
    parent_close_failure = (
        v2_collect_owned_descriptor_slot_close_failure(
            parent_slot,
            EvidenceFailed(
                "selected fixture resource parent descriptor close failed"
            ),
        )
    )
    if parent_close_failure is not None:
        v2_collect_owned_descriptor_slot_close_failure(
            descriptor_slot,
            EvidenceFailed(
                "selected fixture read descriptor close failed"
            ),
        )
        v2_raise_descriptor_close_failure(parent_close_failure)


def _v2_fixture_open_anchored_directory_descriptor_owned(
    relative: str,
    expected_binding: tuple[Any, ...],
    descriptor_slot: list[int | None],
    child_slot: list[int | None],
) -> None:
    if (
        type(descriptor_slot) is not list
        or len(descriptor_slot) != 1
        or list.__getitem__(descriptor_slot, 0) is not None
    ):
        raise EvidenceFailed(
            "selected fixture cwd descriptor slot is not empty"
        )
    expected_identity, expected_parents = (
        v2_fixture_require_bound_resource_binding(expected_binding)
    )
    try:
        leaf = v2_fixture_open_anchored_parent(
            relative,
            expected_parents,
            descriptor_slot,
        )
    except BaseException:
        v2_collect_owned_descriptor_slot_close_failure(
            descriptor_slot,
            EvidenceFailed(
                "selected fixture cwd descriptor close failed"
            ),
        )
        raise
    if leaf is None:
        try:
            parent_descriptor = list.__getitem__(descriptor_slot, 0)
            if parent_descriptor is None:
                raise EvidenceFailed(
                    "selected fixture cwd descriptor ownership was lost"
                )
            root_state = os.fstat(parent_descriptor)
            v2_fixture_require_bound_stat_identity(
                root_state,
                expected_identity,
            )
        except OSError as error:
            v2_collect_owned_descriptor_slot_close_failure(
                descriptor_slot,
                EvidenceFailed(
                    "selected fixture cwd descriptor close failed"
                ),
            )
            raise EvidenceFailed(
                "selected fixture cwd target cannot be opened safely"
            ) from error
        except BaseException:
            v2_collect_owned_descriptor_slot_close_failure(
                descriptor_slot,
                EvidenceFailed(
                    "selected fixture cwd descriptor close failed"
                ),
            )
            raise
        return
    try:
        parent_descriptor = list.__getitem__(descriptor_slot, 0)
        if parent_descriptor is None:
            raise EvidenceFailed(
                "selected fixture resource parent descriptor ownership was lost"
            )
        directory_leaf_flags = (
            os.O_RDONLY | os.O_DIRECTORY | os.O_CLOEXEC | os.O_NOFOLLOW
        )
        list.__setitem__(child_slot, 0, os.open(leaf, directory_leaf_flags, dir_fd=parent_descriptor))
        descriptor = list.__getitem__(child_slot, 0)
        if descriptor is None:
            raise EvidenceFailed(
                "selected fixture cwd descriptor ownership was lost"
            )
        descriptor_state = os.fstat(descriptor)
        if not stat.S_ISDIR(descriptor_state.st_mode):
            raise EvidenceFailed(
                "selected fixture cwd target is not a directory"
            )
        v2_fixture_require_bound_stat_identity(
            descriptor_state,
            expected_identity,
        )
    except HarnessError:
        v2_close_owned_descriptor_slots((
            (
                child_slot,
                EvidenceFailed(
                    "selected fixture cwd descriptor close failed"
                ),
            ),
            (
                descriptor_slot,
                EvidenceFailed(
                    "selected fixture resource parent descriptor close failed"
                ),
            ),
        ), surface_failure=False)
        raise
    except OSError as error:
        v2_close_owned_descriptor_slots((
            (
                child_slot,
                EvidenceFailed(
                    "selected fixture cwd descriptor close failed"
                ),
            ),
            (
                descriptor_slot,
                EvidenceFailed(
                    "selected fixture resource parent descriptor close failed"
                ),
            ),
        ), surface_failure=False)
        raise EvidenceFailed(
            "selected fixture cwd target cannot be opened safely"
        ) from error
    except BaseException:
        v2_close_owned_descriptor_slots((
            (
                child_slot,
                EvidenceFailed(
                    "selected fixture cwd descriptor close failed"
                ),
            ),
            (
                descriptor_slot,
                EvidenceFailed(
                    "selected fixture resource parent descriptor close failed"
                ),
            ),
        ), surface_failure=False)
        raise
    if list.__getitem__(child_slot, 0) is None:
        v2_collect_owned_descriptor_slot_close_failure(
            descriptor_slot,
            EvidenceFailed(
                "selected fixture resource parent descriptor close failed"
            ),
        )
        raise EvidenceFailed("selected fixture cwd descriptor was not opened")
    parent_close_failure = (
        v2_collect_owned_descriptor_slot_close_failure(
            descriptor_slot,
            EvidenceFailed(
                "selected fixture resource parent descriptor close failed"
            ),
        )
    )
    if parent_close_failure is not None:
        v2_collect_owned_descriptor_slot_close_failure(
            child_slot,
            EvidenceFailed(
                "selected fixture cwd descriptor close failed"
            ),
        )
        v2_raise_descriptor_close_failure(parent_close_failure)
    v2_transfer_owned_descriptor_slot(
        child_slot,
        descriptor_slot,
    )


def v2_fixture_open_anchored_directory_descriptor(
    relative: str,
    expected_binding: tuple[Any, ...],
