def v2_fixture_read_selected_repo_relative_file_strict(
    path: Path,
    *,
    label: str,
    cap: int = CAPS["input_artifact_bytes"],
) -> bytes:
    if type(label) is not str or not label:
        raise EvidenceFailed("selected fixture strict-read label is not exact")
    if type(cap) is not int or cap < 0:
        raise EvidenceFailed("selected fixture strict-read cap is not exact")
    (
        relative,
        expected_binding,
        expected_access_parents,
    ) = v2_fixture_require_selected_resource_path(path, "strict-read")
    expected_identity: tuple[int, ...] | None = None
    expected_parents: tuple[tuple[str, int, int, int], ...] | None = None
    if expected_binding is not None:
        expected_identity, expected_parents = (
            v2_fixture_require_bound_resource_binding(expected_binding)
        )
        v2_fixture_selected_lstat_anchored(
            relative,
            expected_binding,
        )
    if expected_binding is None:
        v2_fixture_refuse_access_only_strict_read(
            relative,
            expected_access_parents,
        )
        raise EvidenceFailed(
            "access-only selected fixture strict-read refusal returned"
        )
    payload = v2_read_repo_relative_file_strict(
        relative,
        label=label,
        cap=cap,
        _expected_identity=expected_identity,
        _expected_parent_identities=expected_parents,
    )
    return payload


def v2_fixture_require_selected_fresh_run_dir(
