def v2_fixture_open_selected_read_descriptor(path: Path) -> int:
    relative, expected_binding = v2_fixture_require_observed_resource_path(
        path,
        "open-read-descriptor",
    )
    reservation_slot: list[Any] = [None]
    reservation: list[Any] | None = None
    reservation_settled = False
    try:
        reservation = v2_fixture_reserve_selected_owned_descriptor(
            _reservation_slot=reservation_slot,
        )
        v2_fixture_open_anchored_read_descriptor(
            relative,
            expected_binding,
            reservation,
        )
        descriptor = v2_fixture_register_selected_owned_descriptor(
            reservation
        )
        reservation_settled = True
        list.__setitem__(reservation_slot, 0, None)
    except BaseException:
        retained_reservation = list.__getitem__(reservation_slot, 0)
        if not reservation_settled and type(retained_reservation) is list:
            try:
                v2_fixture_cancel_selected_owned_descriptor_reservation(
                    retained_reservation
                )
                list.__setitem__(reservation_slot, 0, None)
            except BaseException:
                # Scope teardown remains authoritative for an unsettled
                # reservation; the active exception remains the immediate
                # operation failure.
                pass
        raise
    return descriptor


