def v2_fixture_set_process_environment_bytes(key: bytes, value: bytes) -> None:
    v2_fixture_require_selected_resource_operation(
        "process-environment-set"
    )
    if type(key) is not bytes or type(value) is not bytes:
        raise EvidenceFailed(
            "selected fixture environment key and value must be exact bytes"
        )
    if (
        not key
        or b"=" in key
        or b"\0" in key
        or b"\0" in value
        or len(key) + len(value)
        > V2_FIXTURE_RESOURCE_ENVIRONMENT_BYTES_CAP
    ):
        raise EvidenceFailed(
            "selected fixture environment entry is malformed or over cap"
        )
    environment_before = v2_bounded_process_environment_bytes_snapshot()
    current_bytes = sum(
        len(current_key) + len(current_value)
        for current_key, current_value in dict.items(environment_before)
    )
    prior_value = dict.get(environment_before, key)
    projected_bytes = current_bytes + len(key) + len(value)
    if prior_value is not None:
        projected_bytes -= len(key) + len(prior_value)
    if (
        key not in environment_before
        and len(environment_before)
        >= V2_FIXTURE_RESOURCE_ENVIRONMENT_ENTRIES_CAP
        or projected_bytes > V2_FIXTURE_RESOURCE_ENVIRONMENT_BYTES_CAP
    ):
        raise EvidenceFailed(
            "selected fixture environment mutation exceeds its bounded cap"
        )
    try:
        os.environb[key] = value
    except (OSError, ValueError) as error:
        raise EvidenceFailed(
            "selected fixture environment mutation failed"
        ) from error


def v2_fixture_delete_process_environment_bytes(key: bytes) -> None:
    v2_fixture_require_selected_resource_operation(
        "process-environment-delete"
