        )
    if not key or b"=" in key or b"\0" in key:
        raise EvidenceFailed(
            "selected fixture environment key is malformed"
        )
    v2_bounded_process_environment_bytes_snapshot()
    try:
        del os.environb[key]
    except (KeyError, OSError, ValueError) as error:
        raise EvidenceFailed(
            "selected fixture environment deletion failed"
        ) from error


