def v2_fixture_executable_internal_capabilities(
    value: Any,
) -> frozenset[str]:
    return frozenset().union(*(
        capabilities
        for candidate, capabilities
        in V2_FIXTURE_EXECUTABLE_INTERNAL_CAPABILITIES
        if value is candidate
    ))


def v2_external_callable_capabilities(value: Any) -> frozenset[str]:
    return frozenset(
        capability
        for candidate, capability in V2_REFUSAL_EXTERNAL_CALLABLE_CAPABILITIES
        if value is candidate
    )


def v2_require_external_callable_authorized(
    value: Any,
    *,
    context: Mapping[str, Any],
    label: str,
) -> None:
    required = v2_external_callable_capabilities(value)
    if required and required.isdisjoint(
        context["authorized_external_capabilities"]
    ):
        raise EvidenceFailed(
            "refusal callback reaches external runtime state through "
            f"{label}; provide an explicit bounded projection for one of "
            f"{sorted(required)}"
        )


def v2_external_type_path_capabilities(
    value: Any,
    paths: Sequence[Sequence[str]] | None,
) -> frozenset[str]:
    if not paths:
        return frozenset()
    identity = next(
        (
            name
            for name, external_type in V2_REFUSAL_TRUSTED_TYPE_IDENTITIES
            if value is external_type
        ),
        None,
    )
    if identity is None:
        return frozenset()
    return frozenset(
        f"{identity}.{'.'.join(str(part) for part in path)}"
        for path in paths
        if path
        and str(path[0])
        in V2_REFUSAL_EXTERNAL_TYPE_PATHS.get(value, frozenset())
    )


def v2_external_module_value_path_capabilities(
    value: Any,
    paths: Sequence[Sequence[str]] | None,
) -> frozenset[str]:
    if value is not os or not paths:
        return frozenset()
    return frozenset(
        "process-python-environment"
        for path in paths
        if path and str(path[0]) in {"environ", "environb"}
    )


def v2_external_binding_path_capabilities(
    value: Any,
    paths: Sequence[Sequence[str]] | None,
) -> frozenset[str]:
    return frozenset({
        *v2_external_type_path_capabilities(value, paths),
        *v2_external_module_value_path_capabilities(value, paths),
    })


