def v2_harness_error_terminal(error_type: type[HarnessError]) -> str:
    if type(error_type) is not type:
        raise EvidenceFailed(
            "refusal expectation error type must use the exact type metaclass"
        )
    mro = v2_raw_type_mro(error_type)
    if HarnessError not in mro:
        raise EvidenceFailed(
            "refusal expectation error type is not a HarnessError subclass"
        )
    for owner in mro:
        owner_dictionary = v2_raw_type_dictionary(owner)
        if "terminal" not in owner_dictionary:
            continue
        terminal = owner_dictionary["terminal"]
        if (
            type(terminal) is not str
            or terminal == "Pass"
            or terminal not in TERMINAL_EXIT
        ):
            raise EvidenceFailed(
                "refusal expectation terminal is not a supported failure"
            )
        return terminal
    raise EvidenceFailed("refusal expectation error type lacks a terminal")


def v2_sealed_error_terminal(error: BaseException) -> str:
    """Resolve a caught error terminal without invoking instance hooks.

    Strict expectation validation remains in ``v2_harness_error_terminal``.
    This caught-error boundary instead fail-seals malformed or unknown class
    metadata as ``InternalFault`` so terminal publication cannot be lost to a
    secondary diagnostic exception.
    """
    error_type = type(error)
    if type(error_type) is not type:
        return "InternalFault"
    try:
        error_mro = v2_raw_type_mro(error_type)
        terminal = (
            v2_harness_error_terminal(error_type)
            if HarnessError in error_mro
            else "InternalFault"
        )
    except EvidenceFailed:
        return "InternalFault"
    if (
        type(terminal) is not str
        or terminal == "Pass"
        or terminal not in TERMINAL_EXIT
    ):
        return "InternalFault"
    return terminal


