V2_ATTRIBUTE_ACCESS_OPS = frozenset(
    {"LOAD_ATTR", "LOAD_METHOD"}
)
V2_FAST_LOCAL_LOAD_OPS = frozenset({
    "LOAD_FAST",
    "LOAD_FAST_AND_CLEAR",
    "LOAD_FAST_BORROW",
    "LOAD_FAST_CHECK",
    # Kept as a defensive spelling for bytecode metadata readers which expose
    # the compiler's maybe-null pseudo operation. Released CPython 3.11-3.14
    # emits LOAD_FAST_AND_CLEAR/LOAD_FAST_CHECK instead.
    "LOAD_FAST_MAYBE_NULL",
})
V2_FAST_LOCAL_MAYBE_UNBOUND_LOAD_OPS = frozenset({
    "LOAD_FAST_MAYBE_NULL",
})
V2_FAST_SUPERINSTRUCTION_EXPANSIONS = {
    "LOAD_FAST_LOAD_FAST": ("LOAD_FAST", "LOAD_FAST"),
    "LOAD_FAST_BORROW_LOAD_FAST_BORROW": (
        "LOAD_FAST_BORROW",
        "LOAD_FAST_BORROW",
    ),
    "STORE_FAST_LOAD_FAST": ("STORE_FAST", "LOAD_FAST"),
    "STORE_FAST_STORE_FAST": ("STORE_FAST", "STORE_FAST"),
}
V2_WITH_EXCEPT_START_EXIT_STACK_DEPTH = (
    5 if "LOAD_SPECIAL" in dis.opmap else 4
)


@dataclass(frozen=True)
class V2AnalysisInstruction:
    opname: str
    arg: int | None
    argval: Any
    argrepr: str
    positions: Any
    offset: int
    is_jump_target: bool


def v2_analysis_instructions(
    code: types.CodeType,
) -> list[V2AnalysisInstruction]:
    raw_instructions = list(dis.get_instructions(code))
    normalized: list[V2AnalysisInstruction] = []
    for index, instruction in enumerate(raw_instructions):
        expansion = V2_FAST_SUPERINSTRUCTION_EXPANSIONS.get(
            instruction.opname
        )
        if expansion is None:
            normalized.append(
                V2AnalysisInstruction(
                    instruction.opname,
                    instruction.arg,
                    instruction.argval,
                    instruction.argrepr,
                    instruction.positions,
                    instruction.offset,
                    instruction.is_jump_target,
                )
            )
            continue
        names = instruction.argval
        if (
            type(names) is not tuple
            or len(names) != len(expansion)
            or any(type(name) is not str for name in names)
        ):
            raise EvidenceFailed(
                "refusal-state fast superinstruction operands are not exact"
            )
        next_instruction = (
            raw_instructions[index + 1]
            if index + 1 < len(raw_instructions)
            else None
        )
        for component_index, (opname, name) in enumerate(
            zip(expansion, names, strict=True)
        ):
            positions = instruction.positions
            if (
                component_index == len(expansion) - 1
                and opname in {"LOAD_FAST", "LOAD_FAST_BORROW"}
                and next_instruction is not None
                and next_instruction.opname == "PUSH_NULL"
            ):
                # PEP 709 can fuse the loop-variable store with the callable
                # load while assigning the fused instruction the loop
                # variable's position. PUSH_NULL retains the callable token's
                # exact source span, which the call matcher needs.
                positions = next_instruction.positions
            normalized.append(
                V2AnalysisInstruction(
                    opname,
                    None,
                    name,
                    name,
                    positions,
                    instruction.offset,
                    instruction.is_jump_target and component_index == 0,
                )
            )
    return normalized


def v2_code_parameter_layout(
    code: types.CodeType,
) -> tuple[tuple[str, str], ...]:
    """Return exact parameter names and their zero-call binding classes."""
    if type(code) is not types.CodeType:
        raise EvidenceFailed("refusal-state parameter code is not exact")
    fixed_count = code.co_argcount + code.co_kwonlyargcount
    layout = [
        (
            name,
            "positional"
            if index < code.co_argcount
            else "keyword-only",
        )
        for index, name in enumerate(code.co_varnames[:fixed_count])
    ]
    next_index = fixed_count
    if code.co_flags & 0x04:  # CO_VARARGS
        if next_index >= len(code.co_varnames):
            raise EvidenceFailed("refusal-state variadic parameter is missing")
        list.append(layout, (code.co_varnames[next_index], "variadic"))
        next_index += 1
    if code.co_flags & 0x08:  # CO_VARKEYWORDS
        if next_index >= len(code.co_varnames):
            raise EvidenceFailed(
                "refusal-state keyword-variadic parameter is missing"
            )
        list.append(
            layout,
            (code.co_varnames[next_index], "keyword-variadic"),
        )
    if any(type(name) is not str for name, _kind in layout):
        raise EvidenceFailed("refusal-state parameter names are not exact")
    return tuple(layout)


def v2_code_parameter_names(code: types.CodeType) -> tuple[str, ...]:
    """Return positional, keyword-only, variadic, and keyword-variadic names."""
    return tuple(name for name, _kind in v2_code_parameter_layout(code))


def v2_instruction_access_path(
    instructions: Sequence[V2AnalysisInstruction],
    index: int,
) -> tuple[tuple[str, ...], int]:
    path: list[str] = []
    path_end = index
    for following_index in range(index + 1, len(instructions)):
        following = instructions[following_index]
        if following.opname not in V2_ATTRIBUTE_ACCESS_OPS:
            break
        if not isinstance(following.argval, str):
            break
        path.append(following.argval)
        path_end = following_index
    return tuple(path), path_end


def v2_access_has_direct_call_protocol(
    instructions: Sequence[V2AnalysisInstruction],
    source_index: int,
    path_end: int,
) -> bool:
    source = instructions[source_index]
    terminal = instructions[path_end]
    if any(
        instruction.opname in {"STORE_ATTR", "DELETE_ATTR"}
        for instruction in instructions[source_index + 1 : path_end + 1]
    ):
        return False
    if source.opname == "LOAD_GLOBAL" and "NULL" in source.argrepr:
        return True
    if terminal.opname == "LOAD_METHOD" or "NULL|self" in terminal.argrepr:
        return True
    if (
        sys.version_info < (3, 13)
        and source_index > 0
        and instructions[source_index - 1].opname == "PUSH_NULL"
    ):
        return True
    return (
        path_end + 1 < len(instructions)
        and instructions[path_end + 1].opname == "PUSH_NULL"
    )


def v2_matching_direct_call_index(
    instructions: Sequence[V2AnalysisInstruction],
    source_index: int,
    path_end: int,
) -> int | None:
    matches = v2_matching_direct_call_indices(
        instructions,
        source_index,
        path_end,
    )
    return matches[0] if matches else None


def v2_matching_direct_call_indices(
    instructions: Sequence[V2AnalysisInstruction],
    source_index: int,
    path_end: int,
) -> tuple[int, ...]:
    if not v2_access_has_direct_call_protocol(
        instructions,
        source_index,
        path_end,
    ):
        return ()
    return v2_matching_prepared_call_indices(instructions, path_end)


def v2_matching_prepared_call_index(
    instructions: Sequence[V2AnalysisInstruction],
    target_end: int,
) -> int | None:
    matches = v2_matching_prepared_call_indices(instructions, target_end)
    if not matches:
        raise EvidenceFailed(
            "refusal-state direct call cannot be bound to exact "
            "source-position metadata"
        )
    return matches[0]


def v2_matching_prepared_call_indices(
    instructions: Sequence[V2AnalysisInstruction],
    target_end: int,
) -> tuple[int, ...]:
    terminal_position = instructions[target_end].positions
    terminal_fields = (
        terminal_position.lineno,
        terminal_position.end_lineno,
        terminal_position.col_offset,
        terminal_position.end_col_offset,
    )
    if any(type(field) is not int for field in terminal_fields):
        raise EvidenceFailed(
            "refusal-state direct call lacks exact source-position metadata"
        )
    terminal_start = (
        terminal_position.lineno,
        terminal_position.col_offset,
    )
    terminal_stop = (
        terminal_position.end_lineno,
        terminal_position.end_col_offset,
    )
    matches: list[int] = []
    for index in range(target_end + 1, len(instructions)):
        instruction = instructions[index]
        if instruction.opname not in V2_CALL_OPS:
            continue
        call_position = instruction.positions
        call_fields = (
            call_position.lineno,
            call_position.end_lineno,
            call_position.col_offset,
            call_position.end_col_offset,
        )
        if any(type(field) is not int for field in call_fields):
            continue
        call_start = (
            call_position.lineno,
            call_position.col_offset,
        )
        call_stop = (
            call_position.end_lineno,
            call_position.end_col_offset,
        )
        if call_start <= terminal_start and terminal_stop <= call_stop:
            list.append(matches, index)
    return tuple(matches)


def v2_static_subscript_call(
    instructions: Sequence[V2AnalysisInstruction],
    path_start: int,
    path_end: int,
) -> tuple[Any, int] | None:
    key_index = path_end + 1
    subscript_index = path_end + 2
    if subscript_index >= len(instructions):
        return None
    key_instruction = instructions[key_index]
    if key_instruction.opname not in {"LOAD_CONST", "LOAD_SMALL_INT"}:
        return None
    key = key_instruction.argval
    if type(key) is not str and type(key) is not int:
        return None
    subscript = instructions[subscript_index]
    if not (
        subscript.opname == "BINARY_SUBSCR"
        or subscript.opname == "BINARY_OP" and subscript.argrepr == "[]"
    ):
        return None
    preceding_push_null = (
        path_start > 0
        and instructions[path_start - 1].opname == "PUSH_NULL"
    )
    following_index = subscript_index + 1
    following_push_null = (
        following_index < len(instructions)
        and instructions[following_index].opname == "PUSH_NULL"
    )
    direct_call_protocol = (
        (
            preceding_push_null
            or instructions[path_start].opname == "LOAD_GLOBAL"
            and "NULL" in instructions[path_start].argrepr
        )
        if sys.version_info < (3, 13)
        else following_push_null
    )
    if not direct_call_protocol:
        return None
    call_index = v2_matching_prepared_call_index(
        instructions,
        subscript_index,
    )
    return key, call_index


def v2_call_result_access_path(
    instructions: Sequence[V2AnalysisInstruction],
    call_index: int,
) -> tuple[str, ...]:
    path, _ = v2_instruction_access_path(instructions, call_index)
    if path:
        return path
    inner_position = instructions[call_index].positions
    inner_fields = (
        inner_position.lineno,
        inner_position.end_lineno,
        inner_position.col_offset,
        inner_position.end_col_offset,
    )
    if any(type(field) is not int for field in inner_fields):
        raise EvidenceFailed(
            "refusal-state call result lacks exact source-position metadata"
        )
    inner_start = (inner_position.lineno, inner_position.col_offset)
    inner_stop = (inner_position.end_lineno, inner_position.end_col_offset)
    for following in instructions[call_index + 1 :]:
        if following.opname not in V2_CALL_OPS:
            continue
        outer_position = following.positions
        outer_fields = (
            outer_position.lineno,
            outer_position.end_lineno,
            outer_position.col_offset,
            outer_position.end_col_offset,
        )
        if any(type(field) is not int for field in outer_fields):
            continue
        outer_start = (
            outer_position.lineno,
            outer_position.col_offset,
        )
        outer_stop = (
            outer_position.end_lineno,
            outer_position.end_col_offset,
        )
        if outer_start == inner_start and inner_stop < outer_stop:
            return V2_DIRECT_CALL_RESULT_PATH
    return path


V2_FAST_ORIGIN_UNKNOWN = ("unknown",)
V2_FAST_ORIGIN_STATIC = ("static",)
V2_FAST_ORIGIN_UNBOUND = ("unbound",)
V2_FAST_ORIGIN_NULL = ("null",)
V2_FAST_ORIGIN_RESOLUTION_CAP = 32
V2_SCALAR_PROTOCOL_RESULTS = frozenset({
    "abs",
    "all",
    "any",
    "ascii",
    "bin",
    "bool",
    "bytes",
    "chr",
    "complex",
    "float",
    "format",
    "hash",
    "hex",
    "int",
    "isinstance",
    "issubclass",
    "len",
    "oct",
    "ord",
    "pow",
    "repr",
    "round",
    "str",
    "type",
})
V2_SCALAR_MODULE_CALL_PATHS = frozenset({
    ("math", ("ceil",)),
    ("math", ("isfinite",)),
    ("str", ("startswith",)),
    ("stat", ("S_IFMT",)),
    ("stat", ("S_IMODE",)),
    ("stat", ("S_ISBLK",)),
    ("stat", ("S_ISCHR",)),
    ("stat", ("S_ISDIR",)),
    ("stat", ("S_ISFIFO",)),
    ("stat", ("S_ISLNK",)),
    ("stat", ("S_ISREG",)),
    ("stat", ("S_ISSOCK",)),
})


def v2_fast_audited_exact_json_result_kind(
    origin: tuple[Any, ...],
) -> str | None:
    """Return the unique detached-JSON result kind encoded in an origin."""
    if not (
        origin
        and origin[0] == "audited-exact-json"
        and len(origin) == 6
        and type(origin[1]) is str
        and origin[1]
        and origin[2] in {"exact-json-dict", "exact-json-list"}
        and type(origin[3]) is types.CodeType
        and type(origin[4]) is types.CodeType
        and type(origin[5]) is int
        and origin[5] >= 0
    ):
        return None
    return origin[2]


def v2_fast_origin_is_exact_json(
    origin: tuple[Any, ...],
    *,
    depth: int = 0,
) -> bool:
    """Recognize only recursively detached audited JSON provenance."""
    if depth > V2_REFUSAL_STATE_DEPTH_CAP or not origin:
        return False
    if v2_fast_audited_exact_json_result_kind(origin) is not None:
        return True
    kind = origin[0]
    if kind == "exact-json-member":
        return (
            len(origin) >= 2
            and type(origin[1]) is tuple
            and v2_fast_origin_is_exact_json(
                origin[1],
                depth=depth + 1,
            )
        )
    if kind == "choice":
        return bool(origin[1]) and all(
            v2_fast_origin_is_exact_json(
                option,
                depth=depth + 1,
            )
            for option in origin[1]
        )
    if kind == "derived" and origin[1] in {
        "GET_ITER",
        "GET_YIELD_FROM_ITER",
    }:
        return v2_fast_origin_is_exact_json(
            origin[2],
            depth=depth + 1,
        )
    if kind in {"iter-item", "unpack"}:
        return v2_fast_origin_is_exact_json(
            origin[1],
            depth=depth + 1,
        )
    return False


def v2_fast_origin_carries_exact_json_alias(
    origin: tuple[Any, ...],
    *,
    depth: int = 0,
    hazardous_allocation_sites: frozenset[tuple[Any, ...]] = frozenset(),
) -> bool:
    """Recognize values that can retain a detached exact-JSON alias."""
    if not origin:
        return False
    if depth > V2_REFUSAL_STATE_DEPTH_CAP:
        # This is a hazard predicate, not a proof predicate.  An origin that
        # exceeds the bounded walk must fail closed instead of laundering an
        # alias behind a deep chain of otherwise admissible wrappers.
        return True
    if v2_fast_origin_is_exact_json(origin, depth=depth):
        return True
    kind = origin[0]

    def nested_alias(part: Any) -> bool:
        if type(part) is not tuple or not part:
            return False
        if type(part[0]) is tuple:
            return any(
                v2_fast_origin_carries_exact_json_alias(
                    candidate,
                    depth=depth + 1,
                    hazardous_allocation_sites=hazardous_allocation_sites,
                )
                for candidate in part
                if type(candidate) is tuple
            )
        return v2_fast_origin_carries_exact_json_alias(
            part,
            depth=depth + 1,
            hazardous_allocation_sites=hazardous_allocation_sites,
        )

    if kind == "choice":
        return len(origin) >= 2 and nested_alias(origin[1])
    if kind == "aggregate":
        return len(origin) >= 3 and nested_alias(origin[2])
    if kind in {
        "attribute",
        "dict-copy",
        "iter-item",
        "iter-static",
        "maybe-unbound",
        "mutated-member",
        "result-access",
        "subscript",
        "unpack",
    }:
        return len(origin) >= 2 and nested_alias(origin[1])
    if kind == "aggregate-reference":
        # Slot 2 records whether the referenced local allocation had acquired
        # an exact-JSON alias.  Legacy or malformed references have no proof
        # of absence and therefore remain hazardous.
        return bool(
            len(origin) != 3
            or origin[2] is not False
            or origin[1] in hazardous_allocation_sites
        )
    if kind == "dict-view":
        return len(origin) >= 3 and nested_alias(origin[2])
    if kind in {"mapping-merge", "aggregate-map-values"}:
        return any(nested_alias(part) for part in origin[1:])
    if kind == "protocol-result":
        if len(origin) < 4:
            return True
        names = origin[1]
        arguments = origin[2]
        scalar_result = origin[3]
        if scalar_result is True:
            return False
        if type(names) is not tuple or type(arguments) is not tuple:
            return True
        # These builtins construct values that do not retain references to
        # their inputs.  Every other non-scalar protocol result is treated as
        # alias-retaining (iterators, shallow containers, and selectors such
        # as min/max/next all can return or expose an input member).
        if names and all(
            type(name) is str
            and name in {"bytearray", "divmod", "range"}
            for name in names
        ):
            return False
        return nested_alias(arguments)
    if kind == "call-result":
        if len(origin) < 2:
            return True
        if nested_alias(origin[1]):
            return True
        return len(origin) >= 3 and nested_alias(origin[2])
    if kind == "nested-function":
        if len(origin) < 3 or type(origin[2]) is not tuple:
            return True
        return any(
            type(attribute_row) is not tuple
            or len(attribute_row) != 2
            or nested_alias(attribute_row[1])
            for attribute_row in origin[2]
        )
    if kind == "prepared-call":
        if len(origin) < 3:
            return True
        return nested_alias(origin[1]) or nested_alias(origin[2])
    if kind == "suspended-nested":
        if len(origin) < 3:
            return True
        return nested_alias(origin[1]) or nested_alias(origin[2])
    if kind == "derived" and len(origin) >= 3 and origin[1] in {
        "BINARY_OP",
        "BINARY_SLICE",
        "GET_ITER",
        "GET_YIELD_FROM_ITER",
    }:
        return any(nested_alias(part) for part in origin[2:])
    return False


def v2_fast_origin_is_owned_exact_json_outer(
    origin: tuple[Any, ...],
    *,
    depth: int = 0,
    hazardous_allocation_sites: frozenset[tuple[Any, ...]] = frozenset(),
) -> bool:
    """Recognize a fresh outer container that only borrows nested JSON."""
    if depth > V2_REFUSAL_STATE_DEPTH_CAP or not origin:
        return False
    if not v2_fast_origin_carries_exact_json_alias(
        origin,
        depth=depth,
        hazardous_allocation_sites=hazardous_allocation_sites,
    ):
        return False
    kind = origin[0]
    if kind == "dict-copy":
        return True
    if kind == "aggregate":
        return bool(
            len(origin) >= 2
            and origin[1] in {
                "BUILD_CONST_KEY_MAP",
                "BUILD_LIST",
                "BUILD_MAP",
                "BUILD_SET",
                "BUILD_TUPLE",
            }
        )
    if kind == "choice":
        return bool(origin[1]) and all(
            v2_fast_origin_is_owned_exact_json_outer(
                option,
                depth=depth + 1,
                hazardous_allocation_sites=hazardous_allocation_sites,
            )
            for option in origin[1]
        )
    if kind == "mapping-merge":
        return (
            len(origin) >= 2
            and type(origin[1]) is tuple
            and v2_fast_origin_is_owned_exact_json_outer(
                origin[1],
                depth=depth + 1,
                hazardous_allocation_sites=hazardous_allocation_sites,
            )
        )
    if kind == "protocol-result" and len(origin) >= 4:
        names = origin[1]
        return bool(
            type(names) is tuple
            and names
            and all(
                type(name) is str
                and name in {
                    "bytearray",
                    "dict",
                    "frozenset",
                    "list",
                    "set",
                    "sorted",
                    "tuple",
                }
                for name in names
            )
        )
    if kind == "derived" and len(origin) >= 3:
        return origin[1] == "BINARY_SLICE"
    return False


def v2_fast_origin_is_borrowed_exact_json_alias(
    origin: tuple[Any, ...],
    *,
    hazardous_allocation_sites: frozenset[tuple[Any, ...]] = frozenset(),
) -> bool:
    """Return whether mutation through this origin can alter trusted JSON."""
    return bool(
        v2_fast_origin_carries_exact_json_alias(
            origin,
            hazardous_allocation_sites=hazardous_allocation_sites,
        )
        and not v2_fast_origin_is_owned_exact_json_outer(
            origin,
            hazardous_allocation_sites=hazardous_allocation_sites,
        )
    )


def v2_fast_exact_inert_key(value: Any, *, depth: int = 0) -> bool:
    """Return whether key equality/hash is exact and cannot run user code."""
    if depth > V2_REFUSAL_STATE_DEPTH_CAP:
        return False
    if type(value) in {
        type(None), bool, int, float, complex, str, bytes,
    }:
        return True
    return type(value) is tuple and all(
        v2_fast_exact_inert_key(part, depth=depth + 1)
        for part in value
    )


def v2_fast_constant_origin(value: Any) -> tuple[Any, ...]:
    """Keep exact constant types distinct inside origin sets and mappings."""
    return ("constant", value, v2_type_identity(type(value)))


def v2_fast_exact_key_from_origin(
    origin: tuple[Any, ...],
) -> tuple[bool, Any]:
    if (
        origin
        and origin[0] == "constant"
        and len(origin) >= 2
        and v2_fast_exact_inert_key(origin[1])
    ):
        return True, origin[1]
    if (
        origin
        and origin[0] == "constant-tuple"
        and len(origin) == 2
        and v2_fast_exact_inert_key(origin[1])
    ):
        return True, origin[1]
    return False, None


def v2_fast_exact_key_equivalent(
    left_origin: tuple[Any, ...],
    right_origin: tuple[Any, ...],
) -> bool | None:
    """Tri-state exact built-in dict-key equivalence without hook dispatch."""
    left_exact, left = v2_fast_exact_key_from_origin(left_origin)
    right_exact, right = v2_fast_exact_key_from_origin(right_origin)
    if not left_exact or not right_exact:
        return None
    # Dict lookup treats an identical object as the same key even when its
    # equality is non-reflexive (notably an exact NaN object).
    if left is right:
        return True
    return bool(left == right)


def v2_fast_fixed_mapping_entries(
    entries: Sequence[
        tuple[tuple[Any, ...], tuple[Any, ...]]
    ],
) -> tuple[tuple[tuple[Any, ...], tuple[Any, ...]], ...]:
    """Apply ordered last-write semantics where key equivalence is exact."""
    normalized: list[
        tuple[tuple[Any, ...], tuple[Any, ...]]
    ] = []
    for stored_key, stored_value in entries:
        for entry_index, (prior_key, _prior_value) in enumerate(normalized):
            if v2_fast_exact_key_equivalent(
                prior_key,
                stored_key,
            ) is True:
                # Python retains the first equivalent key object but replaces
                # its value on a later ordered write.
                normalized[entry_index] = (prior_key, stored_value)
                break
        else:
            normalized.append((stored_key, stored_value))
    return tuple(normalized)


def v2_fast_aggregate_mapping_entries(
    candidate: tuple[Any, ...],
) -> tuple[tuple[tuple[Any, ...], tuple[Any, ...]], ...] | None:
    if not candidate or candidate[0] != "aggregate":
        return None
    members = candidate[2]
    if candidate[1] == "BUILD_MAP":
        if len(members) % 2:
            return None
        entries = tuple(
            (members[index], members[index + 1])
            for index in range(0, len(members), 2)
        )
        return (
            v2_fast_fixed_mapping_entries(entries)
            if len(candidate) >= 5 and candidate[4] is False
            else entries
        )
    if (
        candidate[1] == "BUILD_CONST_KEY_MAP"
        and members
        and members[-1]
        and members[-1][0] == "constant-tuple"
        and len(members[-1][1]) == len(members) - 1
    ):
        entries = tuple(
            (v2_fast_constant_origin(key), value)
            for key, value in zip(
                members[-1][1],
                members[:-1],
                strict=True,
            )
        )
        return (
            v2_fast_fixed_mapping_entries(entries)
            if len(candidate) >= 5 and candidate[4] is False
            else entries
        )
    return None


def v2_fast_dict_view_members(
    candidate: tuple[Any, ...],
) -> tuple[tuple[Any, ...], ...] | None:
    if (
        len(candidate) != 3
        or candidate[0] != "dict-view"
        or candidate[1] not in {"items", "values"}
    ):
        return None
    entries = v2_fast_aggregate_mapping_entries(candidate[2])
    if entries is None:
        return None
    if candidate[1] == "values":
        return tuple(value for _key, value in entries)
    return tuple(
        ("aggregate", "BUILD_TUPLE", (key, value))
        for key, value in entries
    )


def v2_fast_origin_binding(
    source_kind: str,
    source_name: str,
    source_path: tuple[str, ...] = (),
) -> tuple[Any, ...]:
    return ("binding", source_kind, source_name, source_path)


def v2_fast_origin_with_path(
    origin: tuple[Any, ...],
    path: tuple[str, ...],
) -> tuple[Any, ...]:
    if not path:
        return origin
    return ("attribute", origin, path)


def v2_fast_origin_stack_effect(
    instruction: V2AnalysisInstruction,
) -> int | None:
    opcode = dis.opmap.get(instruction.opname)
    if opcode is None:
        return None
    try:
        if instruction.arg is None:
            return dis.stack_effect(opcode)
        return dis.stack_effect(opcode, instruction.arg)
    except (TypeError, ValueError):
        return None


def v2_bounded_origin_height(
    value: Any,
    identity_cache: dict[int, tuple[tuple[Any, ...], int]],
) -> int:
    """Return legacy origin nesting height, retaining the cap+1 sentinel."""
    if type(value) is not tuple or not value:
        return 0
    cache_key = id(value)
    cached = dict.get(identity_cache, cache_key)
    if cached is not None and cached[0] is value:
        return cached[1]
    nested_parts = value[1:] if type(value[0]) is str else value
    height = 0
    for part in nested_parts:
        if type(part) is not tuple:
            continue
        height = max(
            height,
            min(
                V2_REFUSAL_STATE_DEPTH_CAP + 1,
                1 + v2_bounded_origin_height(part, identity_cache),
            ),
        )
        if height > V2_REFUSAL_STATE_DEPTH_CAP:
            break
    dict.__setitem__(identity_cache, cache_key, (value, height))
    return height


def v2_fast_origin_sort_key(
    value: Any,
    _identity_cache: dict[
        int,
        tuple[Any, tuple[Any, ...]],
    ] | None = None,
) -> tuple[Any, ...]:
    """Return an address-free structural order for origin-lattice values."""
    identity_cache = (
        {} if _identity_cache is None else _identity_cache
    )
    cacheable = type(value) in {tuple, types.CodeType}
    cache_key = id(value)
    if cacheable:
        cached = dict.get(identity_cache, cache_key)
        if cached is not None and cached[0] is value:
            return cached[1]
    if type(value) is types.CodeType:
        result = (
            "code",
            value.co_filename,
            value.co_name,
            value.co_qualname,
            value.co_firstlineno,
            value.co_argcount,
            value.co_posonlyargcount,
            value.co_kwonlyargcount,
            value.co_nlocals,
            value.co_stacksize,
            value.co_flags,
            value.co_code.hex(),
            value.co_linetable.hex(),
            value.co_exceptiontable.hex(),
            tuple(value.co_names),
            tuple(value.co_varnames),
            tuple(value.co_freevars),
            tuple(value.co_cellvars),
            tuple(
                v2_fast_origin_sort_key(constant, identity_cache)
                for constant in value.co_consts
            ),
        )
    elif type(value) is tuple:
        result = (
            "tuple",
            tuple(
                v2_fast_origin_sort_key(part, identity_cache)
                for part in value
            ),
        )
    elif type(value) in {str, int, bool, type(None)}:
        result = (type(value).__name__, value)
    elif type(value) is bytes:
        result = ("bytes", value.hex())
    elif type(value) is float:
        result = ("float", struct.pack(">d", value).hex())
    elif type(value) is complex:
        result = (
            "complex",
            struct.pack(">d", value.real).hex(),
            struct.pack(">d", value.imag).hex(),
        )
    elif type(value) is range:
        result = ("range", value.start, value.stop, value.step)
    elif type(value) is slice:
        result = (
            "slice",
            v2_fast_origin_sort_key(value.start, identity_cache),
            v2_fast_origin_sort_key(value.stop, identity_cache),
            v2_fast_origin_sort_key(value.step, identity_cache),
        )
    elif value is Ellipsis:
        result = ("singleton", "Ellipsis")
    elif value is NotImplemented:
        result = ("singleton", "NotImplemented")
    elif type(value) is type:
        result = ("type", value.__module__, value.__qualname__)
    elif type(value) is list:
        result = (
            "list",
            tuple(
                v2_fast_origin_sort_key(part, identity_cache)
                for part in value
            ),
        )
    elif type(value) in {frozenset, set}:
        members = [
            v2_fast_origin_sort_key(part, identity_cache)
            for part in value
        ]
        result = (type(value).__name__, tuple(sorted(members)))
    else:
        raise EvidenceFailed(
            "refusal-state origin ordering reached an unsupported exact type: "
            f"{v2_type_identity(type(value))}"
        )
    if cacheable:
        dict.__setitem__(identity_cache, cache_key, (value, result))
    return result


def v2_nested_function_freevar_origins(
    nested_code: types.CodeType,
    callable_origins: Sequence[tuple[Any, ...]],
) -> dict[str, tuple[Any, ...]]:
    """Bind a nested function's closure cells to exact parent origins."""
    freevar_names = tuple(nested_code.co_freevars)
    if not freevar_names:
        return {}
    merged: dict[str, tuple[Any, ...]] = {}
    matched = False

    def add(name: str, origin: tuple[Any, ...]) -> None:
        prior = merged.get(name)
        if prior is None or prior == origin:
            merged[name] = origin
            return
        options: set[tuple[Any, ...]] = set()
        for candidate in (prior, origin):
            if candidate and candidate[0] == "choice":
                options.update(candidate[1])
            else:
                options.add(candidate)
        merged[name] = (
            V2_FAST_ORIGIN_UNKNOWN
            if len(options) > V2_FAST_ORIGIN_RESOLUTION_CAP
            else (
                "choice",
                tuple(sorted(options, key=v2_fast_origin_sort_key)),
            )
        )

    for callable_origin in callable_origins:
        if (
            not callable_origin
            or callable_origin[0] != "nested-function"
            or callable_origin[1] is not nested_code
            or len(callable_origin) != 3
        ):
            continue
        matched = True
        closure_payloads = [
            payload
            for flag, payload in callable_origin[2]
            if flag == 8
        ]
        if len(closure_payloads) != 1:
            raise EvidenceFailed(
                "refusal-state invoked nested closure payload is not exact "
                f"in {nested_code.co_qualname}"
            )
        closure = closure_payloads[0]
        closure_options = (
            closure[1]
            if closure and closure[0] == "choice"
            else (closure,)
        )
        for option in closure_options:
            if (
                not option
                or option[0] != "aggregate"
                or option[1] != "BUILD_TUPLE"
                or len(option[2]) != len(freevar_names)
            ):
                raise EvidenceFailed(
                    "refusal-state invoked nested closure cells are not "
                    f"exact in {nested_code.co_qualname}"
                )
            for name, origin in zip(
                freevar_names,
                option[2],
                strict=True,
            ):
                add(name, origin)
    if not matched or set(merged) != set(freevar_names):
        raise EvidenceFailed(
            "refusal-state invoked nested closure is incomplete in "
            f"{nested_code.co_qualname}"
        )
    return merged


def v2_fast_local_origin_dataflow(
    instructions: Sequence[V2AnalysisInstruction],
    code: types.CodeType,
    *,
    active_executable_function: types.FunctionType | None = None,
    parameter_origins: Mapping[str, tuple[Any, ...]] | None = None,
    freevar_origins: Mapping[str, tuple[Any, ...]] | None = None,
    _nested_depth: int = 0,
) -> dict[str, Any]:
    """Build a bounded reaching-origin graph over normalized CPython CFGs."""
    if _nested_depth > V2_REFUSAL_STATE_DEPTH_CAP:
        raise EvidenceFailed(
            "refusal-state nested comprehension analysis exceeds its depth cap"
        )
    origin_height_identity_cache: dict[
        int,
        tuple[tuple[Any, ...], int],
    ] = {}
    origin_sort_identity_cache: dict[
        int,
        tuple[Any, tuple[Any, ...]],
    ] = {}
    origin_cache_entry_cap = max(256, len(instructions) * 64)
    hazardous_mapping_allocation_sites: set[tuple[Any, ...]] = set()
    hazard_epoch = 0

    def exact_json_hazard_sites() -> frozenset[tuple[Any, ...]]:
        return frozenset(hazardous_mapping_allocation_sites)

    def origin_carries_exact_json_alias(
        origin: tuple[Any, ...],
    ) -> bool:
        return v2_fast_origin_carries_exact_json_alias(
            origin,
            hazardous_allocation_sites=exact_json_hazard_sites(),
        )

    def origin_is_borrowed_exact_json_alias(
        origin: tuple[Any, ...],
    ) -> bool:
        return v2_fast_origin_is_borrowed_exact_json_alias(
            origin,
            hazardous_allocation_sites=exact_json_hazard_sites(),
        )

    def register_mapping_exact_json_hazard(
        origin: tuple[Any, ...],
    ) -> tuple[Any, ...]:
        nonlocal hazard_epoch
        if not (
            len(origin) >= 5
            and origin[0] == "aggregate"
            and origin[1] in {"BUILD_MAP", "BUILD_CONST_KEY_MAP"}
            and type(origin[3]) is tuple
            and origin_carries_exact_json_alias(origin)
        ):
            return origin
        allocation_site = origin[3]
        if allocation_site not in hazardous_mapping_allocation_sites:
            set.add(hazardous_mapping_allocation_sites, allocation_site)
            hazard_epoch += 1
        return origin

    def origin_sort_key(value: Any) -> tuple[Any, ...]:
        if (
            dict.__len__(origin_sort_identity_cache)
            >= origin_cache_entry_cap
        ):
            dict.clear(origin_sort_identity_cache)
        return v2_fast_origin_sort_key(
            value,
            origin_sort_identity_cache,
        )
    parameter_layout = dict(v2_code_parameter_layout(code))
    initial_bindings: dict[tuple[str, str], tuple[Any, ...]] = {}
    for name in parameter_layout:
        initial_bindings[("fast", name)] = (
            parameter_origins[name]
            if parameter_origins is not None and name in parameter_origins
            else v2_fast_origin_binding("parameter", name)
        )
    for name in code.co_freevars:
        initial_bindings[("freevar", name)] = (
            freevar_origins[name]
            if freevar_origins is not None and name in freevar_origins
            else v2_fast_origin_binding("freevar", name)
        )

    source_call_indices: defaultdict[int, set[int]] = defaultdict(set)
    observed_call_sources: defaultdict[int, set[tuple[Any, ...]]] = (
        defaultdict(set)
    )
    access_expressions: dict[int, tuple[Any, ...]] = {}
    implicit_call_expressions: dict[int, tuple[Any, ...]] = {}
    dynamic_uses: defaultdict[
        int,
        set[tuple[str, tuple[Any, ...]]],
    ] = defaultdict(set)
    exact_result_call_indices: set[int] = set()
    return_expressions: set[tuple[Any, ...]] = set()
    invoked_nested_calls: defaultdict[
        types.CodeType,
        defaultdict[
            int,
            set[
                tuple[
                    tuple[Any, ...],
                    tuple[tuple[Any, ...], ...],
                    tuple[str, ...] | None,
                ]
            ],
        ],
    ] = defaultdict(lambda: defaultdict(set))
    nested_container_result_cache: dict[
        tuple[
            tuple[tuple[Any, ...], ...],
            tuple[tuple[Any, ...], ...],
            tuple[str, ...] | None,
        ],
        tuple[Any, ...] | None,
    ] = {}

    for index, instruction in enumerate(instructions):
        source: tuple[Any, ...] | None = None
        if (
            instruction.opname in {"LOAD_GLOBAL", "LOAD_NAME"}
            and type(instruction.argval) is str
        ):
            source = v2_fast_origin_binding("global", instruction.argval)
        elif (
            instruction.opname in {"LOAD_DEREF", "LOAD_CLASSDEREF"}
            and type(instruction.argval) is str
            and instruction.argval in code.co_freevars
        ):
            source = v2_fast_origin_binding("freevar", instruction.argval)
        elif (
            instruction.opname in V2_FAST_LOCAL_LOAD_OPS
            and type(instruction.argval) is str
        ):
            source = ("local", instruction.argval)
            if instruction.opname in V2_FAST_LOCAL_MAYBE_UNBOUND_LOAD_OPS:
                source = ("maybe-unbound", source)
        if source is None:
            continue
        path, path_end = v2_instruction_access_path(instructions, index)
        access = v2_fast_origin_with_path(source, path)
        call_indices = v2_matching_direct_call_indices(
            instructions,
            index,
            path_end,
        )
        for call_index in call_indices:
            source_call_indices[index].add(call_index)

    def origin_options(expression: tuple[Any, ...]) -> set[tuple[Any, ...]]:
        if expression and expression[0] == "choice":
            return set(expression[1])
        return {expression}

    def callable_frame_identity(
        expression: tuple[Any, ...],
    ) -> tuple[Any, ...]:
        if (
            expression
            and expression[0] == "nested-function"
            and len(expression) == 3
        ):
            return ("nested-function-code", expression[1])
        return expression

    def append_aggregate_members(
        target: tuple[Any, ...],
        members: Iterable[tuple[Any, ...]],
    ) -> tuple[Any, ...]:
        if not (
            len(target) >= 5
            and target[0] == "aggregate"
            and target[1] == "BUILD_LIST"
        ):
            return V2_FAST_ORIGIN_UNKNOWN
        combined = tuple(sorted(
            {*target[2], *members},
            key=origin_sort_key,
        ))
        if len(combined) > V2_FAST_ORIGIN_RESOLUTION_CAP:
            return V2_FAST_ORIGIN_UNKNOWN
        return (
            "aggregate",
            "BUILD_LIST",
            combined,
            target[3],
            True,
        )

    def replace_aggregate_list_item(
        target: tuple[Any, ...],
        key: tuple[Any, ...],
        value: tuple[Any, ...],
    ) -> tuple[Any, ...]:
        if not (
            len(target) >= 5
            and target[0] == "aggregate"
            and target[1] == "BUILD_LIST"
            and target[4] is False
            and key
            and key[0] == "constant"
            and type(key[1]) in {bool, int}
            and -len(target[2]) <= int(key[1]) < len(target[2])
        ):
            return V2_FAST_ORIGIN_UNKNOWN
        index = int(key[1]) % len(target[2])
        members = list(target[2])
        members[index] = value
        return (
            "aggregate",
            "BUILD_LIST",
            tuple(members),
            target[3],
            False,
        )

    def aggregate_mapping_entries(
        candidate: tuple[Any, ...],
    ) -> tuple[tuple[tuple[Any, ...], tuple[Any, ...]], ...] | None:
        return v2_fast_aggregate_mapping_entries(candidate)

    def merge_mapping_entries_by_equivalence(
        rows: Iterable[
            tuple[tuple[Any, ...], tuple[Any, ...]]
        ],
    ) -> list[tuple[tuple[Any, ...], tuple[Any, ...]]]:
        """Merge only proven-equivalent keys; retain unknown collisions."""
        combined: list[
            tuple[tuple[Any, ...], tuple[Any, ...]]
        ] = []
        for stored_key, stored_value in rows:
            for row_index, (prior_key, prior_value) in enumerate(combined):
                if (
                    prior_key == stored_key
                    or v2_fast_exact_key_equivalent(
                        prior_key,
                        stored_key,
                    ) is True
                ):
                    # Identical abstract origins may denote distinct concrete
                    # loop members, but one possibility row is sufficient:
                    # retain the shared key provenance and merge every value
                    # provenance.  Exact runtime key equivalence remains a
                    # separate, stronger case handled by the second branch.
                    combined[row_index] = (
                        prior_key,
                        merge_origin(prior_value, stored_value),
                    )
                    break
            else:
                combined.append((stored_key, stored_value))
        return combined

    def append_aggregate_mapping_entry(
        target: tuple[Any, ...],
        key: tuple[Any, ...],
        value: tuple[Any, ...],
    ) -> tuple[Any, ...]:
        entries = aggregate_mapping_entries(target)
        if entries is None or len(target) < 5:
            return V2_FAST_ORIGIN_UNKNOWN
        allocation_site = target[3]

        def collapse_recursive_mapping(
            candidate: tuple[Any, ...],
            *,
            depth: int = 0,
        ) -> tuple[Any, ...]:
            if candidate and candidate[0] in {
                "binding",
                "call-result",
                "result-access",
            }:
                return candidate
            if (
                candidate
                and candidate[0] == "attribute"
                and candidate[1]
                and candidate[1][0] == "binding"
            ):
                return candidate
            if depth > V2_REFUSAL_STATE_DEPTH_CAP:
                return V2_FAST_ORIGIN_UNKNOWN
            if (
                len(candidate) >= 5
                and candidate[0] == "aggregate"
                and candidate[1] in {"BUILD_MAP", "BUILD_CONST_KEY_MAP"}
                and candidate[3] == allocation_site
            ):
                return ("aggregate-reference", allocation_site, False)
            if (
                len(candidate) == 3
                and candidate[0] == "aggregate-map-values"
                and candidate[1] == allocation_site
            ):
                return ("aggregate-reference", allocation_site, False)
            changed = False
            parts: list[Any] = []
            for part in candidate:
                if type(part) is tuple:
                    updated = collapse_recursive_mapping(
                        part,
                        depth=depth + 1,
                    )
                    changed = changed or updated != part
                    parts.append(updated)
                else:
                    parts.append(part)
            return tuple(parts) if changed else candidate

        value_carried_exact_json_alias = (
            origin_carries_exact_json_alias(value)
        )
        value = collapse_recursive_mapping(value)

        def mark_alias_references(candidate: Any) -> Any:
            if type(candidate) is not tuple or not candidate:
                return candidate
            if (
                candidate[0] == "aggregate-reference"
                and len(candidate) >= 2
                and candidate[1] == allocation_site
            ):
                return ("aggregate-reference", allocation_site, True)
            changed = False
            parts: list[Any] = []
            for part in candidate:
                updated = mark_alias_references(part)
                changed = changed or updated != part
                parts.append(updated)
            return tuple(parts) if changed else candidate

        if (
            origin_carries_exact_json_alias(target)
            or origin_carries_exact_json_alias(key)
            or origin_carries_exact_json_alias(value)
            or value_carried_exact_json_alias
        ):
            entries = tuple(
                (
                    mark_alias_references(stored_key),
                    mark_alias_references(stored_value),
                )
                for stored_key, stored_value in entries
            )
            key = mark_alias_references(key)
            value = mark_alias_references(value)
        if target[4] is False:
            combined = v2_fast_fixed_mapping_entries((
                *entries,
                (key, value),
            ))
            if len(combined) > V2_FAST_ORIGIN_RESOLUTION_CAP:
                return V2_FAST_ORIGIN_UNKNOWN
            return register_mapping_exact_json_hazard((
                "aggregate",
                "BUILD_MAP",
                tuple(part for entry in combined for part in entry),
                allocation_site,
                False,
            ))
        if target[4] is True:
            # Once a loop-carried map has been mutated, retaining its complete
            # recursively constructed values causes each DP iteration to
            # embed the prior iteration's whole provenance tree.  Preserve
            # only the external binding/call-result leaves needed by the
            # protocol and result-contract checks; exact scalar/container
            # structure remains represented by the map itself.
            sources = bounded_origin_summary_sources(value)
            value = (
                next(iter(sources))
                if len(sources) == 1
                else (
                    "aggregate",
                    "ORIGIN_SUMMARY",
                    tuple(sorted(sources, key=origin_sort_key)),
                )
                if sources
                else V2_FAST_ORIGIN_STATIC
            )
        combined_entries = merge_mapping_entries_by_equivalence((
            *entries,
            (key, value),
        ))
        if target[4] is True:
            # BUILD_MAP keys and values have distinct semantics.  A key's
            # provenance must never become a possible value origin merely
            # because the loop-carried map is summarized.
            for _stored_key, stored_value in combined_entries:
                sources.update(bounded_origin_summary_sources(stored_value))
            summary_value = (
                next(iter(sources))
                if len(sources) == 1
                else (
                    "aggregate",
                    "ORIGIN_SUMMARY",
                    tuple(sorted(sources, key=origin_sort_key)),
                )
                if sources
                else V2_FAST_ORIGIN_STATIC
            )
            return register_mapping_exact_json_hazard((
                "aggregate",
                "BUILD_MAP",
                (V2_FAST_ORIGIN_STATIC, summary_value),
                allocation_site,
                True,
            ))
        combined = tuple(sorted(
            combined_entries,
            key=origin_sort_key,
        ))
        if len(combined) > V2_FAST_ORIGIN_RESOLUTION_CAP:
            return V2_FAST_ORIGIN_UNKNOWN
        return register_mapping_exact_json_hazard((
            "aggregate",
            "BUILD_MAP",
            tuple(part for entry in combined for part in entry),
            allocation_site,
            True,
        ))

    def iterable_member_origins(
        source: tuple[Any, ...],
    ) -> set[tuple[Any, ...]]:
        members: set[tuple[Any, ...]] = set()
        for candidate in origin_options(source):
            if v2_fast_origin_is_exact_json(candidate):
                members.add((
                    "exact-json-member",
                    candidate,
                    "<iter-item>",
                ))
                continue
            view_members = v2_fast_dict_view_members(candidate)
            if view_members is not None:
                members.update(view_members)
            elif candidate and candidate[0] == "aggregate":
                members.update(candidate[2])
            elif (
                candidate
                and candidate[0] == "derived"
                and candidate[1] in {"GET_ITER", "GET_YIELD_FROM_ITER"}
            ):
                members.update(iterable_member_origins(candidate[2]))
            else:
                members.add((
                    "iter-item",
                    ("derived", "GET_ITER", candidate),
                ))
        return members

    def exact_positional_expansion(
        source: tuple[Any, ...],
    ) -> tuple[tuple[Any, ...], ...] | None:
        rows: list[tuple[tuple[Any, ...], ...]] = []
        for candidate in origin_options(source):
            if candidate and candidate[0] == "constant-tuple":
                rows.append(tuple(
                    v2_fast_constant_origin(value)
                    for value in candidate[1]
                ))
            elif (
                candidate
                and candidate[0] == "aggregate"
                and candidate[1] in {"BUILD_LIST", "BUILD_TUPLE"}
                and (len(candidate) < 5 or candidate[4] is not True)
            ):
                rows.append(tuple(candidate[2]))
            else:
                return None
        if not rows:
            return None
        lengths = {len(row) for row in rows}
        if len(lengths) != 1:
            return None
        return tuple(
            merge_origins(row[index] for row in rows)
            for index in range(next(iter(lengths), 0))
        )

    def exact_keyword_expansion(
        source: tuple[Any, ...],
    ) -> tuple[tuple[str, ...], tuple[tuple[Any, ...], ...]] | None:
        def one(
            candidate: tuple[Any, ...],
        ) -> tuple[tuple[str, ...], tuple[tuple[Any, ...], ...]] | None:
            if candidate and candidate[0] == "mapping-merge":
                left = exact_keyword_expansion(candidate[1])
                right = exact_keyword_expansion(candidate[2])
                if left is None or right is None:
                    return None
                return ((*left[0], *right[0]), (*left[1], *right[1]))
            if not candidate or candidate[0] != "aggregate":
                return None
            if len(candidate) >= 5 and candidate[4] is True:
                # A control-flow-merged or subscript-mutated mapping retains
                # value provenance but no longer proves one exact keyword
                # sequence for CALL_FUNCTION_EX.
                return None
            members = candidate[2]
            if candidate[1] == "BUILD_MAP":
                if len(members) % 2:
                    return None
                names: list[str] = []
                values: list[tuple[Any, ...]] = []
                for index in range(0, len(members), 2):
                    key = members[index]
                    if (
                        not key
                        or key[0] != "constant"
                        or type(key[1]) is not str
                    ):
                        return None
                    names.append(key[1])
                    values.append(members[index + 1])
                return tuple(names), tuple(values)
            if (
                candidate[1] == "BUILD_CONST_KEY_MAP"
                and members
                and members[-1]
                and members[-1][0] == "constant-tuple"
                and all(type(name) is str for name in members[-1][1])
                and len(members[-1][1]) == len(members) - 1
            ):
                return tuple(members[-1][1]), tuple(members[:-1])
            return None

        rows = [one(candidate) for candidate in origin_options(source)]
        if not rows or any(row is None for row in rows):
            return None
        exact_rows = [row for row in rows if row is not None]
        names = {row[0] for row in exact_rows}
        if len(names) != 1:
            return None
        keyword_names = next(iter(names))
        return keyword_names, tuple(
            merge_origins(row[1][index] for row in exact_rows)
            for index in range(len(keyword_names))
        )

    def origin_depth(value: Any, depth: int = 0) -> int:
        if type(value) is not tuple or not value:
            return depth
        if depth > V2_REFUSAL_STATE_DEPTH_CAP:
            return depth
        if (
            dict.__len__(origin_height_identity_cache)
            >= origin_cache_entry_cap
        ):
            dict.clear(origin_height_identity_cache)
        return min(
            V2_REFUSAL_STATE_DEPTH_CAP + 1,
            depth
            + v2_bounded_origin_height(
                value,
                origin_height_identity_cache,
            ),
        )

    def inert_scalar_origin(value: tuple[Any, ...]) -> bool:
        """Recognize exact scalar recurrence inputs without widening objects."""
        if not value:
            return False
        kind = value[0]
        if kind in {"constant", "static"}:
            return True
        if kind == "choice":
            return bool(value[1]) and all(
                inert_scalar_origin(option) for option in value[1]
            )
        if kind == "protocol-result":
            return len(value) >= 4 and (
                value[3] is True
                or value[1]
                and set(value[1]).issubset({"max", "min", "sum"})
                and all(
                    inert_scalar_origin(argument)
                    for argument in value[2]
                )
            )
        if kind == "derived" and value[1] == "BINARY_OP":
            return all(
                type(part) is not tuple or inert_scalar_origin(part)
                for part in value[2:]
            )
        return False

    def repeated_pure_posix_parent_root(
        value: tuple[Any, ...],
    ) -> tuple[Any, ...] | None:
        """Return the exact constructor root of a repeated ``.parent`` path."""
        candidate = value
        parent_seen = False
        while (
            candidate
            and candidate[0] == "attribute"
            and candidate[2] == ("parent",)
        ):
            parent_seen = True
            candidate = candidate[1]
        if (
            candidate
            and candidate[0] == "result-access"
            and candidate[2]
            and all(part == "parent" for part in candidate[2])
        ):
            parent_seen = True
            candidate = candidate[1]
        if not parent_seen or not candidate or candidate[0] != "call-result":
            return None
        callable_origin = candidate[1]
        if callable_origin != (
            "binding",
            "global",
            "PurePosixPath",
            (),
        ):
            return None
        return candidate

    def bounded_origin_summary_sources(
        value: tuple[Any, ...],
        *,
        depth: int = 0,
    ) -> set[tuple[Any, ...]]:
        """Retain external provenance leaves without recursive containers."""
        if depth > V2_REFUSAL_STATE_DEPTH_CAP:
            return {V2_FAST_ORIGIN_UNKNOWN}
        if not value:
            return set()
        if v2_fast_origin_is_exact_json(value):
            return {value}
        kind = value[0]
        if kind == "aggregate-reference":
            # A proven-clean local recursive reference contributes no
            # external source.  A reference that has acquired an exact-JSON
            # alias (or lacks the complete three-slot proof) must survive
            # summarization so a later lookup cannot collapse it to STATIC.
            return (
                set()
                if len(value) == 3 and value[2] is False
                else {value}
            )
        if kind in {
            "binding",
            "call-result",
            "result-access",
            "unknown",
        }:
            return {value}
        if (
            kind == "attribute"
            and value[1]
            and value[1][0] == "binding"
        ):
            return {value}
        if kind in {
            "attribute",
            "iter-item",
            "maybe-unbound",
            "mutated-member",
            "subscript",
            "unpack",
        }:
            sources = bounded_origin_summary_sources(
                value[1],
                depth=depth + 1,
            )
            return {
                (kind, source, *value[2:])
                for source in sources
            }
        sources: set[tuple[Any, ...]] = set()
        for part in value[1:]:
            if type(part) is not tuple:
                continue
            if part and type(part[0]) is tuple:
                nested_parts = part
            else:
                nested_parts = (part,)
            for nested in nested_parts:
                sources.update(bounded_origin_summary_sources(
                    nested,
                    depth=depth + 1,
                ))
                if len(sources) > V2_FAST_ORIGIN_RESOLUTION_CAP:
                    return {V2_FAST_ORIGIN_UNKNOWN}
        return sources

    origin_merge_identity_cache: dict[
        tuple[int, int],
        tuple[
            tuple[Any, ...],
            tuple[Any, ...],
            tuple[Any, ...],
        ],
    ] = {}

    def merge_origin_uncached(
        left: tuple[Any, ...],
        right: tuple[Any, ...],
    ) -> tuple[Any, ...]:
        if left is right:
            return left
        if left == right:
            return left
        left_parent_root = repeated_pure_posix_parent_root(left)
        right_parent_root = repeated_pure_posix_parent_root(right)
        if (
            left_parent_root is not None
            and left_parent_root == right_parent_root
        ):
            # Walking lexical parents is a loop-carried recurrence over the
            # exact PurePosixPath constructor's audited pure ``parent``
            # property.  Preserve the constructor identity and one bounded
            # property contract instead of nesting one attribute node per
            # back-edge until the conservative depth cap produces unknown.
            return (
                "result-access",
                left_parent_root,
                ("parent",),
            )
        if (
            (
                left[0] == "static"
                or right[0] == "static"
                or left[0] == "derived" and left[1] == "BINARY_OP"
                or right[0] == "derived" and right[1] == "BINARY_OP"
                or left[0] == "protocol-result"
                or right[0] == "protocol-result"
                or left[0] == "choice"
                or right[0] == "choice"
            )
            and inert_scalar_origin(left)
            and inert_scalar_origin(right)
        ):
            # Loop-carried exact scalar recurrences (for example a byte
            # offset advanced by ``len(chunk)``) otherwise grow one nested
            # choice per back-edge until the resolution cap turns them into
            # ``unknown``.  Collapse only proven scalar arithmetic; callable,
            # aggregate, binding, and call-result provenance remains intact.
            return V2_FAST_ORIGIN_STATIC
        if (
            left[0] == right[0]
            and left[0] in {
                "attribute",
                "iter-item",
                "maybe-unbound",
                "mutated-member",
                "subscript",
                "unpack",
            }
            and left[2:] == right[2:]
        ):
            return (
                left[0],
                merge_origin(left[1], right[1]),
                *left[2:],
            )
        if (
            left[0] == right[0] == "aggregate"
            and left[1] == right[1] == "BUILD_TUPLE"
            and len(left[2]) == len(right[2])
        ):
            return (
                "aggregate",
                "BUILD_TUPLE",
                tuple(
                    merge_origin(left_member, right_member)
                    for left_member, right_member in zip(
                        left[2],
                        right[2],
                        strict=True,
                    )
                ),
            )
        if (
            len(left) >= 5
            and len(right) >= 5
            and left[0] == right[0] == "aggregate"
            and left[1] == right[1] == "BUILD_LIST"
            and left[3] == right[3]
        ):
            if (
                left[4] is right[4] is False
                and len(left[2]) == len(right[2])
            ):
                # Reprocessing a fixed-shape list literal (notably ``*[m]``)
                # can observe successive states of a member without changing
                # the list's positional shape.  Preserve each position while
                # merging its origin; LIST_APPEND/comprehension possibility
                # sets carry the True marker and remain on the branch below.
                return (
                    "aggregate",
                    "BUILD_LIST",
                    tuple(
                        merge_origin(left_member, right_member)
                        for left_member, right_member in zip(
                            left[2],
                            right[2],
                            strict=True,
                        )
                    ),
                    left[3],
                    False,
                )
            # LIST_APPEND retains the comprehension list below the iterator.
            # Merge possible appended member origins for the same allocation
            # site instead of growing a recursive choice on every loop edge.
            # The final marker disables positional-subscript exactness because
            # these members are a bounded possibility set, not list positions.
            members = tuple(sorted(
                set(left[2]) | set(right[2]),
                key=origin_sort_key,
            ))
            if len(members) > V2_FAST_ORIGIN_RESOLUTION_CAP:
                return V2_FAST_ORIGIN_UNKNOWN
            return (
                "aggregate",
                "BUILD_LIST",
                members,
                left[3],
                True,
            )
        if (
            len(left) >= 5
            and len(right) >= 5
            and left[0] == right[0] == "aggregate"
            and left[1] == right[1]
            and left[1] in {"BUILD_LIST", "BUILD_SET"}
            and left[3] == right[3]
        ):
            members = tuple(sorted(
                {*left[2], *right[2]},
                key=origin_sort_key,
            ))
            if len(members) > V2_FAST_ORIGIN_RESOLUTION_CAP:
                return V2_FAST_ORIGIN_UNKNOWN
            return (
                "aggregate",
                left[1],
                members,
                left[3],
                True,
            )
        if (
            len(left) == len(right) == 3
            and left[0] == right[0] == "aggregate-map-values"
            and left[1] == right[1]
        ):
            return (
                "aggregate-map-values",
                left[1],
                merge_origin(left[2], right[2]),
            )
        if (
            len(left) == len(right) == 3
            and left[0] == right[0] == "dict-view"
            and left[1] == right[1]
        ):
            return (
                "dict-view",
                left[1],
                merge_origin(left[2], right[2]),
            )
        if (
            left[0] == "aggregate"
            and left[1] == "ORIGIN_SUMMARY"
            or right[0] == "aggregate"
            and right[1] == "ORIGIN_SUMMARY"
        ):
            summary_members = {
                source
                for candidate in (left, right)
                for source in bounded_origin_summary_sources(candidate)
            }
            if len(summary_members) > V2_FAST_ORIGIN_RESOLUTION_CAP:
                return V2_FAST_ORIGIN_UNKNOWN
            if not summary_members:
                return V2_FAST_ORIGIN_STATIC
            if len(summary_members) == 1:
                return next(iter(summary_members))
            return (
                "aggregate",
                "ORIGIN_SUMMARY",
                tuple(sorted(
                    summary_members,
                    key=origin_sort_key,
                )),
            )
        if (
            len(left) >= 5
            and len(right) >= 5
            and left[0] == right[0] == "aggregate"
            and left[1] in {"BUILD_MAP", "BUILD_CONST_KEY_MAP"}
            and right[1] in {"BUILD_MAP", "BUILD_CONST_KEY_MAP"}
            and left[3] == right[3]
        ):
            left_entries = aggregate_mapping_entries(left)
            right_entries = aggregate_mapping_entries(right)
            if left_entries is None or right_entries is None:
                return V2_FAST_ORIGIN_UNKNOWN
            allocation_site = left[3]

            def mark_merged_alias_references(candidate: Any) -> Any:
                if type(candidate) is not tuple or not candidate:
                    return candidate
                if (
                    candidate[0] == "aggregate-reference"
                    and len(candidate) >= 2
                    and candidate[1] == allocation_site
                ):
                    return (
                        "aggregate-reference",
                        allocation_site,
                        True,
                    )
                changed = False
                parts: list[Any] = []
                for part in candidate:
                    updated = mark_merged_alias_references(part)
                    changed = changed or updated != part
                    parts.append(updated)
                return tuple(parts) if changed else candidate

            if any(
                origin_carries_exact_json_alias(stored_key)
                or origin_carries_exact_json_alias(stored_value)
                for stored_key, stored_value in (
                    *left_entries,
                    *right_entries,
                )
            ):
                # A recursive reference denotes this same allocation.  If
                # either control-flow arm introduces a trusted exact-JSON
                # alias, every retained self-reference must carry that
                # possibility too; otherwise a lookup through the other arm
                # could launder the alias behind a stale False marker.
                left_entries = tuple(
                    (
                        mark_merged_alias_references(stored_key),
                        mark_merged_alias_references(stored_value),
                    )
                    for stored_key, stored_value in left_entries
                )
                right_entries = tuple(
                    (
                        mark_merged_alias_references(stored_key),
                        mark_merged_alias_references(stored_value),
                    )
                    for stored_key, stored_value in right_entries
                )
            left_is_summary = (
                left[4] is True
                and len(left_entries) == 1
                and left_entries[0][0] == V2_FAST_ORIGIN_STATIC
            )
            right_is_summary = (
                right[4] is True
                and len(right_entries) == 1
                and right_entries[0][0] == V2_FAST_ORIGIN_STATIC
            )
            if left_is_summary or right_is_summary:
                summary_values: list[tuple[Any, ...]] = []
                for _candidate, entries, is_summary in (
                    (left, left_entries, left_is_summary),
                    (right, right_entries, right_is_summary),
                ):
                    if is_summary:
                        summary_values.append(entries[0][1])
                        continue
                    for _stored_key, stored_value in entries:
                        # A mapping join summarizes possible values only.
                        # Keys remain lookup selectors and must not become
                        # candidate value provenance when one side is already
                        # represented by a loop-carried summary.
                        summary_values.append(stored_value)
                summary_value = (
                    merge_origins(summary_values)
                    if summary_values
                    else V2_FAST_ORIGIN_STATIC
                )
                return register_mapping_exact_json_hazard((
                    "aggregate",
                    "BUILD_MAP",
                    (V2_FAST_ORIGIN_STATIC, summary_value),
                    left[3],
                    True,
                ))
            merged_rows = merge_mapping_entries_by_equivalence((
                *left_entries,
                *right_entries,
            ))
            entries = tuple(sorted(
                merged_rows,
                key=origin_sort_key,
            ))
            if len(entries) > V2_FAST_ORIGIN_RESOLUTION_CAP:
                return V2_FAST_ORIGIN_UNKNOWN
            return register_mapping_exact_json_hazard((
                "aggregate",
                "BUILD_MAP",
                tuple(part for entry in entries for part in entry),
                left[3],
                True,
            ))
        if (
            left
            and right
            and left[0] == right[0] == "nested-function"
            and len(left) == len(right) == 3
            and left[1] is right[1]
            and tuple(flag for flag, _ in left[2])
            == tuple(flag for flag, _ in right[2])
        ):
            return (
                "nested-function",
                left[1],
                tuple(
                    (
                        left_flag,
                        merge_origin(left_value, right_value),
                    )
                    for (left_flag, left_value), (
                        right_flag,
                        right_value,
                    ) in zip(left[2], right[2], strict=True)
                ),
            )
        if (
            left
            and right
            and left[0] == right[0] == "prepared-call"
            and len(left) == len(right) == 4
            and len(left[2]) == len(right[2])
            and left[3] == right[3]
        ):
            return (
                "prepared-call",
                merge_origin(left[1], right[1]),
                tuple(
                    merge_origin(left_arg, right_arg)
                    for left_arg, right_arg in zip(
                        left[2],
                        right[2],
                        strict=True,
                    )
                ),
                left[3],
            )
        if (
            len(left) == len(right) == 3
            and left[0] == right[0] == "derived"
            and left[1] == right[1]
            and left[1] in {"GET_ITER", "GET_YIELD_FROM_ITER"}
        ):
            return (
                "derived",
                left[1],
                merge_origin(left[2], right[2]),
            )
        if max(origin_depth(left), origin_depth(right)) > (
            V2_REFUSAL_STATE_DEPTH_CAP
        ):
            return V2_FAST_ORIGIN_UNKNOWN
        options = origin_options(left) | origin_options(right)
        if V2_FAST_ORIGIN_UNKNOWN in options or len(
            options
        ) > V2_FAST_ORIGIN_RESOLUTION_CAP:
            return V2_FAST_ORIGIN_UNKNOWN
        return (
            "choice",
            tuple(sorted(options, key=origin_sort_key)),
        )

    def merge_origin(
        left: tuple[Any, ...],
        right: tuple[Any, ...],
    ) -> tuple[Any, ...]:
        if left is right:
            return left
        cache_key = (id(left), id(right))
        cached = dict.get(origin_merge_identity_cache, cache_key)
        if (
            cached is not None
            and cached[0] is left
            and cached[1] is right
        ):
            return cached[2]
        result = merge_origin_uncached(left, right)
        if (
            dict.__len__(origin_merge_identity_cache)
            >= origin_cache_entry_cap
        ):
            dict.clear(origin_merge_identity_cache)
        dict.__setitem__(
            origin_merge_identity_cache,
            cache_key,
            (left, right, result),
        )
        return result

    def merge_binding_maps(
        left: Mapping[tuple[str, str], tuple[Any, ...]],
        right: Mapping[tuple[str, str], tuple[Any, ...]],
    ) -> dict[tuple[str, str], tuple[Any, ...]]:
        merged: dict[tuple[str, str], tuple[Any, ...]] = {}
        for key in set(left) | set(right):
            merged[key] = merge_origin(
                left.get(key, V2_FAST_ORIGIN_UNBOUND),
                right.get(key, V2_FAST_ORIGIN_UNBOUND),
            )
        return merged

    def merge_origins(
        values: Iterable[tuple[Any, ...]],
    ) -> tuple[Any, ...]:
        iterator = iter(values)
        try:
            merged = next(iterator)
        except StopIteration:
            return V2_FAST_ORIGIN_UNKNOWN
        for value in iterator:
            merged = merge_origin(merged, value)
        return merged

    def replace_origin_tree(
        value: tuple[Any, ...],
        target: tuple[Any, ...],
        replacement: tuple[Any, ...],
        *,
        depth: int = 0,
    ) -> tuple[Any, ...]:
        if value == target:
            return register_mapping_exact_json_hazard(replacement)
        if depth > V2_REFUSAL_STATE_DEPTH_CAP or type(value) is not tuple:
            return value
        changed = False
        parts: list[Any] = []
        for part in value:
            if type(part) is tuple:
                updated = replace_origin_tree(
                    part,
                    target,
                    replacement,
                    depth=depth + 1,
                )
                changed = changed or updated != part
                parts.append(updated)
            else:
                parts.append(part)
        rebuilt = tuple(parts) if changed else value
        if not (
            len(rebuilt) >= 5
            and rebuilt[0] == "aggregate"
            and rebuilt[1] in {"BUILD_MAP", "BUILD_CONST_KEY_MAP"}
            and origin_carries_exact_json_alias(rebuilt)
        ):
            return rebuilt
        allocation_site = rebuilt[3]

        def mark_alias_references(candidate: Any) -> Any:
            if type(candidate) is not tuple or not candidate:
                return candidate
            if (
                candidate[0] == "aggregate-reference"
                and len(candidate) >= 2
                and candidate[1] == allocation_site
            ):
                return ("aggregate-reference", allocation_site, True)
            candidate_changed = False
            candidate_parts: list[Any] = []
            for candidate_part in candidate:
                updated_part = mark_alias_references(candidate_part)
                candidate_changed = candidate_changed or (
                    updated_part != candidate_part
                )
                candidate_parts.append(updated_part)
            return (
                tuple(candidate_parts)
                if candidate_changed
                else candidate
            )

        return register_mapping_exact_json_hazard(
            mark_alias_references(rebuilt)
        )

    def aggregate_mapping_lookup(
        source: tuple[Any, ...],
        key_origin: tuple[Any, ...],
    ) -> tuple[Any, ...] | None:
        def bounded_value_sources(
            value: tuple[Any, ...],
            allocation_site: tuple[Any, ...],
        ) -> tuple[Any, ...]:
            sources: set[tuple[Any, ...]] = set()
            visited: set[tuple[Any, ...]] = set()

            def visit(candidate: Any, depth: int = 0) -> None:
                if (
                    depth > V2_REFUSAL_STATE_DEPTH_CAP
                    or type(candidate) is not tuple
                    or not candidate
                    or candidate in visited
                ):
                    return
                visited.add(candidate)
                if v2_fast_origin_is_exact_json(candidate):
                    sources.add(candidate)
                    return
                kind = candidate[0]
                if kind == "aggregate-reference":
                    if len(candidate) == 3 and candidate[2] is False:
                        return
                    # True references retain a trusted exact-JSON alias;
                    # malformed/legacy references have no proof of absence.
                    # Keep either as an explicit source so downstream hazard
                    # checks refuse instead of treating the lookup as STATIC.
                    sources.add(candidate)
                    return
                if kind in {
                    "binding",
                    "call-result",
                    "iter-item",
                    "result-access",
                    "subscript",
                    "unpack",
                    "unknown",
                }:
                    sources.add(candidate)
                    return
                if (
                    kind == "attribute"
                    and candidate[1]
                    and candidate[1][0] == "binding"
                ):
                    sources.add(candidate)
                    return
                for part in candidate[1:]:
                    if type(part) is tuple:
                        if part and type(part[0]) is tuple:
                            for nested in part:
                                visit(nested, depth + 1)
                        else:
                            visit(part, depth + 1)

            visit(value)
            if not sources:
                return V2_FAST_ORIGIN_STATIC
            if len(sources) == 1:
                return next(iter(sources))
            return (
                "aggregate",
                "ORIGIN_SUMMARY",
                tuple(sorted(sources, key=origin_sort_key)),
            )

        key_options = origin_options(key_origin)
        exact_key_origins = tuple(
            option
            for option in key_options
            if v2_fast_exact_key_from_origin(option)[0]
        )
        keys_are_exact = bool(key_options) and len(
            exact_key_origins
        ) == len(key_options)
        values: list[tuple[Any, ...]] = []
        for candidate in origin_options(source):
            entries = aggregate_mapping_entries(candidate)
            if entries is None:
                return None
            matched = [
                value
                for stored_key, value in entries
                if not keys_are_exact
                or any(
                    v2_fast_exact_key_equivalent(
                        stored_key,
                        exact_key_origin,
                    ) is not False
                    for exact_key_origin in exact_key_origins
                )
            ]
            if matched:
                merged_matches = merge_origins(matched)
                if len(candidate) >= 5 and candidate[4] is True:
                    merged_matches = bounded_value_sources(
                        merged_matches,
                        candidate[3],
                    )
                values.append(
                    (
                        "aggregate-map-values",
                        candidate[3],
                        merged_matches,
                    )
                    if len(candidate) >= 5 and candidate[4] is True
                    else merged_matches
                )
        return merge_origins(values) if values else None

    def flattened_callable_binding(
        candidate: tuple[Any, ...],
    ) -> tuple[Any, ...] | None:
        if candidate and candidate[0] == "binding":
            return candidate
        if (
            candidate
            and candidate[0] == "attribute"
            and candidate[1]
            and candidate[1][0] == "binding"
        ):
            base = candidate[1]
            return (
                "binding",
                base[1],
                base[2],
                (*base[3], *candidate[2]),
            )
        return None

    def audited_local_fast_result_origin(
        callable_options: set[tuple[Any, ...]],
        arguments: Sequence[tuple[Any, ...]],
        *,
        call_index: int,
        keyword_names: tuple[str, ...] | None,
    ) -> tuple[Any, ...] | None:
        """Return a code-pinned exact result kind for one direct global call."""
        if len(callable_options) != 1:
            return None
        binding = next(iter(callable_options))
        if (
            binding[0:2] != ("binding", "global")
            or len(binding) != 4
            or binding[3] != ()
            or type(binding[2]) is not str
            or type(active_executable_function) is not types.FunctionType
            or type(call_index) is not int
            or call_index < 0
            or keyword_names is None
            or type(keyword_names) is not tuple
            or any(type(name) is not str for name in keyword_names)
        ):
            return None
        call_instruction = instructions[call_index]

        def is_direct_innermost_source(source_index: int) -> bool:
            source_instruction = instructions[source_index]
            if (
                source_instruction.opname not in {"LOAD_GLOBAL", "LOAD_NAME"}
                or source_instruction.argval != binding[2]
            ):
                return False
            path, path_end = v2_instruction_access_path(
                instructions,
                source_index,
            )
            matching_calls = v2_matching_direct_call_indices(
                instructions,
                source_index,
                path_end,
            )
            return bool(
                path == ()
                and matching_calls
                and matching_calls[0] == call_index
            )

        direct_source_indices = tuple(
            source_index
            for source_index in source_call_indices
            if is_direct_innermost_source(source_index)
        )
        if (
            call_instruction.opname == "CALL_FUNCTION_EX"
            or len(direct_source_indices) != 1
            or type(call_instruction.offset) is not int
        ):
            return None
        function_globals = v2_raw_function_attribute(
            active_executable_function,
            "__globals__",
        )
        if type(function_globals) is not dict:
            raise EvidenceFailed(
                "refusal-state audited fast-result globals are not exact"
            )
        bound_candidate = dict.get(function_globals, binding[2])
        contracts = V2_AUDITED_LOCAL_FAST_RESULT_CONTRACTS
        result_kinds = V2_AUDITED_LOCAL_FAST_RESULT_KINDS
        pure_result_contracts = V2_AUDITED_LOCAL_PURE_CALL_RESULT_PATHS
        pure_code_contracts = V2_AUDITED_LOCAL_PURE_CALL_CODE_CONTRACTS
        registry_contract = (
            V2_AUDITED_LOCAL_FAST_RESULT_REGISTRY_CONTRACT
        )
        if (
            type(contracts) is not tuple
            or type(result_kinds) is not frozenset
            or type(registry_contract) is not tuple
            or len(registry_contract) != 2
            or tuple.__getitem__(registry_contract, 0) is not result_kinds
            or tuple.__getitem__(registry_contract, 1) is not contracts
            or type(pure_result_contracts) is not tuple
            or any(
                type(row) is not tuple or len(row) != 2
                for row in tuple.__iter__(pure_result_contracts)
            )
            or type(pure_code_contracts) is not tuple
            or any(
                type(row) is not tuple or len(row) != 2
                for row in tuple.__iter__(pure_code_contracts)
            )
        ):
            raise EvidenceFailed(
                "refusal-state audited fast-result registry is malformed"
            )
        matched_contracts: list[
            tuple[types.FunctionType, types.CodeType, str]
        ] = []
        seen_binding_names: set[str] = set()
        seen_candidate_ids: set[int] = set()
        seen_code_ids: set[int] = set()
        for contract in tuple.__iter__(contracts):
            if type(contract) is not tuple or len(contract) != 4:
                raise EvidenceFailed(
                    "refusal-state audited fast-result row is malformed"
                )
            (
                binding_name,
                candidate,
                pinned_code,
                result_kind,
            ) = contract
            if (
                type(binding_name) is not str
                or not binding_name
                or binding_name in seen_binding_names
                or type(candidate) is not types.FunctionType
                or id(candidate) in seen_candidate_ids
                or type(pinned_code) is not types.CodeType
                or id(pinned_code) in seen_code_ids
                or v2_raw_function_attribute(candidate, "__code__")
                is not pinned_code
                or type(result_kind) is not str
                or result_kind not in result_kinds
                or v2_raw_function_attribute(candidate, "__globals__")
                is not function_globals
                or dict.get(function_globals, binding_name) is not candidate
                or sum(
                    pure_candidate is candidate
                    for pure_candidate, _allowed_paths
                    in pure_result_contracts
                )
                != 1
                or sum(
                    pure_candidate is candidate
                    and pure_code is pinned_code
                    for pure_candidate, pure_code
                    in pure_code_contracts
                )
                != 1
            ):
                raise EvidenceFailed(
                    "refusal-state audited fast-result row identity drifted"
                )
            seen_binding_names.add(binding_name)
            seen_candidate_ids.add(id(candidate))
            seen_code_ids.add(id(pinned_code))
            if (
                binding_name == binding[2]
                and bound_candidate is candidate
            ):
                matched_contracts.append((
                    candidate,
                    pinned_code,
                    result_kind,
                ))
        if not matched_contracts:
            return None
        if len(matched_contracts) != 1:
            raise EvidenceFailed(
                "refusal-state audited fast-result contract is ambiguous"
            )
        _candidate, _pinned_code, result_kind = matched_contracts[0]
        if result_kind in {"exact-json-dict", "exact-json-list"}:
            return (
                "audited-exact-json",
                binding[2],
                result_kind,
                _pinned_code,
                code,
                call_instruction.offset,
            )
        return (
            "protocol-result",
            (f"audited-local:{binding[2]}:{result_kind}",),
            tuple(arguments),
            True,
        )

    def has_direct_attribute_call(
        call_index: int,
        attribute_name: str,
    ) -> bool:
        if any(
            call_index in call_indices
            and v2_instruction_access_path(
                instructions,
                source_index,
            )[0] == (attribute_name,)
            for source_index, call_indices in source_call_indices.items()
        ):
            return True
        # A literal receiver has no preceding named LOAD to seed
        # source_call_indices.  Its LOAD_METHOD/LOAD_ATTR can still be tied
        # directly to this CALL by the same bounded stack-window matcher;
        # storing the callable first breaks that window and remains refused.
        return any(
            instruction.opname in V2_ATTRIBUTE_ACCESS_OPS
            and instruction.argval == attribute_name
            and call_index in v2_matching_direct_call_indices(
                instructions,
                source_index,
                source_index,
            )
            for source_index, instruction in enumerate(instructions)
        )

    def dict_get_result_origin(
        callable_options: set[tuple[Any, ...]],
        arguments: Sequence[tuple[Any, ...]],
        keyword_names: tuple[str, ...] | None,
        *,
        call_index: int,
    ) -> tuple[Any, ...] | None:
        flattened = {
            flattened_callable_binding(candidate)
            for candidate in callable_options
        }
        unbound_call = flattened == {
            ("binding", "global", "dict", ("get",))
        }
        bound_call = bool(callable_options) and all(
            candidate
            and candidate[0] == "attribute"
            and candidate[2] == ("get",)
            and (
                aggregate_mapping_entries(candidate[1]) is not None
                or fresh_base_dict_copy_origin(candidate[1])
            )
            for candidate in callable_options
        )
        if not unbound_call and not bound_call:
            return None
        expected_counts = {2, 3} if unbound_call else {1, 2}
        if keyword_names != () or len(arguments) not in expected_counts:
            dynamic_uses[index].add((
                "invalid-exact-dict-get-call-shape",
                V2_FAST_ORIGIN_STATIC,
            ))
            return None
        if not has_direct_attribute_call(call_index, "get"):
            dynamic_uses[index].add((
                "aliased-exact-dict-get-call",
                V2_FAST_ORIGIN_STATIC,
            ))
            return None
        if unbound_call:
            receiver, key_origin = arguments[:2]
            default_origin = (
                arguments[2]
                if len(arguments) == 3
                else V2_FAST_ORIGIN_STATIC
            )
        else:
            bound_receivers = {
                candidate[1] for candidate in callable_options
            }
            receiver = merge_origins(bound_receivers)
            key_origin = arguments[0]
            default_origin = (
                arguments[1]
                if len(arguments) == 2
                else V2_FAST_ORIGIN_STATIC
            )
        dynamic_uses[index].add(("mapping-key-protocol", receiver))
        snapshot_result_receiver = bool(
            code is v2_fixture_set_process_environment_bytes.__code__
            and receiver
            and receiver[0] == "call-result"
            and receiver[1]
            == (
                "binding",
                "global",
                "v2_bounded_process_environment_bytes_snapshot",
                (),
            )
        )
        if snapshot_result_receiver:
            # The exact private snapshot helper has a separately identity-
            # checked bytes-to-bytes return contract.  Keep the value rooted
            # in that helper instead of treating base ``dict.get`` as a
            # globally pure arbitrary-value factory.
            dynamic_uses[index].add(("call-protocol", key_origin))
            snapshot_value = (
                "result-access",
                receiver,
                ("dict-get-value",),
            )
            return merge_origins((snapshot_value, default_origin))
        if any(
            aggregate_mapping_entries(candidate) is None
            and not fresh_base_dict_copy_origin(candidate)
            for candidate in origin_options(receiver)
        ):
            return None
        # Exact dict lookup still hashes and compares its key.  Retain that
        # operand on the protocol-validation path so a user-defined
        # ``__hash__``/``__eq__`` cannot run during the projected callback.
        dynamic_uses[index].add(("call-protocol", key_origin))

        def exact_receiver_key_presence() -> bool | None:
            key_options = origin_options(key_origin)
            exact_key_origins = tuple(
                option
                for option in key_options
                if v2_fast_exact_key_from_origin(option)[0]
            )
            if (
                len(exact_key_origins) != len(key_options)
                or len(exact_key_origins) != 1
            ):
                return None
            exact_key_origin = exact_key_origins[0]
            receiver_options = origin_options(receiver)
            if not receiver_options:
                return None
            presences: list[bool] = []
            for candidate in receiver_options:
                entries = aggregate_mapping_entries(candidate)
                if (
                    entries is None
                    or len(candidate) < 5
                    or candidate[4] is not False
                ):
                    return None
                equivalences = tuple(
                    v2_fast_exact_key_equivalent(
                        stored_key,
                        exact_key_origin,
                    )
                    for stored_key, _stored_value in entries
                )
                if any(equivalent is None for equivalent in equivalences):
                    return None
                presences.append(any(equivalences))
            if presences and all(presences):
                return True
            if presences and not any(presences):
                return False
            return None

        mapped = aggregate_mapping_lookup(receiver, key_origin)
        if mapped is None:
            key_options = origin_options(key_origin)
            exact_keys = tuple(
                v2_fast_exact_key_from_origin(option)[1]
                for option in key_options
                if v2_fast_exact_key_from_origin(option)[0]
            )
            exact_key = (
                exact_keys[0]
                if len(exact_keys) == 1 and len(key_options) == 1
                else None
            )
            mapped = ("subscript", receiver, exact_key)
        key_presence = exact_receiver_key_presence()
        if key_presence is True:
            return mapped
        if key_presence is False:
            return default_origin
        return merge_origins((mapped, default_origin))

    def dict_copy_result_origin(
        callable_options: set[tuple[Any, ...]],
        arguments: Sequence[tuple[Any, ...]],
        keyword_names: tuple[str, ...] | None,
        *,
        call_index: int,
    ) -> tuple[Any, ...] | None:
        flattened = {
            flattened_callable_binding(candidate)
            for candidate in callable_options
        }
        unbound_call = flattened == {
            ("binding", "global", "dict", ("copy",))
        }
        bound_call = bool(callable_options) and all(
            candidate
            and candidate[0] == "attribute"
            and candidate[2] == ("copy",)
            and aggregate_mapping_entries(candidate[1]) is not None
            for candidate in callable_options
        )
        if not unbound_call and not bound_call:
            if callable_options and all(
                candidate
                and candidate[0] == "attribute"
                and candidate[2] == ("copy",)
                for candidate in callable_options
            ):
                dynamic_uses[index].add((
                    "non-exact-dict-copy-receiver",
                    V2_FAST_ORIGIN_STATIC,
                ))
            return None
        expected_argument_count = 1 if unbound_call else 0
        if (
            keyword_names != ()
            or len(arguments) != expected_argument_count
        ):
            dynamic_uses[index].add((
                "invalid-exact-dict-copy-call-shape",
                V2_FAST_ORIGIN_STATIC,
            ))
            return None
        if not has_direct_attribute_call(call_index, "copy"):
            dynamic_uses[index].add((
                "aliased-exact-dict-copy-call",
                V2_FAST_ORIGIN_STATIC,
            ))
            return None
        receivers = (
            tuple(origin_options(arguments[0]))
            if unbound_call
            else tuple(candidate[1] for candidate in callable_options)
        )
        snapshots: list[tuple[Any, ...]] = []
        for receiver in receivers:
            entries = aggregate_mapping_entries(receiver)
            if entries is None:
                snapshots.append((
                    "dict-copy",
                    receiver,
                    ("copy-allocation-site", call_index),
                ))
                continue
            snapshots.append((
                "aggregate",
                "BUILD_MAP",
                tuple(part for entry in entries for part in entry),
                ("copy-allocation-site", call_index),
                (
                    receiver[4]
                    if len(receiver) >= 5
                    else False
                ),
            ))
        return merge_origins(snapshots) if snapshots else None

    def dict_items_result_origin(
        callable_options: set[tuple[Any, ...]],
        arguments: Sequence[tuple[Any, ...]],
        keyword_names: tuple[str, ...] | None,
        *,
