        if unbound_call:
            receivers = tuple(origin_options(arguments[0]))
        else:
            receivers = tuple(
                candidate[1] for candidate in callable_options
            )
        direct_source = has_direct_attribute_call(call_index, "items")
        if not direct_source:
            dynamic_uses[index].add((
                "aliased-exact-dict-view-call",
                (
                    "aggregate",
