                        callable_options,
                        key=origin_sort_key,
                    )),
                ),
            ))
            return None
        results: list[tuple[Any, ...]] = []
        for receiver in receivers:
            if aggregate_mapping_entries(receiver) is None:
                return None
            results.append((
                "dict-view",
                "items",
                receiver,
            ))
        return merge_origins(results) if results else None

    def dict_values_result_origin(
        callable_options: set[tuple[Any, ...]],
        arguments: Sequence[tuple[Any, ...]],
        keyword_names: tuple[str, ...] | None,
        *,
        call_index: int,
    ) -> tuple[Any, ...] | None:
        flattened = {
            flattened_callable_binding(candidate)
            for candidate in callable_options
        }
        receivers: tuple[tuple[Any, ...], ...]
        unbound_call = flattened == {
            ("binding", "global", "dict", ("values",))
        }
        bound_call = bool(callable_options) and all(
            candidate
            and candidate[0] == "attribute"
            and candidate[2] == ("values",)
            and aggregate_mapping_entries(candidate[1]) is not None
            for candidate in callable_options
        )
        if not unbound_call and not bound_call:
            return None
        expected_argument_count = 1 if unbound_call else 0
        if (
            keyword_names != ()
            or len(arguments) != expected_argument_count
        ):
            dynamic_uses[index].add((
                "invalid-exact-dict-view-call-shape",
                V2_FAST_ORIGIN_STATIC,
            ))
            return None
        if unbound_call:
            receivers = tuple(origin_options(arguments[0]))
        else:
            receivers = tuple(
                candidate[1] for candidate in callable_options
            )
        direct_source = has_direct_attribute_call(call_index, "values")
        if not direct_source:
            # Exact receiver provenance is not enough to bless a callable
            # saved and invoked later.  Require the ``.values`` source load
            # itself to be in this CALL's direct, position-bound window.
            dynamic_uses[index].add((
                "aliased-exact-dict-view-call",
                (
                    "aggregate",
                    "CALLABLE_OPTIONS",
                    tuple(sorted(
                        callable_options,
                        key=origin_sort_key,
                    )),
                ),
            ))
            return None
        results: list[tuple[Any, ...]] = []
        for receiver in receivers:
            if aggregate_mapping_entries(receiver) is None:
                return None
