                "dict-view",
                "values",
                receiver,
            ))
        return merge_origins(results) if results else None

    def dict_getitem_result_origin(
        callable_options: set[tuple[Any, ...]],
        arguments: Sequence[tuple[Any, ...]],
        keyword_names: tuple[str, ...] | None,
        *,
        call_index: int,
    ) -> tuple[Any, ...] | None:
        flattened = {
            flattened_callable_binding(candidate)
            for candidate in callable_options
        }
        if flattened != {
            ("binding", "global", "dict", ("__getitem__",))
        }:
            return None
        if keyword_names != () or len(arguments) != 2:
            dynamic_uses[index].add((
                "invalid-exact-getitem-call-shape",
                V2_FAST_ORIGIN_STATIC,
            ))
            return None
        if not has_direct_attribute_call(call_index, "__getitem__"):
            dynamic_uses[index].add((
                "aliased-exact-getitem-call",
                V2_FAST_ORIGIN_STATIC,
            ))
            return None
        receiver, key_origin = arguments
        # ``dict.__getitem__`` may dispatch ``__hash__``/``__eq__`` on a
        # dynamic key even when the receiver is an exact local mapping.  Keep
        # that key on the ordinary protocol-validation path; exact inert
        # str/int keys remain admissible while hook-bearing values fail
        # closed before the projected helper is executed.
        dynamic_uses[index].add(("call-protocol", key_origin))
        dynamic_uses[index].add(("mapping-key-protocol", receiver))
        if any(
            aggregate_mapping_entries(candidate) is None
            for candidate in origin_options(receiver)
        ):
            return None
        mapped = aggregate_mapping_lookup(receiver, key_origin)
        return mapped if mapped is not None else V2_FAST_ORIGIN_STATIC

    def list_getitem_result_origin(
        callable_options: set[tuple[Any, ...]],
        arguments: Sequence[tuple[Any, ...]],
        keyword_names: tuple[str, ...] | None,
        *,
        call_index: int,
    ) -> tuple[Any, ...] | None:
        flattened = {
            flattened_callable_binding(candidate)
            for candidate in callable_options
        }
        if flattened != {
            ("binding", "global", "list", ("__getitem__",))
        }:
            return None
        if keyword_names != () or len(arguments) != 2:
            dynamic_uses[index].add((
                "invalid-exact-getitem-call-shape",
                V2_FAST_ORIGIN_STATIC,
            ))
            return None
        if not has_direct_attribute_call(call_index, "__getitem__"):
            dynamic_uses[index].add((
                "aliased-exact-getitem-call",
                V2_FAST_ORIGIN_STATIC,
            ))
            return None
        receiver, key_origin = arguments
        # A dynamic list index can dispatch ``__index__``.  The exact element
        # projection below is therefore conditional on the same bounded
        # protocol check used by other audited built-in calls.
        dynamic_uses[index].add(("call-protocol", key_origin))
        key_options = origin_options(key_origin)
        exact_indices = {
            int(candidate[1])
            for candidate in key_options
            if candidate
            and candidate[0] == "constant"
            and type(candidate[1]) in {bool, int}
        }
        results: list[tuple[Any, ...]] = []
        for candidate in origin_options(receiver):
            if not (
                len(candidate) >= 5
                and candidate[0] == "aggregate"
                and candidate[1] == "BUILD_LIST"
            ):
                return None
            if (
                candidate[4] is False
                and len(exact_indices) == len(key_options) == 1
            ):
                selected_index = next(iter(exact_indices))
                if (
                    -len(candidate[2])
                    <= selected_index
                    < len(candidate[2])
                ):
                    results.append(candidate[2][selected_index])
                    continue
                results.append(V2_FAST_ORIGIN_STATIC)
                continue
            # LIST_APPEND/LIST_EXTEND deliberately turn a list into an
            # unordered possibility summary (marker True).  Its members are
            # complete provenance possibilities but no longer occupy known
            # positions, so an exact numeric index must not select one of
            # them.  Merge every possible member instead; downstream callable
            # resolution will reject ambiguity when those members differ.
            results.append(
                merge_origins(candidate[2])
                if candidate[2]
                else V2_FAST_ORIGIN_STATIC
            )
        return merge_origins(results) if results else V2_FAST_ORIGIN_STATIC

    def exact_base_len_result_origin(
        callable_options: set[tuple[Any, ...]],
        arguments: Sequence[tuple[Any, ...]],
        keyword_names: tuple[str, ...] | None,
        *,
        call_index: int,
    ) -> tuple[Any, ...] | None:
        flattened = {
            flattened_callable_binding(candidate)
            for candidate in callable_options
        }
        if frozenset(flattened) not in {
            frozenset({("binding", "global", "dict", ("__len__",))}),
            frozenset({("binding", "global", "list", ("__len__",))}),
        }:
            return None
        if (
            keyword_names != ()
            or len(arguments) != 1
            or not has_direct_attribute_call(call_index, "__len__")
        ):
            return None
        # Calling an exact base descriptor either raises without dispatching
        # user code or returns a built-in int.  Do not retain the receiver as
        # an alias of that scalar result.
        return V2_FAST_ORIGIN_STATIC

    def exact_container_method_result_origin(
        callable_options: set[tuple[Any, ...]],
        arguments: Sequence[tuple[Any, ...]],
    ) -> tuple[Any, ...] | None:
        if not callable_options or not all(
            candidate
            and candidate[0] == "attribute"
            and candidate[2] == ("issubset",)
            and candidate[1]
            and candidate[1][0] == "protocol-result"
            and candidate[1][1] == ("set",)
            for candidate in callable_options
        ):
            return None
        for argument in arguments:
            dynamic_uses[index].add(("call-protocol", argument))
        return (
            "protocol-result",
            ("set.issubset",),
            tuple(arguments),
            True,
        )

    def nested_comprehension_result_origin(
        callable_options: set[tuple[Any, ...]],
        arguments: Sequence[tuple[Any, ...]],
        keyword_names: tuple[str, ...] | None,
    ) -> tuple[Any, ...] | None:
        """Summarize exact built-in comprehension containers by provenance."""
        if (
            not callable_options
            or keyword_names not in {(), None}
            or any(
                not candidate
                or candidate[0] != "nested-function"
                or candidate[1].co_name not in {"<dictcomp>", "<listcomp>"}
                for candidate in callable_options
            )
        ):
            return None
        cache_key = (
            tuple(sorted(callable_options, key=origin_sort_key)),
            tuple(arguments),
            keyword_names,
        )
        if cache_key in nested_container_result_cache:
            return nested_container_result_cache[cache_key]
        results: list[tuple[Any, ...]] = []
        # Insert a conservative sentinel before recursion so a deliberately
        # recursive nested-code graph cannot recurse without bound.
        nested_container_result_cache[cache_key] = None
        for candidate in callable_options:
            nested_code = candidate[1]
            parameter_layout = dict(v2_code_parameter_layout(nested_code))
            if (
                len(arguments) != 1
                or len(parameter_layout) != 1
                or nested_code.co_argcount != 1
                or nested_code.co_kwonlyargcount
            ):
                return None
            parameter_name = next(iter(parameter_layout))
            nested_data = v2_fast_local_origin_dataflow(
                v2_analysis_instructions(nested_code),
                nested_code,
                parameter_origins={parameter_name: arguments[0]},
                freevar_origins=v2_nested_function_freevar_origins(
                    nested_code,
                    (candidate,),
                ),
                _nested_depth=_nested_depth + 1,
            )
            nested_returns = nested_data["return_expressions"]
            expected_kind = (
                "BUILD_MAP"
                if nested_code.co_name == "<dictcomp>"
                else "BUILD_LIST"
            )
            if (
                not nested_returns
                or any(
                    not expression
                    or expression[0] != "aggregate"
                    or expression[1] != expected_kind
                    for expression in nested_returns
                )
            ):
                return None
            qualified_returns = tuple(
                replace_origin_tree(
                    expression,
                    expression[3],
                    (
                        "nested-allocation-site",
                        nested_code,
                        expression[3],
                    ),
                )
                for expression in nested_returns
            )
            results.append(merge_origins(qualified_returns))
        result = merge_origins(results) if results else None
        nested_container_result_cache[cache_key] = result
        return result

    def merge_states(
        prior: tuple[
            tuple[tuple[Any, ...], ...],
            dict[tuple[str, str], tuple[Any, ...]],
            frozenset[tuple[Any, ...]],
        ],
        incoming: tuple[
            tuple[tuple[Any, ...], ...],
            dict[tuple[str, str], tuple[Any, ...]],
            frozenset[tuple[Any, ...]],
        ],
    ) -> tuple[
        tuple[tuple[Any, ...], ...],
        dict[tuple[str, str], tuple[Any, ...]],
        frozenset[tuple[Any, ...]],
    ]:
        prior_stack, prior_bindings, prior_invalidations = prior
        next_stack, next_bindings, next_invalidations = incoming
        if len(prior_stack) != len(next_stack):
            aligned_height = min(
                code.co_stacksize,
                max(len(prior_stack), len(next_stack)),
            )
            padded_prior = (
                (V2_FAST_ORIGIN_UNKNOWN,) * (
                    aligned_height - min(aligned_height, len(prior_stack))
                )
                + prior_stack[-aligned_height:]
            )
            padded_next = (
                (V2_FAST_ORIGIN_UNKNOWN,) * (
                    aligned_height - min(aligned_height, len(next_stack))
                )
                + next_stack[-aligned_height:]
            )
            merged_stack = tuple(
                merge_origin(left, right)
                for left, right in zip(
                    padded_prior,
                    padded_next,
                    strict=True,
                )
            )
        else:
            merged_stack = tuple(
                merge_origin(left, right)
                for left, right in zip(
                    prior_stack,
                    next_stack,
                    strict=True,
                )
            )
        return (
            merged_stack,
            merge_binding_maps(prior_bindings, next_bindings),
            prior_invalidations | next_invalidations,
        )

    offset_to_index: dict[int, int] = {}
    for index, instruction in enumerate(instructions):
        offset_to_index.setdefault(instruction.offset, index)

    exception_successors: defaultdict[
        int,
        list[tuple[int, int, bool]],
    ] = defaultdict(list)
    try:
        exception_entries = tuple(dis.Bytecode(code).exception_entries)
    except (AttributeError, TypeError, ValueError):
        exception_entries = ()
    for entry in exception_entries:
        target_index = offset_to_index.get(entry.target)
        if target_index is None:
            continue
        for index, instruction in enumerate(instructions):
            if entry.start <= instruction.offset < entry.end:
                exception_successors[index].append((
                    target_index,
                    entry.depth,
                    bool(entry.lasti),
                ))

    def jump_target_index(
        instruction: V2AnalysisInstruction,
    ) -> int | None:
        target = instruction.argval
        if type(target) is not int:
            target = getattr(target, "offset", None)
        return offset_to_index.get(target) if type(target) is int else None

    def edge_stack_effect(
        instruction: V2AnalysisInstruction,
        *,
        jump: bool,
    ) -> int | None:
        opcode = dis.opmap.get(instruction.opname)
        if opcode is None:
            return None
        try:
            if instruction.arg is None:
                return dis.stack_effect(opcode, jump=jump)
            return dis.stack_effect(opcode, instruction.arg, jump=jump)
        except (TypeError, ValueError):
            return None

    def adjusted_stack(
        stack: Sequence[tuple[Any, ...]],
        effect: int | None,
    ) -> tuple[tuple[Any, ...], ...]:
        if effect is None:
            return (V2_FAST_ORIGIN_UNKNOWN,) * len(stack)
        target_height = max(0, len(stack) + effect)
        if target_height <= len(stack):
            return tuple(stack[:target_height])
        return (
            *tuple(stack),
            *(
                V2_FAST_ORIGIN_UNKNOWN
                for _index in range(target_height - len(stack))
            ),
        )

    def binding_key(
        opname: str,
        name: str,
    ) -> tuple[str, str]:
        if opname in {"LOAD_GLOBAL", "LOAD_NAME", "STORE_GLOBAL", "STORE_NAME"}:
            return ("global", name)
        if name in code.co_cellvars:
            return ("fast", name)
        if name in code.co_freevars:
            return ("freevar", name)
        return ("fast", name)

    def binding_default(key: tuple[str, str]) -> tuple[Any, ...]:
        kind, name = key
        if kind == "global":
            return v2_fast_origin_binding("global", name)
        if kind == "freevar":
            return v2_fast_origin_binding("freevar", name)
        return V2_FAST_ORIGIN_UNBOUND

    def member_invalidated(
        base: tuple[Any, ...],
        member: tuple[Any, ...],
        invalidations: frozenset[tuple[Any, ...]],
    ) -> bool:
        return any(
            (candidate, member) in invalidations
            for candidate in origin_options(base)
        )

    expected_stack_heights: dict[int, int] = {0: 0}
    height_worklist: deque[int] = deque([0])

    def record_expected_height(target: int | None, height: int) -> None:
        if target is None or not 0 <= target < len(instructions):
            return
        bounded_height = min(code.co_stacksize, max(0, height))
        prior_height = expected_stack_heights.get(target)
        if prior_height is None:
            expected_stack_heights[target] = bounded_height
            height_worklist.append(target)
        elif prior_height != bounded_height:
            # Valid CPython control-flow joins have one concrete height.  A
            # disagreement can arise only at a normalized adaptive opcode or
            # conservative exception edge, so retain the shallower verified
            # suffix instead of allowing a fictitious stack-growth cycle.
            merged_height = min(prior_height, bounded_height)
            if merged_height != prior_height:
                expected_stack_heights[target] = merged_height
                height_worklist.append(target)

    while height_worklist:
        height_index = height_worklist.popleft()
        height_instruction = instructions[height_index]
        input_height = expected_stack_heights[height_index]
        height_opname = height_instruction.opname
        if height_opname.startswith("POP_JUMP"):
            record_expected_height(
                jump_target_index(height_instruction),
                input_height + (
                    edge_stack_effect(height_instruction, jump=True) or 0
                ),
            )
            record_expected_height(
                height_index + 1,
                input_height + (
                    edge_stack_effect(height_instruction, jump=False) or 0
                ),
            )
        elif height_opname.startswith("JUMP_IF"):
            record_expected_height(
                jump_target_index(height_instruction),
                input_height + (
                    edge_stack_effect(height_instruction, jump=True) or 0
                ),
            )
            record_expected_height(
                height_index + 1,
                input_height + (
                    edge_stack_effect(height_instruction, jump=False) or 0
                ),
            )
        elif height_opname in {"FOR_ITER", "SEND"}:
            record_expected_height(
                jump_target_index(height_instruction),
                input_height + (
                    edge_stack_effect(height_instruction, jump=True) or 0
                ),
            )
            record_expected_height(
                height_index + 1,
                input_height + (
                    edge_stack_effect(height_instruction, jump=False) or 0
                ),
            )
        elif height_opname.startswith("JUMP"):
            record_expected_height(
                jump_target_index(height_instruction),
                input_height + (
                    edge_stack_effect(height_instruction, jump=True) or 0
                ),
            )
        elif height_opname not in {
            "RAISE_VARARGS",
            "RERAISE",
            "RETURN_CONST",
            "RETURN_VALUE",
        }:
            record_expected_height(
                height_index + 1,
                input_height + (
                    v2_fast_origin_stack_effect(height_instruction) or 0
                ),
            )
        for target, handler_depth, handler_lasti in exception_successors.get(
            height_index,
            (),
        ):
            record_expected_height(
                target,
                handler_depth + 1 + int(handler_lasti),
            )

    states: dict[
        int,
        tuple[
            tuple[tuple[Any, ...], ...],
            dict[tuple[str, str], tuple[Any, ...]],
            frozenset[tuple[Any, ...]],
        ],
    ] = {0: ((), dict(initial_bindings), frozenset())}
    worklist: deque[int] = deque([0])
    queued = {0}
    updates = 0
    update_cap = max(256, len(instructions) * 96)

    def queue_state(
        target: int | None,
        state: tuple[
            tuple[tuple[Any, ...], ...],
            dict[tuple[str, str], tuple[Any, ...]],
            frozenset[tuple[Any, ...]],
        ],
    ) -> None:
        nonlocal updates
        if target is None or not 0 <= target < len(instructions):
            return
        expected_height = expected_stack_heights.get(target)
        if expected_height is not None and len(state[0]) != expected_height:
            retained = state[0][-expected_height:] if expected_height else ()
            state = (
                (
                    (V2_FAST_ORIGIN_UNKNOWN,) * (
                        expected_height - len(retained)
                    )
                    + retained
                ),
                state[1],
                state[2],
            )
        prior = states.get(target)
        if prior is not None and (prior is state or prior == state):
            return
        merged = state if prior is None else merge_states(prior, state)
        if prior == merged:
            return
        states[target] = merged
        updates += 1
        if updates > update_cap:
            changed_bindings = sorted(
                f"{kind}:{name}"
                for kind, name in set(prior[1]) | set(merged[1])
                if prior[1].get((kind, name))
                != merged[1].get((kind, name))
            ) if prior is not None else []
            raise EvidenceFailed(
                "refusal-state fast-local CFG exceeds its convergence cap "
                f"in {code.co_qualname} on edge {index}->{target}; "
                f"stack_changed={prior is None or prior[0] != merged[0]}, "
                f"stack_heights={None if prior is None else len(prior[0])}"
                f"->{len(merged[0])}, "
                "stack_shapes="
                f"{[(item[0] if item else 'empty', origin_depth(item)) for item in merged[0]][:8]}, "
                f"binding_changes={changed_bindings[:8]}, "
                "invalidation_changed="
                f"{prior is None or prior[2] != merged[2]}"
            )
        if target not in queued:
            queued.add(target)
            worklist.append(target)

