    def exact_global_binding_path(
        candidate: tuple[Any, ...],
    ) -> tuple[str, tuple[str, ...]] | None:
        if (
            candidate
            and candidate[0] == "binding"
            and candidate[1] == "global"
        ):
            return candidate[2], candidate[3]
        if (
            candidate
            and candidate[0] == "attribute"
            and candidate[1]
            and candidate[1][0] == "binding"
            and candidate[1][1] == "global"
        ):
            base = candidate[1]
            return base[2], (*base[3], *candidate[2])
        return None

