    def fresh_base_dict_copy_origin(candidate: tuple[Any, ...]) -> bool:
        """Recognize a fresh plain-dict result even when contents are opaque."""
        return bool(
            candidate
            and (
                candidate[0] == "dict-copy"
                or (
                    candidate[0] == "call-result"
                    and len(candidate) >= 2
                    and flattened_callable_binding(candidate[1])
                    == ("binding", "global", "dict", ("copy",))
                )
            )
        )

    def exact_dict_setitem_replacements(
        callable_options: set[tuple[Any, ...]],
        arguments: Sequence[tuple[Any, ...]],
        keyword_names: tuple[str, ...] | None,
    ) -> tuple[
        bool,
        tuple[tuple[tuple[Any, ...], tuple[Any, ...]], ...],
    ]:
        flattened = {
            flattened_callable_binding(candidate)
            for candidate in callable_options
        }
        unbound_call = flattened == {
            ("binding", "global", "dict", ("__setitem__",))
        }
        bound_call = bool(callable_options) and all(
            candidate
            and candidate[0] == "attribute"
            and candidate[2] == ("__setitem__",)
            and aggregate_mapping_entries(candidate[1]) is not None
            for candidate in callable_options
        )
        if not unbound_call and not bound_call:
            return False, ()
        expected_argument_count = 3 if unbound_call else 2
        if (
            keyword_names != ()
            or len(arguments) != expected_argument_count
        ):
            dynamic_uses[index].add((
                "invalid-exact-dict-mutation-call-shape",
                V2_FAST_ORIGIN_STATIC,
            ))
            return True, ()
        receivers = (
            tuple(origin_options(arguments[0]))
            if unbound_call
            else tuple(candidate[1] for candidate in callable_options)
        )
        if receivers:
            dynamic_uses[index].add((
                "mapping-key-protocol",
                merge_origins(receivers),
            ))
        key_origin, stored_value = (
            arguments[1],
            arguments[2],
        ) if unbound_call else (
            arguments[0],
            arguments[1],
        )
        dynamic_uses[index].add(("call-protocol", key_origin))
        replacements: list[
            tuple[tuple[Any, ...], tuple[Any, ...]]
        ] = []
        for receiver in receivers:
            summarized_assertion_projection = (
                len(receiver) >= 5
                and receiver[0] == "aggregate"
                and receiver[1]
                in {"BUILD_MAP", "BUILD_CONST_KEY_MAP"}
                and receiver[4] is True
                and active_executable_function
                is V2_ASSERTION_EVIDENCE_PROJECTOR_CONTRACT[0]
                and code is V2_ASSERTION_EVIDENCE_PROJECTOR_CONTRACT[1]
            )
            if not (
                len(receiver) >= 5
                and receiver[0] == "aggregate"
                and receiver[1]
                in {"BUILD_MAP", "BUILD_CONST_KEY_MAP"}
                and (
                    receiver[4] is False
                    or summarized_assertion_projection
                )
            ):
                return False, ()
            updated = append_aggregate_mapping_entry(
                receiver,
                key_origin,
                stored_value,
            )
            if updated == V2_FAST_ORIGIN_UNKNOWN:
                # An unchanged receiver would erase the newly stored value from
                # the post-mutation graph. Fall back to the unmodeled-mutation
                # path, which retains the callable, receiver, key, and value.
                return False, ()
            replacements.append((receiver, updated))
        return True, tuple(replacements)

    def exact_list_setitem_replacements(
        callable_options: set[tuple[Any, ...]],
        arguments: Sequence[tuple[Any, ...]],
        keyword_names: tuple[str, ...] | None,
    ) -> tuple[
        bool,
        tuple[tuple[tuple[Any, ...], tuple[Any, ...]], ...],
    ]:
        """Model a direct base-list write only on fixed local allocations."""
        flattened = {
            flattened_callable_binding(candidate)
            for candidate in callable_options
        }
        if flattened != {
            ("binding", "global", "list", ("__setitem__",))
        }:
            return False, ()
        if keyword_names != () or len(arguments) != 3:
            dynamic_uses[index].add((
                "invalid-exact-list-mutation-call-shape",
                V2_FAST_ORIGIN_STATIC,
            ))
            return False, ()
        receiver, key_origin, stored_value = arguments
        key_options = origin_options(key_origin)
        exact_indices = {
            int(candidate[1])
            for candidate in key_options
            if candidate
            and candidate[0] == "constant"
            and type(candidate[1]) in {bool, int}
        }
        if len(exact_indices) != len(key_options) or not exact_indices:
            dynamic_uses[index].add(("call-protocol", key_origin))
            return False, ()
        replacements: list[
            tuple[tuple[Any, ...], tuple[Any, ...]]
        ] = []
        for candidate in origin_options(receiver):
            if not (
                len(candidate) >= 5
                and candidate[0] == "aggregate"
                and candidate[1] == "BUILD_LIST"
                and candidate[4] is False
            ):
                return False, ()
            updated_candidates = {
                replace_aggregate_list_item(
                    candidate,
                    v2_fast_constant_origin(exact_index),
                    stored_value,
                )
                for exact_index in exact_indices
            }
            if (
                V2_FAST_ORIGIN_UNKNOWN in updated_candidates
                or len(updated_candidates) != 1
            ):
                return False, ()
            replacements.append((candidate, next(iter(updated_candidates))))
        return bool(replacements), tuple(replacements)

    def record_exact_dict_contains_protocol(
        callable_options: set[tuple[Any, ...]],
        arguments: Sequence[tuple[Any, ...]],
        keyword_names: tuple[str, ...] | None,
    ) -> None:
        flattened = {
            flattened_callable_binding(candidate)
            for candidate in callable_options
        }
        unbound_call = flattened == {
            ("binding", "global", "dict", ("__contains__",))
        }
        bound_call = bool(callable_options) and all(
            candidate
            and candidate[0] == "attribute"
            and candidate[2] == ("__contains__",)
            for candidate in callable_options
        )
        if keyword_names != ():
            return
        if unbound_call and len(arguments) == 2:
            receiver, key_origin = arguments
        elif bound_call and len(arguments) == 1:
            receiver = merge_origins(
                candidate[1] for candidate in callable_options
            )
            key_origin = arguments[0]
        else:
            return
        dynamic_uses[index].add(("mapping-key-protocol", receiver))
        dynamic_uses[index].add(("call-protocol", key_origin))

    def record_possible_dict_keyed_method_protocol(
        callable_options: set[tuple[Any, ...]],
        arguments: Sequence[tuple[Any, ...]],
        keyword_names: tuple[str, ...] | None,
    ) -> None:
        """Retain receiver-key validation without assuming custom semantics."""
        if keyword_names != () or not callable_options:
            return
        keyed_names = frozenset({
            "__contains__",
            "__delitem__",
            "__getitem__",
            "__setitem__",
            "get",
            "pop",
            "setdefault",
        })
        flattened = {
            flattened_callable_binding(candidate)
            for candidate in callable_options
        }
        unbound_names = {
            path[0]
            for candidate in flattened
            if candidate is not None
            for namespace, path in ((candidate[2], candidate[3]),)
            if namespace == "dict"
            and len(path) == 1
            and path[0] in keyed_names
        }
        if len(unbound_names) == 1 and len(arguments) >= 2:
            receiver = arguments[0]
            key_origin = arguments[1]
        else:
            bound_names = {
                candidate[2][0]
                for candidate in callable_options
                if candidate
                and candidate[0] == "attribute"
                and len(candidate[2]) == 1
                and candidate[2][0] in keyed_names
                and not (
                    candidate[1]
                    and candidate[1][0] == "binding"
                    and candidate[1][1] == "global"
                    and not candidate[1][3]
                    and candidate[1][2] in {
                        "bytearray",
                        "bytes",
                        "dict",
                        "frozenset",
                        "list",
                        "range",
                        "set",
                        "str",
                        "tuple",
                    }
                )
            }
            if len(bound_names) != 1 or not arguments:
                return
            receiver = merge_origins(
                candidate[1] for candidate in callable_options
            )
            key_origin = arguments[0]
        dynamic_uses[index].add(("mapping-key-protocol", receiver))
        dynamic_uses[index].add(("call-protocol", key_origin))

    def exact_dict_pop_effect(
        callable_options: set[tuple[Any, ...]],
        arguments: Sequence[tuple[Any, ...]],
        keyword_names: tuple[str, ...] | None,
    ) -> tuple[
        bool,
        tuple[tuple[tuple[Any, ...], tuple[Any, ...]], ...],
        tuple[Any, ...] | None,
    ]:
        """Model exact local pop, including removal and returned provenance."""
        flattened = {
            flattened_callable_binding(candidate)
            for candidate in callable_options
        }
        unbound_call = flattened == {
            ("binding", "global", "dict", ("pop",))
        }
        bound_call = bool(callable_options) and all(
            candidate
            and candidate[0] == "attribute"
            and candidate[2] == ("pop",)
            and (
                aggregate_mapping_entries(candidate[1]) is not None
                or fresh_base_dict_copy_origin(candidate[1])
                or exact_protocol_container(candidate[1], "dict")
            )
            for candidate in callable_options
        )
        if not unbound_call and not bound_call:
            return False, (), None
        expected_counts = {2, 3} if unbound_call else {1, 2}
        if keyword_names != () or len(arguments) not in expected_counts:
            dynamic_uses[index].add((
                "invalid-exact-dict-mutation-call-shape",
                V2_FAST_ORIGIN_STATIC,
            ))
            return True, (), V2_FAST_ORIGIN_UNKNOWN
        receivers = (
            tuple(origin_options(arguments[0]))
            if unbound_call
            else tuple(candidate[1] for candidate in callable_options)
        )
        if receivers:
            dynamic_uses[index].add((
                "mapping-key-protocol",
                merge_origins(receivers),
            ))
        key_index = 1 if unbound_call else 0
        default_index = 2 if unbound_call else 1
        key_origin = arguments[key_index]
        dynamic_uses[index].add(("call-protocol", key_origin))
        default_origin = (
            arguments[default_index]
            if len(arguments) > default_index
            else None
        )
        key_options = origin_options(key_origin)
        exact_key_origins = tuple(
            option
            for option in key_options
            if v2_fast_exact_key_from_origin(option)[0]
        )
        if (
            len(exact_key_origins) != len(key_options)
            or len(exact_key_origins) != 1
        ):
            conservative_replacements: list[
                tuple[tuple[Any, ...], tuple[Any, ...]]
            ] = []
            for receiver in receivers:
                if (
                    aggregate_mapping_entries(receiver) is None
                    and not fresh_base_dict_copy_origin(receiver)
                    and not exact_protocol_container(receiver, "dict")
                ):
                    return False, (), None
                conservative_replacements.append((receiver, receiver))
            return (
                True,
                tuple(conservative_replacements),
                V2_FAST_ORIGIN_UNKNOWN,
            )
        exact_key_origin = exact_key_origins[0]
        exact_key = v2_fast_exact_key_from_origin(exact_key_origin)[1]
        replacements: list[
            tuple[tuple[Any, ...], tuple[Any, ...]]
        ] = []
        results: list[tuple[Any, ...]] = []
        for receiver in receivers:
            if fresh_base_dict_copy_origin(receiver):
                replacements.append((receiver, receiver))
                mapped = ("subscript", receiver, exact_key)
                results.append(
                    merge_origins((mapped, default_origin))
                    if default_origin is not None
                    else mapped
                )
                continue
            entries = aggregate_mapping_entries(receiver)
            if entries is None or len(receiver) < 5:
                return False, (), None
            if receiver[4] is True:
                replacements.append((receiver, receiver))
                results.append(V2_FAST_ORIGIN_UNKNOWN)
                continue
            retained: list[
                tuple[tuple[Any, ...], tuple[Any, ...]]
            ] = []
            removed: list[tuple[Any, ...]] = []
            for stored_key, stored_value in entries:
                equivalent = v2_fast_exact_key_equivalent(
                    stored_key,
                    exact_key_origin,
                )
                if equivalent is None:
                    return False, (), None
                if equivalent:
                    removed.append(stored_value)
                else:
                    retained.append((stored_key, stored_value))
            updated_receiver = (
                "aggregate",
                "BUILD_MAP",
                tuple(part for entry in retained for part in entry),
                receiver[3],
                False,
            )
            replacements.append((receiver, updated_receiver))
            if removed:
                results.append(merge_origins(removed))
            elif default_origin is not None:
                results.append(default_origin)
            else:
                results.append(V2_FAST_ORIGIN_STATIC)
        return (
            True,
            tuple(replacements),
            merge_origins(results) if results else V2_FAST_ORIGIN_STATIC,
        )

    def modeled_bound_list_append_targets(
        callable_options: set[tuple[Any, ...]],
        arguments: Sequence[tuple[Any, ...]],
        keyword_names: tuple[str, ...] | None,
    ) -> set[tuple[Any, ...]]:
        """Return the sole exact list mutated by a modeled bound append."""
        if (
            not callable_options
            or keyword_names != ()
            or len(arguments) != 1
            or any(
                not candidate
                or candidate[0] != "attribute"
                or candidate[2] != ("append",)
                or len(candidate[1]) < 5
                or candidate[1][0] != "aggregate"
                or candidate[1][1] != "BUILD_LIST"
                for candidate in callable_options
            )
        ):
            return set()
        targets = {candidate[1] for candidate in callable_options}
        return targets if len(targets) == 1 else set()

    def exact_protocol_container(
        candidate: tuple[Any, ...],
        container_name: str,
    ) -> bool:
        return bool(
            candidate
            and candidate[0] == "protocol-result"
            and container_name in candidate[1]
        )

    def unmodeled_mutator_call(
        callable_options: set[tuple[Any, ...]],
        arguments: Sequence[tuple[Any, ...]],
        keyword_names: tuple[str, ...] | None,
        *,
        recognized_dict_setitem: bool,
        recognized_dict_pop: bool,
        recognized_list_setitem: bool,
    ) -> bool:
        modeled_append_targets = modeled_bound_list_append_targets(
            callable_options,
            arguments,
            keyword_names,
        )
        for candidate in callable_options:
            binding_path = exact_global_binding_path(candidate)
            if (
                candidate
                and candidate[0] == "attribute"
                and candidate[2]
                and candidate[2][0]
                in {
                    *dict_mutator_names,
                    *list_mutator_names,
                    *set_mutator_names,
                    *bytearray_mutator_names,
                }
                and origin_is_borrowed_exact_json_alias(candidate[1])
            ):
                # Detached JSON is fresh, but granting continued exact-member
                # authority after an alias mutates it would be unsound.  Keep
                # every bound container mutator fail-closed; callers can
                # reconstruct a new exact container instead.
                return True
            if (
                recognized_dict_setitem
                and binding_path is not None
                and binding_path[0] == "dict"
                and binding_path[1] == ("__setitem__",)
            ):
                continue
            if (
                recognized_dict_pop
                and binding_path is not None
                and binding_path[0] == "dict"
                and binding_path[1] == ("pop",)
            ):
                continue
            if (
                binding_path is not None
                and binding_path[0] == "dict"
                and binding_path[1]
                and binding_path[1][0] in dict_mutator_names
            ):
                return True
            if (
                binding_path is not None
                and binding_path[0] == "OrderedDict"
                and binding_path[1]
                and binding_path[1][0] in ordered_dict_mutator_names
            ):
                return True
            if (
                binding_path is not None
                and binding_path[0] == "list"
                and binding_path[1]
                and binding_path[1][0] in list_mutator_names
            ):
                # The modeled append path is deliberately bound to a concrete
                # local list allocation.  Unbound base descriptors do not
                # carry that identity and therefore fail closed.
                if (
                    recognized_list_setitem
                    and binding_path[1] == ("__setitem__",)
                ):
                    continue
                return True
            if (
                binding_path is not None
                and binding_path[0] == "bytearray"
                and binding_path[1]
                and binding_path[1][0] in bytearray_mutator_names
            ):
                return True
            if (
                binding_path is not None
                and binding_path[0] == "set"
                and binding_path[1]
                and binding_path[1][0] in set_mutator_names
            ):
                return True
            if (
                candidate
                and candidate[0] == "attribute"
                and candidate[2]
                and candidate[2][0] in dict_mutator_names
                and (
                    (
                        aggregate_mapping_entries(candidate[1]) is not None
                        and (
                            candidate[2] != ("__setitem__",)
                            or not recognized_dict_setitem
                        )
                    )
                    or exact_protocol_container(candidate[1], "dict")
                )
                and not (
                    recognized_dict_pop
                    and candidate[2] == ("pop",)
                )
            ):
                return True
            if (
                candidate
                and candidate[0] == "attribute"
                and candidate[2]
                and candidate[2][0] in bytearray_mutator_names
                and exact_protocol_container(candidate[1], "bytearray")
            ):
                return True
            if (
                candidate
                and candidate[0] == "attribute"
                and candidate[2]
                and candidate[2][0] in list_mutator_names
                and (
                    (
                        len(candidate[1]) >= 5
                        and candidate[1][0] == "aggregate"
                        and candidate[1][1] == "BUILD_LIST"
                    )
                    or exact_protocol_container(candidate[1], "list")
                )
                and not (
                    candidate[2] == ("append",)
                    and candidate[1] in modeled_append_targets
                )
            ):
                return True
            if (
                candidate
                and candidate[0] == "attribute"
                and candidate[2]
                and candidate[2][0] in set_mutator_names
                and (
                    (
                        candidate[1]
                        and candidate[1][0] == "aggregate"
                        and candidate[1][1] == "BUILD_SET"
                    )
                    or exact_protocol_container(candidate[1], "set")
                )
            ):
                return True
            if (
                binding_path is not None
                and binding_path[0] == "operator"
                and binding_path[1]
                and binding_path[1][0] in operator_mutator_names
            ):
                return True
        return False

    while worklist:
        index = worklist.popleft()
        queued.discard(index)
        hazard_epoch_at_entry = hazard_epoch
        # Reprocessing a converging CFG node must replace that call site's
        # transient nested-invocation rows.  Accumulating every intermediate
        # state creates phantom callable aliases that are absent from the
        # converged stack, especially for 3.13+ inlined dict comprehensions.
        for nested_code, calls_by_site in tuple(invoked_nested_calls.items()):
            calls_by_site.pop(index, None)
            if not calls_by_site:
                invoked_nested_calls.pop(nested_code, None)
        dynamic_uses.pop(index, None)
        exact_result_call_indices.discard(index)
        instruction = instructions[index]
        opname = instruction.opname
        input_stack, input_bindings, input_invalidations = states[index]
        stack = list(input_stack)
        bindings = dict(input_bindings)
        invalidations = set(input_invalidations)

        def pop_origin() -> tuple[Any, ...]:
            return list.pop(stack) if stack else V2_FAST_ORIGIN_UNKNOWN

        def pop_origins(count: int) -> list[tuple[Any, ...]]:
            return [pop_origin() for _index in range(max(0, count))]

        custom_edges: list[
            tuple[int | None, tuple[tuple[Any, ...], ...]]
        ] | None = None

        if opname in V2_FAST_LOCAL_LOAD_OPS:
            key = ("fast", instruction.argval)
            expression = bindings.get(key, binding_default(key))
            if opname in V2_FAST_LOCAL_MAYBE_UNBOUND_LOAD_OPS:
                expression = ("maybe-unbound", expression)
            list.append(stack, expression)
            if opname == "LOAD_FAST_AND_CLEAR" and type(
                instruction.argval
            ) is str:
                bindings[key] = V2_FAST_ORIGIN_UNBOUND
        if opname in {"LOAD_GLOBAL", "LOAD_NAME"}:
            effect = v2_fast_origin_stack_effect(instruction)
            if effect == 2:
                list.append(stack, V2_FAST_ORIGIN_NULL)
            key = ("global", instruction.argval)
            list.append(
                stack,
                bindings.get(key, binding_default(key))
                if type(instruction.argval) is str else V2_FAST_ORIGIN_UNKNOWN,
            )
        if opname in {"LOAD_DEREF", "LOAD_CLASSDEREF"}:
            if type(instruction.argval) is str:
                key = binding_key(opname, instruction.argval)
                list.append(stack, bindings.get(key, binding_default(key)))
            else:
                list.append(stack, V2_FAST_ORIGIN_UNKNOWN)
        if opname in {"LOAD_CONST", "LOAD_SMALL_INT"}:
            if type(instruction.argval) is types.CodeType:
                list.append(stack, ("code", instruction.argval))
            elif (
                type(instruction.argval) is tuple
                and v2_fast_exact_inert_key(instruction.argval)
            ):
                list.append(
                    stack,
                    ("constant-tuple", tuple(instruction.argval)),
                )
            elif v2_fast_exact_inert_key(instruction.argval):
                list.append(
                    stack,
                    v2_fast_constant_origin(instruction.argval),
                )
            else:
                list.append(stack, V2_FAST_ORIGIN_STATIC)
        if opname == "LOAD_COMMON_CONSTANT":
            list.append(stack, V2_FAST_ORIGIN_STATIC)
        if opname == "LOAD_CLOSURE":
            if type(instruction.argval) is str:
                key = binding_key("LOAD_DEREF", instruction.argval)
                list.append(stack, bindings.get(key, binding_default(key)))
            else:
                list.append(stack, V2_FAST_ORIGIN_UNKNOWN)
        if opname in {"LOAD_BUILD_CLASS", "LOAD_ASSERTION_ERROR"}:
            list.append(stack, V2_FAST_ORIGIN_STATIC)
        if opname == "PUSH_NULL":
            list.append(stack, V2_FAST_ORIGIN_NULL)
        if opname in V2_ATTRIBUTE_ACCESS_OPS:
            base = pop_origin()
            attribute = (
                (instruction.argval,)
                if type(instruction.argval) is str
                else ("<unknown-attribute>",)
            )
            expression = (
                ("mutated-member", base, ("attribute", *attribute))
                if member_invalidated(
                    base,
                    ("attribute", *attribute),
                    frozenset(invalidations),
                )
                else v2_fast_origin_with_path(base, attribute)
            )
            effect = v2_fast_origin_stack_effect(instruction)
            if effect == 1:
                list.append(stack, V2_FAST_ORIGIN_NULL)
            list.append(stack, expression)
        if opname == "LOAD_SPECIAL":
            base = pop_origin()
            special_name = (
                (instruction.argval,)
                if type(instruction.argval) is str
                else (instruction.argrepr,)
                if instruction.argrepr in {"__enter__", "__exit__"}
                else ("<unknown-special>",)
            )
            if special_name == ("__enter__",):
                dynamic_uses[index].add(("context-enter", base))
            list.append(
                stack,
                v2_fast_origin_with_path(base, special_name),
            )
            list.append(stack, base)
        if opname == "BEFORE_WITH":
            base = pop_origin()
            enter_callable = v2_fast_origin_with_path(base, ("__enter__",))
            dynamic_uses[index].add(("context-enter", base))
            list.append(
                stack,
                v2_fast_origin_with_path(base, ("__exit__",)),
            )
            list.append(stack, ("call-result", enter_callable))
        if opname == "WITH_EXCEPT_START":
            # CPython 3.14 retains ``(__exit__, receiver, exc_info...)``;
            # 3.11-3.13 retain ``(__exit__, exc_info...)``. Bind the deferred
            # callable at the release-specific stack depth, then represent its
            # result as an inert truth operand. Nested ``with`` statements can
            # make the total stack longer, so length alone cannot distinguish
            # these layouts.
            exit_stack_depth = V2_WITH_EXCEPT_START_EXIT_STACK_DEPTH
            exit_callable = (
                input_stack[-exit_stack_depth]
                if len(input_stack) >= exit_stack_depth
                else V2_FAST_ORIGIN_UNKNOWN
            )
            implicit_call_expressions[index] = exit_callable
            list.append(stack, V2_FAST_ORIGIN_STATIC)
        if opname in {"MATCH_MAPPING", "MATCH_SEQUENCE"}:
            # These type-flag probes retain the subject and push an exact bool;
            # GET_LEN, MATCH_KEYS, and UNPACK_SEQUENCE carry the operations
            # that may dispatch runtime protocols on the subject.
            list.append(stack, V2_FAST_ORIGIN_STATIC)
        if opname == "GET_LEN":
            subject = (
                stack[-1] if stack else V2_FAST_ORIGIN_UNKNOWN
            )
            dynamic_uses[index].add(("length", subject))
            list.append(stack, V2_FAST_ORIGIN_STATIC)
        if opname == "MATCH_KEYS":
            subject = (
                input_stack[-2]
                if len(input_stack) >= 2
                else V2_FAST_ORIGIN_UNKNOWN
            )
            keys = (
                input_stack[-1]
                if input_stack
                else V2_FAST_ORIGIN_UNKNOWN
            )
            dynamic_uses[index].add(("match-keys", subject))
            dynamic_uses[index].add(("call-protocol", keys))
            list.append(stack, V2_FAST_ORIGIN_STATIC)
        if opname == "COPY":
            depth = instruction.arg
            list.append(
                stack,
                stack[-depth]
                if type(depth) is int and 0 < depth <= len(stack)
                else V2_FAST_ORIGIN_UNKNOWN,
            )
        if opname == "SWAP":
            depth = instruction.arg
            if type(depth) is int and 0 < depth <= len(stack):
                stack[-1], stack[-depth] = stack[-depth], stack[-1]
            else:
                list.clear(stack)
        if opname in V2_CALL_OPS:
            effect = v2_fast_origin_stack_effect(instruction)
            pop_count = 1 - effect if effect is not None else len(stack)
            consumed = pop_origins(pop_count)
            call_keyword_names: tuple[str, ...] | None = ()
            if opname == "CALL_KW":
                keyword_origin = (
                    consumed[0] if consumed else V2_FAST_ORIGIN_UNKNOWN
                )
                call_keyword_names = (
                    keyword_origin[1]
                    if keyword_origin
                    and keyword_origin[0] == "constant-tuple"
                    and all(type(name) is str for name in keyword_origin[1])
                    else None
                )
            elif opname == "CALL_FUNCTION_EX":
                # *args/**kwargs expansion needs aggregate-shape proof.  The
                # nested binder deliberately refuses this marker rather than
                # guessing that an aggregate is one positional parameter or
                # silently applying defaults after DICT_MERGE.
                call_keyword_names = None
            simulated = next(
                (
                    candidate for candidate in reversed(consumed)
                    if candidate != V2_FAST_ORIGIN_NULL
                ),
                V2_FAST_ORIGIN_UNKNOWN,
            )
            prepared_arguments: tuple[tuple[Any, ...], ...] = ()
            simulated_options = origin_options(simulated)
            prepared_rows = tuple(
                option
                for option in simulated_options
                if option and option[0] == "prepared-call"
            )
            direct_rows = {
                option
                for option in simulated_options
                if not option or option[0] != "prepared-call"
            }
            prepared_callable_options = {
                candidate
                for option in prepared_rows
                for candidate in origin_options(option[1])
            }
            prepared_callable_identities = {
                callable_frame_identity(candidate)
                for candidate in prepared_callable_options
            }
            if prepared_rows and all(
                callable_frame_identity(candidate)
                in prepared_callable_identities
                for candidate in direct_rows
            ):
                # On 3.11 a converged loop edge can retain the same callable
                # both before and after PRECALL preparation.  This is not a
                # real callable alternative: unwrap the prepared frame when
                # every direct row is the identical underlying callable.
                argument_lengths = {
                    len(option[2]) for option in prepared_rows
                }
                if len(argument_lengths) == 1:
                    prepared_arguments = tuple(
                        merge_origins(
                            (option[2][argument_index]
                             for option in prepared_rows),
                        )
                        for argument_index in range(
                            next(iter(argument_lengths))
                        )
                    )
                prepared_keyword_names = {option[3] for option in prepared_rows}
                call_keyword_names = (
                    next(iter(prepared_keyword_names))
                    if len(prepared_keyword_names) == 1
                    else None
                )
                simulated = merge_origins((
                    *direct_rows,
                    *(option[1] for option in prepared_rows),
                ))
            # Source spans are only corroboration.  In particular, one span
            # can cover nested calls on 3.14 and a subscript expression on
            # 3.11; it must never replace or invalidate the simulated
            # call-frame origin.  The exact-source sets remain useful for
            # bounded reprocessing when a predecessor is first discovered.
            callable_origin = simulated
            # A worklist instruction can be revisited as predecessors merge.
            # Keep the callable from its latest (therefore most complete)
            # input state; retaining transient earlier states creates phantom
            # aliases that are not present at the converged CFG node.
            implicit_call_expressions[index] = callable_origin
            callable_options = origin_options(callable_origin)
            for candidate in callable_options:
                if candidate and candidate[0] == "nested-function":
                    nested_code = candidate[1]
                    if nested_code.co_flags & 0x20:
                        continue
            argument_count = (
                instruction.arg if type(instruction.arg) is int else 0
            )
            arguments = (
                list(prepared_arguments)
                if prepared_arguments
                else []
                if opname == "CALL_FUNCTION_EX"
                else list(reversed(
                    consumed[1:1 + argument_count]
                ))
                if opname == "CALL_KW"
                else list(reversed(consumed[:argument_count]))
            )
            if opname == "CALL_FUNCTION_EX":
                has_keyword_mapping = (
                    bool(instruction.arg & 1)
                    if type(instruction.arg) is int
                    else bool(consumed)
                    and consumed[0] != V2_FAST_ORIGIN_NULL
                )
                positional_source_index = (
                    1
                    if instruction.arg is None or has_keyword_mapping
                    else 0
                )
                positional_source = (
                    consumed[positional_source_index]
                    if positional_source_index < len(consumed)
                    else V2_FAST_ORIGIN_UNKNOWN
                )
                keyword_source = (
                    consumed[0]
                    if has_keyword_mapping and consumed
                    else ("aggregate", "BUILD_MAP", ())
                )
                positional_expansion = exact_positional_expansion(
                    positional_source
                )
                keyword_expansion = exact_keyword_expansion(keyword_source)
                if (
                    positional_expansion is None
                    or keyword_expansion is None
                ):
                    dynamic_uses[index].add((
                        "unproven-call-expansion",
                        (
                            "aggregate",
                            "CALL_FUNCTION_EX",
                            (positional_source, keyword_source),
                        ),
                    ))
                    arguments = []
                    call_keyword_names = None
                else:
                    call_keyword_names, keyword_arguments = keyword_expansion
                    arguments = [
                        *positional_expansion,
                        *keyword_arguments,
                    ]
            record_exact_dict_contains_protocol(
                callable_options,
                arguments,
                call_keyword_names,
            )
            record_possible_dict_keyed_method_protocol(
                callable_options,
                arguments,
                call_keyword_names,
            )
            (
                recognized_dict_setitem,
                dict_setitem_replacements,
            ) = exact_dict_setitem_replacements(
                callable_options,
                arguments,
                call_keyword_names,
            )
            (
                recognized_list_setitem,
                list_setitem_replacements,
            ) = exact_list_setitem_replacements(
                callable_options,
                arguments,
                call_keyword_names,
            )
            (
                recognized_dict_pop,
                dict_pop_replacements,
                dict_pop_result,
            ) = exact_dict_pop_effect(
                callable_options,
                arguments,
                call_keyword_names,
            )
            for receiver, updated_receiver in (
                *dict_setitem_replacements,
                *list_setitem_replacements,
                *dict_pop_replacements,
            ):
                for binding, origin in tuple(bindings.items()):
                    bindings[binding] = replace_origin_tree(
                        origin,
                        receiver,
                        updated_receiver,
                    )
                stack = [
                    replace_origin_tree(
                        origin,
                        receiver,
                        updated_receiver,
                    )
                    for origin in stack
                ]
            if unmodeled_mutator_call(
                callable_options,
                arguments,
                call_keyword_names,
                recognized_dict_setitem=recognized_dict_setitem,
                recognized_dict_pop=recognized_dict_pop,
                recognized_list_setitem=recognized_list_setitem,
            ):
                dynamic_uses[index].add((
                    "unmodeled-exact-container-mutation",
                    (
                        "aggregate",
                        "MUTATION_CALL",
                        (callable_origin, *arguments),
                    ),
                ))
            append_targets = modeled_bound_list_append_targets(
                callable_options,
                arguments,
                call_keyword_names,
            )
            if append_targets:
                append_target = next(iter(append_targets))
                appended = append_aggregate_members(
                    append_target,
                    arguments,
                )
                for binding, origin in tuple(bindings.items()):
                    bindings[binding] = replace_origin_tree(
                        origin,
                        append_target,
                        appended,
                    )
                stack = [
                    replace_origin_tree(
                        origin,
                        append_target,
                        appended,
                    )
                    for origin in stack
                ]
            list_getitem_result = list_getitem_result_origin(
                callable_options,
                arguments,
                call_keyword_names,
                call_index=index,
            )
            dict_get_result = dict_get_result_origin(
                callable_options,
                arguments,
                call_keyword_names,
                call_index=index,
            )
            dict_getitem_result = dict_getitem_result_origin(
                callable_options,
                arguments,
                call_keyword_names,
                call_index=index,
            )
            dict_copy_result = dict_copy_result_origin(
                callable_options,
                arguments,
                call_keyword_names,
                call_index=index,
            )
            dict_items_result = dict_items_result_origin(
                callable_options,
                arguments,
                call_keyword_names,
                call_index=index,
            )
            dict_values_result = dict_values_result_origin(
                callable_options,
                arguments,
                call_keyword_names,
                call_index=index,
            )
            exact_base_len_result = exact_base_len_result_origin(
                callable_options,
                arguments,
                call_keyword_names,
                call_index=index,
            )
            container_method_result = exact_container_method_result_origin(
                callable_options,
                arguments,
            )
            modeled_bound_call = bool(
                append_targets
                or recognized_dict_setitem
                or recognized_dict_pop
                or recognized_list_setitem
                or list_getitem_result is not None
                or dict_get_result is not None
                or dict_getitem_result is not None
                or dict_copy_result is not None
                or dict_items_result is not None
                or dict_values_result is not None
                or exact_base_len_result is not None
                or container_method_result is not None
            )
            if not modeled_bound_call:
                protocol_bound_receivers = tuple(
                    candidate[1]
                    for candidate in callable_options
                    if candidate
                    and candidate[0] == "attribute"
                    and v2_fast_origin_requires_unmodeled_bound_protocol(
                        candidate[1]
                    )
                )
                if protocol_bound_receivers:
                    for receiver in protocol_bound_receivers:
                        dynamic_uses[index].add(("call-protocol", receiver))
                    for argument in arguments:
                        dynamic_uses[index].add(("call-protocol", argument))
            nested_positional_arity = max(
                (
                    option[1].co_argcount
                    for option in callable_options
                    if option and option[0] == "nested-function"
                ),
                default=0,
            )
            if not arguments and nested_positional_arity:
                implicit_arguments = [
                    candidate for candidate in consumed
                    if candidate != V2_FAST_ORIGIN_NULL
                    and candidate not in callable_options
                    and not (
                        candidate
                        and candidate[0] == "prepared-call"
                    )
                ]
                arguments = list(reversed(
                    implicit_arguments[:nested_positional_arity]
                ))
            for candidate in callable_options:
                if candidate and candidate[0] == "nested-function":
                    invoked_nested_calls[candidate[1]][index].add((
                        candidate,
                        tuple(arguments),
                        call_keyword_names,
                    ))
            protocol_candidate_flags = tuple(
                candidate[0] == "binding"
                and candidate[1] == "global"
                and not candidate[3]
                and candidate[2] in protocol_callables
                for candidate in callable_options
            )
            protocol = bool(protocol_candidate_flags) and all(
                protocol_candidate_flags
            )
            if any(protocol_candidate_flags) and not protocol:
                dynamic_uses[index].add((
                    "ambiguous-callable-protocol",
                    callable_origin,
                ))
            scalar_module_call = bool(callable_options) and all(
                exact_global_binding_path(candidate)
                in V2_SCALAR_MODULE_CALL_PATHS
                for candidate in callable_options
            )
            consumes_generator = any(
                candidate[0] == "binding"
                and candidate[1] == "global"
                and not candidate[3]
                and candidate[2] in generator_consumers
                for candidate in callable_options
            )
            if protocol or scalar_module_call:
                class_test_protocol = protocol and all(
                    candidate[2] in {"isinstance", "issubclass", "type"}
                    for candidate in callable_options
                )
                keyword_count = (
                    len(call_keyword_names)
                    if call_keyword_names is not None
                    else 0
                )
                positional_count = max(0, len(arguments) - keyword_count)
                key_argument_indices = {
                    positional_count + keyword_index
                    for keyword_index, keyword_name in enumerate(
                        call_keyword_names or ()
                    )
                    if keyword_name == "key"
                    and all(
                        candidate[2] in {"max", "min", "sorted"}
                        for candidate in callable_options
                    )
                }
                # The iterable operands are projected below before a key
                # callback is admitted.  Model the callback item as an exact
                # protocol-vetted value instead of trying to reverse a set or
                # sorted implementation into a positional origin.  This keeps
                # the callback body in the transitive code audit while the
                # runtime protocol validator remains the authority for whether
                # its possible items can dispatch user hooks.
                key_item_origin = (
                    "iter-static",
                    ("protocol-key-item",),
                    (),
                )
                for argument_index, argument in enumerate(arguments):
                    if class_test_protocol:
                        # type/isinstance/issubclass do not dispatch ordinary
                        # conversion/iteration protocols modeled by this
                        # path.  Their class-info operands remain normal
                        # binding accesses and are identity/state projected;
                        # treating typing.Mapping/Sequence as iterable data
                        # would reject an identity-pinned class-info value.
                        continue
                    if argument_index not in key_argument_indices:
                        dynamic_uses[index].add(("call-protocol", argument))
                        continue
                    key_options = origin_options(argument)
                    if key_options and all(
                        option
                        and option[0] == "nested-function"
                        and not option[1].co_flags & 0x20
                        for option in key_options
                    ):
                        for option in key_options:
                            invoked_nested_calls[option[1]][index].add((
                                option,
                                (key_item_origin,),
                                (),
                            ))
                    else:
                        # A non-local key callback is executable state, not an
                        # inert protocol value.  Keep it on the conservative
                        # projection path rather than assuming its return is
                        # pure merely because the outer builtin is audited.
