                        else (formatted,)
                    ),
                ),
            ))
            list.append(stack, V2_FAST_ORIGIN_STATIC)
        if opname.startswith("UNARY_"):
            source = pop_origin()
            dynamic_uses[index].add((opname, source))
            list.append(stack, ("derived", opname, source))
        if (
            opname.startswith("BINARY_")
            and opname not in {"BINARY_SLICE", "BINARY_SUBSCR"}
            and not (opname == "BINARY_OP" and instruction.argrepr == "[]")
            or opname in {"COMPARE_OP", "CONTAINS_OP", "IS_OP"}
        ):
            right = pop_origin()
            left = pop_origin()
            if opname == "CONTAINS_OP":
                dynamic_uses[index].add(("call-protocol", left))
                dynamic_uses[index].add(("contains-protocol", right))
            in_place_method = {
                "|=": "__ior__",
                "&=": "__iand__",
                "-=": "__isub__",
                "^=": "__ixor__",
                "+=": "__iadd__",
                "*=": "__imul__",
            }.get(instruction.argrepr) if opname == "BINARY_OP" else None
            if (
                opname == "BINARY_OP"
                and in_place_method is not None
                and any(
                    aggregate_mapping_entries(candidate) is not None
                    or (
                        candidate
                        and candidate[0] == "aggregate"
                        and candidate[1] in {"BUILD_LIST", "BUILD_SET"}
                    )
                    or any(
                        exact_protocol_container(candidate, name)
                        for name in ("bytearray", "dict", "list", "set")
                    )
                    or origin_is_borrowed_exact_json_alias(candidate)
                    for candidate in origin_options(left)
                )
            ):
                dynamic_uses[index].add((
                    "unmodeled-exact-container-mutation",
                    left,
                ))
            operation_name = (
                f"{opname}:{instruction.argrepr}"
                if opname in {"BINARY_OP", "COMPARE_OP"}
                else opname
            )
            dynamic_uses[index].add((
                operation_name,
                ("aggregate", opname, (left, right)),
            ))
            # CONTAINS_OP, IS_OP, and CPython 3.14 COMPARE_OP forms annotated
            # as ``bool(...)`` already leave an exact bool.  Retaining their
            # independently audited operand choices in the result can exceed
            # the bounded choice cap and manufacture an ``unknown`` at the
            # following POP_JUMP.  Non-bool COMPARE_OP forms deliberately keep
            # the derived origin because a rich-comparison result may still
            # dispatch ``__bool__`` later.
            bool_comparison_result = bool(
                opname in {"CONTAINS_OP", "IS_OP"}
                or opname == "COMPARE_OP"
                and instruction.argrepr.startswith("bool(")
            )
            list.append(
                stack,
                V2_FAST_ORIGIN_STATIC
                if bool_comparison_result
                else ("derived", opname, left, right),
            )
        if opname == "POP_TOP":
            pop_origin()
        if opname == "RETURN_VALUE":
            return_expressions.add(
                stack[-1] if stack else V2_FAST_ORIGIN_UNKNOWN
            )
        elif opname == "RETURN_CONST":
            return_expressions.add(
                v2_fast_constant_origin(instruction.argval)
                if v2_fast_exact_inert_key(instruction.argval)
                else V2_FAST_ORIGIN_STATIC
            )
        if opname in {
            "RETURN_CONST",
            "RETURN_VALUE",
            "RAISE_VARARGS",
            "RERAISE",
        }:
            list.clear(stack)
            custom_edges = []
        if opname in {
            "CACHE",
            "COPY_FREE_VARS",
            "EXTENDED_ARG",
            "KW_NAMES",
            "MAKE_CELL",
            "NOP",
            "NOT_TAKEN",
            "RESUME",
        }:
            pass
        elif opname.startswith("JUMP") and custom_edges is None:
            custom_edges = [(jump_target_index(instruction), tuple(stack))]
        elif custom_edges is None and opname not in {
            *V2_ATTRIBUTE_ACCESS_OPS,
            *V2_FAST_LOCAL_LOAD_OPS,
            "BINARY_SUBSCR",
            "BINARY_SLICE",
            "BUILD_CONST_KEY_MAP",
            "BUILD_LIST",
            "BUILD_MAP",
            "BUILD_SET",
            "BUILD_TUPLE",
            "CALL",
            "CALL_FUNCTION_EX",
            "CALL_INTRINSIC_1",
            "CALL_KW",
            "COMPARE_OP",
            "CONTAINS_OP",
            "COPY",
            "DELETE_ATTR",
            "DELETE_FAST",
            "DELETE_SUBSCR",
            "DICT_MERGE",
            "DICT_UPDATE",
            "FOR_ITER",
            "GET_ITER",
            "GET_LEN",
            "GET_YIELD_FROM_ITER",
            "IS_OP",
            "LOAD_ASSERTION_ERROR",
            "LOAD_BUILD_CLASS",
            "LOAD_CLASSDEREF",
            "LOAD_CLOSURE",
            "LOAD_COMMON_CONSTANT",
            "LOAD_CONST",
            "LOAD_DEREF",
            "LOAD_GLOBAL",
            "LOAD_NAME",
            "LOAD_SMALL_INT",
            "LOAD_SPECIAL",
            "LIST_APPEND",
            "LIST_EXTEND",
            "MAP_ADD",
            "MATCH_KEYS",
            "MATCH_MAPPING",
            "MATCH_SEQUENCE",
            "MAKE_FUNCTION",
            "POP_TOP",
            "PRECALL",
            "PUSH_NULL",
            "SEND",
            "SET_ADD",
            "SET_FUNCTION_ATTRIBUTE",
            "SET_UPDATE",
            "STORE_ATTR",
            "STORE_DEREF",
            "STORE_FAST",
            "STORE_FAST_MAYBE_NULL",
            "STORE_GLOBAL",
            "STORE_NAME",
            "STORE_SLICE",
            "STORE_SUBSCR",
            "SWAP",
            "TO_BOOL",
            "UNPACK_EX",
            "UNPACK_SEQUENCE",
            "BEFORE_WITH",
            "WITH_EXCEPT_START",
        } and not opname.startswith(("BINARY_", "UNARY_")):
            effect = v2_fast_origin_stack_effect(instruction)
            if effect is None:
                list.clear(stack)
            elif effect < 0:
                pop_origins(-effect)
            elif effect > 0:
                for _index in range(effect):
                    list.append(stack, V2_FAST_ORIGIN_UNKNOWN)

        access = None
        if index in source_call_indices or opname in {
            *V2_FAST_LOCAL_LOAD_OPS,
            "LOAD_CLASSDEREF",
            "LOAD_DEREF",
            "LOAD_GLOBAL",
            "LOAD_NAME",
        }:
            source_expression: tuple[Any, ...] | None = None
            if opname in V2_FAST_LOCAL_LOAD_OPS:
                key = ("fast", instruction.argval)
                source_expression = input_bindings.get(
                    key,
                    binding_default(key),
                )
                if opname in V2_FAST_LOCAL_MAYBE_UNBOUND_LOAD_OPS:
                    source_expression = ("maybe-unbound", source_expression)
            elif opname in {"LOAD_DEREF", "LOAD_CLASSDEREF"} and type(
                instruction.argval
            ) is str:
                key = binding_key(opname, instruction.argval)
                source_expression = input_bindings.get(
                    key,
                    binding_default(key),
                )
            elif opname in {"LOAD_GLOBAL", "LOAD_NAME"} and type(
                instruction.argval
            ) is str:
                key = ("global", instruction.argval)
                source_expression = input_bindings.get(
                    key,
                    binding_default(key),
                )
            if source_expression is not None:
                path, _path_end = v2_instruction_access_path(
                    instructions,
                    index,
                )
                access = v2_fast_origin_with_path(source_expression, path)
                prior_access = access_expressions.get(index)
                access_expressions[index] = (
                    access if prior_access is None
                    else merge_origin(prior_access, access)
                )
                for call_index in source_call_indices.get(index, set()):
                    if access not in observed_call_sources[call_index]:
                        observed_call_sources[call_index].add(access)
                        if call_index in states and call_index not in queued:
                            queued.add(call_index)
                            worklist.append(call_index)

        if custom_edges is None:
            custom_edges = [(index + 1, tuple(stack))]
        output_invalidations = frozenset(invalidations)
        for target, edge_stack in custom_edges:
            queue_state(
                target,
                (edge_stack, dict(bindings), output_invalidations),
            )
        for target, handler_depth, handler_lasti in exception_successors.get(
            index,
            (),
        ):
            handler_stack = list(input_stack[:handler_depth])
            list.append(handler_stack, V2_FAST_ORIGIN_UNKNOWN)
            if handler_lasti:
                list.append(handler_stack, V2_FAST_ORIGIN_UNKNOWN)
            queue_state(
                target,
                (
                    tuple(handler_stack),
                    merge_binding_maps(input_bindings, bindings),
                    output_invalidations,
                ),
            )
        if hazard_epoch != hazard_epoch_at_entry:
            # Exact-JSON reachability is monotone per local allocation site.
            # Revisit every materialized CFG state when a site first becomes
            # hazardous so an alias captured earlier on another path cannot
            # retain a stale ``aggregate-reference(..., False)`` proof.
            dict.clear(origin_merge_identity_cache)
            for state_index in tuple(states):
                if state_index not in queued:
                    queued.add(state_index)
                    worklist.append(state_index)

    return {
        "definitions": {},
        "load_expressions": access_expressions,
        "dynamic_uses": tuple(sorted(
            (
                (site_index, *use)
                for site_index, site_uses in dynamic_uses.items()
                for use in site_uses
            ),
            key=lambda row: (
                row[0],
                v2_fast_origin_sort_key((row[1], row[2])),
            ),
        )),
        "return_expressions": frozenset(return_expressions),
        "implicit_call_expressions": tuple(sorted(
            implicit_call_expressions.items(),
            key=lambda row: (row[0], v2_fast_origin_sort_key(row[1])),
        )),
        "exact_result_call_indices": frozenset(exact_result_call_indices),
        "invoked_nested_codes": frozenset({
            nested_code
            for nested_code, calls_by_site in invoked_nested_calls.items()
            if calls_by_site
        }),
        "invoked_nested_calls": {
            nested_code: tuple(
                call
                for site_calls in calls_by_site.values()
                for call in site_calls
            )
            for nested_code, calls_by_site in invoked_nested_calls.items()
            if calls_by_site
        },
        "parameter_layout": parameter_layout,
    }


def v2_nested_invocation_parameter_origins(
    nested_code: types.CodeType,
    calls: Sequence[
        tuple[
            tuple[Any, ...],
            tuple[tuple[Any, ...], ...],
            tuple[str, ...] | None,
        ]
    ],
) -> dict[str, tuple[Any, ...]]:
    """Bind an invoked nested code object's parameters to parent origins."""
    parameter_layout = dict(v2_code_parameter_layout(nested_code))
    positional_names = list(
        nested_code.co_varnames[:nested_code.co_argcount]
    )
    positional_only_names = set(
        positional_names[:nested_code.co_posonlyargcount]
    )
    positional_or_keyword_names = set(
        positional_names[nested_code.co_posonlyargcount:]
    )
    keyword_only_names = list(nested_code.co_varnames[
        nested_code.co_argcount:
        nested_code.co_argcount + nested_code.co_kwonlyargcount
    ])
    keyword_bindable_names = (
        positional_or_keyword_names | set(keyword_only_names)
    )
    merged: dict[str, tuple[Any, ...]] = {}

    def add(name: str, origin: tuple[Any, ...]) -> None:
        prior = merged.get(name)
        if prior is None or prior == origin:
            merged[name] = origin
            return
        options: set[tuple[Any, ...]] = set()
        for candidate in (prior, origin):
            if candidate and candidate[0] == "choice":
                options.update(candidate[1])
            else:
                options.add(candidate)
        merged[name] = (
            V2_FAST_ORIGIN_UNKNOWN
            if len(options) > V2_FAST_ORIGIN_RESOLUTION_CAP
            else (
                "choice",
                tuple(sorted(options, key=v2_fast_origin_sort_key)),
            )
        )

    for callable_origin, arguments, keyword_names in calls:
        if (
            not callable_origin
            or callable_origin[0] != "nested-function"
            or callable_origin[1] is not nested_code
        ):
            continue
        if nested_code.co_flags & (0x04 | 0x08):
            raise EvidenceFailed(
                "refusal-state invoked nested variadic signature cannot be "
                f"bound exactly in {nested_code.co_qualname}"
            )
        if keyword_names is None:
            raise EvidenceFailed(
                "refusal-state nested *args/**kwargs expansion cannot be "
                f"bound exactly in {nested_code.co_qualname}"
            )
        if len(keyword_names) > len(arguments):
            raise EvidenceFailed(
                "refusal-state nested keyword arity exceeds supplied values "
                f"in {nested_code.co_qualname}"
            )
        positional_count = len(arguments) - len(keyword_names)
        if positional_count > len(positional_names):
            raise EvidenceFailed(
                "refusal-state nested call supplies too many positional "
                f"arguments in {nested_code.co_qualname}"
            )
        per_call: dict[str, tuple[Any, ...]] = dict(zip(
            positional_names[:positional_count],
            arguments[:positional_count],
            strict=True,
        ))
        seen_keyword_names: set[str] = set()
        for name, origin in zip(
            keyword_names,
            arguments[positional_count:],
            strict=True,
        ):
            if name in seen_keyword_names:
                raise EvidenceFailed(
                    "refusal-state nested call repeats a keyword in "
                    f"{nested_code.co_qualname}"
                )
            seen_keyword_names.add(name)
            if name in positional_only_names or name not in keyword_bindable_names:
                raise EvidenceFailed(
                    "refusal-state nested call supplies an unexpected keyword "
                    f"{name!r} in {nested_code.co_qualname}"
                )
            if name in per_call:
                raise EvidenceFailed(
                    "refusal-state nested call supplies a parameter twice in "
                    f"{nested_code.co_qualname}"
                )
            per_call[name] = origin
        attributes = dict(callable_origin[2])
        positional_defaults: dict[str, tuple[Any, ...]] = {}
        defaults = attributes.get(1)
        if (
            type(defaults) is tuple
            and defaults
            and defaults[0] == "aggregate"
            and defaults[1] == "BUILD_TUPLE"
        ):
            default_values = defaults[2]
            if len(default_values) > len(positional_names):
                raise EvidenceFailed(
                    "refusal-state nested positional defaults exceed the "
                    f"signature in {nested_code.co_qualname}"
                )
            if default_values:
                positional_defaults = dict(zip(
                    positional_names[-len(default_values):],
                    default_values,
                    strict=True,
                ))
        keyword_default_origins: dict[str, tuple[Any, ...]] = {}
        keyword_defaults = attributes.get(2)
        if (
            type(keyword_defaults) is tuple
            and keyword_defaults
            and keyword_defaults[0] == "aggregate"
        ):
            members = keyword_defaults[2]
            keyword_rows: list[tuple[Any, tuple[Any, ...]]] = []
            if (
                keyword_defaults[1] == "BUILD_CONST_KEY_MAP"
                and members
                and members[-1]
                and members[-1][0] == "constant-tuple"
            ):
                keys = members[-1][1]
                keyword_rows = list(zip(
                    keys,
                    members[:-1],
                    strict=True,
                ))
            elif keyword_defaults[1] == "BUILD_MAP":
                keyword_rows = [
                    (members[index][1], members[index + 1])
                    for index in range(0, len(members) - 1, 2)
                    if members[index]
                    and members[index][0] == "constant"
                    and type(members[index][1]) is str
                ]
            for name, origin in keyword_rows:
                if type(name) is str and name in parameter_layout:
                    keyword_default_origins[name] = origin
        for name in positional_names:
            if name not in per_call and name in positional_defaults:
                per_call[name] = positional_defaults[name]
        for name in keyword_only_names:
            if name not in per_call and name in keyword_default_origins:
                per_call[name] = keyword_default_origins[name]
        missing_required = [
            name
            for name in (*positional_names, *keyword_only_names)
            if name not in per_call
        ]
        if missing_required:
            raise EvidenceFailed(
                "refusal-state nested call leaves required parameters "
                f"unbound in {nested_code.co_qualname}: {missing_required}"
            )
        for name, origin in per_call.items():
            add(name, origin)
    return merged


def v2_resolve_fast_origin(
    expression: tuple[Any, ...],
    definitions: Mapping[str, frozenset[tuple[Any, ...]]],
    *,
    trail: tuple[str, ...] = (),
    depth: int = 0,
) -> frozenset[tuple[Any, ...]]:
    if depth > V2_REFUSAL_STATE_DEPTH_CAP:
        return frozenset({V2_FAST_ORIGIN_UNKNOWN})
    kind = expression[0] if expression else "unknown"
    if kind == "local":
        name = expression[1]
        if type(name) is not str or name in trail:
            return frozenset({V2_FAST_ORIGIN_UNKNOWN})
        candidates = definitions.get(name)
        if not candidates:
            return frozenset({V2_FAST_ORIGIN_UNKNOWN})
        resolved: set[tuple[Any, ...]] = set()
        for candidate in candidates:
            resolved.update(v2_resolve_fast_origin(
                candidate,
                definitions,
                trail=(*trail, name),
                depth=depth + 1,
            ))
            if len(resolved) > V2_FAST_ORIGIN_RESOLUTION_CAP:
                return frozenset({V2_FAST_ORIGIN_UNKNOWN})
        return frozenset(resolved)
    if kind == "choice":
        resolved = set()
        for candidate in expression[1]:
            resolved.update(v2_resolve_fast_origin(
                candidate,
                definitions,
                trail=trail,
                depth=depth + 1,
            ))
        return (
            frozenset(resolved)
            if len(resolved) <= V2_FAST_ORIGIN_RESOLUTION_CAP
            else frozenset({V2_FAST_ORIGIN_UNKNOWN})
        )
    if kind == "attribute":
        base, path = expression[1], expression[2]
        resolved: set[tuple[Any, ...]] = set()
        for candidate in v2_resolve_fast_origin(
            base,
            definitions,
            trail=trail,
            depth=depth + 1,
        ):
            if candidate[0] == "binding":
                resolved.add((
                    "binding",
                    candidate[1],
                    candidate[2],
                    (*candidate[3], *path),
                ))
            elif candidate[0] == "call-result":
                resolved.add(("result-access", candidate, path))
            elif candidate[0] == "result-access":
                resolved.add((
                    "result-access",
                    candidate[1],
                    (*candidate[2], *path),
                ))
            elif candidate[0] == "maybe-unbound":
                resolved.add((
                    "maybe-unbound",
                    ("attribute", candidate[1], path),
                ))
            elif candidate[0] == "iter-binding":
                resolved.add((
                    "iter-binding",
                    candidate[1],
                    (*candidate[2], *path),
                ))
            elif candidate[0] == "iter-static":
                resolved.add((
                    "iter-static",
                    candidate[1],
                    (*candidate[2], *path),
                ))
            elif candidate[0] == "aggregate-map-values":
                # A summarized mapping lookup denotes one of the bounded
                # value provenances in slot 2.  Attribute lookup distributes
                # over that possibility set; treating the summary wrapper as
                # the runtime receiver loses the exact before/after aliases
                # preserved by shallow-copy and loop-carried map analysis.
                pending_values = list(v2_resolve_fast_origin(
                    candidate[2],
                    definitions,
                    trail=trail,
                    depth=depth + 1,
                ))
                expanded_values: list[tuple[Any, ...]] = []
                while pending_values:
                    value_candidate = pending_values.pop()
                    if (
                        value_candidate
                        and value_candidate[0] == "aggregate"
                        and value_candidate[1] == "ORIGIN_SUMMARY"
                    ):
                        pending_values.extend(value_candidate[2])
                        if (
                            len(pending_values) + len(expanded_values)
                            > V2_FAST_ORIGIN_RESOLUTION_CAP
                        ):
                            return frozenset({V2_FAST_ORIGIN_UNKNOWN})
                        continue
                    expanded_values.append(value_candidate)
                for value_candidate in expanded_values:
                    resolved.update(v2_resolve_fast_origin(
                        ("attribute", value_candidate, path),
                        definitions,
                        trail=trail,
                        depth=depth + 1,
                    ))
                    if len(resolved) > V2_FAST_ORIGIN_RESOLUTION_CAP:
                        return frozenset({V2_FAST_ORIGIN_UNKNOWN})
            elif candidate[0] == "aggregate":
                resolved.add(("attribute", candidate, path))
            elif (
                candidate[0] == "unpack"
                and candidate[1]
                and candidate[1][0] == "result-access"
            ):
                result_access = candidate[1]
                resolved.add((
                    "result-access",
                    result_access[1],
                    (
                        *result_access[2],
                        f"<unpack:{candidate[2]}>",
                        *path,
                    ),
                ))
            else:
                result_roots = v2_fast_origin_call_result_roots(candidate)
                if len(result_roots) == 1:
                    resolved.add((
                        "result-access",
                        ("call-result", next(iter(result_roots))),
                        path,
                    ))
                else:
                    resolved.add(("attribute", candidate, path))
        return frozenset(resolved)
    if kind == "call-result":
        return frozenset(
            ("call-result", candidate, *expression[2:])
            for candidate in v2_resolve_fast_origin(
                expression[1],
                definitions,
                trail=trail,
                depth=depth + 1,
            )
        )
    if kind == "iter-item":
        source = expression[1]
        while source and source[0] == "derived" and source[1] in {
            "GET_ITER",
            "GET_YIELD_FROM_ITER",
        }:
            source = source[2]
        resolved: set[tuple[Any, ...]] = set()
        for candidate in v2_resolve_fast_origin(
            source,
            definitions,
            trail=trail,
            depth=depth + 1,
        ):
            while (
                candidate
                and candidate[0] == "derived"
                and candidate[1] in {"GET_ITER", "GET_YIELD_FROM_ITER"}
            ):
                candidate = candidate[2]
            if v2_fast_origin_is_exact_json(candidate):
                resolved.add((
                    "exact-json-member",
                    candidate,
                    "<iter-item>",
                ))
                continue
            view_members = v2_fast_dict_view_members(candidate)
            if view_members is not None:
                for member in view_members:
                    resolved.update(v2_resolve_fast_origin(
                        member,
                        definitions,
                        trail=trail,
                        depth=depth + 1,
                    ))
            elif candidate[0] == "choice":
                # A local may resolve to a GET_ITER wrapper whose operand is
                # the join of multiple exact aggregate shapes.  The wrapper
                # is removed above after local resolution, so flatten the
                # newly exposed join here as well.  This is required by the
                # 3.13+ dict-comprehension bytecode shape and does not widen
                # any dynamic member: each option is resolved independently.
                for option in candidate[1]:
                    resolved.update(v2_resolve_fast_origin(
                        ("iter-item", option),
                        definitions,
                        trail=trail,
                        depth=depth + 1,
                    ))
            elif candidate[0] == "binding":
                resolved.add(("iter-binding", candidate, ()))
            elif candidate[0] == "call-result":
                resolved.add((
                    "result-access",
                    candidate,
                    ("<iter-item>",),
                ))
            elif candidate[0] == "result-access":
                resolved.add((
                    "result-access",
                    candidate[1],
                    (*candidate[2], "<iter-item>"),
                ))
            elif candidate[0] == "aggregate":
                for member in candidate[2]:
                    resolved.update(v2_resolve_fast_origin(
                        member,
                        definitions,
                        trail=trail,
                        depth=depth + 1,
                    ))
            elif candidate[0] == "constant-tuple":
                # LOAD_CONST tuples have exact, prevalidated membership.  In
                # particular, the empty tuple on the false branch of
                # ``mapping.get(...) or ()`` contributes no iterator member;
                # retaining a synthetic member creates a false ambiguous
                # callable origin in the comprehension body.
                resolved.update(
                    v2_fast_constant_origin(member)
                    for member in candidate[1]
                )
            elif (
                candidate[0] == "protocol-result"
                and candidate[1] == ("range",)
            ):
                # ``range`` iteration is the one protocol iterable whose
                # members are unconditionally exact built-in integers.  Keep
                # their later method calls (for example ``bit_length``)
                # statically typed without granting the same privilege to
                # sorted/list/tuple results that preserve arbitrary members.
                resolved.add(("iter-static", candidate, ()))
            elif (
                candidate[0] in {"call-result", "subscript"}
                and not v2_fast_origin_call_result_roots(candidate)
            ):
                resolved.add(("iter-static", candidate, ()))
            else:
                resolved.add(("iter-item", candidate))
        return frozenset(resolved)
    if kind == "unpack":
        index = expression[2] if len(expression) > 2 else None
        resolved: set[tuple[Any, ...]] = set()
        for candidate in v2_resolve_fast_origin(
            expression[1],
            definitions,
            trail=trail,
            depth=depth + 1,
        ):
            if (
                candidate
                and candidate[0] == "aggregate"
                and type(index) is int
                and 0 <= index < len(candidate[2])
            ):
                resolved.update(v2_resolve_fast_origin(
                    candidate[2][index],
                    definitions,
                    trail=trail,
                    depth=depth + 1,
                ))
            else:
                resolved.add(("unpack", candidate, index))
        return frozenset(resolved)
    if kind in {"subscript", "maybe-unbound"}:
        suffix = expression[2:]
        return frozenset(
            (kind, candidate, *suffix)
            for candidate in v2_resolve_fast_origin(
                expression[1],
                definitions,
                trail=trail,
                depth=depth + 1,
            )
        )
    return frozenset({expression})


def v2_fast_origin_call_result_roots(
    expression: tuple[Any, ...],
) -> frozenset[tuple[Any, ...]]:
    roots: set[tuple[Any, ...]] = set()

    def visit_nested_provenance(candidate: Any, depth: int) -> None:
        if depth > V2_REFUSAL_STATE_DEPTH_CAP or type(candidate) is not tuple:
            return
        if not candidate:
            return
        if type(candidate[0]) is tuple:
            for nested in candidate:
                visit_nested_provenance(nested, depth + 1)
            return
        if candidate[0] == "binding":
            roots.add(candidate)
            return
        for part in candidate[1:]:
            if type(part) is not tuple:
                continue
            if part and type(part[0]) is tuple:
                for nested in part:
                    visit_nested_provenance(nested, depth + 1)
            else:
                visit_nested_provenance(part, depth + 1)

    def visit(candidate: Any, depth: int) -> None:
        if depth > V2_REFUSAL_STATE_DEPTH_CAP or type(candidate) is not tuple:
            return
        if not candidate:
            return
        if v2_fast_origin_is_exact_json(candidate):
            # Audited detached JSON severs executable provenance from the
            # input object graph. Its recursively exact members therefore do
            # not require derived-result authority from producer arguments.
            return
        kind = candidate[0]
        if kind == "call-result":
            callable_origin = candidate[1]
            if (
                type(callable_origin) is tuple
                and callable_origin
                and callable_origin[0] == "binding"
            ):
                roots.add(callable_origin)
            elif (
                type(callable_origin) is tuple
                and callable_origin
                and callable_origin[0] == "attribute"
                and callable_origin[1]
                and callable_origin[1][0] == "binding"
            ):
                base = callable_origin[1]
                roots.add((
                    "binding",
                    base[1],
                    base[2],
                    (*base[3], *callable_origin[2]),
                ))
            elif (
                type(callable_origin) is tuple
                and callable_origin
                and callable_origin[0] == "nested-function"
            ):
                # The nested code body is audited transitively.  Retain its
                # exact invocation inputs as the constructed-result root so
                # a local helper returning parameter-derived rows does not
                # become an unrooted factory merely because its callable is
                # represented by MAKE_FUNCTION rather than a global binding.
                visit_nested_provenance(callable_origin[2], depth + 1)
                if len(candidate) >= 3:
                    visit_nested_provenance(candidate[2], depth + 1)
            else:
                visit(callable_origin, depth + 1)
            return
        if kind in {
            "aggregate",
            "aggregate-map-values",
            "attribute",
            "choice",
            "derived",
            "dict-copy",
            "dict-view",
            "iter-item",
            "maybe-unbound",
            "mutated-member",
            "protocol-result",
            "result-access",
            "subscript",
            "unpack",
        }:
            for part in candidate[1:]:
                if type(part) is tuple:
                    if part and type(part[0]) is tuple:
                        for nested in part:
                            visit(nested, depth + 1)
                    else:
                        visit(part, depth + 1)

    visit(expression, 0)
    return frozenset(roots)


def v2_fast_origin_is_static(expression: tuple[Any, ...]) -> bool:
    if not expression:
        return False
    if v2_fast_origin_is_exact_json(expression):
        return True
    kind = expression[0]
    if kind in {
        "constant",
        "iter-static",
        "nested-function",
        "static",
        "static-callable",
    }:
        return True
    if kind == "attribute":
        if v2_fast_origin_is_exact_json(expression[1]):
            # Exact JSON proves a hook-free built-in value, not a particular
            # receiver type or method contract.  Bound methods can still
            # execute protocols on their arguments (for example str.format
            # or list.index), so they require a dedicated audited model.
            return False
        if (
            expression[1]
            and expression[1][0] == "protocol-result"
            and expression[1][1] == ("set",)
            and expression[2] == ("issubset",)
        ):
            return True
        if expression[2] == ("append",):
            receiver = expression[1]
            if (
                receiver
                and receiver[0] == "subscript"
                and receiver[1]
                and receiver[1][0] == "aggregate"
                and receiver[1][1] == "BUILD_LIST"
                and receiver[1][2]
                and all(
                    member
                    and member[0] == "aggregate"
                    and member[1] == "BUILD_LIST"
                    for member in receiver[1][2]
                )
            ):
                # Indexing an exact built-in list whose bounded possibility
                # set contains only exact built-in lists cannot resolve to a
                # user-defined ``append`` implementation.  The index may
                # still raise normally, but no dynamic descriptor executes.
                return True
        return v2_fast_origin_is_static(expression[1])
    if kind == "aggregate":
        # BUILD_LIST/SET/TUPLE/MAP produce exact built-in containers even
        # when their members are dynamic. Calling a base container method is
        # therefore a statically known receiver operation; member origins are
        # still traversed separately for subscript/unpack/call-result use.
        return True
    if kind == "iter-item":
        source = expression[1]
        while source and source[0] == "derived" and source[1] in {
            "GET_ITER",
            "GET_YIELD_FROM_ITER",
        }:
            source = source[2]
        return (
            source
            and source[0] == "protocol-result"
            and source[1] == ("range",)
        )
    if kind == "derived":
        return all(
            type(part) is not tuple or v2_fast_origin_is_static(part)
            for part in expression[2:]
        )
    if kind == "protocol-result":
        return expression[3] is True
    return False


def v2_fast_origin_requires_unmodeled_bound_protocol(
    expression: tuple[Any, ...],
) -> bool:
    """Return whether an unmodeled bound call needs protocol auditing.

    Static callable admission is recursive: derived values, iterator items,
    and nested attribute wrappers can all be accepted without having a small
    top-level origin tag. Keep this gate recursive as well so a new static
    origin shape cannot silently bypass argument-protocol validation. A
    retained aggregate reference is intentionally included even though it is
    not generally static: using a method on that reference is itself the
    protocol escape that this check must reject.
    """
    if not expression or expression[0] == "binding":
        return False
    return (
        expression[0] == "aggregate-reference"
        or v2_fast_origin_is_static(expression)
    )


def v2_code_access_analysis(
    code: types.CodeType,
    *,
    context: dict[str, Any],
    depth: int = 0,
    merge_nested_bindings: bool = True,
    constants_prevalidated: bool = False,
    entry_parameter_origins: Mapping[
        str,
        tuple[Any, ...],
    ] | None = None,
    entry_freevar_origins: Mapping[
        str,
        tuple[Any, ...],
    ] | None = None,
) -> dict[str, Any]:
    if depth > V2_REFUSAL_STATE_DEPTH_CAP:
        raise EvidenceFailed("refusal-state code traversal exceeds its depth cap")
    if not constants_prevalidated:
        # dis.get_instructions renders constant argument representations.
        # Validate and bound the exact constant graph first so dis cannot
        # perform an unbounded integer/string conversion of untrusted code.
        v2_code_semantic_projection(
            code,
            context=context,
            depth=depth,
        )
    instructions = v2_analysis_instructions(code)
    v2_refusal_charge(context, "instructions", len(instructions))
    if any(
        type(constant) is str
        and constant in V2_REFLECTIVE_NAMESPACE_ATTRIBUTES
        for constant in code.co_consts
    ):
        raise EvidenceFailed(
            "refusal callback contains a reflective namespace name in "
            f"{code.co_qualname}; provide an explicit bounded external-state "
            "projection"
        )
    accesses: defaultdict[str, set[str]] = defaultdict(set)
    module_paths: defaultdict[str, set[tuple[str, ...]]] = defaultdict(set)
    bare_global_names: set[str] = set()
    called_global_names: set[str] = set()
    called_global_paths: defaultdict[
        str,
        set[tuple[str, ...]],
    ] = defaultdict(set)
    call_result_paths: defaultdict[str, set[tuple[str, ...]]] = defaultdict(set)
    global_path_call_result_paths: defaultdict[
        str,
        defaultdict[tuple[str, ...], set[tuple[str, ...]]],
    ] = defaultdict(lambda: defaultdict(set))
    freevar_paths: defaultdict[str, set[tuple[str, ...]]] = defaultdict(set)
    bare_freevar_names: set[str] = set()
    called_freevar_names: set[str] = set()
    called_freevar_paths: defaultdict[
        str,
        set[tuple[str, ...]],
    ] = defaultdict(set)
    freevar_call_result_paths: defaultdict[
        str,
        set[tuple[str, ...]],
    ] = defaultdict(set)
    freevar_path_call_result_paths: defaultdict[
        str,
        defaultdict[tuple[str, ...], set[tuple[str, ...]]],
    ] = defaultdict(lambda: defaultdict(set))
    parameter_names = frozenset(v2_code_parameter_names(code))
    inherited_parameter_names: set[str] = set()

    def collect_entry_parameter_names(
        candidate: Any,
        *,
        depth: int = 0,
    ) -> None:
        if depth > V2_REFUSAL_STATE_DEPTH_CAP or type(candidate) is not tuple:
            return
        if not candidate:
            return
        if type(candidate[0]) is tuple:
            for nested in candidate:
                collect_entry_parameter_names(nested, depth=depth + 1)
            return
        if (
            candidate[0] == "binding"
            and candidate[1] == "parameter"
            and type(candidate[2]) is str
        ):
            inherited_parameter_names.add(candidate[2])
            return
        for part in candidate[1:]:
            if type(part) is tuple:
                collect_entry_parameter_names(part, depth=depth + 1)

    for entry_origins in (
        entry_parameter_origins,
        entry_freevar_origins,
    ):
        if entry_origins is None:
            continue
        for origin in entry_origins.values():
            collect_entry_parameter_names(origin)
    effective_parameter_names = frozenset({
        *parameter_names,
        *inherited_parameter_names,
    })
    parameter_paths: defaultdict[str, set[tuple[str, ...]]] = defaultdict(set)
    bare_parameter_names: set[str] = set()
    called_parameter_names: set[str] = set()
    called_parameter_paths: defaultdict[
        str,
        set[tuple[str, ...]],
    ] = defaultdict(set)
    parameter_call_result_paths: defaultdict[
        str,
        set[tuple[str, ...]],
    ] = defaultdict(set)
    parameter_path_call_result_paths: defaultdict[
        str,
        defaultdict[tuple[str, ...], set[tuple[str, ...]]],
    ] = defaultdict(lambda: defaultdict(set))
    protocol_global_names: set[str] = set()
    protocol_freevar_names: set[str] = set()
    protocol_parameter_names: set[str] = set()
    mapping_key_protocol_global_names: set[str] = set()
    mapping_key_protocol_freevar_names: set[str] = set()
    mapping_key_protocol_parameter_names: set[str] = set()
    contains_protocol_global_names: set[str] = set()
    contains_protocol_freevar_names: set[str] = set()
    contains_protocol_parameter_names: set[str] = set()
    operation_protocol_global_paths: defaultdict[
        str,
        defaultdict[tuple[str, ...], set[str]],
    ] = defaultdict(lambda: defaultdict(set))
    operation_protocol_freevar_paths: defaultdict[
        str,
        defaultdict[tuple[str, ...], set[str]],
    ] = defaultdict(lambda: defaultdict(set))
    operation_protocol_parameter_paths: defaultdict[
        str,
        defaultdict[tuple[str, ...], set[str]],
    ] = defaultdict(lambda: defaultdict(set))
    static_subscript_calls: list[dict[str, Any]] = []
    effective_entry_parameter_origins = entry_parameter_origins
    if (
        context.get("active_executable_function")
        is V2_FIXTURE_STRICT_READ_PARAMETER_CONTRACT_CALLABLE
        and code
        is V2_FIXTURE_STRICT_READ_PARAMETER_CONTRACT_CALLABLE.__code__
        and V2_FIXTURE_SELECTED_RESOURCE_IMPLEMENTATION_CAPABILITY
        in context["authorized_external_capabilities"]
    ):
        # The exact selected-resource wrapper reaches this private reader only
        # after validating and supplying both state bindings.  Represent that
        # private call contract explicitly so its optional public defaults do
        # not masquerade as reachable values inside guarded tuple operations.
        exact_integer = v2_fast_constant_origin(0)
        identity_origin = (
            "aggregate",
            "BUILD_TUPLE",
            (exact_integer,) * 7,
        )
        parent_row_origin = (
            "aggregate",
            "BUILD_TUPLE",
            (
                v2_fast_constant_origin("."),
                exact_integer,
                exact_integer,
                exact_integer,
            ),
        )
        parent_identities_origin = (
            "aggregate",
            "BUILD_TUPLE",
            (parent_row_origin,),
        )
        effective_entry_parameter_origins = {
            **(
                dict(entry_parameter_origins)
                if entry_parameter_origins is not None
                else {}
            ),
            "_expected_identity": identity_origin,
            "_expected_parent_identities": parent_identities_origin,
        }
    fast_origin_data = v2_fast_local_origin_dataflow(
        instructions,
        code,
        active_executable_function=context.get(
            "active_executable_function"
        ),
        parameter_origins=effective_entry_parameter_origins,
        freevar_origins=entry_freevar_origins,
    )
    fast_origin_definitions = fast_origin_data["definitions"]
    descriptor_slot_mutation_contract = next(
        (
            (parameter_names, admits_direct_base_setitem)
            for (
                contract_callable,
                contract_code,
                parameter_names,
                admits_direct_base_setitem,
            ) in V2_FIXTURE_DESCRIPTOR_SLOT_MUTATION_CODE_CONTRACTS
            if context.get("active_executable_function")
            is contract_callable
            and code is contract_code
            and V2_FIXTURE_SELECTED_RESOURCE_IMPLEMENTATION_CAPABILITY
            in context["authorized_external_capabilities"]
        ),
        None,
    )
    required_environment_capabilities = frozenset({
        V2_FIXTURE_SELECTED_RESOURCE_SCOPE_CONTROL_CAPABILITY,
        "process-python-environment",
    })
    environment_code_contracts = tuple(
        contract
        for contract in V2_FIXTURE_ENVIRONMENT_MUTATION_CODE_CONTRACTS
        if code is contract[1]
    )
    if environment_code_contracts and not any(
        context.get("active_executable_function") is contract_callable
        and required_environment_capabilities.issubset(
            context["authorized_external_capabilities"]
        )
        for contract_callable, _contract_code, _operations
        in environment_code_contracts
    ):
        # These helpers are authority-bearing only as the exact callable,
        # exact code, and exact capability triple.  Refuse that mismatch at
        # the contract boundary before ordinary bytecode analysis can produce
        # an incidental container/protocol diagnostic from an earlier
        # instruction in the helper body.
        raise EvidenceFailed(
            "refusal-state process-environment helper is outside its "
            f"exact callable operation contract in {code.co_qualname}"
        )
    environment_mutation_contract = next(
        (
            frozenset(operations)
            for contract_callable, contract_code, operations
            in environment_code_contracts
            if context.get("active_executable_function")
            is contract_callable
            and code is contract_code
            and required_environment_capabilities.issubset(
                context["authorized_external_capabilities"]
            )
        ),
        frozenset(),
    )
    environment_snapshot_contract = bool(
        context.get("active_executable_function")
        is V2_BOUNDED_PROCESS_ENVIRONMENT_SNAPSHOT_CALLABLE
        and code is V2_BOUNDED_PROCESS_ENVIRONMENT_SNAPSHOT_CALLABLE.__code__
        and "process-python-environment"
        in context["authorized_external_capabilities"]
    )
    retained_reconstruction_contract = any(
        context.get("active_executable_function") is candidate
        and code is contract_code
        for candidate, contract_code
        in V2_TRANSPORT_CACHE_TRANSACTION_CODE_CONTRACTS
    )
    transport_cache_mutation_contract = next(
        (
            operations
            for contract_callable, contract_code, operations
            in V2_TRANSPORT_CACHE_MUTATION_CODE_CONTRACTS
            if context.get("active_executable_function")
            is contract_callable
            and code is contract_code
        ),
        frozenset(),
    )

    def exact_descriptor_slot_parameter_origin(
        expression: tuple[Any, ...],
    ) -> bool:
        if descriptor_slot_mutation_contract is None:
            return False
        parameter_names, _admits_direct_base_setitem = (
            descriptor_slot_mutation_contract
        )
        resolved = v2_resolve_fast_origin(
            expression,
            fast_origin_definitions,
        )
        return bool(resolved) and all(
            origin
            and origin[0] == "binding"
            and origin[1] == "parameter"
            and origin[2] in parameter_names
            and origin[3] == ()
            for origin in resolved
        )

    def exact_descriptor_slot_base_setitem(
        expression: tuple[Any, ...],
    ) -> bool:
        if not (
            descriptor_slot_mutation_contract is not None
            and descriptor_slot_mutation_contract[1]
            and expression
            and expression[0:2] == ("aggregate", "MUTATION_CALL")
            and len(expression) == 3
            and len(expression[2]) == 4
            and expression[2][0]
            == (
                "attribute",
                ("binding", "global", "list", ()),
                ("__setitem__",),
            )
        ):
            return False
        _callable_origin, receiver, key_origin, stored_value = expression[2]
        key_is_exact, key = v2_fast_exact_key_from_origin(key_origin)
        return bool(
            exact_descriptor_slot_parameter_origin(receiver)
            and key_is_exact
            and type(key) is int
            and key == 0
            and stored_value
            and stored_value[0] == "call-result"
            and stored_value[1]
            == (
                "attribute",
                ("binding", "global", "os", ()),
                ("open",),
            )
        )

    def exact_descriptor_slot_store(
        expression: tuple[Any, ...],
    ) -> bool:
        if not (
            expression
            and expression[0:2] == ("aggregate", "STORE_SUBSCR")
            and len(expression) == 3
            and len(expression[2]) == 3
        ):
            return False
        receiver, key_origin, stored_value = expression[2]
        key_is_exact, key = v2_fast_exact_key_from_origin(key_origin)
        if not (
            exact_descriptor_slot_parameter_origin(receiver)
            and key_is_exact
            and type(key) is int
            and key == 0
        ):
            return False
        if stored_value == v2_fast_constant_origin(None):
            return True

        def exact_slot_zero_value(origin: tuple[Any, ...]) -> bool:
            if origin and origin[0] == "choice":
                return bool(origin[1]) and all(
                    exact_slot_zero_value(option) for option in origin[1]
                )
            if origin and origin[0] == "subscript":
                return bool(
                    exact_descriptor_slot_parameter_origin(origin[1])
                    and type(origin[2]) is int
                    and origin[2] == 0
                )
            return bool(
                origin
                and origin[0] == "mutated-member"
                and exact_descriptor_slot_parameter_origin(origin[1])
                and origin[2] == ("subscript", 0)
            )

        return exact_slot_zero_value(stored_value)

    def mutation_receiver_expression(
        expression: tuple[Any, ...],
        mode: str,
    ) -> tuple[Any, ...]:
        expected_kind = (
            "STORE_SUBSCR"
            if mode == "store-subscript"
            else "DELETE_SUBSCR"
            if mode == "delete-subscript"
            else None
        )
        if (
            expected_kind is not None
            and expression
            and expression[0:2] == ("aggregate", expected_kind)
            and len(expression) == 3
            and expression[2]
        ):
            return expression[2][0]
        return expression

    def exact_transport_cache_receiver_origin(
        expression: tuple[Any, ...],
    ) -> bool:
        resolved = v2_resolve_fast_origin(
            expression,
            fast_origin_definitions,
        )
        return bool(resolved) and all(
            origin
            == (
                "binding",
                "global",
                "_v2_child_transport_cache",
                (),
            )
            for origin in resolved
        )

    def record_exact_transport_cache_operation(
        expression: tuple[Any, ...],
        mode: str,
    ) -> bool:
        if not (
            mode in transport_cache_mutation_contract
            and mode in {"store-subscript", "delete-subscript"}
        ):
            return False
        receiver = mutation_receiver_expression(expression, mode)
        if not exact_transport_cache_receiver_origin(receiver):
            return False
        operation_protocol_global_paths[
            "_v2_child_transport_cache"
        ][()].add(
            f"{V2_AUDITED_TRANSPORT_CACHE_OPERATION_PREFIX}{mode}"
        )
        return True

    def exact_environment_receiver_origin(
        expression: tuple[Any, ...],
        expected_path: tuple[str, ...],
    ) -> bool:
        resolved = v2_resolve_fast_origin(
            expression,
            fast_origin_definitions,
        )
        normalized: list[tuple[str, ...]] = []
        for origin in resolved:
            if (
                origin
                and origin[0] == "binding"
                and origin[1:3] == ("global", "os")
            ):
                normalized.append(origin[3])
                continue
            if (
                origin
                and origin[0] == "attribute"
                and origin[1]
                and origin[1][0] == "binding"
                and origin[1][1:3] == ("global", "os")
            ):
                normalized.append((*origin[1][3], *origin[2]))
                continue
            return False
        return bool(normalized) and all(
            path == expected_path for path in normalized
        )

    def protected_environment_receiver_origin(
        expression: tuple[Any, ...],
        mode: str,
    ) -> bool:
        """Recognize protected environment receivers without authorizing them."""
        receiver = mutation_receiver_expression(expression, mode)
        resolved = v2_resolve_fast_origin(
            receiver,
            fast_origin_definitions,
        )
        if not resolved:
            return False
        normalized: list[tuple[str, ...]] = []
        for origin in resolved:
            if (
                origin
                and origin[0] == "binding"
                and origin[1:3] == ("global", "os")
            ):
                normalized.append(origin[3])
                continue
            if (
                origin
                and origin[0] == "attribute"
                and origin[1]
                and origin[1][0] == "binding"
                and origin[1][1:3] == ("global", "os")
            ):
                normalized.append((*origin[1][3], *origin[2]))
                continue
            return False
        protected_roots = {"environ", "environb"}
        if any(path and path[0] in protected_roots for path in normalized):
            return True
        return bool(
            normalized
            and all(path == () for path in normalized)
            and mode in {
                "store-attribute:environ",
                "store-attribute:environb",
                "delete-attribute:environ",
                "delete-attribute:environb",
            }
        )

    def exact_environment_snapshot_receiver(
        expression: tuple[Any, ...],
    ) -> bool:
        return bool(
            environment_snapshot_contract
            and exact_environment_receiver_origin(
                expression,
                ("environb",),
            )
        )

    def record_exact_environment_operation(
        expression: tuple[Any, ...],
        mode: str,
    ) -> bool:
        matching_paths = tuple(
            path
            for contract_mode, path in environment_mutation_contract
            if contract_mode == mode
        )
        if len(matching_paths) != 1:
            return False
        path = matching_paths[0]
        receiver = mutation_receiver_expression(expression, mode)
        if not exact_environment_receiver_origin(receiver, path):
            return False
        if mode in {"store-subscript", "delete-subscript"}:
            expected_length = 3 if mode == "store-subscript" else 2
            if not (
                expression
                and len(expression) == 3
                and len(expression[2]) == expected_length
            ):
                return False
            key_origin = expression[2][1]
            if key_origin != ("binding", "parameter", "key", ()):
                return False
            if (
                mode == "store-subscript"
                and expression[2][2]
                != ("binding", "parameter", "value", ())
            ):
                return False
        operation_protocol_global_paths["os"][path].add(
            f"{V2_AUDITED_ENVIRONMENT_OPERATION_PREFIX}{mode}"
        )
        return True

    environment_attribute_mutation_source_load_indices: set[int] = set()
    if environment_mutation_contract:
        allowed_attribute_modes = {
            mode
            for mode, path in environment_mutation_contract
            if path == () and mode.startswith("store-attribute:")
        }
        for load_index, load_instruction in enumerate(instructions):
            if not (
                load_instruction.opname in {"LOAD_GLOBAL", "LOAD_NAME"}
                and load_instruction.argval == "os"
            ):
                continue
            for later in instructions[
                load_index + 1 : min(len(instructions), load_index + 5)
            ]:
                if later.opname == "STORE_ATTR" and (
                    f"store-attribute:{later.argval}"
                    in allowed_attribute_modes
                ):
                    environment_attribute_mutation_source_load_indices.add(
                        load_index
                    )
                    break
                if later.opname in {
                    "CALL",
                    "CALL_FUNCTION_EX",
                    "CALL_KW",
                    "LOAD_GLOBAL",
                    "LOAD_NAME",
                    "RETURN_CONST",
                    "RETURN_VALUE",
                }:
                    break

    def record_static_subscript_call(
        *,
        source_kind: str,
        source_name: str,
        source_path: tuple[str, ...],
        path_start: int,
        path_end: int,
    ) -> None:
        result = v2_static_subscript_call(
            instructions,
            path_start,
            path_end,
        )
        if result is None:
            return
        key, call_index = result
        static_subscript_calls.append({
            "source_kind": source_kind,
            "source_name": source_name,
            "source_path": source_path,
            "key": key,
            "call_result_path": v2_call_result_access_path(
                instructions,
                call_index,
            ),
        })

    def record_result_path(
        root: tuple[Any, ...],
        result_path: tuple[str, ...],
    ) -> None:
        if not result_path or root[0] != "binding":
            return
        source_kind, source_name, source_path = root[1], root[2], root[3]
        if (
            source_kind == "global"
            and (
                not source_path
                and source_name in V2_SCALAR_PROTOCOL_RESULTS
                or (source_name, source_path)
                in V2_SCALAR_MODULE_CALL_PATHS
            )
        ):
            return
        if source_kind == "global":
            if source_path:
                paths = global_path_call_result_paths[source_name][source_path]
            else:
                paths = call_result_paths[source_name]
        elif source_kind == "freevar":
            if source_path:
                paths = freevar_path_call_result_paths[source_name][source_path]
            else:
                paths = freevar_call_result_paths[source_name]
        elif source_kind == "parameter":
            if source_path:
                paths = parameter_path_call_result_paths[source_name][source_path]
            else:
                paths = parameter_call_result_paths[source_name]
        else:
            raise EvidenceFailed(
                "refusal-state fast-local result has an unsupported root"
            )
        paths.discard(())
        paths.add(result_path)

    def record_binding_access(
        binding: tuple[Any, ...],
        *,
        call_index: int | None,
    ) -> None:
        source_kind, source_name, source_path = (
            binding[1],
            binding[2],
            binding[3],
        )
        result_path = (
            ()
            if call_index in fast_origin_data["exact_result_call_indices"]
            else v2_call_result_access_path(instructions, call_index)
            if call_index is not None
            else ()
        )
        scalar_call = (
            call_index is not None
            and source_kind == "global"
            and (
                not source_path
                and source_name in V2_SCALAR_PROTOCOL_RESULTS
                or (source_name, source_path)
                in V2_SCALAR_MODULE_CALL_PATHS
            )
        )
        if source_kind == "global":
            if source_path:
                module_paths[source_name].add(source_path)
                if call_index is not None:
                    called_global_paths[source_name].add(source_path)
                    if not scalar_call:
                        global_path_call_result_paths[source_name][
                            source_path
                        ].add(result_path)
            else:
                bare_global_names.add(source_name)
                if call_index is not None:
                    called_global_names.add(source_name)
                    if not scalar_call:
                        call_result_paths[source_name].add(result_path)
        elif source_kind == "freevar":
            if source_path:
                freevar_paths[source_name].add(source_path)
                if call_index is not None:
                    called_freevar_paths[source_name].add(source_path)
                    freevar_path_call_result_paths[source_name][
                        source_path
                    ].add(result_path)
            else:
                bare_freevar_names.add(source_name)
                if call_index is not None:
                    called_freevar_names.add(source_name)
                    freevar_call_result_paths[source_name].add(result_path)
        elif source_kind == "parameter":
            if source_path:
                parameter_paths[source_name].add(source_path)
                if call_index is not None:
                    called_parameter_paths[source_name].add(source_path)
                    parameter_path_call_result_paths[source_name][
                        source_path
                    ].add(result_path)
            else:
                bare_parameter_names.add(source_name)
                if call_index is not None:
                    called_parameter_names.add(source_name)
                    parameter_call_result_paths[source_name].add(result_path)
        else:
            raise EvidenceFailed(
                "refusal-state fast-local binding has an unsupported origin"
            )

    def record_fast_expression(
        expression: tuple[Any, ...],
        *,
        call_index: int | None,
    ) -> None:
        resolved = v2_resolve_fast_origin(
            expression,
            fast_origin_definitions,
        )
        if call_index is not None and len(resolved) != 1:
            alternatives_are_projectable = bool(resolved) and (
                all(
                    v2_fast_origin_is_static(origin)
                    or origin[0] == "result-access"
                    for origin in resolved
                )
            )
            if not alternatives_are_projectable:
                call_instruction = instructions[call_index]
                call_line = (
                    call_instruction.positions.lineno
                    if call_instruction.positions is not None
                    else None
                )
                raise EvidenceFailed(
                    "refusal-state callable reaches a control-flow-ambiguous "
                    f"local alias in {code.co_qualname} at line {call_line!r}"
                )
        for origin in resolved:
            kind = origin[0]
            if kind == "binding":
                record_binding_access(origin, call_index=call_index)
                continue
            if kind == "result-access":
                roots = v2_fast_origin_call_result_roots(origin[1])
                call_result = origin[1]
                callable_origin = (
                    call_result[1]
                    if call_result[0] == "call-result"
                    else V2_FAST_ORIGIN_UNKNOWN
                )
                if (
                    not roots
                    and callable_origin[0] == "subscript"
                    and callable_origin[1][0] == "binding"
                    and type(callable_origin[2]) in {str, int}
                ):
                    base = callable_origin[1]
                    static_subscript_calls.append({
                        "source_kind": base[1],
                        "source_name": base[2],
                        "source_path": base[3],
                        "key": callable_origin[2],
                        "call_result_path": origin[2],
                    })
                    continue
                if (
                    not roots
                    and context.get("active_executable_function")
                    is v2_validate_history_projection
                    and callable_origin[0] == "attribute"
                    and callable_origin[2] == ("get",)
                    and callable_origin[1]
                    and callable_origin[1][0] == "subscript"
                    and callable_origin[1][1]
                    and callable_origin[1][1][0]
                    in {"aggregate", "mapping-merge"}
                    and (
                        origin[2] == V2_DERIVED_CALL_RESULT_PATH
                        or origin[2]
                        and origin[2][0] == "<iter-item>"
                        and all(
                            part in {"get", "strip"}
                            for part in origin[2][1:]
                        )
                    )
                ):
                    # The exact history validator first closes and validates
                    # every decoded JSON row, then builds a local ID-indexed
                    # map and iterates ``row.get(...)`` results from it.  This
                    # identity-bound exception admits only that local mapping
                    # receiver; same-code clones and parameter/freevar aliases
                    # retain no such authority.
                    continue
                if len(roots) != 1:
                    raise EvidenceFailed(
                        "refusal-state stored call result has an ambiguous root "
                        f"in {code.co_qualname}: "
                        + repr(tuple(sorted(
                            roots,
                            key=v2_fast_origin_sort_key,
                        )))
                        + f" for {origin!r}"
                    )
                record_result_path(next(iter(roots)), origin[2])
                continue
            if kind == "call-result":
                if call_index is not None:
                    raise EvidenceFailed(
                        "refusal-state callable invokes a dynamically produced "
                        "local result (a dynamically produced call result) in "
                        f"{code.co_qualname}"
                    )
                continue
            if kind == "iter-binding":
                if call_index is not None:
                    binding = origin[1]
                    if binding[1] != "parameter":
                        raise EvidenceFailed(
                            "refusal-state callable invokes a method from an "
                            "unproven iterated binding in "
                            f"{code.co_qualname}"
                        )
                continue
            if kind == "iter-static":
                continue
            if kind == "subscript":
                base, key = origin[1], origin[2]
                roots = v2_fast_origin_call_result_roots(base)
                for root in roots:
                    record_result_path(root, V2_DERIVED_CALL_RESULT_PATH)
                if call_index is not None and base[0] == "binding":
                    if type(key) not in {str, int}:
                        raise EvidenceFailed(
                            "refusal-state stored subscript key is not exact"
                        )
                    static_subscript_calls.append({
                        "source_kind": base[1],
                        "source_name": base[2],
                        "source_path": base[3],
                        "key": key,
                        "call_result_path": v2_call_result_access_path(
                            instructions,
                            call_index,
                        ),
                    })
                    continue
            if (
                call_index is not None
                and call_index
                in fast_origin_data["exact_result_call_indices"]
                and kind == "attribute"
                and origin[1]
                and origin[1][0] == "dict-copy"
                and origin[2] in {("get",), ("pop",)}
            ):
                # ``dict.copy(exact_mapping)`` allocates an exact plain dict
                # even when the source contents are opaque to static
                # dataflow.  The call-site analyzer has already required a
                # direct method window, exact call shape, inert lookup key,
                # and receiver-key protocol validation before marking this
                # call as an exact-result call.  Admit only those modeled
                # plain-dict methods here; a stored method alias never gains
                # the exact-result marker and still fails closed.
                continue
            if v2_fast_origin_is_static(origin):
                continue
            if call_index is not None:
                if kind in {"maybe-unbound", "unbound"}:
                    raise EvidenceFailed(
                        "refusal-state callable reaches a possibly unbound "
                        f"local alias in {code.co_qualname}"
                    )
                raise EvidenceFailed(
                    "refusal-state callable invokes an unproven local value "
                    f"in {code.co_qualname}: {origin!r}"
                )

    def record_dynamic_result_use(expression: tuple[Any, ...]) -> None:
        for origin in v2_resolve_fast_origin(
            expression,
            fast_origin_definitions,
        ):
            for root in v2_fast_origin_call_result_roots(origin):
                record_result_path(root, V2_DERIVED_CALL_RESULT_PATH)

    def record_protocol_argument_use(
        expression: tuple[Any, ...],
        *,
        operation_label: str = "protocol",
    ) -> None:
        resolved = v2_resolve_fast_origin(
            expression,
            fast_origin_definitions,
        )
        visited: set[tuple[Any, ...]] = set()

        def visit(origin: tuple[Any, ...]) -> None:
            if origin in visited:
                return
            visited.add(origin)
            if v2_fast_origin_is_exact_json(origin):
                return
            kind = origin[0]
            if kind == "aggregate-reference":
                raise EvidenceFailed(
                    "refusal-state protocol reaches an opaque aggregate "
                    f"reference in {code.co_qualname}: "
                    f"operation={operation_label!r}"
                )
            if kind == "binding":
                source_kind, source_name, source_path = (
                    origin[1],
                    origin[2],
                    origin[3],
                )
                if (
                    source_path
                    and source_kind in {"global", "freevar"}
                ):
                    # Path-bearing global/closure origins are already exact
                    # state-projected at that path.  Protocol-validating the
                    # containing object would turn ``os.environb`` into a
                    # protocol use of the module ``os`` and reject the wrong
                    # value.
                    return
                # Validate the containing exact runtime value when a static
                # subscript or attribute path feeds a protocol.  This is
                # intentionally broader than validating only the selected
                # member, but it avoids executing the lookup during preflight
                # and still rejects any hook-bearing value in the container.
                if source_kind == "global":
                    protocol_global_names.add(source_name)
                elif source_kind == "freevar":
                    protocol_freevar_names.add(source_name)
                elif source_kind == "parameter":
                    protocol_parameter_names.add(source_name)
                else:
                    raise EvidenceFailed(
                        "refusal-state protocol call reaches an unsupported "
                        f"binding in {code.co_qualname}"
                    )
                return
            if kind == "iter-binding":
                binding = origin[1]
                visit(binding)
                return
            if kind in {
                "constant",
                "constant-tuple",
                "iter-static",
                "protocol-result",
                "static",
            }:
                return
            if kind == "dict-view":
                members = v2_fast_dict_view_members(origin)
                if members is None:
                    raise EvidenceFailed(
                        "refusal-state dict view receiver is not an exact "
                        f"built-in mapping in {code.co_qualname}"
                    )
                for member in members:
                    visit(member)
                return
            if kind == "aggregate":
                for member in origin[2]:
                    visit(member)
                return
            if kind == "aggregate-map-values":
                visit(origin[2])
                return
            if kind == "choice":
                for option in origin[1]:
                    visit(option)
                return
            if kind == "attribute":
                base = origin[1]
                if (
                    base
                    and base[0] == "binding"
                    and base[1] in {"global", "freevar"}
                ):
                    # The exact global/closure binding and accessed path are
                    # already retained by the ordinary access graph.  Its
                    # projected value, not the containing module/path object,
                    # is the protocol operand.  Marking the base itself as a
                    # protocol value would incorrectly reject exact Path
                    # properties and path-scoped external values such as
                    # ``os.environb``.
                    return
                visit(base)
                return
            if kind in {"derived", "mapping-merge"}:
                for part in origin[2:]:
                    if type(part) is tuple:
                        # Nested operands are retained in their pre-resolution
                        # form by the outer derived node.  Resolve each operand
                        # before classifying it so an attribute of a proven
                        # constructor result becomes a result-access contract,
                        # while an attribute of a parameter still reaches and
                        # validates that parameter binding.
                        for resolved_part in v2_resolve_fast_origin(
                            part,
                            fast_origin_definitions,
                        ):
                            visit(resolved_part)
                return
            if kind in {
                "iter-item",
                "subscript",
                "unpack",
                "maybe-unbound",
            }:
                visit(origin[1])
                return
            if kind == "suspended-nested":
                for argument in origin[2]:
                    visit(argument)
                return
            if kind in {"call-result", "result-access"}:
                # record_dynamic_result_use below attaches the explicit
                # derived-result contract to the originating callable.  The
                # callable projection then admits only an identity-listed
                # return contract; arbitrary factories remain fail-closed.
                return
            raise EvidenceFailed(
                "refusal-state protocol call argument has an unproven "
                f"origin in {code.co_qualname}: origin_kind={kind!r} "
                f"expression_kind={(expression[0] if expression else None)!r} "
                f"operation={operation_label!r} line={dynamic_use_line!r}"
            )

        for origin in resolved:
            visit(origin)

    def record_container_protocol_use(
        expression: tuple[Any, ...],
        *,
        contains: bool,
    ) -> None:
        """Validate receiver keys/members without conflating dict values."""
        if (
            not contains
            and exact_descriptor_slot_parameter_origin(expression)
        ):
            # The identity-pinned private helper contract guarantees an exact
            # one-element base list.  The key remains independently checked;
            # this suppresses only the receiver protocol needed by its slot
            # read/write, never containment or member protocols.
            return
        if not contains and any(
            mode in {"store-subscript", "delete-subscript"}
            and exact_environment_receiver_origin(expression, path)
            for mode, path in environment_mutation_contract
        ):
            return
        if not contains and exact_environment_snapshot_receiver(expression):
            module_paths["os"].add(("environb",))
            return
        visited: set[tuple[Any, ...]] = set()

        def visit(origin: tuple[Any, ...]) -> None:
            if origin in visited:
                return
            visited.add(origin)
            if v2_fast_origin_is_exact_json(origin):
                return
            kind = origin[0]
            if kind == "choice":
                for option in origin[1]:
                    visit(option)
                return
            if kind == "dict-copy":
                visit(origin[1])
                return
            if kind == "binding":
                source_kind, source_name, source_path = (
                    origin[1],
                    origin[2],
                    origin[3],
                )
                if (
                    context.get("active_executable_function")
                    is v2_build_inventory
                    and code is v2_build_inventory.__code__
                    and source_kind == "parameter"
                    and source_name == "snapshot"
                    and source_path
                    in {
                        ("all_issues",),
                        ("inventory",),
                        ("source",),
                    }
                ):
                    # v2_build_inventory admits only the two exact carrier
                    # classes and validates these outer payload types before
                    # reaching a container operation.  Retain the exact path;
                    # never turn this into authority for another function,
                    # parameter, descendant path, or same-code clone.
                    parameter_paths[source_name].add(source_path)
                    return
                if source_path:
                    raise EvidenceFailed(
                        "refusal-state container protocol reaches a "
                        f"path-bearing binding in {code.co_qualname}"
                    )
                targets = (
                    (
                        contains_protocol_global_names,
                        contains_protocol_freevar_names,
                        contains_protocol_parameter_names,
                    )
                    if contains
                    else (
                        mapping_key_protocol_global_names,
                        mapping_key_protocol_freevar_names,
                        mapping_key_protocol_parameter_names,
                    )
                )
                if source_kind == "global":
                    targets[0].add(source_name)
                elif source_kind == "freevar":
                    targets[1].add(source_name)
                elif source_kind == "parameter":
                    targets[2].add(source_name)
                else:
                    raise EvidenceFailed(
                        "refusal-state container protocol reaches an "
                        f"unsupported binding in {code.co_qualname}"
                    )
                return
            mapping_entries = v2_fast_aggregate_mapping_entries(origin)
            if mapping_entries is not None:
                for stored_key, _stored_value in mapping_entries:
                    record_protocol_argument_use(stored_key)
                return
            if contains:
                record_protocol_argument_use(origin)
                return
            if (
                kind == "aggregate"
                and origin[1] in {"BUILD_LIST", "BUILD_TUPLE"}
            ) or kind in {
                "constant",
                "constant-tuple",
                "protocol-result",
                "static",
            }:
                return
            record_protocol_argument_use(origin)

        for origin in v2_resolve_fast_origin(
            expression,
            fast_origin_definitions,
        ):
            visit(origin)

    def record_mutable_receiver_call(
        expression: tuple[Any, ...],
        method_name: str,
    ) -> None:
        """Retain an in-place special-method path on exact bindings."""
        visited: set[tuple[Any, ...]] = set()

        def visit(origin: tuple[Any, ...]) -> None:
            if origin in visited:
                return
            visited.add(origin)
            kind = origin[0]
            if kind == "choice":
                for option in origin[1]:
                    visit(option)
                return
            if kind in {"maybe-unbound", "derived"}:
                if len(origin) > 1 and type(origin[1]) is tuple:
                    visit(origin[1])
                return
            if kind != "binding":
                return
            source_kind, source_name, source_path = (
                origin[1],
                origin[2],
                origin[3],
            )
            method_path = (*source_path, method_name)
            if source_kind == "global":
                module_paths[source_name].add(method_path)
                called_global_paths[source_name].add(method_path)
            elif source_kind == "freevar":
                freevar_paths[source_name].add(method_path)
                called_freevar_paths[source_name].add(method_path)
            elif source_kind == "parameter":
                parameter_paths[source_name].add(method_path)
                called_parameter_paths[source_name].add(method_path)
            else:
                raise EvidenceFailed(
                    "refusal-state mutable receiver reaches an unsupported "
                    f"binding in {code.co_qualname}"
                )

        for origin in v2_resolve_fast_origin(
            expression,
            fast_origin_definitions,
        ):
            visit(origin)

    def record_operation_protocol_operand(
        expression: tuple[Any, ...],
        mode: str,
        *,
        inspect_local_members: bool = False,
    ) -> None:
        """Bind an opcode protocol to its runtime operand, not its members."""
        visited: set[tuple[Any, ...]] = set()

        def visit(origin: tuple[Any, ...]) -> None:
            if origin in visited:
                return
            visited.add(origin)
            if v2_fast_origin_is_exact_json(origin):
                return
            kind = origin[0]
            if kind == "choice":
                for option in origin[1]:
                    visit(option)
                return
            if kind in {"maybe-unbound", "iter-item", "unpack"}:
                visit(origin[1])
                return
            if kind == "binding":
                source_kind, source_name, source_path = (
                    origin[1],
                    origin[2],
                    origin[3],
                )
                if (
                    retained_reconstruction_contract
                    and mode == "context"
                    and source_kind == "global"
                    and source_name == "_v2_child_transport_cache_lock"
                    and source_path == ()
                ):
                    operation_protocol_global_paths[source_name][()].add(
                        V2_AUDITED_RETAINED_RECONSTRUCTION_OPERATION_PREFIX
                        + "context"
                    )
                    return
                targets = (
                    operation_protocol_global_paths
                    if source_kind == "global"
                    else operation_protocol_freevar_paths
                    if source_kind == "freevar"
                    else operation_protocol_parameter_paths
                    if source_kind == "parameter"
                    else None
                )
                if targets is None:
                    raise EvidenceFailed(
                        "refusal-state operation protocol reaches an "
                        f"unsupported binding in {code.co_qualname}"
                    )
                targets[source_name][source_path].add(mode)
                return
            if kind == "aggregate":
                if inspect_local_members:
                    record_protocol_argument_use(
                        origin,
                        operation_label=mode,
                    )
                return
            if (
                kind == "derived"
                and mode == "truth"
                and origin[1] in {"COMPARE_OP", "CONTAINS_OP", "IS_OP"}
            ):
                # These opcodes produce an exact bool.  Truth-testing that
                # bool cannot redispatch protocols on the compared operands;
                # their own opcode handlers remain responsible for any
                # equality, ordering, hashing, or containment hooks.
                return
            if kind in {
                "constant",
                "constant-tuple",
                "dict-copy",
                "protocol-result",
                "static",
            }:
                return
            if kind == "unknown":
                raise EvidenceFailed(
                    "refusal-state operation protocol has an unproven "
                    f"operand in {code.co_qualname}: mode={mode!r} "
                    f"origin_kind={kind!r} "
                    f"expression_kind={(expression[0] if expression else None)!r} "
                    f"line={dynamic_use_line!r}"
                )
            # A derived/subscript operand can still root in a runtime
            # binding.  Reuse the generic origin walker for that uncertain
            # case; direct exact containers above deliberately avoid member
            # recursion for truth, iteration, and reference-copying ops.
            record_protocol_argument_use(
                origin,
                operation_label=mode,
            )

        for origin in v2_resolve_fast_origin(
            expression,
            fast_origin_definitions,
        ):
            visit(origin)

    def record_external_mutation_receiver(
        expression: tuple[Any, ...],
        mode: str,
    ) -> None:
        """Bind a mutation receiver or refuse an unaddressable derived one."""
        if mode == "store-subscript" and exact_descriptor_slot_store(
            expression
        ):
            return
        receiver = mutation_receiver_expression(expression, mode)
        if exact_descriptor_slot_parameter_origin(receiver):
            raise EvidenceFailed(
                "refusal-state descriptor slot mutation is outside its "
                f"exact callable operation contract in {code.co_qualname}"
            )
        if record_exact_transport_cache_operation(expression, mode):
            return
        if (
            transport_cache_mutation_contract
            and exact_transport_cache_receiver_origin(receiver)
        ):
            raise EvidenceFailed(
                "refusal-state transport-cache mutation is outside its "
                f"exact callable operation contract in {code.co_qualname}"
            )
        if record_exact_environment_operation(expression, mode):
            return
        if environment_mutation_contract:
            raise EvidenceFailed(
                "refusal-state process-environment helper mutation is "
                "outside its exact callable operation contract in "
                f"{code.co_qualname}"
            )
        if protected_environment_receiver_origin(expression, mode):
            raise EvidenceFailed(
                "refusal-state process-environment mutation is outside its "
                f"exact callable operation contract in {code.co_qualname}"
            )
        expression = receiver
        visited: set[tuple[Any, ...]] = set()

        def is_exact_local_mutation_receiver(
            origin: tuple[Any, ...],
        ) -> bool:
            if not origin:
                return False
            if origin[0] in {"aggregate", "dict-copy"}:
                return True
            return bool(
                origin[0] == "mapping-merge"
                and is_exact_local_mutation_receiver(origin[1])
            )

        def visit(origin: tuple[Any, ...]) -> None:
            if origin in visited:
                return
            visited.add(origin)
            kind = origin[0]
            if kind == "choice":
                for option in origin[1]:
                    visit(option)
                return
            if kind == "binding":
                record_operation_protocol_operand(origin, mode)
                return
            if kind == "mapping-merge" and is_exact_local_mutation_receiver(
                origin
            ):
                # BUILD_MAP/DICT_MERGE retains the identity of the fresh local
                # destination in its left spine; values from the merged source
                # do not make that receiver external callback state.
                return
            if kind in {"aggregate", "dict-copy"} or (
                kind == "protocol-result"
                and origin[1] in {("bytearray",), ("dict",), ("list",), ("set",)}
            ):
                # A freshly constructed local exact container cannot mutate
                # callback state that existed at projection time.
                return
            raise EvidenceFailed(
                "refusal-state mutation receiver is not an exact local "
                f"aggregate or addressable binding in {code.co_qualname} "
                f"at line {dynamic_use_line!r}; origin_kind={kind!r}"
            )

        for origin in v2_resolve_fast_origin(
            expression,
            fast_origin_definitions,
        ):
            visit(origin)

    for index, instruction in enumerate(instructions):
        if instruction.opname in V2_IMPORT_OPS:
            raise EvidenceFailed(
                "refusal callback contains import bytecode in "
                f"{code.co_qualname}; provide an explicit bounded external-state "
                "projection"
            )
        if (
            instruction.opname in {"LOAD_ATTR", "LOAD_METHOD"}
            and instruction.argval in V2_REFLECTIVE_NAMESPACE_ATTRIBUTES
        ):
            raise EvidenceFailed(
                "refusal callback uses reflective namespace access in "
                f"{code.co_qualname}; provide an explicit bounded "
                "external-state projection"
            )
        if (
            instruction.opname in V2_GLOBAL_ACCESS_OPS
            and isinstance(instruction.argval, str)
        ):
            name = instruction.argval
            accesses[name].add(instruction.opname)
            if instruction.opname not in {"LOAD_GLOBAL", "LOAD_NAME"}:
                continue
            expression = fast_origin_data["load_expressions"].get(index)
            if expression is None:
                raise EvidenceFailed(
                    "refusal-state global access lacks a reaching origin"
                )
            if index in environment_attribute_mutation_source_load_indices:
                # The exact STORE_ATTR operation below retains the module
                # receiver and attribute name.  Do not also misclassify this
                # base-producing load as an ambient bare-module observation.
                continue
            record_fast_expression(expression, call_index=None)
        if (
            instruction.opname in {"LOAD_DEREF", "LOAD_CLASSDEREF"}
            and isinstance(instruction.argval, str)
            and instruction.argval in code.co_freevars
        ):
            expression = fast_origin_data["load_expressions"].get(index)
            if expression is None:
                raise EvidenceFailed(
                    "refusal-state closure access lacks a reaching origin"
                )
            record_fast_expression(expression, call_index=None)
        if (
            instruction.opname in V2_FAST_LOCAL_LOAD_OPS
            and type(instruction.argval) is str
        ):
            expression = fast_origin_data["load_expressions"].get(index)
            if expression is None:
                raise EvidenceFailed(
                    "refusal-state fast-local access lacks an origin"
                )
            record_fast_expression(expression, call_index=None)
    for dynamic_use_index, operation, expression in fast_origin_data[
        "dynamic_uses"
    ]:
        dynamic_use_instruction = instructions[dynamic_use_index]
        dynamic_use_line = (
            dynamic_use_instruction.positions.lineno
            if dynamic_use_instruction.positions is not None
            else None
        )
        if operation == "unproven-call-expansion":
            raise EvidenceFailed(
                "refusal-state *args/**kwargs expansion has unproven "
                f"membership in {code.co_qualname}"
            )
        if operation == "aliased-exact-dict-view-call":
            raise EvidenceFailed(
                "refusal-state exact dict view callable requires a direct "
                f"source-to-call window in {code.co_qualname}"
            )
        if operation == "invalid-exact-dict-view-call-shape":
            raise EvidenceFailed(
                "refusal-state exact dict view call has invalid positional "
                f"or keyword shape in {code.co_qualname}"
            )
        if operation == "invalid-exact-dict-mutation-call-shape":
            raise EvidenceFailed(
                "refusal-state exact dict mutation call has invalid "
                f"positional or keyword shape in {code.co_qualname}"
            )
        if operation == "invalid-exact-list-mutation-call-shape":
            raise EvidenceFailed(
                "refusal-state exact list mutation call has invalid "
                f"positional or keyword shape in {code.co_qualname}"
            )
        if operation == "invalid-exact-dict-get-call-shape":
            raise EvidenceFailed(
                "refusal-state exact dict get call has invalid positional "
                f"or keyword shape in {code.co_qualname}"
            )
        if operation == "aliased-exact-dict-get-call":
            raise EvidenceFailed(
                "refusal-state exact dict get callable requires a direct "
                f"source-to-call window in {code.co_qualname}"
            )
        if operation == "invalid-exact-getitem-call-shape":
            raise EvidenceFailed(
                "refusal-state exact base getitem call has invalid "
                f"positional or keyword shape in {code.co_qualname}"
            )
        if operation == "aliased-exact-getitem-call":
            raise EvidenceFailed(
                "refusal-state exact base getitem callable requires a direct "
                f"source-to-call window in {code.co_qualname}"
            )
        if operation == "invalid-exact-dict-copy-call-shape":
            raise EvidenceFailed(
                "refusal-state exact dict copy call has invalid positional "
                f"or keyword shape in {code.co_qualname}"
            )
        if operation == "aliased-exact-dict-copy-call":
            raise EvidenceFailed(
                "refusal-state exact dict copy callable requires a direct "
                f"source-to-call window in {code.co_qualname}"
            )
        if operation == "non-exact-dict-copy-receiver":
            raise EvidenceFailed(
                "refusal-state dict copy receiver is not a proven exact "
                f"mapping in {code.co_qualname}"
            )
        if operation == "unmodeled-exact-container-mutation":
            if exact_descriptor_slot_base_setitem(expression):
                continue
            raise EvidenceFailed(
                "refusal-state exact container mutation is not modeled in "
                f"{code.co_qualname} at line {dynamic_use_line!r}"
            )
        if operation == "exact-json-argument-escape":
            raise EvidenceFailed(
                "refusal-state detached exact JSON escapes to an unaudited "
                f"callable in {code.co_qualname} at line {dynamic_use_line!r}"
            )
        if operation == "ambiguous-callable-protocol":
            raise EvidenceFailed(
                "refusal-state callable choice mixes protocol-dispatch and "
                f"non-protocol targets in {code.co_qualname}"
            )
        if operation == "call-protocol":
            record_protocol_argument_use(
                expression,
                operation_label=operation,
            )
        if operation == "mapping-key-protocol":
            record_container_protocol_use(expression, contains=False)
        if operation == "contains-protocol":
            record_container_protocol_use(expression, contains=True)
        if operation in {"iterate", "unpack"}:
            record_operation_protocol_operand(
                expression,
                "iterate",
            )
        if operation == "length":
            record_operation_protocol_operand(
                expression,
                "length",
            )
        if operation == "match-keys":
            record_operation_protocol_operand(
                expression,
                "match-keys",
            )
        if operation == "truth" or operation == "UNARY_NOT":
            record_operation_protocol_operand(
                expression,
                "truth",
            )
        if operation == "context-enter":
            record_operation_protocol_operand(
                expression,
                "context",
            )
        if operation == "format-value":
            record_protocol_argument_use(
                expression,
                operation_label=operation,
            )
        if operation == "slice":
            for slice_origin in v2_resolve_fast_origin(
                expression,
                fast_origin_definitions,
            ):
                if not (
                    slice_origin
                    and slice_origin[0] == "aggregate"
                    and slice_origin[1] == "BINARY_SLICE"
                    and len(slice_origin[2]) == 3
                ):
                    record_protocol_argument_use(slice_origin)
                    continue
                receiver, start, stop = slice_origin[2]
                record_operation_protocol_operand(
                    receiver,
                    "slice-receiver",
                )
                record_protocol_argument_use(start)
                record_protocol_argument_use(stop)
        if operation in {"store-subscript", "delete-subscript"}:
            record_external_mutation_receiver(expression, operation)
            continue
        if operation.startswith("store-attribute:"):
            record_external_mutation_receiver(expression, operation)
            continue
        if operation.startswith("delete-attribute:"):
            record_external_mutation_receiver(expression, operation)
            continue
        if (
            operation.startswith("UNARY_")
            and operation != "UNARY_NOT"
        ):
            record_operation_protocol_operand(
                expression,
                f"unary:{operation}",
            )
        if (
            operation.startswith("BINARY_")
            or operation.startswith("COMPARE_OP:")
        ):
            operands = (
                expression[2]
                if expression
                and expression[0] == "aggregate"
                and len(expression) >= 3
                else (expression,)
            )
            comparison = operation.startswith("COMPARE_OP:")
            for operand in operands:
                record_operation_protocol_operand(
                    operand,
                    (
                        f"compare:{operation.split(':', 1)[1]}"
                        if comparison
                        else f"binary:{operation}"
                    ),
                    inspect_local_members=comparison,
                )
        if operation.startswith("mutable-receiver-call:"):
            record_mutable_receiver_call(
                expression,
                operation.split(":", 1)[1],
            )
        record_dynamic_result_use(expression)
    for call_index, expression in fast_origin_data[
        "implicit_call_expressions"
    ]:
        record_fast_expression(expression, call_index=call_index)
    # Nested function invocation dataflow varies across CPython 3.11-3.14
    # (LOAD_FAST_BORROW, CALL_KW, CALL_FUNCTION_EX, closure aliases, and
    # SET_FUNCTION_ATTRIBUTE all change the local pattern). This refusal
    # boundary deliberately scans every nested code constant. Dormant nested
    # imports or reflective namespace access therefore fail closed instead of
    # depending on a version-specific call-window heuristic.
    nested_codes = [
        constant
        for constant in code.co_consts
        if type(constant) is types.CodeType
    ]
    for nested_code in nested_codes:
        merge_current_bindings = (
            merge_nested_bindings
            or nested_code in fast_origin_data["invoked_nested_codes"]
            or nested_code.co_name in {
                "<listcomp>",
                "<setcomp>",
                "<dictcomp>",
            }
        )
        nested_calls = fast_origin_data["invoked_nested_calls"].get(
            nested_code,
            (),
        )
        nested_freevar_origins = (
            v2_nested_function_freevar_origins(
                nested_code,
                tuple(call[0] for call in nested_calls),
            )
            if nested_calls and nested_code.co_freevars
            else None
        )
        entry_origins = None
        exact_initial_binding = bool(nested_calls) and nested_code.co_name in {
            "<dictcomp>",
            "<genexpr>",
            "<listcomp>",
            "<setcomp>",
        }
        if exact_initial_binding:
            entry_origins = v2_nested_invocation_parameter_origins(
                nested_code,
                nested_calls,
            )
        # Invoked comprehensions must be analyzed with their exact call-site
        # binding on the first pass.  A generic pre-pass would treat the
        # synthetic `.0` iterator as unconstrained and could refuse before the
        # proven iterator origin was ever applied.  Ordinary nested functions
        # retain the generic first pass so dormant forbidden operations are
        # diagnosed before an inexact or variadic invocation is bound.
        nested = v2_code_access_analysis(
            nested_code,
            context=context,
            depth=depth + 1,
            merge_nested_bindings=merge_nested_bindings,
            constants_prevalidated=True,
            entry_parameter_origins=entry_origins,
            entry_freevar_origins=nested_freevar_origins,
        )
        if not merge_current_bindings:
            continue
        if nested_calls and not exact_initial_binding:
            entry_origins = v2_nested_invocation_parameter_origins(
                nested_code,
                nested_calls,
            )
            nested = v2_code_access_analysis(
                nested_code,
                context=context,
                depth=depth + 1,
                merge_nested_bindings=merge_nested_bindings,
                constants_prevalidated=True,
                entry_parameter_origins=entry_origins,
                entry_freevar_origins=nested_freevar_origins,
            )
        unresolved_nested_calls = sorted(
            (
                set(nested["called_parameter_names"])
            | {
                name for name, paths in nested[
                    "called_parameter_paths"
                ].items() if paths
            }
            | set(nested["protocol_parameter_names"])
            | set(nested["mapping_key_protocol_parameter_names"])
            | set(nested["contains_protocol_parameter_names"])
            | set(nested["operation_protocol_parameter_paths"])
            ).difference(effective_parameter_names)
        )
        if nested_calls and unresolved_nested_calls:
            raise EvidenceFailed(
                "refusal-state invoked nested callable reaches unresolved "
                "parameters in "
                f"{code.co_qualname}: {', '.join(unresolved_nested_calls)}"
            )
        for name, operations in nested["accesses"].items():
            accesses[name].update(operations)
        for name, paths in nested["module_paths"].items():
            module_paths[name].update(paths)
        bare_global_names.update(nested["bare_global_names"])
        called_global_names.update(nested["called_global_names"])
        protocol_global_names.update(nested["protocol_global_names"])
        mapping_key_protocol_global_names.update(
            nested["mapping_key_protocol_global_names"]
        )
        contains_protocol_global_names.update(
            nested["contains_protocol_global_names"]
        )
        for name, by_path in nested[
            "operation_protocol_global_paths"
        ].items():
            for path, modes in by_path.items():
                operation_protocol_global_paths[name][path].update(modes)
        for name, paths in nested["called_global_paths"].items():
            called_global_paths[name].update(paths)
        for name, paths in nested["call_result_paths"].items():
            call_result_paths[name].update(paths)
        for name, by_path in nested[
            "global_path_call_result_paths"
        ].items():
            for path, result_paths in by_path.items():
                global_path_call_result_paths[name][path].update(
                    result_paths
                )
        for name, paths in nested["parameter_paths"].items():
            if name in effective_parameter_names:
                parameter_paths[name].update(paths)
        bare_parameter_names.update(
            name for name in nested["bare_parameter_names"]
            if name in effective_parameter_names
        )
        called_parameter_names.update(
            name for name in nested["called_parameter_names"]
            if name in effective_parameter_names
        )
        protocol_parameter_names.update(
            name for name in nested["protocol_parameter_names"]
            if name in effective_parameter_names
        )
        mapping_key_protocol_parameter_names.update(
            name
            for name in nested["mapping_key_protocol_parameter_names"]
            if name in effective_parameter_names
        )
        contains_protocol_parameter_names.update(
            name
            for name in nested["contains_protocol_parameter_names"]
            if name in effective_parameter_names
        )
        for name, by_path in nested[
            "operation_protocol_parameter_paths"
        ].items():
            if name not in effective_parameter_names:
                continue
            for path, modes in by_path.items():
                operation_protocol_parameter_paths[name][path].update(modes)
        for name, paths in nested["called_parameter_paths"].items():
            if name in effective_parameter_names:
                called_parameter_paths[name].update(paths)
        for name, paths in nested[
            "parameter_call_result_paths"
        ].items():
            if name in effective_parameter_names:
                parameter_call_result_paths[name].update(paths)
        for name, by_path in nested[
            "parameter_path_call_result_paths"
        ].items():
            if name not in effective_parameter_names:
                continue
            for path, result_paths in by_path.items():
                parameter_path_call_result_paths[name][path].update(
                    result_paths
                )
        for row in nested["static_subscript_calls"]:
            if (
                row["source_kind"] == "parameter"
                and row["source_name"] not in effective_parameter_names
            ):
                raise EvidenceFailed(
                    "refusal-state invoked nested callable reaches an "
                    "unresolved parameter subscript in "
                    f"{code.co_qualname}: {row['source_name']}"
                )
            static_subscript_calls.append(dict(row))
        for name, paths in nested["freevar_paths"].items():
            if name in code.co_freevars:
                freevar_paths[name].update(paths)
            elif name in effective_parameter_names:
                parameter_paths[name].update(paths)
        for name in nested["bare_freevar_names"]:
            if name in code.co_freevars:
                bare_freevar_names.add(name)
            elif name in effective_parameter_names:
                bare_parameter_names.add(name)
        for name in nested["called_freevar_names"]:
            if name in code.co_freevars:
                called_freevar_names.add(name)
            elif name in effective_parameter_names:
                called_parameter_names.add(name)
            else:
                raise EvidenceFailed(
                    "refusal-state nested callable reaches an unresolved "
                    f"closure binding {name} in {code.co_qualname}"
                )
        for name in nested["protocol_freevar_names"]:
            if name in code.co_freevars:
                protocol_freevar_names.add(name)
            elif name in effective_parameter_names:
                protocol_parameter_names.add(name)
            else:
                raise EvidenceFailed(
                    "refusal-state nested protocol call reaches an "
                    f"unresolved closure binding {name} in {code.co_qualname}"
                )
        for nested_names, freevar_target, parameter_target in (
            (
                nested["mapping_key_protocol_freevar_names"],
                mapping_key_protocol_freevar_names,
                mapping_key_protocol_parameter_names,
            ),
            (
                nested["contains_protocol_freevar_names"],
                contains_protocol_freevar_names,
                contains_protocol_parameter_names,
            ),
        ):
            for name in nested_names:
                if name in code.co_freevars:
                    freevar_target.add(name)
                elif name in effective_parameter_names:
                    parameter_target.add(name)
                else:
                    raise EvidenceFailed(
                        "refusal-state nested container protocol reaches an "
                        f"unresolved closure binding {name} in "
                        f"{code.co_qualname}"
                    )
        for name, by_path in nested[
            "operation_protocol_freevar_paths"
        ].items():
            destination = (
                operation_protocol_freevar_paths[name]
                if name in code.co_freevars
                else operation_protocol_parameter_paths[name]
                if name in effective_parameter_names
                else None
            )
            if destination is None:
                raise EvidenceFailed(
                    "refusal-state nested operation protocol reaches an "
                    f"unresolved closure binding {name} in "
                    f"{code.co_qualname}"
                )
            for path, modes in by_path.items():
                destination[path].update(modes)
        for name, paths in nested["called_freevar_paths"].items():
            if name in code.co_freevars:
                called_freevar_paths[name].update(paths)
            elif name in effective_parameter_names:
                called_parameter_paths[name].update(paths)
            elif paths:
                raise EvidenceFailed(
                    "refusal-state nested callable reaches an unresolved "
                    f"closure path {name} in {code.co_qualname}"
                )
        for name, paths in nested[
            "freevar_call_result_paths"
        ].items():
            if name in code.co_freevars:
                freevar_call_result_paths[name].update(paths)
            elif name in effective_parameter_names:
                parameter_call_result_paths[name].update(paths)
        for name, by_path in nested[
            "freevar_path_call_result_paths"
        ].items():
            destination = (
                freevar_path_call_result_paths[name]
                if name in code.co_freevars
                else parameter_path_call_result_paths[name]
                if name in effective_parameter_names
                else None
            )
            if destination is None:
                continue
            for path, result_paths in by_path.items():
                destination[path].update(result_paths)
    context["global_accesses"] += len(accesses)
    if context["global_accesses"] > V2_REFUSAL_GLOBAL_ACCESS_CAP:
        raise EvidenceFailed(
            "refusal-state transitive global access set exceeds its cap"
        )
    return {
        "accesses": {
            name: tuple(sorted(operations))
            for name, operations in sorted(
                accesses.items(),
                key=lambda row: row[0].encode("utf-8"),
            )
        },
        "module_paths": {
            name: tuple(sorted(paths))
            for name, paths in sorted(
                module_paths.items(),
                key=lambda row: row[0].encode("utf-8"),
            )
        },
        "bare_global_names": frozenset(bare_global_names),
        "called_global_names": frozenset(called_global_names),
        "protocol_global_names": frozenset(protocol_global_names),
        "mapping_key_protocol_global_names": frozenset(
            mapping_key_protocol_global_names
        ),
        "contains_protocol_global_names": frozenset(
            contains_protocol_global_names
        ),
        "operation_protocol_global_paths": {
            name: {
                path: tuple(sorted(modes))
                for path, modes in sorted(by_path.items())
            }
            for name, by_path in sorted(
                operation_protocol_global_paths.items(),
                key=lambda row: row[0].encode("utf-8"),
            )
        },
        "called_global_paths": {
            name: tuple(sorted(paths))
            for name, paths in sorted(
                called_global_paths.items(),
                key=lambda row: row[0].encode("utf-8"),
            )
        },
        "call_result_paths": {
            name: tuple(sorted(paths))
            for name, paths in sorted(
                call_result_paths.items(),
                key=lambda row: row[0].encode("utf-8"),
            )
        },
        "global_path_call_result_paths": {
            name: {
                path: tuple(sorted(result_paths))
                for path, result_paths in sorted(by_path.items())
            }
            for name, by_path in sorted(
                global_path_call_result_paths.items(),
                key=lambda row: row[0].encode("utf-8"),
            )
        },
        "freevar_paths": {
            name: tuple(sorted(paths))
            for name, paths in sorted(
                freevar_paths.items(),
                key=lambda row: row[0].encode("utf-8"),
            )
        },
        "bare_freevar_names": frozenset(bare_freevar_names),
        "called_freevar_names": frozenset(called_freevar_names),
        "protocol_freevar_names": frozenset(protocol_freevar_names),
        "mapping_key_protocol_freevar_names": frozenset(
            mapping_key_protocol_freevar_names
        ),
        "contains_protocol_freevar_names": frozenset(
            contains_protocol_freevar_names
        ),
        "operation_protocol_freevar_paths": {
            name: {
                path: tuple(sorted(modes))
                for path, modes in sorted(by_path.items())
            }
            for name, by_path in sorted(
                operation_protocol_freevar_paths.items(),
                key=lambda row: row[0].encode("utf-8"),
            )
        },
        "called_freevar_paths": {
            name: tuple(sorted(paths))
            for name, paths in sorted(
                called_freevar_paths.items(),
                key=lambda row: row[0].encode("utf-8"),
            )
        },
        "freevar_call_result_paths": {
            name: tuple(sorted(paths))
            for name, paths in sorted(
                freevar_call_result_paths.items(),
                key=lambda row: row[0].encode("utf-8"),
            )
        },
        "freevar_path_call_result_paths": {
            name: {
                path: tuple(sorted(result_paths))
                for path, result_paths in sorted(by_path.items())
            }
            for name, by_path in sorted(
                freevar_path_call_result_paths.items(),
                key=lambda row: row[0].encode("utf-8"),
            )
        },
        "parameter_paths": {
            name: tuple(sorted(paths))
            for name, paths in sorted(
                parameter_paths.items(),
                key=lambda row: row[0].encode("utf-8"),
            )
        },
        "bare_parameter_names": frozenset(bare_parameter_names),
        "called_parameter_names": frozenset(called_parameter_names),
        "protocol_parameter_names": frozenset(protocol_parameter_names),
        "mapping_key_protocol_parameter_names": frozenset(
            mapping_key_protocol_parameter_names
        ),
        "contains_protocol_parameter_names": frozenset(
            contains_protocol_parameter_names
        ),
        "operation_protocol_parameter_paths": {
            name: {
                path: tuple(sorted(modes))
                for path, modes in sorted(by_path.items())
            }
            for name, by_path in sorted(
                operation_protocol_parameter_paths.items(),
                key=lambda row: row[0].encode("utf-8"),
            )
        },
        "called_parameter_paths": {
            name: tuple(sorted(paths))
            for name, paths in sorted(
                called_parameter_paths.items(),
                key=lambda row: row[0].encode("utf-8"),
            )
        },
        "parameter_call_result_paths": {
            name: tuple(sorted(paths))
            for name, paths in sorted(
                parameter_call_result_paths.items(),
                key=lambda row: row[0].encode("utf-8"),
            )
        },
        "parameter_path_call_result_paths": {
            name: {
                path: tuple(sorted(result_paths))
                for path, result_paths in sorted(by_path.items())
            }
            for name, by_path in sorted(
                parameter_path_call_result_paths.items(),
                key=lambda row: row[0].encode("utf-8"),
            )
        },
        "static_subscript_calls": tuple(
            sorted(
                {
                    canonical_bytes(row): row
                    for row in static_subscript_calls
                }.values(),
                key=canonical_bytes,
            )
        ),
    }


def v2_code_global_accesses(
    code: types.CodeType,
    *,
    context: dict[str, Any] | None = None,
    depth: int = 0,
) -> dict[str, tuple[str, ...]]:
    if context is None:
        context = v2_new_refusal_projection_context()
    return v2_code_access_analysis(
        code,
        context=context,
        depth=depth,
    )["accesses"]


def v2_code_constant_projection(
    value: Any,
    *,
    context: dict[str, Any] | None = None,
    depth: int = 0,
) -> Any:
    if depth > V2_REFUSAL_STATE_DEPTH_CAP:
        raise EvidenceFailed("refusal-state code constant exceeds its depth cap")
    if context is None:
        context = v2_new_refusal_projection_context()
    if value is None or value is Ellipsis:
        return {"kind": "singleton", "value": repr(value)}
    if type(value) is bool:
        return value
    if type(value) is int:
        integer_text = v2_bounded_exact_integer_text(
            value,
            label="refusal-state code constant",
            error_type=EvidenceFailed,
        )
        v2_refusal_charge(
            context,
            "scalar_bytes",
            len(integer_text.encode("ascii")),
        )
        return value
    if type(value) is str:
        v2_refusal_charge(
            context,
            "scalar_bytes",
            len(value.encode("utf-8")),
        )
        return value
    if type(value) is float:
        return {
            "kind": "float",
            "ieee754_binary64": struct.pack(">d", value).hex(),
        }
    if type(value) is complex:
        return {
            "kind": "complex",
            "real_ieee754_binary64": struct.pack(">d", value.real).hex(),
            "imag_ieee754_binary64": struct.pack(">d", value.imag).hex(),
        }
    if type(value) is bytes:
        v2_refusal_charge(context, "scalar_bytes", len(value))
        return {
            "kind": "bytes",
            "byte_length": len(value),
            "content_root": "sha256-v1:" + hashlib.sha256(value).hexdigest(),
        }
    if type(value) is tuple:
        v2_refusal_charge(context, "items", len(value))
        return {
            "kind": "tuple",
            "items": [
                v2_code_constant_projection(
                    item,
                    context=context,
                    depth=depth + 1,
                )
                for item in value
            ],
        }
    if type(value) is slice:
        return {
            "kind": "slice",
            "start": v2_code_constant_projection(
                value.start,
                context=context,
                depth=depth + 1,
            ),
            "stop": v2_code_constant_projection(
                value.stop,
                context=context,
                depth=depth + 1,
            ),
            "step": v2_code_constant_projection(
                value.step,
                context=context,
                depth=depth + 1,
            ),
        }
    if type(value) is frozenset:
        v2_refusal_charge(context, "items", len(value))
        items = [
            v2_code_constant_projection(
                item,
                context=context,
                depth=depth + 1,
            )
            for item in value
        ]
        items = sorted(items, key=canonical_bytes)
        return {"kind": "frozenset", "items": items}
    if type(value) is types.CodeType:
        return v2_code_semantic_projection(
            value,
            context=context,
            depth=depth + 1,
        )
    raise EvidenceFailed(
        "refusal-state code contains an unsupported constant type: "
        f"{v2_type_identity(type(value))}"
    )


def v2_code_semantic_projection(
    code: types.CodeType,
    *,
    context: dict[str, Any] | None = None,
    depth: int = 0,
) -> dict[str, Any]:
    if depth > V2_REFUSAL_STATE_DEPTH_CAP:
        raise EvidenceFailed("refusal-state code projection exceeds its depth cap")
    if context is None:
        context = v2_new_refusal_projection_context()
    v2_refusal_charge(context, "items", len(code.co_consts))
    v2_refusal_charge(context, "scalar_bytes", len(code.co_code))
    return {
        "argcount": code.co_argcount,
        "posonlyargcount": code.co_posonlyargcount,
        "kwonlyargcount": code.co_kwonlyargcount,
        "nlocals": code.co_nlocals,
        "stacksize": code.co_stacksize,
        "flags": code.co_flags,
        "bytecode_root": (
            "sha256-v1:" + hashlib.sha256(code.co_code).hexdigest()
        ),
        "constants": [
            v2_code_constant_projection(
                value,
                context=context,
                depth=depth + 1,
            )
            for value in code.co_consts
        ],
        "names": list(code.co_names),
        "varnames": list(code.co_varnames),
        "freevars": list(code.co_freevars),
        "cellvars": list(code.co_cellvars),
        "filename_root": text_root(code.co_filename),
        "name": code.co_name,
        "qualname": code.co_qualname,
        "firstlineno": code.co_firstlineno,
        "linetable_root": (
            "sha256-v1:" + hashlib.sha256(code.co_linetable).hexdigest()
        ),
        "exceptiontable_root": (
            "sha256-v1:"
            + hashlib.sha256(code.co_exceptiontable).hexdigest()
        ),
    }


def v2_type_identity(value: type[Any]) -> str:
    module = v2_raw_type_attribute(value, "__module__")
    qualname = v2_raw_type_attribute(value, "__qualname__")
    if type(module) is not str or type(qualname) is not str:
        raise EvidenceFailed("refusal-state type identity fields are not exact")
    return f"{module}.{qualname}"


def v2_raw_function_attribute(value: types.FunctionType, name: str) -> Any:
    if type(value) is not types.FunctionType:
        raise EvidenceFailed("refusal-state callable is not an exact function")
    descriptor = V2_FUNCTION_ATTRIBUTE_DESCRIPTORS.get(name)
    if name == "__annotate__":
        descriptor = V2_FUNCTION_ANNOTATE_DESCRIPTOR
    elif name == "__type_params__":
        descriptor = V2_FUNCTION_TYPE_PARAMS_DESCRIPTOR
    if descriptor is None:
        raise EvidenceFailed(
            "refusal-state requested an unsupported raw function attribute"
        )
    return v2_exact_descriptor_read(
        descriptor,
        value,
        types.FunctionType,
        label=f"function {name}",
    )


def v2_function_default_bindings(
    value: types.FunctionType,
    code: types.CodeType,
) -> dict[str, Any]:
    defaults = v2_raw_function_attribute(value, "__defaults__") or ()
    keyword_defaults = (
        v2_raw_function_attribute(value, "__kwdefaults__") or {}
    )
    if type(defaults) is not tuple or type(keyword_defaults) is not dict:
        raise EvidenceFailed(
            "refusal-state function default metadata is not exact"
        )
    positional_names = tuple(code.co_varnames[: code.co_argcount])
    if len(defaults) > len(positional_names):
        raise EvidenceFailed(
            "refusal-state function has more defaults than parameters"
        )
    bindings = dict(
        zip(positional_names[len(positional_names) - len(defaults) :], defaults)
    )
    keyword_names = tuple(
        code.co_varnames[
            code.co_argcount : code.co_argcount + code.co_kwonlyargcount
        ]
    )
    if any(
        type(name) is not str or name not in keyword_names
        for name in keyword_defaults
    ):
        raise EvidenceFailed(
            "refusal-state function keyword defaults differ from parameters"
        )
    bindings.update(keyword_defaults)
    return bindings


def v2_function_annotation_projection(
    value: types.FunctionType,
    *,
    seen: dict[int, int],
    context: dict[str, Any],
    depth: int,
) -> dict[str, Any]:
    annotator: Any = None
    if V2_FUNCTION_ANNOTATE_DESCRIPTOR is not None:
        annotator = v2_exact_descriptor_read(
            V2_FUNCTION_ANNOTATE_DESCRIPTOR,
            value,
            types.FunctionType,
            label="function lazy annotator",
        )
    if annotator is not None:
        # Reading __annotations__ on CPython 3.14 can execute __annotate__.
        # Bind the annotator graph itself and forbid callback bytecode from
        # touching either reflective attribute; never evaluate it here.
        return {
            "kind": "lazy-annotator",
            "annotator": (
                v2_trusted_callable_projection(
                    annotator,
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                )
                if type(annotator) is types.FunctionType
                else v2_state_projection_value(
                    annotator,
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                )
            ),
        }
    annotations = v2_raw_function_attribute(value, "__annotations__")
    if type(annotations) is not dict:
        raise EvidenceFailed(
            "refusal-state function annotations dictionary is not exact"
        )
    return {
        "kind": "materialized-annotations",
        "state": v2_state_projection_value(
            annotations,
            seen=seen,
            context=context,
            depth=depth + 1,
        ),
    }


def v2_function_type_params_projection(
    value: types.FunctionType,
    *,
    seen: dict[int, int],
    context: dict[str, Any],
    depth: int,
) -> dict[str, Any]:
    if V2_FUNCTION_TYPE_PARAMS_DESCRIPTOR is None:
        return {"kind": "runtime-unsupported"}
    type_params = v2_exact_descriptor_read(
        V2_FUNCTION_TYPE_PARAMS_DESCRIPTOR,
        value,
        types.FunctionType,
        label="function type parameters",
    )
    if type(type_params) is not tuple:
        raise EvidenceFailed(
            "refusal-state function type parameters are not an exact tuple"
        )
    return {
        "kind": "type-parameters",
        "state": v2_state_projection_value(
            type_params,
            seen=seen,
            context=context,
            depth=depth + 1,
        ),
    }


def v2_trusted_callable_projection_body(
    value: Any,
    *,
    seen: dict[int, int],
    context: dict[str, Any],
    depth: int,
) -> dict[str, Any]:
    if v2_is_dangerous_builtin(value):
        raise EvidenceFailed(
            "refusal callback reaches a dynamic namespace builtin; provide "
            "an explicit bounded external-state projection"
        )
    v2_require_external_callable_authorized(
        value,
        context=context,
        label="an aliased external callable",
    )
    selected_scope_role = (
        v2_fixture_selected_resource_scope_boundary_role(value)
    )
    if selected_scope_role is not None:
        code = v2_raw_function_attribute(value, "__code__")
        if type(code) is not types.CodeType:
            raise EvidenceFailed(
                "selected-resource scope boundary lost its exact code"
            )
        return {
            "kind": "audited-selected-resource-scope-boundary",
            "role": selected_scope_role,
            "code": v2_code_semantic_projection(code, context=context),
            "closure_state": "INTENTIONALLY_NOT_AUTHORITY_EVIDENCE",
            "no_claim": (
                "the exact scope boundary is code-identity-bound and tested "
                "separately; live thread and token state is not portable "
                "refusal evidence"
            ),
        }
    if type(value) is types.FunctionType:
        code = v2_raw_function_attribute(value, "__code__")
        closure = v2_raw_function_attribute(value, "__closure__") or ()
        if type(code) is not types.CodeType or type(closure) is not tuple:
            raise EvidenceFailed(
                "refusal-state trusted function metadata is not exact"
            )
        if len(closure) != len(code.co_freevars):
            raise EvidenceFailed(
                "refusal-state trusted function closure metadata differs"
            )
        closure_rows: list[dict[str, Any]] = []
        for name, cell in zip(code.co_freevars, closure, strict=True):
            try:
                cell_value = cell.cell_contents
            except ValueError:
                cell_state: Any = {"kind": "empty-cell"}
            else:
                if v2_raw_instance_of(cell_value, types.ModuleType):
                    cell_state = {
                        "kind": "structural-module-binding",
                        "module": v2_raw_module_name(cell_value),
                        "trusted_runtime_module": v2_is_trusted_module(
                            cell_value
                        ),
                    }
                else:
                    cell_state = v2_state_projection_value(
                        cell_value,
                        seen=seen,
                        context=context,
                        depth=depth + 1,
                    )
            closure_rows.append({"name": name, "state": cell_state})
        function_attributes = v2_raw_function_attribute(value, "__dict__")
        if type(function_attributes) is not dict:
            raise EvidenceFailed(
                "refusal-state function attribute dictionary is not exact"
            )
        name = v2_raw_function_attribute(value, "__name__")
        qualname = v2_raw_function_attribute(value, "__qualname__")
        if type(name) is not str or type(qualname) is not str:
            raise EvidenceFailed("refusal-state function names are not exact")
        return {
            "kind": "trusted-module-python-callable",
            "module": v2_state_projection_value(
                v2_raw_function_attribute(value, "__module__"),
                seen=seen,
                context=context,
                depth=depth + 1,
            ),
            "name": name,
            "qualname": qualname,
            "doc": v2_state_projection_value(
                v2_raw_function_attribute(value, "__doc__"),
                seen=seen,
                context=context,
                depth=depth + 1,
            ),
            "code": v2_code_semantic_projection(code, context=context),
            "defaults": v2_state_projection_value(
                v2_raw_function_attribute(value, "__defaults__"),
                seen=seen,
                context=context,
                depth=depth + 1,
            ),
            "keyword_defaults": v2_state_projection_value(
                v2_raw_function_attribute(value, "__kwdefaults__"),
                seen=seen,
                context=context,
                depth=depth + 1,
            ),
            "annotations": v2_function_annotation_projection(
                value,
                seen=seen,
                context=context,
                depth=depth + 1,
            ),
            "type_params": v2_function_type_params_projection(
                value,
                seen=seen,
                context=context,
                depth=depth + 1,
            ),
            "closure": closure_rows,
            "attributes": v2_state_projection_value(
                function_attributes,
                seen=seen,
                context=context,
                depth=depth + 1,
            ),
        }
    if type(value) is V2_OPERATOR_ATTRGETTER_TYPE:
        reduce_descriptor = v2_raw_type_dictionary(
            V2_OPERATOR_ATTRGETTER_TYPE
        ).get("__reduce__")
        if type(reduce_descriptor) is not types.MethodDescriptorType:
            raise EvidenceFailed(
                "refusal-state operator.attrgetter reduce contract differs"
            )
        reduced = reduce_descriptor(value)
        if (
            type(reduced) is not tuple
            or len(reduced) != 2
            or reduced[0] is not V2_OPERATOR_ATTRGETTER_TYPE
            or type(reduced[1]) is not tuple
            or any(type(name) is not str for name in reduced[1])
        ):
            raise EvidenceFailed(
                "refusal-state operator.attrgetter payload is not exact"
            )
        return {
            "kind": "operator.attrgetter",
            "attributes": list(reduced[1]),
        }
    if type(value) is V2_OPERATOR_ITEMGETTER_TYPE:
        reduced = V2_OPERATOR_ITEMGETTER_REDUCE_DESCRIPTOR(value)
        if (
            type(reduced) is not tuple
            or len(reduced) != 2
            or reduced[0] is not V2_OPERATOR_ITEMGETTER_TYPE
            or type(reduced[1]) is not tuple
        ):
            raise EvidenceFailed(
                "refusal-state operator.itemgetter payload is not exact"
            )
        return {
            "kind": "operator.itemgetter",
            "items": [
                v2_state_projection_value(
                    item,
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                )
                for item in tuple.__iter__(reduced[1])
            ],
        }
    if not v2_exact_type_is_one_of(value, (
        types.BuiltinFunctionType,
        types.BuiltinMethodType,
        V2_REGEX_BOUND_METHOD_TYPE,
        types.ClassMethodDescriptorType,
        types.MethodDescriptorType,
        types.MethodWrapperType,
        types.WrapperDescriptorType,
    )):
        raise EvidenceFailed(
            "refusal-state trusted callable has an unsupported exact type: "
            f"{v2_type_identity(type(value))}"
        )

    module = v2_optional_raw_builtin_descriptor_attribute(
        value,
        "__module__",
    )
    qualname = v2_optional_raw_builtin_descriptor_attribute(
        value,
        "__qualname__",
    )
    name = v2_optional_raw_builtin_descriptor_attribute(value, "__name__")
    if module is not None and type(module) is not str:
        raise EvidenceFailed(
            "refusal-state built-in callable module is not exact"
        )
    if qualname is not None and type(qualname) is not str:
        raise EvidenceFailed(
            "refusal-state built-in callable qualname is not exact"
        )
    if name is not None and type(name) is not str:
        raise EvidenceFailed(
            "refusal-state built-in callable name is not exact"
        )
    if not qualname and not name:
        raise EvidenceFailed(
            "refusal-state built-in callable lacks an exact name"
        )
    return {
        "kind": "trusted-module-builtin-callable",
        "type": v2_type_identity(type(value)),
        "module": module or "",
        "qualname": qualname or name,
    }


def v2_trusted_callable_projection(
    value: Any,
    *,
    seen: dict[int, int],
    context: dict[str, Any],
    depth: int,
) -> dict[str, Any]:
    identity = id(value)
    object_ids: dict[int, int] = context["object_ids"]
    active_ids: set[int] = context["active_ids"]
    if identity in object_ids:
        return {
            "kind": "reference",
            "node_id": object_ids[identity],
            "cycle": identity in active_ids,
        }
    v2_refusal_charge(context, "nodes")
    node_id = context["next_node_id"]
    context["next_node_id"] += 1
    object_ids[identity] = node_id
    context["object_references"][identity] = value
    active_ids.add(identity)
    seen[identity] = depth
    try:
        return {
            "node_id": node_id,
            **v2_trusted_callable_projection_body(
                value,
                seen=seen,
                context=context,
                depth=depth,
            ),
        }
    finally:
        active_ids.discard(identity)
        seen.pop(identity, None)


def v2_structural_external_callable_projection(
    value: Any,
    *,
    seen: dict[int, int],
    context: dict[str, Any],
    depth: int,
) -> dict[str, Any]:
    capabilities = v2_external_callable_capabilities(value)
    if not capabilities:
        raise EvidenceFailed(
            "refusal-state structural external callable lacks an exact "
            "capability identity"
        )
    prior_authorized_capabilities = context[
        "authorized_external_capabilities"
    ]
    try:
        # A dormant class attribute must retain the exact callable binding,
        # but merely being present on a reachable type cannot authorize the
        # callback to observe or mutate that external state.
        context["authorized_external_capabilities"] = frozenset(
            set(prior_authorized_capabilities).union(capabilities)
        )
        callable_state = v2_trusted_callable_projection(
            value,
            seen=seen,
            context=context,
            depth=depth + 1,
        )
    finally:
        context[
            "authorized_external_capabilities"
        ] = prior_authorized_capabilities
    return {
        "kind": "structural-external-callable-binding",
        "capabilities": sorted(capabilities),
        "callable": callable_state,
    }


def v2_structural_external_wrapper_projection(
    value: Any,
    *,
    seen: dict[int, int],
    context: dict[str, Any],
    depth: int,
) -> dict[str, Any]:
    wrapped = v2_unwrap_function_wrapper(value)
    capabilities = v2_external_callable_capabilities(wrapped)
    if not capabilities:
        raise EvidenceFailed(
            "refusal-state structural external wrapper lacks an exact "
            "capability identity"
        )
    prior_authorized_capabilities = context[
        "authorized_external_capabilities"
    ]
    try:
        context["authorized_external_capabilities"] = frozenset(
            set(prior_authorized_capabilities).union(capabilities)
        )
        descriptor_state = v2_state_projection_value(
            value,
            seen=seen,
            context=context,
            depth=depth + 1,
        )
    finally:
        context[
            "authorized_external_capabilities"
        ] = prior_authorized_capabilities
    return {
        "kind": "structural-external-callable-wrapper-binding",
        "capabilities": sorted(capabilities),
        "descriptor": descriptor_state,
    }


def v2_raw_instance_dictionary(value: Any) -> dict[str, Any] | None:
    owners = v2_raw_type_mro(type(value))
    for owner in owners:
        owner_attributes = v2_raw_type_dictionary(owner)
        if "__dict__" not in owner_attributes:
            continue
        descriptor = owner_attributes["__dict__"]
        if type(descriptor) is not types.GetSetDescriptorType:
            raise EvidenceFailed(
                "refusal-state object dictionary descriptor is shadowed"
            )
        try:
            raw = types.GetSetDescriptorType.__get__(
                descriptor,
                value,
                type(value),
            )
        except AttributeError:
            return None
        except Exception as error:
            raise EvidenceFailed(
                "refusal-state object dictionary inspection failed"
            ) from error
        if type(raw) is not dict:
            raise EvidenceFailed(
                "refusal-state object dictionary is not exact"
            )
        return raw
    return None


def v2_raw_attribute_without_user_code(
    value: Any,
    name: str,
    *,
    allow_absent_slot: bool = False,
) -> Any:
    if v2_raw_instance_of(value, types.ModuleType):
        if type(value) is not types.ModuleType:
            raise EvidenceFailed(
                "refusal-state trusted module path reaches a module subclass"
            )
        attributes = v2_raw_module_dict(value)
        if name in attributes:
            return attributes[name]
        raise EvidenceFailed(
            "refusal-state trusted module attribute path is absent"
        )
    if v2_raw_is_type_object(value):
        if type(value) is not type:
            raise EvidenceFailed(
                "refusal-state class attribute path has a custom metaclass"
            )
        for owner in v2_raw_type_mro(value):
            owner_attributes = v2_raw_type_dictionary(owner)
            if name not in owner_attributes:
                continue
            attribute = owner_attributes[name]
            if type(attribute) is types.FunctionType:
                return attribute
            if type(attribute) is staticmethod:
                return v2_unwrap_function_wrapper(attribute)
            if type(attribute) is classmethod:
                return types.MethodType(
                    v2_unwrap_function_wrapper(attribute),
                    value,
                )
            if type(attribute) is types.ClassMethodDescriptorType:
                return types.ClassMethodDescriptorType.__get__(
                    attribute,
                    None,
                    value,
                )
            descriptor_type_attributes = {
                descriptor_name
                for descriptor_owner in v2_raw_type_mro(type(attribute))
                for descriptor_name in v2_raw_type_dictionary(descriptor_owner)
            }
            if (
                "__get__" in descriptor_type_attributes
                and type(attribute)
                not in {
                    property,
                    types.ClassMethodDescriptorType,
                    types.GetSetDescriptorType,
                    types.MemberDescriptorType,
                    types.MethodDescriptorType,
                    types.WrapperDescriptorType,
                }
            ):
                raise EvidenceFailed(
                    "refusal-state class attribute path reaches a custom "
                    "descriptor"
                )
            return attribute
        raise EvidenceFailed(
            "refusal-state trusted module class attribute path is absent"
        )

    if type(value) is types.FunctionType and (
        name in V2_FUNCTION_ATTRIBUTE_DESCRIPTORS
        or name == "__annotate__"
        and V2_FUNCTION_ANNOTATE_DESCRIPTOR is not None
        or name == "__type_params__"
        and V2_FUNCTION_TYPE_PARAMS_DESCRIPTOR is not None
    ):
        return v2_raw_function_attribute(value, name)

    if type(value) is property:
        property_descriptor = V2_PROPERTY_ACCESSOR_DESCRIPTORS.get(name)
        if name == "__doc__":
            property_descriptor = V2_PROPERTY_DOC_DESCRIPTOR
        elif name == "__name__":
            property_descriptor = V2_PROPERTY_NAME_DESCRIPTOR
        if property_descriptor is not None:
            return v2_exact_descriptor_read(
                property_descriptor,
                value,
                property,
                label=f"property {name}",
            )

    if type(value) is defaultdict and name == "default_factory":
        return v2_exact_descriptor_read(
            V2_DEFAULTDICT_FACTORY_DESCRIPTOR,
            value,
            defaultdict,
            label="defaultdict default_factory",
        )

    if type(value) is deque and name == "maxlen":
        return v2_exact_descriptor_read(
            V2_DEQUE_MAXLEN_DESCRIPTOR,
            value,
            deque,
            label="deque maxlen",
        )

    if type(value) is types.MethodType and name in V2_METHOD_ATTRIBUTE_DESCRIPTORS:
        return v2_exact_descriptor_read(
            V2_METHOD_ATTRIBUTE_DESCRIPTORS[name],
            value,
            types.MethodType,
            label=f"bound method {name}",
        )

    value_type = type(value)
    inherited_attribute: Any = None
    inherited_present = False
    inherited_has_get = False
    inherited_is_data_descriptor = False
    for owner in v2_raw_type_mro(value_type):
        owner_attributes = v2_raw_type_dictionary(owner)
        if name not in owner_attributes:
            continue
        inherited_attribute = owner_attributes[name]
        inherited_present = True
        descriptor_type_attributes = {
            descriptor_name
            for descriptor_owner in v2_raw_type_mro(type(inherited_attribute))
            for descriptor_name in v2_raw_type_dictionary(descriptor_owner)
        }
        inherited_has_get = "__get__" in descriptor_type_attributes
        inherited_is_data_descriptor = bool(
            descriptor_type_attributes.intersection({"__set__", "__delete__"})
        )
        break
    if inherited_present and type(inherited_attribute) is types.MemberDescriptorType:
        return v2_exact_descriptor_read(
            inherited_attribute,
            value,
            value_type,
            label=f"slot {name}",
            allow_absent=allow_absent_slot,
        )
    if inherited_present and inherited_is_data_descriptor:
        raise EvidenceFailed(
            "refusal-state trusted module attribute path reaches a data "
            "descriptor without an audited pure getter"
        )
    attributes = v2_raw_instance_dictionary(value)
    if attributes is not None and name in attributes:
        return attributes[name]
    if inherited_present:
        if type(inherited_attribute) is types.FunctionType:
            return types.MethodType(inherited_attribute, value)
        if type(inherited_attribute) is staticmethod:
            return v2_unwrap_function_wrapper(inherited_attribute)
        if type(inherited_attribute) is classmethod:
            return types.MethodType(
                v2_unwrap_function_wrapper(inherited_attribute),
                value_type,
            )
        if v2_exact_type_is_one_of(inherited_attribute, (
            types.ClassMethodDescriptorType,
            types.MethodDescriptorType,
            types.WrapperDescriptorType,
        )):
            try:
                return type(inherited_attribute).__get__(
                    inherited_attribute,
                    value,
                    value_type,
                )
            except Exception as error:
                raise EvidenceFailed(
                    "refusal-state built-in method descriptor binding failed"
                ) from error
        if inherited_has_get:
            raise EvidenceFailed(
                "refusal-state trusted module inherited attribute requires "
                "descriptor execution"
            )
        return inherited_attribute
    raise EvidenceFailed(
        "refusal-state trusted module attribute path is absent"
    )


def v2_executable_function_overlay(
    value: types.FunctionType,
    *,
    seen: dict[int, int],
    context: dict[str, Any],
    depth: int,
) -> dict[str, Any]:
    if depth > V2_REFUSAL_STATE_DEPTH_CAP:
        raise EvidenceFailed(
            "refusal-state executable-call traversal exceeds its depth cap"
        )
    pinned_local_code = next(
        (
            code
            for candidate, code
            in (
                *V2_AUDITED_LOCAL_PURE_CALL_CODE_CONTRACTS,
                V2_ASSERTION_EVIDENCE_PROJECTOR_CONTRACT,
                V2_CHILD_PAYLOAD_VALIDATOR_CONTRACT,
                *V2_CHECK_OBLIGATION_CODE_CONTRACTS,
                *V2_HISTORY_JSON_HELPER_CODE_CONTRACTS,
            )
            if value is candidate
        ),
        None,
    )
    if (
        pinned_local_code is not None
        and v2_raw_function_attribute(value, "__code__")
        is not pinned_local_code
    ):
        raise EvidenceFailed(
            "refusal-state audited local callable code identity drifted"
        )
    identity = id(value)
    active: set[int] = context["executable_overlay_active_ids"]
    completed: set[int] = context["executable_overlay_completed_ids"]
    references: dict[int, types.FunctionType] = context[
        "executable_overlay_references"
    ]
    prior_reference = references.get(identity)
    if prior_reference is not None and prior_reference is not value:
        raise EvidenceFailed(
            "refusal-state executable overlay observed recycled identity"
        )
    references[identity] = value
    prior_authorized_capabilities = context[
        "authorized_external_capabilities"
    ]
    prior_active_executable_function = context[
        "active_executable_function"
    ]
    direct_capabilities = v2_external_callable_capabilities(value)
    if direct_capabilities and direct_capabilities.isdisjoint(
        prior_authorized_capabilities
    ):
        raise EvidenceFailed(
            "refusal callback reaches a private fixture implementation "
            "without its exact selected-resource wrapper"
        )
    if identity in active:
        return {
            "kind": "executable-call-cycle",
            "function_node_id": context["object_ids"].get(identity),
        }
    if identity in completed:
        return {
            "kind": "executable-call-reference",
            "function_node_id": context["object_ids"].get(identity),
        }
    if value is v2_validate_exact_json_wire:
        function_node_id = context["object_ids"].get(identity)
        if function_node_id is None:
            v2_refusal_charge(context, "nodes")
            function_node_id = context["next_node_id"]
            context["next_node_id"] += 1
            context["object_ids"][identity] = function_node_id
        runtime_preflight_contract = V2_RUNTIME_CODE_PREFLIGHT_CONTRACT
        if (
            type(runtime_preflight_contract) is not tuple
            or len(runtime_preflight_contract) != 26
        ):
            raise EvidenceFailed(
                "exact-wire refusal boundary lost its runtime preflight"
            )
        preflight_callable = tuple.__getitem__(
            runtime_preflight_contract,
            0,
        )
        if (
            preflight_callable is not v2_validate_runtime_code_contracts
            or type(preflight_callable) is not types.FunctionType
        ):
            raise EvidenceFailed(
                "exact-wire refusal boundary lost its runtime preflight"
            )
        preflight_callable()
        keyword_defaults = v2_raw_function_attribute(
            value,
            "__kwdefaults__",
        )
        if type(keyword_defaults) is not dict:
            raise EvidenceFailed(
                "exact-wire refusal boundary lost its exact cap defaults"
            )
        completed.add(identity)
        return {
            "kind": "audited-exact-wire-validator-boundary",
            "function_node_id": function_node_id,
            "code": v2_code_semantic_projection(
                pinned_local_code,
                context=context,
            ),
            "cap_defaults": {
                key: item for key, item in dict.items(keyword_defaults)
            },
            "dependency_contract": (
                "runtime-code-preflight-transitive-closure"
            ),
            "input_state": "projected-by-caller-before-execution",
        }
    selected_scope_role = (
        v2_fixture_selected_resource_scope_boundary_role(value)
    )
    if selected_scope_role is not None:
        code = v2_raw_function_attribute(value, "__code__")
        if type(code) is not types.CodeType:
            raise EvidenceFailed(
                "selected-resource scope boundary lost its exact code"
            )
        completed.add(identity)
        return {
            "kind": "audited-selected-resource-scope-boundary",
            "role": selected_scope_role,
            "code": v2_code_semantic_projection(code, context=context),
            "closure_state": "INTENTIONALLY_NOT_AUTHORITY_EVIDENCE",
            "no_claim": (
                "the exact scope boundary is code-identity-bound and tested "
                "separately; live thread and token state is not portable "
                "refusal evidence"
            ),
        }
    active.add(identity)
    try:
        context["active_executable_function"] = value
        # A nested untrusted helper must not inherit ambient authorization from
        # a caller. Exact top-level harness functions receive only the direct
        # external capabilities statically named by their own code below.
        context["authorized_external_capabilities"] = frozenset(
            set(context["explicit_external_capabilities"]).union(
                v2_fixture_executable_internal_capabilities(value)
            )
        )
        code = v2_raw_function_attribute(value, "__code__")
        closure = v2_raw_function_attribute(value, "__closure__") or ()
        if type(code) is not types.CodeType or type(closure) is not tuple:
            raise EvidenceFailed(
                "refusal-state executable function metadata is not exact"
            )
        if len(closure) != len(code.co_freevars):
            raise EvidenceFailed(
                "refusal-state executable function closure metadata differs"
            )
        if code is V2_CONTEXTMANAGER_HELPER_CODE:
            function_attributes = v2_raw_function_attribute(
                value,
                "__dict__",
            )
            wrapped = function_attributes.get("__wrapped__")
            if type(wrapped) is not types.FunctionType:
                raise EvidenceFailed(
                    "refusal-state contextmanager wrapper lacks an exact "
                    "Python function"
                )
            projection = {
                "kind": "contextmanager-executable-wrapper",
                "function_node_id": context["object_ids"].get(identity),
                "wrapper_code": v2_code_semantic_projection(
                    code,
                    context=context,
                ),
                "wrapped": v2_executable_function_overlay(
                    wrapped,
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
            }
            completed.add(identity)
            return projection
        code_projection = v2_code_semantic_projection(
            code,
            context=context,
        )
        analysis = v2_code_access_analysis(
            code,
            context=context,
            constants_prevalidated=True,
        )
        function_globals = v2_raw_function_attribute(value, "__globals__")
        function_builtins = v2_raw_function_attribute(value, "__builtins__")
        if type(function_globals) is not dict:
            raise EvidenceFailed(
                "refusal-state executable globals mapping is not exact"
            )
        if v2_raw_instance_of(function_builtins, types.ModuleType):
            builtin_values = v2_raw_module_dict(function_builtins)
        elif type(function_builtins) is dict:
            builtin_values = function_builtins
        else:
            raise EvidenceFailed(
                "refusal-state executable builtins mapping is not exact"
            )
        projection_context = context
        global_rows: list[dict[str, Any]] = []
        for name, operations in analysis["accesses"].items():
            global_present = name in function_globals
            builtin_present = not global_present and name in builtin_values
            row: dict[str, Any] = {
                "name": name,
                "operations": list(operations),
                "source": (
                    "global"
                    if global_present
                    else "builtin"
                    if builtin_present
                    else "missing"
                ),
            }
            if global_present or builtin_present:
                global_value = (
                    function_globals[name]
                    if global_present
                    else builtin_values[name]
                )
                operation_paths = analysis[
                    "operation_protocol_global_paths"
                ].get(name)
                environment_mutation_base = bool(
                    global_value is os
                    and not analysis["module_paths"].get(name)
                    and name not in analysis["bare_global_names"]
                    and operation_paths
                    and set(operation_paths) == {()}
                    and {
                        mode
                        for modes in operation_paths.values()
                        for mode in modes
                    }.issubset({
                        (
                            V2_AUDITED_ENVIRONMENT_OPERATION_PREFIX
                            + "store-attribute:environ"
                        ),
                        (
                            V2_AUDITED_ENVIRONMENT_OPERATION_PREFIX
                            + "store-attribute:environb"
                        ),
                    })
                    and {
                        V2_FIXTURE_SELECTED_RESOURCE_SCOPE_CONTROL_CAPABILITY,
                        "process-python-environment",
                    }.issubset(
                        projection_context[
                            "authorized_external_capabilities"
                        ]
                    )
                )
                row["state"] = (
                    {
                        "kind": "audited-environment-mutation-module-base",
                        "module": "os",
                    }
                    if environment_mutation_base
                    else
                    v2_trusted_callable_projection(
                        global_value,
                        seen=seen,
                        context=projection_context,
                        depth=depth + 1,
                    )
                    if type(global_value) is types.FunctionType
                    else v2_state_projection_value(
                        global_value,
                        seen=seen,
                        context=projection_context,
                        module_paths=analysis["module_paths"].get(name),
                        bare_module_reference=(
                            name in analysis["bare_global_names"]
                        ),
                        depth=depth + 1,
                    )
                )
                row["executable_access"] = v2_executable_access_projection(
                    global_value,
                    binding_name=name,
                    paths=analysis["module_paths"].get(name),
                    bare_reference=(
                        name in analysis["bare_global_names"]
                    ),
                    called=(name in analysis["called_global_names"]),
                    called_paths=analysis["called_global_paths"].get(name),
                    call_result_paths=analysis["call_result_paths"].get(name),
                    path_call_result_paths=analysis[
                        "global_path_call_result_paths"
                    ].get(name),
                    seen=seen,
                    context=projection_context,
                    depth=depth + 1,
                    protocol_used=(
                        name in analysis["protocol_global_names"]
                    ),
                    mapping_keys_used=(
                        name in analysis[
                            "mapping_key_protocol_global_names"
                        ]
                    ),
                    contains_used=(
                        name in analysis["contains_protocol_global_names"]
                    ),
                    operation_protocol_paths=analysis[
                        "operation_protocol_global_paths"
                    ].get(name),
                )
            global_rows.append(row)
        closure_rows: list[dict[str, Any]] = []
        for name, cell in zip(code.co_freevars, closure, strict=True):
            try:
                cell_value = cell.cell_contents
            except ValueError:
                closure_rows.append({"name": name, "state": {"kind": "empty-cell"}})
                continue
            paths = analysis["freevar_paths"].get(name)
            closure_rows.append({
                "name": name,
                "state": v2_state_projection_value(
                    cell_value,
                    seen=seen,
                    context=projection_context,
                    module_paths=paths,
                    bare_module_reference=(
                        name in analysis["bare_freevar_names"]
                    ),
                    depth=depth + 1,
                ),
                "executable_access": v2_executable_access_projection(
                    cell_value,
                    binding_name=name,
                    paths=paths,
                    bare_reference=(
                        name in analysis["bare_freevar_names"]
                    ),
                    called=(name in analysis["called_freevar_names"]),
                    called_paths=analysis["called_freevar_paths"].get(name),
                    call_result_paths=analysis[
                        "freevar_call_result_paths"
                    ].get(name),
                    path_call_result_paths=analysis[
                        "freevar_path_call_result_paths"
                    ].get(name),
                    seen=seen,
                    context=projection_context,
                    depth=depth + 1,
                    protocol_used=(
                        name in analysis["protocol_freevar_names"]
                    ),
                    mapping_keys_used=(
                        name in analysis[
                            "mapping_key_protocol_freevar_names"
                        ]
                    ),
                    contains_used=(
                        name in analysis["contains_protocol_freevar_names"]
                    ),
                    operation_protocol_paths=analysis[
                        "operation_protocol_freevar_paths"
                    ].get(name),
                ),
            })
        default_bindings = v2_function_default_bindings(value, code)
        parameter_rows: list[dict[str, Any]] = []
        for name in code.co_varnames[: code.co_argcount + code.co_kwonlyargcount]:
            if name not in default_bindings:
                continue
            parameter_value = default_bindings[name]
            paths = analysis["parameter_paths"].get(name)
            parameter_rows.append({
                "name": name,
                "state": v2_state_projection_value(
                    parameter_value,
                    seen=seen,
                    context=projection_context,
                    module_paths=paths,
                    bare_module_reference=(
                        name in analysis["bare_parameter_names"]
                    ),
                    depth=depth + 1,
                ),
                "executable_access": v2_executable_access_projection(
                    parameter_value,
                    binding_name=name,
                    paths=paths,
                    bare_reference=(
                        name in analysis["bare_parameter_names"]
                    ),
                    called=(name in analysis["called_parameter_names"]),
                    called_paths=analysis[
                        "called_parameter_paths"
                    ].get(name),
                    call_result_paths=analysis[
                        "parameter_call_result_paths"
                    ].get(name),
                    path_call_result_paths=analysis[
                        "parameter_path_call_result_paths"
                    ].get(name),
                    seen=seen,
                    context=projection_context,
                    depth=depth + 1,
                    protocol_used=(
                        name in analysis["protocol_parameter_names"]
                    ),
                    mapping_keys_used=(
                        name in analysis[
                            "mapping_key_protocol_parameter_names"
                        ]
                    ),
                    contains_used=(
                        name in analysis["contains_protocol_parameter_names"]
                    ),
                    operation_protocol_paths=analysis[
                        "operation_protocol_parameter_paths"
                    ].get(name),
                ),
            })
        v2_refusal_charge(
            projection_context,
            "items",
            len(global_rows) + len(closure_rows) + len(parameter_rows),
        )
        projection = {
            "kind": "executable-function-accesses",
            "function_node_id": context["object_ids"].get(identity),
            "name": code.co_qualname,
            "code": code_projection,
            "referenced_globals": global_rows,
            "referenced_closure": closure_rows,
            "referenced_default_parameters": parameter_rows,
            "no_claim": V2_EXECUTABLE_CODE_PROJECTION_NO_CLAIM,
        }
        completed.add(identity)
        return projection
    finally:
        context[
            "authorized_external_capabilities"
        ] = prior_authorized_capabilities
        context[
            "active_executable_function"
        ] = prior_active_executable_function
        active.discard(identity)


def v2_called_value_projection(
    value: Any,
    *,
    call_result_paths: Sequence[Sequence[str]] | None,
    seen: dict[int, int],
    context: dict[str, Any],
    depth: int,
) -> dict[str, Any]:
    value_is_type = v2_raw_is_type_object(value)
    direct_result_invocation = any(
        tuple(str(part) for part in path) == V2_DIRECT_CALL_RESULT_PATH
        for path in call_result_paths or ()
    )
    if direct_result_invocation:
        raise EvidenceFailed(
            "refusal callback invokes a dynamically produced call result"
        )
    nonempty_result_paths = [
        tuple(str(part) for part in path)
        for path in call_result_paths or ()
        if path and tuple(str(part) for part in path) != V2_DIRECT_CALL_RESULT_PATH
    ]
    active_executable_function = context.get("active_executable_function")
    active_executable_code = (
        v2_raw_function_attribute(
            active_executable_function,
            "__code__",
        )
        if type(active_executable_function) is types.FunctionType
        else None
    )
    obligation_code_contract_is_current = any(
        active_executable_function is candidate
        and active_executable_code is code
        for candidate, code in V2_CHECK_OBLIGATION_CODE_CONTRACTS
    )
    assertion_projector_code_contract_is_current = (
        active_executable_function
        is V2_ASSERTION_EVIDENCE_PROJECTOR_CONTRACT[0]
        and active_executable_code
        is V2_ASSERTION_EVIDENCE_PROJECTOR_CONTRACT[1]
    )
    child_payload_code_contract_is_current = (
        active_executable_function
        is V2_CHILD_PAYLOAD_VALIDATOR_CONTRACT[0]
        and active_executable_code
        is V2_CHILD_PAYLOAD_VALIDATOR_CONTRACT[1]
    )
    history_json_code_contract_is_current = any(
        active_executable_function is candidate
        and active_executable_code is code
        for candidate, code in V2_HISTORY_JSON_HELPER_CODE_CONTRACTS
    )
    exact_container_validator_result_paths = next(
        (
            allowed_paths
            for candidate, code, descriptor, allowed_paths
            in V2_EXACT_CONTAINER_VALIDATOR_RESULT_CONTRACTS
            if active_executable_function is candidate
            and active_executable_code is code
            and value is descriptor
        ),
        None,
    )
    if value_is_type:
        if type(value) is not type:
            raise EvidenceFailed(
                "refusal callback calls a class with a custom metaclass; "
                "provide an explicit bounded projection"
            )
        constructor_rows: list[dict[str, Any]] = []
        trusted_builtin_constructor = any(
            value is candidate
            for candidate in V2_REFUSAL_TRUSTED_BUILTIN_TYPES
        )
        audited_constructor = any(
            value is candidate
            for candidate in V2_REFUSAL_AUDITED_CONSTRUCTOR_TYPES
        )
        if not trusted_builtin_constructor and not audited_constructor:
            harness_error_constructor = HarnessError in v2_raw_type_mro(
                value
            )
            for constructor_name in ("__new__", "__init__"):
                constructor = v2_raw_attribute_without_user_code(
                    value,
                    constructor_name,
                )
                if type(constructor) is types.MethodType:
                    constructor = v2_exact_descriptor_read(
                        V2_METHOD_ATTRIBUTE_DESCRIPTORS["__func__"],
                        constructor,
                        types.MethodType,
                        label=f"{constructor_name} function",
                    )
                if type(constructor) is types.FunctionType:
                    constructor_rows.append({
                        "name": constructor_name,
                        "state": v2_executable_function_overlay(
                            constructor,
                            seen=seen,
                            context=context,
                            depth=depth + 1,
                        ),
                    })
                elif (
                    constructor is object.__new__
                    or constructor is object.__init__
                    or harness_error_constructor
                ):
                    constructor_rows.append({
                        "name": constructor_name,
                        "state": {
                            "kind": "audited-base-constructor",
                            "identity": (
                                "harness-error-base"
                                if harness_error_constructor
                                else "builtins.object"
                            ),
                        },
                    })
                else:
                    raise EvidenceFailed(
                        "refusal callback calls a class with an unaudited "
                        f"native {constructor_name} constructor"
                    )
        if nonempty_result_paths and not trusted_builtin_constructor:
            for result_path in nonempty_result_paths:
                audited_native_result_path = (
                    len(result_path) == 1
                    and result_path[0]
                    in V2_AUDITED_CONSTRUCTOR_NATIVE_RESULT_PATHS.get(
                        value,
                        frozenset(),
                    )
                )
                if audited_native_result_path:
                    constructor_rows.append({
                        "name": result_path[0],
                        "state": {
                            "kind": (
                                "audited-local-constructor-native-result-path"
                            ),
                            "constructor": v2_type_identity(value),
                        },
                    })
                    continue
                method = v2_raw_attribute_without_user_code(
                    value,
                    result_path[0],
                )
                if type(method) is types.MethodType:
                    method = v2_exact_descriptor_read(
                        V2_METHOD_ATTRIBUTE_DESCRIPTORS["__func__"],
                        method,
                        types.MethodType,
                        label="constructed result method function",
                    )
                if type(method) is property:
                    method = v2_exact_descriptor_read(
                        V2_PROPERTY_ACCESSOR_DESCRIPTORS["fget"],
                        method,
                        property,
                        label="constructed result property getter",
                    )
                if type(method) is types.FunctionType:
                    constructor_rows.append({
                        "name": ".".join(result_path),
                        "state": v2_executable_function_overlay(
                            method,
                            seen=seen,
                            context=context,
                            depth=depth + 1,
                        ),
                    })
                else:
                    raise EvidenceFailed(
                        "refusal callback calls a dynamically resolved class "
                        "result path without an auditable Python function: "
                        f"{v2_type_identity(value)}.{'.'.join(result_path)}"
                    )
        return {
            "kind": "called-class",
            "constructors": constructor_rows,
        }
    if nonempty_result_paths:
        if exact_container_validator_result_paths is not None:
            if not all(
                path in exact_container_validator_result_paths
                for path in nonempty_result_paths
            ):
                descriptor_name = (
                    v2_optional_raw_builtin_descriptor_attribute(
                        value,
                        "__name__",
                    )
                )
                raise EvidenceFailed(
                    "refusal callback exact-container validator result path "
                    "is outside its code-identity-bound contract: "
                    f"active={active_executable_function.__qualname__}; "
                    f"descriptor={v2_type_identity(type(value))}."
                    f"{descriptor_name or '<unnamed>'}; "
                    f"paths={[list(path) for path in nonempty_result_paths]}"
                )
            return {
                "kind": "audited-exact-container-validator-result",
                "paths": [list(path) for path in nonempty_result_paths],
            }
        if (
            child_payload_code_contract_is_current
            and value is dict.__getitem__
            and all(
                path == V2_DERIVED_CALL_RESULT_PATH
                for path in nonempty_result_paths
            )
        ):
            # The exact validator admits only an exact outer dict, then applies
            # exact nested-type gates before every length, iteration, or member
            # operation on values returned through this base descriptor.
            return {
                "kind": "audited-child-payload-dict-getitem-results",
                "paths": [list(path) for path in nonempty_result_paths],
            }
        if (
            history_json_code_contract_is_current
            and value is dict.get
            and all(
                path
                in {
                    V2_DERIVED_CALL_RESULT_PATH,
                    ("<iter-item>",),
                }
                or (
                    context.get("active_executable_function")
                    is v2_build_inventory
                    and path == ("<iter-item>", "get")
                )
                for path in nonempty_result_paths
            )
        ):
            return {
                "kind": "audited-history-json-dict-get-result-paths",
                "paths": [list(path) for path in nonempty_result_paths],
            }
        if (
            obligation_code_contract_is_current
            and any(
                value is candidate
                for candidate in (
                    dict.__iter__,
                    dict.__len__,
                    list.__len__,
                    list.__getitem__,
                )
            )
            and all(
                path == V2_DERIVED_CALL_RESULT_PATH
                for path in nonempty_result_paths
            )
        ):
            # The registry first proves every receiver is an exact dict and
            # every key is an exact string. Its base-descriptor iterator is
            # then consumed only to build a bounded detached key sequence.
            return {
                "kind": "audited-obligation-registry-dict-base-result",
                "paths": [list(path) for path in nonempty_result_paths],
            }
        if (
            obligation_code_contract_is_current
            and value is dict.__getitem__
            and all(
                path == V2_DERIVED_CALL_RESULT_PATH
                for path in nonempty_result_paths
            )
        ):
            # Each validator first proves the receiver is an exact dict with
            # exact string keys, then exact-gates every returned scalar or
            # container before it performs a protocol-bearing operation.
            return {
                "kind": "audited-obligation-exact-dict-getitem-result",
                "paths": [list(path) for path in nonempty_result_paths],
            }
        if (
            assertion_projector_code_contract_is_current
            and any(
                value is candidate
                for candidate in (
                    dict.__contains__,
                    dict.__getitem__,
                    dict.__len__,
                    OrderedDict.__len__,
                    list.__len__,
                    tuple.__len__,
                    set.__len__,
                    frozenset.__len__,
                )
            )
            and all(
                path == V2_DERIVED_CALL_RESULT_PATH
                for path in nonempty_result_paths
            )
        ):
            # The code-identity-bound projector reaches each base descriptor
            # only after its matching exact-container type gate. Length and
            # membership results feed only closed-shape or bounded accounting;
            # selected values are immediately exact-type/semantic-root gated.
            return {
                "kind": "audited-assertion-evidence-exact-container-result",
                "paths": [list(path) for path in nonempty_result_paths],
            }
        if (
            assertion_projector_code_contract_is_current
            and value is id
            and all(
                path == V2_DERIVED_CALL_RESULT_PATH
                for path in nonempty_result_paths
            )
        ):
            # Container identities are used only for active-ancestor cycle
            # detection. They never enter the deterministic evidence output.
            return {
                "kind": "audited-assertion-evidence-cycle-identity",
                "paths": [list(path) for path in nonempty_result_paths],
            }
        if (
            assertion_projector_code_contract_is_current
            and any(
                value is candidate
                for candidate in (
                    dict.__iter__,
                    list.__iter__,
                    tuple.__iter__,
                    set.__iter__,
                    frozenset.__iter__,
                )
            )
            and all(
                path
                in {
                    V2_DERIVED_CALL_RESULT_PATH,
                    ("<iter-item>",),
                }
                for path in nonempty_result_paths
            )
        ):
            # Each iterator is reached only after its matching exact-container
            # type gate. The dict-envelope path exact-gates every key; sequence
            # and set paths consume only a bounded detached snapshot.
            return {
                "kind": "audited-assertion-evidence-exact-container-iteration",
                "paths": [list(path) for path in nonempty_result_paths],
            }
        if (
            assertion_projector_code_contract_is_current
            and any(
                value is candidate
                for candidate in (
                    dict.items,
                    OrderedDict.items,
                )
            )
            and all(
                path
                in {
                    V2_DERIVED_CALL_RESULT_PATH,
                    ("<iter-item>",),
                }
                for path in nonempty_result_paths
            )
        ):
            # Exact mapping gates precede these base ``items`` snapshots; each
            # detached pair is length-checked and its key exact-string gated
            # before projection or dictionary insertion.
            return {
                "kind": "audited-assertion-evidence-exact-mapping-items",
                "paths": [list(path) for path in nonempty_result_paths],
            }
        if (
            assertion_projector_code_contract_is_current
            and value is memoryview.tobytes
            and all(
                path == V2_DERIVED_CALL_RESULT_PATH
                for path in nonempty_result_paths
            )
        ):
            # The exact memoryview type gate precedes the base descriptor call;
            # its detached bytes result is length-checked before hashing.
            return {
                "kind": "audited-assertion-evidence-memoryview-snapshot",
                "paths": [list(path) for path in nonempty_result_paths],
            }
        audited_result_methods = next(
            (
                methods
                for candidate, methods in V2_AUDITED_PURE_CALL_RESULT_PATHS
                if value is candidate
            ),
            None,
        )
        if audited_result_methods is None:
            local_audited_row = next(
                (
                    (candidate, methods)
                    for candidate, methods
                    in V2_AUDITED_LOCAL_PURE_CALL_RESULT_PATHS
                    if value is candidate
                ),
                None,
            )
            if local_audited_row is not None:
                local_candidate, local_methods = local_audited_row
                local_code_is_current = (
                    type(local_candidate) is not types.FunctionType
                    or any(
                        local_candidate is pinned_candidate
                        and v2_raw_function_attribute(
                            local_candidate,
                            "__code__",
                        )
                        is pinned_code
                        for pinned_candidate, pinned_code
                        in V2_AUDITED_LOCAL_PURE_CALL_CODE_CONTRACTS
                    )
                )
                if local_code_is_current:
                    audited_result_methods = local_methods
        if audited_result_methods is None and type(value) in {
            types.BuiltinFunctionType,
            types.BuiltinMethodType,
            V2_REGEX_BOUND_METHOD_TYPE,
        }:
            bound_self = v2_optional_raw_builtin_descriptor_attribute(
                value,
                "__self__",
            )
            bound_name = v2_optional_raw_builtin_descriptor_attribute(
                value,
                "__name__",
            )
            audited_result_methods = next(
                (
                    methods
                    for owner, name, methods
                    in V2_AUDITED_PURE_BOUND_CALL_RESULT_PATHS
                    if bound_self is owner and bound_name == name
                ),
                None,
            )
            if (
                audited_result_methods is None
                and type(value) is V2_REGEX_BOUND_METHOD_TYPE
                and bound_name in {"finditer", "fullmatch"}
            ):
                audited_result_methods = (
                    frozenset({
                        V2_DERIVED_CALL_RESULT_PATH[0],
                        ("<iter-item>", "group"),
                    })
                    if bound_name == "finditer"
                    else frozenset({
                        V2_DERIVED_CALL_RESULT_PATH[0],
                    })
                )
        if audited_result_methods is not None and all(
            path in audited_result_methods
            or len(path) == 1 and path[0] in audited_result_methods
            for path in nonempty_result_paths
        ):
            return {
                "kind": "audited-pure-call-result-paths",
                "paths": [list(path) for path in nonempty_result_paths],
            }
        capabilities = v2_external_callable_capabilities(value)
        if capabilities and not capabilities.isdisjoint(
            context["authorized_external_capabilities"]
        ):
            return {
                "kind": "authorized-external-call-result-paths",
                "capabilities": sorted(capabilities),
                "paths": [list(path) for path in nonempty_result_paths],
            }
        active_function = context.get("active_executable_function")
        active_name = (
            v2_raw_function_attribute(active_function, "__qualname__")
            if type(active_function) is types.FunctionType
            else v2_type_identity(type(active_function))
        )
        value_name: str | None = None
        if type(value) is types.FunctionType:
            raw_value_name = v2_raw_function_attribute(
                value,
                "__qualname__",
            )
            if type(raw_value_name) is str:
                value_name = raw_value_name
        elif type(value) in {
            types.BuiltinFunctionType,
            types.BuiltinMethodType,
            types.MethodDescriptorType,
            types.WrapperDescriptorType,
            V2_REGEX_BOUND_METHOD_TYPE,
        }:
            raw_value_name = v2_optional_raw_builtin_descriptor_attribute(
                value,
                "__name__",
            )
            if type(raw_value_name) is str:
                value_name = raw_value_name
        raise EvidenceFailed(
            "refusal callback dereferences a dynamically resolved callable "
            "result; provide an explicit bounded return-state projection: "
            f"active={active_name}; callable_type="
            f"{v2_type_identity(type(value))}; callable_name="
            f"{value_name or '<unnamed>'}; paths="
            f"{[list(path) for path in nonempty_result_paths]}"
        )
    return {"kind": "called-value-without-result-dereference"}


def v2_validate_protocol_argument_value(
    value: Any,
    *,
    label: str,
    depth: int = 0,
) -> None:
    """Reject values whose protocol conversion can dispatch user hooks."""
    if depth > V2_REFUSAL_STATE_DEPTH_CAP:
        raise EvidenceFailed(f"{label} protocol value exceeds its depth cap")
    exact_type = type(value)
    if any(
        value is exact_builtin_identity
        for exact_builtin_identity in (
            builtins.bytes,
            builtins.dict,
            builtins.str,
        )
    ):
        # CPython 3.13+ can retain the owner of an unbound exact built-in
        # descriptor in the simulated call frame.  These identities are
        # inert class objects here, not user-provided protocol operands.
        return
    if exact_type is slice:
        # ``slice`` itself is exact, but applying it can invoke
        # ``__index__`` on any of start/stop/step.  Validate those exact
        # components instead of incorrectly treating the wrapper as inert.
        for component in (value.start, value.stop, value.step):
            v2_validate_protocol_argument_value(
                component,
                label=label,
                depth=depth + 1,
            )
        return
    if exact_type in {
        type(None),
        bool,
        int,
        float,
        complex,
        str,
        bytes,
        bytearray,
        range,
    }:
        return
    if exact_type is types.CodeType:
        # A code object is admitted only after its bytecode metadata and every
        # nested constant pass the exact-type semantic projection. CPython can
        # construct an exact CodeType containing hostile custom constants, so
        # exact type identity alone is intentionally insufficient.
        v2_code_semantic_projection(
            value,
            context=v2_new_refusal_projection_context(),
            depth=depth + 1,
        )
        return
    if exact_type is list:
        members = list.__iter__(value)
    elif exact_type is tuple:
        members = tuple.__iter__(value)
    elif exact_type is set:
        members = set.__iter__(value)
    elif exact_type is frozenset:
        members = frozenset.__iter__(value)
    elif exact_type is dict:
        members = (
            item
            for pair in dict.items(value)
            for item in pair
        )
    elif exact_type is OrderedDict:
        members = (
            item
            for pair in OrderedDict.items(value)
            for item in pair
        )
    else:
        raise EvidenceFailed(
            f"{label} protocol argument has a hook-bearing or non-exact "
            f"type: {v2_type_identity(exact_type)}"
        )
    for member in members:
        v2_validate_protocol_argument_value(
            member,
            label=label,
            depth=depth + 1,
        )


def v2_validate_container_protocol_argument_value(
    value: Any,
    *,
    label: str,
    contains: bool,
) -> None:
    """Validate lookup/containment receivers with dict key-only precision."""
    if type(value) is dict:
        keys = dict.__iter__(value)
    elif type(value) is OrderedDict:
        keys = OrderedDict.__iter__(value)
    else:
        if contains:
            v2_validate_protocol_argument_value(value, label=label)
            return
        if type(value) in {
            list,
            tuple,
            str,
            bytes,
            bytearray,
            range,
        }:
            return
        raise EvidenceFailed(
            f"{label} lookup receiver has a hook-bearing or non-exact "
            f"type: {v2_type_identity(type(value))}"
        )
    for key in keys:
        v2_validate_protocol_argument_value(key, label=label)


def v2_validate_operation_protocol_argument_value(
    value: Any,
    *,
    mode: str,
    label: str,
    context: Mapping[str, Any],
) -> None:
    """Validate one implicit opcode protocol without touching inert members."""
    exact_type = type(value)
    environment_capabilities = {
        V2_FIXTURE_SELECTED_RESOURCE_SCOPE_CONTROL_CAPABILITY,
        "process-python-environment",
    }
    if mode.startswith(
        V2_AUDITED_RETAINED_RECONSTRUCTION_OPERATION_PREFIX
    ):
        exact_mode = mode[
            len(V2_AUDITED_RETAINED_RECONSTRUCTION_OPERATION_PREFIX) :
        ]
        if (
            value is _v2_child_transport_cache_lock
            and exact_mode == "context"
            and any(
                context.get("active_executable_function") is candidate
                and candidate.__code__ is contract_code
                for candidate, contract_code
                in V2_TRANSPORT_CACHE_TRANSACTION_CODE_CONTRACTS
            )
        ):
            return
        raise EvidenceFailed(
            f"{label} retained-reconstruction operation has a mismatched "
            f"exact receiver or mode: {exact_mode}"
        )
    if mode.startswith(V2_AUDITED_TRANSPORT_CACHE_OPERATION_PREFIX):
        exact_mode = mode[
            len(V2_AUDITED_TRANSPORT_CACHE_OPERATION_PREFIX) :
        ]
        allowed_operations = next(
            (
                operations
                for contract_callable, contract_code, operations
                in V2_TRANSPORT_CACHE_MUTATION_CODE_CONTRACTS
                if context.get("active_executable_function")
                is contract_callable
                and contract_callable.__code__ is contract_code
            ),
            frozenset(),
        )
        if (
            value is _v2_child_transport_cache
            and exact_mode in allowed_operations
        ):
            return
        raise EvidenceFailed(
            f"{label} transport-cache operation has a mismatched exact "
            f"receiver or mode: {exact_mode}"
        )
    if (
        any(
            value is candidate
            for candidate in (
                V2_PROCESS_ENVIRONMENT_PROTECTED_DESCENDANT_BINDINGS
            )
        )
        and (
            mode in {"store-subscript", "delete-subscript"}
            or mode.startswith("store-attribute:")
            or mode.startswith("delete-attribute:")
        )
    ):
        raise EvidenceFailed(
            f"{label} protected environment descendant mutation lacks exact "
            f"analyzed operation provenance for mode {mode}"
        )
    if (
        "process-python-environment"
        in context["authorized_external_capabilities"]
        and value is V2_PROCESS_ENVIRONMENT_BYTES_BINDING
        and mode == "iterate"
    ):
        return
    if mode.startswith(V2_AUDITED_ENVIRONMENT_OPERATION_PREFIX):
        exact_mode = mode[len(V2_AUDITED_ENVIRONMENT_OPERATION_PREFIX) :]
        if not environment_capabilities.issubset(
            context["authorized_external_capabilities"]
        ):
            raise EvidenceFailed(
                f"{label} audited environment operation lacks its exact "
                "capability set"
            )
        if (
            value is V2_PROCESS_ENVIRONMENT_BYTES_BINDING
            and exact_mode
            in {
                "store-subscript",
                "delete-subscript",
                "store-attribute:decodevalue",
            }
        ):
            return
        if (
            value is V2_PROCESS_ENVIRONMENT_TEXT_BINDING
            and exact_mode == "store-attribute:encodekey"
        ):
            return
        if value is os and exact_mode in {
            "store-attribute:environ",
            "store-attribute:environb",
        }:
            return
        raise EvidenceFailed(
            f"{label} audited environment operation has a mismatched exact "
            f"receiver or mode: {exact_mode}"
        )
    if (
        (
            any(
                value is candidate
                for candidate in (
                    V2_PROCESS_ENVIRONMENT_TEXT_BINDING,
                    V2_PROCESS_ENVIRONMENT_BYTES_BINDING,
                )
            )
            and (
                mode in {"store-subscript", "delete-subscript"}
                or mode.startswith("store-attribute:")
                or mode.startswith("delete-attribute:")
            )
        )
        or (
            value is os
            and mode
            in {
                "store-attribute:environ",
                "store-attribute:environb",
                "delete-attribute:environ",
                "delete-attribute:environb",
            }
        )
    ):
        raise EvidenceFailed(
            f"{label} protected environment mutation lacks exact analyzed "
            f"operation provenance for mode {mode}"
        )

    def resolves_default_attribute_mutator(
        *,
        deleting: bool,
        attribute_name: str,
    ) -> bool:
        dispatch_name = "__delattr__" if deleting else "__setattr__"
        if v2_raw_is_type_object(value):
            dispatch_mro = v2_raw_type_mro(type(value))
            expected_owner = type
            descriptor_mro = dispatch_mro
        else:
            dispatch_mro = v2_raw_type_mro(exact_type)
            expected_owner = object
            descriptor_mro = v2_raw_type_mro(exact_type)
        resolved_dispatch: tuple[type[Any], Any] | None = None
        for owner in dispatch_mro:
            attributes = v2_raw_type_dictionary(owner)
            if dispatch_name in attributes:
                resolved_dispatch = (owner, attributes[dispatch_name])
                break
        expected_dispatch = v2_raw_type_dictionary(expected_owner).get(
            dispatch_name
        )
        if (
            resolved_dispatch is None
            or resolved_dispatch[0] is not expected_owner
            or resolved_dispatch[1] is not expected_dispatch
        ):
            return False
        descriptor_operation = "__delete__" if deleting else "__set__"
        for owner in descriptor_mro:
            attributes = v2_raw_type_dictionary(owner)
            if attribute_name not in attributes:
                continue
            descriptor = attributes[attribute_name]
            descriptor_type_has_operation = any(
                descriptor_operation in v2_raw_type_dictionary(
                    descriptor_owner
                )
                for descriptor_owner in v2_raw_type_mro(type(descriptor))
            )
            if descriptor_type_has_operation and type(descriptor) not in {
                types.GetSetDescriptorType,
                types.MemberDescriptorType,
            }:
                return False
            break
        return True

    scalar_types = {
        type(None),
        bool,
        int,
        float,
        complex,
        str,
        bytes,
        bytearray,
        range,
        slice,
        type,
    }
    container_types = {
        list,
        tuple,
        set,
        frozenset,
        dict,
        OrderedDict,
    }
    if mode == "truth":
        if exact_type in scalar_types | container_types:
            return
    elif mode == "iterate":
        if exact_type in {
            str,
            bytes,
            bytearray,
            range,
            list,
            tuple,
            set,
            frozenset,
            dict,
            OrderedDict,
        }:
            return
    elif mode == "length":
        if exact_type in {
            str,
            bytes,
            bytearray,
            range,
            list,
            tuple,
            set,
            frozenset,
            dict,
            OrderedDict,
        }:
            return
    elif mode == "match-keys":
        if exact_type in {dict, OrderedDict}:
            v2_validate_container_protocol_argument_value(
                value,
                label=label,
                contains=True,
            )
            return
    elif mode == "slice-receiver":
        if exact_type in {
            str,
            bytes,
            bytearray,
            range,
            list,
            tuple,
        }:
            return
    elif mode.startswith("unary:"):
        if exact_type in scalar_types | container_types:
            return
    elif mode.startswith("binary:"):
        in_place_operator = mode.rpartition(":")[2]
        mutable_in_place_types: dict[str, set[type[Any]]] = {
            "+=": {list, bytearray},
            "*=": {list, bytearray},
            "|=": {dict, OrderedDict, set},
            "&=": {set},
            "-=": {set},
            "^=": {set},
        }
        if exact_type in mutable_in_place_types.get(
            in_place_operator,
            set(),
        ):
            raise EvidenceFailed(
                f"{label} exact mutable container operation is not "
                f"modeled for {mode}: {v2_type_identity(exact_type)}"
            )
        if exact_type in {set, frozenset, dict, OrderedDict}:
            # Set/dict algebra can compare or hash stored keys/elements.
            v2_validate_protocol_argument_value(value, label=label)
            return
        if exact_type in scalar_types | {list, tuple}:
            # Numeric/string operations and list/tuple concat/repeat do not
            # invoke hooks on contained values.
            return
    elif mode.startswith("compare:"):
        if exact_type in container_types | {slice}:
            # Equality and ordering can delegate to contained values.
            v2_validate_protocol_argument_value(value, label=label)
            return
        if exact_type in scalar_types:
            return
    elif mode == "context":
        # No exact built-in scalar/container has context-manager semantics.
        pass
    elif mode in {"store-subscript", "delete-subscript"}:
        # Any bound receiver predates callback entry; mutating it would make
        # the refusal proof depend on post-execution state comparison.
        pass
    elif mode.startswith("store-attribute:") or mode.startswith(
        "delete-attribute:"
    ):
        operation, _, attribute_name = mode.partition(":")
        deleting = operation == "delete-attribute"
        if (
            attribute_name != "<unknown>"
            and resolves_default_attribute_mutator(
                deleting=deleting,
                attribute_name=attribute_name,
            )
        ):
            return
    else:
        raise EvidenceFailed(f"{label} has an unknown operation mode: {mode}")
    raise EvidenceFailed(
        f"{label} operation protocol can dispatch user code for mode "
        f"{mode}: {v2_type_identity(exact_type)}"
    )


def v2_executable_access_projection(
    value: Any,
    *,
    binding_name: str | None = None,
    paths: Sequence[Sequence[str]] | None,
    bare_reference: bool,
    called: bool,
    called_paths: Sequence[Sequence[str]] | None,
    call_result_paths: Sequence[Sequence[str]] | None,
    path_call_result_paths: Mapping[
        tuple[str, ...],
        Sequence[Sequence[str]],
    ] | None,
    seen: dict[int, int],
    context: dict[str, Any],
    depth: int,
    protocol_used: bool = False,
    mapping_keys_used: bool = False,
    contains_used: bool = False,
    operation_protocol_paths: Mapping[
        tuple[str, ...],
        Sequence[str],
    ] | None = None,
) -> Any:
    binding_label = (
        f"refusal-state executable binding {binding_name!r}"
        if binding_name is not None
        else "refusal-state executable binding"
    )
    mutable_methods_by_type: tuple[
        tuple[type[Any], frozenset[str]],
        ...,
    ] = (
        (
            dict,
            frozenset({
                "__delitem__",
                "__init__",
                "__ior__",
                "__setitem__",
                "clear",
                "pop",
                "popitem",
                "setdefault",
                "update",
            }),
        ),
        (
            OrderedDict,
            frozenset({
                "__delitem__",
                "__init__",
                "__ior__",
                "__setitem__",
                "clear",
                "move_to_end",
                "pop",
                "popitem",
                "setdefault",
                "update",
            }),
        ),
        (
            list,
            frozenset({
                "__delitem__",
                "__iadd__",
                "__imul__",
                "__init__",
                "__setitem__",
                "append",
                "clear",
                "extend",
                "insert",
                "pop",
                "remove",
                "reverse",
                "sort",
            }),
        ),
        (
            bytearray,
            frozenset({
                "__delitem__",
                "__iadd__",
                "__imul__",
                "__init__",
                "__setitem__",
                "append",
                "clear",
                "extend",
                "insert",
                "pop",
                "remove",
                "reverse",
            }),
        ),
        (
            set,
            frozenset({
                "__iand__",
                "__init__",
                "__ior__",
                "__isub__",
                "__ixor__",
                "add",
                "clear",
                "difference_update",
                "discard",
                "intersection_update",
                "pop",
                "remove",
                "symmetric_difference_update",
                "update",
            }),
        ),
    )
    for raw_path in called_paths or ():
        path = tuple(str(part) for part in raw_path)
        if not path:
            continue
        receiver = value
        unavailable = False
        for part in path[:-1]:
            receiver = v2_raw_attribute_without_user_code(
                receiver,
                part,
                allow_absent_slot=True,
            )
            if (
                receiver is None
                or receiver is V2_RAW_DESCRIPTOR_ATTRIBUTE_ABSENT
            ):
                unavailable = True
                break
        if unavailable:
            continue
        mutator_names = next(
            (
                names
                for exact_type, names in mutable_methods_by_type
                if type(receiver) is exact_type
            ),
            frozenset(),
        )
        allowed_transport_cache_mutations = next(
            (
                operations
                for contract_callable, contract_code, operations
                in V2_TRANSPORT_CACHE_MUTATION_CODE_CONTRACTS
                if context.get("active_executable_function")
                is contract_callable
                and contract_callable.__code__ is contract_code
            ),
            frozenset(),
        )
        audited_retained_cache_mutator = bool(
            value is _v2_child_transport_cache
            and len(path) == 1
            and path[0] in allowed_transport_cache_mutations
        )
        if path[-1] in mutator_names and not audited_retained_cache_mutator:
            raise EvidenceFailed(
                "refusal-state exact mutable container receiver call is "
                f"not modeled: {v2_type_identity(type(receiver))}."
                f"{path[-1]}"
            )
    for raw_path, modes in (operation_protocol_paths or {}).items():
        path = tuple(str(part) for part in raw_path)
        operand = value
        unavailable = False
        for part in path:
            operand = v2_raw_attribute_without_user_code(
                operand,
                part,
                allow_absent_slot=True,
            )
            if (
                operand is None
                or operand is V2_RAW_DESCRIPTOR_ATTRIBUTE_ABSENT
            ):
                unavailable = True
                break
        if unavailable:
            continue
        for mode in modes:
            v2_validate_operation_protocol_argument_value(
                operand,
                mode=str(mode),
                label=binding_label,
                context=context,
            )
    if protocol_used:
        v2_validate_protocol_argument_value(
            value,
            label=binding_label,
        )
    if mapping_keys_used:
        v2_validate_container_protocol_argument_value(
            value,
            label=binding_label,
            contains=False,
        )
    if contains_used:
        v2_validate_container_protocol_argument_value(
            value,
            label=binding_label,
            contains=True,
        )
    rows: list[dict[str, Any]] = []
    if bare_reference and value is v2_state_projection_value:
        rows.append({
            "path": [],
            "state": {
                "kind": "refusal-projector-internal-executable-boundary",
                "function_node_id": context["object_ids"].get(id(value)),
            },
        })
    elif bare_reference and type(value) is types.FunctionType:
        rows.append({
            "path": [],
            "state": v2_executable_function_overlay(
                value,
                seen=seen,
                context=context,
                depth=depth + 1,
            ),
        })
    if called:
        rows.append({
            "path": ["<called>"],
            "state": v2_called_value_projection(
                value,
                call_result_paths=call_result_paths,
                seen=seen,
                context=context,
                depth=depth + 1,
            ),
        })
    normalized_called_paths = {
        tuple(str(part) for part in path)
        for path in called_paths or ()
    }
    normalized_path_results = {
        tuple(str(part) for part in path): result_paths
        for path, result_paths in (path_call_result_paths or {}).items()
    }
    for raw_path in paths or ():
        path = tuple(str(part) for part in raw_path)
        if (
            v2_raw_is_type_object(value)
            and path
            and path[0] == "mro"
        ):
            raise EvidenceFailed(
                "refusal callback uses dynamic class-MRO access; provide an "
                "explicit bounded projection"
            )
        current = value
        unavailable_none_path = False
        unavailable_slot_path = False
        for part in path:
            if current is None:
                unavailable_none_path = True
                break
            current = v2_raw_attribute_without_user_code(
                current,
                part,
                allow_absent_slot=True,
            )
            if current is V2_RAW_DESCRIPTOR_ATTRIBUTE_ABSENT:
                unavailable_slot_path = True
                break
        if unavailable_none_path:
            rows.append({
                "path": list(path),
                "state": {
                    "kind": "statically-unavailable-on-none-binding",
                },
            })
            continue
        if unavailable_slot_path:
            rows.append({
                "path": list(path),
                "state": {
                    "kind": "statically-unavailable-slot-binding",
                },
            })
            continue
        if v2_raw_instance_of(value, types.ModuleType) and v2_is_trusted_module(value):
            state: Any = {
                "kind": "audited-trusted-module-path",
                "module": v2_raw_module_name(value),
                "path": list(path),
            }
        elif type(current) is types.MethodType:
            function = v2_exact_descriptor_read(
                V2_METHOD_ATTRIBUTE_DESCRIPTORS["__func__"],
                current,
                types.MethodType,
                label="executable bound method function",
            )
            state = {
                "kind": "executable-bound-method",
                "function": v2_executable_function_overlay(
                    function,
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
                "bound_self": v2_state_projection_value(
                    v2_exact_descriptor_read(
                        V2_METHOD_ATTRIBUTE_DESCRIPTORS["__self__"],
                        current,
                        types.MethodType,
                        label="executable bound method self",
                    ),
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
            }
        elif current is v2_state_projection_value:
            state = {
                "kind": "refusal-projector-internal-executable-boundary",
                "function_node_id": context["object_ids"].get(id(current)),
            }
        elif type(current) is types.FunctionType:
            state = v2_executable_function_overlay(
                current,
                seen=seen,
                context=context,
                depth=depth + 1,
            )
        elif v2_raw_instance_of(current, types.ModuleType) and v2_is_trusted_module(current):
            raise EvidenceFailed(
                "refusal callback dynamically aliases a trusted module through "
                f"{'.'.join(path)}; provide an explicit bounded projection"
            )
        else:
            state = v2_state_projection_value(
                current,
                seen=seen,
                context=context,
                depth=depth + 1,
            )
        row = {"path": list(path), "state": state}
        if path in normalized_called_paths:
            row["called_state"] = v2_called_value_projection(
                current,
                call_result_paths=normalized_path_results.get(path),
                seen=seen,
                context=context,
                depth=depth + 1,
            )
        rows.append(row)
    if not rows:
        return {"kind": "no-executable-access"}
    v2_refusal_charge(context, "items", len(rows))
    return {"kind": "executable-accesses", "rows": rows}


def v2_project_module_value(
    value: types.ModuleType,
    *,
    module_paths: Sequence[Sequence[str]] | None,
    bare_reference: bool,
    seen: dict[int, int],
    context: dict[str, Any],
    depth: int,
) -> dict[str, Any]:
    attributes = v2_raw_module_dict(value)
    raw_module_name = attributes.get("__name__")
    if raw_module_name is not None and type(raw_module_name) is not str:
        raise EvidenceFailed("refusal-state module name is not exact")
    module_name = raw_module_name if raw_module_name is not None else ""
    if v2_is_trusted_module(value):
        if bare_reference or not module_paths:
            raise EvidenceFailed(
                f"refusal callback uses trusted module {module_name} "
                "dynamically; provide an explicit bounded external-state "
                "projection"
            )
        rows: list[dict[str, Any]] = []
        for raw_path in module_paths:
            path = tuple(str(part) for part in raw_path)
            required_path_capabilities = (
                v2_external_module_value_path_capabilities(
                    value,
                    (path,),
                )
            )
            if (
                required_path_capabilities
                and required_path_capabilities.isdisjoint(
                    context["authorized_external_capabilities"]
                )
            ):
                raise EvidenceFailed(
                    "refusal callback reaches external runtime state through "
                    f"{module_name}.{'.'.join(path)}; provide an explicit "
                    "bounded projection for one of "
                    f"{sorted(required_path_capabilities)}"
                )
            current: Any = value
            try:
                for part in path:
                    current = v2_raw_attribute_without_user_code(current, part)
            except HarnessError as error:
                path_text = ".".join(path)
                raise EvidenceFailed(
                    "refusal-state trusted module attribute path "
                    f"{module_name}.{path_text} is not statically present: "
                    f"{v2_bounded_diagnostic_summary(error)}"
                ) from error
            if v2_is_dangerous_builtin(current):
                raise EvidenceFailed(
                    "refusal callback reaches a dynamic namespace builtin; "
                    "provide an explicit bounded external-state projection"
                )
            v2_require_external_callable_authorized(
                current,
                context=context,
                label=f"{module_name}.{'.'.join(path)}",
            )
            if v2_exact_type_is_one_of(current, (
                types.FunctionType,
                types.BuiltinFunctionType,
            )):
                try:
                    state = v2_trusted_callable_projection(
                        current,
                        seen=seen,
                        context=context,
                        depth=depth + 1,
                    )
                except HarnessError as error:
                    path_text = ".".join(path)
                    raise EvidenceFailed(
                        "refusal-state trusted module callable "
                        f"{module_name}.{path_text} is not bounded: "
                        f"{v2_bounded_diagnostic_summary(error)}"
                    ) from error
            else:
                try:
                    state = v2_state_projection_value(
                        current,
                        seen=seen,
                        context=context,
                        depth=depth + 1,
                    )
                except HarnessError as error:
                    path_text = ".".join(path)
                    raise EvidenceFailed(
                        "refusal-state trusted module value "
                        f"{module_name}.{path_text} is not bounded: "
                        f"{v2_bounded_diagnostic_summary(error)}"
                    ) from error
            rows.append({"path": list(path), "state": state})
        v2_refusal_charge(context, "items", len(rows))
        return {
            "kind": "trusted-module-attributes",
            "module": module_name,
            "attributes": rows,
        }
    excluded = {
        "__builtins__",
        "__name__",
    }
    if "__builtins__" in attributes:
        raise EvidenceFailed(
            "refusal-state custom module __builtins__ requires an explicit "
            "bounded projection"
        )
    names = [name for name in attributes if name not in excluded]
    if any(type(name) is not str for name in names):
        raise EvidenceFailed("refusal-state module has a non-string attribute")
    names.sort(key=lambda name: name.encode("utf-8"))
    v2_refusal_charge(context, "items", len(names))
    module_attribute_rows: list[dict[str, Any]] = []
    for name in names:
        try:
            state = v2_state_projection_value(
                attributes[name],
                seen=seen,
                context=context,
                depth=depth + 1,
            )
        except HarnessError as error:
            raise EvidenceFailed(
                "refusal-state custom module attribute "
                f"{module_name}.{name} is not bounded: "
                f"{v2_bounded_diagnostic_summary(error)}"
            ) from error
        module_attribute_rows.append({"name": name, "state": state})
    return {
        "kind": "custom-module",
        "module": module_name,
        "attributes": module_attribute_rows,
        "type_state": v2_state_projection_value(
            type(value),
            seen=seen,
            context=context,
            depth=depth + 1,
        ),
    }


def v2_state_object_metadata(
    value: Any,
    *,
    seen: dict[int, int],
    context: dict[str, Any],
    depth: int,
) -> dict[str, Any]:
    raw_attributes = v2_raw_instance_dictionary(value)
    attribute_rows: list[dict[str, Any]] = []
    raw_attribute_items = list(dict.items(raw_attributes or {}))
    if any(type(name) is not str for name, _ in raw_attribute_items):
        raise EvidenceFailed(
            "refusal-state object has a non-string attribute"
        )
    for name, attribute in sorted(
        raw_attribute_items,
        key=lambda row: row[0].encode("utf-8"),
    ):
        attribute_rows.append(
            {
                "name": name,
                "state": v2_state_projection_value(
                    attribute,
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
            }
        )
    slot_rows: list[dict[str, Any]] = []
    owners = v2_raw_type_mro(type(value))
    for owner in owners:
        owner_attributes = v2_raw_type_dictionary(owner)
        for descriptor_name, descriptor in owner_attributes.items():
            if type(descriptor) is not types.MemberDescriptorType:
                continue
            try:
                slot_value = types.MemberDescriptorType.__get__(
                    descriptor,
                    value,
                    type(value),
                )
            except AttributeError:
                continue
            except Exception as error:
                raise EvidenceFailed(
                    "refusal-state slot inspection failed"
                ) from error
            slot_rows.append(
                {
                    "slot": f"{v2_type_identity(owner)}:{descriptor_name}",
                    "state": v2_state_projection_value(
                        slot_value,
                        seen=seen,
                        context=context,
                        depth=depth + 1,
                    ),
                }
            )
    slot_rows.sort(key=lambda row: row["slot"].encode("utf-8"))
    v2_refusal_charge(
        context,
        "items",
        len(attribute_rows) + len(slot_rows),
    )
    metadata: dict[str, Any] = {}
    if raw_attributes is not None:
        metadata["instance_dictionary_present"] = True
    if attribute_rows:
        metadata["attributes"] = attribute_rows
    if slot_rows:
        metadata["slots"] = slot_rows
    return metadata


def v2_class_attribute_executable_projection(
    attribute: Any,
    *,
    seen: dict[int, int],
    context: dict[str, Any],
    depth: int,
) -> Any | None:
    """Bind every Python executable reachable from one raw class attribute."""
    functions: list[tuple[str, types.FunctionType]] = []
    if type(attribute) is types.FunctionType:
        functions.append(("function", attribute))
    elif v2_exact_type_is_one_of(attribute, (staticmethod, classmethod)):
        wrapped = v2_unwrap_function_wrapper(attribute)
        if type(wrapped) is types.FunctionType:
            functions.append(("wrapped-function", wrapped))
    elif type(attribute) is property:
        for accessor, descriptor in V2_PROPERTY_ACCESSOR_DESCRIPTORS.items():
            function = v2_exact_descriptor_read(
                descriptor,
                attribute,
                property,
                label=f"property {accessor}",
            )
            if type(function) is types.FunctionType:
                functions.append((accessor, function))
    elif type(attribute) is V2_ENUM_PROPERTY_TYPE:
        raw_attributes = v2_raw_instance_dictionary(attribute)
        for name, value in dict.items(raw_attributes or {}):
            if type(name) is str and type(value) is types.FunctionType:
                functions.append((name, value))
    if not functions:
        return None
    functions.sort(key=lambda row: row[0].encode("utf-8"))
    v2_refusal_charge(context, "items", len(functions))
    return {
        "kind": "recursive-python-executable-closure",
        "functions": [
            {
                "role": role,
                "state": v2_executable_function_overlay(
                    function,
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
            }
            for role, function in functions
        ],
    }


def v2_state_projection_value(
    value: Any,
    *,
    seen: dict[int, int] | None = None,
    context: dict[str, Any] | None = None,
    module_paths: Sequence[Sequence[str]] | None = None,
    bare_module_reference: bool = True,
    allow_class_sentinel_object: bool = False,
    depth: int = 0,
) -> Any:
    if depth > V2_REFUSAL_STATE_DEPTH_CAP:
        raise EvidenceFailed("refusal-state projection exceeds its depth cap")
    if value is None or type(value) is bool:
        return value
    if context is None:
        context = v2_new_refusal_projection_context()
    if type(value) is int:
        integer_text = v2_bounded_exact_integer_text(
            value,
            label="refusal-state exact integer",
            error_type=EvidenceFailed,
        )
        v2_refusal_charge(
            context,
            "scalar_bytes",
            len(integer_text.encode("ascii")),
        )
        return value
    if type(value) is float:
        return {
            "kind": "float",
            "ieee754_binary64": struct.pack(">d", value).hex(),
        }
    if type(value) is complex:
        return {
            "kind": "complex",
            "real_ieee754_binary64": struct.pack(">d", value.real).hex(),
            "imag_ieee754_binary64": struct.pack(">d", value.imag).hex(),
        }
    if type(value) is str:
        v2_refusal_charge(
            context,
            "scalar_bytes",
            len(value.encode("utf-8")),
        )
        return value
    if type(value) is bytes:
        v2_refusal_charge(context, "scalar_bytes", len(value))
        return {
            "kind": "bytes",
            "byte_length": len(value),
            "content_root": "sha256-v1:" + hashlib.sha256(value).hexdigest(),
        }
    if value is Ellipsis or value is NotImplemented:
        return {"kind": "singleton", "value": repr(value)}
    for sentinel_name, sentinel in V2_DATACLASS_SENTINEL_IDENTITIES:
        if value is sentinel:
            return {
                "kind": f"dataclasses.{sentinel_name}",
                "type_state": v2_state_projection_value(
                    type(value),
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
            }
    if v2_exact_type_is_one_of(
        value,
        V2_DATACLASS_EXCLUSIVE_SENTINEL_TYPES,
    ):
        raise EvidenceFailed(
            "refusal-state dataclass sentinel impostor is not an accepted "
            "singleton identity"
        )
    for runtime_name, runtime_value in (
        V2_REFUSAL_TRUSTED_RUNTIME_VALUE_IDENTITIES
    ):
        if value is runtime_value:
            return {
                "kind": "trusted-runtime-value",
                "identity": runtime_name,
            }
    if v2_is_dangerous_builtin(value):
        raise EvidenceFailed(
            "refusal callback reaches a dynamic namespace builtin; provide "
            "an explicit bounded external-state projection"
        )
    v2_require_external_callable_authorized(
        value,
        context=context,
        label="an aliased external callable",
    )
    if seen is None:
        seen = {}
    identity = id(value)
    object_ids: dict[int, int] = context["object_ids"]
    active_ids: set[int] = context["active_ids"]
    if identity in object_ids:
        return {
            "kind": "reference",
            "node_id": object_ids[identity],
            "cycle": identity in active_ids,
        }
    v2_refusal_charge(context, "nodes")
    node_id = context["next_node_id"]
    context["next_node_id"] += 1
    object_ids[identity] = node_id
    context["object_references"][identity] = value
    active_ids.add(identity)
    seen[identity] = depth

    def finish(body: dict[str, Any]) -> dict[str, Any]:
        return {"node_id": node_id, **body}

    prior_active_executable_function = context[
        "active_executable_function"
    ]
    prior_authorized_capabilities = context[
        "authorized_external_capabilities"
    ]
    if type(value) is types.FunctionType:
        context["active_executable_function"] = value
        context["authorized_external_capabilities"] = frozenset(
            set(context["explicit_external_capabilities"]).union(
                v2_fixture_executable_internal_capabilities(value)
            )
        )
    try:
        if type(value) is slice:
            return finish({
                "kind": "slice",
                "start": v2_state_projection_value(
                    value.start,
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
                "stop": v2_state_projection_value(
                    value.stop,
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
                "step": v2_state_projection_value(
                    value.step,
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
            })
        if type(value) is types.CodeType:
            return finish({
                "kind": "code",
                "semantic": v2_code_semantic_projection(
                    value,
                    context=context,
                    depth=depth + 1,
                ),
            })
        if type(value) is types.GenericAlias:
            reduced = V2_GENERIC_ALIAS_REDUCE_DESCRIPTOR(value)
            if (
                type(reduced) is not tuple
                or len(reduced) != 2
                or reduced[0] is not types.GenericAlias
                or type(reduced[1]) is not tuple
                or len(reduced[1]) != 2
            ):
                raise EvidenceFailed(
                    "refusal-state generic alias payload is not exact"
                )
            return finish({
                "kind": "types.GenericAlias",
                "origin": v2_state_projection_value(
                    reduced[1][0],
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
                "arguments": v2_state_projection_value(
                    reduced[1][1],
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
            })
        if v2_raw_instance_of(value, types.ModuleType):
            return finish(
                v2_project_module_value(
                    value,
                    module_paths=module_paths,
                    bare_reference=bare_module_reference,
                    seen=seen,
                    context=context,
                    depth=depth,
                )
            )
        if type(value) is timezone:
            offset = timezone.utcoffset(value, None)
            if offset is None:
                raise EvidenceFailed(
                    "refusal-state exact timezone lacks an exact UTC offset"
                )
            return finish({
                "kind": "datetime.timezone",
                "offset": {
                    "days": offset.days,
                    "seconds": offset.seconds,
                    "microseconds": offset.microseconds,
                },
                "name": v2_state_projection_value(
                    timezone.tzname(value, None),
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
            })
        metadata = (
            {}
            if value is os.environ
            or value is os.environb
            or v2_exact_type_is_one_of(value, V2_REFUSAL_PATH_TYPES)
            or v2_exact_type_is_one_of(value, V2_REFUSAL_LOCK_TYPES)
            or type(value) is re.Pattern
            or v2_raw_instance_of(
                value,
                (
                    types.FunctionType,
                    types.ModuleType,
                    types.MethodType,
                    types.BuiltinFunctionType,
                    types.BuiltinMethodType,
                    types.ClassMethodDescriptorType,
                    types.MethodDescriptorType,
                    types.MethodWrapperType,
                    types.WrapperDescriptorType,
                    types.GetSetDescriptorType,
                    types.MemberDescriptorType,
                    staticmethod,
                    classmethod,
                    property,
                    V2_ENUM_PROPERTY_TYPE,
                    type,
                ),
            )
            else v2_state_object_metadata(
                value,
                seen=seen,
                context=context,
                depth=depth,
            )
        )
        value_type_mro = v2_raw_type_mro(type(value))
        if any(base is str for base in value_type_mro) and type(value) is not str:
            v2_require_audited_type_layout(
                value,
                audited_native_bases=(str,),
            )
            scalar_value = str.__str__(value)
            v2_refusal_charge(
                context,
                "scalar_bytes",
                len(scalar_value.encode("utf-8")),
            )
            return finish({
                "kind": "str-subclass",
                "value": scalar_value,
                "object_state": metadata,
                "type_state": v2_state_projection_value(
                    type(value),
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
            })
        if any(base is bytes for base in value_type_mro) and type(value) is not bytes:
            v2_require_audited_type_layout(
                value,
                audited_native_bases=(bytes,),
            )
            scalar_value = bytes.__getitem__(value, slice(None))
            v2_refusal_charge(
                context,
                "scalar_bytes",
                len(scalar_value),
            )
            return finish({
                "kind": "bytes-subclass",
                "byte_length": len(scalar_value),
                "content_root": (
                    "sha256-v1:" + hashlib.sha256(scalar_value).hexdigest()
                ),
                "object_state": metadata,
                "type_state": v2_state_projection_value(
                    type(value),
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
            })
        if (
            any(base is int for base in value_type_mro)
            and type(value) is not bool
            and type(value) is not int
        ):
            v2_require_audited_type_layout(
                value,
                audited_native_bases=(int,),
            )
            scalar_value = int.__int__(value)
            integer_text = v2_bounded_exact_integer_text(
                scalar_value,
                label="refusal-state integer subclass value",
                error_type=EvidenceFailed,
            )
            v2_refusal_charge(
                context,
                "scalar_bytes",
                len(integer_text.encode("ascii")),
            )
            return finish({
                "kind": "int-subclass",
                "value": scalar_value,
                "object_state": metadata,
                "type_state": v2_state_projection_value(
                    type(value),
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
            })
        if any(base is float for base in value_type_mro) and type(value) is not float:
            v2_require_audited_type_layout(
                value,
                audited_native_bases=(float,),
            )
            scalar_value = float.__float__(value)
            return finish({
                "kind": "float-subclass",
                "ieee754_binary64": struct.pack(">d", scalar_value).hex(),
                "object_state": metadata,
                "type_state": v2_state_projection_value(
                    type(value),
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
            })
        if any(base is complex for base in value_type_mro) and type(value) is not complex:
            v2_require_audited_type_layout(
                value,
                audited_native_bases=(complex,),
            )
            scalar_value = complex.__complex__(value)
            return finish({
                "kind": "complex-subclass",
                "real_ieee754_binary64": struct.pack(
                    ">d", scalar_value.real
                ).hex(),
                "imag_ieee754_binary64": struct.pack(
                    ">d", scalar_value.imag
                ).hex(),
                "object_state": metadata,
                "type_state": v2_state_projection_value(
                    type(value),
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
            })
        if type(value) is object and allow_class_sentinel_object:
            # Exact object instances have no inspectable payload. Their only
            # meaningful in-graph identity is still preserved by node and
            # reference topology. This exception is restricted to a class
            # attribute sentinel; arbitrary callback-owned object instances
            # remain opaque and fail closed below.
            return finish({
                "kind": "class-stateless-object-sentinel",
                "type": "builtins.object",
            })
        if value is v2_state_projection_value:
            # The redaction path legitimately calls back into this projector.
            # Bind the exact in-process function and its executable structure,
            # but do not recursively expand the projector's own globals. A
            # rebound or spoofed function does not satisfy this identity check
            # and therefore receives the normal graph-wide analysis.
            structural_state = v2_trusted_callable_projection_body(
                value,
                seen=seen,
                context=context,
                depth=depth + 1,
            )
            return finish({
                **structural_state,
                "kind": "refusal-projector-internal-callable",
            })
        if type(value) is V2_REFUSAL_LOCK_TYPE:
            return finish({
                "kind": "thread-lock",
                "locked": V2_REFUSAL_LOCK_TYPE.locked(value),
            })
        if type(value) is V2_REFUSAL_RLOCK_TYPE:
            return finish({
                "kind": "thread-rlock",
                **v2_rlock_observation(value),
            })
        if v2_exact_type_is_one_of(value, (
            V2_OPERATOR_ATTRGETTER_TYPE,
            V2_OPERATOR_ITEMGETTER_TYPE,
        )):
            return finish(
                v2_trusted_callable_projection_body(
                    value,
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                )
            )
        if v2_exact_type_is_one_of(value, (staticmethod, classmethod)):
            wrapped_function = v2_unwrap_function_wrapper(value)
            wrapped_projection = (
                v2_trusted_callable_projection(
                    wrapped_function,
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                )
                if type(wrapped_function) is types.FunctionType
                else v2_state_projection_value(
                    wrapped_function,
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                )
            )
            return finish({
                "kind": (
                    "staticmethod-descriptor"
                    if type(value) is staticmethod
                    else "classmethod-descriptor"
                ),
                "function": wrapped_projection,
                "object_state": metadata,
            })
        if type(value) is property:
            accessor_states: dict[str, Any] = {}
            for accessor, descriptor in V2_PROPERTY_ACCESSOR_DESCRIPTORS.items():
                function = v2_exact_descriptor_read(
                    descriptor,
                    value,
                    property,
                    label=f"property {accessor}",
                )
                accessor_states[accessor] = (
                    v2_trusted_callable_projection(
                        function,
                        seen=seen,
                        context=context,
                        depth=depth + 1,
                    )
                    if type(function) is types.FunctionType
                    else v2_state_projection_value(
                        function,
                        seen=seen,
                        context=context,
                        depth=depth + 1,
                    )
                    if function is not None
                    else None
                )
            return finish({
                "kind": "property-descriptor",
                "accessors": accessor_states,
                "name": (
                    {
                        "kind": "runtime-unsupported",
                    }
                    if V2_PROPERTY_NAME_DESCRIPTOR is None
                    else v2_state_projection_value(
                        v2_exact_descriptor_read(
                            V2_PROPERTY_NAME_DESCRIPTOR,
                            value,
                            property,
                            label="property name",
                        ),
                        seen=seen,
                        context=context,
                        depth=depth + 1,
                    )
                ),
                "doc": v2_state_projection_value(
                    v2_exact_descriptor_read(
                        V2_PROPERTY_DOC_DESCRIPTOR,
                        value,
                        property,
                        label="property doc",
                    ),
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
                "object_state": metadata,
            })
        if type(value) is V2_ENUM_PROPERTY_TYPE:
            raw_attributes = v2_raw_instance_dictionary(value)
            if type(raw_attributes) is not dict:
                raise EvidenceFailed(
                    "refusal-state enum property dictionary is not exact"
                )
            attribute_rows: list[dict[str, Any]] = []
            for name, attribute in sorted(
                dict.items(raw_attributes),
                key=lambda row: row[0].encode("utf-8"),
            ):
                if type(name) is not str:
                    raise EvidenceFailed(
                        "refusal-state enum property has a non-string attribute"
                    )
                attribute_rows.append({
                    "name": name,
                    "state": (
                        v2_trusted_callable_projection(
                            attribute,
                            seen=seen,
                            context=context,
                            depth=depth + 1,
                        )
                        if type(attribute) is types.FunctionType
                        else v2_state_projection_value(
                            attribute,
                            seen=seen,
                            context=context,
                            depth=depth + 1,
                        )
                    ),
                })
            v2_refusal_charge(context, "items", len(attribute_rows))
            return finish({
                "kind": "enum-property-descriptor",
                "attributes": attribute_rows,
                "type_state": v2_state_projection_value(
                    type(value),
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
            })
        if v2_raw_instance_of(value, memoryview):
            try:
                payload = value.tobytes()
            except ValueError:
                return finish({
                    "kind": "memoryview",
                    "released": True,
                    "object_state": metadata,
                })
            v2_refusal_charge(context, "scalar_bytes", len(payload))
            return finish({
                "kind": "memoryview",
                "released": False,
                "byte_length": len(payload),
                "content_root": (
                    "sha256-v1:" + hashlib.sha256(payload).hexdigest()
                ),
                "format": value.format,
                "itemsize": value.itemsize,
                "ndim": value.ndim,
                "shape": list(value.shape) if value.shape is not None else None,
                "strides": (
                    list(value.strides) if value.strides is not None else None
                ),
                "readonly": value.readonly,
                "object_state": metadata,
            })
        if v2_raw_instance_of(value, bytearray):
            v2_require_audited_type_layout(
                value,
                audited_native_bases=(bytearray,),
            )
            payload = bytes(bytearray.__iter__(value))
            v2_refusal_charge(context, "scalar_bytes", len(payload))
            return finish({
                "kind": "bytearray",
                "byte_length": len(payload),
                "content_root": (
                    "sha256-v1:" + hashlib.sha256(payload).hexdigest()
                ),
                "object_state": metadata,
                "type_state": v2_state_projection_value(
                    type(value),
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
            })
        if v2_exact_type_is_one_of(value, V2_REFUSAL_PATH_TYPES):
            return finish({
                "kind": "path",
                "raw_object_state": v2_state_object_metadata(
                    value,
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
                "type_state": v2_state_projection_value(
                    type(value),
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
            })
        if type(value) is re.Pattern:
            return finish({
                "kind": "regular-expression",
                "pattern": v2_state_projection_value(
                    value.pattern,
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
                "flags": v2_state_projection_value(
                    value.flags,
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
                "groups": v2_state_projection_value(
                    value.groups,
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
                "groupindex": v2_state_projection_value(
                    dict(value.groupindex),
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
            })
        if value is os.environ or value is os.environb:
            environment_state = v2_raw_instance_dictionary(value)
            if type(environment_state) is not dict:
                raise EvidenceFailed(
                    "refusal-state process environment dictionary is not exact"
                )
            raw_data = environment_state.get("_data")
            if type(raw_data) is not dict:
                raise EvidenceFailed(
                    "refusal-state process environment backing data is not exact"
                )
            codec_rows: list[dict[str, Any]] = []
            for codec_name in (
                "encodekey",
                "decodekey",
                "encodevalue",
                "decodevalue",
            ):
                codec = environment_state.get(codec_name)
                if type(codec) is types.FunctionType:
                    codec_state = v2_trusted_callable_projection(
                        codec,
                        seen=seen,
                        context=context,
                        depth=depth + 1,
                    )
                elif codec is bytes:
                    codec_state = v2_state_projection_value(
                        codec,
                        seen=seen,
                        context=context,
                        depth=depth + 1,
                    )
                else:
                    raise EvidenceFailed(
                        "refusal-state process environment codec is not an "
                        "audited exact function or bytes identity"
                    )
                codec_rows.append({
                    "name": codec_name,
                    "state": codec_state,
                })
            return finish({
                "kind": "process-environment",
                "type": v2_type_identity(type(value)),
                "type_state": v2_state_projection_value(
                    type(value),
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
                "raw_data": v2_state_projection_value(
                    raw_data,
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
                "codecs": codec_rows,
            })
        value_type_mro = v2_raw_type_mro(type(value))
        if (
            any(base is collections_abc.Mapping for base in value_type_mro)
            and not any(base is dict for base in value_type_mro)
        ):
            raise EvidenceFailed(
                "refusal-state arbitrary Mapping inspection is forbidden; "
                "provide an explicit bounded projection"
            )
        if v2_raw_instance_of(value, OrderedDict):
            v2_require_audited_type_layout(
                value,
                audited_native_bases=(dict, OrderedDict),
            )
            raw_entries = list(OrderedDict.items(value))
            v2_refusal_charge(context, "items", 2 * len(raw_entries))
            return finish({
                "kind": "ordered-dictionary",
                "entries_in_logical_order": [
                    {
                        "key": v2_state_projection_value(
                            key,
                            seen=seen,
                            context=context,
                            depth=depth + 1,
                        ),
                        "value": v2_state_projection_value(
                            item,
                            seen=seen,
                            context=context,
                            depth=depth + 1,
                        ),
                    }
                    for key, item in raw_entries
                ],
                "object_state": metadata,
                "type_state": v2_state_projection_value(
                    type(value),
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
            })
        if v2_raw_instance_of(value, dict):
            audited_dictionary_bases = (
                (dict, defaultdict)
                if any(base is defaultdict for base in value_type_mro)
                else (dict,)
            )
            v2_require_audited_type_layout(
                value,
                audited_native_bases=audited_dictionary_bases,
            )
            raw_entries = list(dict.items(value))
            v2_refusal_charge(context, "items", 2 * len(raw_entries))
            entries = []
            for key, item in raw_entries:
                entries.append({
                    "key": v2_state_projection_value(
                        key,
                        seen=seen,
                        context=context,
                        depth=depth + 1,
                    ),
                    "value": v2_state_projection_value(
                        item,
                        seen=seen,
                        context=context,
                        depth=depth + 1,
                    ),
                })
            projection = {
                "kind": "dictionary",
                "type": v2_type_identity(type(value)),
                "entries_in_iteration_order": entries,
                "object_state": metadata,
                "type_state": v2_state_projection_value(
                    type(value),
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
            }
            if v2_raw_instance_of(value, defaultdict):
                projection["default_factory"] = v2_state_projection_value(
                    v2_exact_descriptor_read(
                        V2_DEFAULTDICT_FACTORY_DESCRIPTOR,
                        value,
                        defaultdict,
                        label="defaultdict default_factory",
                    ),
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                )
            return finish(projection)
        if v2_raw_instance_of(value, list):
            v2_require_audited_type_layout(
                value,
                audited_native_bases=(list,),
            )
            sequence_items = list(list.__iter__(value))
            sequence_kind = "list"
        elif v2_raw_instance_of(value, tuple):
            v2_require_audited_type_layout(
                value,
                audited_native_bases=(tuple,),
            )
            sequence_items = list(tuple.__iter__(value))
            sequence_kind = "tuple"
        elif v2_raw_instance_of(value, deque):
            v2_require_audited_type_layout(
                value,
                audited_native_bases=(deque,),
            )
            sequence_items = list(deque.__iter__(value))
            sequence_kind = "deque"
        else:
            sequence_items = None
            sequence_kind = ""
        if sequence_items is not None:
            v2_refusal_charge(context, "items", len(sequence_items))
            projection = {
                "kind": sequence_kind,
                "type": v2_type_identity(type(value)),
                "items": [
                    v2_state_projection_value(
                        item,
                        seen=seen,
                        context=context,
                        depth=depth + 1,
                    )
                    for item in sequence_items
                ],
                "object_state": metadata,
                "type_state": v2_state_projection_value(
                    type(value),
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
            }
            if v2_raw_instance_of(value, deque):
                projection["maxlen"] = v2_exact_descriptor_read(
                    V2_DEQUE_MAXLEN_DESCRIPTOR,
                    value,
                    deque,
                    label="deque maxlen",
                )
            return finish(projection)
        if v2_raw_instance_of(value, (set, frozenset)):
            audited_set_base = (
                set
                if any(base is set for base in value_type_mro)
                else frozenset
            )
            v2_require_audited_type_layout(
                value,
                audited_native_bases=(audited_set_base,),
            )
            raw_items = (
                list(set.__iter__(value))
                if v2_raw_instance_of(value, set)
                else list(frozenset.__iter__(value))
            )
            v2_refusal_charge(context, "items", len(raw_items))
            items: list[Any] = []
            for item in raw_items:
                projected_item = v2_state_projection_value(
                    item,
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                )
                if isinstance(projected_item, dict) and "node_id" in projected_item:
                    raise EvidenceFailed(
                        "refusal-state sets may contain only graph-free scalar "
                        "values"
                    )
                items.append(projected_item)
            items.sort(key=canonical_bytes)
            return finish({
                "kind": (
                    "set" if v2_raw_instance_of(value, set) else "frozenset"
                ),
                "items": items,
                "object_state": metadata,
                "type_state": v2_state_projection_value(
                    type(value),
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
            })
        if v2_raw_instance_of(value, argparse.Namespace):
            v2_require_audited_type_layout(value)
            return finish({
                "kind": "argparse.Namespace",
                "object_state": metadata,
                "type_state": v2_state_projection_value(
                    type(value),
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
            })
        if type(value) is types.MethodType:
            return finish({
                "kind": "bound-python-method",
                "function": v2_state_projection_value(
                    v2_exact_descriptor_read(
                        V2_METHOD_ATTRIBUTE_DESCRIPTORS["__func__"],
                        value,
                        types.MethodType,
                        label="bound method function",
                    ),
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
                "bound_self": v2_state_projection_value(
                    v2_exact_descriptor_read(
                        V2_METHOD_ATTRIBUTE_DESCRIPTORS["__self__"],
                        value,
                        types.MethodType,
                        label="bound method self",
                    ),
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
            })
        if v2_exact_type_is_one_of(value, (
            types.BuiltinFunctionType,
            types.BuiltinMethodType,
            V2_REGEX_BOUND_METHOD_TYPE,
            types.ClassMethodDescriptorType,
            types.MethodDescriptorType,
            types.MethodWrapperType,
            types.WrapperDescriptorType,
        )):
            if v2_is_dangerous_builtin(value):
                raise EvidenceFailed(
                    "refusal callback reaches a dynamic namespace builtin; "
                    "provide an explicit bounded external-state projection"
                )
            bound_self = v2_optional_raw_builtin_descriptor_attribute(
                value,
                "__self__",
            )
            if v2_raw_instance_of(bound_self, types.ModuleType):
                bound_projection: Any = {
                    "kind": "trusted-bound-module"
                    if v2_is_trusted_module(bound_self)
                    else "custom-bound-module",
                    "module": v2_raw_module_name(bound_self),
                }
            elif v2_raw_is_type_object(bound_self):
                bound_projection = v2_state_projection_value(
                    bound_self,
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                )
            else:
                bound_projection = v2_state_projection_value(
                    bound_self,
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                )
            callable_state = v2_trusted_callable_projection_body(
                value,
                seen=seen,
                context=context,
                depth=depth + 1,
            )
            return finish({
                **callable_state,
                "kind": "builtin-callable",
                "bound_self": bound_projection,
            })
        if v2_exact_type_is_one_of(value, (
            types.GetSetDescriptorType,
            types.MemberDescriptorType,
        )):
            descriptor_name = v2_raw_builtin_descriptor_attribute(
                value,
                "__name__",
            )
            descriptor_owner = v2_raw_builtin_descriptor_attribute(
                value,
                "__objclass__",
            )
            if (
                type(descriptor_name) is not str
                or not v2_raw_is_type_object(descriptor_owner)
            ):
                raise EvidenceFailed(
                    "refusal-state built-in descriptor metadata is not exact"
                )
            return finish({
                "kind": "builtin-descriptor",
                "type": v2_type_identity(type(value)),
                "name": descriptor_name,
                "owner": v2_state_projection_value(
                    descriptor_owner,
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
            })
        if type(value) is types.FunctionType:
            function_code = v2_raw_function_attribute(value, "__code__")
            function_closure = (
                v2_raw_function_attribute(value, "__closure__") or ()
            )
            if (
                type(function_code) is not types.CodeType
                or type(function_closure) is not tuple
            ):
                raise EvidenceFailed(
                    "refusal-state function executable metadata is not exact"
                )
            function_freevars = function_code.co_freevars
            if len(function_closure) != len(function_freevars):
                raise EvidenceFailed(
                    "refusal-state function closure metadata differs"
                )
            function_code_projection = v2_code_semantic_projection(
                function_code,
                context=context,
            )
            analysis = v2_code_access_analysis(
                function_code,
                context=context,
                constants_prevalidated=True,
            )
            closure_rows: list[dict[str, Any]] = []
            for name, cell in zip(
                function_freevars,
                function_closure,
                strict=True,
            ):
                try:
                    cell_value = cell.cell_contents
                except ValueError:
                    closure_state = {"kind": "empty-cell"}
                    closure_executable_access = {
                        "kind": "empty-cell-no-executable-access",
                    }
                else:
                    paths = analysis["freevar_paths"].get(name)
                    closure_state = (
                        v2_trusted_callable_projection(
                            cell_value,
                            seen=seen,
                            context=context,
                            depth=depth + 1,
                        )
                        if type(cell_value) is types.FunctionType
                        else v2_state_projection_value(
                            cell_value,
                            seen=seen,
                            context=context,
                            module_paths=paths,
                            bare_module_reference=(
                                name in analysis["bare_freevar_names"]
                            ),
                            depth=depth + 1,
                        )
                    )
                    closure_executable_access = (
                        v2_executable_access_projection(
                            cell_value,
                            binding_name=name,
                            paths=paths,
                            bare_reference=(
                                name in analysis["bare_freevar_names"]
                            ),
                            called=(
                                name in analysis["called_freevar_names"]
                            ),
                            called_paths=analysis[
                                "called_freevar_paths"
                            ].get(name),
                            call_result_paths=analysis[
                                "freevar_call_result_paths"
                            ].get(name),
                            path_call_result_paths=analysis[
                                "freevar_path_call_result_paths"
                            ].get(name),
                            seen=seen,
                            context=context,
                            depth=depth + 1,
                            protocol_used=(
                                name in analysis["protocol_freevar_names"]
                            ),
                            mapping_keys_used=(
                                name in analysis[
                                    "mapping_key_protocol_freevar_names"
                                ]
                            ),
                            contains_used=(
                                name in analysis[
                                    "contains_protocol_freevar_names"
                                ]
                            ),
                            operation_protocol_paths=analysis[
                                "operation_protocol_freevar_paths"
                            ].get(name),
                        )
                    )
                closure_rows.append({
                    "name": name,
                    "state": closure_state,
                    "executable_access": closure_executable_access,
                })
            default_bindings = v2_function_default_bindings(
                value,
                function_code,
            )
            parameter_rows: list[dict[str, Any]] = []
            for name in function_code.co_varnames[
                : function_code.co_argcount + function_code.co_kwonlyargcount
            ]:
                if name not in default_bindings:
                    continue
                parameter_value = default_bindings[name]
                paths = analysis["parameter_paths"].get(name)
                parameter_rows.append({
                    "name": name,
                    "state": v2_state_projection_value(
                        parameter_value,
                        seen=seen,
                        context=context,
                        module_paths=paths,
                        bare_module_reference=(
                            name in analysis["bare_parameter_names"]
                        ),
                        depth=depth + 1,
                    ),
                    "executable_access": v2_executable_access_projection(
                        parameter_value,
                        binding_name=name,
                        paths=paths,
                        bare_reference=(
                            name in analysis["bare_parameter_names"]
                        ),
                        called=(
                            name in analysis["called_parameter_names"]
                        ),
                        called_paths=analysis[
                            "called_parameter_paths"
                        ].get(name),
                        call_result_paths=analysis[
                            "parameter_call_result_paths"
                        ].get(name),
                        path_call_result_paths=analysis[
                            "parameter_path_call_result_paths"
                        ].get(name),
                        seen=seen,
                        context=context,
                        depth=depth + 1,
                        protocol_used=(
                            name in analysis["protocol_parameter_names"]
                        ),
                        mapping_keys_used=(
                            name in analysis[
                                "mapping_key_protocol_parameter_names"
                            ]
                        ),
                        contains_used=(
                            name in analysis[
                                "contains_protocol_parameter_names"
                            ]
                        ),
                        operation_protocol_paths=analysis[
                            "operation_protocol_parameter_paths"
                        ].get(name),
                    ),
                })
            accesses = analysis["accesses"]
            function_globals = v2_raw_function_attribute(value, "__globals__")
            function_builtins = v2_raw_function_attribute(
                value,
                "__builtins__",
            )
            if type(function_globals) is not dict:
                raise EvidenceFailed(
                    "refusal-state function globals mapping is not exact"
                )
            if v2_raw_instance_of(function_builtins, types.ModuleType):
                builtin_values = v2_raw_module_dict(function_builtins)
            elif type(function_builtins) is dict:
                builtin_values = function_builtins
            else:
                raise EvidenceFailed(
                    "refusal-state function builtins mapping is not exact"
                )
            global_rows: dict[str, dict[str, Any]] = {}
            for name, operations in accesses.items():
                global_present = name in function_globals
                builtin_present = not global_present and name in builtin_values
                row: dict[str, Any] = {
                    "operations": list(operations),
                    "source": (
                        "global"
                        if global_present
                        else "builtin"
                        if builtin_present
                        else "missing"
                    ),
                }
                if global_present or builtin_present:
                    global_value = (
                        function_globals[name]
                        if global_present
                        else builtin_values[name]
                    )
                    if v2_is_dangerous_builtin(global_value):
                        raise EvidenceFailed(
                            "refusal callback reaches a dynamic namespace "
                            "builtin; provide an explicit bounded external-state "
                            "projection"
                        )
                    required_type_capabilities = (
                        v2_external_binding_path_capabilities(
                            global_value,
                            analysis["module_paths"].get(name),
                        )
                    )
                    if required_type_capabilities.isdisjoint(
                        context["authorized_external_capabilities"]
                    ) and required_type_capabilities:
                        raise EvidenceFailed(
                            "refusal callback reaches external runtime state "
                            f"through {name}; provide an explicit bounded "
                            "projection for one of "
                            f"{sorted(required_type_capabilities)}"
                        )
                    try:
                        if type(global_value) is types.FunctionType:
                            row["state"] = v2_trusted_callable_projection(
                                global_value,
                                seen=seen,
                                context=context,
                                depth=depth + 1,
                            )
                        elif v2_raw_instance_of(global_value, types.ModuleType):
                            row["state"] = v2_state_projection_value(
                                global_value,
                                seen=seen,
                                context=context,
                                module_paths=analysis["module_paths"].get(name),
                                bare_module_reference=(
                                    name in analysis["bare_global_names"]
                                ),
                                depth=depth + 1,
                            )
                        else:
                            row["state"] = v2_state_projection_value(
                                global_value,
                                seen=seen,
                                context=context,
                                module_paths=analysis["module_paths"].get(
                                    name
                                ),
                                bare_module_reference=(
                                    name in analysis["bare_global_names"]
                                ),
                                depth=depth + 1,
                            )
                        row["executable_access"] = (
                            v2_executable_access_projection(
                                global_value,
                                binding_name=name,
                                paths=analysis["module_paths"].get(name),
                                bare_reference=(
                                    name in analysis["bare_global_names"]
                                ),
                                called=(
                                    name in analysis["called_global_names"]
                                ),
                                called_paths=analysis[
                                    "called_global_paths"
                                ].get(name),
                                call_result_paths=analysis[
                                    "call_result_paths"
                                ].get(name),
                                path_call_result_paths=analysis[
                                    "global_path_call_result_paths"
                                ].get(name),
                                seen=seen,
                                context=context,
                                depth=depth + 1,
                                protocol_used=(
                                    name in analysis["protocol_global_names"]
                                ),
                                mapping_keys_used=(
                                    name in analysis[
                                        "mapping_key_protocol_global_names"
                                    ]
                                ),
                                contains_used=(
                                    name in analysis[
                                        "contains_protocol_global_names"
                                    ]
                                ),
                                operation_protocol_paths=analysis[
                                    "operation_protocol_global_paths"
                                ].get(name),
                            )
                        )
                    except HarnessError as error:
                        raise EvidenceFailed(
                            "refusal-state function global "
                            f"{function_code.co_qualname}.{name} is not bounded: "
                            f"{v2_bounded_diagnostic_summary(error)}"
                        ) from error
                global_rows[name] = row
            function_attributes = v2_raw_function_attribute(value, "__dict__")
            if type(function_attributes) is not dict:
                raise EvidenceFailed(
                    "refusal-state function attribute dictionary is not exact"
                )
            function_name = v2_raw_function_attribute(value, "__name__")
            function_qualname = v2_raw_function_attribute(
                value,
                "__qualname__",
            )
            if type(function_name) is not str or type(function_qualname) is not str:
                raise EvidenceFailed("refusal-state function names are not exact")
            projection = finish({
                "kind": "function",
                "module": v2_state_projection_value(
                    v2_raw_function_attribute(value, "__module__"),
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
                "name": function_name,
                "qualname": function_qualname,
                "doc": v2_state_projection_value(
                    v2_raw_function_attribute(value, "__doc__"),
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
                "code": function_code_projection,
                "defaults": v2_state_projection_value(
                    v2_raw_function_attribute(value, "__defaults__"),
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
                "keyword_defaults": v2_state_projection_value(
                    v2_raw_function_attribute(value, "__kwdefaults__"),
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
                "annotations": v2_function_annotation_projection(
                    value,
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
                "type_params": v2_function_type_params_projection(
                    value,
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
                "closure": closure_rows,
                "referenced_default_parameters": parameter_rows,
                "attributes": v2_state_projection_value(
                    function_attributes,
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
                "referenced_globals": global_rows,
            })
            return projection
        if v2_raw_is_type_object(value):
            for trusted_name, trusted_type in (
                V2_REFUSAL_TRUSTED_TYPE_IDENTITIES
            ):
                if value is trusted_type:
                    return finish({
                        "kind": "trusted-runtime-type",
                        "identity": trusted_name,
                    })
            if any(
                value is trusted_type
                for trusted_type in V2_REFUSAL_TRUSTED_BUILTIN_TYPES
            ):
                return finish({
                    "kind": "trusted-builtin-type",
                    "type": v2_type_identity(value),
                })
            class_dictionary = v2_raw_type_dictionary(value)
            excluded_attributes = {
                "_abc_impl",
                "__base__",
                "__bases__",
                "__dict__",
                "__doc__",
                "__mro__",
                "__module__",
                "__qualname__",
                "__subclasses__",
                "__weakref__",
            }
            class_attribute_rows: list[dict[str, Any]] = []
            pinned_class_attributes = next(
                (
                    attributes
                    for candidate, attributes in (
                        V2_REFUSAL_PINNED_CLASS_ATTRIBUTES.items()
                    )
                    if value is candidate
                ),
                None,
            )
            raw_class_items = list(class_dictionary.items())
            if any(type(name) is not str for name, _ in raw_class_items):
                raise EvidenceFailed(
                    "refusal-state class has a non-string attribute"
                )
            for name, attribute in sorted(
                raw_class_items,
                key=lambda row: row[0].encode("utf-8"),
            ):
                if name in excluded_attributes:
                    continue
                attribute_is_pinned = (
                    pinned_class_attributes is not None
                    and pinned_class_attributes.get(
                        name,
                        V2_REFUSAL_PINNED_CLASS_ATTRIBUTE_MISSING,
                    )
                    is attribute
                )
                if (
                    attribute_is_pinned
                    and type(attribute) is V2_OPERATOR_METHODCALLER_TYPE
                ):
                    attribute_state = {
                        "kind": "pinned-immutable-stdlib-methodcaller",
                    }
                elif v2_exact_type_is_one_of(
                    attribute,
                    (staticmethod, classmethod),
                ):
                    wrapped_attribute = v2_unwrap_function_wrapper(
                        attribute
                    )
                    if v2_external_callable_capabilities(wrapped_attribute):
                        attribute_state = (
                            v2_structural_external_wrapper_projection(
                                attribute,
                                seen=seen,
                                context=context,
                                depth=depth + 1,
                            )
                        )
                    else:
                        attribute_state = v2_state_projection_value(
                            attribute,
                            seen=seen,
                            context=context,
                            depth=depth + 1,
                        )
                elif type(attribute) is property:
                    attribute_state = v2_state_projection_value(
                        attribute,
                        seen=seen,
                        context=context,
                        depth=depth + 1,
                    )
                elif v2_raw_instance_of(attribute, types.ModuleType) and v2_is_trusted_module(
                    attribute
                ):
                    attribute_state = {
                        "kind": "trusted-module-binding",
                        "module": v2_raw_module_name(attribute),
                    }
                elif v2_external_callable_capabilities(attribute):
                    attribute_state = (
                        v2_structural_external_callable_projection(
                            attribute,
                            seen=seen,
                            context=context,
                            depth=depth + 1,
                        )
                    )
                elif type(attribute) is types.FunctionType:
                    attribute_state = v2_trusted_callable_projection(
                        attribute,
                        seen=seen,
                        context=context,
                        depth=depth + 1,
                    )
                else:
                    try:
                        attribute_state = v2_state_projection_value(
                            attribute,
                            seen=seen,
                            context=context,
                            allow_class_sentinel_object=(
                                type(attribute) is object
                            ),
                            depth=depth + 1,
                        )
                    except HarnessError as error:
                        raise EvidenceFailed(
                            "refusal-state class attribute "
                            f"{v2_type_identity(value)}.{name} is not bounded: "
                            f"{v2_bounded_diagnostic_summary(error)}"
                        ) from error
                attribute_row = {
                    "name": name,
                    "state": attribute_state,
                }
                capture_attribute_executable_closure = (
                    not attribute_is_pinned
                )
                if capture_attribute_executable_closure:
                    try:
                        executable_closure = (
                            v2_class_attribute_executable_projection(
                                attribute,
                                seen=seen,
                                context=context,
                                depth=depth + 1,
                            )
                        )
                    except HarnessError as error:
                        raise EvidenceFailed(
                            "refusal-state class executable closure "
                            f"{v2_type_identity(value)}.{name} is not "
                            "bounded: "
                            f"{v2_bounded_diagnostic_summary(error)}"
                        ) from error
                    if executable_closure is not None:
                        attribute_row["executable_closure"] = (
                            executable_closure
                        )
                class_attribute_rows.append(attribute_row)
            v2_refusal_charge(context, "items", len(class_attribute_rows))
            bases = v2_raw_type_attribute(value, "__bases__")
            if type(bases) is not tuple:
                raise EvidenceFailed("refusal-state type bases are not exact")
            return finish({
                "kind": "type",
                "type": v2_type_identity(value),
                "metaclass": v2_state_projection_value(
                    type(value),
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
                "bases": [
                    v2_state_projection_value(
                        base,
                        seen=seen,
                        context=context,
                        depth=depth + 1,
                    )
                    for base in tuple.__iter__(bases)
                ],
                "doc": v2_state_projection_value(
                    v2_raw_type_attribute(value, "__doc__"),
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                ),
                "attributes": class_attribute_rows,
            })
        if not v2_type_layout_is_audited(type(value)):
            raise EvidenceFailed(
                "refusal-state object reaches unaudited extension-backed "
                "instance state"
            )
        value_is_callable = any(
            "__call__" in v2_raw_type_dictionary(base)
            for base in value_type_mro
        )
        type_state = v2_state_projection_value(
            type(value),
            seen=seen,
            context=context,
            module_paths=(
                (("__call__",),)
                if value_is_callable
                else None
            ),
            bare_module_reference=not value_is_callable,
            depth=depth + 1,
        )
        call_state: Any = None
        call_access_state: Any = None
        if value_is_callable:
            call_descriptor: Any = None
            for owner in v2_raw_type_mro(type(value)):
                owner_dictionary = v2_raw_type_dictionary(owner)
                if "__call__" in owner_dictionary:
                    call_descriptor = owner_dictionary["__call__"]
                    break
            if call_descriptor is None:
                raise EvidenceFailed(
                    "refusal-state callable implementation is not statically "
                    "inspectable"
                )
            if v2_exact_type_is_one_of(
                call_descriptor,
                (staticmethod, classmethod),
            ):
                wrapped_call = v2_unwrap_function_wrapper(call_descriptor)
                call_state = v2_state_projection_value(
                    call_descriptor,
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                )
                call_access_state = (
                    v2_executable_function_overlay(
                        wrapped_call,
                        seen=seen,
                        context=context,
                        depth=depth + 1,
                    )
                    if type(wrapped_call) is types.FunctionType
                    else {"kind": "no-python-function-overlay"}
                )
            elif type(call_descriptor) is types.FunctionType:
                call_state = v2_trusted_callable_projection(
                    call_descriptor,
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                )
                call_access_state = v2_executable_function_overlay(
                    call_descriptor,
                    seen=seen,
                    context=context,
                    depth=depth + 1,
                )
            elif v2_exact_type_is_one_of(call_descriptor, (
                types.BuiltinFunctionType,
                types.MethodDescriptorType,
                types.WrapperDescriptorType,
            )):
                raise EvidenceFailed(
                    "refusal-state callable object uses an unaudited "
                    "built-in call implementation"
                )
            else:
                raise EvidenceFailed(
                    "refusal-state callable implementation is opaque"
                )
        if metadata or call_state is not None:
            return finish({
                "kind": "object",
                "type": v2_type_identity(type(value)),
                "type_state": type_state,
                "object_state": metadata,
                "call_implementation": call_state,
                "call_executable_access": call_access_state,
            })
        return finish({
            "kind": "opaque",
            "type": v2_type_identity(type(value)),
            "type_state": type_state,
        })
    finally:
        context[
            "active_executable_function"
        ] = prior_active_executable_function
        context[
            "authorized_external_capabilities"
        ] = prior_authorized_capabilities
        active_ids.discard(identity)
        seen.pop(identity, None)


def v2_projection_contains_opaque(value: Any) -> bool:
    if isinstance(value, Mapping):
        return value.get("kind") == "opaque" or any(
            v2_projection_contains_opaque(item) for item in value.values()
        )
    if isinstance(value, (list, tuple)):
        return any(v2_projection_contains_opaque(item) for item in value)
    return False


def v2_projection_opaque_paths(
    value: Any,
    *,
    path: str = "$",
    limit: int = 8,
) -> list[str]:
    if limit <= 0:
        return []
    if isinstance(value, Mapping):
        if value.get("kind") == "opaque":
            return [f"{path}:{value.get('type', 'unknown')}"]
        paths: list[str] = []
        for key, item in value.items():
            paths.extend(
                v2_projection_opaque_paths(
                    item,
                    path=f"{path}.{key}",
                    limit=limit - len(paths),
                )
            )
            if len(paths) >= limit:
                break
        return paths
    if isinstance(value, (list, tuple)):
        paths = []
        for index, item in enumerate(value):
            paths.extend(
                v2_projection_opaque_paths(
                    item,
                    path=f"{path}[{index}]",
                    limit=limit - len(paths),
                )
            )
            if len(paths) >= limit:
                break
        return paths
    return []


def v2_validate_refusal_projection_graph(value: Any) -> dict[str, int]:
    definitions: dict[int, str] = {}
    references: list[tuple[int, str]] = []

    def visit(item: Any, path: str) -> None:
        if type(item) is dict:
            node_id = item.get("node_id")
            if node_id is not None:
                if type(node_id) is not int or node_id < 0:
                    raise EvidenceFailed(
                        "refusal-state graph contains an invalid node identifier"
                    )
                if item.get("kind") == "reference":
                    references.append((node_id, path))
                elif node_id in definitions:
                    raise EvidenceFailed(
                        "refusal-state graph contains duplicate node definitions"
                    )
                else:
                    definitions[node_id] = path
            for key, child in dict.items(item):
                visit(child, f"{path}.{key}")
        elif type(item) is list:
            for index, child in enumerate(list.__iter__(item)):
                visit(child, f"{path}[{index}]")

    visit(value, "$")
    dangling = [
        (node_id, path)
        for node_id, path in references
        if node_id not in definitions
    ]
    if dangling:
        sample = ", ".join(
            f"{node_id}@{path}" for node_id, path in dangling[:8]
        )
        raise EvidenceFailed(
            "refusal-state graph contains dangling references: " + sample
        )
    expected_node_ids = set(range(len(definitions)))
    if set(definitions) != expected_node_ids:
        missing = sorted(expected_node_ids.difference(definitions))[:8]
        unexpected = sorted(set(definitions).difference(expected_node_ids))[:8]
        raise EvidenceFailed(
            "refusal-state graph contains discarded or noncontiguous node "
            f"definitions; missing={missing}, unexpected={unexpected}, "
            f"definition_count={len(definitions)}"
        )
    return {
        "definitions": len(definitions),
        "references": len(references),
        "dangling": 0,
    }


def v2_explicit_projection_external_capabilities(
    projection: Callable[[], Any],
) -> frozenset[str]:
    capabilities: set[str] = set()
    visited: set[int] = set()
    visited_references: dict[int, Any] = {}
    analysis_context = v2_new_refusal_projection_context()

    def visit(value: Any, depth: int) -> None:
        if depth > V2_REFUSAL_STATE_DEPTH_CAP:
            raise EvidenceFailed(
                "explicit projection capability traversal exceeds its depth cap"
            )
        identity = id(value)
        if identity in visited:
            return
        visited.add(identity)
        visited_references[identity] = value
        direct_capabilities = v2_external_callable_capabilities(value)
        capabilities.update(direct_capabilities)
        if direct_capabilities:
            return
        bound_self: Any = None
        if type(value) is types.MethodType:
            bound_self = v2_exact_descriptor_read(
                V2_METHOD_ATTRIBUTE_DESCRIPTORS["__self__"],
                value,
                types.MethodType,
                label="explicit projection method receiver",
            )
            value = v2_exact_descriptor_read(
                V2_METHOD_ATTRIBUTE_DESCRIPTORS["__func__"],
                value,
                types.MethodType,
                label="explicit projection method function",
            )
        if type(value) is not types.FunctionType:
            try:
                call_target = v2_raw_attribute_without_user_code(
                    value,
                    "__call__",
                )
            except HarnessError:
                return
            if v2_exact_type_is_one_of(
                call_target,
                (types.FunctionType, types.MethodType),
            ):
                visit(call_target, depth + 1)
            return
        code = v2_raw_function_attribute(value, "__code__")
        analysis = v2_code_access_analysis(
            code,
            context=analysis_context,
            merge_nested_bindings=False,
        )
        globals_mapping = v2_raw_function_attribute(value, "__globals__")
        builtins_mapping = v2_raw_function_attribute(value, "__builtins__")
        if type(globals_mapping) is not dict:
            raise EvidenceFailed(
                "explicit projection globals mapping is not exact"
            )
        if type(builtins_mapping) is types.ModuleType:
            builtin_values = v2_raw_module_dict(builtins_mapping)
        elif type(builtins_mapping) is dict:
            builtin_values = builtins_mapping
        else:
            raise EvidenceFailed(
                "explicit projection builtins mapping is not exact"
            )
        def visit_accessed_binding(
            binding: Any,
            *,
            bare_called: bool,
            accessed_paths: Sequence[Sequence[str]] | None,
            called_paths: Sequence[Sequence[str]] | None,
            binding_depth: int,
        ) -> None:
            capabilities.update(
                v2_external_binding_path_capabilities(
                    binding,
                    accessed_paths,
                )
            )
            if bare_called:
                visit(binding, binding_depth + 1)
            for raw_path in called_paths or ():
                path = tuple(str(part) for part in raw_path)
                capabilities.update(
                    v2_external_type_path_capabilities(
                        binding,
                        (path,),
                    )
                )
                current = binding
                for part in path:
                    current = v2_raw_attribute_without_user_code(
                        current,
                        part,
                    )
                visit(current, binding_depth + 1)

        for name in analysis["accesses"]:
            if name in globals_mapping:
                global_value = globals_mapping[name]
            elif name in builtin_values:
                global_value = builtin_values[name]
            else:
                continue
            visit_accessed_binding(
                global_value,
                bare_called=(name in analysis["called_global_names"]),
                accessed_paths=analysis["module_paths"].get(name),
                called_paths=analysis["called_global_paths"].get(name),
                binding_depth=depth,
            )
        parameter_bindings = v2_function_default_bindings(value, code)
        if bound_self is not None and code.co_argcount > 0:
            parameter_bindings[code.co_varnames[0]] = bound_self
        for name, default_value in parameter_bindings.items():
            visit_accessed_binding(
                default_value,
                bare_called=(name in analysis["called_parameter_names"]),
                accessed_paths=analysis["parameter_paths"].get(name),
                called_paths=analysis["called_parameter_paths"].get(name),
                binding_depth=depth,
            )
        closure = v2_raw_function_attribute(value, "__closure__") or ()
        closure_bindings: dict[str, Any] = {}
        for name, cell in zip(code.co_freevars, closure, strict=True):
            try:
                cell_value = cell.cell_contents
            except ValueError:
                continue
            closure_bindings[name] = cell_value
            visit_accessed_binding(
                cell_value,
                bare_called=(name in analysis["called_freevar_names"]),
                accessed_paths=analysis["freevar_paths"].get(name),
                called_paths=analysis["called_freevar_paths"].get(name),
                binding_depth=depth,
            )
        for subscript_call in analysis["static_subscript_calls"]:
            source_kind = subscript_call["source_kind"]
            source_name = subscript_call["source_name"]
            if source_kind == "global":
                if source_name in globals_mapping:
                    current = globals_mapping[source_name]
                elif source_name in builtin_values:
                    current = builtin_values[source_name]
                else:
                    continue
            elif source_kind == "parameter":
                if source_name not in parameter_bindings:
                    continue
                current = parameter_bindings[source_name]
            elif source_kind == "freevar":
                if source_name not in closure_bindings:
                    continue
                current = closure_bindings[source_name]
            else:
                raise EvidenceFailed(
                    "explicit projection subscript source is unsupported"
                )
            for part in subscript_call["source_path"]:
                current = v2_raw_attribute_without_user_code(
                    current,
                    str(part),
                )
            key = subscript_call["key"]
            if type(current) is dict:
                raw_items = list(dict.items(current))
                if any(
                    type(candidate_key) is not str
                    and type(candidate_key) is not int
                    for candidate_key, _candidate_value in raw_items
                ):
                    raise EvidenceFailed(
                        "explicit projection static dict subscript contains "
                        "a non-exact stored key"
                    )
                target = V2_REFUSAL_PINNED_CLASS_ATTRIBUTE_MISSING
                for candidate_key, candidate_value in raw_items:
                    exact_match = (
                        type(key) is str
                        and type(candidate_key) is str
                        and str.__eq__(candidate_key, key) is True
                    ) or (
                        type(key) is int
                        and type(candidate_key) is int
                        and int.__eq__(candidate_key, key) is True
                    )
                    if exact_match:
                        target = candidate_value
                        break
                if target is V2_REFUSAL_PINNED_CLASS_ATTRIBUTE_MISSING:
                    raise EvidenceFailed(
                        "explicit projection static dict subscript lacks an "
                        "exact hook-free key match"
                    )
            elif type(current) is list:
                if type(key) is not int:
                    raise EvidenceFailed(
                        "explicit projection static list subscript index is "
                        "not an exact integer"
                    )
                list_length = list.__len__(current)
                if not -list_length <= key < list_length:
                    raise EvidenceFailed(
                        "explicit projection static list subscript index is "
                        "out of bounds"
                    )
                target = list.__getitem__(current, key)
            elif type(current) is tuple:
                if type(key) is not int:
                    raise EvidenceFailed(
                        "explicit projection static tuple subscript index is "
                        "not an exact integer"
                    )
                tuple_length = tuple.__len__(current)
                if not -tuple_length <= key < tuple_length:
                    raise EvidenceFailed(
                        "explicit projection static tuple subscript index is "
                        "out of bounds"
                    )
                target = tuple.__getitem__(current, key)
            else:
                raise EvidenceFailed(
                    "explicit projection static subscript call does not use "
                    "an audited exact container"
                )
            visit(target, depth + 1)

    visit(projection, 0)
    # Static bytecode reachability can conservatively identify a whole
    # process-state dimension, but it cannot prove that a branch actually
    # executed or that an arbitrary projector result retained a resource key.
    # Authorization is therefore restricted to dimensions the harness itself
    # captures in full before and after the callback. Other external calls
    # remain fail-closed even if they appear in projector bytecode.
    return frozenset(capabilities).intersection(
        V2_AUTOMATIC_EXTERNAL_STATE_CAPABILITIES
    )


def v2_authorized_external_state_projection(
    *,
    context: dict[str, Any],
) -> dict[str, Any]:
    capabilities = context["authorized_external_capabilities"]
    state: dict[str, Any] = {}
    if "process-cwd" in capabilities:
        try:
            raw_cwd = os.getcwdb()
        except OSError as error:
            raise EvidenceFailed(
                "refusal-state current-directory capture failed"
            ) from error
        state["process-cwd"] = v2_state_projection_value(
            raw_cwd,
            context=context,
        )
    if "process-python-environment" in capabilities:
        state["process-python-environment"] = v2_state_projection_value(
            os.environ,
            context=context,
        )
    if "process-recursion-limit" in capabilities:
        state["process-recursion-limit"] = sys.getrecursionlimit()
    unknown = set(capabilities).difference(
        V2_AUTOMATIC_EXTERNAL_STATE_CAPABILITIES
    )
    if unknown:
        raise EvidenceFailed(
            "refusal-state external capabilities lack automatic full-state "
            f"capture: {sorted(unknown)}"
        )
    return state


def v2_capture_restorable_external_process_state(
    capabilities: Iterable[str],
) -> dict[str, Any]:
    accepted = frozenset(capabilities)
    unknown = accepted.difference(V2_AUTOMATIC_EXTERNAL_STATE_CAPABILITIES)
    if unknown:
        raise EvidenceFailed(
            "refusal-state restoration received unsupported external "
            f"capabilities: {sorted(unknown)}"
        )
    state: dict[str, Any] = {}
    _, receipt_payload = v2_capture_command_receipt_state()
    state["harness-command-receipts"] = receipt_payload
    if (
        type(_cancel_requested) is not bool
        or type(_cancel_signal_epoch) is not int
        or _cancel_signal_epoch < 0
    ):
        raise EvidenceFailed("restorable cancellation state is malformed")
    state["harness-cancellation"] = (
        _cancel_requested,
        _cancel_signal_epoch,
    )
    if "process-cwd" in accepted:
        state["process-cwd"] = os.getcwdb()
    if "process-python-environment" in accepted:
        environment = os.environ
        environment_bytes = os.environb
        if (
            environment is not V2_INITIAL_PROCESS_ENVIRONMENT
            or environment_bytes is not V2_INITIAL_PROCESS_ENVIRONMENT_BYTES
        ):
            raise EvidenceFailed(
                "restorable process environment binding is not pinned"
            )
        state["process-python-environment"] = {
            "environment": environment,
            "environment_bytes": environment_bytes,
            "environment_attributes": (
                v2_exact_instance_dictionary_snapshot(
                    environment,
                    label="restorable process environment",
                )
            ),
            "environment_bytes_attributes": (
                v2_exact_instance_dictionary_snapshot(
                    environment_bytes,
                    label="restorable byte process environment",
                )
            ),
            "environment_bytes_entries": (
                v2_bounded_process_environment_bytes_snapshot()
            ),
        }
    if "process-recursion-limit" in accepted:
        state["process-recursion-limit"] = sys.getrecursionlimit()
    return state


def v2_restore_external_process_state(state: Mapping[str, Any]) -> None:
    if type(state) is not dict:
        raise EvidenceFailed(
            "refusal-state saved process contract is not an exact object"
        )
    required_fields = {
        "harness-command-receipts",
        "harness-cancellation",
    }
    permitted_fields = required_fields | {
        "process-cwd",
        "process-python-environment",
        "process-recursion-limit",
    }
    if not required_fields <= set(state) or set(state) - permitted_fields:
        raise EvidenceFailed(
            "refusal-state saved process contract fields differ"
        )
    receipt_payload = state["harness-command-receipts"]
    cancellation = state["harness-cancellation"]
    if type(receipt_payload) is not bytes:
        raise EvidenceFailed(
            "refusal-state saved command receipt contract is malformed"
        )
    decoded_receipts = strict_json_loads(
        receipt_payload,
        label="saved command receipt state preflight",
        require_canonical=True,
    )
    decoded_receipts = v2_validate_exact_json_wire(
        decoded_receipts,
        label="saved command receipt state preflight",
    )
    if type(decoded_receipts) is not list:
        raise EvidenceFailed(
            "refusal-state saved command receipt contract is not an array"
        )
    if (
        type(cancellation) is not tuple
        or tuple.__len__(cancellation) != 2
        or type(tuple.__getitem__(cancellation, 0)) is not bool
        or type(tuple.__getitem__(cancellation, 1)) is not int
        or tuple.__getitem__(cancellation, 1) < 0
    ):
        raise EvidenceFailed(
            "refusal-state saved cancellation contract is malformed"
        )
    target_cwd: bytes | None = None
    if "process-cwd" in state:
        target_cwd = state["process-cwd"]
        if type(target_cwd) is not bytes:
            raise EvidenceFailed(
                "refusal-state saved cwd is not exact bytes"
            )
    target_limit: int | None = None
    if "process-recursion-limit" in state:
        target_limit = state["process-recursion-limit"]
        if type(target_limit) is not int or target_limit <= 0:
            raise EvidenceFailed(
                "refusal-state saved recursion limit is malformed"
            )
    target_environment: dict[str, Any] | None = None
    if "process-python-environment" in state:
        candidate_environment = state["process-python-environment"]
        if (
            type(candidate_environment) is not dict
            or set(candidate_environment) != {
                "environment",
                "environment_attributes",
                "environment_bytes",
                "environment_bytes_attributes",
                "environment_bytes_entries",
            }
        ):
            raise EvidenceFailed(
                "refusal-state saved environment contract is not exact"
            )
        saved_environment = candidate_environment["environment"]
        saved_environment_bytes = candidate_environment[
            "environment_bytes"
        ]
        saved_entries = candidate_environment["environment_bytes_entries"]
        if (
            saved_environment is not V2_INITIAL_PROCESS_ENVIRONMENT
            or saved_environment_bytes
            is not V2_INITIAL_PROCESS_ENVIRONMENT_BYTES
            or type(saved_entries) is not dict
            or any(
                type(key) is not bytes or type(value) is not bytes
                for key, value in dict.items(saved_entries)
            )
        ):
            raise EvidenceFailed(
                "refusal-state saved byte environment is not exact"
            )
        v2_exact_instance_dictionary_snapshots_match(
            candidate_environment["environment_attributes"],
            candidate_environment["environment_attributes"],
            label="saved refusal-state process environment",
        )
        v2_exact_instance_dictionary_snapshots_match(
            candidate_environment["environment_bytes_attributes"],
            candidate_environment["environment_bytes_attributes"],
            label="saved refusal-state byte process environment",
        )
        target_environment = candidate_environment

    def restore_recursion_limit() -> None:
        if target_limit is not None and sys.getrecursionlimit() != target_limit:
            sys.setrecursionlimit(target_limit)

    def restore_environment() -> None:
        if target_environment is None:
            return
        v2_restore_process_environment(
            target_environment["environment"],
            target_environment["environment_bytes"],
            target_environment["environment_attributes"],
            target_environment["environment_bytes_attributes"],
            target_environment["environment_bytes_entries"],
        )

    def restore_cwd() -> None:
        if target_cwd is not None and os.getcwdb() != target_cwd:
            os.chdir(target_cwd)

    def restore_receipts() -> None:
        v2_restore_command_receipt_state(receipt_payload)

    def restore_cancellation() -> None:
        v2_restore_cancel_state(
            tuple.__getitem__(cancellation, 0),
            tuple.__getitem__(cancellation, 1),
        )

    steps: tuple[tuple[str, Callable[[], None]], ...] = ()
    if target_limit is not None:
        steps = (*steps, ("process-recursion-limit", restore_recursion_limit))
    if target_environment is not None:
        steps = (*steps, ("process-environment", restore_environment))
    if target_cwd is not None:
        steps = (*steps, ("process-cwd", restore_cwd))
    steps = (
        *steps,
        ("command-receipts", restore_receipts),
        ("cancellation", restore_cancellation),
    )

    def verify() -> None:
        saved_requested = tuple.__getitem__(cancellation, 0)
        saved_epoch = tuple.__getitem__(cancellation, 1)
        expected_requested = (
            saved_requested
            if _cancel_signal_epoch == saved_epoch
            else True
        )
        if (
            target_limit is not None
            and sys.getrecursionlimit() != target_limit
            or target_cwd is not None
            and os.getcwdb() != target_cwd
            or target_environment is not None
            and (
                os.environ is not target_environment["environment"]
                or os.environb
                is not target_environment["environment_bytes"]
                or not v2_exact_instance_dictionary_matches(
                    target_environment["environment"],
                    target_environment["environment_attributes"],
                    label="restored refusal-state process environment",
                )
                or not v2_exact_instance_dictionary_matches(
                    target_environment["environment_bytes"],
                    target_environment["environment_bytes_attributes"],
                    label="restored refusal-state byte process environment",
                )
                or tuple(dict.items(
                    v2_bounded_process_environment_bytes_snapshot()
                ))
                != tuple(dict.items(
                    target_environment["environment_bytes_entries"]
                ))
                or not v2_process_environment_backing_is_pinned()
            )
            or _command_receipts is not V2_INITIAL_COMMAND_RECEIPTS
            or v2_capture_command_receipt_state()[1] != receipt_payload
            or _cancel_signal_epoch < saved_epoch
            or _cancel_requested is not expected_requested
        ):
            raise EvidenceFailed(
                "refusal-state process restoration did not converge"
            )

    try:
        report = v2_run_convergent_restoration(steps, verify)
    except BaseException as error:
        raise EvidenceFailed(
            "refusal-state process restoration runner failed"
        ) from error
    if report["converged"] is not True or report["anomalies"]:
        cleanup_error = EvidenceFailed(
            "refusal-state process restoration had cleanup anomalies"
        )
        if report["anomalies"]:
            raise cleanup_error from report["anomalies"][0][1]
        raise cleanup_error


def v2_reject_unbound_required_parameter_calls(value: Any) -> None:
    if type(value) is not types.FunctionType:
        return
    code = v2_raw_function_attribute(value, "__code__")
    if type(code) is not types.CodeType:
        raise EvidenceFailed("explicit projection function code is not exact")
    analysis = v2_code_access_analysis(
        code,
        context=v2_new_refusal_projection_context(),
        merge_nested_bindings=False,
    )
    defaults = v2_function_default_bindings(value, code)
    parameter_layout = dict(v2_code_parameter_layout(code))
    required = {
        name
        for name, kind in parameter_layout.items()
        if kind in {"positional", "keyword-only"}
        and name not in defaults
    }
    invoked = set(analysis["called_parameter_names"])
    invoked.update(
        name
        for name, paths in analysis["called_parameter_paths"].items()
        if paths
    )
    invoked.update(
        row["source_name"]
        for row in analysis["static_subscript_calls"]
        if row["source_kind"] == "parameter"
    )
    unbound_invoked = sorted(required & invoked)
    if unbound_invoked:
        raise EvidenceFailed(
            "explicit projection invokes an unbound required parameter: "
            + ", ".join(unbound_invoked)
        )
    empty_variadic_invoked = sorted(
        name
        for name in invoked
        if parameter_layout.get(name) in {"variadic", "keyword-variadic"}
    )
    if empty_variadic_invoked:
        raise EvidenceFailed(
            "explicit projection invokes an empty variadic parameter: "
            + ", ".join(empty_variadic_invoked)
        )


def v2_bounded_explicit_projection(value: Any) -> Any:
    v2_reject_unbound_required_parameter_calls(value)
    context = v2_new_refusal_projection_context()
    projected = v2_state_projection_value(value, context=context)
    v2_validate_refusal_projection_graph(projected)
    if v2_projection_contains_opaque(projected):
        raise EvidenceFailed(
            "explicit refusal projection contains unprojectable opaque state"
        )
    payload = canonical_bytes(projected)
    if len(payload) > context["limits"]["projection_bytes"]:
        raise EvidenceFailed(
            "explicit refusal projection exceeds its aggregate projection bytes cap"
        )
    return projected


def v2_callback_refusal_projection(
    callback: Callable[[], Any],
    *,
    collector_rows: Sequence[Mapping[str, Any]],
    limits: Mapping[str, int] | None = None,
    authorized_external_capabilities: Iterable[str] = (),
) -> dict[str, Any]:
    detached_command_receipts, command_receipt_payload = (
        v2_capture_command_receipt_state()
    )
    projection_context = v2_new_refusal_projection_context(
        limits,
        authorized_external_capabilities=authorized_external_capabilities,
    )
    projection = {
        "schema": V2_REFUSAL_PROJECTION_SCHEMA,
        "python_runtime": {
            "implementation": sys.implementation.name,
            "cache_tag": sys.implementation.cache_tag,
            "version": [
                sys.version_info.major,
                sys.version_info.minor,
                sys.version_info.micro,
            ],
            "byteorder": sys.byteorder,
        },
        "automatic_callback_state": v2_state_projection_value(
            callback,
            context=projection_context,
        ),
        "authorized_external_state": v2_authorized_external_state_projection(
            context=projection_context,
        ),
        "collector_check_roots": v2_state_projection_value(
            [row["semantic_root"] for row in collector_rows],
            context=projection_context,
        ),
        "command_receipts": v2_state_projection_value(
            detached_command_receipts,
            context=projection_context,
        ),
        "command_receipt_count": len(detached_command_receipts),
        "command_receipt_content_root": (
            "sha256-v1:" + hashlib.sha256(command_receipt_payload).hexdigest()
        ),
        "command_receipt_list_binding_is_pinned": (
            _command_receipts is V2_INITIAL_COMMAND_RECEIPTS
        ),
        "cancel_requested": _cancel_requested,
        "cancel_signal_epoch": _cancel_signal_epoch,
    }
    v2_validate_refusal_projection_graph(projection)
    if v2_projection_contains_opaque(projection):
        opaque_paths = v2_projection_opaque_paths(projection)
        raise EvidenceFailed(
            "refusal callback contains unprojectable opaque state at "
            f"{', '.join(opaque_paths)}; provide an explicit bounded projection"
        )
    payload = canonical_bytes(projection)
    if len(payload) > projection_context["limits"]["projection_bytes"]:
        raise EvidenceFailed(
            "refusal-state projection exceeds its aggregate projection bytes cap"
        )
    return projection


def v2_raw_type_name(value: type[Any]) -> str:
    name = v2_raw_type_attribute(value, "__name__")
    if type(name) is not str:
        raise EvidenceFailed("refusal-state error type name is not exact")
    return name


V2_DISCLOSED_EXCEPTION_TYPES: tuple[type[BaseException], ...] = (
    BaseException,
    Exception,
    KeyboardInterrupt,
    SystemExit,
    GeneratorExit,
    ArithmeticError,
    AssertionError,
    AttributeError,
    BufferError,
    EOFError,
    ImportError,
    LookupError,
    MemoryError,
    NameError,
    OSError,
    ReferenceError,
    RuntimeError,
    StopAsyncIteration,
    StopIteration,
    SyntaxError,
    SystemError,
    TypeError,
    ValueError,
    Warning,
    HarnessError,
    UsageRefused,
    InputRefused,
    NoData,
    EvidenceFailed,
    CancelledDrained,
    InfrastructureFailed,
)
V2_DISCLOSED_EXCEPTION_TYPE_NAMES = frozenset(
    value.__name__ for value in V2_DISCLOSED_EXCEPTION_TYPES
)


def v2_exception_type_is_disclosed(value: type[Any]) -> bool:
    return (
        value is BaseException
        or value is Exception
        or value is KeyboardInterrupt
        or value is SystemExit
        or value is GeneratorExit
        or value is ArithmeticError
        or value is AssertionError
        or value is AttributeError
        or value is BufferError
        or value is EOFError
        or value is ImportError
        or value is LookupError
        or value is MemoryError
        or value is NameError
        or value is OSError
        or value is ReferenceError
        or value is RuntimeError
        or value is StopAsyncIteration
        or value is StopIteration
        or value is SyntaxError
        or value is SystemError
        or value is TypeError
        or value is ValueError
        or value is Warning
        or value is HarnessError
        or value is UsageRefused
        or value is InputRefused
        or value is NoData
        or value is EvidenceFailed
        or value is CancelledDrained
        or value is InfrastructureFailed
    )


def v2_diagnostic_type_projection(value: type[Any]) -> str:
    try:
        module = v2_raw_type_attribute(value, "__module__")
        qualname = v2_raw_type_attribute(value, "__qualname__")
    except EvidenceFailed:
        return "opaque-value-type"
    if type(module) is not str or type(qualname) is not str:
        return "opaque-value-type"
    try:
        module_bytes = v2_assertion_evidence_utf8_length(
            module,
            cap=V2_DIAGNOSTIC_SOURCE_CHARACTERS_CAP,
            label="diagnostic value type module",
        )
        if module_bytes >= V2_DIAGNOSTIC_SOURCE_CHARACTERS_CAP:
            return "<value-type-oversize>"
        v2_assertion_evidence_utf8_length(
            qualname,
            cap=(
                V2_DIAGNOSTIC_SOURCE_CHARACTERS_CAP
                - module_bytes
                - 1
            ),
            label="diagnostic value type qualified name",
        )
    except EvidenceFailed:
        return "<value-type-oversize>"
    identity = module + "." + qualname
    encoded = str.encode(identity, "utf-8")
    disclosed_builtin = (
        value is types.NoneType
        or value is bool
        or value is int
        or value is float
        or value is str
        or value is bytes
        or value is bytearray
        or value is memoryview
        or value is list
        or value is tuple
        or value is set
        or value is frozenset
        or value is dict
    )
    if disclosed_builtin and module == "builtins":
        return identity
    return "<value-type-root:" + hashlib.sha256(encoded).hexdigest() + ">"


def v2_exception_type_projection(value: type[Any]) -> str:
    try:
        raw_name = v2_raw_type_name(value)
    except EvidenceFailed:
        return "opaque-exception"
    safely_disclosed = v2_exception_type_is_disclosed(value)
    if safely_disclosed:
        try:
            v2_assertion_evidence_utf8_length(
                raw_name,
                cap=V2_EXCEPTION_TYPE_IDENTITY_BYTES_CAP,
                label="v2 disclosed exception type identity",
            )
        except EvidenceFailed:
            return "<exception-type-oversize>"
        if (
            re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", raw_name) is None
            or v2_contains_absolute_path(raw_name)
            or v2_redact_contextual_text(raw_name) != raw_name
        ):
            return "opaque-exception"
        return raw_name
    try:
        raw_module = v2_raw_type_attribute(value, "__module__")
        raw_qualname = v2_raw_type_attribute(value, "__qualname__")
    except EvidenceFailed:
        return "opaque-exception"
    if type(raw_module) is not str or type(raw_qualname) is not str:
        return "opaque-exception"
    try:
        module_bytes = v2_assertion_evidence_utf8_length(
            raw_module,
            cap=V2_EXCEPTION_TYPE_IDENTITY_BYTES_CAP,
            label="v2 exception type module identity",
        )
        if module_bytes >= V2_EXCEPTION_TYPE_IDENTITY_BYTES_CAP:
            return "<exception-type-oversize>"
        v2_assertion_evidence_utf8_length(
            raw_qualname,
            cap=(
                V2_EXCEPTION_TYPE_IDENTITY_BYTES_CAP
                - module_bytes
                - 1
            ),
            label="v2 exception type qualified identity",
        )
    except EvidenceFailed:
        return "<exception-type-oversize>"
    replacement_encoded = str.encode(
        raw_module + "." + raw_qualname,
        "utf-8",
    )
    return (
        "<exception-type-root:"
        + hashlib.sha256(replacement_encoded).hexdigest()
        + ">"
    )


def v2_validate_exception_type_projection(value: Any) -> None:
    if (
        type(value) is not str
        or not value
        or len(value) > V2_EXCEPTION_TYPE_IDENTITY_BYTES_CAP
    ):
        raise EvidenceFailed(
            "v2 exception type projection is malformed"
        )
    try:
        encoded = str.encode(value, "utf-8")
    except UnicodeEncodeError as error:
        raise EvidenceFailed(
            "v2 exception type projection is malformed"
        ) from error
    valid_shape = (
        value == "opaque-exception"
        or value == "<exception-type-oversize>"
        or re.fullmatch(
            r"<exception-type-root:[0-9a-f]{64}>",
            value,
        )
        is not None
        or value in V2_DISCLOSED_EXCEPTION_TYPE_NAMES
    )
    if len(encoded) > V2_EXCEPTION_TYPE_IDENTITY_BYTES_CAP or not valid_shape:
        raise EvidenceFailed(
            "v2 exception type projection is malformed"
        )


def v2_exception_diagnostic(value: BaseException) -> tuple[str, bool]:
    arguments = v2_exact_descriptor_read(
        V2_BASE_EXCEPTION_ARGS_DESCRIPTOR,
        value,
        type(value),
        label="exception arguments",
    )
    if type(arguments) is not tuple:
        return "", False
    if not arguments:
        return "", True
    if len(arguments) == 1 and type(arguments[0]) is str:
        return arguments[0], True
    return "", False


V2_REFUSAL_PROCESS_STATE_LOCK = threading.RLock()


def v2_serialize_refusal_process_state(
    callback: Callable[..., Any],
) -> Callable[..., Any]:
    """Serialize a complete refusal transaction over process-global state."""

    def locked(*arguments: Any, **keywords: Any) -> Any:
        with V2_REFUSAL_PROCESS_STATE_LOCK:
            return callback(*arguments, **keywords)

    locked.__name__ = callback.__name__
    locked.__qualname__ = callback.__qualname__
    return locked


def v2_detach_assertion_result_wire(
    value: Any,
    *,
    label: str,
) -> Any:
    return v2_validate_exact_json_wire(
        value,
        label=label,
        item_cap=V2_ASSERTION_RESULT_EXACT_WIRE_ITEM_CAP,
        node_cap=V2_ASSERTION_RESULT_EXACT_WIRE_NODE_CAP,
        depth_cap=V2_ASSERTION_RESULT_EXACT_WIRE_DEPTH_CAP,
        byte_cap=V2_LOG_LINE_BYTES_CAP,
        snapshot_byte_cap=(
            V2_ASSERTION_RESULT_EXACT_WIRE_SNAPSHOT_BYTES_CAP
        ),
    )


V2_AUDITED_LOCAL_PURE_CALL_RESULT_PATHS += ((
    v2_detach_assertion_result_wire,
    frozenset({V2_DERIVED_CALL_RESULT_PATH[0]}),
),)
V2_AUDITED_LOCAL_PURE_CALL_CODE_CONTRACTS += ((
    v2_detach_assertion_result_wire,
    v2_detach_assertion_result_wire.__code__,
),)


class V2CheckCollector:
    __slots__ = (
        "case_id",
        "assertion_id",
        "rows",
        "_precompacted_fields",
    )

    def __init__(self, case_id: str, assertion_id: str) -> None:
        self.case_id = case_id
        self.assertion_id = assertion_id
        self.rows: list[dict[str, Any]] = []
        self._precompacted_fields: dict[str, dict[str, str]] = {}

    @staticmethod
    def _root_only(projected: Any) -> dict[str, Any]:
        payload = canonical_bytes(projected)
        return {
            "projection_root": semantic_root(projected),
            "canonical_bytes": len(payload),
        }

    @staticmethod
    def _bounded_with_state(value: Any) -> tuple[Any, bool]:
        projected = v2_assertion_evidence_projection(value)
        if (
            type(projected) is dict
            and dict.__len__(projected) == 2
            and set(dict.__iter__(projected))
            == {"projection_root", "canonical_bytes"}
        ):
            return V2CheckCollector._root_only(projected), True
        payload = canonical_bytes(projected)
        if len(payload) <= V2_ASSERTION_EVIDENCE_INLINE_BYTES_CAP:
            return projected, False
        return V2CheckCollector._root_only(projected), True

    @staticmethod
    def _bounded(value: Any) -> Any:
        projected, _root_only = V2CheckCollector._bounded_with_state(value)
        return projected

    def check(
        self,
        check_id: str,
        condition: bool,
        *,
        expected: Any,
        observed: Any,
    ) -> None:
        if type(self) is not V2CheckCollector:
            raise EvidenceFailed("v2 assertion collector instance type drifted")
        v2_validate_check_id(
            check_id,
            label=f"{self.case_id} emitted check",
        )
        if type(condition) is not bool:
            raise EvidenceFailed(
                f"{self.case_id}/{check_id} produced a non-boolean condition"
            )
        if type(self.rows) is not list:
            raise EvidenceFailed(
                f"{self.case_id} assertion rows are not an exact list"
            )
        row_count = list.__len__(self.rows)
        if row_count >= V2_ASSERTION_CHECKS_CAP:
            raise EvidenceFailed(
                f"{self.case_id} exceeds the bounded assertion-check cap"
            )
        existing_check_ids: set[str] = set()
        for row in list.__iter__(self.rows):
            if (
                type(row) is not dict
                or dict.__len__(row) != len(V2_ASSERTION_CHECK_FIELDS)
                or set(dict.__iter__(row)) != V2_ASSERTION_CHECK_FIELDS
                or type(dict.__getitem__(row, "check_id")) is not str
            ):
                raise EvidenceFailed(
                    f"{self.case_id} retained malformed assertion rows"
                )
            set.add(
                existing_check_ids,
                dict.__getitem__(row, "check_id"),
            )
        if check_id in existing_check_ids:
            raise EvidenceFailed(
                f"{self.case_id} produced a duplicate or noncanonical check ID"
            )
        if (
            type(self._precompacted_fields) is not dict
            or dict.__len__(self._precompacted_fields) > row_count
        ):
            raise EvidenceFailed(
                f"{self.case_id} assertion receipt provenance is malformed"
            )
        expected_projection, expected_precompacted = (
            V2CheckCollector._bounded_with_state(expected)
        )
        observed_projection, observed_precompacted = (
            V2CheckCollector._bounded_with_state(observed)
        )
        row = v2_rooted(
            {
                "check_id": check_id,
                "expected": expected_projection,
                "observed": observed_projection,
                "passed": condition,
            }
        )
        list.append(self.rows, row)
        precompacted: dict[str, str] = {}
        if expected_precompacted:
            precompacted["expected"] = semantic_root(expected_projection)
        if observed_precompacted:
            precompacted["observed"] = semantic_root(observed_projection)
        if precompacted:
            dict.__setitem__(
                self._precompacted_fields,
                check_id,
                precompacted,
            )
        if condition is not True:
            raise EvidenceFailed(
                f"{self.case_id}/{check_id} failed: "
                "expected/observed projections retained by root; "
                f"expected_root={semantic_root(row['expected'])}, "
                f"observed_root={semantic_root(row['observed'])}"
            )

    @v2_serialize_refusal_process_state
    def refuses(
        self,
        check_id: str,
        error_type: type[HarnessError],
        callback: Callable[[], Any],
        *,
        contains: str | None = None,
        projection: Callable[[], Any] | None = None,
        projection_label: str | None = None,
    ) -> None:
        if type(self) is not V2CheckCollector:
            raise EvidenceFailed("v2 assertion collector instance type drifted")
        expected_terminal = v2_harness_error_terminal(error_type)
        if projection is not None and not projection_label:
            raise EvidenceFailed(
                f"{self.case_id}/{check_id} stateful refusal lacks a projection label"
            )
        effective_projection_label = (
            "AUTOMATIC_CALLBACK_GRAPH_AND_EXPLICIT_EXTERNAL_STATE"
            if projection is not None
            else "AUTOMATIC_CALLBACK_GRAPH_AND_HARNESS_STATE"
        )
        authorized_external_capabilities = (
            v2_explicit_projection_external_capabilities(projection)
            if projection is not None
            else frozenset()
        )

        def capture_projection() -> dict[str, Any]:
            automatic = v2_callback_refusal_projection(
                callback,
                collector_rows=self.rows,
                authorized_external_capabilities=(
                    authorized_external_capabilities
                ),
            )
            explicit_callable_state: dict[str, Any] | None = None
            explicit_external_state: Any = None
            if projection is not None:
                restorable_process_state = (
                    v2_capture_restorable_external_process_state(
                        authorized_external_capabilities
                    )
                )
                projection_primary: BaseException | None = None
                try:
                    explicit_callable_state = (
                        v2_callback_refusal_projection(
                            projection,
                            collector_rows=[],
                            authorized_external_capabilities=(
                                authorized_external_capabilities
                            ),
                        )
                    )
                    explicit_external_state = v2_bounded_explicit_projection(
                        projection()
                    )
                    explicit_callable_state_after = (
                        v2_callback_refusal_projection(
                            projection,
                            collector_rows=[],
                            authorized_external_capabilities=(
                                authorized_external_capabilities
                            ),
                        )
                    )
                    if (
                        canonical_bytes(explicit_callable_state)
                        != canonical_bytes(explicit_callable_state_after)
                    ):
                        raise EvidenceFailed(
                            "explicit refusal projection mutated its own "
                            "reachable state"
                        )
                except BaseException as error:
                    projection_primary = error
                cleanup_primary: BaseException | None = None
                try:
                    v2_restore_external_process_state(
                        restorable_process_state
                    )
                except BaseException as error:
                    cleanup_primary = error
                if projection_primary is not None:
                    if cleanup_primary is not None:
                        v2_attach_cleanup_note(
                            projection_primary,
                            cleanup_primary,
                        )
                    raise projection_primary
                if cleanup_primary is not None:
                    raise cleanup_primary
            return {
                "automatic_callback_state": automatic,
                "explicit_projection_callable_state": (
                    explicit_callable_state
                ),
                "explicit_external_state": explicit_external_state,
                "explicit_projection_label": projection_label,
                "authorized_external_capabilities": sorted(
                    authorized_external_capabilities
                ),
            }

        try:
            before_value = capture_projection()
        except BaseException as error:
            projection_message, projection_message_exact = (
                v2_exception_diagnostic(error)
                if type(error) in {
                    InputRefused,
                    NoData,
                    EvidenceFailed,
                    CancelledDrained,
                    InfrastructureFailed,
                }
                else ("", False)
            )
            projection_diagnostic = (
                v2_bounded_diagnostic_summary(
                    projection_message
                )
                if projection_message_exact
                else v2_raw_type_name(type(error))
            )
            raise EvidenceFailed(
                f"{self.case_id}/{check_id} refusal projection failed "
                f"before callback: {projection_diagnostic}"
            ) from error
        before = semantic_root(before_value)
        caught: BaseException | None = None
        returned = False
        try:
            callback()
            returned = True
        except BaseException as error:
            caught = error
        after_value: dict[str, Any] | None = None
        after_projection_error: BaseException | None = None
        try:
            after_value = capture_projection()
        except BaseException as error:
            after_projection_error = error
        after = semantic_root(after_value) if after_value is not None else None
        projection_divergence = (
            first_projection_divergence(before_value, after_value)
            if after_value is not None
            else None
        )
        exact_error_type = caught is not None and type(caught) is error_type
        caught_terminal = expected_terminal if exact_error_type else None
        diagnostic, diagnostic_exact = (
            v2_exception_diagnostic(caught)
            if exact_error_type and caught is not None
            else ("", False)
        )
        contains_match = (
            contains is None
            or (
                exact_error_type
                and diagnostic_exact
                and contains in diagnostic
            )
        )
        projection_unchanged = (
            after_projection_error is None
            and projection_divergence is None
            and before == after
        )
        V2CheckCollector.check(
            self,
            check_id,
            not returned
            and exact_error_type
            and caught_terminal == expected_terminal
            and contains_match
            and projection_unchanged,
            expected={
                "returned": False,
                "exact_error_type": error_type.__name__,
                "terminal": expected_terminal,
                "contains_match": True,
                "unchanged_projection_root": before,
                "projection_label": effective_projection_label,
                "first_divergence": None,
                "after_projection_error": None,
            },
            observed={
                "returned": returned,
                "caught_error_type": (
                    v2_raw_type_name(type(caught))
                    if caught is not None
                    else None
                ),
                "terminal": caught_terminal,
                "contains_match": contains_match,
                "projection_root_after": after,
                "projection_label": effective_projection_label,
                "explicit_projection_label": projection_label,
                "first_divergence": projection_divergence,
                "after_projection_error": (
                    v2_raw_type_name(type(after_projection_error))
                    if after_projection_error is not None
                    else None
                ),
                "diagnostic_root": (
                    text_root(diagnostic) if diagnostic else None
                ),
                "diagnostic_summary": (
                    v2_bounded_diagnostic_summary(diagnostic)
                    if diagnostic
                    else None
                ),
            },
        )

    def _document(
        self,
        parameters: Mapping[str, Any],
        rows: Sequence[Mapping[str, Any]],
    ) -> dict[str, Any]:
        if type(self) is not V2CheckCollector:
            raise EvidenceFailed("v2 assertion collector instance type drifted")
        try:
            accepted_parameters = v2_validate_exact_json_wire(
                parameters,
                label=f"{self.case_id} assertion parameters",
                item_cap=V2_ASSERTION_RESULT_EXACT_WIRE_ITEM_CAP,
                node_cap=V2_ASSERTION_RESULT_EXACT_WIRE_NODE_CAP,
                depth_cap=V2_ASSERTION_RESULT_EXACT_WIRE_DEPTH_CAP - 1,
                byte_cap=V2_LOG_LINE_BYTES_CAP,
                snapshot_byte_cap=(
                    V2_ASSERTION_RESULT_EXACT_WIRE_SNAPSHOT_BYTES_CAP
                ),
            )
        except InputRefused as error:
            raise EvidenceFailed(
                f"{self.case_id} assertion parameters are outside the "
                "exact-wire resource contract"
            ) from error
        if type(accepted_parameters) is not dict:
            raise EvidenceFailed(
                f"{self.case_id} assertion parameters are not an object"
            )
        if not rows:
            raise EvidenceFailed(f"{self.case_id} executed no assertion checks")
        document = {
            "schema": V2_ASSERTION_RESULT_SCHEMA,
            "case_id": self.case_id,
            "assertion_id": self.assertion_id,
            "executor_id": self.assertion_id,
            "parameters": accepted_parameters,
            "parameter_root": semantic_root(accepted_parameters),
            "ordered_checks": list(rows),
            "ordered_check_roots": [row["semantic_root"] for row in rows],
            "check_count": len(rows),
            "terminal": "Pass",
            "no_claim": V2_ASSERTION_RESULT_NO_CLAIM,
        }
        return v2_rooted(document)

    @staticmethod
    def _exact_wire_resource_profile(
        value: Any,
    ) -> tuple[int, int, int, int, int]:
        nodes = 0
        items = 0
        maximum_depth = 0
        snapshot_bytes = 0
        stack: list[tuple[Any, int]] = [(value, 0)]
        while stack:
            current, depth = list.pop(stack)
            nodes += 1
            maximum_depth = max(maximum_depth, depth)
            if type(current) is list:
                length = list.__len__(current)
                items += length
                snapshot_bytes += (
                    V2_EXACT_WIRE_LIST_SNAPSHOT_BASE_BYTES
                    + length * V2_EXACT_WIRE_LIST_SNAPSHOT_ITEM_BYTES
                )
                stack.extend(
                    (item, depth + 1)
                    for item in list.__iter__(current)
                )
            elif type(current) is dict:
                length = dict.__len__(current)
                items += 2 * length
                snapshot_bytes += (
                    V2_EXACT_WIRE_DICT_SNAPSHOT_BASE_BYTES
                    + length * V2_EXACT_WIRE_DICT_SNAPSHOT_ITEM_BYTES
                )
                stack.extend(
                    (item, depth + 1)
                    for item in dict.values(current)
                )
        return (
            len(canonical_bytes(value)),
            items,
            nodes,
            maximum_depth,
            snapshot_bytes,
        )

    @staticmethod
    def _select_compaction_indexes(
        baseline_profile: tuple[int, int, int, int],
        candidate_deltas: tuple[tuple[int, int, int, int], ...],
        resource_caps: tuple[int, int, int, int],
        *,
        state_limit: int = V2_ASSERTION_COMPACTION_SEARCH_STATES_CAP,
        transition_limit: int = (
            V2_ASSERTION_COMPACTION_SEARCH_TRANSITIONS_CAP
        ),
    ) -> tuple[tuple[int, ...] | None, dict[str, Any]]:
        if (
            type(baseline_profile) is not tuple
            or len(baseline_profile) != 4
            or any(
                type(value) is not int or value < 0
                for value in baseline_profile
            )
            or type(resource_caps) is not tuple
            or len(resource_caps) != 4
            or any(
                type(value) is not int or value <= 0
                for value in resource_caps
            )
            or type(candidate_deltas) is not tuple
            or len(candidate_deltas) > 2 * V2_ASSERTION_CHECKS_CAP
            or any(
                type(delta) is not tuple
                or len(delta) != 4
                or any(type(value) is not int for value in delta)
                for delta in candidate_deltas
            )
            or type(state_limit) is not int
            or not 1 <= state_limit
            <= V2_ASSERTION_COMPACTION_SEARCH_STATES_CAP
            or type(transition_limit) is not int
            or not 1 <= transition_limit
            <= V2_ASSERTION_COMPACTION_SEARCH_TRANSITIONS_CAP
        ):
            raise EvidenceFailed(
                "v2 assertion compaction search input is malformed"
            )

        grouped_indexes: dict[
            tuple[int, int, int, int],
            list[int],
        ] = {}
        for candidate_index, delta in enumerate(candidate_deltas):
            group = dict.get(grouped_indexes, delta)
            if group is None:
                group = []
                dict.__setitem__(grouped_indexes, delta, group)
            list.append(group, candidate_index)
        groups = tuple(
            (delta, tuple(indexes))
            for delta, indexes in dict.items(grouped_indexes)
        )
        suffix_best: list[tuple[int, int, int, int]] = [
            (0, 0, 0, 0)
            for _ in range(len(groups) + 1)
        ]
        suffix_maximum: list[tuple[int, int, int, int]] = [
            (0, 0, 0, 0)
            for _ in range(len(groups) + 1)
        ]
        for group_index in range(len(groups) - 1, -1, -1):
            delta, indexes = groups[group_index]
            following = suffix_best[group_index + 1]
            following_maximum = suffix_maximum[group_index + 1]
            suffix_best[group_index] = tuple(
                following[dimension]
                + min(0, len(indexes) * delta[dimension])
                for dimension in range(4)
            )
            suffix_maximum[group_index] = tuple(
                following_maximum[dimension]
                + max(0, len(indexes) * delta[dimension])
                for dimension in range(4)
            )

        normalization_product = math.prod(resource_caps)
        normalization_weights = tuple(
            normalization_product // cap for cap in resource_caps
        )

        def profile_fits(profile: tuple[int, int, int, int]) -> bool:
            return all(
                0 <= observed <= cap
                for observed, cap in zip(
                    profile,
                    resource_caps,
                    strict=True,
                )
            )

        def suffix_can_fit(
            group_index: int,
            profile: tuple[int, int, int, int],
        ) -> bool:
            optimistic = suffix_best[group_index]
            recoverable = suffix_maximum[group_index]
            return all(
                observed + improvement <= cap
                and observed + recovery >= 0
                for observed, improvement, recovery, cap in zip(
                    profile,
                    optimistic,
                    recoverable,
                    resource_caps,
                    strict=True,
                )
            )

        def telemetry(
            *,
            outcome: str,
            selected_count: int,
            final_profile: tuple[int, int, int, int] | None,
            states_popped: int,
            transitions_generated: int,
            search_complete: bool,
            no_fit_proven: bool,
            fit_found: bool = False,
            best_fit_selected_count: int | None = None,
            best_fit_profile: tuple[int, int, int, int] | None = None,
        ) -> dict[str, Any]:
            return {
                "outcome": outcome,
                "candidate_count": len(candidate_deltas),
                "group_count": len(groups),
                "selected_count": selected_count,
                "baseline_profile": list(baseline_profile),
                "final_profile": (
                    list(final_profile)
                    if final_profile is not None
                    else None
                ),
                "states_popped": states_popped,
                "transitions_generated": transitions_generated,
                "state_limit": state_limit,
                "transition_limit": transition_limit,
                "search_complete": search_complete,
                "no_fit_proven": no_fit_proven,
                "fit_found": fit_found,
                "best_fit_selected_count": best_fit_selected_count,
                "best_fit_profile": (
                    list(best_fit_profile)
                    if best_fit_profile is not None
                    else None
                ),
            }

        if profile_fits(baseline_profile):
            return (), telemetry(
                outcome="ADMITTED_WITHOUT_COMPACTION",
                selected_count=0,
                final_profile=baseline_profile,
                states_popped=0,
                transitions_generated=0,
                search_complete=True,
                no_fit_proven=False,
                fit_found=True,
                best_fit_selected_count=0,
                best_fit_profile=baseline_profile,
            )

        violated_dimensions = tuple(
            dimension
            for dimension, (observed, cap) in enumerate(
                zip(baseline_profile, resource_caps, strict=True)
            )
            if observed > cap
        )
        violated_dimension = (
            violated_dimensions[0]
            if len(violated_dimensions) == 1
            else None
        )
        single_dimension_candidate_indexes = tuple(
            candidate_index
            for candidate_index, delta in enumerate(candidate_deltas)
            if violated_dimension is not None
            and delta[violated_dimension] < 0
        )
        monotone_single_dimension = (
            len(violated_dimensions) == 1
            and len(groups) > 1
            and bool(single_dimension_candidate_indexes)
            and state_limit
            == V2_ASSERTION_COMPACTION_SEARCH_STATES_CAP
            and transition_limit
            == V2_ASSERTION_COMPACTION_SEARCH_TRANSITIONS_CAP
            and all(
                candidate_deltas[candidate_index][dimension] <= 0
                for candidate_index in single_dimension_candidate_indexes
                for dimension in range(4)
                if dimension != violated_dimension
            )
            and all(
                baseline_profile[dimension]
                + sum(
                    candidate_deltas[candidate_index][dimension]
                    for candidate_index in single_dimension_candidate_indexes
                )
                >= 0
                for dimension in range(4)
            )
        )
        if monotone_single_dimension:
            if violated_dimension is None:
                raise EvidenceFailed(
                    "v2 assertion compaction single-dimension dispatch "
                    "lost its violated dimension"
                )
            deficit = (
                baseline_profile[violated_dimension]
                - resource_caps[violated_dimension]
            )
            improvements = tuple(
                -candidate_deltas[candidate_index][violated_dimension]
                for candidate_index in single_dimension_candidate_indexes
            )
            accumulated_improvement = 0
            minimum_selected_count: int | None = None
            for selected_count, improvement in enumerate(
                sorted(improvements, reverse=True),
                start=1,
            ):
                accumulated_improvement += improvement
                if accumulated_improvement >= deficit:
                    minimum_selected_count = selected_count
                    break
            if minimum_selected_count is None:
                return None, telemetry(
                    outcome="NO_FIT_PROVEN",
                    selected_count=0,
                    final_profile=None,
                    states_popped=1,
                    transitions_generated=len(improvements),
                    search_complete=True,
                    no_fit_proven=True,
                )

            # With one violated dimension, candidates that do not improve it
            # cannot occur in a minimum-cardinality fit: dropping one would
            # preserve or improve the fit. When every improving candidate is
            # nonpositive in the other already-fitting dimensions, the sum of
            # the k largest improvements therefore proves the exact minimum
            # cardinality. Prefix DP then reconstructs the maximum original
            # candidate mask without enumerating subsets. It tracks whichever
            # side is smaller: selected candidates maximize retained gain,
            # while excluded candidates minimize discarded gain. The latter
            # is equivalent because the full eligible mask is fixed.
            candidate_count = len(improvements)
            excluded_count = candidate_count - minimum_selected_count
            use_selected_side = minimum_selected_count <= excluded_count
            dynamic_width = (
                minimum_selected_count
                if use_selected_side
                else excluded_count
            )
            dynamic_cells = sum(
                min(prefix_count, dynamic_width)
                for prefix_count in range(1, candidate_count + 1)
            )
            allocated_states = 1 + candidate_count + dynamic_cells
            generated_transitions = 2 * dynamic_cells
            if (
                allocated_states <= state_limit
                and generated_transitions <= transition_limit
            ):
                if use_selected_side:
                    impossible_improvement = -1
                    best_improvement_by_prefix: list[
                        tuple[int, ...]
                    ] = [(0,)]
                    for prefix_count, improvement in enumerate(
                        improvements,
                        start=1,
                    ):
                        prior = best_improvement_by_prefix[-1]
                        row = [
                            0,
                            *(
                                impossible_improvement
                                for _ in range(
                                    min(prefix_count, dynamic_width)
                                )
                            ),
                        ]
                        for selected_count in range(1, len(row)):
                            excluded = (
                                prior[selected_count]
                                if selected_count < len(prior)
                                else impossible_improvement
                            )
                            included_prefix = prior[selected_count - 1]
                            included = (
                                included_prefix + improvement
                                if included_prefix
                                != impossible_improvement
                                else impossible_improvement
                            )
                            row[selected_count] = max(excluded, included)
                        list.append(
                            best_improvement_by_prefix,
                            tuple(row),
                        )

                    remaining_deficit = deficit
                    remaining_slots = minimum_selected_count
                    selected_descending: list[int] = []
                    for candidate_index in range(
                        candidate_count - 1,
                        -1,
                        -1,
                    ):
                        if remaining_slots == 0:
                            break
                        lower_prefix = best_improvement_by_prefix[
                            candidate_index
                        ]
                        lower_best = (
                            lower_prefix[remaining_slots - 1]
                            if remaining_slots - 1 < len(lower_prefix)
                            else impossible_improvement
                        )
                        if (
                            lower_best != impossible_improvement
                            and improvements[candidate_index] + lower_best
                            >= remaining_deficit
                        ):
                            list.append(
                                selected_descending,
                                single_dimension_candidate_indexes[
                                    candidate_index
                                ],
                            )
                            remaining_deficit -= improvements[
                                candidate_index
                            ]
                            remaining_slots -= 1
                    if remaining_slots != 0 or remaining_deficit > 0:
                        raise EvidenceFailed(
                            "v2 assertion compaction single-dimension exact "
                            "selected-side reconstruction failed"
                        )
                    selected = tuple(reversed(selected_descending))
                else:
                    total_improvement = sum(improvements)
                    remaining_allowance = total_improvement - deficit
                    impossible_discard = total_improvement + 1
                    least_discard_by_prefix: list[
                        tuple[int, ...]
                    ] = [(0,)]
                    for prefix_count, improvement in enumerate(
                        improvements,
                        start=1,
                    ):
                        prior = least_discard_by_prefix[-1]
                        row = [
                            0,
                            *(
                                impossible_discard
                                for _ in range(
                                    min(prefix_count, dynamic_width)
                                )
                            ),
                        ]
                        for discarded_count in range(1, len(row)):
                            retained = (
                                prior[discarded_count]
                                if discarded_count < len(prior)
                                else impossible_discard
                            )
                            discarded_prefix = prior[discarded_count - 1]
                            discarded = (
                                discarded_prefix + improvement
                                if discarded_prefix != impossible_discard
                                else impossible_discard
                            )
                            row[discarded_count] = min(
                                retained,
                                discarded,
                            )
                        list.append(
                            least_discard_by_prefix,
                            tuple(row),
                        )

                    remaining_exclusions = excluded_count
                    excluded_positions: list[int] = []
                    for candidate_index in range(
                        candidate_count - 1,
                        -1,
                        -1,
                    ):
                        lower_prefix = least_discard_by_prefix[
                            candidate_index
                        ]
                        lower_keep_cost = (
                            lower_prefix[remaining_exclusions]
                            if remaining_exclusions < len(lower_prefix)
                            else impossible_discard
                        )
                        if lower_keep_cost <= remaining_allowance:
                            continue
                        if remaining_exclusions == 0:
                            raise EvidenceFailed(
                                "v2 assertion compaction single-dimension "
                                "excluded-side reconstruction exhausted its "
                                "exclusion budget"
                            )
                        lower_exclude_cost = lower_prefix[
                            remaining_exclusions - 1
                        ]
                        improvement = improvements[candidate_index]
                        if (
                            lower_exclude_cost == impossible_discard
                            or improvement + lower_exclude_cost
                            > remaining_allowance
                        ):
                            raise EvidenceFailed(
                                "v2 assertion compaction single-dimension "
                                "excluded-side reconstruction failed"
                            )
                        list.append(excluded_positions, candidate_index)
                        remaining_allowance -= improvement
                        remaining_exclusions -= 1
                    if remaining_exclusions != 0:
                        raise EvidenceFailed(
                            "v2 assertion compaction single-dimension exact "
                            "excluded-side reconstruction was incomplete"
                        )
                    excluded_position_set = frozenset(excluded_positions)
                    selected = tuple(
                        candidate_index
                        for position, candidate_index in enumerate(
                            single_dimension_candidate_indexes
                        )
                        if position not in excluded_position_set
                    )
                if len(selected) != minimum_selected_count:
                    raise EvidenceFailed(
                        "v2 assertion compaction single-dimension exact "
                        "selection cardinality drifted"
                    )
                final_profile = tuple(
                    baseline_value
                    + sum(
                        candidate_deltas[candidate_index][dimension]
                        for candidate_index in selected
                    )
                    for dimension, baseline_value in enumerate(
                        baseline_profile
                    )
                )
                if (
                    any(value < 0 for value in final_profile)
                    or not profile_fits(final_profile)
                ):
                    raise EvidenceFailed(
                        "v2 assertion compaction single-dimension exact "
                        "selection did not fit"
                    )
                return selected, telemetry(
                    outcome="ADMITTED",
                    selected_count=len(selected),
                    final_profile=final_profile,
                    states_popped=allocated_states,
                    transitions_generated=generated_transitions,
                    search_complete=True,
                    no_fit_proven=False,
                    fit_found=True,
                    best_fit_selected_count=len(selected),
                    best_fit_profile=final_profile,
                )

        initial_violation_score = sum(
            max(0, baseline_profile[dimension] - resource_caps[dimension])
            * normalization_weights[dimension]
            for dimension in range(4)
        )
        pending: list[
            tuple[
                int,
                int,
                int,
                int,
                tuple[int, int, int, int],
                int,
            ]
        ] = [(
            0,
            initial_violation_score,
            0,
            0,
            baseline_profile,
            0,
        )]
        best_objective_by_state: dict[
            tuple[int, tuple[int, int, int, int]],
            tuple[int, int],
        ] = {(0, baseline_profile): (0, 0)}
        states_popped = 0
        transitions_generated = 0
        best_fit: tuple[
            tuple[int, int],
            int,
            tuple[int, int, int, int],
        ] | None = None
        while pending:
            if states_popped >= state_limit:
                return None, telemetry(
                    outcome="SEARCH_LIMIT_REACHED",
                    selected_count=0,
                    final_profile=None,
                    states_popped=states_popped,
                    transitions_generated=transitions_generated,
                    search_complete=False,
                    no_fit_proven=False,
                    fit_found=best_fit is not None,
                    best_fit_selected_count=(
                        best_fit[0][0] if best_fit is not None else None
                    ),
                    best_fit_profile=(
                        best_fit[2] if best_fit is not None else None
                    ),
                )
            (
                selected_count,
                _violation_score,
                negative_mask,
                negative_group_index,
                profile,
                selected_mask,
            ) = heapq.heappop(pending)
            group_index = -negative_group_index
            states_popped += 1
            state_key = (group_index, profile)
            if dict.get(best_objective_by_state, state_key) != (
                selected_count,
                negative_mask,
            ):
                continue
            if group_index == len(groups) and profile_fits(profile):
                selected = tuple(
                    index
                    for index in range(len(candidate_deltas))
                    if selected_mask & (1 << index)
                )
                return selected, telemetry(
                    outcome="ADMITTED",
                    selected_count=len(selected),
                    final_profile=profile,
                    states_popped=states_popped,
                    transitions_generated=transitions_generated,
                    search_complete=True,
                    no_fit_proven=False,
                    fit_found=True,
                    best_fit_selected_count=len(selected),
                    best_fit_profile=profile,
                )
            if (
                group_index >= len(groups)
                or not suffix_can_fit(group_index, profile)
            ):
                continue
            delta, indexes = groups[group_index]
            suffix_masks = [0]
            suffix_mask = 0
            for candidate_index in reversed(indexes):
                suffix_mask |= 1 << candidate_index
                list.append(suffix_masks, suffix_mask)
            options: list[
                tuple[
                    tuple[Any, ...],
                    tuple[int, int, int, int],
                    int,
                ]
            ] = []
            for selected_from_group in range(len(indexes) + 1):
                next_profile = tuple(
                    profile[dimension]
                    + selected_from_group * delta[dimension]
                    for dimension in range(4)
                )
                next_mask = selected_mask | suffix_masks[
                    selected_from_group
                ]
                violation_score = sum(
                    (
                        max(
                            0,
                            next_profile[dimension]
                            - resource_caps[dimension],
                        )
                        + max(0, -next_profile[dimension])
                    )
                    * normalization_weights[dimension]
                    for dimension in range(4)
                )
                violated_count = sum(
                    not (
                        0
                        <= next_profile[dimension]
                        <= resource_caps[dimension]
                    )
                    for dimension in range(4)
                )
                list.append(options, (
                    (
                        violation_score,
                        violated_count,
                        selected_from_group,
                        next_profile,
                        -next_mask,
                    ),
                    next_profile,
                    next_mask,
                ))
            options.sort(key=lambda option: option[0])
            if (
                transitions_generated + len(options)
                > transition_limit
            ):
                return None, telemetry(
                    outcome="SEARCH_LIMIT_REACHED",
                    selected_count=0,
                    final_profile=None,
                    states_popped=states_popped,
                    transitions_generated=transitions_generated,
                    search_complete=False,
                    no_fit_proven=False,
                    fit_found=best_fit is not None,
                    best_fit_selected_count=(
                        best_fit[0][0] if best_fit is not None else None
                    ),
                    best_fit_profile=(
                        best_fit[2] if best_fit is not None else None
                    ),
                )
            transitions_generated += len(options)
            for _priority, next_profile, next_mask in options:
                next_group_index = group_index + 1
                state_key = (next_group_index, next_profile)
                next_selected_count = selected_count + (
                    next_mask ^ selected_mask
                ).bit_count()
                next_objective = (next_selected_count, -next_mask)
                if profile_fits(next_profile) and (
                    best_fit is None
                    or next_objective < best_fit[0]
                ):
                    best_fit = (
                        next_objective,
                        next_mask,
                        next_profile,
                    )
                prior_objective = dict.get(
                    best_objective_by_state,
                    state_key,
                )
                if (
                    (
                        prior_objective is not None
                        and prior_objective <= next_objective
                    )
                    or not suffix_can_fit(next_group_index, next_profile)
                ):
                    continue
                dict.__setitem__(
                    best_objective_by_state,
                    state_key,
                    next_objective,
                )
                next_violation_score = sum(
                    (
                        max(
                            0,
                            next_profile[dimension]
                            - resource_caps[dimension],
                        )
                        + max(0, -next_profile[dimension])
                    )
                    * normalization_weights[dimension]
                    for dimension in range(4)
                )
                heapq.heappush(
                    pending,
                    (
                        next_selected_count,
                        next_violation_score,
                        -next_mask,
                        -next_group_index,
                        next_profile,
                        next_mask,
                    ),
                )
        return None, telemetry(
            outcome="NO_FIT_PROVEN",
            selected_count=0,
            final_profile=None,
            states_popped=states_popped,
            transitions_generated=transitions_generated,
            search_complete=True,
            no_fit_proven=True,
        )

    def finish(self, parameters: Mapping[str, Any]) -> dict[str, Any]:
        if type(self) is not V2CheckCollector:
            raise EvidenceFailed("v2 assertion collector instance type drifted")
        if type(self.rows) is not list:
            raise EvidenceFailed(
                f"{self.case_id} assertion rows are not an exact list"
            )
        source_row_count = list.__len__(self.rows)
        if source_row_count == 0:
            raise EvidenceFailed(f"{self.case_id} executed no assertion checks")
        if source_row_count > V2_ASSERTION_CHECKS_CAP:
            raise EvidenceFailed(
                f"{self.case_id} exceeds the bounded assertion-check cap"
            )
        if type(self._precompacted_fields) is not dict:
            raise EvidenceFailed(
                f"{self.case_id} assertion receipt provenance is malformed"
            )
        provenance_count = dict.__len__(self._precompacted_fields)
        if provenance_count > source_row_count:
            raise EvidenceFailed(
                f"{self.case_id} assertion receipt provenance exceeds its cap"
            )
        try:
            accepted_parameters = v2_validate_exact_json_wire(
                parameters,
                label=f"{self.case_id} assertion parameters",
                item_cap=V2_ASSERTION_RESULT_EXACT_WIRE_ITEM_CAP,
                node_cap=V2_ASSERTION_RESULT_EXACT_WIRE_NODE_CAP,
                depth_cap=V2_ASSERTION_RESULT_EXACT_WIRE_DEPTH_CAP - 1,
                byte_cap=V2_LOG_LINE_BYTES_CAP,
                snapshot_byte_cap=(
                    V2_ASSERTION_RESULT_EXACT_WIRE_SNAPSHOT_BYTES_CAP
                ),
            )
        except InputRefused as error:
            raise EvidenceFailed(
                f"{self.case_id} assertion parameters are outside the "
                "exact-wire resource contract"
            ) from error
        if type(accepted_parameters) is not dict:
            raise EvidenceFailed(
                f"{self.case_id} assertion parameters are not an object"
            )
        source_rows = list(list.__iter__(self.rows))
        if (
            list.__len__(self.rows) != source_row_count
            or len(source_rows) != source_row_count
        ):
            raise EvidenceFailed(
                f"{self.case_id} assertion rows mutated during finalization"
            )
        provenance_items = list(
            dict.items(self._precompacted_fields)
        )
        if (
            dict.__len__(self._precompacted_fields) != provenance_count
            or len(provenance_items) != provenance_count
        ):
            raise EvidenceFailed(
                f"{self.case_id} assertion receipt provenance mutated "
                "during finalization"
            )
        provenance_snapshot: dict[str, dict[str, str]] = {}
        provenance_keys: set[str] = set()
        for check_id, field_roots in provenance_items:
            if (
                type(check_id) is not str
                or check_id in provenance_keys
                or type(field_roots) is not dict
                or not 1 <= dict.__len__(field_roots) <= 2
            ):
                raise EvidenceFailed(
                    f"{self.case_id} assertion receipt provenance is malformed"
                )
            field_root_items = list(dict.items(field_roots))
            if (
                len(field_root_items) != dict.__len__(field_roots)
                or not {
                    field for field, _root in field_root_items
                }.issubset({"expected", "observed"})
                or any(
                    type(field) is not str
                    or not v2_is_semantic_root(root)
                    for field, root in field_root_items
                )
            ):
                raise EvidenceFailed(
                    f"{self.case_id} assertion receipt provenance is malformed"
                )
            set.add(provenance_keys, check_id)
            provenance_snapshot[check_id] = dict(field_root_items)
        if (
            dict.__len__(self._precompacted_fields) != provenance_count
            or any(
                type(dict.get(self._precompacted_fields, check_id)) is not dict
                or list(
                    dict.items(
                        dict.get(self._precompacted_fields, check_id)
                    )
                )
                != list(dict.items(field_roots))
                for check_id, field_roots
                in dict.items(provenance_snapshot)
            )
        ):
            raise EvidenceFailed(
                f"{self.case_id} assertion receipt provenance mutated "
                "during finalization"
            )
        working_rows: list[dict[str, Any]] = []
        precompacted_field_keys: set[tuple[str, str]] = set()
        observed_check_ids: set[str] = set()
        for row_index, row in enumerate(source_rows):
            if (
                type(row) is not dict
                or dict.__len__(row) != len(V2_ASSERTION_CHECK_FIELDS)
                or set(dict.__iter__(row)) != V2_ASSERTION_CHECK_FIELDS
                or type(row["check_id"]) is not str
                or row["check_id"] in observed_check_ids
                or row["passed"] is not True
                or not v2_is_semantic_root(row["semantic_root"])
            ):
                raise EvidenceFailed(
                    f"{self.case_id} assertion row {row_index} is malformed"
                )
            v2_validate_check_id(
                row["check_id"],
                label=f"{self.case_id} assertion row {row_index}",
            )
            try:
                detached_expected = v2_validate_exact_json_wire(
                    row["expected"],
                    label=f"{self.case_id} expected evidence {row_index}",
                    item_cap=V2_ASSERTION_EVIDENCE_ITEM_CAP,
                    node_cap=V2_ASSERTION_EVIDENCE_NODE_CAP,
                    depth_cap=V2_ASSERTION_EVIDENCE_DEPTH_CAP,
                    byte_cap=V2_ASSERTION_EVIDENCE_PROJECTION_BYTES_CAP,
                    snapshot_byte_cap=(
                        V2_ASSERTION_EVIDENCE_SNAPSHOT_BYTES_CAP
                    ),
                )
                detached_observed = v2_validate_exact_json_wire(
                    row["observed"],
                    label=f"{self.case_id} observed evidence {row_index}",
                    item_cap=V2_ASSERTION_EVIDENCE_ITEM_CAP,
                    node_cap=V2_ASSERTION_EVIDENCE_NODE_CAP,
                    depth_cap=V2_ASSERTION_EVIDENCE_DEPTH_CAP,
                    byte_cap=V2_ASSERTION_EVIDENCE_PROJECTION_BYTES_CAP,
                    snapshot_byte_cap=(
                        V2_ASSERTION_EVIDENCE_SNAPSHOT_BYTES_CAP
                    ),
                )
            except (InputRefused, EvidenceFailed) as error:
                raise EvidenceFailed(
                    f"{self.case_id} assertion row is outside its rooted "
                    "evidence resource contract"
                ) from error
            detached_row = v2_rooted({
                "check_id": row["check_id"],
                "expected": detached_expected,
                "observed": detached_observed,
                "passed": True,
            })
            if detached_row["semantic_root"] != row["semantic_root"]:
                raise EvidenceFailed(
                    f"{self.case_id} assertion row mutated during finalization"
                )
            check_id = detached_row["check_id"]
            set.add(observed_check_ids, check_id)
            field_roots = dict.get(
                provenance_snapshot,
                check_id,
            )
            for field in ("expected", "observed"):
                value = detached_row[field]
                receipt_shaped = (
                    type(value) is dict
                    and dict.__len__(value) == 2
                    and set(dict.__iter__(value))
                    == {"projection_root", "canonical_bytes"}
                )
                marked_root = (
                    dict.get(field_roots, field)
                    if type(field_roots) is dict
                    else None
                )
                if receipt_shaped:
                    if (
                        marked_root is None
                        or not v2_is_semantic_root(value["projection_root"])
                        or type(value["canonical_bytes"]) is not int
                        or not 2 <= value["canonical_bytes"]
                        <= V2_ASSERTION_EVIDENCE_PROJECTION_BYTES_CAP
                        or semantic_root(value) != marked_root
                    ):
                        raise EvidenceFailed(
                            f"{self.case_id} assertion receipt provenance "
                            "differs from its bounded evidence"
                        )
                    set.add(
                        precompacted_field_keys,
                        (check_id, field),
                    )
                elif (
                    len(canonical_bytes(value))
                    > V2_ASSERTION_EVIDENCE_INLINE_BYTES_CAP
                ):
                    raise EvidenceFailed(
                        f"{self.case_id} assertion inline evidence exceeds "
                        "its bounded producer contract"
                    )
                elif marked_root is not None:
                    raise EvidenceFailed(
                        f"{self.case_id} assertion receipt provenance is stale"
                    )
            working_rows.append(detached_row)
        if provenance_keys != {
            check_id
            for check_id, _field in precompacted_field_keys
        }:
            raise EvidenceFailed(
                f"{self.case_id} assertion receipt provenance is stale"
            )
        document = V2CheckCollector._document(
            self,
            accepted_parameters,
            working_rows,
        )
        initial_canonical_bytes = len(canonical_bytes(document))
        try:
            accepted_document = v2_detach_assertion_result_wire(
                document,
                label=f"{self.case_id} assertion result",
            )
        except InputRefused:
            accepted_document = None
        if type(accepted_document) is dict:
            return accepted_document
        baseline_profile = V2CheckCollector._exact_wire_resource_profile(
            document
        )
        candidates: list[
            tuple[int, int, int, int, int, int, int, str, dict[str, Any]]
        ] = []
        for row_index, row in enumerate(working_rows):
            for field_ordinal, field in enumerate(("expected", "observed")):
                if (row["check_id"], field) in precompacted_field_keys:
                    continue
                value = row[field]
                compacted = V2CheckCollector._root_only(value)
                value_profile = (
                    V2CheckCollector._exact_wire_resource_profile(value)
                )
                compacted_profile = (
                    V2CheckCollector._exact_wire_resource_profile(compacted)
                )
                deltas = tuple(
                    compacted_value - value_value
                    for compacted_value, value_value in zip(
                        compacted_profile,
                        value_profile,
                        strict=True,
                    )
                )
                if canonical_bytes(compacted) != canonical_bytes(value):
                    if all(
                        deltas[dimension] >= 0
                        for dimension in (0, 1, 2, 4)
                    ):
                        continue
                    candidates.append((
                        *deltas,
                        row_index,
                        field_ordinal,
                        field,
                        compacted,
                    ))
        resource_caps = (
            V2_LOG_LINE_BYTES_CAP,
            V2_ASSERTION_RESULT_EXACT_WIRE_ITEM_CAP,
            V2_ASSERTION_RESULT_EXACT_WIRE_NODE_CAP,
            V2_ASSERTION_RESULT_EXACT_WIRE_DEPTH_CAP,
            V2_ASSERTION_RESULT_EXACT_WIRE_SNAPSHOT_BYTES_CAP,
        )
        if baseline_profile[3] > resource_caps[3]:
            raise EvidenceFailed(
                f"{self.case_id} assertion evidence depth envelope differs "
                "from its result-depth contract"
            )
        violated_dimensions = tuple(
            dimension
            for dimension, (observed, cap) in enumerate(
                zip(baseline_profile, resource_caps, strict=True)
            )
            if dimension != 3 and observed > cap
        )
        priority_denominators = tuple(
            max(
                1,
                baseline_profile[dimension]
                - resource_caps[dimension],
            )
            for dimension in violated_dimensions
        )
        priority_normalization = math.prod(priority_denominators)

        def candidate_priority(
            candidate: tuple[
                int,
                int,
                int,
                int,
                int,
                int,
                int,
                str,
                dict[str, Any],
            ],
        ) -> tuple[Any, ...]:
            harms = sum(
                candidate[dimension] > 0
                for dimension in violated_dimensions
            )
            progress = sum(
                max(0, -candidate[dimension])
                * (priority_normalization // denominator)
                for dimension, denominator in zip(
                    violated_dimensions,
                    priority_denominators,
                    strict=True,
                )
            )
            return (
                harms != 0,
                harms,
                -progress,
                candidate[0],
                candidate[5],
                candidate[6],
            )

        candidates.sort(key=candidate_priority)
        baseline_rows = tuple(working_rows)

        def try_candidate_indexes(
            indexes: Sequence[int],
        ) -> dict[str, Any] | None:
            predicted_profile = tuple(
                baseline_value
                + sum(
                    candidates[candidate_index][dimension]
                    for candidate_index in indexes
                )
                for dimension, baseline_value
                in enumerate(baseline_profile)
            )
            if (
                predicted_profile[0] > V2_LOG_LINE_BYTES_CAP
                or predicted_profile[1]
                > V2_ASSERTION_RESULT_EXACT_WIRE_ITEM_CAP
                or predicted_profile[2]
                > V2_ASSERTION_RESULT_EXACT_WIRE_NODE_CAP
                or predicted_profile[4]
                > V2_ASSERTION_RESULT_EXACT_WIRE_SNAPSHOT_BYTES_CAP
            ):
                return None
            trial_rows = list(baseline_rows)
            for candidate_index in indexes:
                (
                    _byte_delta,
                    _item_delta,
                    _node_delta,
                    _depth_delta,
                    _snapshot_delta,
                    row_index,
                    _ordinal,
                    field,
                    compacted,
                ) = candidates[candidate_index]
                row = dict(trial_rows[row_index])
                dict.pop(row, "semantic_root")
                dict.__setitem__(row, field, compacted)
                trial_rows[row_index] = v2_rooted(row)
            trial_document = V2CheckCollector._document(
                self,
                accepted_parameters,
                trial_rows,
            )
            try:
                candidate_document = v2_detach_assertion_result_wire(
                    trial_document,
                    label=f"{self.case_id} assertion result",
                )
            except InputRefused:
                return None
            return (
                candidate_document
                if type(candidate_document) is dict
                else None
            )

        additive_baseline_profile = (
            baseline_profile[0],
            baseline_profile[1],
            baseline_profile[2],
            baseline_profile[4],
        )
        additive_resource_caps = (
            resource_caps[0],
            resource_caps[1],
            resource_caps[2],
            resource_caps[4],
        )
        additive_candidate_deltas = tuple(
            (candidate[0], candidate[1], candidate[2], candidate[4])
            for candidate in candidates
        )
        selected_indexes, search_telemetry = (
            V2CheckCollector._select_compaction_indexes(
                additive_baseline_profile,
                additive_candidate_deltas,
                additive_resource_caps,
            )
        )
        if selected_indexes is not None:
            accepted_document = try_candidate_indexes(selected_indexes)
            if accepted_document is None:
                raise EvidenceFailed(
                    f"{self.case_id} assertion compaction resource profile "
                    "fit differed from exact result admission"
                )
            return accepted_document
        if search_telemetry["no_fit_proven"] is True:
            search_summary = (
                "complete bounded search proved that no fitting root-only "
                "evidence-field projection exists"
            )
        elif search_telemetry["fit_found"] is True:
            search_summary = (
                "bounded search found a fitting root-only evidence-field "
                "projection but reached its explicit work limit before "
                "minimum-compaction optimality was proven"
            )
        else:
            search_summary = (
                "bounded search reached its explicit work limit before a "
                "fitting root-only evidence-field projection or no-fit proof"
            )
        raise EvidenceFailed(
            f"{self.case_id} {search_summary}; "
            f"candidate_count={search_telemetry['candidate_count']}; "
            f"group_count={search_telemetry['group_count']}; "
            f"states_popped={search_telemetry['states_popped']}; "
            "transitions_generated="
            f"{search_telemetry['transitions_generated']}; "
            f"search_complete={search_telemetry['search_complete']}; "
            f"no_fit_proven={search_telemetry['no_fit_proven']}; "
            f"initial_canonical_bytes={initial_canonical_bytes}"
        )


V2_ASSERTION_COLLECTOR_CLASS_CONTRACT = V2CheckCollector
V2_FUNCTION_TYPE_CONTRACT = types.FunctionType
V2_CODE_TYPE_CONTRACT = types.CodeType
V2_FUNCTION_TYPE_DICTIONARY = type.__getattribute__(
    types.FunctionType,
    "__dict__",
)
V2_FUNCTION_CODE_DESCRIPTOR_CONTRACT = (
    V2_FUNCTION_TYPE_DICTIONARY["__code__"]
)
V2_FUNCTION_DEFAULTS_DESCRIPTOR_CONTRACT = (
    V2_FUNCTION_TYPE_DICTIONARY["__defaults__"]
)
V2_FUNCTION_KEYWORD_DEFAULTS_DESCRIPTOR_CONTRACT = (
    V2_FUNCTION_TYPE_DICTIONARY["__kwdefaults__"]
)
V2_FUNCTION_CLOSURE_DESCRIPTOR_CONTRACT = (
    V2_FUNCTION_TYPE_DICTIONARY["__closure__"]
)
V2_FUNCTION_GLOBALS_DESCRIPTOR_CONTRACT = (
    V2_FUNCTION_TYPE_DICTIONARY["__globals__"]
)
V2_ASSERTION_COLLECTOR_METHOD_NAMES = (
    "__init__",
    "_root_only",
    "_bounded_with_state",
    "_bounded",
    "check",
    "refuses",
    "_document",
    "_exact_wire_resource_profile",
    "_select_compaction_indexes",
    "finish",
)
V2_ASSERTION_COLLECTOR_CLASS_DICTIONARY = type.__getattribute__(
    V2CheckCollector,
    "__dict__",
)
V2_ASSERTION_COLLECTOR_CLASS_KEYS_CONTRACT = frozenset(
    V2_ASSERTION_COLLECTOR_CLASS_DICTIONARY
)
V2_ASSERTION_COLLECTOR_STORAGE_NAMES = (
    "case_id",
    "assertion_id",
    "rows",
    "_precompacted_fields",
)
V2_ASSERTION_COLLECTOR_STORAGE_CONTRACTS = (
    (
        "__slots__",
        V2_ASSERTION_COLLECTOR_CLASS_DICTIONARY["__slots__"],
    ),
    *(
        (
            name,
            V2_ASSERTION_COLLECTOR_CLASS_DICTIONARY[name],
        )
        for name in V2_ASSERTION_COLLECTOR_STORAGE_NAMES
    ),
)
V2_ASSERTION_COLLECTOR_DISPATCH_CONTRACTS = tuple(
    (
        name,
        V2_ASSERTION_COLLECTOR_CLASS_DICTIONARY[name],
        type.__getattribute__(V2CheckCollector, name),
    )
    for name in V2_ASSERTION_COLLECTOR_METHOD_NAMES
)
V2_ASSERTION_COLLECTOR_CLASS_METADATA_CONTRACTS = tuple(
    (name, value)
    for name, value in V2_ASSERTION_COLLECTOR_CLASS_DICTIONARY.items()
    if name not in {
        "__slots__",
        *V2_ASSERTION_COLLECTOR_STORAGE_NAMES,
        *V2_ASSERTION_COLLECTOR_METHOD_NAMES,
    }
)
V2_ASSERTION_COLLECTOR_CODE_CONTRACTS = tuple(
    (candidate, candidate.__code__)
    for _name, _descriptor, candidate
    in V2_ASSERTION_COLLECTOR_DISPATCH_CONTRACTS
)
V2_ASSERTION_COLLECTOR_DEFAULT_CONTRACTS = tuple(
    (
        candidate,
        candidate.__defaults__,
        candidate.__kwdefaults__,
        (
            tuple(dict.items(candidate.__kwdefaults__))
            if type(candidate.__kwdefaults__) is dict
            else None
        ),
    )
    for candidate, _code in V2_ASSERTION_COLLECTOR_CODE_CONTRACTS
)
V2_ASSERTION_COLLECTOR_REFUSES_CLOSURE = (
    V2CheckCollector.refuses.__closure__ or ()
)
V2_ASSERTION_COLLECTOR_REFUSES_CLOSURE_CONTRACTS = tuple(
    (
        cell,
        cell.cell_contents,
        cell.cell_contents.__code__,
        cell.cell_contents.__defaults__,
        cell.cell_contents.__kwdefaults__,
        (
            tuple(dict.items(cell.cell_contents.__kwdefaults__))
            if type(cell.cell_contents.__kwdefaults__) is dict
            else None
        ),
    )
    for cell in V2_ASSERTION_COLLECTOR_REFUSES_CLOSURE
    if type(cell.cell_contents) is types.FunctionType
)


def v2_require_fixture_resource_cap(
    value: int,
    cap: int,
    *,
    diagnostic: str,
) -> None:
    """Enforce one exact inclusive selected-resource boundary."""
    if type(value) is not int or value < 0:
        raise EvidenceFailed(
            "fixture resource cap observation is not a non-negative exact integer"
        )
    if type(cap) is not int or cap < 0:
        raise InfrastructureFailed(
            "fixture resource cap is not a non-negative exact integer"
        )
    if type(diagnostic) is not str or not diagnostic:
        raise InfrastructureFailed(
            "fixture resource cap diagnostic is malformed"
        )
    if value > cap:
        raise EvidenceFailed(diagnostic)


def v2_fixture_callback_data_projection(value: Any) -> Any:
    """Project one selected-resource callback through the mature graph."""
    context = v2_new_refusal_projection_context(
        {
            "scalar_bytes": V2_FIXTURE_RESOURCE_ADDITIONAL_STATE_BYTES_CAP,
            "projection_bytes": (
                V2_FIXTURE_RESOURCE_ADDITIONAL_STATE_BYTES_CAP
            ),
        },
        authorized_external_capabilities=(
            V2_FIXTURE_SELECTED_RESOURCE_CAPABILITY,
        ),
    )
    projection = v2_state_projection_value(value, context=context)
    v2_validate_refusal_projection_graph(projection)
    if v2_projection_contains_opaque(projection):
        raise EvidenceFailed(
            "fixture callback contains unprojectable opaque state"
        )
    try:
        payload = canonical_bytes(projection)
    except (TypeError, ValueError, UnicodeEncodeError) as error:
        raise EvidenceFailed(
            "fixture callback projection is not canonical JSON data"
        ) from error
    v2_require_fixture_resource_cap(
        len(payload),
        V2_FIXTURE_RESOURCE_ADDITIONAL_STATE_BYTES_CAP,
        diagnostic="fixture callback data exceeds its projection byte cap",
    )
    return projection


def v2_fixture_additional_state_projection(value: Any) -> Any:
    """Return a stable, bounded, occurrence-detached JSON-like tree."""
    try:
        return v2_validate_exact_json_wire(
            value,
            label="fixture additional state",
            item_cap=V2_REFUSAL_ITEM_CAP,
            node_cap=V2_REFUSAL_ITEM_CAP + 1,
            depth_cap=V2_REFUSAL_STATE_DEPTH_CAP,
            byte_cap=V2_FIXTURE_RESOURCE_ADDITIONAL_STATE_BYTES_CAP,
            snapshot_byte_cap=(
                V2_FIXTURE_RESOURCE_ADDITIONAL_STATE_SNAPSHOT_BYTES_CAP
            ),
        )
    except InputRefused as error:
        diagnostic, exact = v2_exception_diagnostic(error)
        if not exact:
            raise EvidenceFailed(
                "fixture additional state was refused without an exact diagnostic"
            ) from error
        raise EvidenceFailed(diagnostic) from error


def v2_fixture_descriptor_names(
    candidate_directories: tuple[str, ...] = (
        "/dev/fd",
        "/proc/self/fd",
    ),
    *,
    list_directory: Callable[[str], list[str]] = os.listdir,
) -> tuple[str, list[str]]:
    if type(candidate_directories) is not tuple or not candidate_directories:
        raise EvidenceFailed(
            "fixture descriptor census candidates are malformed"
        )
    v2_require_fixture_resource_cap(
        len(candidate_directories),
        V2_FIXTURE_RESOURCE_DESCRIPTOR_CANDIDATES_CAP,
        diagnostic=(
            "fixture descriptor census candidate count exceeds its cap"
        ),
    )
    for path in candidate_directories:
        if type(path) is not str or not path:
            raise EvidenceFailed(
                "fixture descriptor census candidates are malformed"
            )
        if len(path) > V2_FIXTURE_RESOURCE_DESCRIPTOR_CANDIDATE_PATH_BYTES_CAP:
            raise EvidenceFailed(
                "fixture descriptor census candidate path exceeds its byte cap"
            )
        try:
            path_bytes = str.encode(path, "utf-8")
        except UnicodeEncodeError as error:
            raise EvidenceFailed(
                "fixture descriptor census candidate path is not valid UTF-8"
            ) from error
        v2_require_fixture_resource_cap(
            len(path_bytes),
            V2_FIXTURE_RESOURCE_DESCRIPTOR_CANDIDATE_PATH_BYTES_CAP,
            diagnostic=(
                "fixture descriptor census candidate path exceeds its byte cap"
            ),
        )
    unavailable_errors: list[OSError] = []
    for directory in candidate_directories:
        try:
            names = list_directory(directory)
        except OSError as error:
            if error.errno in {
                errno.ENOENT,
                errno.ENOTDIR,
                errno.EACCES,
                errno.EPERM,
            }:
                unavailable_errors.append(error)
                continue
            raise InfrastructureFailed(
                "fixture resource descriptor census failed"
            ) from error
        if (
            type(names) is not list
            or any(type(name) is not str for name in names)
        ):
            raise InfrastructureFailed(
                "fixture resource descriptor census returned malformed names"
            )
        v2_require_fixture_resource_cap(
            len(names),
            V2_FIXTURE_RESOURCE_DESCRIPTOR_ENTRIES_CAP,
            diagnostic=(
                "fixture resource descriptor census exceeds its bounded cap"
            ),
        )
        return directory, names
    raise InfrastructureFailed(
        "fixture resource descriptor census is unavailable on this host"
    ) from unavailable_errors[0]


def v2_bounded_process_environment_bytes_snapshot() -> dict[bytes, bytes]:
    """Capture the live Python bytes environment without an unbounded copy."""
    environment = os.environb
    try:
        declared_count = len(environment)
    except Exception as error:
        raise EvidenceFailed(
            "fixture resource environment changed while being captured"
        ) from error
    v2_require_fixture_resource_cap(
        declared_count,
        V2_FIXTURE_RESOURCE_ENVIRONMENT_ENTRIES_CAP,
        diagnostic="fixture resource environment entry count exceeds its cap",
    )
    snapshot: dict[bytes, bytes] = {}
    raw_bytes = 0
    try:
        for key in environment:
            if len(snapshot) >= V2_FIXTURE_RESOURCE_ENVIRONMENT_ENTRIES_CAP:
                raise EvidenceFailed(
                    "fixture resource environment entry count exceeds its cap"
                )
            value = environment[key]
            if type(key) is not bytes or type(value) is not bytes:
                raise EvidenceFailed(
                    "fixture resource environment contains non-exact bytes"
                )
            if key in snapshot:
                raise EvidenceFailed(
                    "fixture resource environment changed while being captured"
                )
            entry_bytes = len(key) + len(value)
            if entry_bytes > (
                V2_FIXTURE_RESOURCE_ENVIRONMENT_BYTES_CAP - raw_bytes
            ):
                raise EvidenceFailed(
                    "fixture resource environment bytes exceed their cap"
                )
            raw_bytes += entry_bytes
            snapshot[key] = value
    except EvidenceFailed:
        raise
    except Exception as error:
        raise EvidenceFailed(
            "fixture resource environment changed while being captured"
        ) from error
    verified_keys: dict[bytes, None] = {}
    try:
        if os.environb is not environment:
            raise EvidenceFailed(
                "fixture resource environment changed while being captured"
            )
        for key in environment:
            if len(verified_keys) >= (
                V2_FIXTURE_RESOURCE_ENVIRONMENT_ENTRIES_CAP
            ):
                raise EvidenceFailed(
                    "fixture resource environment entry count exceeds its cap"
                )
            value = environment[key]
            if (
                type(key) is not bytes
                or type(value) is not bytes
                or key in verified_keys
                or not dict.__contains__(snapshot, key)
                or value != dict.__getitem__(snapshot, key)
            ):
                raise EvidenceFailed(
                    "fixture resource environment changed while being captured"
                )
            verified_keys[key] = None
        final_count = len(environment)
    except EvidenceFailed:
        raise
    except Exception as error:
        raise EvidenceFailed(
            "fixture resource environment changed while being captured"
        ) from error
    if (
        len(snapshot) != declared_count
        or len(verified_keys) != declared_count
        or final_count != declared_count
        or tuple(snapshot) != tuple(verified_keys)
    ):
        raise EvidenceFailed(
            "fixture resource environment changed while being captured"
        )
    return snapshot


# This helper is defined after the primary callable registry because the
# resource guard itself lives later in the harness.  Bind its exact identity
# once it exists; no name-, module-, or signature-based capability matching is
# permitted.
V2_FIXTURE_EXECUTABLE_INTERNAL_CAPABILITIES += ((
    v2_bounded_process_environment_bytes_snapshot,
    frozenset({"process-python-environment"}),
),)
V2_BOUNDED_PROCESS_ENVIRONMENT_SNAPSHOT_CALLABLE = (
    v2_bounded_process_environment_bytes_snapshot
)
V2_AUDITED_LOCAL_PURE_CALL_RESULT_PATHS += ((
    v2_bounded_process_environment_bytes_snapshot,
    frozenset({
        V2_DERIVED_CALL_RESULT_PATH[0],
        "dict-get-value",
    }),
),)
V2_AUDITED_LOCAL_PURE_CALL_CODE_CONTRACTS += ((
    v2_bounded_process_environment_bytes_snapshot,
    v2_bounded_process_environment_bytes_snapshot.__code__,
),)


def v2_exact_fixture_resource_paths_snapshot(
    paths: Sequence[Path],
) -> tuple[Path, ...]:
    """Copy an exact list/tuple under the path cap without user hooks."""
    if type(paths) not in {list, tuple}:
        raise EvidenceFailed(
            "fixture resource paths must use an exact bounded sequence"
        )
    declared_count = len(paths)
    v2_require_fixture_resource_cap(
        declared_count,
        V2_FIXTURE_RESOURCE_PATHS_CAP,
        diagnostic="fixture resource path count exceeds its bounded cap",
    )
    exact_getitem = (
        list.__getitem__ if type(paths) is list else tuple.__getitem__
    )
    snapshot: list[Path] = []
    try:
        for index in range(declared_count):
            if len(paths) != declared_count:
                raise EvidenceFailed(
                    "fixture resource paths changed while being captured"
                )
            path = exact_getitem(paths, index)
            if type(path) is not type(REPO_ROOT):
                raise EvidenceFailed(
                    "fixture resource path must use the exact repository path type"
                )
            list.append(snapshot, path)
    except EvidenceFailed:
        raise
    except (IndexError, RuntimeError) as error:
        raise EvidenceFailed(
            "fixture resource paths changed while being captured"
        ) from error
    if len(paths) != declared_count:
        raise EvidenceFailed(
            "fixture resource paths changed while being captured"
        )
    try:
        if len(paths) != declared_count:
            raise EvidenceFailed(
                "fixture resource paths changed while being captured"
            )
        for index in range(declared_count):
            if exact_getitem(paths, index) is not snapshot[index]:
                raise EvidenceFailed(
                    "fixture resource paths changed while being captured"
                )
        if len(paths) != declared_count:
            raise EvidenceFailed(
                "fixture resource paths changed while being captured"
            )
    except EvidenceFailed:
        raise
    except (IndexError, RuntimeError) as error:
        raise EvidenceFailed(
            "fixture resource paths changed while being captured"
        ) from error
    return tuple(snapshot)


def v2_fixture_resource_state(
    paths: Sequence[Path],
    *,
    additional_state: Callable[[], Any] | None = None,
) -> dict[str, Any]:
    """Capture bounded semantic state for fixture-backed refusal checks.

    These checks intentionally exercise selected descriptor and filesystem
    behavior outside the general callback graph. The projection binds each
    named resource itself, the live descriptor census, Python's environment
    mapping, cwd, recursion limit, harness state, and callback defaults/closure
    data. It does not claim directory-descendant membership, native-only
    ``putenv`` state, descriptor offsets, or unrelated filesystem state.
    """
    path_snapshot = v2_exact_fixture_resource_paths_snapshot(paths)
    prepared_paths: list[
        tuple[
            bytes,
            str,
            Path,
            tuple[
                tuple[int, ...],
                tuple[tuple[str, int, int, int], ...],
            ],
        ]
    ] = []
    seen_paths: set[str] = set()
    for path in path_snapshot:
        relative, binding = v2_fixture_capture_anchored_resource_binding(
            path
        )
        try:
            relative_bytes = str.encode(relative, "utf-8")
        except UnicodeEncodeError as error:
            raise EvidenceFailed(
                "fixture resource relative path is not valid UTF-8"
            ) from error
        v2_require_fixture_resource_cap(
            len(relative_bytes),
            V2_FIXTURE_RESOURCE_PATH_BYTES_CAP,
            diagnostic=(
                "fixture resource relative path exceeds its byte cap"
            ),
        )
        if relative in seen_paths:
            raise EvidenceFailed("fixture resource paths contain a duplicate")
        seen_paths.add(relative)
        prepared_paths.append(
            (relative_bytes, relative, path, binding)
        )

    rows: list[dict[str, Any]] = []
    total_file_bytes = 0
    for (
        _relative_bytes,
        relative,
        path,
        binding,
    ) in sorted(prepared_paths, key=lambda item: item[0]):
        expected_identity, expected_parents = (
            v2_fixture_require_bound_resource_binding(binding)
        )
        parent_slot: list[int | None] = [None]
        descriptor_slot: list[int | None] = [None]
        verification_parent_slot: list[int | None] = [None]
        symlink_target_bytes: bytes | None = None
        resource_succeeded = False
        try:
            leaf = v2_fixture_open_anchored_parent(
                relative,
                expected_parents,
                parent_slot,
            )
            parent_descriptor = list.__getitem__(parent_slot, 0)
            if parent_descriptor is None:
                raise EvidenceFailed(
                    "fixture resource parent descriptor ownership was lost"
                )
            try:
                state = (
                    os.fstat(parent_descriptor)
                    if leaf is None
                    else os.stat(
                        leaf,
                        dir_fd=parent_descriptor,
                        follow_symlinks=False,
                    )
                )
            except OSError as error:
                raise EvidenceFailed(
                    f"fixture resource metadata read failed: {relative}"
                ) from error
            v2_fixture_require_bound_stat_identity(
                state,
                expected_identity,
            )
            row: dict[str, Any] = {
                "path": relative,
                "identity": {
                    "device": state.st_dev,
                    "inode": state.st_ino,
                    "mode": state.st_mode,
                    "link_count": state.st_nlink,
                    "change_time_ns": state.st_ctime_ns,
                },
            }
            if stat.S_ISREG(state.st_mode):
                if leaf is None:
                    raise EvidenceFailed(
                        "fixture resource regular file has no anchored leaf"
                    )
                v2_require_fixture_resource_cap(
                    state.st_size,
                    V2_FIXTURE_RESOURCE_FILE_BYTES_CAP,
                    diagnostic=(
                        "fixture resource file exceeds its byte cap: "
                        f"{relative}"
                    ),
                )
                total_file_bytes += state.st_size
                v2_require_fixture_resource_cap(
                    total_file_bytes,
                    V2_FIXTURE_RESOURCE_TOTAL_FILE_BYTES_CAP,
                    diagnostic=(
                        "fixture resource aggregate file bytes exceed their "
                        "cap"
                    ),
                )
                try:
                    resource_read_flags = (
                        os.O_RDONLY
                        | os.O_CLOEXEC
                        | os.O_NONBLOCK
                        | os.O_NOFOLLOW
                    )
                    list.__setitem__(descriptor_slot, 0, os.open(leaf, resource_read_flags, dir_fd=parent_descriptor))
                    descriptor = list.__getitem__(descriptor_slot, 0)
                    if descriptor is None:
                        raise EvidenceFailed(
                            "fixture resource descriptor ownership was lost"
                        )
                    descriptor_before = os.fstat(descriptor)
                    identity_before = v2_fixture_stat_identity_tuple(
                        descriptor_before
                    )
                    if identity_before != expected_identity:
                        raise EvidenceFailed(
                            "fixture resource changed before fingerprinting "
                            f"{relative}"
                        )
                    chunks: list[bytes] = []
                    offset = 0
                    while offset < descriptor_before.st_size:
                        chunk = os.pread(
                            descriptor,
                            min(
                                64 * 1024,
                                descriptor_before.st_size - offset,
                            ),
                            offset,
                        )
                        if not chunk:
                            break
                        chunks.append(chunk)
                        offset += len(chunk)
                    payload = b"".join(chunks)
                    descriptor_after = os.fstat(descriptor)
                    identity_after = v2_fixture_stat_identity_tuple(
                        descriptor_after
                    )
                except OSError as error:
                    raise EvidenceFailed(
                        "fixture resource fingerprint read failed: "
                        f"{relative}"
                    ) from error
                if (
                    len(payload) != state.st_size
                    or identity_after != identity_before
                ):
                    raise EvidenceFailed(
                        "fixture resource changed while fingerprinting "
                        f"{relative}"
                    )
                row.update({
                    "kind": "regular-file",
                    "size": state.st_size,
                    "mtime_ns": state.st_mtime_ns,
                    "content_root": (
                        "sha256-v1:" + hashlib.sha256(payload).hexdigest()
                    ),
                })
            elif stat.S_ISDIR(state.st_mode):
                row.update({
                    "kind": "directory",
                    "size": state.st_size,
                    "mtime_ns": state.st_mtime_ns,
                })
            elif stat.S_ISLNK(state.st_mode):
                if leaf is None:
                    raise EvidenceFailed(
                        "fixture resource symbolic link has no anchored leaf"
                    )
                try:
                    target = os.readlink(
                        leaf,
                        dir_fd=parent_descriptor,
                    )
                except OSError as error:
                    raise EvidenceFailed(
                        "fixture resource symbolic-link read failed: "
                        f"{relative}"
                    ) from error
                target_bytes = os.fsencode(target)
                symlink_target_bytes = target_bytes
                try:
                    str.encode(target, "utf-8")
                    target_display: str | None = target
                    target_encoding = "utf-8"
                except UnicodeEncodeError:
                    target_display = None
                    target_encoding = "posix-bytes"
                v2_require_fixture_resource_cap(
                    len(target_bytes),
                    V2_FIXTURE_RESOURCE_SYMLINK_BYTES_CAP,
                    diagnostic=(
                        "fixture resource symlink target exceeds its cap: "
                        f"{relative}"
                    ),
                )
                row.update({
                    "kind": "symbolic-link",
                    "size": state.st_size,
                    "mtime_ns": state.st_mtime_ns,
                    "target": target_display,
                    "target_encoding": target_encoding,
                    "target_byte_length": len(target_bytes),
                    "target_root": (
                        "sha256-v1:"
                        + hashlib.sha256(target_bytes).hexdigest()
                    ),
                })
            else:
                row.update({
                    "kind": "other",
                    "size": state.st_size,
                    "mtime_ns": state.st_mtime_ns,
                })
            try:
                final_state = (
                    os.fstat(parent_descriptor)
                    if leaf is None
                    else os.stat(
                        leaf,
                        dir_fd=parent_descriptor,
                        follow_symlinks=False,
                    )
                )
            except OSError as error:
                raise EvidenceFailed(
                    f"fixture resource metadata recheck failed: {relative}"
                ) from error
            v2_fixture_require_bound_stat_identity(
                final_state,
                expected_identity,
            )
            verification_leaf = v2_fixture_open_anchored_parent(
                relative,
                expected_parents,
                verification_parent_slot,
            )
            if verification_leaf != leaf:
                raise EvidenceFailed(
                    "fixture resource leaf changed while fingerprinting "
                    f"{relative}"
                )
            try:
                verification_parent_descriptor = list.__getitem__(
                    verification_parent_slot,
                    0,
                )
                if verification_parent_descriptor is None:
                    raise EvidenceFailed(
                        "fixture resource verification-parent descriptor "
                        "ownership was lost"
                    )
                verification_state = (
                    os.fstat(verification_parent_descriptor)
                    if verification_leaf is None
                    else os.stat(
                        verification_leaf,
                        dir_fd=verification_parent_descriptor,
                        follow_symlinks=False,
                    )
                )
            except OSError as error:
                raise EvidenceFailed(
                    "fixture resource final metadata verification failed: "
                    f"{relative}"
                ) from error
            v2_fixture_require_bound_stat_identity(
                verification_state,
                expected_identity,
            )
            if stat.S_ISLNK(verification_state.st_mode):
                if verification_leaf is None or symlink_target_bytes is None:
                    raise EvidenceFailed(
                        "fixture resource symbolic-link verification lost its "
                        "bound target"
                    )
                try:
                    verification_target_bytes = os.fsencode(os.readlink(
                        verification_leaf,
                        dir_fd=verification_parent_descriptor,
                    ))
                except OSError as error:
                    raise EvidenceFailed(
                        "fixture resource symbolic-link target recheck failed: "
                        f"{relative}"
                    ) from error
                if verification_target_bytes != symlink_target_bytes:
                    raise EvidenceFailed(
                        "fixture resource symbolic-link target changed while "
                        f"fingerprinting {relative}"
                    )
            resource_succeeded = True
        finally:
            v2_close_owned_descriptor_slots((
                (
                    descriptor_slot,
                    EvidenceFailed(
                        "fixture resource descriptor close failed: "
                        f"{relative}"
                    ),
                ),
                (
                    verification_parent_slot,
                    EvidenceFailed(
                        "fixture resource verification-parent descriptor "
                        "close failed"
                    ),
                ),
                (
                    parent_slot,
                    EvidenceFailed(
                        "fixture resource parent descriptor close failed"
                    ),
                ),
            ), surface_failure=resource_succeeded)
        rows.append(row)
    descriptor_census_source, descriptor_names = (
        v2_fixture_descriptor_names()
    )
    descriptors: list[dict[str, int]] = []
    seen_descriptor_names: dict[str, None] = {}
    maximum_descriptor_name = str(V2_FIXTURE_RESOURCE_DESCRIPTOR_MAX)
    for descriptor_name in descriptor_names:
        if (
            len(descriptor_name) > len(maximum_descriptor_name)
            or not str.isascii(descriptor_name)
            or not str.isdigit(descriptor_name)
            or (
                len(descriptor_name) > 1
                and str.startswith(descriptor_name, "0")
            )
            or (
                len(descriptor_name) == len(maximum_descriptor_name)
                and descriptor_name > maximum_descriptor_name
            )
            or descriptor_name in seen_descriptor_names
        ):
            raise InfrastructureFailed(
                "fixture resource descriptor census returned a malformed name"
            )
        dict.__setitem__(seen_descriptor_names, descriptor_name, None)
        try:
            descriptor = int(descriptor_name, 10)
        except ValueError as error:
            raise InfrastructureFailed(
                "fixture resource descriptor census returned a malformed name"
            ) from error
        if descriptor > V2_FIXTURE_RESOURCE_DESCRIPTOR_MAX:
            raise InfrastructureFailed(
                "fixture resource descriptor census returned a malformed name"
            )
        try:
            descriptor_state = os.fstat(descriptor)
            descriptor_flags = fcntl.fcntl(descriptor, fcntl.F_GETFD)
            status_flags = fcntl.fcntl(descriptor, fcntl.F_GETFL)
        except OverflowError as error:
            raise InfrastructureFailed(
                "fixture resource descriptor census returned a malformed name"
            ) from error
        except OSError as error:
            if error.errno in {errno.EBADF, errno.ENOENT}:
                # /dev/fd can enumerate its own already-closed directory
                # descriptor. Only descriptors still live after enumeration
                # belong to the stable process state.
                continue
            raise EvidenceFailed(
                "fixture resource descriptor census failed"
            ) from error
        descriptors.append({
            "descriptor": descriptor,
            "device": descriptor_state.st_dev,
            "inode": descriptor_state.st_ino,
            "mode": descriptor_state.st_mode,
            "change_time_ns": descriptor_state.st_ctime_ns,
            "descriptor_flags": descriptor_flags,
            "status_flags": status_flags,
        })
    descriptors.sort(key=lambda row: row["descriptor"])
    environment_is_pinned = (
        os.environ is V2_INITIAL_PROCESS_ENVIRONMENT
        and os.environb is V2_INITIAL_PROCESS_ENVIRONMENT_BYTES
    )
    environment_attributes_pinned = (
        environment_is_pinned
        and v2_exact_instance_dictionary_matches(
            V2_INITIAL_PROCESS_ENVIRONMENT,
            V2_INITIAL_PROCESS_ENVIRONMENT_ATTRIBUTES,
            label="fixture process environment",
        )
        and v2_exact_instance_dictionary_matches(
            V2_INITIAL_PROCESS_ENVIRONMENT_BYTES,
            V2_INITIAL_PROCESS_ENVIRONMENT_BYTES_ATTRIBUTES,
            label="fixture byte process environment",
        )
    )
    environment_backing_pinned = (
        environment_is_pinned
        and v2_process_environment_backing_is_pinned()
    )
    environment_rows: list[dict[str, Any]] = []
    if environment_is_pinned:
        environment_snapshot = (
            v2_bounded_process_environment_bytes_snapshot()
        )
        environment_rows = [
            {
                "key_byte_length": len(key),
                "key_root": "sha256-v1:" + hashlib.sha256(key).hexdigest(),
                "value_byte_length": len(value),
                "value_root": "sha256-v1:" + hashlib.sha256(value).hexdigest(),
            }
            for key, value in dict.items(environment_snapshot)
        ]
    _, command_receipt_payload = v2_capture_command_receipt_state()
    if type(_cancel_signal_epoch) is not int or _cancel_signal_epoch < 0:
        raise EvidenceFailed("fixture resource cancellation epoch is malformed")
    if additional_state is None:
        extra = None
    else:
        additional_cwd = os.getcwdb()
        additional_environment_object = os.environ
        additional_environment_bytes_object = os.environb
        additional_environment_attributes = (
            v2_exact_instance_dictionary_snapshot(
                additional_environment_object,
                label="additional-state process environment",
            )
        )
        additional_environment_bytes_attributes = (
            v2_exact_instance_dictionary_snapshot(
                additional_environment_bytes_object,
                label="additional-state byte process environment",
            )
        )
        additional_environment_entries = tuple(dict.items(
            v2_bounded_process_environment_bytes_snapshot()
        ))
        additional_recursion_limit = sys.getrecursionlimit()
        _, additional_receipt_payload = v2_capture_command_receipt_state()
        additional_cancel_requested = _cancel_requested
        additional_cancel_epoch = _cancel_signal_epoch
        try:
            additional_value = additional_state()
        except HarnessError:
            raise
        except Exception as error:
            raise EvidenceFailed(
                "fixture resource additional-state callback failed"
            ) from error
        if (
            os.getcwdb() != additional_cwd
            or os.environ is not additional_environment_object
            or os.environb is not additional_environment_bytes_object
            or not v2_exact_instance_dictionary_matches(
                additional_environment_object,
                additional_environment_attributes,
                label="additional-state restored process environment",
            )
            or not v2_exact_instance_dictionary_matches(
                additional_environment_bytes_object,
                additional_environment_bytes_attributes,
                label="additional-state restored byte process environment",
            )
            or tuple(dict.items(
                v2_bounded_process_environment_bytes_snapshot()
            )) != additional_environment_entries
            or sys.getrecursionlimit() != additional_recursion_limit
            or v2_capture_command_receipt_state()[1]
            != additional_receipt_payload
            or _cancel_requested is not additional_cancel_requested
            or _cancel_signal_epoch != additional_cancel_epoch
        ):
            raise EvidenceFailed(
                "fixture resource additional-state callback mutated process state"
            )
        extra = v2_fixture_additional_state_projection(additional_value)
    try:
        process_cwd = os.getcwdb()
    except OSError as error:
        raise EvidenceFailed(
            "fixture resource process cwd capture failed"
        ) from error
    projection = {
        "paths": rows,
        "descriptor_census_source": descriptor_census_source,
        "open_descriptors": descriptors,
        "process_cwd": {
            "byte_length": len(process_cwd),
            "content_root": (
                "sha256-v1:" + hashlib.sha256(process_cwd).hexdigest()
            ),
        },
        "process_python_environment_is_pinned": environment_is_pinned,
        "process_python_environment_attributes_are_pinned": (
            environment_attributes_pinned
        ),
        "process_python_environment_backing_is_pinned": (
            environment_backing_pinned
        ),
        "process_python_environment": environment_rows,
        "process_recursion_limit": sys.getrecursionlimit(),
        "additional_state": extra,
        "command_receipt_count": len(_command_receipts),
        "command_receipt_content_root": (
            "sha256-v1:" + hashlib.sha256(command_receipt_payload).hexdigest()
        ),
        "command_receipt_list_binding_is_pinned": (
            _command_receipts is V2_INITIAL_COMMAND_RECEIPTS
        ),
        "cancel_requested": _cancel_requested,
        "cancel_signal_epoch": _cancel_signal_epoch,
    }
    projection_payload = canonical_bytes(projection)
    v2_require_fixture_resource_cap(
        len(projection_payload),
        V2_FIXTURE_RESOURCE_PROJECTION_BYTES_CAP,
        diagnostic=(
            "fixture resource state exceeds its aggregate projection byte cap"
        ),
    )
    final_path_snapshot = v2_exact_fixture_resource_paths_snapshot(paths)
    if len(final_path_snapshot) != len(path_snapshot) or any(
        final_path_snapshot[index] is not path_snapshot[index]
        for index in range(len(path_snapshot))
    ):
        raise EvidenceFailed(
            "fixture resource paths changed while being captured"
        )
    return projection


def v2_exact_instance_dictionary_snapshot(
    value: Any,
    *,
    label: str,
) -> tuple[tuple[str, Any], ...]:
    raw = v2_raw_instance_dictionary(value)
    if raw is None or any(type(key) is not str for key in dict.keys(raw)):
        raise EvidenceFailed(f"{label} lacks an exact string-keyed dictionary")
    return tuple(dict.items(raw))


def v2_exact_instance_dictionary_matches(
    value: Any,
    snapshot: Any,
    *,
    label: str,
) -> bool:
    if type(snapshot) is not tuple:
        raise EvidenceFailed(f"{label} snapshot is not an exact tuple")
    raw = v2_raw_instance_dictionary(value)
    if raw is None:
        raise EvidenceFailed(f"{label} lost its exact instance dictionary")
    current_rows = tuple(dict.items(raw))
    if tuple.__len__(current_rows) != tuple.__len__(snapshot):
        return False
    for index in range(tuple.__len__(snapshot)):
        expected_row = tuple.__getitem__(snapshot, index)
        current_row = tuple.__getitem__(current_rows, index)
        if (
            type(expected_row) is not tuple
            or tuple.__len__(expected_row) != 2
            or type(current_row) is not tuple
            or tuple.__len__(current_row) != 2
        ):
            raise EvidenceFailed(f"{label} snapshot row is malformed")
        expected_key = tuple.__getitem__(expected_row, 0)
        expected_value = tuple.__getitem__(expected_row, 1)
        current_key = tuple.__getitem__(current_row, 0)
        current_value = tuple.__getitem__(current_row, 1)
        if type(expected_key) is not str:
            raise EvidenceFailed(f"{label} snapshot has a non-string key")
        if current_key != expected_key or current_value is not expected_value:
            return False
    return True


def v2_exact_instance_dictionary_snapshots_match(
    left: Any,
    right: Any,
    *,
    label: str,
) -> bool:
    if type(left) is not tuple or type(right) is not tuple:
        raise EvidenceFailed(f"{label} snapshots are not exact tuples")
    if tuple.__len__(left) != tuple.__len__(right):
        return False
    for index in range(tuple.__len__(left)):
        left_row = tuple.__getitem__(left, index)
        right_row = tuple.__getitem__(right, index)
        if (
            type(left_row) is not tuple
            or tuple.__len__(left_row) != 2
            or type(right_row) is not tuple
            or tuple.__len__(right_row) != 2
        ):
            raise EvidenceFailed(f"{label} snapshot row is malformed")
        left_key = tuple.__getitem__(left_row, 0)
        right_key = tuple.__getitem__(right_row, 0)
        if type(left_key) is not str or type(right_key) is not str:
            raise EvidenceFailed(f"{label} snapshot key is malformed")
        if (
            left_key != right_key
            or tuple.__getitem__(left_row, 1)
            is not tuple.__getitem__(right_row, 1)
        ):
            return False
    return True


def v2_restore_exact_instance_dictionary(
    value: Any,
    snapshot: Any,
    *,
    label: str,
) -> None:
    if type(snapshot) is not tuple:
        raise EvidenceFailed(f"{label} snapshot is not an exact tuple")
    raw = v2_raw_instance_dictionary(value)
    if raw is None:
        raise EvidenceFailed(f"{label} lost its exact instance dictionary")
    validated_rows: tuple[tuple[str, Any], ...] = ()
    for row in snapshot:
        if type(row) is not tuple or tuple.__len__(row) != 2:
            raise EvidenceFailed(f"{label} snapshot row is malformed")
        key = tuple.__getitem__(row, 0)
        item = tuple.__getitem__(row, 1)
        if type(key) is not str:
            raise EvidenceFailed(f"{label} snapshot has a non-string key")
        validated_rows = (*validated_rows, (key, item))
    for key in list(dict.keys(raw)):
        dict.__delitem__(raw, key)
    for key, item in validated_rows:
        dict.__setitem__(raw, key, item)
    if not v2_exact_instance_dictionary_matches(
        value,
        validated_rows,
        label=label,
    ):
        raise EvidenceFailed(f"{label} exact restoration did not converge")


def v2_restore_process_environment(
    saved_environment: Any,
    saved_environment_bytes: Any,
    saved_environment_attributes: Any,
    saved_environment_bytes_attributes: Any,
    saved_environment_entries: Any,
) -> None:
    if (
        saved_environment is not V2_INITIAL_PROCESS_ENVIRONMENT
        or saved_environment_bytes
        is not V2_INITIAL_PROCESS_ENVIRONMENT_BYTES
        or type(saved_environment_entries) is not dict
        or any(
            type(key) is not bytes or type(value) is not bytes
            for key, value in dict.items(saved_environment_entries)
        )
    ):
        raise EvidenceFailed("saved process environment contract is malformed")
    v2_exact_instance_dictionary_snapshots_match(
        saved_environment_attributes,
        saved_environment_attributes,
        label="saved process environment",
    )
    v2_exact_instance_dictionary_snapshots_match(
        saved_environment_bytes_attributes,
        saved_environment_bytes_attributes,
        label="saved byte process environment",
    )

    def restore_string_attributes() -> None:
        v2_restore_exact_instance_dictionary(
            saved_environment,
            saved_environment_attributes,
            label="saved process environment",
        )

    def restore_bytes_attributes() -> None:
        v2_restore_exact_instance_dictionary(
            saved_environment_bytes,
            saved_environment_bytes_attributes,
            label="saved byte process environment",
        )

    def restore_bindings() -> None:
        os.environ = saved_environment
        os.environb = saved_environment_bytes

    def restore_entries() -> None:
        current_keys = tuple(saved_environment_bytes)
        for key in current_keys:
            if type(key) is not bytes:
                raise EvidenceFailed(
                    "live process environment key is not exact bytes"
                )
            del saved_environment_bytes[key]
        for key, value in dict.items(saved_environment_entries):
            saved_environment_bytes[key] = value

    def verify_environment() -> None:
        if (
            os.environ is not saved_environment
            or os.environb is not saved_environment_bytes
            or not v2_exact_instance_dictionary_matches(
                saved_environment,
                saved_environment_attributes,
                label="restored process environment",
            )
            or not v2_exact_instance_dictionary_matches(
                saved_environment_bytes,
                saved_environment_bytes_attributes,
                label="restored byte process environment",
            )
            or tuple(dict.items(
                v2_bounded_process_environment_bytes_snapshot()
            )) != tuple(dict.items(saved_environment_entries))
            or not v2_process_environment_backing_is_pinned()
        ):
            raise EvidenceFailed(
                "process environment restoration did not converge"
            )

    string_attributes_done = False
    bytes_attributes_done = False
    bindings_done = False
    entries_done = False
    anomalies: list[BaseException] = []
    converged = False
    for _sweep in range(3):
        if not string_attributes_done:
            try:
                restore_string_attributes()
            except BaseException as error:
                list.append(anomalies, error)
            else:
                string_attributes_done = True
        if not bytes_attributes_done:
            try:
                restore_bytes_attributes()
            except BaseException as error:
                list.append(anomalies, error)
            else:
                bytes_attributes_done = True
        if not bindings_done:
            try:
                restore_bindings()
            except BaseException as error:
                list.append(anomalies, error)
            else:
                bindings_done = True
        if not entries_done:
            try:
                restore_entries()
            except BaseException as error:
                list.append(anomalies, error)
            else:
                entries_done = True
        if (
            string_attributes_done
            and bytes_attributes_done
            and bindings_done
            and entries_done
        ):
            try:
                verify_environment()
            except BaseException as error:
                list.append(anomalies, error)
                string_attributes_done = False
                bytes_attributes_done = False
                bindings_done = False
                entries_done = False
            else:
                converged = True
                break
    if not converged or anomalies:
        cleanup_error = EvidenceFailed(
            "process environment restoration had cleanup anomalies"
        )
        if anomalies:
            raise cleanup_error from list.__getitem__(anomalies, 0)
        raise cleanup_error


V2_INITIAL_PROCESS_ENVIRONMENT_ATTRIBUTES = (
    v2_exact_instance_dictionary_snapshot(
        V2_INITIAL_PROCESS_ENVIRONMENT,
        label="initial process environment",
    )
)
V2_INITIAL_PROCESS_ENVIRONMENT_BYTES_ATTRIBUTES = (
    v2_exact_instance_dictionary_snapshot(
        V2_INITIAL_PROCESS_ENVIRONMENT_BYTES,
        label="initial byte process environment",
    )
)
_v2_initial_environment_raw = v2_raw_instance_dictionary(
    V2_INITIAL_PROCESS_ENVIRONMENT
)
_v2_initial_environment_bytes_raw = v2_raw_instance_dictionary(
    V2_INITIAL_PROCESS_ENVIRONMENT_BYTES
)
if (
    _v2_initial_environment_raw is None
    or _v2_initial_environment_bytes_raw is None
    or not dict.__contains__(_v2_initial_environment_raw, "_data")
    or not dict.__contains__(_v2_initial_environment_bytes_raw, "_data")
):
    raise EvidenceFailed("initial process environment lacks a pinned backing")
V2_INITIAL_PROCESS_ENVIRONMENT_BACKING = dict.__getitem__(
    _v2_initial_environment_raw,
    "_data",
)
if (
    dict.__getitem__(_v2_initial_environment_bytes_raw, "_data")
    is not V2_INITIAL_PROCESS_ENVIRONMENT_BACKING
):
    raise EvidenceFailed("initial process environment wrappers do not share backing")


def v2_process_environment_backing_is_pinned() -> bool:
    environment_raw = v2_raw_instance_dictionary(
        V2_INITIAL_PROCESS_ENVIRONMENT
    )
    environment_bytes_raw = v2_raw_instance_dictionary(
        V2_INITIAL_PROCESS_ENVIRONMENT_BYTES
    )
    return (
        environment_raw is not None
        and environment_bytes_raw is not None
        and dict.__contains__(environment_raw, "_data")
        and dict.__contains__(environment_bytes_raw, "_data")
        and dict.__getitem__(environment_raw, "_data")
        is V2_INITIAL_PROCESS_ENVIRONMENT_BACKING
        and dict.__getitem__(environment_bytes_raw, "_data")
        is V2_INITIAL_PROCESS_ENVIRONMENT_BACKING
    )


def v2_capture_command_receipt_state() -> tuple[list[Any], bytes]:
    if (
        _command_receipts is not V2_INITIAL_COMMAND_RECEIPTS
        or type(_command_receipts) is not list
    ):
        raise EvidenceFailed("command receipt list binding is not pinned")
    detached = v2_validate_exact_json_wire(
        _command_receipts,
        label="command receipt state",
    )
    if type(detached) is not list:
        raise EvidenceFailed("command receipt state is not an exact array")
    payload = canonical_bytes(detached)
    v2_require_fixture_resource_cap(
        len(payload),
        V2_FIXTURE_RESOURCE_PROJECTION_BYTES_CAP,
        diagnostic="command receipt state exceeds its bounded byte cap",
    )
    return detached, payload


def v2_restore_command_receipt_state(payload: Any) -> None:
    global _command_receipts
    if type(payload) is not bytes:
        raise EvidenceFailed("saved command receipt state is not exact bytes")
    restored = strict_json_loads(
        payload,
        label="saved command receipt state",
        require_canonical=True,
    )
    restored = v2_validate_exact_json_wire(
        restored,
        label="saved command receipt state",
    )
    if type(restored) is not list:
        raise EvidenceFailed("saved command receipt state is not an array")
    _command_receipts = V2_INITIAL_COMMAND_RECEIPTS
    list.clear(V2_INITIAL_COMMAND_RECEIPTS)
    for row in restored:
        list.append(V2_INITIAL_COMMAND_RECEIPTS, row)
    _, verified_payload = v2_capture_command_receipt_state()
    if verified_payload != payload:
        raise EvidenceFailed("command receipt restoration did not converge")


def v2_restore_cancel_state(saved_requested: Any, saved_epoch: Any) -> None:
    global _cancel_requested, _cancel_signal_epoch
    if (
        type(saved_requested) is not bool
        or type(saved_epoch) is not int
        or saved_epoch < 0
        or type(_cancel_requested) is not bool
    ):
        raise EvidenceFailed("saved cancellation state is malformed")
    if type(_cancel_signal_epoch) is not int or _cancel_signal_epoch < saved_epoch:
        raise EvidenceFailed("cancellation signal epoch moved backward")
    if _cancel_signal_epoch == saved_epoch:
        _cancel_requested = saved_requested
    else:
        _cancel_requested = True


def v2_capture_fixture_process_observation() -> dict[str, Any]:
    if (
        os.environ is not V2_INITIAL_PROCESS_ENVIRONMENT
        or os.environb is not V2_INITIAL_PROCESS_ENVIRONMENT_BYTES
        or not v2_process_environment_backing_is_pinned()
    ):
        raise EvidenceFailed("fixture process environment identity is not pinned")
    environment_attributes = v2_exact_instance_dictionary_snapshot(
        V2_INITIAL_PROCESS_ENVIRONMENT,
        label="fixture process environment observation",
    )
    environment_bytes_attributes = v2_exact_instance_dictionary_snapshot(
        V2_INITIAL_PROCESS_ENVIRONMENT_BYTES,
        label="fixture byte process environment observation",
    )
    environment_entries = v2_bounded_process_environment_bytes_snapshot()
    _, receipt_payload = v2_capture_command_receipt_state()
    if (
        type(_cancel_requested) is not bool
        or type(_cancel_signal_epoch) is not int
        or _cancel_signal_epoch < 0
    ):
        raise EvidenceFailed("fixture cancellation epoch is malformed")
    return {
        "cwd": os.getcwdb(),
        "environment": V2_INITIAL_PROCESS_ENVIRONMENT,
        "environment_bytes": V2_INITIAL_PROCESS_ENVIRONMENT_BYTES,
        "environment_attributes": environment_attributes,
        "environment_bytes_attributes": environment_bytes_attributes,
        "environment_backing": V2_INITIAL_PROCESS_ENVIRONMENT_BACKING,
        "environment_entries": environment_entries,
        "recursion_limit": sys.getrecursionlimit(),
        "command_receipts": V2_INITIAL_COMMAND_RECEIPTS,
        "command_receipt_payload": receipt_payload,
        "cancel_requested": _cancel_requested,
        "cancel_epoch": _cancel_signal_epoch,
        "selected_resource_scope_pristine": (
            v2_fixture_selected_resource_scope_is_pristine()
        ),
    }


def v2_fixture_process_observations_match(
    left: Any,
    right: Any,
) -> bool:
    if type(left) is not dict or type(right) is not dict:
        raise EvidenceFailed("fixture process observations are not exact objects")
    expected_fields = {
        "cwd",
        "environment",
        "environment_bytes",
        "environment_attributes",
        "environment_bytes_attributes",
        "environment_backing",
        "environment_entries",
        "recursion_limit",
        "command_receipts",
        "command_receipt_payload",
        "cancel_requested",
        "cancel_epoch",
        "selected_resource_scope_pristine",
    }
    if set(left) != expected_fields or set(right) != expected_fields:
        raise EvidenceFailed("fixture process observation schema differs")
    return (
        left["cwd"] == right["cwd"]
        and left["environment"] is right["environment"]
        and left["environment_bytes"] is right["environment_bytes"]
        and left["environment_backing"] is right["environment_backing"]
        and type(left["environment_entries"]) is dict
        and type(right["environment_entries"]) is dict
        and tuple(dict.items(left["environment_entries"]))
        == tuple(dict.items(right["environment_entries"]))
        and left["recursion_limit"] == right["recursion_limit"]
        and left["command_receipts"] is right["command_receipts"]
        and left["command_receipt_payload"]
        == right["command_receipt_payload"]
        and left["cancel_requested"] is right["cancel_requested"]
        and left["cancel_epoch"] == right["cancel_epoch"]
        and left["selected_resource_scope_pristine"]
        is right["selected_resource_scope_pristine"]
        and v2_exact_instance_dictionary_snapshots_match(
            left["environment_attributes"],
            right["environment_attributes"],
            label="fixture process environment observation",
        )
        and v2_exact_instance_dictionary_snapshots_match(
            left["environment_bytes_attributes"],
            right["environment_bytes_attributes"],
            label="fixture byte process environment observation",
        )
    )


def v2_capture_double_coherent_fixture_process_baseline() -> dict[str, Any]:
    first = v2_capture_fixture_process_observation()
    second = v2_capture_fixture_process_observation()
    if not v2_fixture_process_observations_match(first, second):
        raise EvidenceFailed("fixture process baseline changed between captures")
    return first


def v2_run_convergent_restoration(
    steps: tuple[tuple[str, Callable[[], None]], ...],
    verify: Callable[[], None],
) -> dict[str, Any]:
    v2_validate_fixture_restoration_plan(
        steps,
        verify,
        label="fixture restoration plan",
    )
    rows: list[dict[str, Any]] = []
    for row in steps:
        name = tuple.__getitem__(row, 0)
        callback = tuple.__getitem__(row, 1)
        rows.append({"name": name, "callback": callback, "state": "PENDING"})
    anomalies: list[tuple[str, BaseException]] = []
    attempts: list[dict[str, Any]] = []
    attempt_ordinal = 0
    converged = False
    for sweep_index in range(3):
        for row in rows:
            if row["state"] == "SUCCEEDED":
                continue
            row["state"] = "RUNNING"
            callback = row["callback"]
            if type(callback) is not types.FunctionType:
                raise EvidenceFailed(
                    "fixture restoration callback identity changed"
                )
            try:
                callback()
            except BaseException as error:
                row["state"] = "PENDING"
                anomalies.append((row["name"], error))
                attempts.append(
                    {
                        "attempt": attempt_ordinal,
                        "sweep": sweep_index,
                        "step": row["name"],
                        "outcome": "FAILED",
                        "error_type": v2_exception_type_projection(
                            type(error)
                        ),
                        "diagnostic": v2_bounded_diagnostic_summary(error),
                    }
                )
            else:
                row["state"] = "SUCCEEDED"
                attempts.append(
                    {
                        "attempt": attempt_ordinal,
                        "sweep": sweep_index,
                        "step": row["name"],
                        "outcome": "SUCCEEDED",
                        "error_type": None,
                        "diagnostic": None,
                    }
                )
            attempt_ordinal += 1
        if all(row["state"] == "SUCCEEDED" for row in rows):
            try:
                verify()
            except BaseException as error:
                anomalies.append(("verify", error))
                attempts.append(
                    {
                        "attempt": attempt_ordinal,
                        "sweep": sweep_index,
                        "step": "verify",
                        "outcome": "FAILED",
                        "error_type": v2_exception_type_projection(
                            type(error)
                        ),
                        "diagnostic": v2_bounded_diagnostic_summary(error),
                    }
                )
                attempt_ordinal += 1
                for row in rows:
                    row["state"] = "PENDING"
            else:
                attempts.append(
                    {
                        "attempt": attempt_ordinal,
                        "sweep": sweep_index,
                        "step": "verify",
                        "outcome": "SUCCEEDED",
                        "error_type": None,
                        "diagnostic": None,
                    }
                )
                attempt_ordinal += 1
                converged = True
                break
    return {
        "converged": converged,
        "states": tuple((row["name"], row["state"]) for row in rows),
        "anomalies": tuple(anomalies),
        "attempts": tuple(attempts),
    }


def v2_append_exception_note_without_hooks(
    primary: Any,
    note: Any,
) -> bool:
    if type(note) is not str:
        return False
    try:
        note_bytes = str.encode(note, "utf-8")
    except UnicodeEncodeError:
        return False
    if (
        len(note_bytes) > V2_EXCEPTION_NOTE_BYTES_CAP
        or v2_contains_absolute_path(note)
        or v2_redact_contextual_text(note) != note
    ):
        return False
    try:
        if not v2_raw_instance_of(primary, BaseException):
            return False
        raw_attributes = v2_raw_instance_dictionary(primary)
    except EvidenceFailed:
        return False
    if raw_attributes is None:
        return False
    attribute_count = dict.__len__(raw_attributes)
    if (
        attribute_count > V2_EXCEPTION_METADATA_ATTRIBUTES_CAP
        or any(
            type(key) is not str
            for key in dict.__iter__(raw_attributes)
        )
    ):
        return False
    notes_present = dict.__contains__(raw_attributes, "__notes__")
    if not notes_present:
        if attribute_count >= V2_EXCEPTION_METADATA_ATTRIBUTES_CAP:
            return False
        dict.__setitem__(raw_attributes, "__notes__", [note])
        return True
    notes = dict.__getitem__(raw_attributes, "__notes__")
    if type(notes) is not list:
        return False
    note_count = list.__len__(notes)
    if note_count >= V2_EXCEPTION_NOTES_CAP:
        return False
    note_snapshot: list[str] = []
    encoded_sizes: list[int] = []
    for index in range(note_count):
        try:
            existing_note = list.__getitem__(notes, index)
        except (IndexError, RuntimeError):
            return False
        if type(existing_note) is not str:
            return False
        try:
            existing_bytes = str.encode(existing_note, "utf-8")
        except UnicodeEncodeError:
            return False
        if len(existing_bytes) > V2_EXCEPTION_NOTE_BYTES_CAP:
            return False
        list.append(note_snapshot, existing_note)
        list.append(encoded_sizes, len(existing_bytes))
    try:
        verification_snapshot = [
            list.__getitem__(notes, index)
            for index in range(note_count)
        ]
    except (IndexError, RuntimeError):
        return False
    if (
        list.__len__(notes) != note_count
        or verification_snapshot != note_snapshot
        or sum(encoded_sizes) + len(note_bytes)
        > V2_EXCEPTION_NOTES_TOTAL_BYTES_CAP
    ):
        return False
    list.append(notes, note)
    return True


def v2_attach_cleanup_note(primary: BaseException, cleanup: BaseException) -> None:
    note = (
        "fixture cleanup anomaly: "
        + v2_exception_type_projection(type(cleanup))
    )
    v2_append_exception_note_without_hooks(primary, note)


V2_FIXTURE_RESOURCE_TRANSACTION_LOCK = V2_REFUSAL_PROCESS_STATE_LOCK


def _v2_check_fixture_resource_refusal_transaction(
    checks: V2CheckCollector,
    check_id: str,
    error_type: type[HarnessError],
    callback: Callable[[], Any],
    *,
    contains: str,
    paths: Sequence[Path],
    operation_grants: Sequence[
        tuple[str, Sequence[Path] | None]
    ],
    access_paths: Sequence[Path] | None = None,
    additional_state: Callable[[], Any] | None = None,
) -> None:
    baseline = v2_capture_double_coherent_fixture_process_baseline()
    saved_cwd = baseline["cwd"]
    saved_environment_object = baseline["environment"]
    saved_environment_bytes_object = baseline["environment_bytes"]
    saved_environment_attributes = baseline["environment_attributes"]
    saved_environment_bytes_attributes = baseline[
        "environment_bytes_attributes"
    ]
    saved_environment_bytes = baseline["environment_entries"]
    saved_recursion_limit = baseline["recursion_limit"]
    saved_command_receipt_payload = baseline["command_receipt_payload"]
    saved_cancel_requested = baseline["cancel_requested"]
    saved_cancel_epoch = baseline["cancel_epoch"]
    observed_path_snapshot = v2_exact_fixture_resource_paths_snapshot(paths)
    operation_grant_snapshot = (
        v2_exact_fixture_resource_operation_grants_snapshot(
            operation_grants
        )
    )
    access_path_source = paths if access_paths is None else access_paths
    access_path_snapshot = v2_exact_fixture_resource_paths_snapshot(
        access_path_source
    )
    access_path_keys = tuple(
        v2_fixture_selected_resource_path_key(path)
        for path in access_path_snapshot
    )
    saved_cwd_state: os.stat_result | None = None
    saved_cwd_descriptor_slot: list[int | None] = [None]
    selected_resource_scope_token_slot: list[Any] = [None]

    def restore_recursion_limit() -> None:
        if sys.getrecursionlimit() != saved_recursion_limit:
            sys.setrecursionlimit(saved_recursion_limit)

    def restore_environment() -> None:
        v2_restore_process_environment(
            saved_environment_object,
            saved_environment_bytes_object,
            saved_environment_attributes,
            saved_environment_bytes_attributes,
            saved_environment_bytes,
        )

    def restore_cwd() -> None:
        descriptor = list.__getitem__(saved_cwd_descriptor_slot, 0)
        if descriptor is None:
            if os.getcwdb() == saved_cwd:
                return
            raise EvidenceFailed("fixture cwd descriptor ownership was lost")
        if type(descriptor) is not int:
            raise EvidenceFailed("fixture cwd descriptor ownership was lost")
        if saved_cwd_state is None:
            if os.getcwdb() == saved_cwd:
                return
            raise EvidenceFailed("fixture cwd descriptor baseline is absent")
        try:
            descriptor_state = os.fstat(descriptor)
        except OSError as error:
            if os.getcwdb() != saved_cwd:
                os.chdir(saved_cwd)
            raise EvidenceFailed("fixture cwd descriptor was closed early") from error
        if (
            descriptor_state.st_dev != saved_cwd_state.st_dev
            or descriptor_state.st_ino != saved_cwd_state.st_ino
        ):
            raise EvidenceFailed("fixture cwd descriptor identity changed")
        os.fchdir(descriptor)

    def close_cwd_descriptor() -> None:
        descriptor = list.__getitem__(saved_cwd_descriptor_slot, 0)
        if descriptor is None:
            return
        if type(descriptor) is not int:
            raise EvidenceFailed("fixture cwd descriptor ownership was lost")
        try:
            descriptor_state = os.fstat(descriptor)
            current_cwd_state = os.stat(b".", follow_symlinks=False)
        except OSError as error:
            raise EvidenceFailed(
                "fixture cwd descriptor could not be verified before close"
            ) from error
        if (
            saved_cwd_state is not None
            and (
                descriptor_state.st_dev != saved_cwd_state.st_dev
                or descriptor_state.st_ino != saved_cwd_state.st_ino
                or current_cwd_state.st_dev != saved_cwd_state.st_dev
                or current_cwd_state.st_ino != saved_cwd_state.st_ino
            )
        ):
            raise EvidenceFailed(
                "fixture cwd restoration must precede descriptor close"
            )
        close_failure = v2_collect_owned_descriptor_slot_close_failure(
            saved_cwd_descriptor_slot,
            EvidenceFailed(
                "fixture cwd descriptor could not be closed safely"
            ),
        )
        if close_failure is not None:
            v2_raise_descriptor_close_failure(close_failure)

    def restore_command_receipts() -> None:
        v2_restore_command_receipt_state(saved_command_receipt_payload)

    def restore_cancellation() -> None:
        v2_restore_cancel_state(saved_cancel_requested, saved_cancel_epoch)

    def restore_selected_resource_scope() -> None:
        selected_resource_scope_token = list.__getitem__(
            selected_resource_scope_token_slot,
            0,
        )
        if (
            selected_resource_scope_token is None
            and v2_fixture_selected_resource_scope_is_pristine()
        ):
            return
        if type(selected_resource_scope_token) is not list:
            raise EvidenceFailed(
                "fixture resource scope token ownership was lost"
            )
        v2_fixture_selected_resource_scope_leave(
            selected_resource_scope_token
        )
        list.__setitem__(selected_resource_scope_token_slot, 0, None)

    def verify_restoration() -> None:
        if (
            os.environ is not saved_environment_object
            or os.environb is not saved_environment_bytes_object
            or not v2_exact_instance_dictionary_matches(
                saved_environment_object,
                saved_environment_attributes,
                label="restored fixture process environment",
            )
            or not v2_exact_instance_dictionary_matches(
                saved_environment_bytes_object,
                saved_environment_bytes_attributes,
                label="restored fixture byte process environment",
            )
            or tuple(dict.items(
                v2_bounded_process_environment_bytes_snapshot()
            )) != tuple(dict.items(saved_environment_bytes))
            or not v2_process_environment_backing_is_pinned()
            or sys.getrecursionlimit() != saved_recursion_limit
            or os.getcwdb() != saved_cwd
            or _command_receipts is not V2_INITIAL_COMMAND_RECEIPTS
            or v2_capture_command_receipt_state()[1]
            != saved_command_receipt_payload
            or _cancel_signal_epoch < saved_cancel_epoch
            or (
                _cancel_signal_epoch == saved_cancel_epoch
                and _cancel_requested is not saved_cancel_requested
            )
            or (
                _cancel_signal_epoch > saved_cancel_epoch
                and _cancel_requested is not True
            )
            or not v2_fixture_selected_resource_scope_is_pristine()
            or list.__getitem__(saved_cwd_descriptor_slot, 0) is not None
        ):
            raise EvidenceFailed(
                "fixture resource cleanup left changed process state"
            )

    restoration_steps = (
        ("selected-resource-scope", restore_selected_resource_scope),
        ("process-environment", restore_environment),
        ("process-cwd", restore_cwd),
        ("process-recursion-limit", restore_recursion_limit),
        ("command-receipts", restore_command_receipts),
        ("cancellation", restore_cancellation),
        ("cwd-descriptor-close", close_cwd_descriptor),
    )

    def verify_observed_path_source() -> None:
        current = v2_exact_fixture_resource_paths_snapshot(paths)
        if len(current) != len(observed_path_snapshot) or any(
            current[index] is not observed_path_snapshot[index]
            for index in range(len(observed_path_snapshot))
        ):
            raise EvidenceFailed(
                "fixture selected-resource observed paths changed during "
                "refusal checking"
            )

    def verify_access_path_source() -> None:
        current = v2_exact_fixture_resource_paths_snapshot(
            access_path_source
        )
        if len(current) != len(access_path_snapshot) or any(
            current[index] is not access_path_snapshot[index]
            for index in range(len(access_path_snapshot))
        ):
            raise EvidenceFailed(
                "fixture selected-resource access paths changed during "
                "refusal checking"
            )

    def verify_operation_grant_source() -> None:
        current = v2_exact_fixture_resource_operation_grants_snapshot(
            operation_grants
        )
        if len(current) != len(operation_grant_snapshot):
            raise EvidenceFailed(
                "fixture selected-resource operation grants changed during "
                "refusal checking"
            )
        for index, (operation, granted_paths) in enumerate(
            operation_grant_snapshot
        ):
            current_operation, current_paths = current[index]
            if current_operation is not operation or (
                granted_paths is None and current_paths is not None
            ):
                raise EvidenceFailed(
                    "fixture selected-resource operation grants changed during "
                    "refusal checking"
                )
            if granted_paths is not None and (
                current_paths is None
                or len(current_paths) != len(granted_paths)
                or any(
                    current_paths[path_index] is not granted_paths[path_index]
                    for path_index in range(len(granted_paths))
                )
            ):
                raise EvidenceFailed(
                    "fixture selected-resource operation grants changed during "
                    "refusal checking"
                )

    def capture_state() -> dict[str, Any]:
        verify_observed_path_source()
        verify_access_path_source()
        verify_operation_grant_source()
        additional_callable_before = (
            v2_fixture_callback_data_projection(additional_state)
            if additional_state is not None
            else None
        )
        resources = v2_fixture_resource_state(
            observed_path_snapshot,
            additional_state=additional_state,
        )
        additional_callable_after = (
            v2_fixture_callback_data_projection(additional_state)
            if additional_state is not None
            else None
        )
        if additional_callable_before != additional_callable_after:
            raise EvidenceFailed(
                "fixture resource additional-state projector mutated its "
                "reachable data"
            )
        return {
            "resources": resources,
            "selected_resource_observed_paths": [
                v2_fixture_selected_resource_path_key(path)
                for path in observed_path_snapshot
            ],
            "selected_resource_access_paths": list(access_path_keys),
            "selected_resource_operation_grants": [
                {
                    "operation": operation,
                    "paths": (
                        [
                            v2_fixture_selected_resource_path_key(path)
                            for path in granted_paths
                        ]
                        if granted_paths is not None
                        else None
                    ),
                }
                for operation, granted_paths in operation_grant_snapshot
            ],
            "callback_data": v2_fixture_callback_data_projection(callback),
            "additional_state_callable_data": additional_callable_after,
        }

    body_primary: BaseException | None = None
    restoration_report: dict[str, Any] | None = None
    before_state: dict[str, Any] | None = None
    before_root: str | None = None
    error: HarnessError | None = None
    after_state: dict[str, Any] | None = None
    after_capture_error: BaseException | None = None
    after_root: str | None = None
    try:
        try:
            try:
                list.__setitem__(
                    saved_cwd_descriptor_slot,
                    0,
                    os.open(
                        b".",
                        os.O_RDONLY | getattr(os, "O_CLOEXEC", 0),
                    ),
                )
                captured_cwd_descriptor = list.__getitem__(
                    saved_cwd_descriptor_slot,
                    0,
                )
                if type(captured_cwd_descriptor) is not int:
                    raise EvidenceFailed(
                        "fixture resource cwd descriptor ownership was lost"
                    )
                saved_cwd_state = os.fstat(captured_cwd_descriptor)
                observed_cwd_state = os.stat(
                    b".",
                    follow_symlinks=False,
                )
            except OSError as capture_error:
                raise EvidenceFailed(
                    "fixture resource baseline cwd descriptor capture failed"
                ) from capture_error
            if (
                saved_cwd_state.st_dev != observed_cwd_state.st_dev
                or saved_cwd_state.st_ino != observed_cwd_state.st_ino
            ):
                raise EvidenceFailed(
                    "fixture resource baseline cwd identity changed"
                )
            v2_fixture_selected_resource_scope_enter(
                observed_path_snapshot,
                access_path_snapshot,
                operation_grant_snapshot,
                _token_slot=selected_resource_scope_token_slot,
            )
            before_state = capture_state()
            before_root = semantic_root(before_state)
            error = expect_error(error_type, callback, contains=contains)
            try:
                after_state = capture_state()
            except BaseException as capture_error:
                after_capture_error = capture_error
            after_root = (
                semantic_root(after_state)
                if after_state is not None
                else None
            )
        except BaseException as primary:
            body_primary = primary
    finally:
        restoration_runner_anomalies: list[tuple[str, BaseException]] = []
        try:
            restoration_report = v2_run_convergent_restoration(
                restoration_steps,
                verify_restoration,
            )
        except BaseException as restoration_runner_error:
            list.append(
                restoration_runner_anomalies,
                ("restoration-runner", restoration_runner_error),
            )
        if (
            restoration_report is None
            or restoration_report.get("converged") is not True
        ):
            try:
                fallback_report = v2_run_convergent_restoration(
                    restoration_steps,
                    verify_restoration,
                )
            except BaseException as fallback_runner_error:
                list.append(
                    restoration_runner_anomalies,
                    ("fallback-restoration-runner", fallback_runner_error),
                )
            else:
                if restoration_report is None:
                    restoration_report = fallback_report
                else:
                    restoration_report = {
                        "converged": fallback_report["converged"],
                        "states": fallback_report["states"],
                        "anomalies": (
                            *restoration_report["anomalies"],
                            *fallback_report["anomalies"],
                        ),
                    }
        if restoration_report is None:
            restoration_report = {
                "converged": False,
                "states": (),
                "anomalies": tuple(restoration_runner_anomalies),
            }
        elif restoration_runner_anomalies:
            restoration_report = {
                "converged": restoration_report["converged"],
                "states": restoration_report["states"],
                "anomalies": (
                    *restoration_runner_anomalies,
                    *restoration_report["anomalies"],
                ),
            }
    if restoration_report is None:
        raise EvidenceFailed("fixture resource cleanup produced no report")
    restoration_anomalies = restoration_report["anomalies"]
    cleanup_error: EvidenceFailed | None = None
    if (
        restoration_report["converged"] is not True
        or restoration_anomalies
    ):
        cleanup_error = EvidenceFailed(
            "fixture resource cleanup did not converge without anomalies"
        )
    if body_primary is not None:
        if cleanup_error is not None:
            v2_attach_cleanup_note(body_primary, cleanup_error)
        raise body_primary
    if cleanup_error is not None:
        if restoration_anomalies:
            raise cleanup_error from restoration_anomalies[0][1]
        raise cleanup_error
    if (
        error is None
        or before_state is None
        or before_root is None
    ):
        raise EvidenceFailed("fixture resource refusal body produced no evidence")
    diagnostic, diagnostic_exact = v2_exception_diagnostic(error)
    divergence = (
        first_projection_divergence(before_state, after_state)
        if after_state is not None
        else None
    )
    checks.check(
        check_id,
        type(error) is error_type
        and diagnostic_exact
        and contains in diagnostic
        and after_capture_error is None
        and divergence is None
        and before_root == after_root,
        expected={
            "exact_error_type": v2_raw_type_name(error_type),
            "terminal": v2_harness_error_terminal(error_type),
            "diagnostic_contains": contains,
            "fixture_state_root": before_root,
            "first_divergence": None,
            "after_capture_error": None,
        },
        observed={
            "error_type": v2_raw_type_name(type(error)),
            "terminal": (
                v2_harness_error_terminal(type(error))
                if type(error) is error_type
                else None
            ),
            "diagnostic_exact": diagnostic_exact,
            "diagnostic_contains": contains in diagnostic,
            "diagnostic_root": text_root(diagnostic),
            "fixture_state_root_before": before_root,
            "fixture_state_root_after": after_root,
            "first_divergence": divergence,
            "after_capture_error": (
                v2_raw_type_name(type(after_capture_error))
                if after_capture_error is not None
                else None
            ),
        },
    )


def v2_check_fixture_resource_refusal(
    checks: V2CheckCollector,
    check_id: str,
    error_type: type[HarnessError],
    callback: Callable[[], Any],
    *,
    contains: str,
    paths: Sequence[Path],
    operation_grants: Sequence[
        tuple[str, Sequence[Path] | None]
    ],
    access_paths: Sequence[Path] | None = None,
    additional_state: Callable[[], Any] | None = None,
) -> None:
    with V2_FIXTURE_RESOURCE_TRANSACTION_LOCK:
        _v2_check_fixture_resource_refusal_transaction(
            checks,
            check_id,
            error_type,
            callback,
            contains=contains,
            paths=paths,
            operation_grants=operation_grants,
            access_paths=access_paths,
            additional_state=additional_state,
        )


