def v2_normalized_target_source_issue(
    target: Mapping[str, Any],
) -> dict[str, Any]:
    """Reconstruct the root-bearing source shape retained by a target row."""
    target = v2_released_json_snapshot(
        target,
        label="normalized target source projection",
        error_type=EvidenceFailed,
    )
    if type(target) is not dict:
        raise EvidenceFailed(
            "normalized target source projection is not an exact object"
        )
    active_context = dict.get(target, "active_work_context")
    if type(active_context) is not dict:
        raise EvidenceFailed(
            "normalized target source projection lacks exact active context"
        )
    context = active_context
    return {
        "source_issue_projection_root": str(
            dict.get(target, "source_issue_projection_root") or ""
        ),
        "id": str(dict.get(target, "id") or ""),
        "title": str(dict.get(target, "title") or ""),
        "type": str(
            dict.get(target, "type")
            or dict.get(target, "issue_type")
            or ""
        ),
        "status": str(dict.get(target, "status") or ""),
        "priority": dict.get(target, "priority"),
        "assignee": str(dict.get(target, "tracker_assignee") or ""),
        "owner": str(dict.get(target, "tracker_owner") or ""),
        "parent": str(dict.get(target, "parent") or ""),
        "labels": list(dict.get(target, "labels") or []),
        "estimated_minutes": dict.get(
            target,
            "target_implementation_estimated_minutes"
        ),
        "tracker_ready": dict.get(context, "tracker_ready") is True,
        "non_actionable_reasons": list(
            dict.get(context, "non_actionable_reasons") or []
        ),
        "field_roots": dict(dict.get(target, "field_roots") or {}),
        "missing_sections": list(dict.get(target, "missing_sections") or []),
        "disposition": str(dict.get(target, "disposition") or ""),
        "dependencies": list(dict.get(target, "dependencies") or []),
        "dependents": list(dict.get(target, "dependents") or []),
    }


def v2_synthetic_source_issue(
    target: Mapping[str, Any],
) -> dict[str, Any]:
    """Compatibility name for normalized synthetic fixture reconstruction."""
    return v2_normalized_target_source_issue(target)


V2_NORMALIZED_TARGET_IDENTITY_SCHEMA = (
    "frankensim.beads-template-hygiene.target-identity.v2"
)
V2_NORMALIZED_TARGET_IDENTITY_ALGORITHM = (
    "SHA256_CANONICAL_JSON_SCHEMA_AND_RETAINED_TARGET_PROJECTION"
)
V2_NORMALIZED_TARGET_ROOT_EXCLUDED_FIELD_ORDER = (
    "campaign_epoch_root",
    "semantic_root",
    "target_root",
)
V2_NORMALIZED_TARGET_ROOT_EXCLUDED_FIELDS = frozenset(
    V2_NORMALIZED_TARGET_ROOT_EXCLUDED_FIELD_ORDER
)


def v2_normalized_target_root(target: Mapping[str, Any]) -> str:
    """Bind every retained target field that can affect downstream planning."""
    target = v2_released_json_snapshot(
        target,
        label="normalized target root input",
        error_type=EvidenceFailed,
    )
    if type(target) is not dict:
        raise EvidenceFailed(
            "normalized target root input is not an exact object"
        )
    projection = {
        key: value
        for key, value in dict.items(target)
        if key not in V2_NORMALIZED_TARGET_ROOT_EXCLUDED_FIELDS
    }
    return semantic_root(
        {
            "schema": V2_NORMALIZED_TARGET_IDENTITY_SCHEMA,
            "projection": projection,
        }
    )


def v2_validate_synthetic_target_identity(
    target: Mapping[str, Any],
) -> None:
    target = v2_released_json_snapshot(
        target,
        label="synthetic target identity input",
        error_type=EvidenceFailed,
    )
    if type(target) is not dict:
        raise EvidenceFailed(
            "synthetic target identity input is not an exact object"
        )
    source_issue = v2_normalized_target_source_issue(target)
    expected_v1_row_root = semantic_root(
        {"id": dict.get(target, "id"), "v1": True}
    )
    expected_source_projection_root = semantic_root(
        {
            key: value
            for key, value in dict.items(source_issue)
            if key != "source_issue_projection_root"
        }
    )
    expected_target_root = v2_normalized_target_root(target)
    expected_dependency_root = v2_dependency_neighborhood_root(
        source_issue
    )
    if (
        dict.get(target, "source_issue_projection_root")
        != expected_source_projection_root
    ):
        raise EvidenceFailed(
            "synthetic source projection root differs from its canonical "
            "source shape"
        )
    if dict.get(target, "target_root") != expected_target_root:
        raise EvidenceFailed(
            "synthetic target root differs from normalized target-identity.v2"
        )
    if (
        dict.get(target, "dependency_neighborhood_root")
        != expected_dependency_root
    ):
        raise EvidenceFailed(
            "synthetic dependency root differs from its normalized source "
            "projection"
        )
    if dict.get(target, "v1_row_root") != expected_v1_row_root:
        raise EvidenceFailed(
            "synthetic v1 row root differs from its canonical identity"
        )


def v2_synthetic_target(
    index: int,
    *,
    issue_id: str | None = None,
    priority: int = 2,
    status: str = "open",
    disposition: str | None = None,
    issue_type: str = "task",
    missing_sections: Sequence[str] = ("## Acceptance Criteria",),
    readiness_seed: str = "REVIEW_ONLY",
    review_minutes: int = 1,
    retained_payload_bytes: int = 512,
    assignee: str = "",
    tracker_ready: bool | None = None,
) -> dict[str, Any]:
    issue_id = issue_id or f"synthetic-{index:04d}"
    resolved_disposition = (
        disposition
        if disposition is not None
        else (
            "HISTORICAL_IMMUTABLE_REVIEW"
            if status == "closed"
            else (
                "OWNER_REVIEW_REQUIRED"
                if status == "deferred" or not missing_sections
                else "SUBSTANTIVE_SEMANTIC_OMISSION"
            )
        )
    )
    field_texts = {
        "description": (
            f"Acceptance clause for synthetic target {issue_id}"
        ),
        "acceptance_criteria": "",
        "design": "",
        "notes": "",
    }
    field_roots = {
        field: text_root(text) for field, text in field_texts.items()
    }
    resolved_tracker_ready = (
        status == "open" if tracker_ready is None else tracker_ready
    )
    active_context = v2_active_work_context(
        v2_bind_tracker_actionability(
            {"id": issue_id, "status": status, "assignee": assignee},
            tracker_ready=resolved_tracker_ready,
        )
    )
    target = {
            "id": issue_id,
            "issue_id": issue_id,
            "title": f"Synthetic target {index:04d}",
            "type": issue_type,
            "issue_type": issue_type,
            "status": status,
            "priority": priority,
            "priority_lane": f"P{priority}",
            "status_lane": status,
            "lane": f"P{priority}/{status}",
            "campaign_epoch_root": "",
            "destination": (
                "history-v2.json" if status == "closed" else "review-plan-v2.json"
            ),
            "movement_destination": (
                "history-v2.json" if status == "closed" else "review-plan-v2.json"
            ),
            "tracker_assignee": assignee,
            "coordination_assignee": assignee,
            "tracker_owner": "",
            "parent": "",
            "labels": [],
            "missing_sections": list(
                v2_canonical_missing_sections(
                    issue_type,
                    tuple(missing_sections),
                )
            ),
            "disposition": resolved_disposition,
            "template_warning_state": (
                "PRESENT" if missing_sections else "NONE"
            ),
            "semantic_review_disposition": (
                v2_unreviewed_semantic_disposition(
                    status=status,
                    classification_disposition=resolved_disposition,
                )
            ),
            "semantic_review_receipt_state": "UNREVIEWED",
            "semantic_review_dimensions": (
                v2_unreviewed_semantic_dimensions()
            ),
            "semantic_review_receipt_root": None,
            "reviewed_no_change_receipt_root": None,
            "disposition_rationale": "synthetic exact disposition",
            "disposition_falsifier": "a contrary rooted fixture invalidates it",
            "field_roots": field_roots,
            "field_byte_lengths": {
                field: len(str.encode(text, "utf-8"))
                for field, text in field_texts.items()
            },
            "clause_roots": v2_complete_clause_roots(field_texts),
            "v1_row_root": semantic_root({"id": issue_id, "v1": True}),
            "dependencies": [],
            "dependents": [],
            "domain_candidates": [],
            "domain_candidate": [],
            "declared_domain_owner": "",
            "declared_acceptance_owner": "",
            "implementation_owner": assignee or "UNRESOLVED",
            "evidence_owner": "UNRESOLVED",
            "terminal_consumer": "UNRESOLVED",
            "reviewer_provenance": {
                "state": "NODATA",
                "receipt_root": None,
            },
            "source_closure": {
                "required": False,
                "state": "NOT_REQUIRED_BY_V1_CLASSIFICATION",
            },
            "user_effect": "make exact review debt visible to users",
            "target_implementation_estimated_minutes": 60,
            "target_implementation_estimate_minutes": 60,
            "target_implementation_estimate_state": "DECLARED",
            "review_minutes": review_minutes,
            "generated_child_estimated_minutes": review_minutes,
            "retained_payload_bytes": retained_payload_bytes,
            "external_authority_adapter_identity": "",
            "external_authority_receipt_root": "",
            "external_authority_verdict": "NODATA",
            "conditional_write_capability_identity": "",
            "conditional_write_receipt_root": "",
            "conditional_write_verdict": "NODATA",
            "readiness": readiness_seed,
            "remediation_route": "ANALYSIS_ONLY",
            "active_work_context": active_context,
            "no_claim": "synthetic planning row grants no authority",
        }
    target["source_issue_projection_root"] = semantic_root(
        {
            key: value
            for key, value in dict.items(v2_synthetic_source_issue(target))
            if key != "source_issue_projection_root"
        }
    )
    source_issue = v2_synthetic_source_issue(target)
    target["dependency_neighborhood_root"] = (
        v2_dependency_neighborhood_root(source_issue)
    )
    target["target_root"] = v2_normalized_target_root(target)
    v2_validate_synthetic_target_identity(target)
    return v2_rooted(target)


def v2_rebind_synthetic_target_identity(
    target: Mapping[str, Any],
) -> dict[str, Any]:
    candidate = v2_released_json_snapshot(
        target,
        label="synthetic target identity rebind",
        error_type=EvidenceFailed,
    )
    if type(candidate) is not dict:
        raise EvidenceFailed("synthetic target rebind input is not an object")
    dict.pop(candidate, "semantic_root", None)
    active_context = dict.get(candidate, "active_work_context")
    if type(active_context) is not dict:
        raise EvidenceFailed(
            "synthetic target rebind lacks exact active work context"
        )
    tracker_ready = dict.get(active_context, "tracker_ready")
    if type(tracker_ready) is not bool:
        raise EvidenceFailed(
            "synthetic target rebind tracker readiness is not exact"
        )
    # Normalized target rows deliberately rename tracker-owned fields such as
    # `assignee`.  Reconstruct the production source shape before deriving
    # actionability so assigned targets do not silently become unassigned and
    # dependency-based reasons stay aligned with the target identity roots.
    actionability_bound = v2_bind_tracker_actionability(
        v2_synthetic_source_issue(candidate),
        tracker_ready=tracker_ready,
    )
    candidate["active_work_context"] = v2_active_work_context(
        actionability_bound
    )
    source_issue = v2_synthetic_source_issue(candidate)
    candidate["source_issue_projection_root"] = semantic_root(
        {
            key: value
            for key, value in dict.items(source_issue)
            if key != "source_issue_projection_root"
        }
    )
    source_issue = v2_synthetic_source_issue(candidate)
    candidate["dependency_neighborhood_root"] = (
        v2_dependency_neighborhood_root(source_issue)
    )
    candidate["target_root"] = v2_normalized_target_root(candidate)
    v2_validate_synthetic_target_identity(candidate)
    return v2_rooted(candidate)


def v2_synthetic_inventory(
    targets: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    if type(targets) is list:
        target_rows = list.__iter__(targets)
    elif type(targets) is tuple:
        target_rows = tuple.__iter__(targets)
    else:
        raise EvidenceFailed(
            "synthetic inventory targets are not an exact list or tuple"
        )
    targets = v2_released_json_snapshot(
        list(target_rows),
        label="synthetic inventory targets",
        error_type=EvidenceFailed,
    )
    if type(targets) is not list:
        raise EvidenceFailed(
            "synthetic inventory target snapshot is not an exact array"
        )
    for row in targets:
        if type(row) is not dict:
            raise EvidenceFailed(
                "synthetic inventory target is not an exact object"
            )
        v2_validate_synthetic_target_identity(row)
    campaign_root = semantic_root(
        [
            {"id": row["id"], "target_root": row["target_root"]}
            for row in sorted(targets, key=lambda value: value["id"])
        ]
    )
    normalized_rows = [
        {
            **{
                key: value
                for key, value in dict.items(row)
                if key != "semantic_root"
            },
            "campaign_epoch_root": campaign_root,
        }
        for row in sorted(targets, key=lambda value: value["id"])
    ]
    for normalized in normalized_rows:
        v2_validate_unreviewed_semantic_contract(
            normalized,
            label=f"synthetic inventory target {normalized['id']}",
        )
    rows = [v2_rooted(normalized) for normalized in normalized_rows]
    document = v2_rooted(
        {
            "schema": V2_INVENTORY_SCHEMA,
            "v1_inventory_root": semantic_root({"synthetic": True}),
            "campaign_epoch_root": campaign_root,
            "filters": {
                "priorities": [],
                "statuses": [],
                "targets": [],
                "readiness": [],
                "routes": [],
                "empty_means_all": True,
                "authority_filters_apply_to_selected_projection": True,
            },
            "rows": rows,
            "counts": {
                "targets": len(rows),
                "nonclosed": sum(row["status"] != "closed" for row in rows),
                "history": sum(row["status"] == "closed" for row in rows),
                "warnings": sum(len(row["missing_sections"]) for row in rows),
            },
            "nonclosed_ids_root": semantic_root(
                sorted(row["id"] for row in rows if row["status"] != "closed")
            ),
            "history_ids_root": semantic_root(
                sorted(row["id"] for row in rows if row["status"] == "closed")
            ),
            "no_claim": "synthetic inventory is test evidence only",
        }
    )
    try:
        return v2_validate_review_inventory(document)
    except HarnessError as error:
        raise EvidenceFailed(
            "synthetic inventory builder produced an invalid inventory"
        ) from error


def v2_synthetic_semantic_dimension_verdict(
    disposition: str,
    dimension: str,
) -> str:
    if disposition == "REMEDIATION_REQUIRED":
        return "FINDING" if dimension == "user_value" else "SATISFIED"
    if disposition == "REVIEWED_NO_CHANGE":
        return "SATISFIED"
    if disposition not in V2_SEMANTIC_EXACT_SIGNAL_DIMENSION:
        raise EvidenceFailed(
            f"unsupported synthetic semantic disposition {disposition!r}"
        )
    signal_dimension, signal = V2_SEMANTIC_EXACT_SIGNAL_DIMENSION[
        disposition
    ]
    return signal if dimension == signal_dimension else "SATISFIED"


def v2_synthetic_receipts(
    inventory: Mapping[str, Any],
    *,
    compatible: bool = False,
    declared: bool = False,
    manual: bool = False,
    semantic_reviewed: bool = False,
    semantic_disposition: str | None = None,
    external_verdict: str = "NODATA",
    conditional_verdict: str = "NODATA",
    gate_verdict: str = "NODATA",
) -> dict[str, Any]:
    rows = list(inventory["rows"])
    target_ids = sorted(row["id"] for row in rows)
    compatibility_key = "synthetic-compatible" if compatible else ""
    compatibility_root = ""
    if compatible:
        compatibility_root = semantic_root(
            {
                "compatibility_key": compatibility_key,
                "coordination": sorted((row["id"], "") for row in rows),
                "declared_domain": sorted(
                    (row["id"], "synthetic-domain") for row in rows
                ),
                "user_effect": sorted(
                    (row["id"], row["user_effect"]) for row in rows
                ),
                "reviewers": sorted(
                    (row["id"], "synthetic-reviewer", "fixture")
                    for row in rows
                ),
                "dependency_neighborhood": sorted(
                    (row["id"], row["dependency_neighborhood_root"]) for row in rows
                ),
                "target_ids": target_ids,
                "target_roots": sorted(
                    (row["id"], row["target_root"]) for row in rows
                ),
                "rationale": "all bound synthetic dimensions agree",
                "falsifier": "any bound dimension differs",
            }
        )
    receipts: list[dict[str, Any]] = []
    for target in rows:
        target_semantic_disposition = (
            semantic_disposition
            or str(target["semantic_review_disposition"])
        )
        semantic_dimensions = (
            [
                v2_semantic_dimension_receipt(
                    target_root=target["target_root"],
                    dimension=dimension,
                    verdict=v2_synthetic_semantic_dimension_verdict(
                        target_semantic_disposition,
                        dimension,
                    ),
                    reason=(
                        f"synthetic reviewed reason for {dimension}"
                    ),
                    falsifier=(
                        f"synthetic reviewed falsifier for {dimension}"
                    ),
                )
                for dimension in V2_SEMANTIC_REVIEW_DIMENSIONS
            ]
            if semantic_reviewed
            else []
        )
        source_closure = dict(target["source_closure"])
        if source_closure["required"] and semantic_reviewed:
            closure_verdict = next(
                row["verdict"]
                for row in semantic_dimensions
                if row["dimension"] == "source_and_terminal_closure"
            )
            if closure_verdict == "SATISFIED":
                source_closure["state"] = "ROOT_BOUND_REVIEWED_COMPLETE"
            elif closure_verdict == "NOT_APPLICABLE":
                source_closure["state"] = "ROOT_BOUND_NOT_APPLICABLE"
            else:
                source_closure["state"] = "ROOT_BOUND_REVIEW_BLOCKED"
        receipt = {
            "target_id": target["id"],
            "target_root": target["target_root"],
            "inventory_root": inventory["semantic_root"],
            "campaign_epoch_root": inventory["campaign_epoch_root"],
            "reviewer": (
                "synthetic-reviewer"
                if declared or compatible or semantic_reviewed
                else ""
            ),
            "reviewer_kind": (
                "fixture"
                if declared or compatible or semantic_reviewed
                else ""
            ),
            "coordination_assignee": "",
            "declared_domain_owner": (
                "synthetic-domain"
                if compatible or declared or semantic_reviewed
                else ""
            ),
            "declared_acceptance_owner": (
                "synthetic-acceptance-owner"
                if declared or compatible or semantic_reviewed
                else ""
            ),
            "implementation_owner": "synthetic-implementer",
            "evidence_owner": "synthetic-evidence-owner",
            "terminal_consumer": "synthetic-consumer",
            "source_closure": source_closure,
            "user_effect": target["user_effect"],
            "review_minutes": target["review_minutes"],
            "semantic_review_disposition": target_semantic_disposition,
            "semantic_review_dimensions": semantic_dimensions,
            "semantic_review_rationale": (
                "synthetic root-bound semantic adjudication"
                if semantic_reviewed
                else ""
            ),
            "semantic_review_falsifier": (
                "any target or dimension root drift invalidates adjudication"
                if semantic_reviewed
                else ""
            ),
            "compatibility_key": compatibility_key,
            "compatibility_target_ids": target_ids if compatible else [],
            "compatibility_receipt_root": compatibility_root,
            "compatibility_rationale": (
                "all bound synthetic dimensions agree" if compatible else ""
            ),
            "compatibility_falsifier": (
                "any bound dimension differs" if compatible else ""
            ),
            "manual_authorization": manual,
            "manual_authorization_source": (
                "synthetic-owner-declaration" if manual else ""
            ),
            "external_authority_adapter": (
                "fixture-independent-adapter"
                if external_verdict == "VALID"
                else ""
            ),
            "external_authority_receipt_root": (
                v2_fixture_gate_receipt_root(
                    "external",
                    target_root=target["target_root"],
                )
                if external_verdict == "VALID"
                else ""
            ),
            "external_authority_verdict": external_verdict,
            "conditional_capability_identity": (
                "fixture-atomic-cas"
                if conditional_verdict == "VALID"
                else ""
            ),
            "conditional_capability_receipt_root": (
                v2_fixture_gate_receipt_root(
                    "conditional",
                    target_root=target["target_root"],
                )
                if conditional_verdict == "VALID"
                else ""
            ),
            "conditional_capability_verdict": conditional_verdict,
            "gate_admission_receipt_root": (
                v2_fixture_gate_receipt_root(
                    "admission",
                    target_root=target["target_root"],
                )
                if gate_verdict == "VALID"
                else ""
            ),
            "gate_admission_verdict": gate_verdict,
            "no_claim": V2_REVIEW_RECEIPT_ROW_NO_CLAIM,
        }
        receipts.append(v2_rooted(receipt))
    return v2_rooted(
        {
            "schema": V2_REVIEW_RECEIPTS_SCHEMA,
            "inventory_root": inventory["semantic_root"],
            "campaign_epoch_root": inventory["campaign_epoch_root"],
            "receipts": receipts,
            "source": "SYNTHETIC_FIXTURE",
            "no_claim": V2_REVIEW_RECEIPTS_NO_CLAIM,
        }
    )


def v2_synthetic_authority(
    inventory: Mapping[str, Any],
    *,
    compatible: bool = False,
    declared: bool = False,
    manual: bool = False,
    semantic_reviewed: bool = False,
    semantic_disposition: str | None = None,
    external_verdict: str = "NODATA",
    conditional_verdict: str = "NODATA",
    gate_verdict: str = "NODATA",
    version: str = "0.2.19",
    allow_mechanical_fixture: bool = False,
) -> dict[str, Any]:
    claim_free = (
        not compatible
        and not declared
        and not manual
        and not semantic_reviewed
        and semantic_disposition is None
        and external_verdict == "NODATA"
        and conditional_verdict == "NODATA"
        and gate_verdict == "NODATA"
    )
    receipts = (
        v2_empty_review_receipts(
            inventory_root=inventory["semantic_root"],
            campaign_epoch_root=inventory["campaign_epoch_root"],
        )
        if claim_free
        else v2_synthetic_receipts(
            inventory,
            compatible=compatible,
            declared=declared,
            manual=manual,
            semantic_reviewed=semantic_reviewed,
            semantic_disposition=semantic_disposition,
            external_verdict=external_verdict,
            conditional_verdict=conditional_verdict,
            gate_verdict=gate_verdict,
        )
    )
    return v2_derive_authority(
        inventory,
        receipts,
        current_br_version=version,
        allow_mechanical_fixture=allow_mechanical_fixture,
    )


def v2_empty_prior_campaign() -> dict[str, Any]:
    return v2_rooted(
        {
            "state": "NOT_PROVIDED",
            "bundle_path": None,
            "terminal_root": None,
            "inventory_root": None,
            "rows": [],
            "no_claim": V2_PRIOR_CAMPAIGN_NOT_PROVIDED_NO_CLAIM,
        }
    )


def v2_fixture_manifest_with_history(
    manifest: Mapping[str, Any],
    history_contract: Mapping[str, Any],
) -> dict[str, Any]:
    fixture = dict(manifest)
    fixture["history_contract"] = dict(history_contract)
    fixture["content_identity"] = semantic_root(
        {
            "base_manifest_root": manifest["semantic_root"],
            "history_contract": history_contract,
            "purpose": "artifact-only self-test trust anchor",
        }
    )
    fixture.pop("semantic_root", None)
    fixture["semantic_root"] = semantic_root(fixture)
    return fixture


def v2_fixture_br_envelopes(
    full_issue: Mapping[str, Any],
) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any]]:
    status = str(full_issue["status"])
    exported_count = int(v2_issue_is_exportable(full_issue))
    fixture_ready = (
        status == "open"
        and full_issue.get("pinned") is not True
        and full_issue.get("ephemeral") is not True
        and full_issue.get("is_template") is not True
        and "-wisp-" not in str(full_issue["id"])
        and not str(full_issue.get("defer_until") or "")
        and not any(
            str(
                relation.get("type")
                or relation.get("dependency_type")
                or ""
            )
            in V2_BLOCKING_DEPENDENCY_TYPES
            and not v2_is_terminal_status(
                str(relation.get("status") or "")
            )
            for relation in (full_issue.get("dependencies") or ())
            if isinstance(relation, Mapping)
        )
    )
    tracker_status = v2_normalize_br_status(
        {
            "summary": {
                "average_lead_time_hours": 0.0,
                "blocked_issues": int(status == "blocked"),
                "closed_issues": int(status == "closed"),
                "deferred_issues": int(status == "deferred"),
                "draft_issues": int(status == "draft"),
                "epics_eligible_for_closure": 0,
                "in_progress_issues": int(status == "in_progress"),
                "open_issues": int(status == "open"),
                "pinned_issues": int(
                    status != "tombstone"
                    and (
                        full_issue.get("pinned") is True
                        or status == "pinned"
                    )
                ),
                "ready_issues": int(fixture_ready),
                "tombstone_issues": int(status == "tombstone"),
                "total_issues": int(status != "tombstone"),
            }
        },
        error_type=EvidenceFailed,
    )
    sync_status = v2_normalize_br_sync_status(
        {
            "db_newer": False,
            "dirty_count": 0,
            "git_export": {
                "available": False,
                "reason": "not_probed",
                "diagnostic_command": "br vcs-status --json",
            },
            "jsonl_content_hash": "0" * 64,
            "jsonl_exists": True,
            "jsonl_newer": False,
            "last_export_time": None,
            "last_import_time": None,
            "reliability_audit": {
                "anomalies": [],
                "anomaly_count": 0,
                "health": "healthy",
                "source": "sync.status",
            },
            "workspace_health": "healthy",
        },
        input_kind="released_live",
        error_type=EvidenceFailed,
    )
    chunk = {
        "byte_count": 1,
        "first_line_hash": "1" * 64,
        "hash": "2" * 64,
        "index": 0,
        "last_line_hash": "1" * 64,
        "line_count": 1,
        "start_line": 0,
    }
    action = {
        "action": "reuse_unchanged",
        "base_index": 0,
        "byte_count": 1,
        "candidate_index": 0,
        "line_count": 1,
        "start_line": 0,
    }
    chunks = [chunk] if exported_count else []
    actions = [action] if exported_count else []
    comparison = {
        "added_byte_count": 0,
        "added_chunks": 0,
        "base_byte_count": exported_count,
        "base_chunk_count": exported_count,
        "base_line_count": exported_count,
        "candidate_byte_count": exported_count,
        "candidate_chunk_count": exported_count,
        "candidate_line_count": exported_count,
        "changed_base_byte_count": 0,
        "changed_candidate_byte_count": 0,
        "changed_chunks": 0,
        "chunk_size_lines_match": True,
        "comparable_chunk_count": exported_count,
        "drift_detected": False,
        "first_changed_chunk_index": None,
        "removed_byte_count": 0,
        "removed_chunks": 0,
        "root_hashes_match": True,
        "safe_reuse_prefix_chunks": exported_count,
        "schema_versions_match": True,
        "unchanged_byte_count": exported_count,
        "unchanged_chunks": exported_count,
    }
    batches = (
        [
            {
                "action_count": 1,
                "actions": [action],
                "byte_count": 1,
                "candidate_end_index": 1,
                "candidate_start_index": 0,
                "index": 0,
                "kind": "candidate_output",
                "line_count": 1,
            }
        ]
        if exported_count
        else []
    )
    export_witness = v2_normalize_br_export_witness(
        {
            "base_comparison": comparison,
            "base_jsonl_path": str(
                REPO_ROOT / ".beads" / "beads.base.jsonl"
            ),
            "base_parallel_work_plan": {
                "batches": batches,
                "candidate_output_batches": exported_count,
                "deterministic_batch_order": True,
                "max_parallelism": (
                    V2_BR_WITNESS_CAPTURE_MAX_PARALLELISM
                ),
                "metadata_only_drop_batches": 0,
                "total_batches": exported_count,
            },
            "base_reuse_materialization": {
                "dropped_byte_count": 0,
                "dropped_chunks": 0,
                "output_byte_count": exported_count,
                "read_added_byte_count": 0,
                "read_added_chunks": 0,
                "rebuilt_byte_count": 0,
                "rebuilt_chunks": 0,
                "reused_byte_count": exported_count,
                "reused_chunks": exported_count,
            },
            "base_reuse_plan": {
                "actions": actions,
                "comparison": comparison,
                "schedule": {
                    "candidate_output_actions": exported_count,
                    "candidate_output_byte_count": exported_count,
                    "candidate_output_line_count": exported_count,
                    "deterministic_candidate_order": True,
                    "dropped_byte_count": 0,
                    "max_parallel_candidate_actions": exported_count,
                    "metadata_only_drop_actions": 0,
                    "read_added_actions": 0,
                    "read_added_byte_count": 0,
                    "rebuild_actions": 0,
                    "rebuild_byte_count": 0,
                    "reusable_actions": exported_count,
                    "reusable_byte_count": exported_count,
                    "total_actions": exported_count,
                },
            },
            "jsonl_path": str(REPO_ROOT / ".beads" / "issues.jsonl"),
            "witness": {
                "byte_count": exported_count,
                "chunk_size_lines": (
                    V2_BR_WITNESS_CAPTURE_CHUNK_SIZE_LINES
                ),
                "chunks": chunks,
                "line_count": exported_count,
                "root_hash": v2_br_witness_root(
                    schema_version="br.jsonl-witness.v1",
                    chunk_size_lines=(
                        V2_BR_WITNESS_CAPTURE_CHUNK_SIZE_LINES
                    ),
                    line_count=exported_count,
                    byte_count=exported_count,
                    chunks=chunks,
                ),
                "schema_version": "br.jsonl-witness.v1",
            },
        },
        input_kind="released_live",
        workspace_root=REPO_ROOT,
        error_type=EvidenceFailed,
    )
    v2_validate_live_envelope_consistency(
        tracker_status=tracker_status,
        sync_status=sync_status,
        export_witness=export_witness,
        full_issues=[full_issue],
        error_type=EvidenceFailed,
    )
    return tracker_status, sync_status, export_witness


def v2_fixture_audit_capture(
    full_issue: Mapping[str, Any],
    *,
    history_mode: bool,
) -> dict[str, Any]:
    if not history_mode:
        return v2_not_requested_audit_capture()
    audit_events = [
        {
            "id": 3,
            "event_type": "commented",
            "actor": "fixture-commenter",
            "timestamp": "2026-01-02T00:00:00.002000+00:00",
            "comment": "Fixture retained canonical comment.",
        },
        {
            "id": 2,
            "event_type": "closed",
            "actor": "fixture-closer",
            "timestamp": "2026-01-02T00:00:00.001000+00:00",
            "comment": full_issue["close_reason"],
        },
        {
            "id": 1,
            "event_type": "status_changed",
            "actor": "fixture-closer",
            "timestamp": "2026-01-02T00:00:00+00:00",
            "old_value": "open",
            "new_value": "closed",
        },
    ]
    normalized_audit = v2_normalize_audit_document(
        {"issue_id": full_issue["id"], "events": audit_events},
        issue_id=full_issue["id"],
    )
    audit_stdout = canonical_bytes(
        {"issue_id": full_issue["id"], "events": audit_events}
    )
    audit_argv = [
        "br",
        "audit",
        "log",
        full_issue["id"],
        "--json",
        *BR_READ_FLAGS,
    ]
    return v2_rooted(
        {
            "capture_count": 2,
            "worker_bound": V2_AUDIT_WORKERS,
            "issue_ids": [full_issue["id"]],
            "documents": [normalized_audit],
            "command_receipts": [
                {
                    "capture_ordinal": capture_ordinal,
                    "issue_id": full_issue["id"],
                    "argv": audit_argv,
                    "exit_code": 0,
                    "result_category": "SUCCESS",
                    "stdout_byte_length": len(audit_stdout),
                    "stdout_root": (
                        "sha256-v1:" + hashlib.sha256(audit_stdout).hexdigest()
                    ),
                    "normalized_document_root": normalized_audit[
                        "semantic_root"
                    ],
                    "stderr_byte_length": 0,
                    "stderr_root": (
                        "sha256-v1:" + hashlib.sha256(b"").hexdigest()
                    ),
                    "raw_stream_bodies_retained": False,
                }
                for capture_ordinal in (1, 2)
            ],
            "raw_stream_bodies_retained": False,
            "no_claim": V2_AUDIT_CAPTURE_NO_CLAIM,
        }
    )


def v2_released_fixture_issue(
    issue: Mapping[str, Any],
) -> dict[str, Any]:
    """Add the exact released-br wire fields used by replay fixtures."""
    released = dict(issue)
    issue_type = str(released.get("issue_type") or released.get("type") or "")
    if not issue_type:
        raise EvidenceFailed("released replay fixture lacks an issue type")
    released.setdefault("issue_type", issue_type)
    released.setdefault("created_at", "2026-01-01T00:00:00+00:00")
    released.setdefault("created_by", "fixture-creator")
    released.setdefault("compaction_level", 0)
    released.setdefault("original_size", 0)
    released.setdefault("source_repo", "frankensim-fixture")
    released.setdefault(
        "source_repo_path",
        "/fixture/private/frankensim-replay-source",
    )
    return released


def v2_replayable_fixture_bundle(
    manifest: Mapping[str, Any],
    *,
    subject_mode: str,
    issue: Mapping[str, Any] | None = None,
    oversize: bool = False,
    artifact_root: str = "target/v2-fixture",
    artifact_dir: str | None = None,
) -> tuple[
    dict[str, bytes],
    dict[str, Any],
    tuple[
        dict[str, Any],
        dict[str, Any],
        dict[str, Any],
        dict[str, Any],
        dict[str, Any],
        dict[str, Any],
        dict[str, bytes],
    ],
]:
    if subject_mode not in {"review-plan", "history-plan"}:
        raise EvidenceFailed("replayable fixture subject mode is unknown")
    resolved_artifact_dir = artifact_dir or f"{subject_mode}-run"
    history_mode = subject_mode == "history-plan"
    raw_issue = dict(
        issue
        or fixture_issue(
            issue_id=(
                "fixture-history-replay"
                if history_mode
                else "fixture-review-replay"
            ),
            status="closed" if history_mode else "open",
            priority=2,
            description=(
                "x" * (V2_CHILD_DESCRIPTION_CAP + 1)
                if oversize
                else "Exact released-tool fixture work with replay boundaries."
            ),
            acceptance="",
            labels=("reality-check", "authority:template-hygiene"),
        )
    )
    if history_mode:
        raw_issue.update(
            {
                "created_at": "2026-01-01T00:00:00+00:00",
                "created_by": "fixture-creator",
                "closed_at": "2026-01-02T00:00:00+00:00",
                "close_reason": "Fixture history replay completed.",
            }
        )
    raw_issue = v2_released_fixture_issue(raw_issue)
    full_issue = v2_full_issue_projection(raw_issue)
    fixture_status_scopes = v2_canonical_status_scopes(
        [*V2_RELEASED_KNOWN_STATUSES, full_issue["status"]]
    )
    fixture_audit = v2_fixture_audit_capture(
        full_issue,
        history_mode=history_mode,
    )
    missing = {
        full_issue["id"]: fixture_expected_missing(full_issue["type"])
    }
    lint = fixture_lint(
        [full_issue],
        missing,
        status_scopes=fixture_status_scopes,
    )
    accepted_manifest = dict(manifest)
    if history_mode:
        history_contract = dict(manifest["history_contract"])
        history_contract.update(
            {
                "legacy_coverage_anchor_issue": full_issue["id"],
                "legacy_coverage_anchor_closed_at": full_issue["closed_at"],
                "legacy_coverage_anchor_status_event_id": 1,
                "legacy_coverage_anchor_close_event_id": 2,
                "legacy_coverage_count": 0,
                "legacy_coverage_rows_root": semantic_root([]),
                "known_pair_max_skew_ms": 1_000,
            }
        )
        accepted_manifest = v2_fixture_manifest_with_history(
            manifest,
            history_contract,
        )
    synthetic_findings = independent_template_findings(full_issue)
    lint_ids = sorted(lint_result_map(lint))
    independent_ids = [full_issue["id"]] if synthetic_findings else []
    nonclosed_ids = (
        []
        if v2_is_terminal_status(full_issue["status"])
        else [full_issue["id"]]
    )
    selected_ids = sorted(
        set(lint_ids) | set(independent_ids) | set(nonclosed_ids)
    )
    fixture_command_output = canonical_bytes({"fixture": "bounded-read"})
    fixture_br_version = {
        "version": "0.2.19",
        "build": "release",
        "commit": "fixture-released-br",
        "branch": "fixture",
        "rust_version": "1.99.0-nightly",
        "target": "fixture",
        "features": [],
    }
    fixture_br_capabilities = {
        "tool": "br",
        "version": "0.2.19",
        "contract_version": "br.capabilities.v1",
        "features": [
            {
                "name": "local_first_issue_tracking",
                "description": "Fixture local-first contract.",
            }
        ],
        "commands": [
            {
                "name": "list",
                "summary": "List fixture issues",
                "operation": "read",
                "workspace": "required",
                "machine_output": ["json"],
                "examples": ["br list --json"],
            }
        ],
        "global_flags": [
            {
                "flag": "--json",
                "description": "Request machine-readable JSON output.",
            }
        ],
        "output_formats": ["json"],
        "exit_codes": [
            {
                "code": 0,
                "category": "success",
                "description": "Command completed successfully.",
            }
        ],
        "env_vars": [
            {
                "name": "BR_OUTPUT_FORMAT",
                "description": "Select the default output format.",
            }
        ],
        "safety": [
            {
                "name": "no_automatic_git_operations",
                "guarantee": "br does not run automatic git operations.",
            }
        ],
        "recommended_entrypoints": ["br capabilities --format json"],
    }
    (
        fixture_tracker_status,
        fixture_sync_status,
        fixture_export_witness,
    ) = v2_fixture_br_envelopes(full_issue)
    fixture_ready_issue_ids = (
        [full_issue["id"]]
        if fixture_tracker_status["summary"]["ready_issues"] == 1
        else []
    )
    fixture_membership_row = v2_retain_released_br_row(
        {
            **raw_issue,
            "dependency_count": len(
                raw_issue.get("dependencies") or []
            ),
            "dependent_count": len(
                raw_issue.get("dependents") or []
            ),
        }
    )
    fixture_list_rows = (
        []
        if full_issue["status"] == "tombstone"
        else [fixture_membership_row]
    )
    fixture_tombstone_rows = (
        [fixture_membership_row]
        if full_issue["status"] == "tombstone"
        else []
    )
    fixture_ready_rows = (
        [v2_retain_released_br_row(dict(raw_issue))]
        if fixture_ready_issue_ids
        else []
    )
    fixture_source_files = v2_source_file_identities()
    fixture_source_files[2] = {
        **fixture_source_files[2],
        "content_identity": accepted_manifest["content_identity"],
    }
    fixture_rule_contract = v2_source_rule_contract()
    fixture_round_projections = v2_observation_command_projection_entries(
        tracker_status=fixture_tracker_status,
        tracker_ready_issue_ids=fixture_ready_issue_ids,
        sync_status=fixture_sync_status,
        export_witness=fixture_export_witness,
        version=fixture_br_version,
        capabilities=fixture_br_capabilities,
        issue_ids=[full_issue["id"]],
        listed_rows=fixture_list_rows,
        tombstone_rows=fixture_tombstone_rows,
        tracker_ready_rows=fixture_ready_rows,
        full_issues=[full_issue],
        lint=lint,
    )
    fixture_projection_entries = [
        *fixture_round_projections,
        *fixture_round_projections,
    ]
    fixture_command_receipts = [
        {
            "capture_sequence": index,
            "capture_ordinal": (
                1 if index < len(fixture_round_projections) else 2
            ),
            "projection_kind": projection["projection_kind"],
            "normalized_projection_root": projection[
                "normalized_projection_root"
            ],
            "argv": argv,
            "exit_code": 0,
            "category": "SUCCESS",
            "stdout": {
                "bytes": len(fixture_command_output),
                "root": (
                    "sha256-v1:"
                    + hashlib.sha256(fixture_command_output).hexdigest()
                ),
                "body_retained": False,
            },
            "stderr": {
                "bytes": 0,
                "root": "sha256-v1:" + hashlib.sha256(b"").hexdigest(),
                "body_retained": False,
            },
            "cleanup_error_count": 0,
            "cleanup_error_kinds": [],
            "redaction_verdict": "RAW_STREAM_BODIES_NOT_RETAINED",
        }
        for index, (argv, projection) in enumerate(
            zip(
                v2_expected_observation_argv(
                    [full_issue["id"]],
                    status_scopes=fixture_status_scopes,
                ),
                fixture_projection_entries,
                strict=True,
            )
        )
    ]
    fixture_capture = v2_capture_state(
        issue_ids=[full_issue["id"]],
        full_issues=[full_issue],
        lint=lint,
        tracker_status=fixture_tracker_status,
        tracker_ready_issue_ids=fixture_ready_issue_ids,
        sync_status=fixture_sync_status,
        export_witness=fixture_export_witness,
        version=fixture_br_version,
        capabilities=fixture_br_capabilities,
        source_files=fixture_source_files,
        rule_contract=fixture_rule_contract,
        case_manifest_root=accepted_manifest["semantic_root"],
        case_manifest_content_identity=accepted_manifest[
            "content_identity"
        ],
        listed_rows=fixture_list_rows,
        tombstone_rows=fixture_tombstone_rows,
        tracker_ready_rows=fixture_ready_rows,
    )
    observation = v2_rooted(
        {
            "schema": V2_SOURCE_SCHEMA,
            "capture_contract": {
                "count": 2,
                "coherent": True,
                "tracker_cli": "br",
                "direct_tracker_file_access": False,
                "network_access": False,
                "audit_bracket": v2_rooted(
                    {
                        "state": (
                            "CAPTURED" if history_mode else "NOT_REQUESTED"
                        ),
                        "position": V2_AUDIT_CAPTURE_POSITION,
                        "source_before_ordinal": 1,
                        "source_after_ordinal": 2,
                        "audit_capture_ordinals": (
                            [1, 2] if history_mode else []
                        ),
                        "source_before_root": fixture_capture["semantic_root"],
                        "source_after_root": fixture_capture["semantic_root"],
                        "audit_capture_root": fixture_audit["semantic_root"],
                        "no_claim": V2_AUDIT_BRACKET_NO_CLAIM,
                    }
                ),
            },
            "br_version": fixture_br_version,
            "br_capabilities": fixture_br_capabilities,
            "tracker_status": fixture_tracker_status,
            "tracker_list_rows": fixture_list_rows,
            "tracker_list_rows_root": semantic_root(fixture_list_rows),
            "tracker_tombstone_rows": fixture_tombstone_rows,
            "tracker_tombstone_rows_root": semantic_root(
                fixture_tombstone_rows
            ),
            "tracker_ready_rows": fixture_ready_rows,
            "tracker_ready_issue_ids": fixture_ready_issue_ids,
            "tracker_ready_issue_ids_root": semantic_root(
                fixture_ready_issue_ids
            ),
            "tracker_ready_rows_root": semantic_root(fixture_ready_rows),
            "sync_status": fixture_sync_status,
            "export_witness": fixture_export_witness,
            "case_manifest_root": accepted_manifest["semantic_root"],
            "case_manifest_content_identity": accepted_manifest[
                "content_identity"
            ],
            "coherent_capture_root": fixture_capture["semantic_root"],
            "source_files": fixture_source_files,
            "rule_contract_root": semantic_root(fixture_rule_contract),
            "live_issue_count": 1,
            "live_issue_projection_root": semantic_root([full_issue]),
            "lint_issue_ids_root": semantic_root(lint_ids),
            "independent_finding_issue_ids_root": semantic_root(
                independent_ids
            ),
            "nonclosed_issue_ids_root": semantic_root(nonclosed_ids),
            "selected_review_issue_ids_root": semantic_root(selected_ids),
            "selected_review_issue_count": len(selected_ids),
            "nonclosed_issue_count": len(nonclosed_ids),
            "closed_finding_issue_count": len(
                (set(lint_ids) | set(independent_ids))
                - set(nonclosed_ids)
            ),
            "status_cut": list(fixture_status_scopes),
            "command_receipts": fixture_command_receipts,
            "no_claim": V2_SOURCE_OBSERVATION_NO_CLAIM,
        }
    )
    v1_inventory = assemble_inventory(
        lint,
        [full_issue],
        observation,
        (
            {full_issue["id"]: synthetic_findings}
            if synthetic_findings
            else None
        ),
        include_issue_rows_without_findings=True,
    )
    snapshot = LiveSnapshot(
        lint,
        [full_issue],
        observation,
        v1_inventory,
        {},
        (full_issue,),
    )
    campaign_root, _ = v2_campaign_epoch(snapshot)
    inventory = v2_build_inventory(
        snapshot,
        campaign_epoch_root=campaign_root,
        priority_filter=None,
        status_filter=None,
    )
    receipts = v2_empty_review_receipts(
        inventory_root=inventory["semantic_root"],
        campaign_epoch_root=inventory["campaign_epoch_root"],
    )
    authority = v2_derive_authority(
        inventory,
        receipts,
        current_br_version="0.2.19",
    )
    prior = v2_empty_prior_campaign()
    audit = fixture_audit
    source = v2_build_source_document(
        snapshot=snapshot,
        manifest=accepted_manifest,
        inventory=inventory,
        review_receipts=receipts,
        prior_campaign=prior,
        audit_capture=audit,
        priority_filter=None,
        status_filter=None,
    )
    if history_mode:
        review = v2_not_requested(
            schema=V2_REVIEW_PLAN_SCHEMA,
            mode=subject_mode,
            source_root=source["semantic_root"],
            inventory_root=inventory["semantic_root"],
            projection="review-plan",
        )
        optional: dict[str, bytes] = {}
        history = v2_build_history(
            source_root=source["semantic_root"],
            inventory=inventory,
            authority=authority,
            all_issues=snapshot.all_issues,
            audit_capture=audit,
            history_contract=accepted_manifest["history_contract"],
        )
    else:
        review, optional = v2_build_review_plan(
            inventory,
            authority,
            max_targets=V2_REVIEW_TARGET_DEFAULT,
        )
        history = v2_not_requested(
            schema=V2_HISTORY_SCHEMA,
            mode=subject_mode,
            source_root=source["semantic_root"],
            inventory_root=inventory["semantic_root"],
            projection="history",
        )
    zero = v2_build_zero_sets(
        source_root=source["semantic_root"],
        inventory=inventory,
        prior_campaign=prior,
        current_universe=snapshot.all_issues,
        current_finding_ids=v2_snapshot_current_finding_ids(snapshot),
    )
    reproduction = [
        str(SCRIPT_REL),
        f"--{subject_mode}",
        "--artifact-root",
        artifact_root,
        "--artifact-dir",
        resolved_artifact_dir,
    ]
    payloads = v2_bundle_payloads(
        mode=subject_mode,
        subject_mode=subject_mode,
        artifact_root=artifact_root,
        artifact_dir=resolved_artifact_dir,
        source=source,
        inventory=inventory,
        authority=authority,
        review_plan=review,
        history=history,
        zero_sets=zero,
        optional_payloads=optional,
        reproduction=reproduction,
        current_source_files=fixture_source_files,
    )
    components = (
        source,
        inventory,
        authority,
        review,
        history,
        zero,
        optional,
    )
    return payloads, accepted_manifest, components


def v2_plan_for_count(
    count: int,
    *,
    max_targets: int,
    review_minutes: int = 1,
) -> tuple[dict[str, Any], dict[str, Any], dict[str, bytes]]:
    inventory = v2_synthetic_inventory(
        [
            v2_synthetic_target(index, review_minutes=review_minutes)
            for index in range(count)
        ]
    )
    receipts = v2_synthetic_receipts(
        inventory,
        compatible=count > 1,
    )
    authority = v2_derive_authority(
        inventory,
        receipts,
        current_br_version="0.2.19",
    )
    plan, optional = v2_build_review_plan(
        inventory,
        authority,
        max_targets=max_targets,
        review_receipts=receipts,
    )
    return plan, authority, optional


def v2_authentic_projection_fixture(
    raw_issues: Sequence[Mapping[str, Any]],
    *,
    missing_by_id: Mapping[str, Sequence[str]] | None = None,
) -> tuple[
    list[dict[str, Any]],
    dict[str, Any],
    LiveSnapshot,
    dict[str, Any],
]:
    full_issues = sorted(
        (
            v2_full_issue_projection(v2_released_fixture_issue(issue))
            for issue in raw_issues
        ),
        key=lambda row: row["id"],
    )
    v2_assert_unique(
        [row["id"] for row in full_issues],
        label="authentic fixture issue IDs",
    )
    normalized_missing = {
        row["id"]: tuple(
            sorted(
                (
                    missing_by_id.get(
                        row["id"],
                        fixture_expected_missing(row["type"]),
                    )
                    if missing_by_id is not None
                    else fixture_expected_missing(row["type"])
                )
            )
        )
        for row in full_issues
    }
    fixture_status_scopes = v2_canonical_status_scopes(
        [
            *V2_RELEASED_KNOWN_STATUSES,
            *(row["status"] for row in full_issues),
        ]
    )
    lint = fixture_lint(
        full_issues,
        normalized_missing,
        status_scopes=fixture_status_scopes,
    )
    selected = [
        row
        for row in full_issues
        if not v2_is_terminal_status(row["status"])
        or (
            row["status"] == "closed"
            and normalized_missing[row["id"]]
        )
    ]
    tracker_ready_issue_ids = sorted(
        row["id"]
        for row in full_issues
        if v2_fixture_br_envelopes(row)[0]["summary"]["ready_issues"] == 1
    )
    source = fixture_source(
        full_issues,
        status_scopes=fixture_status_scopes,
    )
    source.pop("semantic_root", None)
    source["tracker_ready_issue_ids"] = tracker_ready_issue_ids
    source["tracker_ready_issue_ids_root"] = semantic_root(
        tracker_ready_issue_ids
    )
    source = v2_rooted(source)
    v1_inventory = assemble_inventory(
        lint,
        selected,
        source,
        include_issue_rows_without_findings=True,
    )
    snapshot = LiveSnapshot(
        lint,
        selected,
        source,
        v1_inventory,
        {},
        tuple(full_issues),
    )
    campaign_root, _ = v2_campaign_epoch(snapshot)
    inventory = v2_build_inventory(
        snapshot,
        campaign_epoch_root=campaign_root,
        priority_filter=None,
        status_filter=None,
    )
    return full_issues, lint, snapshot, inventory


def v2_execute_schema_cli_ux(
    case: Mapping[str, Any],
    manifest: Mapping[str, Any],
) -> dict[str, Any]:
    slug = str(case["id"]).removeprefix("template-lint-v2.")
    checks = V2CheckCollector(case["id"], case["assertion_id"])
    parameters = {"family": "schema-cli-ux", "slug": slug}
    if slug == "schema-closed-manifest":
        checks.check(
            "top-level-closed",
            set(manifest) - {"content_identity", "semantic_root"}
            == V2_MANIFEST_TOP_LEVEL_KEYS,
            expected=sorted(V2_MANIFEST_TOP_LEVEL_KEYS),
            observed=sorted(set(manifest) - {"content_identity", "semantic_root"}),
        )
        duplicate_rejected = False
        try:
            tomllib.loads("value = 1\nvalue = 2\n")
        except tomllib.TOMLDecodeError:
            duplicate_rejected = True
        checks.check(
            "duplicate-toml-key-refused",
            duplicate_rejected,
            expected=True,
            observed=duplicate_rejected,
        )
        checks.check(
            "schema-version",
            manifest["schema"] == V2_MANIFEST_SCHEMA
            and manifest["schema_version"] == 2,
            expected=(V2_MANIFEST_SCHEMA, 2),
            observed=(manifest["schema"], manifest["schema_version"]),
        )
        manifest_payload = bounded_read(REPO_ROOT / CASE_MANIFEST_V2_REL)
        accepted_identity = v2_validate_accepted_manifest_payload(
            manifest_payload
        )
        checks.check(
            "accepted-manifest-content-identity-exact",
            accepted_identity
            == manifest["content_identity"]
            == V2_ACCEPTED_MANIFEST_CONTENT_IDENTITY,
            expected=V2_ACCEPTED_MANIFEST_CONTENT_IDENTITY,
            observed={
                "loaded": manifest["content_identity"],
                "revalidated": accepted_identity,
            },
        )
        harness_payload = bounded_read(REPO_ROOT / SCRIPT_REL)
        harness_contract_identity = v2_validate_harness_contract_payload(
            harness_payload,
            manifest["harness_contract_identity"],
        )
        checks.check(
            "harness-contract-identity-exact",
            harness_contract_identity
            == manifest["harness_contract_identity"],
            expected=manifest["harness_contract_identity"],
            observed=harness_contract_identity,
        )
        hostile_identity_hooks = {
            "bytes": 0,
            "decode": 0,
            "encode": 0,
            "equality": 0,
            "rooted_getitem": 0,
            "rooted_items": 0,
            "rooted_iteration": 0,
            "string": 0,
        }

        class HostileIdentityBytes(bytes):
            def __bytes__(self) -> bytes:
                hostile_identity_hooks["bytes"] += 1
                raise RuntimeError("hostile identity bytes conversion")

            def decode(self, *_args: Any, **_kwargs: Any) -> str:
                hostile_identity_hooks["decode"] += 1
                raise RuntimeError("hostile identity bytes decode")

            def __eq__(self, _other: object) -> bool:
                hostile_identity_hooks["equality"] += 1
                raise RuntimeError("hostile identity bytes equality")

        class HostileIdentityString(str):
            def encode(self, *_args: Any, **_kwargs: Any) -> bytes:
                hostile_identity_hooks["encode"] += 1
                raise RuntimeError("hostile identity string encode")

            def __eq__(self, _other: object) -> bool:
                hostile_identity_hooks["equality"] += 1
                raise RuntimeError("hostile identity string equality")

            def __str__(self) -> str:
                hostile_identity_hooks["string"] += 1
                raise RuntimeError("hostile identity string conversion")

        class HostileRootedDocument(dict):
            def __getitem__(self, _key: object) -> Any:
                hostile_identity_hooks["rooted_getitem"] += 1
                raise RuntimeError("hostile rooted document getitem")

            def items(self) -> Any:
                hostile_identity_hooks["rooted_items"] += 1
                raise RuntimeError("hostile rooted document items")

            def __iter__(self) -> Iterator[Any]:
                hostile_identity_hooks["rooted_iteration"] += 1
                raise RuntimeError("hostile rooted document iteration")

        manifest_bytes_type_error = expect_error(
            EvidenceFailed,
            lambda: v2_validate_accepted_manifest_payload(
                HostileIdentityBytes(manifest_payload)
            ),
            contains="input must be exact bytes",
        )
        harness_bytes_type_error = expect_error(
            EvidenceFailed,
            lambda: v2_harness_contract_identity(
                HostileIdentityBytes(harness_payload)
            ),
            contains="input must be exact bytes",
        )
        harness_identity_type_error = expect_error(
            InputRefused,
            lambda: v2_validate_harness_contract_payload(
                harness_payload,
                HostileIdentityString(harness_contract_identity),
            ),
            contains="identity is malformed",
        )
        rooted_document_type_error = expect_error(
            EvidenceFailed,
            lambda: v2_rooted(HostileRootedDocument({"value": 1})),
            contains="not an exact object",
        )
        checks.check(
            "manifest-and-harness-identities-require-exact-scalar-types",
            manifest_bytes_type_error.terminal == "EvidenceFailed"
            and harness_bytes_type_error.terminal == "EvidenceFailed"
            and harness_identity_type_error.terminal == "InputRefused"
            and rooted_document_type_error.terminal == "EvidenceFailed"
            and hostile_identity_hooks
            == {
                "bytes": 0,
                "decode": 0,
                "encode": 0,
                "equality": 0,
                "rooted_getitem": 0,
                "rooted_items": 0,
                "rooted_iteration": 0,
                "string": 0,
            },
            expected={
                "terminals": [
                    "EvidenceFailed",
                    "EvidenceFailed",
                    "InputRefused",
                    "EvidenceFailed",
                ],
                "hostile_hook_calls": 0,
            },
            observed={
                "terminals": [
                    manifest_bytes_type_error.terminal,
                    harness_bytes_type_error.terminal,
                    harness_identity_type_error.terminal,
                    rooted_document_type_error.terminal,
                ],
                "hostile_hooks": hostile_identity_hooks,
            },
        )
        current_pin = V2_ACCEPTED_MANIFEST_CONTENT_IDENTITY.encode("ascii")
        alternate_pin = b"sha256-v1:" + (b"f" * 64)
        if current_pin == alternate_pin or harness_payload.count(current_pin) != 1:
            raise EvidenceFailed(
                "harness identity normalization fixture is not unique"
            )
        normalized_pin_payload = harness_payload.replace(
            current_pin,
            alternate_pin,
            1,
        )
        checks.check(
            "harness-manifest-pin-normalization-stable",
            v2_harness_contract_identity(normalized_pin_payload)
            == harness_contract_identity,
            expected=harness_contract_identity,
            observed=v2_harness_contract_identity(
                normalized_pin_payload
            ),
        )
        weakening_source = (
            b'            or check["passed"] is not True\n'
        )
        weakening_replacement = (
            b'            or type(check["passed"]) is not bool\n'
        )
        if harness_payload.count(weakening_source) != 1:
            raise EvidenceFailed(
                "harness semantic-weakening mutation site is not unique"
            )
        weakened_harness_payload = harness_payload.replace(
            weakening_source,
            weakening_replacement,
            1,
        )
        checks.refuses(
            "harness-semantic-weakening-with-stable-check-ids-refused",
            InputRefused,
            lambda: v2_validate_harness_contract_payload(
                weakened_harness_payload,
                manifest["harness_contract_identity"],
            ),
            contains="harness contract identity drifted",
            projection=lambda: {
                "accepted_harness_contract_identity": manifest[
                    "harness_contract_identity"
                ],
                "mutated_harness_contract_identity": (
                    v2_harness_contract_identity(weakened_harness_payload)
                ),
            },
            projection_label="HARNESS_CONTRACT_IDENTITIES",
        )
        drift_payload = manifest_payload + b"\n"
        original_document = tomllib.loads(manifest_payload.decode("utf-8"))
        drift_document = tomllib.loads(drift_payload.decode("utf-8"))
        checks.check(
            "trailing-newline-drift-preserves-toml-semantics",
            drift_document == original_document,
            expected=semantic_root(original_document),
            observed=semantic_root(drift_document),
        )
        identity_projection = lambda: {
            "accepted_identity": V2_ACCEPTED_MANIFEST_CONTENT_IDENTITY,
            "loaded_identity": manifest["content_identity"],
        }
        checks.refuses(
            "semantically-equivalent-manifest-byte-drift-refused",
            InputRefused,
