        def mutate_probe_result(
            callback: Callable[[dict[str, Any]], None],
        ) -> dict[str, Any]:
            candidate = strict_json_loads(
                canonical_bytes(valid_probe_result),
                label="valid assertion-result mutation seed",
                require_canonical=True,
            )
            candidate.pop("semantic_root", None)
            callback(candidate)
            return v2_rooted(candidate)

        def bind_result_checks(
            row: dict[str, Any],
            ordered_checks: Sequence[Mapping[str, Any]],
        ) -> None:
            row["ordered_checks"] = [
                dict(check) for check in ordered_checks
            ]
            row["ordered_check_roots"] = [
                str(check["semantic_root"]) for check in ordered_checks
            ]
            row["check_count"] = len(ordered_checks)

        depth_envelope_result = strict_json_loads(
            canonical_bytes(valid_probe_result),
            label="depth-envelope assertion-result seed",
            require_canonical=True,
        )
        depth_envelope_result.pop("semantic_root")
        depth_envelope_first_check = dict(
            depth_envelope_result["ordered_checks"][0]
        )
        depth_envelope_first_check.pop("semantic_root")
        depth_envelope_first_check["expected"] = depth_exact_value
        depth_envelope_first_check["observed"] = depth_exact_value
        depth_envelope_first_check = v2_rooted(
            depth_envelope_first_check
        )
        bind_result_checks(
            depth_envelope_result,
            [
                depth_envelope_first_check,
                *depth_envelope_result["ordered_checks"][1:],
            ],
        )
        depth_envelope_result = v2_rooted(depth_envelope_result)
        validated_depth_envelope_result = v2_validate_assertion_result(
            probe_case,
            depth_envelope_result,
            probe_obligation,
        )
        checks.check(
            "assertion-evidence-depth-survives-result-envelope",
            validated_depth_envelope_result["semantic_root"]
            == depth_envelope_result["semantic_root"],
            expected={
                "evidence_depth": V2_ASSERTION_EVIDENCE_DEPTH_CAP,
                "result_exact_wire_depth": (
                    V2_ASSERTION_RESULT_EXACT_WIRE_DEPTH_CAP
                ),
                "validated": True,
            },
            observed={
                "evidence_depth": V2_ASSERTION_EVIDENCE_DEPTH_CAP,
                "result_exact_wire_depth": (
                    V2_ASSERTION_RESULT_EXACT_WIRE_DEPTH_CAP
                ),
                "validated": (
                    validated_depth_envelope_result["semantic_root"]
                    == depth_envelope_result["semantic_root"]
                ),
            },
        )
        aggregate_case = next(
            row
            for row in manifest["case"]
            if row["id"]
            == "template-lint-v2.nomock-live-target-unchanged"
        )
        aggregate_obligation = manifest["check_obligations"][
            aggregate_case["assertion_id"]
        ]
        aggregate_slug = aggregate_case["id"].removeprefix(
            "template-lint-v2."
