        aggregate_family = next(
            family
            for first, last, family in V2_EXECUTOR_FAMILY_NAMES
            if first <= aggregate_case["ordinal"] <= last
        )
        aggregate_parameters = {
            "family": aggregate_family,
            "slug": aggregate_slug,
