        aggregate_budget_profiles: dict[str, tuple[int, int, int, int, int]] = {}

        def aggregate_budget_result(
            *,
            mode: str = "inline",
        ) -> tuple[
            dict[str, Any],
            int,
            int,
            bool,
            bool,
        ]:
            if mode == "item-dense":
                selected_case = {
                    "id": "n",
                    "assertion_id": "n",
                }
                selected_obligation = {
                    "ordered_check_ids": [
                        f"n{index}" for index in range(15)
                    ],
                }
                selected_parameters = {
                    "family": "n",
                    "slug": "n",
                }
            else:
                selected_case = next(
                    row
                    for row in manifest["case"]
                    if row["id"]
                    == "template-lint-v2.schema-executable-assertions"
                )
                if mode not in {"collision", "dense-small"}:
                    selected_case = aggregate_case
                selected_obligation = manifest["check_obligations"][
                    selected_case["assertion_id"]
                ]
                selected_slug = selected_case["id"].removeprefix(
                    "template-lint-v2."
                )
                selected_family = next(
                    family
                    for first, last, family in V2_EXECUTOR_FAMILY_NAMES
                    if first <= selected_case["ordinal"] <= last
                )
                selected_parameters = {
                    "family": selected_family,
                    "slug": selected_slug,
                }
            collector = V2CheckCollector(
                selected_case["id"],
                selected_case["assertion_id"],
            )
            for check_index, check_id in enumerate(
                selected_obligation["ordered_check_ids"]
            ):
                evidence_value = (
                    collision_shaped_value
                    if mode == "collision"
                    else dense_large_value
                    if mode in {"dense-large", "mixed-root-only"}
                    else paired_inline_value
                    if mode == "paired-inline"
                    else item_dense_value
                    if mode == "item-dense"
                    else dense_small_value
                    if mode == "dense-small"
                    else inline_exact_value
                )
                collector.check(
                    check_id,
                    True,
                    expected=(
                        inline_plus_one_value
                        if mode == "mixed-root-only" and check_index == 0
                        else evidence_value
                    ),
                    observed=evidence_value,
