        class DeceptiveAssertionString(str):
            def __eq__(self, _other: object) -> bool:
                deceptive_result_hooks["eq"] += 1
                return True

            def __ne__(self, _other: object) -> bool:
                deceptive_result_hooks["ne"] += 1
                return False

            def __str__(self) -> str:
                deceptive_result_hooks["str"] += 1
                raise RuntimeError("deceptive assertion string conversion")

        deceptive_scalar_result = strict_json_loads(
