        deceptive_hook_observation = dict(deceptive_result_hooks)

        def result_with_forged_evidence(value: Any) -> dict[str, Any]:
            candidate = strict_json_loads(
                canonical_bytes(valid_probe_result),
                label="forged assertion evidence seed",
                require_canonical=True,
            )
            candidate.pop("semantic_root")
            check = dict(candidate["ordered_checks"][0])
            check.pop("semantic_root")
            check["expected"] = value
            check = v2_rooted(check)
            bind_result_checks(
                candidate,
                [check, *candidate["ordered_checks"][1:]],
            )
            return v2_rooted(candidate)

