            bind_result_checks(row, row["ordered_checks"][:-1])

        def add_unobligated_check(row: dict[str, Any]) -> None:
            extra_check = v2_rooted(
                {
                    "check_id": "unobligated-extra-check",
                    "expected": True,
                    "observed": True,
                    "passed": True,
                }
