                "assertion-result-wrong-family-refused",
                mutate_probe_result(
                    lambda row: (
                        row["parameters"].__setitem__("family", "wrong-family"),
                        row.__setitem__(
                            "parameter_root",
                            semantic_root(row["parameters"]),
                        ),
                    )
                ),
            )
        )
        malformed_results.append(
            (
                "assertion-result-wrong-slug-refused",
                mutate_probe_result(
                    lambda row: (
                        row["parameters"].__setitem__("slug", "wrong-slug"),
                        row.__setitem__(
                            "parameter_root",
                            semantic_root(row["parameters"]),
                        ),
                    )
                ),
            )
        )
        malformed_results.append(
            (
                "assertion-result-parameter-root-refused",
                mutate_probe_result(
                    lambda row: row.__setitem__(
                        "parameter_root",
                        semantic_root({"wrong": "parameter"}),
                    )
                ),
            )
        )

        def false_check(row: dict[str, Any]) -> None:
            check = dict(row["ordered_checks"][0])
            check.pop("semantic_root", None)
            check["passed"] = False
            check = v2_rooted(check)
            bind_result_checks(
                row,
                [check, *row["ordered_checks"][1:]],
            )

        malformed_results.append(
            (
                "assertion-result-false-check-refused",
                mutate_probe_result(false_check),
            )
        )

        def duplicate_check(row: dict[str, Any]) -> None:
            check = dict(row["ordered_checks"][0])
            bind_result_checks(
                row,
                [check, dict(check), *row["ordered_checks"][1:]],
            )

        malformed_results.append(
            (
                "assertion-result-duplicate-check-refused",
                mutate_probe_result(duplicate_check),
            )
        )

        def stale_check_root(row: dict[str, Any]) -> None:
            check = dict(row["ordered_checks"][0])
            check["observed"] = False
            bind_result_checks(
                row,
                [check, *row["ordered_checks"][1:]],
            )

        malformed_results.append(
            (
                "assertion-result-stale-check-root-refused",
                mutate_probe_result(stale_check_root),
            )
        )
        malformed_results.append(
            (
                "assertion-result-ordered-root-refused",
                mutate_probe_result(
                    lambda row: row.__setitem__(
                        "ordered_check_roots",
                        [
                            semantic_root({"wrong": "check"}),
                            *row["ordered_check_roots"][1:],
                        ],
                    )
                ),
            )
        )

        def over_check_cap(row: dict[str, Any]) -> None:
            check = dict(row["ordered_checks"][0])
            row["ordered_checks"] = [
                dict(check)
                for _ in range(V2_ASSERTION_CHECKS_CAP + 1)
            ]
            row["ordered_check_roots"] = [
                check["semantic_root"]
                for _ in range(V2_ASSERTION_CHECKS_CAP + 1)
            ]
            row["check_count"] = V2_ASSERTION_CHECKS_CAP + 1

        malformed_results.append(
            (
                "assertion-result-check-cap-refused",
                mutate_probe_result(over_check_cap),
            )
        )
        for check_id, candidate in malformed_results:
            checks.refuses(
                check_id,
                EvidenceFailed,
                lambda candidate=candidate: v2_validate_assertion_result(
                    probe_case,
                    candidate,
                    probe_obligation,
                ),
            )

        def mutate_probe_obligation(
            callback: Callable[[dict[str, Any]], None],
        ) -> dict[str, Any]:
            candidate = {
                "case_id": str(probe_obligation["case_id"]),
                "check_count": int(probe_obligation["check_count"]),
                "ordered_check_ids": list(
                    probe_obligation["ordered_check_ids"]
                ),
            }
            callback(candidate)
            return candidate

        malformed_obligations: list[tuple[str, dict[str, Any]]] = [
            (
                "check-obligation-missing-field-refused",
                mutate_probe_obligation(
                    lambda row: row.pop("case_id")
                ),
            ),
            (
                "check-obligation-extra-field-refused",
                mutate_probe_obligation(
                    lambda row: row.__setitem__("unexpected", True)
                ),
            ),
            (
                "check-obligation-boolean-count-refused",
                mutate_probe_obligation(
                    lambda row: row.__setitem__("check_count", True)
                ),
            ),
            (
                "check-obligation-empty-refused",
                mutate_probe_obligation(
                    lambda row: row.update(
                        {
                            "check_count": 0,
                            "ordered_check_ids": [],
                        }
                    )
                ),
            ),
            (
                "check-obligation-count-mismatch-refused",
                mutate_probe_obligation(
                    lambda row: row.__setitem__(
                        "check_count",
                        int(row["check_count"]) + 1,
                    )
                ),
            ),
            (
                "check-obligation-cap-plus-one-refused",
                mutate_probe_obligation(
                    lambda row: row.update(
                        {
                            "check_count": V2_ASSERTION_CHECKS_CAP + 1,
                            "ordered_check_ids": [
                                f"check-{index:03d}"
                                for index in range(
                                    V2_ASSERTION_CHECKS_CAP + 1
                                )
                            ],
                        }
                    )
                ),
            ),
            (
                "check-obligation-duplicate-id-refused",
                mutate_probe_obligation(
                    lambda row: row.update(
                        {
                            "check_count": 2,
                            "ordered_check_ids": [
                                row["ordered_check_ids"][0],
                                row["ordered_check_ids"][0],
                            ],
                        }
                    )
                ),
            ),
            (
                "check-obligation-noncanonical-id-refused",
                mutate_probe_obligation(
                    lambda row: row.update(
                        {
                            "check_count": 1,
                            "ordered_check_ids": ["Noncanonical-ID"],
                        }
                    )
                ),
            ),
            (
                "check-obligation-overlong-id-refused",
                mutate_probe_obligation(
                    lambda row: row.update(
                        {
                            "check_count": 1,
                            "ordered_check_ids": [
                                "a" * (V2_CHECK_ID_BYTES_CAP + 1)
                            ],
                        }
                    )
                ),
            ),
            (
                "check-obligation-wrong-case-refused",
                mutate_probe_obligation(
                    lambda row: row.__setitem__(
                        "case_id",
                        str(manifest["case"][3]["id"]),
                    )
                ),
            ),
        ]
        for check_id, candidate in malformed_obligations:
            checks.refuses(
                check_id,
                EvidenceFailed,
                lambda candidate=candidate: v2_validate_check_obligation(
                    probe_case,
                    candidate,
