    elif slug == "cli-path-admission":
        valid = safe_relative("target/v2/évidence", label="fixture")
        checks.check(
            "nfc-relative-admitted",
            str(valid) == "target/v2/évidence",
            expected="target/v2/évidence",
            observed=str(valid),
        )
        hostile = (
            "",
            ".",
            "..",
            "a/../b",
            "/absolute",
            "~/alias",
            "C:\\alias",
            "a\\b",
            "bad\u0001path",
            "target/v2/e\u0301vidence",
        )
        for index, value in enumerate(hostile):
            checks.refuses(
                f"unsafe-path-{index:02d}",
                UsageRefused,
                lambda value=value: safe_relative(value, label="fixture"),
            )
        path_byte_cap_error = expect_error(
            UsageRefused,
            lambda: safe_relative(
                "a" * (CAPS["relative_path_bytes"] + 1),
                label="fixture",
            ),
            contains="path",
        )
        path_invalid_utf8_error = expect_error(
            UsageRefused,
            lambda: safe_relative("\udcff", label="fixture"),
            contains="valid UTF-8",
        )
        checks.check(
            "path-bounded-byte-cap",
            path_byte_cap_error.terminal == "UsageRefused"
            and path_invalid_utf8_error.terminal == "UsageRefused",
            expected={
                "byte_cap_terminal": "UsageRefused",
                "invalid_utf8_terminal": "UsageRefused",
            },
            observed={
                "byte_cap_terminal": path_byte_cap_error.terminal,
                "invalid_utf8_terminal": path_invalid_utf8_error.terminal,
            },
        )
        with fixture_br_lease():
            strict_root = resolve_safe(
                "target/beads-template-hygiene/strict-read-fixture",
                label="strict-read fixture root",
            )
            strict_root.mkdir(parents=True, exist_ok=True)
            regular_path = strict_root / "regular.json"
            linked_target_path = strict_root / "linked-target.json"
            linked_alias_path = strict_root / "linked-alias.json"
            symlink_path = strict_root / "symlink.json"
            real_parent = strict_root / "real-parent"
            parent_alias = strict_root / "parent-alias"
            parent_member = real_parent / "member.json"
            parent_alias_member = parent_alias / "member.json"
            race_path = strict_root / "race.json"
            regular_payload = b'{"fixture":"strict-read"}\n'
            write_once(regular_path, regular_payload)
            write_once(
                linked_target_path,
                b'{"fixture":"linked-target"}\n',
            )
            real_parent.mkdir(parents=True, exist_ok=True)
            write_once(
                parent_member,
                b'{"fixture":"parent-member"}\n',
            )
            write_once(
                race_path,
                b'{"fixture":"mid-read-change"}\n',
            )
            if not os.path.lexists(linked_alias_path):
                os.link(linked_target_path, linked_alias_path)
            linked_target_state = os.lstat(linked_target_path)
            linked_alias_state = os.lstat(linked_alias_path)
            if (
                linked_target_state.st_dev != linked_alias_state.st_dev
                or linked_target_state.st_ino != linked_alias_state.st_ino
                or linked_target_state.st_nlink < 2
            ):
                raise InfrastructureFailed(
                    "strict-read hard-link fixture identity differs"
                )
            if not os.path.lexists(symlink_path):
                os.symlink("regular.json", symlink_path)
            if not symlink_path.is_symlink() or os.readlink(
                symlink_path
            ) != "regular.json":
                raise InfrastructureFailed(
                    "strict-read leaf-symlink fixture identity differs"
                )
            if not os.path.lexists(parent_alias):
                os.symlink("real-parent", parent_alias)
            if not parent_alias.is_symlink() or os.readlink(
                parent_alias
            ) != "real-parent":
                raise InfrastructureFailed(
                    "strict-read parent-symlink fixture identity differs"
                )

            def strict_fixture_relative(path: Path) -> str:
                return path.relative_to(REPO_ROOT).as_posix()

            strict_fixture_paths = (
                strict_root,
                regular_path,
                linked_target_path,
                linked_alias_path,
                symlink_path,
                real_parent,
                parent_alias,
                parent_member,
                race_path,
            )

            def strict_fixture_additional_state() -> dict[str, bool]:
                return {
                    "os_pread_is_expected": (
                        v2_fixture_selected_pread_is_pristine()
                    )
                }

            regular_observed_payload = v2_read_repo_relative_file_strict(
                strict_fixture_relative(regular_path),
                label="strict-read regular fixture",
            )
            strict_acquisition_rows: dict[str, dict[str, Any]] = {}
            for acquisition_kind in ("root", "child", "leaf"):
                original_strict_open = os.open
                original_strict_close = os.close
                prior_strict_trace = sys.gettrace()
                opened_descriptors: list[int] = []
                closed_descriptors: list[int] = []
                acquisition_primary = RuntimeError(
                    f"synthetic strict-reader {acquisition_kind} acquisition "
                    "interruption"
                )
                acquisition_gap = RuntimeError(
                    "synthetic strict-reader ownership gap detected"
                )

                def tracked_strict_open(
                    path: Any,
                    flags: int,
                    *args: Any,
                    **kwargs: Any,
                ) -> int:
                    descriptor = original_strict_open(
                        path,
                        flags,
                        *args,
                        **kwargs,
                    )
                    list.append(opened_descriptors, descriptor)
                    return descriptor

                def tracked_strict_close(descriptor: int) -> None:
                    list.append(closed_descriptors, descriptor)
                    original_strict_close(descriptor)

                def interrupt_strict_acquisition(
                    frame: types.FrameType,
                    event: str,
                    _argument: Any,
                ) -> Any:
                    if (
                        event == "line"
                        and frame.f_code
                        is v2_read_repo_relative_file_strict.__code__
                    ):
                        frame_locals = frame.f_locals
                        directory_slots = frame_locals.get(
                            "directory_descriptor_slots",
                        )
                        file_slot = frame_locals.get(
                            "file_descriptor_slot",
                        )
                        owned_slots = [
                            *(
                                directory_slots
                                if type(directory_slots) is list
                                else []
                            ),
                            *(
                                [file_slot]
                                if type(file_slot) is list
                                else []
                            ),
                        ]
                        slot_owned = [
                            descriptor
                            for slot in owned_slots
                            if type(slot) is list and len(slot) == 1
                            for descriptor in (list.__getitem__(slot, 0),)
                            if type(descriptor) is int
                        ]
                        unowned = [
                            descriptor
                            for descriptor in opened_descriptors
                            if descriptor not in closed_descriptors
                            and descriptor not in slot_owned
                        ]
                        if unowned:
                            sys.settrace(None)
                            for descriptor in unowned:
                                tracked_strict_close(descriptor)
                            raise acquisition_gap
                        if (
                            acquisition_kind == "root"
                            and len(slot_owned) == 1
                            and "root_descriptor" not in frame_locals
                            or acquisition_kind == "child"
                            and len(slot_owned) == 2
                            and "child_descriptor" not in frame_locals
                            or acquisition_kind == "leaf"
                            and type(file_slot) is list
                            and len(file_slot) == 1
                            and type(list.__getitem__(file_slot, 0)) is int
                            and "file_descriptor" not in frame_locals
                        ):
                            sys.settrace(None)
                            raise acquisition_primary
                    return interrupt_strict_acquisition

                os.open = tracked_strict_open
                os.close = tracked_strict_close
                sys.settrace(interrupt_strict_acquisition)
                acquisition_observed: BaseException | None = None
                try:
                    v2_read_repo_relative_file_strict(
                        strict_fixture_relative(regular_path),
                        label=(
                            "strict-read acquisition interruption fixture"
                        ),
                    )
                except BaseException as error:
                    acquisition_observed = error
                finally:
                    sys.settrace(prior_strict_trace)
                    os.open = original_strict_open
                    os.close = original_strict_close
                dict.__setitem__(
                    strict_acquisition_rows,
                    acquisition_kind,
                    {
                        "primary_preserved": (
                            acquisition_observed is acquisition_primary
                        ),
                        "opened": opened_descriptors,
                        "closed": closed_descriptors,
                    },
                )

            strict_cleanup_owner_code = (
                V2_FUNCTION_CODE_DESCRIPTOR_CONTRACT.__get__(
                    v2_close_owned_descriptor_slots,
                    V2_FUNCTION_TYPE_CONTRACT,
                )
            )
            strict_cleanup_drain_codes = tuple(
                candidate
                for candidate in strict_cleanup_owner_code.co_consts
                if type(candidate) is types.CodeType
                and candidate.co_name == "drain_remaining"
            )
            if len(strict_cleanup_drain_codes) != 1:
                raise EvidenceFailed(
                    "strict-reader cleanup drain code identity is ambiguous"
                )
            strict_cleanup_drain_code = strict_cleanup_drain_codes[0]

            def exercise_strict_cleanup_interruption(
                interruption_kind: str,
            ) -> dict[str, Any]:
                original_strict_open = os.open
                original_strict_close = os.close
                prior_strict_trace = sys.gettrace()
                opened_descriptors: list[int] = []
                closed_descriptors: list[int] = []
                cleanup_primary = RuntimeError(
                    "synthetic strict-reader cleanup interruption"
                )

                def tracked_cleanup_open(
                    path: Any,
                    flags: int,
                    *args: Any,
                    **kwargs: Any,
                ) -> int:
                    descriptor = original_strict_open(
                        path,
                        flags,
                        *args,
                        **kwargs,
                    )
                    list.append(opened_descriptors, descriptor)
                    return descriptor

                def tracked_cleanup_close(descriptor: int) -> None:
                    list.append(closed_descriptors, descriptor)
                    original_strict_close(descriptor)

                def interrupt_strict_cleanup(
                    frame: types.FrameType,
                    event: str,
                    _argument: Any,
                ) -> Any:
                    if (
                        event == "line"
                        and frame.f_code is strict_cleanup_drain_code
                    ):
                        specifications = frame.f_locals.get(
                            "exact_specifications",
                        )
                        if type(specifications) is tuple:
                            populated = [
                                list.__getitem__(slot, 0)
                                for slot, _typed_error in specifications
                                if type(slot) is list
                                and len(slot) == 1
                                and type(list.__getitem__(slot, 0)) is int
                            ]
                            if (
                                interruption_kind == "before-first"
                                and opened_descriptors
                                and not closed_descriptors
                                and len(populated)
                                == len(opened_descriptors)
                                or interruption_kind == "between-attempts"
                                and len(closed_descriptors) == 1
                                and populated
                            ):
                                sys.settrace(None)
                                raise cleanup_primary
                    return interrupt_strict_cleanup

                cleanup_observed: BaseException | None = None
                os.open = tracked_cleanup_open
                os.close = tracked_cleanup_close
                sys.settrace(interrupt_strict_cleanup)
                try:
                    v2_read_repo_relative_file_strict(
                        strict_fixture_relative(regular_path),
                        label="strict-read cleanup interruption fixture",
                    )
                except BaseException as error:
                    cleanup_observed = error
                finally:
                    sys.settrace(prior_strict_trace)
                    os.open = original_strict_open
                    os.close = original_strict_close
                return {
                    "primary_preserved": cleanup_observed is cleanup_primary,
                    "opened": opened_descriptors,
                    "closed": closed_descriptors,
                }

            strict_cleanup_rows = {
                interruption_kind: exercise_strict_cleanup_interruption(
                    interruption_kind
                )
                for interruption_kind in (
                    "before-first",
                    "between-attempts",
                )
            }
            original_strict_root_stat = os.stat

            def changed_strict_root_path_stat(
                path: Any,
                *args: Any,
                **kwargs: Any,
            ) -> Any:
                state = original_strict_root_stat(path, *args, **kwargs)
                if (
                    path == REPO_ROOT
                    and kwargs.get("dir_fd") is None
                    and kwargs.get("follow_symlinks") is False
                ):
                    return types.SimpleNamespace(
                        st_dev=state.st_dev,
                        st_ino=state.st_ino + 1,
                        st_mode=state.st_mode,
                    )
                return state

            os.stat = changed_strict_root_path_stat
            try:
                strict_root_path_change_error = expect_error(
                    InputRefused,
                    lambda: v2_read_repo_relative_file_strict(
                        strict_fixture_relative(regular_path),
                        label="strict-read replaced root fixture",
                    ),
                    contains=(
                        "repository root path identity changed while being read"
                    ),
                )
            finally:
                os.stat = original_strict_root_stat

            checks.check(
                "strict-reader-regular-file-exact",
                regular_observed_payload == regular_payload
                and strict_root_path_change_error.terminal == "InputRefused"
                and strict_acquisition_rows["root"]["primary_preserved"]
                is True
                and len(strict_acquisition_rows["root"]["opened"]) == 1
                and strict_acquisition_rows["root"]["closed"]
                == strict_acquisition_rows["root"]["opened"]
                and strict_acquisition_rows["child"]["primary_preserved"]
                is True
                and len(strict_acquisition_rows["child"]["opened"]) == 2
                and strict_acquisition_rows["child"]["closed"]
                == list(reversed(
                    strict_acquisition_rows["child"]["opened"]
                ))
                and strict_acquisition_rows["leaf"]["primary_preserved"]
                is True
                and len(strict_acquisition_rows["leaf"]["opened"])
                == len(PurePosixPath(
                    strict_fixture_relative(regular_path)
                ).parts) + 1
                and strict_acquisition_rows["leaf"]["closed"]
                == list(reversed(
                    strict_acquisition_rows["leaf"]["opened"]
                ))
                and all(
                    row["primary_preserved"] is True
                    and row["closed"] == list(reversed(row["opened"]))
                    and len(row["closed"]) == len(row["opened"])
                    for row in strict_cleanup_rows.values()
                ),
                expected={
                    "bytes": len(regular_payload),
                    "content_root": "sha256-v1:"
                    + hashlib.sha256(regular_payload).hexdigest(),
                    "root_path_change_terminal": "InputRefused",
                    "acquisition_interruptions": {
                        "root": "owned-list-closes-root",
                        "child": "owned-list-closes-child-then-root",
                        "leaf": "owned-list-closes-leaf-child-root",
                    },
                    "cleanup_interruptions": (
                        "before-first-and-between-attempts-drain-exactly-once"
                    ),
                },
                observed={
                    "bytes": len(regular_observed_payload),
                    "content_root": "sha256-v1:"
                    + hashlib.sha256(
                        regular_observed_payload
                    ).hexdigest(),
                    "root_path_change_terminal": (
                        strict_root_path_change_error.terminal
                    ),
                    "acquisition_interruptions": strict_acquisition_rows,
                    "cleanup_interruptions": strict_cleanup_rows,
                },
            )
            v2_check_fixture_resource_refusal(
                checks,
                "strict-reader-leaf-symlink-refused",
                InputRefused,
                lambda: v2_fixture_read_selected_repo_relative_file_strict(
                    symlink_path,
                    label="strict-read leaf symlink",
                ),
                contains="cannot be opened safely",
                paths=strict_fixture_paths,
                operation_grants=(
                    ("strict-read", (symlink_path,)),
                    ("race-pristine-observation", None),
                ),
                additional_state=strict_fixture_additional_state,
            )
            v2_check_fixture_resource_refusal(
                checks,
                "strict-reader-hard-link-refused",
                InputRefused,
                lambda: v2_fixture_read_selected_repo_relative_file_strict(
                    linked_alias_path,
                    label="strict-read hard link",
                ),
                contains="not one uniquely linked regular file",
                paths=strict_fixture_paths,
                operation_grants=(
                    ("strict-read", (linked_alias_path,)),
                    ("race-pristine-observation", None),
                ),
                additional_state=strict_fixture_additional_state,
            )
            v2_check_fixture_resource_refusal(
                checks,
                "strict-reader-parent-symlink-refused",
                InputRefused,
                lambda: v2_fixture_read_selected_repo_relative_file_strict(
                    parent_alias_member,
                    label="strict-read parent symlink",
                ),
                contains="cannot be opened safely",
                paths=strict_fixture_paths,
                operation_grants=(
                    (
                        "strict-read",
                        (parent_alias_member,),
                    ),
                    ("race-pristine-observation", None),
                ),
                access_paths=(
                    *strict_fixture_paths,
                    parent_alias_member,
                ),
                additional_state=strict_fixture_additional_state,
            )
            v2_check_fixture_resource_refusal(
                checks,
                "strict-reader-cap-plus-one-refused",
                InputRefused,
                lambda: v2_fixture_read_selected_repo_relative_file_strict(
                    regular_path,
                    label="strict-read capped fixture",
                    cap=len(regular_payload) - 1,
                ),
                contains="bounded byte cap",
                paths=strict_fixture_paths,
                operation_grants=(
                    ("strict-read", (regular_path,)),
                    ("race-pristine-observation", None),
                ),
                additional_state=strict_fixture_additional_state,
            )

            v2_check_fixture_resource_refusal(
                checks,
                "strict-reader-mid-read-change-refused",
                InputRefused,
                lambda: v2_fixture_read_selected_with_mtime_race(
                    race_path,
                    label="strict-read changing fixture",
                ),
                contains="changed while being read",
                paths=strict_fixture_paths,
                operation_grants=(
                    ("synthetic-mtime-race-read", (race_path,)),
                    ("race-pristine-observation", None),
                ),
                additional_state=strict_fixture_additional_state,
            )
            access_only_path = parent_alias_member
            access_only_token_slot: list[Any] = [None]
            try:
                access_only_token = v2_fixture_selected_resource_scope_enter(
                    strict_fixture_paths,
                    (*strict_fixture_paths, access_only_path),
                    (("strict-read", (access_only_path,)),),
                    _token_slot=access_only_token_slot,
                )
            except BaseException:
                retained_access_only_token = list.__getitem__(
                    access_only_token_slot,
                    0,
                )
                if type(retained_access_only_token) is list:
                    v2_fixture_selected_resource_scope_leave(
                        retained_access_only_token
                    )
                    list.__setitem__(access_only_token_slot, 0, None)
                raise
            access_only_leaf_hooks = {
                "open": 0,
                "pread": 0,
                "readlink": 0,
            }
            original_access_only_open = os.open
            original_access_only_pread = os.pread
            original_access_only_readlink = os.readlink

            def observe_access_only_open(
                path: Any,
                *args: Any,
                **kwargs: Any,
            ) -> int:
                if path == "member.json":
                    access_only_leaf_hooks["open"] += 1
                return original_access_only_open(path, *args, **kwargs)

            def observe_access_only_pread(
                *args: Any,
                **kwargs: Any,
            ) -> bytes:
                access_only_leaf_hooks["pread"] += 1
                return original_access_only_pread(*args, **kwargs)

            def observe_access_only_readlink(
                *args: Any,
                **kwargs: Any,
            ) -> Any:
                access_only_leaf_hooks["readlink"] += 1
                return original_access_only_readlink(*args, **kwargs)

            os.open = observe_access_only_open
            os.pread = observe_access_only_pread
            os.readlink = observe_access_only_readlink
            try:
                access_only_error = expect_error(
                    InputRefused,
                    lambda: (
                        v2_fixture_read_selected_repo_relative_file_strict(
                            access_only_path,
                            label="strict-read access-only symlink parent",
                        )
                    ),
                    contains="cannot be opened safely",
                )
            finally:
                os.open = original_access_only_open
                os.pread = original_access_only_pread
                os.readlink = original_access_only_readlink
                v2_fixture_selected_resource_scope_leave(access_only_token)
                list.__setitem__(access_only_token_slot, 0, None)
            checks.check(
                "access-only-strict-refusal-never-touches-leaf",
                access_only_error.terminal == "InputRefused"
                and access_only_leaf_hooks
                == {"open": 0, "pread": 0, "readlink": 0}
                and v2_fixture_selected_resource_scope_is_pristine(),
                expected={
                    "terminal": "InputRefused",
                    "leaf_hooks": {"open": 0, "pread": 0, "readlink": 0},
                    "scope_pristine": True,
                },
                observed={
                    "terminal": access_only_error.terminal,
                    "leaf_hooks": access_only_leaf_hooks,
                    "scope_pristine": (
                        v2_fixture_selected_resource_scope_is_pristine()
                    ),
                },
            )
    elif slug == "cli-review-receipts":
        inventory = v2_synthetic_inventory([v2_synthetic_target(0)])
        empty = v2_load_review_receipts(None, inventory=inventory)
        authority = v2_derive_authority(
            inventory,
            empty,
            current_br_version="0.2.19",
        )
        checks.check(
            "absent-receipt-review-only",
            authority["decisions"][0]["readiness"] == "REVIEW_ONLY"
            and authority["decisions"][0]["remediation_route"] == "ANALYSIS_ONLY",
            expected=("REVIEW_ONLY", "ANALYSIS_ONLY"),
            observed=(
                authority["decisions"][0]["readiness"],
                authority["decisions"][0]["remediation_route"],
            ),
        )
        checks.refuses(
            "duplicate-json-key",
            InputRefused,
            lambda: strict_json_loads(
                '{"target":1,"target":2}\n',
                label="fixture receipt",
            ),
            contains="duplicate",
        )
        expected_actions = {
            "REMEDIATION_REQUIRED": "REMEDIATION_CANDIDATE",
            "REVIEWED_NO_CHANGE": "RETAINED_ADJUDICATION",
            "ROLLUP_ONLY": "RETAINED_ADJUDICATION",
            "CONTRIBUTION_ONLY": "RETAINED_ADJUDICATION",
            "BLOCKED_AUTHORITY": "AUTHORITY_RESOLUTION_REQUIRED",
            "TYPED_INAPPLICABLE": "RETAINED_ADJUDICATION",
        }
        reviewed_documents: dict[str, dict[str, Any]] = {}
        for disposition, expected_action in expected_actions.items():
            receipts = v2_synthetic_receipts(
                inventory,
                semantic_reviewed=True,
                semantic_disposition=disposition,
            )
            v2_validate_receipt_bindings(receipts, inventory)
            decision = v2_derive_authority(
                inventory,
                receipts,
                current_br_version="0.2.19",
            )["decisions"][0]
            reviewed_documents[disposition] = receipts
            checks.check(
                f"semantic-disposition-{disposition.lower()}",
                decision["semantic_review_disposition"] == disposition
                and decision["semantic_review_receipt_state"]
                == "ROOT_BOUND_REVIEWED"
                and decision["semantic_review_action"] == expected_action
                and len(decision["semantic_review_dimensions"])
                == len(V2_SEMANTIC_REVIEW_DIMENSIONS)
                and [
                    row["dimension"]
                    for row in decision["semantic_review_dimensions"]
                ]
                == list(V2_SEMANTIC_REVIEW_DIMENSIONS)
                and all(
                    isinstance(row["evidence_root"], str)
                    and row["evidence_root"].startswith("sha256-v1:")
                    for row in decision["semantic_review_dimensions"]
                ),
                expected={
                    "disposition": disposition,
                    "state": "ROOT_BOUND_REVIEWED",
                    "action": expected_action,
                    "dimensions": len(V2_SEMANTIC_REVIEW_DIMENSIONS),
                },
                observed={
                    "disposition": decision[
                        "semantic_review_disposition"
                    ],
                    "state": decision["semantic_review_receipt_state"],
                    "action": decision["semantic_review_action"],
                    "dimensions": len(
                        decision["semantic_review_dimensions"]
                    ),
                },
            )

        def reroot_receipt_document(
            document: Mapping[str, Any],
            mutation: Callable[[dict[str, Any]], None],
        ) -> dict[str, Any]:
            candidate = json.loads(canonical_bytes(document))
            candidate.pop("semantic_root", None)
            receipt = candidate["receipts"][0]
            receipt.pop("semantic_root", None)
            mutation(receipt)
            candidate["receipts"][0] = v2_rooted(receipt)
            return v2_rooted(candidate)

        def set_semantic_dimension_verdict(
            receipt: dict[str, Any],
            dimension: str,
            verdict: str,
        ) -> None:
            dimension_receipt = next(
                row
                for row in receipt["semantic_review_dimensions"]
                if row["dimension"] == dimension
            )
            dimension_receipt.update(
                v2_semantic_dimension_receipt(
                    target_root=receipt["target_root"],
                    dimension=dimension,
                    verdict=verdict,
                    reason=dimension_receipt["reason"],
                    falsifier=dimension_receipt["falsifier"],
                )
            )

        base_reviewed = reviewed_documents["REMEDIATION_REQUIRED"]
        malformed_receipts: list[
            tuple[str, Callable[[dict[str, Any]], None], str]
        ] = [
            (
                "manual-authorization-string-false",
                lambda row: row.__setitem__(
                    "manual_authorization",
                    "false",
                ),
                "not boolean",
            ),
            (
                "partial-semantic-dimensions",
                lambda row: row.__setitem__(
                    "semantic_review_dimensions",
                    row["semantic_review_dimensions"][:-1],
                ),
                "every semantic dimension",
            ),
            (
                "reordered-semantic-dimensions",
                lambda row: row.__setitem__(
                    "semantic_review_dimensions",
                    list(reversed(row["semantic_review_dimensions"])),
                ),
                "noncanonical",
            ),
            (
                "nodata-reviewed-dimension",
                lambda row: row["semantic_review_dimensions"][0].update(
                    {"verdict": "NODATA"}
                ),
                "reviewed verdict",
            ),
            (
                "wrong-dimension-evidence-root",
                lambda row: row["semantic_review_dimensions"][0].update(
                    {"evidence_root": semantic_root({"wrong": "scope"})}
                ),
                "evidence root",
            ),
            (
                "missing-dimension-reason",
                lambda row: row["semantic_review_dimensions"][0].update(
                    {"reason": ""}
                ),
                "reason",
            ),
            (
                "missing-dimension-falsifier",
                lambda row: row["semantic_review_dimensions"][0].update(
                    {"falsifier": ""}
                ),
                "falsifier",
            ),
            (
                "stale-target-root",
                lambda row: row.__setitem__(
                    "target_root",
                    semantic_root({"stale": "target"}),
                ),
                "target root drifted",
            ),
            (
                "row-provenance-envelope-mismatch",
                lambda row: row.__setitem__(
                    "inventory_root",
                    semantic_root({"different": "inventory"}),
                ),
                "differs from its provenance envelope",
            ),
            (
                "affirmative-review-receipt-row-no-claim",
                lambda row: row.__setitem__(
                    "no_claim",
                    "this receipt authorizes live mutation and release",
                ),
                "no-claim boundary differs",
            ),
        ]
        for name, mutation, diagnostic in malformed_receipts:
            candidate = reroot_receipt_document(base_reviewed, mutation)
            checks.refuses(
                name,
                InputRefused,
                lambda candidate=candidate: v2_validate_receipt_bindings(
                    candidate,
                    inventory,
                ),
                contains=diagnostic,
            )
        source_provenance_mismatch = reroot_receipt_document(
            base_reviewed,
            lambda row: row.__setitem__(
                "campaign_epoch_root",
                semantic_root({"different": "campaign"}),
            ),
        )
        checks.refuses(
            "source-row-provenance-envelope-mismatch-refused",
            InputRefused,
            lambda: v2_validate_source_review_receipt_envelope(
                source_provenance_mismatch
            ),
            contains="differs from its provenance envelope",
        )
        stale_empty_receipts = v2_empty_review_receipts(
            inventory_root=semantic_root({"stale": "empty-inventory"}),
            campaign_epoch_root=semantic_root({"stale": "empty-campaign"}),
        )
        checks.refuses(
            "empty-receipt-envelope-remains-current-campaign-bound",
            InputRefused,
            lambda: v2_validate_receipt_bindings(
                stale_empty_receipts,
                inventory,
            ),
            contains="envelope does not bind the current campaign",
        )
        affirmative_document_claim = strict_json_loads(
            canonical_bytes(base_reviewed),
            label="affirmative review receipt document seed",
            require_canonical=True,
        )
        affirmative_document_claim.pop("semantic_root", None)
        affirmative_document_claim["no_claim"] = (
            "these receipts authorize tracker mutation and release"
        )
        affirmative_document_claim = v2_rooted(
            affirmative_document_claim
        )
        checks.refuses(
            "affirmative-review-receipt-document-no-claim-refused",
            InputRefused,
            lambda: v2_validate_receipt_bindings(
                affirmative_document_claim,
                inventory,
            ),
            contains="different source or schema",
        )

        mixed_no_change = reroot_receipt_document(
            reviewed_documents["REVIEWED_NO_CHANGE"],
            lambda row: row["semantic_review_dimensions"][1].update(
                {
                    "verdict": "ROUTED",
                    "evidence_root": semantic_root(
                        {
                            "target_root": row["target_root"],
                            "dimension": row[
                                "semantic_review_dimensions"
                            ][1]["dimension"],
                            "verdict": "ROUTED",
                            "reason": row[
                                "semantic_review_dimensions"
                            ][1]["reason"],
                            "falsifier": row[
                                "semantic_review_dimensions"
                            ][1]["falsifier"],
                        }
                    ),
                }
            ),
        )
        checks.refuses(
            "reviewed-no-change-mixed-verdict-refused",
            InputRefused,
            lambda: v2_validate_receipt_bindings(
                mixed_no_change,
                inventory,
            ),
            contains="every dimension SATISFIED",
        )

        for disposition, (
            signal_dimension,
            signal,
        ) in V2_SEMANTIC_EXACT_SIGNAL_DIMENSION.items():
            wrong_dimension = next(
                dimension
                for dimension in V2_SEMANTIC_REVIEW_DIMENSIONS
                if dimension != signal_dimension
            )

            def relocate_signal(
                row: dict[str, Any],
                *,
                expected_dimension: str = signal_dimension,
                misplaced_dimension: str = wrong_dimension,
                misplaced_signal: str = signal,
            ) -> None:
                set_semantic_dimension_verdict(
                    row,
                    expected_dimension,
                    "SATISFIED",
                )
                set_semantic_dimension_verdict(
                    row,
                    misplaced_dimension,
                    misplaced_signal,
                )

            wrong_dimension_receipt = reroot_receipt_document(
                reviewed_documents[disposition],
                relocate_signal,
            )
            checks.refuses(
                f"{disposition.lower()}-wrong-signal-dimension-refused",
                InputRefused,
                lambda candidate=wrong_dimension_receipt: (
                    v2_validate_receipt_bindings(candidate, inventory)
                ),
                contains=f"requires exactly {signal_dimension}={signal}",
            )

            def add_ambiguous_signal(
                row: dict[str, Any],
                *,
                extra_dimension: str = wrong_dimension,
                extra_signal: str = signal,
            ) -> None:
                set_semantic_dimension_verdict(
                    row,
                    extra_dimension,
                    extra_signal,
                )

            ambiguous_receipt = reroot_receipt_document(
                reviewed_documents[disposition],
                add_ambiguous_signal,
            )
            checks.refuses(
                f"{disposition.lower()}-multiple-signal-dimensions-refused",
                InputRefused,
                lambda candidate=ambiguous_receipt: (
                    v2_validate_receipt_bindings(candidate, inventory)
                ),
                contains=f"requires exactly {signal_dimension}={signal}",
            )

        remediation_without_finding = reroot_receipt_document(
            reviewed_documents["REMEDIATION_REQUIRED"],
            lambda row: set_semantic_dimension_verdict(
                row,
                "user_value",
                "SATISFIED",
            ),
        )
        checks.refuses(
            "remediation-without-finding-refused",
            InputRefused,
            lambda: v2_validate_receipt_bindings(
                remediation_without_finding,
                inventory,
            ),
            contains="requires at least one FINDING",
        )
        remediation_with_routed_signal = reroot_receipt_document(
            reviewed_documents["REMEDIATION_REQUIRED"],
            lambda row: set_semantic_dimension_verdict(
                row,
                "dependencies",
                "ROUTED",
            ),
        )
        checks.refuses(
            "remediation-ambiguous-routed-signal-refused",
            InputRefused,
            lambda: v2_validate_receipt_bindings(
                remediation_with_routed_signal,
                inventory,
            ),
            contains="allows only SATISFIED or FINDING",
        )
        remediation_with_multiple_findings = reroot_receipt_document(
            reviewed_documents["REMEDIATION_REQUIRED"],
            lambda row: set_semantic_dimension_verdict(
                row,
                "dependencies",
                "FINDING",
            ),
        )
        v2_validate_receipt_bindings(
            remediation_with_multiple_findings,
            inventory,
        )
        checks.check(
            "remediation-multiple-findings-admitted",
            True,
            expected="admitted",
            observed="admitted",
        )

        blocked_without_acceptance = reroot_receipt_document(
            reviewed_documents["BLOCKED_AUTHORITY"],
            lambda row: row.__setitem__(
                "declared_acceptance_owner",
                "",
            ),
        )
        blocked_decision = v2_derive_authority(
            inventory,
            blocked_without_acceptance,
            current_br_version="0.2.19",
        )["decisions"][0]
        checks.check(
            "blocked-review-retained-without-acceptance-authority",
            blocked_decision["semantic_review_receipt_state"]
            == "ROOT_BOUND_REVIEWED"
            and blocked_decision["semantic_review_action"]
            == "AUTHORITY_RESOLUTION_REQUIRED"
            and blocked_decision["readiness"] == "REVIEW_ONLY"
            and blocked_decision["reviewer_provenance"]["reviewer"]
            == "synthetic-reviewer"
            and blocked_decision["declared_acceptance_owner"] == "",
            expected={
                "state": "ROOT_BOUND_REVIEWED",
                "action": "AUTHORITY_RESOLUTION_REQUIRED",
                "readiness": "REVIEW_ONLY",
            },
            observed={
                "state": blocked_decision[
                    "semantic_review_receipt_state"
                ],
                "action": blocked_decision["semantic_review_action"],
                "readiness": blocked_decision["readiness"],
                "reviewer": blocked_decision["reviewer_provenance"][
                    "reviewer"
                ],
            },
        )

        two_inventory = v2_synthetic_inventory(
            [v2_synthetic_target(0), v2_synthetic_target(1)]
        )
        reversed_receipts = v2_synthetic_receipts(
            two_inventory,
            semantic_reviewed=True,
        )
        reversed_receipts = dict(reversed_receipts)
        reversed_receipts.pop("semantic_root", None)
        reversed_receipts["receipts"] = list(
            reversed(reversed_receipts["receipts"])
        )
        reversed_receipts = v2_rooted(reversed_receipts)
        checks.refuses(
            "noncanonical-receipt-row-order-refused",
            InputRefused,
            lambda: v2_validate_receipt_bindings(
                reversed_receipts,
                two_inventory,
            ),
            contains="canonical target order",
        )
        external_source = strict_json_loads(
            canonical_bytes(base_reviewed),
            label="external review-receipt source seed",
            require_canonical=True,
        )
        external_source.pop("semantic_root", None)
        external_source["source"] = "fixtures/review-receipts.json"
        source_payload = v2_reconstructed_review_receipt_source_payload(
            external_source
        )
        external_source["source_identity"] = {
            "path": "fixtures/review-receipts.json",
            "bytes": len(source_payload),
            "root": (
                "sha256-v1:" + hashlib.sha256(source_payload).hexdigest()
            ),
        }
        external_source = v2_rooted(external_source)
        v2_validate_receipt_bindings(external_source, inventory)
        checks.check(
            "external-receipt-source-identity-binds-canonical-input",
            True,
            expected={
                "bytes": len(source_payload),
                "root": (
                    "sha256-v1:"
                    + hashlib.sha256(source_payload).hexdigest()
                ),
            },
            observed=external_source["source_identity"],
        )

        def reroot_external_source(
            mutation: Callable[[dict[str, Any]], None],
        ) -> dict[str, Any]:
            candidate = strict_json_loads(
                canonical_bytes(external_source),
                label="external receipt identity mutation seed",
                require_canonical=True,
            )
            candidate.pop("semantic_root", None)
            mutation(candidate)
            return v2_rooted(candidate)

        missing_source_identity = reroot_external_source(
            lambda value: value.pop("source_identity")
        )
        checks.refuses(
            "external-receipt-missing-source-identity-refused",
            InputRefused,
            lambda: v2_validate_receipt_bindings(
                missing_source_identity,
                inventory,
            ),
            contains="lacks its required file identity",
        )
        forged_source_identity = reroot_external_source(
            lambda value: value["source_identity"].__setitem__(
                "root",
                semantic_root({"forged": "source bytes"}),
            )
        )
        checks.refuses(
            "external-receipt-forged-source-identity-refused",
            InputRefused,
            lambda: v2_validate_receipt_bindings(
                forged_source_identity,
                inventory,
            ),
            contains="does not bind reconstructed canonical bytes",
        )

        def rebound_external_source_path(
            relative_path: str,
        ) -> dict[str, Any]:
            candidate = strict_json_loads(
                canonical_bytes(external_source),
                label="external receipt source-path mutation seed",
                require_canonical=True,
            )
            candidate.pop("semantic_root", None)
            candidate["source"] = relative_path
            candidate["source_identity"]["path"] = relative_path
            payload = v2_reconstructed_review_receipt_source_payload(
                candidate
            )
            candidate["source_identity"]["bytes"] = len(payload)
            candidate["source_identity"]["root"] = (
                "sha256-v1:" + hashlib.sha256(payload).hexdigest()
            )
            return v2_rooted(candidate)

        invalid_external_suffixes = (
            (
                "external-receipt-txt-source-refused",
                "fixtures/review-receipts.txt",
            ),
            (
                "external-receipt-jsonl-source-refused",
                "fixtures/review-receipts.jsonl",
