                {
                    "schema": V2_ZERO_SETS_SCHEMA,
                    "counts": {
                        "zero_receipts": 25 if not count else 24
                    },
                }
            )
            return v2_synopsis(
                subject_mode="review-plan",
                review_plan=review,
                history=history,
                authority=authority,
                zero_sets=zero,
                artifact_dir="target/v2/fixture",
                reproduction=["script", "--review-plan"],
                explain_target=None,
            )

        if slug == "ux-empty-synopsis":
