                    and synopsis["selected_ids"]["shown"]
                    == min(count, V2_SYNOPSIS_ID_PREVIEW_CAP)
                    and synopsis["selected_ids"]["ids"] == expected_ids
                    and synopsis["selected_ids"]["truncated"]
                    == (count > V2_SYNOPSIS_ID_PREVIEW_CAP)
                    and (
                        synopsis["selected_ids"]["notice"] is not None
                    )
                    == (count > V2_SYNOPSIS_ID_PREVIEW_CAP),
                    expected={
                        "total": count,
                        "shown": min(
                            count,
                            V2_SYNOPSIS_ID_PREVIEW_CAP,
                        ),
                        "ids": expected_ids,
                        "truncated": (
                            count > V2_SYNOPSIS_ID_PREVIEW_CAP
                        ),
                    },
                    observed=synopsis["selected_ids"],
                )
            synopsis = boundary_synopses[
                V2_SYNOPSIS_ID_PREVIEW_CAP + 1
            ]
            exact_bytes = len(canonical_bytes(synopsis))
            original_synopsis_cap = V2_SYNOPSIS_BYTES_CAP
            injected_results: dict[str, Any] = {}
            try:
                globals()["V2_SYNOPSIS_BYTES_CAP"] = exact_bytes + 1
                injected_results["n_plus_one"] = fixture_synopsis(
                    V2_SYNOPSIS_ID_PREVIEW_CAP + 1
                )
                globals()["V2_SYNOPSIS_BYTES_CAP"] = exact_bytes
                injected_results["n"] = fixture_synopsis(
                    V2_SYNOPSIS_ID_PREVIEW_CAP + 1
                )
                globals()["V2_SYNOPSIS_BYTES_CAP"] = exact_bytes - 1
                try:
                    fixture_synopsis(V2_SYNOPSIS_ID_PREVIEW_CAP + 1)
                except EvidenceFailed as error:
                    injected_results["n_minus_one"] = error
            finally:
                globals()["V2_SYNOPSIS_BYTES_CAP"] = original_synopsis_cap
            checks.check(
                "synopsis-byte-cap-injected-n-minus-one-n-n-plus-one",
                len(
                    canonical_bytes(injected_results["n_plus_one"])
                )
                == exact_bytes
                and len(canonical_bytes(injected_results["n"]))
                == exact_bytes
                and isinstance(
                    injected_results.get("n_minus_one"),
                    EvidenceFailed,
                )
                and "UTF-8 byte cap"
                in str(injected_results["n_minus_one"]),
                expected={
                    "n_minus_one": "EvidenceFailed",
                    "n": exact_bytes,
                    "n_plus_one": exact_bytes,
                },
                observed={
                    "n_minus_one": type(
                        injected_results.get("n_minus_one")
                    ).__name__,
                    "n": len(canonical_bytes(injected_results["n"])),
                    "n_plus_one": len(
                        canonical_bytes(
                            injected_results["n_plus_one"]
                        )
                    ),
                },
            )
            checks.check(
                "large-synopsis-retains-complete-artifact-no-claim",
                synopsis["selected_ids"]["total"]
                == V2_SYNOPSIS_ID_PREVIEW_CAP + 1
                and synopsis["selected_ids"]["shown"]
                == V2_SYNOPSIS_ID_PREVIEW_CAP
                and "machine artifacts are complete"
                in str(synopsis["selected_ids"]["notice"])
                and "complete machine artifacts remain untruncated"
                in synopsis["no_claim"],
                expected={
                    "total": V2_SYNOPSIS_ID_PREVIEW_CAP + 1,
                    "shown": V2_SYNOPSIS_ID_PREVIEW_CAP,
                    "artifacts": "untruncated",
                },
                observed={
                    "selected_ids": synopsis["selected_ids"],
                    "no_claim": synopsis["no_claim"],
                },
            )
    elif slug == "ux-streams-color-tty":
        help_result = run_command(
            [str(REPO_ROOT / SCRIPT_REL), "--help"],
            environment_overrides={
                "NO_COLOR": "1",
                "TERM": "dumb",
            },
            record_global_receipt=False,
        )
        invalid_result = run_command(
            [
                str(REPO_ROOT / SCRIPT_REL),
                "--self-test-v2",
                "--unknown-v2-mode",
            ],
            expected=(TERMINAL_EXIT["UsageRefused"],),
            environment_overrides={
                "NO_COLOR": "1",
                "TERM": "dumb",
            },
            record_global_receipt=False,
        )
        invalid_document = strict_json_loads(
            invalid_result.stdout,
            label="v2 invalid CLI terminal",
            require_canonical=True,
        )
        v2_validate_preflight_terminal_document(invalid_document)
        checks.check(
            "actual-help-stdout-stderr-no-color",
            help_result.returncode == 0
            and "--review-plan" in help_result.stdout
            and help_result.stderr == ""
            and "\x1b[" not in help_result.stdout
            and "\x1b[" not in help_result.stderr,
            expected={
                "exit": 0,
                "stdout": "help",
                "stderr": "",
                "ansi": False,
            },
            observed={
                "exit": help_result.returncode,
                "stdout_root": text_root(help_result.stdout),
                "stderr_root": text_root(help_result.stderr),
                "ansi": "\x1b["
                in (help_result.stdout + help_result.stderr),
            },
        )
        checks.check(
            "actual-invalid-cli-typed-exit-and-streams",
            invalid_result.returncode == TERMINAL_EXIT["UsageRefused"]
            and invalid_result.stderr == ""
            and invalid_document["schema"] == V2_PREFLIGHT_TERMINAL_SCHEMA
            and set(invalid_document) == V2_PREFLIGHT_TERMINAL_FIELDS
            and invalid_document["terminal"] == "UsageRefused"
            and invalid_document["exit_code"]
            == TERMINAL_EXIT["UsageRefused"]
            and "\x1b[" not in invalid_result.stdout
            and "\x1b[" not in invalid_result.stderr,
            expected={
                "exit": TERMINAL_EXIT["UsageRefused"],
                "schema": V2_PREFLIGHT_TERMINAL_SCHEMA,
                "terminal": "UsageRefused",
                "stderr": "",
                "ansi": False,
            },
            observed={
                "exit": invalid_result.returncode,
                "schema": invalid_document.get("schema"),
                "terminal": invalid_document.get("terminal"),
                "typed_exit": invalid_document.get("exit_code"),
                "stderr_root": text_root(invalid_result.stderr),
                "ansi": "\x1b["
                in (invalid_result.stdout + invalid_result.stderr),
            },
        )
        accepted_failure_result = run_command(
            [
                str(REPO_ROOT / SCRIPT_REL),
                "--case-v2",
                "template-lint-v2.unknown-accepted-case",
            ],
            expected=(TERMINAL_EXIT["UsageRefused"],),
            environment_overrides={
                "NO_COLOR": "1",
                "TERM": "dumb",
            },
            record_global_receipt=False,
        )
        accepted_failure_document = strict_json_loads(
            accepted_failure_result.stdout,
            label="v2 accepted-execution terminal",
            require_canonical=True,
        )
        v2_validate_execution_terminal_document(
            accepted_failure_document
        )
        checks.check(
            "actual-accepted-v2-failure-uses-execution-terminal",
            accepted_failure_result.returncode
            == TERMINAL_EXIT["UsageRefused"]
            and accepted_failure_result.stderr == ""
            and accepted_failure_document["schema"]
            == V2_EXECUTION_TERMINAL_SCHEMA
            and accepted_failure_document["terminal"]
            == "UsageRefused"
            and accepted_failure_document["mode"] == "case-v2"
            and accepted_failure_document["phase"] == "TEST_RUNNER"
            and accepted_failure_document["artifact_state"]
            == "NOT_APPLICABLE"
            and accepted_failure_document["manifest_root"]
            == manifest["semantic_root"],
            expected={
                "exit": TERMINAL_EXIT["UsageRefused"],
                "schema": V2_EXECUTION_TERMINAL_SCHEMA,
                "terminal": "UsageRefused",
                "mode": "case-v2",
                "phase": "TEST_RUNNER",
                "artifact_state": "NOT_APPLICABLE",
                "manifest_root": manifest["semantic_root"],
                "stderr": "",
            },
            observed={
                "exit": accepted_failure_result.returncode,
                "document": accepted_failure_document,
                "stderr_root": text_root(
                    accepted_failure_result.stderr
                ),
            },
        )
        repeated_invalid = run_command(
            [
                str(REPO_ROOT / SCRIPT_REL),
                "--self-test-v2",
                "--unknown-v2-mode",
            ],
            expected=(TERMINAL_EXIT["UsageRefused"],),
            environment_overrides={"TERM": "dumb"},
            record_global_receipt=False,
        )
        checks.check(
            "pipe-execution-no-tty-dependency-and-no-color-determinism",
            invalid_result.stdout == repeated_invalid.stdout
            and invalid_result.stderr == repeated_invalid.stderr
            and invalid_result.returncode == repeated_invalid.returncode,
            expected={
                "stdout_root": text_root(invalid_result.stdout),
                "stderr_root": text_root(invalid_result.stderr),
                "exit": invalid_result.returncode,
            },
            observed={
                "stdout_root": text_root(repeated_invalid.stdout),
                "stderr_root": text_root(repeated_invalid.stderr),
                "exit": repeated_invalid.returncode,
            },
        )
        forbidden_manifest_result = run_command(
            [str(REPO_ROOT / SCRIPT_REL), "--self-test-v2"],
            expected=(TERMINAL_EXIT["EvidenceFailed"],),
            environment_overrides={
                "FS_TEMPLATE_HYGIENE_FORBID_V2_LOAD": "1",
                "NO_COLOR": "1",
                "TERM": "dumb",
            },
            record_global_receipt=False,
        )
        forbidden_manifest_document = strict_json_loads(
            forbidden_manifest_result.stdout,
            label="v2 forbidden-manifest preflight terminal",
            require_canonical=True,
        )
        v2_validate_preflight_terminal_document(
            forbidden_manifest_document
        )
        checks.check(
            "actual-v2-manifest-preflight-closed",
            forbidden_manifest_result.returncode
            == TERMINAL_EXIT["EvidenceFailed"]
            and forbidden_manifest_result.stderr == ""
            and forbidden_manifest_document["schema"]
            == V2_PREFLIGHT_TERMINAL_SCHEMA
            and set(forbidden_manifest_document)
            == V2_PREFLIGHT_TERMINAL_FIELDS
            and forbidden_manifest_document["terminal"]
            == "EvidenceFailed"
            and forbidden_manifest_document["mode"] == "self-test-v2"
            and forbidden_manifest_document["recovery"]
            == "FIX_HARNESS_OR_CONTRACT_AND_RETRY",
            expected={
                "exit": TERMINAL_EXIT["EvidenceFailed"],
                "schema": V2_PREFLIGHT_TERMINAL_SCHEMA,
                "terminal": "EvidenceFailed",
                "mode": "self-test-v2",
                "recovery": "FIX_HARNESS_OR_CONTRACT_AND_RETRY",
            },
            observed={
                "exit": forbidden_manifest_result.returncode,
                "document": forbidden_manifest_document,
                "stderr_root": text_root(forbidden_manifest_result.stderr),
            },
        )
    elif slug == "compat-v1-immutable":
        v1 = load_case_manifest()
        compatibility = manifest["compatibility_contract"]
        payload = bounded_read(REPO_ROOT / CASE_MANIFEST_REL)
        retained_manifest_blob = run_command(
            [
                "git",
                "rev-parse",
                (
                    compatibility["v1_manifest_adopted_git_commit"]
                    + ":"
                    + compatibility["v1_manifest_path"]
                ),
            ],
            record_global_receipt=False,
        ).stdout.strip()
        checks.check(
            "v1-content-root",
            "sha256-v1:" + hashlib.sha256(payload).hexdigest()
            == compatibility["v1_manifest_content_root"],
            expected=compatibility["v1_manifest_content_root"],
            observed="sha256-v1:" + hashlib.sha256(payload).hexdigest(),
        )
        checks.check(
            "v1-semantic-root",
            v1["semantic_root"]
            == compatibility["v1_case_manifest_semantic_root"],
            expected=compatibility["v1_case_manifest_semantic_root"],
            observed=v1["semantic_root"],
        )
        checks.check(
            "v1-registry-counts",
            len(v1["case"]) == 21
            and compatibility["v1_assertion_count"] == 148,
            expected={"cases": 21, "assertions": 148},
            observed={
                "cases": len(v1["case"]),
                "assertions": compatibility["v1_assertion_count"],
            },
        )
        checks.check(
            "v1-manifest-baseline-portably-retained",
            retained_manifest_blob
            == compatibility["v1_manifest_adopted_git_blob"]
            and compatibility["v1_manifest_blob_retention"]
            == "REACHABLE_COMMIT_PATH_IDENTITY",
            expected={
                "blob": compatibility["v1_manifest_adopted_git_blob"],
                "retention": "REACHABLE_COMMIT_PATH_IDENTITY",
            },
            observed={
                "blob": retained_manifest_blob,
                "retention": compatibility[
                    "v1_manifest_blob_retention"
                ],
            },
        )
        checks.check(
            "nonportable-adoption-evidence-is-explicit-nodata",
            compatibility["v1_harness_blob_retention"]
            == "UNREACHABLE_LOCAL_OBJECT_NODATA"
            and compatibility["adoption_artifact_retention"]
            == "IGNORED_LOCAL_ONLY_NODATA"
            and compatibility["portable_adoption_evidence"] is False
            and compatibility["compatibility_proof_authority"]
            == "CURRENT_V1_MANIFEST_AND_RUNTIME_REGRESSION_ONLY",
            expected={
                "harness": "UNREACHABLE_LOCAL_OBJECT_NODATA",
                "artifact": "IGNORED_LOCAL_ONLY_NODATA",
                "portable": False,
                "authority": (
                    "CURRENT_V1_MANIFEST_AND_RUNTIME_REGRESSION_ONLY"
                ),
            },
            observed={
                "harness": compatibility[
                    "v1_harness_blob_retention"
                ],
                "artifact": compatibility[
                    "adoption_artifact_retention"
                ],
                "portable": compatibility[
                    "portable_adoption_evidence"
                ],
                "authority": compatibility[
                    "compatibility_proof_authority"
                ],
            },
        )
    else:
        raise EvidenceFailed(f"no schema/CLI/UX executor for {slug}")
    return checks.finish(parameters)


def v2_execute_source_cases(
    case: Mapping[str, Any],
    manifest: Mapping[str, Any],
) -> dict[str, Any]:
    slug = str(case["id"]).removeprefix("template-lint-v2.")
    checks = V2CheckCollector(case["id"], case["assertion_id"])
    parameters = {"family": "source", "slug": slug}

    def capture_state(
        rows: Sequence[Mapping[str, Any]],
        *,
        released_rows: Sequence[Mapping[str, Any]] = (),
        lint: Mapping[str, Any] | None = None,
        tracker_status: Mapping[str, Any] | None = None,
        tracker_ready_issue_ids: Sequence[str] = (),
        capabilities: Mapping[str, Any] | None = None,
        source_files: Sequence[Mapping[str, Any]] | None = None,
        rule_contract: Mapping[str, Any] | None = None,
    ) -> dict[str, Any]:
        ordered = sorted((dict(row) for row in rows), key=lambda row: row["id"])
        ordered_released = sorted(
            (v2_released_fixture_issue(row) for row in released_rows),
            key=lambda row: row["id"],
        )
        if [row["id"] for row in ordered_released] != [
            row["id"] for row in ordered
        ]:
            raise EvidenceFailed(
                "synthetic capture released rows differ from projections"
            )
        listed_rows = [
            v2_retain_released_br_row(
                {
                    **row,
                    "dependency_count": len(row.get("dependencies") or []),
                    "dependent_count": len(row.get("dependents") or []),
                }
            )
            for row in ordered_released
            if row.get("status") != "tombstone"
        ]
        tombstone_rows = [
            v2_retain_released_br_row(
                {
                    **row,
                    "dependency_count": len(row.get("dependencies") or []),
                    "dependent_count": len(row.get("dependents") or []),
                }
            )
            for row in ordered_released
            if row.get("status") == "tombstone"
        ]
        ready_id_set = set(tracker_ready_issue_ids)
        ready_rows = [
            v2_retain_released_br_row(dict(row))
            for row in ordered_released
            if row["id"] in ready_id_set
        ]
        normalized_lint = (
            dict(lint)
            if lint is not None
            else fixture_lint(
                ordered,
                {
                    str(row["id"]): tuple(row.get("missing_sections") or ())
                    for row in ordered
                },
                status_scopes=v2_canonical_status_scopes(
                    [
                        *V2_RELEASED_KNOWN_STATUSES,
                        *(row["status"] for row in ordered),
                    ]
                ),
            )
        )
        return v2_capture_state(
            issue_ids=[str(row["id"]) for row in ordered],
            full_issues=ordered,
            lint=normalized_lint,
            tracker_status=dict(tracker_status or {"state": "clean"}),
            tracker_ready_issue_ids=list(tracker_ready_issue_ids),
            sync_status={"state": "synchronized"},
            export_witness={"state": "current"},
            version={"version": "0.2.19"},
            capabilities=dict(
                capabilities or {"contract_version": "br.capabilities.v1"}
            ),
            source_files=list(
                source_files
                or [
                    {
                        "path": "synthetic-source",
                        "bytes": 1,
                        "content_identity": text_root("x"),
                    }
                ]
            ),
            rule_contract=dict(
                rule_contract
                or {
                    "classifier": (
                        "synthetic-independent-template-findings"
                    )
                }
            ),
            case_manifest_root=manifest["semantic_root"],
            case_manifest_content_identity=manifest[
                "content_identity"
            ],
            listed_rows=listed_rows,
            tombstone_rows=tombstone_rows,
            tracker_ready_rows=ready_rows,
        )

    def authentic_capture(
        raw_rows: Sequence[Mapping[str, Any]],
        *,
        missing_by_id: Mapping[str, Sequence[str]] | None = None,
        tracker_status: Mapping[str, Any] | None = None,
        capabilities: Mapping[str, Any] | None = None,
        source_files: Sequence[Mapping[str, Any]] | None = None,
        rule_contract: Mapping[str, Any] | None = None,
    ) -> tuple[dict[str, Any], dict[str, Any], LiveSnapshot, dict[str, Any]]:
        released_rows = [v2_released_fixture_issue(row) for row in raw_rows]
        full_issues, lint, snapshot, inventory = (
            v2_authentic_projection_fixture(
                released_rows,
                missing_by_id=missing_by_id,
            )
        )
        return (
            capture_state(
                full_issues,
                released_rows=released_rows,
                lint=lint,
                tracker_status=tracker_status,
                capabilities=capabilities,
                source_files=source_files,
                rule_contract=rule_contract,
            ),
            lint,
            snapshot,
            inventory,
        )

    if slug == "source-zero-one":
        empty_capture = capture_state([])
        checks.check(
            "empty-source-capture-is-first-class",
            v2_list_issue_ids(
                {
                    "issues": [],
                    "has_more": False,
                    "limit": 0,
                    "offset": 0,
                    "total": 0,
                },
                label="empty issue list",
            )
            == []
            and empty_capture["issue_ids"] == []
            and empty_capture["issue_count"] == 0
            and empty_capture["full_issue_projection_root"]
            == semantic_root([]),
            expected={
                "issue_ids": [],
                "issue_count": 0,
                "full_issue_projection_root": semantic_root([]),
            },
            observed={
                "issue_ids": empty_capture["issue_ids"],
                "issue_count": empty_capture["issue_count"],
                "full_issue_projection_root": empty_capture[
                    "full_issue_projection_root"
                ],
            },
        )
        released_container_hooks = {"dict": 0, "list": 0, "str": 0}

        class HostileReleasedDictionary(dict):
            def __contains__(self, _key: object) -> bool:
                released_container_hooks["dict"] += 1
                raise RuntimeError("hostile released dictionary contains")

            def __getitem__(self, _key: object) -> Any:
                released_container_hooks["dict"] += 1
                raise RuntimeError("hostile released dictionary getitem")

            def __iter__(self) -> Iterator[Any]:
                released_container_hooks["dict"] += 1
                raise RuntimeError("hostile released dictionary iterator")

            def __len__(self) -> int:
                released_container_hooks["dict"] += 1
                raise RuntimeError("hostile released dictionary length")

            def get(self, _key: object, _default: Any = None) -> Any:
                released_container_hooks["dict"] += 1
                raise RuntimeError("hostile released dictionary get")

            def items(self) -> Any:
                released_container_hooks["dict"] += 1
                raise RuntimeError("hostile released dictionary items")

            def keys(self) -> Any:
                released_container_hooks["dict"] += 1
                raise RuntimeError("hostile released dictionary keys")

        class HostileReleasedList(list[Any]):
            def __getitem__(self, _key: object) -> Any:
                released_container_hooks["list"] += 1
                raise RuntimeError("hostile released list getitem")

            def __iter__(self) -> Iterator[Any]:
                released_container_hooks["list"] += 1
                raise RuntimeError("hostile released list iterator")

            def __len__(self) -> int:
                released_container_hooks["list"] += 1
                raise RuntimeError("hostile released list length")

        class HostileReleasedString(str):
            def __eq__(self, _other: object) -> bool:
                released_container_hooks["str"] += 1
                raise RuntimeError("hostile released string equality")

            def __hash__(self) -> int:
                released_container_hooks["str"] += 1
                raise RuntimeError("hostile released string hash")

            def __str__(self) -> str:
                released_container_hooks["str"] += 1
                raise RuntimeError("hostile released string conversion")

            def encode(self, *_args: Any, **_kwargs: Any) -> bytes:
                released_container_hooks["str"] += 1
                raise RuntimeError("hostile released string encoding")

        hostile_list_envelope = HostileReleasedDictionary()
        for key, value in dict.items({
            "issues": [],
            "has_more": False,
            "limit": 0,
            "offset": 0,
            "total": 0,
        }):
            dict.__setitem__(hostile_list_envelope, key, value)
        hostile_list_rows = HostileReleasedList()
        hostile_list_row = HostileReleasedDictionary()
        dict.__setitem__(hostile_list_row, "id", "fixture-hostile-row-aa")
        list.append(hostile_list_rows, {"id": "fixture-hostile-list-aa"})
        hostile_base_row = v2_released_fixture_issue(fixture_issue(
            issue_id="fixture-hostile-scalar-aa",
            status="open",
        ))
        hostile_scalar_list_row = dict(hostile_base_row)
        hostile_scalar_list_row["id"] = HostileReleasedString(
            "fixture-hostile-scalar-aa"
        )
        hostile_scalar_list_row["dependency_count"] = 0
        hostile_scalar_list_row["dependent_count"] = 0
        hostile_nested_list = HostileReleasedList()
        list.append(hostile_nested_list, "fixture-label")
        hostile_nested_list_row = dict(hostile_base_row)
        hostile_nested_list_row["labels"] = hostile_nested_list
        hostile_nested_dictionary = HostileReleasedDictionary()
        dict.__setitem__(hostile_nested_dictionary, "id", 1)
        hostile_nested_dictionary_row = dict(hostile_base_row)
        hostile_nested_dictionary_row["comments"] = [
            hostile_nested_dictionary
        ]
        released_container_errors = [
            expect_error(
                InfrastructureFailed,
                lambda: v2_normalize_released_br_list_rows(
                    hostile_list_envelope,
                    label="hostile released list envelope",
                ),
                contains="not exact released JSON data",
            ),
            expect_error(
                InfrastructureFailed,
                lambda: v2_normalize_released_br_list_rows(
                    {
                        "issues": hostile_list_rows,
                        "has_more": False,
                        "limit": 0,
                        "offset": 0,
                        "total": 1,
                    },
                    label="hostile released list rows",
                ),
                contains="not exact released JSON data",
            ),
            expect_error(
                InfrastructureFailed,
                lambda: v2_normalize_released_br_list_rows(
                    {
                        "issues": [hostile_list_row],
                        "has_more": False,
                        "limit": 0,
                        "offset": 0,
                        "total": 1,
                    },
                    label="hostile released list row",
                ),
                contains="not exact released JSON data",
            ),
            expect_error(
                InfrastructureFailed,
                lambda: v2_normalize_released_br_ready_rows(
                    hostile_list_rows,
                    label="hostile released ready envelope",
                ),
                contains="not exact released JSON data",
            ),
            expect_error(
                InfrastructureFailed,
                lambda: v2_normalize_released_br_ready_rows(
                    [hostile_list_row],
                    label="hostile released ready row",
                ),
                contains="not exact released JSON data",
            ),
            expect_error(
                InfrastructureFailed,
                lambda: v2_normalize_released_br_list_rows(
                    {
                        "issues": [hostile_scalar_list_row],
                        "has_more": False,
                        "limit": 0,
                        "offset": 0,
                        "total": 1,
                    },
                    label="hostile released scalar row",
                ),
                contains="not exact released JSON data",
