        def reroot_synthetic_inventory_target(
            source_inventory: Mapping[str, Any],
            *,
            target_index: int,
            mutation: Callable[[dict[str, Any]], None],
            rebind_target_root: bool = False,
        ) -> dict[str, Any]:
            candidate = strict_json_loads(
                canonical_bytes(source_inventory),
                label="synthetic identity mutation seed",
                require_canonical=True,
            )
            candidate.pop("semantic_root", None)
            target = candidate["rows"][target_index]
            target.pop("semantic_root", None)
            mutation(target)
            if rebind_target_root:
                target["target_root"] = v2_normalized_target_root(target)
            candidate["rows"][target_index] = v2_rooted(target)
            return v2_rooted(candidate)

