        def production_kind_inventory(
            source_inventory: Mapping[str, Any],
        ) -> dict[str, Any]:
            candidate = strict_json_loads(
                canonical_bytes(source_inventory),
                label="production-kind inventory seed",
                require_canonical=True,
            )
            candidate.pop("semantic_root", None)
            candidate["no_claim"] = (
                "v2 inventory is a tracker-read-only projection of template "
                "debt; it grants no review, mutation, completion, or product "
                "authority"
            )
            candidate["v1_inventory_root"] = semantic_root(
                {"production_fixture": True}
            )
            production_rows: list[dict[str, Any]] = []
            for target in candidate["rows"]:
                target.pop("semantic_root", None)
                target["no_claim"] = (
                    "this normalized target schedules review only; it does "
                    "not approve semantics, mutate the target, or prove "
                    "implementation"
                )
                target["user_effect"] = (
                    "make the target planning contract specific, testable, "
                    "replayable, and honest without changing target behavior"
                )
                review_minutes = v2_review_minutes(
                    v2_synthetic_source_issue(target)
                )
                target["review_minutes"] = review_minutes
                target["generated_child_estimated_minutes"] = review_minutes
                target["target_root"] = v2_normalized_target_root(target)
                production_rows.append(v2_rooted(target))
            candidate["rows"] = production_rows
            return v2_rooted(candidate)

