            selected_capture_state: dict[str, Any] | None = None,
            selected_source_files: list[dict[str, Any]] = source_files,
            selected_lint: dict[str, Any] = first_snapshot.lint,
            selected_full_issues: tuple[dict[str, Any], ...] | None = None,
            selected_command_receipts: tuple[dict[str, Any], ...] = (),
        ) -> V2LiveCaptureRound:
            return V2LiveCaptureRound(
                ordinal=ordinal,
                issue_ids=tuple(row["id"] for row in full_issues),
                listed_rows=tuple(listed_rows),
