            )
            source_fields.update(overrides)
            return V2LiveCaptureRound(**source_fields)

        round_one = build_live_round(1, selected_capture_state=first)
        round_two = build_live_round(2, selected_capture_state=second)
        round_one_fields = v2_exact_live_capture_round(
            round_one,
