            == first_inventory["campaign_epoch_root"]
            and historical_receipts["campaign_epoch_root"]
            != second_inventory["campaign_epoch_root"],
            expected="first-campaign provenance admitted by second campaign",
            observed={
                "receipt_inventory": historical_receipts["inventory_root"],
                "second_inventory": second_inventory["semantic_root"],
                "receipt_campaign": historical_receipts[
                    "campaign_epoch_root"
                ],
                "second_campaign": second_inventory[
                    "campaign_epoch_root"
                ],
            },
        )
        first_external_authority = v2_derive_authority(
            first_inventory,
            historical_receipts,
            current_br_version="0.3.0",
            allow_mechanical_fixture=True,
        )
        second_external_authority = v2_derive_authority(
            second_inventory,
            historical_receipts,
            current_br_version="0.3.0",
            allow_mechanical_fixture=True,
        )
        first_external_decision = next(
            row
            for row in first_external_authority["decisions"]
            if row["target_id"] == "fixture-selected"
        )
        second_external_decision = next(
            row
            for row in second_external_authority["decisions"]
            if row["target_id"] == "fixture-selected"
        )
        expected_selected_external_root = v2_fixture_gate_receipt_root(
            "external",
            target_root=second_selected_target["target_root"],
        )
        checks.check(
            "external-receipt-admitted-after-unrelated-campaign-drift",
            historical_receipts["inventory_root"]
            != second_inventory["semantic_root"]
            and historical_receipts["campaign_epoch_root"]
            != second_inventory["campaign_epoch_root"]
            and reviewed_receipt["external_authority_receipt_root"]
            == expected_selected_external_root
            and first_external_decision["external_authority"]["verified"]
            is True
            and second_external_decision["external_authority"]["verified"]
            is True
            and first_external_decision["external_authority"][
                "receipt_root"
            ]
            == expected_selected_external_root
            == second_external_decision["external_authority"][
                "receipt_root"
            ]
            and first_external_decision["semantic_root"]
            == second_external_decision["semantic_root"],
            expected={
                "verified": True,
                "receipt_root": expected_selected_external_root,
                "selected_decision_stable": True,
                "authority_claim": "synthetic fixture only",
            },
            observed={
                "first_verified": first_external_decision[
                    "external_authority"
                ]["verified"],
                "second_verified": second_external_decision[
                    "external_authority"
                ]["verified"],
                "first_receipt_root": first_external_decision[
                    "external_authority"
                ]["receipt_root"],
                "second_receipt_root": second_external_decision[
                    "external_authority"
                ]["receipt_root"],
                "selected_decision_stable": (
                    first_external_decision["semantic_root"]
                    == second_external_decision["semantic_root"]
                ),
            },
        )
        checks.check(
            "reviewed-receipt-scope-root-stable-after-unrelated-drift",
            first_reviewed_decision["semantic_review_receipt_root"]
            == reviewed_scope_root
            == second_reviewed_decision["semantic_review_receipt_root"]
            and first_reviewed_decision["reviewer_provenance"][
                "receipt_root"
            ]
            == reviewed_scope_root
            == second_reviewed_decision["reviewer_provenance"][
                "receipt_root"
            ],
            expected=reviewed_scope_root,
            observed={
                "first_semantic": first_reviewed_decision[
                    "semantic_review_receipt_root"
                ],
                "second_semantic": second_reviewed_decision[
                    "semantic_review_receipt_root"
                ],
                "first_reviewer": first_reviewed_decision[
                    "reviewer_provenance"
                ]["receipt_root"],
                "second_reviewer": second_reviewed_decision[
                    "reviewer_provenance"
                ]["receipt_root"],
            },
        )
        checks.check(
            "reviewed-selected-decision-root-stable-after-unrelated-drift",
            first_reviewed_decision["semantic_root"]
            == second_reviewed_decision["semantic_root"],
            expected=first_reviewed_decision["semantic_root"],
            observed=second_reviewed_decision["semantic_root"],
        )
        first_reviewed_key = child_key_for(
            first_reviewed_plan,
            "fixture-selected",
        )
        second_reviewed_key = child_key_for(
            second_reviewed_plan,
            "fixture-selected",
        )
        checks.check(
            "reviewed-selected-child-key-stable-after-unrelated-drift",
            first_reviewed_key == second_reviewed_key,
            expected=first_reviewed_key,
            observed=second_reviewed_key,
        )

        selected_mutations: list[
            tuple[
                str,
                list[dict[str, Any]],
                Mapping[str, Sequence[str]] | None,
            ]
        ] = []
        for name, field, value in (
            ("field", "description", "Changed selected source clause."),
            ("owner", "owner", "changed-selected-owner"),
            ("priority-lane", "priority", 2),
            ("status-lane", "status", "blocked"),
            (
                "dependency-neighbor",
                "dependencies",
                [
                    {
                        "id": "external:fixture:changed-neighbor",
                        "title": "Changed selected dependency neighbor",
                        "dependency_type": "blocks",
                        "status": "blocked",
                        "priority": 3,
                    }
                ],
            ),
        ):
            changed_selected = json.loads(json.dumps(selected_raw))
            changed_selected[field] = value
            selected_mutations.append(
                (name, [changed_selected, dict(unrelated_a)], None)
            )
        selected_mutations.append(
            (
                "lint-membership",
                [dict(selected_raw), dict(unrelated_a)],
                {
                    "fixture-selected": ("## Steps to Reproduce",),
                    "fixture-unrelated": ("## Acceptance Criteria",),
                },
            )
        )
        for name, raw_rows, missing in selected_mutations:
            _, changed_inventory, _, changed_plan = planned_fixture(
                raw_rows,
                missing_by_id=missing,
            )
            changed_key = child_key_for(changed_plan, "fixture-selected")
            checks.check(
                f"selected-{name}-invalidates-affected-key",
                changed_key != first_selected_key
                and next(
                    row
                    for row in changed_inventory["rows"]
                    if row["id"] == "fixture-selected"
                )["target_root"]
                != next(
                    row
                    for row in first_inventory["rows"]
                    if row["id"] == "fixture-selected"
                )["target_root"],
                expected="different selected key",
                observed={
                    "before": first_selected_key,
                    "after": changed_key,
                },
            )
            checks.refuses(
                f"reviewed-receipt-selected-{name}-drift-refused",
                InputRefused,
                lambda changed_inventory=changed_inventory: (
                    v2_validate_receipt_bindings(
                        historical_receipts,
                        changed_inventory,
                    )
                ),
                contains="target root drifted",
            )

        _, _, _, receipt_inventory = authentic_capture([selected_raw])
        inventory = receipt_inventory
        base_receipts = v2_synthetic_receipts(
            inventory,
            declared=True,
        )
        base_authority = v2_derive_authority(
            inventory,
            base_receipts,
            current_br_version="0.2.19",
        )
        base_plan, _ = v2_build_review_plan(
            inventory,
            base_authority,
            max_targets=1,
            review_receipts=base_receipts,
        )
        base_child_key = base_plan["children"][0]["child_key"]
        base_receipt_scope_root = v2_review_receipt_scope_root(
            base_receipts["receipts"][0]
        )
        for name, field, value in (
            ("owner", "implementation_owner", "changed-owner"),
            ("evidence-owner", "evidence_owner", "changed-evidence-owner"),
            ("consumer", "terminal_consumer", "changed-consumer"),
        ):
            changed_receipts = json.loads(json.dumps(base_receipts))
            changed_receipt = changed_receipts["receipts"][0]
            changed_receipt[field] = value
            changed_receipt.pop("semantic_root", None)
            changed_receipts["receipts"][0] = v2_rooted(changed_receipt)
            changed_receipts.pop("semantic_root", None)
            changed_receipts = v2_rooted(changed_receipts)
            changed_authority = v2_derive_authority(
                inventory,
                changed_receipts,
                current_br_version="0.2.19",
            )
            changed_plan, _ = v2_build_review_plan(
                inventory,
                changed_authority,
                max_targets=1,
                review_receipts=changed_receipts,
            )
            changed_child_key = changed_plan["children"][0]["child_key"]
            changed_receipt_scope_root = v2_review_receipt_scope_root(
                changed_receipts["receipts"][0]
            )
            checks.check(
                f"selected-{name}-receipt-invalidates-child-key",
                changed_child_key != base_child_key
                and changed_receipt_scope_root != base_receipt_scope_root,
                expected="different receipt scope root and child key",
                observed={
                    "key_before": base_child_key,
                    "key_after": changed_child_key,
                    "scope_before": base_receipt_scope_root,
                    "scope_after": changed_receipt_scope_root,
                },
            )
    else:
        raise EvidenceFailed(f"no source executor for {slug}")
    return checks.finish(parameters)


def v2_execute_authority_cases(
    case: Mapping[str, Any],
    manifest: Mapping[str, Any],
) -> dict[str, Any]:
    slug = str(case["id"]).removeprefix("template-lint-v2.")
    checks = V2CheckCollector(case["id"], case["assertion_id"])
    parameters = {"family": "row-authority", "slug": slug}
    base_inventory = v2_synthetic_inventory([v2_synthetic_target(0)])
    if slug == "row-complete-planned-child":
        authority = v2_synthetic_authority(base_inventory)
        plan, _ = v2_build_review_plan(
            base_inventory,
            authority,
            max_targets=10,
        )
        child = plan["children"][0]
        readiness_hook_calls = {"lower": 0, "str": 0}

        class HostileReadiness(str):
            def lower(self) -> str:
                readiness_hook_calls["lower"] += 1
                return "declared_ready"

            def __str__(self) -> str:
                readiness_hook_calls["str"] += 1
                return "DECLARED_READY"

        hostile_readiness_decision = dict(authority["decisions"][0])
        hostile_readiness_decision["readiness"] = HostileReadiness(
            hostile_readiness_decision["readiness"]
        )
        hostile_readiness_error = expect_error(
            EvidenceFailed,
            lambda: v2_make_child(
                [
                    (
                        base_inventory["rows"][0],
                        hostile_readiness_decision,
                    )
                ],
                packing_witness={
                    "semantic_root": V2_PACKING_PREFLIGHT_WITNESS_ROOT,
                },
            ),
            contains="not exact released JSON data",
        )
        hostile_projection_hooks = {
            "mapping_get": 0,
            "mapping_getitem": 0,
            "mapping_items": 0,
            "mapping_iter": 0,
            "sequence_iter": 0,
            "sequence_getitem": 0,
            "sequence_len": 0,
        }

        class HostileProjectionMapping(dict):
            def get(self, key: Any, default: Any = None) -> Any:
                hostile_projection_hooks["mapping_get"] += 1
                return super().get(key, default)

            def __getitem__(self, key: Any) -> Any:
                hostile_projection_hooks["mapping_getitem"] += 1
                return super().__getitem__(key)

            def items(self) -> Any:
                hostile_projection_hooks["mapping_items"] += 1
                return super().items()

            def __iter__(self) -> Any:
                hostile_projection_hooks["mapping_iter"] += 1
                return super().__iter__()

        class HostileProjectionSequence(list):
            def __iter__(self) -> Any:
                hostile_projection_hooks["sequence_iter"] += 1
                return super().__iter__()

            def __getitem__(self, key: Any) -> Any:
                hostile_projection_hooks["sequence_getitem"] += 1
                return super().__getitem__(key)

            def __len__(self) -> int:
                hostile_projection_hooks["sequence_len"] += 1
                return super().__len__()

        exact_target = base_inventory["rows"][0]
        exact_decision = authority["decisions"][0]
        nested_context_target = dict(exact_target)
        nested_context_target["active_work_context"] = (
            HostileProjectionMapping(exact_target["active_work_context"])
        )
        nested_labels_target = dict(exact_target)
        nested_labels_target["labels"] = HostileProjectionSequence(
            exact_target["labels"]
        )
        nested_authority_decision = dict(exact_decision)
        nested_authority_decision["external_authority"] = (
            HostileProjectionMapping(exact_decision["external_authority"])
        )
        hostile_projection_callbacks: tuple[
            tuple[str, Callable[[], Any]], ...
        ] = (
            (
                "target_outer_source_projection",
                lambda: v2_normalized_target_source_issue(
                    HostileProjectionMapping(exact_target)
                ),
            ),
            (
                "target_nested_context",
                lambda: v2_normalized_target_source_issue(
                    nested_context_target
                ),
            ),
            (
                "target_nested_labels_root",
                lambda: v2_normalized_target_root(nested_labels_target),
            ),
            (
                "authority_target_outer",
                lambda: v2_normalized_authority_row(
                    HostileProjectionMapping(exact_target),
                    exact_decision,
                ),
            ),
            (
                "authority_decision_outer",
                lambda: v2_normalized_authority_row(
                    exact_target,
                    HostileProjectionMapping(exact_decision),
                ),
            ),
            (
                "authority_nested_gate",
                lambda: v2_normalized_authority_row(
                    exact_target,
                    nested_authority_decision,
                ),
            ),
        )
        hostile_projection_errors: dict[str, HarnessError] = {}
        for label, callback in hostile_projection_callbacks:
            hostile_projection_errors[label] = expect_error(
                EvidenceFailed,
                callback,
            )
        checks.check(
            "normalized-target-authority-hostile-containers-zero-hook-refusal",
            set(hostile_projection_errors)
            == {label for label, _ in hostile_projection_callbacks}
            and all(
                error.terminal == "EvidenceFailed"
                for error in hostile_projection_errors.values()
            )
            and all(value == 0 for value in hostile_projection_hooks.values()),
            expected={
                "refusals": {
                    label: "EvidenceFailed"
                    for label, _ in hostile_projection_callbacks
                },
                "hook_calls": {
                    key: 0 for key in hostile_projection_hooks
                },
            },
            observed={
                "refusals": {
                    label: {
                        "terminal": error.terminal,
                        "diagnostic": str(error),
                    }
                    for label, error in hostile_projection_errors.items()
                },
                "hook_calls": dict(hostile_projection_hooks),
            },
        )
        required = set(
            manifest["row_contract"]["planned_child_required_fields"]
        )
        checks.check(
            "planned-child-required-fields",
            set(child) == required == V2_PLANNED_CHILD_FIELDS,
            expected=sorted(required),
            observed=sorted(child),
        )
        normalized = authority["normalized_rows"][0]
        expected_row_fields = set(
            manifest["row_contract"]["required_fields"]
        )
        checks.check(
            "normalized-authority-row-schema-complete",
            set(normalized)
            == expected_row_fields
            == V2_NORMALIZED_ROW_FIELDS,
            expected=sorted(expected_row_fields),
            observed=sorted(normalized),
        )
        v2_validate_child_payload(child)
        checks.check(
            "planned-child-transport-valid",
            hostile_readiness_error.terminal == "EvidenceFailed"
            and readiness_hook_calls == {"lower": 0, "str": 0},
            expected={
                "transport": "valid",
                "hostile_readiness_terminal": "EvidenceFailed",
                "readiness_hook_calls": {"lower": 0, "str": 0},
            },
            observed={
                "transport_root": child["semantic_root"],
                "hostile_readiness_terminal": (
                    hostile_readiness_error.terminal
                ),
                "readiness_hook_calls": readiness_hook_calls,
            },
        )

        def reroot_planned_child(
            source_child: Mapping[str, Any],
            mutation: Callable[[dict[str, Any]], None],
        ) -> dict[str, Any]:
            candidate = strict_json_loads(
                canonical_bytes(source_child),
                label="planned child mutation seed",
                require_canonical=True,
            )
            candidate.pop("semantic_root", None)
            mutation(candidate)
            return v2_rooted(candidate)

        affirmative_no_claim = reroot_planned_child(
            child,
            lambda value: value.__setitem__(
                "no_claim",
                "this planned child grants tracker mutation and release authority",
            ),
        )
        checks.refuses(
            "planned-child-affirmative-no-claim-refused",
            EvidenceFailed,
            lambda: v2_validate_child_payload(
                affirmative_no_claim
            ),
            contains="scalar or enum contract",
        )
        unknown_workflow = reroot_planned_child(
            child,
            lambda value: value.__setitem__(
                "disposition_workflow",
                "GENERIC_REVIEW",
            ),
        )
        checks.refuses(
            "planned-child-unknown-workflow-refused",
            EvidenceFailed,
            lambda: v2_validate_child_payload(unknown_workflow),
            contains="scalar or enum contract",
        )

        def forge_lane_parent(
            value: dict[str, Any],
        ) -> None:
            value["lane_parent"] = "frankensim-unrelated-parent"
            value["intended_generated_edges"][0]["to"] = (
                value["lane_parent"]
            )

        wrong_lane_parent = reroot_planned_child(
            child,
            forge_lane_parent,
        )
        checks.refuses(
            "planned-child-wrong-lane-parent-refused",
            EvidenceFailed,
            lambda: v2_validate_child_payload(wrong_lane_parent),
            contains="scalar or enum contract",
        )
        for label, mutation in (
            (
                "identity-lane-parent",
                lambda value: value["external_ref_key_inputs"].__setitem__(
                    "lane_parent",
                    "frankensim-unrelated-parent",
                ),
            ),
            (
                "identity-generation-gate",
                lambda value: value["external_ref_key_inputs"].__setitem__(
                    "generation_gate_id",
                    "frankensim-unrelated-gate",
                ),
            ),
            (
                "identity-compatibility",
                lambda value: value["external_ref_key_inputs"][
                    "compatibility"
                ].__setitem__(
                    "rationale",
                    "forged standalone compatibility rationale",
                ),
            ),
        ):
            candidate = reroot_planned_child(child, mutation)
            checks.refuses(
                f"planned-child-{label}-refused",
                EvidenceFailed,
                lambda candidate=candidate: v2_validate_child_payload(
                    candidate
                ),
                contains="external identity inputs disagree",
            )

        def forge_uncovered_complete_compatibility(
            value: dict[str, Any],
        ) -> None:
            compatibility_root = semantic_root(
                {"forged": "uncovered compatibility"}
            )
            value["compatibility"] = {
                "key": "forged-compatibility",
                "target_ids": ["different-target"],
                "receipt_root": compatibility_root,
                "rationale": "forged rationale",
                "falsifier": "forged falsifier",
                "target_complete": True,
            }
            value["external_ref_key_inputs"]["compatibility"] = dict(
                value["compatibility"]
            )

        uncovered_compatibility = reroot_planned_child(
            child,
            forge_uncovered_complete_compatibility,
        )
        checks.refuses(
            "planned-child-uncovered-complete-compatibility-refused",
            EvidenceFailed,
            lambda: v2_validate_child_payload(
                uncovered_compatibility
            ),
            contains="does not cover its child",
        )
        false_with_compatibility_data = reroot_planned_child(
            child,
            lambda value: value["compatibility"].__setitem__(
                "key",
                "forged-key-with-false-state",
            ),
        )
        checks.refuses(
            "planned-child-false-compatibility-data-refused",
            EvidenceFailed,
            lambda: v2_validate_child_payload(
                false_with_compatibility_data
            ),
            contains="no-compatibility singleton receipt differs",
        )
        for field in (
            "title",
            "target_ids",
            "intended_generated_edges",
            "semantic_review_disposition",
            "semantic_review_receipt_state",
            "semantic_review_action",
            "semantic_review_receipt_roots",
            "reviewed_no_change_receipt_roots",
            "responsibility_assignments",
        ):
            mutated = dict(child)
            mutated.pop(field)
            mutated = v2_rooted(mutated)
            checks.refuses(
                f"missing-{field}",
                InputRefused,
                lambda mutated=mutated: v2_validate_child_payload(mutated),
                contains="non-closed schema",
            )

        optional_target = {
            "id": "closure-optional",
            "source_closure": {
                "required": False,
                "state": "NOT_REQUIRED_BY_V1_CLASSIFICATION",
            },
        }
        optional_receipt = {
            "source_closure": dict(optional_target["source_closure"]),
            "semantic_review_dimensions": [],
        }
        required_target = {
            "id": "closure-required",
            "source_closure": {
                "required": True,
                "state": "REVIEW_REQUIRED",
            },
        }

        def closure_receipt(
            *,
            state: str,
            verdict: str | None,
        ) -> dict[str, Any]:
            return {
                "source_closure": {
                    "required": True,
                    "state": state,
                },
                "semantic_review_dimensions": (
                    []
                    if verdict is None
                    else [
                        {
                            "dimension": "source_and_terminal_closure",
                            "verdict": verdict,
                        }
                    ]
                ),
            }

        v2_validate_source_closure_transition(
            target=optional_target,
            receipt=optional_receipt,
            semantic_complete=False,
        )
        for state, verdict in (
            ("REVIEW_REQUIRED", None),
            ("ROOT_BOUND_REVIEWED_COMPLETE", "SATISFIED"),
            ("ROOT_BOUND_NOT_APPLICABLE", "NOT_APPLICABLE"),
            ("ROOT_BOUND_REVIEW_BLOCKED", "FINDING"),
        ):
            v2_validate_source_closure_transition(
                target=required_target,
                receipt=closure_receipt(
                    state=state,
                    verdict=verdict,
                ),
                semantic_complete=verdict is not None,
            )
        checks.check(
            "source-closure-transition-matrix-valid-cells",
            True,
            expected=[
                "NOT_REQUIRED_IMMUTABLE",
                "REVIEW_REQUIRED",
                "ROOT_BOUND_REVIEWED_COMPLETE",
                "ROOT_BOUND_NOT_APPLICABLE",
                "ROOT_BOUND_REVIEW_BLOCKED",
            ],
            observed="all accepted",
        )
        changed_optional = {
            **optional_receipt,
            "source_closure": {
                "required": False,
                "state": "ROOT_BOUND_NOT_APPLICABLE",
            },
        }
        checks.refuses(
            "source-closure-not-required-state-change-refused",
            InputRefused,
            lambda: v2_validate_source_closure_transition(
                target=optional_target,
                receipt=changed_optional,
                semantic_complete=False,
            ),
            contains="changes a not-required source closure",
        )
        changed_required_flag = closure_receipt(
            state="REVIEW_REQUIRED",
            verdict=None,
        )
        changed_required_flag["source_closure"]["required"] = False
        checks.refuses(
            "source-closure-required-flag-change-refused",
            InputRefused,
            lambda: v2_validate_source_closure_transition(
                target=required_target,
                receipt=changed_required_flag,
                semantic_complete=False,
            ),
            contains="changes the source-closure obligation",
        )
        stale_required_target = {
            **required_target,
            "source_closure": {
                "required": True,
                "state": "ROOT_BOUND_REVIEWED_COMPLETE",
            },
        }
        checks.refuses(
            "source-closure-stale-target-base-refused",
            InputRefused,
            lambda: v2_validate_source_closure_transition(
                target=stale_required_target,
                receipt=closure_receipt(
                    state="ROOT_BOUND_REVIEWED_COMPLETE",
                    verdict="SATISFIED",
                ),
                semantic_complete=True,
            ),
            contains="invalid base state",
        )
        checks.refuses(
            "source-closure-verdict-state-mismatch-refused",
            InputRefused,
            lambda: v2_validate_source_closure_transition(
                target=required_target,
                receipt=closure_receipt(
                    state="ROOT_BOUND_REVIEW_BLOCKED",
                    verdict="SATISFIED",
                ),
                semantic_complete=True,
            ),
            contains="transition disagrees",
        )
        two_target_inventory = v2_synthetic_inventory(
