            projection_label="EXACT_TARGET_ROWS_BYTES",
        )
        incompatible_authority = v2_synthetic_authority(
            mutation_inventory,
            declared=False,
            manual=False,
        )
        v2_build_review_plan(
            mutation_inventory,
            incompatible_authority,
            max_targets=10,
        )
        checks.check(
            "analysis-route-target-unchanged",
            semantic_root(target_projection()) == before
            and incompatible_authority["decisions"][0][
                "remediation_route"
            ]
            == "ANALYSIS_ONLY",
            expected=(before, "ANALYSIS_ONLY"),
            observed=(
                semantic_root(target_projection()),
                incompatible_authority["decisions"][0][
                    "remediation_route"
                ],
            ),
        )
    else:
        raise EvidenceFailed(f"no authority executor for {slug}")
    return checks.finish(parameters)


def v2_execute_packing_cases(
    case: Mapping[str, Any],
    manifest: Mapping[str, Any],
) -> dict[str, Any]:
    del manifest
    slug = str(case["id"]).removeprefix("template-lint-v2.")
    checks = V2CheckCollector(case["id"], case["assertion_id"])
    parameters = {"family": "packing", "slug": slug}
    if slug == "packing-hard-keys":
        base = v2_synthetic_target(0)
        authority = v2_synthetic_authority(
            v2_synthetic_inventory([base])
        )["decisions"][0]
        base_vector = v2_hard_vector(base, authority)
        mutations = {
            "priority": {"priority": 3},
            "status": {"status": "blocked"},
            "disposition": {"disposition": "OWNER_REVIEW_REQUIRED"},
            "type": {"type": "bug"},
            "missing": {"missing_sections": ["## Success Criteria"]},
        }
        for name, changes in mutations.items():
            target = dict(base)
            target.update(changes)
            checks.check(
                f"hard-key-{name}",
                v2_hard_vector(target, authority) != base_vector,
                expected="different vector",
                observed=v2_hard_vector(target, authority),
            )
        changed_authority = dict(authority)
        changed_authority["semantic_review_disposition"] = (
            "BLOCKED_AUTHORITY"
        )
        checks.check(
            "hard-key-semantic-review-disposition",
            v2_hard_vector(base, changed_authority) != base_vector,
            expected="different vector",
            observed=v2_hard_vector(base, changed_authority),
        )
        changed_authority = dict(authority)
        changed_authority["semantic_review_receipt_state"] = (
            "ROOT_BOUND_REVIEWED"
        )
        checks.check(
            "hard-key-semantic-review-receipt-state",
            v2_hard_vector(base, changed_authority) != base_vector,
            expected="different vector",
            observed=v2_hard_vector(base, changed_authority),
        )
        changed_authority = dict(authority)
        changed_authority["semantic_review_action"] = (
            "AUTHORITY_RESOLUTION_REQUIRED"
        )
        checks.check(
            "hard-key-semantic-review-action",
            v2_hard_vector(base, changed_authority) != base_vector,
            expected="different vector",
            observed=v2_hard_vector(base, changed_authority),
        )
        changed_authority = dict(authority)
        changed_authority["readiness"] = "DECLARED_READY"
        checks.check(
            "hard-key-readiness",
            v2_hard_vector(base, changed_authority) != base_vector,
            expected="different vector",
            observed=v2_hard_vector(base, changed_authority),
        )
        changed_authority = dict(authority)
        changed_authority["remediation_route"] = "MANUAL_BR_REVIEW"
        checks.check(
            "hard-key-remediation-route",
            v2_hard_vector(base, changed_authority) != base_vector,
            expected="different vector",
            observed=v2_hard_vector(base, changed_authority),
        )
        changed_authority = dict(authority)
        changed_context = dict(changed_authority["active_work_context"])
        changed_context["generated_child_desired_status"] = "deferred"
        changed_authority["active_work_context"] = changed_context
        checks.check(
            "hard-key-generated-child-desired-status",
            v2_hard_vector(base, changed_authority) != base_vector,
            expected="different vector",
            observed=v2_hard_vector(base, changed_authority),
        )
    elif slug == "packing-compatible-receipt":
        plan, _, _ = v2_plan_for_count(2, max_targets=10)
        checks.check(
            "compatible-merge",
            len(plan["children"]) == 1
            and len(plan["children"][0]["target_ids"]) == 2,
            expected={"children": 1, "targets": 2},
            observed={
                "children": len(plan["children"]),
                "targets": len(plan["children"][0]["target_ids"]),
            },
        )
        checks.check(
            "receipt-rationale-falsifier",
            bool(plan["children"][0]["compatibility"]["rationale"])
            and bool(plan["children"][0]["compatibility"]["falsifier"]),
            expected=True,
            observed=plan["children"][0]["compatibility"],
        )
        identity_inventory = v2_synthetic_inventory(
            [
                v2_synthetic_target(
                    50,
                    issue_id="packing-identity-a",
                ),
                v2_synthetic_target(
                    51,
                    issue_id="packing-identity-b",
                ),
            ]
        )
        identity_authority = v2_synthetic_authority(
            identity_inventory,
            compatible=True,
        )
        identity_decisions = {
            row["target_id"]: row
            for row in identity_authority["decisions"]
        }
        identity_rows = [
            (target, identity_decisions[target["id"]])
            for target in identity_inventory["rows"]
        ]
        stale_target = dict(identity_rows[0][0])
        stale_target["title"] = "Stale packing target"
        stale_authority = dict(identity_rows[0][1])
        stale_authority["implementation_owner"] = "stale-owner"
        cross_bound_authority = strict_json_loads(
            canonical_bytes(identity_rows[0][1]),
            label="packing cross-bound authority seed",
            require_canonical=True,
        )
        cross_bound_authority.pop("semantic_root", None)
        cross_bound_authority["target_root"] = identity_rows[1][0][
            "target_root"
        ]
        cross_bound_authority = v2_rooted(cross_bound_authority)
        stale_estimate_target = strict_json_loads(
            canonical_bytes(identity_rows[0][0]),
            label="packing stale normalized estimate seed",
            require_canonical=True,
        )
        stale_estimate_target.pop("semantic_root", None)
        stale_estimate_target["target_implementation_estimated_minutes"] = 61
        stale_estimate_target["target_implementation_estimate_minutes"] = 61
        stale_estimate_target = v2_rooted(stale_estimate_target)
        stale_dependency_target = strict_json_loads(
            canonical_bytes(identity_rows[0][0]),
            label="packing stale normalized dependency seed",
            require_canonical=True,
        )
        stale_dependency_target.pop("semantic_root", None)
        stale_dependency_target["dependency_neighborhood_root"] = semantic_root(
            {"stale": "packing dependency neighborhood"}
        )
        stale_dependency_target = v2_rooted(stale_dependency_target)
        row_mutations = (
            (
                "stale_target",
                (stale_target, identity_rows[0][1]),
            ),
            (
                "stale_authority",
                (identity_rows[0][0], stale_authority),
            ),
            (
                "cross_bound_target_root",
                (identity_rows[0][0], cross_bound_authority),
            ),
            (
                "rerooted_estimate_with_stale_target_root",
                (stale_estimate_target, identity_rows[0][1]),
            ),
            (
                "rerooted_dependency_with_stale_target_root",
                (stale_dependency_target, identity_rows[0][1]),
            ),
        )
        with _v2_child_transport_cache_lock:
            cache_before_entrypoints = [
                (
                    key,
                    value,
                    (value[0], value[1], dict(value[2])),
                )
                for key, value in _v2_child_transport_cache.items()
            ]
        entrypoint_errors: dict[str, HarnessError] = {}
        for mutation_label, mutated_row in row_mutations:
            for entrypoint, callback in (
                (
                    "child_identity",
                    lambda mutated_row=mutated_row: (
                        v2_child_row_identity([mutated_row])
                    ),
                ),
                (
                    "packing_binding",
                    lambda mutated_row=mutated_row: (
                        v2_packing_input_bindings([mutated_row])
                    ),
                ),
                (
                    "transport_observation",
                    lambda mutated_row=mutated_row: (
                        v2_child_transport_observations([mutated_row])
                    ),
                ),
                (
                    "child_builder",
                    lambda mutated_row=mutated_row: v2_make_child(
                        [mutated_row],
                        packing_witness={
                            "semantic_root": V2_PACKING_PREFLIGHT_WITNESS_ROOT,
                        },
                    ),
                ),
            ):
                entrypoint_errors[
                    f"{mutation_label}/{entrypoint}"
                ] = expect_error(EvidenceFailed, callback)
        with _v2_child_transport_cache_lock:
            cache_after_entrypoints = list(
                _v2_child_transport_cache.items()
            )
        cache_unchanged = (
            len(cache_after_entrypoints) == len(cache_before_entrypoints)
            and all(
                observed_key == expected_key
                and observed_value is expected_value
                and observed_value == expected_copy
                for (
                    observed_key,
                    observed_value,
                ), (
                    expected_key,
                    expected_value,
                    expected_copy,
                ) in zip(
                    cache_after_entrypoints,
                    cache_before_entrypoints,
                    strict=True,
                )
            )
        )
        duplicate_binding_error = expect_error(
            EvidenceFailed,
            lambda: v2_packing_input_bindings(
                [identity_rows[0], identity_rows[0]]
            ),
            contains="duplicated",
        )
        checks.check(
            "packing-row-identity-entrypoints-refusal-matrix",
            len(entrypoint_errors) == len(row_mutations) * 4
            and all(
                error.terminal == "EvidenceFailed"
                for error in entrypoint_errors.values()
            )
            and duplicate_binding_error.terminal == "EvidenceFailed"
            and cache_unchanged,
            expected={
                "mutation_entrypoint_refusals": len(row_mutations) * 4,
                "duplicate_binding": "EvidenceFailed",
                "transport_cache_unchanged": True,
            },
            observed={
                "mutation_entrypoints": {
                    label: {
                        "terminal": error.terminal,
                        "diagnostic": str(error),
                    }
                    for label, error in entrypoint_errors.items()
                },
                "duplicate_binding": {
                    "terminal": duplicate_binding_error.terminal,
                    "diagnostic": str(duplicate_binding_error),
                },
                "transport_cache_unchanged": cache_unchanged,
            },
        )

        invalid_id_errors: dict[str, HarnessError] = {}
        invalid_ids = {
            "whitespace": "   ",
            "over_cap": (
                "p" * (V2_LOCAL_ISSUE_PREFIX_BYTES_CAP + 1) + "-abc"
            ),
            "ill_formed_unicode": "packing-\udcff",
        }
        for label, invalid_id in invalid_ids.items():
            invalid_target = dict(identity_rows[0][0])
            invalid_authority = dict(identity_rows[0][1])
            invalid_target["id"] = invalid_id
            invalid_authority["target_id"] = invalid_id
            invalid_id_errors[label] = expect_error(
                EvidenceFailed,
                lambda invalid_target=invalid_target,
                invalid_authority=invalid_authority: (
                    v2_packing_group_row_identity(
                        [(invalid_target, invalid_authority)]
                    )
                ),
            )
        mismatched_id_authority = dict(identity_rows[0][1])
        mismatched_id_authority["target_id"] = "packing-identity-b"
        mismatched_id_error = expect_error(
            EvidenceFailed,
            lambda: v2_packing_group_row_identity(
                [(identity_rows[0][0], mismatched_id_authority)]
            ),
            contains="mismatched",
        )
        prior_group_cap = V2_INVENTORY_ROWS_CAP
        try:
            globals()["V2_INVENTORY_ROWS_CAP"] = 1
            admitted_group_identity = v2_packing_group_row_identity(
                [identity_rows[0]]
            )
            over_group_cap_error = expect_error(
                EvidenceFailed,
                lambda: v2_packing_group_row_identity(identity_rows),
                contains="row cardinality",
            )
        finally:
            globals()["V2_INVENTORY_ROWS_CAP"] = prior_group_cap
        checks.check(
            "packing-row-id-grammar-and-group-cap-matrix",
            set(invalid_id_errors) == set(invalid_ids)
            and all(
                error.terminal == "EvidenceFailed"
                for error in invalid_id_errors.values()
            )
            and mismatched_id_error.terminal == "EvidenceFailed"
            and len(admitted_group_identity) == 1
            and over_group_cap_error.terminal == "EvidenceFailed",
            expected={
                "invalid_id_refusals": sorted(invalid_ids),
                "mismatched_id": "EvidenceFailed",
                "group_cap_n": 1,
                "group_cap_n_plus_one": "EvidenceFailed",
            },
            observed={
                "invalid_ids": {
                    label: {
                        "terminal": error.terminal,
                        "diagnostic": str(error),
                    }
                    for label, error in invalid_id_errors.items()
                },
                "mismatched_id": {
                    "terminal": mismatched_id_error.terminal,
                    "diagnostic": str(mismatched_id_error),
                },
                "admitted_group_size": len(admitted_group_identity),
                "over_cap": {
                    "terminal": over_group_cap_error.terminal,
                    "diagnostic": str(over_group_cap_error),
                },
            },
        )

        reviewed_inventory = v2_synthetic_inventory(
            [
                v2_synthetic_target(
                    60,
                    issue_id="packing-forged-compatibility-a",
                ),
                v2_synthetic_target(
                    61,
                    issue_id="packing-forged-compatibility-b",
                ),
            ]
        )
        reviewed_receipts = v2_synthetic_receipts(
            reviewed_inventory,
            semantic_reviewed=True,
            semantic_disposition="REMEDIATION_REQUIRED",
        )
        reviewed_authority = v2_derive_authority(
            reviewed_inventory,
            reviewed_receipts,
            current_br_version="0.2.19",
        )
        forged_compatibility_authority = strict_json_loads(
            canonical_bytes(reviewed_authority),
            label="forged authority compatibility seed",
            require_canonical=True,
        )
        forged_compatibility_authority.pop("semantic_root", None)
        forged_ids = sorted(
            row["id"] for row in reviewed_inventory["rows"]
        )
        forged_root = semantic_root(
            {"forged": "authority compatibility"}
        )
        forged_decisions: list[dict[str, Any]] = []
        for decision in forged_compatibility_authority["decisions"]:
            decision.pop("semantic_root", None)
            decision["compatibility"] = {
                "key": "forged-authority-merge",
                "target_ids": forged_ids,
                "receipt_root": forged_root,
                "rationale": "forged collective rationale",
                "falsifier": "forged collective falsifier",
                "target_complete": True,
            }
            forged_decisions.append(v2_rooted(decision))
        forged_compatibility_authority["decisions"] = forged_decisions
        forged_compatibility_authority = v2_rooted(
            forged_compatibility_authority
        )
        forged_compatibility_error = expect_error(
            HarnessError,
            lambda: v2_build_review_plan(
                reviewed_inventory,
                forged_compatibility_authority,
                max_targets=10,
            ),
            contains="root does not match its scope",
        )
        checks.check(
            "forged-authority-compatibility-cannot-mint-merge",
            forged_compatibility_error.terminal
            in {"InputRefused", "EvidenceFailed"},
            expected={
                "terminal": "refused",
                "diagnostic": "root does not match its scope",
            },
            observed={
                "terminal": forged_compatibility_error.terminal,
                "diagnostic": str(forged_compatibility_error),
            },
        )

        contradiction_inventory = v2_synthetic_inventory(
            [
                v2_synthetic_target(
                    70,
                    issue_id="packing-authority-contradiction",
                )
            ]
        )
        contradiction_authority = v2_synthetic_authority(
            contradiction_inventory
        )

        def contradictory_authority(
            mutation: Callable[[dict[str, Any]], None],
        ) -> dict[str, Any]:
            candidate = strict_json_loads(
                canonical_bytes(contradiction_authority),
                label="authority contradiction seed",
                require_canonical=True,
            )
            candidate.pop("semantic_root", None)
            decision = candidate["decisions"][0]
            decision.pop("semantic_root", None)
            mutation(decision)
            candidate["decisions"][0] = v2_rooted(decision)
            return v2_rooted(candidate)

        contradiction_mutations = {
            "external_verified_without_evidence": (
                lambda decision: decision["external_authority"].__setitem__(
                    "verified",
                    True,
                )
            ),
            "conditional_verified_without_evidence": (
                lambda decision: decision[
                    "conditional_write_capability"
                ].__setitem__("verified", True)
            ),
            "gate_verified_without_evidence": (
                lambda decision: decision["gate_admission"].__setitem__(
                    "verified",
                    True,
                )
            ),
            "manual_claims_mechanical_authority": (
                lambda decision: decision["manual_authorization"].__setitem__(
                    "mechanical_authority",
                    True,
                )
            ),
            "empty_compatibility_claims_complete": (
                lambda decision: decision["compatibility"].__setitem__(
                    "target_complete",
                    True,
                )
            ),
            "deferred_prohibition_flip": (
                lambda decision: decision.__setitem__(
                    "deferred_apply_prohibition",
                    True,
                )
            ),
        }
        contradiction_errors: dict[str, HarnessError] = {}
        for label, mutation in contradiction_mutations.items():
            candidate = contradictory_authority(mutation)
            contradiction_errors[label] = expect_error(
                HarnessError,
                lambda candidate=candidate: v2_build_review_plan(
                    contradiction_inventory,
                    candidate,
                    max_targets=10,
                ),
            )
        mechanical_receipts = v2_synthetic_receipts(
            contradiction_inventory,
            declared=True,
            external_verdict="VALID",
            conditional_verdict="VALID",
            gate_verdict="VALID",
        )
        mechanical_authority = v2_derive_authority(
            contradiction_inventory,
            mechanical_receipts,
            current_br_version="0.3.0",
            allow_mechanical_fixture=True,
        )
        contradiction_errors["mechanical_receipt_provenance_omitted"] = (
            expect_error(
                EvidenceFailed,
                lambda: v2_build_review_plan(
                    contradiction_inventory,
                    mechanical_authority,
                    max_targets=10,
                ),
                contains="lacks its admitted receipt document",
            )
        )
        mechanical_control_plan, _ = v2_build_review_plan(
            contradiction_inventory,
            mechanical_authority,
            max_targets=10,
            review_receipts=mechanical_receipts,
            allow_mechanical_fixture=True,
        )
        expected_contradiction_labels = {
            *contradiction_mutations,
            "mechanical_receipt_provenance_omitted",
        }
        checks.check(
            "authority-nested-state-contradiction-refusal-matrix",
            set(contradiction_errors) == expected_contradiction_labels
            and all(
                error.terminal in {"InputRefused", "EvidenceFailed"}
                for error in contradiction_errors.values()
            )
            and mechanical_control_plan["children"][0][
                "remediation_route"
            ]
            == "AUTOMATED_CONDITIONAL",
            expected={
                **{
                    label: "refused"
                    for label in expected_contradiction_labels
                },
                "root_bound_mechanical_control": "AUTOMATED_CONDITIONAL",
            },
            observed={
                "refusals": {
                    label: {
                        "terminal": error.terminal,
                        "diagnostic": str(error),
                    }
                    for label, error in contradiction_errors.items()
                },
                "root_bound_mechanical_control": (
                    mechanical_control_plan["children"][0][
                        "remediation_route"
                    ]
                ),
            },
        )
    elif slug == "packing-generic-merge-refused":
        def check_hostile_twins(
            name: str,
            targets: Sequence[Mapping[str, Any]],
            *,
            declared: bool = False,
        ) -> None:
            inventory = v2_synthetic_inventory(targets)
            receipts = v2_synthetic_receipts(
                inventory,
                declared=declared,
            )
            authority = v2_derive_authority(
                inventory,
                receipts,
                current_br_version="0.2.19",
            )
            plan, _ = v2_build_review_plan(
                inventory,
                authority,
                max_targets=10,
                review_receipts=receipts,
            )
            children = plan["children"]
            checks.check(
                f"{name}-cannot-merge",
                len(children) == len(targets) == 2
                and all(
                    len(child["target_ids"]) == 1
                    and child["compatibility"]["target_complete"] is False
                    and child["compatibility"]["key"] == ""
                    and child["compatibility"]["target_ids"] == []
                    for child in children
                )
                and sorted(
                    target_id
                    for child in children
                    for target_id in child["target_ids"]
                )
                == sorted(str(target["id"]) for target in targets),
                expected={
                    "children": 2,
                    "target_counts": [1, 1],
                    "compatibility": "absent",
                },
                observed={
                    "children": len(children),
                    "target_counts": [
                        len(child["target_ids"]) for child in children
                    ],
                    "compatibility": [
                        child["compatibility"] for child in children
                    ],
                },
            )

        check_hostile_twins(
            "bare-type-twins",
            [
                v2_synthetic_target(
                    0,
                    issue_id="generic-bare-type-a",
                    issue_type="task",
                ),
                v2_synthetic_target(
                    1,
                    issue_id="generic-bare-type-b",
                    issue_type="task",
                ),
            ],
        )
        lexical_a = v2_synthetic_target(
            0,
            issue_id="generic-lexical-a",
        )
        lexical_b = v2_synthetic_target(
            1,
            issue_id="generic-lexical-b",
        )
        lexical_a = v2_rebind_synthetic_target_identity(
            {
                **{
                    key: value
                    for key, value in lexical_a.items()
                    if key != "semantic_root"
                },
                "title": "Review mesh import boundary",
            }
        )
        lexical_b = v2_rebind_synthetic_target_identity(
            {
                **{
                    key: value
                    for key, value in lexical_b.items()
                    if key != "semantic_root"
                },
                "title": "Review mesh imports boundary",
            }
        )
        check_hostile_twins(
            "lexical-similarity-twins",
            [lexical_a, lexical_b],
        )
        copied_a = v2_synthetic_target(
            0,
            issue_id="generic-copied-prose-a",
        )
        copied_b = dict(
            v2_synthetic_target(
                1,
                issue_id="generic-copied-prose-b",
            )
        )
        copied_b.pop("semantic_root", None)
        copied_b["field_roots"] = dict(copied_a["field_roots"])
        copied_b["field_byte_lengths"] = dict(
            copied_a["field_byte_lengths"]
        )
        copied_b["clause_roots"] = strict_json_loads(
            canonical_bytes(copied_a["clause_roots"]),
            label="copied-prose clause roots",
            require_canonical=True,
        )
        copied_b = v2_rebind_synthetic_target_identity(copied_b)
        check_hostile_twins(
            "copied-prose-twins",
            [copied_a, copied_b],
        )
        check_hostile_twins(
            "aggregate-warning-count-twins",
            [
                v2_synthetic_target(
                    0,
                    issue_id="generic-count-a",
                    missing_sections=("## Acceptance Criteria",),
                ),
                v2_synthetic_target(
                    1,
                    issue_id="generic-count-b",
                    missing_sections=("## Success Criteria",),
                ),
            ],
        )
        check_hostile_twins(
            "generic-domain-twins",
            [
                v2_synthetic_target(
                    0,
                    issue_id="generic-domain-a",
                ),
                v2_synthetic_target(
                    1,
                    issue_id="generic-domain-b",
                ),
            ],
            declared=True,
        )
    elif slug == "packing-rationale-falsifier":
