        )

        def record_direct_review_plan_refusal(
            check_id: str,
            callback: Callable[[], Any],
            *,
            contains: str,
        ) -> None:
            cache_before = list(_v2_child_transport_cache.items())
            error = expect_error(
                EvidenceFailed,
                callback,
                contains=contains,
            )
            cache_after = list(_v2_child_transport_cache.items())
            checks.check(
                check_id,
                error.terminal == "EvidenceFailed"
                and contains in str(error)
                and cache_after == cache_before,
                expected={
                    "terminal": "EvidenceFailed",
                    "diagnostic": contains,
                    "transport_cache_unchanged": True,
                },
                observed={
                    "terminal": error.terminal,
                    "diagnostic": str(error),
                    "transport_cache_unchanged": (
                        cache_after == cache_before
                    ),
                },
            )

        prior_inventory_rows_cap = V2_INVENTORY_ROWS_CAP
        try:
            globals()["V2_INVENTORY_ROWS_CAP"] = 0
            for field in bounded_review_fields:
                stale_plan = strict_json_loads(
                    canonical_bytes(plan),
                    label="review-plan collection cap mutation seed",
                    require_canonical=True,
                )
                for bounded_field in bounded_review_fields:
                    stale_plan[bounded_field] = []
                stale_plan[field] = [{}]
                record_direct_review_plan_refusal(
                    f"review-plan-{field}-cap-precedes-stale-root",
                    lambda stale_plan=stale_plan: v2_validate_review_plan(
                        stale_plan,
                        inventory,
                        authority,
                    ),
                    contains="row cap",
                )
            record_direct_review_plan_refusal(
                "review-plan-builder-cap-precedes-rooting",
                lambda: v2_build_review_plan(
                    inventory,
                    authority,
                    max_targets=10,
                ),
                contains="source collections exceed the exact row cap",
            )
        finally:
            globals()["V2_INVENTORY_ROWS_CAP"] = prior_inventory_rows_cap
        prior_run_artifact_cap = RUN_ARTIFACT_CAP
        stale_plan = strict_json_loads(
            canonical_bytes(plan),
            label="review-plan artifact cap mutation seed",
            require_canonical=True,
        )
        stale_plan["no_claim"] += " stale"
        try:
            globals()["RUN_ARTIFACT_CAP"] = 1
            record_direct_review_plan_refusal(
                "review-plan-byte-cap-precedes-stale-root",
                lambda: v2_validate_review_plan(
                    stale_plan,
                    inventory,
                    authority,
                ),
                contains="aggregate byte cap",
            )
            record_direct_review_plan_refusal(
                "review-plan-builder-byte-cap-before-rooting",
                lambda: v2_build_review_plan(
                    inventory,
                    authority,
                    max_targets=10,
                ),
                contains="aggregate byte cap",
            )
        finally:
            globals()["RUN_ARTIFACT_CAP"] = prior_run_artifact_cap
    elif slug == "packing-exact-small-optimum":
        for count in range(1, 14):
            plan, _, _ = v2_plan_for_count(count, max_targets=3)
            witness = plan["packing_witnesses"][0]
            expected_children = math.ceil(count / 3)
            checks.check(
                f"exact-count-{count:02d}",
                witness["algorithm"] == "EXACT_SUBSET_PARTITION"
                and witness["exact_optimality_claim"] is True
                and witness["objective"]["child_count"] == expected_children,
                expected={
                    "algorithm": "EXACT_SUBSET_PARTITION",
                    "children": expected_children,
                },
                observed={
                    "algorithm": witness["algorithm"],
                    "children": witness["objective"]["child_count"],
                },
            )
        minute_loads = (240, 240, 160, 160, 80, 80)
        byte_loads = (900, 100, 800, 200, 700, 300)
        inventory = v2_synthetic_inventory(
            [
                v2_synthetic_target(
                    index,
                    review_minutes=minutes,
                    retained_payload_bytes=byte_loads[index],
                )
                for index, minutes in enumerate(minute_loads)
            ]
        )
        authority = v2_synthetic_authority(inventory, compatible=True)
        authority_by_id = {
            row["target_id"]: row for row in authority["decisions"]
        }
        rows = [
            (target, authority_by_id[target["id"]])
            for target in inventory["rows"]
        ]

        def independent_load(
            group: Sequence[
                tuple[Mapping[str, Any], Mapping[str, Any]]
            ],
        ) -> tuple[int, int, int]:
            return (
                sum(int(decision["review_minutes"]) for _, decision in group),
                sum(int(target["retained_payload_bytes"]) for target, _ in group),
                len(group),
            )

        def independent_key(
            groups: Sequence[
                Sequence[tuple[Mapping[str, Any], Mapping[str, Any]]]
            ],
        ) -> tuple[Any, ...]:
            loads = [independent_load(group) for group in groups]
            return (
                len(groups),
                max(load[0] for load in loads),
                max(load[1] for load in loads),
                max(load[2] for load in loads),
                tuple(sorted(loads, reverse=True)),
                tuple(
                    sorted(
                        tuple(sorted(target["id"] for target, _ in group))
                        for group in groups
                    )
                ),
            )

        independent_best: tuple[Any, ...] | None = None

        def enumerate_partitions(
            index: int,
            groups: list[
                list[tuple[Mapping[str, Any], Mapping[str, Any]]]
            ],
        ) -> None:
            nonlocal independent_best
            if index == len(rows):
                candidate = independent_key(groups)
                if independent_best is None or candidate < independent_best:
                    independent_best = candidate
                return
            row = rows[index]
            for group_index in range(len(groups) + 1):
                if group_index == len(groups):
                    groups.append([row])
                    enumerate_partitions(index + 1, groups)
                    groups.pop()
                    continue
                proposed = [*groups[group_index], row]
                minutes, retained_bytes, target_count = independent_load(proposed)
                if (
                    target_count > 3
                    or minutes > V2_REVIEW_MINUTES_CAP
                    or retained_bytes > V2_CHILD_PAYLOAD_CAP
                ):
                    continue
                groups[group_index].append(row)
                enumerate_partitions(index + 1, groups)
                groups[group_index].pop()

        enumerate_partitions(0, [])
        actual_bins, actual_witness = v2_pack_group(rows, max_targets=3)
        actual_key = independent_key(actual_bins)
        checks.check(
            "independent-enumeration-confirms-varied-load-optimum",
            independent_best is not None
            and actual_key == independent_best
            and actual_witness["objective"]
            == v2_objective_document(actual_bins),
            expected=independent_best,
            observed=actual_key,
        )
    elif slug == "packing-large-gap-witness":
        large_inventory = v2_synthetic_inventory(
            [v2_synthetic_target(index) for index in range(14)]
        )
        large_receipts = v2_synthetic_receipts(
            large_inventory,
            compatible=True,
        )
        large_authority = v2_derive_authority(
            large_inventory,
            large_receipts,
            current_br_version="0.2.19",
        )
        plan, _ = v2_build_review_plan(
            large_inventory,
            large_authority,
            max_targets=10,
            review_receipts=large_receipts,
        )
        witness = plan["packing_witnesses"][0]
        target_by_id = {
            row["id"]: row for row in large_inventory["rows"]
        }
        authority_by_id = {
            row["target_id"]: row
            for row in large_authority["decisions"]
        }
        grouped_children = [
            child
            for child in plan["children"]
            if child["packing_witness_root"] == witness["semantic_root"]
        ]
        grouped_ids = sorted(
            target_id
            for child in grouped_children
            for target_id in child["target_ids"]
        )
        grouped_rows = [
            (target_by_id[target_id], authority_by_id[target_id])
            for target_id in grouped_ids
        ]
        v2_verify_packing_witness_independent(
            rows=grouped_rows,
            grouped_children=grouped_children,
            witness=witness,
            max_targets=10,
        )
        checks.check(
            "large-witness-complete-and-independently-validated",
            witness["algorithm"] == "DETERMINISTIC_LPT_VECTOR_PACKING"
            and "lower_bound_vector" in witness
            and "achieved_objective" in witness
            and "gap_witness" in witness
            and witness["exact_optimality_claim"] is False,
            expected=True,
            observed=witness,
        )

        def mutate_large_witness(
            mutation: Callable[[dict[str, Any]], None],
        ) -> dict[str, Any]:
            candidate = strict_json_loads(
                canonical_bytes(witness),
                label="large packing witness mutation seed",
                require_canonical=True,
            )
            candidate.pop("semantic_root", None)
            mutation(candidate)
            return v2_rooted(candidate)

        arithmetic_mutations: tuple[
            tuple[str, Callable[[dict[str, Any]], None]],
            ...,
        ] = (
            (
                "lower-bound-vector",
                lambda row: row["lower_bound_vector"].__setitem__(
                    "targets",
                    int(row["lower_bound_vector"]["targets"]) + 1,
                ),
            ),
            (
                "achieved-objective",
                lambda row: row["achieved_objective"].__setitem__(
                    "maximum_review_minutes",
                    int(
                        row["achieved_objective"][
                            "maximum_review_minutes"
                        ]
                    )
                    + 1,
                ),
            ),
            (
                "child-count-gap",
                lambda row: row.__setitem__(
                    "child_count_gap",
                    int(row["child_count_gap"]) + 1,
                ),
            ),
            (
                "gap-witness",
                lambda row: row["gap_witness"].__setitem__(
                    "maximum_retained_bytes_above_average",
                    int(
                        row["gap_witness"][
                            "maximum_retained_bytes_above_average"
                        ]
                    )
                    + 1,
                ),
            ),
        )
        for name, mutation in arithmetic_mutations:
            candidate = mutate_large_witness(mutation)
            witness_cache_before = list(
                _v2_child_transport_cache.items()
            )
            witness_error = expect_error(
                EvidenceFailed,
                lambda candidate=candidate: (
                    v2_verify_packing_witness_independent(
                        rows=grouped_rows,
                        grouped_children=grouped_children,
                        witness=candidate,
                        max_targets=10,
                    )
                ),
                contains="arithmetic differs",
            )
            checks.check(
                f"independent-validator-refuses-{name}-mutation",
                witness_error.terminal == "EvidenceFailed"
                and "arithmetic differs" in str(witness_error)
                and list(_v2_child_transport_cache.items())
                == witness_cache_before,
                expected={
                    "terminal": "EvidenceFailed",
                    "diagnostic": "arithmetic differs",
                    "cache_unchanged": True,
                },
                observed={
                    "terminal": witness_error.terminal,
                    "diagnostic": str(witness_error),
                    "cache_unchanged": (
                        list(_v2_child_transport_cache.items())
                        == witness_cache_before
                    ),
                },
            )
    elif slug == "packing-order-invariant":
        for population, max_targets, expected_algorithm in (
            (8, 3, "EXACT_SUBSET_PARTITION"),
            (14, 3, "DETERMINISTIC_LPT_VECTOR_PACKING"),
        ):
            targets = [
                v2_synthetic_target(index) for index in range(population)
            ]
            first_inventory = v2_synthetic_inventory(targets)
            second_inventory = v2_synthetic_inventory(
                list(reversed(targets))
            )
            first_receipts = v2_synthetic_receipts(
                first_inventory,
                compatible=True,
            )
            second_receipts = v2_synthetic_receipts(
                second_inventory,
                compatible=True,
            )
            first_authority = v2_derive_authority(
                first_inventory,
                first_receipts,
                current_br_version="0.2.19",
            )
            second_authority = v2_derive_authority(
                second_inventory,
                second_receipts,
                current_br_version="0.2.19",
            )
            first, _ = v2_build_review_plan(
                first_inventory,
                first_authority,
                max_targets=max_targets,
                review_receipts=first_receipts,
            )
            second, _ = v2_build_review_plan(
                second_inventory,
                second_authority,
                max_targets=max_targets,
                review_receipts=second_receipts,
            )
            checks.check(
                f"input-order-invariant-{population}",
                first["semantic_root"] == second["semantic_root"]
                and first["packing_witnesses"][0]["algorithm"]
                == expected_algorithm,
                expected={
                    "root": first["semantic_root"],
                    "algorithm": expected_algorithm,
                },
                observed={
                    "root": second["semantic_root"],
                    "algorithm": second["packing_witnesses"][0]["algorithm"],
                },
            )
        base_issues: list[dict[str, Any]] = []
        for index in range(3):
            base_issues.append(
                fixture_issue(
                    issue_id=f"permutation-{index}",
                    title=f"Permutation fixture {index}",
                    issue_type="bug",
                    priority=2,
                    labels=("zeta", "alpha", "middle"),
                    dependencies=(
                        {
                            "id": f"external:dependency-z-{index}",
                            "type": "related",
                            "status": "open",
                            "priority": 2,
                        },
                        {
                            "id": f"external:dependency-a-{index}",
                            "type": "blocks",
                            "status": "blocked",
                            "priority": 1,
                        },
                    ),
                )
            )
        permuted_issues: list[dict[str, Any]] = []
        for issue in reversed(base_issues):
            permuted = {
                key: value for key, value in reversed(tuple(issue.items()))
            }
            permuted["labels"] = list(issue["labels"])
            permuted["dependencies"] = [
                {
                    key: value
                    for key, value in reversed(tuple(edge.items()))
                }
                for edge in issue["dependencies"]
            ]
            permuted_issues.append(permuted)
        base_missing = {
            issue["id"]: (
                "## Steps to Reproduce",
                "## Acceptance Criteria",
            )
            for issue in base_issues
        }
        permuted_missing = {
            issue_id: tuple(reversed(values))
            for issue_id, values in reversed(tuple(base_missing.items()))
        }
        base_full, _, _, base_inventory = v2_authentic_projection_fixture(
            base_issues,
            missing_by_id=base_missing,
        )
        permuted_full, _, _, permuted_inventory = (
            v2_authentic_projection_fixture(
                permuted_issues,
                missing_by_id=permuted_missing,
            )
        )
        base_receipts = v2_synthetic_receipts(
            base_inventory,
            compatible=True,
        )
        permuted_receipts = v2_synthetic_receipts(
            permuted_inventory,
            compatible=True,
        )
        base_authority = v2_derive_authority(
            base_inventory,
            base_receipts,
            current_br_version="0.2.19",
        )
        permuted_authority = v2_derive_authority(
            permuted_inventory,
            permuted_receipts,
            current_br_version="0.2.19",
        )
        base_plan, _ = v2_build_review_plan(
            base_inventory,
            base_authority,
            max_targets=3,
            review_receipts=base_receipts,
        )
        permuted_plan, _ = v2_build_review_plan(
            permuted_inventory,
            permuted_authority,
            max_targets=3,
            review_receipts=permuted_receipts,
        )
        checks.check(
            "mapping-field-and-source-row-order-invariant",
            canonical_bytes(base_full) == canonical_bytes(permuted_full)
            and base_inventory["semantic_root"]
            == permuted_inventory["semantic_root"]
            and canonical_bytes(base_receipts)
            == canonical_bytes(permuted_receipts)
            and base_authority["semantic_root"]
            == permuted_authority["semantic_root"]
            and base_plan["semantic_root"]
            == permuted_plan["semantic_root"]
            and [
                child["child_key"] for child in base_plan["children"]
            ]
            == [
                child["child_key"]
                for child in permuted_plan["children"]
            ]
            and [
                child["target_ids"] for child in base_plan["children"]
            ]
            == [
                child["target_ids"]
                for child in permuted_plan["children"]
            ]
            and [
                witness["semantic_root"]
                for witness in base_plan["packing_witnesses"]
            ]
            == [
                witness["semantic_root"]
                for witness in permuted_plan["packing_witnesses"]
            ],
            expected={
                "inventory_root": base_inventory["semantic_root"],
                "authority_root": base_authority["semantic_root"],
                "plan_root": base_plan["semantic_root"],
                "child_keys": [
                    child["child_key"] for child in base_plan["children"]
                ],
            },
            observed={
                "inventory_root": permuted_inventory["semantic_root"],
                "authority_root": permuted_authority["semantic_root"],
                "plan_root": permuted_plan["semantic_root"],
                "child_keys": [
                    child["child_key"]
                    for child in permuted_plan["children"]
                ],
            },
        )
        raw_list_permuted_issues = []
        for issue in reversed(base_issues):
            raw_list_permuted = dict(issue)
            raw_list_permuted["labels"] = list(reversed(issue["labels"]))
            raw_list_permuted["dependencies"] = list(
                reversed(issue["dependencies"])
            )
            raw_list_permuted_issues.append(raw_list_permuted)
        (
            raw_list_full,
            _,
            _,
            raw_list_inventory,
        ) = v2_authentic_projection_fixture(
            raw_list_permuted_issues,
            missing_by_id=permuted_missing,
        )
        raw_list_receipts = v2_synthetic_receipts(
            raw_list_inventory,
            compatible=True,
        )
        raw_list_authority = v2_derive_authority(
            raw_list_inventory,
            raw_list_receipts,
            current_br_version="0.2.19",
        )
        raw_list_plan, _ = v2_build_review_plan(
            raw_list_inventory,
            raw_list_authority,
            max_targets=3,
            review_receipts=raw_list_receipts,
        )
        repeated_raw_list_full, _, _, repeated_raw_list_inventory = (
            v2_authentic_projection_fixture(
                list(reversed(raw_list_permuted_issues)),
                missing_by_id=base_missing,
            )
        )
        checks.check(
            "raw-list-order-provenance-rebinds-work-identity",
            [row["labels"] for row in base_full]
            == [row["labels"] for row in raw_list_full]
            and [row["dependencies"] for row in base_full]
            == [row["dependencies"] for row in raw_list_full]
            and all(
                base_row["released_field_value_roots"]["labels"]
                != raw_row["released_field_value_roots"]["labels"]
                and base_row["released_field_value_roots"]["dependencies"]
                != raw_row["released_field_value_roots"]["dependencies"]
                and base_row["source_issue_projection_root"]
                != raw_row["source_issue_projection_root"]
                for base_row, raw_row in zip(
                    base_full,
                    raw_list_full,
                    strict=True,
                )
            )
            and base_inventory["semantic_root"]
            != raw_list_inventory["semantic_root"]
            and base_authority["semantic_root"]
            != raw_list_authority["semantic_root"]
            and base_plan["semantic_root"] != raw_list_plan["semantic_root"]
            and canonical_bytes(raw_list_full)
            == canonical_bytes(repeated_raw_list_full)
            and raw_list_inventory["semantic_root"]
            == repeated_raw_list_inventory["semantic_root"],
            expected={
                "canonical_labels_and_relations": "equal",
                "raw_value_roots": "different",
                "downstream_work_identity": "different",
                "same_raw_input_replay": "stable",
            },
            observed={
                "base_inventory_root": base_inventory["semantic_root"],
                "permuted_inventory_root": raw_list_inventory[
                    "semantic_root"
                ],
                "base_plan_root": base_plan["semantic_root"],
                "permuted_plan_root": raw_list_plan["semantic_root"],
                "repeated_inventory_root": repeated_raw_list_inventory[
                    "semantic_root"
                ],
            },
        )
    elif slug == "packing-refinement-imbalance":
        inventory = v2_synthetic_inventory(
            [v2_synthetic_target(index) for index in range(4)]
        )
        merged_receipts = v2_synthetic_receipts(
            inventory,
            compatible=True,
        )
        merged = v2_derive_authority(
            inventory,
            merged_receipts,
            current_br_version="0.2.19",
        )
        merged_plan, _ = v2_build_review_plan(
            inventory,
            merged,
            max_targets=10,
            review_receipts=merged_receipts,
        )
        refined = v2_synthetic_authority(inventory, compatible=False)
        refined_plan, _ = v2_build_review_plan(
            inventory,
            refined,
            max_targets=10,
        )
        checks.check(
            "refinement-never-remerges",
            len(merged_plan["children"]) == 1
            and len(refined_plan["children"]) == 4,
            expected=(1, 4),
            observed=(
                len(merged_plan["children"]),
                len(refined_plan["children"]),
            ),
        )
    elif slug == "packing-oversize-escalation":
        inventory = v2_synthetic_inventory(
            [
                v2_synthetic_target(
                    0,
                    retained_payload_bytes=V2_CHILD_PAYLOAD_CAP + 1,
                )
            ]
        )
        authority = v2_synthetic_authority(inventory)
        plan, optional = v2_build_review_plan(
            inventory,
            authority,
            max_targets=10,
        )
        entry = plan["oversize_content"][0]
        full = strict_json_loads(
            next(iter(optional.values())),
            label="synthetic oversize",
            require_canonical=True,
        )
        checks.check(
            "oversize-registry-complete",
            set(entry) == V2_OVERSIZE_REGISTRY_FIELDS
            and full["bounded_incomplete_index"]["complete"] is False
            and entry["exceeded_caps"] == full["exceeded_caps"]
            and entry["exceeded_caps"]
            == v2_oversize_exceeded_caps(
                inventory["rows"][0],
                authority["decisions"][0],
            ),
            expected={
                "registry_fields": sorted(V2_OVERSIZE_REGISTRY_FIELDS),
                "bounded_index_complete": False,
                "exceeded_caps": [
                    "max_retained_child_payload_bytes"
                ],
            },
            observed={
                "registry_fields": sorted(entry),
                "bounded_index_complete": full[
                    "bounded_incomplete_index"
                ]["complete"],
                "exceeded_caps": [
                    row["cap"] for row in entry["exceeded_caps"]
                ],
                "full_root": full["semantic_root"],
            },
        )
        for (
            route_name,
            receipt_kwargs,
            version,
            allow_fixture,
            expected_route,
        ) in (
            (
                "manual",
                {"declared": True, "manual": True},
                "0.2.19",
                False,
                "MANUAL_BR_REVIEW",
            ),
            (
                "future-automated",
                {
                    "declared": True,
                    "external_verdict": "VALID",
                    "conditional_verdict": "VALID",
                    "gate_verdict": "VALID",
                },
                "0.3.0",
                True,
                "AUTOMATED_CONDITIONAL",
            ),
        ):
            routed_receipts = v2_synthetic_receipts(
                inventory,
                **receipt_kwargs,
            )
            routed_authority = v2_derive_authority(
                inventory,
                routed_receipts,
                current_br_version=version,
                allow_mechanical_fixture=allow_fixture,
            )
            routed_plan, _ = v2_build_review_plan(
                inventory,
                routed_authority,
                max_targets=10,
                review_receipts=routed_receipts,
                allow_mechanical_fixture=allow_fixture,
            )
            routed_child = routed_plan["children"][0]
            v2_validate_child_payload(routed_child)
            checks.check(
                f"oversize-{route_name}-route-preserved",
                routed_child["disposition_workflow"]
                == "OVERSIZE_REVIEW_REQUIRED"
                and routed_child["remediation_route"] == expected_route
                and routed_child["semantic_review_action"]
                == routed_authority["decisions"][0][
                    "semantic_review_action"
                ],
                expected={
                    "workflow": "OVERSIZE_REVIEW_REQUIRED",
                    "route": expected_route,
                },
                observed={
                    "workflow": routed_child["disposition_workflow"],
                    "route": routed_child["remediation_route"],
                    "semantic_action": routed_child[
                        "semantic_review_action"
                    ],
                },
            )
    else:
        raise EvidenceFailed(f"no packing executor for {slug}")
    return checks.finish(parameters)


def v2_history_fixture(
    manifest: Mapping[str, Any],
    *,
    legacy: bool = False,
    missing_modern_event: bool = False,
    conflicting_close: bool = False,
    candidate_consumers: bool = False,
) -> tuple[
    dict[str, Any],
    dict[str, Any],
    list[dict[str, Any]],
    dict[str, Any],
    dict[str, Any],
]:
    anchor_id = "fixture-anchor"
    anchor_closed_at = "2026-01-02T00:00:00.000000+00:00"
    anchor_raw = {
        "id": anchor_id,
        "title": "Fixture audit anchor",
        "issue_type": "task",
        "status": "closed",
        "priority": 2,
        "description": "Anchor source.",
        "acceptance_criteria": "Exact anchor.",
        "design": "",
        "notes": "See fixture-consumer." if candidate_consumers else "",
        "assignee": "fixture-assignee",
        "labels": [],
        "parent": "",
        "created_at": "2026-01-01T00:00:00+00:00",
        "created_by": "fixture-creator",
        "updated_at": "2026-01-02T00:00:00.002000+00:00",
        "closed_at": anchor_closed_at,
        "close_reason": "Fixture anchor completed.",
        "estimated_minutes": 5,
        "comments": [
            {
                "id": 10,
                "issue_id": anchor_id,
                "author": "fixture-tracker-commenter",
                "text": "Fixture retained tracker comment.",
                "created_at": "2026-01-01T12:00:00+00:00",
            }
        ],
        "dependencies": [],
        "dependents": (
            [
                {
                    "id": "fixture-consumer",
                    "title": "Fixture consumer",
                    "dependency_type": "blocks",
                    "status": "open",
                    "priority": 2,
                }
            ]
            if candidate_consumers
            else []
        ),
    }
    anchor = v2_full_issue_projection(anchor_raw)
    anchor_events = [
        {
            "id": 3,
            "event_type": "commented",
            "actor": "fixture-commenter",
            "timestamp": "2026-01-02T00:00:00.003000+00:00",
            "comment": "Fixture retained canonical comment.",
        },
        {
            "id": 2,
            "event_type": "closed",
            "actor": "fixture-closer",
            "timestamp": "2026-01-02T00:00:00.002000+00:00",
            "comment": "Fixture anchor completed.",
        },
        {
            "id": 1,
            "event_type": "status_changed",
            "actor": "fixture-closer",
            "timestamp": "2026-01-02T00:00:00.001000+00:00",
            "old_value": "open",
            "new_value": "closed",
        },
    ]
    if conflicting_close:
        anchor_events = [
            {
                "id": 5,
                "event_type": "closed",
                "actor": "other-closer",
                "timestamp": "2026-01-02T00:00:00.005000+00:00",
                "comment": "Fixture anchor completed.",
            },
            {
                "id": 4,
                "event_type": "status_changed",
                "actor": "other-closer",
                "timestamp": "2026-01-02T00:00:00.004000+00:00",
                "old_value": "open",
                "new_value": "closed",
            },
            *anchor_events,
        ]
    anchor_audit = v2_normalize_audit_document(
        {"issue_id": anchor_id, "events": anchor_events},
        issue_id=anchor_id,
    )
    all_issues = [anchor]
    audit_documents = [anchor_audit]
    target_id = anchor_id
    if missing_modern_event:
        modern_id = "fixture-modern-missing-close"
        modern_raw = {
            **anchor_raw,
            "id": modern_id,
            "title": "Fixture modern close without audit evidence",
            "closed_at": "2026-01-03T00:00:00+00:00",
            "updated_at": "2026-01-03T00:00:00+00:00",
            "close_reason": "Modern fixture completed.",
            "comments": [
                {**comment, "issue_id": modern_id}
                for comment in anchor_raw["comments"]
            ],
            "dependents": [],
        }
        modern_issue = v2_full_issue_projection(modern_raw)
        modern_audit = v2_normalize_audit_document(
            {"issue_id": modern_id, "events": []},
            issue_id=modern_id,
        )
        all_issues.append(modern_issue)
        audit_documents.append(modern_audit)
        target_id = modern_id
    if legacy:
        legacy_id = "fixture-legacy"
        legacy_raw = {
            **anchor_raw,
            "id": legacy_id,
            "title": "Fixture legacy close",
            "closed_at": "2026-01-01T12:00:00+00:00",
            "close_reason": "Legacy fixture completed.",
            "updated_at": "2026-01-03T00:00:00+00:00",
            "notes": "Later non-close audit metadata.",
            "comments": [
                {**comment, "issue_id": legacy_id}
                for comment in anchor_raw["comments"]
            ],
            "dependents": [],
        }
        legacy_issue = v2_full_issue_projection(legacy_raw)
        legacy_audit = v2_normalize_audit_document(
            {
                "issue_id": legacy_id,
                "events": [
                    {
                        "id": 4,
                        "event_type": "label_added",
                        "actor": "later-agent",
                        "timestamp": "2026-01-03T00:00:00+00:00",
                        "comment": "Added label after legacy close.",
                    }
                ],
            },
            issue_id=legacy_id,
        )
        all_issues.append(legacy_issue)
        audit_documents.append(legacy_audit)
        target_id = legacy_id
    issue_by_id = {row["id"]: row for row in all_issues}
    selected_issue = issue_by_id[target_id]
    target = v2_synthetic_target(
        0,
        issue_id=target_id,
        priority=selected_issue["priority"],
        status="closed",
        disposition="HISTORICAL_IMMUTABLE_REVIEW",
        issue_type=selected_issue["type"],
        assignee=selected_issue["assignee"],
    )
    target = dict(target)
    target.update(
        {
            "title": selected_issue["title"],
            "tracker_assignee": selected_issue["assignee"],
            "coordination_assignee": selected_issue["assignee"],
            "tracker_owner": selected_issue["owner"],
            "parent": selected_issue["parent"],
            "labels": list(selected_issue["labels"]),
            "field_roots": dict(selected_issue["field_roots"]),
            "dependencies": list(selected_issue["dependencies"]),
            "dependents": list(selected_issue["dependents"]),
            "target_implementation_estimated_minutes": selected_issue[
                "estimated_minutes"
            ],
            "target_implementation_estimate_minutes": selected_issue[
                "estimated_minutes"
            ],
            "target_implementation_estimate_state": (
                "DECLARED"
                if type(selected_issue["estimated_minutes"]) is int
                and selected_issue["estimated_minutes"] >= 0
                else "NODATA"
            ),
            "active_work_context": v2_active_work_context(
                selected_issue
            ),
        }
    )
    target = v2_rebind_synthetic_target_identity(target)
    inventory = v2_synthetic_inventory([target])
    authority = v2_synthetic_authority(inventory)
    audit_capture = v2_rooted(
        {
            "capture_count": 2,
            "worker_bound": 8,
            "issue_ids": sorted(row["issue_id"] for row in audit_documents),
            "documents": sorted(
                audit_documents, key=lambda row: row["issue_id"]
            ),
            "command_receipts": [],
            "raw_stream_bodies_retained": False,
            "no_claim": "synthetic audit capture",
        }
    )
    anchor_timestamp = v2_parse_timestamp(
        anchor_closed_at,
        label="fixture anchor",
    )
    legacy_rows = sorted(
        [
            {
                "id": issue["id"],
                "closed_at": issue["closed_at"],
                "close_reason_root": text_root(issue["close_reason"]),
            }
            for issue in all_issues
            if v2_parse_timestamp(
                issue["closed_at"],
                label=f"fixture {issue['id']}",
            )
            < anchor_timestamp
        ],
        key=lambda row: row["id"],
    )
    contract = dict(manifest["history_contract"])
    contract.update(
        {
            "legacy_coverage_anchor_issue": anchor_id,
            "legacy_coverage_anchor_closed_at": anchor_closed_at,
            "legacy_coverage_anchor_status_event_id": 1,
            "legacy_coverage_anchor_close_event_id": 2,
            "legacy_coverage_count": len(legacy_rows),
            "legacy_coverage_rows_root": semantic_root(legacy_rows),
            "known_pair_max_skew_ms": 1_000,
        }
    )
    return inventory, authority, all_issues, audit_capture, contract


def v2_execute_history_cases(
    case: Mapping[str, Any],
    manifest: Mapping[str, Any],
) -> dict[str, Any]:
    slug = str(case["id"]).removeprefix("template-lint-v2.")
    checks = V2CheckCollector(case["id"], case["assertion_id"])
    parameters = {"family": "history-zero-movement", "slug": slug}
    if slug == "history-known-closer":
        inventory, authority, issues, audit, contract = v2_history_fixture(
            manifest
        )
        source_root = semantic_root({"fixture": "known"})
        history = v2_build_history(
            source_root=source_root,
            inventory=inventory,
            authority=authority,
            all_issues=issues,
            audit_capture=audit,
            history_contract=contract,
        )
        row = history["rows"][0]
        close_pair_hook_calls = {
            "outer_getitem": 0,
            "outer_iteration": 0,
            "outer_length": 0,
            "mapping_get": 0,
            "mapping_items": 0,
            "mapping_iteration": 0,
            "scalar_equality": 0,
            "scalar_strip": 0,
        }

        class HostileCloseEventList(list):
            def __getitem__(self, _index: object) -> Any:
                close_pair_hook_calls["outer_getitem"] += 1
                raise RuntimeError("hostile close-event list getitem")

            def __iter__(self) -> Iterator[Any]:
                close_pair_hook_calls["outer_iteration"] += 1
                raise RuntimeError("hostile close-event list iteration")

            def __len__(self) -> int:
                close_pair_hook_calls["outer_length"] += 1
                raise RuntimeError("hostile close-event list length")

        class HostileCloseEvent(dict):
            def get(self, *_args: Any, **_kwargs: Any) -> Any:
                close_pair_hook_calls["mapping_get"] += 1
                raise RuntimeError("hostile close-event mapping get")

            def items(self) -> Any:
                close_pair_hook_calls["mapping_items"] += 1
                raise RuntimeError("hostile close-event mapping items")

            def __iter__(self) -> Iterator[Any]:
                close_pair_hook_calls["mapping_iteration"] += 1
                raise RuntimeError("hostile close-event mapping iteration")

        class HostileCloseEventString(str):
            def __eq__(self, _other: object) -> bool:
                close_pair_hook_calls["scalar_equality"] += 1
                raise RuntimeError("hostile close-event scalar equality")

            def strip(self, *_args: Any, **_kwargs: Any) -> str:
                close_pair_hook_calls["scalar_strip"] += 1
                raise RuntimeError("hostile close-event scalar strip")

        close_pair_arguments = {
            "issue_id": "fixture-anchor",
            "show_timestamp": v2_parse_timestamp(
                "2026-01-02T00:00:00.002000+00:00",
                label="hostile close-pair fixture",
            ),
            "close_reason": "Fixture anchor completed.",
            "max_skew_ms": 1_000,
        }
        close_pair_outer_error = expect_error(
            EvidenceFailed,
            lambda: v2_current_close_pairs(
                HostileCloseEventList([]),
                **close_pair_arguments,
            ),
            contains="not an exact list",
        )
        close_pair_mapping_error = expect_error(
            EvidenceFailed,
            lambda: v2_current_close_pairs(
                [HostileCloseEvent({"event_type": "closed"})],
                **close_pair_arguments,
            ),
            contains="not an exact object",
        )
        close_pair_scalar_error = expect_error(
            EvidenceFailed,
            lambda: v2_current_close_pairs(
                [{
                    "id": 2,
                    "event_type": HostileCloseEventString("closed"),
                    "actor": "fixture-closer",
                    "timestamp": "2026-01-02T00:00:00.002000+00:00",
                    "comment": "Fixture anchor completed.",
                }],
                **close_pair_arguments,
            ),
            contains="non-exact scalar",
        )
        checks.check(
            "known-closer-exact",
            row["closer_state"] == "KNOWN"
            and row["close_actor"] == "fixture-closer"
            and row["close_actor_source"] == "br.audit.log.closed.actor"
            and isinstance(row["audit_event_root"], str)
            and re.fullmatch(
                r"sha256-v1:[0-9a-f]{64}",
                row["audit_event_root"],
            )
            is not None
            and close_pair_outer_error.terminal == "EvidenceFailed"
            and close_pair_mapping_error.terminal == "EvidenceFailed"
            and close_pair_scalar_error.terminal == "EvidenceFailed"
            and all(value == 0 for value in close_pair_hook_calls.values()),
            expected={
                "closer_state": "KNOWN",
                "close_actor": "fixture-closer",
                "hostile_terminals": [
                    "EvidenceFailed",
                    "EvidenceFailed",
                    "EvidenceFailed",
                ],
                "hostile_hook_calls": 0,
            },
            observed={
                "closer_state": row["closer_state"],
                "close_actor": row["close_actor"],
                "audit_event_root": row["audit_event_root"],
                "hostile_terminals": [
                    close_pair_outer_error.terminal,
                    close_pair_mapping_error.terminal,
                    close_pair_scalar_error.terminal,
                ],
                "hostile_hook_calls": close_pair_hook_calls,
            },
        )
        expected_comment = {
            "event_id": 3,
            "actor": "fixture-commenter",
            "timestamp": "2026-01-02T00:00:00.003000Z",
            "comment": "Fixture retained canonical comment.",
            "comment_root": text_root(
                "Fixture retained canonical comment."
            ),
        }
        expected_tracker_comment = {
            "id": 10,
            "issue_id": "fixture-anchor",
            "author": "fixture-tracker-commenter",
            "text": "Fixture retained tracker comment.",
            "created_at": "2026-01-01T12:00:00+00:00",
        }
        checks.check(
            "canonical-commented-event-retained",
            row["comments"] == [expected_comment]
            and row["tracker_comments"] == [expected_tracker_comment],
            expected={
                "audit_comment": expected_comment,
                "tracker_comment": expected_tracker_comment,
                "streams_equated": False,
            },
            observed={
                "audit_comment": (
                    row["comments"][0] if row["comments"] else None
                ),
                "tracker_comment": (
                    row["tracker_comments"][0]
                    if row["tracker_comments"]
                    else None
                ),
                "streams_equated": False,
            },
        )

        def malformed_authority_event_error(
            mutation: Callable[[list[dict[str, Any]]], None],
        ) -> TerminalObservation:
            events = strict_json_loads(
                canonical_bytes(audit["documents"][0]["events"]),
                label="history authority-event mutation seed",
                require_canonical=True,
            )
            mutation(events)
            return expect_error(
                EvidenceFailed,
                lambda: v2_normalize_audit_document(
                    {"issue_id": issues[0]["id"], "events": events},
                    issue_id=issues[0]["id"],
                ),
                contains="malformed released",
            )

        missing_old_value_error = malformed_authority_event_error(
            lambda events: next(
                event
                for event in events
                if event["event_type"] == "status_changed"
            ).pop("old_value")
        )
        checks.check(
            "close-transition-missing-old-value-refused",
            missing_old_value_error.terminal == "EvidenceFailed",
            expected="EvidenceFailed",
            observed=missing_old_value_error.terminal,
        )
        closed_to_closed_error = malformed_authority_event_error(
            lambda events: next(
                event
                for event in events
                if event["event_type"] == "status_changed"
            ).__setitem__("old_value", "closed")
        )
        checks.check(
            "close-transition-closed-to-closed-refused",
            closed_to_closed_error.terminal == "EvidenceFailed",
            expected="EvidenceFailed",
            observed=closed_to_closed_error.terminal,
        )
        close_shape_error = malformed_authority_event_error(
            lambda events: next(
                event
                for event in events
                if event["event_type"] == "closed"
            ).__setitem__("new_value", "closed")
        )
        checks.check(
            "close-event-unexpected-transition-field-refused",
            close_shape_error.terminal == "EvidenceFailed",
            expected="EvidenceFailed",
            observed=close_shape_error.terminal,
        )

        def history_audit_with_events(
            events: Sequence[Mapping[str, Any]],
        ) -> dict[str, Any]:
            raw_document = {
                "issue_id": issues[0]["id"],
                "events": [dict(event) for event in events],
            }
            normalized_document = v2_normalize_audit_document(
                raw_document,
                issue_id=issues[0]["id"],
            )
            stdout_bytes = canonical_bytes(raw_document)
            candidate = strict_json_loads(
                canonical_bytes(audit),
                label="history audit-event fixture seed",
                require_canonical=True,
            )
            candidate.pop("semantic_root", None)
            candidate["documents"] = [normalized_document]
            for receipt in candidate["command_receipts"]:
                receipt["stdout_byte_length"] = len(stdout_bytes)
                receipt["stdout_root"] = (
                    "sha256-v1:" + hashlib.sha256(stdout_bytes).hexdigest()
                )
                receipt["normalized_document_root"] = normalized_document[
                    "semantic_root"
                ]
            return v2_rooted(candidate)

        reclosed_events = [
            {
                "id": 6,
                "event_type": "commented",
                "actor": "fixture-commenter",
                "timestamp": "2026-01-02T00:00:00.002000+00:00",
                "comment": "Fixture retained canonical comment.",
            },
            {
                "id": 5,
                "event_type": "closed",
                "actor": "fixture-closer",
                "timestamp": "2026-01-02T00:00:00.001000+00:00",
                "comment": issues[0]["close_reason"],
            },
            {
                "id": 4,
                "event_type": "status_changed",
                "actor": "fixture-closer",
                "timestamp": "2026-01-02T00:00:00+00:00",
                "old_value": "open",
                "new_value": "closed",
            },
            {
                "id": 3,
                "event_type": "reopened",
                "actor": "fixture-reopener",
                "timestamp": "2026-01-01T12:00:00+00:00",
                "comment": "Reopened for additional review.",
            },
            {
                "id": 2,
                "event_type": "closed",
                "actor": "fixture-first-closer",
                "timestamp": "2026-01-01T11:00:00.001000+00:00",
                "comment": "Earlier close reason.",
            },
            {
                "id": 1,
                "event_type": "status_changed",
                "actor": "fixture-first-closer",
                "timestamp": "2026-01-01T11:00:00+00:00",
                "old_value": "open",
                "new_value": "closed",
            },
        ]
        reclosed_audit = history_audit_with_events(reclosed_events)
        reclosed_contract = dict(contract)
        reclosed_contract["legacy_coverage_anchor_status_event_id"] = 4
        reclosed_contract["legacy_coverage_anchor_close_event_id"] = 5
        reclosed_history = v2_build_history(
            source_root=source_root,
            inventory=inventory,
            authority=authority,
            all_issues=issues,
            audit_capture=reclosed_audit,
            history_contract=reclosed_contract,
        )
        v2_validate_history_projection(
            reclosed_history,
            source_root=source_root,
            inventory=inventory,
            authority=authority,
            all_issues=issues,
            audit_capture=reclosed_audit,
            history_contract=reclosed_contract,
        )
        reclosed_row = reclosed_history["rows"][0]
        current_close_event = reclosed_audit["documents"][0]["events"][1]
        checks.check(
            "close-reopen-reclose-selects-current-pair",
            reclosed_row["closer_state"] == "KNOWN"
            and reclosed_row["close_actor"] == "fixture-closer"
            and reclosed_row["audit_event_root"]
            == semantic_root(current_close_event),
            expected={
                "closer_state": "KNOWN",
                "close_actor": "fixture-closer",
                "audit_event_root": semantic_root(current_close_event),
            },
            observed={
                "closer_state": reclosed_row["closer_state"],
                "close_actor": reclosed_row["close_actor"],
                "audit_event_root": reclosed_row["audit_event_root"],
            },
        )

        ambiguous_events = [
            {
                "id": 5,
                "event_type": "closed",
                "actor": "fixture-closer",
                "timestamp": "2026-01-02T00:00:00.002000+00:00",
                "comment": issues[0]["close_reason"],
            },
            {
                "id": 4,
                "event_type": "status_changed",
                "actor": "fixture-closer",
                "timestamp": "2026-01-02T00:00:00.001000+00:00",
                "old_value": "open",
                "new_value": "closed",
            },
            {
                "id": 3,
                "event_type": "status_changed",
                "actor": "fixture-closer",
                "timestamp": "2026-01-02T00:00:00.000500+00:00",
                "old_value": "open",
                "new_value": "closed",
            },
        ]
        ambiguous_audit = history_audit_with_events(ambiguous_events)
        ambiguous_contract = dict(contract)
        ambiguous_contract["legacy_coverage_anchor_status_event_id"] = 4
        ambiguous_contract["legacy_coverage_anchor_close_event_id"] = 5
        checks.refuses(
            "ambiguous-current-close-pair-refused",
            EvidenceFailed,
            lambda: v2_build_history(
                source_root=source_root,
                inventory=inventory,
                authority=authority,
                all_issues=issues,
                audit_capture=ambiguous_audit,
                history_contract=ambiguous_contract,
            ),
            contains="close audit pair conflicts",
        )

        def audit_with_pair_timestamps(
            *,
            close_timestamp: str,
            transition_timestamp: str,
        ) -> dict[str, Any]:
            candidate = strict_json_loads(
                canonical_bytes(audit),
                label="history skew-boundary audit seed",
                require_canonical=True,
            )
            candidate.pop("semantic_root", None)
            document = dict(candidate["documents"][0])
            document.pop("semantic_root", None)
            events = [dict(event) for event in document["events"]]
            for event in events:
                if event["event_type"] == "closed":
                    event["timestamp"] = close_timestamp
                elif (
                    event["event_type"] == "status_changed"
                    and event.get("new_value") == "closed"
                ):
                    event["timestamp"] = transition_timestamp
            document["events"] = events
            candidate["documents"] = [v2_rooted(document)]
            return v2_rooted(candidate)

        exact_contract = dict(contract)
        exact_contract["known_pair_max_skew_ms"] = 2
        exact_history = v2_build_history(
            source_root=source_root,
            inventory=inventory,
            authority=authority,
            all_issues=issues,
            audit_capture=audit,
            history_contract=exact_contract,
        )
        exact_close_event = next(
            event
            for event in audit["documents"][0]["events"]
            if event["event_type"] == "closed"
        )
        exact_skew_us, exact_cap_us = v2_history_skew_microseconds(
            show_timestamp=v2_parse_timestamp(
                issues[0]["closed_at"],
                label="history exact-cap source",
            ),
            close_timestamp=v2_parse_timestamp(
                exact_close_event["timestamp"],
                label="history exact-cap close",
            ),
            max_skew_ms=exact_contract["known_pair_max_skew_ms"],
        )
        checks.check(
            "known-pair-exact-millisecond-cap-admitted",
            exact_history["rows"][0]["closer_state"] == "KNOWN"
            and exact_contract["known_pair_max_skew_ms"] == 2
            and exact_skew_us == exact_cap_us == 2_000,
            expected={
                "retained_contract_ms": 2,
                "exact_skew_us": 2_000,
                "exact_cap_us": 2_000,
            },
            observed={
                "retained_contract_ms": exact_contract[
                    "known_pair_max_skew_ms"
                ],
                "exact_skew_us": exact_skew_us,
                "exact_cap_us": exact_cap_us,
            },
        )
        cap_plus_one_audit = audit_with_pair_timestamps(
            close_timestamp="2026-01-02T00:00:00.002001+00:00",
            transition_timestamp="2026-01-02T00:00:00.001000+00:00",
        )
        checks.refuses(
            "known-pair-cap-plus-one-microsecond-builder-refused",
            EvidenceFailed,
            lambda: v2_build_history(
                source_root=source_root,
                inventory=inventory,
                authority=authority,
                all_issues=issues,
                audit_capture=cap_plus_one_audit,
                history_contract=exact_contract,
            ),
            contains="close audit pair conflicts",
        )
        cap_plus_one_history = strict_json_loads(
            canonical_bytes(exact_history),
            label="history cap-plus-one validator seed",
            require_canonical=True,
        )
        cap_plus_one_history.pop("semantic_root", None)
        cap_plus_one_history["audit_capture_root"] = cap_plus_one_audit[
            "semantic_root"
        ]
        cap_plus_one_row = dict(cap_plus_one_history["rows"][0])
        cap_plus_one_row.pop("semantic_root", None)
        cap_plus_one_document = cap_plus_one_audit["documents"][0]
        cap_plus_one_close = next(
            event
            for event in cap_plus_one_document["events"]
            if event["event_type"] == "closed"
        )
        cap_plus_one_row["audit_stream_root"] = cap_plus_one_document[
            "semantic_root"
        ]
        cap_plus_one_row["source_roots"][2] = cap_plus_one_document[
            "semantic_root"
        ]
        cap_plus_one_row["audit_event_root"] = semantic_root(
            cap_plus_one_close
        )
        cap_plus_one_history["rows"] = [v2_rooted(cap_plus_one_row)]
        cap_plus_one_history = v2_rooted(cap_plus_one_history)
        checks.refuses(
            "known-pair-cap-plus-one-microsecond-validator-refused",
            EvidenceFailed,
            lambda: v2_validate_history_projection(
                cap_plus_one_history,
                source_root=source_root,
                inventory=inventory,
                authority=authority,
                all_issues=issues,
                audit_capture=cap_plus_one_audit,
                history_contract=exact_contract,
            ),
            contains="known-closer audit binding differs",
        )
        negative_skew_audit = audit_with_pair_timestamps(
            close_timestamp="2026-01-01T23:59:59.999999+00:00",
            transition_timestamp="2026-01-01T23:59:59.999998+00:00",
        )
        checks.refuses(
            "known-pair-negative-skew-and-order-refused",
            EvidenceFailed,
            lambda: v2_build_history(
                source_root=source_root,
                inventory=inventory,
                authority=authority,
                all_issues=issues,
                audit_capture=negative_skew_audit,
                history_contract=exact_contract,
            ),
            contains="close audit pair conflicts",
        )

        def reroot_history_row(
            mutation: Callable[[dict[str, Any]], None],
        ) -> dict[str, Any]:
            candidate = strict_json_loads(
                canonical_bytes(history),
                label="history row mutation seed",
                require_canonical=True,
            )
            candidate.pop("semantic_root", None)
            candidate_row = dict(candidate["rows"][0])
            candidate_row.pop("semantic_root", None)
            mutation(candidate_row)
            candidate["rows"] = [v2_rooted(candidate_row)]
            return v2_rooted(candidate)

        forged_actor_source = reroot_history_row(
            lambda value: value.__setitem__(
                "close_actor_source",
                "self.reported.model.identity",
            )
        )
        checks.refuses(
            "rerooted-known-closer-source-refused",
            EvidenceFailed,
            lambda: v2_validate_history_projection(
                forged_actor_source,
                source_root=source_root,
                inventory=inventory,
                authority=authority,
                all_issues=issues,
                audit_capture=audit,
                history_contract=contract,
            ),
            contains="known-closer audit binding differs",
        )
        for label, mutation in (
            (
                "actor",
                lambda value: value.__setitem__(
                    "close_actor",
                    "forged-closer",
                ),
            ),
            (
                "audit-event-root",
                lambda value: value.__setitem__(
                    "audit_event_root",
                    semantic_root({"forged": "close event"}),
                ),
            ),
            (
                "close-reason",
                lambda value: (
                    value.__setitem__(
                        "close_reason",
                        "Forged close reason.",
                    ),
                    value.__setitem__(
                        "close_reason_root",
                        text_root("Forged close reason."),
                    ),
                ),
            ),
        ):
            candidate = reroot_history_row(mutation)
            checks.refuses(
                f"rerooted-known-closer-{label}-refused",
                EvidenceFailed,
                lambda candidate=candidate: v2_validate_history_projection(
                    candidate,
                    source_root=source_root,
                    inventory=inventory,
                    authority=authority,
                    all_issues=issues,
                    audit_capture=audit,
                    history_contract=contract,
                ),
                contains="known-closer audit binding differs",
            )
        forged_notes = reroot_history_row(
            lambda value: value.__setitem__(
                "notes",
                value["notes"] + " altered without a matching root",
            )
        )
        checks.refuses(
            "rerooted-history-notes-root-lie-refused",
            EvidenceFailed,
            lambda: v2_validate_history_projection(
                forged_notes,
                source_root=source_root,
                inventory=inventory,
                authority=authority,
                all_issues=issues,
                audit_capture=audit,
                history_contract=contract,
            ),
            contains="scalar or source bindings differ",
        )

        def forge_audit_stream_root(
