            "zero-cell-count-precedes-stale-root",
            EvidenceFailed,
            lambda: v2_validate_zero_sets(
                stale_cell_count,
                source_root=sparse_source_root,
                inventory=sparse_inventory,
                prior_campaign=v2_empty_prior_campaign(),
            ),
            contains=(
                "exact "
                f"{5 * len(V2_RELEASED_KNOWN_STATUSES)}-row array"
            ),
        )

        second_target = v2_synthetic_target(
            101,
            issue_id="zero-cap-second-target",
            priority=3,
            status="blocked",
        )
        two_row_inventory = v2_synthetic_inventory(
            [sparse_inventory["rows"][0], second_target]
        )
        stale_prior = strict_json_loads(
            canonical_bytes(v2_empty_prior_campaign()),
            label="zero-set prior cap mutation seed",
            require_canonical=True,
        )
        stale_prior["rows"] = [{}, {}]
        stale_scope = strict_json_loads(
            canonical_bytes(sparse),
            label="zero-set successor cap mutation seed",
            require_canonical=True,
        )
        stale_scope["scope_successors"] = [{}, {}]
        stale_movements = strict_json_loads(
            canonical_bytes(sparse),
            label="zero-set movement cap mutation seed",
            require_canonical=True,
        )
        stale_movements["movements"] = [{}, {}]
        current_universe_over_cap = [
            sparse_inventory["rows"][0],
            second_target,
        ]
        prior_inventory_rows_cap = V2_INVENTORY_ROWS_CAP
        try:
            globals()["V2_INVENTORY_ROWS_CAP"] = 1
            zero_cap_callbacks = (
                (
                    "zero-inventory-cap-precedes-root",
                    lambda: v2_validate_zero_sets(
                        sparse,
                        source_root=sparse_source_root,
                        inventory=two_row_inventory,
                        prior_campaign=v2_empty_prior_campaign(),
                    ),
                    "inventory rows",
                ),
                (
                    "zero-current-universe-cap-precedes-root",
                    lambda: v2_validate_zero_sets(
                        sparse,
                        source_root=sparse_source_root,
                        inventory=sparse_inventory,
                        prior_campaign=v2_empty_prior_campaign(),
                        current_universe=current_universe_over_cap,
                    ),
                    "current universe rows",
                ),
                (
                    "zero-prior-cap-precedes-root",
                    lambda: v2_validate_zero_sets(
                        sparse,
                        source_root=sparse_source_root,
                        inventory=sparse_inventory,
                        prior_campaign=stale_prior,
                    ),
                    "prior-campaign rows",
                ),
                (
                    "zero-scope-successor-cap-precedes-root",
                    lambda: v2_validate_zero_sets(
                        stale_scope,
                        source_root=sparse_source_root,
                        inventory=sparse_inventory,
                        prior_campaign=v2_empty_prior_campaign(),
                    ),
                    "scope-successor rows",
                ),
                (
                    "zero-movement-cap-precedes-root",
                    lambda: v2_validate_zero_sets(
                        stale_movements,
                        source_root=sparse_source_root,
                        inventory=sparse_inventory,
                        prior_campaign=v2_empty_prior_campaign(),
                    ),
                    "movement rows",
                ),
                (
                    "zero-builder-inventory-cap-before-sorting",
                    lambda: v2_build_zero_sets(
                        source_root=sparse_source_root,
                        inventory=two_row_inventory,
                        prior_campaign=v2_empty_prior_campaign(),
                    ),
                    "inventory rows",
                ),
                (
                    "zero-builder-current-cap-before-copying",
                    lambda: v2_build_zero_sets(
                        source_root=sparse_source_root,
                        inventory=sparse_inventory,
                        prior_campaign=v2_empty_prior_campaign(),
                        current_universe=current_universe_over_cap,
                    ),
                    "current universe rows",
                ),
                (
                    "zero-builder-prior-cap-before-indexing",
                    lambda: v2_build_zero_sets(
                        source_root=sparse_source_root,
                        inventory=sparse_inventory,
                        prior_campaign=stale_prior,
                    ),
                    "prior-campaign rows",
                ),
            )
            for check_id, callback, diagnostic in zero_cap_callbacks:
                checks.refuses(
                    check_id,
                    EvidenceFailed,
                    callback,
                    contains=diagnostic,
                )
        finally:
            globals()["V2_INVENTORY_ROWS_CAP"] = prior_inventory_rows_cap

        stale_byte_cap = strict_json_loads(
            canonical_bytes(sparse),
            label="zero-set byte cap mutation seed",
            require_canonical=True,
        )
        stale_byte_cap["no_claim"] += " stale"
        prior_run_artifact_cap = RUN_ARTIFACT_CAP
        try:
            globals()["RUN_ARTIFACT_CAP"] = 1
            checks.refuses(
                "zero-byte-cap-precedes-stale-root",
                EvidenceFailed,
                lambda: v2_validate_zero_sets(
                    stale_byte_cap,
                    source_root=sparse_source_root,
                    inventory=sparse_inventory,
                    prior_campaign=v2_empty_prior_campaign(),
                ),
                contains="aggregate byte cap",
            )
            checks.refuses(
                "zero-builder-byte-cap-before-rooting",
                EvidenceFailed,
                lambda: v2_build_zero_sets(
                    source_root=sparse_source_root,
                    inventory=sparse_inventory,
                    prior_campaign=v2_empty_prior_campaign(),
                ),
                contains="aggregate byte cap",
            )
        finally:
            globals()["RUN_ARTIFACT_CAP"] = prior_run_artifact_cap
    elif slug in {
        "movement-cross-lane",
        "movement-live-to-history",
        "movement-history-to-live",
    }:
        transitions = {
            "movement-cross-lane": ("open", 1, "blocked", 2, "MOVED_TO_LANE"),
            "movement-live-to-history": (
                "open",
                1,
                "closed",
                1,
                "MOVED_TO_HISTORY",
            ),
            "movement-history-to-live": (
                "closed",
                1,
                "open",
                1,
                "MOVED_FROM_HISTORY",
            ),
        }
        before_status, before_priority, after_status, after_priority, expected_class = (
            transitions[slug]
        )
        current_target = v2_synthetic_target(
            0,
            status=after_status,
            priority=after_priority,
            missing_sections=(
                ()
                if slug == "movement-live-to-history"
                else ("## Acceptance Criteria",)
            ),
        )
        current_universe = [current_target]
        inventory = v2_synthetic_inventory(
            []
            if slug == "movement-live-to-history"
            else [current_target]
        )
        current_id = current_target["id"]
        movement_finding_ids = (
            []
            if slug == "movement-live-to-history"
            else [current_id]
        )
        prior = v2_rooted(
            {
                "state": "PROVIDED",
                "bundle_path": "target/v2-fixture/prior-run",
                "terminal_root": semantic_root({"terminal": "prior"}),
                "inventory_root": semantic_root({"inventory": "prior"}),
                "campaign_epoch_root": semantic_root(
                    {"campaign": "prior"}
                ),
                "rows": [
                    {
                        "id": current_id,
                        "status": before_status,
                        "priority": before_priority,
                        "target_root": semantic_root({"before": current_id}),
                        "destination": (
                            "history-v2.json"
                            if before_status == "closed"
                            else "review-plan-v2.json"
                        ),
                    }
                ],
                "no_claim": V2_PRIOR_CAMPAIGN_PROVIDED_NO_CLAIM,
            }
        )
        zero = v2_build_zero_sets(
            source_root=semantic_root({"fixture": slug}),
            inventory=inventory,
            prior_campaign=prior,
            current_universe=current_universe,
            current_finding_ids=movement_finding_ids,
        )
        movement = zero["movements"][0]
        checks.check(
            "movement-class-lineage",
            movement["class"] == expected_class
            and movement["successor_lineage_root"].startswith("sha256-v1:")
            and movement["current_universe_root"]
            == zero["current_universe_root"]
            and movement["destination_root_kind"]
            == (
                "FULL_UNIVERSE_CLEAN_SUCCESSOR"
                if slug == "movement-live-to-history"
                else "INVENTORY_TARGET"
            )
            and zero["current_universe_count"] == 1
            and len(zero["scope_successors"])
            == (1 if slug == "movement-live-to-history" else 0),
            expected={
                "class": expected_class,
                "destination_root_kind": (
                    "FULL_UNIVERSE_CLEAN_SUCCESSOR"
                    if slug == "movement-live-to-history"
                    else "INVENTORY_TARGET"
                ),
                "universe_count": 1,
            },
            observed={
                "movement": movement,
                "universe_count": zero["current_universe_count"],
                "scope_successors": zero["scope_successors"],
            },
        )
        malformed = json.loads(canonical_bytes(zero))
        malformed["movements"][0]["class"] = "MOVED_TO_LANE"
        if expected_class == "MOVED_TO_LANE":
            malformed["movements"][0]["class"] = "MOVED_TO_HISTORY"
        malformed["movements"][0] = v2_rooted(
            malformed["movements"][0]
        )
        malformed = v2_rooted(malformed)
        checks.refuses(
            "rerooted-movement-class-refused",
            EvidenceFailed,
            lambda: v2_validate_zero_sets(
                malformed,
                source_root=zero["source_root"],
                inventory=inventory,
                prior_campaign=prior,
                current_universe=current_universe,
                current_finding_ids=movement_finding_ids,
            ),
            contains="independently reconstructed",
            projection=lambda: malformed,
            projection_label="MOVEMENT_ARTIFACT",
        )
        for field, replacement in (
            ("destination_root_kind", "INVENTORY_TARGET"),
            (
                "current_universe_root",
                semantic_root({"forged": "universe"}),
            ),
        ):
            if movement[field] == replacement:
                replacement = (
                    "FULL_UNIVERSE_CLEAN_SUCCESSOR"
                    if field == "destination_root_kind"
                    else semantic_root({"forged": "other-universe"})
                )
            tampered = json.loads(canonical_bytes(zero))
            tampered["movements"][0][field] = replacement
            tampered["movements"][0] = v2_rooted(
                tampered["movements"][0]
            )
            tampered = v2_rooted(tampered)
            checks.refuses(
                f"rerooted-movement-{field}-refused",
                EvidenceFailed,
                lambda tampered=tampered: v2_validate_zero_sets(
                    tampered,
                    source_root=zero["source_root"],
                    inventory=inventory,
                    prior_campaign=prior,
                    current_universe=current_universe,
                    current_finding_ids=movement_finding_ids,
                ),
                contains="independently reconstructed",
            )
        if slug == "movement-live-to-history":
            checks.refuses(
                "prior-target-absent-current-universe-refused",
                InputRefused,
                lambda: v2_build_zero_sets(
                    source_root=zero["source_root"],
                    inventory=inventory,
                    prior_campaign=prior,
                    current_universe=[],
                    current_finding_ids=[],
                ),
                contains="absent from the current source universe",
            )
            nonclosed_successor = dict(current_target)
            nonclosed_successor.pop("semantic_root", None)
            nonclosed_successor["status"] = "open"
            nonclosed_successor = v2_rooted(nonclosed_successor)
            checks.refuses(
                "prior-target-nonclosed-out-of-scope-refused",
                InputRefused,
                lambda: v2_build_zero_sets(
                    source_root=zero["source_root"],
                    inventory=inventory,
                    prior_campaign=prior,
                    current_universe=[nonclosed_successor],
                    current_finding_ids=[],
                ),
                contains="without a clean closed successor",
            )
            filtered_finding_target = v2_synthetic_target(
                0,
                status="closed",
                priority=3,
                missing_sections=("## Acceptance Criteria",),
            )
            filtered_zero = v2_build_zero_sets(
                source_root=zero["source_root"],
                inventory=v2_synthetic_inventory([]),
                prior_campaign=prior,
                current_universe=[filtered_finding_target],
                current_finding_ids=[current_id],
            )
            filtered_successor = filtered_zero["scope_successors"][0]
            filtered_movement = filtered_zero["movements"][0]
            checks.check(
                "filtered-closed-live-finding-not-clean-successor",
                filtered_successor["finding_state"] == "CURRENT_FINDING"
                and filtered_successor["reason"]
                == "FILTERED_CURRENT_FINDING"
                and filtered_successor["reason"]
                != "CLOSED_WITHOUT_CURRENT_FINDING",
                expected={
                    "finding_state": "CURRENT_FINDING",
                    "reason": "FILTERED_CURRENT_FINDING",
                },
                observed=filtered_successor,
            )
            checks.refuses(
                "closed-without-current-finding-requires-unfiltered-absence",
                EvidenceFailed,
                lambda: v2_validate_zero_sets(
                    filtered_zero,
                    source_root=zero["source_root"],
                    inventory=v2_synthetic_inventory([]),
                    prior_campaign=prior,
                    current_universe=[filtered_finding_target],
                    current_finding_ids=[],
                ),
                contains="finding binding differs",
            )
            filtered_target_id = "fixture-filtered-current-finding"
            filtered_anchor_id = "fixture-selected-filter-anchor"
            _, _, filter_snapshot, _ = v2_authentic_projection_fixture(
                [
                    fixture_issue(
                        issue_id=filtered_target_id,
                        title="Filtered blocked current finding",
                        status="blocked",
                        priority=3,
                    ),
                    fixture_issue(
                        issue_id=filtered_anchor_id,
                        title="Selected open filter anchor",
                        status="open",
                        priority=0,
                    ),
                ],
                missing_by_id={
                    filtered_target_id: ("## Acceptance Criteria",),
                    filtered_anchor_id: (),
                },
            )
            filter_campaign_root, _ = v2_campaign_epoch(filter_snapshot)
            filter_finding_ids = v2_snapshot_current_finding_ids(
                filter_snapshot
            )
            filtered_prior = v2_rooted(
                {
                    "state": "PROVIDED",
                    "bundle_path": "target/v2-fixture/filtered-prior-run",
                    "terminal_root": semantic_root(
                        {"terminal": "filtered-prior"}
                    ),
                    "inventory_root": semantic_root(
                        {"inventory": "filtered-prior"}
                    ),
                    "campaign_epoch_root": semantic_root(
                        {"campaign": "filtered-prior"}
                    ),
                    "rows": [
                        {
                            "id": filtered_target_id,
                            "status": "open",
                            "priority": 2,
                            "target_root": semantic_root(
                                {"before": filtered_target_id}
                            ),
                            "destination": "review-plan-v2.json",
                        }
                    ],
                    "no_claim": V2_PRIOR_CAMPAIGN_PROVIDED_NO_CLAIM,
                }
            )

            def filtered_projection(
                *,
                priorities: set[str] | None = None,
                statuses: set[str] | None = None,
                targets: set[str] | None = None,
            ) -> tuple[dict[str, Any], dict[str, Any]]:
                filtered_inventory = v2_build_inventory(
                    filter_snapshot,
                    campaign_epoch_root=filter_campaign_root,
                    priority_filter=priorities,
                    status_filter=statuses,
                    target_filter=targets,
                )
                filtered_projection_zero = v2_build_zero_sets(
                    source_root=semantic_root(
                        {
                            "fixture": "genuine-filtered-current-finding",
                            "priorities": sorted(priorities or ()),
                            "statuses": sorted(statuses or ()),
                            "targets": sorted(targets or ()),
                        }
                    ),
                    inventory=filtered_inventory,
                    prior_campaign=filtered_prior,
                    current_universe=filter_snapshot.all_issues,
                    current_finding_ids=filter_finding_ids,
                )
                return filtered_inventory, filtered_projection_zero

            priority_inventory, priority_zero = filtered_projection(
                priorities={"P0"}
            )
            status_inventory, status_zero = filtered_projection(
                statuses={"open"}
            )
            target_inventory, target_zero = filtered_projection(
                targets={filtered_anchor_id}
            )
            checks.check(
                "priority-filtered-current-finding-keeps-typed-destination",
                priority_inventory["filters"]["priorities"] == ["P0"]
                and [row["id"] for row in priority_inventory["rows"]]
                == [filtered_anchor_id]
                and priority_zero["scope_successors"][0]["status"]
                == "blocked"
                and priority_zero["scope_successors"][0]["finding_state"]
                == "CURRENT_FINDING"
                and priority_zero["movements"][0]["destination_root_kind"]
                == "FULL_UNIVERSE_FILTERED_FINDING",
                expected={
                    "filter": ["P0"],
                    "selected_ids": [filtered_anchor_id],
                    "filtered_status": "blocked",
                    "destination_root_kind": (
                        "FULL_UNIVERSE_FILTERED_FINDING"
                    ),
                },
                observed={
                    "filters": priority_inventory["filters"],
                    "selected_ids": [
                        row["id"] for row in priority_inventory["rows"]
                    ],
                    "successors": priority_zero["scope_successors"],
                    "movements": priority_zero["movements"],
                },
            )
            checks.check(
                "status-filtered-current-finding-keeps-typed-destination",
                status_inventory["filters"]["statuses"] == ["open"]
                and [row["id"] for row in status_inventory["rows"]]
                == [filtered_anchor_id]
                and status_zero["scope_successors"][0]["status"]
                == "blocked"
                and status_zero["scope_successors"][0]["reason"]
                == "FILTERED_CURRENT_FINDING"
                and status_zero["movements"][0]["class"]
                == "MOVED_TO_LANE",
                expected={
                    "filter": ["open"],
                    "selected_ids": [filtered_anchor_id],
                    "filtered_status": "blocked",
                    "reason": "FILTERED_CURRENT_FINDING",
                    "movement_class": "MOVED_TO_LANE",
                },
                observed={
                    "filters": status_inventory["filters"],
                    "selected_ids": [
                        row["id"] for row in status_inventory["rows"]
                    ],
                    "successors": status_zero["scope_successors"],
                    "movements": status_zero["movements"],
                },
            )
            checks.check(
                "target-filtered-current-finding-keeps-typed-destination",
                target_inventory["filters"]["targets"]
                == [filtered_anchor_id]
                and [row["id"] for row in target_inventory["rows"]]
                == [filtered_anchor_id]
                and target_zero["scope_successors"][0]["finding_state"]
                == "CURRENT_FINDING"
                and target_zero["movements"][0][
                    "destination_finding_state"
                ]
                == "CURRENT_FINDING"
                and target_zero["movements"][0][
                    "current_finding_issue_ids_root"
                ]
                == target_zero["current_finding_issue_ids_root"],
                expected={
                    "filter": [filtered_anchor_id],
                    "selected_ids": [filtered_anchor_id],
                    "finding_state": "CURRENT_FINDING",
                    "lineage_finding_root_bound": True,
                },
                observed={
                    "filters": target_inventory["filters"],
                    "selected_ids": [
                        row["id"] for row in target_inventory["rows"]
                    ],
                    "successors": target_zero["scope_successors"],
                    "movements": target_zero["movements"],
                },
            )
    else:
        raise EvidenceFailed(f"no history executor for {slug}")
    return checks.finish(parameters)


def v2_synthetic_payloads(
    manifest: Mapping[str, Any],
    *,
    oversize: bool = False,
) -> tuple[dict[str, bytes], tuple[Any, ...]]:
    payloads, _, components = v2_replayable_fixture_bundle(
        manifest,
        subject_mode="review-plan",
        oversize=oversize,
        artifact_root="target/v2-fixture",
        artifact_dir="run",
    )
    return payloads, components


V2_FAULT_FIXTURE_SEAL_SCHEMA = (
    "frankensim.beads-template-hygiene.fault-fixture-seal.v2"
)
V2_FAULT_FIXTURE_SEAL_NAME = ".fault-fixture-seal-v2.json"
V2_FAULT_FIXTURE_SEAL_FIELDS = frozenset(
    {
        "schema",
        "manifest_content_identity",
        "harness_contract_identity",
        "label",
        "tree_projection",
        "tree_root",
        "no_claim",
        "semantic_root",
    }
)


def v2_fault_fixture_tree_projection(base: Path) -> list[dict[str, Any]]:
    try:
        base_stat = os.lstat(base)
    except OSError as error:
        raise EvidenceFailed(
            "retained fault fixture base cannot be inspected"
        ) from error
    if not stat.S_ISDIR(base_stat.st_mode):
        raise EvidenceFailed(
            "retained fault fixture base is not a directory"
        )
    projection: list[dict[str, Any]] = []
    seen_identities: dict[tuple[int, int], str] = {}
    directory_count = 0
    nondirectory_count = 0
    enumerated_path_bytes = 0
    total_member_cap = (
        V2_BUNDLE_FILES_CAP + V2_BUNDLE_DIRECTORIES_CAP
    )
    pending = [base]
    while pending:
        directory = pending.pop()
        try:
            entries = []
            with os.scandir(directory) as iterator:
                for entry in iterator:
                    entries.append(entry)
                    seal_allowance = 1 if directory == base else 0
                    if (
                        len(projection) + len(entries)
                        > total_member_cap + seal_allowance
                    ):
                        raise EvidenceFailed(
                            "retained fault fixture enumeration exceeds "
                            "the aggregate member cap"
                        )
            entries.sort(key=lambda entry: entry.name)
        except HarnessError:
            raise
        except OSError as error:
            raise EvidenceFailed(
                "retained fault fixture directory cannot be enumerated"
            ) from error
        for entry in entries:
            path = Path(entry.path)
            relative = path.relative_to(base).as_posix()
            if relative == V2_FAULT_FIXTURE_SEAL_NAME:
                continue
            try:
                relative = v2_safe_member(
                    relative,
                    label="retained fault fixture member",
                )
            except InputRefused as error:
                raise EvidenceFailed(
                    "retained fault fixture member path is unsafe"
                ) from error
            relative_bytes = len(relative.encode("utf-8"))
            enumerated_path_bytes += relative_bytes
            v2_validate_bundle_enumeration_budget(
                file_count=nondirectory_count,
                directory_count=directory_count,
                path_bytes=enumerated_path_bytes,
            )
            try:
                value = os.lstat(path)
            except OSError as error:
                raise EvidenceFailed(
                    "retained fault fixture member cannot be inspected"
                ) from error
            if stat.S_ISDIR(value.st_mode):
                directory_count += 1
                v2_validate_bundle_enumeration_budget(
                    file_count=nondirectory_count,
                    directory_count=directory_count,
                    path_bytes=enumerated_path_bytes,
                )
                projection.append({"path": relative, "kind": "directory"})
                pending.append(path)
                continue
            if stat.S_ISLNK(value.st_mode):
                nondirectory_count += 1
                v2_validate_bundle_enumeration_budget(
                    file_count=nondirectory_count,
                    directory_count=directory_count,
                    path_bytes=enumerated_path_bytes,
                )
                try:
                    target = os.readlink(path)
                except OSError as error:
                    raise EvidenceFailed(
                        "retained fault fixture symlink cannot be read"
                    ) from error
                target_path = PurePosixPath(target)
                raw_target_parts = target.split("/")
                if (
                    target_path.is_absolute()
                    or ".." in target_path.parts
                    or any(
                        part in {"", ".", ".."}
                        for part in raw_target_parts
                    )
                    or len(raw_target_parts) > CAPS["path_depth"]
                    or any(
                        len(part.encode("utf-8"))
                        > CAPS["path_component_bytes"]
                        for part in raw_target_parts
                    )
                    or len(target.encode("utf-8"))
                    > CAPS["relative_path_bytes"]
                ):
                    raise EvidenceFailed(
                        "retained fault fixture symlink target is unsafe"
                    )
                projection.append(
                    {
                        "path": relative,
                        "kind": "symlink",
                        "target": target,
                    }
                )
                continue
            if not stat.S_ISREG(value.st_mode) or value.st_nlink != 1:
                raise EvidenceFailed(
                    "retained fault fixture contains an unsafe member kind"
                )
            nondirectory_count += 1
            v2_validate_bundle_enumeration_budget(
                file_count=nondirectory_count,
                directory_count=directory_count,
                path_bytes=enumerated_path_bytes,
            )
            identity = (int(value.st_dev), int(value.st_ino))
            if identity in seen_identities:
                raise EvidenceFailed(
                    "retained fault fixture contains an inode alias"
                )
            seen_identities[identity] = relative
            if value.st_size > RUN_ARTIFACT_CAP + 1:
                raise EvidenceFailed(
                    "retained fault fixture file exceeds the fault cap"
                )
            flags = os.O_RDONLY | os.O_CLOEXEC
            flags |= os.O_NOFOLLOW
            descriptor_slot: list[int | None] = [None]
            file_read_succeeded = False
            try:
                try:
                    list.__setitem__(descriptor_slot, 0, os.open(path, flags))
                except OSError as error:
                    raise EvidenceFailed(
                        "retained fault fixture file cannot be opened safely"
                    ) from error
                descriptor = list.__getitem__(descriptor_slot, 0)
                if descriptor is None:
                    raise EvidenceFailed(
                        "retained fault fixture file ownership was lost"
                    )
                digest = hashlib.sha256()
                total = 0
                before = os.fstat(descriptor)
                while True:
                    chunk = os.read(descriptor, 1024 * 1024)
                    if not chunk:
                        break
                    total += len(chunk)
                    if total > RUN_ARTIFACT_CAP + 1:
                        raise EvidenceFailed(
                            "retained fault fixture file grew beyond its cap"
                        )
                    digest.update(chunk)
                after = os.fstat(descriptor)
                file_read_succeeded = True
            finally:
                v2_close_owned_descriptor_slots((
                    (
                        descriptor_slot,
                        EvidenceFailed(
                            "retained fault fixture file close failed"
                        ),
                    ),
                ), surface_failure=file_read_succeeded)
            if (
                before.st_dev != value.st_dev
                or before.st_ino != value.st_ino
                or before.st_nlink != 1
                or total != before.st_size
                or before.st_size != after.st_size
                or before.st_mtime_ns != after.st_mtime_ns
                or before.st_ctime_ns != after.st_ctime_ns
            ):
                raise EvidenceFailed(
                    "retained fault fixture file changed during verification"
                )
            projection.append(
                {
                    "path": relative,
                    "kind": "file",
                    "byte_length": total,
                    "content_root": "sha256-v1:" + digest.hexdigest(),
                }
            )
    projection.sort(key=lambda row: (row["path"], row["kind"]))
    return projection


def v2_fault_fixture_seal_path(
    artifact_root: str,
    fixture_base: str,
) -> Path:
    return (
        resolve_run_dir(
            artifact_root,
            fixture_base,
            label="retained fault fixture",
            must_exist=True,
        )
        / V2_FAULT_FIXTURE_SEAL_NAME
    )


def v2_parse_fault_fixture_seal(payload: bytes) -> Any:
    try:
        return strict_json_loads(
            payload,
            label="retained fault fixture seal",
            require_canonical=True,
        )
    except HarnessError as error:
        raise EvidenceFailed(
            "retained fault fixture seal is malformed or noncanonical; "
            "manual recovery is required"
        ) from error


def v2_verify_fault_fixture_seal(
    manifest: Mapping[str, Any],
    *,
    artifact_root: str,
    fixture_base: str,
    label: str,
) -> str:
    seal_path = v2_fault_fixture_seal_path(artifact_root, fixture_base)
    try:
        seal_payload = bounded_read(
            seal_path,
            cap=RUN_ARTIFACT_CAP,
            nofollow=True,
            require_unique_link=True,
        )
    except HarnessError as error:
        raise EvidenceFailed(
            "retained fault fixture seal cannot be read through a unique "
            "nofollow descriptor"
        ) from error
    seal = v2_parse_fault_fixture_seal(seal_payload)
    base = seal_path.parent
    projection = v2_fault_fixture_tree_projection(base)
    return v2_validate_fault_fixture_seal(
        manifest,
        label=label,
        seal=seal,
        projection=projection,
    )


def v2_validate_fault_fixture_seal(
    manifest: Mapping[str, Any],
    *,
    label: str,
    seal: Any,
    projection: Any,
) -> str:
    if (
        not isinstance(seal, dict)
        or set(seal) != V2_FAULT_FIXTURE_SEAL_FIELDS
    ):
        raise EvidenceFailed(
            "retained fault fixture seal has a non-closed schema"
        )
    verify_semantic_root(seal, label="retained fault fixture seal")
    if not isinstance(projection, list):
        raise EvidenceFailed(
            "retained fault fixture projection is not an ordered array"
        )
    tree_root = semantic_root(projection)
    if (
        seal["schema"] != V2_FAULT_FIXTURE_SEAL_SCHEMA
        or seal["manifest_content_identity"] != manifest["content_identity"]
        or seal["harness_contract_identity"]
        != manifest["harness_contract_identity"]
        or seal["label"] != label
        or seal["tree_projection"] != projection
        or seal["tree_root"] != tree_root
        or seal["no_claim"]
        != (
            "the seal proves only exact retained fault-fixture bytes and "
            "membership; it mints no product or tracker authority"
        )
    ):
        raise EvidenceFailed(
            "retained fault fixture differs from its final seal; "
            "manual recovery is required"
        )
    return tree_root


def v2_finish_fault_fixture(
    manifest: Mapping[str, Any],
    *,
    artifact_root: str,
    fixture_base: str,
    label: str,
) -> str:
    seal_path = v2_fault_fixture_seal_path(artifact_root, fixture_base)
    try:
        os.lstat(seal_path)
        seal_exists = True
    except FileNotFoundError:
        seal_exists = False
    except OSError as error:
        raise EvidenceFailed(
            "retained fault fixture seal cannot be inspected"
        ) from error
    if seal_exists:
        return v2_verify_fault_fixture_seal(
            manifest,
            artifact_root=artifact_root,
            fixture_base=fixture_base,
            label=label,
        )
    projection = v2_fault_fixture_tree_projection(seal_path.parent)
    tree_root = semantic_root(projection)
    seal = v2_rooted(
        {
            "schema": V2_FAULT_FIXTURE_SEAL_SCHEMA,
            "manifest_content_identity": manifest["content_identity"],
            "harness_contract_identity": manifest[
                "harness_contract_identity"
            ],
            "label": label,
            "tree_projection": projection,
            "tree_root": tree_root,
            "no_claim": (
                "the seal proves only exact retained fault-fixture bytes and "
                "membership; it mints no product or tracker authority"
            ),
        }
    )
    v2_write_exclusive(seal_path, canonical_bytes(seal))
    v2_fsync_directory(seal_path.parent)
    return v2_verify_fault_fixture_seal(
        manifest,
        artifact_root=artifact_root,
        fixture_base=fixture_base,
        label=label,
    )


def v2_fresh_fault_fixture_base(
    manifest: Mapping[str, Any],
    *,
    label: str,
) -> tuple[str, str, bool]:
    """Claim or exactly verify one deterministic retained fault-fixture base."""
    identity = hashlib.sha256(
        canonical_bytes(
            {
                "manifest_content_identity": manifest["content_identity"],
                "harness_contract_identity": manifest[
                    "harness_contract_identity"
                ],
                "label": label,
            }
        )
    ).hexdigest()[:24]
    artifact_root = "target/beads-template-hygiene/v2-e2e"
    base = f"retained-fault-{label}-{identity}"
    root_relative = safe_relative(
        artifact_root,
        label="retained fault fixture root",
    )
    root_descriptor_slot: list[int | None] = [None]
    created = False
    operation_succeeded = False
    try:
        v2_open_or_create_directory_chain(
            root_relative,
            label="retained fault fixture root",
            _descriptor_slot=root_descriptor_slot,
        )
        root_descriptor = list.__getitem__(root_descriptor_slot, 0)
        if root_descriptor is None:
            raise InfrastructureFailed(
                "retained fault fixture root descriptor ownership was lost"
            )
        try:
            os.mkdir(base, 0o755, dir_fd=root_descriptor)
            os.fsync(root_descriptor)
            created = True
        except FileExistsError:
            created = False
        except OSError as error:
            raise EvidenceFailed(
                "retained fault fixture cannot be claimed safely"
            ) from error
        operation_succeeded = True
    finally:
        v2_close_owned_descriptor_slots((
            (
                root_descriptor_slot,
                InfrastructureFailed(
                    "retained fault fixture root descriptor close failed"
                ),
            ),
        ), surface_failure=operation_succeeded)
    if not created:
        seal_path = v2_fault_fixture_seal_path(artifact_root, base)
        deadline = time.monotonic() + 5.0
        while not seal_path.exists() and time.monotonic() < deadline:
            time.sleep(0.05)
        if not seal_path.exists():
            raise EvidenceFailed(
                "retained fault fixture lacks its final seal; "
                "manual recovery is required"
            )
        v2_verify_fault_fixture_seal(
            manifest,
            artifact_root=artifact_root,
            fixture_base=base,
            label=label,
        )
    return artifact_root, base, created


def v2_fault_fixture_payloads(
    manifest: Mapping[str, Any],
    *,
    artifact_root: str,
    artifact_dir: str,
    oversize: bool = False,
) -> tuple[dict[str, bytes], tuple[Any, ...]]:
    payloads, _, components = v2_replayable_fixture_bundle(
        manifest,
        subject_mode="review-plan",
        oversize=oversize,
        artifact_root=artifact_root,
        artifact_dir=artifact_dir,
    )
    return payloads, components


def v2_payload_identity_projection(
    payloads: Mapping[str, bytes],
) -> dict[str, dict[str, Any]]:
    return {
        name: {
            "byte_length": len(payload),
            "content_root": (
                "sha256-v1:" + hashlib.sha256(payload).hexdigest()
            ),
        }
        for name, payload in sorted(payloads.items())
    }


def v2_execute_artifact_cases(
    case: Mapping[str, Any],
    manifest: Mapping[str, Any],
) -> dict[str, Any]:
    slug = str(case["id"]).removeprefix("template-lint-v2.")
    checks = V2CheckCollector(case["id"], case["assertion_id"])
    parameters = {"family": "artifact-log-replay", "slug": slug}
    if slug == "artifact-review-base-set":
        payloads, components = v2_synthetic_payloads(manifest)
        checks.check(
            "review-nine-base-files",
            set(V2_RUN_ARTIFACTS).issubset(payloads)
            and len(set(V2_RUN_ARTIFACTS)) == 9
            and components[3]["state"] == "POPULATED"
            and components[4]["state"] == "NOT_REQUESTED",
            expected={"base": 9, "review": "POPULATED", "history": "NOT_REQUESTED"},
            observed={
                "base": len(set(V2_RUN_ARTIFACTS) & set(payloads)),
                "review": components[3]["state"],
                "history": components[4]["state"],
            },
        )
    elif slug == "artifact-history-base-set":
        payloads, _, components = v2_replayable_fixture_bundle(
            manifest,
            subject_mode="history-plan",
            artifact_root="target/v2-fixture",
            artifact_dir="history-run",
        )
        review = components[3]
        history = components[4]
        checks.check(
            "history-nine-base-files",
            set(payloads) == set(V2_RUN_ARTIFACTS)
            and history["state"] == "POPULATED"
            and review["state"] == "NOT_REQUESTED",
            expected={"files": 9, "history": "POPULATED", "review": "NOT_REQUESTED"},
            observed={
                "files": len(payloads),
                "history": history["state"],
                "review": review["state"],
            },
        )
    elif slug == "artifact-not-requested-projection":
        document = v2_not_requested(
            schema=V2_HISTORY_SCHEMA,
            mode="review-plan",
            source_root=semantic_root({"source": 1}),
            inventory_root=semantic_root({"inventory": 1}),
            projection="history",
        )
        expected = {
            "schema",
            "state",
            "mode",
            "projection",
            "source_root",
            "inventory_root",
            "rows",
            "no_claim",
            "semantic_root",
        }
        checks.check(
            "not-requested-closed-schema",
            set(document) == expected
            and document["state"] == "NOT_REQUESTED"
            and document["rows"] == [],
            expected=sorted(expected),
            observed=sorted(document),
        )
        mutated = dict(document)
        mutated["state"] = "POPULATED"
        checks.check(
            "empty-populated-root-differs",
            semantic_root(
                {key: value for key, value in mutated.items() if key != "semantic_root"}
            )
            != document["semantic_root"],
            expected="different root",
            observed=semantic_root(
                {key: value for key, value in mutated.items() if key != "semantic_root"}
            ),
        )
    elif slug == "artifact-oversize-inventory":
        payloads, components = v2_synthetic_payloads(
            manifest,
            oversize=True,
        )
        review = components[3]
        entry = review["oversize_content"][0]
        optional_name = entry["relative_path"]
        matching_targets = [
            row
            for row in components[1]["rows"]
            if row["target_root"] in entry["target_roots"]
        ]
        checks.check(
            "registered-optional-exact",
            optional_name in payloads
            and entry["byte_length"] == len(payloads[optional_name])
            and entry["aggregate_cap_accounting"] == len(payloads[optional_name]),
            expected=entry["byte_length"],
            observed=len(payloads[optional_name]),
        )
        checks.check(
            "optional-roots-complete",
            len(matching_targets) == 1
            and entry["target_roots"]
            == [matching_targets[0]["target_root"]]
            and entry["field_roots"] == matching_targets[0]["field_roots"]
            and entry["clause_roots"] == matching_targets[0]["clause_roots"],
            expected={
                "matching_targets": 1,
                "target_roots": entry["target_roots"],
                "field_roots": entry["field_roots"],
                "clause_roots": entry["clause_roots"],
            },
            observed={
                "matching_targets": len(matching_targets),
                "target_roots": entry["target_roots"],
                "field_roots": entry["field_roots"],
                "clause_roots": entry["clause_roots"],
            },
        )
    elif slug == "artifact-no-overwrite-partial":
        existing_output_text = str(REPO_ROOT)
        checks.refuses(
            "existing-output-refused",
            EvidenceFailed,
            lambda: require_fresh_run_dir(
                Path(existing_output_text),
                label="fixture output",
            ),
            contains="already exists",
        )
        prefix = {"source-v2.json": b"{}\n"}
        checks.check(
            "partial-prefix-not-complete",
            "terminal.json" not in prefix,
            expected="terminal absent",
            observed=sorted(prefix),
        )
        for error_type in (InputRefused, NoData, EvidenceFailed):
            artifact_root, artifact_dir = v2_persistent_e2e_location(
                manifest,
                label=f"refusal-{error_type.terminal.lower()}",
            )
            refusal_payloads, failure = v2_refusal_bundle_payloads(
                mode="review-plan",
                artifact_root=artifact_root,
                artifact_dir=artifact_dir,
                manifest=manifest,
                error=error_type("bounded semantic refusal fixture"),
                stage="selected_projection",
                available_roots={
                    "source": None,
                    "inventory": None,
                    "authority": None,
                    "review_plan": None,
                    "history": None,
                    "zero_sets": None,
                },
                argv=[str(SCRIPT_REL), "--review-plan"],
            )
            (
                _,
                retained_refusal,
                refusal_terminal,
                refusal_events,
            ) = v2_publish_and_read_persistent_fixture(
                artifact_root=artifact_root,
                artifact_dir=artifact_dir,
                payloads=refusal_payloads,
            )
            validated = v2_validate_refusal_bundle(
                artifact_root=artifact_root,
                input_dir=artifact_dir,
                payloads=retained_refusal,
                terminal=refusal_terminal,
                events=refusal_events,
                accepted_manifest=manifest,
            )
            checks.check(
                f"complete-non-green-{error_type.terminal.lower()}",
                set(refusal_payloads) == set(V2_RUN_ARTIFACTS)
                and refusal_terminal["bundle_state"]
                == "COMPLETE_NON_GREEN"
                and refusal_terminal["optional_content_registry"] == []
                and refusal_terminal["failure_root"]
                == failure["semantic_root"]
                and validated["terminal"] == error_type.terminal
                and validated["complete_green_prefix"] is False,
                expected={
                    "files": 9,
                    "terminal": error_type.terminal,
                    "green": False,
                },
                observed={
                    "files": len(refusal_payloads),
                    "terminal": validated["terminal"],
                    "green": validated["complete_green_prefix"],
                },
            )
            replay_output = f"{artifact_dir}-forbidden-replay"
            replay_output_path = resolve_run_dir(
                artifact_root,
                replay_output,
                label="refusal replay output",
            )
            if replay_output_path.exists():
                raise EvidenceFailed(
                    "semantic-refusal replay unexpectedly has an output prefix"
                )
            try:
                v2_replay_bundle(
                    artifact_root=artifact_root,
                    input_dir=artifact_dir,
                    output_dir=replay_output,
                )
            except PublishedV2Refusal as replay_error:
                checks.check(
                    "filesystem-replay-preserves-"
                    f"{error_type.terminal.lower()}",
                    replay_error.terminal == error_type.terminal
                    and replay_error.document["exit_code"]
                    == TERMINAL_EXIT[error_type.terminal]
                    and replay_error.document[
                        "replay_validated_without_output"
                    ]
                    is True
                    and not replay_output_path.exists(),
                    expected={
                        "terminal": error_type.terminal,
                        "exit_code": TERMINAL_EXIT[error_type.terminal],
                        "output_exists": False,
                    },
                    observed={
                        "terminal": replay_error.terminal,
                        "exit_code": replay_error.document["exit_code"],
                        "output_exists": replay_output_path.exists(),
                    },
                )
            else:
                raise EvidenceFailed(
                    "semantic-refusal replay incorrectly returned Pass"
                )
    elif slug == "artifact-membership-path-safety":
        for index, value in enumerate(
            ("../escape", "/absolute", "a//b", "a/./b", "a\\b", "e\u0301")
        ):
            checks.refuses(
                f"unsafe-member-{index}",
                InputRefused,
                lambda value=value: v2_safe_member(value, label="fixture"),
                contains="unsafe",
            )
        expected = sorted(V2_RUN_ARTIFACTS)
        extra = sorted([*V2_RUN_ARTIFACTS, "extra.json"])
        checks.check(
            "extra-membership-detected",
            expected != extra,
            expected=expected,
            observed=extra,
        )
        identities: dict[tuple[int, int], str] = {}
        v2_register_member_identity(
            identities,
            device=1,
            inode=100,
            link_count=1,
            relative="source-v2.json",
            kind="file",
        )
        identity_projection = lambda: [
            {
                "device": device,
                "inode": inode,
                "path": path,
            }
            for (device, inode), path in sorted(dict.items(identities))
        ]
        checks.refuses(
            "inode-alias-refused",
            InputRefused,
            lambda: v2_register_member_identity(
                identities,
                device=1,
                inode=100,
                link_count=1,
                relative="inventory-v2.json",
                kind="file",
            ),
            contains="inode alias",
            projection=identity_projection,
            projection_label="BUNDLE_MEMBER_IDENTITIES",
        )
        checks.refuses(
            "external-hardlink-refused",
            InputRefused,
            lambda: v2_register_member_identity(
                identities,
                device=1,
                inode=101,
                link_count=2,
                relative="authority-v2.json",
                kind="file",
            ),
            contains="hard-link alias",
            projection=identity_projection,
            projection_label="BUNDLE_MEMBER_IDENTITIES",
        )
        artifact_root, fixture_base, fixture_created = (
            v2_fresh_fault_fixture_base(
            manifest,
            label="artifact-membership-path-safety",
            )
        )

        missing_dir = f"{fixture_base}/missing-member"
        missing_payloads, _ = v2_fault_fixture_payloads(
            manifest,
            artifact_root=artifact_root,
            artifact_dir=missing_dir,
        )
        missing_publication = dict(missing_payloads)
        missing_publication.pop("source-v2.json")
        if fixture_created:
            v2_publish_bundle(
                artifact_root=artifact_root,
                artifact_dir=missing_dir,
                payloads=missing_publication,
            )
        missing_error = expect_error(
            InputRefused,
            lambda: v2_read_retained_bundle(
                artifact_root=artifact_root,
                input_dir=missing_dir,
            ),
            contains="first divergence at source-v2.json",
        )
        checks.check(
            "retained-missing-member-production-refusal",
            missing_error.terminal == "InputRefused",
            expected={
                "terminal": "InputRefused",
                "first_member": "source-v2.json",
            },
            observed={
                "terminal": missing_error.terminal,
                "diagnostic": str(missing_error),
            },
        )

        changed_dir = f"{fixture_base}/changed-member"
        changed_payloads, _ = v2_fault_fixture_payloads(
            manifest,
            artifact_root=artifact_root,
            artifact_dir=changed_dir,
        )
        changed_publication = dict(changed_payloads)
        changed_publication["source-v2.json"] += b" "
        if fixture_created:
            v2_publish_bundle(
                artifact_root=artifact_root,
                artifact_dir=changed_dir,
                payloads=changed_publication,
            )
        changed_output_dir = f"{fixture_base}/changed-replay-output"
        changed_error = expect_error(
            InputRefused,
            lambda: v2_replay_bundle(
                artifact_root=artifact_root,
                input_dir=changed_dir,
                output_dir=changed_output_dir,
            ),
            contains="not canonical JSON",
        )
        checks.check(
            "retained-changed-member-production-refusal",
            changed_error.terminal == "InputRefused"
            and not resolve_run_dir(
                artifact_root,
                changed_output_dir,
                label="changed-member replay output",
            ).exists(),
            expected={
                "terminal": "InputRefused",
                "output_exists": False,
            },
            observed={
                "terminal": changed_error.terminal,
                "diagnostic": str(changed_error),
                "output_exists": resolve_run_dir(
                    artifact_root,
                    changed_output_dir,
                    label="changed-member replay output",
                ).exists(),
            },
        )

        symlink_dir = f"{fixture_base}/symlink-member"
        symlink_payloads, _ = v2_fault_fixture_payloads(
            manifest,
            artifact_root=artifact_root,
            artifact_dir=symlink_dir,
        )
        symlink_publication = dict(symlink_payloads)
        symlink_publication.pop("source-v2.json")
        if fixture_created:
            v2_publish_bundle(
                artifact_root=artifact_root,
                artifact_dir=symlink_dir,
                payloads=symlink_publication,
            )
        symlink_output = resolve_run_dir(
            artifact_root,
            symlink_dir,
            label="symlink-member fixture",
            must_exist=True,
        )
        if fixture_created:
            try:
                os.symlink(
                    "inventory-v2.json",
                    symlink_output / "source-v2.json",
                )
                v2_fsync_directory(symlink_output)
            except OSError as error:
                raise InfrastructureFailed(
                    "retained symlink-member fixture could not be created"
                ) from error
        symlink_error = expect_error(
            InputRefused,
            lambda: v2_read_retained_bundle(
                artifact_root=artifact_root,
                input_dir=symlink_dir,
            ),
            contains="unsafe member",
        )
        checks.check(
            "retained-symlink-member-production-refusal",
            symlink_error.terminal == "InputRefused"
            and (symlink_output / "source-v2.json").is_symlink(),
            expected={
                "terminal": "InputRefused",
                "retained_symlink": True,
            },
            observed={
                "terminal": symlink_error.terminal,
                "diagnostic": str(symlink_error),
                "retained_symlink": (
                    symlink_output / "source-v2.json"
                ).is_symlink(),
            },
        )

        over_cap_dir = f"{fixture_base}/over-cap-member"
        over_cap_payloads, _ = v2_fault_fixture_payloads(
            manifest,
            artifact_root=artifact_root,
            artifact_dir=over_cap_dir,
        )
        over_cap_publication = dict(over_cap_payloads)
        over_cap_publication.pop("source-v2.json")
        if fixture_created:
            v2_publish_bundle(
                artifact_root=artifact_root,
                artifact_dir=over_cap_dir,
                payloads=over_cap_publication,
            )
        over_cap_output = resolve_run_dir(
