            try:
                over_cap_flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL
                over_cap_flags |= os.O_NOFOLLOW
                list.__setitem__(over_cap_descriptor_slot, 0, os.open(over_cap_output / "source-v2.json", over_cap_flags, 0o644))
                over_cap_descriptor = list.__getitem__(
                    over_cap_descriptor_slot,
                    0,
                )
                if over_cap_descriptor is None:
                    raise InfrastructureFailed(
                        "retained over-cap fixture descriptor ownership "
                        "was lost"
                    )
                os.ftruncate(over_cap_descriptor, RUN_ARTIFACT_CAP + 1)
                os.fsync(over_cap_descriptor)
                over_cap_body_succeeded = True
            except OSError as error:
                raise InfrastructureFailed(
                    "retained over-cap fixture could not be created"
                ) from error
            finally:
                v2_close_owned_descriptor_slots((
