        class HostileModuleGlobalsBinding:
            def __call__(self) -> dict[str, Any]:
                exact_wire_globals_hooks["calls"] += 1
                raise RuntimeError("hostile module globals binding")

        exact_wire_module_globals = (
            V2_FUNCTION_GLOBALS_DESCRIPTOR_CONTRACT.__get__(
