                "invalid_subscript_terminals": [
                    list_subscript_error.terminal,
                    tuple_subscript_error.terminal,
                ],
                "nested_keyword_binding": nested_binding_results,
                "protocol_arguments": protocol_argument_results,
                "selected_public_projections": (
                    selected_public_projection_results
                ),
                "dict_get_protocol": {
                    "terminal": dict_get_protocol_error.terminal,
                    "hook_calls": {"iter": dict_get_protocol_hooks.iter},
                },
                "exact_container_dataflow": (
                    exact_container_dataflow_results
                ),
                "dict_values": dict_values_projection_results,
                "nested_mapping_projection_kind": (
                    nested_mapping_projection_kind
                ),
                "module_fullmatch_projection_kind": (
                    module_fullmatch_projection_kind
                ),
                "publication_prefix_collision_projection_kind": (
                    publication_prefix_collision_projection_kind
                ),
                "comprehension_projection_callbacks_reached": len(
                    comprehension_projection_probe.rows
                ),
                "capabilities": capability_results,
            },
        )

        class DynamicResultInvocationState:
            def __init__(self) -> None:
                self.immediate = False
                self.stored = False
                self.native_constructor = False

        dynamic_result_callbacks_invoked = DynamicResultInvocationState()

        def inert_result_factory() -> Callable[[], None]:
            return lambda: None

        def immediate_dynamic_result_callback(
            factory: Callable[[], Callable[[], None]] = inert_result_factory,
        ) -> None:
            dynamic_result_callbacks_invoked.immediate = True
            factory()()
            raise InputRefused("unreachable immediate result refusal")

        def stored_dynamic_result_callback(
            factory: Callable[[], Callable[[], None]] = inert_result_factory,
        ) -> None:
            dynamic_result_callbacks_invoked.stored = True
            generated = factory()
            generated()
            raise InputRefused("unreachable stored result refusal")

        inert_code = (lambda: None).__code__

        def native_constructor_callback(
            constructor: type[Any] = types.FunctionType,
            code: types.CodeType = inert_code,
        ) -> None:
            dynamic_result_callbacks_invoked.native_constructor = True
            constructor(code, {})
            raise InputRefused("unreachable native constructor refusal")

        def unbound_required_call(value: Callable[[], None]) -> None:
            value()

        def unbound_required_method(value: Any) -> None:
            value.read()

        def bound_default_call(
            value: Callable[[], None] = lambda: None,
        ) -> None:
            value()

        bound_default_projection = v2_bounded_explicit_projection(
            bound_default_call
        )
        bound_default_parameter_rows = dict.get(
            bound_default_projection,
            "referenced_default_parameters",
            [],
        )
        bound_default_access_rows = (
            dict.get(
                dict.get(
                    bound_default_parameter_rows[0],
                    "executable_access",
                    {},
                ),
                "rows",
                [],
            )
            if bound_default_parameter_rows
            else []
        )
        bound_default_no_claim = (
            dict.get(
                dict.get(bound_default_access_rows[0], "state", {}),
                "no_claim",
            )
            if bound_default_access_rows
            else None
        )

        dynamic_result_errors = {
            "immediate": expect_error(
                EvidenceFailed,
                lambda: v2_callback_refusal_projection(
                    immediate_dynamic_result_callback,
                    collector_rows=[],
                ),
                contains="dynamically produced call result",
            ),
            "stored": expect_error(
                EvidenceFailed,
                lambda: v2_callback_refusal_projection(
                    stored_dynamic_result_callback,
                    collector_rows=[],
                ),
                contains="dynamically produced local result",
            ),
            "native_constructor": expect_error(
                EvidenceFailed,
                lambda: v2_callback_refusal_projection(
                    native_constructor_callback,
                    collector_rows=[],
                ),
                contains="unaudited native __new__ constructor",
            ),
            "unbound_required_call": expect_error(
                EvidenceFailed,
                lambda: v2_bounded_explicit_projection(
                    unbound_required_call
                ),
                contains="invokes an unbound required parameter",
            ),
            "unbound_required_method": expect_error(
                EvidenceFailed,
                lambda: v2_bounded_explicit_projection(
                    unbound_required_method
                ),
                contains="invokes an unbound required parameter",
            ),
        }
        checks.check(
            "refusal-dynamic-call-results-and-native-constructors-fail-closed",
            {
                "immediate": dynamic_result_callbacks_invoked.immediate,
                "stored": dynamic_result_callbacks_invoked.stored,
                "native_constructor": (
                    dynamic_result_callbacks_invoked.native_constructor
                ),
            }
            == {
                "immediate": False,
                "stored": False,
                "native_constructor": False,
            }
            and all(
                error.terminal == "EvidenceFailed"
                for error in dynamic_result_errors.values()
            )
            and bound_default_no_claim
            == V2_EXECUTABLE_CODE_PROJECTION_NO_CLAIM,
            expected={
                "callbacks_invoked": {
                    "immediate": False,
                    "stored": False,
                    "native_constructor": False,
                },
                "terminals": {
                    "immediate": "EvidenceFailed",
                    "stored": "EvidenceFailed",
                    "native_constructor": "EvidenceFailed",
                    "unbound_required_call": "EvidenceFailed",
                    "unbound_required_method": "EvidenceFailed",
                },
                "bound_default_call": "projected-with-no-claim",
            },
            observed={
                "callbacks_invoked": dynamic_result_callbacks_invoked,
                "terminals": {
                    name: error.terminal
                    for name, error in dynamic_result_errors.items()
                },
                "bound_default_projection_no_claim": (
                    bound_default_no_claim
                ),
            },
        )

        reconstruction_projection_context = (
            v2_new_refusal_projection_context()
        )
        reconstruction_code_projection = v2_state_projection_value(
            v2_reconstruct_retained,
            context=reconstruction_projection_context,
        )
        v2_validate_refusal_projection_graph(
            reconstruction_code_projection
        )
        reconstruction_projection_opaque = v2_projection_contains_opaque(
            reconstruction_code_projection
        )
        reconstruction_projection_payload = canonical_bytes(
            reconstruction_code_projection
        )
        reconstruction_no_claim_found = False
        reconstruction_projection_stack: list[Any] = [
            reconstruction_code_projection
        ]
        while reconstruction_projection_stack:
            projected_value = list.pop(reconstruction_projection_stack)
            if type(projected_value) is dict:
                if (
                    dict.get(projected_value, "no_claim")
                    == V2_EXECUTABLE_CODE_PROJECTION_NO_CLAIM
                ):
                    reconstruction_no_claim_found = True
                list.extend(
                    reconstruction_projection_stack,
                    dict.values(projected_value),
                )
            elif type(projected_value) is list:
                list.extend(
                    reconstruction_projection_stack,
                    projected_value,
                )
        public_reconstruction_projection = v2_bounded_explicit_projection(
            v2_reconstruct_retained
        )
        public_reconstruction_projection_opaque = (
            v2_projection_contains_opaque(
                public_reconstruction_projection
            )
        )
        public_reconstruction_projection_payload = canonical_bytes(
            public_reconstruction_projection
        )
        public_reconstruction_no_claim_found = False
        public_reconstruction_stack: list[Any] = [
            public_reconstruction_projection
        ]
        while public_reconstruction_stack:
            projected_value = list.pop(public_reconstruction_stack)
            if type(projected_value) is dict:
                if (
                    dict.get(projected_value, "no_claim")
                    == V2_EXECUTABLE_CODE_PROJECTION_NO_CLAIM
                ):
                    public_reconstruction_no_claim_found = True
                list.extend(
                    public_reconstruction_stack,
                    dict.values(projected_value),
                )
            elif type(projected_value) is list:
                list.extend(public_reconstruction_stack, projected_value)
        reconstruction_limits = reconstruction_projection_context["limits"]
        reconstruction_counters = {
            key: reconstruction_projection_context["counters"][key]
            for key in (
                "nodes",
                "items",
                "scalar_bytes",
                "instructions",
            )
        }
        checks.check(
            "retained-reconstruction-transitive-code-closure-is-bounded-with-no-claim",
            not reconstruction_projection_opaque
            and reconstruction_no_claim_found
            and len(reconstruction_projection_payload)
            <= reconstruction_limits["projection_bytes"]
            and all(
                reconstruction_counters[key]
                <= reconstruction_limits[key]
                for key in reconstruction_counters
            )
            and not public_reconstruction_projection_opaque
            and public_reconstruction_no_claim_found,
            expected={
                "opaque": False,
                "all_counters_within_limits": True,
                "canonical_projection_within_limit": True,
                "executable_code_no_claim": (
                    V2_EXECUTABLE_CODE_PROJECTION_NO_CLAIM
                ),
                "public_projection_without_bound_inputs": (
                    "bounded code-only projection with executable-code no-claim"
                ),
            },
            observed={
                "opaque": reconstruction_projection_opaque,
                "counters": reconstruction_counters,
                "limits": {
                    key: reconstruction_limits[key]
                    for key in (
                        "nodes",
                        "items",
                        "scalar_bytes",
                        "instructions",
                        "projection_bytes",
                    )
                },
                "canonical_projection_bytes": len(
                    reconstruction_projection_payload
                ),
                "executable_code_no_claim_found": (
                    reconstruction_no_claim_found
                ),
                "public_projection_without_bound_inputs": {
                    "canonical_bytes": len(
                        public_reconstruction_projection_payload
                    ),
                    "opaque": public_reconstruction_projection_opaque,
                    "executable_code_no_claim_found": (
                        public_reconstruction_no_claim_found
                    ),
                },
            },
        )

        refusal_rlock = threading.RLock()
        rlock_type_dictionary = v2_raw_type_dictionary(
            V2_REFUSAL_RLOCK_TYPE
        )
        rlock_capabilities_present = all(
            name in rlock_type_dictionary
            for name in (
                "_is_owned",
                "_recursion_count",
                "acquire",
                "release",
            )
        )

        def leak_rlock_then_refuse(
            guard: Any = refusal_rlock,
        ) -> None:
            guard.acquire()
            raise InputRefused("synthetic refusal after RLock leak")

        rlock_collector = V2CheckCollector(
            "fixture-rlock-refusal-state",
            "fixture.rlock-refusal-state",
        )
        leaked_rlock_owned = False
        leaked_rlock_count = 0
        try:
            rlock_error = expect_error(
                EvidenceFailed,
                lambda: rlock_collector.refuses(
                    "rlock-leaked",
                    InputRefused,
                    leak_rlock_then_refuse,
                ),
                contains="rlock-leaked failed",
            )
        finally:
            leaked_rlock_owned = bool(
                rlock_type_dictionary["_is_owned"](refusal_rlock)
            )
            leaked_rlock_count = int(
                rlock_type_dictionary["_recursion_count"](refusal_rlock)
            )
            for _ in range(leaked_rlock_count):
                rlock_type_dictionary["release"](refusal_rlock)
        restored_rlock_state = v2_rlock_observation(refusal_rlock)

        cross_thread_rlock = threading.RLock()
        cross_thread_entered = threading.Event()
        cross_thread_release = threading.Event()
        cross_thread_errors: list[str] = []

        def hold_cross_thread_rlock() -> None:
            try:
                cross_thread_rlock.acquire()
                cross_thread_entered.set()
                if not cross_thread_release.wait(5.0):
                    raise RuntimeError("cross-thread RLock fixture timed out")
            except BaseException as error:
                cross_thread_errors.append(v2_raw_type_name(type(error)))
            finally:
                if rlock_type_dictionary["_is_owned"](cross_thread_rlock):
                    rlock_type_dictionary["release"](cross_thread_rlock)

        cross_thread = threading.Thread(
            target=hold_cross_thread_rlock,
            name="v2-rlock-observation-fixture",
            daemon=True,
        )
        cross_thread.start()
        try:
            if not cross_thread_entered.wait(5.0):
                raise EvidenceFailed(
                    "cross-thread RLock fixture did not acquire its lock"
                )
            cross_thread_observation = v2_rlock_observation(
                cross_thread_rlock
            )
        finally:
            cross_thread_release.set()
            cross_thread.join(5.0)
        cross_thread_restored = v2_rlock_observation(cross_thread_rlock)
        checks.check(
            "refusal-rlock-leak-detected-and-test-cleanup-restores",
            rlock_capabilities_present
            and leaked_rlock_owned is True
            and leaked_rlock_count == 1
            and rlock_error.terminal == "EvidenceFailed"
            and len(rlock_collector.rows) == 1
            and rlock_collector.rows[0]["passed"] is False
            and restored_rlock_state["owned_by_current_thread"] is False
            and restored_rlock_state["current_thread_recursion_count"] == 0
            and restored_rlock_state["locked_by_any_thread"] is False
            and cross_thread_observation["locked_by_any_thread"] is True
            and cross_thread_observation["owned_by_current_thread"] is False
            and cross_thread_observation["current_thread_recursion_count"] == 0
            and not cross_thread.is_alive()
            and cross_thread_errors == []
            and cross_thread_restored["locked_by_any_thread"] is False,
            expected={
                "cpython_capabilities_present": True,
                "leaked_owned": True,
                "leaked_recursion_count": 1,
                "collector_rows": 1,
                "collector_passed": False,
                "collector_terminal": "EvidenceFailed",
                "restored_owned_by_current_thread": False,
                "restored_recursion_count": 0,
                "other_thread_lock_observed": True,
                "other_thread_fixture_retired": True,
            },
            observed={
                "cpython_capabilities_present": rlock_capabilities_present,
                "leaked_owned": leaked_rlock_owned,
                "leaked_recursion_count": leaked_rlock_count,
                "collector_rows": len(rlock_collector.rows),
                "collector_passed": rlock_collector.rows[0]["passed"],
                "collector_terminal": rlock_error.terminal,
                "restored": restored_rlock_state,
                "cross_thread_observation": cross_thread_observation,
                "cross_thread_restored": cross_thread_restored,
                "cross_thread_alive": cross_thread.is_alive(),
                "cross_thread_errors": cross_thread_errors,
            },
        )

        cap_node_value = [["left"], ["right"]]
        node_measure_context = v2_new_refusal_projection_context()
        v2_state_projection_value(
            cap_node_value,
            context=node_measure_context,
        )
        required_nodes = node_measure_context["counters"]["nodes"]
        v2_state_projection_value(
            cap_node_value,
            context=v2_new_refusal_projection_context(
                {"nodes": required_nodes}
            ),
        )
        node_cap_error = expect_error(
            EvidenceFailed,
            lambda: v2_state_projection_value(
                cap_node_value,
                context=v2_new_refusal_projection_context(
                    {"nodes": required_nodes - 1}
                ),
            ),
            contains="aggregate nodes cap",
        )

        cap_item_value = ["alpha", "beta", "gamma"]
        item_measure_context = v2_new_refusal_projection_context()
        v2_state_projection_value(
            cap_item_value,
            context=item_measure_context,
        )
        required_items = item_measure_context["counters"]["items"]
        v2_state_projection_value(
            cap_item_value,
            context=v2_new_refusal_projection_context(
                {"items": required_items}
            ),
        )
        item_cap_error = expect_error(
            EvidenceFailed,
            lambda: v2_state_projection_value(
                cap_item_value,
                context=v2_new_refusal_projection_context(
                    {"items": required_items - 1}
                ),
            ),
            contains="aggregate items cap",
        )

        cap_scalar_value = "four"
        v2_state_projection_value(
            cap_scalar_value,
            context=v2_new_refusal_projection_context(
                {"scalar_bytes": 4}
            ),
        )
        scalar_cap_error = expect_error(
            EvidenceFailed,
            lambda: v2_state_projection_value(
                cap_scalar_value,
                context=v2_new_refusal_projection_context(
                    {"scalar_bytes": 3}
                ),
            ),
            contains="aggregate scalar bytes cap",
        )

        def cap_instruction_callback() -> None:
            raise InputRefused("synthetic cap refusal")

        instruction_measure_context = v2_new_refusal_projection_context()
        v2_code_access_analysis(
            cap_instruction_callback.__code__,
            context=instruction_measure_context,
        )
        required_instructions = instruction_measure_context["counters"][
            "instructions"
        ]
        v2_code_access_analysis(
            cap_instruction_callback.__code__,
            context=v2_new_refusal_projection_context(
                {"instructions": required_instructions}
            ),
        )
        instruction_cap_error = expect_error(
            EvidenceFailed,
            lambda: v2_code_access_analysis(
                cap_instruction_callback.__code__,
                context=v2_new_refusal_projection_context(
                    {"instructions": required_instructions - 1}
                ),
            ),
            contains="aggregate instructions cap",
        )

        baseline_cap_projection = v2_callback_refusal_projection(
            cap_instruction_callback,
            collector_rows=[],
        )
        required_projection_bytes = len(
            canonical_bytes(baseline_cap_projection)
        )
        v2_callback_refusal_projection(
            cap_instruction_callback,
            collector_rows=[],
            limits={"projection_bytes": required_projection_bytes},
        )
        projection_bytes_cap_error = expect_error(
            EvidenceFailed,
            lambda: v2_callback_refusal_projection(
                cap_instruction_callback,
                collector_rows=[],
                limits={
                    "projection_bytes": required_projection_bytes - 1,
                },
            ),
            contains="aggregate projection bytes cap",
        )
        cap_terminals = [
            node_cap_error.terminal,
            item_cap_error.terminal,
            scalar_cap_error.terminal,
            instruction_cap_error.terminal,
            projection_bytes_cap_error.terminal,
        ]
        checks.check(
            "refusal-projection-aggregate-caps-exact-and-plus-one",
            required_nodes > 0
            and required_items > 0
            and required_instructions > 0
            and required_projection_bytes > 0
            and cap_terminals == ["EvidenceFailed"] * 5,
            expected={
                "exact_caps_admitted": [
                    "nodes",
                    "items",
                    "scalar_bytes",
                    "instructions",
                    "projection_bytes",
                ],
                "plus_one_terminals": ["EvidenceFailed"] * 5,
            },
            observed={
                "required": {
                    "nodes": required_nodes,
                    "items": required_items,
                    "scalar_bytes": 4,
                    "instructions": required_instructions,
                    "projection_bytes": required_projection_bytes,
                },
                "plus_one_terminals": cap_terminals,
            },
        )

        outcome_rows: dict[str, dict[str, Any]] = {}

        return_mutation_state = MutableRefusalProbe()

        def mutate_then_return() -> None:
            return_mutation_state.phase = "after"

        wrong_error_state = MutableRefusalProbe()

        def mutate_then_wrong_error() -> None:
            wrong_error_state.phase = "after"
            raise NoData("synthetic wrong terminal")

        diagnostic_mismatch_state = MutableRefusalProbe()

        def mutate_then_wrong_diagnostic() -> None:
            diagnostic_mismatch_state.phase = "after"
            raise InputRefused("synthetic unmatched diagnostic")

        keyboard_interrupt_state = MutableRefusalProbe()

        def mutate_then_keyboard_interrupt() -> None:
            keyboard_interrupt_state.phase = "after"
            raise KeyboardInterrupt("synthetic keyboard interrupt")

        system_exit_state = MutableRefusalProbe()

        def mutate_then_system_exit() -> None:
            system_exit_state.phase = "after"
            raise SystemExit("synthetic system exit")

        hostile_wrong_error_hooks = RefusalHookCounters()
        hostile_wrong_error_hooks.terminal = 0
        hostile_wrong_error_hooks.str = 0

        class HostileWrongError(HarnessError):
            @property
            def terminal(self) -> str:
                hostile_wrong_error_hooks.terminal += 1
                raise RuntimeError("hostile terminal property executed")

            def __str__(self) -> str:
                hostile_wrong_error_hooks.str += 1
                raise RuntimeError("hostile error string executed")

        hostile_wrong_error_state = MutableRefusalProbe()

        def mutate_then_hostile_wrong_error() -> None:
            hostile_wrong_error_state.phase = "after"
            raise HostileWrongError("synthetic hostile wrong error")

        outcome_fixtures = (
            (
                "returned",
                mutate_then_return,
                return_mutation_state,
                None,
            ),
            (
                "wrong-error",
                mutate_then_wrong_error,
                wrong_error_state,
                None,
            ),
            (
                "wrong-diagnostic",
                mutate_then_wrong_diagnostic,
                diagnostic_mismatch_state,
                "required diagnostic",
            ),
            (
                "keyboard-interrupt",
                mutate_then_keyboard_interrupt,
                keyboard_interrupt_state,
                None,
            ),
            (
                "system-exit",
                mutate_then_system_exit,
                system_exit_state,
                None,
            ),
            (
                "hostile-wrong-error",
                mutate_then_hostile_wrong_error,
                hostile_wrong_error_state,
                None,
            ),
        )
        outcome_terminals: list[str] = []
        for outcome_name, outcome_callback, outcome_state, required_text in (
            outcome_fixtures
        ):
            outcome_collector = V2CheckCollector(
                f"fixture-{outcome_name}-refusal-outcome",
                f"fixture.{outcome_name}-refusal-outcome",
            )
            outcome_error = expect_error(
                EvidenceFailed,
                lambda collector=outcome_collector,
                callback=outcome_callback,
                contains=required_text: collector.refuses(
                    f"{outcome_name}-outcome",
                    InputRefused,
                    callback,
                    contains=contains,
                ),
                contains=f"{outcome_name}-outcome failed",
            )
            outcome_terminals.append(outcome_error.terminal)
            row = outcome_collector.rows[0]
            observed_evidence = row["observed"]
            outcome_rows[outcome_name] = {
                "state_phase": outcome_state.phase,
                "row_count": len(outcome_collector.rows),
                "passed": row["passed"],
                "first_divergence_retained": (
                    isinstance(observed_evidence, dict)
                    and observed_evidence.get("first_divergence") is not None
                ),
                "returned": (
                    observed_evidence.get("returned")
                    if isinstance(observed_evidence, dict)
                    else None
                ),
                "caught_error_type": (
                    observed_evidence.get("caught_error_type")
                    if isinstance(observed_evidence, dict)
                    else None
                ),
                "contains_match": (
                    observed_evidence.get("contains_match")
                    if isinstance(observed_evidence, dict)
                    else None
                ),
            }
        checks.check(
            "refusal-outcome-mismatch-still-records-state-divergence",
            outcome_terminals == ["EvidenceFailed"] * 6
            and all(
                row["state_phase"] == "after"
                and row["row_count"] == 1
                and row["passed"] is False
                and row["first_divergence_retained"] is True
                for row in outcome_rows.values()
            )
            and outcome_rows["returned"]["returned"] is True
            and outcome_rows["wrong-error"]["caught_error_type"] == "NoData"
            and outcome_rows["wrong-diagnostic"]["contains_match"] is False
            and outcome_rows["keyboard-interrupt"]["caught_error_type"]
            == "KeyboardInterrupt"
            and outcome_rows["system-exit"]["caught_error_type"]
            == "SystemExit"
            and outcome_rows["hostile-wrong-error"]["caught_error_type"]
            == "HostileWrongError"
            and hostile_wrong_error_hooks.terminal == 0
            and hostile_wrong_error_hooks.str == 0,
            expected={
                "terminals": ["EvidenceFailed"] * 6,
                "one_failed_row_each": True,
                "state_divergence_retained_each": True,
                "returned_callback": True,
                "wrong_error_type": "NoData",
                "diagnostic_match": False,
                "base_exception_types": [
                    "KeyboardInterrupt",
                    "SystemExit",
                ],
                "hostile_wrong_error_hooks": {"terminal": 0, "str": 0},
            },
            observed={
                "terminals": outcome_terminals,
                "rows": outcome_rows,
                "hostile_wrong_error_hooks": {
                    "terminal": hostile_wrong_error_hooks.terminal,
                    "str": hostile_wrong_error_hooks.str,
                },
            },
        )
    elif slug == "log-order-terminal":
        payloads, _ = v2_synthetic_payloads(manifest)
        events = v2_read_event_stream(payloads["events.jsonl"])
        terminal = strict_json_loads(
            payloads["terminal.json"],
            label="synthetic terminal",
            require_canonical=True,
        )
        checks.check(
            "dense-unique-last-terminal",
            [event["sequence"] for event in events] == list(range(len(events)))
            and sum(event["terminal"] is not None for event in events) == 1
            and events[-1]["terminal"] == "Pass",
            expected=True,
            observed={
                "sequence": [event["sequence"] for event in events],
                "terminals": [
                    event["sequence"]
                    for event in events
                    if event["terminal"] is not None
                ],
            },
        )
        checks.check(
            "terminal-binds-event-roots",
            terminal["event_roots"] == [semantic_root(event) for event in events]
            and terminal["terminal_event_root"] == semantic_root(events[-1]),
            expected=terminal["event_roots"],
            observed=[semantic_root(event) for event in events],
        )
    elif slug in {"replay-review-offline", "replay-history-offline"}:
        before_receipts = len(_command_receipts)
        subject_mode = (
            "review-plan"
            if slug == "replay-review-offline"
            else "history-plan"
        )
        payloads, accepted_manifest, retained = v2_replayable_fixture_bundle(
            manifest,
            subject_mode=subject_mode,
        )
        retained_source_file_identities = [
            dict(row)
            for row in retained[0]["captured"]["observation"]["source_files"]
        ]
        terminal = strict_json_loads(
            payloads["terminal.json"],
            label="replayable fixture terminal",
            require_canonical=True,
        )
        events = v2_read_event_stream(payloads["events.jsonl"])
        reconstructed = v2_reconstruct_retained(
            artifact_root="target/v2-fixture",
            input_dir=f"{subject_mode}-run",
            payloads=payloads,
            terminal=terminal,
            events=events,
            accepted_manifest=accepted_manifest,
            current_source_files=retained_source_file_identities,
        )
        after_receipts = len(_command_receipts)
        checks.check(
            "artifact-only-reconstruction-exact",
            [row["semantic_root"] for row in reconstructed[:6]]
            == [row["semantic_root"] for row in retained[:6]]
            and reconstructed[6] == retained[6],
            expected=[row["semantic_root"] for row in retained[:6]],
            observed=[row["semantic_root"] for row in reconstructed[:6]],
        )
        checks.check(
            "selected-and-not-requested-projections",
            (
                reconstructed[3]["state"] == "POPULATED"
                and reconstructed[4]["state"] == "NOT_REQUESTED"
                if subject_mode == "review-plan"
                else reconstructed[3]["state"] == "NOT_REQUESTED"
                and reconstructed[4]["state"] == "POPULATED"
            ),
            expected=(
                ("POPULATED", "NOT_REQUESTED")
                if subject_mode == "review-plan"
                else ("NOT_REQUESTED", "POPULATED")
            ),
            observed=(
                reconstructed[3]["state"],
                reconstructed[4]["state"],
            ),
        )
        checks.check(
            "offline-no-command-calls",
            before_receipts == after_receipts,
            expected=before_receipts,
            observed=after_receipts,
        )
    elif slug == "replay-tamper-live-denied":
        payloads, accepted_manifest, retained = v2_replayable_fixture_bundle(
            manifest,
            subject_mode="review-plan",
        )
        retained_source_file_identities = [
            dict(row)
            for row in retained[0]["captured"]["observation"]["source_files"]
        ]
        terminal = strict_json_loads(
            payloads["terminal.json"],
            label="tamper fixture terminal",
            require_canonical=True,
        )
        events = v2_read_event_stream(payloads["events.jsonl"])
        before_receipts = len(_command_receipts)
        reconstructed = v2_reconstruct_retained(
            artifact_root="target/v2-fixture",
            input_dir="review-plan-run",
            payloads=payloads,
            terminal=terminal,
            events=events,
            accepted_manifest=accepted_manifest,
            current_source_files=retained_source_file_identities,
        )
        checks.check(
            "offline-baseline-no-live-or-network",
            len(reconstructed) == 7
            and len(_command_receipts) == before_receipts
            and reconstructed[0]["network_access"] is False
            and reconstructed[0]["direct_tracker_file_access"] is False,
            expected={
                "components": 7,
                "new_command_receipts": 0,
                "network_access": False,
                "direct_tracker_file_access": False,
            },
            observed={
                "components": len(reconstructed),
                "new_command_receipts": len(_command_receipts) - before_receipts,
                "network_access": reconstructed[0]["network_access"],
                "direct_tracker_file_access": reconstructed[0][
                    "direct_tracker_file_access"
                ],
            },
        )
        fixture_replay_equivalence = {
            "retained_terminal_root": terminal["semantic_root"],
            "retained_source_root": reconstructed[0]["semantic_root"],
            "retained_inventory_root": reconstructed[1]["semantic_root"],
            "retained_authority_root": reconstructed[2]["semantic_root"],
            "retained_review_plan_root": reconstructed[3]["semantic_root"],
            "retained_history_root": reconstructed[4]["semantic_root"],
            "retained_zero_sets_root": reconstructed[5]["semantic_root"],
            "retained_events_content_root": terminal[
                "events_content_root"
            ],
            "live_tracker_reads": False,
            "live_tracker_writes": False,
            "network_access": False,
        }
        fixture_replay_payloads = v2_bundle_payloads(
            mode="replay",
            subject_mode="review-plan",
            artifact_root="target/v2-fixture",
            artifact_dir="replay-output",
            source=reconstructed[0],
            inventory=reconstructed[1],
            authority=reconstructed[2],
            review_plan=reconstructed[3],
            history=reconstructed[4],
            zero_sets=reconstructed[5],
            optional_payloads=reconstructed[6],
            reproduction=v2_reproduction_argv(
                mode="replay",
                artifact_root="target/v2-fixture",
                artifact_dir="replay-output",
                replay_input="review-plan-run",
            ),
            current_source_files=reconstructed[0]["captured"][
                "observation"
            ]["source_files"],
            replay_equivalence=fixture_replay_equivalence,
        )
        published_replay_terminal = strict_json_loads(
            fixture_replay_payloads["terminal.json"],
            label="fixture published replay terminal",
            require_canonical=True,
        )
        replay_result_seed = v2_rooted(
            {
                "schema": V2_REPLAY_RESULT_SCHEMA,
                "terminal": "Pass",
                "subject_mode": "review-plan",
                "artifact_dir": "target/v2-fixture/replay-output",
                "retained_terminal_root": terminal["semantic_root"],
                "replay_terminal_root": published_replay_terminal[
                    "semantic_root"
                ],
                "live_tracker_reads": False,
                "live_tracker_writes": False,
                "network_access": False,
                "no_claim": V2_REPLAY_RESULT_NO_CLAIM,
            }
        )
        def validate_fixture_replay_result(
            candidate: Mapping[str, Any],
        ) -> None:
            v2_validate_replay_result_document(
                candidate,
                published_terminal=published_replay_terminal,
            )

        validate_fixture_replay_result(replay_result_seed)
        checks.check(
            "replay-result-valid-closed-rooted",
            set(replay_result_seed) == V2_REPLAY_RESULT_FIELDS
            and replay_result_seed["schema"] == V2_REPLAY_RESULT_SCHEMA
            and replay_result_seed["semantic_root"]
            == semantic_root(
                {
                    key: value
                    for key, value in replay_result_seed.items()
                    if key != "semantic_root"
                }
            ),
            expected={
                "schema": V2_REPLAY_RESULT_SCHEMA,
                "fields": sorted(V2_REPLAY_RESULT_FIELDS),
                "rooted": True,
            },
            observed={
                "schema": replay_result_seed["schema"],
                "fields": sorted(replay_result_seed),
                "semantic_root": replay_result_seed["semantic_root"],
            },
        )

        def reroot_replay_result(
            field: str,
            value: Any = None,
            *,
            remove: bool = False,
        ) -> dict[str, Any]:
            candidate = strict_json_loads(
                canonical_bytes(replay_result_seed),
                label="v2 replay result mutation seed",
                require_canonical=True,
            )
            if type(candidate) is not dict:
                raise EvidenceFailed(
                    "v2 replay result mutation seed is not an exact object"
                )
            dict.pop(candidate, "semantic_root", None)
            if remove:
                dict.pop(candidate, field)
            else:
                candidate[field] = value
            return v2_rooted(candidate)

        def record_replay_result_refusal(
            check_id: str,
            candidate: Mapping[str, Any],
            *,
            contains: str,
        ) -> None:
            error = expect_error(
                EvidenceFailed,
                lambda: validate_fixture_replay_result(candidate),
                contains=contains,
            )
            checks.check(
                check_id,
                error.terminal == "EvidenceFailed"
                and contains in str(error),
                expected={
                    "terminal": "EvidenceFailed",
                    "diagnostic_contains": contains,
                },
                observed={
                    "terminal": error.terminal,
                    "diagnostic": str(error),
                },
            )

        record_replay_result_refusal(
            "replay-result-extra-field-refused",
            reroot_replay_result("unexpected", True),
            contains="non-closed schema",
        )
        record_replay_result_refusal(
            "replay-result-missing-field-refused",
            reroot_replay_result("network_access", remove=True),
            contains="non-closed schema",
        )
        record_replay_result_refusal(
            "replay-result-nonpass-refused",
            reroot_replay_result("terminal", "EvidenceFailed"),
            contains="contract differs",
        )
        record_replay_result_refusal(
            "replay-result-live-activity-claim-refused",
            reroot_replay_result("live_tracker_reads", True),
            contains="contract differs",
        )
        record_replay_result_refusal(
            "replay-result-unsafe-artifact-path-refused",
            reroot_replay_result(
                "artifact_dir",
                "../escaped-replay",
            ),
            contains="artifact directory is unsafe",
        )
        stale_replay_result = strict_json_loads(
            canonical_bytes(replay_result_seed),
            label="v2 replay result stale-root seed",
            require_canonical=True,
        )
        stale_replay_result["replay_terminal_root"] = semantic_root(
            {"fixture": "changed replay terminal"}
        )
        record_replay_result_refusal(
            "replay-result-stale-root-refused",
            stale_replay_result,
            contains="semantic_root",
        )
        published_binding_mutations = (
            (
                "replay_terminal_root",
                semantic_root({"fixture": "other published replay"}),
            ),
            (
                "retained_terminal_root",
                semantic_root({"fixture": "other retained terminal"}),
            ),
            (
                "artifact_dir",
                "target/v2-fixture/other-replay-output",
            ),
        )
        published_binding_errors = [
            expect_error(
                EvidenceFailed,
                lambda field=field, replacement=replacement: (
                    validate_fixture_replay_result(
                        reroot_replay_result(
                            field,
                            replacement,
                        )
                    )
                ),
                contains="differs from its published terminal",
            )
            for field, replacement in published_binding_mutations
        ]
        checks.check(
            "replay-result-published-terminal-bindings-refused",
            all(
                error.terminal == "EvidenceFailed"
                for error in published_binding_errors
            ),
            expected={
                field: "EvidenceFailed"
                for field, _ in published_binding_mutations
            },
            observed={
                field: error.terminal
                for (field, _), error in zip(
                    published_binding_mutations,
                    published_binding_errors,
                    strict=True,
                )
            },
        )

        def forbidden_replay_subprocess() -> None:
            with v2_offline_replay_scope():
                with v2_offline_replay_scope():
                    run_command(
                        (sys.executable, "-c", "print('must-not-run')"),
                        record_global_receipt=False,
                    )

        original_guard_runner = _run_command_unscoped
        guard_launcher_calls = 0

        def forbidden_guard_runner(
            _argv: Sequence[str],
            **_kwargs: Any,
        ) -> subprocess.CompletedProcess[str]:
            nonlocal guard_launcher_calls
            guard_launcher_calls += 1
            raise EvidenceFailed(
                "offline replay guard reached the forbidden launcher"
            )

        try:
            globals()["_run_command_unscoped"] = forbidden_guard_runner
            replay_guard_state_before = {
                "offline_replay_depth": _v2_offline_replay_depth,
                "active_subprocess_count": _v2_active_subprocesses,
                "command_receipt_count": len(_command_receipts),
                "forbidden_launcher_calls": guard_launcher_calls,
            }
            replay_guard_error = expect_error(
                EvidenceFailed,
                forbidden_replay_subprocess,
                contains="forbids run_command-routed subprocesses",
            )
            replay_guard_state_after = {
                "offline_replay_depth": _v2_offline_replay_depth,
                "active_subprocess_count": _v2_active_subprocesses,
                "command_receipt_count": len(_command_receipts),
                "forbidden_launcher_calls": guard_launcher_calls,
            }
            checks.check(
                "offline-replay-subprocess-guard-refuses",
                replay_guard_error.terminal == "EvidenceFailed"
                and "forbids run_command-routed subprocesses"
                in str(replay_guard_error)
                and replay_guard_state_after == replay_guard_state_before,
                expected={
                    "terminal": "EvidenceFailed",
                    "diagnostic_contains": (
                        "forbids run_command-routed subprocesses"
                    ),
                    "state_unchanged": True,
                },
                observed={
                    "terminal": replay_guard_error.terminal,
                    "diagnostic": str(replay_guard_error),
                    "state_before": replay_guard_state_before,
                    "state_after": replay_guard_state_after,
                },
            )
        finally:
            globals()["_run_command_unscoped"] = original_guard_runner

        original_unscoped_runner = _run_command_unscoped
        command_entered = threading.Event()
        release_command = threading.Event()
        command_thread_errors: list[BaseException] = []

        def blocking_unscoped_runner(
            argv: Sequence[str],
            **_kwargs: Any,
        ) -> subprocess.CompletedProcess[str]:
            command_entered.set()
            if not release_command.wait(5.0):
                raise EvidenceFailed(
                    "cross-thread subprocess fixture timed out"
                )
            return subprocess.CompletedProcess(
                args=list(argv),
                returncode=0,
                stdout="held-command-finished\n",
                stderr="",
            )

        def run_held_command() -> None:
            try:
                run_command(
                    (sys.executable, "-c", "print('fixture')"),
                    record_global_receipt=False,
                )
            except BaseException as error:
                command_thread_errors.append(error)

        def enter_replay_once() -> None:
            with v2_offline_replay_scope():
                pass

        command_thread = threading.Thread(
            target=run_held_command,
            name="v2-active-command-guard-fixture",
            daemon=True,
        )
        try:
            globals()["_run_command_unscoped"] = blocking_unscoped_runner
            command_thread.start()
            if not command_entered.wait(5.0):
                raise EvidenceFailed(
                    "cross-thread subprocess fixture did not enter"
                )
            replay_while_command_error = expect_error(
                EvidenceFailed,
                enter_replay_once,
                contains="cannot overlap an active subprocess",
            )
        finally:
            release_command.set()
            command_thread.join(5.0)
            globals()["_run_command_unscoped"] = original_unscoped_runner
        checks.check(
            "offline-replay-refuses-while-subprocess-active-cross-thread",
            replay_while_command_error.terminal == "EvidenceFailed"
            and not command_thread.is_alive()
            and command_thread_errors == []
            and _v2_offline_replay_depth == 0
            and _v2_active_subprocesses == 0,
            expected={
                "terminal": "EvidenceFailed",
                "thread_retired": True,
                "thread_errors": [],
                "scope_depth": 0,
                "active_subprocesses": 0,
            },
            observed={
                "terminal": replay_while_command_error.terminal,
                "thread_retired": not command_thread.is_alive(),
                "thread_errors": [
                    type(error).__name__ for error in command_thread_errors
                ],
                "scope_depth": _v2_offline_replay_depth,
                "active_subprocesses": _v2_active_subprocesses,
            },
        )

        replay_entered = threading.Event()
        release_replay = threading.Event()
        replay_thread_errors: list[BaseException] = []
        forbidden_launcher_calls = 0

        def hold_replay_scope() -> None:
            try:
                with v2_offline_replay_scope():
                    replay_entered.set()
                    if not release_replay.wait(5.0):
                        raise EvidenceFailed(
                            "cross-thread replay fixture timed out"
                        )
            except BaseException as error:
                replay_thread_errors.append(error)

        def counting_forbidden_launcher(
            argv: Sequence[str],
            **_kwargs: Any,
        ) -> subprocess.CompletedProcess[str]:
            nonlocal forbidden_launcher_calls
            forbidden_launcher_calls += 1
            return subprocess.CompletedProcess(
                args=list(argv),
                returncode=0,
                stdout="must-not-launch\n",
                stderr="",
            )

        replay_thread = threading.Thread(
            target=hold_replay_scope,
            name="v2-active-replay-guard-fixture",
            daemon=True,
        )
        try:
            globals()["_run_command_unscoped"] = counting_forbidden_launcher
            replay_thread.start()
            if not replay_entered.wait(5.0):
                raise EvidenceFailed(
                    "cross-thread replay fixture did not enter"
                )
            command_while_replay_error = expect_error(
                EvidenceFailed,
                lambda: run_command(
                    (sys.executable, "-c", "print('must-not-launch')"),
                    record_global_receipt=False,
                ),
                contains="forbids run_command-routed subprocesses",
            )
        finally:
            release_replay.set()
            replay_thread.join(5.0)
            globals()["_run_command_unscoped"] = original_unscoped_runner
        checks.check(
            "subprocess-refuses-before-launch-while-replay-active-cross-thread",
            command_while_replay_error.terminal == "EvidenceFailed"
            and forbidden_launcher_calls == 0
            and not replay_thread.is_alive()
            and replay_thread_errors == []
            and _v2_offline_replay_depth == 0
            and _v2_active_subprocesses == 0,
            expected={
                "terminal": "EvidenceFailed",
                "launcher_calls": 0,
                "thread_retired": True,
                "thread_errors": [],
                "scope_depth": 0,
                "active_subprocesses": 0,
            },
            observed={
                "terminal": command_while_replay_error.terminal,
                "launcher_calls": forbidden_launcher_calls,
                "thread_retired": not replay_thread.is_alive(),
                "thread_errors": [
                    type(error).__name__ for error in replay_thread_errors
                ],
                "scope_depth": _v2_offline_replay_depth,
                "active_subprocesses": _v2_active_subprocesses,
            },
        )
        post_guard = run_command(
            (sys.executable, "-c", "print('guard-restored')"),
            record_global_receipt=False,
        )
        checks.check(
            "offline-replay-guard-reentrant-exception-safe",
            _v2_offline_replay_depth == 0
            and _v2_active_subprocesses == 0
            and post_guard.returncode == 0
            and post_guard.stdout == "guard-restored\n",
            expected={
                "scope_depth": 0,
                "active_subprocesses": 0,
                "post_guard_stdout": "guard-restored\n",
            },
            observed={
                "scope_depth": _v2_offline_replay_depth,
                "active_subprocesses": _v2_active_subprocesses,
                "post_guard_returncode": post_guard.returncode,
                "post_guard_stdout_root": text_root(post_guard.stdout),
            },
        )
        source_seed = strict_json_loads(
            payloads["source-v2.json"],
            label="retained source mutation seed",
            require_canonical=True,
        )
        mutation_source_file_identities = [
            dict(row) for row in retained_source_file_identities
        ]

        def validate_retained_source(candidate: Mapping[str, Any]) -> None:
            v2_validate_source_document_against_source_files(
                candidate,
                mutation_source_file_identities,
            )

        def reroot_source_top(
            mutation: Callable[[dict[str, Any]], None],
        ) -> dict[str, Any]:
            candidate = strict_json_loads(
                canonical_bytes(source_seed),
                label="retained source top-level mutation",
                require_canonical=True,
            )
            candidate.pop("semantic_root", None)
            mutation(candidate)
            return v2_rooted(candidate)

        def reroot_source_capture(
            capture_name: str,
            mutation: Callable[[dict[str, Any]], None],
        ) -> dict[str, Any]:
            candidate = strict_json_loads(
                canonical_bytes(source_seed),
                label=f"retained source {capture_name} mutation",
                require_canonical=True,
            )
            candidate.pop("semantic_root", None)
            captured_document = dict(
                candidate["captured"][capture_name]
            )
            captured_document.pop("semantic_root", None)
            mutation(captured_document)
            captured_document = v2_rooted(captured_document)
            candidate["captured"][capture_name] = captured_document
            candidate["capture_roots"][capture_name] = (
                captured_document["semantic_root"]
            )
            return v2_rooted(candidate)

        def reroot_source_issue(
            mutation: Callable[[dict[str, Any]], None],
        ) -> dict[str, Any]:
            candidate = strict_json_loads(
                canonical_bytes(source_seed),
                label="retained source issue mutation",
                require_canonical=True,
            )
            candidate.pop("semantic_root", None)
            issue = dict(candidate["captured"]["all_issues"][0])
            mutation(issue)
            issue["source_issue_projection_root"] = semantic_root(
                {
                    key: value
                    for key, value in issue.items()
                    if key
                    not in {"no_claim", "source_issue_projection_root"}
                }
            )
            candidate["captured"]["all_issues"] = [issue]
            candidate["capture_roots"]["all_issues"] = semantic_root(
                candidate["captured"]["all_issues"]
            )
            return v2_rooted(candidate)

        source_no_claim = reroot_source_top(
            lambda row: row.__setitem__(
                "no_claim",
                "this source authorizes tracker mutation and release",
            )
        )
        checks.refuses(
            "rerooted-source-affirmative-no-claim-refused",
            InputRefused,
            lambda: validate_retained_source(source_no_claim),
            contains="invalid identity or authority",
        )
        observation_no_claim = reroot_source_capture(
            "observation",
            lambda row: row.__setitem__(
                "no_claim",
                "this observation authenticates identities and grants authority",
            ),
        )
        checks.refuses(
            "rerooted-observation-affirmative-no-claim-refused",
            InputRefused,
            lambda: validate_retained_source(observation_no_claim),
            contains="observation identity or capture contract",
        )
        issue_no_claim = reroot_source_issue(
            lambda row: row.__setitem__(
                "no_claim",
                "this tracker row proves implementation and ownership",
            )
        )
        checks.refuses(
            "rerooted-source-issue-affirmative-no-claim-refused",
            InputRefused,
            lambda: validate_retained_source(issue_no_claim),
            contains="invalid core scalars",
        )
        review_receipts_no_claim = reroot_source_capture(
            "review_receipts",
            lambda row: row.__setitem__(
                "no_claim",
                "these declarations authorize mutation and release",
            ),
        )
        checks.refuses(
            "rerooted-source-review-receipts-no-claim-refused",
            InputRefused,
            lambda: validate_retained_source(
                review_receipts_no_claim
            ),
            contains="identity or no-claim differs",
        )
        prior_campaign_no_claim = reroot_source_capture(
            "prior_campaign",
            lambda row: row.__setitem__(
                "no_claim",
