    elif slug == "mutation-dropped-duplicate-target":
        targets = [v2_synthetic_target(0), v2_synthetic_target(1)]
        exact_inventory = v2_synthetic_inventory(targets)
        exact_authority = v2_synthetic_authority(exact_inventory)
        plan, _ = v2_build_review_plan(
            exact_inventory,
            exact_authority,
            max_targets=10,
        )
        mutations: list[tuple[str, list[dict[str, Any]]]] = [
            ("dropped", plan["children"][:1]),
            ("duplicated", [*plan["children"], plan["children"][0]]),
        ]
        for label, children in mutations:
            mutated = dict(plan)
            mutated["children"] = children
            mutated = v2_rooted(mutated)
            checks.refuses(
                f"{label}-target",
                EvidenceFailed,
                lambda mutated=mutated: v2_validate_review_plan(
                    mutated,
                    exact_inventory,
                    exact_authority,
                ),
                contains="target mapping",
            )
        cross_lane_child = dict(plan["children"][0])
        cross_lane_child["priority"] = 4
        cross_lane_child = v2_rooted(cross_lane_child)
        cross_lane_plan = dict(plan)
        cross_lane_plan["children"] = [
            cross_lane_child,
            *plan["children"][1:],
        ]
        cross_lane_plan = v2_rooted(cross_lane_plan)
        checks.refuses(
            "cross-lane-substitution",
            EvidenceFailed,
            lambda: v2_validate_review_plan(
                cross_lane_plan,
                exact_inventory,
                exact_authority,
            ),
            contains="scalar or enum contract",
        )
        cross_lane_inventory = v2_synthetic_inventory(
            [
                v2_synthetic_target(
                    0,
                    issue_id="synthetic-cross-lane-0",
                    priority=2,
                ),
                v2_synthetic_target(
                    1,
                    issue_id="synthetic-cross-lane-1",
                    priority=4,
                ),
            ]
        )
        cross_lane_authority = v2_synthetic_authority(
            cross_lane_inventory
        )
        cross_lane_decisions = {
            row["target_id"]: row
            for row in cross_lane_authority["decisions"]
        }
        checks.refuses(
            "cross-lane-construction-refused-at-hard-partition",
            EvidenceFailed,
            lambda: v2_make_child(
                [
                    (
                        target,
                        cross_lane_decisions[target["id"]],
                    )
                    for target in cross_lane_inventory["rows"]
                ],
                packing_witness={
                    "semantic_root": V2_PACKING_PREFLIGHT_WITNESS_ROOT,
                },
            ),
            contains="hard partition",
        )
        mutable_bytes = bytearray(b"stable")
        before_byte_root = v2_state_projection_value(mutable_bytes)
        mutable_bytes[0] = ord("u")
        after_byte_root = v2_state_projection_value(mutable_bytes)
        mutable_bytes[0] = ord("s")
        checks.check(
            "bytearray-and-memoryview-state-is-content-bound",
            before_byte_root != after_byte_root
            and before_byte_root["byte_length"]
            == v2_state_projection_value(memoryview(mutable_bytes))[
                "byte_length"
            ]
            and before_byte_root["content_root"]
            == v2_state_projection_value(memoryview(mutable_bytes))[
                "content_root"
            ],
            expected="content mutation changes the projected root",
            observed={
                "before": before_byte_root,
                "after": after_byte_root,
                "restored_memoryview": v2_state_projection_value(
                    memoryview(mutable_bytes)
                ),
            },
        )
        mutation_probe = V2CheckCollector(
            "fixture-bytearray-mutation-probe",
            "fixture.bytearray-mutation-probe",
        )
        bytearray_mutation_callback_calls = 0

        def mutate_then_refuse() -> None:
            nonlocal bytearray_mutation_callback_calls
            bytearray_mutation_callback_calls += 1
            mutable_bytes[0] = ord("u")
            raise InputRefused("synthetic refusal after byte mutation")

        try:
            guard_error = expect_error(
                EvidenceFailed,
                lambda: mutation_probe.refuses(
                    "mutation-must-not-pass",
                    InputRefused,
                    mutate_then_refuse,
                ),
                contains=(
                    "operation protocol can dispatch user code for mode "
                    "store-subscript: builtins.bytearray"
                ),
            )
        finally:
            bytearray.__setitem__(mutable_bytes, 0, ord("s"))

        def capture_bytearray_default(
            _target: bytearray = mutable_bytes,
        ) -> None:
            raise InputRefused("synthetic captured bytearray refusal")

        bytearray_projection_before = v2_callback_refusal_projection(
            capture_bytearray_default,
            collector_rows=[],
        )
        bytearray.__setitem__(mutable_bytes, 0, ord("u"))
        try:
            bytearray_projection_after = v2_callback_refusal_projection(
                capture_bytearray_default,
                collector_rows=[],
            )
        finally:
            bytearray.__setitem__(mutable_bytes, 0, ord("s"))
        bytearray_projection_divergence = first_projection_divergence(
            bytearray_projection_before,
            bytearray_projection_after,
        )
        checks.check(
            "refusal-guard-detects-bytearray-mutation",
            guard_error.terminal == "EvidenceFailed"
            and bytearray_mutation_callback_calls == 0
            and len(mutation_probe.rows) == 0
            and bytearray_projection_divergence
            == (
                "$.automatic_callback_state."
                "referenced_default_parameters[0].state.content_root"
            )
            and bytes(bytearray.__iter__(mutable_bytes)) == b"stable",
            expected={
                "terminal": "EvidenceFailed",
                "dynamic_mutation_callback": "refused before execution",
                "captured_content_divergence": True,
                "state_restored": True,
            },
            observed={
                "terminal": guard_error.terminal,
                "callback_calls": bytearray_mutation_callback_calls,
                "collector_rows": len(mutation_probe.rows),
                "captured_content_divergence": (
                    bytearray_projection_divergence
                ),
                "projection_root_before": semantic_root(
                    bytearray_projection_before
                ),
                "projection_root_after": semantic_root(
                    bytearray_projection_after
                ),
                "state_restored": (
                    bytes(bytearray.__iter__(mutable_bytes)) == b"stable"
                ),
            },
        )

    elif slug == "fault-output-lock-export":
        publication_script_path = REPO_ROOT / SCRIPT_REL
        publication_scripts_path = REPO_ROOT / "scripts"
        publication_fixture_paths = (
            REPO_ROOT,
            publication_script_path,
            publication_scripts_path,
        )
        v2_check_fixture_resource_refusal(
            checks,
            "existing-output-reservation",
            EvidenceFailed,
            lambda: v2_fixture_require_selected_fresh_run_dir(
                REPO_ROOT,
                label="fixture guaranteed-existing root",
            ),
            contains="already exists",
            paths=publication_fixture_paths,
            operation_grants=(("fresh-run-dir-check", (REPO_ROOT,)),),
        )
        v2_check_fixture_resource_refusal(
            checks,
            "exclusive-writer-no-overwrite",
            EvidenceFailed,
            lambda: v2_fixture_write_selected_exclusive(
                publication_script_path,
                b"forbidden",
            ),
            contains="overwrite is forbidden",
            paths=publication_fixture_paths,
            operation_grants=((
                "exclusive-overwrite-refusal",
                (publication_script_path,),
            ),),
        )
        descriptor_leak_probe = V2CheckCollector(
            "fixture-resource-descriptor-leak-probe",
            "fixture.resource-descriptor-leak-probe",
        )
        leaked_descriptor_close_calls: list[int] = []
        original_leak_probe_close = os.close

        def observe_leaked_descriptor_close(descriptor: int) -> None:
            frame: types.FrameType | None = sys._getframe()
            for _depth in range(16):
                if frame is None:
                    break
                if (
                    frame.f_code
                    is v2_fixture_selected_resource_scope_leave.__code__
                ):
                    list.append(leaked_descriptor_close_calls, descriptor)
                    break
                frame = frame.f_back
            original_leak_probe_close(descriptor)

        def leak_descriptor_then_refuse() -> None:
            v2_fixture_open_selected_read_descriptor(
                publication_script_path
            )
            raise EvidenceFailed("synthetic descriptor leak refusal")

        os.close = observe_leaked_descriptor_close
        try:
            descriptor_leak_error = expect_error(
                EvidenceFailed,
                lambda: v2_check_fixture_resource_refusal(
                    descriptor_leak_probe,
                    "descriptor-leak-must-fail",
                    EvidenceFailed,
                    leak_descriptor_then_refuse,
                    contains="synthetic descriptor leak",
                    paths=publication_fixture_paths,
                    operation_grants=((
                        "open-read-descriptor",
                        (publication_script_path,),
                    ),),
                ),
                contains="descriptor-leak-must-fail failed",
            )
        finally:
            os.close = original_leak_probe_close
        descriptor_probe_calls: list[str] = []

        def fallback_descriptor_census(directory: str) -> list[str]:
            descriptor_probe_calls.append(directory)
            if directory == "/synthetic-primary-fd":
                raise OSError(errno.ENOENT, "synthetic unavailable census")
            return ["7", "8"]

        fallback_descriptor_source, fallback_descriptor_names = (
            v2_fixture_descriptor_names(
                ("/synthetic-primary-fd", "/synthetic-secondary-fd"),
                list_directory=fallback_descriptor_census,
            )
        )

        def missing_descriptor_census(_directory: str) -> list[str]:
            raise OSError(errno.ENOENT, "synthetic unavailable census")

        missing_descriptor_census_error = expect_error(
            InfrastructureFailed,
            lambda: v2_fixture_descriptor_names(
                ("/synthetic-primary-fd", "/synthetic-secondary-fd"),
                list_directory=missing_descriptor_census,
            ),
            contains="descriptor census is unavailable on this host",
        )

        def failed_descriptor_census(_directory: str) -> list[str]:
            raise OSError(errno.EIO, "synthetic census failure")

        failed_descriptor_census_error = expect_error(
            InfrastructureFailed,
            lambda: v2_fixture_descriptor_names(
                ("/synthetic-primary-fd",),
                list_directory=failed_descriptor_census,
            ),
            contains="descriptor census failed",
        )
        checks.check(
            "resource-refusal-fingerprint-detects-descriptor-leak",
            descriptor_leak_error.terminal == "EvidenceFailed"
            and len(descriptor_leak_probe.rows) == 1
            and descriptor_leak_probe.rows[0]["passed"] is False
            and len(leaked_descriptor_close_calls) == 1
            and v2_fixture_selected_resource_scope_is_pristine()
            and descriptor_probe_calls
            == ["/synthetic-primary-fd", "/synthetic-secondary-fd"]
            and fallback_descriptor_source == "/synthetic-secondary-fd"
            and fallback_descriptor_names == ["7", "8"]
            and missing_descriptor_census_error.terminal
            == "InfrastructureFailed"
            and failed_descriptor_census_error.terminal
            == "InfrastructureFailed",
            expected={
                "terminal": "EvidenceFailed",
                "probe_passed": False,
                "leaked_descriptor_count": 1,
                "fixture_cleanup_close_attempts": 1,
                "descriptor_fallback_calls": [
                    "/synthetic-primary-fd",
                    "/synthetic-secondary-fd",
                ],
                "descriptor_fallback_source": "/synthetic-secondary-fd",
                "descriptor_fallback_names": ["7", "8"],
                "missing_descriptor_directory": "InfrastructureFailed",
                "failed_descriptor_census": "InfrastructureFailed",
            },
            observed={
                "terminal": descriptor_leak_error.terminal,
                "probe_passed": descriptor_leak_probe.rows[0]["passed"],
                "leaked_descriptor_count": len(
                    leaked_descriptor_close_calls
                ),
                "fixture_cleanup_close_calls": leaked_descriptor_close_calls,
                "scope_pristine": (
                    v2_fixture_selected_resource_scope_is_pristine()
                ),
                "descriptor_fallback_calls": descriptor_probe_calls,
                "descriptor_fallback_source": fallback_descriptor_source,
                "descriptor_fallback_names": fallback_descriptor_names,
                "missing_descriptor_directory": (
                    missing_descriptor_census_error.terminal
                ),
                "failed_descriptor_census": (
                    failed_descriptor_census_error.terminal
                ),
            },
        )

        scope_token_slot: list[Any] = [None]
        scope_token = v2_fixture_selected_resource_scope_enter(
            publication_fixture_paths,
            publication_fixture_paths,
            (
                (
                    "process-cwd",
                    (publication_scripts_path,),
                ),
                (
                    "strict-read",
                    (publication_script_path,),
                ),
                ("race-pristine-observation", None),
