            "fixture-resource-baseline-failure-probe",
            "fixture.resource-baseline-failure-probe",
        )
        baseline_owned_descriptor: int | None = None
        baseline_descriptor_close_calls: list[int] = []
        baseline_callback_called = False
        original_baseline_close = os.close

        def observe_baseline_descriptor_close(descriptor: int) -> None:
            if descriptor == baseline_owned_descriptor:
                list.append(baseline_descriptor_close_calls, descriptor)
            original_baseline_close(descriptor)

        def fail_after_baseline_scope_enter(
            _paths: Sequence[Path],
            *,
            additional_state: Callable[[], Any] | None = None,
        ) -> dict[str, Any]:
            nonlocal baseline_owned_descriptor
            _ = additional_state
            reservation_slot: list[Any] = [None]
            reservation: list[Any] | None = None
            reservation_settled = False
            try:
                reservation = v2_fixture_reserve_selected_owned_descriptor(
                    _reservation_slot=reservation_slot,
                )
                baseline_flags = (
                    os.O_RDONLY
                    | os.O_DIRECTORY
                    | os.O_CLOEXEC
                    | os.O_NOFOLLOW
                )
                list.__setitem__(reservation, 0, os.open(REPO_ROOT, baseline_flags))
            except BaseException:
                retained_reservation = list.__getitem__(
                    reservation_slot,
                    0,
                )
                if type(retained_reservation) is list:
                    v2_fixture_cancel_selected_owned_descriptor_reservation(
                        retained_reservation
                    )
                    list.__setitem__(reservation_slot, 0, None)
                raise
            try:
                baseline_owned_descriptor = (
                    v2_fixture_register_selected_owned_descriptor(
                        reservation
                    )
                )
                reservation_settled = True
                list.__setitem__(reservation_slot, 0, None)
            except BaseException:
                retained_reservation = list.__getitem__(
                    reservation_slot,
                    0,
                )
                if not reservation_settled and type(retained_reservation) is list:
                    try:
                        v2_fixture_cancel_selected_owned_descriptor_reservation(
                            retained_reservation
                        )
                        list.__setitem__(reservation_slot, 0, None)
                    except BaseException:
                        pass
                raise
            raise EvidenceFailed(
                "synthetic baseline capture failed after scope enter"
            )

        def baseline_callback_must_not_run() -> None:
            nonlocal baseline_callback_called
            baseline_callback_called = True
            raise EvidenceFailed("baseline callback unexpectedly ran")

        globals()["v2_fixture_resource_state"] = (
            fail_after_baseline_scope_enter
        )
        os.close = observe_baseline_descriptor_close
        try:
            baseline_capture_error = expect_error(
                EvidenceFailed,
                lambda: v2_check_fixture_resource_refusal(
                    baseline_failure_probe,
                    "baseline-capture-must-refuse",
                    EvidenceFailed,
                    baseline_callback_must_not_run,
                    contains="baseline callback unexpectedly ran",
                    paths=publication_fixture_paths,
                    operation_grants=(),
                ),
                contains=(
                    "synthetic baseline capture failed after scope enter"
                ),
            )
        finally:
            globals()["v2_fixture_resource_state"] = (
                original_baseline_resource_state
            )
            os.close = original_baseline_close

        transaction_pretry_primary = RuntimeError(
            "synthetic transaction post-enter interruption"
        )
        prior_transaction_pretry_trace = sys.gettrace()

        def interrupt_transaction_after_scope_enter(
            frame: types.FrameType,
            event: str,
            _argument: Any,
        ) -> Any:
            if (
                event == "line"
                and frame.f_code
                is _v2_check_fixture_resource_refusal_transaction.__code__
                and type(frame.f_locals.get(
                    "selected_resource_scope_token_slot"
                )) is list
                and type(list.__getitem__(frame.f_locals.get(
                    "selected_resource_scope_token_slot"
                ), 0)) is list
                and frame.f_locals.get("before_state") is None
            ):
                sys.settrace(None)
                raise transaction_pretry_primary
            return interrupt_transaction_after_scope_enter

        transaction_pretry_observed: BaseException | None = None
        sys.settrace(interrupt_transaction_after_scope_enter)
        try:
            _v2_check_fixture_resource_refusal_transaction(
                V2CheckCollector(
                    "fixture-resource-transaction-pretry-probe",
                    "fixture.resource.transaction-pretry-probe",
                ),
                "transaction-pretry-must-unwind",
                EvidenceFailed,
                lambda: (_ for _ in ()).throw(
                    EvidenceFailed("unreachable transaction callback")
                ),
                contains="unreachable transaction callback",
                paths=(),
                operation_grants=(),
            )
        except BaseException as error:
            transaction_pretry_observed = error
            error.__traceback__ = None
        finally:
            sys.settrace(prior_transaction_pretry_trace)
        transaction_pretry_scope_pristine = (
            v2_fixture_selected_resource_scope_is_pristine()
        )
        pre_registration_callbacks: list[str] = []
        duplicate_enter_probe = V2CheckCollector(
            "fixture-resource-duplicate-enter-probe",
            "fixture.resource.duplicate-enter-probe",
        )
        duplicate_enter_error = expect_error(
            EvidenceFailed,
            lambda: _v2_check_fixture_resource_refusal_transaction(
                duplicate_enter_probe,
                "duplicate-enter-must-preserve-primary",
                EvidenceFailed,
                lambda: list.append(
                    pre_registration_callbacks,
                    "duplicate-enter",
                ),
                contains="unreachable duplicate-enter callback",
                paths=(
                    publication_script_path,
                    publication_script_path,
                ),
                operation_grants=(),
            ),
            contains=(
                "scope paths are duplicate or not fully state-bound"
            ),
        )
        unbound_grant_probe = V2CheckCollector(
            "fixture-resource-unbound-grant-probe",
            "fixture.resource.unbound-grant-probe",
        )
        unbound_grant_error = expect_error(
            EvidenceFailed,
            lambda: _v2_check_fixture_resource_refusal_transaction(
                unbound_grant_probe,
                "unbound-grant-must-preserve-primary",
                EvidenceFailed,
                lambda: list.append(
                    pre_registration_callbacks,
                    "unbound-grant",
                ),
                contains="unreachable unbound-grant callback",
                paths=publication_fixture_paths,
                operation_grants=((
                    "strict-read",
                    (
                        REPO_ROOT
                        / "synthetic-unselected-operation-grant-probe",
                    ),
                ),),
            ),
            contains=(
                "operation grant paths are duplicate, unselected, or not "
                "state-bound"
            ),
        )
        pre_registration_scope_pristine = (
            v2_fixture_selected_resource_scope_is_pristine()
        )
        original_process_observation = (
            v2_capture_fixture_process_observation
        )
        baseline_mismatch_capture_calls = 0
        baseline_mismatch_callback_called = False
        baseline_mismatch_probe = V2CheckCollector(
            "fixture-resource-double-baseline-mismatch-probe",
            "fixture.resource.double-baseline-mismatch-probe",
        )

        def mismatching_process_observation() -> dict[str, Any]:
            nonlocal baseline_mismatch_capture_calls
            baseline_mismatch_capture_calls += 1
            observation = original_process_observation()
            if baseline_mismatch_capture_calls == 2:
                observation = dict(observation)
                observation["recursion_limit"] += 1
            return observation

        def baseline_mismatch_callback() -> None:
            nonlocal baseline_mismatch_callback_called
            baseline_mismatch_callback_called = True
            raise EvidenceFailed("baseline mismatch callback unexpectedly ran")

        globals()["v2_capture_fixture_process_observation"] = (
            mismatching_process_observation
        )
        try:
            baseline_mismatch_error = expect_error(
                EvidenceFailed,
                lambda: v2_check_fixture_resource_refusal(
                    baseline_mismatch_probe,
                    "double-baseline-mismatch-must-refuse",
                    EvidenceFailed,
                    baseline_mismatch_callback,
                    contains="baseline mismatch callback unexpectedly ran",
                    paths=publication_fixture_paths,
                    operation_grants=(),
                ),
                contains="baseline changed between captures",
            )
        finally:
            globals()["v2_capture_fixture_process_observation"] = (
                original_process_observation
            )
        checks.check(
            "resource-baseline-capture-failure-unwinds-scope",
            baseline_capture_error.terminal == "EvidenceFailed"
            and not baseline_callback_called
            and baseline_failure_probe.rows == []
            and baseline_owned_descriptor is not None
            and baseline_descriptor_close_calls
            == [baseline_owned_descriptor]
            and transaction_pretry_observed is transaction_pretry_primary
            and transaction_pretry_scope_pristine
            and duplicate_enter_error.terminal == "EvidenceFailed"
            and unbound_grant_error.terminal == "EvidenceFailed"
            and pre_registration_callbacks == []
            and duplicate_enter_probe.rows == []
            and unbound_grant_probe.rows == []
            and pre_registration_scope_pristine
            and baseline_mismatch_error.terminal == "EvidenceFailed"
            and baseline_mismatch_capture_calls == 2
            and not baseline_mismatch_callback_called
            and baseline_mismatch_probe.rows == []
            and v2_fixture_selected_resource_scope_is_pristine(),
            expected={
                "terminal": "EvidenceFailed",
                "callback_called": False,
                "probe_rows": [],
                "owned_descriptor_close_attempts": 1,
                "post_enter_interruption": (
                    "raw-primary-preserved-and-scope-left"
                ),
                "pre_registration_failures": {
                    "duplicate_paths": "original EvidenceFailed",
                    "unbound_grant": "original EvidenceFailed",
                    "callbacks_called": [],
                    "collector_rows": [],
                },
                "double_coherent_baseline_mismatch": {
                    "captures": 2,
                    "callback_called": False,
                    "collector_rows": [],
                },
                "scope_pristine": True,
            },
            observed={
                "terminal": baseline_capture_error.terminal,
                "callback_called": baseline_callback_called,
                "probe_rows": baseline_failure_probe.rows,
                "owned_descriptor_close_calls": (
                    baseline_descriptor_close_calls
                ),
                "post_enter_interruption": {
                    "primary_preserved": (
                        transaction_pretry_observed
                        is transaction_pretry_primary
                    ),
                    "scope_pristine": transaction_pretry_scope_pristine,
                },
                "pre_registration_failures": {
                    "duplicate_paths": duplicate_enter_error.terminal,
                    "unbound_grant": unbound_grant_error.terminal,
                    "callbacks_called": pre_registration_callbacks,
                    "collector_rows": [
                        len(duplicate_enter_probe.rows),
                        len(unbound_grant_probe.rows),
                    ],
                    "scope_pristine": pre_registration_scope_pristine,
                },
                "double_coherent_baseline_mismatch": {
                    "terminal": baseline_mismatch_error.terminal,
                    "captures": baseline_mismatch_capture_calls,
                    "callback_called": baseline_mismatch_callback_called,
                    "collector_rows": baseline_mismatch_probe.rows,
                },
                "scope_pristine": (
                    v2_fixture_selected_resource_scope_is_pristine()
                ),
            },
        )

        original_resource_transaction = (
            _v2_check_fixture_resource_refusal_transaction
        )
        transaction_entries: list[str] = []
        transaction_thread_errors: list[str] = []
        first_transaction_entered = threading.Event()
        release_first_transaction = threading.Event()
        second_transaction_attempted = threading.Event()

        def synthetic_resource_transaction(
            _checks: V2CheckCollector,
            check_id: str,
            *_args: Any,
            **_kwargs: Any,
        ) -> None:
            list.append(transaction_entries, f"enter:{check_id}")
            if check_id == "first":
                first_transaction_entered.set()
                if not release_first_transaction.wait(timeout=5):
                    raise RuntimeError(
                        "synthetic transaction release timed out"
                    )
            list.append(transaction_entries, f"exit:{check_id}")

        def invoke_synthetic_resource_transaction(check_id: str) -> None:
            try:
                v2_check_fixture_resource_refusal(
                    checks,
                    check_id,
                    EvidenceFailed,
                    lambda: None,
                    contains="unused",
                    paths=(),
                    operation_grants=(),
                )
            except BaseException as error:
                list.append(
                    transaction_thread_errors,
                    v2_raw_type_name(type(error)),
                )

        def invoke_second_synthetic_resource_transaction() -> None:
            second_transaction_attempted.set()
            invoke_synthetic_resource_transaction("second")

        globals()[
            "_v2_check_fixture_resource_refusal_transaction"
        ] = synthetic_resource_transaction
        first_transaction_thread = threading.Thread(
            target=lambda: invoke_synthetic_resource_transaction("first"),
        )
        second_transaction_thread = threading.Thread(
            target=invoke_second_synthetic_resource_transaction,
        )
        first_transaction_started = False
        second_transaction_started = False
        first_entered_in_time = False
        second_attempted_in_time = False
        serialized_prefix: list[str] = []
        try:
            first_transaction_thread.start()
            first_transaction_started = True
            first_entered_in_time = first_transaction_entered.wait(timeout=5)
            second_transaction_thread.start()
            second_transaction_started = True
            second_attempted_in_time = second_transaction_attempted.wait(
                timeout=5
            )
            serialized_prefix = list(transaction_entries)
            release_first_transaction.set()
        finally:
            release_first_transaction.set()
            if first_transaction_started:
                first_transaction_thread.join(timeout=5)
            if second_transaction_started:
                second_transaction_thread.join(timeout=5)
            globals()[
                "_v2_check_fixture_resource_refusal_transaction"
            ] = original_resource_transaction

        failure_cleanup_entered = threading.Event()
        failure_cleanup_release = threading.Event()
        failure_cleanup_primary = RuntimeError(
            "synthetic transaction orchestration failure"
        )

        def synthetic_failure_cleanup_transaction(
            *_args: Any,
            **_kwargs: Any,
        ) -> None:
            failure_cleanup_entered.set()
            if not failure_cleanup_release.wait(timeout=5):
                raise RuntimeError(
                    "synthetic failure cleanup release timed out"
                )

        globals()[
            "_v2_check_fixture_resource_refusal_transaction"
        ] = synthetic_failure_cleanup_transaction
        failure_cleanup_thread = threading.Thread(
            target=lambda: invoke_synthetic_resource_transaction(
                "failure-cleanup"
            ),
        )
        failure_cleanup_started = False
        failure_cleanup_entered_in_time = False
        failure_cleanup_observed: BaseException | None = None
        try:
            failure_cleanup_thread.start()
            failure_cleanup_started = True
            failure_cleanup_entered_in_time = (
                failure_cleanup_entered.wait(timeout=5)
            )
            raise failure_cleanup_primary
        except BaseException as error:
            failure_cleanup_observed = error
        finally:
            failure_cleanup_release.set()
            if failure_cleanup_started:
                failure_cleanup_thread.join(timeout=5)
            globals()[
                "_v2_check_fixture_resource_refusal_transaction"
            ] = original_resource_transaction

        generic_refusal_projection = v2_callback_refusal_projection
        generic_refusal_entries: list[str] = []
        generic_refusal_errors: list[str] = []
        generic_first_entered = threading.Event()
        generic_release_first = threading.Event()
        generic_second_attempted = threading.Event()
        generic_first_collector = V2CheckCollector(
            "generic-refusal-serialization-first",
            "generic.refusal.serialization.first",
        )
        generic_second_collector = V2CheckCollector(
            "generic-refusal-serialization-second",
            "generic.refusal.serialization.second",
        )
        generic_process_baseline = (
            v2_capture_double_coherent_fixture_process_baseline()
        )

        def first_serialized_refusal() -> None:
            raise InputRefused("synthetic first serialized refusal")

        def second_serialized_refusal() -> None:
            raise InputRefused("synthetic second serialized refusal")

        def synthetic_serialized_refusal_projection(
            callback: Callable[[], Any],
            *,
            collector_rows: Sequence[Mapping[str, Any]],
            authorized_external_capabilities: frozenset[str],
        ) -> dict[str, Any]:
            del collector_rows, authorized_external_capabilities
            callback_label = (
                "first"
                if callback is first_serialized_refusal
                else "second"
            )
            list.append(
                generic_refusal_entries,
                f"projection:{callback_label}",
            )
            if (
                callback is first_serialized_refusal
                and generic_refusal_entries == ["projection:first"]
            ):
                generic_first_entered.set()
                if not generic_release_first.wait(timeout=5):
                    raise RuntimeError(
                        "synthetic generic refusal release timed out"
                    )
            return {"callback": callback_label}

        def invoke_generic_refusal(
            collector: V2CheckCollector,
            check_id: str,
            callback: Callable[[], Any],
        ) -> None:
            try:
                collector.refuses(
                    check_id,
                    InputRefused,
                    callback,
                    contains=f"synthetic {check_id} serialized refusal",
                )
            except BaseException as error:
                list.append(
                    generic_refusal_errors,
                    v2_raw_type_name(type(error)),
                )

        def invoke_second_generic_refusal() -> None:
            generic_second_attempted.set()
            invoke_generic_refusal(
                generic_second_collector,
                "second",
                second_serialized_refusal,
            )

        globals()["v2_callback_refusal_projection"] = (
            synthetic_serialized_refusal_projection
        )
        generic_first_thread = threading.Thread(
            target=lambda: invoke_generic_refusal(
                generic_first_collector,
                "first",
                first_serialized_refusal,
            ),
        )
        generic_second_thread = threading.Thread(
            target=invoke_second_generic_refusal,
        )
        generic_prefix: list[str] = []
        generic_first_entered_in_time = False
        generic_second_attempted_in_time = False
        try:
            generic_first_thread.start()
            generic_first_entered_in_time = generic_first_entered.wait(
                timeout=5
            )
            generic_second_thread.start()
            generic_second_attempted_in_time = (
                generic_second_attempted.wait(timeout=5)
            )
            generic_prefix = list(generic_refusal_entries)
            generic_release_first.set()
        finally:
            generic_release_first.set()
            generic_first_thread.join(timeout=5)
            generic_second_thread.join(timeout=5)
            globals()["v2_callback_refusal_projection"] = (
                generic_refusal_projection
            )
        generic_process_after = (
            v2_capture_double_coherent_fixture_process_baseline()
        )
        generic_process_state_unchanged = (
            v2_fixture_process_observations_match(
                generic_process_baseline,
                generic_process_after,
            )
        )
        checks.check(
            "selected-resource-transactions-serialize-across-threads",
            first_entered_in_time
            and second_attempted_in_time
            and serialized_prefix == ["enter:first"]
            and transaction_entries
            == [
                "enter:first",
                "exit:first",
                "enter:second",
                "exit:second",
            ]
            and not first_transaction_thread.is_alive()
            and not second_transaction_thread.is_alive()
            and failure_cleanup_entered_in_time
            and failure_cleanup_observed is failure_cleanup_primary
            and not failure_cleanup_thread.is_alive()
            and _v2_check_fixture_resource_refusal_transaction
            is original_resource_transaction
            and transaction_thread_errors == []
            and generic_first_entered_in_time
            and generic_second_attempted_in_time
            and generic_prefix == ["projection:first"]
            and generic_refusal_entries
            == [
                "projection:first",
                "projection:first",
                "projection:second",
                "projection:second",
            ]
            and not generic_first_thread.is_alive()
            and not generic_second_thread.is_alive()
            and generic_refusal_errors == []
            and len(generic_first_collector.rows) == 1
            and generic_first_collector.rows[0]["passed"] is True
            and len(generic_second_collector.rows) == 1
            and generic_second_collector.rows[0]["passed"] is True
            and generic_process_state_unchanged,
            expected={
                "prefix_while_second_waits": ["enter:first"],
                "ordered_entries": [
                    "enter:first",
                    "exit:first",
                    "enter:second",
                    "exit:second",
                ],
                "failure_path_cleanup": (
                    "primary-preserved-thread-joined-global-restored"
                ),
                "generic_refusal_transactions": (
                    "serialized-with-exact-process-state-restoration"
                ),
                "thread_errors": [],
            },
            observed={
                "first_entered_in_time": first_entered_in_time,
                "second_attempted_in_time": second_attempted_in_time,
                "prefix_while_second_waits": serialized_prefix,
                "ordered_entries": transaction_entries,
                "threads_alive": [
                    first_transaction_thread.is_alive(),
                    second_transaction_thread.is_alive(),
                ],
                "failure_path_cleanup": {
                    "entered_in_time": failure_cleanup_entered_in_time,
                    "primary_preserved": (
                        failure_cleanup_observed is failure_cleanup_primary
                    ),
                    "thread_alive": failure_cleanup_thread.is_alive(),
                    "global_restored": (
                        _v2_check_fixture_resource_refusal_transaction
                        is original_resource_transaction
                    ),
                },
                "generic_refusal_transactions": {
                    "first_entered_in_time": generic_first_entered_in_time,
                    "second_attempted_in_time": (
                        generic_second_attempted_in_time
                    ),
                    "prefix_while_second_waits": generic_prefix,
                    "ordered_entries": generic_refusal_entries,
                    "thread_errors": generic_refusal_errors,
                    "threads_alive": [
                        generic_first_thread.is_alive(),
                        generic_second_thread.is_alive(),
                    ],
                    "collector_passed": [
                        generic_first_collector.rows[0]["passed"],
                        generic_second_collector.rows[0]["passed"],
                    ],
                    "process_state_unchanged": (
                        generic_process_state_unchanged
                    ),
                },
                "thread_errors": transaction_thread_errors,
            },
        )

        permission_fallback_calls: list[str] = []

        def permission_fallback_descriptor_census(
            directory: str,
        ) -> list[str]:
            list.append(permission_fallback_calls, directory)
            if directory == "/synthetic-permission-fd":
                raise OSError(errno.EPERM, "synthetic restricted census")
            return []

        permission_fallback_source, permission_fallback_names = (
            v2_fixture_descriptor_names(
                (
                    "/synthetic-permission-fd",
                    "/synthetic-permission-fallback-fd",
                ),
                list_directory=permission_fallback_descriptor_census,
            )
        )
        malformed_descriptor_listing_error = expect_error(
            InfrastructureFailed,
            lambda: v2_fixture_descriptor_names(
                ("/synthetic-malformed-fd",),
                list_directory=lambda _directory: ("7",),  # type: ignore[arg-type]
            ),
            contains="returned malformed names",
        )
        original_descriptor_name_provider = v2_fixture_descriptor_names
        original_descriptor_fstat = os.fstat
        descriptor_fstat_calls: list[int] = []

        def closed_synthetic_descriptor(descriptor: int) -> Any:
            list.append(descriptor_fstat_calls, descriptor)
            raise OSError(errno.EBADF, "synthetic closed descriptor")

        descriptor_name_errors: dict[str, str] = {}
        try:
            os.fstat = closed_synthetic_descriptor
            globals()["v2_fixture_descriptor_names"] = (
                lambda: (
                    "/synthetic-descriptor-fd",
                    [str(V2_FIXTURE_RESOURCE_DESCRIPTOR_MAX)],
                )
            )
            exact_max_descriptor_projection = v2_fixture_resource_state([])
            for descriptor_label, descriptor_names in (
                ("empty", [""]),
                ("nondigit", ["descriptor"]),
                ("leading-zero", ["00"]),
                ("duplicate", ["7", "7"]),
                (
                    "max-plus-one",
                    [str(V2_FIXTURE_RESOURCE_DESCRIPTOR_MAX + 1)],
                ),
                ("very-long", ["9" * 10_000]),
            ):
                globals()["v2_fixture_descriptor_names"] = (
                    lambda names=descriptor_names: (
                        "/synthetic-descriptor-fd",
                        names,
                    )
                )
                descriptor_name_error = expect_error(
                    InfrastructureFailed,
                    lambda: v2_fixture_resource_state([]),
                    contains="returned a malformed name",
                )
                dict.__setitem__(
                    descriptor_name_errors,
                    descriptor_label,
                    descriptor_name_error.terminal,
                )
        finally:
            globals()["v2_fixture_descriptor_names"] = (
                original_descriptor_name_provider
            )
            os.fstat = original_descriptor_fstat
        checks.check(
            "descriptor-census-name-and-errno-bounds",
            permission_fallback_calls
            == [
                "/synthetic-permission-fd",
                "/synthetic-permission-fallback-fd",
            ]
            and permission_fallback_source
            == "/synthetic-permission-fallback-fd"
            and permission_fallback_names == []
            and malformed_descriptor_listing_error.terminal
            == "InfrastructureFailed"
            and exact_max_descriptor_projection["open_descriptors"] == []
            and descriptor_fstat_calls
