            def exercise_single_parent_close_attempt(
                callback: Callable[[], Any],
                *,
                diagnostic: str,
            ) -> dict[str, Any]:
                root_descriptor: int | None = None
                close_calls: list[int] = []

                def tracked_open(
                    path: Any,
                    flags: int,
                    *args: Any,
                    **kwargs: Any,
                ) -> int:
                    nonlocal root_descriptor
                    descriptor = original_resource_open(
                        path,
                        flags,
                        *args,
                        **kwargs,
                    )
                    if path == REPO_ROOT and kwargs.get("dir_fd") is None:
                        root_descriptor = descriptor
                    return descriptor

                def fail_once_after_parent_close(descriptor: int) -> None:
                    list.append(close_calls, descriptor)
                    original_resource_close(descriptor)
                    if descriptor == root_descriptor:
                        raise OSError(
                            errno.EIO,
                            "synthetic ownership-transfer close failure",
                        )

                os.open = tracked_open
                os.close = fail_once_after_parent_close
                try:
