            def interrupt_selected_handoff(
                frame: types.FrameType,
                event: str,
                _argument: Any,
            ) -> Any:
                if (
                    event == "line"
                    and frame.f_code
                    is _v2_fixture_open_anchored_parent_owned.__code__
                ):
                    frame_locals = frame.f_locals
                    descriptor_slot = frame_locals.get(
                        "descriptor_slot",
                    )
                    child_slot = frame_locals.get("child_slot")
                    slot_owned = [
                        descriptor
                        for slot in (descriptor_slot, child_slot)
                        if type(slot) is list
                        and len(slot) == 1
                        for descriptor in (list.__getitem__(slot, 0),)
                        if type(descriptor) is int
                    ]
                    unowned = [
                        descriptor
                        for descriptor in selected_handoff_opened
                        if descriptor not in selected_handoff_closed
                        and descriptor not in slot_owned
                    ]
                    if unowned:
                        sys.settrace(None)
                        for descriptor in unowned:
                            tracked_selected_handoff_close(descriptor)
                        raise selected_handoff_gap
                    if (
                        type(descriptor_slot) is list
                        and len(descriptor_slot) == 1
                        and list.__getitem__(descriptor_slot, 0) is None
                        and type(child_slot) is list
                        and len(child_slot) == 1
                        and type(list.__getitem__(child_slot, 0)) is int
                        and frame_locals.get(
                            "close_failure",
                        )
                        is None
                    ):
                        sys.settrace(None)
                        raise selected_handoff_primary
                return interrupt_selected_handoff

            selected_handoff_observed: BaseException | None = None
            os.open = tracked_selected_handoff_open
            os.close = tracked_selected_handoff_close
            sys.settrace(interrupt_selected_handoff)
