                output_slot: list[int | None] = [None]
                primary = RuntimeError(
                    "synthetic selected-resource acquisition interruption"
                )
                ownership_gap = RuntimeError(
                    "synthetic selected-resource acquisition gap detected"
                )

                def tracked_open(
                    path: Any,
                    flags: int,
                    *args: Any,
                    **kwargs: Any,
                ) -> int:
                    descriptor = original_resource_open(
                        path,
                        flags,
                        *args,
                        **kwargs,
                    )
                    list.append(opened, descriptor)
                    return descriptor

                def tracked_close(descriptor: int) -> None:
                    list.append(closed, descriptor)
                    original_resource_close(descriptor)

                def interrupt_acquisition(
                    frame: types.FrameType,
                    event: str,
                    _argument: Any,
                ) -> Any:
                    if (
                        event == "line"
                        and frame.f_code
                        is _v2_fixture_open_anchored_parent_owned.__code__
                    ):
                        frame_locals = frame.f_locals
                        descriptor_slot = frame_locals.get(
                            "descriptor_slot",
                        )
                        child_slot = frame_locals.get("child_slot")
                        slot_owned = [
                            descriptor
                            for slot in (descriptor_slot, child_slot)
                            if type(slot) is list
                            and len(slot) == 1
                            for descriptor in (list.__getitem__(slot, 0),)
                            if type(descriptor) is int
                        ]
                        unowned = [
                            descriptor
                            for descriptor in opened
                            if descriptor not in closed
                            and descriptor not in slot_owned
                        ]
                        if unowned:
                            sys.settrace(None)
                            for descriptor in unowned:
                                tracked_close(descriptor)
                            raise ownership_gap
                        if (
                            acquisition_kind == "root"
                            and type(descriptor_slot) is list
                            and len(descriptor_slot) == 1
                            and type(list.__getitem__(descriptor_slot, 0))
                            is int
                            and type(child_slot) is list
                            and len(child_slot) == 1
                            and list.__getitem__(child_slot, 0) is None
                            and "current_descriptor" not in frame_locals
                            or acquisition_kind == "child"
                            and type(descriptor_slot) is list
                            and len(descriptor_slot) == 1
                            and type(list.__getitem__(descriptor_slot, 0))
                            is int
                            and type(child_slot) is list
                            and len(child_slot) == 1
                            and type(list.__getitem__(child_slot, 0)) is int
                            and "child_descriptor" not in frame_locals
                        ):
                            sys.settrace(None)
                            raise primary
                    return interrupt_acquisition

                observed: BaseException | None = None
                os.open = tracked_open
                os.close = tracked_close
                sys.settrace(interrupt_acquisition)
                try:
                    v2_fixture_open_anchored_parent(
                        selected_relative,
                        selected_parent_binding,
                        output_slot,
                    )
                except BaseException as error:
                    observed = error
                finally:
                    sys.settrace(prior_trace)
                    os.open = original_resource_open
                    os.close = original_resource_close
                return {
                    "primary_preserved": observed is primary,
                    "opened": opened,
                    "closed": closed,
                    "slot": output_slot,
                }

            selected_acquisition_rows = {
                acquisition_kind: exercise_selected_acquisition_interrupt(
                    acquisition_kind
                )
                for acquisition_kind in ("root", "child")
            }

            selected_directory_relative, selected_directory_binding = (
                v2_fixture_capture_anchored_resource_binding(
                    REPO_ROOT / "scripts"
                )
            )

            def exercise_selected_wrapper_true_return(
                wrapper_kind: str,
            ) -> dict[str, Any]:
                output_slot: list[int | None] = [None]
                opened: list[int] = []
                closed: list[int] = []
                return_arguments: list[Any] = []
                primary = RuntimeError(
                    "synthetic selected-resource wrapper true-return "
                    "interruption"
                )
                target = (
                    v2_fixture_open_anchored_parent
                    if wrapper_kind == "anchored-parent"
                    else v2_fixture_open_anchored_directory_descriptor
                )

                def tracked_open(
                    path: Any,
                    flags: int,
                    *args: Any,
                    **kwargs: Any,
                ) -> int:
                    descriptor = original_resource_open(
                        path,
                        flags,
                        *args,
                        **kwargs,
                    )
                    list.append(opened, descriptor)
                    return descriptor

                def tracked_close(descriptor: int) -> None:
                    list.append(closed, descriptor)
                    original_resource_close(descriptor)

                def interrupt_true_return(
                    frame: types.FrameType,
                    event: str,
                    argument: Any,
                ) -> Any:
                    if event == "return" and frame.f_code is target.__code__:
                        list.append(return_arguments, argument)
                        sys.settrace(None)
                        raise primary
                    return interrupt_true_return

                observed: BaseException | None = None
                os.open = tracked_open
                os.close = tracked_close
                sys.settrace(interrupt_true_return)
                try:
                    if wrapper_kind == "anchored-parent":
                        v2_fixture_open_anchored_parent(
                            selected_relative,
                            selected_parent_binding,
                            output_slot,
                        )
                    else:
                        v2_fixture_open_anchored_directory_descriptor(
                            selected_directory_relative,
                            selected_directory_binding,
                            output_slot,
                        )
                except BaseException as error:
                    observed = error
                finally:
                    sys.settrace(prior_trace)
                    os.open = original_resource_open
                retained_descriptor = list.__getitem__(output_slot, 0)
                retained_before_rescue = (
                    len(return_arguments) == 1
                    and type(retained_descriptor) is int
                    and retained_descriptor in opened
                    and opened.count(retained_descriptor)
                    == closed.count(retained_descriptor) + 1
                )
                try:
                    v2_close_owned_descriptor_slots((
                        (
                            output_slot,
                            EvidenceFailed(
                                "selected-resource true-return descriptor "
                                "close failed"
                            ),
                        ),
                    ), surface_failure=True)
                finally:
                    os.close = original_resource_close
                return {
                    "primary_preserved": observed is primary,
                    "return_event_count": len(return_arguments),
                    "retained_before_caller_rescue": retained_before_rescue,
                    "opened": opened,
                    "closed": closed,
                    "slot": output_slot,
                    "each_descriptor_closed_once": (
                        len(opened) == len(closed)
                        and Counter(opened) == Counter(closed)
                    ),
                }

            selected_wrapper_true_return_rows = {
                wrapper_kind: exercise_selected_wrapper_true_return(
                    wrapper_kind
                )
                for wrapper_kind in (
                    "anchored-parent",
                    "anchored-directory",
                )
            }

            selected_return_leaf_descriptor: int | None = None
            selected_return_close_calls: list[int] = []
            selected_return_primary = RuntimeError(
                "synthetic selected-resource return interruption"
            )
            selected_return_token_slot: list[Any] = [None]
            selected_return_token = (
                v2_fixture_selected_resource_scope_enter(
                    (selected_resource_path,),
                    (selected_resource_path,),
                    ((
                        "open-read-descriptor",
                        (selected_resource_path,),
                    ),),
                    _token_slot=selected_return_token_slot,
                )
            )
            selected_return_arguments: list[Any] = []

            def tracked_selected_return_open(
                path: Any,
                flags: int,
                *args: Any,
                **kwargs: Any,
            ) -> int:
                nonlocal selected_return_leaf_descriptor
                descriptor = original_resource_open(
                    path,
                    flags,
                    *args,
                    **kwargs,
                )
                if (
                    path == PurePosixPath(SCRIPT_REL).name
                    and not flags & os.O_DIRECTORY
                    and kwargs.get("dir_fd") is not None
                ):
                    selected_return_leaf_descriptor = descriptor
                return descriptor

            def tracked_selected_return_close(descriptor: int) -> None:
                if descriptor == selected_return_leaf_descriptor:
                    list.append(selected_return_close_calls, descriptor)
                original_resource_close(descriptor)

            def interrupt_selected_return(
                frame: types.FrameType,
                event: str,
                argument: Any,
            ) -> Any:
                if (
                    event == "return"
                    and frame.f_code
                    is v2_fixture_open_selected_read_descriptor.__code__
                ):
                    list.append(selected_return_arguments, argument)
                    sys.settrace(None)
                    raise selected_return_primary
                return interrupt_selected_return

            selected_return_observed: BaseException | None = None
            os.open = tracked_selected_return_open
            os.close = tracked_selected_return_close
            sys.settrace(interrupt_selected_return)
            try:
                v2_fixture_open_selected_read_descriptor(
                    selected_resource_path
                )
            except BaseException as error:
                selected_return_observed = error
            finally:
                sys.settrace(prior_trace)
                os.open = original_resource_open
                selected_return_retained_before_rescue = (
                    len(selected_return_arguments) == 1
                    and list.__getitem__(selected_return_arguments, 0)
                    == selected_return_leaf_descriptor
                    and type(selected_return_leaf_descriptor) is int
                    and selected_return_close_calls == []
                    and not v2_fixture_selected_resource_scope_is_pristine()
                )
                try:
                    v2_fixture_selected_resource_scope_leave(
                        selected_return_token
                    )
                    list.__setitem__(selected_return_token_slot, 0, None)
                finally:
                    os.close = original_resource_close

            selected_leaf_descriptor: int | None = None

            def tracked_selected_leaf_open(
                path: Any,
                flags: int,
                *args: Any,
                **kwargs: Any,
            ) -> int:
                nonlocal selected_leaf_descriptor
                descriptor = original_resource_open(
                    path,
                    flags,
                    *args,
                    **kwargs,
                )
                if (
                    path == PurePosixPath(SCRIPT_REL).name
                    and not flags & os.O_DIRECTORY
                    and kwargs.get("dir_fd") is not None
                ):
                    selected_leaf_descriptor = descriptor
                return descriptor

            def failed_selected_fstat(descriptor: int) -> Any:
                if descriptor == selected_leaf_descriptor:
                    raise OSError(errno.EIO, "synthetic selected fstat")
                return original_resource_fstat(descriptor)

            def tracked_resource_close(descriptor: int) -> None:
                if descriptor == selected_leaf_descriptor:
                    list.append(resource_close_calls, descriptor)
                original_resource_close(descriptor)

            os.open = tracked_selected_leaf_open
            os.fstat = failed_selected_fstat
            os.close = tracked_resource_close
            record_resource_error(
                "selected-fstat",
                lambda: v2_fixture_resource_state([
                    selected_resource_path
                ]),
                "fingerprint read failed",
            )
            os.open = original_resource_open
            os.fstat = original_resource_fstat
            os.close = original_resource_close

            def failed_selected_pread(
                _descriptor: int,
                _length: int,
                _offset: int,
            ) -> bytes:
                raise OSError(errno.EIO, "synthetic selected pread")

            os.pread = failed_selected_pread
            record_resource_error(
                "selected-pread",
                lambda: v2_fixture_resource_state([
                    selected_resource_path
                ]),
                "fingerprint read failed",
            )
            os.pread = original_resource_pread

            def failed_selected_close(descriptor: int) -> None:
                if descriptor != selected_leaf_descriptor:
                    original_resource_close(descriptor)
                    return
                list.append(resource_failed_close_calls, descriptor)
                original_resource_close(descriptor)
                raise OSError(errno.EIO, "synthetic selected close")

            selected_leaf_descriptor = None
            os.open = tracked_selected_leaf_open
            os.close = failed_selected_close
            record_resource_error(
                "selected-close",
                lambda: v2_fixture_resource_state([
                    selected_resource_path
                ]),
                "descriptor close failed",
            )
            os.open = original_resource_open
            os.close = original_resource_close

            selected_leaf_descriptor = None
            os.open = tracked_selected_leaf_open
            os.fstat = failed_selected_fstat
            os.close = failed_selected_close
            record_resource_error(
                "selected-fstat-and-close",
                lambda: v2_fixture_resource_state([
