            os.close = original_resource_close

            synthetic_recheck_link = (
                REPO_ROOT / "synthetic-resource-recheck-link"
            )
            synthetic_link_state = os.stat_result(
                (stat.S_IFLNK | 0o777, 2, 1, 1, 0, 0, 1, 0, 0, 0),
                {"st_atime_ns": 0, "st_mtime_ns": 3, "st_ctime_ns": 4},
            )
            synthetic_link_identity = v2_fixture_stat_identity_tuple(
                synthetic_link_state
            )
            synthetic_link_binding = (
                synthetic_link_identity,
                ((".", 1, 1, stat.S_IFDIR),),
            )
            synthetic_link_stat_calls = 0

            def synthetic_recheck_capture(path: Path) -> Any:
                if path == synthetic_recheck_link:
                    return (
                        "synthetic-resource-recheck-link",
                        synthetic_link_binding,
                    )
                return original_resource_capture_binding(path)

            def synthetic_recheck_open_parent(
                relative: str,
                expected_parents: Any,
                descriptor_slot: list[int | None],
            ) -> Any:
                if relative == "synthetic-resource-recheck-link":
                    if expected_parents != synthetic_link_binding[1]:
                        raise EvidenceFailed(
                            "synthetic resource parent binding changed"
                        )
                    list.__setitem__(descriptor_slot, 0, 951)
                    return "synthetic-resource-recheck-link"
                return original_resource_open_parent(
                    relative,
                    expected_parents,
                    descriptor_slot,
                )

            def failed_symlink_recheck_stat(
                path: Any,
                *args: Any,
                **kwargs: Any,
            ) -> Any:
                nonlocal synthetic_link_stat_calls
                if path == "synthetic-resource-recheck-link":
                    synthetic_link_stat_calls += 1
                    if synthetic_link_stat_calls > 1:
                        raise OSError(
                            errno.EIO,
                            "synthetic symlink metadata recheck",
                        )
                    return synthetic_link_state
                return original_resource_stat(path, *args, **kwargs)

            def synthetic_recheck_readlink(
                path: Any,
                *args: Any,
                **kwargs: Any,
            ) -> str:
                if path == "synthetic-resource-recheck-link":
                    return "x"
                return original_resource_readlink(path, *args, **kwargs)

            def synthetic_recheck_close(descriptor: int) -> None:
                if descriptor == 951:
                    return
                original_resource_close(descriptor)

            globals()["v2_fixture_capture_anchored_resource_binding"] = (
                synthetic_recheck_capture
            )
            globals()["v2_fixture_open_anchored_parent"] = (
                synthetic_recheck_open_parent
            )
            os.stat = failed_symlink_recheck_stat
            os.readlink = synthetic_recheck_readlink
            os.close = synthetic_recheck_close
            record_resource_error(
                "symlink-metadata-recheck",
                lambda: v2_fixture_resource_state([
                    synthetic_recheck_link
                ]),
