            and len(parent_close_failure_calls) == 2
            and all(
                row["terminal"] == "EvidenceFailed"
                and row["single_parent_attempt"] is True
                and row["one_child_cleanup"] is True
                for row in ownership_transfer_close_rows.values()
            )
            and selected_handoff_observed is selected_handoff_primary
            and len(selected_handoff_opened) == 2
            and selected_handoff_closed == selected_handoff_opened
            and selected_handoff_slot == [None]
            and selected_acquisition_rows["root"]["primary_preserved"]
            is True
            and len(selected_acquisition_rows["root"]["opened"]) == 1
            and selected_acquisition_rows["root"]["closed"]
            == selected_acquisition_rows["root"]["opened"]
            and selected_acquisition_rows["root"]["slot"] == [None]
            and selected_acquisition_rows["child"]["primary_preserved"]
            is True
            and len(selected_acquisition_rows["child"]["opened"]) == 2
            and selected_acquisition_rows["child"]["closed"]
            == list(reversed(
                selected_acquisition_rows["child"]["opened"]
            ))
            and selected_acquisition_rows["child"]["slot"] == [None]
            and all(
                row["primary_preserved"] is True
                and row["return_event_count"] == 1
                and row["retained_before_caller_rescue"] is True
                and row["slot"] == [None]
                and row["each_descriptor_closed_once"] is True
                for row in selected_wrapper_true_return_rows.values()
            )
            and selected_return_observed is selected_return_primary
            and selected_return_retained_before_rescue
            and selected_return_leaf_descriptor is not None
            and selected_return_close_calls
