            and v2_fixture_selected_resource_scope_is_pristine()
            and non_exact_stat_error.terminal == "EvidenceFailed"
            and symlink_target_recheck_calls == 2
            and len(resource_close_calls) == 1
            and len(resource_failed_close_calls) == 3
            and len(cwd_root_close_calls) == 1,
            expected={
