        resource_identity_terminals: dict[str, str] = {}
        synthetic_identity_link = (
            REPO_ROOT / "synthetic-resource-identity-link"
        )
        synthetic_identity_state = os.stat_result(
            (stat.S_IFLNK | 0o777, 21, 20, 1, 0, 0, 1, 0, 0, 0),
            {"st_atime_ns": 0, "st_mtime_ns": 22, "st_ctime_ns": 23},
        )
        synthetic_identity_binding = (
            v2_fixture_stat_identity_tuple(synthetic_identity_state),
            ((".", 20, 20, stat.S_IFDIR),),
        )
        synthetic_identity_stat_mode = "baseline"
        synthetic_identity_stat_calls = 0

        def synthetic_identity_capture(path: Path) -> Any:
            if path == synthetic_identity_link:
                return (
                    "synthetic-resource-identity-link",
                    synthetic_identity_binding,
                )
            return original_resource_capture_binding(path)

        def synthetic_identity_open_parent(
            relative: str,
            expected_parents: Any,
            descriptor_slot: list[int | None],
        ) -> Any:
            if relative == "synthetic-resource-identity-link":
                if expected_parents != synthetic_identity_binding[1]:
                    raise EvidenceFailed(
                        "synthetic identity parent binding changed"
                    )
                list.__setitem__(descriptor_slot, 0, 952)
                return "synthetic-resource-identity-link"
            return original_resource_open_parent(
                relative,
                expected_parents,
                descriptor_slot,
            )

        def synthetic_identity_stat(
            path: Any,
            *args: Any,
            **kwargs: Any,
        ) -> Any:
            nonlocal synthetic_identity_stat_calls
            if path != "synthetic-resource-identity-link":
                return original_resource_stat(path, *args, **kwargs)
            synthetic_identity_stat_calls += 1
            if (
                synthetic_identity_stat_calls > 1
                and synthetic_identity_stat_mode == "error"
            ):
                raise OSError(
                    errno.EIO,
                    "synthetic identity metadata recheck",
                )
            if (
                synthetic_identity_stat_calls > 1
                and synthetic_identity_stat_mode == "changed"
            ):
                return changed_resource_stat(synthetic_identity_state)
            return synthetic_identity_state

        def synthetic_identity_readlink(
            path: Any,
            *args: Any,
            **kwargs: Any,
        ) -> str:
            if path == "synthetic-resource-identity-link":
                return "x"
            return original_resource_readlink(path, *args, **kwargs)

        def synthetic_identity_close(descriptor: int) -> None:
            if descriptor == 952:
                return
            original_resource_close(descriptor)

        try:
            globals()["v2_fixture_capture_anchored_resource_binding"] = (
                synthetic_identity_capture
            )
            globals()["v2_fixture_open_anchored_parent"] = (
                synthetic_identity_open_parent
            )
            os.stat = synthetic_identity_stat
            os.readlink = synthetic_identity_readlink
            os.close = synthetic_identity_close
            synthetic_identity_stat_calls = 0
            synthetic_identity_stat_mode = "changed"
            replaced_leaf_error = expect_error(
                EvidenceFailed,
                lambda: v2_fixture_resource_state([
                    synthetic_identity_link
                ]),
                contains="changed after state capture",
            )
            dict.__setitem__(
                resource_identity_terminals,
                "leaf-replaced",
                replaced_leaf_error.terminal,
            )
            synthetic_identity_stat_calls = 0
            synthetic_identity_stat_mode = "error"
            failed_leaf_error = expect_error(
                EvidenceFailed,
                lambda: v2_fixture_resource_state([
                    synthetic_identity_link
                ]),
                contains="metadata recheck failed",
            )
            dict.__setitem__(
                resource_identity_terminals,
                "leaf-recheck-error",
                failed_leaf_error.terminal,
            )
            globals()["v2_fixture_capture_anchored_resource_binding"] = (
                original_resource_capture_binding
            )
            globals()["v2_fixture_open_anchored_parent"] = (
                original_resource_open_parent
            )
            os.stat = original_resource_stat
            os.readlink = original_resource_readlink
            os.close = original_resource_close

            selected_relative, selected_binding = (
                v2_fixture_capture_anchored_resource_binding(
                    selected_resource_path
                )
            )
            selected_parent_descriptor_ordinals: dict[int, int] = {}
            selected_parent_open_count = 0
            selected_parent_fault = "changed"

            def prebound_selected_capture(path: Path) -> Any:
                if path == selected_resource_path:
                    return selected_relative, selected_binding
                return original_resource_capture_binding(path)

            def tracked_selected_parent_open(
                path: Any,
                flags: int,
                *args: Any,
                **kwargs: Any,
            ) -> int:
                nonlocal selected_parent_open_count
                descriptor = original_resource_open(
                    path,
                    flags,
                    *args,
                    **kwargs,
                )
                if (
                    path == selected_parent_path.name
                    and flags & os.O_DIRECTORY
                    and kwargs.get("dir_fd") is not None
                ):
                    selected_parent_open_count += 1
                    dict.__setitem__(
                        selected_parent_descriptor_ordinals,
                        descriptor,
                        selected_parent_open_count,
                    )
                return descriptor

            def fault_selected_parent_fstat(descriptor: int) -> Any:
                ordinal = dict.get(
                    selected_parent_descriptor_ordinals,
                    descriptor,
                )
                if ordinal == 2 and selected_parent_fault == "error":
                    raise OSError(
                        errno.EIO,
                        "synthetic parent verification fstat",
                    )
                state = original_resource_fstat(descriptor)
                if ordinal == 2 and selected_parent_fault == "changed":
                    return changed_resource_stat(state)
                return state

            globals()["v2_fixture_capture_anchored_resource_binding"] = (
                prebound_selected_capture
            )
            os.open = tracked_selected_parent_open
            os.fstat = fault_selected_parent_fstat
            replaced_parent_error = expect_error(
                EvidenceFailed,
                lambda: v2_fixture_resource_state([
                    selected_resource_path
                ]),
                contains="parent changed after state capture",
            )
            dict.__setitem__(
                resource_identity_terminals,
                "parent-replaced",
                replaced_parent_error.terminal,
            )
            selected_parent_descriptor_ordinals = {}
            selected_parent_open_count = 0
            selected_parent_fault = "error"
            failed_parent_error = expect_error(
                EvidenceFailed,
                lambda: v2_fixture_resource_state([
                    selected_resource_path
                ]),
                contains="parent metadata cannot be read safely",
            )
            dict.__setitem__(
                resource_identity_terminals,
                "parent-recheck-error",
                failed_parent_error.terminal,
            )
        finally:
            globals()["v2_fixture_capture_anchored_resource_binding"] = (
                original_resource_capture_binding
            )
            globals()["v2_fixture_open_anchored_parent"] = (
                original_resource_open_parent
            )
            os.open = original_resource_open
            os.fstat = original_resource_fstat
            os.stat = original_resource_stat
            os.readlink = original_resource_readlink
            os.close = original_resource_close
        checks.check(
            "resource-final-path-and-parent-identity-changes-refused",
            resource_identity_terminals
            == {
                "leaf-replaced": "EvidenceFailed",
                "leaf-recheck-error": "EvidenceFailed",
                "parent-replaced": "EvidenceFailed",
                "parent-recheck-error": "EvidenceFailed",
            },
            expected={
                "leaf-replaced": "EvidenceFailed",
                "leaf-recheck-error": "EvidenceFailed",
                "parent-replaced": "EvidenceFailed",
                "parent-recheck-error": "EvidenceFailed",
            },
            observed=resource_identity_terminals,
        )

        def guarded_process_state_expect_error(
            callback: Callable[[], Any],
            *,
            contains: str,
        ) -> HarnessError:
            guard_cwd = os.getcwdb()
            guard_environment = os.environ
            guard_environment_bytes = os.environb
            if (
                guard_environment is not V2_INITIAL_PROCESS_ENVIRONMENT
                or guard_environment_bytes
                is not V2_INITIAL_PROCESS_ENVIRONMENT_BYTES
                or not v2_process_environment_backing_is_pinned()
                or not v2_fixture_selected_resource_scope_is_pristine()
            ):
                raise EvidenceFailed(
                    "test-owned process-state guard baseline is not pristine"
                )
            guard_environment_attributes = (
                v2_exact_instance_dictionary_snapshot(
                    guard_environment,
                    label="test-owned fixture process environment guard",
                )
            )
            guard_environment_bytes_attributes = (
                v2_exact_instance_dictionary_snapshot(
                    guard_environment_bytes,
                    label=(
                        "test-owned fixture byte process environment guard"
                    ),
                )
            )
            guard_environment_entries = (
                v2_bounded_process_environment_bytes_snapshot()
            )
            guard_recursion_limit = sys.getrecursionlimit()
            guard_recursion_setter = sys.setrecursionlimit
            guard_command_receipts = V2_INITIAL_COMMAND_RECEIPTS
            _, guard_command_receipt_payload = (
                v2_capture_command_receipt_state()
            )
            guard_cancel_requested = _cancel_requested
            guard_cancel_epoch = _cancel_signal_epoch
            try:
                return expect_error(
                    EvidenceFailed,
                    callback,
                    contains=contains,
                )
            finally:
                guard_restoration_errors: list[BaseException] = []

                def guard_restore_recursion() -> None:
                    sys.setrecursionlimit = guard_recursion_setter
                    if sys.getrecursionlimit() != guard_recursion_limit:
                        guard_recursion_setter(guard_recursion_limit)

                def guard_restore_environment() -> None:
                    v2_restore_process_environment(
                        guard_environment,
                        guard_environment_bytes,
                        guard_environment_attributes,
                        guard_environment_bytes_attributes,
                        guard_environment_entries,
                    )

                def guard_restore_cwd() -> None:
                    if os.getcwdb() != guard_cwd:
                        os.chdir(guard_cwd)

                def guard_restore_receipts() -> None:
                    v2_restore_command_receipt_state(
                        guard_command_receipt_payload
                    )

                def guard_restore_cancellation() -> None:
                    v2_restore_cancel_state(
                        guard_cancel_requested,
                        guard_cancel_epoch,
                    )

                guard_steps = (
                    ("process-environment", guard_restore_environment),
                    ("process-cwd", guard_restore_cwd),
                    ("process-recursion-limit", guard_restore_recursion),
                    ("command-receipts", guard_restore_receipts),
                    ("cancellation", guard_restore_cancellation),
                )

                def guard_verify() -> None:
                    current_cancel_expected = (
                        guard_cancel_requested
                        if _cancel_signal_epoch == guard_cancel_epoch
                        else True
                    )
                    if (
                        os.getcwdb() != guard_cwd
                        or os.environ is not guard_environment
                        or os.environb is not guard_environment_bytes
                        or not v2_exact_instance_dictionary_matches(
                            guard_environment,
                            guard_environment_attributes,
                            label=(
                                "test-owned restored fixture process "
                                "environment"
                            ),
                        )
                        or not v2_exact_instance_dictionary_matches(
                            guard_environment_bytes,
                            guard_environment_bytes_attributes,
                            label=(
                                "test-owned restored fixture byte process "
                                "environment"
                            ),
                        )
                        or tuple(dict.items(
                            v2_bounded_process_environment_bytes_snapshot()
                        )) != tuple(dict.items(guard_environment_entries))
                        or not v2_process_environment_backing_is_pinned()
                        or sys.setrecursionlimit is not guard_recursion_setter
                        or sys.getrecursionlimit() != guard_recursion_limit
                        or _command_receipts is not guard_command_receipts
                        or v2_capture_command_receipt_state()[1]
                        != guard_command_receipt_payload
                        or _cancel_signal_epoch < guard_cancel_epoch
                        or _cancel_requested is not current_cancel_expected
                        or not v2_fixture_selected_resource_scope_is_pristine()
                    ):
                        raise EvidenceFailed(
                            "test-owned process-state cleanup did not converge"
                        )

                guard_report = v2_run_convergent_restoration(
                    guard_steps,
                    guard_verify,
                )
                for _guard_name, guard_error in guard_report["anomalies"]:
                    list.append(guard_restoration_errors, guard_error)
                if guard_report["converged"] is not True:
                    list.append(
                        guard_restoration_errors,
                        EvidenceFailed(
                            "test-owned process-state cleanup did not converge"
                        ),
                    )
                if guard_restoration_errors:
                    raise EvidenceFailed(
                        "test-owned process-state cleanup failed"
                    ) from guard_restoration_errors[0]

        process_cwd_before = os.getcwdb()
        process_environment_key = b"FS_V2_RESOURCE_RESTORE_PROBE"
        process_environment_before = os.environb.get(process_environment_key)
        process_environment_mutation = (
            b"mutated-a"
            if process_environment_before != b"mutated-a"
            else b"mutated-b"
        )
        process_recursion_before = sys.getrecursionlimit()
        process_environment_codec_before = os.environ.encodekey
        process_receipt_list_before = V2_INITIAL_COMMAND_RECEIPTS
        _, process_receipt_payload_before = v2_capture_command_receipt_state()
        process_cancel_before = _cancel_requested
        process_cancel_epoch_before = _cancel_signal_epoch
        process_cwd_probe = V2CheckCollector(
            "fixture-resource-cwd-mutation-probe",
            "fixture.resource-cwd-mutation-probe",
