        class HostilePublicationPath(str):
            def casefold(self) -> str:
                publication_path_hook_calls["casefold"] += 1
                return "terminal.json"

            def encode(self, *_args: Any, **_kwargs: Any) -> bytes:
                publication_path_hook_calls["encode"] += 1
                return b"terminal.json"

        hostile_publication_payloads: dict[Any, bytes] = {
            "terminal.json": b"{}\n",
        }
        dict.__setitem__(
            hostile_publication_payloads,
            HostilePublicationPath("hostile.json"),
            b"{}\n",
        )
        hostile_publication_error = expect_error(
            EvidenceFailed,
            lambda: v2_preflight_publication_topology(
                hostile_publication_payloads
            ),
            contains="exact",
        )

        class HostilePublicationPayloads(Mapping[str, bytes]):
            def __getitem__(self, _key: str) -> bytes:
                publication_path_hook_calls["getitem"] += 1
                raise RuntimeError("hostile publication __getitem__ executed")

            def __iter__(self) -> Iterator[str]:
                publication_path_hook_calls["iter"] += 1
                raise RuntimeError("hostile publication __iter__ executed")

            def __len__(self) -> int:
                publication_path_hook_calls["len"] += 1
                raise RuntimeError("hostile publication __len__ executed")

            def items(self) -> Any:
                publication_path_hook_calls["items"] += 1
                raise RuntimeError("hostile publication items executed")

        hostile_publication_mapping_error = expect_error(
            EvidenceFailed,
            lambda: v2_preflight_publication_topology(
                HostilePublicationPayloads()
            ),
            contains="exact dictionary",
        )
        checks.check(
            "publication-path-subclass-hooks-refused-before-alias-normalization",
            hostile_publication_error.terminal == "EvidenceFailed"
            and hostile_publication_mapping_error.terminal == "EvidenceFailed"
            and publication_path_hook_calls
            == {
                "casefold": 0,
                "encode": 0,
                "getitem": 0,
                "items": 0,
                "iter": 0,
                "len": 0,
            },
            expected={
                "terminal": "EvidenceFailed",
                "mapping_terminal": "EvidenceFailed",
                "hook_calls": {
                    "casefold": 0,
                    "encode": 0,
                    "getitem": 0,
                    "items": 0,
                    "iter": 0,
                    "len": 0,
                },
            },
            observed={
                "terminal": hostile_publication_error.terminal,
                "mapping_terminal": (
                    hostile_publication_mapping_error.terminal
                ),
                "hook_calls": publication_path_hook_calls,
            },
        )
        preflight_reservation = V2BundleReservation(
            output=REPO_ROOT,
            artifact_root="target",
            artifact_dir="fixture",
            terminal_descriptor=2,
            output_descriptor=1,
            parent_descriptor=0,
            path_anchors=(),
        )
        preflight_calls = {"verify": 0, "write": 0}
        original_verify = v2_verify_reserved_publication
        original_writer = v2_write_reserved_member

        def refuse_initial_prefix(
            _reservation: V2BundleReservation,
            *,
            payloads: Mapping[str, bytes],
            terminal_sealed: bool,
        ) -> None:
            del payloads, terminal_sealed
            preflight_calls["verify"] += 1
            raise InfrastructureFailed(
                "synthetic exact-prefix verification failure"
            )

        def count_forbidden_write(
            _reservation: V2BundleReservation,
            *,
            relative: PurePosixPath,
            payload: bytes,
        ) -> dict[str, int]:
            del relative, payload
            preflight_calls["write"] += 1
            return {}

        globals()["v2_verify_reserved_publication"] = refuse_initial_prefix
        globals()["v2_write_reserved_member"] = count_forbidden_write
        try:
            preflight_error = expect_error(
                InfrastructureFailed,
                lambda: _v2_publish_reserved_bundle(
                    preflight_reservation,
                    payloads={
                        "source-v2.json": b"{}\n",
                        "terminal.json": b"{}\n",
                    },
                ),
                contains="exact-prefix",
            )
        finally:
            globals()["v2_verify_reserved_publication"] = original_verify
            globals()["v2_write_reserved_member"] = original_writer
        checks.check(
            "exact-prefix-verification-precedes-every-payload-write",
            preflight_error.terminal == "InfrastructureFailed"
            and preflight_calls == {"verify": 1, "write": 0}
            and preflight_reservation.terminal_assignment_started is False,
            expected={"verify": 1, "write": 0, "terminal_started": False},
            observed={
                **preflight_calls,
                "terminal_started": (
                    preflight_reservation.terminal_assignment_started
                ),
            },
        )

        cleanup_rows: list[dict[str, Any]] = []

        def exercise_directory_cleanup(
            *,
            fail_primary: bool,
        ) -> None:
            original_open = os.open
            original_fsync = os.fsync
            original_close = os.close
            operations: list[str] = []

            def fake_open(*_args: Any, **_kwargs: Any) -> int:
                operations.append("open")
                return 301

            def fake_fsync(_descriptor: int) -> None:
                operations.append("fsync")
                if fail_primary:
                    raise OSError(errno.EIO, "synthetic fsync primary")

            def fake_close(_descriptor: int) -> None:
                operations.append("close")
                raise OSError(errno.EIO, "synthetic fsync close")

            os.open = fake_open
            os.fsync = fake_fsync
            os.close = fake_close
            expected_diagnostic = (
                "v2 directory fsync failed"
                if fail_primary
                else "v2 directory descriptor close failed"
            )
            try:
                error = expect_error(
                    InfrastructureFailed,
                    lambda: v2_fsync_directory(REPO_ROOT),
                    contains=expected_diagnostic,
                )
            finally:
                os.open = original_open
                os.fsync = original_fsync
                os.close = original_close
            cleanup_rows.append({
                "case": (
                    "directory-primary-and-close"
                    if fail_primary
                    else "directory-close-only"
                ),
                "terminal": error.terminal,
                "diagnostic": str(error),
                "operations": operations,
            })

        def exercise_exclusive_writer_cleanup(
            *,
            fail_primary: bool,
            invalid_count: Any = None,
            count_case: str | None = None,
        ) -> None:
            original_open = os.open
            original_write = os.write
            original_fsync = os.fsync
            original_close = os.close
            operations: list[str] = []

            def fake_open(*_args: Any, **_kwargs: Any) -> int:
                operations.append("open")
                return 302

            def fake_write(_descriptor: int, payload: bytes) -> Any:
                operations.append("write")
                if fail_primary:
                    raise OSError(errno.EIO, "synthetic write primary")
                if invalid_count is not None:
                    return invalid_count
                return len(payload)

            def fake_fsync(_descriptor: int) -> None:
                operations.append("fsync")

            def fake_close(_descriptor: int) -> None:
                operations.append("close")
                raise OSError(errno.EIO, "synthetic writer close")

            os.open = fake_open
            os.write = fake_write
            os.fsync = fake_fsync
            os.close = fake_close
            expected_diagnostic = (
                "v2 exclusive writer failed for reserved artifact"
                if fail_primary
                else (
                    "v2 exclusive writer observed an invalid write count"
                    if count_case is not None
                    else (
                        "v2 exclusive writer could not close reserved "
                        "artifact"
                    )
                )
            )
            try:
                error = expect_error(
                    InfrastructureFailed,
                    lambda: v2_write_exclusive(
                        REPO_ROOT / "synthetic-cleanup-member",
                        b"x",
                    ),
                    contains=expected_diagnostic,
                )
            finally:
                os.open = original_open
                os.write = original_write
                os.fsync = original_fsync
                os.close = original_close
            cleanup_rows.append({
                "case": (
                    "exclusive-primary-and-close"
                    if fail_primary
                    else (
                        f"exclusive-invalid-{count_case}-and-close"
                        if count_case is not None
                        else "exclusive-close-only"
                    )
                ),
                "terminal": error.terminal,
                "diagnostic": str(error),
                "operations": operations,
            })

        def exercise_reserved_member_cleanup(
            *,
            operation: str,
            fail_primary: bool,
            invalid_count: Any = None,
            count_case: str | None = None,
            parent_close_only: bool = False,
        ) -> None:
            original_open_reserved_directory = v2_open_reserved_directory
            original_read_descriptor_strict = v2_read_descriptor_strict
            original_open = os.open
            original_write = os.write
            original_fsync = os.fsync
            original_fstat = os.fstat
            original_close = os.close
            operations: list[str] = []
            parent_descriptor = 501 if operation == "write" else 601
            member_descriptor = 502 if operation == "write" else 602

            def fake_open_reserved_directory(
                _reservation: V2BundleReservation,
                _relative: PurePosixPath,
                *,
                create: bool,
                _descriptor_slot: list[int | None] | None = None,
            ) -> int:
                operations.append(f"open-parent:{create}")
                if _descriptor_slot is not None:
                    list.__setitem__(
                        _descriptor_slot,
                        0,
                        parent_descriptor,
                    )
                return parent_descriptor

            def fake_open(*_args: Any, **_kwargs: Any) -> int:
                operations.append("open-member")
                return member_descriptor

            def fake_write(_descriptor: int, payload: bytes) -> Any:
                operations.append("write")
                if fail_primary:
                    raise OSError(errno.EIO, "synthetic reserved write")
                if invalid_count is not None:
                    return invalid_count
                return len(payload)

            def fake_fsync(descriptor: int) -> None:
                operations.append(f"fsync:{descriptor}")

            def fake_fstat(_descriptor: int) -> Any:
                operations.append("fstat")
                return types.SimpleNamespace(
                    st_dev=1,
                    st_ino=2,
                    st_mode=stat.S_IFREG | 0o644,
                    st_nlink=1,
                    st_size=1,
                    st_mtime_ns=3,
                    st_ctime_ns=4,
                )

            def fake_read_descriptor_strict(
                _descriptor: int,
                *,
                label: str,
                expected_identity: Mapping[str, int] | None = None,
            ) -> bytes:
                del label, expected_identity
                operations.append("read")
                if fail_primary:
                    raise InputRefused("synthetic reserved read primary")
                return b"x"

            def fake_close(descriptor: int) -> None:
                operations.append(f"close:{descriptor}")
                if parent_close_only and descriptor == member_descriptor:
                    return
                raise OSError(errno.EIO, "synthetic reserved close")

            globals()["v2_open_reserved_directory"] = (
                fake_open_reserved_directory
            )
            globals()["v2_read_descriptor_strict"] = (
                fake_read_descriptor_strict
            )
            os.open = fake_open
            os.write = fake_write
            os.fsync = fake_fsync
            os.fstat = fake_fstat
            os.close = fake_close
            synthetic_reservation = V2BundleReservation(
                output=REPO_ROOT,
                artifact_root="target",
                artifact_dir="synthetic-cleanup",
                terminal_descriptor=None,
                output_descriptor=None,
                parent_descriptor=None,
                path_anchors=(),
            )
            if operation == "write":
                callback: Callable[[], Any] = lambda: (
                    v2_write_reserved_member(
                        synthetic_reservation,
                        relative=PurePosixPath("member.json"),
                        payload=b"x",
                    )
                )
                expected_type: type[HarnessError] = InfrastructureFailed
                expected_diagnostic = (
                    "v2 descriptor-relative write failed for member.json"
                    if fail_primary
                    else (
                        "v2 reserved member observed an invalid write count"
                        if count_case is not None
                        else (
                            "v2 reserved member parent descriptor close "
                            "failed: member.json"
                            if parent_close_only
                            else (
                                "v2 reserved member descriptor close failed: "
                                "member.json"
                            )
                        )
                    )
                )
            else:
                callback = lambda: v2_read_reserved_member(
                    synthetic_reservation,
                    name="member.json",
                    expected_identity={},
                )
                expected_type = (
                    InputRefused if fail_primary else InfrastructureFailed
                )
                expected_diagnostic = (
                    "synthetic reserved read primary"
                    if fail_primary
                    else (
                        "v2 reserved artifact descriptor close failed: "
                        "member.json"
                    )
                )
            try:
                error = expect_error(
                    expected_type,
                    callback,
                    contains=expected_diagnostic,
                )
            finally:
                globals()["v2_open_reserved_directory"] = (
                    original_open_reserved_directory
                )
                globals()["v2_read_descriptor_strict"] = (
                    original_read_descriptor_strict
                )
                os.open = original_open
                os.write = original_write
                os.fsync = original_fsync
                os.fstat = original_fstat
                os.close = original_close
            cleanup_rows.append({
                "case": (
                    f"reserved-{operation}-"
                    + (
                        "primary-and-close"
                        if fail_primary
                        else (
                            f"invalid-{count_case}-and-close"
                            if count_case is not None
                            else (
                                "parent-close-failure"
                                if parent_close_only
                                else "close-only"
                            )
                        )
                    )
                ),
                "terminal": error.terminal,
                "diagnostic": str(error),
                "operations": operations,
            })

        def exercise_strict_directory_registration(
            *,
            non_directory: bool,
        ) -> None:
            original_open = os.open
            original_fstat = os.fstat
            original_close = os.close
            operations: list[str] = []
            descriptors = iter((10, 11))

            def fake_open(*_args: Any, **_kwargs: Any) -> int:
                descriptor = next(descriptors)
                operations.append(f"open:{descriptor}")
                return descriptor

            def fake_fstat(descriptor: int) -> Any:
                operations.append(f"fstat:{descriptor}")
                if descriptor == 10:
                    return types.SimpleNamespace(
                        st_dev=1,
                        st_ino=10,
                        st_mode=stat.S_IFDIR | 0o755,
                    )
                if not non_directory:
                    raise OSError(errno.EIO, "synthetic child fstat")
                return types.SimpleNamespace(st_mode=stat.S_IFREG | 0o644)

            def fake_close(descriptor: int) -> None:
                operations.append(f"close:{descriptor}")

            os.open = fake_open
            os.fstat = fake_fstat
            os.close = fake_close
            diagnostic = (
                "contains a non-directory component"
                if non_directory
                else "cannot be opened safely"
            )
            try:
                error = expect_error(
                    InputRefused,
                    lambda: v2_read_repo_relative_file_strict(
                        "scripts/member.json",
                        label="synthetic strict child",
                    ),
                    contains=diagnostic,
                )
            finally:
                os.open = original_open
                os.fstat = original_fstat
                os.close = original_close
            cleanup_rows.append({
                "case": (
                    "strict-child-nondirectory"
                    if non_directory
                    else "strict-child-fstat-primary"
                ),
                "terminal": error.terminal,
                "diagnostic": str(error),
                "operations": operations,
            })

        def exercise_bounded_read_semantic_precedence(
            *,
            identity_change: bool,
        ) -> None:
            original_open = os.open
            original_fstat = os.fstat
            original_fdopen = os.fdopen
            original_close = os.close
            operations: list[str] = []
            fstat_calls = 0

            class SyntheticHandle:
                def __enter__(self) -> "SyntheticHandle":
                    operations.append("handle-enter")
                    return self

                def read(self, _count: int) -> bytes:
                    operations.append("read")
                    return b"x" if identity_change else b"xx"

                def __exit__(
                    self,
                    _error_type: Any,
                    _error: Any,
                    _traceback: Any,
                ) -> None:
                    operations.append("handle-exit")

            def fake_open(*_args: Any, **_kwargs: Any) -> int:
                operations.append("open")
                return 20

            def fake_fstat(_descriptor: int) -> Any:
                nonlocal fstat_calls
                fstat_calls += 1
                operations.append(f"fstat:{fstat_calls}")
                return types.SimpleNamespace(
                    st_dev=1,
                    st_ino=(2 if fstat_calls == 1 or not identity_change else 3),
                    st_mode=stat.S_IFREG | 0o644,
                    st_nlink=1,
                    st_size=1,
                    st_mtime_ns=4,
                    st_ctime_ns=5,
                )

            def fake_fdopen(
                _descriptor: int,
                _mode: str,
                *,
                closefd: bool,
            ) -> SyntheticHandle:
                operations.append(f"fdopen:{closefd}")
                return SyntheticHandle()

            def fake_close(_descriptor: int) -> None:
                operations.append("close")
                raise OSError(errno.EIO, "synthetic bounded-read close")

            os.open = fake_open
            os.fstat = fake_fstat
            os.fdopen = fake_fdopen
            os.close = fake_close
            diagnostic = (
                "changed during bounded read"
                if identity_change
                else "exceeds 1 byte cap"
            )
            try:
                error = expect_error(
                    InputRefused,
                    lambda: bounded_read(
                        publication_script_path,
                        cap=1,
                    ),
                    contains=diagnostic,
                )
            finally:
                os.open = original_open
                os.fstat = original_fstat
                os.fdopen = original_fdopen
                os.close = original_close
            cleanup_rows.append({
                "case": (
                    "bounded-read-identity-and-close"
                    if identity_change
                    else "bounded-read-oversize-and-close"
                ),
                "terminal": error.terminal,
                "diagnostic": str(error),
                "operations": operations,
            })

        def exercise_non_oserror_cleanup() -> None:
            original_close = os.close
            operations: list[str] = []
            raw_cause = RuntimeError(
                "synthetic non-OSError close failure"
            )

            def fake_close(descriptor: int) -> None:
                operations.append(f"close:{descriptor}")
                if descriptor == 701:
                    raise raw_cause
                if descriptor == 702:
                    raise OSError(
                        errno.EIO,
                        "synthetic later OSError close failure",
                    )

            caught: BaseException | None = None
            os.close = fake_close
            try:
                try:
                    v2_close_owned_descriptors(
                        (
                            (
                                701,
                                InfrastructureFailed(
                                    "synthetic first close failure"
                                ),
                            ),
                            (
                                702,
                                InfrastructureFailed(
                                    "synthetic second close failure"
                                ),
                            ),
                            (
                                703,
                                InfrastructureFailed(
                                    "synthetic third close failure"
                                ),
                            ),
                        ),
                        surface_failure=True,
                    )
                except BaseException as error:
                    caught = error
            finally:
                os.close = original_close
            cleanup_rows.append({
                "case": "non-oserror-first-cleanup",
                "terminal": (
                    type(caught).__name__
                    if caught is not None
                    else None
                ),
                "diagnostic": str(caught) if caught is not None else None,
                "cause_preserved": caught is raw_cause,
                "operations": operations,
            })

        for cleanup_primary_failure in (False, True):
            exercise_directory_cleanup(
                fail_primary=cleanup_primary_failure,
            )
            exercise_exclusive_writer_cleanup(
                fail_primary=cleanup_primary_failure,
            )
            exercise_reserved_member_cleanup(
                operation="write",
                fail_primary=cleanup_primary_failure,
            )
            exercise_reserved_member_cleanup(
                operation="read",
                fail_primary=cleanup_primary_failure,
            )
        for invalid_count_case, invalid_write_count in (
            ("bool", True),
            ("overreported", 2),
        ):
            exercise_exclusive_writer_cleanup(
                fail_primary=False,
                invalid_count=invalid_write_count,
                count_case=invalid_count_case,
            )
            exercise_reserved_member_cleanup(
                operation="write",
                fail_primary=False,
                invalid_count=invalid_write_count,
                count_case=invalid_count_case,
            )
        exercise_reserved_member_cleanup(
            operation="write",
            fail_primary=False,
            parent_close_only=True,
        )
        exercise_strict_directory_registration(non_directory=False)
        exercise_strict_directory_registration(non_directory=True)
        exercise_bounded_read_semantic_precedence(identity_change=False)
        exercise_bounded_read_semantic_precedence(identity_change=True)
        exercise_non_oserror_cleanup()

        def exercise_reserved_member_acquisition(
            operation: str,
            acquisition_kind: str,
        ) -> dict[str, Any]:
            original_open_reserved_directory = v2_open_reserved_directory
            original_open = os.open
            original_close = os.close
            prior_trace = sys.gettrace()
            parent_descriptor = 1301 if operation == "write" else 1401
            member_descriptor = 1302 if operation == "write" else 1402
            acquired: list[int] = []
            closed: list[int] = []
            primary = RuntimeError(
                "synthetic reserved-member acquisition interruption"
            )
            ownership_gap = RuntimeError(
                "synthetic reserved-member acquisition ownership gap"
            )

            def fake_reserved_directory(
                _reservation: V2BundleReservation,
                _relative: PurePosixPath,
                *,
                create: bool,
                _descriptor_slot: list[int | None] | None = None,
            ) -> int:
                del create
                if _descriptor_slot is not None:
                    list.__setitem__(
                        _descriptor_slot,
                        0,
                        parent_descriptor,
                    )
                list.append(acquired, parent_descriptor)
                return parent_descriptor

            def fake_member_open(*_args: Any, **_kwargs: Any) -> int:
                list.append(acquired, member_descriptor)
                return member_descriptor

            def fake_member_close(descriptor: int) -> None:
                list.append(closed, descriptor)

            target_code = (
                v2_write_reserved_member.__code__
                if operation == "write"
                else v2_read_reserved_member.__code__
            )

            def interrupt_reserved_member_acquisition(
                frame: types.FrameType,
                event: str,
                _argument: Any,
            ) -> Any:
                if event == "line" and frame.f_code is target_code:
                    frame_locals = frame.f_locals
                    parent_slot = frame_locals.get(
                        "parent_descriptor_slot",
                    )
                    member_slot = frame_locals.get("descriptor_slot")
                    owned = [
                        descriptor
                        for slot in (parent_slot, member_slot)
                        if type(slot) is list and len(slot) == 1
                        for descriptor in (list.__getitem__(slot, 0),)
                        if type(descriptor) is int
                    ]
                    unowned = [
                        descriptor
                        for descriptor in acquired
                        if descriptor not in closed and descriptor not in owned
                    ]
                    if unowned:
                        sys.settrace(None)
                        for descriptor in unowned:
                            fake_member_close(descriptor)
                        raise ownership_gap
                    target_slot = (
                        parent_slot
                        if acquisition_kind == "parent"
                        else member_slot
                    )
                    local_name = (
                        "parent_descriptor"
                        if acquisition_kind == "parent"
                        else "descriptor"
                    )
                    if (
                        type(target_slot) is list
                        and len(target_slot) == 1
                        and type(list.__getitem__(target_slot, 0)) is int
                        and local_name not in frame_locals
                    ):
                        sys.settrace(None)
                        raise primary
                return interrupt_reserved_member_acquisition

            globals()["v2_open_reserved_directory"] = fake_reserved_directory
            os.open = fake_member_open
            os.close = fake_member_close
            sys.settrace(interrupt_reserved_member_acquisition)
            observed: BaseException | None = None
            synthetic_reservation = V2BundleReservation(
                output=REPO_ROOT,
                artifact_root="target",
                artifact_dir="member-acquisition",
                terminal_descriptor=None,
                output_descriptor=None,
                parent_descriptor=None,
                path_anchors=(),
            )
            try:
                if operation == "write":
                    v2_write_reserved_member(
                        synthetic_reservation,
                        relative=PurePosixPath("member.json"),
                        payload=b"x",
                    )
                else:
                    v2_read_reserved_member(
                        synthetic_reservation,
                        name="member.json",
                        expected_identity={},
                    )
            except BaseException as error:
                observed = error
            finally:
                sys.settrace(prior_trace)
                globals()["v2_open_reserved_directory"] = (
                    original_open_reserved_directory
                )
                os.open = original_open
                os.close = original_close
            return {
                "primary_preserved": observed is primary,
                "acquired": acquired,
                "closed": closed,
            }

        reserved_member_acquisition_rows = {
            f"{operation}-{acquisition_kind}": (
                exercise_reserved_member_acquisition(
                    operation,
                    acquisition_kind,
                )
            )
            for operation in ("write", "read")
            for acquisition_kind in ("parent", "member")
        }

        generic_collector_close_line = min(
            instruction.positions.lineno
            for instruction in dis.get_instructions(
                v2_collect_owned_descriptor_close_failure
            )
            if instruction.argval == "close"
            and instruction.positions.lineno is not None
        )
        generic_collector_trace_reached = False
        slot_collector_close_calls: list[int] = []
        slot_collector_probe_slot: list[int | None] = [1501]
        slot_collector_probe_error: BaseException | None = None
        original_slot_collector_close = os.close
        prior_slot_collector_trace = sys.gettrace()

        def interrupt_generic_collector_close(
            frame: types.FrameType,
            event: str,
            _argument: Any,
        ) -> Any:
            nonlocal generic_collector_trace_reached
            if (
                event == "line"
                and frame.f_code
                is v2_collect_owned_descriptor_close_failure.__code__
                and frame.f_lineno == generic_collector_close_line
            ):
                generic_collector_trace_reached = True
                sys.settrace(None)
                raise RuntimeError(
                    "numeric collector must not own a slot close"
                )
            return interrupt_generic_collector_close

        os.close = lambda descriptor: list.append(
            slot_collector_close_calls,
            descriptor,
        )
        sys.settrace(interrupt_generic_collector_close)
        try:
            v2_close_owned_descriptor_slots((
                (
                    slot_collector_probe_slot,
                    InfrastructureFailed(
                        "synthetic slot collector close failed"
                    ),
                ),
            ), surface_failure=False)
        except BaseException as error:
            slot_collector_probe_error = error
        finally:
            sys.settrace(prior_slot_collector_trace)
            os.close = original_slot_collector_close

        fallback_probe_slots: tuple[list[int | None], ...] = (
            [1601],
            [1602],
            [1603],
        )
        fallback_probe_close_calls: list[int] = []
        fallback_probe_collector_calls = 0
        fallback_probe_interrupted = False
        fallback_probe_primary = RuntimeError(
            "synthetic slot collector body primary"
        )
        fallback_probe_secondary = RuntimeError(
            "synthetic slot collector fallback interruption"
        )
        fallback_probe_observed: BaseException | None = None
        original_slot_close_collector = (
            v2_collect_owned_descriptor_slot_close_failure
        )
        original_fallback_probe_close = os.close
        prior_fallback_probe_trace = sys.gettrace()
        fallback_probe_entry_line = max(
            instruction.positions.lineno
            for instruction in dis.get_instructions(
                v2_close_owned_descriptor_slots
            )
            if instruction.opname == "STORE_FAST"
            and instruction.argval == "fallback_started"
            and instruction.positions.lineno is not None
        )

        def fail_first_slot_collector_call(
            slot: list[int | None],
            typed_error: HarnessError,
        ) -> V2DescriptorCloseFailure | None:
            nonlocal fallback_probe_collector_calls
            fallback_probe_collector_calls += 1
            if fallback_probe_collector_calls == 1:
                raise fallback_probe_primary
            return original_slot_close_collector(slot, typed_error)

        def interrupt_slot_collector_fallback(
            frame: types.FrameType,
            event: str,
            _argument: Any,
        ) -> Any:
            nonlocal fallback_probe_interrupted
            if (
                event == "line"
                and frame.f_code
                is v2_close_owned_descriptor_slots.__code__
                and frame.f_lineno == fallback_probe_entry_line
                and frame.f_locals.get("active_primary")
                is fallback_probe_primary
                and frame.f_locals.get("fallback_started") is False
            ):
                fallback_probe_interrupted = True
                sys.settrace(None)
                raise fallback_probe_secondary
            return interrupt_slot_collector_fallback

        globals()["v2_collect_owned_descriptor_slot_close_failure"] = (
            fail_first_slot_collector_call
        )
        os.close = lambda descriptor: list.append(
            fallback_probe_close_calls,
            descriptor,
        )
        sys.settrace(interrupt_slot_collector_fallback)
        try:
            v2_close_owned_descriptor_slots(tuple(
                (
                    slot,
                    InfrastructureFailed(
                        "synthetic fallback probe close failed"
                    ),
                )
                for slot in fallback_probe_slots
            ), surface_failure=True)
        except BaseException as error:
            fallback_probe_observed = error
        finally:
            sys.settrace(prior_fallback_probe_trace)
            globals()["v2_collect_owned_descriptor_slot_close_failure"] = (
                original_slot_close_collector
            )
            os.close = original_fallback_probe_close

        outermost_probe_slots: tuple[list[int | None], ...] = (
            [1701],
            [1702],
            [1703],
        )
        outermost_probe_close_calls: list[int] = []
        outermost_probe_body_primary = RuntimeError(
