        outermost_probe_cleanup_primary = RuntimeError(
            "synthetic outermost cleanup interruption"
        )
        outermost_probe_observed: BaseException | None = None
        outermost_probe_interrupted = False
        prior_outermost_probe_trace = sys.gettrace()
        original_outermost_probe_close = os.close
        outermost_probe_lines = sorted({
            instruction.positions.lineno
            for instruction in dis.get_instructions(
                v2_close_owned_descriptor_slots
            )
            if instruction.argval == "drain_remaining"
            and instruction.positions.lineno is not None
        })
        outermost_probe_line = outermost_probe_lines[-2]

        def interrupt_outermost_descriptor_drain(
            frame: types.FrameType,
            event: str,
            _argument: Any,
        ) -> Any:
            nonlocal outermost_probe_interrupted
            if (
                event == "line"
                and frame.f_code
                is v2_close_owned_descriptor_slots.__code__
                and frame.f_lineno == outermost_probe_line
            ):
                outermost_probe_interrupted = True
                sys.settrace(None)
                raise outermost_probe_cleanup_primary
            return interrupt_outermost_descriptor_drain

        os.close = lambda descriptor: list.append(
            outermost_probe_close_calls,
            descriptor,
