        sys.settrace(interrupt_outermost_descriptor_drain)
        try:
            try:
                raise outermost_probe_body_primary
            finally:
                v2_close_owned_descriptor_slots(tuple(
                    (
                        slot,
                        InfrastructureFailed(
                            "synthetic outermost descriptor close failed"
                        ),
                    )
                    for slot in outermost_probe_slots
                ), surface_failure=False)
        except BaseException as error:
            outermost_probe_observed = error
        finally:
            sys.settrace(prior_outermost_probe_trace)
            os.close = original_outermost_probe_close

        cleanup_by_case = {
