        class DescriptorTransferInstructionPrimary(BaseException):
            pass

        def descriptor_transfer_probe_reservation(
            descriptor: int | None,
            *,
            role: str | None = None,
        ) -> V2BundleReservation:
            return V2BundleReservation(
                output=REPO_ROOT,
                artifact_root="target",
                artifact_dir="descriptor-instruction-probe",
                terminal_descriptor=(
                    descriptor if role == "terminal" else None
                ),
                output_descriptor=(
                    descriptor if role == "output" else None
                ),
                parent_descriptor=(
                    descriptor if role == "parent" else None
                ),
                path_anchors=(),
                handoff_owner_active=True,
            )

        def descriptor_transfer_probe_state(
            descriptor: int,
            kind: str,
        ) -> tuple[
            tuple[Any, ...],
            tuple[list[int | None], ...],
            tuple[FixtureBrDescriptorOwner, ...],
            tuple[V2BundleReservation, ...],
        ]:
            if kind == "slot-to-slot":
                source_slot: list[int | None] = [descriptor]
                destination_slot: list[int | None] = [None]
                return (
                    (source_slot, destination_slot),
                    (source_slot, destination_slot),
                    (),
                    (),
                )
            if kind == "fixture-field-to-slot":
                owner = FixtureBrDescriptorOwner(descriptor)
                destination_slot = [None]
                return (
                    (owner, destination_slot),
                    (destination_slot,),
                    (owner,),
                    (),
                )
            if kind == "reservation-field-to-slot":
                reservation = descriptor_transfer_probe_reservation(
                    descriptor,
                    role="terminal",
                )
                destination_slot = [None]
                return (
                    (reservation, "terminal", destination_slot),
                    (destination_slot,),
                    (),
                    (reservation,),
                )
            if kind == "slot-to-reservation-field":
                source_slot = [descriptor]
                reservation = descriptor_transfer_probe_reservation(None)
                return (
                    (source_slot, reservation, "terminal"),
                    (source_slot,),
                    (),
                    (reservation,),
                )
            raise EvidenceFailed(
                "descriptor instruction probe kind is malformed"
            )

        def cleanup_descriptor_transfer_probe_state(
            slots: tuple[list[int | None], ...],
            owners: tuple[FixtureBrDescriptorOwner, ...],
            reservations: tuple[V2BundleReservation, ...],
        ) -> None:
            for owner in owners:
                owner.close()
            for reservation in reservations:
                v2_close_reservation(reservation, surface_failure=False)
            v2_close_owned_descriptor_slots(tuple(
                (
                    slot,
                    InfrastructureFailed(
                        "descriptor instruction probe close failed"
                    ),
                )
                for slot in slots
            ), surface_failure=False)

        def descriptor_transfer_probe_state_is_empty(
            slots: tuple[list[int | None], ...],
            owners: tuple[FixtureBrDescriptorOwner, ...],
            reservations: tuple[V2BundleReservation, ...],
        ) -> bool:
            return (
                all(list.__getitem__(slot, 0) is None for slot in slots)
                and all(owner._descriptor is None for owner in owners)
                and all(
                    reservation.terminal_descriptor is None
                    and reservation.output_descriptor is None
                    and reservation.parent_descriptor is None
                    and reservation.handoff_owner_active is False
                    for reservation in reservations
                )
            )

        descriptor_instruction_specs = (
            (
                "slot-to-slot",
                v2_transfer_owned_descriptor_slot,
            ),
            (
                "fixture-field-to-slot",
                v2_transfer_fixture_descriptor_owner_to_slot,
            ),
            (
                "reservation-field-to-slot",
                v2_transfer_reservation_descriptor_to_slot,
            ),
            (
                "slot-to-reservation-field",
                v2_transfer_descriptor_slot_to_reservation,
            ),
        )
        descriptor_instruction_rows: list[dict[str, Any]] = []
        descriptor_instruction_mode = "CPYTHON_3_11_LINE_EVENTS_ONLY"
        descriptor_instruction_monitoring = getattr(
            sys,
            "monitoring",
            None,
        )
        descriptor_instruction_original_close = os.close
        descriptor_instruction_tool_id: int | None = None
        try:
            if descriptor_instruction_monitoring is not None:
                descriptor_instruction_mode = (
                    "CPYTHON_SYS_MONITORING_ONE_SHOT_INSTRUCTION"
                )
                descriptor_instruction_tool_id = next(
                    (
                        candidate
                        for candidate in range(6)
                        if descriptor_instruction_monitoring.get_tool(
                            candidate
                        )
                        is None
                    ),
                    None,
                )
                if descriptor_instruction_tool_id is None:
                    raise EvidenceFailed(
                        "descriptor instruction probe has no free monitoring "
                        "tool id"
                    )
                descriptor_instruction_monitoring.use_tool_id(
                    descriptor_instruction_tool_id,
                    "frankensim-descriptor-transfer-probe",
                )
                for spec_index, (kind, transfer) in enumerate(
                    descriptor_instruction_specs
                ):
                    baseline_descriptor = 2000 + spec_index
                    (
                        arguments,
                        slots,
                        owners,
                        reservations,
                    ) = descriptor_transfer_probe_state(
                        baseline_descriptor,
                        kind,
                    )
                    executed_offsets: list[int] = []

                    def capture_descriptor_instruction(
                        code: types.CodeType,
                        offset: int,
                        *,
                        target_code: types.CodeType = transfer.__code__,
                    ) -> None:
                        if code is target_code:
                            list.append(executed_offsets, offset)

                    descriptor_instruction_monitoring.register_callback(
                        descriptor_instruction_tool_id,
                        descriptor_instruction_monitoring.events.INSTRUCTION,
                        capture_descriptor_instruction,
                    )
                    descriptor_instruction_monitoring.set_local_events(
                        descriptor_instruction_tool_id,
                        transfer.__code__,
                        descriptor_instruction_monitoring.events.INSTRUCTION,
                    )
                    baseline_closed: list[int] = []
                    os.close = lambda value: list.append(
                        baseline_closed,
                        value,
                    )
                    transfer(*arguments)
                    descriptor_instruction_monitoring.set_local_events(
                        descriptor_instruction_tool_id,
                        transfer.__code__,
                        0,
                    )
                    cleanup_descriptor_transfer_probe_state(
                        slots,
                        owners,
                        reservations,
                    )
                    unique_offsets = tuple(dict.fromkeys(executed_offsets))
                    instruction_by_offset = {
                        instruction.offset: instruction
                        for instruction in dis.get_instructions(transfer)
                    }
                    failure_rows: list[dict[str, Any]] = []
                    for offset in unique_offsets:
                        descriptor = 3000 + spec_index
                        (
                            arguments,
                            slots,
                            owners,
                            reservations,
                        ) = descriptor_transfer_probe_state(
                            descriptor,
                            kind,
                        )
                        close_calls: list[int] = []
                        primary = DescriptorTransferInstructionPrimary(
                            f"{kind}:{offset}"
                        )
                        observed: BaseException | None = None

                        def interrupt_descriptor_instruction(
                            code: types.CodeType,
                            current_offset: int,
                            *,
                            target_code: types.CodeType = transfer.__code__,
                            target_offset: int = offset,
                        ) -> None:
                            if (
                                code is target_code
                                and current_offset == target_offset
                            ):
                                descriptor_instruction_monitoring.set_local_events(
                                    descriptor_instruction_tool_id,
                                    target_code,
                                    0,
                                )
                                raise primary

                        descriptor_instruction_monitoring.register_callback(
                            descriptor_instruction_tool_id,
                            descriptor_instruction_monitoring.events.INSTRUCTION,
                            interrupt_descriptor_instruction,
                        )
                        descriptor_instruction_monitoring.set_local_events(
                            descriptor_instruction_tool_id,
                            transfer.__code__,
                            descriptor_instruction_monitoring.events.INSTRUCTION,
                        )
                        os.close = lambda value: list.append(
                            close_calls,
                            value,
                        )
                        try:
                            transfer(*arguments)
                        except BaseException as error:
                            observed = error
                        finally:
                            descriptor_instruction_monitoring.set_local_events(
                                descriptor_instruction_tool_id,
                                transfer.__code__,
                                0,
                            )
                            cleanup_descriptor_transfer_probe_state(
                                slots,
                                owners,
                                reservations,
                            )
                        if (
                            observed is not primary
                            or close_calls != [descriptor]
                            or not descriptor_transfer_probe_state_is_empty(
                                slots,
                                owners,
                                reservations,
                            )
                        ):
                            instruction = instruction_by_offset[offset]
                            list.append(failure_rows, {
                                "offset": offset,
                                "opname": instruction.opname,
                                "line": instruction.positions.lineno,
                                "primary_preserved": observed is primary,
                                "close_calls": close_calls,
                                "owners_empty": (
                                    descriptor_transfer_probe_state_is_empty(
                                        slots,
                                        owners,
                                        reservations,
                                    )
                                ),
                            })
                    list.append(descriptor_instruction_rows, {
                        "kind": kind,
                        "executed_offsets": [
                            {
                                "offset": offset,
                                "opname": instruction_by_offset[offset].opname,
                                "line": instruction_by_offset[
                                    offset
                                ].positions.lineno,
                            }
                            for offset in unique_offsets
                        ],
                        "injected_count": len(unique_offsets),
                        "baseline_close_calls": baseline_closed,
                        "failure_rows": failure_rows,
                    })
            else:
                descriptor_instruction_rows = [
                    {
                        "kind": kind,
                        "executed_offsets": [],
                        "injected_count": 0,
                        "baseline_close_calls": [],
                        "failure_rows": [],
                    }
                    for kind, _transfer in descriptor_instruction_specs
                ]
        finally:
            os.close = descriptor_instruction_original_close
            if (
                descriptor_instruction_monitoring is not None
                and descriptor_instruction_tool_id is not None
            ):
                for _kind, transfer in descriptor_instruction_specs:
                    descriptor_instruction_monitoring.set_local_events(
                        descriptor_instruction_tool_id,
                        transfer.__code__,
                        0,
                    )
                descriptor_instruction_monitoring.register_callback(
                    descriptor_instruction_tool_id,
                    descriptor_instruction_monitoring.events.INSTRUCTION,
                    None,
                )
                descriptor_instruction_monitoring.free_tool_id(
                    descriptor_instruction_tool_id
                )
        descriptor_instruction_rows_by_kind = {
            row["kind"]: row for row in descriptor_instruction_rows
        }
        checks.check(
            "descriptor-ownership-transfer-instruction-matrix",
            set(descriptor_instruction_rows_by_kind)
            == {kind for kind, _transfer in descriptor_instruction_specs}
            and (
                all(
                    row["injected_count"] > 0
                    and row["baseline_close_calls"]
                    == [2000 + spec_index]
                    and row["failure_rows"] == []
                    for spec_index, row in enumerate(
                        descriptor_instruction_rows
                    )
                )
                if descriptor_instruction_monitoring is not None
                else sys.version_info[:2] == (3, 11)
                and all(
                    row["injected_count"] == 0
                    and row["failure_rows"] == []
                    for row in descriptor_instruction_rows
                )
            ),
            expected={
                "kinds": [
                    kind for kind, _transfer in descriptor_instruction_specs
                ],
                "supported_runtime": (
                    "every normally executed instruction interrupted once; "
                    "raw primary preserved; one close; no remaining owner"
                ),
                "cpython_3_11": (
                    "line-event-only fallback; no instruction-atomic claim"
                ),
                "no_claim": (
                    "pure Python does not make os.open return-to-slot or the "
                    "close-attempt marker-to-syscall edge opcode-atomic"
                ),
            },
            observed={
