            original_fsync = os.fsync
            original_fstat = os.fstat
            original_close = os.close
            prior_trace = sys.gettrace()
            base = 870 if handoff_kind == "inner" else 880
            expected_descriptors = [base + 1, base + 2, base + 3]
            acquired: list[int] = []
            closed: list[int] = []
            open_descriptors = iter(expected_descriptors[1:])
            retained_return_values: list[V2BundleReservation] = []
            reservation_slot: list[V2BundleReservation | None] = [None]
            primary = RuntimeError(
                "synthetic reservation return handoff interruption"
