            def fake_chain(*_args: Any, **kwargs: Any) -> int:
                slot = kwargs.get("_descriptor_slot")
                if type(slot) is list and len(slot) == 1:
                    list.__setitem__(slot, 0, expected_descriptors[0])
                list.append(acquired, expected_descriptors[0])
                return expected_descriptors[0]

            def fake_open(*_args: Any, **_kwargs: Any) -> int:
                descriptor = next(open_descriptors)
                list.append(acquired, descriptor)
                return descriptor

            def fake_anchor(
                path: Path,
                *,
                expect_directory: bool,
            ) -> tuple[Path, int, int, int]:
                return (
