            )
            def interrupt_reservation_return_handoff(
                frame: types.FrameType,
                event: str,
                argument: Any,
            ) -> Any:
                if (
                    event == "return"
                    and frame.f_code is target.__code__
                    and type(argument) is V2BundleReservation
                ):
                    list.append(retained_return_values, argument)
                    sys.settrace(None)
                    raise primary
                return interrupt_reservation_return_handoff

            globals()["v2_open_or_create_directory_chain"] = fake_chain
            globals()["v2_capture_path_anchor"] = fake_anchor
            globals()["v2_stat_identity"] = lambda _value: {}
            globals()["v2_assert_reservation_anchors"] = (
                lambda _reservation: None
            )
            os.mkdir = lambda *_args, **_kwargs: None
            os.open = fake_open
            os.fsync = lambda _descriptor: None
            os.fstat = lambda _descriptor: object()
            os.close = fake_close
            sys.settrace(interrupt_reservation_return_handoff)
            observed: BaseException | None = None
            retained_argument_is_slot_owner = False
            fields_before_caller_rescue: list[int | None] = []
            owner_active_before_caller_rescue: bool | None = None
            fields_after_caller_rescue: list[int | None] = []
            owner_active_after_caller_rescue: bool | None = None
            slot_after_caller_rescue: Any = None
            caller_rescue_performed = False
            try:
