        live_plan_refusal_reservation = V2BundleReservation(
            output=REPO_ROOT,
            artifact_root="target",
            artifact_dir="live-plan-cleanup-probe",
            terminal_descriptor=851,
            output_descriptor=852,
            parent_descriptor=853,
            path_anchors=(),
        )
        live_plan_refusal_close_calls: list[int] = []
        synthetic_refusal_terminal = v2_rooted({
            "schema": V2_TERMINAL_SCHEMA,
            "terminal": "InputRefused",
        })
        synthetic_refusal_failure = v2_rooted({
            "schema": V2_FAILURE_EVIDENCE_SCHEMA,
            "first_divergence": {"stage": "source_capture_round_1"},
            "recovery": ["repair the synthetic refusal"],
        })

        def synthetic_live_plan_refusal_payloads(
            **_kwargs: Any,
        ) -> tuple[dict[str, bytes], dict[str, Any]]:
            return (
                {
                    "terminal.json": canonical_bytes(
                        synthetic_refusal_terminal
                    ),
                },
                synthetic_refusal_failure,
            )

        def synthetic_live_plan_refusal_publish(
            reservation: V2BundleReservation,
            **_kwargs: Any,
        ) -> dict[str, Any]:
            reservation.terminal_assignment_started = True
            reservation.terminal_assignment_committed = True
            reservation.sealed = True
            return {}

        def fail_live_plan_refusal_close(descriptor: int) -> None:
            list.append(live_plan_refusal_close_calls, descriptor)
            if descriptor == 851:
                raise OSError(
                    errno.EIO,
                    "synthetic sealed-refusal cleanup close failure",
                )

        def deliver_live_plan_refusal_reservation(
            **kwargs: Any,
        ) -> V2BundleReservation:
            reservation_slot = kwargs.get("_reservation_slot")
            if type(reservation_slot) is not list or len(reservation_slot) != 1:
                raise EvidenceFailed(
                    "synthetic refusal reservation slot is malformed"
                )
            list.__setitem__(
                reservation_slot,
                0,
                live_plan_refusal_reservation,
            )
            return live_plan_refusal_reservation

        globals()["resolve_run_dir"] = (
            lambda *_args, **_kwargs: REPO_ROOT / "target" / "probe"
        )
        globals()["require_fresh_run_dir"] = (
            lambda *_args, **_kwargs: None
        )
        globals()["v2_reserve_bundle"] = (
            deliver_live_plan_refusal_reservation
        )
        globals()["v2_source_rule_contract"] = (
            lambda: (_ for _ in ()).throw(live_plan_refusal_primary)
        )
        globals()["v2_refusal_bundle_payloads"] = (
            synthetic_live_plan_refusal_payloads
        )
        globals()["v2_publish_reserved_bundle"] = (
            synthetic_live_plan_refusal_publish
        )
        os.close = fail_live_plan_refusal_close
        live_plan_refusal_observed: BaseException | None = None
        try:
            v2_execute_live_plan(
                mode="review-plan",
                parsed=live_plan_arguments,
                manifest={},
            )
        except BaseException as error:
            live_plan_refusal_observed = error
        finally:
            globals()["resolve_run_dir"] = original_resolve_run_dir_callable
            globals()["require_fresh_run_dir"] = (
                original_require_fresh_run_dir_callable
            )
            globals()["v2_reserve_bundle"] = original_reserve_bundle_callable
            globals()["v2_source_rule_contract"] = (
                original_source_rule_contract_callable
            )
            globals()["v2_refusal_bundle_payloads"] = (
                original_refusal_payloads_callable
            )
            globals()["v2_publish_reserved_bundle"] = (
                original_publish_reserved_callable
            )
            os.close = original_reservation_close
        live_plan_refusal_document = (
            live_plan_refusal_observed.document
            if type(live_plan_refusal_observed) is PublishedV2Refusal
            else {}
        )
        live_plan_refusal_unrooted = dict(live_plan_refusal_document)
        dict.pop(live_plan_refusal_unrooted, "semantic_root", None)

        def exercise_reservation_caller_handoff(
            caller_kind: str,
        ) -> dict[str, Any]:
            base = 890 if caller_kind == "publish" else 900
            artifact_dir = f"{caller_kind}-caller-handoff"
            reservation_holder = [
                V2BundleReservation(
                    output=REPO_ROOT,
                    artifact_root="target",
                    artifact_dir=artifact_dir,
                    terminal_descriptor=base + 1,
                    output_descriptor=base + 2,
                    parent_descriptor=base + 3,
                    path_anchors=(),
                    handoff_owner_active=True,
                )
            ]
            delivered_reservation = reservation_holder[0]
            delivered = False
            close_calls: list[int] = []
            primary = RuntimeError(
                "synthetic reservation caller handoff interruption"
            )
            phase: str | None = None
            prior_trace = sys.gettrace()

            def deliver_reservation(**kwargs: Any) -> V2BundleReservation:
                nonlocal delivered
                reservation_slot = kwargs.get("_reservation_slot")
                if (
                    type(reservation_slot) is not list
                    or len(reservation_slot) != 1
                ):
                    raise EvidenceFailed(
                        "synthetic caller reservation slot is malformed"
                    )
                delivered = True
                reservation = list.pop(reservation_holder)
                list.__setitem__(reservation_slot, 0, reservation)
                return reservation

            target = (
                v2_publish_bundle
                if caller_kind == "publish"
                else _v2_execute_live_plan_owned
            )

            def interrupt_reservation_caller_handoff(
                frame: types.FrameType,
                event: str,
                _argument: Any,
            ) -> Any:
                nonlocal phase
                if (
                    event == "line"
                    and frame.f_code is target.__code__
                    and delivered
                ):
                    local_reservation = frame.f_locals.get("reservation")
                    local_slot = frame.f_locals.get("reservation_slot")
                    slot_reservation = (
                        list.__getitem__(local_slot, 0)
                        if type(local_slot) is list and len(local_slot) == 1
                        else None
                    )
                    if (
                        type(local_reservation) is not V2BundleReservation
                        and type(slot_reservation) is V2BundleReservation
                        and slot_reservation.artifact_dir == artifact_dir
                    ):
                        phase = "caller-slot-owned-before-local-store"
                    elif (
                        type(local_reservation) is V2BundleReservation
                        and local_reservation.artifact_dir == artifact_dir
                    ):
                        phase = "caller-slot-and-local-owned"
                    else:
                        phase = "pre-delivery"
                    sys.settrace(None)
                    raise primary
                return interrupt_reservation_caller_handoff

            globals()["v2_reserve_bundle"] = deliver_reservation
            globals()["resolve_run_dir"] = (
                lambda *_args, **_kwargs: REPO_ROOT / "target" / "probe"
            )
            globals()["require_fresh_run_dir"] = (
                lambda *_args, **_kwargs: None
            )
            os.close = lambda descriptor: list.append(
                close_calls,
                descriptor,
            )
            sys.settrace(interrupt_reservation_caller_handoff)
            observed: BaseException | None = None
            try:
                if caller_kind == "publish":
                    v2_publish_bundle(
                        artifact_root="target",
                        artifact_dir="publish-caller-handoff",
                        payloads={},
                    )
                else:
                    v2_execute_live_plan(
                        mode="review-plan",
                        parsed=live_plan_arguments,
                        manifest={},
                    )
            except BaseException as error:
                observed = error
                error.__traceback__ = None
            finally:
                sys.settrace(prior_trace)
                globals()["v2_reserve_bundle"] = (
                    original_reserve_bundle_callable
                )
                globals()["resolve_run_dir"] = (
                    original_resolve_run_dir_callable
                )
                globals()["require_fresh_run_dir"] = (
                    original_require_fresh_run_dir_callable
                )
                os.close = original_reservation_close
            fields_before_test_teardown = [
                delivered_reservation.terminal_descriptor,
                delivered_reservation.output_descriptor,
                delivered_reservation.parent_descriptor,
            ]
            owner_active_before_test_teardown = (
                delivered_reservation.handoff_owner_active
            )
            delivered_reservation.terminal_descriptor = None
            delivered_reservation.output_descriptor = None
            delivered_reservation.parent_descriptor = None
            delivered_reservation.handoff_owner_active = False
            return {
                "primary_preserved": observed is primary,
                "phase": phase,
                "close_calls": close_calls,
                "fields_before_test_teardown": (
                    fields_before_test_teardown
                ),
                "owner_active_before_test_teardown": (
                    owner_active_before_test_teardown
                ),
            }

        reservation_caller_handoff_rows = {
            caller_kind: exercise_reservation_caller_handoff(caller_kind)
            for caller_kind in ("publish", "live-plan")
        }

        reservation_finalizer_transfer_line = min(
            instruction.positions.lineno
            for instruction in dis.get_instructions(
                v2_finalize_reservation_descriptor
            )
            if instruction.argval
            == "v2_transfer_reservation_descriptor_to_slot"
            and instruction.positions.lineno is not None
