        def exercise_reservation_finalizer_close_line(
            target_role: str,
            ordinal: int,
        ) -> dict[str, Any]:
            base = 9200 + ordinal * 10
            expected_close_calls = [base + 1, base + 2, base + 3]
            close_calls: list[int] = []
            interrupted = False
            observed: BaseException | None = None
            primary = RuntimeError(
                "synthetic reservation finalizer close-line interruption"
            )
            reservation = V2BundleReservation(
                output=REPO_ROOT,
                artifact_root="target",
                artifact_dir="finalizer-close-line",
                terminal_descriptor=base + 1,
                output_descriptor=base + 2,
                parent_descriptor=base + 3,
                path_anchors=(),
                handoff_owner_active=True,
            )
            original_close = os.close
            prior_trace = sys.gettrace()

            def interrupt_reservation_finalizer_close_line(
                frame: types.FrameType,
                event: str,
                _argument: Any,
            ) -> Any:
                nonlocal interrupted
                if (
                    not interrupted
                    and event == "line"
                    and frame.f_code
                    is v2_finalize_reservation_descriptor.__code__
                    and frame.f_lineno == reservation_finalizer_transfer_line
                    and frame.f_locals.get("role") == target_role
                ):
                    interrupted = True
                    sys.settrace(None)
                    raise primary
                return interrupt_reservation_finalizer_close_line

            os.close = lambda descriptor: list.append(
                close_calls,
                descriptor,
            )
            sys.settrace(interrupt_reservation_finalizer_close_line)
            try:
                reservation.__del__()
            except BaseException as error:
                observed = error
            finally:
                sys.settrace(prior_trace)
                os.close = original_close
            fields = [
                reservation.terminal_descriptor,
                reservation.output_descriptor,
                reservation.parent_descriptor,
            ]
            owner_active = reservation.handoff_owner_active
            # Never let a failing synthetic row feed fake descriptor values to
            # the interpreter's later implicit finalizer invocation.
            reservation.terminal_descriptor = None
            reservation.output_descriptor = None
            reservation.parent_descriptor = None
            reservation.handoff_owner_active = False
            return {
                "interrupted": interrupted,
                "error": observed,
                "close_calls": close_calls,
                "expected_close_calls": expected_close_calls,
                "fields": fields,
                "owner_active": owner_active,
            }

        reservation_finalizer_close_line_rows = tuple(
            exercise_reservation_finalizer_close_line(
