        def exercise_reserved_directory_failure(
            failure_mode: str,
        ) -> tuple[list[str], BaseException | None, BaseException | None]:
            original_dup = os.dup
            original_open = os.open
            original_fstat = os.fstat
            original_close = os.close
            operations: list[str] = []
            raw_failure = RuntimeError(
                "synthetic reserved-directory raw fstat failure"
            )
            return_failure = RuntimeError(
                "synthetic reserved-directory return interruption"
            )

            def fake_dup(descriptor: int) -> int:
                list.append(operations, f"dup:{descriptor}")
                if failure_mode == "dup":
                    raise OSError(errno.EIO, "synthetic dup failure")
                return 901

            def fake_open(*_args: Any, **_kwargs: Any) -> int:
                list.append(operations, "open:child")
                if failure_mode == "open":
                    raise OSError(errno.EIO, "synthetic child open failure")
                return 902

            def fake_fstat(_descriptor: int) -> Any:
                list.append(operations, "fstat:child")
                if failure_mode == "fstat":
                    raise OSError(errno.EIO, "synthetic child fstat failure")
                if failure_mode == "raw-fstat":
                    raise raw_failure
                return types.SimpleNamespace(
                    st_mode=stat.S_IFDIR | 0o755
                )

            def fake_close(descriptor: int) -> None:
                list.append(operations, f"close:{descriptor}")
                if failure_mode == "parent-close" and descriptor == 901:
                    raise OSError(
                        errno.EIO,
                        "synthetic parent close failure",
                    )

            os.dup = fake_dup
            os.open = fake_open
            os.fstat = fake_fstat
            os.close = fake_close
            observed_error: BaseException | None = None
            prior_trace = sys.gettrace()
            return_lines = frozenset(
                instruction.positions.lineno
                for instruction in dis.get_instructions(
                    _v2_open_reserved_directory_owned
                )
                if instruction.opname == "RETURN_VALUE"
                and instruction.positions.lineno is not None
            )

            def interrupt_reserved_directory_return(
                frame: types.FrameType,
                event: str,
                _argument: Any,
            ) -> Any:
                if (
                    event == "line"
                    and frame.f_code
                    is _v2_open_reserved_directory_owned.__code__
                    and frame.f_lineno in return_lines
                ):
                    sys.settrace(None)
                    raise return_failure
                return interrupt_reserved_directory_return

            if failure_mode == "return-interrupt":
                sys.settrace(interrupt_reserved_directory_return)
            result_descriptor_slot: list[int | None] = [None]
            try:
                v2_open_reserved_directory(
                    V2BundleReservation(
                        output=REPO_ROOT,
                        artifact_root="target",
                        artifact_dir="reserved-directory",
                        terminal_descriptor=None,
                        output_descriptor=900,
                        parent_descriptor=None,
                        path_anchors=(),
                    ),
                    PurePosixPath("child"),
                    create=False,
                    _descriptor_slot=result_descriptor_slot,
                )
            except BaseException as error:
                observed_error = error
            finally:
                try:
                    v2_close_owned_descriptor_slots((
                        (
                            result_descriptor_slot,
                            InfrastructureFailed(
                                "synthetic reserved-directory result close "
                                "failed"
                            ),
                        ),
                    ), surface_failure=False)
                finally:
                    sys.settrace(prior_trace)
                    os.dup = original_dup
                    os.open = original_open
                    os.fstat = original_fstat
                    os.close = original_close
            return (
                operations,
                observed_error,
                return_failure
                if failure_mode == "return-interrupt"
                else raw_failure,
            )

        reserved_directory_rows = {
            failure_mode: exercise_reserved_directory_failure(failure_mode)
            for failure_mode in (
                "dup",
                "open",
                "fstat",
                "parent-close",
                "raw-fstat",
