        original_open_directory_chain = v2_open_or_create_directory_chain
        original_capture_anchor = v2_capture_path_anchor
        original_reserve_mkdir = os.mkdir
        original_reserve_open = os.open
        original_reserve_fsync = os.fsync
        original_reserve_close = os.close
        reserve_cleanup_operations: list[str] = []
        reserve_primary = RuntimeError(
            "synthetic reserve anchor primary failure"
        )
        reserve_open_descriptors = iter((1002, 1003))

        def synthetic_reserve_open(*_args: Any, **_kwargs: Any) -> int:
            descriptor = next(reserve_open_descriptors)
            list.append(
                reserve_cleanup_operations,
                f"open:{descriptor}",
            )
            return descriptor

        def synthetic_reserve_close(descriptor: int) -> None:
            list.append(
                reserve_cleanup_operations,
                f"close:{descriptor}",
            )
            if descriptor == 1003:
                raise RuntimeError(
                    "synthetic terminal cleanup failure"
                )

        def synthetic_open_directory_chain(
            *_args: Any,
            **kwargs: Any,
        ) -> int:
            descriptor_slot = kwargs.get("_descriptor_slot")
            if type(descriptor_slot) is list and len(descriptor_slot) == 1:
                list.__setitem__(descriptor_slot, 0, 1001)
            return 1001

        globals()["v2_open_or_create_directory_chain"] = (
            synthetic_open_directory_chain
        )
        globals()["v2_capture_path_anchor"] = (
            lambda *_args, **_kwargs: (_ for _ in ()).throw(
                reserve_primary
            )
