        os.mkdir = lambda *_args, **_kwargs: None
        os.open = synthetic_reserve_open
        os.fsync = lambda _descriptor: None
        os.close = synthetic_reserve_close
        reserve_observed: BaseException | None = None
        reserve_failure_slot: list[V2BundleReservation | None] = [None]
        try:
            _v2_reserve_bundle(
                artifact_root="target",
                artifact_dir="synthetic-reserve-failure",
                _reservation_slot=reserve_failure_slot,
            )
        except BaseException as error:
            reserve_observed = error
        finally:
            globals()["v2_open_or_create_directory_chain"] = (
                original_open_directory_chain
            )
            globals()["v2_capture_path_anchor"] = original_capture_anchor
            os.mkdir = original_reserve_mkdir
            os.open = original_reserve_open
            os.fsync = original_reserve_fsync
            os.close = original_reserve_close

        def exercise_reserve_post_transfer_failure() -> dict[str, Any]:
            acquired: list[int] = []
            closed: list[int] = []
            open_descriptors = iter((1212, 1213))
            reservation_slot: list[V2BundleReservation | None] = [None]
            primary = RuntimeError(
                "synthetic post-transfer identity failure"
            )
            retained_reservation: V2BundleReservation | None = None
            observed: BaseException | None = None
            original_identity = v2_stat_identity
            original_anchor = v2_capture_path_anchor
            original_fstat = os.fstat

            def fake_post_transfer_chain(
                *_args: Any,
                **kwargs: Any,
            ) -> int:
                descriptor_slot = kwargs.get("_descriptor_slot")
                if type(descriptor_slot) is not list or len(descriptor_slot) != 1:
                    raise EvidenceFailed(
                        "synthetic post-transfer parent slot is malformed"
                    )
                list.__setitem__(descriptor_slot, 0, 1211)
                list.append(acquired, 1211)
                return 1211

            def fake_post_transfer_open(
                *_args: Any,
                **_kwargs: Any,
            ) -> int:
                descriptor = next(open_descriptors)
                list.append(acquired, descriptor)
                return descriptor

            def fake_post_transfer_anchor(
                path: Path,
                *,
                expect_directory: bool,
            ) -> tuple[Path, int, int, int]:
                return (
                    path,
                    1,
                    1210,
                    stat.S_IFDIR if expect_directory else stat.S_IFREG,
                )

            globals()["v2_open_or_create_directory_chain"] = (
                fake_post_transfer_chain
            )
            globals()["v2_capture_path_anchor"] = (
                fake_post_transfer_anchor
            )
            globals()["v2_stat_identity"] = (
                lambda _value: (_ for _ in ()).throw(primary)
            )
            os.mkdir = lambda *_args, **_kwargs: None
            os.open = fake_post_transfer_open
            os.fsync = lambda _descriptor: None
            os.fstat = lambda _descriptor: object()
            os.close = lambda descriptor: list.append(closed, descriptor)
            try:
                _v2_reserve_bundle(
                    artifact_root="target",
                    artifact_dir="synthetic-post-transfer-failure",
                    _reservation_slot=reservation_slot,
                )
            except BaseException as error:
                observed = error
                traceback_cursor = error.__traceback__
                while traceback_cursor is not None:
                    if (
                        traceback_cursor.tb_frame.f_code
                        is _v2_reserve_bundle.__code__
                    ):
                        candidate = traceback_cursor.tb_frame.f_locals.get(
                            "reservation"
                        )
                        if type(candidate) is V2BundleReservation:
                            retained_reservation = candidate
                    traceback_cursor = traceback_cursor.tb_next
            finally:
                globals()["v2_open_or_create_directory_chain"] = (
                    original_open_directory_chain
                )
                globals()["v2_capture_path_anchor"] = original_anchor
                globals()["v2_stat_identity"] = original_identity
                os.mkdir = original_reserve_mkdir
                os.open = original_reserve_open
                os.fsync = original_reserve_fsync
                os.fstat = original_fstat
                os.close = original_reserve_close
            fields_before_test_teardown = (
                [
                    retained_reservation.terminal_descriptor,
                    retained_reservation.output_descriptor,
                    retained_reservation.parent_descriptor,
                ]
                if retained_reservation is not None
                else []
            )
            owner_active_before_test_teardown = (
                retained_reservation.handoff_owner_active
                if retained_reservation is not None
                else None
            )
            slot_before_test_teardown = list.__getitem__(
                reservation_slot,
                0,
            )
            if observed is not None:
                observed.__traceback__ = None
            return {
                "primary_preserved": observed is primary,
                "acquired": acquired,
                "closed": closed,
                "retained": retained_reservation is not None,
                "fields_before_test_teardown": (
                    fields_before_test_teardown
                ),
                "owner_active_before_test_teardown": (
                    owner_active_before_test_teardown
                ),
                "slot_before_test_teardown": slot_before_test_teardown,
            }

        reserve_post_transfer_failure_row = (
            exercise_reserve_post_transfer_failure()
        )

        def exercise_reserve_acquisition_interruption(
            acquisition_kind: str,
        ) -> dict[str, Any]:
            acquired: list[int] = []
            closed: list[int] = []
            next_open_descriptor = iter((1202, 1203))
            primary = RuntimeError(
                "synthetic reserve acquisition interruption"
            )
            ownership_gap = RuntimeError(
                "synthetic reserve acquisition ownership gap"
            )
            prior_trace = sys.gettrace()

            def fake_directory_chain(
                *_args: Any,
                **kwargs: Any,
            ) -> int:
                descriptor_slot = kwargs.get("_descriptor_slot")
                if type(descriptor_slot) is list and len(descriptor_slot) == 1:
                    list.__setitem__(descriptor_slot, 0, 1201)
                list.append(acquired, 1201)
                return 1201

            def fake_reserve_open(*_args: Any, **_kwargs: Any) -> int:
                descriptor = next(next_open_descriptor)
                list.append(acquired, descriptor)
                return descriptor

            def fake_reserve_close(descriptor: int) -> None:
                list.append(closed, descriptor)

            def interrupt_reserve_acquisition(
                frame: types.FrameType,
                event: str,
                _argument: Any,
            ) -> Any:
                if (
                    event == "line"
                    and frame.f_code is _v2_reserve_bundle.__code__
                ):
                    frame_locals = frame.f_locals
                    slots = [
                        frame_locals.get("parent_descriptor_slot"),
                        frame_locals.get("output_descriptor_slot"),
                        frame_locals.get("terminal_descriptor_slot"),
                    ]
                    owned = [
                        descriptor
                        for slot in slots
                        if type(slot) is list and len(slot) == 1
                        for descriptor in (list.__getitem__(slot, 0),)
                        if type(descriptor) is int
                    ]
                    unowned = [
                        descriptor
                        for descriptor in acquired
                        if descriptor not in closed and descriptor not in owned
                    ]
                    if unowned:
                        sys.settrace(None)
                        for descriptor in unowned:
                            fake_reserve_close(descriptor)
                        raise ownership_gap
                    target_slot = {
                        "parent": slots[0],
                        "output": slots[1],
                        "terminal": slots[2],
                    }[acquisition_kind]
                    local_name = f"{acquisition_kind}_descriptor"
                    if (
                        type(target_slot) is list
                        and len(target_slot) == 1
                        and type(list.__getitem__(target_slot, 0)) is int
                        and local_name not in frame_locals
                    ):
                        sys.settrace(None)
                        raise primary
                return interrupt_reserve_acquisition

            globals()["v2_open_or_create_directory_chain"] = (
                fake_directory_chain
            )
            os.mkdir = lambda *_args, **_kwargs: None
            os.open = fake_reserve_open
            os.fsync = lambda _descriptor: None
            os.close = fake_reserve_close
            sys.settrace(interrupt_reserve_acquisition)
            observed: BaseException | None = None
            reservation_slot: list[V2BundleReservation | None] = [None]
            try:
                _v2_reserve_bundle(
                    artifact_root="target",
                    artifact_dir="synthetic-reserve-acquisition",
                    _reservation_slot=reservation_slot,
                )
            except BaseException as error:
                observed = error
            finally:
                sys.settrace(prior_trace)
                globals()["v2_open_or_create_directory_chain"] = (
                    original_open_directory_chain
                )
                os.mkdir = original_reserve_mkdir
                os.open = original_reserve_open
                os.fsync = original_reserve_fsync
                os.close = original_reserve_close
            return {
                "primary_preserved": observed is primary,
                "acquired": acquired,
                "closed": closed,
            }

        reserve_acquisition_rows = {
            acquisition_kind: exercise_reserve_acquisition_interruption(
                acquisition_kind
            )
            for acquisition_kind in ("parent", "output", "terminal")
        }
        checks.check(
            "reserved-directory-and-reserve-failure-cleanup-matrix",
            type(reserved_directory_rows["dup"][1])
            is InfrastructureFailed
            and reserved_directory_rows["dup"][0] == ["dup:900"]
            and type(reserved_directory_rows["open"][1])
            is InfrastructureFailed
            and reserved_directory_rows["open"][0]
            == ["dup:900", "open:child", "close:901"]
            and type(reserved_directory_rows["fstat"][1])
            is InfrastructureFailed
            and reserved_directory_rows["fstat"][0]
