            and reserve_post_transfer_failure_row
            == {
                "primary_preserved": True,
                "acquired": [1211, 1212, 1213],
                "closed": [1213, 1212, 1211],
                "retained": True,
                "fields_before_test_teardown": [None, None, None],
                "owner_active_before_test_teardown": False,
                "slot_before_test_teardown": None,
