                ),
                "reserve_failure_closes": [1003, 1002, 1001],
                "reserve_post-open_interruptions": (
                    "parent-output-terminal-owned-before-next-line"
                ),
                "reserve_post-transfer_failure": (
                    "retained-traceback-owner-closed-before-test-teardown"
                ),
            },
            observed={
                "reserved_directory": {
                    name: {
                        "operations": row[0],
                        "error_type": (
                            v2_raw_type_name(type(row[1]))
                            if row[1] is not None
                            else None
