        directory_chain_return_handoffs: list[bool] = []

        def exercise_directory_chain(
            *,
            fail_operation: str | None = None,
            interrupt_at: str | None = None,
        ) -> tuple[
            list[tuple[Any, ...]],
            BaseException | None,
            BaseException | None,
        ]:
            original_open = os.open
            original_mkdir = os.mkdir
            original_fstat = os.fstat
            original_fsync = os.fsync
            original_close = os.close
            operations: list[tuple[Any, ...]] = []
            opened_descriptors: list[int] = []
            closed_descriptors: list[int] = []
            next_descriptor = 100
            interruption = RuntimeError(
                f"synthetic directory-chain {interrupt_at} interruption"
            )
            ownership_gap = RuntimeError(
                "synthetic directory-chain unowned acquisition detected"
            )

            class DirectoryStat:
                st_mode = stat.S_IFDIR | 0o755

            def fake_open(
                path: Any,
                flags: int,
                mode: int = 0o777,
                *,
                dir_fd: int | None = None,
            ) -> int:
                del flags, mode
                nonlocal next_descriptor
                descriptor = next_descriptor
                next_descriptor += 1
                operations.append(
                    ("open", str(path), dir_fd, descriptor)
                )
                list.append(opened_descriptors, descriptor)
                return descriptor

            def fake_mkdir(
                path: Any,
                mode: int = 0o777,
                *,
                dir_fd: int | None = None,
            ) -> None:
                del mode
                operations.append(("mkdir", str(path), dir_fd))

            def fake_fstat(descriptor: int) -> DirectoryStat:
                operations.append(("fstat", descriptor))
                if fail_operation == "fstat":
                    raise OSError("synthetic fstat failure")
                return DirectoryStat()

            def fake_fsync(descriptor: int) -> None:
                operations.append(("fsync", descriptor))
                if fail_operation == "fsync":
                    raise OSError("synthetic fsync failure")

            def fake_close(descriptor: int) -> None:
                operations.append(("close", descriptor))
                list.append(closed_descriptors, descriptor)
                if fail_operation == "parent-close" and descriptor == 100:
                    raise OSError("synthetic parent close failure")

            os.open = fake_open
            os.mkdir = fake_mkdir
            os.fstat = fake_fstat
            os.fsync = fake_fsync
            os.close = fake_close
            error: BaseException | None = None
            prior_trace = sys.gettrace()
            return_lines = frozenset(
                instruction.positions.lineno
                for instruction in dis.get_instructions(
                    _v2_open_or_create_directory_chain_owned
                )
                if instruction.opname == "RETURN_VALUE"
                and instruction.positions.lineno is not None
            )

            def interrupt_directory_chain(
                frame: types.FrameType,
                event: str,
                _argument: Any,
            ) -> Any:
                if (
                    event != "line"
                    or frame.f_code
                    is not _v2_open_or_create_directory_chain_owned.__code__
                ):
                    return interrupt_directory_chain
                frame_locals = frame.f_locals
                descriptor_slot = frame_locals.get(
                    "descriptor_slot",
                )
                child_slot = frame_locals.get("child_slot")
                slot_owned = [
                    descriptor
                    for slot in (descriptor_slot, child_slot)
                    if type(slot) is list
                    and len(slot) == 1
                    for descriptor in (list.__getitem__(slot, 0),)
                    if type(descriptor) is int
                ]
                unowned = [
                    descriptor
                    for descriptor in opened_descriptors
                    if descriptor not in closed_descriptors
                    and descriptor not in slot_owned
                ]
                if unowned:
                    sys.settrace(None)
                    for descriptor in unowned:
                        fake_close(descriptor)
                    raise ownership_gap
                if interrupt_at == "return" and frame.f_lineno in return_lines:
                    sys.settrace(None)
                    raise interruption
                if interrupt_at in {"root-acquisition", "child-acquisition"}:
                    if (
                        interrupt_at == "root-acquisition"
                        and type(descriptor_slot) is list
                        and len(descriptor_slot) == 1
                        and type(list.__getitem__(descriptor_slot, 0)) is int
                        and type(child_slot) is list
                        and len(child_slot) == 1
                        and list.__getitem__(child_slot, 0) is None
                        and "descriptor" not in frame_locals
                        or interrupt_at == "child-acquisition"
                        and type(descriptor_slot) is list
                        and len(descriptor_slot) == 1
                        and type(list.__getitem__(descriptor_slot, 0)) is int
                        and type(child_slot) is list
                        and len(child_slot) == 1
                        and type(list.__getitem__(child_slot, 0)) is int
                        and "next_descriptor" not in frame_locals
                    ):
                        sys.settrace(None)
                        raise interruption
                if interrupt_at == "handoff":
                    if (
                        type(descriptor_slot) is list
                        and len(descriptor_slot) == 1
                        and list.__getitem__(descriptor_slot, 0) is None
                        and type(child_slot) is list
                        and len(child_slot) == 1
                        and type(list.__getitem__(child_slot, 0)) is int
                        and frame_locals.get(
                            "parent_close_failure",
                        )
                        is None
                    ):
                        sys.settrace(None)
                        raise interruption
                return interrupt_directory_chain

            if interrupt_at is not None:
                sys.settrace(interrupt_directory_chain)
            result_descriptor_slot: list[int | None] = [None]
            try:
                result_descriptor = v2_open_or_create_directory_chain(
                    PurePosixPath("alpha/beta"),
                    label="synthetic directory chain",
                    _descriptor_slot=result_descriptor_slot,
                )
                list.append(
                    directory_chain_return_handoffs,
                    type(result_descriptor) is int
                    and result_descriptor
                    == list.__getitem__(result_descriptor_slot, 0),
                )
            except BaseException as caught:
                error = caught
            finally:
                try:
                    v2_close_owned_descriptor_slots((
                        (
                            result_descriptor_slot,
                            InfrastructureFailed(
                                "synthetic directory-chain result close "
                                "failed"
                            ),
                        ),
                    ), surface_failure=False)
                finally:
                    sys.settrace(prior_trace)
                    os.open = original_open
                    os.mkdir = original_mkdir
                    os.fstat = original_fstat
                    os.fsync = original_fsync
                    os.close = original_close
            return operations, error, interruption

        acquisition_negative_slot: list[int | None] = [None]
        acquisition_negative_opened: list[int] = []
        acquisition_negative_closed: list[int] = []
        acquisition_negative_primary = RuntimeError(
            "synthetic acquisition detector negative control"
        )

        def unsafe_multiline_acquisition_negative_control() -> None:
            descriptor = 190
            list.append(acquisition_negative_opened, descriptor)
            acquisition_negative_slot[0] = descriptor

        def detect_negative_control_gap(
            frame: types.FrameType,
            event: str,
            _argument: Any,
        ) -> Any:
            if (
                event == "line"
                and frame.f_code
                is unsafe_multiline_acquisition_negative_control.__code__
                and acquisition_negative_opened
                and list.__getitem__(acquisition_negative_slot, 0) is None
            ):
                sys.settrace(None)
                list.append(
                    acquisition_negative_closed,
                    acquisition_negative_opened[-1],
                )
                raise acquisition_negative_primary
            return detect_negative_control_gap

        prior_negative_trace = sys.gettrace()
        sys.settrace(detect_negative_control_gap)
        acquisition_negative_observed: BaseException | None = None
        try:
            unsafe_multiline_acquisition_negative_control()
        except BaseException as error:
            acquisition_negative_observed = error
        finally:
            sys.settrace(prior_negative_trace)

        directory_operations, directory_error, _ = (
            exercise_directory_chain()
        )
        (
            directory_parent_close_operations,
            directory_parent_close_error,
            _,
        ) = exercise_directory_chain(fail_operation="parent-close")
        (
            directory_handoff_interrupt_operations,
            directory_handoff_interrupt_error,
            directory_handoff_interrupt_primary,
        ) = exercise_directory_chain(interrupt_at="handoff")
        (
            directory_return_interrupt_operations,
            directory_return_interrupt_error,
            directory_return_interrupt_primary,
        ) = exercise_directory_chain(interrupt_at="return")
        (
            directory_root_acquisition_operations,
            directory_root_acquisition_error,
            directory_root_acquisition_primary,
        ) = exercise_directory_chain(interrupt_at="root-acquisition")
        (
            directory_child_acquisition_operations,
            directory_child_acquisition_error,
            directory_child_acquisition_primary,
        ) = exercise_directory_chain(interrupt_at="child-acquisition")
        checks.check(
            "directory-entry-open-fstat-fsync-close-order",
            directory_error is None
            and directory_chain_return_handoffs == [True]
            and directory_operations
            == [
                ("open", str(REPO_ROOT), None, 100),
                ("mkdir", "alpha", 100),
                ("open", "alpha", 100, 101),
                ("fstat", 101),
                ("fsync", 100),
                ("close", 100),
                ("mkdir", "beta", 101),
                ("open", "beta", 101, 102),
                ("fstat", 102),
                ("fsync", 101),
                ("close", 101),
                ("close", 102),
            ]
            and type(directory_parent_close_error) is InfrastructureFailed
            and str(directory_parent_close_error)
            == "v2 reservation parent descriptor close failed"
            and isinstance(directory_parent_close_error.__cause__, OSError)
            and directory_parent_close_operations
            == [
                ("open", str(REPO_ROOT), None, 100),
                ("mkdir", "alpha", 100),
                ("open", "alpha", 100, 101),
                ("fstat", 101),
                ("fsync", 100),
                ("close", 100),
                ("close", 101),
            ]
