        prior_timeout = CAPS["subprocess_timeout_seconds"]
        try:
            for signum in (signal.SIGINT, signal.SIGTERM):
                epoch_before_signal = _cancel_signal_epoch
                request_cancel(signum, None)
                list.append(
                    signal_epoch_observations,
                    (epoch_before_signal, _cancel_signal_epoch),
                )
                for boundary in (
                    "source",
                    "audit",
                    "packing",
                    "publication",
