            prefix_fixture["output_mode"] = stat.S_IFREG | 0o644
            nondirectory_error = expect_error(
                EvidenceFailed,
                lambda: v2_persistent_terminal_prefix_state(
                    synthetic_output
                ),
                contains="path is not a directory",
            )
            checks.check(
                "persistent-prefix-nondirectory-refused",
                nondirectory_error.terminal == "EvidenceFailed",
                expected={
                    "terminal": "EvidenceFailed",
                    "diagnostic_contains": "path is not a directory",
                    "output_kind": "regular-file",
                },
                observed={
                    "terminal": nondirectory_error.terminal,
                    "diagnostic": str(nondirectory_error),
                    "output_mode": prefix_fixture["output_mode"],
                },
            )
            prefix_fixture["output_mode"] = stat.S_IFDIR | 0o755
            prefix_fixture["terminal_mode"] = stat.S_IFDIR | 0o755
            nonregular_terminal_error = expect_error(
                EvidenceFailed,
                lambda: v2_persistent_terminal_prefix_state(
                    synthetic_output
                ),
                contains="terminal is not a regular file",
            )
            checks.check(
                "persistent-prefix-nonregular-terminal-refused",
                nonregular_terminal_error.terminal == "EvidenceFailed",
                expected={
                    "terminal": "EvidenceFailed",
                    "diagnostic_contains": (
                        "terminal is not a regular file"
                    ),
                    "terminal_kind": "directory",
                },
                observed={
                    "terminal": nonregular_terminal_error.terminal,
                    "diagnostic": str(nonregular_terminal_error),
                    "terminal_mode": prefix_fixture["terminal_mode"],
                },
            )
            prefix_fixture["terminal_mode"] = stat.S_IFREG | 0o644

            original_resolve_run_dir = resolve_run_dir
            original_read_retained_bundle = v2_read_retained_bundle
            original_stability_seconds = (
                V2_PERSISTENT_TERMINAL_STABILITY_SECONDS
            )
            globals()["resolve_run_dir"] = (
                lambda *_args, **_kwargs: synthetic_output
            )
            globals()["V2_PERSISTENT_TERMINAL_STABILITY_SECONDS"] = 0.02
            try:
                partial_reads = 0

                def partial_then_complete(
                    **_kwargs: Any,
                ) -> tuple[
                    Path,
                    dict[str, bytes],
                    dict[str, Any],
                    list[dict[str, Any]],
                ]:
                    nonlocal partial_reads
                    partial_reads += 1
                    if partial_reads == 1:
                        raise InputRefused(
                            "synthetic partial terminal publication"
                        )
                    return synthetic_output, {}, {}, []

                globals()["v2_read_retained_bundle"] = (
                    partial_then_complete
                )
                _, completed_candidate = v2_persistent_e2e_location(
                    manifest,
                    label="synthetic-partial-terminal",
                )
                checks.check(
                    "persistent-partial-terminal-can-complete-during-grace",
                    partial_reads == 2
                    and completed_candidate.startswith(
                        "synthetic-partial-terminal-"
                    )
                    and "-attempt-" not in completed_candidate,
                    expected={
                        "reads": 2,
                        "candidate": "original stable identity",
                    },
                    observed={
                        "reads": partial_reads,
                        "candidate": completed_candidate,
                    },
                )

                globals()["v2_read_retained_bundle"] = (
                    lambda **_kwargs: (_ for _ in ()).throw(
                        InputRefused(
                            "synthetic malformed retained bundle"
                        )
                    )
                )
                stable_invalid_error = expect_error(
                    EvidenceFailed,
                    lambda: v2_persistent_e2e_location(
                        manifest,
                        label="synthetic-invalid-terminal",
                    ),
                    contains="stable nonempty invalid terminal",
                )
                checks.check(
                    "persistent-stable-nonempty-invalid-terminal-refused",
                    stable_invalid_error.terminal == "EvidenceFailed",
                    expected={
                        "terminal": "EvidenceFailed",
                        "diagnostic_contains": (
                            "stable nonempty invalid terminal"
                        ),
                        "recovery": "manual",
                    },
                    observed={
                        "terminal": stable_invalid_error.terminal,
                        "diagnostic": str(stable_invalid_error),
                        "partial_reads": partial_reads,
                    },
                )
            finally:
                globals()["resolve_run_dir"] = original_resolve_run_dir
                globals()["v2_read_retained_bundle"] = (
                    original_read_retained_bundle
                )
                globals()[
                    "V2_PERSISTENT_TERMINAL_STABILITY_SECONDS"
                ] = original_stability_seconds
        finally:
            os.lstat = original_lstat

    elif slug == "resource-all-caps":
