            serialized_cache_order = cache_order_projection()
            serialized_cache_identity = (
                _v2_child_transport_cache.get(
                    cache_fixture_keys["thread-a"]
                )
                is cache_fixture_values["thread-a"]
                and _v2_child_transport_cache.get(
