        def record_cap_refusal(
            check_id: str,
            error_type: type[HarnessError],
            callback: Callable[[], Any],
            *,
            contains: str,
        ) -> None:
            error = expect_error(
                error_type,
                callback,
                contains=contains,
            )
            checks.check(
                check_id,
                type(error) is error_type,
                expected=v2_harness_error_terminal(error_type),
                observed=error.terminal,
            )

