            EvidenceFailed,
            lambda: v2_sanitized_argv(
                ["x"] * (V2_COMMAND_ARGUMENTS_CAP + 1)
            ),
            contains="argument-count",
        )
        v2_sanitized_argv(["x" * V2_COMMAND_ARGUMENT_BYTES_CAP])
        record_cap_refusal(
            "argv-byte-cap-plus-one",
            EvidenceFailed,
            lambda: v2_sanitized_argv(
                ["x" * (V2_COMMAND_ARGUMENT_BYTES_CAP + 1)]
            ),
            contains="argument-byte",
        )
        exact_count_argv = [
            f"argument-{index:02d}"
            for index in range(V2_COMMAND_ARGUMENTS_CAP)
        ]
        count_plus_one_argv = [
            *exact_count_argv,
            f"argument-{V2_COMMAND_ARGUMENTS_CAP:02d}",
        ]
        utf8_boundary_unit = "é"
        utf8_unit_bytes = len(utf8_boundary_unit.encode("utf-8"))
        if V2_COMMAND_ARGUMENT_BYTES_CAP % utf8_unit_bytes != 0:
            raise EvidenceFailed(
                "command argument byte cap cannot express the UTF-8 fixture"
            )
        exact_utf8_argument = utf8_boundary_unit * (
            V2_COMMAND_ARGUMENT_BYTES_CAP // utf8_unit_bytes
        )
        utf8_plus_one_argument = exact_utf8_argument + "x"
        retained_argv_boundary_cases = (
            (
                "argument-count",
                "empty",
                [],
                "InputRefused",
            ),
            (
                "argument-count",
                "exact",
                exact_count_argv,
                "Pass",
            ),
            (
                "argument-count",
                "plus-one",
                count_plus_one_argv,
                "InputRefused",
            ),
            (
                "argument-utf8-bytes",
                "exact",
                [exact_utf8_argument],
                "Pass",
            ),
            (
                "argument-utf8-bytes",
                "plus-one",
                [utf8_plus_one_argument],
                "InputRefused",
            ),
        )

        def retained_argv_measurement(
            boundary: str,
            relation: str,
            arguments: Sequence[str],
        ) -> dict[str, Any]:
            argument_bytes = [
                len(argument.encode("utf-8"))
                for argument in arguments
            ]
            return {
                "boundary": boundary,
                "relation": relation,
                "argument_count": len(arguments),
                "maximum_argument_utf8_bytes": max(
                    argument_bytes,
                    default=0,
                ),
                "aggregate_argument_utf8_bytes": sum(argument_bytes),
                "boundary_argument_code_points": max(
                    (len(argument) for argument in arguments),
                    default=0,
                ),
            }

        observed_retained_argv_rows: list[dict[str, Any]] = []
        expected_retained_argv_rows: list[dict[str, Any]] = []
        for (
            boundary,
            relation,
            arguments,
            expected_terminal,
        ) in retained_argv_boundary_cases:
            label = f"case-81 retained {boundary} {relation}"
            measurement = retained_argv_measurement(
                boundary,
                relation,
                arguments,
            )
            arguments_before = list(arguments)
            try:
                retained_result = v2_validate_retained_argv(
                    arguments,
                    label=label,
                )
            except HarnessError as error:
                terminal = error.terminal
                admitted = False
                returned_same_value = False
                diagnostic = str(error)
            else:
                terminal = "Pass"
                admitted = True
                returned_same_value = retained_result == arguments
                diagnostic = None
            observed_retained_argv_rows.append(
                {
                    **measurement,
                    "terminal": terminal,
                    "admitted": admitted,
                    "input_unchanged": arguments == arguments_before,
                    "returned_same_value": returned_same_value,
                    "diagnostic": diagnostic,
                }
            )
            expected_retained_argv_rows.append(
                {
                    **measurement,
                    "terminal": expected_terminal,
                    "admitted": expected_terminal == "Pass",
                    "input_unchanged": True,
                    "returned_same_value": expected_terminal == "Pass",
                    "diagnostic": (
                        None
                        if expected_terminal == "Pass"
                        else (
                            f"{label} argv is malformed"
                            if not arguments
                            else (
                                f"{label} argv exceeds its bounded contract"
                            )
                        )
                    ),
                }
            )

        invalid_utf8_label = "case-81 retained invalid-utf8"
        invalid_utf8_argument = "\udcff"
        invalid_utf8_sanitizer_error = expect_error(
            EvidenceFailed,
            lambda: v2_sanitized_argv([invalid_utf8_argument]),
            contains="argument is not valid UTF-8",
        )
        invalid_utf8_error = expect_error(
            InputRefused,
            lambda: v2_validate_retained_argv(
                [invalid_utf8_argument],
                label=invalid_utf8_label,
            ),
            contains="argv is not valid UTF-8",
        )
        observed_retained_argv_rows.append({
            "boundary": "argument-utf8-validity",
            "relation": "lone-surrogate",
            "argument_count": 1,
            "boundary_argument_code_points": 1,
            "sanitizer_terminal": invalid_utf8_sanitizer_error.terminal,
            "terminal": invalid_utf8_error.terminal,
            "error_type": v2_raw_type_name(type(invalid_utf8_error)),
            "diagnostic": str(invalid_utf8_error),
        })
        expected_retained_argv_rows.append({
            "boundary": "argument-utf8-validity",
            "relation": "lone-surrogate",
            "argument_count": 1,
            "boundary_argument_code_points": 1,
            "sanitizer_terminal": "EvidenceFailed",
            "terminal": "InputRefused",
            "error_type": "InputRefused",
            "diagnostic": f"{invalid_utf8_label} argv is not valid UTF-8",
        })

        hostile_retained_list_hooks = {
            "equality": 0,
            "getitem": 0,
            "iteration": 0,
            "length": 0,
        }

        class HostileRetainedArgvList(list):
            def __eq__(self, _other: object) -> bool:
                hostile_retained_list_hooks["equality"] += 1
                raise RuntimeError("hostile retained argv list equality")

            def __getitem__(self, _index: object) -> Any:
                hostile_retained_list_hooks["getitem"] += 1
                raise RuntimeError("hostile retained argv list getitem")

            def __iter__(self) -> Iterator[Any]:
                hostile_retained_list_hooks["iteration"] += 1
                raise RuntimeError("hostile retained argv list iteration")

            def __len__(self) -> int:
                hostile_retained_list_hooks["length"] += 1
                raise RuntimeError("hostile retained argv list length")

        hostile_list_label = "case-81 retained exact-list-type"
        try:
            v2_validate_retained_argv(
                HostileRetainedArgvList(["synthetic-argument"]),
                label=hostile_list_label,
            )
        except HarnessError as hostile_list_error:
            hostile_list_terminal = hostile_list_error.terminal
            hostile_list_error_type = v2_raw_type_name(
                type(hostile_list_error)
            )
            hostile_list_diagnostic = str(hostile_list_error)
        else:
            hostile_list_terminal = "Pass"
            hostile_list_error_type = None
            hostile_list_diagnostic = None
        hostile_list_row = {
            "boundary": "exact-container-type",
            "relation": "list-subclass",
            "terminal": hostile_list_terminal,
            "error_type": hostile_list_error_type,
            "hooks": dict(hostile_retained_list_hooks),
            "diagnostic": hostile_list_diagnostic,
        }
        observed_retained_argv_rows.append(hostile_list_row)
        expected_retained_argv_rows.append({
            "boundary": "exact-container-type",
            "relation": "list-subclass",
            "terminal": "InputRefused",
            "error_type": "InputRefused",
            "hooks": {
                "equality": 0,
                "getitem": 0,
                "iteration": 0,
                "length": 0,
            },
            "diagnostic": f"{hostile_list_label} argv is malformed",
        })

        hostile_retained_string_hooks = {
            "encode": 0,
            "equality": 0,
            "iteration": 0,
            "length": 0,
        }

        class HostileRetainedArgvString(str):
            def encode(
                self,
                *_args: Any,
                **_kwargs: Any,
            ) -> bytes:
                hostile_retained_string_hooks["encode"] += 1
                raise RuntimeError("hostile retained argv string encode")

            def __eq__(self, _other: object) -> bool:
                hostile_retained_string_hooks["equality"] += 1
                raise RuntimeError("hostile retained argv string equality")

            def __iter__(self) -> Iterator[str]:
                hostile_retained_string_hooks["iteration"] += 1
                raise RuntimeError("hostile retained argv string iteration")

            def __len__(self) -> int:
                hostile_retained_string_hooks["length"] += 1
                raise RuntimeError("hostile retained argv string length")

        hostile_string_label = "case-81 retained exact-string-type"
        try:
            v2_validate_retained_argv(
                [HostileRetainedArgvString("synthetic-argument")],
                label=hostile_string_label,
            )
        except HarnessError as hostile_string_error:
