            hostile_string_error_type = v2_raw_type_name(
                type(hostile_string_error)
            )
            hostile_string_diagnostic = str(hostile_string_error)
        else:
            hostile_string_terminal = "Pass"
            hostile_string_error_type = None
            hostile_string_diagnostic = None
        hostile_string_row = {
            "boundary": "exact-element-type",
            "relation": "string-subclass",
            "terminal": hostile_string_terminal,
            "error_type": hostile_string_error_type,
            "hooks": dict(hostile_retained_string_hooks),
            "diagnostic": hostile_string_diagnostic,
        }
        observed_retained_argv_rows.append(hostile_string_row)
        expected_retained_argv_rows.append({
            "boundary": "exact-element-type",
            "relation": "string-subclass",
            "terminal": "InputRefused",
            "error_type": "InputRefused",
            "hooks": {
                "encode": 0,
                "equality": 0,
                "iteration": 0,
                "length": 0,
            },
            "diagnostic": f"{hostile_string_label} argv is malformed",
        })

        retained_mutation_source = ["stable-argument"]
        retained_mutation_sanitizer_calls = 0
        original_retained_argv_sanitizer = v2_sanitized_argv

        def mutate_retained_source_during_sanitization(
            candidate: Sequence[Any],
        ) -> list[str]:
            nonlocal retained_mutation_sanitizer_calls
            retained_mutation_sanitizer_calls += 1
            sanitized_candidate = original_retained_argv_sanitizer(
                candidate
            )
            list.__setitem__(
                retained_mutation_source,
                0,
                "changed-argument",
            )
            return sanitized_candidate

        globals()["v2_sanitized_argv"] = (
            mutate_retained_source_during_sanitization
        )
        try:
            retained_mutation_error = expect_error(
                InputRefused,
                lambda: v2_validate_retained_argv(
                    retained_mutation_source,
                    label="case-81 retained mutation",
                ),
                contains="changed while being validated",
            )
        finally:
            globals()["v2_sanitized_argv"] = (
                original_retained_argv_sanitizer
            )
        observed_retained_argv_rows.append({
            "boundary": "source-occurrence-stability",
            "relation": "changed-during-sanitization",
            "terminal": retained_mutation_error.terminal,
            "error_type": v2_raw_type_name(type(retained_mutation_error)),
            "sanitizer_calls": retained_mutation_sanitizer_calls,
            "source": list(retained_mutation_source),
            "diagnostic": str(retained_mutation_error),
        })
        expected_retained_argv_rows.append({
            "boundary": "source-occurrence-stability",
            "relation": "changed-during-sanitization",
            "terminal": "InputRefused",
            "error_type": "InputRefused",
            "sanitizer_calls": 1,
            "source": ["changed-argument"],
            "diagnostic": (
                "case-81 retained mutation argv changed while being "
                "validated"
            ),
        })

        retained_preobservation_source = [
            "first-argument",
            "original-second-argument",
        ]
        retained_preobservation_mutations = 0

        def mutate_retained_source_before_second_observation(
            frame: Any,
            event: str,
            _argument: Any,
        ) -> Any:
            nonlocal retained_preobservation_mutations
            if (
                retained_preobservation_mutations == 0
                and event == "line"
                and frame.f_code is v2_validate_retained_argv.__code__
                and frame.f_locals.get("label")
                == "case-81 retained preobservation mutation"
                and frame.f_locals.get("index") == 0
            ):
                list.__setitem__(
                    retained_preobservation_source,
                    1,
                    "changed-before-second-observation",
                )
                retained_preobservation_mutations += 1
            return mutate_retained_source_before_second_observation

        previous_trace = sys.gettrace()
        sys.settrace(mutate_retained_source_before_second_observation)
        try:
            retained_preobservation_error = expect_error(
                InputRefused,
                lambda: v2_validate_retained_argv(
                    retained_preobservation_source,
