            )
        finally:
            sys.settrace(previous_trace)
        observed_retained_argv_rows.append({
            "boundary": "source-occurrence-stability",
            "relation": "changed-before-second-observation",
            "terminal": retained_preobservation_error.terminal,
            "error_type": v2_raw_type_name(
                type(retained_preobservation_error)
            ),
            "trace_mutations": retained_preobservation_mutations,
            "source": list(retained_preobservation_source),
            "diagnostic": str(retained_preobservation_error),
        })
        expected_retained_argv_rows.append({
            "boundary": "source-occurrence-stability",
            "relation": "changed-before-second-observation",
            "terminal": "InputRefused",
            "error_type": "InputRefused",
            "trace_mutations": 1,
            "source": [
                "first-argument",
                "changed-before-second-observation",
            ],
            "diagnostic": (
                "case-81 retained preobservation mutation argv changed "
                "while being validated"
            ),
        })
        checks.check(
            "retained-argv-count-and-utf8-byte-boundaries",
            observed_retained_argv_rows
            == expected_retained_argv_rows,
            expected=expected_retained_argv_rows,
            observed=observed_retained_argv_rows,
        )
        safe_relative(
            "x" * CAPS["path_component_bytes"],
            label="fixture component",
        )
        record_cap_refusal(
            "path-component-cap-plus-one",
            UsageRefused,
            lambda: safe_relative(
                "x" * (CAPS["path_component_bytes"] + 1),
                label="fixture component",
            ),
            contains="unsafe or over-cap",
        )
        prior_stream_cap = CAPS["subprocess_stdout_bytes"]
        try:
            CAPS["subprocess_stdout_bytes"] = 16
            for stream_fd, stream_name, category in (
                (1, "stdout", "STDOUT_LIMIT"),
                (2, "stderr", "STDERR_LIMIT"),
            ):
                receipt_start = len(_command_receipts)
                error = expect_error(
                    InfrastructureFailed,
                    lambda stream_fd=stream_fd: run_command(
                        (
                            sys.executable,
                            "-c",
                            (
                                "import os; "
                                f"os.write({stream_fd}, b'x' * 17)"
                            ),
                        )
                    ),
                    contains="exceeded the bounded cap",
                )
                receipt = _command_receipts[-1]
                checks.check(
                    f"{stream_name}-capture-cap-is-exact",
                    error.terminal == "InfrastructureFailed"
                    and len(_command_receipts) == receipt_start + 1
                    and receipt["category"] == category
                    and receipt[stream_name]["bytes"] == 16
                    and receipt["cleanup_error_count"] == 0,
                    expected={
                        "category": category,
                        "retained_bytes": 16,
                        "cleanup_errors": 0,
                    },
                    observed={
                        "category": receipt["category"],
                        "retained_bytes": receipt[stream_name]["bytes"],
                        "cleanup_errors": receipt["cleanup_error_count"],
                    },
                )
            non_utf_error = expect_error(
                InfrastructureFailed,
                lambda: run_command(
                    (
                        sys.executable,
                        "-c",
                        "import os; os.write(1, bytes([255]))",
                    )
                ),
                contains="non-UTF-8",
            )
            non_utf_receipt = _command_receipts[-1]
            checks.check(
                "non-utf8-capture-retains-root-only-receipt",
                non_utf_error.terminal == "InfrastructureFailed"
                and non_utf_receipt["category"] == "NON_UTF8"
                and non_utf_receipt["stdout"]["bytes"] == 1
                and non_utf_receipt["stdout"]["body_retained"] is False,
                expected={
                    "category": "NON_UTF8",
                    "bytes": 1,
                    "body_retained": False,
                },
                observed={
                    "category": non_utf_receipt["category"],
                    **non_utf_receipt["stdout"],
                },
            )
            missing_error = expect_error(
                InfrastructureFailed,
                lambda: run_command(("missing-password=topsecret",)),
                contains="required tool not found",
            )
            missing_receipt = _command_receipts[-1]
            checks.check(
                "start-failure-receipt-redacts-sensitive-argv",
