            },
            observed={
                "terminal": oversize_error.terminal,
                "diagnostic": str(oversize_error),
                "member": oversize_member,
                "byte_length_preserved": (
                    len(oversize_publication[oversize_member])
                    == len(oversize_payloads[oversize_member])
                ),
                "output_exists": resolve_run_dir(
                    artifact_root,
                    oversize_output,
                    label="oversize replay output",
                ).exists(),
            },
        )

        root_dir = f"{fixture_base}/forged-semantic-root"
        root_payloads, _ = v2_fault_fixture_payloads(
            manifest,
            artifact_root=artifact_root,
            artifact_dir=root_dir,
        )
        forged_inventory = strict_json_loads(
            root_payloads["inventory-v2.json"],
            label="forged-root inventory seed",
            require_canonical=True,
        )
        forged_inventory["semantic_root"] = semantic_root(
            {"forged": "inventory-root"}
        )
        root_publication = dict(root_payloads)
        root_publication["inventory-v2.json"] = canonical_bytes(
            forged_inventory
        )
        if fixture_created:
            v2_publish_bundle(
                artifact_root=artifact_root,
                artifact_dir=root_dir,
                payloads=root_publication,
            )
        root_output = f"{fixture_base}/forged-root-replay-output"
        root_error = expect_error(
            EvidenceFailed,
            lambda: v2_replay_bundle(
                artifact_root=artifact_root,
                input_dir=root_dir,
                output_dir=root_output,
            ),
            contains="inventory-v2.json.semantic_root",
        )
        checks.check(
            "retained-forged-semantic-root-production-refusal",
            root_error.terminal == "EvidenceFailed"
            and not resolve_run_dir(
                artifact_root,
                root_output,
                label="forged-root replay output",
            ).exists(),
            expected={
                "terminal": "EvidenceFailed",
                "first_divergence": (
                    "inventory-v2.json.semantic_root"
                ),
                "output_exists": False,
            },
            observed={
                "terminal": root_error.terminal,
                "diagnostic": str(root_error),
                "output_exists": resolve_run_dir(
                    artifact_root,
                    root_output,
                    label="forged-root replay output",
                ).exists(),
            },
        )
        fixture_tree_root = v2_finish_fault_fixture(
            manifest,
            artifact_root=artifact_root,
            fixture_base=fixture_base,
            label="mutation-truncation-oversize-root",
        )
        checks.check(
            "retained-mutation-fixture-root",
            all(
                resolve_run_dir(
                    artifact_root,
                    f"{fixture_base}/{name}",
                    label=f"retained mutation fixture {name}",
                    must_exist=True,
                ).exists()
                for name in (
                    "truncated-source",
                    "oversize-root-mutation",
                    "forged-semantic-root",
                )
            )
            and re.fullmatch(
                r"sha256-v1:[0-9a-f]{64}",
                fixture_tree_root,
            )
            is not None,
            expected={
                "artifact_root": artifact_root,
                "fixture_base": fixture_base,
                "retained_variants": 3,
                "tree_root": fixture_tree_root,
            },
            observed={
                "artifact_root": artifact_root,
                "fixture_base": fixture_base,
                "retained_variants": 3,
                "tree_root": fixture_tree_root,
            },
        )

    elif slug == "fault-partial-publication-conflict":
        payloads, _ = v2_synthetic_payloads(manifest)
        events = v2_read_event_stream(payloads["events.jsonl"])
        second_terminal = dict(events[-1])
        second_terminal["sequence"] = len(events)
        duplicate_terminal = b"".join(
            canonical_bytes(row) for row in [*events, second_terminal]
        )
        checks.refuses(
            "duplicate-terminal-refused",
            EvidenceFailed,
            lambda: v2_read_event_stream(duplicate_terminal),
            contains="unique and last",
        )
        artifact_root, fixture_base, fixture_created = (
            v2_fresh_fault_fixture_base(
                manifest,
                label="fault-partial-publication-conflict",
            )
        )
        partial_dir = f"{fixture_base}/partial-prefix"
        partial_payloads, _ = v2_fault_fixture_payloads(
            manifest,
            artifact_root=artifact_root,
            artifact_dir=partial_dir,
        )
        if fixture_created:
            partial_reservation_slot: list[
                V2BundleReservation | None
            ] = [None]
            try:
                v2_reserve_bundle(
                    artifact_root=artifact_root,
                    artifact_dir=partial_dir,
                    _reservation_slot=partial_reservation_slot,
                )
                reservation = list.__getitem__(
                    partial_reservation_slot,
                    0,
                )
                if type(reservation) is not V2BundleReservation:
                    raise EvidenceFailed(
                        "partial-publication fixture reservation ownership "
                        "was lost"
                    )
                for name in ("source-v2.json", "inventory-v2.json"):
                    reservation.written_identities[name] = (
                        v2_write_reserved_member(
                            reservation,
                            relative=PurePosixPath(name),
                            payload=partial_payloads[name],
                        )
                    )
            finally:
                owned_partial_reservation = list.__getitem__(
                    partial_reservation_slot,
                    0,
                )
                if type(owned_partial_reservation) is V2BundleReservation:
                    try:
                        v2_close_reservation(owned_partial_reservation)
                    finally:
                        list.__setitem__(
                            partial_reservation_slot,
                            0,
                            None,
                        )
        partial_output = resolve_run_dir(
            artifact_root,
            partial_dir,
            label="partial-publication fixture",
            must_exist=True,
        )
        partial_error = expect_error(
            InputRefused,
            lambda: v2_read_retained_bundle(
                artifact_root=artifact_root,
                input_dir=partial_dir,
            ),
            contains="terminal.json is malformed JSON",
        )
        observed_files, observed_directories, observed_identities = (
            v2_enumerate_bundle(partial_output)
        )
        expected_membership = {
            name: "PRESENT" for name in sorted(V2_RUN_ARTIFACTS)
        }
        observed_membership = {
            name: "PRESENT" for name in observed_files
        }
        recovery = v2_failure_evidence(
            stage="publication",
            detail=str(partial_error),
            expected=expected_membership,
            observed=observed_membership,
            manifest_root=manifest["semantic_root"],
            available_roots={
                "source": strict_json_loads(
                    partial_payloads["source-v2.json"],
                    label="partial-prefix retained source",
                    require_canonical=True,
                )["semantic_root"],
                "inventory": strict_json_loads(
                    partial_payloads["inventory-v2.json"],
                    label="partial-prefix retained inventory",
                    require_canonical=True,
                )["semantic_root"],
                "authority": None,
                "review_plan": None,
                "history": None,
                "zero_sets": None,
            },
        )
        checks.check(
            "retained-partial-prefix-manual-recovery",
            partial_error.terminal == "InputRefused"
            and observed_files
            == sorted(
                [
                    "inventory-v2.json",
                    "source-v2.json",
                    "terminal.json",
                ]
            )
            and observed_directories == []
            and observed_identities["terminal.json"]["size"] == 0
            and recovery["first_divergence"]
            == "$.authority-v2.json"
            and recovery["recovery"] == "MANUAL_RECOVERY_REQUIRED"
            and recovery["terminal"] == "EvidenceFailed"
            and recovery["detail_root"] == text_root(str(partial_error))
            and recovery["available_roots"]["source"]
            is not None
            and recovery["available_roots"]["inventory"]
            is not None
            and all(
                recovery["available_roots"][name] is None
                for name in (
                    "authority",
                    "review_plan",
                    "history",
                    "zero_sets",
                )
            )
            and recovery["complete_green_prefix"] is False
            and recovery["retry_requires_fresh_run_dir"] is True,
            expected={
                "reader_terminal": "InputRefused",
                "first_divergence": "$.authority-v2.json",
                "recovery": "MANUAL_RECOVERY_REQUIRED",
                "terminal_bytes": 0,
                "complete_green_prefix": False,
            },
            observed={
                "reader_terminal": partial_error.terminal,
                "reader_diagnostic": str(partial_error),
                "files": observed_files,
                "directories": observed_directories,
                "terminal_bytes": observed_identities["terminal.json"][
                    "size"
                ],
                "failure_evidence": recovery,
            },
        )
        before_conflict = {
            "files": observed_files,
            "directories": observed_directories,
            "identities": observed_identities,
        }
        conflict_error = expect_error(
            EvidenceFailed,
            lambda: v2_publish_bundle(
                artifact_root=artifact_root,
                artifact_dir=partial_dir,
                payloads=partial_payloads,
            ),
            contains="already exists",
        )
        after_files, after_directories, after_identities = (
            v2_enumerate_bundle(partial_output)
        )
        after_conflict = {
            "files": after_files,
            "directories": after_directories,
            "identities": after_identities,
        }
        checks.check(
            "retained-partial-prefix-conflicting-retry-refused",
            conflict_error.terminal == "EvidenceFailed"
            and after_conflict == before_conflict
            and after_identities["terminal.json"]["size"] == 0,
            expected={
                "terminal": "EvidenceFailed",
                "prefix_unchanged": True,
                "terminal_bytes": 0,
            },
            observed={
                "terminal": conflict_error.terminal,
                "diagnostic": str(conflict_error),
                "prefix_unchanged": after_conflict == before_conflict,
                "terminal_bytes": after_identities["terminal.json"]["size"],
            },
        )

        duplicate_dir = f"{fixture_base}/duplicate-terminal-event"
        duplicate_payloads, _ = v2_fault_fixture_payloads(
            manifest,
            artifact_root=artifact_root,
            artifact_dir=duplicate_dir,
        )
        duplicate_events = v2_read_event_stream(
            duplicate_payloads["events.jsonl"]
        )
        extra_terminal = dict(duplicate_events[-1])
        extra_terminal["sequence"] = len(duplicate_events)
        duplicate_publication = dict(duplicate_payloads)
        duplicate_publication["events.jsonl"] = b"".join(
            canonical_bytes(row)
            for row in [*duplicate_events, extra_terminal]
        )
        if fixture_created:
            v2_publish_bundle(
                artifact_root=artifact_root,
                artifact_dir=duplicate_dir,
                payloads=duplicate_publication,
            )
        duplicate_error = expect_error(
            EvidenceFailed,
            lambda: v2_read_retained_bundle(
                artifact_root=artifact_root,
                input_dir=duplicate_dir,
            ),
            contains="unique and last",
        )
        duplicate_recovery = v2_failure_evidence(
            stage="terminal-event-conflict",
            detail=str(duplicate_error),
            expected=v2_payload_identity_projection(
                duplicate_payloads
            ),
            observed=v2_payload_identity_projection(
                duplicate_publication
            ),
            manifest_root=manifest["semantic_root"],
        )
        checks.check(
            "retained-duplicate-terminal-manual-recovery",
            duplicate_error.terminal == "EvidenceFailed"
            and duplicate_recovery["first_divergence"]
            == "$.events.jsonl.byte_length"
            and duplicate_recovery["recovery"]
            == "MANUAL_RECOVERY_REQUIRED"
            and duplicate_recovery["terminal"] == "EvidenceFailed"
            and duplicate_recovery["complete_green_prefix"] is False,
            expected={
                "reader_terminal": "EvidenceFailed",
                "first_divergence": "$.events.jsonl.byte_length",
                "recovery": "MANUAL_RECOVERY_REQUIRED",
            },
            observed={
                "reader_terminal": duplicate_error.terminal,
                "reader_diagnostic": str(duplicate_error),
                "failure_evidence": duplicate_recovery,
            },
        )
        fixture_tree_root = v2_finish_fault_fixture(
            manifest,
            artifact_root=artifact_root,
            fixture_base=fixture_base,
            label="fault-partial-publication-conflict",
        )
        checks.check(
            "retained-partial-conflict-fixture-root",
            partial_output.exists()
            and resolve_run_dir(
                artifact_root,
                duplicate_dir,
                label="duplicate-terminal fixture",
                must_exist=True,
            ).exists()
            and re.fullmatch(
                r"sha256-v1:[0-9a-f]{64}",
                fixture_tree_root,
            )
            is not None,
            expected={
                "artifact_root": artifact_root,
                "fixture_base": fixture_base,
                "retained_variants": 2,
                "tree_root": fixture_tree_root,
            },
            observed={
                "artifact_root": artifact_root,
                "fixture_base": fixture_base,
                "retained_variants": 2,
                "tree_root": fixture_tree_root,
            },
        )

    elif slug == "fault-replay-manual-recovery":
        artifact_root, fixture_base, fixture_created = (
            v2_fresh_fault_fixture_base(
                manifest,
                label="fault-replay-manual-recovery",
            )
        )
        scenarios: list[
            tuple[
                str,
                str,
                dict[str, bytes],
                dict[str, bytes],
                type[HarnessError],
                str,
                str,
            ]
        ] = []

        mismatch_dir = f"{fixture_base}/replay-mismatch"
        mismatch_expected, _ = v2_fault_fixture_payloads(
            manifest,
            artifact_root=artifact_root,
            artifact_dir=mismatch_dir,
        )
        mismatch_source = strict_json_loads(
            mismatch_expected["source-v2.json"],
            label="replay-mismatch source seed",
            require_canonical=True,
        )
        mismatch_source["semantic_root"] = semantic_root(
            {"forged": "replay-source-root"}
        )
        mismatch_observed = dict(mismatch_expected)
        mismatch_observed["source-v2.json"] = canonical_bytes(
            mismatch_source
        )
        scenarios.append(
            (
                "replay-mismatch",
                mismatch_dir,
                mismatch_expected,
                mismatch_observed,
                EvidenceFailed,
                "source-v2.json.semantic_root",
                "$.source-v2.json.content_root",
            )
        )

        ambiguous_source_dir = f"{fixture_base}/ambiguous-source"
        ambiguous_source_expected, _ = v2_fault_fixture_payloads(
            manifest,
            artifact_root=artifact_root,
            artifact_dir=ambiguous_source_dir,
        )
        ambiguous_source_observed = dict(ambiguous_source_expected)
        ambiguous_source_observed["source-copy.json"] = (
            ambiguous_source_expected["source-v2.json"]
        )
        scenarios.append(
            (
                "ambiguous-source",
                ambiguous_source_dir,
                ambiguous_source_expected,
                ambiguous_source_observed,
                InputRefused,
                "source-copy.json",
                "$.source-copy.json",
            )
        )

        audit_conflict_dir = f"{fixture_base}/audit-conflict"
        audit_expected, _ = v2_fault_fixture_payloads(
            manifest,
            artifact_root=artifact_root,
            artifact_dir=audit_conflict_dir,
        )
        audit_events = v2_read_event_stream(
            audit_expected["events.jsonl"]
        )
        audit_event_index = next(
            (
                index
                for index, event in enumerate(audit_events)
                if event["stage"].startswith("source-command-")
            ),
            None,
        )
        if audit_event_index is None:
            raise EvidenceFailed(
                "audit-conflict fixture lacks a source-command event"
            )
        conflicted_audit_event = strict_json_loads(
            canonical_bytes(audit_events[audit_event_index]),
            label="audit-conflict event seed",
            require_canonical=True,
        )
        conflicted_audit_event["semantic_projection"][
            "command_receipt_root"
        ] = semantic_root({"forged": "audit-command-receipt"})
        conflicted_audit_events = list(audit_events)
        conflicted_audit_events[audit_event_index] = (
            conflicted_audit_event
        )
        audit_observed = dict(audit_expected)
        audit_observed["events.jsonl"] = b"".join(
            canonical_bytes(event) for event in conflicted_audit_events
        )
        scenarios.append(
            (
                "audit-conflict",
                audit_conflict_dir,
                audit_expected,
                audit_observed,
                EvidenceFailed,
                "terminal event/reproduction seal differs",
                "$.events.jsonl.content_root",
            )
        )

        publication_dir = f"{fixture_base}/publication-ambiguity"
        publication_expected, _ = v2_fault_fixture_payloads(
            manifest,
            artifact_root=artifact_root,
            artifact_dir=publication_dir,
        )
        publication_observed = dict(publication_expected)
        publication_observed["terminal-copy.json"] = (
            publication_expected["terminal.json"]
        )
        scenarios.append(
            (
                "publication-ambiguity",
                publication_dir,
                publication_expected,
                publication_observed,
                InputRefused,
                "terminal-copy.json",
                "$.terminal-copy.json",
            )
        )

        for (
            label,
            input_dir,
            expected_payloads,
            observed_payloads,
            error_type,
            diagnostic,
            expected_divergence,
        ) in scenarios:
            if fixture_created:
                v2_publish_bundle(
                    artifact_root=artifact_root,
                    artifact_dir=input_dir,
                    payloads=observed_payloads,
                )
            output_dir = f"{fixture_base}/{label}-replay-output"
            replay_error = expect_error(
                error_type,
                lambda input_dir=input_dir, output_dir=output_dir: (
                    v2_replay_bundle(
                        artifact_root=artifact_root,
                        input_dir=input_dir,
                        output_dir=output_dir,
                    )
                ),
                contains=diagnostic,
            )
            expected_projection = v2_payload_identity_projection(
                expected_payloads
            )
            observed_projection = v2_payload_identity_projection(
                observed_payloads
            )
            evidence = v2_failure_evidence(
                stage=label,
                detail=str(replay_error),
                expected=expected_projection,
                observed=observed_projection,
                manifest_root=manifest["semantic_root"],
                available_roots={
                    "source": strict_json_loads(
                        expected_payloads["source-v2.json"],
                        label=f"{label} expected source",
                        require_canonical=True,
                    )["semantic_root"],
                    "inventory": strict_json_loads(
                        expected_payloads["inventory-v2.json"],
                        label=f"{label} expected inventory",
                        require_canonical=True,
                    )["semantic_root"],
                    "authority": strict_json_loads(
                        expected_payloads["authority-v2.json"],
                        label=f"{label} expected authority",
                        require_canonical=True,
                    )["semantic_root"],
                    "review_plan": strict_json_loads(
                        expected_payloads["review-plan-v2.json"],
                        label=f"{label} expected review plan",
                        require_canonical=True,
                    )["semantic_root"],
                    "history": strict_json_loads(
                        expected_payloads["history-v2.json"],
                        label=f"{label} expected history",
                        require_canonical=True,
                    )["semantic_root"],
                    "zero_sets": strict_json_loads(
                        expected_payloads["zero-sets-v2.json"],
                        label=f"{label} expected zero sets",
                        require_canonical=True,
                    )["semantic_root"],
                },
            )
            checks.check(
                label,
                replay_error.terminal == error_type.terminal
                and evidence["first_divergence"] == expected_divergence
                and evidence["recovery"] == "MANUAL_RECOVERY_REQUIRED"
                and evidence["terminal"] == "EvidenceFailed"
                and evidence["complete_green_prefix"] is False
                and evidence["retry_requires_fresh_run_dir"] is True
                and evidence["detail_root"] == text_root(str(replay_error))
                and evidence["manifest_root"] == manifest["semantic_root"]
                and all(
                    isinstance(root, str)
                    and root.startswith("sha256-v1:")
                    for root in evidence["available_roots"].values()
                )
                and not resolve_run_dir(
                    artifact_root,
                    output_dir,
                    label=f"{label} replay output",
                ).exists(),
                expected={
                    "validator_terminal": error_type.terminal,
                    "first_divergence": expected_divergence,
                    "recovery": "MANUAL_RECOVERY_REQUIRED",
                    "failure_terminal": "EvidenceFailed",
                    "output_exists": False,
                },
                observed={
                    "validator_terminal": replay_error.terminal,
                    "validator_diagnostic": str(replay_error),
                    "failure_evidence": evidence,
                    "output_exists": resolve_run_dir(
                        artifact_root,
                        output_dir,
                        label=f"{label} replay output",
                    ).exists(),
                },
            )
        fixture_tree_root = v2_finish_fault_fixture(
            manifest,
            artifact_root=artifact_root,
            fixture_base=fixture_base,
            label="fault-replay-manual-recovery",
        )
        checks.check(
            "retained-replay-recovery-fixture-root",
            all(
                resolve_run_dir(
                    artifact_root,
                    input_dir,
                    label=f"retained recovery fixture {label}",
                    must_exist=True,
                ).exists()
                for label, input_dir, *_ in scenarios
            )
            and re.fullmatch(
                r"sha256-v1:[0-9a-f]{64}",
                fixture_tree_root,
            )
            is not None,
            expected={
                "artifact_root": artifact_root,
                "fixture_base": fixture_base,
                "retained_variants": len(scenarios),
                "tree_root": fixture_tree_root,
            },
            observed={
                "artifact_root": artifact_root,
                "fixture_base": fixture_base,
                "retained_variants": len(scenarios),
                "tree_root": fixture_tree_root,
            },
        )

    else:
        raise EvidenceFailed(f"no fault/resource executor for {slug}")
    return checks.finish(parameters)


def v2_nomock_bv_projection() -> dict[str, Any]:
    completed = run_command(("bv", "--robot-triage"))
    document = strict_json_loads(
        completed.stdout,
        label="bv robot triage",
    )
    if not isinstance(document, dict):
        raise InfrastructureFailed("bv robot triage is not an object")
    triage = document.get("triage")
    if not isinstance(triage, dict):
        raise InfrastructureFailed("bv robot triage lacks triage data")
    meta = triage.get("meta")
    health = triage.get("project_health")
    quick = triage.get("quick_ref")
    if not all(isinstance(value, dict) for value in (meta, health, quick)):
        raise InfrastructureFailed("bv robot triage stable sections are malformed")
    projection = {
        "data_hash": str(document.get("data_hash") or ""),
        "version": str(meta.get("version") or ""),
        "issue_count": meta.get("issue_count"),
        "phase2_ready": meta.get("phase2_ready"),
        "counts": health.get("counts"),
        "graph": health.get("graph"),
        "quick_ref": {
            "open_count": quick.get("open_count"),
            "actionable_count": quick.get("actionable_count"),
            "blocked_count": quick.get("blocked_count"),
            "in_progress_count": quick.get("in_progress_count"),
        },
        "robot_mode": "--robot-triage",
        "raw_generated_at_retained": False,
    }
    return v2_rooted(projection)


def v2_nomock_history_evidence(
    manifest: Mapping[str, Any],
) -> dict[str, Any]:
    contract = manifest["history_contract"]
    anchor_id = str(contract["legacy_coverage_anchor_issue"])
    legacy_id = "frankensim-0aeh"
    first = v2_normalize_released_br_list_rows(
        br_read_json(
            "list",
            "--status",
            "closed",
            "--json",
            "--limit",
            "0",
        ),
        label="no-mock closed list first",
    )
    show_document = br_read_json("show", anchor_id, legacy_id, "--json")
    if not isinstance(show_document, list) or len(show_document) != 2:
        raise InfrastructureFailed("no-mock history show did not return two rows")
    show_by_id = {
        str(row.get("id") or ""): v2_full_issue_projection(row)
        for row in show_document
        if isinstance(row, dict)
    }
    if set(show_by_id) != {anchor_id, legacy_id}:
        raise InfrastructureFailed("no-mock history show membership differs")
    anchor_first = v2_capture_one_audit(anchor_id, capture_ordinal=1)[1]
    anchor_second = v2_capture_one_audit(anchor_id, capture_ordinal=2)[1]
    legacy_first = v2_capture_one_audit(legacy_id, capture_ordinal=1)[1]
    legacy_second = v2_capture_one_audit(legacy_id, capture_ordinal=2)[1]
    if anchor_first != anchor_second or legacy_first != legacy_second:
        raise InputRefused("ConcurrentDrift: selected audit evidence changed")
    second = v2_normalize_released_br_list_rows(
        br_read_json(
            "list",
            "--status",
            "closed",
            "--json",
            "--limit",
            "0",
        ),
        label="no-mock closed list second",
    )
    if first != second:
        divergence = first_projection_divergence(first, second)
        raise InputRefused(
            "ConcurrentDrift: normalized closed rows changed during audit at "
            f"{divergence or '$'}"
        )
    first_projection = [
        {
            "id": row["id"],
            "closed_at": str(row.get("closed_at") or ""),
            "close_reason": str(row.get("close_reason") or ""),
        }
        for row in first
    ]
    anchor_timestamp = v2_parse_timestamp(
        contract["legacy_coverage_anchor_closed_at"],
        label="no-mock history anchor",
    )
    legacy_rows = sorted(
        [
            {
                "id": row["id"],
                "closed_at": row["closed_at"],
                "close_reason_root": text_root(row["close_reason"]),
            }
            for row in first_projection
            if row["closed_at"]
            and v2_parse_timestamp(
                row["closed_at"],
                label=f"no-mock closed {row['id']}",
            )
            < anchor_timestamp
        ],
        key=lambda row: row["id"],
    )
    status_id = int(contract["legacy_coverage_anchor_status_event_id"])
    close_id = int(contract["legacy_coverage_anchor_close_event_id"])
    anchor_events = {
        event["id"]: event for event in anchor_first["events"]
    }
    status_event = anchor_events.get(status_id)
    close_event = anchor_events.get(close_id)
    if (
        status_event is None
        or close_event is None
        or status_event.get("new_value") != "closed"
        or close_event.get("comment") != show_by_id[anchor_id]["close_reason"]
        or status_event.get("actor") != close_event.get("actor")
    ):
        raise EvidenceFailed("no-mock known closer pair differs")
    if legacy_first["events"]:
        raise EvidenceFailed("no-mock legacy issue unexpectedly has audit events")
    evidence = v2_rooted(
        {
            "anchor_id": anchor_id,
            "anchor_target_root": v2_target_root(show_by_id[anchor_id]),
            "anchor_audit_root": anchor_first["semantic_root"],
            "anchor_actor": close_event.get("actor"),
            "known_pair": [status_id, close_id],
            "legacy_id": legacy_id,
            "legacy_target_root": v2_target_root(show_by_id[legacy_id]),
            "legacy_audit_root": legacy_first["semantic_root"],
            "legacy_count": len(legacy_rows),
            "legacy_rows_root": semantic_root(legacy_rows),
            "closed_membership_count": len(first_projection),
            "closed_projection_root": semantic_root(first_projection),
            "capture_count": 2,
            "raw_stream_bodies_retained": False,
            "no_claim": (
                "released-br audit evidence proves only exact known and "
                "legacy-unavailable closure provenance"
            ),
        }
    )
    if (
        evidence["legacy_count"] != contract["legacy_coverage_count"]
        or evidence["legacy_rows_root"] != contract["legacy_coverage_rows_root"]
    ):
        raise EvidenceFailed("no-mock legacy coverage receipt differs")
    return dict(evidence)


def v2_reconstruct_payload_map(
    payloads: Mapping[str, bytes],
    accepted_manifest: Mapping[str, Any],
    current_source_files: list[dict[str, Any]],
) -> tuple[
    dict[str, Any],
    dict[str, Any],
    dict[str, Any],
    dict[str, Any],
    dict[str, Any],
    dict[str, Any],
    dict[str, bytes],
]:
    terminal = strict_json_loads(
        payloads["terminal.json"],
        label="no-mock retained terminal",
        require_canonical=True,
    )
    events = v2_read_event_stream(payloads["events.jsonl"])
    return v2_reconstruct_retained(
        artifact_root=str(terminal["artifact_root"]),
        input_dir=str(terminal["artifact_dir"]),
        payloads=payloads,
        terminal=terminal,
        events=events,
        accepted_manifest=accepted_manifest,
        current_source_files=current_source_files,
    )


def v2_select_persistent_attempt(
    base: str,
    *,
    probe: Callable[[str], str],
) -> str:
    attempt = 1
    while attempt <= V2_PERSISTENT_ATTEMPTS_CAP:
        check_cancel()
        candidate = (
            base
            if attempt == 1
            else f"{base}-attempt-{attempt:04d}"
        )
        state = probe(candidate)
        if state not in {"AVAILABLE", "COMPLETE", "INCOMPLETE"}:
            raise EvidenceFailed(
                "persistent fixture attempt probe returned an unknown state"
            )
        if state in {"AVAILABLE", "COMPLETE"}:
            return candidate
        attempt += 1
    raise EvidenceFailed(
        "persistent fixture exhausted its bounded fresh-attempt budget"
    )


def v2_persistent_terminal_prefix_state(output: Path) -> str:
    try:
        output_stat = os.lstat(output)
    except FileNotFoundError:
        return "AVAILABLE"
    except OSError as error:
        raise EvidenceFailed(
            "persistent fixture directory cannot be inspected safely"
        ) from error
    if not stat.S_ISDIR(output_stat.st_mode):
        raise EvidenceFailed(
            "persistent fixture path is not a directory"
        )
    terminal = output / "terminal.json"
    try:
        terminal_stat = os.lstat(terminal)
    except FileNotFoundError:
        return "EMPTY_PREFIX"
    except OSError as error:
        raise EvidenceFailed(
            "persistent fixture terminal cannot be inspected safely"
        ) from error
    if not stat.S_ISREG(terminal_stat.st_mode):
        raise EvidenceFailed(
            "persistent fixture terminal is not a regular file"
        )
    return (
        "EMPTY_PREFIX"
        if terminal_stat.st_size == 0
        else "NONEMPTY_TERMINAL"
    )


def v2_observe_stable_invalid_terminal(
    previous: tuple[int, int, int, int, int] | None,
    previous_count: int,
    current: tuple[int, int, int, int, int],
) -> tuple[tuple[int, int, int, int, int], int, bool]:
    if (
        previous is not None
        and (
            len(previous) != 5
            or any(type(value) is not int or value < 0 for value in previous)
        )
    ):
        raise EvidenceFailed(
            "persistent invalid-terminal prior signature is malformed"
        )
    if (
        type(previous_count) is not int
        or previous_count < 0
        or len(current) != 5
        or any(type(value) is not int or value < 0 for value in current)
    ):
        raise EvidenceFailed(
            "persistent invalid-terminal observation is malformed"
        )
    count = previous_count + 1 if current == previous else 1
    return current, count, count >= 2


def v2_persistent_e2e_location(
    manifest: Mapping[str, Any],
    *,
    label: str,
    identity_binding: Any = None,
) -> tuple[str, str]:
    script_payload = bounded_read(REPO_ROOT / SCRIPT_REL)
    identity = hashlib.sha256(
        canonical_bytes(
            {
                "manifest_content_identity": manifest["content_identity"],
                "script_content_identity": (
                    "sha256-v1:"
                    + hashlib.sha256(script_payload).hexdigest()
                ),
                "label": label,
                "identity_binding": identity_binding,
            }
        )
    ).hexdigest()[:24]
    artifact_root = "target/beads-template-hygiene/v2-e2e"
    base = f"{label}-{identity}"

    def probe(candidate: str) -> str:
        output = resolve_run_dir(
            artifact_root,
            candidate,
            label="persistent v2 fixture candidate",
        )
        prefix_state = v2_persistent_terminal_prefix_state(output)
        if prefix_state == "AVAILABLE":
            return "AVAILABLE"
        if prefix_state == "EMPTY_PREFIX":
            return "INCOMPLETE"
        deadline = (
            time.monotonic()
            + V2_PERSISTENT_TERMINAL_STABILITY_SECONDS
        )
        prior_signature: tuple[int, int, int, int, int] | None = None
        stable_observations = 0
        last_error: HarnessError | None = None
        while True:
            check_cancel()
            try:
                v2_read_retained_bundle(
                    artifact_root=artifact_root,
                    input_dir=candidate,
                )
                return "COMPLETE"
            except (InputRefused, EvidenceFailed) as error:
                last_error = error
            current_state = v2_persistent_terminal_prefix_state(output)
            if current_state != "NONEMPTY_TERMINAL":
                return "INCOMPLETE"
            try:
                terminal_stat = os.lstat(output / "terminal.json")
            except OSError as error:
                raise EvidenceFailed(
                    "persistent fixture terminal changed during bounded "
                    "stability observation"
                ) from error
            signature = (
                int(terminal_stat.st_dev),
                int(terminal_stat.st_ino),
                int(terminal_stat.st_size),
                int(terminal_stat.st_mtime_ns),
                int(terminal_stat.st_ctime_ns),
            )
            (
                prior_signature,
                stable_observations,
                stable_invalid,
            ) = v2_observe_stable_invalid_terminal(
                prior_signature,
                stable_observations,
                signature,
            )
            remaining = deadline - time.monotonic()
            if remaining <= 0 and stable_invalid:
                raise EvidenceFailed(
                    "persistent fixture has a stable nonempty invalid "
                    "terminal; manual recovery is required"
                ) from last_error
            if remaining <= 0:
                return "INCOMPLETE"
            time.sleep(min(0.05, max(0.0, remaining)))

    return (
        artifact_root,
        v2_select_persistent_attempt(base, probe=probe),
    )


def v2_publish_and_read_persistent_fixture(
    *,
    artifact_root: str,
    artifact_dir: str,
    payloads: Mapping[str, bytes],
) -> tuple[
    Path,
    dict[str, bytes],
    dict[str, Any],
    list[dict[str, Any]],
]:
    check_cancel()
    output = resolve_run_dir(
        artifact_root,
        artifact_dir,
        label="persistent v2 fixture",
    )
    publication_error: EvidenceFailed | None = None
    if not output.exists():
        try:
            publication = v2_publish_bundle(
                artifact_root=artifact_root,
                artifact_dir=artifact_dir,
                payloads=payloads,
            )
        except EvidenceFailed as error:
            if not output.exists():
                raise
            publication_error = error
        else:
            if (
                publication["publication_order"][-1] != "terminal.json"
                or publication["terminal_content_sealed_last"] is not True
            ):
                raise EvidenceFailed(
                    "persistent v2 fixture did not seal terminal content last"
                )
    deadline = time.monotonic() + 5.0
    nonempty_invalid_signature: tuple[int, int, int, int, int] | None = None
    stable_nonempty_invalid_observations = 0
    while True:
        check_cancel()
        try:
            directory, retained, terminal, events = (
                v2_read_retained_bundle(
                    artifact_root=artifact_root,
                    input_dir=artifact_dir,
                )
            )
            check_cancel()
            break
        except (InputRefused, EvidenceFailed) as error:
            check_cancel()
            prefix_state = v2_persistent_terminal_prefix_state(output)
            if prefix_state == "NONEMPTY_TERMINAL":
                try:
                    terminal_stat = os.lstat(output / "terminal.json")
                except OSError as stat_error:
                    raise EvidenceFailed(
                        "persistent fixture terminal changed during invalid-"
                        "seal classification"
                    ) from stat_error
                signature = (
                    int(terminal_stat.st_dev),
                    int(terminal_stat.st_ino),
                    int(terminal_stat.st_size),
                    int(terminal_stat.st_mtime_ns),
                    int(terminal_stat.st_ctime_ns),
                )
                (
                    nonempty_invalid_signature,
                    stable_nonempty_invalid_observations,
                    stable_invalid,
                ) = v2_observe_stable_invalid_terminal(
                    nonempty_invalid_signature,
                    stable_nonempty_invalid_observations,
                    signature,
                )
                if stable_invalid:
                    raise EvidenceFailed(
                        "persistent fixture has a stable nonempty invalid "
                        "terminal; manual recovery is required"
                    ) from error
            else:
                nonempty_invalid_signature = None
                stable_nonempty_invalid_observations = 0
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                raise EvidenceFailed(
                    "persistent fixture remained incomplete after the bounded "
                    "concurrent-publication wait; rerun to select a fresh "
                    "attempt directory"
                ) from (publication_error or error)
            check_cancel()
            time.sleep(min(0.05, remaining))
    if dict(retained) != dict(payloads):
        divergence = first_projection_divergence(
            {
                name: (
                    len(payload),
                    "sha256-v1:" + hashlib.sha256(payload).hexdigest(),
                )
                for name, payload in payloads.items()
            },
            {
                name: (
                    len(payload),
                    "sha256-v1:" + hashlib.sha256(payload).hexdigest(),
                )
                for name, payload in retained.items()
            },
        )
        raise EvidenceFailed(
            "persistent v2 fixture differs from expected payloads at "
            f"{divergence or '$'}"
        )
    check_cancel()
    return directory, retained, terminal, events


def v2_fresh_nomock_artifact_location(
    manifest: Mapping[str, Any],
    *,
    label: str,
    identity_binding: Any,
) -> tuple[str, str]:
    if re.fullmatch(r"[a-z0-9][a-z0-9-]{0,63}", label) is None:
        raise EvidenceFailed("no-mock live artifact label is noncanonical")
    try:
        nonce = os.urandom(32).hex()
    except OSError as error:
        raise InfrastructureFailed(
            "no-mock live artifact nonce could not be generated"
        ) from error
    identity = hashlib.sha256(
        canonical_bytes(
            {
                "manifest_content_identity": manifest["content_identity"],
                "label": label,
                "identity_binding": identity_binding,
                "nonce": nonce,
            }
        )
    ).hexdigest()[:24]
    artifact_root = "target/beads-template-hygiene/v2-live-e2e"
    base = f"{label}-{identity}"
    for attempt in range(1, V2_PERSISTENT_ATTEMPTS_CAP + 1):
        check_cancel()
        artifact_dir = (
            base
            if attempt == 1
            else f"{base}-attempt-{attempt:04d}"
        )
        output = resolve_run_dir(
            artifact_root,
            artifact_dir,
            label="no-mock live artifact candidate",
        )
        try:
            value = os.lstat(output)
        except FileNotFoundError:
            return artifact_root, artifact_dir
        except OSError as error:
            raise InfrastructureFailed(
                "no-mock live artifact candidate cannot be inspected safely"
            ) from error
        if not stat.S_ISDIR(value.st_mode):
            raise EvidenceFailed(
                "no-mock live artifact candidate collides with a non-directory"
            )
    raise EvidenceFailed(
        "no-mock live artifact allocator exhausted its bounded fresh attempts"
    )


def v2_validate_live_fixture_plan_label(
    label: Any,
    *,
    replay: Any,
) -> str:
    if (
        type(label) is not str
        or re.fullmatch(r"[a-z0-9][a-z0-9-]{0,63}", label) is None
        or type(replay) is not bool
    ):
        raise EvidenceFailed("fixture live plan label or replay mode is malformed")
    if replay and len(label) > 57:
        raise EvidenceFailed(
            "fixture live plan label exceeds the derived replay-label boundary"
        )
    return label


def v2_fixture_history_manifest(
    manifest: Mapping[str, Any],
    snapshot: Mapping[str, Any],
    *,
    anchor_issue_id: str,
) -> dict[str, Any]:
    """Bind the history contract to one exact released-br fixture capture."""
    detached = v2_validate_exact_json_wire(
        manifest,
        label="fixture history manifest source",
    )
    if type(detached) is not dict:
        raise EvidenceFailed("fixture history manifest source is not an object")
    shows = v2_fixture_show_projection_by_id(snapshot)
    anchor = shows.get(anchor_issue_id)
    audits = snapshot.get("audits")
    if (
        type(anchor) is not dict
        or anchor.get("status") != "closed"
        or type(anchor.get("closed_at")) is not str
        or not anchor["closed_at"]
        or type(anchor.get("close_reason")) is not str
        or not anchor["close_reason"].strip()
        or type(audits) is not dict
        or type(audits.get(anchor_issue_id)) is not dict
    ):
        raise EvidenceFailed(
            "fixture history anchor lacks exact closed source evidence"
        )
    anchor_audit = audits[anchor_issue_id]
    events = anchor_audit.get("events")
    if type(events) is not list:
        raise EvidenceFailed("fixture history anchor audit is malformed")
    anchor_timestamp = v2_parse_timestamp(
        anchor["closed_at"],
        label="fixture history anchor closed timestamp",
    )
    current_pairs = v2_current_close_pairs(
        events,
        issue_id=anchor_issue_id,
        show_timestamp=anchor_timestamp,
        close_reason=anchor["close_reason"],
        max_skew_ms=manifest["history_contract"][
            "known_pair_max_skew_ms"
        ],
    )
    if len(current_pairs) != 1:
        raise EvidenceFailed(
            "fixture history anchor does not have one exact current close pair"
        )
    close_event, status_event = current_pairs[0]
    legacy_rows = sorted(
        (
            {
                "id": issue["id"],
                "closed_at": issue["closed_at"],
                "close_reason_root": text_root(issue["close_reason"]),
            }
            for issue in shows.values()
            if issue["status"] == "closed"
            and issue["id"] != anchor_issue_id
            and type(issue.get("closed_at")) is str
            and issue["closed_at"]
            and type(issue.get("close_reason")) is str
            and issue["close_reason"].strip()
            and v2_parse_timestamp(
                issue["closed_at"],
                label=f"fixture legacy history {issue['id']}",
            )
            < anchor_timestamp
        ),
        key=lambda row: row["id"],
    )
    history_contract = dict(detached["history_contract"])
    history_contract.update(
        {
            "legacy_coverage_anchor_issue": anchor_issue_id,
            "legacy_coverage_anchor_closed_at": anchor["closed_at"],
            "legacy_coverage_anchor_status_event_id": status_event["id"],
            "legacy_coverage_anchor_close_event_id": close_event["id"],
            "legacy_coverage_count": len(legacy_rows),
            "legacy_coverage_rows_root": semantic_root(legacy_rows),
        }
    )
    detached["history_contract"] = history_contract
    dict.pop(detached, "semantic_root", None)
    return v2_rooted(detached)


def v2_run_live_fixture_plan(
    manifest: Mapping[str, Any],
    context: Mapping[str, str],
    *,
    mode: str,
    label: str,
    target_ids: Sequence[str],
    statuses: Sequence[str] = (),
    priorities: Sequence[str] = (),
    review_receipts: str | None = None,
    prior_campaign: str | None = None,
    replay: bool = True,
) -> dict[str, Any]:
    """Run, retain, reconstruct, and optionally replay a genuine fixture plan."""
    exact_context = v2_validate_fixture_context(context)
    exact_label = v2_validate_live_fixture_plan_label(
        label,
        replay=replay,
    )
    if mode not in {"review-plan", "history-plan"}:
        raise EvidenceFailed("fixture live plan mode is unsupported")
    if (
        type(target_ids) not in {list, tuple}
        or not target_ids
        or any(
            type(issue_id) is not str or not issue_id
            for issue_id in target_ids
        )
        or list(target_ids) != sorted(set(target_ids))
        or type(statuses) not in {list, tuple}
        or type(priorities) not in {list, tuple}
        or any(
            type(status) is not str or not status
            for status in statuses
        )
        or list(statuses) != sorted(set(statuses))
        or any(
            type(priority) is not str
            or priority not in {f"P{value}" for value in range(5)}
            for priority in priorities
        )
        or list(priorities) != sorted(set(priorities))
        or (
            review_receipts is not None
            and (type(review_receipts) is not str or not review_receipts)
        )
        or (
            prior_campaign is not None
            and (type(prior_campaign) is not str or not prior_campaign)
        )
    ):
        raise EvidenceFailed("fixture live plan selectors are noncanonical")
    for issue_id in target_ids:
        v2_validate_issue_id(
            issue_id,
            label="fixture live plan target ID",
            error_type=EvidenceFailed,
        )
    for status in statuses:
        v2_validate_status(
            status,
            label="fixture live plan status",
            error_type=EvidenceFailed,
        )
    fixture_root = resolve_safe(
        str(FIXTURE_BR_ROOT_REL),
        label="fixture live plan root",
        must_exist=True,
    )
    accepted_manifest: Mapping[str, Any] = manifest
    contract_snapshot: Mapping[str, Any] | None = None
    if mode == "history-plan":
        contract_snapshot = _v2_fixture_fingerprint_locked(exact_context)
        accepted_manifest = v2_fixture_history_manifest(
            manifest,
            contract_snapshot,
            anchor_issue_id=exact_context["regression_id"],
        )
    identity_binding = {
        "mode": mode,
        "targets": list(target_ids),
        "statuses": list(statuses),
        "priorities": list(priorities),
        "fixture_history_contract_root": (
            accepted_manifest["semantic_root"]
            if mode == "history-plan"
            else None
        ),
    }
    artifact_root, artifact_dir = v2_fresh_nomock_artifact_location(
        accepted_manifest,
        label=exact_label,
        identity_binding=identity_binding,
    )
    reproduction = v2_reproduction_argv(
        mode=mode,
        artifact_root=artifact_root,
        artifact_dir=artifact_dir,
        review_receipts=review_receipts,
        prior_campaign=prior_campaign,
        priorities=(",".join(priorities) if priorities else None),
        statuses=(",".join(statuses) if statuses else None),
        targets=",".join(target_ids),
    )
    parsed = parse_arguments(reproduction[1:])
    synopsis = v2_execute_live_plan(
        mode=mode,
        parsed=parsed,
        manifest=accepted_manifest,
        br_cwd=fixture_root,
    )
    command_receipts = [dict(row) for row in _command_receipts]
    retained_directory, payloads, terminal, events = v2_read_retained_bundle(
        artifact_root=artifact_root,
        input_dir=artifact_dir,
    )
    current_source_files = v2_source_file_identities()
    reconstructed = v2_reconstruct_retained(
        artifact_root=artifact_root,
        input_dir=artifact_dir,
        payloads=payloads,
        terminal=terminal,
        events=events,
        accepted_manifest=accepted_manifest,
        current_source_files=current_source_files,
    )
    source, inventory, authority, review_plan, history, zero_sets, optional = (
        reconstructed
    )
    if (
        terminal["terminal"] != "Pass"
        or terminal["bundle_state"] != "COMPLETE_GREEN"
        or terminal["subject_mode"] != mode
        or set(payloads) != set(terminal["safe_relative_artifacts"])
        or synopsis["mode"] != mode
        or synopsis["selected_ids"]["ids"] != list(target_ids)
    ):
        raise EvidenceFailed("fixture live plan terminal or selection differs")

    replay_result: Mapping[str, Any] | None = None
    replay_terminal: Mapping[str, Any] | None = None
    replay_roots: list[str] | None = None
    replay_directory: Path | None = None
    if replay:
        replay_label = f"{exact_label}-replay"
        replay_root, replay_dir = v2_fresh_nomock_artifact_location(
            accepted_manifest,
            label=replay_label,
            identity_binding={
                "retained_terminal_root": terminal["semantic_root"],
                "mode": mode,
            },
        )
        if replay_root != artifact_root:
            raise EvidenceFailed("fixture live replay escaped its artifact root")
        receipt_count = len(_command_receipts)
        replay_result = v2_replay_bundle(
            artifact_root=artifact_root,
            input_dir=artifact_dir,
            output_dir=replay_dir,
            accepted_manifest=accepted_manifest,
        )
        if len(_command_receipts) != receipt_count:
            raise EvidenceFailed("fixture offline replay invoked a live source")
        (
            replay_directory,
            replay_payloads,
            replay_terminal,
            replay_events,
        ) = v2_read_retained_bundle(
            artifact_root=artifact_root,
            input_dir=replay_dir,
        )
        replay_reconstructed = v2_reconstruct_retained(
            artifact_root=artifact_root,
            input_dir=replay_dir,
            payloads=replay_payloads,
            terminal=replay_terminal,
            events=replay_events,
            accepted_manifest=accepted_manifest,
            current_source_files=current_source_files,
        )
        replay_roots = [
            row["semantic_root"] for row in replay_reconstructed[:6]
        ]
        retained_roots = [row["semantic_root"] for row in reconstructed[:6]]
        if (
            replay_result["terminal"] != "Pass"
            or replay_result["subject_mode"] != mode
            or replay_roots != retained_roots
            or replay_directory == retained_directory
        ):
            raise EvidenceFailed("fixture live plan replay differs")

    return {
        "mode": mode,
        "accepted_manifest": accepted_manifest,
        "contract_snapshot": contract_snapshot,
        "artifact_root": artifact_root,
        "artifact_dir": artifact_dir,
        "retained_directory": retained_directory,
        "payloads": payloads,
        "terminal": terminal,
        "events": events,
        "synopsis": synopsis,
        "source": source,
        "inventory": inventory,
        "authority": authority,
        "review_plan": review_plan,
        "history": history,
        "zero_sets": zero_sets,
        "optional_payloads": optional,
        "command_receipts": command_receipts,
        "replay_result": replay_result,
        "replay_terminal": replay_terminal,
        "replay_roots": replay_roots,
        "replay_directory": replay_directory,
    }


def v2_live_fixture_plan_summary(run: Mapping[str, Any]) -> dict[str, Any]:
    source = run["source"]
    inventory = run["inventory"]
    authority = run["authority"]
    review_plan = run["review_plan"]
    history = run["history"]
    zero_sets = run["zero_sets"]
    return v2_rooted(
        {
            "mode": run["mode"],
            "terminal_root": run["terminal"]["semantic_root"],
            "source_root": source["semantic_root"],
            "observation_root": source["captured"]["observation"][
                "semantic_root"
            ],
            "campaign_epoch_root": source["campaign_epoch_root"],
            "inventory_root": inventory["semantic_root"],
            "inventory_target_roots": [
                {
                    "id": row["id"],
                    "target_root": row["target_root"],
                    "dependency_neighborhood_root": row[
                        "dependency_neighborhood_root"
                    ],
                }
                for row in inventory["rows"]
            ],
            "authority_root": authority["semantic_root"],
            "decision_roots": [
                {
                    "target_id": row["target_id"],
                    "decision_root": row["semantic_root"],
                }
                for row in authority["decisions"]
            ],
            "review_plan_root": review_plan["semantic_root"],
            "review_child_identifiers": sorted(
                str(child["child_key"])
                for child in review_plan.get("children", [])
            ),
            "history_root": history["semantic_root"],
            "zero_sets_root": zero_sets["semantic_root"],
            "optional_artifact_roots": {
                name: "sha256-v1:" + hashlib.sha256(payload).hexdigest()
                for name, payload in sorted(run["optional_payloads"].items())
            },
            "command_receipts_root": semantic_root(
                run["command_receipts"]
            ),
            "replay_roots": run["replay_roots"],
        }
    )


V2_FIXTURE_SNAPSHOT_SCHEMA = (
    "frankensim.beads-template-hygiene.fixture-snapshot.v2"
)


def v2_validate_fixture_context(
    context: Mapping[str, str],
) -> dict[str, str]:
    expected_fields = {"db", "stable_id", "regression_id"}
    if (
        type(context) is not dict
        or set(context) != expected_fields
        or any(
            type(context[field]) is not str or not context[field]
            for field in expected_fields
        )
        or context["db"] != str(FIXTURE_BR_DB_REL)
        or context["stable_id"] == context["regression_id"]
        or not context["stable_id"].startswith(
            FIXTURE_BR_STABLE_ID_PREFIX
        )
        or not context["regression_id"].startswith(
            FIXTURE_BR_REGRESSION_ID_PREFIX
        )
    ):
        raise EvidenceFailed(
            "no-mock fixture snapshot context or canonical roles differ"
        )
    for role in ("stable_id", "regression_id"):
        v2_validate_issue_id(
            context[role],
            label=f"no-mock fixture {role}",
            error_type=EvidenceFailed,
        )
    return dict(context)


def v2_fixture_restorable_list_row(
    row: Mapping[str, Any],
) -> dict[str, Any]:
    if type(row) is not dict:
        raise InfrastructureFailed("fixture list row is not an exact object")
    issue = {
        key: value
        for key, value in dict.items(row)
        if key not in {"dependency_count", "dependent_count"}
    }
    projection = fixture_br_restorable_projection(issue)
    for field in ("dependency_count", "dependent_count"):
        value = dict.get(row, field)
        if type(value) is not int or value < 0:
            raise InfrastructureFailed(
                f"fixture list row {field} is malformed"
            )
        projection[field] = value
    return projection


def v2_fixture_status_identity_projection(
    status: Mapping[str, Any],
) -> dict[str, Any]:
    if type(status) is not dict or type(status.get("summary")) is not dict:
        raise InfrastructureFailed(
            "fixture normalized status is not an exact summary"
        )
    return v2_br_status_identity_projection(
        status,
        error_type=InfrastructureFailed,
    )


def v2_fixture_sync_restorable_projection(
    sync_status: Mapping[str, Any],
) -> dict[str, Any]:
    if type(sync_status) is not dict:
        raise InfrastructureFailed(
            "fixture normalized sync status is not an exact object"
        )
    projection = dict(sync_status)
    projection["last_export_time"] = None
    projection["last_import_time"] = None
    projection["jsonl_content_hash"] = None
    raw_git_export = projection.get("git_export")
    if type(raw_git_export) is dict:
        git_export = dict(raw_git_export)
        git_export["head_hash"] = None
        git_export["worktree_hash"] = None
        projection["git_export"] = git_export
    return projection


def v2_fixture_assert_list_show_coherence(
    rows: Sequence[Mapping[str, Any]],
    shows: Mapping[str, Mapping[str, Any]],
    *,
    label: str,
) -> None:
    for row in rows:
        issue_id = str(dict.get(row, "id") or "")
        show = shows.get(issue_id)
        if show is None:
            raise InfrastructureFailed(
                f"{label} row {issue_id} is absent from show membership"
            )
        dependencies = show.get("dependencies") or []
        dependents = show.get("dependents") or []
        if (
            row.get("dependency_count") != len(dependencies)
            or row.get("dependent_count") != len(dependents)
        ):
            raise InfrastructureFailed(
                f"{label} relation counts differ for {issue_id}"
            )
        for field, value in dict.items(row):
            if field in {"dependency_count", "dependent_count"}:
                continue
            if not dict.__contains__(show, field) or show[field] != value:
                raise InfrastructureFailed(
                    f"{label} field differs for {issue_id}/{field}"
                )


def v2_fixture_assert_ready_show_coherence(
    rows: Sequence[Mapping[str, Any]],
    shows: Mapping[str, Mapping[str, Any]],
) -> None:
    for row in rows:
        issue_id = str(dict.get(row, "id") or "")
        show = shows.get(issue_id)
        if show is None:
            raise InfrastructureFailed(
                f"fixture ready row {issue_id} is absent from show membership"
            )
        for field, value in dict.items(row):
            if not dict.__contains__(show, field) or show[field] != value:
                raise InfrastructureFailed(
                    f"fixture ready/show field differs for {issue_id}/{field}"
                )


def _v2_capture_fixture_snapshot_once_locked(
    context: Mapping[str, str],
    *,
    honor_cancel: bool = True,
) -> dict[str, Any]:
    exact_context = v2_validate_fixture_context(context)
    fixture_root = resolve_safe(
        str(FIXTURE_BR_ROOT_REL),
        label="no-mock fixture root",
        must_exist=True,
    )
    database_rows = fixture_br_list(honor_cancel=honor_cancel)
    issue_ids = [row["id"] for row in database_rows]
    if (
        issue_ids != sorted(issue_ids)
        or len(issue_ids) != len(set(issue_ids))
        or not {
            exact_context["stable_id"],
            exact_context["regression_id"],
        }.issubset(issue_ids)
    ):
        raise InfrastructureFailed(
            "fixture database membership or canonical role binding differs"
        )
    raw_shows = {
        issue_id: fixture_br_show(
            issue_id,
            honor_cancel=honor_cancel,
        )
        for issue_id in issue_ids
    }
    v2_fixture_assert_list_show_coherence(
        database_rows,
        raw_shows,
        label="fixture database list/show",
    )

    exported_rows = fixture_br_export_list(
        honor_cancel=honor_cancel
    )
    expected_exported_rows = [
        row for row in database_rows if v2_issue_is_exportable(row)
    ]
    if exported_rows != expected_exported_rows:
        raise InfrastructureFailed(
            "fixture released DB and JSONL-only rows differ"
        )
    v2_fixture_assert_list_show_coherence(
        exported_rows,
        raw_shows,
        label="fixture JSONL list/show",
    )

    ready_rows = v2_normalize_released_br_ready_rows(
        fixture_br_json("ready", honor_cancel=honor_cancel),
        label="fixture br ready",
    )
    v2_fixture_assert_ready_show_coherence(ready_rows, raw_shows)

    lint_open = v2_normalize_br_lint_document(
        fixture_br_json("lint", honor_cancel=honor_cancel),
        scope="fixture-open",
        error_type=InfrastructureFailed,
    )
    lint_targeted = {
        issue_id: v2_normalize_br_lint_document(
            fixture_br_json(
                "lint",
                issue_id,
                honor_cancel=honor_cancel,
            ),
            scope=f"fixture-{issue_id}",
            error_type=InfrastructureFailed,
        )
        for issue_id in issue_ids
    }
    audits = {
        issue_id: v2_normalize_audit_document(
            fixture_br_json(
                "audit",
                "log",
                issue_id,
                honor_cancel=honor_cancel,
            ),
            issue_id=issue_id,
        )
        for issue_id in issue_ids
    }
    tracker_status = v2_normalize_br_status(
        fixture_br_json(
            "status",
            "--no-activity",
            honor_cancel=honor_cancel,
        ),
        error_type=InfrastructureFailed,
    )
    sync_status = v2_normalize_br_sync_status(
        fixture_br_json(
            "sync",
            "--status",
            honor_cancel=honor_cancel,
        ),
        input_kind="released_live",
        error_type=InfrastructureFailed,
    )
    export_witness = v2_normalize_br_export_witness(
        fixture_br_json(
            "sync",
            "--witness",
            honor_cancel=honor_cancel,
        ),
        input_kind="released_live",
        workspace_root=fixture_root,
        expected_chunk_size_lines=(
            V2_BR_WITNESS_CAPTURE_CHUNK_SIZE_LINES
        ),
        expected_max_parallelism=(
            V2_BR_WITNESS_CAPTURE_MAX_PARALLELISM
        ),
        error_type=InfrastructureFailed,
    )
    version = v2_normalize_br_version(
        fixture_br_json("version", honor_cancel=honor_cancel),
        error_type=InfrastructureFailed,
    )
    capabilities = v2_normalize_br_capabilities(
        fixture_br_json("capabilities", honor_cancel=honor_cancel),
        error_type=InfrastructureFailed,
    )
    if capabilities["version"] != version["version"]:
        raise InfrastructureFailed(
            "fixture br version and capabilities version disagree"
        )
    full_shows = [
        v2_full_issue_projection(raw_shows[issue_id])
        for issue_id in issue_ids
    ]
    v2_validate_live_envelope_consistency(
        tracker_status=tracker_status,
        sync_status=sync_status,
        export_witness=export_witness,
        full_issues=full_shows,
        error_type=InfrastructureFailed,
    )
    if tracker_status["summary"]["ready_issues"] != len(ready_rows):
        raise InfrastructureFailed(
            "fixture ready membership disagrees with tracker status"
        )
    stable_status = v2_fixture_status_identity_projection(tracker_status)
    restorable_database_rows = [
        v2_fixture_restorable_list_row(row) for row in database_rows
    ]
    restorable_exported_rows = [
        v2_fixture_restorable_list_row(row) for row in exported_rows
    ]
    restorable_ready_rows = [
        fixture_br_restorable_projection(row) for row in ready_rows
    ]
    restorable_shows = [
        fixture_br_restorable_projection(raw_shows[issue_id])
        for issue_id in issue_ids
    ]
    canonical_roles = {
        "stable": exact_context["stable_id"],
        "regression": exact_context["regression_id"],
    }
    coherence = v2_rooted(
        {
            "database_list_show": "EXACT",
            "jsonl_list_show": "EXACT",
            "database_jsonl_exportable_rows": "EXACT",
            "ready_show": "EXACT",
            "ready_status_count": "EXACT",
            "status_show_counts": "EXACT_EXCEPT_TRACKER_REPORTED_FIELDS",
            "witness_jsonl_count": "EXACT",
            "version_capabilities": "EXACT",
            "tracker_reported_not_independently_proven": [
                "average_lead_time_hours",
                "blocked_issues_beyond_explicit_status_rows",
                "epics_eligible_for_closure",
            ],
        }
    )
    restorable_state = v2_rooted(
        {
            "fixture_db": exact_context["db"],
            "canonical_roles": canonical_roles,
            "database_rows": restorable_database_rows,
            "exported_rows": restorable_exported_rows,
            "shows": restorable_shows,
            "ready_rows": restorable_ready_rows,
            "lint": {
                "open": lint_open,
                "targeted": lint_targeted,
            },
            "tracker_status": stable_status,
            "sync_status": v2_fixture_sync_restorable_projection(
                sync_status
            ),
            "export_contract": {
                "normalized_exported_rows_are_identity": True,
                "line_count": len(exported_rows),
                "witness_schema": export_witness.get("schema"),
            },
            "version": version,
            "capabilities": capabilities,
            "coherence_root": coherence["semantic_root"],
        }
    )
    snapshot = {
        "schema": V2_FIXTURE_SNAPSHOT_SCHEMA,
        "fixture_db": exact_context["db"],
        "canonical_roles": canonical_roles,
        "issue_ids": issue_ids,
        "database_rows": database_rows,
        "exported_rows": exported_rows,
        "shows": full_shows,
        "ready_rows": ready_rows,
        "lint": {
            "open": lint_open,
            "targeted": lint_targeted,
        },
        "audits": audits,
        "tracker_status": tracker_status,
        "sync_status": sync_status,
        "export_witness": export_witness,
        "version": version,
        "capabilities": capabilities,
        "coherence": coherence,
        "restorable_state": restorable_state,
        "audit_root": semantic_root(audits),
        "no_claim": (
            "the snapshot is a normalized released-br fixture observation; "
            "append-only audit erasure and unobserved transient intermediate "
            "states are outside its restorable-state claim"
        ),
    }
    return v2_rooted(snapshot)


def _v2_capture_fixture_mutation_observation_locked(
    context: Mapping[str, str],
    *,
    intents: Sequence[tuple[str, str]],
) -> dict[str, Any]:
    """Capture bounded in-flight state without requiring a flushed export."""
    exact_context = v2_validate_fixture_context(context)
    issue_ids = sorted({issue_id for issue_id, _field in intents})
    shows = [
        v2_full_issue_projection(fixture_br_show(issue_id))
        for issue_id in issue_ids
    ]
    audits = {
        issue_id: v2_normalize_audit_document(
            fixture_br_json("audit", "log", issue_id),
            issue_id=issue_id,
        )
        for issue_id in issue_ids
    }
    database_rows = fixture_br_list()
    sync_status = v2_normalize_br_sync_status(
        fixture_br_json("sync", "--status"),
        input_kind="released_live",
        error_type=InfrastructureFailed,
    )
    return v2_rooted(
        {
            "schema": (
                "frankensim.beads-template-hygiene."
                "fixture-mutation-observation.v2"
            ),
            "fixture_db": exact_context["db"],
            "canonical_roles": {
                "stable": exact_context["stable_id"],
                "regression": exact_context["regression_id"],
            },
            "restoration_intents": [
                {"issue_id": issue_id, "field": field}
                for issue_id, field in intents
            ],
            "database_rows_root": semantic_root(database_rows),
            "selected_shows": shows,
            "selected_audits": audits,
            "sync_status": sync_status,
            "export_coherence_required": False,
            "no_claim": (
                "an in-flight br mutation may intentionally leave DB newer "
                "than JSONL; only the final transaction verifier may claim "
                "export coherence; declared fields are restoration scope, "
                "not a claim that transient undeclared changes are observed"
            ),
        }
    )


def v2_fixture_fingerprint(
    context: Mapping[str, str],
) -> dict[str, Any]:
    with fixture_br_lease():
        return _v2_fixture_fingerprint_locked(context)


def v2_fixture_snapshot_capture_coherence_projection(
    snapshot: Mapping[str, Any],
) -> dict[str, Any]:
    if type(snapshot) is not dict:
        raise InfrastructureFailed(
            "fixture capture coherence input is not an exact object"
        )
    projection = {
        key: value
        for key, value in dict.items(snapshot)
        if key != "semantic_root"
    }
    projection["tracker_status"] = v2_fixture_status_identity_projection(
        snapshot.get("tracker_status")
    )
    return v2_rooted(projection)


def _v2_fixture_fingerprint_locked(
    context: Mapping[str, str],
    *,
    honor_cancel: bool = True,
) -> dict[str, Any]:
    first = _v2_capture_fixture_snapshot_once_locked(
        context,
        honor_cancel=honor_cancel,
    )
    second = _v2_capture_fixture_snapshot_once_locked(
        context,
        honor_cancel=honor_cancel,
    )
    first_coherence = v2_fixture_snapshot_capture_coherence_projection(
        first
    )
    second_coherence = v2_fixture_snapshot_capture_coherence_projection(
        second
    )
    if first_coherence != second_coherence:
        divergence = first_projection_divergence(
            first_coherence,
            second_coherence,
        )
        raise InputRefused(
            "ConcurrentDrift: normalized fixture double capture differs at "
            f"{divergence or '$'}"
        )
    return second


