def v2_validate_fixture_restoration_step_name(
    value: Any,
    *,
    label: str,
    allow_verify: bool = False,
) -> None:
    if (
        type(value) is not str
        or not value
        or len(value) > V2_FIXTURE_RESTORATION_STEP_NAME_BYTES_CAP
        or type(allow_verify) is not bool
        or (value == "verify" and not allow_verify)
    ):
        raise EvidenceFailed(f"{label} is malformed or reserved")
    try:
        encoded = str.encode(value, "utf-8")
    except UnicodeEncodeError as error:
        raise EvidenceFailed(f"{label} is not valid UTF-8") from error
    if len(encoded) > V2_FIXTURE_RESTORATION_STEP_NAME_BYTES_CAP:
        raise EvidenceFailed(f"{label} exceeds its byte cap")
    if re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.:-]*", value) is None:
        raise EvidenceFailed(f"{label} is not a closed ASCII token")
    if (
        v2_contains_absolute_path(value)
        or v2_redact_contextual_text(value) != value
    ):
        raise EvidenceFailed(f"{label} contains non-publishable context")


def v2_validate_fixture_restoration_plan(
    steps: Any,
    verify: Any,
    *,
    label: str,
) -> tuple[str, ...]:
    if type(steps) is not tuple:
        raise EvidenceFailed(f"{label} is malformed")
    if not 1 <= tuple.__len__(steps) <= 16:
        raise EvidenceFailed(f"{label} step count is out of bounds")
    if type(verify) is not types.FunctionType:
        raise EvidenceFailed(f"{label} verifier is malformed")
    names: list[str] = []
    for index, row in enumerate(steps):
        if type(row) is not tuple or len(row) != 2:
            raise EvidenceFailed(f"{label} row {index} is malformed")
        name = tuple.__getitem__(row, 0)
        callback = tuple.__getitem__(row, 1)
        v2_validate_fixture_restoration_step_name(
            name,
            label=f"{label} row {index} name",
        )
        if type(callback) is not types.FunctionType or name in names:
            raise EvidenceFailed(f"{label} row {index} is malformed")
        names.append(name)
    return tuple(names)


def v2_fixture_exact_key_set(
    value: Any,
    expected: frozenset[str],
    *,
    label: str,
) -> None:
    if type(value) is not dict or type(expected) is not frozenset:
        raise EvidenceFailed(f"{label} is not an exact object contract")
    keys = tuple(dict.__iter__(value))
    if any(type(key) is not str for key in keys):
        raise EvidenceFailed(f"{label} has a non-string schema key")
    if frozenset(keys) != expected or len(keys) != len(expected):
        raise EvidenceFailed(f"{label} has a non-closed schema")


def v2_is_exact_exception_instance(value: Any) -> bool:
    value_type = type(value)
    if type(value_type) is not type:
        return False
    try:
        return BaseException in v2_raw_type_mro(value_type)
    except EvidenceFailed:
        return False


def v2_validate_fixture_restoration_attempt_row(
    attempt: Any,
    *,
    expected_fields: frozenset[str],
    expected_attempt: int,
    state_names: Sequence[str],
    label: str,
    runner: str | None = None,
    expected_runner_attempt: int | None = None,
) -> None:
    v2_fixture_exact_key_set(
        attempt,
        expected_fields,
        label=label,
    )
    if (
        type(expected_attempt) is not int
        or type(attempt["attempt"]) is not int
        or attempt["attempt"] != expected_attempt
        or type(attempt["sweep"]) is not int
        or attempt["sweep"] not in range(3)
        or type(attempt["outcome"]) is not str
        or attempt["outcome"] not in {"FAILED", "SUCCEEDED"}
    ):
        raise EvidenceFailed(f"{label} has malformed scalar context")
    v2_validate_fixture_restoration_step_name(
        attempt["step"],
        label=f"{label} step",
        allow_verify=True,
    )
    if attempt["step"] not in {*state_names, "verify"}:
        raise EvidenceFailed(f"{label} has an unknown step")
    if runner is None:
        if expected_runner_attempt is not None:
            raise EvidenceFailed(f"{label} runner contract is inconsistent")
    elif (
        type(runner) is not str
        or runner not in {"primary", "fallback"}
        or attempt["runner"] != runner
        or type(attempt["runner_attempt"]) is not int
        or expected_runner_attempt is None
        or attempt["runner_attempt"] != expected_runner_attempt
    ):
        raise EvidenceFailed(f"{label} has malformed runner context")
    if attempt["outcome"] == "SUCCEEDED":
        if (
            attempt["error_type"] is not None
            or attempt["diagnostic"] is not None
        ):
            raise EvidenceFailed(f"{label} success carries diagnostics")
        return
    if (
        type(attempt["error_type"]) is not str
        or not attempt["error_type"]
        or type(attempt["diagnostic"]) is not str
        or len(attempt["diagnostic"])
        > V2_DIAGNOSTIC_SUMMARY_BYTES_CAP
    ):
        raise EvidenceFailed(f"{label} failure lacks diagnostics")
    v2_validate_exception_type_projection(attempt["error_type"])
    try:
        diagnostic_bytes = str.encode(attempt["diagnostic"], "utf-8")
    except UnicodeEncodeError as error:
        raise EvidenceFailed(
            f"{label} diagnostic contains ill-formed Unicode"
        ) from error
    if len(diagnostic_bytes) > V2_DIAGNOSTIC_SUMMARY_BYTES_CAP:
        raise EvidenceFailed(f"{label} diagnostic exceeds its byte cap")


def v2_fixture_show_projection_by_id(
    snapshot: Mapping[str, Any],
) -> dict[str, dict[str, Any]]:
    shows = snapshot.get("shows")
    if type(shows) is not list:
        raise EvidenceFailed("fixture snapshot shows are not an exact array")
    by_id: dict[str, dict[str, Any]] = {}
    for index, show in enumerate(shows):
        if type(show) is not dict or type(show.get("id")) is not str:
            raise EvidenceFailed(
                f"fixture snapshot show {index} is malformed"
            )
        issue_id = show["id"]
        if issue_id in by_id:
            raise EvidenceFailed("fixture snapshot duplicates a show ID")
        by_id[issue_id] = show
    return by_id


def v2_validate_fixture_restoration_run_report(
    candidate: Any,
    *,
    label: str,
) -> dict[str, Any]:
    try:
        v2_fixture_exact_key_set(
            candidate,
            V2_FIXTURE_RESTORATION_RUN_REPORT_FIELDS,
            label=f"{label} report",
        )
    except EvidenceFailed as error:
        raise EvidenceFailed(
            f"{label} returned a malformed report"
        ) from error
    if (
        type(candidate["converged"]) is not bool
        or type(candidate["states"]) is not tuple
        or type(candidate["anomalies"]) is not tuple
        or type(candidate["attempts"]) is not tuple
    ):
        raise EvidenceFailed(f"{label} returned a malformed report")
    states = candidate["states"]
    if not 1 <= len(states) <= 16:
        raise EvidenceFailed(f"{label} has a malformed state count")
    state_names: list[str] = []
    for index, row in enumerate(states):
        if (
            type(row) is not tuple
            or len(row) != 2
            or type(row[0]) is not str
            or not row[0]
            or type(row[1]) is not str
            or row[1] not in V2_FIXTURE_RESTORATION_STATE_VALUES
        ):
            raise EvidenceFailed(
                f"{label} state row {index} is malformed"
            )
        v2_validate_fixture_restoration_step_name(
            row[0],
            label=f"{label} state row {index} name",
        )
        state_names.append(row[0])
    if len(state_names) != len(set(state_names)):
        raise EvidenceFailed(f"{label} state names are duplicated")
    anomalies = candidate["anomalies"]
    if len(anomalies) > 51:
        raise EvidenceFailed(f"{label} has a malformed anomaly count")
    normalized_anomalies: list[tuple[str, BaseException]] = []
    for index, row in enumerate(anomalies):
        if (
            type(row) is not tuple
            or len(row) != 2
            or type(row[0]) is not str
            or not row[0]
            or len(row[0])
            > len("fallback:")
            + V2_FIXTURE_RESTORATION_STEP_NAME_BYTES_CAP
            or not v2_is_exact_exception_instance(row[1])
        ):
            raise EvidenceFailed(
                f"{label} anomaly row {index} is malformed"
            )
        v2_validate_fixture_restoration_step_name(
            row[0],
            label=f"{label} anomaly row {index} name",
            allow_verify=True,
        )
        normalized_anomalies.append((row[0], row[1]))
    attempts = candidate["attempts"]
    if not 1 <= len(attempts) <= 51:
        raise EvidenceFailed(f"{label} has a malformed attempt count")
    failed_attempts: list[dict[str, Any]] = []
    for index, attempt in enumerate(attempts):
        v2_validate_fixture_restoration_attempt_row(
            attempt,
            expected_fields=V2_FIXTURE_RESTORATION_ATTEMPT_FIELDS,
            expected_attempt=index,
            state_names=state_names,
            label=f"{label} attempt row {index}",
        )
        if attempt["outcome"] == "SUCCEEDED":
            pass
        else:
            failed_attempts.append(attempt)
    if len(failed_attempts) != len(normalized_anomalies):
        raise EvidenceFailed(
            f"{label} anomaly and failed-attempt counts differ"
        )
    for attempt, (name, error) in zip(
        failed_attempts,
        normalized_anomalies,
        strict=True,
    ):
        if (
            attempt["step"] != name
            or attempt["error_type"]
            != v2_exception_type_projection(type(error))
            or attempt["diagnostic"]
            != v2_bounded_diagnostic_summary(error)
        ):
            raise EvidenceFailed(
                f"{label} failed-attempt diagnostics differ"
            )
    simulated_states = {name: "PENDING" for name in state_names}
    current_sweep = -1
    expected_steps: tuple[str, ...] = ()
    expected_step_index = 0
    verify_seen = False
    for index, attempt in enumerate(attempts):
        sweep = attempt["sweep"]
        step = attempt["step"]
        outcome = attempt["outcome"]
        if sweep != current_sweep:
            if current_sweep >= 0 and (
                expected_step_index != len(expected_steps)
                or (
                    all(
                        state == "SUCCEEDED"
                        for state in simulated_states.values()
                    )
                    and not verify_seen
                )
            ):
                raise EvidenceFailed(
                    f"{label} advances before exhausting a restoration sweep"
                )
            if sweep != current_sweep + 1:
                raise EvidenceFailed(
                    f"{label} attempt sweeps are not canonical"
                )
            current_sweep = sweep
            expected_steps = tuple(
                name
                for name in state_names
                if simulated_states[name] == "PENDING"
            )
            if not expected_steps:
                raise EvidenceFailed(
                    f"{label} starts a sweep without pending restoration"
                )
            expected_step_index = 0
            verify_seen = False
        if step == "verify":
            if (
                verify_seen
                or expected_step_index != len(expected_steps)
                or not all(
                    state == "SUCCEEDED"
                    for state in simulated_states.values()
                )
            ):
                raise EvidenceFailed(
                    f"{label} verification attempt precedes restoration"
                )
            verify_seen = True
            if outcome == "SUCCEEDED":
                if index != len(attempts) - 1:
                    raise EvidenceFailed(
                        f"{label} continues after successful verification"
                    )
            else:
                simulated_states = {
                    name: "PENDING" for name in state_names
                }
            continue
        if (
            verify_seen
            or expected_step_index >= len(expected_steps)
            or step != expected_steps[expected_step_index]
        ):
            raise EvidenceFailed(
                f"{label} restoration attempt order is not canonical"
            )
        expected_step_index += 1
        simulated_states[step] = (
            "SUCCEEDED" if outcome == "SUCCEEDED" else "PENDING"
        )
    if (
        expected_step_index != len(expected_steps)
        or (
            all(
                state == "SUCCEEDED"
                for state in simulated_states.values()
            )
            and not verify_seen
        )
    ):
        raise EvidenceFailed(
            f"{label} ends before exhausting its restoration sweep"
        )
    simulated_rows = tuple(
        (name, simulated_states[name]) for name in state_names
    )
    trace_converged = (
        attempts[-1]["step"] == "verify"
        and attempts[-1]["outcome"] == "SUCCEEDED"
    )
    if not trace_converged and current_sweep != 2:
        raise EvidenceFailed(
            f"{label} nonconverged trace does not exhaust three sweeps"
        )
    if (
        states != simulated_rows
        or candidate["converged"] is not trace_converged
    ):
        raise EvidenceFailed(
            f"{label} state or convergence differs from its attempt trace"
        )
    if candidate["converged"]:
        if (
            any(state != "SUCCEEDED" for _name, state in states)
            or attempts[-1]["step"] != "verify"
            or attempts[-1]["outcome"] != "SUCCEEDED"
        ):
            raise EvidenceFailed(
                f"{label} converged state lacks final verification"
            )
    elif attempts[-1]["outcome"] == "SUCCEEDED" and all(
        state == "SUCCEEDED" for _name, state in states
    ):
        raise EvidenceFailed(
            f"{label} nonconverged state contradicts its final attempt"
        )
    return candidate


def v2_validate_fixture_mutation_intents(
    intents: Sequence[tuple[str, str]],
    *,
    context: Mapping[str, str],
    baseline: Mapping[str, Any],
) -> tuple[tuple[str, str], ...]:
    if type(intents) not in {tuple, list} or not intents:
        raise EvidenceFailed(
            "fixture mutation transaction requires explicit intents"
        )
    issue_ids = set(baseline.get("issue_ids") or [])
    normalized: list[tuple[str, str]] = []
    for index, intent in enumerate(intents):
        if (
            type(intent) is not tuple
            or len(intent) != 2
            or type(intent[0]) is not str
            or type(intent[1]) is not str
            or intent[0] not in issue_ids
            or intent[1] not in V2_FIXTURE_MUTABLE_FIELDS
        ):
            raise EvidenceFailed(
                f"fixture mutation intent {index} is malformed or unsupported"
            )
        normalized.append(intent)
    if len(normalized) != len(set(normalized)):
        raise EvidenceFailed("fixture mutation intents contain duplicates")
    if len(normalized) > V2_FIXTURE_MUTATION_INTENT_CAP:
        raise EvidenceFailed(
            "fixture mutation intents exceed the 15-field restoration cap"
        )
    canonical_roles = baseline.get("canonical_roles")
    expected_roles = {
        "stable": context["stable_id"],
        "regression": context["regression_id"],
    }
    if canonical_roles != expected_roles:
        raise EvidenceFailed(
            "fixture mutation baseline roles differ from the context"
        )
    baseline_shows = v2_fixture_show_projection_by_id(baseline)
    for issue_id, field in normalized:
        if (
            field == "status"
            and baseline_shows[issue_id].get("status") == "closed"
        ):
            raise EvidenceFailed(
                "fixture transaction cannot exactly restore a closed status "
                "because released br advances close metadata"
            )
    return tuple(normalized)


def v2_require_fixture_audit_headroom(
    baseline: Mapping[str, Any],
    intents: Sequence[tuple[str, str]],
    audit_event_budget_by_issue: Mapping[str, int],
) -> dict[str, int]:
    audits = baseline.get("audits")
    if type(audits) is not dict:
        raise EvidenceFailed("fixture mutation baseline lacks audit documents")
    intent_counts = Counter(issue_id for issue_id, _field in intents)
    if (
        type(audit_event_budget_by_issue) is not dict
        or set(audit_event_budget_by_issue) != set(intent_counts)
    ):
        raise EvidenceFailed(
            "fixture audit-event budget membership differs from mutation intents"
        )
    normalized_budgets: dict[str, int] = {}
    for issue_id, intent_count in intent_counts.items():
        document = audits.get(issue_id)
        events = document.get("events") if type(document) is dict else None
        if type(events) is not list:
            raise EvidenceFailed(
                f"fixture mutation baseline audit is malformed for {issue_id}"
            )
        declared_budget = audit_event_budget_by_issue[issue_id]
        minimum_budget = (
            V2_FIXTURE_AUDIT_EVENTS_PER_INTENT_HEADROOM * intent_count
        )
        if (
            type(declared_budget) is not int
            or declared_budget < minimum_budget
            or declared_budget > V2_AUDIT_EVENTS_PER_ISSUE_CAP
        ):
            raise EvidenceFailed(
                "fixture audit-event budget is malformed or below the "
                f"per-intent minimum for {issue_id}"
            )
        required = (
            V2_FIXTURE_AUDIT_EVENT_FIXED_HEADROOM
            + declared_budget
        )
        if len(events) + required > V2_AUDIT_EVENTS_PER_ISSUE_CAP:
            raise InputRefused(
                "fixture audit history lacks safe mutation/restoration "
                f"headroom for {issue_id}"
            )
        normalized_budgets[issue_id] = declared_budget
    return dict(sorted(normalized_budgets.items()))


def fixture_br_set_scalar_field(
    issue_id: str,
    field: str,
    value: Any,
    *,
    honor_cancel: bool = True,
) -> None:
    current = fixture_br_show(issue_id, honor_cancel=honor_cancel)
    if dict.get(current, field) == value or (
        dict.get(current, field) is None and value == ""
    ):
        return
    if field == "title":
        fixture_br_set_title(
            issue_id,
            value,
            honor_cancel=honor_cancel,
        )
        return
    if field == "description":
        fixture_br_set_description(
            issue_id,
            value,
            honor_cancel=honor_cancel,
        )
        return
    if field == "status":
        fixture_br_set_status(
            issue_id,
            value,
            honor_cancel=honor_cancel,
        )
        return
    flag_by_field = {
        "acceptance_criteria": "--acceptance-criteria",
        "assignee": "--assignee",
        "design": "--design",
        "notes": "--notes",
        "owner": "--owner",
        "priority": "--priority",
    }
    flag = flag_by_field.get(field)
    if flag is None:
        raise EvidenceFailed(
            f"fixture scalar restoration field is unsupported: {field}"
        )
    if field == "priority":
        if type(value) is not int or value not in range(5):
            raise EvidenceFailed("fixture priority restoration is malformed")
        rendered = str(value)
    else:
        if type(value) is not str:
            raise EvidenceFailed(
                f"fixture {field} restoration is not an exact string"
            )
        rendered = value
    fixture_br_json(
        "update",
        issue_id,
        flag,
        rendered,
        honor_cancel=honor_cancel,
    )


def fixture_br_restore_dependencies(
    issue_id: str,
    expected: Sequence[Mapping[str, Any]],
    *,
    honor_cancel: bool = True,
) -> None:
    if type(expected) is not list:
        raise EvidenceFailed(
            "fixture dependency restoration baseline is not an exact array"
        )
    expected_by_id: dict[str, str] = {}
    for index, edge in enumerate(expected):
        if (
            type(edge) is not dict
            or type(edge.get("id")) is not str
            or type(edge.get("type")) is not str
            or not edge["type"]
        ):
            raise EvidenceFailed(
                f"fixture dependency baseline row {index} is malformed"
            )
        expected_by_id[edge["id"]] = edge["type"]
    current = fixture_br_show(
        issue_id,
        honor_cancel=honor_cancel,
    ).get("dependencies") or []
    if type(current) is not list:
        raise InfrastructureFailed(
            "fixture current dependencies are not an exact array"
        )
    current_by_id = {
        str(edge.get("id") or ""): str(
            edge.get("dependency_type", edge.get("type", ""))
        )
        for edge in current
        if type(edge) is dict
    }
    failures: list[BaseException] = []
    predicted = dict(current_by_id)
    for neighbor_id, dependency_type in current_by_id.items():
        if expected_by_id.get(neighbor_id) == dependency_type:
            continue
        try:
            fixture_br_json(
                "dep",
                "remove",
                issue_id,
                neighbor_id,
                honor_cancel=honor_cancel,
            )
        except BaseException as error:
            failures.append(error)
        else:
            predicted.pop(neighbor_id, None)
    try:
        current_after_removal = (
            fixture_br_show(
                issue_id,
                honor_cancel=honor_cancel,
            ).get("dependencies") or []
        )
    except BaseException as error:
        failures.append(error)
        retained = predicted
    else:
        retained = {
            str(edge.get("id") or ""): str(
                edge.get("dependency_type", edge.get("type", ""))
            )
            for edge in current_after_removal
            if type(edge) is dict
        }
    for neighbor_id, dependency_type in expected_by_id.items():
        if retained.get(neighbor_id) == dependency_type:
            continue
        try:
            fixture_br_json(
                "dep",
                "add",
                issue_id,
                neighbor_id,
                "--type",
                dependency_type,
                honor_cancel=honor_cancel,
            )
        except BaseException as error:
            failures.append(error)
    if failures:
        raise BaseExceptionGroup(
            "fixture dependency restoration failures",
            failures,
        )


def v2_restore_fixture_intent(
    baseline_shows: Mapping[str, Mapping[str, Any]],
    issue_id: str,
    field: str,
) -> None:
    baseline = baseline_shows.get(issue_id)
    if baseline is None:
        raise EvidenceFailed(
            f"fixture restoration baseline lacks {issue_id}"
        )
    if field == "dependencies":
        fixture_br_restore_dependencies(
            issue_id,
            baseline.get("dependencies") or [],
            honor_cancel=False,
        )
        return
    fixture_br_set_scalar_field(
        issue_id,
        field,
        baseline.get(field),
        honor_cancel=False,
    )


def v2_fixture_audit_delta(
    before: Mapping[str, Any],
    after: Mapping[str, Any],
    *,
    mutated_issue_ids: frozenset[str],
) -> dict[str, Any]:
    before_audits = before.get("audits")
    after_audits = after.get("audits")
    if (
        type(before_audits) is not dict
        or type(after_audits) is not dict
        or set(before_audits) != set(after_audits)
    ):
        raise EvidenceFailed("fixture audit membership differs after cleanup")
    deltas: list[dict[str, Any]] = []
    for issue_id in sorted(before_audits):
        before_document = before_audits[issue_id]
        after_document = after_audits[issue_id]
        if (
            type(before_document) is not dict
            or type(after_document) is not dict
            or type(before_document.get("events")) is not list
            or type(after_document.get("events")) is not list
        ):
            raise EvidenceFailed(
                f"fixture audit document is malformed for {issue_id}"
            )
        old_events = before_document["events"]
        new_stream = after_document["events"]
        suffix = (
            new_stream[len(new_stream) - len(old_events) :]
            if old_events
            else []
        )
        if suffix != old_events:
            raise EvidenceFailed(
                f"fixture audit history is not append-only for {issue_id}"
            )
        added = (
            new_stream[: len(new_stream) - len(old_events)]
            if old_events
            else list(new_stream)
        )
        if issue_id not in mutated_issue_ids and added:
            raise EvidenceFailed(
                f"fixture audit changed for undeclared issue {issue_id}"
            )
        deltas.append(
            {
                "issue_id": issue_id,
                "before_count": len(old_events),
                "after_count": len(new_stream),
                "added_count": len(added),
                "added_root": semantic_root(added),
                "old_stream_preserved_as_suffix": True,
            }
        )
    return v2_rooted({"issues": deltas})


def v2_validate_fixture_audit_event_budgets(
    audit_delta: Mapping[str, Any],
    audit_event_budget_by_issue: Mapping[str, int],
) -> None:
    if (
        type(audit_delta) is not dict
        or set(audit_delta) != V2_FIXTURE_AUDIT_DELTA_FIELDS
        or type(audit_event_budget_by_issue) is not dict
        or any(
            type(issue_id) is not str
            or not issue_id
            or type(budget) is not int
            or budget < 0
            or budget > V2_AUDIT_EVENTS_PER_ISSUE_CAP
            for issue_id, budget in audit_event_budget_by_issue.items()
        )
    ):
        raise EvidenceFailed(
            "fixture audit-event budget verification input is malformed"
        )
    issues = audit_delta["issues"]
    if type(issues) is not list:
        raise EvidenceFailed(
            "fixture audit-event budget verification input is malformed"
        )
    seen: set[str] = set()
    for row in issues:
        if (
            type(row) is not dict
            or set(row) != V2_FIXTURE_AUDIT_DELTA_ISSUE_FIELDS
            or type(row["issue_id"]) is not str
            or not row["issue_id"]
            or type(row["before_count"]) is not int
            or row["before_count"] < 0
            or type(row["after_count"]) is not int
            or row["after_count"] < 0
            or type(row["added_count"]) is not int
            or row["added_count"] < 0
            or row["after_count"]
            != row["before_count"] + row["added_count"]
            or not v2_is_semantic_root(row["added_root"])
            or row["old_stream_preserved_as_suffix"] is not True
        ):
            raise EvidenceFailed(
                "fixture audit-event budget verification row is malformed"
            )
        issue_id = row["issue_id"]
        if issue_id in seen:
            raise EvidenceFailed(
                "fixture audit-event budget verification duplicates an issue"
            )
        seen.add(issue_id)
        declared_budget = audit_event_budget_by_issue.get(issue_id)
        if declared_budget is None and row["added_count"] != 0:
            raise EvidenceFailed(
                "fixture audit events changed for an undeclared issue"
            )
        if (
            declared_budget is not None
            and row["added_count"] > declared_budget
        ):
            raise EvidenceFailed(
                "fixture audit events exceeded the declared transaction "
                f"budget for {issue_id}"
            )
    if not set(audit_event_budget_by_issue).issubset(seen):
        raise EvidenceFailed(
            "fixture audit-event budget verification lacks a declared issue"
        )
    try:
        verify_semantic_root(
            audit_delta,
            label="fixture audit-event delta",
        )
    except (TypeError, ValueError, OverflowError, RecursionError) as error:
        raise EvidenceFailed(
            "fixture audit-event delta root is malformed"
        ) from error


def v2_fixture_restoration_log(
    report: Mapping[str, Any],
) -> dict[str, Any]:
    if type(report) is not dict:
        raise EvidenceFailed("fixture restoration report is malformed")
    report_keys = tuple(dict.__iter__(report))
    if any(type(key) is not str for key in report_keys):
        raise EvidenceFailed(
            "fixture restoration report has a non-string schema key"
        )
    report_fields = frozenset(report_keys)
    allowed_report_fields = {
        V2_FIXTURE_RESTORATION_MERGED_REPORT_FIELDS,
        frozenset({
            *V2_FIXTURE_RESTORATION_MERGED_REPORT_FIELDS,
            "verification",
        }),
    }
    if report_fields not in allowed_report_fields:
        raise EvidenceFailed("fixture restoration report is malformed")
    states = report["states"]
    anomalies = report["anomalies"]
    attempts = report["attempts"]
    runs = report["runs"]
    verification = dict.get(report, "verification")
    if (
        type(report["converged"]) is not bool
        or type(states) is not tuple
        or type(anomalies) is not tuple
        or type(attempts) is not tuple
        or type(runs) is not tuple
        or not 1 <= len(states) <= 16
        or not 1 <= len(runs) <= 2
        or not 1 <= len(attempts) <= 102
        or len(anomalies) > len(attempts)
    ):
        raise EvidenceFailed("fixture restoration report is malformed")
    state_names: list[str] = []
    for index, row in enumerate(states):
        if (
            type(row) is not tuple
            or len(row) != 2
            or type(row[0]) is not str
            or not row[0]
            or type(row[1]) is not str
            or row[1] not in V2_FIXTURE_RESTORATION_STATE_VALUES
        ):
            raise EvidenceFailed(
                f"fixture restoration state row {index} is malformed"
            )
        v2_validate_fixture_restoration_step_name(
            row[0],
            label=f"fixture restoration state row {index} name",
        )
        state_names.append(row[0])
    if len(state_names) != len(set(state_names)):
        raise EvidenceFailed("fixture restoration state names are duplicated")
    for index, row in enumerate(anomalies):
        if (
            type(row) is not tuple
            or len(row) != 2
            or type(row[0]) is not str
            or not row[0]
            or not v2_is_exact_exception_instance(row[1])
        ):
            raise EvidenceFailed(
                f"fixture restoration anomaly row {index} is malformed"
            )
    runner_attempt_counts = {"primary": 0, "fallback": 0}
    for index, attempt in enumerate(attempts):
        if type(attempt) is not dict:
            raise EvidenceFailed(
                f"fixture restoration attempt row {index} is malformed"
            )
        runner = dict.get(attempt, "runner")
        if type(runner) is not str or runner not in runner_attempt_counts:
            raise EvidenceFailed(
                f"fixture restoration attempt row {index} has no runner"
            )
        runner_attempt = runner_attempt_counts[runner]
        v2_validate_fixture_restoration_attempt_row(
            attempt,
            expected_fields=V2_FIXTURE_RESTORATION_LOG_ATTEMPT_FIELDS,
            expected_attempt=index,
            state_names=state_names,
            label=f"fixture restoration attempt row {index}",
            runner=runner,
            expected_runner_attempt=runner_attempt,
        )
        runner_attempt_counts[runner] = runner_attempt + 1
    runner_names: list[str] = []
    for run_index, run in enumerate(runs):
        v2_fixture_exact_key_set(
            run,
            V2_FIXTURE_RESTORATION_RUN_FIELDS,
            label=f"fixture restoration run row {run_index}",
        )
        runner = run["runner"]
        run_states = run["states"]
        if (
            type(runner) is not str
            or runner not in {"primary", "fallback"}
            or type(run["converged"]) is not bool
            or type(run_states) is not tuple
            or len(run_states) != len(states)
            or type(run["anomaly_count"]) is not int
            or run["anomaly_count"] < 0
            or type(run["attempt_count"]) is not int
            or run["attempt_count"] < 1
            or run["attempt_count"] > 51
            or run["anomaly_count"] > run["attempt_count"]
        ):
            raise EvidenceFailed(
                f"fixture restoration run row {run_index} is malformed"
            )
        for state_index, state in enumerate(run_states):
            if (
                type(state) is not tuple
                or len(state) != 2
                or type(state[0]) is not str
                or not state[0]
                or type(state[1]) is not str
                or state[1] not in V2_FIXTURE_RESTORATION_STATE_VALUES
            ):
                raise EvidenceFailed(
                    "fixture restoration run state row "
                    f"{run_index}:{state_index} is malformed"
                )
            v2_validate_fixture_restoration_step_name(
                state[0],
                label=(
                    "fixture restoration run state row "
                    f"{run_index}:{state_index} name"
                ),
            )
        if tuple(name for name, _state in run_states) != tuple(state_names):
            raise EvidenceFailed(
                f"fixture restoration run row {run_index} changes state order"
            )
        runner_names.append(runner)
    if (
        len(runner_names) != len(set(runner_names))
        or tuple(runner_names)
        not in {
            ("primary",),
            ("fallback",),
            ("primary", "fallback"),
        }
    ):
        raise EvidenceFailed("fixture restoration runner order is malformed")
    if len(runs) == 2 and runs[0]["converged"] is True:
        raise EvidenceFailed(
            "fixture restoration fallback follows a converged primary run"
        )
    expected_attempt_runners = tuple(
        run["runner"]
        for run in runs
        for _attempt_index in range(run["attempt_count"])
    )
    actual_attempt_runners = tuple(
        attempt["runner"] for attempt in attempts
    )
    if actual_attempt_runners != expected_attempt_runners:
        raise EvidenceFailed(
            "fixture restoration attempts do not match their run summaries"
        )
    reconstructed_anomalies: list[tuple[str, BaseException]] = []
    for run_index, run in enumerate(runs):
        runner = run["runner"]
        anomaly_prefix = runner + ":"
        run_anomalies = tuple(
            (name[len(anomaly_prefix) :], error)
            for name, error in anomalies
            if str.startswith(name, anomaly_prefix)
        )
        run_attempts = tuple(
            {
                "attempt": attempt["runner_attempt"],
                "sweep": attempt["sweep"],
                "step": attempt["step"],
                "outcome": attempt["outcome"],
                "error_type": attempt["error_type"],
                "diagnostic": attempt["diagnostic"],
            }
            for attempt in attempts
            if attempt["runner"] == runner
        )
        reconstructed = v2_validate_fixture_restoration_run_report(
            {
                "converged": run["converged"],
                "states": run["states"],
                "anomalies": run_anomalies,
                "attempts": run_attempts,
            },
            label=f"fixture reconstructed {runner} restoration runner",
        )
        if (
            len(run_anomalies) != run["anomaly_count"]
            or len(run_attempts) != run["attempt_count"]
            or reconstructed["states"] != run["states"]
            or reconstructed["converged"] is not run["converged"]
        ):
            raise EvidenceFailed(
                f"fixture restoration run row {run_index} is not reproducible"
            )
        list.extend(
            reconstructed_anomalies,
            (
                (anomaly_prefix + name, error)
                for name, error in run_anomalies
            ),
        )
    if tuple(reconstructed_anomalies) != anomalies:
        raise EvidenceFailed(
            "fixture restoration anomalies are not in canonical run order"
        )
    final_run = runs[-1]
    if (
        report["converged"] is not final_run["converged"]
        or states != final_run["states"]
    ):
        raise EvidenceFailed(
            "fixture restoration final state differs from its final run"
        )
    if verification is not None and (
        type(verification) is not dict
    ):
        raise EvidenceFailed(
            "fixture restoration verification receipt is malformed"
        )
    if verification is not None:
        v2_fixture_exact_key_set(
            verification,
            V2_FIXTURE_RESTORATION_VERIFICATION_FIELDS,
            label="fixture restoration verification receipt",
        )
    if verification is not None and any(
            not v2_is_semantic_root(verification[field])
            for field in V2_FIXTURE_RESTORATION_VERIFICATION_FIELDS
    ):
        raise EvidenceFailed(
            "fixture restoration verification receipt is malformed"
        )
    payload = {
            "converged": report["converged"],
            "states": [
                {"name": name, "state": state}
                for name, state in states
            ],
            "anomalies": [
                {
                    "step": name,
                    "error_type": v2_exception_type_projection(type(error)),
                    "diagnostic": v2_bounded_diagnostic_summary(error),
                }
                for name, error in anomalies
            ],
            "attempts": [dict(attempt) for attempt in attempts],
            "runs": [
                {
                    "runner": run["runner"],
                    "converged": run["converged"],
                    "states": [
                        {"name": name, "state": state}
                        for name, state in run["states"]
                    ],
                    "anomaly_count": run["anomaly_count"],
                    "attempt_count": run["attempt_count"],
                }
                for run in runs
            ],
            "verification": (
                dict(verification)
                if verification is not None
                else None
            ),
        }
    rooted = v2_rooted(payload)
    if (
        set(rooted) != V2_FIXTURE_RESTORATION_LOG_FIELDS
        or any(
            set(row) != V2_FIXTURE_RESTORATION_STATE_FIELDS
            for row in rooted["states"]
        )
        or any(
            set(row) != V2_FIXTURE_RESTORATION_ANOMALY_FIELDS
            for row in rooted["anomalies"]
        )
        or any(
            set(row) != V2_FIXTURE_RESTORATION_RUN_FIELDS
            or any(
                set(state) != V2_FIXTURE_RESTORATION_STATE_FIELDS
                for state in row["states"]
            )
            for row in rooted["runs"]
        )
    ):
        raise EvidenceFailed(
            "fixture restoration log projection has a non-closed schema"
        )
    return rooted


def v2_merge_fixture_restoration_reports(
    reports: Sequence[tuple[str, Mapping[str, Any]]],
) -> dict[str, Any]:
    if type(reports) is not tuple or not 1 <= len(reports) <= 2:
        raise EvidenceFailed(
            "fixture restoration report merge requires one or two runs"
        )
    merged_anomalies: list[tuple[str, BaseException]] = []
    merged_attempts: list[dict[str, Any]] = []
    run_rows: list[dict[str, Any]] = []
    seen_runners: set[str] = set()
    runner_order: list[str] = []
    expected_state_names: tuple[str, ...] | None = None
    final_report: Mapping[str, Any] | None = None
    for report_index, report_row in enumerate(reports):
        if type(report_row) is not tuple or len(report_row) != 2:
            raise EvidenceFailed(
                f"fixture restoration report row {report_index} is malformed"
            )
        runner = tuple.__getitem__(report_row, 0)
        candidate = tuple.__getitem__(report_row, 1)
        if (
            type(runner) is not str
            or runner not in {"primary", "fallback"}
            or runner in seen_runners
        ):
            raise EvidenceFailed(
                "fixture restoration run report is malformed"
            )
        runner_order.append(runner)
        candidate = v2_validate_fixture_restoration_run_report(
            candidate,
            label=f"fixture {runner} restoration runner",
        )
        seen_runners.add(runner)
        states = candidate["states"]
        candidate_state_names = tuple(name for name, _state in states)
        if expected_state_names is None:
            expected_state_names = candidate_state_names
        elif candidate_state_names != expected_state_names:
            raise EvidenceFailed(
                "fixture restoration runners changed the state schema"
            )
        anomalies = candidate["anomalies"]
        attempts = candidate["attempts"]
        for name, error in anomalies:
            if (
                type(name) is not str
                or not v2_is_exact_exception_instance(error)
            ):
                raise EvidenceFailed(
                    "fixture restoration anomaly row is malformed"
                )
            merged_anomalies.append((f"{runner}:{name}", error))
        for attempt in attempts:
            v2_fixture_exact_key_set(
                attempt,
                V2_FIXTURE_RESTORATION_ATTEMPT_FIELDS,
                label="fixture restoration attempt row",
            )
            merged_attempts.append(
                {
                    **attempt,
                    "attempt": len(merged_attempts),
                    "runner": runner,
                    "runner_attempt": attempt["attempt"],
                }
            )
        run_rows.append(
            {
                "runner": runner,
                "converged": candidate["converged"],
                "states": states,
                "anomaly_count": len(anomalies),
                "attempt_count": len(attempts),
            }
        )
        final_report = candidate
    if tuple(runner_order) not in {
        ("primary",),
        ("fallback",),
        ("primary", "fallback"),
    }:
        raise EvidenceFailed("fixture restoration runner order is malformed")
    if len(run_rows) == 2 and run_rows[0]["converged"] is True:
        raise EvidenceFailed(
            "fixture restoration fallback follows a converged primary run"
        )
    if final_report is None:
        raise EvidenceFailed("fixture restoration report merge is empty")
    return {
        "converged": final_report["converged"],
        "states": final_report["states"],
        "anomalies": tuple(merged_anomalies),
        "attempts": tuple(merged_attempts),
        "runs": tuple(run_rows),
    }


def v2_run_fixture_restoration_with_fallback(
    steps: tuple[tuple[str, Callable[[], None]], ...],
    verify: Callable[[], None],
    *,
    runner: Callable[
        [
            tuple[tuple[str, Callable[[], None]], ...],
            Callable[[], None],
        ],
        Mapping[str, Any],
    ],
) -> tuple[
    Mapping[str, Any] | None,
    BaseException | None,
    BaseException | None,
]:
    if type(runner) is not types.FunctionType:
        raise EvidenceFailed(
            "fixture restoration fallback runner is not an exact function"
        )
    expected_state_names = v2_validate_fixture_restoration_plan(
        steps,
        verify,
        label="fixture restoration fallback plan",
    )
    runner_primary: BaseException | None = None
    runner_fallback: BaseException | None = None
    primary_report: Mapping[str, Any] | None = None
    fallback_report: Mapping[str, Any] | None = None
    try:
        primary_candidate = runner(steps, verify)
    except BaseException as error:
        runner_primary = error
    else:
        try:
            primary_report = v2_validate_fixture_restoration_run_report(
                primary_candidate,
                label="fixture primary restoration runner",
            )
            if tuple(
                name for name, _state in primary_report["states"]
            ) != expected_state_names:
                raise EvidenceFailed(
                    "fixture primary restoration runner changed the plan"
                )
        except BaseException as error:
            runner_primary = error
            primary_report = None
    if (
        primary_report is None
        or primary_report.get("converged") is not True
    ):
        try:
            fallback_candidate = runner(steps, verify)
        except BaseException as error:
            runner_fallback = error
        else:
            try:
                fallback_report = v2_validate_fixture_restoration_run_report(
                    fallback_candidate,
                    label="fixture fallback restoration runner",
                )
                if tuple(
                    name for name, _state in fallback_report["states"]
                ) != expected_state_names:
                    raise EvidenceFailed(
                        "fixture fallback restoration runner changed the plan"
                    )
            except BaseException as error:
                runner_fallback = error
                fallback_report = None
    available_reports = tuple(
        row
        for row in (
            (
                ("primary", primary_report)
                if primary_report is not None
                else None
            ),
            (
                ("fallback", fallback_report)
                if fallback_report is not None
                else None
            ),
        )
        if row is not None
    )
    report: Mapping[str, Any] | None = None
    if available_reports:
        try:
            report = v2_merge_fixture_restoration_reports(
                available_reports
            )
        except BaseException as error:
            if runner_primary is None:
                runner_primary = error
            elif runner_fallback is None:
                runner_fallback = error
            else:
                v2_attach_cleanup_note(runner_fallback, error)
    return report, runner_primary, runner_fallback


def v2_attach_fixture_cleanup_diagnostics(
    primary: BaseException,
    *,
    report: Mapping[str, Any] | None,
    runner_primary: BaseException | None,
    runner_fallback: BaseException | None,
) -> None:
    notes: list[str] = []
    if report is not None:
        try:
            restoration_log = v2_fixture_restoration_log(report)
        except BaseException as error:
            notes.append(
                "fixture restoration report unreadable: "
                f"{v2_exception_type_projection(type(error))}: "
                f"{v2_bounded_diagnostic_summary(error)}"
            )
        else:
            notes.append(
                "fixture restoration report root: "
                f"{restoration_log['semantic_root']}"
            )
            for attempt in restoration_log["attempts"]:
                notes.append(
                    "fixture restoration attempt "
                    f"{attempt['attempt']} "
                    f"runner={attempt.get('runner', 'unlabeled')} "
                    f"runner_attempt={attempt.get('runner_attempt', attempt['attempt'])} "
                    f"sweep={attempt['sweep']} "
                    f"step={attempt['step']} outcome={attempt['outcome']} "
                    f"error_type={attempt['error_type']} "
                    f"diagnostic={attempt['diagnostic']}"
                )
            verification = restoration_log["verification"]
            if verification is not None:
                notes.append(
                    "fixture restoration verification "
                    f"final_root={verification['final_root']} "
                    "final_restorable_root="
                    f"{verification['final_restorable_root']} "
                    f"audit_delta_root={verification['audit_delta_root']}"
                )
    for label, error in (
        ("primary-runner", runner_primary),
        ("fallback-runner", runner_fallback),
    ):
        if error is not None:
            notes.append(
                f"fixture restoration {label}: "
                f"{v2_exception_type_projection(type(error))}: "
                f"{v2_bounded_diagnostic_summary(error)}"
            )
    for note in notes:
        if not v2_append_exception_note_without_hooks(primary, note):
            break


def v2_raise_fixture_transaction_failures(
    *,
    body_primary: BaseException | None,
    report: Mapping[str, Any] | None,
    runner_primary: BaseException | None,
    runner_fallback: BaseException | None,
) -> None:
    cleanup_error: BaseException | None = None
    cleanup_cause: BaseException | None = None
    unsuccessful_run = False
    validated_report: dict[str, Any] | None = None
    if report is not None:
        try:
            v2_fixture_restoration_log(report)
        except BaseException as error:
            cleanup_error = EvidenceFailed(
                "fixture restoration runner produced a malformed report"
            )
            cleanup_cause = error
        else:
            validated_report = report
            unsuccessful_run = any(
                run["converged"] is not True
                for run in validated_report["runs"]
            )
    if report is None:
        cleanup_error = EvidenceFailed(
            "fixture restoration runner produced no report"
        )
        cleanup_cause = (
            runner_fallback
            if runner_fallback is not None
            else runner_primary
        )
    elif (
        validated_report is not None
        and (
            validated_report["converged"] is not True
            or len(validated_report["anomalies"]) != 0
            or unsuccessful_run
            or runner_primary is not None
            or runner_fallback is not None
        )
    ):
        cleanup_error = EvidenceFailed(
            "fixture restoration had cleanup anomalies"
        )
        anomaly_rows = validated_report["anomalies"]
        if anomaly_rows:
            cleanup_cause = anomaly_rows[0][1]
        elif runner_fallback is not None:
            cleanup_cause = runner_fallback
        elif runner_primary is not None:
            cleanup_cause = runner_primary
    if body_primary is not None:
        if cleanup_error is not None:
            v2_attach_cleanup_note(body_primary, cleanup_error)
        if (
            cleanup_error is not None
            or report is not None
            or runner_primary is not None
            or runner_fallback is not None
        ):
            v2_attach_fixture_cleanup_diagnostics(
                body_primary,
                report=report,
                runner_primary=runner_primary,
                runner_fallback=runner_fallback,
            )
        raise body_primary
    if cleanup_error is not None:
        v2_attach_fixture_cleanup_diagnostics(
            cleanup_error,
            report=report,
            runner_primary=runner_primary,
            runner_fallback=runner_fallback,
        )
        if cleanup_cause is not None:
            raise cleanup_error from cleanup_cause
        raise cleanup_error


def v2_run_fixture_mutation_transaction(
    context: Mapping[str, str],
    *,
    label: str,
    intents: Sequence[tuple[str, str]],
    audit_event_budget_by_issue: Mapping[str, int],
    body: Callable[[Mapping[str, Any]], Any],
) -> dict[str, Any]:
    return _v2_run_fixture_mutation_transaction_via(
        context,
        label=label,
        intents=intents,
        audit_event_budget_by_issue=audit_event_budget_by_issue,
        body=body,
        transaction_runner=_v2_run_fixture_mutation_transaction_locked,
    )


def _v2_run_fixture_mutation_transaction_via(
    context: Mapping[str, str],
    *,
    label: str,
    intents: Sequence[tuple[str, str]],
    audit_event_budget_by_issue: Mapping[str, int],
    body: Callable[[Mapping[str, Any]], Any],
    transaction_runner: Callable[..., dict[str, Any]],
) -> dict[str, Any]:
    if type(transaction_runner) is not types.FunctionType:
        raise EvidenceFailed(
            "fixture mutation transaction runner is not an exact function"
        )
    with fixture_br_lease():
        return transaction_runner(
            context,
            label=label,
            intents=intents,
            audit_event_budget_by_issue=audit_event_budget_by_issue,
            body=body,
        )


def _v2_run_fixture_mutation_transaction_locked(
    context: Mapping[str, str],
    *,
    label: str,
    intents: Sequence[tuple[str, str]],
    audit_event_budget_by_issue: Mapping[str, int],
    body: Callable[[Mapping[str, Any]], Any],
) -> dict[str, Any]:
    if (
        type(label) is not str
        or not label
        or type(body) is not types.FunctionType
    ):
        raise EvidenceFailed("fixture mutation transaction inputs are malformed")
    exact_context = v2_validate_fixture_context(context)
    current_context = _fixture_br_context_locked()
    if current_context != exact_context:
        raise EvidenceFailed(
            "fixture mutation context differs from the canonical live fixture"
        )
    baseline = _v2_fixture_fingerprint_locked(exact_context)
    exact_intents = v2_validate_fixture_mutation_intents(
        intents,
        context=exact_context,
        baseline=baseline,
    )
    exact_audit_event_budgets = v2_require_fixture_audit_headroom(
        baseline,
        exact_intents,
        audit_event_budget_by_issue,
    )
    baseline_shows = v2_fixture_show_projection_by_id(baseline)
    mutated_issue_ids = frozenset(issue_id for issue_id, _field in exact_intents)
    verification: dict[str, Any] = {}
    restoration_steps: tuple[tuple[str, Callable[[], None]], ...] = tuple(
        (
            f"restore:{issue_id}:{field}",
            (
                lambda issue_id=issue_id, field=field: (
                    v2_restore_fixture_intent(
                        baseline_shows,
                        issue_id,
                        field,
                    )
                )
            ),
        )
        for issue_id, field in reversed(exact_intents)
    )

    def reconcile_export() -> None:
        fixture_br_json(
            "sync",
            "--flush-only",
            honor_cancel=False,
        )

    restoration_steps = (
        *restoration_steps,
        ("reconcile:sync-export", reconcile_export),
    )

    def verify() -> None:
        after = _v2_fixture_fingerprint_locked(
            exact_context,
            honor_cancel=False,
        )
        failures: list[BaseException] = []
        if (
            after["restorable_state"]["semantic_root"]
            != baseline["restorable_state"]["semantic_root"]
        ):
            divergence = first_projection_divergence(
                baseline["restorable_state"],
                after["restorable_state"],
            )
            failures.append(
                EvidenceFailed(
                    "fixture restorable state did not converge at "
                    f"{divergence or '$'}"
                )
            )
        audit_delta: dict[str, Any] | None = None
        try:
            audit_delta = v2_fixture_audit_delta(
                baseline,
                after,
                mutated_issue_ids=mutated_issue_ids,
            )
        except BaseException as error:
            failures.append(error)
        if audit_delta is not None:
            try:
                v2_validate_fixture_audit_event_budgets(
                    audit_delta,
                    exact_audit_event_budgets,
                )
            except BaseException as error:
                failures.append(error)
        if failures:
            raise BaseExceptionGroup(
                "fixture restoration verification failures",
                failures,
            )
        if audit_delta is None:
            raise EvidenceFailed(
                "fixture audit verification produced no evidence"
            )
        verification.clear()
        verification.update({
            "after": after,
            "audit_delta": audit_delta,
        })

    body_primary: BaseException | None = None
    body_result: Any = None
    during: dict[str, Any] | None = None
    runner_primary: BaseException | None = None
    runner_fallback: BaseException | None = None
    report: Mapping[str, Any] | None = None
    transaction_cancel_epoch: int | None = None
    try:
        try:
            check_cancel()
            transaction_cancel_epoch = _cancel_signal_epoch
            body_result = body(baseline)
            during = _v2_capture_fixture_mutation_observation_locked(
                exact_context,
                intents=exact_intents,
            )
        except BaseException as error:
            body_primary = error
    finally:
        (
            report,
            runner_primary,
            runner_fallback,
        ) = v2_run_fixture_restoration_with_fallback(
            restoration_steps,
            verify,
            runner=v2_run_convergent_restoration,
        )
    if report is not None and verification:
        report = {
            **report,
            "verification": {
                "final_root": verification["after"]["semantic_root"],
                "final_restorable_root": verification["after"][
                    "restorable_state"
                ]["semantic_root"],
                "audit_delta_root": verification["audit_delta"][
                    "semantic_root"
                ],
            },
        }
    if (
        body_primary is None
        and transaction_cancel_epoch is not None
        and (
            _cancel_requested
            or _cancel_signal_epoch > transaction_cancel_epoch
        )
    ):
        body_primary = CancelledDrained(
            "cancellation requested; fixture mutation was restored and drained"
        )
    v2_raise_fixture_transaction_failures(
        body_primary=body_primary,
        report=report,
        runner_primary=runner_primary,
        runner_fallback=runner_fallback,
    )
    if report is None or not verification:
        raise EvidenceFailed(
            "fixture restoration completed without final verification"
        )
    restoration_log = v2_fixture_restoration_log(report)
    return v2_rooted(
        {
            "label": label,
            "restoration_intents": [
                {"issue_id": issue_id, "field": field}
                for issue_id, field in exact_intents
            ],
            "audit_event_budget_by_issue": exact_audit_event_budgets,
            "baseline_root": baseline["semantic_root"],
            "baseline_restorable_root": baseline["restorable_state"][
                "semantic_root"
            ],
            "during_root": (
                during["semantic_root"] if during is not None else None
            ),
            "body_result": v2_assertion_evidence_projection(body_result),
            "restoration": restoration_log,
            "audit_delta": verification["audit_delta"],
            "final_root": verification["after"]["semantic_root"],
            "final_restorable_root": verification["after"][
                "restorable_state"
            ]["semantic_root"],
            "no_claim": (
                "br-only restoration proves exact normalized restorable state "
                "and append-only audit preservation; it does not erase audit "
                "events, observe every transient intermediate field value, "
                "or claim wall-clock reversibility"
            ),
        }
    )


def v2_fixture_transaction_regression_matrix() -> dict[str, Any]:
    stable_id = "fixture-transaction-stable"
    regression_id = "fixture-transaction-regression"
    context = {
        "stable_id": stable_id,
        "regression_id": regression_id,
    }

    original_seed_functions = {
        name: globals()[name]
        for name in (
            "fixture_br_find_canonical",
            "fixture_br_create_seed",
            "fixture_br_show",
            "fixture_br_validate_canonical_seed",
            "fixture_br_json",
        )
    }
    fresh_stable_id = FIXTURE_BR_STABLE_ID_PREFIX + "fresh"
    fresh_regression_id = FIXTURE_BR_REGRESSION_ID_PREFIX + "fresh"
    fresh_seed_rows: dict[str, dict[str, Any]] = {}
    fresh_seed_events: list[str] = []
    fresh_seed_find_events: list[str] = []

    def fresh_seed_find(prefix: str) -> dict[str, Any] | None:
        fresh_seed_find_events.append(prefix)
        for issue_id, row in dict.items(fresh_seed_rows):
            if issue_id.startswith(prefix):
                return dict(row)
        return None

    def fresh_seed_create(
        *,
        title: str,
        slug: str,
        status: str,
        description: str,
        ephemeral: bool,
    ) -> dict[str, Any]:
        issue_id = (
            fresh_stable_id
            if slug == "template-hygiene-actionable-v2"
            else fresh_regression_id
        )
        row = {
            "id": issue_id,
            "title": title,
            "description": description,
            "status": status,
            "ephemeral": ephemeral,
            "close_reason": None,
        }
        fresh_seed_rows[issue_id] = row
        fresh_seed_events.append(
            f"create:{issue_id}:{status}:{ephemeral}"
        )
        return dict(row)

    def fresh_seed_show(
        issue_id: str,
        *,
        honor_cancel: bool = True,
    ) -> dict[str, Any]:
        if honor_cancel is not True or issue_id not in fresh_seed_rows:
            raise EvidenceFailed("fresh seed show contract differs")
        row = dict(fresh_seed_rows[issue_id])
        fresh_seed_events.append(f"show:{issue_id}:{row['status']}")
        return row

    def fresh_seed_validate(
        issue: Mapping[str, Any],
        *,
        title: str,
        description: str,
        status: str,
        ephemeral: bool,
    ) -> None:
        if (
            type(issue) is not dict
            or dict.get(issue, "title") != title
            or dict.get(issue, "description") != description
            or dict.get(issue, "status") != status
            or (dict.get(issue, "ephemeral") is True) is not ephemeral
        ):
            raise EvidenceFailed("fresh seed validation contract differs")
        fresh_seed_events.append(f"validate:{issue['id']}:{status}")

    def fresh_seed_json(
        *arguments: str,
        input_text: str | None = None,
        honor_cancel: bool = True,
    ) -> dict[str, Any]:
        if input_text is not None or honor_cancel is not True:
            raise EvidenceFailed("fresh seed JSON command contract differs")
        if arguments == (
            "close",
            fresh_regression_id,
            "--reason",
            FIXTURE_BR_REGRESSION_CLOSE_REASON,
        ):
            row = fresh_seed_rows[fresh_regression_id]
            row["status"] = "closed"
            row["close_reason"] = FIXTURE_BR_REGRESSION_CLOSE_REASON
            fresh_seed_events.append(
                f"close:{fresh_regression_id}:"
                f"{FIXTURE_BR_REGRESSION_CLOSE_REASON}"
            )
            return {}
        if arguments == ("sync", "--flush-only"):
            fresh_seed_events.append("sync:flush-only")
            return {}
        raise EvidenceFailed(
            f"unexpected fresh seed JSON command {arguments!r}"
        )

    globals()["fixture_br_find_canonical"] = fresh_seed_find
    globals()["fixture_br_create_seed"] = fresh_seed_create
    globals()["fixture_br_show"] = fresh_seed_show
    globals()["fixture_br_validate_canonical_seed"] = fresh_seed_validate
    globals()["fixture_br_json"] = fresh_seed_json
    try:
        (
            observed_fresh_stable_id,
            observed_fresh_regression_id,
            fresh_seed_initialized,
        ) = _fixture_br_ensure_canonical_seeds()
        if fresh_seed_initialized:
            fixture_br_json("sync", "--flush-only")
    finally:
        for name, value in dict.items(original_seed_functions):
            globals()[name] = value
    expected_fresh_seed_events = [
        f"create:{fresh_stable_id}:open:False",
        f"show:{fresh_stable_id}:open",
        f"validate:{fresh_stable_id}:open",
        f"create:{fresh_regression_id}:open:True",
        f"show:{fresh_regression_id}:open",
        (
            f"close:{fresh_regression_id}:"
            f"{FIXTURE_BR_REGRESSION_CLOSE_REASON}"
        ),
        f"show:{fresh_regression_id}:closed",
        f"validate:{fresh_regression_id}:closed",
        "sync:flush-only",
    ]
    fresh_seed_context = {
        "passed": fresh_seed_initialized
        and observed_fresh_stable_id == fresh_stable_id
        and observed_fresh_regression_id == fresh_regression_id
        and fresh_seed_events == expected_fresh_seed_events
        and fresh_seed_rows[fresh_regression_id]["status"] == "closed"
        and fresh_seed_rows[fresh_regression_id]["close_reason"]
        == FIXTURE_BR_REGRESSION_CLOSE_REASON
        and fresh_seed_find_events
        == [
            FIXTURE_BR_STABLE_ID_PREFIX,
            FIXTURE_BR_REGRESSION_ID_PREFIX,
        ],
        "events": fresh_seed_events,
        "find_events": fresh_seed_find_events,
        "stable_id": observed_fresh_stable_id,
        "regression_id": observed_fresh_regression_id,
        "regression_status": fresh_seed_rows[fresh_regression_id][
            "status"
        ],
        "regression_close_reason": fresh_seed_rows[
            fresh_regression_id
        ]["close_reason"],
    }

    preexisting_seed_residue_rows: list[dict[str, Any]] = []
    for residue_case, residue_status, residue_reason, residue_ephemeral in (
        (
            "open-status",
            "open",
            FIXTURE_BR_REGRESSION_CLOSE_REASON,
            True,
        ),
        ("wrong-reason", "closed", "wrong fixture reason", True),
        (
            "non-ephemeral",
            "closed",
            FIXTURE_BR_REGRESSION_CLOSE_REASON,
            False,
        ),
        (
            "integer-ephemeral",
            "closed",
            FIXTURE_BR_REGRESSION_CLOSE_REASON,
            1,
        ),
    ):
        residue_state = {
            fresh_stable_id: {
                "id": fresh_stable_id,
                "title": FIXTURE_BR_STABLE_TITLE,
                "description": FIXTURE_BR_STABLE_DESCRIPTION,
                "status": "open",
                "ephemeral": False,
                "close_reason": None,
            },
            fresh_regression_id: {
                "id": fresh_regression_id,
                "title": FIXTURE_BR_REGRESSION_TITLE,
                "description": FIXTURE_BR_REGRESSION_DESCRIPTION,
                "status": residue_status,
                "ephemeral": residue_ephemeral,
                "close_reason": residue_reason,
            },
        }
        residue_state_root_before = semantic_root(residue_state)
        residue_mutations: list[str] = []
        residue_validations: list[str] = []

        def residue_find(prefix: str) -> dict[str, Any] | None:
            for issue_id, row in dict.items(residue_state):
                if issue_id.startswith(prefix):
                    return dict(row)
            return None

        def residue_create(**_kwargs: Any) -> dict[str, Any]:
            residue_mutations.append("create")
            raise EvidenceFailed("preexisting residue attempted create")

        def residue_show(
            issue_id: str,
            *,
            honor_cancel: bool = True,
        ) -> dict[str, Any]:
            if honor_cancel is not True:
                raise EvidenceFailed("residue show cancellation differs")
            return dict(residue_state[issue_id])

        def residue_validate(
            issue: Mapping[str, Any],
            **_kwargs: Any,
        ) -> None:
            residue_validations.append(str(dict.get(issue, "id")))

        def residue_json(*arguments: str, **_kwargs: Any) -> dict[str, Any]:
            residue_mutations.append(":".join(arguments))
            raise EvidenceFailed("preexisting residue attempted mutation")

        globals()["fixture_br_find_canonical"] = residue_find
        globals()["fixture_br_create_seed"] = residue_create
        globals()["fixture_br_show"] = residue_show
        globals()["fixture_br_validate_canonical_seed"] = residue_validate
        globals()["fixture_br_json"] = residue_json
        try:
            residue_error = expect_error(
                InfrastructureFailed,
                _fixture_br_ensure_canonical_seeds,
                contains=(
                    "no-mock regression fixture lacks its exact closed "
                    "ephemeral baseline"
                ),
            )
        finally:
            for name, value in dict.items(original_seed_functions):
                globals()[name] = value
        preexisting_seed_residue_rows.append(
            {
                "case": residue_case,
                "terminal": residue_error.terminal,
                "diagnostic_root": text_root(str(residue_error)),
                "state_unchanged": (
                    semantic_root(residue_state) == residue_state_root_before
                ),
                "mutations": residue_mutations,
                "validations": residue_validations,
            }
        )
    preexisting_seed_residue = {
        "passed": all(
            row["terminal"] == "InfrastructureFailed"
            and row["state_unchanged"]
            and row["mutations"] == []
            and row["validations"] == [fresh_stable_id]
            for row in preexisting_seed_residue_rows
        ),
        "cases": preexisting_seed_residue_rows,
    }
    baseline = {
        "issue_ids": [regression_id, stable_id],
        "canonical_roles": {
            "stable": stable_id,
            "regression": regression_id,
        },
        "shows": [
            {"id": regression_id, "status": "closed"},
            {"id": stable_id, "status": "open"},
        ],
        "audits": {
            regression_id: {"events": []},
            stable_id: {"events": []},
        },
    }
    stable_fields = sorted(V2_FIXTURE_MUTABLE_FIELDS)
    regression_fields = [
        field for field in stable_fields if field != "status"
    ]
    fifteen_intents = tuple(
        [(stable_id, field) for field in stable_fields]
        + [
            (regression_id, field)
            for field in regression_fields[:5]
        ]
    )
    sixteen_intents = (
        *fifteen_intents,
        (regression_id, regression_fields[5]),
    )
    admitted_intents = v2_validate_fixture_mutation_intents(
        fifteen_intents,
        context=context,
        baseline=baseline,
    )
    cap_error = expect_error(
        EvidenceFailed,
        lambda: v2_validate_fixture_mutation_intents(
            sixteen_intents,
            context=context,
            baseline=baseline,
        ),
        contains="15-field restoration cap",
    )
    closed_status_error = expect_error(
        EvidenceFailed,
        lambda: v2_validate_fixture_mutation_intents(
            ((regression_id, "status"),),
            context=context,
            baseline=baseline,
        ),
        contains="cannot exactly restore a closed status",
    )
    intent_refusal_inputs: tuple[tuple[str, Any, str], ...] = (
        ("empty", (), "requires explicit intents"),
        (
            "duplicate",
            ((stable_id, "description"), (stable_id, "description")),
            "contain duplicates",
        ),
        (
            "unknown-issue",
            (("fixture-transaction-unknown", "description"),),
            "malformed or unsupported",
        ),
        (
            "unsupported-field",
            ((stable_id, "invented"),),
            "malformed or unsupported",
        ),
        (
            "malformed-row-container",
            ([stable_id, "description"],),
            "malformed or unsupported",
        ),
        (
            "malformed-intent-container",
            {(stable_id, "description")},
            "requires explicit intents",
        ),
    )
    intent_refusals = []
    for refusal_case, candidate, diagnostic in intent_refusal_inputs:
        error = expect_error(
            EvidenceFailed,
            lambda candidate=candidate: v2_validate_fixture_mutation_intents(
                candidate,
                context=context,
                baseline=baseline,
            ),
            contains=diagnostic,
        )
        intent_refusals.append(
            {
                "case": refusal_case,
                "terminal": error.terminal,
                "diagnostic_root": text_root(str(error)),
            }
        )
    intent_preflight = {
        "passed": len(admitted_intents) == 15
        and cap_error.terminal == "EvidenceFailed"
        and closed_status_error.terminal == "EvidenceFailed"
        and all(
            row["terminal"] == "EvidenceFailed"
            for row in intent_refusals
        ),
        "admitted_count": len(admitted_intents),
        "refused_count": len(sixteen_intents),
        "cap_terminal": cap_error.terminal,
        "closed_status_terminal": closed_status_error.terminal,
        "named_refusals": intent_refusals,
    }

    audit_intents = ((stable_id, "description"),)
    exact_headroom_count = (
        V2_AUDIT_EVENTS_PER_ISSUE_CAP
        - V2_FIXTURE_AUDIT_EVENT_FIXED_HEADROOM
        - V2_FIXTURE_AUDIT_EVENTS_PER_INTENT_HEADROOM
    )
    exact_headroom_baseline = {
        **baseline,
        "audits": {
            **baseline["audits"],
            stable_id: {"events": [{}] * exact_headroom_count},
        },
    }
    admitted_budgets = v2_require_fixture_audit_headroom(
        exact_headroom_baseline,
        audit_intents,
        {stable_id: V2_FIXTURE_AUDIT_EVENTS_PER_INTENT_HEADROOM},
    )
    over_headroom_baseline = {
        **baseline,
        "audits": {
            **baseline["audits"],
            stable_id: {"events": [{}] * (exact_headroom_count + 1)},
        },
    }
    headroom_error = expect_error(
        InputRefused,
        lambda: v2_require_fixture_audit_headroom(
            over_headroom_baseline,
            audit_intents,
            {
                stable_id: (
                    V2_FIXTURE_AUDIT_EVENTS_PER_INTENT_HEADROOM
                )
            },
        ),
        contains="lacks safe mutation/restoration headroom",
    )
    below_minimum_error = expect_error(
        EvidenceFailed,
        lambda: v2_require_fixture_audit_headroom(
            baseline,
            audit_intents,
            {
                stable_id: (
                    V2_FIXTURE_AUDIT_EVENTS_PER_INTENT_HEADROOM - 1
                )
            },
        ),
        contains="below the per-intent minimum",
    )

    def synthetic_audit_delta_row(
        issue_id: str,
        *,
        before_count: int,
        added_count: int,
    ) -> dict[str, Any]:
        return {
            "issue_id": issue_id,
            "before_count": before_count,
            "after_count": before_count + added_count,
            "added_count": added_count,
            "added_root": semantic_root(
                {
                    "issue_id": issue_id,
                    "synthetic_added_count": added_count,
                }
            ),
            "old_stream_preserved_as_suffix": True,
        }

    stable_delta_row = synthetic_audit_delta_row(
        stable_id,
        before_count=9,
        added_count=4,
    )
    regression_delta_row = synthetic_audit_delta_row(
        regression_id,
        before_count=7,
        added_count=0,
    )
    exact_delta = v2_rooted(
        {"issues": [stable_delta_row, regression_delta_row]}
    )
    v2_validate_fixture_audit_event_budgets(
        exact_delta,
        {stable_id: 4},
    )
    overrun_delta = v2_rooted(
        {
            "issues": [
                synthetic_audit_delta_row(
                    stable_id,
                    before_count=9,
                    added_count=5,
                ),
                regression_delta_row,
            ]
        }
    )
    budget_overrun_error = expect_error(
        EvidenceFailed,
        lambda: v2_validate_fixture_audit_event_budgets(
            overrun_delta,
            {stable_id: 4},
        ),
        contains="exceeded the declared transaction budget",
    )
    headroom_refusal_specs: tuple[
        tuple[str, Mapping[str, Any], Mapping[str, int], str], ...
    ] = (
        (
            "missing-budget-membership",
            baseline,
            {},
            "membership differs",
        ),
        (
            "extra-budget-membership",
            baseline,
            {stable_id: 4, regression_id: 4},
            "membership differs",
        ),
        (
            "boolean-budget",
            baseline,
            {stable_id: True},
            "malformed or below",
        ),
        (
            "over-cap-budget",
            baseline,
            {stable_id: V2_AUDIT_EVENTS_PER_ISSUE_CAP + 1},
            "malformed or below",
        ),
        (
            "malformed-audit-document",
            {
                **baseline,
                "audits": {
                    **baseline["audits"],
                    stable_id: {"events": {}},
                },
            },
            {stable_id: 4},
            "audit is malformed",
        ),
    )
    headroom_refusals = []
    for refusal_case, candidate, budgets, diagnostic in headroom_refusal_specs:
        error = expect_error(
            EvidenceFailed,
            lambda candidate=candidate, budgets=budgets: (
                v2_require_fixture_audit_headroom(
                    candidate,
                    audit_intents,
                    budgets,
                )
            ),
            contains=diagnostic,
        )
        headroom_refusals.append(
            {
                "case": refusal_case,
                "terminal": error.terminal,
                "diagnostic_root": text_root(str(error)),
            }
        )

    malformed_delta_row = dict(stable_delta_row)
    malformed_delta_row.pop("added_root")
    negative_delta_row = dict(stable_delta_row)
    negative_delta_row["added_count"] = -1
    negative_delta_row["after_count"] = (
        negative_delta_row["before_count"] - 1
    )
    delta_refusal_specs: tuple[
        tuple[str, Mapping[str, Any], Mapping[str, int], str], ...
    ] = (
        (
            "duplicate-row",
            v2_rooted({"issues": [stable_delta_row, stable_delta_row]}),
            {stable_id: 4},
            "duplicates an issue",
        ),
        (
            "malformed-row",
            v2_rooted({"issues": [malformed_delta_row]}),
            {stable_id: 4},
            "row is malformed",
        ),
        (
            "negative-added-count",
            v2_rooted({"issues": [negative_delta_row]}),
            {stable_id: 4},
            "row is malformed",
        ),
        (
            "undeclared-added-events",
            v2_rooted(
                {
                    "issues": [
                        stable_delta_row,
                        synthetic_audit_delta_row(
                            regression_id,
                            before_count=7,
                            added_count=1,
                        ),
                    ]
                }
            ),
            {stable_id: 4},
            "changed for an undeclared issue",
        ),
        (
            "missing-declared-issue",
            v2_rooted({"issues": [regression_delta_row]}),
            {stable_id: 4},
            "lacks a declared issue",
        ),
        (
            "boolean-verification-budget",
            exact_delta,
            {stable_id: True},
            "input is malformed",
        ),
    )
    delta_refusals = []
    for refusal_case, delta, budgets, diagnostic in delta_refusal_specs:
        error = expect_error(
            EvidenceFailed,
            lambda delta=delta, budgets=budgets: (
                v2_validate_fixture_audit_event_budgets(delta, budgets)
            ),
            contains=diagnostic,
        )
        delta_refusals.append(
            {
                "case": refusal_case,
                "terminal": error.terminal,
                "diagnostic_root": text_root(str(error)),
            }
        )
    audit_budget = {
        "passed": admitted_budgets == {stable_id: 4}
        and headroom_error.terminal == "InputRefused"
        and below_minimum_error.terminal == "EvidenceFailed"
        and budget_overrun_error.terminal == "EvidenceFailed"
        and all(
            row["terminal"] == "EvidenceFailed"
            for row in [*headroom_refusals, *delta_refusals]
        ),
        "exact_existing_event_count": exact_headroom_count,
        "declared_budget": admitted_budgets[stable_id],
        "over_headroom_terminal": headroom_error.terminal,
        "below_minimum_terminal": below_minimum_error.terminal,
        "overrun_terminal": budget_overrun_error.terminal,
        "headroom_refusals": headroom_refusals,
        "delta_refusals": delta_refusals,
    }

    transaction_manifest_contract = (
        v2_runtime_fixture_transaction_manifest_contract()
    )
    v2_validate_fixture_transaction_manifest_contract(
        transaction_manifest_contract,
        error_type=EvidenceFailed,
    )
    manifest_contract_refusals = []
    for field, value in transaction_manifest_contract.items():
        candidate = {
            key: (list(row) if type(row) is list else row)
            for key, row in transaction_manifest_contract.items()
        }
        if type(value) is bool:
            candidate[field] = not value
        elif type(value) is int:
            candidate[field] = value + 1
        elif type(value) is list:
            candidate[field] = value[:-1]
        else:
            raise EvidenceFailed(
                "fixture transaction manifest test has an unsupported value"
            )
        error = expect_error(
            EvidenceFailed,
            lambda candidate=candidate: (
                v2_validate_fixture_transaction_manifest_contract(
                    candidate,
                    error_type=EvidenceFailed,
                )
            ),
            contains=field,
        )
        manifest_contract_refusals.append(
            {
                "field": field,
                "terminal": error.terminal,
                "diagnostic_root": text_root(str(error)),
            }
        )
    manifest_contract = {
        "passed": len(manifest_contract_refusals)
        == len(transaction_manifest_contract)
        and all(
            row["terminal"] == "EvidenceFailed"
            for row in manifest_contract_refusals
        ),
        "field_count": len(transaction_manifest_contract),
