    def dependency_fixture_json(*arguments: str, **_keywords: Any) -> Any:
        operation = ":".join(arguments[:4])
        dependency_calls.append(operation)
        if arguments[:3] == ("dep", "remove", stable_id):
            if arguments[3] == "remove-a":
                raise EvidenceFailed("synthetic remove-a failure")
            return {}
        if arguments[:3] == ("dep", "add", stable_id):
            if arguments[3] == "add-a":
                raise EvidenceFailed("synthetic add-a failure")
            return {}
        raise EvidenceFailed("unexpected synthetic dependency operation")

