        unexpected_exception_type=None,
        subject="synthetic fixture transaction serializer regression",
        check_obligation_root=semantic_root(
            "synthetic fixture transaction obligation"
        ),
        harness_contract_identity=semantic_root(
            "synthetic fixture transaction harness"
        ),
    )
    v2_validate_exception_note_projection(
        serialized_body_failure["exception_notes"]
    )
    body_cleanup = {
        "passed": caught_body_error is body_error
        and any("cleanup anomaly" in note for note in body_notes)
        and any("report root" in note for note in body_notes)
        and any("runner=primary" in note for note in body_notes)
        and any("runner=fallback" in note for note in body_notes)
        and any("primary-runner" in note for note in body_notes)
        and any("fallback-runner" in note for note in body_notes)
        and set(serialized_body_failure)
        == V2_TEST_FAILURE_PROJECTION_FIELDS
        and serialized_body_failure["exception_notes"]["state"]
        == "RETAINED"
        and serialized_body_failure["exception_notes"]["count"]
        == len(body_notes)
        and serialized_body_failure["exception_notes"][
            "ordered_roots"
        ]
        == [text_root(note) for note in body_notes]
        and "exception_note_count="
        in v2_runner_diagnostic(body_error),
        "primary_identity_preserved": caught_body_error is body_error,
        "note_count": len(body_notes),
        "note_roots": [text_root(note) for note in body_notes],
        "serialized_projection_root": semantic_root(
            serialized_body_failure
        ),
        "serialized_exception_notes_root": serialized_body_failure[
            "exception_notes"
        ]["semantic_root"],
    }

    hostile_note_hook_calls = 0

    class HostileNoteError(EvidenceFailed):
        def __getattribute__(self, name: str) -> Any:
            nonlocal hostile_note_hook_calls
            if name == "__notes__":
                hostile_note_hook_calls += 1
                raise AssertionError("hostile note hook executed")
            return object.__getattribute__(self, name)

    hostile_note_error = HostileNoteError(
        "synthetic hostile note target"
    )
    hook_free_note_attached = v2_append_exception_note_without_hooks(
        hostile_note_error,
        "fixture cleanup anomaly: EvidenceFailed",
    )
    v2_attach_fixture_cleanup_diagnostics(
        hostile_note_error,
        report=merged_fallback,
        runner_primary=None,
        runner_fallback=None,
    )
    hostile_note_raw = v2_raw_instance_dictionary(hostile_note_error)
    hostile_note_rows = (
        dict.__getitem__(hostile_note_raw, "__notes__")
        if hostile_note_raw is not None
        and dict.__contains__(hostile_note_raw, "__notes__")
        else None
    )

    hostile_bool_calls = 0

    class HostileBoolRunnerError(EvidenceFailed):
        def __bool__(self) -> bool:
            nonlocal hostile_bool_calls
            hostile_bool_calls += 1
            raise AssertionError("hostile runner bool hook executed")

    hostile_bool_runner = HostileBoolRunnerError(
        "synthetic hostile runner cause"
    )
    hostile_bool_caught: BaseException | None = None
    try:
        v2_raise_fixture_transaction_failures(
            body_primary=None,
            report=None,
            runner_primary=None,
            runner_fallback=hostile_bool_runner,
        )
    except BaseException as error:
        hostile_bool_caught = error
    body_cleanup["hostile_hooks"] = {
        "note_hook_calls": hostile_note_hook_calls,
        "note_attached": hook_free_note_attached,
        "raw_note_count": (
            list.__len__(hostile_note_rows)
            if type(hostile_note_rows) is list
            else None
        ),
        "bool_hook_calls": hostile_bool_calls,
        "cause_identity_preserved": (
            hostile_bool_caught is not None
            and hostile_bool_caught.__cause__ is hostile_bool_runner
        ),
    }
    body_cleanup["passed"] = (
        body_cleanup["passed"]
        and hook_free_note_attached
        and hostile_note_hook_calls == 0
        and type(hostile_note_rows) is list
        and list.__len__(hostile_note_rows) >= 2
        and hostile_bool_calls == 0
        and type(hostile_bool_caught) is EvidenceFailed
        and hostile_bool_caught.__cause__ is hostile_bool_runner
    )

    return v2_rooted(
        {
            "intent_preflight": intent_preflight,
            "audit_budget": audit_budget,
            "manifest_contract": manifest_contract,
            "live_label_boundary": live_label_boundary,
            "attempt_all": attempt_all,
            "residue": residue,
            "fallback": fallback,
            "dual_runner": dual_runner,
            "dependency_attempt_all": dependency_attempt_all,
            "status_identity": status_identity,
            "body_cleanup": body_cleanup,
            "fresh_seed_context": fresh_seed_context,
            "preexisting_seed_residue": preexisting_seed_residue,
            "no_claim": (
                "the regression matrix uses bounded in-memory fault seams; "
                "live released-br mutation/restoration is proven separately"
            ),
        }
    )


def v2_fixture_transaction_lease_serialization_probe() -> dict[str, Any]:
    if _fixture_br_lock_depth != 0 or _fixture_br_active_lease is not None:
        raise EvidenceFailed(
            "fixture transaction serialization probe requires pristine lease state"
        )
    original_guard_attempt = _fixture_br_try_acquire_thread_guard
    first_entered = threading.Event()
    release_first = threading.Event()
    second_guard_attempted = threading.Event()
    second_guard_attempt_completed = threading.Event()
    second_entered = threading.Event()
    entry_order: list[str] = []
    results: list[str] = []
    errors: list[str] = []

    def gated_transaction(
        context: Mapping[str, str],
        *,
        label: str,
        intents: Sequence[tuple[str, str]],
        audit_event_budget_by_issue: Mapping[str, int],
        body: Callable[[Mapping[str, Any]], Any],
    ) -> dict[str, Any]:
        del label, intents, audit_event_budget_by_issue, body
        worker = context.get("worker")
        if worker not in {"first", "second"}:
            raise EvidenceFailed(
                "fixture transaction serialization worker is unknown"
            )
        entry_order.append(worker)
        if worker == "first":
            first_entered.set()
            if not release_first.wait(timeout=5.0):
                raise EvidenceFailed(
                    "fixture transaction serialization first worker timed out"
                )
        else:
            second_entered.set()
        return {"worker": worker}

    def unused_body(_baseline: Mapping[str, Any]) -> None:
        return None

    def observed_guard_attempt(
        *,
        owner_slot: list[FixtureBrThreadGuardOwner | None],
    ) -> None:
        is_second = (
            threading.current_thread().name
            == "fixture-transaction-serialization-second"
        )
        if is_second:
            second_guard_attempted.set()
        try:
            original_guard_attempt(owner_slot=owner_slot)
        finally:
            if is_second:
                second_guard_attempt_completed.set()

    def run_worker(worker: str) -> None:
        try:
            result = _v2_run_fixture_mutation_transaction_via(
                {"worker": worker},
                label=f"serialization-{worker}",
                intents=(),
                audit_event_budget_by_issue={},
                body=unused_body,
                transaction_runner=gated_transaction,
            )
        except BaseException as error:
            errors.append(
                f"{worker}:{v2_raw_type_name(type(error))}:"
                f"{v2_bounded_diagnostic_summary(error)}"
            )
        else:
            results.append(str(result.get("worker")))

    globals()[
        "_fixture_br_try_acquire_thread_guard"
    ] = observed_guard_attempt
    first_thread = threading.Thread(
        target=run_worker,
        args=("first",),
        name="fixture-transaction-serialization-first",
    )
    second_thread = threading.Thread(
        target=run_worker,
        args=("second",),
        name="fixture-transaction-serialization-second",
    )
    first_started = False
    second_started = False
    second_entered_before_release = False
    probe_primary: BaseException | None = None
    cleanup_primary: BaseException | None = None
    try:
        first_thread.start()
        first_started = True
        if not first_entered.wait(timeout=5.0):
            raise EvidenceFailed(
                "fixture transaction serialization first worker did not enter"
            )
        second_thread.start()
        second_started = True
        if not second_guard_attempted.wait(timeout=5.0):
            raise EvidenceFailed(
                "fixture transaction serialization second worker did not "
                "reach the guard-acquisition boundary"
            )
        if not second_guard_attempt_completed.wait(timeout=5.0):
            raise EvidenceFailed(
                "fixture transaction serialization second guard attempt "
                "did not complete"
            )
        second_entered_before_release = second_entered.is_set()
    except BaseException as error:
        probe_primary = error
    finally:
        release_first.set()
        first_started = first_started or first_thread.ident is not None
        second_started = second_started or second_thread.ident is not None
        drain_deadline = (
            time.monotonic() + FIXTURE_BR_LOCK_TIMEOUT_SECONDS + 5.0
        )
        for thread, started in (
            (first_thread, first_started),
            (second_thread, second_started),
        ):
            if not started:
                continue
            remaining = drain_deadline - time.monotonic()
            if remaining > 0:
                thread.join(timeout=remaining)
        workers_alive = (
            (first_started and first_thread.is_alive())
            or (second_started and second_thread.is_alive())
        )
        if workers_alive:
            cleanup_primary = EvidenceFailed(
                "fixture transaction serialization workers did not drain "
                "within the shared bounded deadline"
            )
        else:
            globals()[
                "_fixture_br_try_acquire_thread_guard"
            ] = original_guard_attempt
    if probe_primary is not None:
        if cleanup_primary is not None:
            v2_attach_cleanup_note(probe_primary, cleanup_primary)
        raise probe_primary
    if cleanup_primary is not None:
        raise cleanup_primary
    first_alive = first_thread.is_alive()
    second_alive = second_thread.is_alive()
    state_pristine = (
        _fixture_br_lock_depth == 0 and _fixture_br_active_lease is None
    )
    return v2_rooted(
        {
            "passed": not second_entered_before_release
            and second_guard_attempted.is_set()
            and second_guard_attempt_completed.is_set()
            and entry_order == ["first", "second"]
            and sorted(results) == ["first", "second"]
            and not errors
            and not first_alive
            and not second_alive
            and state_pristine,
            "second_entered_before_release": (
                second_entered_before_release
            ),
            "second_guard_attempted": second_guard_attempted.is_set(),
            "second_guard_attempt_completed": (
                second_guard_attempt_completed.is_set()
            ),
            "entry_order": entry_order,
            "results": sorted(results),
            "errors": errors,
            "first_thread_alive": first_alive,
            "second_thread_alive": second_alive,
            "lease_state_pristine": state_pristine,
        }
    )


V2_FIXTURE_BR_CASE_SLUGS = frozenset(
    {
        "nomock-current-br-two-gate-nodata",
        "nomock-review-plan",
        "nomock-history-plan",
        "nomock-unrelated-drift-stability",
        "nomock-selected-drift-refusal",
        "nomock-active-conflict-deferred",
        "nomock-oversize",
        "nomock-offline-replay",
        "nomock-live-target-unchanged",
    }
)


def v2_execute_nomock_cases(
    case: Mapping[str, Any],
    manifest: Mapping[str, Any],
) -> dict[str, Any]:
    slug = str(case["id"]).removeprefix("template-lint-v2.")
    if slug not in V2_FIXTURE_BR_CASE_SLUGS:
        return _v2_execute_nomock_cases_impl(case, manifest)
    lease_lifecycle_probe = None
    if slug == "nomock-live-target-unchanged":
        lease_lifecycle_probe = {
            **v2_fixture_br_lease_lifecycle_probe(),
            "transaction_serialization": (
                v2_fixture_transaction_lease_serialization_probe()
            ),
        }
    with fixture_br_lease() as lease:
        if slug == "nomock-live-target-unchanged":
            fixture_br_external_lock_probe(
                lease,
                expected="CONTENDED",
            )
        result = _v2_execute_nomock_cases_impl(
            case,
            manifest,
            lease_lifecycle_probe=lease_lifecycle_probe,
        )
    if slug == "nomock-live-target-unchanged":
        with fixture_br_lease() as reacquired:
            if (
                reacquired.device != lease.device
                or reacquired.inode != lease.inode
            ):
                raise InfrastructureFailed(
                    "fixture lock identity changed across release and reacquisition"
                )
            fixture_br_external_lock_probe(
                reacquired,
                expected="CONTENDED",
            )
    return result


def _v2_execute_nomock_cases_impl(
    case: Mapping[str, Any],
    manifest: Mapping[str, Any],
    *,
    lease_lifecycle_probe: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    global _cancel_requested
    slug = str(case["id"]).removeprefix("template-lint-v2.")
    checks = V2CheckCollector(case["id"], case["assertion_id"])
    parameters = {"family": "released-br-no-mock-e2e", "slug": slug}

    if slug == "nomock-br-robot-cells":
        issues = normalize_document(
            br_read_json(
                "list",
                "--all",
                "--deferred",
                "--json",
                "--limit",
                "0",
            ),
            label="no-mock all-status list",
        )
        bv_projection = v2_nomock_bv_projection()
        snapshot = collect_live_v2(manifest)
        campaign_root, _ = v2_campaign_epoch(snapshot)
        production_inventory = v2_build_inventory(
            snapshot,
            campaign_epoch_root=campaign_root,
            priority_filter=None,
            status_filter=None,
        )
        production_zero = v2_build_zero_sets(
            source_root=snapshot.source["semantic_root"],
            inventory=production_inventory,
            prior_campaign=v2_empty_prior_campaign(),
            current_universe=snapshot.all_issues,
            current_finding_ids=v2_snapshot_current_finding_ids(snapshot),
        )
        v2_validate_zero_sets(
            production_zero,
            source_root=snapshot.source["semantic_root"],
            inventory=production_inventory,
            prior_campaign=v2_empty_prior_campaign(),
            current_universe=snapshot.all_issues,
            current_finding_ids=v2_snapshot_current_finding_ids(snapshot),
        )
        statuses = Counter(str(row.get("status") or "") for row in issues)
        priorities = Counter(int(row.get("priority")) for row in issues)
        cells = {
            f"P{priority}/{status}": sum(
                row.get("priority") == priority
                and row.get("status") == status
                for row in issues
            )
            for priority in range(5)
            for status in STATUS_SCOPES
        }
        zero_receipts = [
            v2_rooted(
                {
                    "cell": cell,
                    "count": count,
                    "issue_ids_root": semantic_root(
                        sorted(
                            str(row.get("id") or "")
                            for row in issues
                            if f"P{row.get('priority')}/{row.get('status')}" == cell
                        )
                    ),
                }
            )
            for cell, count in sorted(cells.items())
            if count == 0
        ]
        checks.check(
            "released-br-all-state-coverage",
            set(statuses) == set(STATUS_SCOPES)
            and set(priorities) == set(range(5))
            and any(str(row.get("assignee") or "") for row in issues)
            and any(not str(row.get("assignee") or "") for row in issues),
            expected={
                "statuses": list(STATUS_SCOPES),
                "priorities": list(range(5)),
                "assigned_and_ownerless": True,
            },
            observed={
                "statuses": dict(statuses),
                "priorities": {
                    f"P{priority}": priorities[priority]
                    for priority in sorted(priorities)
                },
                "assigned": sum(bool(row.get("assignee")) for row in issues),
            },
        )
        checks.check(
            "robot-deferred-accounting",
            bv_projection["issue_count"]
            == len(issues) - statuses["deferred"]
            and bv_projection["robot_mode"] == "--robot-triage",
            expected=len(issues) - statuses["deferred"],
            observed=bv_projection["issue_count"],
        )
        checks.check(
            "legacy-exact-25-cells-and-zero-receipts",
            len(cells) == 25
            and all(
                receipt["count"] == 0
                and receipt["issue_ids_root"] == semantic_root([])
                for receipt in zero_receipts
            ),
            expected={"cells": 25, "zero_receipts_root_bound": True},
            observed={
                "cells": len(cells),
                "zero_receipts": len(zero_receipts),
            },
        )
        live_nonclosed_ids = sorted(
            str(row.get("id") or "")
            for row in issues
            if not v2_is_terminal_status(row.get("status"))
        )
        inventoried_nonclosed_ids = sorted(
            row["id"]
            for row in production_inventory["rows"]
            if not v2_is_terminal_status(row["status"])
        )
        checks.check(
            "production-v2-exact-covers-complete-nonclosed-universe",
            live_nonclosed_ids == inventoried_nonclosed_ids
            and snapshot.inventory["review_scope"]["nonclosed_complete"]
            is True
            and snapshot.inventory["counts"][
                "complete_review_scope_issues"
            ]
            == len(snapshot.inventory["rows"])
            and all(
                row["semantic_review_disposition"]
                in V2_SEMANTIC_REVIEW_DISPOSITIONS
                for row in production_inventory["rows"]
            ),
            expected={
                "nonclosed_ids_root": semantic_root(live_nonclosed_ids),
                "complete": True,
            },
            observed={
                "nonclosed_ids_root": semantic_root(
                    inventoried_nonclosed_ids
                ),
                "live_count": len(live_nonclosed_ids),
                "inventory_count": len(inventoried_nonclosed_ids),
                "selected_review_count": len(production_inventory["rows"]),
            },
        )
        checks.check(
            "production-zero-validator-and-command-evidence",
            len(production_zero["cells"])
            == 5 * len(production_zero["status_scopes"])
            and production_zero["status_scopes_root"]
            == semantic_root(production_zero["status_scopes"])
            and production_zero["counts"]["issues"]
            == len(production_inventory["rows"])
            and bool(_command_receipts)
            and all(
                isinstance(receipt.get("argv"), list)
                and receipt.get("exit_code") == 0
                for receipt in _command_receipts
            ),
            expected={
                "cells": 5 * len(production_zero["status_scopes"]),
                "status_scopes": production_zero["status_scopes"],
                "targets": len(production_inventory["rows"]),
                "commands": "nonempty successful receipts",
            },
            observed={
                "cells": len(production_zero["cells"]),
                "targets": production_zero["counts"]["issues"],
                "command_count": len(_command_receipts),
                "command_receipts_root": semantic_root(_command_receipts),
            },
        )

    elif slug == "nomock-audit-known-legacy-conflict":
        evidence = v2_nomock_history_evidence(manifest)
        checks.check(
            "released-known-and-legacy",
            evidence["known_pair"]
            == [
                manifest["history_contract"][
                    "legacy_coverage_anchor_status_event_id"
                ],
                manifest["history_contract"][
                    "legacy_coverage_anchor_close_event_id"
                ],
            ]
            and evidence["legacy_count"]
            == manifest["history_contract"]["legacy_coverage_count"],
            expected="pinned known pair and legacy receipt",
            observed=evidence,
        )
        conflicting = {
            "issue_id": "fixture-conflict",
            "events": [
                {
                    "id": 3,
                    "event_type": "closed",
                    "actor": "other",
                    "timestamp": "2026-01-02T00:00:00.002000+00:00",
                    "comment": "Other fixture close.",
                },
                {
                    "id": 2,
                    "event_type": "closed",
                    "actor": "first",
                    "timestamp": "2026-01-02T00:00:00.001000+00:00",
                    "comment": "First fixture close.",
                },
                {
                    "id": 1,
                    "event_type": "status_changed",
                    "actor": "first",
                    "timestamp": "2026-01-02T00:00:00+00:00",
                    "old_value": "open",
                    "new_value": "closed",
                },
            ],
        }
        normalized = v2_normalize_audit_document(
            conflicting,
            issue_id="fixture-conflict",
        )
        checks.check(
            "conflicting-close-state-retained",
            sum(
                event["event_type"] == "closed"
                for event in normalized["events"]
            )
            == 2,
            expected=2,
            observed=normalized["events"],
        )

    elif slug == "nomock-current-br-two-gate-nodata":
        context = fixture_br_context()
        fixture_root = resolve_safe(
            str(FIXTURE_BR_ROOT_REL),
            label="no-mock baseline fixture root",
            must_exist=True,
        )
        stable_issue = fixture_br_show(context["stable_id"])
        regression_issue = fixture_br_show(context["regression_id"])
        ready_ids = v2_ready_issue_ids(
            fixture_br_json("ready", "--limit", "0"),
            label="no-mock fixture ready membership",
        )
        fixture_rows = fixture_br_list()
        db_exportable_ids = sorted(
            str(row.get("id") or "")
            for row in fixture_rows
            if row.get("ephemeral") is not True
            and "-wisp-" not in str(row.get("id") or "")
        )
        exported_ids = sorted(
            str(row.get("id") or "")
            for row in fixture_br_export_list()
        )
        normalized_witness = v2_normalize_br_export_witness(
            fixture_br_json("sync", "--witness"),
            input_kind="released_live",
            workspace_root=fixture_root,
            expected_chunk_size_lines=(
                V2_BR_WITNESS_CAPTURE_CHUNK_SIZE_LINES
            ),
            expected_max_parallelism=(
                V2_BR_WITNESS_CAPTURE_MAX_PARALLELISM
            ),
            error_type=EvidenceFailed,
        )
        witness_body = normalized_witness["witness"]
        canonical_witness_root = v2_br_witness_root(
            schema_version=witness_body["schema_version"],
            chunk_size_lines=witness_body["chunk_size_lines"],
            line_count=witness_body["line_count"],
            byte_count=witness_body["byte_count"],
            chunks=witness_body["chunks"],
        )
        stable_description_root = text_root(FIXTURE_BR_STABLE_DESCRIPTION)
        observed_stable_description_root = text_root(
            str(stable_issue.get("description") or "")
        )
        stable_ready = context["stable_id"] in ready_ids
        stable_non_actionable_reasons = v2_non_actionable_reasons(
            stable_issue,
            tracker_ready=stable_ready,
        )
        checks.check(
            "released-fixture-actionable-export-baseline",
            stable_issue.get("id") == context["stable_id"]
            and stable_issue.get("title") == FIXTURE_BR_STABLE_TITLE
            and stable_issue.get("description")
            == FIXTURE_BR_STABLE_DESCRIPTION
            and observed_stable_description_root
            == stable_description_root
            and stable_issue.get("status") == "open"
            and stable_issue.get("ephemeral") is not True
            and stable_issue.get("pinned") is not True
            and stable_issue.get("is_template") is not True
            and not str(stable_issue.get("defer_until") or "")
            and stable_ready
            and stable_non_actionable_reasons == []
            and regression_issue.get("id") == context["regression_id"]
            and regression_issue.get("status") == "closed"
            and regression_issue.get("close_reason")
            == FIXTURE_BR_REGRESSION_CLOSE_REASON
            and regression_issue.get("ephemeral") is True
            and db_exportable_ids == [context["stable_id"]]
            and exported_ids == [context["stable_id"]]
            and witness_body["line_count"] == 1
            and witness_body["root_hash"] == canonical_witness_root,
            expected={
                "stable_id": context["stable_id"],
                "stable_status": "open",
                "stable_description_root": stable_description_root,
                "stable_ready": True,
                "stable_non_actionable_reasons": [],
                "stable_flags": {
                    "ephemeral": False,
                    "pinned": False,
                    "is_template": False,
                    "deferred": False,
                },
                "regression_id": context["regression_id"],
                "regression_status": "closed",
                "regression_close_reason": (
                    FIXTURE_BR_REGRESSION_CLOSE_REASON
                ),
                "regression_ephemeral": True,
                "db_exportable_ids": [context["stable_id"]],
