        )
        before_summary = v2_live_fixture_plan_summary(before_run)

        def observe_unrelated_drift(
            baseline: Mapping[str, Any],
        ) -> dict[str, Any]:
            regression_before = v2_fixture_show_projection_by_id(
                baseline
            )[regression_id]
            fixture_br_set_description(
                regression_id,
                regression_before["description"]
                + "\n\nUnrelated coherent drift fixture.",
            )
            fixture_br_json("sync", "--flush-only")
            during_run = v2_run_live_fixture_plan(
                manifest,
                context,
                mode="review-plan",
                label="unrelated-drift-during",
                target_ids=[stable_id],
                replay=False,
            )
            during_summary = v2_live_fixture_plan_summary(during_run)
            return {
                "observation_changed": during_summary["observation_root"]
                != before_summary["observation_root"],
                "source_changed": during_summary["source_root"]
                != before_summary["source_root"],
                "target_projection_stable": during_summary[
                    "inventory_target_roots"
                ]
                == before_summary["inventory_target_roots"],
                "decision_projection_stable": during_summary[
                    "decision_roots"
                ]
                == before_summary["decision_roots"],
                "child_membership_stable": during_summary[
                    "review_child_identifiers"
                ]
                == before_summary["review_child_identifiers"],
            }

        transaction = v2_run_fixture_mutation_transaction(
            context,
            label="unrelated-drift-stability",
            intents=((regression_id, "description"),),
            audit_event_budget_by_issue={regression_id: 4},
            body=observe_unrelated_drift,
        )
