        checks.check(
            "unrelated-observation-moves-selected-key-stable",
            during_summary["observation_changed"] is True
            and during_summary["source_changed"] is True
            and during_summary["target_projection_stable"] is True
            and during_summary["decision_projection_stable"] is True
            and during_summary["child_membership_stable"] is True,
            expected={
                "observation_changed": True,
                "source_changed": True,
                "target_roots_stable": True,
                "decision_roots_stable": True,
                "child_keys_stable": True,
            },
            observed={
                "observation_changed": during_summary[
                    "observation_changed"
                ],
                "source_changed": during_summary["source_changed"],
                "target_roots_stable": during_summary[
                    "target_projection_stable"
                ],
                "decision_roots_stable": during_summary[
                    "decision_projection_stable"
                ],
                "child_keys_stable": during_summary[
                    "child_membership_stable"
                ],
            },
        )
