    elif slug == "nomock-active-conflict-deferred":
        context = fixture_br_context()
        issue_id = context["stable_id"]

        def observe_active_conflict(
            _baseline: Mapping[str, Any],
        ) -> dict[str, Any]:
            fixture_br_set_status(issue_id, "in_progress")
            fixture_br_set_scalar_field(
                issue_id,
                "assignee",
                "fixture-active-worker",
            )
            fixture_br_json("sync", "--flush-only")
            before_plan = _v2_fixture_fingerprint_locked(context)
            run = v2_run_live_fixture_plan(
                manifest,
                context,
                mode="review-plan",
                label="active-conflict-during",
                target_ids=[issue_id],
                replay=True,
            )
            after_plan = _v2_fixture_fingerprint_locked(context)
            before_show = v2_fixture_show_projection_by_id(before_plan)[
                issue_id
            ]
            after_show = v2_fixture_show_projection_by_id(after_plan)[issue_id]
            return {
                "decision": run["authority"]["decisions"][0],
                "child": run["review_plan"]["children"][0],
                "planner_before_restorable_root": before_plan[
                    "restorable_state"
                ]["semantic_root"],
                "planner_after_restorable_root": after_plan[
                    "restorable_state"
                ]["semantic_root"],
                "planner_before_audit_root": before_plan["audit_root"],
                "planner_after_audit_root": after_plan["audit_root"],
                "planner_before_comments_root": semantic_root(
                    before_show["comments"]
                ),
                "planner_after_comments_root": semantic_root(
                    after_show["comments"]
                ),
                "command_receipt_count": len(run["command_receipts"]),
                "payload_count": len(run["payloads"]),
                "replay_terminal": run["replay_result"]["terminal"],
            }

        transaction = v2_run_fixture_mutation_transaction(
            context,
            label="active-conflict-deferred",
            intents=((issue_id, "status"), (issue_id, "assignee")),
            audit_event_budget_by_issue={issue_id: 8},
            body=observe_active_conflict,
        )
        observed = transaction["body_result"]
        decision = observed["decision"]
        child = observed["child"]
        checks.check(
            "active-conflict-defers-generated-child",
            decision["active_work_context"]["conflict"] is True
            and decision["active_work_context"]["status"] == "in_progress"
            and decision["active_work_context"]["tracker_assignee"]
            == "fixture-active-worker"
            and decision["remediation_route"] == "ANALYSIS_ONLY"
            and child["desired_status"] == "deferred"
            and observed["payload_count"] == len(V2_RUN_ARTIFACTS)
            and observed["command_receipt_count"] > 0
            and observed["replay_terminal"] == "Pass",
            expected={
                "conflict": True,
                "status": "in_progress",
                "assignee": "fixture-active-worker",
                "route": "ANALYSIS_ONLY",
                "child_status": "deferred",
                "replay": "Pass",
            },
            observed={
                "active_work_context": decision["active_work_context"],
                "route": decision["remediation_route"],
                "child_status": child["desired_status"],
                "payload_count": observed["payload_count"],
                "command_receipt_count": observed[
                    "command_receipt_count"
                ],
                "replay": observed["replay_terminal"],
            },
        )
        checks.check(
            "planner-does-not-mutate-active-target",
            observed["planner_before_restorable_root"]
            == observed["planner_after_restorable_root"]
            and observed["planner_before_audit_root"]
            == observed["planner_after_audit_root"]
            and observed["planner_before_comments_root"]
            == observed["planner_after_comments_root"]
            and transaction["restoration"]["converged"] is True
            and transaction["baseline_restorable_root"]
            == transaction["final_restorable_root"]
            and any(
                row["issue_id"] == issue_id
                and row["old_stream_preserved_as_suffix"] is True
                and row["after_count"] >= row["before_count"]
                for row in transaction["audit_delta"]["issues"]
            ),
            expected={
                "planner_state_unchanged": True,
                "planner_audit_unchanged": True,
                "planner_comments_unchanged": True,
                "transaction_restored": True,
            },
            observed={
                "planner_state_roots": [
                    observed["planner_before_restorable_root"],
                    observed["planner_after_restorable_root"],
                ],
                "planner_audit_roots": [
                    observed["planner_before_audit_root"],
                    observed["planner_after_audit_root"],
                ],
                "planner_comment_roots": [
                    observed["planner_before_comments_root"],
                    observed["planner_after_comments_root"],
                ],
                "transaction_roots": [
                    transaction["baseline_restorable_root"],
                    transaction["final_restorable_root"],
                ],
                "audit_delta": transaction["audit_delta"],
                "restoration_attempts": transaction["restoration"][
                    "attempts"
