        )

    elif slug == "nomock-oversize":
        context = fixture_br_context()
        issue_id = context["stable_id"]

        def observe_live_oversize(
            _baseline: Mapping[str, Any],
        ) -> dict[str, Any]:
            fixture_br_set_description(
                issue_id,
                "x" * (V2_CHILD_DESCRIPTION_CAP + 1),
            )
            fixture_br_json("sync", "--flush-only")
            run = v2_run_live_fixture_plan(
                manifest,
                context,
                mode="review-plan",
                label="released-oversize-live",
                target_ids=[issue_id],
                replay=True,
            )
            optional_documents = {
                name: strict_json_loads(
                    payload,
                    label=f"released oversize optional {name}",
                    require_canonical=True,
                )
                for name, payload in run["optional_payloads"].items()
            }
            registry = run["review_plan"]["oversize_content"]
            optional_names = sorted(optional_documents)
            registry_names = sorted(
                row["relative_path"] for row in registry
            )
            optional_document = (
                optional_documents[optional_names[0]]
                if len(optional_names) == 1
                else None
            )
            payload_is_canonical = (
                type(optional_document) is dict
                and run["optional_payloads"][optional_names[0]]
                == canonical_bytes(optional_document)
            )
            return {
                "registry_count": len(registry),
                "optional_membership_exact": optional_names
                == registry_names,
                "terminal_registry_exact": run["terminal"][
                    "optional_content_registry"
                ]
                == registry,
                "terminal_artifact_membership_exact": set(
                    run["terminal"]["safe_relative_artifacts"]
                )
                == set(V2_RUN_ARTIFACTS) | set(optional_names),
                "workflow": run["review_plan"]["children"][0][
                    "disposition_workflow"
                ],
                "bounded_index_complete": (
                    optional_document["bounded_incomplete_index"][
                        "complete"
                    ]
                    if type(optional_document) is dict
                    else None
                ),
                "document_root_matches_registry": (
                    type(optional_document) is dict
                    and len(registry) == 1
                    and optional_document["semantic_root"]
                    == registry[0]["semantic_root"]
                ),
                "payload_is_canonical": payload_is_canonical,
                "optional_registry_root": semantic_root(registry),
                "replay_terminal": run["replay_result"]["terminal"],
                "replay_roots_present": run["replay_roots"] is not None,
            }

        transaction = v2_run_fixture_mutation_transaction(
            context,
            label="released-oversize",
            intents=((issue_id, "description"),),
            audit_event_budget_by_issue={issue_id: 4},
            body=observe_live_oversize,
        )
        observed = transaction["body_result"]
        checks.check(
            "released-oversize-complete-registry",
            observed["registry_count"] == 1
            and observed["optional_membership_exact"] is True
            and observed["terminal_registry_exact"] is True
            and observed["terminal_artifact_membership_exact"] is True
            and observed["workflow"]
            == "OVERSIZE_REVIEW_REQUIRED"
            and observed["bounded_index_complete"] is False
            and observed["document_root_matches_registry"] is True
            and observed["payload_is_canonical"] is True
            and observed["replay_terminal"] == "Pass"
            and observed["replay_roots_present"] is True,
            expected={
                "registry_count": 1,
                "optional_membership_exact": True,
                "bounded_index_complete": False,
                "workflow": "OVERSIZE_REVIEW_REQUIRED",
                "replay": "Pass",
            },
            observed={
                "registry_count": observed["registry_count"],
                "optional_membership_exact": observed[
                    "optional_membership_exact"
                ],
                "terminal_registry_exact": observed[
                    "terminal_registry_exact"
                ],
                "terminal_artifact_membership_exact": observed[
                    "terminal_artifact_membership_exact"
                ],
                "bounded_index_complete": observed[
                    "bounded_index_complete"
                ],
                "document_root_matches_registry": observed[
                    "document_root_matches_registry"
                ],
                "payload_is_canonical": observed[
                    "payload_is_canonical"
                ],
                "optional_registry_root": observed[
                    "optional_registry_root"
                ],
                "child": observed["workflow"],
                "replay": observed["replay_terminal"],
            },
        )
        checks.check(
            "released-oversize-target-restored",
            transaction["restoration"]["converged"] is True
            and transaction["baseline_restorable_root"]
            == transaction["final_restorable_root"]
            and any(
                row["issue_id"] == issue_id
                and row["old_stream_preserved_as_suffix"] is True
                and row["after_count"] >= row["before_count"]
                for row in transaction["audit_delta"]["issues"]
            ),
            expected={
                "converged": True,
                "restorable_root": transaction[
                    "baseline_restorable_root"
                ],
                "audit_history": "prior stream preserved as suffix",
            },
            observed={
                "converged": transaction["restoration"]["converged"],
                "restorable_root": transaction["final_restorable_root"],
                "audit_delta": transaction["audit_delta"],
                "restoration_attempts": transaction["restoration"][
                    "attempts"
                ],
            },
        )

    elif slug == "nomock-offline-replay":
        context = fixture_br_context()
        live_inputs = {
            "review-plan": v2_run_live_fixture_plan(
                manifest,
                context,
                mode="review-plan",
                label="offline-input-review-live",
                target_ids=[context["stable_id"]],
                replay=False,
            ),
            "history-plan": v2_run_live_fixture_plan(
                manifest,
                context,
                mode="history-plan",
                label="offline-input-history-live",
                target_ids=[context["regression_id"]],
                replay=False,
            ),
        }
        before_receipts = len(_command_receipts)
        roots: dict[str, list[str]] = {}
        for subject_mode in ("review-plan", "history-plan"):
            live_run = live_inputs[subject_mode]
            artifact_root = live_run["artifact_root"]
            artifact_dir = live_run["artifact_dir"]
            accepted = live_run["accepted_manifest"]
            retained = (
                live_run["source"],
                live_run["inventory"],
                live_run["authority"],
                live_run["review_plan"],
                live_run["history"],
                live_run["zero_sets"],
                live_run["optional_payloads"],
            )
            persistent_binding = {
                "subject_mode": subject_mode,
                "retained_terminal_root": live_run["terminal"][
                    "semantic_root"
                ],
            }
            fixture_source_file_identities = [
                dict(row)
                for row in retained[0]["captured"]["observation"][
                    "source_files"
                ]
            ]
            retained_payloads = live_run["payloads"]
            retained_terminal = live_run["terminal"]
            retained_events = live_run["events"]
            reconstructed = v2_reconstruct_retained(
                artifact_root=artifact_root,
                input_dir=artifact_dir,
                payloads=retained_payloads,
                terminal=retained_terminal,
                events=retained_events,
                accepted_manifest=accepted,
                current_source_files=fixture_source_file_identities,
            )
            roots[subject_mode] = [
                row["semantic_root"] for row in reconstructed[:6]
            ]
            checks.check(
                f"{subject_mode}-filesystem-read-reconstruct-exact",
                roots[subject_mode]
                == [row["semantic_root"] for row in retained[:6]],
                expected=[row["semantic_root"] for row in retained[:6]],
                observed=roots[subject_mode],
            )
            checks.check(
                f"{subject_mode}-terminal-content-last-and-complete",
                retained_terminal["bundle_state"] == "COMPLETE_GREEN"
                and retained_terminal["terminal"] == "Pass"
                and retained_terminal["complete_evidence_bundle"] is True
                and retained_terminal["complete_green_prefix"] is True
                and retained_events[-1]["terminal"] == "Pass",
                expected=("COMPLETE_GREEN", "Pass"),
                observed=(
                    retained_terminal["bundle_state"],
                    retained_terminal["terminal"],
                ),
            )
            if subject_mode == "review-plan":
                replay_root, replay_dir = v2_fresh_nomock_artifact_location(
                    accepted,
                    label="offline-review-disjoint-replay",
                    identity_binding=persistent_binding,
                )
                if replay_root != artifact_root:
                    raise EvidenceFailed(
                        "offline review replay escaped its live artifact root"
                    )
                replay_path = resolve_run_dir(
                    artifact_root,
                    replay_dir,
                    label="persistent replay fixture",
                )
                replay_result = v2_replay_bundle(
                    artifact_root=artifact_root,
                    input_dir=artifact_dir,
                    output_dir=replay_dir,
                    accepted_manifest=accepted,
                )
                if replay_result["terminal"] != "Pass":
                    raise EvidenceFailed(
                        "filesystem replay did not return Pass"
                    )
                (
                    _,
                    replay_payloads,
                    replay_terminal,
                    replay_events,
                ) = v2_read_retained_bundle(
                    artifact_root=artifact_root,
                    input_dir=replay_dir,
                )
                replay_reconstructed = v2_reconstruct_retained(
                    artifact_root=artifact_root,
                    input_dir=replay_dir,
                    payloads=replay_payloads,
                    terminal=replay_terminal,
                    events=replay_events,
                    accepted_manifest=accepted,
                    current_source_files=fixture_source_file_identities,
                )
                checks.check(
                    "review-plan-disjoint-filesystem-replay-exact",
                    [
                        row["semantic_root"]
                        for row in replay_reconstructed[:6]
                    ]
                    == roots[subject_mode]
                    and replay_terminal["mode"] == "replay"
                    and replay_terminal["replay_equivalence"][
                        "live_tracker_reads"
                    ]
                    is False
                    and replay_terminal["replay_equivalence"][
                        "live_tracker_writes"
                    ]
                    is False
                    and replay_path
                    != resolve_run_dir(
                        artifact_root,
                        artifact_dir,
                        label="persistent replay source",
                        must_exist=True,
                    ),
                    expected=roots[subject_mode],
                    observed=[
                        row["semantic_root"]
                        for row in replay_reconstructed[:6]
                    ],
                )

                def replay_subprocess_document(
                    completed: subprocess.CompletedProcess[str],
                    *,
                    label: str,
                ) -> dict[str, Any]:
                    document = strict_json_loads(
                        completed.stdout.encode("utf-8"),
                        label=label,
                        require_canonical=True,
                    )
                    if not isinstance(document, dict):
                        raise EvidenceFailed(
                            f"{label} did not emit one JSON object"
                        )
                    return document

                try:
                    replay_subprocess_nonce = os.urandom(32).hex()
                except OSError as error:
                    raise InfrastructureFailed(
                        "explicit replay subprocess nonce could not be generated"
                    ) from error
                offline_root, offline_dir = v2_fresh_nomock_artifact_location(
                    manifest,
                    label="offline-replay-command-path",
                    identity_binding={"nonce": replay_subprocess_nonce},
                )
                offline_directory = resolve_run_dir(
                    offline_root,
                    offline_dir,
                    label="offline replay command path fixture",
                )
                offline_bin = offline_directory / "bin"
                offline_bin.mkdir(parents=True, exist_ok=False)

                def shell_quote(value: str) -> str:
                    return "'" + value.replace("'", "'\"'\"'") + "'"

                dirname_binary = next(
                    (
                        candidate
                        for candidate in ("/usr/bin/dirname", "/bin/dirname")
                        if os.access(candidate, os.X_OK)
                    ),
                    None,
                )
                if dirname_binary is None:
                    raise InfrastructureFailed(
                        "offline replay command path lacks dirname"
                    )
                for command_name, executable in (
                    ("bash", "/bin/bash"),
                    ("python3", sys.executable),
                    ("dirname", dirname_binary),
                ):
                    launcher = offline_bin / command_name
                    write_once(
                        launcher,
                        (
                            "#!/bin/sh\nexec "
                            + shell_quote(str(executable))
                            + " \"$@\"\n"
                        ).encode("utf-8"),
                    )
                    os.chmod(launcher, 0o755)
                offline_path = str(offline_bin)
                tracker_cli_visible = os.access(
                    offline_bin / "br",
                    os.X_OK,
                )
                offline_environment = {"PATH": offline_path}

                explicit_root, explicit_dir = v2_fresh_nomock_artifact_location(
                    accepted,
                    label="explicit-replay-v2-subprocess",
                    identity_binding={
                        "retained_terminal_root": retained_terminal[
                            "semantic_root"
                        ],
                        "nonce": replay_subprocess_nonce,
                    },
                )
                if explicit_root != artifact_root:
                    raise EvidenceFailed(
                        "explicit replay subprocess escaped its artifact root"
                    )
                explicit_completed = run_command(
                    (
                        str(REPO_ROOT / SCRIPT_REL),
                        "--replay-v2",
                        artifact_dir,
                        "--artifact-root",
                        artifact_root,
                        "--artifact-dir",
                        explicit_dir,
                    ),
                    environment_overrides=offline_environment,
                    record_global_receipt=False,
                )
                explicit_result = replay_subprocess_document(
                    explicit_completed,
                    label="explicit replay-v2 stdout",
                )
                (
                    _,
                    explicit_payloads,
                    explicit_terminal,
                    explicit_events,
                ) = v2_read_retained_bundle(
                    artifact_root=artifact_root,
                    input_dir=explicit_dir,
                )
                v2_validate_replay_result_document(
                    explicit_result,
                    published_terminal=explicit_terminal,
                )
                explicit_reconstructed = v2_reconstruct_retained(
                    artifact_root=artifact_root,
                    input_dir=explicit_dir,
                    payloads=explicit_payloads,
                    terminal=explicit_terminal,
                    events=explicit_events,
                    accepted_manifest=accepted,
                    current_source_files=fixture_source_file_identities,
                )
                checks.check(
                    "explicit-replay-v2-subprocess-success-rooted",
                    explicit_completed.returncode == 0
                    and explicit_completed.stderr == ""
                    and explicit_result["schema"]
                    == V2_REPLAY_RESULT_SCHEMA
                    and explicit_result["terminal"] == "Pass"
                    and explicit_result["retained_terminal_root"]
                    == retained_terminal["semantic_root"]
                    and explicit_result["replay_terminal_root"]
                    == explicit_terminal["semantic_root"]
                    and [
                        row["semantic_root"]
                        for row in explicit_reconstructed[:6]
                    ]
                    == roots[subject_mode],
                    expected={
                        "exit_code": 0,
                        "schema": V2_REPLAY_RESULT_SCHEMA,
                        "terminal": "Pass",
                        "retained_terminal_root": retained_terminal[
                            "semantic_root"
                        ],
                        "projection_roots": roots[subject_mode],
                    },
                    observed={
                        "exit_code": explicit_completed.returncode,
                        "stderr_root": text_root(explicit_completed.stderr),
                        "result": explicit_result,
                        "projection_roots": [
                            row["semantic_root"]
                            for row in explicit_reconstructed[:6]
                        ],
                    },
                )

                wrong_v1_root, wrong_v1_input = (
                    v2_fresh_nomock_artifact_location(
                        manifest,
                        label="explicit-replay-v1-probe",
                        identity_binding={
                            "nonce": replay_subprocess_nonce,
                            "schema": RUN_TERMINAL_SCHEMA,
                        },
                    )
                )
                wrong_v1_directory = resolve_run_dir(
                    wrong_v1_root,
                    wrong_v1_input,
                    label="explicit replay v1 schema probe",
                )
                wrong_v1_directory.mkdir(parents=True, exist_ok=False)
                write_once(
                    wrong_v1_directory / "terminal.json",
                    canonical_bytes({"schema": RUN_TERMINAL_SCHEMA}),
                )
                wrong_v1_completed = run_command(
                    (
                        str(REPO_ROOT / SCRIPT_REL),
                        "--replay-v2",
                        wrong_v1_input,
                        "--artifact-root",
                        wrong_v1_root,
                        "--artifact-dir",
                        f"wrong-v1-output-{replay_subprocess_nonce[:16]}",
                    ),
                    expected=(TERMINAL_EXIT["InputRefused"],),
                    environment_overrides={
                        **offline_environment,
                        "FS_TEMPLATE_HYGIENE_FORBID_V2_LOAD": "1",
                    },
                    record_global_receipt=False,
                )
                wrong_v1_document = replay_subprocess_document(
                    wrong_v1_completed,
                    label="explicit replay-v2 wrong-v1 stdout",
                )
                v2_validate_preflight_terminal_document(wrong_v1_document)
                checks.check(
                    "explicit-replay-v2-wrong-v1-refused-pre-manifest",
                    wrong_v1_document["terminal"] == "InputRefused"
                    and wrong_v1_document["mode"] == "replay-v2"
                    and wrong_v1_document["schema"]
                    == V2_PREFLIGHT_TERMINAL_SCHEMA
                    and "manifest_root" not in wrong_v1_document
                    and "manifest loading was forbidden"
                    not in wrong_v1_document["diagnostic_summary"],
                    expected={
                        "schema": V2_PREFLIGHT_TERMINAL_SCHEMA,
                        "terminal": "InputRefused",
                        "mode": "replay-v2",
                        "manifest_loaded": False,
                    },
                    observed=wrong_v1_document,
                )

                auxiliary_completed = run_command(
                    (
                        str(REPO_ROOT / SCRIPT_REL),
                        "--replay-v2",
                        artifact_dir,
                        "--artifact-root",
                        artifact_root,
                        "--artifact-dir",
                        f"aux-refusal-{replay_subprocess_nonce[:16]}",
                        "--targets",
                        context["stable_id"],
                    ),
                    expected=(TERMINAL_EXIT["UsageRefused"],),
                    environment_overrides={
                        **offline_environment,
                        "FS_TEMPLATE_HYGIENE_FORBID_V2_LOAD": "1",
                    },
                    record_global_receipt=False,
                )
                auxiliary_document = replay_subprocess_document(
                    auxiliary_completed,
                    label="explicit replay-v2 auxiliary refusal stdout",
                )
                v2_validate_preflight_terminal_document(auxiliary_document)
                checks.check(
