        cancellation_epoch_before = _cancel_signal_epoch
        cancellation_requested_before = _cancel_requested
        synthetic_cancel_invoked = False

        def mutate_then_request_cancellation(
            _baseline: Mapping[str, Any],
        ) -> None:
            nonlocal synthetic_cancel_invoked
            fixture_br_set_scalar_field(
                context["stable_id"],
                "owner",
                cancellation_owner,
            )
            synthetic_cancel_invoked = True
            request_cancel(signal.SIGINT, None)

        cancellation_error: CancelledDrained | None = None
        concurrent_real_cancellation = False
        cancellation_state_error: BaseException | None = None
        cancellation_epoch_after_synthetic: int | None = None
        try:
            cancellation_error = expect_error(
                CancelledDrained,
                lambda: v2_run_fixture_mutation_transaction(
                    context,
                    label="cancelled-restoration-live",
                    intents=((context["stable_id"], "owner"),),
                    audit_event_budget_by_issue={
                        context["stable_id"]: (
                            V2_FIXTURE_AUDIT_EVENTS_PER_INTENT_HEADROOM
                        )
                    },
                    body=mutate_then_request_cancellation,
                ),
            )
        finally:
            observed_cancel_epoch = _cancel_signal_epoch
            expected_cancel_epoch = (
                cancellation_epoch_before + 1
                if synthetic_cancel_invoked
                else cancellation_epoch_before
            )
            if observed_cancel_epoch < expected_cancel_epoch:
                cancellation_state_error = EvidenceFailed(
                    "fixture cancellation epoch moved backward"
                )
            elif observed_cancel_epoch == expected_cancel_epoch:
                _cancel_requested = cancellation_requested_before
                if _cancel_signal_epoch != observed_cancel_epoch:
                    _cancel_requested = True
                    concurrent_real_cancellation = True
                else:
                    cancellation_epoch_after_synthetic = (
                        observed_cancel_epoch
                    )
            else:
                _cancel_requested = True
                concurrent_real_cancellation = True
        if cancellation_state_error is not None:
            raise cancellation_state_error
        if concurrent_real_cancellation:
            raise CancelledDrained(
                "additional cancellation arrived during the synthetic "
                "fixture cancellation probe; fixture cleanup drained"
            ) from cancellation_error
        if cancellation_error is None:
            raise EvidenceFailed(
                "cancelled fixture transaction produced no terminal evidence"
            )
        cancellation_after = v2_fixture_fingerprint(context)
        cancellation_audit_delta = v2_fixture_audit_delta(
            cancellation_baseline,
            cancellation_after,
            mutated_issue_ids=frozenset({context["stable_id"]}),
        )
        cancellation_budget = {
            context["stable_id"]: (
                V2_FIXTURE_AUDIT_EVENTS_PER_INTENT_HEADROOM
            )
        }
        v2_validate_fixture_audit_event_budgets(
            cancellation_audit_delta,
            cancellation_budget,
        )
        cancellation_notes = list(
            getattr(cancellation_error, "__notes__", ())
        )
        cancellation_failure_projection = (
            v2_build_test_failure_projection(
                error=cancellation_error,
                note_source=cancellation_error,
                diagnostic_code=(
                    "CancelledDrained:fixture-cancelled-restoration-drains"
                ),
                unexpected_exception_type=None,
                subject=(
                    "live fixture cancellation restores and drains before "
                    "surfacing the typed terminal"
                ),
                check_obligation_root=semantic_root(
                    "fixture-cancelled-restoration-drains"
                ),
                harness_contract_identity=manifest[
                    "harness_contract_identity"
                ],
            )
        )
        v2_validate_exception_note_projection(
            cancellation_failure_projection["exception_notes"]
        )
        cancellation_restoration = {
            "passed": cancellation_error.terminal == "CancelledDrained"
            and cancellation_epoch_after_synthetic
            == cancellation_epoch_before + 1
            and _cancel_requested is cancellation_requested_before
            and cancellation_after["restorable_state"]["semantic_root"]
            == cancellation_baseline["restorable_state"]["semantic_root"]
            and any(
                "fixture restoration report root" in note
                for note in cancellation_notes
            )
            and any(
                "fixture restoration verification" in note
                for note in cancellation_notes
            )
            and cancellation_failure_projection["exception_notes"][
                "state"
            ]
            == "RETAINED"
            and cancellation_failure_projection["exception_notes"][
                "count"
            ]
            == len(cancellation_notes),
            "terminal": cancellation_error.terminal,
            "cancel_epoch_before": cancellation_epoch_before,
            "cancel_epoch_after": cancellation_epoch_after_synthetic,
            "cancel_requested_restored": (
                _cancel_requested is cancellation_requested_before
            ),
            "baseline_restorable_root": cancellation_baseline[
                "restorable_state"
            ]["semantic_root"],
            "final_restorable_root": cancellation_after[
                "restorable_state"
            ]["semantic_root"],
            "audit_budget": cancellation_budget,
            "audit_delta_root": cancellation_audit_delta[
