            "note_count": len(cancellation_notes),
            "note_roots": [
                text_root(note) for note in cancellation_notes
            ],
            "serialized_failure_root": semantic_root(
                cancellation_failure_projection
            ),
            "serialized_exception_notes_root": (
                cancellation_failure_projection["exception_notes"][
                    "semantic_root"
                ]
            ),
