        interrupted_lock_descriptor: int | None = None
        lock_handoff_interrupted = False
        lock_target_open_returned = False
        lock_target_open_descriptor: int | None = None
        lock_pre_owner_window_observed = False
        lock_handoff_close_calls: list[int] = []
        original_lock_handoff_open = os.open
        original_lock_handoff_close = os.close

        def observe_lock_handoff_open(
            path: Any,
            *args: Any,
            **kwargs: Any,
        ) -> int:
            nonlocal lock_target_open_returned
            nonlocal lock_target_open_descriptor
            descriptor = original_lock_handoff_open(path, *args, **kwargs)
            if path == FIXTURE_BR_LOCK_REL.name:
                lock_target_open_returned = True
                lock_target_open_descriptor = descriptor
            return descriptor

        def observe_lock_handoff_close(descriptor: int) -> None:
            original_lock_handoff_close(descriptor)
            list.append(lock_handoff_close_calls, descriptor)

        def interrupt_lock_owner_delivery(
            frame: Any,
            event: str,
            _argument: Any,
        ) -> Any:
            nonlocal interrupted_lock_descriptor
            nonlocal lock_pre_owner_window_observed
            if (
                event == "line"
                and frame.f_code
                is _fixture_br_open_lock_descriptor.__code__
                and lock_target_open_returned
            ):
                candidate_owner = frame.f_locals.get("descriptor_owner")
                if (
                    type(candidate_owner)
                    is not FixtureBrDescriptorOwner
                    or candidate_owner._descriptor is None
                ):
                    lock_pre_owner_window_observed = True
                    raise KeyboardInterrupt(
                        "synthetic pre-owner lock interruption"
                    )
            if (
                interrupted_lock_descriptor is None
                and event == "line"
                and frame.f_code
                is _fixture_br_open_lock_descriptor.__code__
                and frame.f_locals.get("owner_returned") is True
            ):
                owner = frame.f_locals.get("descriptor_owner")
                if type(owner) is FixtureBrDescriptorOwner:
                    interrupted_lock_descriptor = owner.descriptor
                    raise KeyboardInterrupt(
                        "synthetic lock-owner delivery interruption"
                    )
            return interrupt_lock_owner_delivery

        prior_lock_handoff_trace = sys.gettrace()
        lock_handoff_target_slot: list[FixtureBrDescriptorOwner | None] = [
            None
        ]
        lock_handoff_parent_slot: list[FixtureBrDescriptorOwner | None] = [
            None
        ]
        os.open = observe_lock_handoff_open
        os.close = observe_lock_handoff_close
        sys.settrace(interrupt_lock_owner_delivery)
        try:
            try:
                _fixture_br_open_lock_descriptor(
                    descriptor_owner_slot=lock_handoff_target_slot,
                    parent_owner_slot=lock_handoff_parent_slot,
                )
            except KeyboardInterrupt:
                lock_handoff_interrupted = True
            else:
                unexpected_lock_owner = list.__getitem__(
                    lock_handoff_target_slot,
                    0,
                )
                if type(unexpected_lock_owner) is FixtureBrDescriptorOwner:
                    unexpected_lock_owner.close()
        finally:
            sys.settrace(prior_lock_handoff_trace)
            os.open = original_lock_handoff_open
            os.close = original_lock_handoff_close
            if (
                lock_pre_owner_window_observed
                and lock_target_open_descriptor is not None
                and lock_target_open_descriptor
                not in lock_handoff_close_calls
            ):
                try:
                    original_lock_handoff_close(
                        lock_target_open_descriptor
                    )
                except OSError:
                    pass
        lock_handoff_owner = list.__getitem__(
            lock_handoff_target_slot,
            0,
        )
        lock_handoff_owner_relinquished = (
            type(lock_handoff_owner) is FixtureBrDescriptorOwner
            and lock_handoff_owner._descriptor is None
        )
        lock_handoff_descriptor_closed = (
            interrupted_lock_descriptor is not None
            and lock_handoff_close_calls.count(interrupted_lock_descriptor)
            == 1
        )
        lock_handoff_test_cleanup_performed = False
        for owner_slot in (
            lock_handoff_target_slot,
            lock_handoff_parent_slot,
        ):
            pending_owner = list.__getitem__(owner_slot, 0)
            if (
                type(pending_owner) is FixtureBrDescriptorOwner
                and pending_owner._descriptor is not None
            ):
                lock_handoff_test_cleanup_performed = True
                pending_owner.close()
        parent_close_failure_injected = False
        parent_close_failure_parent: int | None = None
        parent_close_failure_target: int | None = None
        parent_close_failure_target_closes: list[int] = []
        lock_parent_path = resolve_safe(
            str(FIXTURE_BR_LOCK_REL.parent),
            label="no-mock fixture lock parent fault probe",
        )

        def observe_parent_close_failure_open(
            path: Any,
            *args: Any,
            **kwargs: Any,
        ) -> int:
            nonlocal parent_close_failure_parent
            nonlocal parent_close_failure_target
            descriptor = original_lock_handoff_open(path, *args, **kwargs)
            if path == lock_parent_path:
                parent_close_failure_parent = descriptor
            elif path == FIXTURE_BR_LOCK_REL.name:
                parent_close_failure_target = descriptor
            return descriptor

        def inject_parent_close_failure(descriptor: int) -> None:
            nonlocal parent_close_failure_injected
            original_lock_handoff_close(descriptor)
            if (
                descriptor == parent_close_failure_parent
                and not parent_close_failure_injected
            ):
                parent_close_failure_injected = True
                raise OSError(
                    errno.EIO,
                    "synthetic fixture lock parent close failure",
                )
            if descriptor == parent_close_failure_target:
                list.append(
                    parent_close_failure_target_closes,
                    descriptor,
                )

        os.open = observe_parent_close_failure_open
        os.close = inject_parent_close_failure
        parent_failure_target_slot: list[
            FixtureBrDescriptorOwner | None
        ] = [None]
        parent_failure_parent_slot: list[
            FixtureBrDescriptorOwner | None
        ] = [None]
        parent_close_failure_target_owner_relinquished = False
        parent_close_failure_parent_owner_relinquished = False
        parent_close_failure_test_cleanup_performed = False
        try:
            parent_close_failure_error = expect_error(
                InfrastructureFailed,
                lambda: _fixture_br_open_lock_descriptor(
                    descriptor_owner_slot=parent_failure_target_slot,
                    parent_owner_slot=parent_failure_parent_slot,
                ),
                contains="parent descriptor close failed",
            )
            parent_failure_target_owner = list.__getitem__(
                parent_failure_target_slot,
                0,
            )
            parent_failure_parent_owner = list.__getitem__(
                parent_failure_parent_slot,
                0,
            )
            parent_close_failure_target_owner_relinquished = (
                type(parent_failure_target_owner)
                is FixtureBrDescriptorOwner
                and parent_failure_target_owner._descriptor is None
            )
            parent_close_failure_parent_owner_relinquished = (
                type(parent_failure_parent_owner)
                is FixtureBrDescriptorOwner
                and parent_failure_parent_owner._descriptor is None
            )
        finally:
            os.open = original_lock_handoff_open
            os.close = original_lock_handoff_close
            for owner_slot in (
                parent_failure_target_slot,
                parent_failure_parent_slot,
            ):
                pending_owner = list.__getitem__(owner_slot, 0)
                if (
                    type(pending_owner) is FixtureBrDescriptorOwner
                    and pending_owner._descriptor is not None
                ):
                    parent_close_failure_test_cleanup_performed = True
                    pending_owner.close()
        parent_close_failure_target_closed_once = (
            parent_close_failure_target is not None
            and parent_close_failure_target_closes.count(
                parent_close_failure_target
            )
            == 1
        )
        transaction_serialization_observed = lease_lifecycle_probe[
