),)


def v2_exception_note_projection(error: BaseException) -> dict[str, Any]:
    raw_notes_unavailable = object()
    raw_notes_absent = object()
    try:
        raw_attributes = v2_raw_instance_dictionary(error)
    except EvidenceFailed:
        raw_attributes = None
        raw_notes: Any = raw_notes_unavailable
    else:
        if raw_attributes is None:
            raw_notes = raw_notes_absent
        else:
            raw_attribute_count = dict.__len__(raw_attributes)
            raw_attribute_snapshot_unavailable = (
                raw_attribute_count > V2_EXCEPTION_METADATA_ATTRIBUTES_CAP
            )
            raw_attribute_items: list[tuple[Any, Any]] = []
            if not raw_attribute_snapshot_unavailable:
                try:
                    raw_attribute_items = list(
                        dict.items(raw_attributes)
                    )
                except RuntimeError:
                    raw_attribute_snapshot_unavailable = True
                if (
                    len(raw_attribute_items) != raw_attribute_count
                    or dict.__len__(raw_attributes) != raw_attribute_count
                ):
                    raw_attribute_snapshot_unavailable = True
            if (
                raw_attribute_snapshot_unavailable
                or any(
                    type(key) is not str
                    for key, _item in raw_attribute_items
                )
            ):
                raw_notes = raw_notes_unavailable
            else:
                raw_notes = next(
                    (
                        item
                        for key, item in raw_attribute_items
                        if key == "__notes__"
                    ),
                    raw_notes_absent,
                )
    if raw_notes is raw_notes_unavailable:
        state = "MALFORMED"
        count: int | None = None
        cap_reason: str | None = None
        ordered_roots: list[str] = []
    elif raw_notes is raw_notes_absent:
        state = "ABSENT"
        count = 0
        cap_reason = None
        ordered_roots = []
    elif type(raw_notes) is not list:
        state = "MALFORMED"
        count = None
        cap_reason = None
        ordered_roots = []
    else:
        declared_count = list.__len__(raw_notes)
        if declared_count > V2_EXCEPTION_NOTES_CAP:
            state = "CAP_EXCEEDED"
            count = declared_count
            cap_reason = "COUNT"
            ordered_roots = []
        else:
            snapshot_unstable = False
            try:
                note_snapshot = [
                    list.__getitem__(raw_notes, index)
                    for index in range(declared_count)
                ]
            except (IndexError, RuntimeError):
                note_snapshot = []
                snapshot_unstable = True
            if list.__len__(raw_notes) != declared_count:
                snapshot_unstable = True
            first_snapshot_exact = (
                not snapshot_unstable
                and all(type(note) is str for note in note_snapshot)
            )
            first_snapshot_note_text_cap_exceeded = (
                first_snapshot_exact
                and any(
                    len(note) > V2_EXCEPTION_NOTE_BYTES_CAP
                    for note in note_snapshot
                )
            )
            if (
                first_snapshot_exact
                and not first_snapshot_note_text_cap_exceeded
            ):
                try:
                    verification_snapshot = [
                        list.__getitem__(raw_notes, index)
                        for index in range(declared_count)
                    ]
                except (IndexError, RuntimeError):
                    verification_snapshot = []
                    snapshot_unstable = True
                if (
                    list.__len__(raw_notes) != declared_count
                    or any(
                        type(note) is not str
                        or len(note) > V2_EXCEPTION_NOTE_BYTES_CAP
                        for note in verification_snapshot
                    )
                    or note_snapshot != verification_snapshot
                ):
                    snapshot_unstable = True
            if snapshot_unstable:
                state = "MALFORMED"
                count = None
                cap_reason = None
                ordered_roots = []
            elif any(type(note) is not str for note in note_snapshot):
                state = "MALFORMED"
                count = declared_count
                cap_reason = None
                ordered_roots = []
            elif first_snapshot_note_text_cap_exceeded:
                state = "CAP_EXCEEDED"
                count = declared_count
                cap_reason = "NOTE_TEXT_OR_UTF8_BYTES"
                ordered_roots = []
            else:
                state = "RETAINED"
                count = declared_count
                cap_reason = None
                ordered_roots = []
                total_utf8_bytes = 0
                for note in note_snapshot:
                    if len(note) > V2_EXCEPTION_NOTE_BYTES_CAP:
                        state = "CAP_EXCEEDED"
                        cap_reason = "NOTE_TEXT_OR_UTF8_BYTES"
                        ordered_roots = []
                        break
                    try:
                        encoded_note = str.encode(note, "utf-8")
                    except UnicodeEncodeError:
                        state = "MALFORMED"
                        ordered_roots = []
                        break
                    if len(encoded_note) > V2_EXCEPTION_NOTE_BYTES_CAP:
                        state = "CAP_EXCEEDED"
                        cap_reason = "NOTE_UTF8_BYTES"
                        ordered_roots = []
                        break
                    total_utf8_bytes += len(encoded_note)
                    if (
                        total_utf8_bytes
                        > V2_EXCEPTION_NOTES_TOTAL_BYTES_CAP
                    ):
                        state = "CAP_EXCEEDED"
                        cap_reason = "TOTAL_UTF8_BYTES"
                        ordered_roots = []
                        break
                    ordered_roots.append(
                        "sha256-v1:"
                        + hashlib.sha256(encoded_note).hexdigest()
                    )
    return v2_rooted(
        {
            "state": state,
            "count": count,
            "cap_reason": cap_reason,
            "ordered_roots": ordered_roots,
            "collection_root": semantic_root(
                {
                    "state": state,
                    "count": count,
                    "cap_reason": cap_reason,
                    "ordered_roots": ordered_roots,
                }
            ),
            "raw_bodies_retained": False,
        }
    )


def v2_validate_exception_note_projection(candidate: Any) -> None:
    if (
        type(candidate) is not dict
        or dict.__len__(candidate)
        != len(V2_EXCEPTION_NOTE_PROJECTION_FIELDS)
    ):
        raise EvidenceFailed(
            "v2 failure exception-note projection is malformed"
        )
    candidate_keys = list(dict.__iter__(candidate))
    if (
        any(type(key) is not str for key in candidate_keys)
        or set(candidate_keys) != V2_EXCEPTION_NOTE_PROJECTION_FIELDS
    ):
        raise EvidenceFailed(
            "v2 failure exception-note projection is malformed"
        )
    state = candidate["state"]
    count = candidate["count"]
    cap_reason = candidate["cap_reason"]
    roots = candidate["ordered_roots"]
    collection_root = candidate["collection_root"]
    semantic_identity = candidate["semantic_root"]
    if (
        type(state) is not str
        or len(state) > len("CAP_EXCEEDED")
        or state not in {"ABSENT", "RETAINED", "MALFORMED", "CAP_EXCEEDED"}
        or candidate["raw_bodies_retained"] is not False
        or type(roots) is not list
        or not v2_is_semantic_root(collection_root)
        or not v2_is_semantic_root(semantic_identity)
        or (
            state != "CAP_EXCEEDED"
            and cap_reason is not None
        )
        or (
            state == "CAP_EXCEEDED"
            and (
                type(cap_reason) is not str
                or len(cap_reason) > len("NOTE_TEXT_OR_UTF8_BYTES")
                or cap_reason not in {
                    "COUNT",
                    "NOTE_UTF8_BYTES",
                    "NOTE_TEXT_OR_UTF8_BYTES",
                    "TOTAL_UTF8_BYTES",
                }
            )
        )
    ):
        raise EvidenceFailed(
            "v2 failure exception-note projection is malformed"
        )
    roots_count = list.__len__(roots)
    if roots_count > V2_EXCEPTION_NOTES_CAP:
        raise EvidenceFailed(
            "v2 failure exception-note projection exceeds its root cap"
        )
    if (
        count is not None
        and (
            type(count) is not int
            or count < 0
            or count > sys.maxsize
        )
    ):
        raise EvidenceFailed(
            "v2 failure exception-note projection count is malformed"
        )
    if any(not v2_is_semantic_root(root) for root in roots):
        raise EvidenceFailed(
            "v2 failure exception-note projection root is malformed"
        )
    if (
        (
            state == "ABSENT"
            and (
                type(count) is not int
                or count != 0
                or roots_count != 0
            )
        )
        or (
            state == "RETAINED"
            and (
                type(count) is not int
                or count < 0
                or count > V2_EXCEPTION_NOTES_CAP
                or roots_count != count
            )
        )
        or (
            state == "MALFORMED"
            and (
                count is not None
                and (
                    type(count) is not int
                    or count <= 0
                    or count > V2_EXCEPTION_NOTES_CAP
                )
            )
        )
        or (state == "MALFORMED" and roots_count != 0)
        or (
            state == "CAP_EXCEEDED"
            and (
                type(count) is not int
                or count <= 0
                or roots_count != 0
                or (
                    cap_reason == "COUNT"
                    and count <= V2_EXCEPTION_NOTES_CAP
                )
                or (
                    cap_reason != "COUNT"
                    and count > V2_EXCEPTION_NOTES_CAP
                )
            )
        )
        or collection_root
        != semantic_root(
            {
                "state": state,
                "count": count,
                "cap_reason": cap_reason,
                "ordered_roots": roots,
            }
        )
    ):
        raise EvidenceFailed(
            "v2 failure exception-note projection is incoherent"
        )
    try:
        verify_semantic_root(
            candidate,
            label="v2 failure exception-note projection",
        )
    except (TypeError, ValueError, OverflowError, RecursionError) as error:
        raise EvidenceFailed(
            "v2 failure exception-note projection root is malformed"
        ) from error


def v2_normalize_runner_error(
    caught_error: BaseException,
    *,
    cancellation_message: str,
) -> tuple[HarnessError, str, bool]:
    exact_type = type(caught_error)
    if exact_type is KeyboardInterrupt:
        return (
            CancelledDrained(cancellation_message),
            "CancelledDrained",
            False,
        )
    terminal = (
        "InternalFault"
        if exact_type is HarnessError
        else "UsageRefused"
        if exact_type is UsageRefused
        else "InputRefused"
        if exact_type is InputRefused
        else "NoData"
        if exact_type is NoData
        else "EvidenceFailed"
        if exact_type is EvidenceFailed
        else "CancelledDrained"
        if exact_type is CancelledDrained
        else "InfrastructureFailed"
        if exact_type is InfrastructureFailed
        else None
    )
    if terminal is not None:
        return caught_error, terminal, False
    type_name = v2_exception_type_projection(exact_type)
    diagnostic = v2_bounded_diagnostic_summary(caught_error)
    type_prefix = f"{type_name}:"
    normalized_diagnostic = (
        diagnostic
        if diagnostic == type_prefix
        or diagnostic.startswith(type_prefix + " ")
        else f"{type_name}: {diagnostic}"
    )
    return (
        HarnessError(normalized_diagnostic),
        "InternalFault",
        True,
    )


def v2_runner_diagnostic(
    error: BaseException,
    *,
    note_source: BaseException | None = None,
    note_projection: Mapping[str, Any] | None = None,
) -> str:
    diagnostic = v2_bounded_diagnostic_summary(error)
    if not diagnostic.strip():
        type_name = v2_exception_type_projection(type(error))
        diagnostic = f"{type_name}: no exact diagnostic message"
    accepted_note_projection = (
        v2_exception_note_projection(
            error if note_source is None else note_source
        )
        if note_projection is None
        else note_projection
    )
    v2_validate_exception_note_projection(accepted_note_projection)
    note_state = accepted_note_projection["state"]
    note_count = accepted_note_projection["count"]
    note_cap_reason = accepted_note_projection["cap_reason"]
    if note_state == "RETAINED" and note_count:
        diagnostic += (
            "\nexception_note_count="
            f"{note_count} "
            "exception_notes_root="
            f"{accepted_note_projection['semantic_root']}"
        )
    elif note_state in {"CAP_EXCEEDED", "MALFORMED"}:
        count_projection = (
            f" exception_note_count={note_count}"
            if type(note_count) is int
            else ""
        )
        cap_projection = (
            f" exception_note_cap_reason={note_cap_reason}"
            if type(note_cap_reason) is str
            else ""
        )
        diagnostic += (
            "\nexception_notes_state="
            f"{note_state}"
            f"{count_projection}"
            f"{cap_projection} "
            "exception_notes_root="
            f"{accepted_note_projection['semantic_root']}"
        )
    return diagnostic


def v2_build_test_failure_projection(
    *,
    error: BaseException,
    note_source: BaseException,
    diagnostic_code: str,
    unexpected_exception_type: str | None,
    subject: str,
    check_obligation_root: str,
    harness_contract_identity: str,
    note_projection: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    if unexpected_exception_type is not None:
        v2_validate_exception_type_projection(
            unexpected_exception_type
        )
    accepted_note_projection = (
        v2_exception_note_projection(note_source)
        if note_projection is None
        else note_projection
    )
    v2_validate_exception_note_projection(accepted_note_projection)
    diagnostic = v2_runner_diagnostic(
        error,
        note_projection=accepted_note_projection,
    )
    return {
        "diagnostic_code": diagnostic_code,
        "diagnostic_root": text_root(diagnostic),
        "diagnostic_summary": v2_bounded_diagnostic_summary(diagnostic),
        "unexpected_exception_type": unexpected_exception_type,
        "subject": subject,
        "check_obligation_root": check_obligation_root,
        "harness_contract_identity": harness_contract_identity,
        "exception_notes": accepted_note_projection,
    }


def v2_validate_test_event_document(
    document: Mapping[str, Any],
    *,
    expected_harness_contract_identity: str,
    expected_case: Mapping[str, Any],
    expected_obligation: Mapping[str, Any],
    expected_sequence: int | None = None,
    expected_stage: str | None = None,
    expected_result_root: str | None = None,
    expected_result_check_count: int | None = None,
    expected_result_ordered_check_roots: Sequence[str] = (),
    expected_projection_root: str | None = None,
    expected_terminal: str | None = None,
    final: bool = False,
) -> Mapping[str, Any]:
    if type(document) is not dict:
        raise EvidenceFailed("v2 self-test event is not an object")
    try:
        document = v2_validate_exact_json_wire(
            document,
            label="v2 self-test event",
            item_cap=V2_ASSERTION_RESULT_EXACT_WIRE_ITEM_CAP,
            node_cap=V2_ASSERTION_RESULT_EXACT_WIRE_NODE_CAP,
            depth_cap=V2_ASSERTION_RESULT_EXACT_WIRE_DEPTH_CAP,
            byte_cap=V2_LOG_LINE_BYTES_CAP,
            snapshot_byte_cap=(
                V2_ASSERTION_RESULT_EXACT_WIRE_SNAPSHOT_BYTES_CAP
            ),
        )
        expected_case = v2_validate_exact_json_wire(
            expected_case,
            label="v2 self-test expected event case",
            item_cap=V2_ASSERTION_RESULT_EXACT_WIRE_ITEM_CAP,
            node_cap=V2_ASSERTION_RESULT_EXACT_WIRE_NODE_CAP,
            depth_cap=V2_ASSERTION_RESULT_EXACT_WIRE_DEPTH_CAP,
            byte_cap=V2_LOG_LINE_BYTES_CAP,
            snapshot_byte_cap=(
                V2_ASSERTION_RESULT_EXACT_WIRE_SNAPSHOT_BYTES_CAP
            ),
        )
        expected_obligation = v2_validate_exact_json_wire(
            expected_obligation,
            label="v2 self-test expected event obligation",
            item_cap=V2_ASSERTION_RESULT_EXACT_WIRE_ITEM_CAP,
            node_cap=V2_ASSERTION_RESULT_EXACT_WIRE_NODE_CAP,
            depth_cap=V2_ASSERTION_RESULT_EXACT_WIRE_DEPTH_CAP,
            byte_cap=V2_LOG_LINE_BYTES_CAP,
            snapshot_byte_cap=(
                V2_ASSERTION_RESULT_EXACT_WIRE_SNAPSHOT_BYTES_CAP
            ),
        )
    except InputRefused as error:
        raise EvidenceFailed(
            "v2 self-test event or expected context is outside its exact-wire "
            "resource contract"
        ) from error
    if type(expected_case) is not dict or type(expected_obligation) is not dict:
        raise EvidenceFailed(
            "v2 self-test event validation lacks exact expected context"
        )
    if (
        set(expected_case) != V2_CASE_FIELDS
        or type(expected_case["ordinal"]) is not int
        or expected_case["ordinal"] < 1
        or type(expected_case["id"]) is not str
        or re.fullmatch(
            r"template-lint-v2\.[a-z0-9]+(?:-[a-z0-9]+)*",
            expected_case["id"],
        )
        is None
        or type(expected_case["assertion_id"]) is not str
        or expected_case["assertion_id"]
        != "v2.case."
        + expected_case["id"][len("template-lint-v2.") :]
        or type(expected_case["fixture_engine"]) is not str
        or expected_case["fixture_engine"] not in V2_FIXTURE_ENGINES
        or type(expected_case["subject"]) is not str
        or type(expected_case["criterion_ids"]) is not list
        or not expected_case["criterion_ids"]
        or any(
            type(value) is not str
            for value in expected_case["criterion_ids"]
        )
        or len(expected_case["criterion_ids"])
        != len(set(expected_case["criterion_ids"]))
        or type(expected_case["kinds"]) is not list
        or not expected_case["kinds"]
        or any(
            type(value) is not str or value not in V2_CASE_KINDS
            for value in expected_case["kinds"]
        )
        or len(expected_case["kinds"])
        != len(set(expected_case["kinds"]))
    ):
        raise EvidenceFailed(
            "v2 self-test event expected case context is malformed"
        )
    v2_validate_check_obligation(
        expected_case,
        expected_obligation,
        error_type=EvidenceFailed,
    )
    if (
        type(expected_result_ordered_check_roots) is not list
        and type(expected_result_ordered_check_roots) is not tuple
    ):
        raise EvidenceFailed(
            "v2 self-test event expected result roots are not ordered"
        )
    expected_ordered_root_count = len(
        expected_result_ordered_check_roots
    )
    if (
        type(final) is not bool
        or type(expected_sequence) is not int
        or expected_sequence < 0
        or type(expected_stage) is not str
        or expected_stage not in {"assertion-start", "assertion-terminal"}
        or (
            expected_terminal is not None
            and (
                type(expected_terminal) is not str
                or expected_terminal not in TERMINAL_EXIT
            )
        )
        or (
            expected_stage == "assertion-start"
            and expected_terminal is not None
        )
        or (
            expected_stage == "assertion-terminal"
            and expected_terminal is None
        )
        or (
            expected_projection_root is not None
            and expected_result_root is not None
        )
        or (
            expected_projection_root is not None
            and (
                expected_result_check_count is not None
                or expected_ordered_root_count != 0
            )
        )
        or (
            expected_projection_root is not None
            and (
                final is not True
                or expected_stage != "assertion-terminal"
                or expected_terminal in {None, "Pass"}
            )
        )
        or (
            expected_stage == "assertion-start"
            and (
                expected_result_root is not None
                or expected_projection_root is not None
                or expected_result_check_count is not None
                or expected_ordered_root_count != 0
            )
        )
        or (
            expected_stage == "assertion-terminal"
            and expected_terminal == "Pass"
            and (
                expected_result_root is None
                or expected_projection_root is not None
            )
        )
        or (
            expected_stage == "assertion-terminal"
            and expected_terminal not in {None, "Pass"}
            and (
                expected_result_root is not None
                or expected_result_check_count is not None
                or expected_ordered_root_count != 0
                or (final is True and expected_projection_root is None)
            )
        )
    ):
        raise EvidenceFailed(
            "v2 self-test event expected scalar context is malformed"
        )
    if set(document) != V2_TEST_EVENT_FIELDS:
        raise EvidenceFailed("v2 self-test event has a non-closed schema")
    projection = document["semantic_projection"]
    artifacts = document["safe_relative_artifacts"]
    terminal = document["terminal"]
    case_id = document["case_id"]
    assertion_id = document["assertion_id"]
    if (
        type(projection) is not dict
        or "harness_contract_identity" not in projection
        or "exception_notes" not in projection
    ):
        raise EvidenceFailed(
            "v2 self-test event semantic projection is malformed"
        )
    try:
        v2_validate_exception_note_projection(projection["exception_notes"])
    except EvidenceFailed as error:
        raise EvidenceFailed(
            "v2 self-test event exception-note contract differs"
        ) from error
    if (
        (
            terminal is None
            or (type(terminal) is str and terminal == "Pass")
        )
        and projection["exception_notes"]["state"] != "ABSENT"
    ):
        raise EvidenceFailed(
            "v2 successful self-test event retained exception notes"
        )
    if (
        final
        and terminal is not None
        and terminal != "Pass"
        and set(projection) == V2_TEST_FAILURE_PROJECTION_FIELDS
        and projection["unexpected_exception_type"] is not None
    ):
        try:
            v2_validate_exception_type_projection(
                projection["unexpected_exception_type"]
            )
        except EvidenceFailed as error:
            raise EvidenceFailed(
                "v2 self-test event exception type projection differs"
            ) from error
    if (
        document["schema"] != V2_TEST_EVENT_SCHEMA
        or type(expected_harness_contract_identity) is not str
        or re.fullmatch(
            r"sha256-v1:[0-9a-f]{64}",
            expected_harness_contract_identity,
        )
        is None
        or type(document["sequence"]) is not int
        or document["sequence"] < 0
        or type(case_id) is not str
        or re.fullmatch(
            r"template-lint-v2\.[a-z0-9]+(?:-[a-z0-9]+)*",
            case_id,
        )
        is None
        or type(assertion_id) is not str
        or assertion_id
        != "v2.case."
        + case_id[len("template-lint-v2.") :]
        or document["executor_id"] != assertion_id
        or type(document["parameter_root"]) is not str
        or re.fullmatch(
            r"sha256-v1:[0-9a-f]{64}",
            document["parameter_root"],
        )
        is None
        or type(document["stage"]) is not str
        or document["stage"] not in {
            "assertion-start",
            "assertion-terminal",
        }
        or type(document["argv"]) is not list
        or len(document["argv"]) != 3
        or type(document["argv"][0]) is not str
        or type(document["argv"][1]) is not str
        or type(document["argv"][2]) is not str
        or projection["harness_contract_identity"]
        != expected_harness_contract_identity
        or type(artifacts) is not dict
        or set(artifacts) != {
            "base",
            "optional_count",
            "optional_paths_root",
        }
        or artifacts["base"] != []
        or type(artifacts["optional_count"]) is not int
        or artifacts["optional_count"] != 0
        or artifacts["optional_paths_root"] != semantic_root([])
        or type(document["exit_code"]) is not int
        or type(document["stdout_byte_length"]) is not int
        or document["stdout_byte_length"] != 0
        or type(document["stderr_byte_length"]) is not int
        or document["stderr_byte_length"] != 0
        or document["stdout_root"]
        != "sha256-v1:" + hashlib.sha256(b"").hexdigest()
        or document["stderr_root"]
        != "sha256-v1:" + hashlib.sha256(b"").hexdigest()
        or document["no_claim"] != V2_TEST_EVENT_NO_CLAIM
        or (
            document["stage"] == "assertion-start"
            and (
                terminal is not None
                or document["exit_code"] != 0
                or document["result_category"] != "PASS"
                or document["first_divergence"] is not None
                or document["recovery"] != "NOT_REQUIRED"
            )
        )
        or (
            document["stage"] == "assertion-terminal"
            and (
                type(terminal) is not str
                or terminal not in TERMINAL_EXIT
                or document["exit_code"] != TERMINAL_EXIT[terminal]
            )
        )
        or (
            terminal == "Pass"
            and (
                document["result_category"] != "PASS"
                or document["first_divergence"] is not None
                or document["recovery"] != "NOT_REQUIRED"
            )
        )
        or (
            final
            and terminal is not None
            and not (type(terminal) is str and terminal == "Pass")
            and (
                type(document["first_divergence"]) is not str
                or not str.strip(document["first_divergence"])
                or len(
                    str.encode(document["first_divergence"], "utf-8")
                )
                > V2_FIRST_DIVERGENCE_BYTES_CAP
                or set(projection) != V2_TEST_FAILURE_PROJECTION_FIELDS
                or type(projection["diagnostic_code"]) is not str
                or projection["diagnostic_code"]
                != document["first_divergence"]
                or type(projection["diagnostic_root"]) is not str
                or re.fullmatch(
                    r"sha256-v1:[0-9a-f]{64}",
                    projection["diagnostic_root"],
                ) is None
                or type(projection["diagnostic_summary"]) is not str
                or not str.strip(projection["diagnostic_summary"])
                or len(
                    str.encode(
                        projection["diagnostic_summary"],
                        "utf-8",
                    )
                )
                > V2_DIAGNOSTIC_SUMMARY_BYTES_CAP
                or (
                    projection["unexpected_exception_type"]
                    is not None
                    and (
                        type(projection["unexpected_exception_type"])
                        is not str
                        or not str.strip(
                            projection["unexpected_exception_type"]
                        )
                    )
                )
                or type(projection["subject"]) is not str
                or type(projection["check_obligation_root"]) is not str
                or re.fullmatch(
                    r"sha256-v1:[0-9a-f]{64}",
                    projection["check_obligation_root"],
                ) is None
                or document["result_category"]
                != v2_runner_failure_policy(terminal)[0]
                or document["recovery"]
                != v2_runner_failure_policy(terminal)[1]
            )
        )
    ):
        raise EvidenceFailed("v2 self-test event contract differs")
    if expected_case is not None:
        if expected_obligation is None:
            raise EvidenceFailed(
                "v2 self-test event validation lacks an expected obligation"
            )
        obligation_root = v2_check_obligation_root(
            expected_case,
            expected_obligation,
        )
        expected_parameter = {
            "case_id": expected_case["id"],
            "assertion_id": expected_case["assertion_id"],
            "ordinal": expected_case["ordinal"],
            "fixture_engine": expected_case["fixture_engine"],
            "check_obligation_root": obligation_root,
            "harness_contract_identity": (
                expected_harness_contract_identity
            ),
            "stage": expected_stage,
        }
        if expected_projection_root is not None:
            if not v2_is_semantic_root(expected_projection_root):
                raise EvidenceFailed(
                    "v2 self-test event expected projection root is malformed"
                )
            bound_projection: dict[str, Any] | None = None
            projection_matches = (
                semantic_root(projection) == expected_projection_root
                and set(projection) == V2_TEST_FAILURE_PROJECTION_FIELDS
                and projection["subject"] == expected_case["subject"]
                and projection["check_obligation_root"]
                == obligation_root
            )
        elif expected_result_root is not None:
            if (
                not v2_is_semantic_root(expected_result_root)
                or type(expected_result_check_count) is not int
                or expected_result_check_count < 0
                or (
                    type(expected_result_ordered_check_roots) is not list
                    and type(expected_result_ordered_check_roots) is not tuple
                )
                or len(expected_result_ordered_check_roots)
                != expected_result_check_count
                or any(
                    not v2_is_semantic_root(root)
                    for root in expected_result_ordered_check_roots
                )
            ):
                raise EvidenceFailed(
                    "v2 self-test event expected result binding is malformed"
                )
            bound_projection = {
                "result_root": expected_result_root,
                "check_count": expected_result_check_count,
                "ordered_check_roots": list(
                    expected_result_ordered_check_roots
                ),
                "check_obligation_root": obligation_root,
                "harness_contract_identity": (
                    expected_harness_contract_identity
                ),
                "exception_notes": projection["exception_notes"],
            }
            projection_matches = projection == bound_projection
        else:
            if (
                expected_result_check_count is not None
                or expected_result_ordered_check_roots
            ):
                raise EvidenceFailed(
                    "v2 self-test event has a partial expected result binding"
                )
            bound_projection = {
                "criterion_ids": list(expected_case["criterion_ids"]),
                "kinds": list(expected_case["kinds"]),
                "fixture_engine": expected_case["fixture_engine"],
                "check_obligation_root": obligation_root,
                "harness_contract_identity": (
                    expected_harness_contract_identity
                ),
                "exception_notes": projection["exception_notes"],
            }
            projection_matches = projection == bound_projection
        if (
            document["case_id"] != expected_case["id"]
            or document["assertion_id"] != expected_case["assertion_id"]
            or document["sequence"] != expected_sequence
            or document["stage"] != expected_stage
            or document["terminal"] != expected_terminal
            or document["argv"]
            != v2_sanitized_argv(
                [
                    SCRIPT_REL_TEXT,
                    "--case-v2",
                    expected_case["id"],
                ]
            )
            or document["parameter_root"] != semantic_root(expected_parameter)
            or not projection_matches
        ):
            raise EvidenceFailed(
                "v2 self-test event differs from its expected case binding"
            )
    verify_semantic_root(document, label="v2 self-test event")
    return document


def v2_validate_log_line_payload(
    payload: bytes,
    *,
    label: str,
) -> None:
    if len(payload) > V2_LOG_LINE_BYTES_CAP:
        raise EvidenceFailed(
            f"{label} exceeds the {V2_LOG_LINE_BYTES_CAP}-byte log-line cap"
        )


def v2_validate_emission_case_context(
    accepted_manifest: Mapping[str, Any],
    *,
    expected_case: Mapping[str, Any],
    expected_obligation: Mapping[str, Any],
) -> tuple[Mapping[str, Any], Mapping[str, Any]]:
    if type(accepted_manifest) is not dict:
        raise EvidenceFailed(
            "v2 self-test emission context is not object-shaped"
        )
    try:
        expected_case = v2_validate_exact_json_wire(
            expected_case,
            label="v2 self-test expected case",
            item_cap=V2_ASSERTION_RESULT_EXACT_WIRE_ITEM_CAP,
            node_cap=V2_ASSERTION_RESULT_EXACT_WIRE_NODE_CAP,
            depth_cap=V2_ASSERTION_RESULT_EXACT_WIRE_DEPTH_CAP,
            byte_cap=V2_LOG_LINE_BYTES_CAP,
            snapshot_byte_cap=(
                V2_ASSERTION_RESULT_EXACT_WIRE_SNAPSHOT_BYTES_CAP
            ),
        )
        expected_obligation = v2_validate_exact_json_wire(
            expected_obligation,
            label="v2 self-test expected obligation",
            item_cap=V2_ASSERTION_RESULT_EXACT_WIRE_ITEM_CAP,
            node_cap=V2_ASSERTION_RESULT_EXACT_WIRE_NODE_CAP,
            depth_cap=V2_ASSERTION_RESULT_EXACT_WIRE_DEPTH_CAP,
            byte_cap=V2_LOG_LINE_BYTES_CAP,
            snapshot_byte_cap=(
                V2_ASSERTION_RESULT_EXACT_WIRE_SNAPSHOT_BYTES_CAP
            ),
        )
    except InputRefused as error:
        raise EvidenceFailed(
            "v2 self-test emission context is outside its exact-wire "
            "resource contract"
        ) from error
    if type(expected_case) is not dict or type(expected_obligation) is not dict:
        raise EvidenceFailed(
            "v2 self-test emission context is not object-shaped"
        )
    v2_validate_check_obligation(
        expected_case,
        expected_obligation,
        error_type=EvidenceFailed,
    )
    expected_case_id = expected_case["id"]
    expected_assertion_id = expected_case["assertion_id"]
    if (
        type(expected_case_id) is not str
        or type(expected_assertion_id) is not str
    ):
        raise EvidenceFailed(
            "v2 self-test emission context identity is malformed"
        )
    if (
        "case" not in accepted_manifest
        or "check_obligations" not in accepted_manifest
    ):
        raise EvidenceFailed(
            "v2 self-test emission context lacks accepted registries"
        )
    manifest_cases = accepted_manifest["case"]
    accepted_obligations = accepted_manifest["check_obligations"]
    if (
        type(manifest_cases) is not list
        or type(accepted_obligations) is not dict
    ):
        raise EvidenceFailed(
            "v2 self-test emission context lacks accepted registries"
        )
    accepted_cases = [
        row
        for row in manifest_cases
        if type(row) is dict
        and "id" in row
        and row["id"] == expected_case_id
    ]
    accepted_obligation = (
        accepted_obligations[expected_assertion_id]
        if expected_assertion_id in accepted_obligations
        else None
    )
    if (
        len(accepted_cases) != 1
        or accepted_cases[0] != expected_case
        or accepted_obligation != expected_obligation
    ):
        raise EvidenceFailed(
            "v2 self-test emission context differs from the accepted manifest"
        )
    return expected_case, expected_obligation


def v2_test_document_schema(document: Any) -> str:
    if type(document) is not dict:
        raise EvidenceFailed(
            "v2 self-test emitter received a non-object document"
        )
    schema: Any = None
    schema_present = False
    for key, value in dict.items(document):
        if type(key) is not str:
            raise EvidenceFailed(
                "v2 self-test emitter received a document outside its "
                "exact-wire resource contract"
            )
        if key == "schema":
            schema = value
            schema_present = True
    if not schema_present:
        raise EvidenceFailed(
            "v2 self-test emitter received an unknown document schema"
        )
    if (
        type(schema) is not str
        or schema
        not in {
            V2_TEST_EVENT_SCHEMA,
            V2_ASSERTION_RESULT_SCHEMA,
            V2_TEST_TERMINAL_SCHEMA,
        }
    ):
        raise EvidenceFailed(
            "v2 self-test emitter received an unknown document schema"
        )
    return schema


def v2_emit_test_document(
    document: Mapping[str, Any],
    *,
    accepted_manifest: Mapping[str, Any],
    expected_case: Mapping[str, Any] | None = None,
    expected_obligation: Mapping[str, Any] | None = None,
    expected_sequence: int | None = None,
    expected_stage: str | None = None,
    expected_result: Mapping[str, Any] | None = None,
    expected_projection: Mapping[str, Any] | None = None,
    expected_terminal: str | None = None,
    expected_results: Sequence[Mapping[str, Any]] | None = None,
    expected_event_roots: Sequence[str] | None = None,
    expected_first_divergence: str | None = None,
    expected_diagnostic_root: str | None = None,
    expected_diagnostic_summary: str | None = None,
    expected_recovery: str | None = None,
    expected_failure_scope: str | None = None,
    expected_selected: str | None = None,
) -> None:
    schema = v2_test_document_schema(document)
    try:
        document = v2_validate_exact_json_wire(
            document,
            label="v2 self-test emission document",
            item_cap=V2_ASSERTION_RESULT_EXACT_WIRE_ITEM_CAP,
            node_cap=V2_ASSERTION_RESULT_EXACT_WIRE_NODE_CAP,
            depth_cap=V2_ASSERTION_RESULT_EXACT_WIRE_DEPTH_CAP,
            byte_cap=V2_LOG_LINE_BYTES_CAP,
            snapshot_byte_cap=(
                V2_ASSERTION_RESULT_EXACT_WIRE_SNAPSHOT_BYTES_CAP
            ),
        )
    except InputRefused as error:
        raise EvidenceFailed(
            "v2 self-test emitter received a document outside its exact-wire "
            "resource contract"
        ) from error
    if v2_test_document_schema(document) != schema:
        raise EvidenceFailed(
            "v2 self-test emitter schema changed during exact-wire detachment"
        )
    if schema == V2_TEST_EVENT_SCHEMA:
        if expected_case is None or expected_obligation is None:
            raise EvidenceFailed(
                "v2 self-test event emission lacks exact expected context"
            )
        expected_case, expected_obligation = (
            v2_validate_emission_case_context(
                accepted_manifest,
                expected_case=expected_case,
                expected_obligation=expected_obligation,
            )
        )
        if expected_result is not None:
            expected_result = v2_validate_assertion_result(
                expected_case,
                expected_result,
                expected_obligation,
            )
        if expected_projection is not None:
            try:
                expected_projection = v2_validate_exact_json_wire(
                    expected_projection,
                    label="v2 self-test expected projection",
                    item_cap=V2_ASSERTION_RESULT_EXACT_WIRE_ITEM_CAP,
                    node_cap=V2_ASSERTION_RESULT_EXACT_WIRE_NODE_CAP,
                    depth_cap=V2_ASSERTION_RESULT_EXACT_WIRE_DEPTH_CAP,
                    byte_cap=V2_LOG_LINE_BYTES_CAP,
                    snapshot_byte_cap=(
                        V2_ASSERTION_RESULT_EXACT_WIRE_SNAPSHOT_BYTES_CAP
                    ),
                )
            except InputRefused as error:
                raise EvidenceFailed(
                    "v2 self-test expected projection is outside its "
                    "exact-wire resource contract"
                ) from error
        document = v2_validate_test_event_document(
            document,
            expected_harness_contract_identity=(
                accepted_manifest["harness_contract_identity"]
            ),
            expected_case=expected_case,
            expected_obligation=expected_obligation,
            expected_sequence=expected_sequence,
            expected_stage=expected_stage,
            expected_result_root=(
                expected_result["semantic_root"]
                if expected_result is not None
                else None
            ),
            expected_result_check_count=(
                expected_result["check_count"]
                if expected_result is not None
                else None
            ),
            expected_result_ordered_check_roots=(
                expected_result["ordered_check_roots"]
                if expected_result is not None
                else ()
            ),
            expected_projection_root=(
                semantic_root(expected_projection)
                if expected_projection is not None
                else None
            ),
            expected_terminal=expected_terminal,
            final=True,
        )
    elif schema == V2_ASSERTION_RESULT_SCHEMA:
        if expected_case is None or expected_obligation is None:
            raise EvidenceFailed(
                "v2 assertion-result emission lacks exact expected context"
            )
        expected_case, expected_obligation = (
            v2_validate_emission_case_context(
                accepted_manifest,
                expected_case=expected_case,
                expected_obligation=expected_obligation,
            )
        )
        document = v2_validate_assertion_result(
            expected_case,
            document,
            expected_obligation,
        )
    elif schema == V2_TEST_TERMINAL_SCHEMA:
        if (
            expected_results is None
            or expected_event_roots is None
            or expected_terminal is None
            or expected_recovery is None
        ):
            raise EvidenceFailed(
                "v2 suite-terminal emission lacks exact expected context"
            )
        document = v2_validate_test_terminal_document(
            document,
            accepted_manifest=accepted_manifest,
            expected_results=expected_results,
            expected_event_roots=expected_event_roots,
            expected_selected=expected_selected,
            expected_terminal=expected_terminal,
            expected_first_divergence=expected_first_divergence,
            expected_diagnostic_root=expected_diagnostic_root,
            expected_diagnostic_summary=expected_diagnostic_summary,
            expected_recovery=expected_recovery,
            expected_failure_scope=expected_failure_scope,
        )
    else:
        raise EvidenceFailed(
            "v2 self-test emitter received an unknown document schema"
        )
    v2_validate_log_line_payload(
        canonical_bytes(document),
        label="v2 self-test JSONL document",
    )
    json_stdout(document)


def v2_bounded_first_divergence(
    diagnostic: str,
    *,
    fallback: str,
) -> str:
    candidate = (
        diagnostic.split(" failed:", 1)[0]
        if " failed:" in diagnostic
        else fallback
    )
    candidate = v2_bounded_diagnostic_summary(candidate)
    encoded = candidate.encode("utf-8")
    if len(encoded) <= V2_FIRST_DIVERGENCE_BYTES_CAP:
        return candidate
    suffix = "...<root:" + text_root(candidate) + ">"
    remaining = (
        V2_FIRST_DIVERGENCE_BYTES_CAP
        - len(suffix.encode("utf-8"))
    )
    return (
        encoded[:remaining].decode("utf-8", errors="ignore")
        + suffix
    )


def v2_validate_assertion_result(
    case: Mapping[str, Any],
    result: Any,
    obligation: Any,
) -> Mapping[str, Any]:
    v2_validate_check_obligation(
        case,
        obligation,
        error_type=EvidenceFailed,
    )
    try:
        result = v2_detach_assertion_result_wire(
            result,
            label=f"{case['assertion_id']} assertion result",
        )
    except InputRefused as error:
        raise EvidenceFailed(
            f"{case['assertion_id']} returned assertion evidence outside "
            "the exact-wire resource contract"
        ) from error
    malformed = (
        type(result) is not dict
        or set(result) != V2_ASSERTION_RESULT_FIELDS
        or type(result["schema"]) is not str
        or result["schema"] != V2_ASSERTION_RESULT_SCHEMA
        or type(result["case_id"]) is not str
        or result["case_id"] != case["id"]
        or type(result["assertion_id"]) is not str
        or result["assertion_id"] != case["assertion_id"]
        or type(result["executor_id"]) is not str
        or result["executor_id"] != case["assertion_id"]
        or type(result["terminal"]) is not str
        or result["terminal"] != "Pass"
        or type(result["no_claim"]) is not str
        or result["no_claim"] != V2_ASSERTION_RESULT_NO_CLAIM
        or type(result["semantic_root"]) is not str
        or not v2_is_semantic_root(result["semantic_root"])
        or type(result["parameters"]) is not dict
        or set(result["parameters"]) != {"family", "slug"}
        or type(result["parameters"]["family"]) is not str
        or type(result["parameters"]["slug"]) is not str
        or type(result["parameter_root"]) is not str
        or not v2_is_semantic_root(result["parameter_root"])
        or type(result["ordered_checks"]) is not list
        or not result["ordered_checks"]
        or len(result["ordered_checks"]) > V2_ASSERTION_CHECKS_CAP
        or type(result["ordered_check_roots"]) is not list
        or any(
            not v2_is_semantic_root(root)
            for root in result["ordered_check_roots"]
        )
        or type(result["check_count"]) is not int
        or result["check_count"] != len(result["ordered_checks"])
    )
    if malformed:
        raise EvidenceFailed(
            f"{case['assertion_id']} returned malformed assertion evidence"
    )
    parameters = result["parameters"]
    case_id = case["id"]
    if type(case_id) is not str or not str.startswith(
        case_id,
        "template-lint-v2.",
    ):
        raise EvidenceFailed("assertion result case ID is malformed")
    expected_slug = case_id[len("template-lint-v2.") :]
    ordinal = case["ordinal"]
    expected_family = next(
        (
            family
            for first, last, family in V2_EXECUTOR_FAMILY_NAMES
            if type(ordinal) is int and first <= ordinal <= last
        ),
        None,
    )
    if (
        expected_family is None
        or parameters["family"] != expected_family
        or parameters["slug"] != expected_slug
        or result["parameter_root"] != semantic_root(parameters)
    ):
        raise EvidenceFailed(
            f"{case['assertion_id']} returned unbound assertion parameters"
        )
    check_ids: list[str] = []
    observed_roots: list[str] = []
    for index, check in enumerate(result["ordered_checks"]):
        if (
            type(check) is not dict
            or set(check) != V2_ASSERTION_CHECK_FIELDS
            or type(check["check_id"]) is not str
            or check["passed"] is not True
            or type(check["semantic_root"]) is not str
            or not v2_is_semantic_root(check["semantic_root"])
        ):
            raise EvidenceFailed(
                f"{case['assertion_id']} returned malformed check evidence "
                f"at index {index}"
            )
        try:
            verify_semantic_root(
                check,
                label=f"{case['assertion_id']} ordered check {index}",
            )
        except (
            TypeError,
            ValueError,
            OverflowError,
            RecursionError,
        ) as error:
            raise EvidenceFailed(
                f"{case['assertion_id']} returned noncanonical check "
                f"evidence at index {index}"
            ) from error
        for evidence_field in ("expected", "observed"):
            evidence_value = check[evidence_field]
            receipt_shaped = (
                type(evidence_value) is dict
                and dict.__len__(evidence_value) == 2
                and set(dict.__iter__(evidence_value))
                == {"projection_root", "canonical_bytes"}
            )
            if receipt_shaped and (
                    not v2_is_semantic_root(
                        evidence_value["projection_root"]
                    )
                    or type(evidence_value["canonical_bytes"]) is not int
                    or not 2 <= evidence_value["canonical_bytes"]
                    <= V2_ASSERTION_EVIDENCE_PROJECTION_BYTES_CAP
            ):
                raise EvidenceFailed(
                    f"{case['assertion_id']} returned malformed bounded "
                    f"{evidence_field} evidence receipt at index {index}"
                )
            if (
                not receipt_shaped
                and len(canonical_bytes(evidence_value))
                > V2_ASSERTION_EVIDENCE_INLINE_BYTES_CAP
            ):
                raise EvidenceFailed(
                    f"{case['assertion_id']} returned oversized inline "
                    f"{evidence_field} evidence at index {index}"
                )
            try:
                projected_evidence = v2_assertion_evidence_projection(
                    evidence_value
                )
            except EvidenceFailed as error:
                raise EvidenceFailed(
                    f"{case['assertion_id']} returned invalid projected "
                    f"{evidence_field} evidence at index {index}"
                ) from error
            if projected_evidence != evidence_value:
                raise EvidenceFailed(
                    f"{case['assertion_id']} returned unredacted "
                    f"{evidence_field} evidence at index {index}"
                )
        check_id = check["check_id"]
        v2_validate_check_id(
            check_id,
            label=(
                f"{case['assertion_id']} ordered check {index}"
            ),
        )
        check_ids.append(check_id)
        observed_roots.append(check["semantic_root"])
    if len(check_ids) != len(set(check_ids)):
        raise EvidenceFailed(
            f"{case['assertion_id']} returned duplicate check IDs"
        )
    if (
        result["check_count"] != obligation["check_count"]
        or check_ids != obligation["ordered_check_ids"]
    ):
        raise EvidenceFailed(
            f"{case['assertion_id']} returned checks that differ from its "
            "exact ordered obligation"
        )
    if result["ordered_check_roots"] != observed_roots:
        raise EvidenceFailed(
            f"{case['assertion_id']} returned unbound ordered check roots"
        )
    try:
        verify_semantic_root(
            result,
            label=f"{case['assertion_id']} assertion result",
        )
        result_payload = canonical_bytes(result)
    except (
        TypeError,
        ValueError,
        OverflowError,
        RecursionError,
    ) as error:
        raise EvidenceFailed(
            f"{case['assertion_id']} returned noncanonical assertion evidence"
        ) from error
    v2_validate_log_line_payload(
        result_payload,
        label=f"{case['assertion_id']} assertion result",
    )
    return result


def v2_validate_suite_expected_results(
    accepted_manifest: Mapping[str, Any],
    *,
    selected: Any,
    expected_results: Sequence[Mapping[str, Any]],
) -> tuple[list[Mapping[str, Any]], list[Mapping[str, Any]]]:
    if type(accepted_manifest) is not dict:
        raise EvidenceFailed(
            "v2 suite-terminal accepted manifest is not an exact object"
        )
    accepted_cases = (
        accepted_manifest["case"]
        if "case" in accepted_manifest
        else None
    )
    accepted_obligations = (
        accepted_manifest["check_obligations"]
        if "check_obligations" in accepted_manifest
        else None
    )
    if (
        type(accepted_cases) is not list
        or type(accepted_obligations) is not dict
    ):
        raise EvidenceFailed(
            "v2 suite-terminal accepted manifest lacks registries"
        )
    if selected is not None and type(selected) is not str:
        raise EvidenceFailed(
            "v2 suite-terminal selection is not a string or null"
        )
    if (
        type(expected_results) is not list
        and type(expected_results) is not tuple
    ):
        raise EvidenceFailed(
            "v2 suite-terminal expected results are not ordered"
        )
    expected_cases = [
        row
        for row in accepted_cases
        if type(row) is dict
        if selected is None or row["id"] == selected
    ]
    if (
        not expected_cases
        or len(expected_results) > len(expected_cases)
    ):
        raise EvidenceFailed(
            "v2 suite-terminal expected result cardinality differs"
        )
    validated_results: list[Mapping[str, Any]] = []
    for index, result in enumerate(expected_results):
        case = expected_cases[index]
        assertion_id = case["assertion_id"]
        obligation = (
            accepted_obligations[assertion_id]
            if assertion_id in accepted_obligations
            else None
        )
        validated_results.append(
            v2_validate_assertion_result(
                case,
                result,
                obligation,
            )
        )
    return expected_cases, validated_results


V2_AUDITED_LOCAL_PURE_CALL_RESULT_PATHS += ((
    v2_validate_suite_expected_results,
    frozenset({V2_DERIVED_CALL_RESULT_PATH[0]}),
),)
V2_AUDITED_LOCAL_PURE_CALL_CODE_CONTRACTS += ((
    v2_validate_suite_expected_results,
    v2_validate_suite_expected_results.__code__,
),)


def v2_validate_test_terminal_document(
    document: Mapping[str, Any],
    *,
    accepted_manifest: Mapping[str, Any],
    expected_results: Sequence[Mapping[str, Any]],
    expected_event_roots: Sequence[str],
    expected_selected: str | None,
    expected_terminal: str,
    expected_first_divergence: str | None,
    expected_diagnostic_root: str | None,
    expected_diagnostic_summary: str | None,
    expected_recovery: str,
    expected_failure_scope: str | None,
) -> Mapping[str, Any]:
    if type(document) is not dict:
        raise EvidenceFailed("v2 self-test terminal is not an object")
    try:
        document = v2_validate_exact_json_wire(
            document,
            label="v2 self-test terminal",
            item_cap=V2_ASSERTION_RESULT_EXACT_WIRE_ITEM_CAP,
            node_cap=V2_ASSERTION_RESULT_EXACT_WIRE_NODE_CAP,
            depth_cap=V2_ASSERTION_RESULT_EXACT_WIRE_DEPTH_CAP,
            byte_cap=V2_LOG_LINE_BYTES_CAP,
            snapshot_byte_cap=(
                V2_ASSERTION_RESULT_EXACT_WIRE_SNAPSHOT_BYTES_CAP
            ),
        )
    except InputRefused as error:
        raise EvidenceFailed(
            "v2 self-test terminal is outside its exact-wire resource contract"
        ) from error
    if (
        (
            expected_selected is not None
            and type(expected_selected) is not str
        )
        or type(expected_terminal) is not str
        or expected_terminal not in TERMINAL_EXIT
        or type(expected_recovery) is not str
        or (
            expected_first_divergence is not None
            and type(expected_first_divergence) is not str
        )
        or (
            expected_diagnostic_root is not None
            and type(expected_diagnostic_root) is not str
        )
        or (
            expected_diagnostic_summary is not None
            and type(expected_diagnostic_summary) is not str
        )
        or (
            expected_failure_scope is not None
            and type(expected_failure_scope) is not str
        )
    ):
        raise EvidenceFailed(
            "v2 suite-terminal expected scalar context is malformed"
        )
    if expected_terminal == "Pass":
        if (
            expected_first_divergence is not None
            or expected_diagnostic_root is not None
            or expected_diagnostic_summary is not None
            or expected_recovery != "NOT_REQUIRED"
            or expected_failure_scope is not None
        ):
            raise EvidenceFailed(
                "v2 suite-terminal expected pass context is malformed"
            )
    else:
        try:
            expected_divergence_bytes = str.encode(
                expected_first_divergence,
                "utf-8",
            )
            expected_summary_bytes = str.encode(
                expected_diagnostic_summary,
                "utf-8",
            )
        except (TypeError, UnicodeEncodeError) as error:
            raise EvidenceFailed(
                "v2 suite-terminal expected failure context is malformed"
            ) from error
        if (
            not str.strip(expected_first_divergence)
            or len(expected_divergence_bytes)
            > V2_FIRST_DIVERGENCE_BYTES_CAP
            or not v2_is_semantic_root(expected_diagnostic_root)
            or not str.strip(expected_diagnostic_summary)
            or len(expected_summary_bytes)
            > V2_DIAGNOSTIC_SUMMARY_BYTES_CAP
            or expected_recovery
            != v2_runner_failure_policy(expected_terminal)[1]
            or expected_failure_scope
            not in {"assertion", "suite-boundary"}
        ):
            raise EvidenceFailed(
                "v2 suite-terminal expected failure context is malformed"
            )
    if set(document) != V2_TEST_TERMINAL_FIELDS:
        raise EvidenceFailed("v2 self-test terminal has a non-closed schema")
    terminal = document["terminal"]
    case_ids = document["ordered_case_ids"]
    assertion_ids = document["ordered_assertion_ids"]
    case_roots = document["ordered_case_roots"]
    event_roots = document["ordered_event_roots"]
    failure_scope = document["failure_scope"]
    selected = document["selected"]
    if selected != expected_selected:
        raise EvidenceFailed(
            "v2 suite-terminal selection differs from its expected context"
        )
    expected_cases, validated_results = (
        v2_validate_suite_expected_results(
            accepted_manifest,
            selected=selected,
            expected_results=expected_results,
        )
    )
    expected_case_ids = [row["id"] for row in expected_cases]
    expected_assertion_ids = [
        row["assertion_id"] for row in expected_cases
    ]
    expected_result_roots = [
        row["semantic_root"] for row in validated_results
    ]
    if (
        type(expected_event_roots) is not list
        and type(expected_event_roots) is not tuple
    ):
        raise EvidenceFailed(
            "v2 suite-terminal expected event roots are not ordered"
        )
    expected_event_root_count = len(expected_event_roots)
    if expected_event_root_count > 2 * len(expected_cases):
        raise EvidenceFailed(
            "v2 suite-terminal expected event roots exceed the case bound"
        )
    bound_event_roots = list(
        list.__iter__(expected_event_roots)
        if type(expected_event_roots) is list
        else tuple.__iter__(expected_event_roots)
    )
    if (
        len(bound_event_roots) != expected_event_root_count
        or any(not v2_is_semantic_root(root) for root in bound_event_roots)
    ):
        raise EvidenceFailed(
            "v2 suite-terminal expected event roots are malformed"
        )
    completed_count = len(validated_results)
    expected_completed_case_ids = expected_case_ids[:completed_count]
    expected_completed_assertion_ids = expected_assertion_ids[
        :completed_count
    ]
    expected_check_count = sum(
        int(
            accepted_manifest["check_obligations"][
                assertion_id
            ]["check_count"]
        )
        for assertion_id in expected_completed_assertion_ids
    )
    expected_registry_root = semantic_root(
        sorted(
            row["assertion_id"]
            for row in accepted_manifest["case"]
        )
    )
    if (
        document["schema"] != V2_TEST_TERMINAL_SCHEMA
        or type(terminal) is not str
        or terminal not in TERMINAL_EXIT
        or terminal != expected_terminal
        or type(document["exit_code"]) is not int
        or document["exit_code"] != TERMINAL_EXIT[terminal]
        or document["first_divergence"]
        != expected_first_divergence
        or document["diagnostic_root"] != expected_diagnostic_root
        or document["diagnostic_summary"]
        != expected_diagnostic_summary
        or document["recovery"] != expected_recovery
        or failure_scope != expected_failure_scope
        or type(document["recovery"]) is not str
        or (
            selected is not None
            and type(selected) is not str
        )
        or not expected_cases
        or document["manifest_root"] != accepted_manifest["semantic_root"]
        or document["manifest_content_identity"]
        != accepted_manifest["content_identity"]
        or document["harness_contract_identity"]
        != accepted_manifest["harness_contract_identity"]
        or type(document["case_count"]) is not int
        or type(document["assertion_count"]) is not int
        or type(document["check_count"]) is not int
        or document["case_count"] < 0
        or document["case_count"] != len(validated_results)
        or document["assertion_count"] != document["case_count"]
        or document["check_count"] < 0
        or (
            failure_scope is not None
            and type(failure_scope) is not str
        )
        or type(case_ids) is not list
        or type(assertion_ids) is not list
        or type(case_roots) is not list
        or type(event_roots) is not list
        or len(case_ids) != document["case_count"]
        or len(assertion_ids) != document["assertion_count"]
        or len(case_roots) != document["case_count"]
        or case_roots != expected_result_roots
        or event_roots != bound_event_roots
        or any(type(value) is not str for value in case_ids)
        or any(type(value) is not str for value in assertion_ids)
        or any(type(value) is not str for value in case_roots)
        or any(type(value) is not str for value in event_roots)
        or len(case_roots) != len(set(case_roots))
        or len(event_roots) != len(set(event_roots))
        or len(case_ids) != len(set(case_ids))
        or len(assertion_ids) != len(set(assertion_ids))
        or case_ids != expected_completed_case_ids
        or assertion_ids != expected_completed_assertion_ids
        or document["check_count"] != expected_check_count
        or any(
            assertion_id
            != "v2.case."
            + case_id[len("template-lint-v2.") :]
            for case_id, assertion_id in zip(case_ids, assertion_ids)
        )
        or any(
            re.fullmatch(r"sha256-v1:[0-9a-f]{64}", root) is None
            for root in [*case_roots, *event_roots]
        )
        or type(document["compiled_executor_ids_root"]) is not str
        or re.fullmatch(
            r"sha256-v1:[0-9a-f]{64}",
            document["compiled_executor_ids_root"],
        )
        is None
        or document["compiled_executor_ids_root"] != expected_registry_root
        or document["skipped_assertions"] != []
        or document["aggregate_count_only"] is not False
        or (
            terminal == "Pass"
            and (
                case_ids != expected_case_ids
                or assertion_ids != expected_assertion_ids
                or len(event_roots) != 2 * len(expected_case_ids)
                or failure_scope is not None
                or
                document["first_divergence"] is not None
                or document["diagnostic_root"] is not None
                or document["diagnostic_summary"] is not None
                or document["recovery"] != "NOT_REQUIRED"
                or document["no_claim"]
                != (
                    f"the suite proves only its {len(case_ids)} selected "
                    "bounded executable contracts; it does not mutate or "
                    "complete live target Beads"
                )
            )
        )
        or (
            terminal != "Pass"
            and failure_scope == "assertion"
            and (
                len(event_roots) != 2 * (len(case_ids) + 1)
                or len(case_ids) >= len(expected_case_ids)
                or
                type(document["first_divergence"]) is not str
                or not str.strip(document["first_divergence"])
                or len(
                    str.encode(document["first_divergence"], "utf-8")
                )
                > V2_FIRST_DIVERGENCE_BYTES_CAP
                or type(document["diagnostic_root"]) is not str
                or re.fullmatch(
                    r"sha256-v1:[0-9a-f]{64}",
                    document["diagnostic_root"],
                )
                is None
                or type(document["diagnostic_summary"]) is not str
                or not str.strip(document["diagnostic_summary"])
                or len(
                    str.encode(document["diagnostic_summary"], "utf-8")
                )
                > V2_DIAGNOSTIC_SUMMARY_BYTES_CAP
                or document["recovery"]
                != v2_runner_failure_policy(terminal)[1]
                or document["no_claim"] != "the v2 suite did not pass"
            )
        )
        or (
            terminal != "Pass"
            and failure_scope == "suite-boundary"
            and (
                len(event_roots) != 2 * len(case_ids)
                or len(case_ids) > len(expected_case_ids)
                or
                type(document["first_divergence"]) is not str
                or not str.strip(document["first_divergence"])
                or len(
                    str.encode(document["first_divergence"], "utf-8")
                )
                > V2_FIRST_DIVERGENCE_BYTES_CAP
                or type(document["diagnostic_root"]) is not str
                or re.fullmatch(
                    r"sha256-v1:[0-9a-f]{64}",
                    document["diagnostic_root"],
                )
                is None
                or type(document["diagnostic_summary"]) is not str
                or not str.strip(document["diagnostic_summary"])
                or len(
                    str.encode(document["diagnostic_summary"], "utf-8")
                )
                > V2_DIAGNOSTIC_SUMMARY_BYTES_CAP
                or document["recovery"]
                != v2_runner_failure_policy(terminal)[1]
                or document["no_claim"] != "the v2 suite did not pass"
            )
        )
        or (
            terminal != "Pass"
            and failure_scope not in {"assertion", "suite-boundary"}
        )
    ):
        raise EvidenceFailed("v2 self-test terminal contract differs")
    verify_semantic_root(document, label="v2 self-test terminal")
    return document


