        v2_canonical_missing_sections,
        v2_canonical_missing_sections.__code__,
        dict.get,
        frozenset({
            V2_DERIVED_CALL_RESULT_PATH,
            ("<iter-item>",),
        }),
    ),
    # Semantic-root verification first replaces the caller's object with an
    # exact detached JSON snapshot. Base getitem results are copied into a new
    # exact dict and never used as callables.
    (
        verify_semantic_root,
        verify_semantic_root.__code__,
        dict.__getitem__,
        frozenset({V2_DERIVED_CALL_RESULT_PATH}),
    ),
