        frozenset({V2_DERIVED_CALL_RESULT_PATH}),
    ),
)


def v2_validate_runtime_code_contracts() -> None:
    module_globals = globals()
    required_contract_bindings = (
        "V2_AUDITED_LOCAL_PURE_CALL_CODE_CONTRACTS",
        "V2_ASSERTION_COLLECTOR_CODE_CONTRACTS",
        "V2_AUDITED_LOCAL_FAST_RESULT_REGISTRY_CONTRACT",
        "V2_AUDITED_LOCAL_FAST_RESULT_KINDS",
        "V2_AUDITED_LOCAL_FAST_RESULT_CONTRACTS",
        "V2_FUNCTION_GLOBALS_DESCRIPTOR_CONTRACT",
        "V2_FUNCTION_TYPE_CONTRACT",
        "V2_CODE_TYPE_CONTRACT",
        "V2_FUNCTION_CODE_DESCRIPTOR_CONTRACT",
        "V2_RUNTIME_CODE_PREFLIGHT_CONTRACT",
        "V2_EXACT_CONTAINER_VALIDATOR_RESULT_CONTRACTS",
        "V2_RUNNER_AUTHORITY_GLOBAL_CONTRACTS",
        "V2_RUNNER_AUTHORITY_VALUE_CONTRACTS",
        "V2_RUNNER_AUTHORITY_ERROR_CLASS_CONTRACTS",
    )
    if any(
        not dict.__contains__(module_globals, name)
        for name in required_contract_bindings
    ):
        raise EvidenceFailed(
            "v2 runtime code-contract preflight binding is missing"
        )
    contracts = (
        *V2_AUDITED_LOCAL_PURE_CALL_CODE_CONTRACTS,
        *V2_ASSERTION_COLLECTOR_CODE_CONTRACTS,
    )
    callable_identities: set[int] = set()
    for candidate, pinned_code in contracts:
        if (
            type(candidate) is not V2_FUNCTION_TYPE_CONTRACT
            or type(pinned_code) is not V2_CODE_TYPE_CONTRACT
            or id(candidate) in callable_identities
            or V2_FUNCTION_CODE_DESCRIPTOR_CONTRACT.__get__(
                candidate,
                V2_FUNCTION_TYPE_CONTRACT,
            )
            is not pinned_code
        ):
            raise EvidenceFailed(
                "v2 runtime audited local callable code identity drifted"
            )
        set.add(callable_identities, id(candidate))
    fast_registry = V2_AUDITED_LOCAL_FAST_RESULT_REGISTRY_CONTRACT
    if (
        type(fast_registry) is not tuple
        or len(fast_registry) != 2
        or tuple.__getitem__(fast_registry, 0)
        is not V2_AUDITED_LOCAL_FAST_RESULT_KINDS
        or tuple.__getitem__(fast_registry, 1)
        is not V2_AUDITED_LOCAL_FAST_RESULT_CONTRACTS
        or type(V2_AUDITED_LOCAL_FAST_RESULT_KINDS) is not frozenset
        or V2_AUDITED_LOCAL_FAST_RESULT_KINDS
        != frozenset({
            "exact-int",
            "exact-json-dict",
            "exact-json-list",
            "exact-str",
        })
        or type(V2_AUDITED_LOCAL_FAST_RESULT_CONTRACTS) is not tuple
    ):
        raise EvidenceFailed(
            "v2 runtime audited fast-result registry drifted"
        )
    descriptor_globals = V2_FUNCTION_GLOBALS_DESCRIPTOR_CONTRACT.__get__(
        v2_validate_runtime_code_contracts,
        V2_FUNCTION_TYPE_CONTRACT,
    )
    if descriptor_globals is not module_globals or type(module_globals) is not dict:
        raise EvidenceFailed(
            "v2 runtime runner-authority globals mapping is not exact"
        )
    fast_binding_names: set[str] = set()
    fast_candidate_ids: set[int] = set()
    fast_code_ids: set[int] = set()
    for contract in V2_AUDITED_LOCAL_FAST_RESULT_CONTRACTS:
        if type(contract) is not tuple or len(contract) != 4:
            raise EvidenceFailed(
                "v2 runtime audited fast-result row is malformed"
            )
        binding_name, candidate, pinned_code, result_kind = contract
        if (
            type(binding_name) is not str
            or not binding_name
            or binding_name in fast_binding_names
            or type(candidate) is not V2_FUNCTION_TYPE_CONTRACT
            or id(candidate) in fast_candidate_ids
            or type(pinned_code) is not V2_CODE_TYPE_CONTRACT
            or id(pinned_code) in fast_code_ids
            or V2_FUNCTION_CODE_DESCRIPTOR_CONTRACT.__get__(
                candidate,
                V2_FUNCTION_TYPE_CONTRACT,
            )
            is not pinned_code
            or type(result_kind) is not str
            or result_kind not in V2_AUDITED_LOCAL_FAST_RESULT_KINDS
            or V2_FUNCTION_GLOBALS_DESCRIPTOR_CONTRACT.__get__(
                candidate,
                V2_FUNCTION_TYPE_CONTRACT,
            )
            is not module_globals
            or dict.get(module_globals, binding_name) is not candidate
            or sum(
                pure_candidate is candidate
                for pure_candidate, _allowed_paths
                in V2_AUDITED_LOCAL_PURE_CALL_RESULT_PATHS
            )
            != 1
            or sum(
                pure_candidate is candidate
                and pure_code is pinned_code
                for pure_candidate, pure_code
                in V2_AUDITED_LOCAL_PURE_CALL_CODE_CONTRACTS
            )
            != 1
        ):
            raise EvidenceFailed(
                "v2 runtime audited fast-result row identity drifted"
            )
        fast_binding_names.add(binding_name)
        fast_candidate_ids.add(id(candidate))
        fast_code_ids.add(id(pinned_code))
    fast_dependency_function_names = set(fast_binding_names)
    fast_dependency_value_names: set[str] = set()
    pending_fast_functions = [
        candidate
        for _binding_name, candidate, _pinned_code, _result_kind
        in V2_AUDITED_LOCAL_FAST_RESULT_CONTRACTS
    ]
    visited_fast_function_ids: set[int] = set()
    while pending_fast_functions:
        candidate = pending_fast_functions.pop()
        if id(candidate) in visited_fast_function_ids:
            continue
        visited_fast_function_ids.add(id(candidate))
        for dependency_name in candidate.__code__.co_names:
            if not dict.__contains__(module_globals, dependency_name):
                # Selected interpreter builtins are the declared runtime
                # baseline. Any module-level shadow becomes visible here and
                # must itself be sealed as a value dependency.
                continue
            dependency = dict.__getitem__(module_globals, dependency_name)
            if type(dependency) is V2_FUNCTION_TYPE_CONTRACT:
                fast_dependency_function_names.add(dependency_name)
                pending_fast_functions.append(dependency)
            else:
                fast_dependency_value_names.add(dependency_name)
    authority_function_binding_names = {
        row[0] for row in V2_RUNNER_AUTHORITY_GLOBAL_CONTRACTS
    }
    authority_value_binding_names = {
        row[0] for row in V2_RUNNER_AUTHORITY_VALUE_CONTRACTS
    }
    runner_error_class_binding_names = {
        contract[1]
        for contract in V2_RUNNER_AUTHORITY_ERROR_CLASS_CONTRACTS
    }
    if (
        not fast_dependency_function_names.issubset(
            authority_function_binding_names
        )
        or not fast_dependency_value_names.issubset(
            authority_value_binding_names
        )
        or authority_value_binding_names
        != fast_dependency_value_names | runner_error_class_binding_names
    ):
        raise EvidenceFailed(
            "v2 runtime fast-result transitive authority closure drifted"
        )
    exact_contract_identities: set[tuple[int, int]] = set()
    for candidate, pinned_code, descriptor, allowed_paths in (
        V2_EXACT_CONTAINER_VALIDATOR_RESULT_CONTRACTS
    ):
        contract_identity = (id(candidate), id(descriptor))
        if (
            type(candidate) is not V2_FUNCTION_TYPE_CONTRACT
            or type(pinned_code) is not V2_CODE_TYPE_CONTRACT
            or V2_FUNCTION_CODE_DESCRIPTOR_CONTRACT.__get__(
                candidate,
                V2_FUNCTION_TYPE_CONTRACT,
            )
            is not pinned_code
            or not any(
                descriptor is expected_descriptor
                for expected_descriptor in (
                    dict.get,
                    dict.values,
                    dict.__getitem__,
                    dict.__iter__,
                    dict.__len__,
                    list.__len__,
                    list.__getitem__,
                    list.__iter__,
                )
            )
            or type(allowed_paths) is not frozenset
            or allowed_paths
            not in {
                frozenset({V2_DERIVED_CALL_RESULT_PATH}),
                frozenset({
                    V2_DERIVED_CALL_RESULT_PATH,
                    ("<iter-item>",),
                }),
                frozenset({
                    V2_DERIVED_CALL_RESULT_PATH,
                    V2_DIRECT_CALL_RESULT_PATH,
                    ("<iter-item>",),
                }),
                frozenset({
                    V2_DERIVED_CALL_RESULT_PATH,
                    V2_DIRECT_CALL_RESULT_PATH,
                }),
            }
            or contract_identity in exact_contract_identities
        ):
            raise EvidenceFailed(
                "v2 runtime exact-container validator result contract drifted"
            )
        exact_contract_identities.add(contract_identity)
    runtime_contract = dict.get(
        module_globals,
        "V2_RUNTIME_CODE_PREFLIGHT_CONTRACT",
    )
    if type(runtime_contract) is not tuple or len(runtime_contract) != 26:
        raise EvidenceFailed(
            "v2 runtime code-contract preflight tuple is malformed"
        )
    (
        expected_preflight_callable,
        expected_preflight_code,
        expected_audited_result_paths,
        expected_audited_code_contracts,
        expected_audited_fast_result_registry_contract,
        expected_exact_container_validator_result_contracts,
        expected_collector_code_contracts,
        expected_collector_dispatch_contracts,
        expected_collector_default_contracts,
        expected_collector_class,
        expected_collector_class_keys,
        expected_collector_storage_contracts,
        expected_collector_metadata_contracts,
        expected_refuses_closure,
        expected_refuses_closure_contracts,
        expected_runner_authority_global_contracts,
        expected_runner_authority_value_contracts,
        expected_runner_authority_error_class_contracts,
        expected_terminal_exit_binding_contract,
        expected_function_type,
        expected_code_type,
        expected_function_code_descriptor,
        expected_function_defaults_descriptor,
        expected_function_keyword_defaults_descriptor,
        expected_function_closure_descriptor,
        expected_function_globals_descriptor,
    ) = runtime_contract
    if (
        dict.get(module_globals, "v2_validate_runtime_code_contracts")
        is not expected_preflight_callable
        or expected_function_code_descriptor.__get__(
            expected_preflight_callable,
            expected_function_type,
        )
        is not expected_preflight_code
        or dict.get(
            module_globals,
            "V2_AUDITED_LOCAL_PURE_CALL_RESULT_PATHS",
        )
        is not expected_audited_result_paths
        or dict.get(
            module_globals,
            "V2_AUDITED_LOCAL_PURE_CALL_CODE_CONTRACTS",
        )
        is not expected_audited_code_contracts
        or dict.get(
            module_globals,
            "V2_AUDITED_LOCAL_FAST_RESULT_REGISTRY_CONTRACT",
        )
        is not expected_audited_fast_result_registry_contract
        or dict.get(
            module_globals,
            "V2_EXACT_CONTAINER_VALIDATOR_RESULT_CONTRACTS",
        )
        is not expected_exact_container_validator_result_contracts
        or dict.get(module_globals, "V2_ASSERTION_COLLECTOR_CODE_CONTRACTS")
        is not expected_collector_code_contracts
        or dict.get(
            module_globals,
            "V2_ASSERTION_COLLECTOR_DISPATCH_CONTRACTS",
        )
        is not expected_collector_dispatch_contracts
        or dict.get(
            module_globals,
            "V2_ASSERTION_COLLECTOR_DEFAULT_CONTRACTS",
        )
        is not expected_collector_default_contracts
        or dict.get(module_globals, "V2_ASSERTION_COLLECTOR_CLASS_CONTRACT")
        is not expected_collector_class
        or dict.get(
            module_globals,
            "V2_ASSERTION_COLLECTOR_CLASS_KEYS_CONTRACT",
        )
        is not expected_collector_class_keys
        or dict.get(
            module_globals,
            "V2_ASSERTION_COLLECTOR_STORAGE_CONTRACTS",
        )
        is not expected_collector_storage_contracts
        or dict.get(
            module_globals,
            "V2_ASSERTION_COLLECTOR_CLASS_METADATA_CONTRACTS",
        )
        is not expected_collector_metadata_contracts
        or dict.get(module_globals, "V2_ASSERTION_COLLECTOR_REFUSES_CLOSURE")
        is not expected_refuses_closure
        or dict.get(
            module_globals,
            "V2_ASSERTION_COLLECTOR_REFUSES_CLOSURE_CONTRACTS",
        )
        is not expected_refuses_closure_contracts
        or dict.get(module_globals, "V2_RUNNER_AUTHORITY_GLOBAL_CONTRACTS")
        is not expected_runner_authority_global_contracts
        or dict.get(module_globals, "V2_RUNNER_AUTHORITY_VALUE_CONTRACTS")
        is not expected_runner_authority_value_contracts
        or dict.get(
            module_globals,
            "V2_RUNNER_AUTHORITY_ERROR_CLASS_CONTRACTS",
        )
        is not expected_runner_authority_error_class_contracts
        or dict.get(module_globals, "V2_TERMINAL_EXIT_BINDING_CONTRACT")
        is not expected_terminal_exit_binding_contract
        or dict.get(module_globals, "V2_FUNCTION_TYPE_CONTRACT")
        is not expected_function_type
        or dict.get(module_globals, "V2_CODE_TYPE_CONTRACT")
        is not expected_code_type
        or dict.get(module_globals, "V2_FUNCTION_CODE_DESCRIPTOR_CONTRACT")
        is not expected_function_code_descriptor
        or dict.get(
            module_globals,
            "V2_FUNCTION_DEFAULTS_DESCRIPTOR_CONTRACT",
        )
        is not expected_function_defaults_descriptor
        or dict.get(
            module_globals,
            "V2_FUNCTION_KEYWORD_DEFAULTS_DESCRIPTOR_CONTRACT",
        )
        is not expected_function_keyword_defaults_descriptor
        or dict.get(
            module_globals,
            "V2_FUNCTION_CLOSURE_DESCRIPTOR_CONTRACT",
        )
        is not expected_function_closure_descriptor
        or dict.get(
            module_globals,
            "V2_FUNCTION_GLOBALS_DESCRIPTOR_CONTRACT",
        )
        is not expected_function_globals_descriptor
    ):
        raise EvidenceFailed(
            "v2 runtime code-contract preflight identity drifted"
        )
    for (
        name,
        pinned_candidate,
        pinned_code,
        pinned_defaults,
        pinned_keyword_defaults,
        pinned_keyword_default_items,
        pinned_closure,
        pinned_closure_contents,
    ) in (
        V2_RUNNER_AUTHORITY_GLOBAL_CONTRACTS
    ):
        current_candidate = dict.get(module_globals, name)
        current_keyword_defaults = (
            V2_FUNCTION_KEYWORD_DEFAULTS_DESCRIPTOR_CONTRACT.__get__(
                pinned_candidate,
                V2_FUNCTION_TYPE_CONTRACT,
            )
        )
        current_keyword_default_items = (
            tuple(dict.items(current_keyword_defaults))
            if type(current_keyword_defaults) is dict
            else None
        )
        current_closure = (
            V2_FUNCTION_CLOSURE_DESCRIPTOR_CONTRACT.__get__(
                pinned_candidate,
                V2_FUNCTION_TYPE_CONTRACT,
            )
            or ()
        )
        try:
            current_closure_contents = tuple(
                cell.cell_contents for cell in current_closure
            )
        except ValueError as error:
            raise EvidenceFailed(
                "v2 runtime runner-authority closure is empty"
            ) from error
        if (
            current_candidate is not pinned_candidate
            or type(pinned_candidate) is not V2_FUNCTION_TYPE_CONTRACT
            or V2_FUNCTION_CODE_DESCRIPTOR_CONTRACT.__get__(
                pinned_candidate,
                V2_FUNCTION_TYPE_CONTRACT,
            )
            is not pinned_code
            or V2_FUNCTION_DEFAULTS_DESCRIPTOR_CONTRACT.__get__(
                pinned_candidate,
                V2_FUNCTION_TYPE_CONTRACT,
            )
            is not pinned_defaults
            or current_keyword_defaults is not pinned_keyword_defaults
            or (
                (current_keyword_default_items is None)
                is not (pinned_keyword_default_items is None)
            )
            or (
                current_keyword_default_items is not None
                and pinned_keyword_default_items is not None
                and (
                    len(current_keyword_default_items)
                    != len(pinned_keyword_default_items)
                    or any(
                        current_key is not pinned_key
                        or current_value is not pinned_value
                        for (
                            current_key,
                            current_value,
                        ), (
                            pinned_key,
                            pinned_value,
                        ) in zip(
                            current_keyword_default_items,
                            pinned_keyword_default_items,
                            strict=True,
                        )
                    )
                )
            )
            or current_closure is not pinned_closure
            or len(current_closure_contents)
            != len(pinned_closure_contents)
            or any(
                current_content is not pinned_content
                for current_content, pinned_content in zip(
                    current_closure_contents,
                    pinned_closure_contents,
                    strict=True,
                )
            )
        ):
            raise EvidenceFailed(
                "v2 runtime runner-authority global dispatch drifted"
            )
    value_binding_names: set[str] = set()
    for name, pinned_value in expected_runner_authority_value_contracts:
        if (
            type(name) is not str
            or not name
            or name in value_binding_names
            or dict.get(module_globals, name) is not pinned_value
        ):
            raise EvidenceFailed(
                "v2 runtime runner-authority value binding drifted"
            )
        value_binding_names.add(name)
    if (
        type(expected_runner_authority_error_class_contracts) is not tuple
        or not expected_runner_authority_error_class_contracts
        or not all(
            v2_runner_error_class_contract_matches(contract)
            for contract in expected_runner_authority_error_class_contracts
        )
    ):
        for contract in expected_runner_authority_error_class_contracts:
            v2_restore_runner_error_class_contract(contract)
        raise EvidenceFailed(
            "v2 runtime runner-authority error-class state drifted"
        )
    if V2CheckCollector is not V2_ASSERTION_COLLECTOR_CLASS_CONTRACT:
        raise EvidenceFailed(
            "v2 runtime assertion collector class identity drifted"
        )
    current_class_dictionary = type.__getattribute__(
        V2CheckCollector,
        "__dict__",
    )
    if (
        frozenset(current_class_dictionary)
        != V2_ASSERTION_COLLECTOR_CLASS_KEYS_CONTRACT
    ):
        raise EvidenceFailed(
            "v2 runtime assertion collector class namespace drifted"
        )
    for name, pinned_descriptor in V2_ASSERTION_COLLECTOR_STORAGE_CONTRACTS:
        if current_class_dictionary[name] is not pinned_descriptor:
            raise EvidenceFailed(
                "v2 runtime assertion collector storage identity drifted"
            )
    for name, pinned_value in V2_ASSERTION_COLLECTOR_CLASS_METADATA_CONTRACTS:
        try:
            current_value = current_class_dictionary[name]
        except KeyError as error:
            raise EvidenceFailed(
                "v2 runtime assertion collector metadata is incomplete"
            ) from error
        if current_value is not pinned_value:
            raise EvidenceFailed(
                "v2 runtime assertion collector metadata identity drifted"
            )
    for name, pinned_descriptor, pinned_candidate in (
        V2_ASSERTION_COLLECTOR_DISPATCH_CONTRACTS
    ):
        try:
            current_descriptor = current_class_dictionary[name]
        except KeyError as error:
            raise EvidenceFailed(
                "v2 runtime assertion collector dispatch is incomplete"
            ) from error
        if current_descriptor is not pinned_descriptor:
            raise EvidenceFailed(
                "v2 runtime assertion collector dispatch identity drifted"
            )
        current_candidate = type.__getattribute__(
            V2CheckCollector,
            name,
        )
        if current_candidate is not pinned_candidate:
            raise EvidenceFailed(
                "v2 runtime assertion collector dispatch identity drifted"
            )
    for (
        candidate,
        pinned_defaults,
        pinned_keyword_defaults,
        pinned_keyword_default_items,
    ) in (
        V2_ASSERTION_COLLECTOR_DEFAULT_CONTRACTS
    ):
        current_defaults = (
            V2_FUNCTION_DEFAULTS_DESCRIPTOR_CONTRACT.__get__(
                candidate,
                V2_FUNCTION_TYPE_CONTRACT,
            )
        )
        current_keyword_defaults = (
            V2_FUNCTION_KEYWORD_DEFAULTS_DESCRIPTOR_CONTRACT.__get__(
                candidate,
                V2_FUNCTION_TYPE_CONTRACT,
            )
        )
        current_keyword_default_items = (
            tuple(dict.items(current_keyword_defaults))
            if type(current_keyword_defaults) is dict
            else None
        )
        if (
            current_defaults is not pinned_defaults
            or current_keyword_defaults is not pinned_keyword_defaults
            or (
                (current_keyword_default_items is None)
                is not (pinned_keyword_default_items is None)
            )
            or (
                current_keyword_default_items is not None
                and pinned_keyword_default_items is not None
                and (
                    len(current_keyword_default_items)
                    != len(pinned_keyword_default_items)
                    or any(
                        current_key is not pinned_key
                        or current_value is not pinned_value
                        for (
                            current_key,
                            current_value,
                        ), (
                            pinned_key,
                            pinned_value,
                        ) in zip(
                            current_keyword_default_items,
                            pinned_keyword_default_items,
                            strict=True,
                        )
                    )
                )
            )
        ):
            raise EvidenceFailed(
                "v2 runtime assertion collector default binding drifted"
            )
    current_refuses_closure = (
        V2_FUNCTION_CLOSURE_DESCRIPTOR_CONTRACT.__get__(
            V2CheckCollector.refuses,
            V2_FUNCTION_TYPE_CONTRACT,
        )
        or ()
    )
    if (
        type(current_refuses_closure) is not tuple
        or len(current_refuses_closure)
        != len(V2_ASSERTION_COLLECTOR_REFUSES_CLOSURE)
        or any(
            current is not pinned
            for current, pinned in zip(
                current_refuses_closure,
                V2_ASSERTION_COLLECTOR_REFUSES_CLOSURE,
                strict=True,
            )
        )
    ):
        raise EvidenceFailed(
            "v2 runtime assertion collector closure identity drifted"
        )
    for (
        cell,
        pinned_function,
        pinned_code,
        pinned_defaults,
        pinned_keyword_defaults,
        pinned_keyword_default_items,
    ) in (
        V2_ASSERTION_COLLECTOR_REFUSES_CLOSURE_CONTRACTS
    ):
        try:
            current_function = cell.cell_contents
        except ValueError as error:
            raise EvidenceFailed(
                "v2 runtime assertion collector closure is empty"
            ) from error
        if type(current_function) is not V2_FUNCTION_TYPE_CONTRACT:
            raise EvidenceFailed(
                "v2 runtime assertion collector closure code identity drifted"
            )
        current_keyword_defaults = (
            V2_FUNCTION_KEYWORD_DEFAULTS_DESCRIPTOR_CONTRACT.__get__(
                current_function,
                V2_FUNCTION_TYPE_CONTRACT,
            )
        )
        current_keyword_default_items = (
            tuple(dict.items(current_keyword_defaults))
            if type(current_keyword_defaults) is dict
            else None
        )
        if (
            current_function is not pinned_function
            or V2_FUNCTION_CODE_DESCRIPTOR_CONTRACT.__get__(
                current_function,
                V2_FUNCTION_TYPE_CONTRACT,
            )
            is not pinned_code
            or V2_FUNCTION_DEFAULTS_DESCRIPTOR_CONTRACT.__get__(
                current_function,
                V2_FUNCTION_TYPE_CONTRACT,
            )
            is not pinned_defaults
            or current_keyword_defaults is not pinned_keyword_defaults
            or (
                (current_keyword_default_items is None)
                is not (pinned_keyword_default_items is None)
            )
            or (
                current_keyword_default_items is not None
                and pinned_keyword_default_items is not None
                and (
                    len(current_keyword_default_items)
                    != len(pinned_keyword_default_items)
                    or any(
                        current_key is not pinned_key
                        or current_value is not pinned_value
                        for (
                            current_key,
                            current_value,
                        ), (
                            pinned_key,
                            pinned_value,
                        ) in zip(
                            current_keyword_default_items,
                            pinned_keyword_default_items,
                            strict=True,
                        )
                    )
                )
            )
        ):
            raise EvidenceFailed(
                "v2 runtime assertion collector closure code identity drifted"
            )


def v2_test_terminal_document(
    *,
    manifest: Mapping[str, Any],
    results: Sequence[Mapping[str, Any]],
    event_roots: Sequence[str],
    selected: str | None,
    terminal: str,
    first_divergence: str | None,
    diagnostic_root: str | None,
    diagnostic_summary: str | None,
    recovery: str,
    failure_scope: str | None,
) -> dict[str, Any]:
    _, validated_results = v2_validate_suite_expected_results(
        manifest,
        selected=selected,
        expected_results=results,
    )
    document = v2_rooted(
        {
            "schema": V2_TEST_TERMINAL_SCHEMA,
            "terminal": terminal,
            "exit_code": TERMINAL_EXIT[terminal],
            "selected": selected,
            "manifest_root": manifest["semantic_root"],
            "manifest_content_identity": manifest["content_identity"],
            "harness_contract_identity": manifest[
                "harness_contract_identity"
            ],
            "case_count": len(validated_results),
            "assertion_count": len(validated_results),
            "check_count": sum(
                int(row["check_count"]) for row in validated_results
            ),
            "ordered_case_ids": [
                row["case_id"] for row in validated_results
            ],
            "ordered_assertion_ids": [
                row["assertion_id"] for row in validated_results
            ],
            "ordered_case_roots": [
                row["semantic_root"] for row in validated_results
            ],
            "ordered_event_roots": list(event_roots),
            "compiled_executor_ids_root": semantic_root(
                sorted(
                    row["assertion_id"]
                    for row in manifest["case"]
                )
            ),
            "skipped_assertions": [],
            "aggregate_count_only": False,
            "failure_scope": failure_scope,
            "first_divergence": first_divergence,
            "diagnostic_root": diagnostic_root,
            "diagnostic_summary": diagnostic_summary,
            "recovery": recovery,
            "no_claim": (
                "the suite proves only its "
                f"{len(validated_results)} selected bounded "
                "executable contracts; it does not mutate or complete live "
                "target Beads"
                if terminal == "Pass"
                else "the v2 suite did not pass"
            ),
        }
    )
    document = v2_validate_test_terminal_document(
        document,
        accepted_manifest=manifest,
        expected_results=validated_results,
        expected_event_roots=event_roots,
        expected_selected=selected,
        expected_terminal=terminal,
        expected_first_divergence=first_divergence,
        expected_diagnostic_root=diagnostic_root,
        expected_diagnostic_summary=diagnostic_summary,
        expected_recovery=recovery,
        expected_failure_scope=failure_scope,
    )
    if type(document) is not dict:
        raise EvidenceFailed("v2 suite-terminal snapshot is not an object")
    return document


