def v2_runner_error_class_contract_matches(contract: Any) -> bool:
    if type(contract) is not tuple or len(contract) != 8:
        return False
    (
        candidate,
        pinned_name,
        pinned_qualname,
        pinned_bases,
        pinned_mro,
        pinned_keys,
        pinned_items,
        pinned_function_contracts,
    ) = contract
    if (
        type(candidate) is not type
        or candidate.__name__ != pinned_name
        or candidate.__qualname__ != pinned_qualname
        or type(pinned_bases) is not tuple
        or type(pinned_mro) is not tuple
        or type(pinned_keys) is not frozenset
        or type(pinned_items) is not tuple
        or type(pinned_function_contracts) is not tuple
        or candidate.__bases__ != pinned_bases
        or candidate.__mro__ != pinned_mro
    ):
        return False
    current = type.__getattribute__(candidate, "__dict__")
    if frozenset(current) != pinned_keys or len(current) != len(pinned_items):
        return False
    if not all(
        name in current and current[name] is pinned_value
        for name, pinned_value in pinned_items
    ):
        return False
    for (
        name,
        pinned_function,
        pinned_code,
        pinned_defaults,
        pinned_keyword_defaults,
        pinned_keyword_default_items,
        pinned_closure,
        pinned_closure_contents,
    ) in pinned_function_contracts:
        if current.get(name) is not pinned_function:
            return False
        current_keyword_defaults = pinned_function.__kwdefaults__
        current_keyword_default_items = (
            tuple(dict.items(current_keyword_defaults))
            if type(current_keyword_defaults) is dict
            else None
        )
        current_closure = pinned_function.__closure__ or ()
        try:
            current_closure_contents = tuple(
                cell.cell_contents for cell in current_closure
            )
        except ValueError:
            return False
        if (
            pinned_function.__code__ is not pinned_code
            or pinned_function.__defaults__ is not pinned_defaults
            or current_keyword_defaults is not pinned_keyword_defaults
            or (
                (current_keyword_default_items is None)
                is not (pinned_keyword_default_items is None)
            )
            or (
                current_keyword_default_items is not None
                and pinned_keyword_default_items is not None
                and (
                    len(current_keyword_default_items)
                    != len(pinned_keyword_default_items)
                    or any(
                        current_key is not pinned_key
                        or current_value is not pinned_value
                        for (
                            current_key,
                            current_value,
                        ), (
                            pinned_key,
                            pinned_value,
                        ) in zip(
                            current_keyword_default_items,
                            pinned_keyword_default_items,
                            strict=True,
                        )
                    )
                )
            )
            or current_closure is not pinned_closure
            or len(current_closure_contents) != len(pinned_closure_contents)
            or any(
                current_value is not pinned_value
                for current_value, pinned_value in zip(
                    current_closure_contents,
                    pinned_closure_contents,
                    strict=True,
                )
            )
        ):
            return False
    return True


def v2_restore_runner_error_class_contract(contract: Any) -> None:
    if type(contract) is not tuple or len(contract) != 8:
        raise RuntimeError("v2 runner error-class contract is malformed")
    (
        candidate,
        pinned_name,
        pinned_qualname,
        pinned_bases,
        _pinned_mro,
        pinned_keys,
        pinned_items,
        pinned_function_contracts,
    ) = contract
    if type(candidate) is not type or type(pinned_bases) is not tuple:
        raise RuntimeError("v2 runner error-class contract is malformed")
    if candidate.__bases__ != pinned_bases:
        type.__setattr__(candidate, "__bases__", pinned_bases)
    if candidate.__name__ != pinned_name:
        type.__setattr__(candidate, "__name__", pinned_name)
    if candidate.__qualname__ != pinned_qualname:
        type.__setattr__(candidate, "__qualname__", pinned_qualname)
    current = type.__getattribute__(candidate, "__dict__")
    for name in tuple(current):
        if name not in pinned_keys:
            type.__delattr__(candidate, name)
    for name, pinned_value in pinned_items:
        current = type.__getattribute__(candidate, "__dict__")
        if current.get(name) is pinned_value:
            continue
        if name in {"__dict__", "__weakref__"}:
            raise RuntimeError(
                "v2 runner error-class intrinsic metadata drifted"
            )
        type.__setattr__(candidate, name, pinned_value)
    for (
        _name,
        pinned_function,
        pinned_code,
        pinned_defaults,
        pinned_keyword_defaults,
        pinned_keyword_default_items,
        pinned_closure,
        pinned_closure_contents,
    ) in pinned_function_contracts:
        pinned_function.__code__ = pinned_code
        pinned_function.__defaults__ = pinned_defaults
        if type(pinned_keyword_defaults) is dict:
            dict.clear(pinned_keyword_defaults)
            for key, value in pinned_keyword_default_items or ():
                dict.__setitem__(pinned_keyword_defaults, key, value)
        pinned_function.__kwdefaults__ = pinned_keyword_defaults
        for cell, pinned_content in zip(
            pinned_closure,
            pinned_closure_contents,
            strict=True,
        ):
            cell.cell_contents = pinned_content
    if not v2_runner_error_class_contract_matches(contract):
        raise RuntimeError("v2 runner error-class restoration failed")


