def run_v2_self_tests(
    manifest: Mapping[str, Any],
    *,
    selected: str | None = None,
) -> dict[str, Any]:
    runner_module_globals = globals()
    runtime_code_preflight_contract = V2_RUNTIME_CODE_PREFLIGHT_CONTRACT
    (
        preflight_callable,
        preflight_code,
        expected_audited_result_paths,
        expected_audited_code_contracts,
        expected_audited_fast_result_registry_contract,
        expected_exact_container_validator_result_contracts,
        expected_collector_code_contracts,
        expected_collector_dispatch_contracts,
        expected_collector_default_contracts,
        expected_collector_class,
        expected_collector_class_keys,
        expected_collector_storage_contracts,
        expected_collector_metadata_contracts,
        expected_refuses_closure,
        expected_refuses_closure_contracts,
        expected_runner_authority_global_contracts,
        expected_runner_authority_value_contracts,
        expected_runner_authority_error_class_contracts,
        expected_terminal_exit_binding_contract,
        expected_function_type,
        expected_code_type,
        expected_function_code_descriptor,
        expected_function_defaults_descriptor,
        expected_function_keyword_defaults_descriptor,
        expected_function_closure_descriptor,
        expected_function_globals_descriptor,
    ) = runtime_code_preflight_contract
    runner_evidence_failed: type[BaseException] | None = None
    for value_name, pinned_value in expected_runner_authority_value_contracts:
        if value_name == "EvidenceFailed":
            runner_evidence_failed = pinned_value
            break
    if type(runner_evidence_failed) is not type:
        raise EvidenceFailed(
            "v2 runtime runner-authority error type is unavailable"
        )
    preflight_identity_drift_marker = RuntimeError(
        "v2 runtime code-contract preflight identity drifted"
    )
    preflight_error_class_drift_marker = RuntimeError(
        "v2 runtime runner-authority error-class state drifted"
    )
    if (
        expected_audited_fast_result_registry_contract
        is not V2_AUDITED_LOCAL_FAST_RESULT_REGISTRY_CONTRACT
    ):
        raise EvidenceFailed(
            "v2 runtime audited fast-result registry identity drifted"
        )
    expected_audited_fast_result_kinds = tuple.__getitem__(
        expected_audited_fast_result_registry_contract,
        0,
    )
    expected_audited_fast_result_contracts = tuple.__getitem__(
        expected_audited_fast_result_registry_contract,
        1,
    )
    if (
        V2_AUDITED_LOCAL_FAST_RESULT_KINDS
        is not expected_audited_fast_result_kinds
        or V2_AUDITED_LOCAL_FAST_RESULT_CONTRACTS
        is not expected_audited_fast_result_contracts
    ):
        raise EvidenceFailed(
            "v2 runtime audited fast-result registry members drifted"
        )
    runner_publication_sink = dict.get(runner_module_globals, "json_stdout")
    if type(runner_publication_sink) is not expected_function_type:
        raise EvidenceFailed(
            "v2 runtime publication sink is not an exact function"
        )
    runner_publication_sink_code = (
        expected_function_code_descriptor.__get__(
            runner_publication_sink,
            expected_function_type,
        )
    )
    runner_publication_sink_defaults = (
        expected_function_defaults_descriptor.__get__(
            runner_publication_sink,
            expected_function_type,
        )
    )
    runner_publication_sink_keyword_defaults = (
        expected_function_keyword_defaults_descriptor.__get__(
            runner_publication_sink,
            expected_function_type,
        )
    )
    runner_publication_sink_keyword_default_items = (
        tuple(dict.items(runner_publication_sink_keyword_defaults))
        if type(runner_publication_sink_keyword_defaults) is dict
        else None
    )
    runner_publication_sink_closure = (
        expected_function_closure_descriptor.__get__(
            runner_publication_sink,
            expected_function_type,
        )
        or ()
    )
    try:
        runner_publication_sink_closure_contents = tuple(
            cell.cell_contents for cell in runner_publication_sink_closure
        )
    except ValueError as error:
        raise EvidenceFailed(
            "v2 runtime publication-sink closure is empty"
        ) from error
    if (
        type(expected_terminal_exit_binding_contract) is not tuple
        or len(expected_terminal_exit_binding_contract) != 2
    ):
        raise EvidenceFailed(
            "v2 runtime terminal-exit binding contract is malformed"
        )
    runner_terminal_exit, runner_terminal_exit_items = (
        expected_terminal_exit_binding_contract
    )
    if (
        type(runner_terminal_exit) is not dict
        or type(runner_terminal_exit_items) is not tuple
    ):
        raise EvidenceFailed(
            "v2 runtime terminal-exit binding contract is malformed"
        )

    def validate_runner_publication_contracts() -> None:
        current_sink_keyword_defaults = (
            expected_function_keyword_defaults_descriptor.__get__(
                runner_publication_sink,
                expected_function_type,
            )
        )
        current_sink_keyword_default_items = (
            tuple(dict.items(current_sink_keyword_defaults))
            if type(current_sink_keyword_defaults) is dict
            else None
        )
        current_sink_closure = (
            expected_function_closure_descriptor.__get__(
                runner_publication_sink,
                expected_function_type,
            )
            or ()
        )
        try:
            current_sink_closure_contents = tuple(
                cell.cell_contents for cell in current_sink_closure
            )
        except ValueError as error:
            raise EvidenceFailed(
                "v2 runtime publication-sink closure is empty"
            ) from error
        current_terminal_exit_items = tuple(
            dict.items(runner_terminal_exit)
        )
        if (
            dict.get(runner_module_globals, "json_stdout")
            is not runner_publication_sink
            or expected_function_code_descriptor.__get__(
                runner_publication_sink,
                expected_function_type,
            )
            is not runner_publication_sink_code
            or expected_function_defaults_descriptor.__get__(
                runner_publication_sink,
                expected_function_type,
            )
            is not runner_publication_sink_defaults
            or current_sink_keyword_defaults
            is not runner_publication_sink_keyword_defaults
            or (
                (current_sink_keyword_default_items is None)
                is not (
                    runner_publication_sink_keyword_default_items is None
                )
            )
            or (
                current_sink_keyword_default_items is not None
                and runner_publication_sink_keyword_default_items is not None
                and (
                    len(current_sink_keyword_default_items)
                    != len(runner_publication_sink_keyword_default_items)
                    or any(
                        current_key is not pinned_key
                        or current_value is not pinned_value
                        for (
                            current_key,
                            current_value,
                        ), (
                            pinned_key,
                            pinned_value,
                        ) in zip(
                            current_sink_keyword_default_items,
                            runner_publication_sink_keyword_default_items,
                            strict=True,
                        )
                    )
                )
            )
            or current_sink_closure is not runner_publication_sink_closure
            or len(current_sink_closure_contents)
            != len(runner_publication_sink_closure_contents)
            or any(
                current_content is not pinned_content
                for current_content, pinned_content in zip(
                    current_sink_closure_contents,
                    runner_publication_sink_closure_contents,
                    strict=True,
                )
            )
            or dict.get(runner_module_globals, "TERMINAL_EXIT")
            is not runner_terminal_exit
            or type(runner_terminal_exit) is not dict
            or len(current_terminal_exit_items)
            != len(runner_terminal_exit_items)
            or any(
                current_key is not pinned_key
                or current_value is not pinned_value
                for (
                    current_key,
                    current_value,
                ), (
                    pinned_key,
                    pinned_value,
                ) in zip(
                    current_terminal_exit_items,
                    runner_terminal_exit_items,
                    strict=True,
                )
            )
        ):
            raise EvidenceFailed(
                "v2 runtime publication authority drifted"
            )

