    def validate_runtime_code_postflight() -> None:
        try:
            validate_runtime_code_preflight()
        except BaseException as primary_error:
            try:
                restore_runtime_code_preflight()
                validate_runtime_code_preflight()
            except BaseException as cleanup_error:
                v2_attach_cleanup_note(primary_error, cleanup_error)
                raise primary_error
            if primary_error is preflight_identity_drift_marker or (
                primary_error is preflight_error_class_drift_marker
            ):
                raise runner_evidence_failed(str(primary_error)) from primary_error
            raise primary_error

    validate_runtime_code_postflight()
    accepted_manifest = v2_clone_runner_manifest(manifest)
    manifest = accepted_manifest
    try:
        registry = v2_build_executor_registry(manifest)
    except BaseException as registry_error:
        try:
            validate_runtime_code_postflight()
        except BaseException as postflight_error:
            v2_attach_cleanup_note(postflight_error, registry_error)
            raise postflight_error
        raise
    validate_runtime_code_postflight()
    accepted_obligations = v2_validate_check_obligation_registry(
        manifest["case"],
        manifest["check_obligations"],
        error_type=EvidenceFailed,
    )
    obligations_by_assertion: dict[str, dict[str, Any]] = {}
    for manifest_case in manifest["case"]:
        manifest_assertion_id = manifest_case["assertion_id"]
        accepted = v2_validate_check_obligation(
            manifest_case,
            accepted_obligations.get(manifest_assertion_id),
            error_type=EvidenceFailed,
        )
        obligations_by_assertion[manifest_assertion_id] = {
            "case_id": accepted["case_id"],
            "check_count": accepted["check_count"],
            "ordered_check_ids": list(accepted["ordered_check_ids"]),
        }
    cases = [
        row
        for row in manifest["case"]
        if selected is None or row["id"] == selected
    ]
    if selected is not None and not cases:
        raise UsageRefused(f"unknown v2 case: {selected}")
    results: list[dict[str, Any]] = []
    event_roots: list[str] = []
    sequence = 0

    def fail_suite_boundary(
        caught_error: BaseException,
        *,
        fallback: str,
    ) -> None:
        error, terminal, _internal_fault = v2_normalize_runner_error(
            caught_error,
            cancellation_message=(
                "keyboard cancellation drained at the suite boundary"
            ),
        )
        note_projection = v2_exception_note_projection(caught_error)
        diagnostic = v2_runner_diagnostic(
            error,
            note_projection=note_projection,
        )
        diagnostic_summary = v2_bounded_diagnostic_summary(diagnostic)
        first_divergence = v2_bounded_first_divergence(
            diagnostic,
            fallback=fallback,
        )
        _, recovery = v2_runner_failure_policy(terminal)
        suite_failure = v2_test_terminal_document(
            manifest=manifest,
            results=results,
            event_roots=event_roots,
            selected=selected,
            terminal=terminal,
            first_divergence=first_divergence,
            diagnostic_root=text_root(diagnostic),
            diagnostic_summary=diagnostic_summary,
            recovery=recovery,
            failure_scope="suite-boundary",
        )
        v2_emit_test_document(
            suite_failure,
            accepted_manifest=manifest,
            expected_results=results,
            expected_event_roots=event_roots,
            expected_selected=selected,
            expected_terminal=terminal,
            expected_first_divergence=first_divergence,
            expected_diagnostic_root=text_root(diagnostic),
            expected_diagnostic_summary=diagnostic_summary,
            expected_recovery=recovery,
            expected_failure_scope="suite-boundary",
        )
        raise SystemExit(TERMINAL_EXIT[terminal])

    for case in cases:
        try:
            check_cancel()
        except BaseException as caught_error:
            fail_suite_boundary(
                caught_error,
                fallback="before-assertion-start",
            )
        assertion_id = case["assertion_id"]
        obligation = v2_validate_check_obligation(
            case,
            obligations_by_assertion.get(assertion_id),
            error_type=EvidenceFailed,
        )
        start = v2_test_log_event(
            case=case,
            obligation=obligation,
            harness_contract_identity=manifest["harness_contract_identity"],
            sequence=sequence,
            stage="assertion-start",
        )
        v2_emit_test_document(
            start,
            accepted_manifest=manifest,
            expected_case=case,
            expected_obligation=obligation,
            expected_sequence=sequence,
            expected_stage="assertion-start",
            expected_terminal=None,
        )
        event_roots.append(start["semantic_root"])
        sequence += 1
        executor = registry.get(case["assertion_id"])
        try:
            if executor is None:
                raise EvidenceFailed(
                    f"{case['assertion_id']} has no exact compiled executor"
                )
            executor_manifest = v2_clone_runner_manifest(manifest)
            executor_case = strict_json_loads(
                canonical_bytes(case),
                label=f"{case['assertion_id']} executor case snapshot",
                require_canonical=True,
            )
            executor_manifest_before = canonical_bytes(executor_manifest)
            executor_case_before = canonical_bytes(executor_case)
            validate_runtime_code_postflight()
            try:
                result = executor(executor_case, executor_manifest)
            except BaseException as executor_error:
                try:
                    validate_runtime_code_postflight()
                except BaseException as postflight_error:
                    v2_attach_cleanup_note(
                        postflight_error,
                        executor_error,
                    )
                    raise postflight_error
                raise
            validate_runtime_code_postflight()
            check_cancel()
            try:
                executor_manifest_after = canonical_bytes(
                    executor_manifest
                )
                executor_case_after = canonical_bytes(executor_case)
            except (
                TypeError,
                ValueError,
                OverflowError,
                RecursionError,
            ) as error:
                raise EvidenceFailed(
                    f"{case['assertion_id']} made its accepted case or "
                    "manifest snapshot noncanonical"
                ) from error
            if (
                executor_manifest_after != executor_manifest_before
                or executor_case_after != executor_case_before
            ):
                raise EvidenceFailed(
                    f"{case['assertion_id']} mutated its accepted case or "
                    "manifest snapshot"
                )
            result = v2_validate_assertion_result(
                case,
                result,
                obligation,
            )
            check_cancel()
            terminal_event = v2_test_log_event(
                case=case,
                obligation=obligation,
                harness_contract_identity=manifest[
                    "harness_contract_identity"
                ],
                sequence=sequence,
                stage="assertion-terminal",
                result=result,
                terminal="Pass",
            )
            v2_validate_log_line_payload(
                canonical_bytes(terminal_event),
                label=f"{case['assertion_id']} terminal event",
            )
            v2_emit_test_document(
                result,
                accepted_manifest=manifest,
                expected_case=case,
                expected_obligation=obligation,
            )
            v2_emit_test_document(
                terminal_event,
                accepted_manifest=manifest,
                expected_case=case,
                expected_obligation=obligation,
                expected_sequence=sequence,
                expected_stage="assertion-terminal",
                expected_result=result,
                expected_terminal="Pass",
            )
            event_roots.append(terminal_event["semantic_root"])
            sequence += 1
            results.append(result)
        except OutputPublicationFailed:
            raise
        except BaseException as caught_error:
            error, terminal, internal_fault = v2_normalize_runner_error(
                caught_error,
                cancellation_message=(
                    "keyboard cancellation drained at the assertion boundary"
                ),
            )
            note_projection = v2_exception_note_projection(caught_error)
            diagnostic = v2_runner_diagnostic(
                error,
                note_projection=note_projection,
            )
            diagnostic_summary = v2_bounded_diagnostic_summary(diagnostic)
            first_divergence = v2_bounded_first_divergence(
                diagnostic,
                fallback=str(case["assertion_id"]),
            )
            failed = v2_test_log_event(
                case=case,
                obligation=obligation,
                harness_contract_identity=manifest[
                    "harness_contract_identity"
                ],
                sequence=sequence,
                stage="assertion-terminal",
                terminal=terminal,
            )
            failed["first_divergence"] = first_divergence
            (
                failed["result_category"],
                failed["recovery"],
            ) = v2_runner_failure_policy(
                terminal
            )
            failure_projection = v2_build_test_failure_projection(
                error=error,
                note_source=caught_error,
                diagnostic_code=first_divergence,
                unexpected_exception_type=(
                    v2_exception_type_projection(type(caught_error))
                    if internal_fault
                    else None
                ),
                subject=case["subject"],
                check_obligation_root=v2_check_obligation_root(
                    case,
                    obligation,
                ),
                harness_contract_identity=manifest[
                    "harness_contract_identity"
                ],
                note_projection=note_projection,
            )
            failed["semantic_projection"] = failure_projection
            failed = v2_rooted(failed)
            v2_emit_test_document(
                failed,
                accepted_manifest=manifest,
                expected_case=case,
                expected_obligation=obligation,
                expected_sequence=sequence,
                expected_stage="assertion-terminal",
                expected_projection=failure_projection,
                expected_terminal=terminal,
            )
            event_roots.append(failed["semantic_root"])
            suite_failure = v2_test_terminal_document(
                manifest=manifest,
                results=results,
                event_roots=event_roots,
                selected=selected,
                terminal=terminal,
                first_divergence=first_divergence,
                diagnostic_root=text_root(diagnostic),
                diagnostic_summary=diagnostic_summary,
                recovery=failed["recovery"],
                failure_scope="assertion",
            )
            v2_emit_test_document(
                suite_failure,
                accepted_manifest=manifest,
                expected_results=results,
                expected_event_roots=event_roots,
                expected_selected=selected,
                expected_terminal=terminal,
                expected_first_divergence=first_divergence,
                expected_diagnostic_root=text_root(diagnostic),
                expected_diagnostic_summary=diagnostic_summary,
                expected_recovery=failed["recovery"],
                expected_failure_scope="assertion",
            )
            raise SystemExit(TERMINAL_EXIT[terminal])
    try:
        check_cancel()
    except BaseException as caught_error:
        fail_suite_boundary(
            caught_error,
            fallback="before-suite-terminal",
        )
    terminal = v2_test_terminal_document(
        manifest=manifest,
        results=results,
        event_roots=event_roots,
        selected=selected,
        terminal="Pass",
        first_divergence=None,
        diagnostic_root=None,
        diagnostic_summary=None,
        recovery="NOT_REQUIRED",
        failure_scope=None,
    )
    v2_emit_test_document(
        terminal,
        accepted_manifest=manifest,
        expected_results=results,
        expected_event_roots=event_roots,
        expected_selected=selected,
        expected_terminal="Pass",
        expected_first_divergence=None,
        expected_diagnostic_root=None,
        expected_diagnostic_summary=None,
        expected_recovery="NOT_REQUIRED",
        expected_failure_scope=None,
    )
    return terminal


def v2_raw_invocation_mode(arguments: Sequence[str]) -> str | None:
    for argument in arguments:
        for option, mode in (
            ("--self-test-v2", "self-test-v2"),
            ("--case-v2", "case-v2"),
            ("--review-plan", "review-plan"),
            ("--history-plan", "history-plan"),
            ("--replay-v2", "replay-v2"),
        ):
            if argument == option or argument.startswith(option + "="):
                return mode
    return None


V2_PREFLIGHT_RECOVERY_BY_TERMINAL = {
    "UsageRefused": "CORRECT_ARGUMENTS_AND_RETRY",
    "InputRefused": "CORRECT_ACCEPTED_INPUT_AND_RETRY",
    "NoData": "PROVIDE_REQUIRED_DATA_AND_RETRY",
    "EvidenceFailed": "FIX_HARNESS_OR_CONTRACT_AND_RETRY",
    "CancelledDrained": "RETRY_AFTER_CANCELLATION",
    "InfrastructureFailed": "RESTORE_INFRASTRUCTURE_AND_RETRY",
    "InternalFault": "FIX_INTERNAL_FAULT_AND_RETRY",
}

V2_PREFLIGHT_MODES = frozenset(
    {
        "self-test-v2",
        "case-v2",
        "review-plan",
        "history-plan",
        "replay-v2",
    }
)

V2_EXECUTION_CONTEXT_BY_MODE = {
    "self-test-v2": ("TEST_RUNNER", "NOT_APPLICABLE"),
    "case-v2": ("TEST_RUNNER", "NOT_APPLICABLE"),
    "review-plan": (
        "LIVE_PLANNER",
        "MAY_CONTAIN_INCOMPLETE_RESERVED_PREFIX",
    ),
    "history-plan": (
        "LIVE_PLANNER",
        "MAY_CONTAIN_INCOMPLETE_RESERVED_PREFIX",
    ),
    "replay-v2": (
        "OFFLINE_REPLAY",
        "MAY_CONTAIN_INCOMPLETE_RESERVED_PREFIX",
    ),
}


def v2_validate_preflight_terminal_document(
    document: Mapping[str, Any],
) -> None:
    if (
        type(document) is not dict
        or set(document) != V2_PREFLIGHT_TERMINAL_FIELDS
    ):
        raise EvidenceFailed("v2 preflight terminal has a non-closed schema")
    if (
        type(document["schema"]) is not str
        or document["schema"] != V2_PREFLIGHT_TERMINAL_SCHEMA
        or type(document["terminal"]) is not str
        or document["terminal"] not in TERMINAL_EXIT
        or document["terminal"] == "Pass"
        or type(document["exit_code"]) is not int
        or document["exit_code"]
        != TERMINAL_EXIT[document["terminal"]]
        or type(document["mode"]) is not str
        or document["mode"] not in V2_PREFLIGHT_MODES
        or type(document["first_divergence"]) is not str
        or not str.strip(document["first_divergence"])
        or len(str.encode(document["first_divergence"], "utf-8"))
        > V2_FIRST_DIVERGENCE_BYTES_CAP
        or type(document["diagnostic_root"]) is not str
        or re.fullmatch(
            r"sha256-v1:[0-9a-f]{64}",
            document["diagnostic_root"],
        )
        is None
        or type(document["diagnostic_summary"]) is not str
        or not str.strip(document["diagnostic_summary"])
        or len(str.encode(document["diagnostic_summary"], "utf-8"))
        > V2_DIAGNOSTIC_SUMMARY_BYTES_CAP
        or type(document["recovery"]) is not str
        or document["recovery"]
        != V2_PREFLIGHT_RECOVERY_BY_TERMINAL[document["terminal"]]
        or type(document["no_claim"]) is not str
        or document["no_claim"]
        != (
            "the preflight terminal records a typed failure before accepted "
            "v2 execution and mints no assertion, artifact, tracker, or "
            "release authority"
        )
    ):
        raise EvidenceFailed("v2 preflight terminal contract differs")
    verify_semantic_root(document, label="v2 preflight terminal")


def v2_preflight_terminal_document(
    error: BaseException,
    *,
    mode: str,
) -> dict[str, Any]:
    error_type = type(error)
    terminal = v2_sealed_error_terminal(error)
    error_type_name = v2_exception_type_projection(error_type)
    diagnostic_summary = v2_bounded_diagnostic_summary(error)
    diagnostic = f"{error_type_name}: {diagnostic_summary}"
    recovery = V2_PREFLIGHT_RECOVERY_BY_TERMINAL.get(
        terminal,
        "FIX_INTERNAL_FAULT_AND_RETRY",
    )
    document = v2_rooted(
        {
            "schema": V2_PREFLIGHT_TERMINAL_SCHEMA,
            "terminal": terminal,
            "exit_code": TERMINAL_EXIT[terminal],
            "mode": mode,
            "first_divergence": v2_bounded_first_divergence(
                diagnostic,
                fallback=mode,
            ),
            "diagnostic_root": text_root(diagnostic),
            "diagnostic_summary": diagnostic_summary,
            "recovery": recovery,
            "no_claim": (
                "the preflight terminal records a typed failure before "
                "accepted v2 execution and mints no assertion, artifact, "
                "tracker, or release authority"
            ),
        }
    )
    v2_validate_preflight_terminal_document(document)
    return document


def v2_validate_execution_terminal_document(
    document: Mapping[str, Any],
) -> None:
    if type(document) is not dict:
        raise EvidenceFailed("v2 execution terminal is not an object")
    if set(document) != V2_EXECUTION_TERMINAL_FIELDS:
        raise EvidenceFailed(
            "v2 execution terminal has a non-closed schema"
    )
    terminal = document["terminal"]
    mode = document["mode"]
    if (
        type(mode) is not str
        or type(V2_EXECUTION_CONTEXT_BY_MODE) is not dict
        or not dict.__contains__(V2_EXECUTION_CONTEXT_BY_MODE, mode)
    ):
        raise EvidenceFailed("v2 execution terminal mode is malformed")
    expected_context = V2_EXECUTION_CONTEXT_BY_MODE[mode]
    if (
        type(expected_context) is not tuple
        or len(expected_context) != 2
    ):
        raise EvidenceFailed(
            "v2 execution terminal mode context is malformed"
        )
    expected_phase, expected_artifact_state = expected_context
    if (
        type(expected_phase) is not str
        or type(expected_artifact_state) is not str
    ):
        raise EvidenceFailed(
            "v2 execution terminal mode context scalars are malformed"
        )
    if (
        type(document["schema"]) is not str
        or document["schema"] != V2_EXECUTION_TERMINAL_SCHEMA
        or type(terminal) is not str
        or terminal not in TERMINAL_EXIT
        or terminal == "Pass"
        or type(document["exit_code"]) is not int
        or document["exit_code"] != TERMINAL_EXIT[terminal]
        or type(document["manifest_root"]) is not str
        or re.fullmatch(
            r"sha256-v1:[0-9a-f]{64}",
            document["manifest_root"],
        )
        is None
        or type(document["phase"]) is not str
        or document["phase"]
        != expected_phase
        or type(document["artifact_state"]) is not str
        or document["artifact_state"]
        != expected_artifact_state
        or type(document["complete_evidence_bundle"]) is not bool
        or document["complete_evidence_bundle"] is not False
        or type(document["first_divergence"]) is not str
        or not str.strip(document["first_divergence"])
        or len(str.encode(document["first_divergence"], "utf-8"))
        > V2_FIRST_DIVERGENCE_BYTES_CAP
        or type(document["diagnostic_root"]) is not str
        or re.fullmatch(
            r"sha256-v1:[0-9a-f]{64}",
            document["diagnostic_root"],
        )
        is None
        or type(document["diagnostic_summary"]) is not str
        or not str.strip(document["diagnostic_summary"])
        or len(str.encode(document["diagnostic_summary"], "utf-8"))
        > V2_DIAGNOSTIC_SUMMARY_BYTES_CAP
        or type(document["recovery"]) is not str
        or document["recovery"]
        != V2_PREFLIGHT_RECOVERY_BY_TERMINAL[terminal]
        or type(document["no_claim"]) is not str
        or document["no_claim"]
        != (
            "the execution terminal records a failure after accepted v2 "
            "manifest loading; evidence may be incomplete and any reserved "
            "artifact prefix is not claimed complete; it mints no tracker, "
            "implementation, product, or release authority"
        )
    ):
        raise EvidenceFailed("v2 execution terminal contract differs")
    verify_semantic_root(document, label="v2 execution terminal")


def v2_execution_terminal_document(
    error: BaseException,
    *,
    context: Mapping[str, str],
) -> dict[str, Any]:
    error_type = type(error)
    terminal = v2_sealed_error_terminal(error)
    error_type_name = v2_exception_type_projection(error_type)
    diagnostic_summary = v2_bounded_diagnostic_summary(error)
    diagnostic = f"{error_type_name}: {diagnostic_summary}"
    document = v2_rooted(
        {
            "schema": V2_EXECUTION_TERMINAL_SCHEMA,
            "terminal": terminal,
            "exit_code": TERMINAL_EXIT[terminal],
            "mode": context["mode"],
            "manifest_root": context["manifest_root"],
            "phase": context["phase"],
            "artifact_state": context["artifact_state"],
            "complete_evidence_bundle": False,
            "first_divergence": v2_bounded_first_divergence(
                diagnostic,
                fallback=context["phase"],
            ),
            "diagnostic_root": text_root(diagnostic),
            "diagnostic_summary": diagnostic_summary,
            "recovery": V2_PREFLIGHT_RECOVERY_BY_TERMINAL.get(
                terminal,
                "FIX_INTERNAL_FAULT_AND_RETRY",
            ),
            "no_claim": (
                "the execution terminal records a failure after accepted v2 "
                "manifest loading; evidence may be incomplete and any "
                "reserved artifact prefix is not claimed complete; it mints "
                "no tracker, implementation, product, or release authority"
            ),
        }
    )
    v2_validate_execution_terminal_document(document)
    return document


class HarnessArgumentParser(argparse.ArgumentParser):
    def error(self, message: str) -> None:
        raise UsageRefused(message)


def preflight_arguments(arguments: Sequence[str]) -> set[str]:
    seen: set[str] = set()
    for value in arguments:
        if not value.startswith("--"):
            continue
        option = value.split("=", 1)[0]
        if option == "--output":
            raise UsageRefused("--output is unsupported; use --artifact-root/--artifact-dir")
        if option in seen:
            raise UsageRefused(f"duplicate option is forbidden: {option}")
        seen.add(option)
    return seen


def parse_arguments(arguments: Sequence[str]) -> argparse.Namespace:
    provided = preflight_arguments(arguments)
    parser = HarnessArgumentParser(
        prog=str(SCRIPT_REL),
        description=(
            "Freeze, classify, plan, replay, and explicitly apply exact Beads "
            "template-hygiene work without inventing semantic criteria."
        ),
        allow_abbrev=False,
    )
    modes = parser.add_mutually_exclusive_group(required=True)
    modes.add_argument("--list", action="store_true", help="list frozen case IDs")
    modes.add_argument("--check", action="store_true", help="validate live inventory")
    modes.add_argument("--self-test", action="store_true", help="run all 21 cases")
    modes.add_argument("--inventory", action="store_true", help="write live inventory")
    modes.add_argument("--plan", action="store_true", help="write live review plan")
    modes.add_argument("--apply-manifest", metavar="REL")
    modes.add_argument("--negative", metavar="CASE")
    modes.add_argument(
        "--replay",
        metavar="REL",
        help=(
            "replay a retained v1 bundle or schema-autodetect a retained v2 bundle"
        ),
    )
    modes.add_argument(
        "--replay-v2",
        metavar="REL",
        help=(
            "replay an explicitly versioned v2 bundle without live tracker reads"
        ),
    )
    modes.add_argument("--closeout", action="store_true", help="require zero lint debt")
    modes.add_argument(
        "--review-plan",
        action="store_true",
        help="emit the normalized bounded v2 review plan",
    )
    modes.add_argument(
        "--history-plan",
        action="store_true",
        help="emit immutable v2 closed-history accounting",
    )
    modes.add_argument(
        "--self-test-v2",
        action="store_true",
        help="run all 96 executable v2 assertions",
    )
    modes.add_argument("--case-v2", metavar="CASE")
    parser.add_argument(
        "--artifact-root",
        default="target/beads-template-hygiene",
        help="repository-relative artifact root",
    )
    parser.add_argument(
        "--artifact-dir",
        help="repository-relative directory below artifact root for write modes",
    )
    parser.add_argument(
        "--review-receipts",
        metavar="REL",
        help="safe relative closed review-receipt JSON",
    )
    parser.add_argument(
        "--prior-campaign",
        metavar="REL",
        help="safe relative retained prior v2 campaign bundle",
    )
    parser.add_argument(
        "--priorities",
        metavar="P0,P1,...",
        help="exact comma-separated v2 priority filter",
    )
    parser.add_argument(
        "--statuses",
        metavar="open,closed,...",
        help="exact comma-separated v2 status filter",
    )
    parser.add_argument(
        "--targets",
        metavar="ID,ID,...",
        help="exact comma-separated v2 target-ID filter",
    )
    parser.add_argument(
        "--readiness",
        metavar="STATE,STATE,...",
        help="exact comma-separated review-plan readiness filter",
    )
    parser.add_argument(
        "--routes",
        metavar="ROUTE,ROUTE,...",
        help="exact comma-separated review-plan remediation-route filter",
    )
    parser.add_argument(
        "--max-targets-per-child",
        type=int,
        default=V2_REVIEW_TARGET_DEFAULT,
        metavar="N",
        help="bounded v2 child target cap (1..25)",
    )
    parser.add_argument(
        "--explain-target",
        metavar="ID",
        help="include a bounded explanation for one selected target",
    )
    parsed = parser.parse_args(arguments)
    parsed.provided_options = frozenset(provided)
    return parsed


def require_v2_artifact_grammar(parsed: argparse.Namespace) -> str:
    if "--artifact-root" not in parsed.provided_options:
        raise UsageRefused("--artifact-root is required for v2 artifact modes")
    if "--artifact-dir" not in parsed.provided_options:
        raise UsageRefused("--artifact-dir is required for v2 artifact modes")
    if not 1 <= parsed.max_targets_per_child <= V2_REVIEW_TARGET_HARD_MAX:
        raise UsageRefused(
            f"--max-targets-per-child must be in 1..{V2_REVIEW_TARGET_HARD_MAX}"
        )
    return require_artifact_dir(parsed)


def require_artifact_dir(arguments: argparse.Namespace) -> str:
    if not arguments.artifact_dir:
        raise UsageRefused("--artifact-dir is required for modes that write artifacts")
    safe_relative(arguments.artifact_dir, label="artifact dir")
    return arguments.artifact_dir


def v2_abort_after_output_failure(
    error: OutputPublicationFailed,
) -> None:
    commit_state = (
        str(error.bytes_committed)
        if error.bytes_committed is not None
        else "unknown"
    )
    try:
        sys.stderr.write(
            "InfrastructureFailed: canonical JSONL output may be incomplete; "
            f"bytes_committed={commit_state}; output was not retried\n"
        )
        sys.stderr.flush()
    except BaseException:
        pass
    raise SystemExit(TERMINAL_EXIT["InfrastructureFailed"])


def v2_publish_outer_document(document: Mapping[str, Any]) -> None:
    try:
        json_stdout(document)
    except OutputPublicationFailed as error:
        v2_abort_after_output_failure(error)


def v2_outer_failure_document(
    error: BaseException,
    *,
    raw_mode: str | None,
    execution_context: Mapping[str, str] | None,
) -> dict[str, Any] | None:
    if execution_context is not None:
        return v2_execution_terminal_document(
            error,
            context=execution_context,
        )
    if raw_mode is not None:
        return v2_preflight_terminal_document(
            error,
            mode=raw_mode,
        )
    return None


def main(arguments: Sequence[str]) -> int:
    global _v2_outer_execution_context, _v2_outer_mode
    parsed = parse_arguments(arguments)
    v2_auxiliary_options = {
        "--review-receipts",
        "--prior-campaign",
        "--priorities",
        "--statuses",
        "--targets",
        "--readiness",
        "--routes",
        "--max-targets-per-child",
        "--explain-target",
    }

    if parsed.self_test_v2 or parsed.case_v2:
        if parsed.provided_options & {
            "--artifact-root",
            "--artifact-dir",
            *v2_auxiliary_options,
        }:
            raise UsageRefused("v2 test-runner modes do not accept planner options")
        manifest_v2 = load_case_manifest_v2()
        _v2_outer_execution_context = {
            "mode": (
                "self-test-v2" if parsed.self_test_v2 else "case-v2"
            ),
            "manifest_root": manifest_v2["semantic_root"],
            "phase": "TEST_RUNNER",
            "artifact_state": "NOT_APPLICABLE",
        }
        run_v2_self_tests(manifest_v2, selected=parsed.case_v2)
        return 0

    if parsed.review_plan or parsed.history_plan:
        manifest_v2 = load_case_manifest_v2()
        _v2_outer_execution_context = {
            "mode": (
                "review-plan" if parsed.review_plan else "history-plan"
            ),
            "manifest_root": manifest_v2["semantic_root"],
            "phase": "LIVE_PLANNER",
            "artifact_state": (
                "MAY_CONTAIN_INCOMPLETE_RESERVED_PREFIX"
            ),
        }
        synopsis = v2_execute_live_plan(
            mode="review-plan" if parsed.review_plan else "history-plan",
            parsed=parsed,
            manifest=manifest_v2,
        )
        json_stdout(synopsis)
        return 0

    replay_input = parsed.replay_v2 or parsed.replay
    if replay_input:
        schema = peek_replay_schema(parsed.artifact_root, replay_input)
        if parsed.replay_v2 and schema != V2_TERMINAL_SCHEMA:
            raise InputRefused(
                "--replay-v2 requires a retained v2 terminal schema"
            )
        if schema == V2_TERMINAL_SCHEMA:
            _v2_outer_mode = "replay-v2"
            if parsed.provided_options & v2_auxiliary_options:
                raise UsageRefused("v2 replay does not accept live planner options")
            artifact_dir = require_v2_artifact_grammar(parsed)
            manifest_v2 = load_case_manifest_v2()
            _v2_outer_execution_context = {
                "mode": "replay-v2",
                "manifest_root": manifest_v2["semantic_root"],
                "phase": "OFFLINE_REPLAY",
                "artifact_state": (
                    "MAY_CONTAIN_INCOMPLETE_RESERVED_PREFIX"
                ),
            }
            replay_result = v2_replay_bundle(
                artifact_root=parsed.artifact_root,
                input_dir=replay_input,
                output_dir=artifact_dir,
                accepted_manifest=manifest_v2,
            )
            json_stdout(replay_result)
            return 0
        if schema != RUN_TERMINAL_SCHEMA:
            raise InputRefused("replay terminal schema is neither frozen v1 nor v2")
        if parsed.provided_options & v2_auxiliary_options:
            raise UsageRefused("v1 replay does not accept v2 planner options")
        case_manifest = load_case_manifest()
        artifact_dir = require_artifact_dir(parsed)
        result = replay_bundle(
            artifact_root=parsed.artifact_root,
            input_dir=replay_input,
            output_dir=artifact_dir,
            case_manifest_root=case_manifest["semantic_root"],
        )
        json_stdout(result)
        return 0

    if parsed.provided_options & v2_auxiliary_options:
        raise UsageRefused("v1 modes do not accept v2 planner options")
    case_manifest = load_case_manifest()

    if parsed.list:
        for sequence, row in enumerate(case_manifest["case"]):
            json_stdout(
                {
                    "schema": EVENT_SCHEMA,
                    "mode": "list",
                    "sequence": sequence,
                    "case": row["id"],
                    "role": row["role"],
                    "case_mode": row["mode"],
                    "expected_terminal": row["expected_terminal"],
                    "expected_exit": row["expected_exit"],
                    "mutation": row["mutation"],
                    "replay": row["replay"],
                    "authority": row["authority"],
                }
            )
        json_stdout(
            terminal_row(
                "Pass",
                mode="list",
                detail=f"listed {len(case_manifest['case'])} frozen cases",
                extra={
                    "sequence": len(case_manifest["case"]),
                    "case_manifest_root": case_manifest["semantic_root"],
                },
            )
        )
        return 0

    if parsed.self_test:
        run_self_tests(case_manifest)
        return 0

    if parsed.negative:
        row = next(
            (row for row in case_manifest["case"] if row["id"] == parsed.negative),
            None,
        )
        if row is None:
            raise UsageRefused(f"unknown case: {parsed.negative}")
        if row["role"] not in {"negative", "hostile"}:
            raise UsageRefused(f"{parsed.negative} is not a frozen negative case")
        run_self_tests(case_manifest, selected=parsed.negative)
        return 0

    snapshot = collect_live(case_manifest)

    if parsed.check:
        json_stdout(
            terminal_row(
                "Pass",
                mode="check",
                detail="live exact-set inventory is complete and classified",
                extra={
                    "issues": snapshot.inventory["counts"]["issues"],
                    "warnings": snapshot.inventory["counts"]["warnings"],
                    "inventory_root": snapshot.inventory["semantic_root"],
                    "case_manifest_root": case_manifest["semantic_root"],
                },
            )
        )
        return 0

    if parsed.closeout:
        warnings = snapshot.inventory["counts"]["warnings"]
        if warnings:
            raise NoData(
                f"zero-debt closeout unavailable: {warnings} warnings remain "
                f"across {snapshot.inventory['counts']['issues']} issues"
            )
        json_stdout(
            terminal_row(
                "Pass",
                mode="closeout",
                detail="zero exact template debt independently reconstructed",
                extra={"inventory_root": snapshot.inventory["semantic_root"]},
            )
        )
        return 0

    if parsed.inventory or parsed.plan:
        artifact_dir = require_artifact_dir(parsed)
        result = write_bundle(
            mode="plan" if parsed.plan else "inventory",
            artifact_root=parsed.artifact_root,
            artifact_dir=artifact_dir,
            snapshot=snapshot,
        )
        json_stdout(result)
        return 0

    if parsed.apply_manifest:
        artifact_dir = require_artifact_dir(parsed)
        result = apply_reviewed_manifest(
            manifest_rel=parsed.apply_manifest,
            artifact_root=parsed.artifact_root,
            artifact_dir=artifact_dir,
            snapshot=snapshot,
        )
        json_stdout(result)
        return 0

    raise UsageRefused("no mode selected")


_v2_outer_mode = v2_raw_invocation_mode(sys.argv[1:])
try:
    main_exit = main(sys.argv[1:])
except OutputPublicationFailed as error:
    v2_abort_after_output_failure(error)
except PublishedV2Refusal as error:
    refusal_attributes = v2_raw_instance_dictionary(error)
    if (
        type(refusal_attributes) is not dict
        or type(dict.get(refusal_attributes, "document")) is not dict
    ):
        raise SystemExit(TERMINAL_EXIT["InternalFault"])
    refusal_document = dict.__getitem__(refusal_attributes, "document")
    v2_publish_outer_document(refusal_document)
    raise SystemExit(dict.__getitem__(refusal_document, "exit_code"))
except HarnessError as error:
    v2_failure = v2_outer_failure_document(
        error,
        raw_mode=_v2_outer_mode,
        execution_context=_v2_outer_execution_context,
    )
    if v2_failure is not None:
        v2_publish_outer_document(v2_failure)
        raise SystemExit(v2_failure["exit_code"])
    mode = next(
        (
            sys.argv[index].lstrip("-")
            for index in range(1, len(sys.argv))
            if sys.argv[index].startswith("--")
        ),
        "unknown",
    )
    error_terminal = v2_sealed_error_terminal(error)
    v2_publish_outer_document(
        terminal_row(
            error_terminal,
            mode=mode,
            detail=v2_bounded_diagnostic_summary(error),
        )
    )
    raise SystemExit(TERMINAL_EXIT[error_terminal])
except KeyboardInterrupt:
    cancelled = CancelledDrained(
        (
            "keyboard cancellation drained after accepted v2 manifest "
            "loading"
            if _v2_outer_execution_context is not None
            else "keyboard cancellation drained before accepted v2 execution"
        )
    )
    v2_failure = v2_outer_failure_document(
        cancelled,
        raw_mode=_v2_outer_mode,
        execution_context=_v2_outer_execution_context,
    )
    if v2_failure is not None:
        v2_publish_outer_document(v2_failure)
        raise SystemExit(TERMINAL_EXIT["CancelledDrained"])
    v2_publish_outer_document(
        terminal_row(
            "CancelledDrained",
            mode="unknown",
            detail="keyboard cancellation drained before terminal publication",
        )
    )
    raise SystemExit(TERMINAL_EXIT["CancelledDrained"])
except SystemExit:
    raise
except BaseException as error:
    v2_failure = v2_outer_failure_document(
        error,
        raw_mode=_v2_outer_mode,
        execution_context=_v2_outer_execution_context,
    )
    if v2_failure is not None:
        v2_publish_outer_document(v2_failure)
        raise SystemExit(TERMINAL_EXIT["InternalFault"])
    v2_publish_outer_document(
        terminal_row(
            "InternalFault",
            mode="unknown",
            detail=(
                f"{v2_exception_type_projection(type(error))}: "
                f"{v2_bounded_diagnostic_summary(error)}"
            ),
        )
    )
    raise SystemExit(TERMINAL_EXIT["InternalFault"])
else:
    raise SystemExit(main_exit)
PY
